local addonName, addonTable = ...

addonTable.questData['ru'] = {
[1] = {title = "The \"Chow\" Quest (123)aa", objective = "Kill Kobold Vermin, 2 of em.$Tpunk;!  Kill Kobold Vermin, 2 of em. NEW TEST AGAINСледующее заклинание будет наложено на вас:\n\n", description = "$Tpunk;!  Kill Kobold Vermin, 2 of em. NEW TEST AGAINСледующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nСделать цыпленком\n\nВы получите:\n\n"},
[2] = {title = "Коготь гиппогрифа Острокогтя", objective = "Принесите коготь гиппогрифа Острокогтя Сенани Громосерд на заставу Расщепленного Древа в Ясеневом лесу.", description = "Могучий гиппогриф Острокоготь был убит, и коготь этой свирепой твари – свидетельство вашей победы. Сенани Громосерд на заставе Расщепленного Древа несомненно пожелает увидеть этот трофей – доказательство ваших деяний.", progress = "Да, могучий |3-6(Шаман), я почувствовала твое приближение. Уверена, тебе есть что еще рассказать мне о твоей охоте.", completion = "Очень впечатляет, Душелов... коготь Острокогтя непросто добыть! Тебе везет в охоте!\n\nОстрый Удар давно донимал батраков с лесозаготовок, когда они пытались добраться сюда, на заставу Расщепленного Древа. Несомненно, скоро разойдется весть, что именно ты прикончил чудовище, и множество песен в твою честь будет распеваться у костров и на лесопильнях по всему Ясеневому лесу!", rewards = "Вы получите:\n\n"},
[5] = {title = "Урчащий живот Трясунчика", objective = "Поговорите с шеф-поваром Груалем.", description = "Я прячусь в этом призрачном городе несколько недель и не ел ничего, кроме трав и кореньев! Страшно хочется нормальной еды, и я за нее хорошо заплачу.\n\nУстрой мне пир, и не пожалеешь.\n\nГоворят, что шеф-повар Груаль в таверне \"Алый ворон\" делает превосходные темные пирожки с крабами...", progress = nil, completion = "Значит, тебе нужны пирожки с крабами? Что ж, могу испечь...", rewards = "Вы получите:\n\n"},
[6] = {title = "Награда за голову Гаррика Тихокрада", objective = "Убейте Гаррика Тихокрада и принесите его голову заместителю судьи Виллему в Аббатство Североземья.", description = "Гаррик Тихокрад – головорез, который уже много недель не дает покоя нашим крестьянам и торговцам. Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом. Принесешь мне голову этого негодяя – получишь награду!\n\nНо будь <осторожен/осторожна>, <имя>. Гаррик собрал разбойничью шайку. До него непросто будет добраться.", progress = "Ты нашел шайку Гаррика? Неужто мы, наконец, избавились от этого бандита?", completion = "Ха! Ты его прикончил! Ты оказал большую услугу Элвину и заслуживаешь хорошей награды!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗауженные штаныМногослойный мундирПлащ прапорщика\n\nВы также получите:\n\n"},
[7] = {title = "Нападение на лагерь кобольдов", objective = "Уничтожьте 10 кобольдов-вредителей. Вернитесь к маршалу Макбрайду.", description = "Первое твое задание, <имя>, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья.", progress = "Как прошла охота, Милтрэй? Ты обнаружил и уничтожил этих вредителей?", completion = "Славная работа. Эти кобольды – воры и трусы, но когда их много, они становятся опасны. А людям Штормграда лишняя угроза не нужна.\n\nПримите мою благодарность за хорошую работу.", rewards = "Вы получите:\n\n"},
[8] = {title = "Выгодная сделка", objective = "Доставьте ненадписанное письмо Ренни – хозяйке таверны в Тирисфальских лесах.", description = "Эй, <приятель/подруга>! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! \n\nУ меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-ее-там. Неважно, какая у нее там фамилия! \n\nДа и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и <сам/сама> сможешь там отдохнуть, если захочешь. По крайней мере, ты <должен/должна> туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу.", progress = "А? Что? Что это? \n\nОтрекшиеся... на аппетит они явно не жалуются. Располагайтесь как дома... да, дайте покой своим усталым косточкам. Меня зовут Ренни, если что-то понадобится – я к вашим услугам.", completion = "Ого! Письмо? Отличная новость! Я давно жду весточки от моей старушки-матери из Могильника. Она настоящая святая – моя мать. Как она там поживает... \n\nЧто? Слишком фальшивлю? Не купился?\n\nНу так отстань... тебе абсолютно не обязательно знать, от кого это письмо. Давай, давай, иди отсюда! \n\nВозвращайся, когда будет что потратить... бродяга. \n\nИ вообще, приходи сюда отдохнуть, когда устанешь от своих многодневных приключений или другой подобной глупости.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШляпка лесного грибаОсвежающая ключевая вода\n\nВы также получите:\n\n"},
[9] = {title = "Поля смерти", objective = "Убейте 20 дозорных полей по просьбе фермера Сальдена.", description = "Взгляните, во что превратилось это место! Когда-то эти земли населяли честные крестьяне. Но проклятые воры выжили отсюда всех. Только не меня! Однако угодья захватили големы – дозорные полей.\n\nЕсли вы готовы поработать, я попросил бы вас пойти и убить 20 таких големов. Возвращайтесь за оплатой, когда все будет сделано. Когда расправитесь с теми, что обитают на моем поле, зачистите поля и моих соседей тоже.", progress = "А, я вижу, вы вернулись! Надеюсь, вы упорно работали над тем, чтобы очистить наши угодья от дозорных полей. Двадцати еще не набралось?", completion = "Отличная работа, дружище. Вы полностью отработали свою плату. Кто знает, может быть, Западный Край снова расцветет.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШтаны жнецаОдеяние жнеца\n\nВы также получите:\n\n"},
[10] = {title = "Спасение Холстомера", objective = "Узнайте, что стало с  младшим геодезистом Холстомером и приведите его или верните его оборудование старшему геодезисту Рудознатцу в Прибамбасск.", description = "Ох, это ужасно! Я послал моего лучшего помощника, младшего геодезиста Холстомера в пустыню, на юго-восток отсюда. Именно там располагается Зияющая бездна. Вот, а теперь он пропал, и в последнем докладе шла речь о странных насекомых. Неужели они наводнили уже два основных района пустыни?\n\nПрошу тебя, доберись до Зияющей бездны и поищи там Холстомера! Его... или хотя бы оборудование. Боюсь, больше от бедняги ничего и не осталось.", progress = "Ну, что тебе удалось узнать? Похоже, ты только что из боя... Жив ли Холстомер?", completion = "Юный Холстомер был хорошим гоблином. Будем надеяться, что его кончина не напрасна, и собранные перед смертью сведения не пропали даром.\n\nПохоже, от этих жуков надо ждать неприятностей. Они слишком хитры, но все исследования указывают на то, что эти твари находятся под влиянием третьей стороны! Коли так, беда грозит не только Прибамбасску, но и всей пустыне!", rewards = "Вы получите:\n\n"},
[11] = {title = "Награда за гноллов из стаи Речной Лапы", objective = "Принесите 8 раскрашенных поручей гноллов в казармы заместителю судьи Рейнеру.", description = "На границах Элвиннского леса появились гноллы – звероподобные твари, которым попросту нечего делать в этих краях. К югу от сторожевой башни была замечена большая группа этих существ: их слишком много, чтобы мы сумели с ними справиться. Хуже того: на востоке, у Озера Каменных Столбов, тоже обнаружили гноллов.\n\nАрмия Штормграда будет благодарна любому, кто поможет справиться с этой угрозой. В доказательство своей победы принеси мне раскрашенные нарукавные повязки гноллов.", progress = "Приветствую, Wrestlecake. Ну, как идет война с гноллами?", completion = "О, вижу, ты слов на ветер не бросаешь! Прими нашу благодарность, Wrestlecake.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКулачный щит народного ополченияШтаны Сорванца\n\nВы также получите:\n\n"},
[12] = {title = "Народное ополчение", objective = "Убейте 15 звероловов и 15 контрабандистов из Братства Справедливости и вернитесь к Гриану Камнегриву.", description = "У народного ополчения есть лишь одна цель: защитить земли Западного Края и вернуть в них мир. К сожалению, приходится это делать путем кровопролития.\n\nОдин из моих разведчиков сообщил о группе звероловов из Братства Справедливости, наводящих на местных жителей ужас и панику. У меня есть сообщения, что звероловов Братства замечали около Рудника Янго к северо-западу отсюда, а также неподалеку от фермы Мольсена и тыквенной фермы Хмуроброва. Если ты хочешь присоединиться к ополчению, убей 15 звероловов и 15 контрабандистов из Братства Справедливости, а затем возвращайся ко мне.", progress = nil, completion = "Отличная работа, Мэйнард. Мой разведчик был свидетелем твои доблестных деяний. Пока что с тобой очень приятно иметь дело.", rewards = "Вы получите:\n\n"},
[13] = {title = "Народное ополчение", objective = "Убейте 15 погромщиков и 15 мошенников из Братства Справедливости и вернитесь к Гриану Камнегриву на Сторожевой холм.", description = "Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, <имя>, и пусть весь Западный Край узнает о силе Света.\n\nЗолотой карьер находится неподалеку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты <убил/убила> 15 погромщиков и 15 мошенников из Братства Справедливости.", progress = "Нет времени на разговоры, Дуревестник. Погромщики из братства Справедливости лишают жителей Западного края мира и процветания, которого они заслуживают. Удостоверься, что ты убил как минимум 15 погромщиков и 15 мошенников. Это послужит остальным ясным намеком на то, что разбою здесь места нет.", completion = "Ваша значимость для народного ополчения была подкреплена вашими смелыми действиями.", rewards = "Вы получите:\n\n"},
[14] = {title = "Народное ополчение", objective = "Убейте 15 разбойников, 5 налетчиков и 5 кастетчиков из Братства Справедливости. Вернитесь к Гриану Камнегриву на Сторожевой Холм.", description = "Некоторые члены Братства Справедливости от нас ускользнули. Один из моих разведчиков, которому я очень доверяю, сообщает, что члены этого братства грабят и разоряют деревни вплоть до Южного Западного Края. Мы считаем, что они скрываются в Холмах Разбойничьих Кинжалов, замышляя новые бесчинства. Убей этих негодяев от имени народного ополчения.", progress = nil, completion = "Я покинул разоренные земли Лордерона, вернувшись на свою родину... и застал ее в столь же ужасном состоянии. Но для Западного Края еще есть надежда. Проявленная тобой доблесть доказала, что ты с честью служишь нашему делу. С огромной гордостью я принимаю тебя в ряды народного ополчения. Да воссияет над тобой Свет!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛезвие народного ополченияДубина народной войныИскра народного ополчения\n\nВы также получите:\n\n"},
[15] = {title = "Разведка в руднике Горного эха", objective = "Уничтожьте 10 кобольдов-рабочих и вернитесь к маршалу Макбрайду.", description = "<имя>, мои разведчики доносят, что в эти края проникло гораздо больше кобольдов, чем мы рассчитывали. Группа кобольдов-рабочих разбила лагерь близ Рудника Горного Эха к северу отсюда.\n\nОтправляйся к шахте и уничтожь их. Насколько нам известно, кобольдов там много... Убей-ка десяток, посмотри, сколько  еще осталось, и доложи мне.", progress = "Ты был в руднике? Готов доложить об успехах?", completion = "Меня тревожат сообщения о кобольдах на нашем руднике. К добру это не приведет. Вот, это твоя награда. Когда будешь готов, приходи ко мне. Буду рад, если ты согласишься предпринять еще одну вылазку…", rewards = "Вы получите:\n\n"},
[16] = {title = "Жажда Джерарда", objective = "Работа фермера тяжела, от нее здорово пересыхает в глотке.\n\nЕсли ты дашь мне родниковой воды, могу предложить кое-что взамен.", description = nil, progress = "Работа фермера тяжела, от нее здорово пересыхает в глотке.\n\nЕсли ты дашь мне родниковой воды, могу предложить кое-что взамен.", completion = "Благодарю, Мэйнард! Решишь еще со мной поторговаться – заходи.", rewards = "Вы получите:\n\nСпелое красное яблоко"},
[17] = {title = "В Ульдаман за реагентами", objective = "Принесите 12 грибов-малиновиков Гхаку Целителю в Телcамар.", description = "Мне рассказали о недавно открытом растении, грибе-малиновике. Этот гриб растет целыми колониями на раскопках Ульдамана, в самой глубине. Наверное, встречается еще где-то, но мне известно только одно место. Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься.\n\nОтыщи эти грибы и принеси мне дюжину. Только учти: они могут выпустить облако ядовитых спор, если ты их случайно встряхнешь.\n\nЕсли выполнишь мое поручение, я сделаю для тебя один из моих знаменитых восстановительных эликсиров!", progress = "Ты принес грибы-малиновики, которые нужны мне для работы? Нет грибов – нет награды!", completion = "Молодец, Джэйлол, ты снова показал, на что способен! Эти грибы мне очень пригодятся для исследований!\n\nА теперь, как я и обещал, можешь насладиться вкусом одного из моих восстановительных составов из личных запасов...\n\nЕсли ты тоже увлекаешься алхимией, мы можем вдобавок поговорить и о других делах. В любом случае, благодарю за помощь!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nПриводящее в сознание зелье"},
[18] = {title = "Братство воров", objective = "Принесите 12 красных холщовых бандан заместителю судьи Виллему к Аббатству Североземья.", description = "Тут возле Североземья недавно новая воровская шайка завелась. Зовут себя Братством Справедливости. Видели их за рекой, на востоке.\n\nНе знаю, что у них на уме, но наверняка ничего хорошего! Принеси мне их банданы, и в награду получишь оружие.", progress = "Ну, добыл мне банданы?", completion = "Ага, вижу, ты вернулся не с пустыми руками. Армия Штормграда ценит твою помощь.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКинжал ополченияМолот ополченияКороткий меч ополченияБоевой молот ополченияОкованный посох ополчения\n\nВы также получите:\n\n"},
[19] = {title = "Тарил'зун", objective = "Принесите маршалу Маррису в Красногорье голову Тарил'зуна.", description = "Вестники и отступники из клана Черной горы постоянно устраивают засады на дороге между городом и крепостью Каменной Стражи. Их предводитель – орк по имени Тарил'зун. Он уже натворил достаточно дел. Принеси мне его голову!", progress = "Орки Черной горы по-прежнему не дают нам покоя. Избавь нас хотя бы от Тарил'зуна!", completion = "Тарил'зун был жестоким и коварным орком. Ты молодчина – я знаю, справиться с ним было нелегко. Вот твоя награда, Эфром.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗакаленный огнем кулачный щитКрушитель орков\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[20] = {title = "Угроза Черной горы", objective = "Принесите маршалу Маррису в Приозерье 10 иззубренных топоров.", description = "К нам явились орки Черной Горы из Пылающих степей и захватили крепость Каменной стражи. Они грабят области к северу от Озер, и жители тех земель бежали в город, набились в него, словно сельди в бочку.\n\nПомоги Приозерью избавиться от этой угрозы. Перебей орков Черной Горы и принеси в доказательство десять иззубренных топоров.\n\nХотя орки теснят нас с севера, до нас доходили вести об их появлении и в юго-восточной части Красногорья. Если встретишь их – убивай без колебаний.", progress = "Ты уже охотился на орков, Эфром? Если так, покажи мне...", completion = "Что ж, чем меньше орков, тем лучше. Большое тебе спасибо.", rewards = "Вы получите:\n\n"},
[21] = {title = "Схватка у рудника Горного эха", objective = "Уничтожьте 12 кобольдов-работников и вернитесь к маршалу Макбрайду.", description = "Данные твоей предыдущей разведки подтвердились – на Руднике Горного Эха необходимо провести зачистку. Возвращайся на рудник и помоги очистить его от кобольдов. \n\nВремя дорого, <имя>. Чем дольше кобольды безнаказанно пробудут в руднике, тем сильнее они закрепятся в Североземье.", progress = "Я знаю, это поганая работа, Яробород, но ее необходимо выполнить ради безопасности Североземья. Ты готов предоставить отчет?", completion = "Ты снова заслужил мою похвалу и благодарность армии Штормграда. В руднике еще достаточно кобольдов, но я отправлю других новобранцев бороться с ними. Для тебя имеются другие поручения.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПояс экипировщикаСапоги экипировщикаПерчатки экипировщика\n\nВы также получите:\n\n"},
[22] = {title = "Пирог из печени жутеклыка", objective = "Принесите Сальме Сальден 8 кусков печени жутеклыка, чтобы она могла испечь пирог.", description = "Лук очищен. Чеснок раздавлен. Розмарин измельчен. Основа выпечена. Укроп нарезан. Соус вымешан до гладкости. Все, что мне еще нужно для моего знаменитого пирога – это 8 кусков печени жутеклыка!", progress = "Все, что мне еще нужно для моего знаменитого пирога – это восемь кусков печени жутеклыка!", completion = "Замечательные куски, Бронгард! Большое тебе спасибо! Мы с фермером Сальденом устроим сегодня настоящий праздник. А это – для тебя, за труды. У тебя ведь не было мысли, что |3-6(Охотник) вроде тебя останется без угощения, а?", rewards = "Вы получите:\n\nПирожок из печени жутеклыкаРецепт: пирожок из печени жутеклыка"},
[23] = {title = "Лапа Топтыжня", objective = "Принесите лапу Топтыжня Сенани Громовое Сердце на заставу Расщепленного Древа в Ясеневом лесу.", description = "Вот лапа могучего медведя Топтыжня – ваш трофей этого этапа охоты. На лапе есть маленький знак – месяц. Смысл этого знака покрыт тайной.\n\nЭту лапу надо отнести Сенани Громовое Сердце на заставу Расщепленного Древа, чтобы доказать, что вы одолели могучую тварь, тем самым завершив этот этап охоты.", progress = "Ах – Шпилэ – я только что подумала о тебе! Ну, как прошла охота?", completion = "О, лапа Топтыжня! Твоя навыки меня впечатлили, |3-6(Маг). Говорят, он многих убил. Месяц на его лапе ясно говорит о том, что его обучали ночные эльфы, которые рыщут по Ясеневому лесу. Топтыжень был одним из самых могучих медведей, которых только можно сыскать в этих краях. Убить такую тварь – истинное испытание воли и решимости.\n\nТвои предки гордились бы тобой!", rewards = "Вы получите:\n\n"},
[24] = {title = "Голова Тенумбры", objective = "Принесите голову Тенумбры Сенани Громовое Сердце на заставу Расщепленного Древа в Ясеневом лесу.", description = "Некогда стремительный Тенумбра лежит у ваших ног. Вы победили. Голова убитого ночного саблезуба – достойный трофей этой схватки в ходе охоты. Сенани Громосерд на заставе Расщепленного Древа захочет увидеть ваш трофей и наградить вас за этот этап охоты.", progress = "Еще раз привествую тебя, Комодик! Ты пришел показать мне свои охотничьи трофеи?", completion = "Победа в Ашенвальской охоте! Отлично! Голова Тенумбры, вне всякого сомнения, – достойный трофей столь впечатляющей схватки.\n\nДикий нрав Тенумбры был хорошо известен на заставе. Из-за этого чудовища любое путешествие от Зорамского взморья на запад, особенно пешком, было рискованным. Благодаря тебе этой угрозы больше не существует.", rewards = "Вы получите:\n\n"},
[25] = {title = "Остановка у Каменного Когтя", objective = "Истребите 12 злобных элементалей воды на озере Мистраль, что к востоку от Туннеля Когтя и к юго-западу от заставы Расщепленного Древа.\n\nИсследуйте беседку на озере Мистраль, из которой открывается вид на соседний форт Альянса. \n\nВернитесь к Мастоку Райльшипу на заставу Расщепленного Древа в Ясеневом лесу.", description = "Если хочешь принести пользу, то почему бы тебе не разобраться с ситуацией у Туннеля Когтя?\n\nСообщение между Ясеневым лесом и Каменным Когтем замерло из-за того, что из озера лезет всякая дрянь и нападает на все, что только подойдет поближе... то есть, на все, что на дороге. Но куда лучше простой разборки с элементалями воды будет вот что – разведай-ка беседку на озере Мистраль – ту, с которой открывается отличный вид на соседний форт Альянса.\n\nНу, <готов/готова> принести пользу?", progress = nil, completion = "Да я слышал, как что-то пролетело по озеру подобно пыльной буре Степей. По звуку мы сможем найти пригодный раблюдательный пункт, чтобы присматривать за нашими друзьями из Альянса. Да, только если будем сидеть тихо...\n\nПохоже, от тебя тут больше толку не будет – сообщение между здешними местами и Каменным Когтем налажено. Возьми вот это – заслужил.", rewards = "Вы получите:\n\n"},
[26] = {title = "Необходимый урок", objective = "Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне.", description = "<имя>, я с удовольствием наблюдал за твоими успехами. Ты непременно станешь <знаменитым защитником/знаменитой защитницей> природы.\n\nПришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который дает тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить с Дендритом Блеском Звезд из Круга Кенария. Он будет твоим наставником.", progress = nil, completion = "Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нем ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, ее надо заслужить.\n\nТебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика.\n\nГотовься – время испытания пришло.", rewards = "Вы получите:\n\n"},
[27] = {title = "Необходимый урок", objective = "Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне.", description = "<имя>, Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь <знаменитым защитником/знаменитой защитницей> природы.\n\nПришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который дает тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить там с Дендритом Блеском Звезд из Круга Кенария. Он будет твоим наставником.", progress = nil, completion = "Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нем ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, ее надо заслужить.\n\nТебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика.\n\nГотовься – время испытания пришло.", rewards = "Вы получите:\n\n"},
[28] = {title = "Испытание озера", objective = "Найдите безделушку святилища в озере Элуны и отнесите ее в святилище Ремулоса на северо-западе Лунной Поляны. Оказавшись там, воспользуйтесь безделушкой.\n\nПотом вам будет нужно поговорить с Таджарри в святилище, чтобы завершить испытание.", description = "Вот твое первое испытание – исследуй глубины озера Элуны и найди безделушку святилища. Она быстро разрушается, так что не медля отнеси ее к святилищу Ремулоса. Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны.\n\nНа все испытание тебе дается ограниченное количество времени, и возможно, тебе придется соревноваться с другими друидами, которые тоже ищут безделушки. Быстрота ума и ловкость тела помогут тебе добиться успеха.\n\nУдачи тебе, <имя>.", progress = "Для завершения Испытания озера тебе нужно использовать безделушку святилища в пределах этого места. До тех пор твое испытание считается незавершенным, и ты рискуешь провалить его.", completion = "Что же, сдается мне, еще один друид успешно прошел Испытание Озера! Хвалю тебя, мой юный друг.\n\nКак я уже сказала, мое имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты отдал дань уважения этому месту.", rewards = "Вы получите:\n\n"},
[29] = {title = "Испытание озера", objective = "Найдите безделушку святилища в озере Элуны и отнесите ее в святилище Ремулоса на северо-западе Лунной Поляны. Оказавшись там, воспользуйтесь безделушкой.\n\nПотом вам будет нужно поговорить с Таджарри в святилище, чтобы завершить испытание.", description = "Вот твое первое испытание – исследуй глубины озера Элуны и найди безделушку святилища. Она быстро разрушается, так что не медля отнеси ее к святилищу Ремулоса. Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны.\n\nНа все испытание тебе дается ограниченное количество времени, и возможно, тебе придется соревноваться с другими друидами, которые тоже ищут безделушки. Быстрота ума и ловкость тела помогут тебе добиться успеха.\n\nУдачи тебе, <имя>.", progress = "Для завершения Испытания озера тебе нужно использовать безделушку святилища в пределах этого места. До тех пор твое испытание считается незавершенным, и ты рискуешь провалить его.", completion = "Что же, сдается мне, еще один друид успешно прошел Испытание Озера! Хвалю тебя, мой юный друг.\n\nКак я уже сказала, мое имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты отдал дань уважения этому месту.", rewards = "Вы получите:\n\n"},
[30] = {title = "Испытание Морского Льва", objective = "Найдите половинку подвески Ловкости водяного облика и половинку подвески Выносливости водяного облика. Поговорите с жителями Лунной поляны, чтобы узнать, где могут находиться эти предметы.\n\nСложите из половинок подвеску Морского Льва. Для этого вам надо находиться рядом со святилищем Ремулоса.\n\nОтнесите собранную подвеску Дендриту Блеску Звезд в деревню Ночная Гавань что на Лунной поляне.", description = "Вот твое второе испытание – тебе понадобятся две половинки подвески Морского Льва. Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва. Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика.\n\nПоговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить. Сделав это, отнеси подвеску Дендриту Блеску Звезд.", progress = "Ты уже собрал подвеску, Подлыйзмей? Дай посмотреть. Если тебе нужна помощь, чтобы соединить половинки, обратись к местным жителям. Так ты не только узнаешь то, что тебе надо, но и познакомишься с этой чудесной, благословенной поляной.", completion = "Ты прошел испытание Морского Льва, Подлыйзмей. Прими мои поздравления.\n\nКаждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва.\n\nЗапомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик.", rewards = "Вы получите:\n\n"},
[31] = {title = "Водный облик", objective = "Возвращайтесь в Громовой Утес и покажите Тюраку Руническому Тотему подвеску Морского Льва.", description = "Ты <завершил/завершила> обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Тюраку Руническому Тотему в Громовой Утес. Покажи ему свою подвеску и докажи, что ты <готов/готова> усвоить его уроки. Он завершит твое обучение, благодаря которому ты станешь <единым/единой> с водой.\n\nДоброго тебе пути, юный друид. Мы еще встретимся.", progress = "До меня дошли слухи о твоем триумфальном возвращении в Громовой Утес, но я все равно хочу увидеть доказательства того, что ты усвоил уроки Лунной поляны, прежде чем стану учить тебя принимать водный облик.\n\nЕсть ли у тебя подвеска Морского Льва?", completion = "Великолепно, Подлыйзмей. Твои предки могут гордиться твоими успехами! Ты готов прининять водный облик, и я с радостью научу тебя этому.\n\nПрими также эту вещицу в знак признания твоих успехов в двух испытаниях. Надеюсь, тебе будет приятно присоединить ее к своему снаряжению защитника Природы и хранителя равновесия.", rewards = "Следующее заклинание будет наложено на вас:\n\nВодный облик\n\nВы получите:\n\nПояс Водолея"},
[32] = {title = "Восхождение силитидов", objective = "Отнесите отчет Зилзибину Барабанному Бою в Оргриммар.", description = "Вот твой отчет. Прошу тебя, отнеси его кому-нибудь, сведущему в такого рода вопросах.\n\nЯ слышал про ученого-тролля по имени Зилзибин Барабанный Бой. Он посвятил много времени изучению форм жизни, встречающихся лишь в Азероте; он и историк заодно! Если ты хочешь, чтобы кто-то объяснил, что именно происходит и как это прекратить, обратись к нему. Нам любая помощь не помешает.\n\nЕго дом находится во втором ряду Волока в Оргриммаре.", progress = "Прости, мы не знакомы... Но судя по всему, тебе приходилось слышать обо мне. Чем могу помочь? Ты мне что-то принес?", completion = "Что до твоего отчета... да, я уже встречался с этими тварями. Рудознатец правильно поступил, отправив это письмо и тебя ко мне.\n\nЭти существа мигом пожрут всю пустыню Танарис; они представляют собой одну из величайших опасностей, с которой только можно столкнуться. Знакомься, Томпсон – это силитиды. Так зовутся странные насекомые, которые служат величайшему злу, грозящему и Орде, и Альянсу.\n\nЖаль, что нам не хватило ума понять это раньше.", rewards = "Вы получите:\n\n"},
[33] = {title = "Волки на границе", objective = "Принесите 8 кусков жесткой волчатины Игану Меховщику к Аббатству Североземья.", description = "Ненавижу этих мерзких лесных волков! Но я бы не прочь полакомиться бифштексами из волчатины... Принеси мне жесткой волчатины, и в обмен я предложу тебе что-нибудь полезное.\n\nУбей несколько лесных волков и молодых волков, что водятся в североземских лесах, и принеси мне их мясо.", progress = "Эй, Маркроу! Я уж проголодался... Ты принес волчатину?", completion = "Ну, ты на славу постарался! Прямо не терпится поджарить волчатинки...\n\nУ меня есть кое-что интересное для тебя – выбирай!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМягкие ботинки, отделанные мехомНаручи из волчьей шкуры\n\nВы также получите:\n\n"},
[34] = {title = "Незваный гость", objective = "Убейте Грубобрюха. Принесите Марти Джанроз клык вепря.", description = "Мой сад снова разграблен и вытоптан. И я знаю, кто это сделал! Это проклятый вепрь, которого маршал Маррис прозвал Грубобрюхом.\n\nТеперь мне долго не удастся посадить нарциссы. Они загублены! И во всем виноват мерзкий кабан. Положи конец этому паразиту! Принеси мне его клык, и я с удовольствием вознагражу тебя. Говорят, он пасется в полях на юго-западе от Озер, но порой заходит и сюда, в мой сад.", progress = "Грубобрюх все еще бесчинствует или ты уже избавил Приозерье от этого паразита?", completion = "Наконец-то моему саду ничего не грозит! Спасибо тебе, Бронгард, ты оказал мне большую услугу. Теперь мой сад расцветет с небывалой пышностью!", rewards = "Вы получите:\n\nБукет алых бегоний"},
[35] = {title = "Новые заботы", objective = "Поговорите со стражником Томасом.", description = "Если ты думаешь, что слухи о мурлоках могут оказаться правдой, отправляйся к восточному мосту Элвиннского леса и поговори со стражником Томасом. Он уже неделю несет стражу у моста и должен знать, что там происходит на самом деле.\n\nПринеси мне его отчет.", progress = nil, completion = "Да, это правда: мурлоки поселились в реках и на их берегах в западной части леса. Мы не знаем, почему они пришли сюда, но их следует остерегаться: они агрессивны и довольно умны.", rewards = "Вы получите:\n\n"},
[36] = {title = "Похлебка Западного Края", objective = "Отнесите Сальме Сальден рецепт похлебки Западного Края.", description = "Никогда я не думала, что наступит день, когда я покину ферму. Но поля кишат разбойниками, и для нас теперь тут слишком опасно. Как только фермер Хмуробров починит повозку, мы отправимся в путь.\n\nМожет быть, ты окажешь мне услугу? Я напишу рецепт похлебки Западного Края, а ты отнесешь его Сальме Сальден вон на ту ферму – она сразу за развилкой дороги.", progress = "Я буду очень скучать по Верне Хмуробров... Скажи-ка, ты не встретил ее по пути сюда?", completion = "Эта Верна всегда была такой милой девушкой. Нам будет ее не хватать здесь, в Западном Крае, но, только между нами, в душе она – городская жительница, и Штормград – местечко как раз для нее. Ладно, хватит сплетничать! Начнем же готовить похлебку Западного Края!", rewards = "Вы получите:\n\n"},
[37] = {title = "Пропавшие стражи", objective = "Отправляйтесь на север по реке и отыщите следы пропавших стражников – Рольфа и Малакаи.", description = "Несколько дней назад мы отправили на обследование берегов реки двух наших стражей, Рольфа и Малакаи; ни один из них до сих пор не вернулся. Чтобы составить полный отчет, мне нужно выяснить, что с ними случилось.\n\nОтправляйся на север вдоль реки и разыщи стражей... или хотя бы их останки.", progress = nil, completion = "Хотя на трупе мало что осталось, рядом с ним оказался медальон с надписью \"Камень пехотинца Малакаи\".", rewards = "Вы получите:\n\n"},
[38] = {title = "Похлебка Западного Края", objective = "Принесите Сальме Сальден 3 куска жилистого мяса стервятника, 3 рыла жутеклыка, 3 глаза мурлока и 3 окры.", description = "Помоги мне сварить похлебку Западного Края! Мне нужны для нее следующие ингредиенты:\n\n3 куска жилистого мяса стервятника\n3 рыла жутеклыка\n3 глаза мурлока\n3 окры", progress = "Возвращайся ко мне, когда соберешь 3 куска жилистого мяса стервятника, 3 рыла жутеклыка, 3 глаза мурлока и 3 окры.", completion = "Окра отлично загустит бульон! А теперь мы просто добавим жилистого мяса стервятника, несколько глаз мурлока и эти вкуснейшие рыла жутеклыка. И вот все готово! За оказанную помощь, Маладат, я предлагаю тебе отведать первую порцию похлебки Западного Края.", rewards = "Вы получите:\n\nПохлебка Западного КраяРецепт: похлебка Западного КраяЖаропрочные полуперчатки СалмыОстрый кухонный нож"},
[39] = {title = "Донесение Томаса", objective = "Доставьте донесение в Златоземье маршалу Дугхану.", description = "Нужно сообщить маршалу Дугхану о смерти Малакаи и Рольфа. Наши войска на востоке Элвиннского леса не смогут справиться с мурлоками.\n\nЯ знаю, лишних солдат у нас нет, но, может, Дугхан пришлет хоть какую-то помощь...", progress = nil, completion = "Да, вести невеселые... Людей у нас и так немного, а теперь, когда мурлоки прикончили Рольфа и Малакаи, будет и вовсе несладко.\n\nЕсли положение не изменится к лучшему, боюсь, к концу недели бои будут идти уже в Златоземье...", rewards = "Вы получите:\n\n"},
[40] = {title = "Водяная нечисть", objective = "Реми Повторюх просит вас найти в Златоземье маршала Дугхана и поговорить с ним.", description = "<имя>, в Элвиннском лесу появилась новая напасть. Мурлоки поднялись вверх по рекам в восточной части леса, они распугивают рыбу и нападают на мирных жителей.\n\nЯ предупреждал маршала Дугхана, но его больше беспокоит нашествие гноллов и бандитов. Мурлоков он вообще не принимает в расчет. \n\nЯ прошу тебя, <имя>, поговори с Дугханом и постарайся убедить его послать отряд на восток!", progress = nil, completion = "Да, верно, я говорил с Реми. Поверь, я очень высоко ценю его как торговца, но все отчеты о появлении мурлоков на востоке крайне недостоверны.\n\nЯ понимаю твою тревогу, но пока не будут получены надежные сведения о мурлоках, никаких войск на восток я посылать не стану.", rewards = "Вы получите:\n\n"},
[45] = {title = "Судьба Рольфа", objective = "Обыщите поселение мурлоков и найдите Рольфа – или подтверждение его смерти.", description = "При осмотре местности были обнаружены запутанные следы, ведущие на восток вдоль берега Озера Каменных Столбов. В отдалении видно поселение мурлоков.\n\nВозможно, именно здесь и окончил свой путь Рольф...", progress = nil, completion = "На шее трупа вы находите медальон с надписью \"Пехотинец Рольф Хартфорд\".", rewards = "Вы получите:\n\n"},
[46] = {title = "Награда за мурлоков", objective = "Принесите 8 плавников мурлоков к восточному мосту Элвиннского леса и отдайте их стражнику Томасу.", description = "Армия Штормграда назначила награду за мурлоков – скрытней и добытчиков. Убей их и принеси мне их плавники: армия хорошо за это заплатит.\n\nМурлоки построили селение на Озере Каменных Столбов – это к северу отсюда; еще одно селение расположено на юге – там, где русло реки разделяется надвое.", progress = "Ну что, Rainon, как идет охота?", completion = "Что у нас тут? Плавники? Отлично! Маршал Дугхан обеспокоен мурлоками, поселившимися на востоке леса. Он будет рад узнать, что ситуация под контролем.\n\nТвоя помощь в этом деле была просто неоценимой.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДлинный штыкТвердая металлическая дубинаВидавший виды меч\n\nВы также получите:\n\n"},
[47] = {title = "Золотая пыль", objective = "Принесите 10 порций Золотой пыли в Златоземье Реми Повторюху. Золотую пыль можно добыть у кобольдов в Элвиннском лесу.", description = "Кобольды в этих местах иногда носят с собой Золотую пыль. Достань мне этой пыли, и я дам за нее лучшую цену в городе! Лучшую цену в городе!\n\nКобольдов можно найти на юге, на руднике Подземных глубин, или на северо-востоке, рядом с Яшмовой шахтой.", progress = "Эй! Ну как, есть Золотая пыль... пыль?", completion = "Благодарю за пыль, Wrestlecake. Вот твои деньги... А вот и маленький подарочек от моих друзей. Возможно, он тебе пригодится... Да, пригодится.", rewards = "Вы получите:\n\nМешок разноцветных шариков"},
[48] = {title = "Янтарное сладкое", objective = "Принесите Мрачнобуху Громовару воду святого источника.", description = "Где-то в южных краях, там, где вьется лоза\nЕсть колодец с водой, что чиста как слеза.\nБьет священной воды одинокий ручей,\nБудь же другом, скорей, отправляйся за ней!", progress = "И-ик! Хо-хо! Хочешь выступление на бис?\n\nГде-то в южных краях, там, где вьется лоза\nЕсть колодец с водой, что чиста как слеза.\nБьет священной воды одинокий ручей,\nБудь же другом, скорей, отправляйся за ней!", completion = "И-ик! Хо-хо!", rewards = "Вы получите:\n\n"},
[49] = {title = "Янтарное сладкое", objective = "Принесите Мрачнобуху Громовару мешок ячменя, мешок ржи и мешок кукурузы.", description = "Как прекрасна янтарная россыпь зерна!\nСловно жаром костра пропиталась она.\nЧтобы вышел наш пенный напиток хорош,\nТы ячмень мне добудь, кукурузу и рожь.", progress = "На бис? Легко!\n\nКак прекрасна янтарная россыпь зерна!\nСловно жаром костра пропиталась она.\nЧтобы вышел наш пенный напиток хорош,\nТы ячмень мне добудь, кукурузу и рожь.", completion = "И-ик! Хо-хо!", rewards = "Вы получите:\n\n"},
[50] = {title = "Янтарное сладкое", objective = "Принесите Мрачнобуху Громовару истинное серебро.", description = "Прочь дремота и лень! Встану я поутру,\nЗамешаю зерно и в сусло разотру,\nСплавить куб перегонный - и будет добро!\nТолько истинных свойств подойдет серебро.", progress = "Спеть на бис?С удовольствием, друг! Прочь дремота и лень! Встану я поутру,\nЗамешаю зерно и в сусло разотру,\nСплавить куб перегонный - и будет добро!\nТолько истинных свойств подойдет серебро.", completion = "И-ик! Хо-хо!", rewards = "Вы получите:\n\n"},
[51] = {title = "Янтарное сладкое", objective = "Принесите Мрачнобуху Громовару ветку смоковницы.", description = "Хочешь, друг мой, на брагу взглянуть? - так и быть!\nНам осталось лишь только ее процедить.\nВетвь смоковницы даст нам немного угля,\nБудет хмельный напиток светлей янтаря!", progress = "Повторить? Для тебя – что угодно!\n\nХочешь, друг мой, на брагу взглянуть? - так и быть!\nНам осталось лишь только ее процедить.\nВетвь смоковницы даст нам немного угля,\nБудет хмельный напиток светлей янтаря!", completion = "И-ик! Хо-хо!", rewards = "Вы получите:\n\n"},
[52] = {title = "Защита границы", objective = "Убейте 8 лесных хищников и 5 молодых лесных медведей. Затем вернитесь к стражнику Томасу у восточного моста Элвиннского леса.", description = "Приветствую, <имя>. Чем дальше от Златоземья, тем агрессивнее становятся дикие звери: на Лесопилку Восточной долины постоянно нападают волки и медведи.\n\nХочешь нам помочь?", progress = "Надеюсь, волки и медведи уже перебиты?", completion = "Я так тебе благодарен, Wrestlecake!.. Похоже, в этом лесу поселилось что-то, что гонит зверей прямо на нас.\n\nЧто бы там ни было, хотел бы я, чтобы оно не покидало леса...", rewards = "Вы получите:\n\nПростое лечебное зелье"},
[53] = {title = "Янтарное сладкое", objective = "Принесите Мрачнобуху Громовару вязанку обуглившихся дубовых поленьев.", description = "Вот медовая брага готова вполне,\nСловно солнце играет в ее глубине!\nМы в дубовый бочонок ее разольем,\nА потом насладимся напитком вдвоем!", progress = "Конечно, ради тебя я спою еще раз!\n\nВот медовая брага готова вполне,\nСловно солнце играет в ее глубине!\nМы в дубовый бочонок ее разольем,\nА потом насладимся напитком вдвоем!", completion = "Углем отфильтровано, вызрело в бочке,\nВосторг, упоение в каждом глоточке.\nПоднимем же тост за тебя, за меня\nИ за сладкий напиток цвета янтаря!", rewards = "Вы получите:\n\nЗасапожная фляга Громовара"},
[54] = {title = "Донесение в Златоземье", objective = "Отнесите документы маршала Макбрайда маршалу Дугхану в Златоземье.", description = "<имя>, ты – <класс>, чья верность интересам Североземья ни для кого не является тайной. Теперь тебе поручается защита Элвиннского леса.\n\nЕсли ты принимаешь это поручение, то вот бумаги, которые я подготовил для отправки маршалу Дугхану в Златоземье. Златоземье находится на южном тракте, за пограничными воротами.", progress = "У тебя сообщение от маршала Макбрайда? Североземье по сравнению с Элвиннским лесом – мирный сад, но мне любопытно, о чем пишет Макбрайд.\n\nДайте-ка мне бумаги...", completion = "Что же, тут говорится, что ты был назначен полномочным представителем маршалов Штормграда. Прими мои поздравления.\n\nИ удачи тебе... Охранять Элвинн – это непростая работа. Да еще когда большая часть армии занимается непонятно чем по приказу какого-то аристократишки!\n\nВ наши мрачные времена политика – дело темное...", rewards = "Вы получите:\n\nЩит копейщика"},
[55] = {title = "Морбент Скверн", objective = "Примените Проклятье Морбента против Морбента Скверна, убейте его и верните Проклятье Морбента в лагерь Свена.", description = "Морбент Скверн прячется в своем доме на вершине холма на востоке, рядом с кладбищем Вороньего холма. Пора положить конец его бесчинствам в наших землях…\n\nПримени против него Проклятье Морбента, оно обратит в прах всю его защитную магию.\n\nУбей его. Убей негодяя и избавь нас от его гнусных козней. Стань орудием возмездия, <герой/героиня> Сумеречного леса.", progress = "Неужели Морбент Скверн повержен?!", completion = "Морбент Скверн убит. Темные всадники по-прежнему топчут наши земли, но все же мы одержали победу, хотя и неполную. Я надеялся на это вопреки всему.\n\nТы совершил невозможное, и легенды о тебе будут ходить во всему Сумеречному лесу.\n\nСтупай, Бронгард. Быть может, судьба вновь приведет тебя ко мне...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКюлоты Ночного ДозораПлащ начальника караулаКапюшон Искристого Металла\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nФакел Божественного пламени"},
[56] = {title = "Ночной дозор", objective = "Убейте 8 скелетов-воинов и 6 магов-скелетов по просьбе командира Алтеи Чернодрев.", description = "Я – командир Ночного дозора, и мой долг – охранять покой жителей Темнолесья. Солдаты Штормграда оставили свои посты, предоставив нас самим себе.\n\nЕсли ты <готов/готова> на подвиги, помоги нам! Отправляйся в Застывшие сады на юге от Темнолесья и убей 8 скелетов-воинов и 8 магов-скелетов. Мы должны дать отпор нежити!", progress = "Вижу, ты снова здесь. Если ты хочешь оказать помощь Ночному дозору, возвращайся, когда убьешь 8 скелетов-воинов и 8 магов-скелетов.", completion = "Великолепно, Бронгард. За верную службу народу Темнолесья тебе полагается награда.", rewards = "Вы получите:\n\n"},
[57] = {title = "Ночной дозор", objective = "Убейте 15 скелетов-губителей и 15 ужасных скелетов по просьбе командира Алтеи Чернодрев.", description = "<имя>, я получила сведения о появлении нежити в наших лесах! Если ты не боишься, отправляйся на кладбище Вороньего холма и убей 15 скелетов-губителей и 15 ужасных скелетов. Также говорят, что скелеты появились и к югу от Темнолесья, на Безмятежном кладбище. Мы должны изгнать нежить из Сумеречного леса!", progress = nil, completion = "Народ Темнолесья благодарит тебя, Эфром. Ты доказал свою преданность Ночному дозору.", rewards = "Вы получите:\n\n"},
[58] = {title = "Ночной дозор", objective = "Убейте 20 распространителей чумы в восточном мавзолее Вороньего холма по просьбе командира Алтеи Чернодрев.", description = "Обстановка на Вороньем холме не улучшилась. Безопасность Темнолесья – в твоих руках, <имя>. У нас не хватает стражей для обеспечения безопасности города. Придется тебе снова отправиться на Вороний холм и уничтожить 20 распространителей чумы в восточном мавзолее.", progress = nil, completion = "Я благодарю тебя, Эфром, от лица народа Темнолесья и от себя, как главы Ночного дозора, за храбрость и преданность общему делу. Да озарит Свет твой путь!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНагрудный патронташ Ночного ДозораКолчан Ночного ДозораДжутовый мешок Ночного Дозора\n\nВы также получите:\n\n"},
[59] = {title = "Броня из кожи и ткани", objective = "Отдайте Саре Тимберлейн знак брони Штормграда.", description = "Твои хитроумие и доблесть должны быть вознаграждены. Я приготовил для тебя знак: он пригодится для какой-нибудь части доспехов. Отнеси его Саре Тимберлейн на Лесопилку Восточной долины: она изготовит для тебя броню, или что там тебе будет нужно. Мне хотелось бы надеяться, что новые доспехи помогут тебе, <имя>, в защите Элвиннского леса от врагов.\n\nЛесозаготовки находятся к востоку от сторожевого поста Томаса.", progress = "Армия Штормграда поручила мне снабжение солдат одеждой и доспехами.\n\nЕсли ты дашь мне знак брони, я буду рада помочь тебе.", completion = "Ага, вот и знак! Благодарю. Можешь выбрать любой доспех, какой тебе нужен.\n\nЖелаю удачи, |3-6(Паладин)! Надеюсь, новый доспех тебе пригодится.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nХорошо прошитое одеяниеЗаплатанные штаны\n\nВы также получите:\n\n"},
[60] = {title = "Свечи кобольдов", objective = "Принесите 8 больших свечей в Златоземье Вильяму Песту.", description = "Приветствую тебя, <добрый путник/прекрасная госпожа>! Не найдется ли у тебя свободной минутки?\n\nМы с братом держим аптеку в Штормграде; так вот, мне тут понадобились большие свечи. Воск нужен, понимаешь? Я вот и думаю: может, ты мне поможешь?\n\nСвечи можно достать у кобольдов, а кобольдов, по слухам, в Элвиннских рудниках видимо-невидимо: и в руднике Подземных глубин к югу отсюда, и в Яшмовой шахте на востоке... Может, прогуляешься туда и раздобудешь для меня свечи?", progress = "Ну как, ты уже раздобыл свечи?", completion = "Ну что, пришлось попотеть? Спасибо за свечи, Wrestlecake! А вот и твоя награда...", rewards = "Вы получите:\n\nГорящая восковая палочка"},
[61] = {title = "Посылка в Штормград", objective = "Доставьте посылку Вильяма Моргану Песту в Торговый квартал Штормграда.", description = "В Штормграде мой брат Морган ждет посылки со свечами. У меня нет времени съездить туда самому, но если ты окажешь нам эту услугу, Морган хорошо тебе заплатит.\n\nВот, я тут упаковал свечи. А Моргана найти несложно, он работает в Торговом квартале Штормграда, в аптеке Песта.", progress = "О, да это посылка от моего братца! Вот это здорово! Определенно, сегодня мой счастливый день!", completion = "Вот плата за услугу... Кстати, можешь тут пока осмотреться: уверен, у нас наверняка найдется какое-нибудь зелье или безделушка, которые тебе пригодятся...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВзрывчатая ракетаМасло ОлафаЭликсир львиной силы\n\nВы также получите:\n\n"},
[62] = {title = "Рудник Подземных глубин", objective = "Исследуйте рудник Подземных глубин и вернитесь в Златоземье с докладом для маршала Дугхана.", description = "Рудник в Североземье – не единственная головная боль. До меня дошли известия о том, что и на элвиннском руднике Подземных глубин поселились кобольды.\n\nНужно исследовать рудник и подтвердить эти известия или опровергнуть их. Я буду ждать отчета. Рудник расположен к югу от Златоземья, между фермами Стоунфилд и Маклур.", progress = nil, completion = "Скверные вести. И что дальше? Может, драконы?! Похоже, придется усилить охрану рудника. Спасибо тебе, Wrestlecake. И подожди, не уходи... возможно, у меня найдется для тебя еще одно задание.", rewards = "Вы получите:\n\n"},
[63] = {title = "Зов Воды", objective = "Одолейте оскверненное воплощение воды и поместите в жаровню Вечного источника в Серебряном бору его браслеты и оставшиеся капли чистейшей воды.", description = "На побережье Серебряного Бора, к западу от Гробницы, находится святилище, оскверненное чумой. Духи перестали разговаривать с нашим народом, и тебе предстоит победить воплощение воды и очистить купель.\n\nВозьми браслеты элементалей и остатки зелья Брин и помести их в жаровню. Этот ритуал позволит призвать чистого духа, с которым можно будет поговорить.\n\nПринеси мне доказательство того, что мое задание выполнено, и в награду я дам тебе тотем.", progress = "Жаровня все еще отражает окружающий свет, и, подойдя поближе, вы видите, что пламя тихонько колеблется.\n\nПохоже, эти места не так сильно затронула порча, и в целом, если не считать недостающих компонентов, жаровня готова к ритуалу призыва очищенного воплощения воды.", completion = "Вы помещаете браслеты в жаровню и выливаете в огонь оставшиеся капли зелья Брин. Пламя потрескивает, а вы начинаете проговаривать простые слова, которым вас обучила Ислен...", rewards = "Вы получите:\n\n"},
[64] = {title = "Забытая вещь", objective = "Верните фермеру Хмуроброву его карманные часы, которые находятся в платяном шкафу в его доме на тыквенной ферме на западе.", description = "Это было ужасно! Верна разбудила меня, когда услышала гвалт в поле. Поля были полны хулиганья. Мы бежали в спешке, и я забыл взять с собой карманные часы. Папаша Верны подарил мне эти часы в день нашей с ней свадьбы, и мне прямо нехорошо от мысли, что ими могли завладеть те воры. Я оставил часы в доме, в платяном шкафу. Ищи тыквенную ферму к западу отсюда – ты ее не пропустишь. Если вернешь мне мои часы, я буду очень признателен!", progress = "Боюсь, тебе так и не удалось достать мои часы?", completion = "Мои часы! Благодарю тебя, любезный господин!\n\nМы всего лишь бедные фермеры, потерявшие свою землю, но прошу тебя, прими эту награду в знак нашей признательности.", rewards = "Вы получите:\n\nСвежевыпеченный хлебЛедяное молоко"},
[65] = {title = "Братство Справедливости", objective = "Поговорите с Вилли в Приозерье по просьбе Гриана Камнегрива.", description = "Группа негодяев, ответственных за то, что честные люди покидают Западный Край, зовет себя Братством Справедливости. Мне нужно, чтобы ты <проник/проникла> в эту бандитскую шайку. Нам нужно узнать, кто ее главарь, и где они прячутся. В деревне Приозерье, в таверне, обитает некий Вилли, который мне кое-чем обязан.\n\nОтправляйся в деревню Приозерье, что расположена в Красногорье, к востоку от Элвиннского леса, и все разузнай.", progress = nil, completion = "Так значит, тебя послал Камнегрив? Что ж, я перед ним в долгу.", rewards = "Вы получите:\n\n"},
[66] = {title = "Легенда о Сталване", objective = "Найдите клерка Далтри в ратуше Темнолесья.", description = "Вчера ночью меня охватил беспричинный ужас. Я почувствовала, что моя внучка Алисса оказалась в страшной опасности. Я разложила карты... и со стола на меня взглянула Смерть.\n\nПогрузившись в длительный и тяжкий транс, я сумела разгадать эту темную тайну. Мне открылось имя: Сталван.\n\nОтыщи клерка в городской Ратуше и постарайся побольше разузнать об этом Сталване. Я опасаюсь за всех нас.", progress = nil, completion = "А, так тебя послала мадам Ева...", rewards = "Вы получите:\n\n"},
[67] = {title = "Легенда о Сталване", objective = "Отправьтесь в Лунореченскую школу и сообщите все сведения о Сталване клерку Далтри.", description = "Сталван, значит? Дай-ка погляжу в журнал.\n\nСталван... Сталван... Ну-ка... А, вот он! У меня есть запись о некоем господине Сталване Мистмантле. Последний адрес – Лунореченская школа. Но это было так давно!\n\nОкажи любезность, дай знать, если выяснишь что-либо об этом типе. Записи должны содержаться в порядке.", progress = nil, completion = "Старый сундук со скрипом открывается...", rewards = "Вы получите:\n\n"},
[68] = {title = "Легенда о Сталване", objective = "Отнесите пыльное неотосланное письмо клерку Далтри.", description = "Вы находите в старом сундуке пыльное неотосланное письмо.", progress = "А, я тебя помню. Это ты спрашивал насчет Сталвана. Удалось его отыскать?", completion = "Занятно. Значит, этот тип все же побывал в Луноречье. Странно, что письмо так и не доставили. Тем не менее я обновлю записи в журнале.", rewards = "Вы получите:\n\n"},
[69] = {title = "Легенда о Сталване", objective = "Отправляйтесь в таверну \"Гордость льва\" и спросите, не слышал ли кто о Сталване.", description = "Боже мой! Сразу и не заметил. В журнале, точно под первым адресом Сталвана, написан еще один адрес, частично вычеркнутый. Похоже, он направлялся в таверну \"Гордость льва\" в Златоземье. Можешь поискать сведения там, <имя>.", progress = nil, completion = "Сталван? Знакомое имя.", rewards = "Вы получите:\n\n"},
[70] = {title = "Легенда о Сталване", objective = "Возьмите недоставленное письмо Сталвана из сундука и доставьте его в район каналов Штормграда.", description = "Имя Сталван мне знакомо. А, вспомнил.\n\nМного лет назад ненастной ночью в трактир явился гонец, искавший убежища от непогоды. Около полуночи этот человек, бледный от страха, сбежал вниз по лестнице в пижаме и исчез.\n\nВторопях он оставил письма в сундуке на втором этаже. За ними он так и не вернулся. Осталось одно, от этого Сталвана. Адресовано оно в район каналов Штормграда. Можешь прочитать.", progress = "Что это у тебя? Дай-ка посмотреть...", completion = "А ты не робкого десятка, раз решился доставить это.", rewards = "Вы получите:\n\n"},
[71] = {title = "Доклад для Томаса", objective = "Отдайте стражнику Томасу у восточного моста Элвиннского леса медальоны стражей Рольфа и Малакаи.", description = "Теперь, когда вы нашли оба медальона, отнесите их к мосту и отдайте стражнику Томасу: он должен узнать о смерти обоих стражей.", progress = "Приветствую, Wrestlecake. Тебе удалось узнать, что случилось с Рольфом и Малакаи?", completion = "Увы, Wrestlecake, мои худшие опасения подтвердились. Мурлоки – это угроза, с которой придется считаться...", rewards = "Вы получите:\n\n"},
[72] = {title = "Легенда о Сталване", objective = "Найдите улики в пожитках управляющего Фольсома.", description = "Мой отец был сторожем в этом поместье задолго до меня. Ему-то и пришлось вытирать кровь после того убийства. Но это к делу не относится.\n\nПоследние деньги треста Кременника давно иссякли. А теперь и последние семейные ценности отправляются прямиком на аукцион. Проклятые сборщики налогов!.. Пожалуй, если ты хочешь узнать побольше, можешь порыться в этом барахле. Кто знает, что тебе попадется.", progress = nil, completion = "Вы медленно снимаете крышку с ящика...", rewards = "Вы получите:\n\n"},
[74] = {title = "Легенда о Сталване", objective = "Отнесите страницу из дневника маршалу Хаггарду.", description = "Внутри ящика вы находите много разных вещей: пыльные фамильные ценности, портрет, несколько охотничьих трофеев и старые книги. Уже на самом дне, под глиняной вазой, вам попадается страница, вырванная из дневника.", progress = "Что это у тебя? Не вижу. Зрение стало совсем никудышное. Дай-ка страницу сюда.", completion = "Я едва разбираю буквы, но почерк напоминает мне о... Да, я видел что-то подобное до того, как мое зрение окончательно испортилось.", rewards = "Вы получите:\n\n"},
[75] = {title = "Легенда о Сталване", objective = "Найдите в сундуке на втором этаже выцветшую страницу с записями.", description = "Когда я только приехал сюда, в сундуке на втором этаже лежала кипа пергаментов. Как-то раз я их просмотрел, но потом зрение стало не то, и я махнул на них рукой.\n\nОкажи любезность слепому старику, поищи в сундуке наверху что-нибудь, что сможет помочь тебе разузнать о Сталване. Мне кажется, там была выцветшая страница с интересными записями. Принеси ее мне, и я помогу тебе по мере сил.", progress = "Ну что, нашел страницу, о которой я говорил?", completion = "Это она!", rewards = "Вы получите:\n\n"},
[76] = {title = "Яшмовая шахта", objective = "Обследуйте Яшмовую шахту и вернитесь с докладом в Златоземье к маршалу Дугхану.", description = "Благодаря тебе мы знаем, что рудник Подземных глубин заполонили кобольды. Но нам нужен разведчик, чтобы выяснить, что творится в Яшмовой шахте.\n\nОтправляйся туда и доложи мне, если обнаружишь кобольдов. Иди на восток по дороге, пока не доберешься до Башни Азоры, оттуда поверни на север, и у подножия гор отыщешь шахту.", progress = "Приветствую тебя, Ардаш. Какие новости? Что удалось обнаружить в Яшмовой шахте?", completion = "Кобольды в Яшмовой шахте? Так это правда? Проклятье! Дела идут все хуже и хуже!\n\nКонечно, я благодарен тебе за информацию, Wrestlecake, но лучше бы мы ошибались...", rewards = "Вы получите:\n\n"},
[77] = {title = "Грязное дело", objective = "Найдите заброшенную базу Орды на Осклизлой скале и заберите из ящиков 10 бутылок \"Медовой зыби из Внутренних земель\".", description = "Я понял, про какую тару говорил Дран Дрофферс, у меня такая есть. Я помогу тебе разлить \"Медовую зыбь\" по бутылкам, чтобы этот грубиян, отец Мальтона, остался доволен. Но, разумеется, не бесплатно – взамен я хочу две бутылки \"Зыби\" для себя. Бутылки можно найти в ящиках на заброшенной базе Орды у Осклизлой скалы.\n\nДостать их будет нелегко, потому что в руинах кишмя кишат слизнюки и пиявки, и, говорят, у них там есть какой-то предводитель, что-то вроде верховного слизнюка. Но другого способа нет – придется тебе идти на базу и искать полные бутылки.", progress = "Я так понимаю, что ты принес мне бутылки с напитком, да?", completion = "Отличная работа, Томпсон. Я очень рад, что напиток не испортился – нет ничего хуже на вкус, чем негодная медовуха.\n\nПогоди минутку, магии нужно время, чтобы подействовать на этот ценный груз. Хотя, на самом деле, никакой магии тут нет – я всего лишь перелью эту \"Медовую Зыбь\" в новые бутылки, и тогда этот напиток превратится в величайшее сокровище!\n\nНу вот, готово!", rewards = "Вы получите:\n\n"},
[78] = {title = "Легенда о Сталване", objective = "Отнесите выцветшую страницу записей хозяину таверны Смиттсу.", description = "Я знаю, кто мог бы тебе помочь. Когда я служил в страже Штормграда, мы порой пропускали по стаканчику в темнолесской таверне \"Алый ворон\". Ее хозяин Смиттс всегда был знатоком преданий. Покажи ему эту страницу, посмотрим, что он скажет.", progress = "Тебя послал маршал Хаггард? Что ж ты молчишь?\n\nЭх, старина Хаггард. Бедняга скоро совсем ослепнет. Впрочем, давай, покажи, что там у тебя.", completion = "Клянусь Светом! Я узнаю этот почерк!", rewards = "Вы получите:\n\n"},
[79] = {title = "Легенда о Сталване", objective = "Отнесите грязную страницу командиру Альтее Чернодрев.", description = "Я много лет следил за легендами, ходящими об этом Сталване. Когда несколько лет назад нескольких заезжих аристократов нашли мертвыми, мы с Хаггардом решили расследовать это дело. Я отыскал несколько заляпанных грязью страниц, но мы так и не нашли связи между ними и этим лесным сумасшедшим. Найденные тобой улики подтверждают его вину. Немедленно отнеси эту страницу командиру Чернодрев и расскажи ей о добытых сведениях!", progress = "Надеюсь, ты ко мне не по пустякам пришел, |3-6(Паладин). Но, во имя Света, говори быстрее. Для меня превыше всего безопасность Темнолесья, и терять время впустую я не намерена.", completion = "Надо же, ты оказался настоящим сыщиком, |3-6(Паладин).", rewards = "Вы получите:\n\nСтраница записей, запятнанная кровью"},
[80] = {title = "Легенда о Сталване", objective = "Покажите запятнанную кровью страницу записей клерку Далтри.", description = "Я давно присматриваюсь к этому Сталвану. Но если эта страница написана той же самой рукой, то его вина несомненно доказана.\n\nЗа долгие годы службы клерк Далтри стал настоящим экспертом по различению почерков. Покажи ему эту страницу, проверь, совпадает ли почерк с росписью в журнале.", progress = "И снова ты здесь, Эфром. Что на этот раз?", completion = "Несомненно! Почерк на этой странице совпадает с подписью в журнале.", rewards = "Вы получите:\n\n"},
[81] = {title = "Груз медовухи", objective = "Доставьте бочонок в Оргриммар Драну Дрофферсу.", description = "Я позаботился о том, чтобы ничего не пропало – ни медовуха из бочонка, ни лишние бутылки. Не то чтобы я так уж тепло относился к Драну, но нет ничего хуже, чем когда пропадает выпивка! Вот, держи.\n\nДоставь этот бочонок Драну Дрофферсу в его забегаловку в Оргриммаре. Да, и пожалуйста, не забудь передать привет Мальтону. Скажи, что если он соскучится по отличной выпивке и великолепным собутыльникам, то мы будем в восторге от его визита.", progress = "Если ты не собираешься ничего покупать и у тебя нет ничего с собой, значит, ты впустую отнимаешь у меня время! Где моя медовуха?", completion = "Ну-ка, ну-ка, надо еще посмотреть, что там в этом бочонке!\n\nДа, похоже, все цело. Ну, вот твоя плата за доставку. Я выручу впятеро больше, когда продам ее у себя в таверне! Хы-хы!\n\nНу, а эти лишние бутылки \"Медовой зыби\" из Внутренних земель прибережем для особых случаев. Надо попробовать смешать ее с шампанским. Назовем это... медованским!", rewards = "Вы получите:\n\n"},
[82] = {title = "Исследование Ядовитого улья", objective = "Принесите 5 частей тел насекомых Сентипаар из Ядовитого улья алхимику Пестычинсу в Прибамбасск.", description = "Все эти сообщения о жуках... нам известно, что они опустошают пруды в Ядовитом улье. А НЕИЗВЕСТНО нам... все остальное.\n\nДля начала надо узнать, кто наш враг! Ступай в Ядовитый улей и добудь части тел проклятущих насекомых Сентипаар. Отнеси их алхимику Пестычинсу, пусть повозится. Если уж он возьмется за работу, скоро мы обо всем узнаем!", progress = "Ты ведь младший геодезист, да? Говори скорее, ситуация серьезная! Ты принес мне части тел насекомых, обещанные Рудознатцем?!", completion = "Неплохая работа – я немедленно примусь за анализ этих частей! Сразу скажу одно – таких насекомых я еще не видел. Такое впечатление, что ими управляет какая-то чуждая сила.\n\nНемедленно поговори с Рудознатцем; ситуация серьезная, ему без сомнений понадобится твоя помощь! Не знаю точно, но скорее всего речь снова пойдет о насекомых пустыни Танарис!", rewards = "Вы получите:\n\n"},
[83] = {title = "Красный лен", objective = "Принесите 6 красных льняных повязок на Лесопилку Восточной долины и отдайте их Саре Тимберлейн.", description = "В Североземье Братство Справедливости носит маски из холстины; в Элвиннском лесу они предпочитают лен, который мог бы принести мне гораздо большую пользу... и прибыль.\n\nПринеси мне красные повязки, а я сделаю из них кое-что полезное для тебя.\n\nЛагеря братства разбросаны по всему Элвиннскому лесу.", progress = "Послушай, Wrestlecake, у меня лен кончается. Может, выручишь меня?", completion = "Отличные повязки, даром что ткань грубовата...\n\nВот, держи!", rewards = "Вы получите:\n\nКрасная льняная рубашкаКрасный льняной кушак"},
[84] = {title = "Назад к Билли", objective = "Отнесите пирог со свининой на Виноградники Маклура и отдайте его Билли.", description = "Вот, держи. Отдай этот пирог Билли, да не забудь сказать, что я желаю ему подавиться!", progress = "О-ох... Помираю с голоду... Эй, Wrestlecake, не угостишь пирожком?", completion = "М-м, вкуснятина! Пирог что надо!\n\nПохоже, ко мне возвращается память...", rewards = "Вы получите:\n\n"},
[85] = {title = "Потерянное ожерелье", objective = "Поговорите с Билли Маклюром.", description = "Я потеряла ожерелье. Сдается мне, его стащил этот беспризорник Билли Маклур! Вечно он шастает по виноградникам, как крыса какая-то! Если решишь его искать, то сходи на виноградники, это к востоку отсюда.\n\nПожалуйста, разыщи мое ожерелье, порадуй старуху-вдову!", progress = nil, completion = "Чего-чего она там потеряла? Какое такое ожерелье? Не брал я его, даже в глаза не видел, и вообще я не вор какой-нибудь!\n\nМожет, я и знаю, кто мог это сделать... Вот только вспоминать на голодный желудок сложно, в голове мутится.", rewards = "Вы получите:\n\n"},
[86] = {title = "Пирог для Билли", objective = "Принесите 4 куска кабаньего мяса на ферму Стоунфилд и отдайте тетушке Бернис.", description = "Может, если бы я получил пирог, то смог бы вспомнить, у кого сейчас это твое ожерелье. Кстати... Говорят, у тетушки Бернис получаются отличные пироги со свининой. \n\nЯ вот что думаю: принеси ей кабаньего мяса – около ферм кабанов ошивается видимо-невидимо – и попроси испечь для тебя пирог.", progress = "Что? Я еще должна кормить пирогами мальчишку, который стащил мое ожерелье?! С другой стороны, если подумать, пирог – не такая большая цена за то, чтобы вернуть ожерелье назад.\n\nЛадно уж... Кабанье мясо у тебя есть?", completion = "Хоть мясо и жестковато, его можно потушить на медленном огне и приготовить отличную начинку для пирога!", rewards = "Вы получите:\n\n"},
[87] = {title = "Фикс", objective = "Верните ожерелье тетушке Бернис на ферму Стоунфилдов.", description = "Я играл около рудника Подземных глубин и, похоже, уронил... М-м... В смысле, я там видел ожерелье этой самой дамы. Представления не имею, как оно туда попало; я тут ни при чем!\n\nВ общем, короче, я видел, как здоровенный кобольд с золотыми зубами схватил ожерелье и скрылся в руднике. Если отыщешь этого кобольда, найдешь и ожерелье, точно тебе говорю!", progress = "О, Wrestlecake? Привет, привет... Ну что, нашлось мое ожерелье?", completion = "Мое ожерелье! Оно нашлось! О, дорогуша, спасибо, спасибо!\n\nВот, держи. Это принадлежало моему мужу; \"счастливая вещица\" – он всегда так говорил. Если бы только он взял это с собой в последний поход!..", rewards = "Вы получите:\n\nПерчатки Львиного следа"},
[88] = {title = "Принцесса должна умереть!", objective = "Убейте Принцессу, заберите ее ошейник и отнесите на ферму мамаше Стоунфилд.", description = "У семейства Бреквеллов имеется свинья. Не простая, а призовая, по кличке – ты только представь себе! – Принцесса. И эта громадная гора сала то и дело пробирается на мой огород! Чтобы пожирать мои овощи!\n\nТак вот, прежде чем эта скотина доберется до полей... словом, Принцесса должна умереть! Принеси мне ее ошейник в доказательство того, что это свершилось, а взамен получишь кое-что полезное.\n\nПринцессу держат на тыквенной ферме Бреквеллов: это к востоку от фермы Маклуров. Разберись с ней прежде, чем она проголодается и вернется сюда!", progress = "Ну как? Надеюсь, Принцесса уже мертва?", completion = "Счастье-то какое! Эта хавронья была такой громадной, что в один присест сожрала бы весь наш урожай! Я так тебе благодарна, Wrestlecake!\n\nВзгляни: что-нибудь из этого тебе, надеюсь, подойдет?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВыцветшие сапогиУкрашенные латунью наручиСапоги фермера\n\nВы также получите:\n\n"},
[89] = {title = "Мост Безмолвия", objective = "Принесите 5 железных пик и 5 железных клепок штейгеру Ослоу в Приозерье.", description = "Из-за последнего нашествия орков нам пришлось переплавить весь металл на пули, мечи и доспехи. Мы посылали в Штормград за новыми поставками, но отряд гноллов Красногорья разграбил обоз и сбежал в холмы за Приозерьем.\n\nНам не хватает материалов на ремонт моста. Если ты принесешь мне 5 железных пик и 5 железных клепок, <имя>, я прикажу тебя наградить.\n\nЗа дело!", progress = "Мост сам собой не строится! Где железные пики и железные клепки?", completion = "Отличная работа, Бронгард. Мы можем продолжить восстановление моста. Еще немного, и закончим.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБрюки кузнецаПерчатки мостового рабочегоПерчатки для верховой езды\n\nВы также получите:\n\n"},
[90] = {title = "Пряные котлеты из волчатины", objective = "Принесите 10 постных волчьих боков и травяные приправы Штормграда шеф-повару Груалю в Темнолесье.", description = "Мое коронное блюдо – пряные котлеты из волчатины! Разумеется, я могу тебе их пожарить. Но для этого мне понадобятся кое-какие продукты. Принеси 10 постных волчьих боков и немного травяных приправ Штормграда. В лесу полно волков, и добыть мясо будет несложно. Что до приправы, то ее можно купить у Фелисии Гамп в цветочном магазине в районе каналов Штормграда.", progress = "Ты принес 10 постных волчьих боков? А травяную приправу от Фелисии из Штормграда?", completion = "Отличная работа, Бронгард! Наслаждайся вкуснятиной – приправленной котлетой из волчатины!", rewards = "Вы получите:\n\nПриправленная котлета из волчатиныРецепт: приправленная котлета из волчатины"},
[91] = {title = "Закон Соломона", objective = "Принесите 10 подвесок Темношкуров помощнику судьи Конаху в ратушу Приозерья.", description = "В восточных предгорьях нашего края обосновался враг Штормграда. С помощью тайной магии этот негодяй по имени Моргант сеет ужас и страдания в нашем городе и окрестностях.\n\nОн прибрал под свою руку гноллов из стаи Темношкуров, и они исполняют его повеления. Согласно Закону Озер, пособничество врагу королевства карается смертью.\n\nГноллов следует уничтожить!\n\nПринеси мне 10 подвесок Темношкуров и получишь награду.", progress = "Принеси мне 10 подвесок Темношкуров и получишь награду.", completion = "Суд Озер благодарит тебя за помощь правосудию, Бронгард. Помогая претворить в жизнь законы Королевства, ты способствуешь установлению справедливости в наших землях.", rewards = "Вы получите:\n\n"},
[92] = {title = "Гуляш по-красногорски", objective = "Принесите Бреанне пять кусков жесткого мяса кондора, пять рыл больших сквернохряков и пять порций хрустящего паучьего мяса.", description = "Я бы с радостью сделала для тебя гуляш по-красногорски, но есть небольшое затруднение. Во время недавнего вторжения орков мне пришлось кормить целый отряд солдат Штормграда, и все кладовые опустели... Хотя если ты снабдишь меня всеми необходимыми продуктами, я уж расстараюсь!\n\nПринеси мне пять кусков жесткого мяса кондора, пять рыл больших жутевепрей и пять порций хрустящего паучьего мяса.", progress = "Мне все еще нужны пять кусков жесткого мяса кондора, пять рыл больших жутевепрей и пять порций хрустящего паучьего мяса.", completion = "Молодец, Эфром. И какие отличные куски! А вот и мое коронное блюдо – гуляш по-красногорски.", rewards = "Вы получите:\n\nГуляш по-красногорскиРецепт: гуляш по-красногорски"},
[93] = {title = "Темные пирожки с крабами", objective = "Добудьте 6 липких паучьих лапок и принесите их шеф-повару Груалю в Темнолесье.", description = "Открою тебе тайну: темные пирожки с \"крабами\" делаются из паучьих лапок! Понимаю, эта новость может быть для тебя неприятной, но пирожки получаются вкусные и ароматные – отличная закуска! Принеси мне липкие паучьи лапки, и я испеку для тебя пирожочки.\n\nГоворят, что лучшие лапки у ядовитых кругопрядов. Они плетут паутины на севере, между холмами и рекой.", progress = "Привет тебе, Бронгард. Ну как, удалось добыть липкие паучьи лапки?", completion = "О, отличные лапки! Дай-ка я замариную их особым составом, – не подсматривай! – потом хорошенько подрумяню на сковородке…\n\nИ хотя темные пирожки с крабами – мое коронное блюдо и рецептом я делиться не готов, вот тебе рецепт блюда не хуже.", rewards = "Вы получите:\n\nРецепт: пирожок из паучатины"},
[94] = {title = "Недремлющее Око", objective = "Отнесите амулет Азоры к статуе льва, стоящей рядом с башней Илгалара в Красногорье.", description = "Мой соперник Моргант – волшебник, наделенный великой силой, но лишенный сердечной доброты. Он обосновался в башне Илгалара, что в Красногорье. Я нашел способ следить за ним при помощи Ока Азоры.\n\nОднако Око не дает возможности проникнуть в его мысли. Для такого дела мне потребуется помощь.\n\nЕсли ты согласишься помогать мне, возьми амулет Азоры и отнеси его к башне Илгалара. Амулет нужно положить под статую льва рядом с башней.\n\nЕсли это будет сделано, то с помощью силы Азоры я смогу проникнуть в замыслы Морганта.", progress = "Статуя льва уже не одно десятилетие несет свою одинокую стражу у печально знаменитой башни Илгалара.\n\nУ подножия статуи есть углубление, куда можно вложить драгоценный камень или амулет...", completion = "Вы кладете амулет Азоры в углубление, и он словно бы врастает в камень. Вы слышите голос Теокрита:\n\nПрими мою благодарность, юный Эфром. Отныне ты сможешь говорить со мной посредством этого амулета. После того как я проникну в мысли моего соперника, у меня будет для тебя новое задание.", rewards = "Вы получите:\n\n"},
[95] = {title = "Месть Свена", objective = "Выясните, что зарыто за старым пнем на ферме, где работал Свен.", description = "Раньше я работал на одной из ферм на юго-востоке... а потом темные всадники спустились с перевала Мертвого Ветра и перебили всю мою семью, пока я был в отлучке!\n\nВернувшись, я увидел неподалеку от амбара неясную фигуру человека, который что-то закапывал. Он успел сбежать от меня, а задерживаться я не мог, потому что преследовал темных всадников. Так я и не узнал, что там спрятано.\n\nЕсли ты можешь выяснить, что закопал в землю этот незнакомец, я буду очень признателен. Поищи возле старого пня, рядом с амбаром.", progress = nil, completion = "Вы находите кучу торопливо накиданной земли. Похоже, кто-то хотел что-то спрятать... а времени у него не хватало.", rewards = "Вы получите:\n\n"},
[96] = {title = "Зов Воды", objective = "Отнесите осколок Воды Заклинательнице Воды Ислен в Степи.", description = "Возьми осколок. Возьми его и даруй жизнь.\n\nДаруй жизнь и пойми. Пойми, что вода – это жизнь... А порча – конец жизни.\n\nОберегай и даруй жизнь силой воды.", progress = "Ты вернулся. Отлично!\n\nКак путешествие в Серебряный бор? Много времени заняло?\n\nМне трудно понять, достиг ли ты успеха, ведь большая часть этих земель затронута порчей. Она затмевает все доброе, что есть в них. Впрочем, порой маленькая победа оказывается не менее важной, чем большая. Очищение воды здорово поможет и тебе, и другим шаманам.", completion = "А вот и доказательство твоих свершений, как я и просила.\n\nЯ рада, что могу первой поздравить тебя с успехом и вручить тебе этот... Тотем воды.\n\nПусть он служит тебе верой и правдой. Удачи!\n\nСледующее испытание ожидает тебя нескоро, поэтому учись хорошенько. Чистая вода не только вдыхает новую жизнь в раненых, но может также оказывать и другие эффекты. Когда найдешь время, поговори с наставником шаманов. Может быть, у него найдутся для тебя новые заклинания.", rewards = "Вы изучите:\n\nТотем исцеляющего потока\n\nСледующее заклинание будет наложено на вас:\n\nТотем исцеляющего потока\n\nВы также получите:\n\nТотем воды"},
[97] = {title = "Легенда о Сталване", objective = "Сообщите новости командиру Альтее Чернодрев.", description = "<имя>, немедленно сообщи командиру Чернодрев, что почерки совпадают! Ее подозрения подтвердились!", progress = nil, completion = "Я так и знала! Отличная работа, Эфром!", rewards = "Вы получите:\n\n"},
[98] = {title = "Легенда о Сталване", objective = "Убейте Сталвана Мистмантла и принесите мадам Эве его фамильное кольцо.", description = "Сталван Мистмантл вел порочную жизнь. От его руки погибли многие невинные люди. Несомненно, он виновен в бесчисленных преступлениях, а теперь угрожает и нашему Темнолесью. Лишь Свету известно, что за гнусные злодеяния он готовит. Ступай в его дом к северу от города, <класс>, и покончи со Сталваном раз и навсегда.\n\nПриведя мой приговор в исполнение, отправляйся к мадам Еве и покажи ей его фамильное кольцо. В конце концов именно ее предчувствие позволило нам раскрыть это темное преступление. Благодаря ей в Темнолесье стало безопаснее.", progress = "Да, Бронгард?", completion = "Знаю, Бронгард, Сталван мертв. Я ощутила волну надежды, пробежавшую по оскверненному лесу. Сумеречный лес раз и навсегда освободился от кровожадной твари. Мою радость омрачает лишь мысль о тех, кто пал жертвой этого чудовища. А ты отважен и хитер, |3-6(Охотник).", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПолумесяц Неприкаянных ДуховКольцо Неприкаянных духов\n\nВы также получите:\n\n"},
[99] = {title = "Безрассудство Аругала", objective = "Принесите 6 кандалов из деревни Погребальных Костров Далару Ткачу Рассвета в Гробницу.", description = "По мере того, как растет мое понимание магии Аругала, растет и мое презрение к этому злосчастному глупцу. Я уже почти закончил исследование его так называемого \"лекарственного зелья\". \n\nУ меня будет полная информация, когда я узнаю, какие чары служат причиной странностей, происходящих в деревне Погребальных Костров. Днем живущие там крестьяне выглядят по-человечески. Но когда солнце заходит, деревенский люд превращается в воргенов Лунного Гнева. \n\nМне нужно извлечь энергию из заколдованных кандалов, надетых на крестьян Аругалом. Принеси мне 6 заколдованных кандалов из деревни Погребальных Костров, <имя>.", progress = "Тебе удалось собрать для меня кандалы из деревни Погребальных Костров, Вота?", completion = "Твоя настойчивость весьма похвальна. С помощью информации, которую ты помог мне собрать, Аругал падет, и вся его безрассудная магия развеется. Браво, Вота.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБревноколПест-костоломПепельный жезл\n\nСледующее заклинание будет наложено на вас:\n\nЧародейский интеллект\n\nВы также получите:\n\n"},
[100] = {title = "Зов Воды", objective = "Поговорите с Низшим воплощением воды в Серебряном бору.", description = "Отзвучали последние слова заклятья, и вас ослепляет вспышка света. Звуки капель, падающих на пламя, стихают, и вас переполняет радость: ведь оскверненные духи вокруг вас уничтожены.", progress = nil, completion = "Спасибо тебе. Спасибо шаманам.\n\nПорча отступает, но жизнь продолжает увядать. Пусть шаманы охраняют жизнь.", rewards = nil},
[101] = {title = "Тотем наказания", objective = "Принесите 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда мадам Еве в Темнолесье.", description = "По лесу расползается тление и порча, <имя>, и все мы вынуждены позаботиться о самозащите. Ветер несет мне вести о великой опасности, поджидающей тебя в ближайшем будущем.\n\nЕсли ты желаешь оградить себя от нее, <благородный/благородная:c> <класс>, принеси мне 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда. Тогда я создам тотем Кары, который будет наносить урон тем, кто попытается напасть на тебя.", progress = "Принеси мне 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда, и я создам тотем Кары, который будет наносить урон тем, кто попытается напасть на тебя.", completion = "Ты поступил мудро, Бронгард. Этот тотем Кары защитит тебя от зла, таящегося по всему Азероту и за его пределами. Если тебе будет что-то угрожать, возьми тотем в руку – и его магическая аура защитит тебя. Не теряй мужества, прекрасный |3-6(Охотник). Тебе оно понадобится, ибо я чувствую – грядет немало кровопролитных сражений.", rewards = "Вы получите:\n\nТотем Кары"},
[102] = {title = "Патрулирование Западного Края", objective = "Принесите капитану Данувину на Сторожевой холм 8 лап гноллов.", description = "Штормград отвернулся от нас. Злобный ветер несчастий носится по равнинам Западного Края. Это была моя родина, и я не отвернусь от местных жителей, решивших остаться здесь. Мы, бывшие фермеры, намерены постоять за себя.\n\nТвое задание, если ты за него возьмешься, будет состоять в том, чтобы патрулировать луга Западного Края. Выследи и убей мерзких гноллов, которые, похоже, действуют заодно с ворами из Мертвых копей. Принеси мне 8 лап гноллов, и я вознагражу тебя за проявленное мужество.", progress = "Набрал ли ты уже 8 лап с тех вероломных гноллов?", completion = "Хорошая работа, Эфром. Если на стороне народного ополчения будут такие смельчаки, как ты, Западный Край сможет когда-нибудь вновь стать процветающей житницей, какой был когда-то. Пожалуйста, прими эту награду в знак признательности за твои усилия.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПояс народного ополченияНаручи народного ополчения\n\nВы также получите:\n\n"},
[103] = {title = "Хранитель пламени", objective = "Принесите капитану Грейсону на Маяк в Западном Крае 5 бурдюков с маслом.", description = "Ночь, когда погибла семья смотрителя маяка, была ужасной. Я беспомощно наблюдал за происходившим, поскольку сам Старый Мрачноглаз вел нападавших. Но что случилось, то случилось, и теперь жизнь моряков, плавающих по Великому морю и близко подходящих к опасным прибрежным рифам – моя забота. Поддерживать огонь маяка оказалось некому, и эта обязанность легла на мои плечи.\n\nПомогите мне поддержать огонь факела – принесите 5 фляг масла, собрав их с сельскохозяйственных големов.", progress = "Огонь вскоре погаснет, если не будет масла, Хрофтгор.", completion = "Хвала тебе, смелый |3-6(Воин). Рифы побережья Западного Края будут освещены благодаря твоим трудам. Множество жизней будет спасено, пока горит факел.\n\nМеня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСлабое зелье маныСлабое лечебное зелье\n\nВы также получите:\n\nСвиток интеллектаСвиток выносливости"},
[104] = {title = "Опасность на побережье", objective = "Принесите чешую Старого Мрачноглаза капитану Грейсону к Маяку в Западном Крае.", description = "Когда моя жизнь оборвалась на скалах, я и понятия не имел, что уготовано мне на том свете. Маяк той ночью не светил, поскольку Старый Мрачноглаз перепугал семью смотрителя, и они убежали. Потом они вернулись и вновь зажгли пламя, но Мрачноглаз заставил более слабых духом мурлоков атаковать маяк вместе с ним. Во второй раз семье смотрителя не повезло, и вся она погибла у меня на глазах.\n\nУбейте Старого Мрачноглаза, если увидите его на берегу, принесите мне одну из его чешуй, и я вознагражу вас.", progress = "Ну как, вам еще не удалось справиться с угрозой по имени Старый Мрачноглаз? Его видели носящимся вдоль береговой линии Западного Края.\n\nВозвращайтесь ко мне, когда злобная тварь будет мертва.", completion = "Итак, это злобное чудовище, Мрачноглаз, мертво. Хорошая работа, Бронгард. Вы своими руками прервали одну жизнь, но, возможно, тем самым спасли множество других. Великое море, само по себе исполненное угрозы, станет этой ночью чуточку безопаснее благодаря вашему героическому деянию.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nФакел ГрейсонаКулачный щит МоряЖезл факельного света\n\nВы также получите:\n\n"},
[105] = {title = "Увы тебе, Андорал", objective = "Принесите осколок оберега Араджа верховному палачу Деррингтону в Бастион в Западных Чумных землях.", description = "Увы, пришло время напасть на Андорал и изгнать оттуда лича!\n\nЗлобный Араж Призыватель обосновался в самом сердце руин. Его охраняют многочисленные воины Плети, рассеянные по всему центру бывшего города, а самого Аража охраняют сильнейшие бойцы. Без многочисленных помощников тебе нечего и думать одержать над ним верх.\n\nУбей Аража и принеси мне его кристалл-талисман!", progress = "Тебе было дано задание, Тириус. Ты принес мне кристалл лича в доказательство его выполнения?", completion = "Свершилось! Араж... этот лич наконец-то пал!\n\nСегодня ты оказал огромную услугу Орде. Храбрость и упорство – спутники подлинного героизма. Прошу тебя, прими это в залог нашей благодарности. Пусть все знают, что благодаря тебе Орда одержала победу!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЗнак решимости"},
[106] = {title = "Юные влюбленные", objective = "Отдайте любовное послание Мэйбелл Томми Джо Стоунфилду.", description = "За что мне это наказание? Мое сердце отдано Томми Джо Стоунфилду, я жить без него не могу, но наши родители – заклятые враги! Я не только встретиться – даже взглянуть на него не могу!\n\nПожалуйста, отнеси Томми Джо это письмо. Он обычно бывает у реки к западу от фермы Стоунфилдов, а сама ферма – тоже к западу отсюда...", progress = "Письмо? От Мэйбелл? О, моя радость, свет моей жизни!.. Давай скорее письмо!", completion = "Я больше не могу жить в разлуке с ней! Я должен увидеть ее!", rewards = "Вы получите:\n\n"},
[107] = {title = "Записка для Вильяма", objective = "Отнесите записку бабули Стоунфилд Вильяму Песту.", description = "Бьюсь об заклад, у Вильяма Песта найдется зелье, которое поможет соединить наших юных влюбленных!\n\nВот, держи: отнесешь эту записку Вильяму. Найдешь его в Златоземье, в таверне \"Гордость льва\".", progress = "Что тут у тебя? Записка от бабули Стоунфилд? Ах, Милдред... Сто лет ее не видел. И что же она пишет?", completion = "У меня просто сердце разрывается, как подумаю об этих бедных детках, Мэйбелл и Томми Джо. Ах, молодость... Весна... Любовь...\n\nДумаю, я смогу им чем-нибудь помочь. Погоди-ка, дай подумать...", rewards = "Вы получите:\n\n"},
[109] = {title = "Доклад Гриану Камнегриву", objective = "Поговорите с Грианом Камнегривом. Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края.", description = "Похоже, <класс>, тебе довелось побывать не в одном бою... Думаю, тебе стоит явиться с докладом к Гриану Камнегриву. Он возглавляет ополчение, защищающее фермерские земли Западного Края. Думаю, твоя помощь ему не помешает. Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края.", progress = nil, completion = "А, так это мой друг тебя сюда отправил? С его стороны это большая любезность.\n\nЧто ж... Монархия Штормграда больше не поддерживает нас. Остается полагаться на ополчение. Если ты хочешь сражаться за свободу вместе с нами, я буду рад этому.", rewards = "Вы получите:\n\n"},
[110] = {title = "Анализ частей насекомых", objective = "Найдите в Прибамбасске алхимика Пестычинса и получите результаты анализа частей насекомых.", description = "Мне понадобится время на изучение оборудования Холстомера... и на приведение в порядок его дел. Ох, печенкой чую, не последняя это потеря, проклятые жуки еще покажут нам, где раки зимуют!\n\nПоговори, пожалуйста, с алхимиком Пестычинсом, узнай, как проходят исследования частей насекомых. Если все готово, принести мне результаты.", progress = nil, completion = "Да, результаты готовы. Они, мягко говоря, неприятные.\n\nК сожалению, наши подозрения подтвердились, и насекомых контролирует неведомая сила. И не только неведомая, но и злобная. Этих насекомых превратили в настоящих опустошителей. Я такого еще не видел!", rewards = "Вы получите:\n\n"},
[111] = {title = "Разговор с бабулей", objective = "Поговорите с бабулей Стоунфилд.", description = "Прошу тебя, <имя>, поговори с моей бабулей. Если кто и может сделать так, чтобы мы с Мэйбелл были вместе, так это она.\n\nБабуля сейчас дома – это к востоку отсюда...", progress = nil, completion = "Пока наши семьи враждуют, у Томми Джо и Мэйбелл вряд ли есть шансы; но, может, мы дадим им возможность хоть немного побыть вместе.\n\nХм... Что бы придумать...", rewards = "Вы получите:\n\n"},
[112] = {title = "Хрустальный фукус", objective = "Принесите Уильяму Песту в Златоземье 4 побега хрустального фукуса.", description = "Да, я могу приготовить для Мэйбелл напиток невидимости, чтобы она могла убежать с Виноградников Маклура к своему Томми Джо. Но для этого мне нужен хрустальный фукус.\n\nЭти водоросли растут в океане, и мурлокам иногда удается добыть их. Может, у тех, что живут на берегах Хрустального Озера, найдется нужный компонент. А озеро найти просто: нужно только пойти на восток от Златоземья.", progress = "Тебе удалось добыть хрустальный фукус? Уверен, Мэйбелл ждет не дождется встречи со своим драгоценным Томми Джо...", completion = "Ага, вот и фукус! Отлично, просто отлично! А теперь погоди минутку: сейчас напиток будет готов.", rewards = "Вы получите:\n\n"},
[113] = {title = "Анализ частей насекомых", objective = "Отнесите отчет старшему исследователю Рудознатцу в Прибамбасск. Получите копию отчета, как просил алхимик Пестычинс.", description = "Старший геодезист Рудознатец должен немедленно увидеть мой отчет. Более того... его должны увидеть все, кто умеет читать. Серьезная опасность грозит не только Танарису и Прибамбасску, но если сидеть, сложа руки, то и всему южному Калимдору. Да что там, всему Азероту – эти твари не собираются останавливаться.\n\nПусть Рудознатец сделает копию моего отчета, распространи ее среди всех своих союзников. Пусть все узнают об этом!", progress = "Ну как, младший геодезист Томпсон, старина Пестычинс подготовил отчет?", completion = "Спасибо за доставку отчета, младший геодезист Томпсон; вот плата за верную службу Водной компании Прибамбасска.\n\nХотя я не слишком люблю делиться информацией задарма с теми, кто мог бы заплатить за нее звонкой монетой, но Пестычинса я знаю много лет. Если он советует рассказать о нашествии насекомых всем и каждому, да будет так. Подожди немного, и я сделаю копию.", rewards = "Вы получите:\n\n"},
[114] = {title = "Вылазка", objective = "Отнесите напиток невидимости Мэйбелл Маклюр.", description = "Отнеси этот напиток невидимости юной Мэйбелл. Его действия хватит на то, чтобы девушка успела встретиться с Томми Джо.", progress = "Томми Джо прочел мое письмо? Что он сказал?", completion = "Мне так стыдно, что приходится обманывать свою семью... Но я не могу отказаться от Томми!\n\nБлагодарю тебя, Wrestlecake. Как только подвернется случай, я выпью этот напиток и найду способ пробраться к моему любимому.\n\nА в дополнение к словам благодарности прими вот это.", rewards = "Вы получите:\n\nСлабое лечебное зелье"},
[115] = {title = "Темная магия", objective = "Принесите 3 полуночных сферы маршалу Маррису в Приозерье.", description = "Орки из клана Черной Горы позвали на помощь чародеев, а те принесли с собой источники темной силы – полуночные сферы. Чародеи наносят чувствительные удары по защитникам Красногорья, и мы должны как можно скорее лишить их столь мощного оружия.\n\nДобудь для меня полуночные сферы. Ты найдешь их у чародеев Черной Горы. Я придумаю, как избавиться от Сфер, чтобы мир стал лучше и чище!", progress = "Как успехи с чародеями? Где полуночные сферы?", completion = "Благодарю тебя, Бронгард. Я немедленно прикажу уничтожить эту мерзость.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[116] = {title = "Засуха", objective = "Принесите кабатчику Дэниэлсу из Озер бочонок громоварского светлого из Западного края, бочонок \"Мерло\" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья.", description = "У меня возникло небольшое затруднение, <имя>. Еще немного, и все бутылки опустеют, а поставок алкоголя давно не было. Проклятые орки.\n\nНе хочешь подзаработать?\n\nПринеси мне бочонок громоварского светлого от Мрачнобуха Громовара из Западного Края, бочонок \"Мерло\" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья, и я тебя непременно награжу.", progress = "Принеси мне бочонок громоварского светлого от Мрачнобуха Громовара из Западного Края, бочонок \"Мерло\" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья, и я тебя непременно награжу.", completion = "Отличная работа, Бронгард! Я представляю, сколько дорог тебе пришлось исходить, чтобы принести мне такое количество первосортных напитков. Завсегдатаи трактира будут счастливы!\n\nМоя жена неплохая рукодельница. Прошу, прими плащ, сшитый ею, в знак моей признательности.", rewards = "Вы получите:\n\nТонкотканый плащКошелек, набитый монетами"},
[117] = {title = "Громоварское", objective = "Принесите Мрачнобуху Громовару 5 шишек хмеля.", description = "Торопись, мой друг, и иди побыстрей,\nЧтоб нашего пойла отведать скорей.\nОно ближе к пиву – не спутаешь с кашей,\nНо нужен нам хмель, чтоб сварить пойло наше.", progress = "Торопись, мой друг, и иди побыстрей,\nЧтоб нашего пойла отведать скорей.\nОно ближе к пиву – не спутаешь с кашей,\nНо нужен нам хмель, чтоб сварить пойло наше.", completion = "Хмель, и ячмень, и дрожжи, и солод -\nОт вкуса кидает то в жар, то в холод.\nНе надо просить и не надо молить,\nВедь можно себе из бочонка налить!", rewards = "Вы получите:\n\nБочонок громоварского"},
[118] = {title = "Цена подков", objective = "Отнесите записку Вернера кузнецу Аргусу в Златоземье.", description = "Я потратил так много железа на доспехи и оружие для стражников Штормграда, что теперь его не хватает даже на подковы для лошадей!\n\nОтнеси эту записку кузнецу Аргусу в Златоземье, я хочу попросить его прислать мне партию подков.", progress = "Что такое? Говоришь, Вернер тебя послал? Давай сюда его письмо. И ГОВОРИ ГРОМЧЕ!", completion = "Так старому Вернеру нужны подковы, да?!", rewards = "Вы получите:\n\n"},
[119] = {title = "Доставка подков", objective = "Вернитесь к Вернеру Осгуду в Красногорье. Отдайте ему ящик с подковами.", description = "Ладно, так и быть, пошлю ему 50 подков…\n\nВот они, уже упакованы, осталось только доставить! Передай Вернеру, что с ним приятно иметь дело. Пусть не забудет прочитать записку, прикрепленную к ящику!", progress = "О, да ты вернулся! Удалось достать подковы?", completion = "Спасибо, ты здорово мне помог.\n\nЧто это? Аргус приложил к ящику записку... Что?! Аргус хочет ПЛАТЫ? Пф!\n\nЛадно, Мэйнард, спасибо за помощь.", rewards = "Вы получите:\n\n"},
[120] = {title = "Гонец в Штормград", objective = "Мировой судья Соломон просит вас отнести отчет генералу Маркусу Джонатану в Штормград.", description = "Тяжелые настали времена, <класс>. Город в непрерывной осаде. Если из Штормграда не пришлют подкрепление, нам не выстоять. Я доверяю тебе важнейшее письмо. Отнеси его в Штормград генералу Маркусу Джонатану. И поскорее возвращайся с вестями – неважно, добрыми или злыми.\n\nСпеши!", progress = "С чем пришел?", completion = "Вольно, |3-6(Паладин).\n\nЧиновник Соломон – благородный человек. Его слова много для меня значат. Я поговорю с королем и объясню ему ситуацию. Заверьте доброго судью, что он получит подержку армии Штормграда. Я вышлю подкрепление, как только получу приказ Его Величества.", rewards = "Вы получите:\n\n"},
[121] = {title = "Посланец в Штормград", objective = "Отнесите ответ генерала Маркуса Джонатана мировому судье Соломону в Приозерье.", description = "Пока я жду ответа от короля, хочу, чтобы ты <отнес/отнесла> это письмо мировому судье Соломону. \n\n<Свободен/Свободна>, <класс>!", progress = "Новости от генерала? Когда прибудет подкрепление?", completion = "Благодарю тебя, |3-6(Паладин). В знак признательности Озер и Штормграда прими эти деньги.\n\nХотя, признаться, смысл этого письма туманен. Что-то неладно в нашем королевстве. Боюсь, это не конец, а начало войны.", rewards = "Вы получите:\n\n"},
[122] = {title = "Брюшная чешуя", objective = "Добудьте 6 лоскутов чешуи с брюха черных дракончиков и отнесите их Вернеру Осгуду в Красногорье.", description = "В обмен на подковы Аргус из Златоземья просит брюшную чешую черных дракончиков. Если ты добудешь мне 6 лоскутов чешуи, я смогу расплатиться с Аргусом... И для тебя что-нибудь сделаю.\n\nЧерных дракончиков можно отыскать к югу от Озер, но им не сидится на одном месте. Проще всего высматривать их, направляясь по другим делам, и охотиться по случаю.", progress = "Если я не отдам чешую жадине Аргусу, он пошлет за ней кого-нибудь другого. Ты уже добыл материал?", completion = "Спасибо! Теперь я смогу расплатиться с Аргусом...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги из черного дракончикаПерчатки из черного дракончика\n\nВы также получите:\n\n"},
[123] = {title = "Вымогатель", objective = "Пойдите в Златоземье к маршалу Дугхану и отдайте ему расписание Вымогателя.", description = "На этом листке – расписание поставок золота из рудников в Элвиннском лесу. Поставки расписаны по дням и часам, а в качестве получателя указан некий \"Вымогатель\".\n\nСудя по всему, Вымогатель обосновался неподалеку от тыквенного поля Бреквеллов в восточной части Элвиннского леса.\n\nПохоже, это важные сведения. Было бы неплохо сообщить их маршалу Дугхану: он сейчас в Златоземье.", progress = "Что?! Да никто из наших в Элвиннских шахтах уже несколько месяцев не работает!\n\nДай-ка сюда эту бумажку...", completion = "Хм... Я слышал об этом \"Вымогателе\", вот только не знаю, на кого он работает. Должен тебя поблагодарить: расписание поможет нам разгадать эту тайну...", rewards = "Вы получите:\n\n"},
[124] = {title = "Лай гноллов", objective = "Убейте 10 громил из стаи Красногорья и 8 мистиков из стаи Красногорья. Вернитесь к Вернеру Осгуду.", description = "Будто нам одних орков мало! А теперь вдоль хребта рядом с моими стойлами шастают громилы и мистики гноллов и при случае воруют лошадей…\n\nЕсли ты сможешь избавить меня от этих проходимцев, мы с лошадьми будем весьма признательны.", progress = "Лошади по-прежнему нервничают, а по ночам все еще доносится проклятый волчий вой. Прошу тебя, Груль, сделай что-нибудь с этими гноллами!", completion = "Благодарю тебя за помощь, Эфром!", rewards = "Вы получите:\n\n"},
[125] = {title = "Утраченные инструменты", objective = "Достаньте ящик с инструментами штейгера Ослоу со дна Озера Безмолвия.", description = "Мне не помешала бы помощь, <имя>. Наш город в осаде, и достать припасы и оборудование все труднее. Мои инструменты везли из Златоземья в фургоне, но мост был уничтожен. Мы перегрузили их в лодку, но тут орки пробили ее снарядом из катапульты! И вот невезенье, ящик опустился на самое дно озера.\n\nДостань его, <имя>, и я щедро вознагражу тебя.", progress = "Удалось вытащить инструменты?", completion = "Отличная работа, Бронгард! Я уж и не надеялся вновь увидеть свои инструменты.", rewards = "Вы получите:\n\nНакладки из жесткой кожи"},
[126] = {title = "Вой в холмах", objective = "Принесите лапу Изувоя Вернеру Осгуду в Приозерье.", description = "<имя>, гноллы по-прежнему здесь. Я слышу, как они завывают, охотясь в холмах над Приозерьем. И один из них воет громче других – это Изувой, их вождь.\n\nСтоит его прикончить, и вся стая разбежится! Убей его и принеси в доказательство отрубленную лапу.\n\nСоблюдай осторожность,  этот гнолл заслуженно возглавляет целую стаю. Он совсем не прост...", progress = "Изувой – опасное существо, Эфром. Если ты еще не готов сразиться с ним, я тебя понимаю.", completion = "И снова благодарю тебя за помощь. Штормград еле-еле справляется с орками, у них не хватает солдат, чтобы защищать Красногорье от напастей вроде гноллов.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо Железной волиЗолотые сапоги народного ополчения\n\nВы также получите:\n\n"},
[127] = {title = "Продажа рыбы", objective = "Принесите 10 тушек пятнистой рыбы-луны портовому начальнику Барену в Приозерье.", description = "Застывшее озеро славится пятнистой рыбой-луной. На нее всегда есть спрос... А мой запас подходит к концу!\n\nПринеси мне штук десять рыбин, и я хорошо за них заплачу. Если ты <сам/сама> не умеешь удить, то... Попытайся отнять рыбу у мурлоков!", progress = "Ну как, где моя рыба-луна?", completion = "Иметь с тобой дело – одно удовольствие, дружище!", rewards = "Вы получите:\n\nСуп из плавников мурлокаРецепт: суп из плавников мурлокаРыбий жир"},
[128] = {title = "Награда за головы орков Черной горы", objective = "Убейте 15 воителей из клана Черной горы.", description = "Мы должны уничтожить клан Черной Горы. Враг вторгся в наши земли. Эти горы по праву принадлежат королю Штормграда. До нас дошли сведения, что главы всех видов войск клана называются воителями. Их можно отыскать в северном лагере, к западу от дороги, ведущей в Пылающие степи.\n\nМировой судья Соломон распорядился перебить этих гнусных тварей. Убей 15 воителей из клана Черной Горы и возвращайся ко мне.", progress = nil, completion = "Вижу, ты доблестно сражался с кланом Черной Горы, |3-6(Чернокнижник). Ты оказал нашему городу неоценимую услугу.", rewards = "Вы получите:\n\n"},
[129] = {title = "Бесплатный обед", objective = "Отнесите обед стражнику Паркеру. Он патрулирует дорогу, ведущую в Темнолесье.", description = "Можешь оказать мне услугу? Я приготовила обед для стражника Паркера, но он ушел на дежурство... Он-то может постоять за себя, но простой горожанке вроде меня не стоит соваться в те края.\n\nЕсли ты отнесешь ему обед, я бесплатно тебя накормлю! Паркер патрулирует участок дороги, ведущей в Сумеречный лес.", progress = "Дарси прислала мне обед, да? У нее доброе сердце. Что ж... Пора подкрепиться!", completion = "Спасибо, вкусно и сытно покушать я люблю. Хранить Приозерье от нападений орков и гноллов нелегко!", rewards = "Вы получите:\n\n"},
[130] = {title = "Визит к травнице", objective = "Поговорите с травницей Красногорья Марти Джайнроз.", description = "Если ты все равно идешь к Дарси, не отнесешь ли ей от меня цветы? Букетик можно приобрести у травницы в Приозерье, в западной части города.\n\nТолько когда будешь покупать цветы… не говори травнице Марти, от кого они и кому...", progress = nil, completion = "Тебе нужен букет цветов? Ты вроде бы у нас недавно... уже нашел даму сердца?\n\nПонимаю, мне не следует совать нос не в свое дело, но приятно видеть витающую в воздухе любовь... особенно в такие опасные времена.", rewards = "Вы получите:\n\n"},
[131] = {title = "Доставка нарциссов", objective = "Отнесите Дарси букет нарциссов.", description = "Вот и букет. Я выбрала для тебя нарциссы. Мои любимые цветы!", progress = "И снова здравствуй, Мэйнард. Понравился ли Паркеру обед?", completion = "Какая прелесть! Надо поскорее поставить их в воду!\n\nНо... это любимые цветы Марти. Неужели Паркер послал тебя за букетом к этой ревнивой мегере? Ты ведь не сказал, для кого они? Иначе не удивлюсь, если она их отравила.\n\nНет-нет, ты ни в чем не виноват. Большое спасибо! А вот и твой обед.", rewards = "Вы получите:\n\nСоте из рыбы-луны"},
[132] = {title = "Братство Справедливости", objective = "Отнесите записку Вилли Гриану Камнегриву в Западный Край.", description = "То, о чем я хочу вам рассказать, может стоить мне жизни. Бандиты из Братства Справедливости замышляют что-то крупномасштабное. Последнее, что я слышал, – что они действуют заодно со всякими гноллами, кобольдами и даже гоблинами.\n\nОтнеси эту записку Камнегриву. В ней разъясняется все, что я знаю на эту тему.", progress = "Приятно видеть вас снова, Мэйнард. Так что там Вилли собирался рассказать?", completion = "Эх!.. Надо было сгноить этого мошенника, когда у меня был шанс. Но эта информация действительно очень важна. Хорошая работа.", rewards = "Вы получите:\n\n"},
[133] = {title = "Фигурка вурдалака", objective = "Добудьте 7 ребер вурдалаков и принесите их в хижину Аберкромби.", description = "Я живу вдали от города, никто меня не защищает, и даже странно, как это меня до сих пор не сожрали вурдалаки и мертвяки! Только вчера несколько костеглодов ломились ко мне в дом!..\n\nЯ хочу сделать особую фигурку – что-то вроде пугала для этой нежити. Для этого мне понадобится несколько ребер вурдалаков. Их можно добыть, убивая плотоядов, костеглодов, мозгоедов, гнилую нежить и распространителей чумы.\n\nПринеси мне ребра, и я дам тебе несколько монет.", progress = "Кажется, я слышу за домом шаги вурдалаков – надо поскорее сделать фигурку! Ты принес мне ребра вурдалаков?", completion = "О, спасибо. Это наверняка сработает!", rewards = "Вы получите:\n\n"},
[134] = {title = "Нападение огров", objective = "Вернуть ящик Аберкромби владельцу.", description = "Несколько недель назад я собирал травы вдали от дома, и на меня напал отряд огров! Я сбежал, бросив свой ящик с ценными инструментами и травами.\n\nПрогнав меня, они вернулись к своему кургану в южной части Сумеречного леса. Думаю, они оставили мой ящик неподалеку от кургана.\n\nПрошу тебя, <имя>, верни мне ящик, без него я как без рук.", progress = "Ты принес мой ящик? Коли так, пожалуйста... Быстро дай его сюда!", completion = "Хвала Нек... то есть ТЕБЕ, Эфром! Ты более чем заслуживаешь награды.\n\nАга! Как я счастлив! Впереди много радостных ночей!", rewards = "Вы получите:\n\n"},
[135] = {title = "Братство Справедливости", objective = "Отнесите записку Вилли Матиасу Шоу в Штормград.", description = "Интересно, что имел в виду Вилли, когда упомянул о Каменщиках. Оговорился или проговорился? Могут ли разбойники из Братства Справедливости быть связаны с Каменщиками? Только один человек должен знать наверняка: Матиас Шоу, глава ШРУ. Покажите ему записку Вилли и посмотрите, сможет ли он пролить свет на эту тайну. Если вам не сразу удастся найти Шоу, поищите в Казармах в Старом городе.", progress = "Какое у тебя ко мне дело? Я очень занятой человек...", completion = "Это дело может оказаться сложнее, чем полагает Камнегрив.", rewards = "Вы получите:\n\n"},
[136] = {title = "Спрятанное сокровище капитана Сандерса", objective = "Найдите сундучок капитана Сандерса и поищите в нем следующую подсказку.", description = "Если ты читаешь это – значится, старина капитан Сандерс уже покоится на дне. Так что мое сокровище теперь может стать твоим, главное – следуй подсказкам.\n\nСначала найди мой сундучок. Его, должно быть, уже наполовину песком занесло, а находится он на западном побережье Западного Края рядом с обломками корабля. Обломков-то там много, но ржавый якорь на берегу – только один. Найди этот якорь, и ты найдешь мой сундучок. Загляни внутрь за следующей подсказкой.", progress = nil, completion = "Сундучок медленно, со скрипом, открывается. Кажется, ничего в нем нет, кроме песка и воды. Постойте-ка! Проворно выползает маленький крабик, а в клешнях у него – следующая подсказка!", rewards = "Вы получите:\n\n"},
[138] = {title = "Спрятанное сокровище капитана Сандерса", objective = "Найдите старую бочку рядом с разрушенным очагом и поищите в ней следующий ключ.\n\nПрилагается предмет: \n", description = "Ключ к поиску сокровища таков: \"Отличная работа, приятель! Теперь тебе идти на восток. На восток в холмы, на восток к дороге. Ищи на обочине дороги развалины старого очага. Там найдешь старую бочку, в которой и будет следующий ключ\".", progress = nil, completion = "Отличная работа, охотник за сокровищами!", rewards = "Вы получите:\n\n"},
[139] = {title = "Спрятанное сокровище капитана Сандерса", objective = "Найдите следующую подсказку в пустом кувшине, найденном рядом с ветряной мельницей.\n\nПрилагается предмет: \n", description = "Обыскивая бочку, вы обнаруживаете еще один кусок пергамента. На нем написано: \"А теперь от этой бочки поверни к северу. Прямо, как ворон летит, иди, пока не наткнешься на пустой кувшин рядом с одинокой ветряной мельницей на прибрежных утесах. Осмотри кувшин внимательно – может, и найдешь то, что ищешь\".", progress = nil, completion = "Ты на пути к главному призу, искатель сокровищ!", rewards = "Вы получите:\n\n"},
[140] = {title = "Спрятанное сокровище капитана Сандерса", objective = "Установите местонахождение сундука капитана Сандерса и откройте его.\n\nПрилагается предмет: \n", description = "Конечно же, глубоко внутри старого кувшина лежит еще одна подсказка к поиску сокровища Сандерса. Чернила кое-где расплылись, а бумага отдает виски, но кое-что вам удалось разобрать: \"Раз уж ты <нашел/нашла> мой старый кувшин из-под виски, значит, ты близко <подобрался/подобралась> к сокровищу! Иди от бутылки на запад и спустись к берегу. Доберешься до воды – не останавливайся! Плыви, пока не найдешь остров, где и находится мой сундук с сокровищем!", progress = nil, completion = "Петли на крышке старого сундука заржавели, но поддаются. Вы с усилием открываете сундук и забираете сокровище.\n\nПоздравляем!", rewards = "Вы получите:\n\nСеребряный слитокРубашка капитана СандерсаКушак капитана СандерсаМешок для добычи капитана Сандерса"},
[141] = {title = "Братство Справедливости", objective = "Передайте документ, написанный Шоу, Гриану Камнегриву в Западный Край.", description = "Гильдию каменщиков возглавлял человек по имени Эдвин ван Клиф. Именно он занимался восстановлением Штормграда после разорения его орками во время Первой войны. Должно быть, ван Клиф и его люди остались недовольны тем, как с ними обошелся король, когда восстановление города было завершено. Это могло бы объяснить пару вещей.\n\nЯ тут расписал все более подробно для вашего начальства в Западном Крае. Сразу же отправляйтесь туда и передайте ему документ!", progress = "Пролил ли Мастер Шоу какой-то свет на происходящее?", completion = "Эдвин ван Клиф... Мне хорошо известно это имя. Обидно думать, что этот трудолюбивый и талантливый человек мог превратиться в такого мерзавца. Мне понадобятся дополнительные доказательства, чтобы я поверил в это.", rewards = "Вы получите:\n\n"},
[142] = {title = "Братство Справедливости", objective = "Выследите вестника из Братства Справедливости в Западном Крае и принесите отнятое у него сообщение Гриану Камнегриву.", description = "Нам нужно выяснить местонахождение Убежища Братства Справедливости. <имя>, мой разведчик сообщает, что на дороге между Луноречьем, Прииском на Золотом Берегу и Рудником Янго видели вестника из Братства Справедливости. Я хочу, чтобы вы его поймали. Если он окажет сопротивление, убейте его и принесите мне то, что будет у него найдено.", progress = "Мэйнард, удалось ли вам найти какую-то информацию? Вы определили местоположение посланника?", completion = "Вот явное доказательство того, что ими верховодит ван Клиф. Теперь все, что нам нужно узнать, – это где прячутся бандиты братства.\n\nНам тут немного повезло, пока вас не было. Мы поймали вора, пытавшегося украсть повозку Сальдена. Он пообещал навести нас на убежище бандитов в обмен на жизнь. Я прошу вас защитить его, чтобы предатель братства мог указать, где находится убежище. Возвращайтесь ко мне, когда выясните местонахождение убежища.", rewards = "Вы получите:\n\n"},
[143] = {title = "Гонец в Западный Край", objective = "Отнесите просьбу о помощи Гриану Камнегриву в Западный Край.", description = "Что-то странное происходит в армии Штормграда, подкрепления все нет и нет. К сожалению, мы не можем позволить себе ждать. Нельзя же сидеть сложа руки и не пытаться позвать соседей на помощь, пока доблестные воины Приозерья погибают один за другим. Говорят, в Западном Крае создано народное ополчение.\n\nОтнеси мою просьбу о помощи его предводителю, Гриану Камнегриву. Может быть, его люди помогут нам продержаться до подхода королевских отрядов.", progress = "Привет тебе, |3-6(Паладин). Какое дело привело тебя к народному ополчению?", completion = "Добрый вестник, ты хорошо послужил своему господину.", rewards = "Вы получите:\n\n"},
[144] = {title = "Гонец в Западный Край", objective = "Вернитесь к чиновнику Соломону с ответом Гриана Камнегрива.", description = "Меня очень огорчило письмо мирового судьи Соломона. К сожалению, он не ведает о войне, начавшейся в Западном Крае, иначе не ждал бы помощи от нас. Нам самим без ополчения не обойтись, потому что Штормград бросил нас на произвол судьбы.\n\nОтнеси мой ответ в Красногорье, <класс>, и передай своему хозяину, что я скорблю всем сердцем о гибели отважных бойцов.", progress = "Скоро ли ждать прибытия народного ополчения? Добрые ли вести ты несешь от лорда Камнегрива?", completion = "Что сказать, вести недобрые. Я и не подозревал, что у Камнегрива трудности, схожие с нашими. Что же отвлекает армию Штормграда от защиты ее собственных земель? Впрочем, зря я об этом говорю вслух.\n\nВот, вестник. Прими эти монеты в знак благодарности за верную службу городу. Быть может, скоро ты мне снова понадобишься.", rewards = "Вы получите:\n\n"},
[145] = {title = "Гонец в Темнолесье", objective = "Отнесите письмо лорду Чернодреву в Темнолесье.", description = "И снова мне нужна твоя помощь. Я написал письмо лорду Чернодреву, прося его прислать нам на помощь обученных бойцов Ночного дозора на защиту Озер. Надо как можно скорее доставить мое послание. Действуй осторожно. Лорд Чернодрев – мэр города Темнолесья, расположенного в сердце Сумеречного леса. Не сходи с дороги.", progress = "Похоже, ты прибыл издалека, |3-6(Паладин). Что привело тебя в Темнолесье?", completion = "Благодарю за проделанный путь. Вести и верно важные.", rewards = "Вы получите:\n\n"},
[146] = {title = "Гонец в Темнолесье", objective = "Вернитесь к мировому судье Соломону с ответом лорда Элло Чернодрева.", description = "Не знай я мирового судью Соломона лично, решил бы, что он сошел с ума. Послать в Приозерье Ночной дозор, потому что Штормград отказал в помощи? Мы и создали его, когда земли наводнила нечистая магия, а Штормград бросил нас на произвол судьбы. Если я пошлю в Приозерье Ночной дозор, то наш город падет, едва лишь Дозор доберется  до края леса.\n\nОтнеси мой ответ своему господину в Приозерье.", progress = "Рад снова видеть тебя, посланник. Могу ли я сообщить маршалу, что Ночная стража уже в пути?", completion = "Во имя Света! Армия Штормграда отступила из Западного Края. И Дозор не сможет защищать Темнолесье? Здесь таится предательство. Как же так?\n\nО, я забыл отблагодарить тебя за услуги, |3-6(Паладин). Прими вот эту плату. А теперь извини меня. Что-то творится в Штормграде, и я должен докопаться до сути.", rewards = "Вы получите:\n\n"},
[147] = {title = "Охота на человека", objective = "Найдите и убейте Вымогателя, а затем принесите его кольцо маршалу Дугхану.", description = "Если Вымогатель забирает золото с наших рудников, значит, он обворовывает королевство! Он должен предстать перед судом – а мне понадобится то кольцо, которое упоминалось в записке. Возможно, оно поможет нам узнать, на кого работает этот Вымогатель...\n\nЗдесь написано, что Вымогатель скрывается на тыквенном поле Бреквеллов. Попробуй поискать его там.", progress = "Тебе удалось разыскать Вымогателя? И на кого же он работает?", completion = "Так тебе удалось его найти? Отлично, Маркроу, просто прекрасно! Больше он ничего не будет \"вымогать\" на Элвиннских шахтах!\n\nА это кольцо... О, очень интересно! Это кольцо древнего братства Каменщиков Штормграда. С чего бы это мелкому воришке носить кольцо гильдии? И как вышло, что Братство Справедливости добывает золото на наших рудниках?\n\nНепростые вопросы, верно? Надеюсь, когда-нибудь мы узнаем ответ.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлетеные перчатки ШтормградаЭластичные накулачники\n\nВы также получите:\n\n"},
[148] = {title = "Припасы из Темнолесья", objective = "Поговорите с мадам Евой.", description = "Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... Мне не добраться до цели.\n\nНе <мог/могла> бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос? Ее можно приобрести у мадам Евы, которая живет на центральной площади города.", progress = nil, completion = "А, так тебе нужна нить из призрачных волос? Боюсь, мои запасы иссякли, но я могу сделать еще... Если ты принесешь мне призрачные волосы.", rewards = "Вы получите:\n\n"},
[149] = {title = "Прядь призрачных волос", objective = "Отнесите Слепой Мэри призрачный гребень.", description = "На старой ферме, в холмах к югу от Темнолесья, живет несчастное привидение по имени Слепая Мэри.\n\nВозьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы. Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити.\n\nБудь <осторожен/осторожна>, рядом с домом бродит множество темных тварей.", progress = "*Всхлипывает.* Пожалуйста, не смотри на меня! Я вырвала глаза собственными руками, но все равно чувствую твой взгляд!\n\nЯ уродина! Уродина! Прошу тебя, отвернись!", completion = "Что это? Гребень? Какая прелесть! И он спокойно скользит по моим волосам, хотя они давно сбились в ужасный слипшийся колтун.\n\nАх, мне бы в зеркало посмотреться...", rewards = "Вы получите:\n\n"},
[150] = {title = "Мурлоки-браконьеры", objective = "Принесите 8 плавников мурлоков портовому начальнику Барену в Приозерье.", description = "Мурлоки начинают нас беспокоить. Все больше мурлокских рыбаков селится вдоль побережья Озера Безмолвия и вовсю ловит рыбу! Надо изгнать их, пока они не опустошили все озеро!\n\nУбей побольше мурлоков! Принеси мне восемь их плавников, и я найду, чем тебе отплатить...", progress = "Принес плавники? Торопись, надо скорее изгнать мурлоков из нашего озера!", completion = "Молодец, Эфром. Надеюсь, тебе не слишком солоно пришлось.\n\nСтранно, что они ушли так далеко от моря. Хотелось бы знать, отчего они сбежали...", rewards = "Вы получите:\n\nДворфийская удочка"},
[151] = {title = "Бедная старая Савраска", objective = "Принесите 8 горстей овса Верне Хмуробров.", description = "Бедная старая Савраска! Несчастная лошадка так устала от непосильного труда и бесчисленных лишений... Я ее покормила перед тем, как уехать с фермы, но мы не ожидали, что повозка сломается по дороге. Я была бы вам очень благодарна, <сэр/леди>, если бы вы могли принести ей несколько горстей овса с окрестных полей.\n\nУверена, что вы найдете овес на любой ферме в Западном Крае, если только сумеете увернуться от этих ужасных машин, которые буйствуют на полях. К юго-западу отсюда расположено несколько фермерских хозяйств.", progress = "Старая Савраска уже валится с ног. Не добыл ли ты овса для нее?", completion = "Огромное тебе спасибо, Бронгард! Бедная старая Савраска будет просто счастлива!", rewards = "Вы получите:\n\nПопона старой СавраскиМешок с едой старой Савраски"},
[152] = {title = "Зачистка побережья", objective = "Убейте 7 волноловов, 7 воинов, 7 оракулов и 7 береговиков-мурлоков и вернитесь к капитану Грейсону на Маяк в Западном Крае.", description = "Ты, должно быть, <видел/видела> все эти обломки кораблей вдоль побережья. Великое море и в самом деле очень сурово. Береговую линию Западного Края нужно держать чистой, чтобы моряки, если приплывут к нашим берегам, были в безопасности. На сегодняшний день мурлоки являются большой проблемой...\n\nРазберись с ними – убей 7 волноловов, 7 воинов, 7 оракулов и 7 береговиков, – и награда будет ждать тебя.", progress = "Убей 7 волноловов, 7 воинов, 7 оракулов и 7 береговиков-мурлоков, – и награда будет ждать тебя.", completion = "Хорошая работа, Эфром. У тебя отличные боевые навыки! Благодаря тебе побережье Западного Края стало более безопасным местом.", rewards = "Вы получите:\n\n"},
[153] = {title = "Красные кожаные банданы", objective = "Принесите разведчику Галиану на Сторожевой холм 15 красных кожаных бандан.", description = "В Братстве Справедливости идет постоянная кипучая деятельность. Я уже долго слежу за их передвижениями. Между прочим, я заметил, что многих бандитов можно опознать по красным кожаным банданам.\n\nПринесите мне 15 таких бандан, и я позабочусь о том, чтобы вы получили вознаграждение.", progress = "Принесите мне 15 красных кожаных бандан, и я вам хорошо заплачу.", completion = "Хорошая работа, Хрофтгор. Пожалуйста, примите один из этих предметов в качестве оплаты за ваши труды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлащ народного ополченияНаголенники народного ополченияПоножи народного ополчения\n\nВы также получите:\n\n"},
[154] = {title = "Гребень для Эвы", objective = "Верните гребень для призрачных волос мадам Еве в Темнолесье.", description = "НЕТ!!!\n\nУбери его, убери от меня этот гребень!\n\nЯ чудовище, меня больше никто не назовет прекрасной!", progress = "Чувствую, ты уже видел Слепую Мэри. Гребень все еще у тебя?..", completion = "Ну, из этого выйдет целая катушка нити из призрачных волос, да еще и останется несколько прядей. Прими эти монеты в уплату за лишние пряди.", rewards = "Вы получите:\n\n"},
[155] = {title = "Братство Справедливости", objective = "Сопроводите предателя к тайному убежищу Братства Справедливости. Когда он покажет, где прячутся ван Клиф и его люди, вернитесь к Гриану Камнегриву.", description = "Так Камнегрив считает, что <такой слабый/такая слабая:r> <раса> сможет меня защитить? А ведь придется. Возьми-ка с собой пару-тройку друзей.\n\nТы же знаешь, что делать, да? Ты прикрываешь мою спину, а я веду тебя к убежищу Братства Справедливости. Держись ко мне поближе. Бандиты братства охотятся за моей головой. Если нас увидят вместе, они попытаются меня убить.\n\nДай мне знать, когда ты и друзья, которых ты соберешь, будут готовы идти.", progress = nil, completion = "Великолепно, сэр Бронгард! Теперь, когда мы знаем, где прячется ван Клиф, – он наш!", rewards = "Вы получите:\n\n"},
[156] = {title = "Сбор цветков гнили", objective = "Соберите 8 цветков гнили и отнесите их хозяину таверны Смиттсу.", description = "Если ты принесешь мне несколько цветков гнили, я сделаю для тебя сок зомби.\n\nЦветки гнили растут в самых странных местах. Например, в черепах ужасных скелетов и скелетов-губителей... хотя я лично туда не заглядывал!\n\nКладбище Вороньего холма и Безмятежное кладбище кишмя кишат этими скелетами. Заодно ты и нас от них избавишь. Темнолесье будет тебе весьма признательно.", progress = "Привет. Ну как, принес цветки гнили?", completion = "Отлично, ты сумел добыть цветки гнили. А я расскажу Альтее Чернодрев из Ночного дозора, что тебе удалось уничтожить несколько скелетов.\n\nНочной дозор охраняет покой Темнолесья, и им нелегко приходится. Разумеется, вести о добровольцах, помогающих остановить нашествие нечисти, будут отрадой для всех.", rewards = "Вы получите:\n\n"},
[157] = {title = "Доставка ниток", objective = "Принесите нить из призрачных волос в хижину на севере от кладбища Вороньего холма и отдайте ее Аберкромби.", description = "Вот тебе нитки, <имя>. Им можно найти тысячи способов применения – от связывания злых духов до зашивания жизни в бездушные предметы.", progress = "Я должен обвязать нитью из призрачных волос двери и окна, чтобы не пускать в дом чуждых призраков. Ты принес ее?", completion = "Великолепно! Она прекрасно подойдет…\n\nВот, дражайший Эфром, прими это в уплату за благороднейший поступок.", rewards = "Вы получите:\n\n"},
[158] = {title = "Сок зомби", objective = "Поговорите с хозяином таверны Смиттсом.", description = "Мне нужна бутылка особого напитка – сока зомби. У хозяина темнолесской таверны \"Алый ворон\" Смиттса наверняка найдется лишняя бутылочка.\n\nТоропись, <имя>. Ночи стоят холодные, и мне не терпится снова наполнить жилы огнем.", progress = nil, completion = "Значит, тебе нужен сок зомби? Хм... это довольно крепкий напиток, обычно его у меня не заказывают.", rewards = "Вы получите:\n\n"},
[159] = {title = "Доставка сока", objective = "Отнесите сок зомби в хижину Аберкромби.", description = "А вот и сок зомби…\n\nБудь с ним <осторожен/осторожна>. Он такой крепкий, что мертвого поднимет!", progress = "Сок зомби согреет меня долгими холодными ночами. Ты принес его?", completion = "Тысяча благодарностей, Эфром. Твоя глу... то есть твоя доброта согрела сердце старика!\n\nВот, друг, прими это в знак моей благодарности.", rewards = "Вы получите:\n\n"},
[160] = {title = "Записка для мэра", objective = "Отнесите письмо Аберкромби Элло Чернодреву, мэру Темнолесья.", description = "Отнеси эту записку Элло Чернодреву, мэру Темнолесья.\n\nМы с ним старые друзья... И когда он прочитает это и узнает, что ты для меня <сделал/сделала>... не сомневаюсь, он будет счастлив не меньше меня! Ха-ха-ха!!!", progress = "Аберкромби?.. Я не знаю такого человека. Так говоришь, этот Аберкромби написал мне письмо?\n\nЧто ж, давай его сюда...", completion = "*Элло рассматривает письмо...*\n\nЧто это за язык? Похоже, какой-то древний... Не могу его прочитать.", rewards = "Вы получите:\n\n"},
[161] = {title = "Прямая и черная угроза", objective = "Отнесите странно пахнущий порошок в Дун Модр Ашлану Камнехмылу, специалисту по взрывчатым веществам.", description = "Если мои подозрения верны, то это взрывчатый порошок. Его следует показать специалистам, чтобы выяснить, с чем именно мы имеем дело. Ашлана Камнехмыла направили в полк, охраняющий Дун Модр и мост Тандола. Путь предстоит нелегкий и опасный, <имя>.\n\nПройди через врата Альгаза, по дороге, ведущей через Болотину, и отыщи Камнехмыла в Дун Модре. Советую не сходить с дороги и не задерживаться.", progress = "Что ты там бубнишь, сынок? В ушах звенит, аж жуть. Ух ты, что это ты мне принес?", completion = "Да, старина Плотина не зря беспокоится.", rewards = "Вы получите:\n\n"},
[162] = {title = "Возвышение силитидов", objective = "Отнесите отчет о наблюдении за насекомыми Грацине Силе Духа в Дарнасс.", description = "Прошу тебя, отнеси этот отчет кому-нибудь, сведущему в такого рода вопросах.\n\nЯ слышал про одну ночную эльфийку по имени Грацина Сила Духа. Она посвятила много времени изучению форм жизни, встречающихся лишь в Азероте; она и историк заодно! Если ты хочешь, чтобы кто-то объяснил, что именно происходит и как это прекратить, обратись к ней. Нам любая помощь не помешает.\n\nГоворят, она сейчас в храме Луны в Дарнассе.", progress = "Да пребудут с тобой мир и покой, незнакомец. Зачем ты искал меня?", completion = "Что до твоего отчета... мы, ночные эльфы, знаем, о каком ужасе идет речь. Рудознатец правильно поступил, отправив свой отчет и тебя ко мне.\n\nЭти существа мигом пожрут всю пустыню Танарис; они представляют собой одну из величайших опасностей, с которой только можно столкнуться. Знакомься, Ишт – это силитиды. Так зовутся странные насекомые, которые служат величайшему злу, грозящему и Орде, и Альянсу.\n\nЖаль, что нам не хватило ума понять это раньше.", rewards = "Вы получите:\n\n"},
[163] = {title = "Вороний холм", objective = "Выясните, кто поселился на Вороньем холме.", description = "Что-то неладно на Вороньем холме, <имя>. Калор клянется, что он заметил кого-то – или что-то – в одном из домов. Две ночи подряд он видел крадущиеся тени, а на третью – свет в одном из окон.\n\nЕсли тебя и в самом деле беспокоит безопасность Темнолесья, выясни, что за чудовище скрывается на Вороньем холме.", progress = nil, completion = "Нет! Прошу, не убивай меня! Это всего лишь я... Трясунчик! Они повсюду... Мне не скрыться! Чудовища на Вороньем холме? Н-н-нет... не может быть. Всего лишь безвредный Трясунчик.", rewards = "Вы получите:\n\n"},
[164] = {title = "Припасы для Свена", objective = "Отнесите Свену припасы.", description = "Ты знаешь Свена? Вот кто настоящий служитель Света! Он и его последователи стоят лагерем в северо-западной части Сумеречного леса.\n\nУвы, их так мало, что некого отправить за припасами в город. Не поможешь ли ты ему?", progress = "С первого взгляда ты кажешься опытным бойцом, |3-6(Паладин). Хочешь пополнить наши ряды?", completion = "Припасы нам очень пригодятся. Семья Кэрвинов не оставляет нас без помощи. Вот, прими награду за труды.", rewards = "Вы получите:\n\n"},
[165] = {title = "Отшельник", objective = "Навестите старика в хижине рядом с кладбищем Вороньего холма.", description = "Одно время в город частенько приходил старик и покупал припасы, но в последнее время я его не видела. Он живет в хижине рядом с кладбищем Вороньего холма, если я верно запомнила. Не навестишь ли ты его? Вдруг с ним что-то случилось?", progress = nil, completion = "Илана Карвин? Хе-хе, да, разумеется, Карвин. \n\nНет, со мной все в порядке, но мне трудновато ходить в город. Дороги нынче опасные, а я не молодею. Может, ты окажешь старику пару услуг?", rewards = "Вы получите:\n\n"},
[166] = {title = "Братство Справедливости", objective = "Убейте Эдвина ван Клифа и принесите его голову Гриану Камнегриву.", description = "Осталось одно, последнее задание. Эдвин ван Клиф должен умереть. Хотя меня печалит сам факт вынесения человеку смертного приговора, для всего народа Западного Края будет гораздо лучше, если ван Клиф упокоится навечно. Принесите мне голову этого негодяя, когда с ним будет покончено.", progress = "Как продвигается ваша охота на Эдвина ван Клифа?", completion = "Бронгард, вы проявили удивительную храбрость. Народное ополчение благодарит вас за службу народу Западного Края. Смерть ван Клифа станет началом конца для Братства Справедливости. Надеюсь, недалек тот прекрасный день, когда мир вновь снизойдет на эту честную землю.\n\nЧесть имею, сэр!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШоссы Западного КраяМундир Западного КраяПосох Западного Края\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[167] = {title = "О, брат мой...", objective = "Принесите значок Лиги Исследователей, принадлежавший штейгеру Чертополоху в Штормград.", description = "Мы находились в обширных шахтах Западного Края, скрытых глубоко под землями Луноречья. Понятия не имею, откуда явились эти мерзкие вороватые вонючки. Так или иначе – туннель обрушился на нас. Мне удалось выбраться, но остальные... о них я ничего не знаю.\n\nВдруг тебе повезет больше, чем мне? Я ищу своего брата. Он всегда носил значок Лиги Исследователей. Если ты не найдешь брата, постарайся найти хотя бы его значок.", progress = "Нет ли у тебя каких-либо известий о моем брате? Можно ли еще надеяться, ведь столько времени прошло?", completion = "Мои подозрения оправдались. Бедный мой брат... Что ж, благодарю. Определенность лучше загадок, даже если она лишает надежды.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nМесть горняка"},
[168] = {title = "Сбор воспоминаний", objective = "Добудьте 4 карточки Союза шахтеров и верните их Дикому Чертополохху в Штормград.", description = "Многие из моих друзей погибли в тот роковой день, когда обрушился штрек. Если тебя как-нибудь занесет в ту шахту в Луноречье, пожалуйста, постарайся добыть что-то, что поможет их опознать. А если найдешь их карточки Союза шахтеров, принеси их мне, я отправлю их семьям погибших.", progress = "Принеси мне карточки Союза шахтеров, которые принадлежали моим друзьям...", completion = "Спасибо тебе, Rainon. Твоя помощь в посмертном успокоении жертв этой чудовищной трагедии была неоценимой. Их семьи будут тебе признательны.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги проходчикаПыльные шахтерские перчатки\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[169] = {title = "Розыск: Гат'Илзогг", objective = "Убейте Гат'Илзогга и принесите его голову мировому судье Соломону в Приозерье.", description = "Розыск! Гат'Илзогг, вождь клана Черной Горы, разыскивается за нападение на крепость Каменной Стражи и набеги на окрестности Приозерья. \n\nГат'Илзогг крайне опасен. По последним сведениям, он находится в недавно захваченной крепости и замышляет новые преступления против Королевства. Нашествие орков должно быть остановлено любой ценой. Храбрец, доставивший голову Гат'Илзогга мировому судье  Соломону, будет щедро вознагражден.", progress = "Что это, |3-6(дворф)?", completion = "Великолепная работа, Бронгард! Гат'Илзогг вел своих громил в бой, и они убивали ни в чем не повинных людей. Мы отомстили ему. Это первый шаг на пути возвращения крепости королевству Штормграда!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[170] = {title = "Новая угроза", objective = "Убейте 6 троггов из племени Каменной Челюсти и 6 сильных троггов из племени Каменной Челюсти.", description = "Надеюсь, ты <оказался/оказалась> здесь не случайно, <класс>. Не буду лукавить: после недавнего нападения троггов для нас любая помощь – дар небес.\n\nЯ слышал, что эти мерзавцы теперь повсюду лезут – ну и до Холодной долины тоже добрались. Говорят, их полно в горах на юго-востоке и возле замерзшего озера.\n\nТак ведь и это еще не все! Недавно они напали на наш лагерь на западе и разгромили его!\n\nНам и так воинов не хватает, а тут еще эти гады... Послушай, <приятель/подруга>, может, ты нам поможешь? Боюсь, иначе нам троггов не одолеть...", progress = "Упорные твари эти трогги, правда ведь?", completion = "Если повсюду происходит то же, что и здесь, у нас, то, клянусь бородой Магни, нас ждет большая беда! Остается надеяться, что король и Совет придумают, что делать с этими проклятыми троггами, иначе нам конец.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМедвежья шальКрестьянский поясСнеговые сапоги\n\nВы также получите:\n\n"},
[171] = {title = "Опекун Альянса", objective = "Проводите своего подопечного в приют Штормграда, вернув свисток ребенка-сироты попечительнице сирот Найтингейл в Храмовый квартал.", description = "Ты <был/была> очень <добр/добра> ко мне, <имя>. Я и представить не мог, что Детская неделя пройдет так весело. Спасибо. Я не хочу печалится из-за собственной судьбы – предки всегда говорили мне, что я должен быть выше всех несчастий. Знаешь, когда я вырасту, я хочу стать героем... как ты.\n\nКак ни жаль, мне пора домой. Давай вернемся, и я расскажу нашей попечительнице, что ты лучше всех!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОшейник поросенкаКрысиная клеткаЧерепаха в коробочкеРасплата скупца\n\nВы также получите:\n\n"},
[172] = {title = "Детская неделя", objective = "Используйте свисток орка-сироты. Присматривайте за сиротой в течение всей Детской недели.\n\nПрилагается предмет: \n", description = "Ты хочешь помочь сиротам? Да благословят тебя боги! Что бы мы без тебя делали!\n\nВот, возьми этот свисток. Действовать он будет недолго – до конца Детской недели. Свистнув в него, ты сможешь поговорить с сиротой, за которым ты обещаешь присматривать. Свистни еще раз, и ты отпустишь ребенка восвояси.\n\nПрошу тебя, <имя>, пользуйся свистком почаще, не забывай своего подопечного! Для детей это так важно...", progress = nil, completion = "Заг-заг! Меня зовут Грент. Ты теперь мой опекун, да? Ты ищешь приключений, совсем как мои мама с папой! Наша попечительница говорит, что они с честью погибли в бою! Я так рад с тобой познакомиться!\n\nА мы теперь будем все делать вместе? Мне столько всего хочется сделать, а попечительница говорила, ты мне в эту неделю будешь все равно как старший брат. Вот здорово!", rewards = nil},
[173] = {title = "Воргены в лесу", objective = "Калор из Темнолесья просит вас убить 6 тенеткачей Ночной Погибели.", description = "На Сумеречный лес наступают силы тьмы, и цель мастера Кэрвина – борьба с этим злом. Благодаря нашим усилиям народ Темнолесья живет в безопасности.\n\nТы считаешь, что <достоин/достойна> вступить в наши ряды?\n\nКогда-то я был таким же, как ты. Меня раздражало самодовольство Дозора, и я стал соратником мастера Кэрвина. Если ты хочешь показать, на что <способен/способна>, то слова тебе не помощники.\n\nВыступи против воргенов-тенеткачей Ночной Погибели в Светлой роще – светлой, ха! – и Гниющем саду.", progress = nil, completion = "Твои успехи впечатляют, Бронгард. Похоже, ты на многое способен. Пожалуй, твоим талантам следует найти более достойное применение.\n\nВпрочем, вот что интересно... Воргены появились словно из ниоткуда. Но, с другой стороны, в наши границы вторглось такое количество странных существ, что это не самая большая проблема.", rewards = "Вы получите:\n\n"},
[174] = {title = "Взгляни на звезды", objective = "Принесите Виктору Призм'Антрасу бронзовую трубку.", description = "Один мой друг, гном по имени Ког, обещал мне помочь создать устройство, которое позволит изучать звезды. Уверен, что есть и иные объяснения творящемуся в лесу, чем магическое вмешательство.\n\nПринеси мне бронзовую трубку, изготовленную искусным инженером. Согласно чертежам Кога, это шаг номер один.", progress = "Тебе удалось отыскать искусного инженера и сделать бронзовую трубку?", completion = "Великолепно, Эфром! Первый шаг мы сделали успешно!", rewards = "Вы получите:\n\n"},
[175] = {title = "Взгляни на звезды", objective = "Найдите Мэри и уговорите ее пожертвовать зеркало для проекта Виктора.", description = "Согласно чертежам Кога, мне нужно отыскать способ отражать свет. Помнится, есть у нас одна особа по имени Мэри, которая вечно таскает с собой зеркальце. Может быть, ты отыщешь ее и она одолжит нам свою отражающую поверхность? Кажется, она когда-то жила в южной части Сумеречного леса.", progress = nil, completion = "Все верно, у меня некогда было зеркальце.", rewards = "Вы получите:\n\n"},
[176] = {title = "Разыскивается:  \"Дробитель\"", objective = "Убейте Дробителя и принесите маршалу Дугхану большой коготь гнолла.", description = "Разыскивается: Дробитель\n\nВ юго-западной части Элвиннского леса поселился могучий гнолл по прозванию Дробитель. Несмотря на все усилия, поймать его так и не удалось.\n\nАрмия Штормграда назначила за этого гнолла щедрую награду. Чтобы получить ее, необходимо представить маршалу Дугхану доказательства смерти Дробителя.", progress = "О да, этот Дробитель мне и моим людям немало крови попортил... Ты можешь о нем что-нибудь сообщить?", completion = "Ха! Отличная работа! А я уже было думал, что никому не под силу совладать с этим чудовищем!\n\nВот твоя награда, Wrestlecake, а с ней прими и мою благодарность: этот гнолл у нас уже вот где сидел!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМундир пехотинцаПоножи штормградского стражникаСбалансированный боевой посох\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[177] = {title = "Взгляни на звезды", objective = "Заберите зеркало Слепой Мэри у Невменяемого Вурдалака и отдайте его Виктору в Темнолесье.", description = "Зеркальце было одним из моих главных сокровищ... но потом со мной случилось несчастье. После этого я зашвырнула стекляшку за амбар. Одно время там бродил Невменяемый Вурдалак. Может быть, он утащил мое зеркальце. Говорят, что теперь эта тварь живет на Безмятежном кладбище.", progress = "Я показал Когу наш прибор для изучения звезд, и он его одобрил. Ты не добыл отражающее устройство?", completion = "Шедеврально! Это непременно сработает. Я глубоко признателен!", rewards = "Вы получите:\n\n"},
[178] = {title = "Поручение Теокрита", objective = "Принесите выцветшую подвеску Темношкуров верховному магу Теокриту.", description = "*До вас доносится бесплотный голос...*\n\nНе пугайся. Я Теокрит, верховный маг башни Азоры в Элвиннском лесу. При помощи этой подвески гноллы из стаи Темношкуров общаются со своим повелителем Моргантом.\n\nЯ потратил много времени на то, чтобы тоже научиться вещать через эти подвески. Если ты слышишь мое сообщение, значит заклинание сработало.\n\nПринеси мне эту подвеску, и я щедро вознагражу тебя.", progress = "Говоришь, ты слышал мой голос из подвески? Хм-м-м... Дай-ка ее мне, надо ее как следует изучить.", completion = "Благодарю тебя, Бронгард. Я передал это сообщение через подвески Темношкуров несколько недель назад и полагал, что заклинание не сработало. Оказывается, в конечном итоге оно достигло по меньшей мере некоторых из них.\n\nХочется верить, что рано или поздно я научусь посылать таким образом боевые заклинания и обездвиживать тех гноллов, которые носят эти подвески.\n\nК сожалению, до этого еще очень далеко.", rewards = "Вы получите:\n\nВосстанавливающий бальзам"},
[179] = {title = "Дворфские экипировщики", objective = "Принесите Стену Крепкоруку 8 кусков жесткого волчьего мяса.", description = "Ну-ка, ну-ка, что тут у нас?.. Холодновато в наших краях, верно? Готов спорить, у тебя все время мерзнут руки. Ну, угадал?\n\nЯ скажу, что тебе нужно: пара хороших теплых перчаток. Ну да, душа у меня добрая, так что замерзнуть я тебе не дам. Только вот есть одно условие.\n\nПринеси мне волчьего мяса – и мы, считай, в расчете. Справедливо, как думаешь? Мне – мясо, а уж я-то позабочусь о том, чтобы у тебя пальцы больше не мерзли. Ну, что скажешь?", progress = "Что, потрепали тебя волки? Да уж, когти и клыки – это тебе не шуточки!", completion = "О! Прекрасно! Волчье мясо – это то, что надо!.. Не беспокойся, Эфром, свою часть сделки я выполню честно. Вот, посмотри, что из этого тебе подойдет.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки охотника на кроликовПерчатки охотника на волковПерчатки охотника на вепрей\n\nВы также получите:\n\n"},
[180] = {title = "Разыскивается: лейтенант Фангор", objective = "Убейте лейтенанта Фангора и принесите его лапу мировому судье Соломону в Приозерье.", description = "Разыскивается: лейтенант Фангор\n\nГлава гнолльской стаи Темношкуров, соратник Морганта, врага Города и Королевства. По приказу чиновника Соломона подлый предатель Штормграда приговаривается к смерти. Тот, кто приведет приговор в исполнение, должен в доказательство принести лапу Фангора мировому судье Соломону.", progress = "Какие новости ты несешь Суду?", completion = "Значит, злобный лейтенант Фангор мертв? Прекрасно. Ты удивительно храбрый |3-6(Паладин). Городской совет Приозерья благодарит тебя за помощь.", rewards = "Вы получите:\n\n"},
[181] = {title = "Взгляни на звезды", objective = "Отыщите Ззарк'Вула в кургане на юге Сумеречного леса и принесите его монокль Виктору в Темнолесье.", description = "Для завершения работы не хватает только одного предмета. Согласно чертежам Кога, нам нужна линза. Единственную подходящую линзу в наших краях будет нелегко достать.\n\nВ кургане на юге Сумеречного леса живет огр по имени Ззарк'Вул. Если сможешь, принеси мне его монокль, и я использую его вместо линзы!", progress = "Тебе удалось уговорить Ззарк'Вула одолжить нам свой монокль для эксперимента?", completion = "Наконец-то! Устройство для изучения звезд готово! Спасибо тебе, Эфром. Я могу продолжить исследования...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗодиакальные ПерчаткиПояс Звезд\n\nВы также получите:\n\n"},
[182] = {title = "Пещера троллей", objective = "Убейте 14 троллей-подростков из племени Мерзлогривов.", description = "Нас с моим братом Сениром отправили в Дун Морог, чтобы разведать, действительно ли там объявились тролли, и насколько серьезна эта угроза. Совету хватает хлопот с троггами, лишние проблемы им ни к чему.\n\nНасколько я видел, тролли здесь не слишком хорошо закрепились; в основном они живут в южной пещере. Как по мне, тут и армия не нужна: несколько крепких бойцов вполне управятся.\n\nМожет, и ты решишь поучаствовать в этом деле? Не за так, конечно: у меня есть что тебе предложить.", progress = "Насколько я знаю, эти тролли происходят из клана Снежной Гривы. Боюсь, о них я не знаю больше ничего, что могло бы тебе пригодиться, Элрибар.", completion = "Проклятые тролли! Да не озарит их Извечный Свет!\n\n*Шумно дышит; немного успокаивается.*\n\nЭти негодяи ввалились ко мне ночью и украли мои записи! У меня хватило ума не доверять этому негодному подмастерь...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСекач Старой НаковальниМолот Старой НаковальниНож Старой НаковальниДеревянный молот Старой Наковальни\n\nВы также получите:\n\nЦелебная трава"},
[183] = {title = "Охотник на вепрей", objective = "Убейте 12 малых скальных вепрей по просьбе Талина Остроглаза.", description = "Нет ничего лучше охоты на диких вепрей, верно?\n\nПравда, здесь, в Холодной долине, их расплодилось столько, что весь интерес пропадает. Их и загонять не надо – они злые, как демоны, и сами бросаются прямо на охотника. Я бы даже сказал, что этих злобных свиней так много, что и охотиться-то стало опасно...\n\nКороче говоря, я буду благодарен, если ты поможешь мне прикончить хотя бы нескольких кабанов.", progress = "Как идет охота?", completion = "Отлично, просто отлично! Теперь я могу спокойно отдох... М-м... Заняться охотой. Благодарю за помощь, Эфром.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДворфийские матерчатые брюкиДворфийские кожаные штаны\n\nВы также получите:\n\n"},
[184] = {title = "Документ Хмуроброва", objective = "Доставьте фермеру Хмуроброву документ на ферму.", description = "Вот бумага, дающая право на расширение фермерских владений в Западном Крае. Она подписана Теодором Хмуробровом и его женой, Верной Хмуробров. На обороте документа торопливо нацарапаны слова:\n\n\"Мы нажали на Хмуроброва и получили от него нужную бумагу. Если тебе захочется заполучить один из участков, она тебе пригодится.\n\nС Хмуробровами проблем не предвидится: я видел, как они покидают Западный Край, у них как раз телега сломалась.\"\n\nНаверное, Хмуробровы были бы рады получить этот документ назад...", progress = "У тебя бумага на мою ферму? Вот это да! Вот это здорово! Несколько дней назад ее украли какие-то мерзавцы... Я думал, назад мне ее уже не получить.\n\nПожалуйста, отдай мне эту бумагу. Конечно, мы сейчас уезжаем из Западного Края и вернемся не скоро, но наступят времена, когда она нам очень пригодится...", completion = "Ты представить не можешь, Wrestlecake, как мы тебе благодарны! Конечно, сейчас в этих краях приличным людям не место, но, может, времена переменятся, и тогда нам нужно будет предъявить эту бумагу на право владения землей.\n\nКонечно, многого я предложить не могу, но возьми хотя бы вот это...", rewards = "Вы получите:\n\nСпелый арбузМаленькая тыква"},
[185] = {title = "Схватка с тигром", objective = "Ажек Руак из экспедиции Эрнестуэя попросила вас убить 10 молодых тигров Тернистой долины.", description = "Когда я была маленькой девочкой, отец научил меня искусству охоты на тигров.\n\nМолодых зверей гораздо проще выслеживать и убивать. Поэтому начнем с простого. Молодые тигры часто забредают к лагерю экспедиции.\n\nПостарайся выследить и убить несколько зверей.", progress = "Пока ты не научишься справляться с молодыми тиграми, о дальнейших уроках и речи быть не может.", completion = "Неплохо, Эфром. Пора тебе двигаться дальше.", rewards = "Вы получите:\n\n"},
[186] = {title = "Схватка с тигром", objective = "Ажек Руак из экспедиции Эрнестуэя попросила вас убить 10 тигров Тернистой долины.", description = "А ты учишься, <класс>. Посмотрим, как ты справишься со взрослыми кошками. На сей раз тебе предстоит убить 10 тигров Тернистой долины.", progress = "Если ты жаждешь великих свершений, докажи сначала, что способен на малые. Убей 10 тигров Тернистой долины и возвращайся.", completion = "Впечатляюще, |3-6(Охотник). Ты делаешь успехи.", rewards = "Вы получите:\n\n"},
[187] = {title = "Схватка с тигром", objective = "Ажек Руак из экспедиции Эрнестуэя попросила вас убить 10 старых тигров Тернистой долины.", description = "Поднимем ставки. Докажи, что сможешь убить 10 старых тигров Тернистой долины. Справишься – и я признаю, что ты <готов/готова> к последнему испытанию, после которого я объявлю тебя великим охотником на тигров в присутствии мастера Эрнестуэя.\n\nСтарые тигры Тернистой долины неуловимы для врага и безжалостны в схватке.", progress = "Прежде чем перейти к последнему заданию и претендовать на звание великого охотника, убей 10 старых тигров Тернистой долины.", completion = "Очень, очень неплохо. Думаю, ты почти готов.", rewards = "Вы получите:\n\n"},
[188] = {title = "Схватка с тигром", objective = "Ажек Руак из экспедиции Эрнестуэя просит вас убить Син'Далл и принеси ее лапу.", description = "Вот твое последнее испытание. Мы уже много недель выслеживаем эту хитрую тигрицу, прозванную Син'Далл. Интересно, сможешь ли ты сделать то, что не удавалось ни одному |3-2(<раса>) – выследить и убить Син'Далл. Принеси мне ее лапу в доказательство своего подвига.\n\nДаже выследить ее – непростая задача.", progress = "Как идет охота на Син'Далл?", completion = "Впечатляюще, должна сказать! Ты великий Охотник на тигров, Томпсон!", rewards = "Вы получите:\n\nПерчатки охотника на тигров"},
[189] = {title = "Уши троллей Кровавого Скальпа", objective = "Добудьте 15 ушей троллей из племени Кровавого Скальпа и принесите их Кебоку в Пиратскую бухту.", description = "Проклятые тролли! Они постоянно убивают наших агентов! Я потерял в стычках с ними лучших своих бойцов. Цена операции все растет и растет! Как я объясню это барону Ревилгазу?\n\nРешительные действия нас спасут... Думай, Кебок... Тебя назначили на эту должность не за безделье... Придумал! Тебя...<имя> зовут, да? Ты ведь мне поможешь? А уж я заплачу!\n\nПредлагаю сделку... ты принесешь мне уши пятнадцати троллей из племени Кровавого Скальпа, а я дам тебе денег.", progress = "Ну как, надеюсь, успешно? Проклятые тролли кишмя кишат! Грязные твари.\n\nКстати, мое предложение и на твоих друзей распространяется! Тебе не помешает помощь!", completion = "Отлично, отлично. Это временно решит проблему…\n\n*Он принимается бормотать себе что-то под нос насчет огромных издержек…*\n\nЧто? Ты все еще здесь? Награда? А, да... Разумеется, бери... этого должно с лихвой хватить.", rewards = "Вы получите:\n\nГоблинская удочка"},
[190] = {title = "Схватка с пантерой", objective = "Сэр С. Дж. Эрлгедин из экспедиции Эрнестуэя попросил вас убить 10 молодых пантер.", description = "Если ты хочешь отправиться на охоту вместе с нами под предводительством Хеминга, докажи, что умеешь выслеживать пантер. Не бойся, начнем с простого. Для примера убей 10 молодых пантер.\n\nВыследить их – только полдела...", progress = nil, completion = "Доброе начало, Эфром!", rewards = "Вы получите:\n\n"},
[191] = {title = "Схватка с пантерой", objective = "Сэр С. Дж. Эрлгедин из экспедиции Эрнестуэя попросил вас убить 10 пантер.", description = "А теперь задача потруднее. Если ты хочешь доказать, что <достоин/достойна> общаться с настоящими охотниками, убей 10 пантер.\n\nС этими ребятами не так легко справиться, они посильнее молодых зверей, с которыми тебе приходилось сталкиваться прежде.", progress = "Иди, убей 10 пантер! Покажи, на что способен.", completion = "Великолепно, Эфром!", rewards = "Вы получите:\n\n"},
[192] = {title = "Схватка с пантерой", objective = "Сэр С. Дж. Эрлгедин из экспедиции Эрнестуэя попросил вас убить 10 тенебрюхих пантер.", description = "Усложняем задание. Настоящий охотник сможет одолеть даже тенебрюхих пантер, самых опасных в Тернистой долине. Докажи, что сможешь прикончить 10 таких тварей.\n\nЕсли тебе покажется, что их трудно выслеживать, попробуй для начала убить одну...", progress = nil, completion = "Молодец, Эфром!", rewards = "Вы получите:\n\n"},
[193] = {title = "Схватка с пантерой", objective = "Сэр С. Дж. Эрлгедин из экспедиции Эрнестуэя попросил принести ему клык Баг'тиры.", description = "Тебе почти удалось доказать, что ты <великий охотник/великая охотница> на пантер. И все же остается одна пантера по имени Баг'тира.\n\nДобудь ее клык, и мое уважение тебе обеспечено!", progress = "Баг'тира – хитрый зверь. Как идет охота?", completion = "Итак, великая Баг'тира мертва! Браво, Эфром. Ты и правда могучий |3-6(Маг)!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nПоножи охотника на пантер"},
[194] = {title = "Схватка с ящером", objective = "Хеминг Эрнестуэй просит вас убить 10 ящеров Тернистой долины.", description = "Значит, ты считаешь себя <превосходным охотником/превосходной охотницей>? Проверим. Ступай в джунгли и подстрели 10 ящеров Тернистой долины. Посмотрим, как ты справишься с крупной дичью.\n\nИ нет, я не скажу, где их искать! Первая половина испытания – поиски зверя.", progress = "Мне не доводилось встречать охотников, которые добывали дичь, попусту ошиваясь у костра – конечно, не считая моего отца. Ты собираешься подстрелить этих ящеров или будешь ждать, когда они умрут от старости?", completion = "Неплохо, старина!", rewards = "Вы получите:\n\n"},
[195] = {title = "Схватка с ящером", objective = "Хеминг Эрнестуэй просит вас убить 10 ящеров-кнутохвостов.", description = "А теперь я задам тебе задачку, посмотрим, придется ли она тебе по вкусу. Отправляйся в джунгли и добудь 10 ящеров-кнутохвостов. Увидим, хватит ли тебе пороху!", progress = nil, completion = "Именно так и появляются трофеи над камином! Неплохая охота, Эфром!", rewards = "Вы получите:\n\n"},
[196] = {title = "Схватка с ящером", objective = "Хеминг Эрнестуэй попросил вас убить 10 тропических ловцов.", description = "Посмотрим, как ты справишься со следующим испытанием. Здесь живут хитрые ящеры, мы зовем их тропическими ловцами. Их гораздо труднее выследить и убить, чем другие виды, с которыми тебе пришлось столкнуться. Убей 10 тропических ловцов, и я соглашусь, что из тебя еще выйдет <настоящий охотник/настоящая охотница>.", progress = "Ба! Что ты здесь делаешь? Настоящий охотник никогда не сдается, пока в поле зрения есть дичь. Не думаю, что тропические ловцы сами прибегут сюда и бросятся в костер. Глупый мальчик.", completion = "Хо-хо!!! У нас есть настоящий убийца ящеров! Неплохо, старина!", rewards = "Вы получите:\n\n"},
[197] = {title = "Схватка с ящером", objective = "Хеминг Эрнестуэй попросил вас убить Тетиса, хитрого, опасного ящера Тернистой долины.", description = "Ну, раз ты ходишь в джунгли как к себе домой, дай-ка я расскажу тебе о свирепом ящере, которого даже мне не удалось убить. Ажек называет этого хитрого ящера Тетис.\n\nЕсли ты хочешь показать подлинное мастерство, убей Тетис и принеси мне его коготь. Этот подвиг не удался еще ни одному охотнику!", progress = "Как идет охота на Тетис? Я так понимаю, ее следы вели к нашему лагерю?", completion = "Великий Эфром, убийца ящеров!\n\nНеплохо звучит, а?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nМундир Охотника на ящеров"},
[198] = {title = "Припасы для рядового Торсена", objective = "Доставьте различные припасы гоблинов рядовому Торсену.", description = "Хммм. У меня и правда есть для тебя дело. Лейтенант Дорен и его последователи там, на севере, регулярно получают от нас поставки еды и оборудования.\n\nПришло время доставить очередную партию, а, учитывая нападения троллей, никто не хочет за это браться. Лагерь Дорена располагается на северо-западе от дороги у входа в Тернистую долину из Сумеречного леса. Отнеси эту посылку рядовому Торсену, а если его нет в лагере, значит, он дежурит на юге от него. Он займется этими припасами.\n\nУчти, если ты провалишь задание, придется тебе возместить мои затраты.", progress = "Да? Что тебе нужно? А, припасы гоблинов. Странно, что их доставил |3-6(человек), обычно они сами этим занимаются. Не важно... Ты ведь их не касался? Славно, славно... Мы бы не хотели, чтобы с нашими минами что-нибудь случилось, о нет.", completion = "Эти мины помогут нам защититься от этого зверя, Курцена, и его людей. Спасибо за доставку. Если тебе нужна работа, может быть, я смогу помочь тебе. И тебе не придется иметь дело с гоблинами, а?", rewards = "Вы получите:\n\n"},
[199] = {title = "Прямая и черная угроза", objective = "Вернитесь к главному инженеру Плотине и покажите ему найденную улику.", description = "Вы берете образец странно пахнущего порошка.", progress = "Ну как, нашел улики?", completion = "Это тревожная находка, мягко говоря!", rewards = "Вы получите:\n\n"},
[200] = {title = "Букмекер Герод", objective = "Найдите записи букмекера Герода.", description = "Если Курцену известна тайна Торсена, значит, в наши ряды затесался шпион. Необходимо выяснить, откуда просочилась информация!\n\nСвязным Торсена в лагере Курцена был букмекер Герод. Герод работает снабженцем у Курцена, и знает все о его лагере. Если удастся добыть его записи, быть может, мы узнаем, как накрыли Торсена.\n\nКогда мы служили в войсках Курцена, кабинет букмекера располагался на верхнем этаже единственного двухэтажного дома в лагере. Скорее всего, его записи по-прежнему там.", progress = nil, completion = "Вы находите записи букмекера Герода.\n\nСреди них: список поставок в лагерь, запросы от полковника Курцена и различные письма.", rewards = "Вы получите:\n\n"},
[201] = {title = "Поиск лагеря", objective = "Найдите лагерь охотников и сообщите о его местонахождении Кразеку из Пиратской бухты.", description = "Мне сообщили о группе охотников, разбивших лагерь вверх по реке от рудника Торговой Компании возле озера Назферити. Я бы не придал этому значения, но говорят, будто один из тамошних охотников – сам Хеминг Эрнестуэй. Мне не верится, но у него настолько высокие связи, если ты понимаешь о чем я, что лучше заранее обезопасить себя.\n\nПочему бы тебе не заглянуть в этот лагерь и не разузнать, что они замышляют?", progress = nil, completion = "Хмм, значит у меня были точные сведения, как обычно. Любопытно. Кажется, они не представляют для нас опасности, но, быть может, им нужны наши превосходные товары. Хммм...", rewards = "Вы получите:\n\n"},
[202] = {title = "Полковник Курцен", objective = "Убейте 6 гвардейцев и 4 заместителей Курцена и принесите голову Курцена лейтенанту Дорену в Лагерь повстанцев.", description = "И снова ты <показал/показала> нам, на что <способен/способна>. Кажется, талантов тебя не меньше, чем у самого Курцена! Это может спасти нас, горстку повстанцев...если ты сможешь выступить против Курцена и одержать над ним верх!\n\nОн управляет своими людьми из глубин Схрона. Ступай в эту пещеру, пробейся сквозь ряды ее защитников, и одолей Курцена и его ближайших приспешников.\n\nПрощай, <имя>. Ты – наша последняя надежда.", progress = "Смею ли я надеяться, что Курцен и его защитники мертвы, Эфром?", completion = "Я не смел верить вестям, но ты несешь нам доказательство того, что... Курцен и его главные сторонники повержены. Ты спас нас всех!\n\nДжунгли полны различных угроз, но никто не мог сравниться с жестоким и умным Курценом. Теперь, когда его нет, мы можем вздохнуть спокойнее.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nШрапнельный самострел"},
[203] = {title = "Второе восстание", objective = "Убейте 15 партизан Курцена.\n\nВернитесь к сержанту Йохве в Лагерь повстанцев.", description = "Мы решительно проигрываем полковнику Курцену. Он не только блестящий тактик – его войска превосходят нас в численности в десять раз! Чтобы выжить, нам придется прибегнуть к его же подлой тактике.\n\nПроберись в лагерь на востоке и убей как можно больше его бойцов. И скройся до прибытия подкрепления.", progress = "Надеюсь, охота оказалась успешной, Крастэц. Нам не продержаться без твоей помощи.", completion = "Отлично. Потеря опытных бойцов вынудит его ослабит натиск на наш лагерь.\n\nА ты не боишься быть на нашей стороне, зная, какие силы выступают против нас??", rewards = "Вы получите:\n\n"},
[204] = {title = "Дурное лекарство", objective = "Принесите сержанту Йохве из Лагеря повстанцев 7 порций зелья из джунглей и 1 порцию экстракта ядовитого папоротника.", description = "Чтобы получить шанс выстоять против Курцена, нам необходимо лишить его лекарей. Он собрал немало целителей, которые лечат его войска зельями из джунглей и травят наших бойцов экстрактами ядовитого папоротника.\n\nНам и самим нужны эти составы, чтобы изучить их и создать свои собственные. Обыщи поселок Курцена – лекарства находятся у его целителей и партизан, а экстракты скорее всего хранятся в ящиках с припасами.", progress = "Я жду – не дождусь зелий и экстракта, Эфром.", completion = "Молодец, Эфром. Эти лекарства помогут нам выжить и сохранить боеспособность. А при помощи экстракта мы создадим собственные снадобья.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОплечье Пальмового листаПартизанский колун\n\nВы также получите:\n\n"},
[205] = {title = "Тролльское колдовство", objective = "Принесите 4 фетиша троллей из племени Дробителей Черепов брату Нимезу в лагерь Повстанцев.", description = "Пока я изучаю принесенные тобой прорисовки, собери для меня принадлежности злой магии троллей. Тебе придется проникнуть в земли племени Дробителей Черепов, второго племени на далеком юге, и добыть фетиши у их знахарей и мистиков.", progress = "Ты принес фетиши, Маладат? Должно быть, именно в них заключается секрет падения Курцена... Мне нужно это узнать!", completion = "Спасибо. Я изучу эти фетиши и пойму, они ли причина того, что Курцен обратился ко злу.", rewards = "Вы получите:\n\n"},
[206] = {title = "Май'Зот", objective = "Принесите Око Разума брату Нимезу в лагерь Повстанцев.", description = "Хотя Курцен и мертв, зло, соблазнившее его, живет! Вот что мне удалось выяснить: огрский маг – Май'Зот – живет в огрском кургане в восточных горах Тернистой долины. Говорят, что он пользуется магией, овладевающей разумом, и я не сомневаюсь, что Май'Зот виноват в падении Курцена.\n\nПока он жив, зло будет расползаться, и может даже появиться второй Курцен.\n\nУбей его и принеси мне его Око Разума, артефакт, позволяющий ему творить темные дела.", progress = "Да пребудет с тобой мое благословение. Сила Май'Зота сравнима лишь с чернотой его души.", completion = "Ага! Тебе удалось убить его! На стороне добра действуют великие силы, Бронетазик! Да не ослабеет твоя рука!\n\nЯ исследую Око Разума и попытаюсь придумать, как пользоваться им во благо. Если это невозможно... его следует уничтожить.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЗастывшая сфера"},
[207] = {title = "Тайна Курцена", objective = "Найдите 4 таблички, перерисуйте их и принесите их брату Нимезу.", description = "Когда-то полковник Курцен был великим и благородным человеком – я хочу выяснить, что заставило его свернуть с пути истинного! Должно быть, он находится под воздействием магии троллей. Надо изучить древние легенды, чтобы убедиться в этом.\n\nВ руинах тролльских городов в Тернистой долине спрятаны 4 таблички. Мне необходимо их добыть и прочесть! Перерисуй с них все отметки и принеси рисунки мне.\n\nПервая табличка находится в Руинах Бал'лал, вторая – на Коварном рифе, а третья и четвертая – в Руинах Зул'Кунды.", progress = "Полиграф! У тебя есть прорисовки тролльских табличек? Я должен раскрыть их тайны!", completion = "Спасибо, Полиграф. Я изучу твои рисунки и попытаюсь выяснить, есть ли связь между троллями и злом, одолевшим полковника Курцена.", rewards = "Вы получите:\n\n"},
[208] = {title = "Охотник на крупную дичь", objective = "Хеминг Эрнестуэй попросил вас принести ему голову короля Бангалаша, огромного белого тигра.", description = "<имя>, ты <достоин/достойна> занять место среди нас. И на полях битвы в Лордероне, и в глубоких джунглях, мне редко приходилось видеть столь умелое обращение с оружием.\n\nТебе удалось убить свирепого Син'Далла, неуловимую Баг'тиру и коварного Тетиса. Осталось одно – добыть голову короля Бангалаша. Давненько я точу зуб на этого белого тигра и оказался здесь именно ради него. Убей короля Бангалаша, и мы признаем, что тебе нет равных в искусстве охоты.", progress = "Вижу, ты вернулся, старина. Мне не раз приходилось заползать в лагерь и зализывать раны после столкновения с королем Бангалашем. Побудь здесь.", completion = "Отлично сработано! Здорово! Поздравляю, Эфром, ты преуспел там, где другие потерпели поражение.\n\nВидеть тебя в рядах нашего охотничьего отряда – это честь для меня. Отныне никто не усомнится в твоем искусстве охотника и следопыта.\n\nУра тебе! Ура!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛук предводителя охотниковВинтовка опытного охотника\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[209] = {title = "Клыки троллей", objective = "Добудьте 18 клыков троллей из клана Дробителей Черепов и принесите их Кебоку в Бухту Контрабандистов.", description = "Убивать тигров и добывать их клыки на экспорт в южные моря – трудно и дорого. К счастью, мы придумали способ обрабатывать простые рого-подобные предметы и изготавливать неотличимые подделки.\n\nЛучше всего, как ни смешно, подходят клыки троллей из племени Дробителей Черепов.\n\nШ-ш-ш, спокойно, чем меньше знает покупатель, тем крепче он спит, верно? Принеси мне побольше таких клыков, чтобы мы могли подготовить ежемесячную поставку!", progress = "Сильные, заразы, а? Ну, как успехи? Не хочу показаться нетерпеливым, но это мне покою не дает. Так как?", completion = "А, хорошо, хорошо! Хотя ты мог бы получше счистить... Ну, неважно, неважно что. Спасибо, Эфром, благодаря тебе у нас возрастет производительность и доходы! Хорошо, хорошо, а теперь перейдем к следующему делу...", rewards = "Вы получите:\n\n"},
[210] = {title = "Горшок Кразека", objective = "Отнесите разбитый горшок Кразека гоблину Кразеку.", description = "Готовка по большей части лежит на мне. И она доставляла мне много хлопот, пока я не купил механический горшок у одного гоблина в Пиратской бухте. Это чудо какое-то! Он сэкономил мне много часов... Пока не сломался!\n\nМожет, ты отнесешь его назад к продавцу, в ремонт? Продавца зовут Кразек.", progress = "Привет! Ты что-то мне принес?", completion = "А, вижу, разбитый горшок Кразека! Отличное устройство, но иногда выходят из строя пружины или шестерни. Посмотрим, что случилось с этой штукой…\n\nАга! Заржавел паровой агрегат, полетел сальник, а у надувателя отломились зубья. Странно, как тут умудрялись хотя бы варить репу!\n\nМогу ли я это починить? Разумеется!\n\nНо не за бесплатно. Бесплатный бывает только сыр в мышеловке...", rewards = "Вы получите:\n\n"},
[211] = {title = "Увы тебе, Андорал", objective = "Принесите осколок оберега Араджа командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра в Западных Чумных землях.", description = "Увы, пришло время напасть на Андорал и изгнать оттуда лича!\n\nЗлобный Араж Призыватель обосновался в самом сердце руин. Его охраняют многочисленные воины Плети, рассеянные по всему центру бывшего города, а самого Аража охраняют сильнейшие бойцы. Без многочисленных помощников тебе нечего и думать одержать над ним верх.\n\nУбей Аража и принеси мне его кристалл-талисман!", progress = "Тебе было дано задание, Самгоркалкин. Ты принес мне кристалллича в доказательство его выполнения?", completion = "Свершилось! Араж... этот лич наконец-то пал!\n\nСегодня ты оказал огромную услугу Альянсу. Храбрость и упорство – спутники подлинного героизма. Прошу тебя, прими это в знак нашей благодарности. Пусть все знают, что благодаря тебе Альянс одержал победу!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЗнак решимости"},
[212] = {title = "Холодный обед", objective = "Убейте ледоглазого василиска и принесите его охлажденный окорок Ангусу Штерну в \"Синий Отшельник\".\n\n*В этом задании запрещено в случае гибели освобождать свой дух.*", description = "Одно из моих коронных блюд – мороженый василиск под соусом винегрет из лайма. Проблема лишь в том, что... Это мясо не подлежит хранению, а ведь я должен приготовить это блюдо сегодня вечером – на день рождения одного благородного господина! Если сможете, принесите мне охлажденный окорок только что убитого ледоглазого василиска, а я организую специально для вас царскую трапезу!\n\nЛедоглазые василиски обитают в дюнах на северо-западе Тернистой долины, так что путь вам предстоит неблизкий. И не задерживайтесь по дороге!", progress = "Маладат! Вы добыли окорок? Я должен уже начать его готовить, а не то весь банкет пойдет насмарку!", completion = "О, вот это окорочок! Большое, просто огромное спасибо!\n\nА теперь попрошу меня простить, мне нужно быстренько нарубить мясо, замариновать его и сервировать для банкета.", rewards = "Вы получите:\n\n"},
[213] = {title = "Недружественное поглощение", objective = "Добудьте 8 упавших кристаллов и принесите их Кебоку в Пиратскую бухту.", description = "Он слишком далеко зашел! Мало того, что этот Гелриз теснит управляющих, назначенных торговыми олигархами, теперь он попытался обвести вокруг пальца знаменитейшего пирата!\n\nРевилгаз заявил, что не потерпит такого, и велел любым способом решить проблему.\n\nЛюбым способом? Я выбираю кражу. Геологов Торговой компании, работающих рядом с озером Назферити, заинтересовали странные синие кристаллы, найденные в руднике. Принеси мне образцы этих камней, и меня не волнует, что тебе придется сделать с геологами для выполнения задания.", progress = "Мне нужны эти камни, Эфром. Любой ценой! Подробности мне не нужны, только результат, ни больше, ни меньше.", completion = "Любопытно. Огранка кристаллов говорит только о том, что они собираются пользоваться ими в качестве горючего или катализатора. Большего сказать я не могу. Образцы необходимо показать старшему химику Хихиканту.", rewards = "Вы получите:\n\nУкрашенные перчатки"},
[214] = {title = "Красные шелковые банданы", objective = "Принесите 10 красных шелковых бандан разведчице Риэле к башне на Сторожевом холме.", description = "Не секрет, что красные банданы являются отличительным знаком бандитов из Братства Справедливости. Но мы узнали, что материал, из которого они изготовлены, указывает на ранг члена братства.\n\nЯ рассказываю вам об этом, потому что хочу, чтобы вы устранили как можно больше бандитов высокого ранга. Обладающих наивысшим рангом, без сомнения, можно найти в тайном убежище ван Клифа. Когда справитесь с заданием, принесите мне 10 красных шелковых бандан в доказательство их смерти – и будете вознаграждены. Желаю удачи, <имя>.", progress = "Избавили ли вы нашу землю от бандитов из Братства Справедливости? Если да, предъявите в качестве доказательства 10 красных шелковых бандан.", completion = "Отличная работа Бронгард! От имени народного ополчения я благодарю вас за ваши усилия. Вскоре с помощью таких смельчаков, как вы, мы вернем эту землю ее народу.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТвердый клинокРезной кинжалПронзающий топор\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[215] = {title = "Тайны джунглей", objective = "Поговорите с лейтенантом Дореном в Лагере повстанцев.", description = "Спасибо, что <спас/спасла> меня, <имя>. Понимаю, как это выглядит... но позволь мне объяснить.\n\nЛейтенант Дорен поручил мне снова завербоваться к Курцену, чтобы следить за его солдатами и предоставлять столь необходимые сведения повстанцам. Ты <видел/видела>, чем обернулась для меня попытка проникнуть в лагерь Курцена. Я думал, что это - мой шанс... Еще раз спасибо за спасение.\n\nЭто была тайная миссия, никому о ней не говори. Но лейтенант Дорен может все объяснить.", progress = nil, completion = "Да, Торсен сказал тебе правду. Только помалкивай об этом. Одно время мы, повстанцы, были слепо преданы полковнику Курцену. Но сейчас он перешел на сторону зла, и наша верность обратилась в ненависть. Если кто-нибудь узнает, что рядовой Торсен имел дело с людьми Курцена, однажды утром мы можем найти его с перерезанным горлом.\n\nНасколько мне известно, о задании Торсена знала только сержант Йохва и я. И кто-то еще. Предатель.", rewards = "Вы получите:\n\n"},
[216] = {title = "Между молотом и Колючим Мехом", objective = "Убейте 12 мстителей из племени Колючего Меха и 12 шаманов из племени Колючего Меха. Большинство из них находятся к востоку от Зорамского взморья в деревне Колючего Меха. Выполнив задачу, возвращайтесь к Карангу Амаккару в форт Зорам'гар, что в Ясеневом лесу.", description = "Эти фурболги Колючего Меха мешают нашему продвижению! Деревня Колючего Меха, что лежит на востоке, преграждает нам путь к заставе Расщепленного Древа. Это на дороге, что идет в обход деревни Астранаар. Если мы не будем ее контролировать, Альянс получит дополнительный путь для вторжения.\n\n<имя>, мы должны заткнуть эту дыру!\n\nИди в деревню Колючего Меха да устрой фурболгам прореживание. Выполнишь задачу – получишь награду, но важнее будет то, что ты выполнишь свой долг перед Ордой!", progress = nil, completion = "Отлично, |3-6(Маг), отлично! Я буду продолжать посылать отряды истреблять этих фурболгов, но по крайней мере я могу рассчитывать, что еще одна дорога расчищена от сил Альянса. Теперь завоевание Ясеневого леса Ордой пойдет полным ходом!\n\nТы заслужил свою награду, герой! Честь и слава тебе!", rewards = "Вы получите:\n\n"},
[217] = {title = "Защита королевских земель", objective = "Убейте предводителя троггов Громага и его охранников, Скрежетуна и Буяна. Сообщите об этом капитану Ругельфассу в южной сторожевой башне.", description = "<имя>, наши разведчики обнаружили предводителя троггов. Похоже, этих тварей привел к озеру Лок Модан их вождь по имени Громаг. Его хорошо охраняют. Два элитных стража, Скрежетун и Буян, ни на шаг от него не отходят.\n\nЕсли ты <уверен/уверена> в своих силах, <имя>, можешь возглавить операцию по ликвидации Громага и его громил. Если нам удастся прикончить вождя троггов, то появится шанс загнать проклятых тварей обратно под землю.", progress = "Громаг и его охранники, Скрежетун и Буян, все еще живы. Задание не выполнено, покуда все трое живы. Все дворфы рассчитывают на тебя, Малагрис.", completion = "Превосходно, Вив! Ты вернул надежду Лок Модану. Громаг мертв, и у нас появилась надежда изгнать троггов из наших земель.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБрюки первопроходцаДворфийская защитаСчастливые брюки\n\nВы также получите:\n\n"},
[218] = {title = "Украденные записи", objective = "Убейте Грик'нира Холодного и верните Грелину его записи.", description = "Мои записи! Они уволокли в свою мерзкую пещеру мои записи! Здоровенный громила, весь разрисованный с головы до ног... Жаль, я не смог разглядеть его получше!\n\nПослушай, тебе ведь уже приходилось иметь дело с троллями? Может, ты сумеешь вернуть мои драгоценные записи?..", progress = "А, Эфром! Ну, как дела?", completion = "Великолепно, Эфром! Словами не передать, как я благодарен! Мои записи, наконец-то!.. Да к тому же, похоже, троллей Холодной долины удалось-таки обуздать, так что больше беспокоиться не о чем.\n\nКстати, послушай: я скоро закончу свое донесение – так, может, ты поработаешь курьером и доставишь его моему братцу Сениру?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДворфийский каплевидный щитГладкий дорожный посох\n\nВы также получите:\n\n"},
[219] = {title = "Пропавший без вести", objective = "Проводите капрала Кеешана до Красногорья.", description = "Наконец-то, сторонники Альянса!\n\nПомогите... Пожалуйста...\n\nПоследнее, что я помню – как орки окружили наш отряд. Меня ударили по затылку, и в глазах потемнело. А теперь я пленник в этой пещере. Спасите меня, я тяжело ранен.\n\nМне понадобится помощь, чтобы добраться до города... Пожалуйста... Вы моя последняя надежда...", progress = "Да?", completion = "Ты отлично послужил Королевству, |3-6(Паладин). Благодарю тебя за помощь капралу Кеешану. Одному ему не удалось бы сбежать от орков Черной Горы. Подобная храбрость заслуживает великой награды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОдеяние СоломонаПлетеный нагрудник делегатаУкрепленный костью кожаный доспех\n\nВы также получите:\n\n"},
[220] = {title = "Зов Воды", objective = "Отнесите фиал с чистейшей водой Ислен Заклинательнице Воды в Степи.", description = "Прежде чем дать тебе в награду следующий тотем, Ислен поручит тебе еще одно задание. Для этого понадобится фиал с водой, который я дал тебе.\n\nСтупай, поговори с ней. Мы еще встретимся.", progress = "И снова здравствуй, Ахахаха. Выглядишь ты неплохо.\n\nЧто привело тебя ко мне?", completion = "А, фиал с водой, созданной и благословленной Брин и добытой тобой, ни больше ни меньше.\n\nЖидкость в этом фиале необходима для создания сапты, но годится и для других целей.\n\nПри помощи этой сапты ты сможешь разглядеть водных духов в святилище в Серебряном бору, к югу от Подгорода. Что же до оставшихся капель... о них я расскажу тебе потом.\n\nНе боишься долгого пути, Ахахаха?", rewards = "Вы получите:\n\nСапта воды"},
[221] = {title = "Воргены в лесу", objective = "Убейте 12 вестников Тьмы из стаи Ночной Погибели.", description = "Может, ты <заметил/заметила> крупных воргенов, бродящих по лесу в компании тенеткачей? Судя по всему, большую часть воргенских сил и составляют эти самые вестники Тьмы.\n\nСтранствуя по лесу, я узнал, что они захватили и Гниющий сад на юго-западе от города. Эти воргены сильнее тех, с которыми тебе уже пришлось столкнуться.\n\nБудь <осторожен/осторожна>.", progress = "Уже вернулся, Бордор? Надеюсь, ты не собираешься отказываться от задания?", completion = "Ты достойно выступил против вестников Тьмы, Бронгард. Но, похоже, ряды их нескончаемы. На место убитых становятся все новые и новые воргены.\n\nЧто за злая сила притягивает их сюда? Зачем они явились терзать наш несчастный город... \n\nЯ возлагаю надежду на мастера Кэрвина. Не сомневаюсь, он разберется с этой проблемой.", rewards = "Вы получите:\n\n"},
[222] = {title = "Воргены в лесу", objective = "Калор просит вас убить 8 Ярых Клыков из стаи Ночной Погибели и 8 нечистых воргенов из стаи Ночной Погибели.", description = "Твои прежние достижения наводят меня на мысль, что ты можешь схватиться с сильнейшими из воргенов, наводнивших наши леса.\n\nСамими опасными из всех оказались Ярые Клыки и нечистые воргены. Они живут рядом с пещерами и в руднике на юге.\n\nЗарево их костров видно издалека.", progress = nil, completion = "Честно говоря, Бронгард, я не верил, что ты справишься с этой задачей, но ты воистину могучий |3-6(Охотник). Более того, если ты хочешь официально присоединиться к борьбе мастера Кэрвина, я с радостью напишу тебе рекомендательное письмо.", rewards = "Вы получите:\n\n"},
[223] = {title = "Воргены в лесу", objective = "Отнесите записку Калора Джонатану Карвину.", description = "Вот, <имя>. Отнеси это письмо мастеру Кэрвину.\n\n*Он отдает вам поблекший пергамент.*\n\nЕсли к нам потянутся такие, как ты, в отряде будет больше людей, чем в Ночном дозоре! Быть может, тогда мы завершим работу, которую сейчас делаем с большим трудом.", progress = "Да, что тебе нужно? Быстрее, у меня полно неотложных дел.", completion = "Прости за холодный прием, Бронгард, ты ведь понимаешь, что я очень занятой человек. Вижу, ты произвел впечатление на Калора. Уверяю тебя, это нелегко. Так или иначе, он рекомендует принять тебя в наши ряды.\n\nВокруг полно ненадежных людей, а нам нужна помощь тех, на кого можно положиться. Мы бьемся против демонов, нежити и их пособников. Не теряй бдительности, осторожности и не доверяй никому, кто не хочет нам помочь.\n\nДа озарит тебя Свет!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлащ верыЩит Веры\n\nВы также получите:\n\nОсвященный жезл"},
[224] = {title = "Защита королевских земель", objective = "Горный пехотинец Кремневик просит вас убить 10 троггов из племени Камнедробов и 10 разведчиков из племени Камнедробов.", description = "Мы должны защитить озеро Лок, <имя>! Множество королевских солдат проливает кровь в далеких землях, а наш родной край в опасности. Трогги полезли изо всех щелей! Нашествие троггов грозит безопасности Стальгорна. Пора истребить мерзких мутантов!\n\nНам нужна твоя помощь, <отважный искатель приключений/отважная искательница приключений>. Ступай и устрани нависшую над нами угрозу. Убей 10 троггов из племени Камнедробов и 10 разведчиков из племени Камнедробов и возвращайся.", progress = "Лок Модан в осаде, Клиус! Все сторонники Альянса, способные держать оружие, должны нам помочь. Ты уже убил 10  троггов из племени Камнедробов и 10 разведчиков из племени Камнедробов?", completion = "Молодчина, Wrestlecake! Ты проявил немалое мужество на поле боя. Побольше таких, как ты, и мы победим троггов. Ты славно послужил королю Магни.\n\nЕсли тебе по нраву такие свершения, поговори с горным пехотинцем Булыжным Карьером. Капитан дал ему непростое задание. Уверен, ему понадобится помощь. Поговори с Булыжным Карьером, он сейчас в башне.", rewards = "Вы получите:\n\nДаларанский острый сыр"},
[225] = {title = "Заброшенная могила", objective = "Поговорите с Широй Фон-Инди в Темнолесье.", description = "Надпись на древнем могильном камне гласит:\n\nМОРГАН ЛАДИМОР\n\n*При внимательном рассмотрении вы замечаете, что могилу недавно раскапывали, и большая часть земли насыпана заново...*", progress = nil, completion = "Морган Ладимор?\n\nА-а-а, да, разумеется. У него долгая и печальная история. Я знал его до того, как он ушел на войну, но с тех пор ни разу не видел. Он был добрым и благородным человеком, но окончил свою жизнь плохо.\n\nПодожди-ка, я дам тебе вещь, которая поведает его историю лучше, чем я...", rewards = "Вы получите:\n\n"},
[226] = {title = "Волки идут по пятам", objective = "Убейте 12 голодных лютых волков и 8 бешеных лютых волков. Вернитесь к Ларсу в лагерь Свена на западной границе Сумеречного леса.", description = "Нас со Свеном ждут трудные времена, учитывая, что на востоке поселился Некромант. Мы здесь совсем одни, приходится самим добывать себе еду. Такое впечатление, что всякий раз, как я возвращаюсь в лагерь, неся добычу, за мной увязывываются лютые волки. Что и говорить, жить здесь опасно!\n\nНо если ты избавишь нас хотя бы от части волков, нам станет полегче. Они живут на севере и на востоке отсюда, возле реки.", progress = "Охота еще не закончена?..", completion = "О, хорошо. Ты здорово проредил волчью стаю, и если хищники перестанут нас преследовать, мы сможем заняться Морбентом Скверном.\n\nВот, возьми в награду взрывпакеты. Их делают в городе, и Свену недавно выделили целую партию.", rewards = "Вы получите:\n\nВзрывпакет"},
[227] = {title = "Морган Ладимор", objective = "Поговорите с командиром Альтеей Чернодрев в Темнолесье.", description = "*Он роется на полках и вытаскивает книгу в кожаном переплете.*\n\nЕсли хочешь узнать побольше, спроси Альтею, она занималась... проблемами... возникшими с ним в последнее время.", progress = nil, completion = "Морган Ладимор? Никогда о нем не слышала...\n\nА, ты о Мор'Ладиме! Ты не знаешь его историю?\n\nЧто ж, я объясню тебе вкратце. По Сумеречному лесу бродит неупокоенный мертвец, зовущий себя Мор'Ладимом. Судя по всему, это восставшее из могилы тело Моргана Ладимора, о котором ты, кажется, уже слышал. Он доставил нам массу неприятностей – начиная от нападения на патрульных и заканчивая убийствами простых людей.\n\n*Она смеривает вас взглядом.*\n\nКажется, ты смог бы помочь ему упокоиться с миром.", rewards = "Вы получите:\n\n\"Роман о Моргане Ладиморе\""},
[228] = {title = "Мор'Ладим", objective = "Убейте Мор'Ладима и отнесите его череп командиру Альтее Чернодрев в Темнолесье.", description = "Разведчики сообщают, что Мор'Ладим бродит по кладбищу. Мы похоронили его за домом на холме, знаешь, где это?\n\nБольше я тебе ничем помочь не могу... Разве что пожелать удачи.", progress = "Я не буду винить тебя, если тебе не удастся справиться с ним, Эфром. Мор'Ладим отнял жизни у сильнейших из наших воинов.", completion = "Ты убил его? Это великий подвиг, Эфром! Прими благодарность от имени народа Темнолесья и Ночного дозора.\n\nАх, да... Осталось еще одно дело...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[229] = {title = "Выжившая дочь", objective = "Поговорите с Сарой Ладимор в Темнолесье.", description = "Надо было предупредить тебя раньше…\n\nКак бы тебе сказать…\n\nМорган думал, что у него погибла вся семья, но его дочь, Сара Ладимор, жива и служит в Ночном дозоре. Ее всегда беспокоили... обстоятельства... связанные с гибелью ее отца. Быть может, ты сообщишь ей о случившемся.", progress = nil, completion = "Да? Мой отец…\n\n*Она опускает глаза.*\n\nЖаль... что я не могу ничего для него сделать... Ах, если бы я поговорила с ним до того, как...", rewards = "Вы получите:\n\n"},
[230] = {title = "Лагерь Свена", objective = "Принесите Свену книгу, найденную на ферме Свена.", description = "Порывшись в груде земли, вы находите небольшую книгу, перепачканную грязью.\n\nНа ней нет заглавия, зато в ней содержатся сведения, необходимые Свену.", progress = "Что ты нашел?! Пожалуйста, дай посмотреть...", completion = "*Свен прочитывает несколько страниц и захлопывает книгу.*\n\nЭтот таинственный незнакомец – свидетель смерти моей семьи! У меня столько вопросов к этому человеку... Узнать бы, кто он!", rewards = "Вы получите:\n\n"},
[231] = {title = "Дочерняя любовь", objective = "Отнесите кольцо Сары Ладимор на могилу Моргана Ладимора.", description = "Возьми это кольцо и отнеси на его могилу. Может быть... может быть, он поймет, что я жива и никто не винит его в случившемся.\n\n*Со слезами на глазах она снимает кольцо с правой руки и отдает вам.*\n\nИ... спасибо, <имя>.", progress = "Оставь меня в покое...", completion = "*В шорохе ветра слышится призрачный голос...*\n\nЧто это?.. Сара? Неужели она жива? Камень с сердца…\n\nЭфром. Возьми мой меч, Принцип. Моя душа упокоилась, и он более мне не нужен. Он был выкован во имя добра, а я оказался не достоин владеть им. Быть может, ты сможешь нести Свет вместо меня.\n\nЛиз, любовь моя...", rewards = "Вы получите:\n\nПринцип"},
[232] = {title = "Посылка для аптекаря Зинг", objective = "Отнесите заказ на товары Алессандро Луке в Подгород.", description = "Королевскому фармацевтическому обществу нужна твоя помощь. Слушай внимательно, поскольку, если мой план удастся, мы оба окажемся в выгодном положении.\n\nСогласна, аптекарь Чанн... немного тронутый... но его исследования приносят свои плоды, если попадают в руки к умному человеку. К счастью, я как раз из таких. Отнеси этот заказ Алессандро Лусе, хозяину \"Тысячи мелочей Синей Луны\", он даст тебе набор для полевых испытаний. Принеси его мне, и я расскажу тебе подробнее о задании.", progress = "Да, чем могу помочь? Ты здесь по приказу Королевского фармацевтического общества или же просто поговорить пришел?", completion = "А, так Зинг нужен набор для полевых испытаний? Жаль, что она не решилась осчастливить меня своим визитом.\n\nЛадно, сейчас я подготовлю набор.", rewards = "Вы получите:\n\n"},
[233] = {title = "Почта Холодной долины", objective = "Доставьте письма Талину Остроглазу.", description = "Не думаю, что ты горишь желанием мне помочь, <парень/красотка>, но у меня тут целая куча писем, а времени на доставку нет.\n\nЭто все для Талина Остроглаза. Его лагерь – у замерзшего озера, к западу отсюда.\n\nНу что, может, доставишь ему почту?", progress = "А? Что? Для меня что-то есть?", completion = "Благодарю тебя, я уже давно ждал этих писем...\n\nКонечно, они не все для меня. Вот это, скажем, для Грелина Белоборода. Он тут неподалеку живет, может, зайдешь к нему?", rewards = "Вы получите:\n\n"},
[234] = {title = "Почта Холодной долины", objective = "Доставьте письмо Грелину Белобороду.", description = "Если мне память не изменяет, лагерь Грелина находится дальше по дороге, на юго-восток отсюда. Не сомневаюсь, он будет рад этому посланию.", progress = "Могу ли я тебе чем-нибудь помочь?", completion = "Здорово! Я уже давно не получал весточки из Стальгорна.", rewards = "Вы получите:\n\n"},
[235] = {title = "Большая охота", objective = "Поговорите с Сенани Громосерд на заставе Расщепленного Древа в Ясеневом лесу.", description = "Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!\n\nОрде удалось закрепиться в землях к северу от Степей. И два наших форпоста – застава Расщепленного Древа и застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на заставе Расщепленного Древа, к северу от Степей. Она ждет желающих принять участие в большой охоте!", progress = nil, completion = "Добро пожаловать на новое пограничье, Демонорох. Ясеневый лес – край неограниченных возможностей, где юному |3-2(Чернокнижник) вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть.\n\nКак понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.", rewards = "Вы получите:\n\n"},
[236] = {title = "Горючее для разрушителей", objective = "Осадный кузнец Крепкохват из крепости Ледяных Оков попросил вас собрать 10 неугасимых угольков с тел воинов Орды в Огненной котловине.", description = "<имя>! Ты как раз вовремя. Хотя эта битва закончилась, мы должны подготовиться к новым сражениям. Отправляйся в Огненную котловину, который находится в на юго-востоке озера Ледяных Оков, и принеси оттуда несколько неугасимых угольков.\n\nСмешав их с обычным углем, мы получим топливо для наших разрушителей и осадных машин.\n\nКстати, если по пути тебе встретятся солдаты Орды – не стесняйся, убей их и забери угольки. Нельзя допустить, чтобы в следующей битве преимущество оказалось на их стороне.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[237] = {title = "Защита королевских земель", objective = "Горный пехотинец Булыжный Карьер просит вас убить 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов.", description = "Горный пехотинец Кремневик превозносит тебя до небес, <раса>. Поэтому я хочу доверить тебе очень важное задание. Мы не должны ослаблять натиск на троггов, пока наши братья-дворфы не вернутся с войны.\n\nОтправляйся в южные холмы и убей 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов. Это поможет нам выиграть время. Когда выполнишь задание, возвращайся.", progress = "Мы должны выиграть время, |3-6(гном). Тебе приказано убить 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов. Не ослабляй натиск на врага, пока не подойдет подкрепление. Сейчас не время сидеть сложа руки.", completion = "Ты прекрасно справился с заданием, |3-6(человек)! Сам король может гордиться тобой.\n\nК сожалению, обещанное подкрепление так и не подошло. Фронт обагрен кровью воинов Альянса. Вести о потерях наполняют горечью мое сердце... Так пусть же эти жертвы будут не напрасны! Мы должны с честью выдержать невзгоды и вернуть Альянсу былую славу.\n\nПоговори с горным пехотинцем Стеноломом, он даст тебе новое задание. Ты нужен нам как никогда.", rewards = "Вы получите:\n\nПростое лечебное зелье"},
[238] = {title = "Посылка для аптекаря Зинг", objective = "Отнесите набор для проведения полевых испытаний аптекарю Зинг в Подгород.", description = "Я подготовил набор, <имя>. Не сомневаюсь, аптекарю Зинг не терпится его получить. Отнеси посылку как можно скорее и сообщи ей, что я запишу стоимость набора на счет Общества. Кроме того, передай ей мой пламенный привет.\n\nНу же, не стой как истукан. Простым курьерам не ведом отдых, а?", progress = "Похоже, Луса такой же надоедливый, как и ты. Впрочем, неважно. Давай сюда набор. Мне нужно немного с ним поработать, чтобы знать, какие компоненты искать.\n\nТы ведь принес его?", completion = "Хорошо – приятно работать с теми, кто старается не тратить мое время попусту.\n\nКогда я закончу с набором, ты сможешь двинуться в путь. Набор пригодится для сбора необходимых данных.\n\nЯ попытаюсь закончить побыстрее. А пока ждешь, можешь обдумать, что возьмешь с собой в пустыню.\n\nДа, именно в пустыню.", rewards = "Вы получите:\n\n"},
[239] = {title = "Гарнизон у Западного ручья просит помощи!", objective = "Отправляйтесь  в Гарнизон у Западного ручья и поговорите с заместителем судьи Рейнером.", description = "Гарнизон западной границы докладывает об усилении активности гноллов и грабителей. Они просят, чтобы мы прислали подкрепление из Штормграда... Но у нас не хватает людей!\n\nТвоя помощь не была бы лишней. Поговори с заместителем судьи Рейнером: он сейчас находится в гарнизоне у Западного ручья. Рейнер скажет тебе, что делать.\n\nГарнизон расположен к западу отсюда: иди по дороге, а потом, когда перейдешь через речушку по мосту, сверни направо.", progress = nil, completion = "Тебя что, маршал Дугхан сюда послал? Ну... Ты, конечно, не солдат, но маршалу я доверяю.\n\nУ нас тут сложилась, скажем так, напряженная ситуация. Надеюсь, ты сумеешь нам помочь.", rewards = "Вы получите:\n\n"},
[240] = {title = "Возвращение к Трясунчику", objective = "Отнесите Трясунчику темные пирожки с крабами.", description = "А вот и пирожки с \"крабами\" а-ля Груал!", progress = "Эфром, ты уже здесь! А где моя еда?!", completion = "Ага! Спасибо, Эфром. Как раз то, что нужно.\n\nА вот и твоя плата за услугу!", rewards = "Вы получите:\n\n"},
[243] = {title = "Поход в пустыню", objective = "Поговорите с главным инженером Чепухастером из Прибамбасска насчет источника энергии для набора для полевых испытаний.\n\nПрилагается предмет: \n", description = "Ты отправишься в пустыню Танарис изучать состав тканей василисков, скорпидов и гиен. Добудь образцы тканей и проверь их при помощи этого набора; подозреваю, что не все окажутся удачными. Мне нужно по восемь образцов каждого вида.\n\nКроме того, у гоблинов Прибамбасска есть источники энергии, необходимые для работы измененного набора. Поговори с главным инженером Чепухастером и добудь у него источник энергии.\n\nБез образцов ткани можешь не возвращаться.", progress = nil, completion = "А, наши источники энергии 4711-ФТЗ! Обычно мы пользуемся ими для электрификации колодцев, но БЛАГОДАРЯ ПРОКЛЯТЫМ КОЧЕВНИКАМ энергии у нас в избытке.\n\nНе вопрос, я могу добыть тебе источник энергии, для каких бы гнусных научных целей он тебе ни понадобился. А, думаешь, я ни о чем не догадался? Как бы не так. Но это тебе дорого обойдется, |3-6(нежить). В Прибамбасске ничто не достается даром.", rewards = "Вы получите:\n\n"},
[244] = {title = "Вторжение гноллов", objective = "Поговорите с заместителем судьи Фелдоном.", description = "Привет тебе, <класс>. Мне приказано охранять этот участок дороги. Хотя сейчас здесь безопасно, к северу и к востоку отсюда я видел лагеря гноллов.\n\nВ Приозерье должны узнать о том, что гноллы собирают армию! Сообщи об этом заместителю судьи Фелдону. Уверен, он заплатит тебе за принесенные вести.\n\nФелдон обычно обходит территорию к югу от моста по дороге в Приозерье.", progress = nil, completion = "К Элвиннскому лесу подбираются гноллы Красногорья? Похоже, скоро они доберутся и до наших земель. И тогда не только Приозерье окажется в осаде!\n\nВозьми плату за вести, хоть они и скверные. И время сейчас неподходящее, ведь мы ничего не сможем противопоставить новой угрозе.", rewards = "Вы получите:\n\n"},
[245] = {title = "Восьминогая угроза", objective = "Убейте 15 карликовых ядовитых кругопрядов и доложите об этом дозорному Додсу в Сумеречном лесу.", description = "Привет тебе, <класс>. Наверное, ты <видел/видела> пауков на западной границе? Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья.\n\nМне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться. Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов.\n\nМой тебе совет: остерегайся их яда.", progress = nil, completion = "А! Ты вернулся. И на первый взгляд – в целости и сохранности. Разумеется, Эфром, Ночной дозор весьма тебе признателен. Я обещал вознаградить тебя, и обещание свое выполняю. Держи.", rewards = "Вы получите:\n\nРукавицы Ночного Дозора"},
[246] = {title = "Подсчет врагов", objective = "Убейте 10 полукровок из стаи Красногорья и 6 браконьеров из стаи Красногорья и сообщить об этом заместителю судьи Фелдону в Приозерье.", description = "У нас нет лишних людей, но с гноллами, о которых ты говоришь, надо что-то делать.\n\nПоищи их в южной части Красногорья. Убей, кого сможешь, и сообщи мне об их общем числе и степени угрозы, которую они представляют для города. Гноллы стоят лагерем вдоль южной дороги.\n\nСделай это ради армии Штормграда, <имя>, и получишь награду.", progress = "Прости, Ларсварог, но у меня сейчас совсем нет времени. Если тебе не о чем сообщить, мне лучше вернуться к делам.", completion = "*Заместитель судьи Фелдон слушает ваш отчет.*\n\nЗначит, там собралось немало гноллов, и, судя по всему, они весьма сильны. Должно быть, тебе нелегко было собрать эти сведения.\n\nЧто ж, Эфром, мы благодарим тебя за помощь.\n\nЕсли ты еще не беседовал с маршалом Маррисом и мировым судьей Соломоном, непременно обратись к ним. Дела у нас идут все хуже; не сомневаюсь, эти двое найдут тебе работу.", rewards = "Вы получите:\n\n"},
[247] = {title = "Завершение охоты", objective = "Шаманко, ты убил всех трех чудовищ охоты в Ясеневом лесу. Ты предоставил мне несомненные доказательства их гибели, так что сомнений в твоих силе и упорстве у меня нет. В твоих жилах течет кровь охотников, и да будет тебе хвала по делам!\n\nПрошу, прими эту безделицу в знак благодарности за твои деяния, совершенные тобой ныне в Ясеневом лесу во славу Орды. Да будут духи предков милостивы к тебе!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nБроня Буйного охотника"},
[248] = {title = "Пронизывающий взор", objective = "Поднимитесь на уцелевшую башню рядом с крепостью Каменной Стражи.\n\nОтыщите подходящее место и спрячьте там амулет Азоры.", description = "Я наблюдал за башней Илгалара и понял, что Моргант враждует с орками крепости Каменной Стражи. Не знаю, что за этим кроется, но ты можешь помочь мне приоткрыть завесу тайны.\n\nВозьми еще один амулет Азоры и отнеси его на вершину уцелевшей башни рядом с крепостью.\n\nОтыщи подходящее место для амулета и спрячь его там. Для этой цели прекрасно подойдет сундук или кувшин.", progress = "Когда-то в этом кувшине был какой-то смрадный напиток, но теперь пустой сосуд лежит, забытый, на паре бочек.", completion = "Это подходящий сосуд для амулета Азоры. Он позволит Теокриту проникнуть в помыслы обитателей крепости Каменной Стражи.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[249] = {title = "Моргант", objective = "Победите Морганта.\n\nПринесите его подвеску Тени Теокриту в башню Азоры в Элвиннском лесу.", description = "Ценой долгих усилий я раскрыл планы Морганта.\n\nОн ищет Косу Элуны... и быть может, уже отыскал ее! Коли так, то скоро Красногорье, а следом и все королевство Штормграда почувствует его темную мощь.\n\nЯ не готов выступить против Морганта, но, боюсь, терять время нельзя. Ты <должен/должна> войти в башню Илгалара и бросить ему вызов.\n\nОдолей злодея, принеси мне его подвеску Тени, и королевство тебя не забудет.", progress = "Торопись, Эфром, пока не сбылись мои опасения и темное влияние Морганта не расползлось по всей стране.", completion = "Ты сделал великое дело, Эфром. Чернокнижник Моргант повержен, и Штормград избавлен от великой опасности.\n\nСмиренно прошу принять эту награду. Я пожелал бы тебе мира, выпади нам жить в мирные времена.\n\nВместо этого желаю удачи в ожидающих тебя испытаниях и победы в предстоящих боях.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nОплечье Розы"},
[250] = {title = "Прямая и черная угроза", objective = "Осмотрите область вокруг восточной части Дамбы и отыщите для главного инженера Плотины улику, указывающую на замыслы дворфов Черного Железа.", description = "Хвала небесам, что хоть кого-то волнует наша дамба. Будто мало нам разрушенного моста Тандола и разграбленного Дун Модра! Не сомневаюсь, следующей целью Черного Железа станет именно Дамба. Большую часть охраны отослали биться за Альянс, в том числе моего старшего инспектора.\n\nПотому-то ты мне и <нужен/нужна>, <имя>. Я заметил саперов из клана Черного железа неподалеку от восточной части дамбы. Разведай обстановку и возвращайся с уликами.", progress = nil, completion = "В подозрительной бочке содержится странно пахнущий порошок.", rewards = "Вы получите:\n\n"},
[251] = {title = "Перевод записки Аберкромби", objective = "Отнесите письмо, адресованное Элло, Шире Фон-Инди.", description = "Отнесите записку Шире Фон-Инди. Он знает множество языков и не чужд древним искусствам – если кто и может перевести это послание, то это он.", progress = "Значит, это записка от отшельника Аберкромби? Я с ним не знаком, но если он живет на кладбище, то мозг у него – трухлявый, как старый пень!", completion = "*Шира принимается за перевод записки...*", rewards = "Вы получите:\n\n"},
[252] = {title = "Перевод для Элло", objective = "Отнесите переведенное письмо лорду Элло Чернодреву.", description = "О небо! Если то, о чем сказано в этой записке – правда, то Аберкромби сделал нечто... невообразимое.\n\nОтнеси-ка переведенную записку Элло.\n\nИ поторопись, поскольку я боюсь, что это чудовище уже ковыляет к городу...", progress = "А, так записку перевели? Дай-ка взглянуть...", completion = "*Элло читает письмо... и бледнеет на глазах. Затем он поднимает на вас взгляд.*\n\nХотя ты помогал Аберкромби по доброте душевной, именно ты обрек наш город на гибель.\n\n*Элло погружается в раздумья...*", rewards = "Вы получите:\n\nПереведенное письмо бальзамировщика"},
[253] = {title = "Невеста Бальзамировщика", objective = "Отыщите могилу Элизы. Извлеките из нее сердце Бальзамировщика и вернитесь к Элло Чернодреву.", description = "Бальзамировщиком в наших краях давно пугают детей. Когда-то он был добрым алхимиком, но смерть любимой жены Элизы лишила его рассудка. Чтобы вернуть ее к жизни, он прибег к темной магии и даже вложил в грудь мертвой супруги собственное сердце.\n\nЭто оживило Элизу... но ее сразило проклятие – она возжелала человеческой плоти, и Бальзамировщику пришлось закопать ее обратно.\n\nВсе его могущество заключено в сердце. Отыщи могилу Элизы, извлеки из нее сердце и принеси его мне, пока оно бьется. Если тебе удастся выполнить это, то сила Бальзамировщика иссякнет.", progress = "Тебе удалось найти могилу Элизы? А достать сердце Бальзамировщика?", completion = "Получилось! Магия этого сердца защитит нас от зла Бальзамировщика и послужит могущественным талисманом Темнолесью.\n\nТы совершил подвиг во имя нашего народа, Эфром. Мы тебя не забудем.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nОплечье ЧестиРыцарский щит Темнолесья"},
[254] = {title = "Копание земли", objective = "Вы копаете землю... и наконец находите остатки гроба.\n\nВы слышите скрежет когтей по крышке и лязганье гнилых зубов…\n\nРешитесь ли вы открыть гроб и достать сердце Бальзамировщика?", description = nil, progress = nil, completion = nil, rewards = nil},
[255] = {title = "Наемники", objective = "Мировой судья Тупонос просит вас убить 4 огров из клана Мо'грош, 4 громил из клана Мо'грош и 4 головорезов из клана Мо'грош.", description = "Пройдет два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да еще два месяца они будут до нас добираться! И мало того, что наш город остался без защиты, но раскоп и дамба – дамба! – тоже в опасности.\n\nПохоже, у меня нет выбора. Придется искать наемников.\n\nКак насчет тебя? На первый взгляд ты подходишь, <класс>. На северном берегу озера разбила лагерь группа огров. Может быть, ты избавишь наш город от опасности?", progress = nil, completion = "Прекрасные новости! Я и народ Телcамара глубоко признательны тебе. Ведь если нам удастся разобраться с ограми, мы сможем заняться троггами.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[256] = {title = "Разыскивается: Чок'сул", objective = "Убейте Чок'сула и принесите его голову чиновнику Тупоносу в Телcамар.", description = "По приказу магистрата Телcамара:\n\nЧок-сул, обвиняемый в организации нападений на город Телcамар, Каменную дамбу и раскоп, приговаривается к смерти любым из возможных способов.\n\nВознаграждение получит тот, кто предоставит в Магистрат доказательства смерти Чок-сула.\n\nВ последний раз обвиняемого видели в лагере огров в северо-восточной части озера Лок Модан.", progress = "Да? Чем я могу вам помочь?", completion = "Ой! Что это? И зачем ты притащил ее…\n\nБоги!.. Это она? Ну, разрази меня гром, неужели это голова проклятого огра? Вот это улов! Что ж, награда и благодарность от имени всего народа Телcамара достаются тебе по праву!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНадежные плетеные наплечникиСапоги Кимбры\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nМалое кольцо Благословения"},
[257] = {title = "Похвальба охотника", objective = "Убейте 6 горных канюков и вернитесь к Дэрилу Юному в Приют странников. На выполнение задания отводится 15 минут.", description = "Думаешь тягаться с Дэрилом Смелым? Не советую! Разумеется, отговаривать тебя я не буду. Вот испытание, которое тебе явно не по силам. Не огорчайся, если ничего не выйдет.\n\nНеподалеку от озера Лок Модан свила гнезда стая канюков. Почему бы не подстрелить несколько тварей? Знаешь что, если ты справишься с моим заданием за пятнадцать минут, я отдам тебе свой лук или ружье.\n\n*Он с презрением осматривает вас.*\n\nВсе равно тебе нечего терять.", progress = "Не вышло? Не расстраивайся, бедненький Яробород…\n\nНе всем же быть такими, как я.", completion = "Что? Получилось?!\n\nПослушай добрый совет, Wrestlecake, пусть успех не кружит тебе голову. Я хочу сказать, любой безусый паренек с луком справился бы с такими... небольшими существами. Надеюсь, тебе не слишком нравится убивать канюков, м-м-м? Не хотелось бы, чтобы они стали исчезающим видом.\n\nЧто ж, э-э-э... Пусть не говорят, что Дэрил Смелый не держит свое слово.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОхотничий лук ДэрилаОхотничья винтовка Дэрила\n\nВы также получите:\n\n"},
[258] = {title = "Вызов охотнику", objective = "Убейте 5 старых горных вепрей и вернитесь к Дэрилу Юному в Приют странников. На выполнение задания отводится 12 минут.", description = "<имя> <Батькович/Батьковна>, да? Вижу, ты лопаешься от гордости за выполненное задание, а? Я же говорил, что это легко.\n\nА вот попробуй поохотиться на кабанов. Верь мне, это тебе не поросята из  Холодной долины, с ними надо поосторожнее. На сей раз даю тебе двенадцать минут.\n\nНе расстраивайся, если ничего не выйдет. Я тебе рубаху с собственного плеча отдам, если ты справишься!\n\nЯ не рассказывал, как получил свой знаменитый шрам? Нет? Это было два года назад...", progress = "Вполне простительно пожалеть себя, если тебе утер нос кто-то столь же юный, как я. Не расстраивайся, Гандальф...\n\nКстати, это у тебя имя такое или кличка?", completion = "Похоже, тебе несладко пришлось. Видно, кабаны задали тебе изрядную трепку, да? Не беспокойся, я никому не расскажу о твоем поражении. Тебе и без досужих болтунов тяжело.\n\nО! Ты умудрился убить кабанов? Я... что ж... хочу сказать, ничего удивительного! Любой ребенок смог бы... Обещание?\n\nКакое еще обещание?", rewards = "Вы получите:\n\nТонкая матерчатая рубашкаКороткий меч Дэрила"},
[261] = {title = "Путями Алого ордена", objective = "Убейте 30 опустошителей-отрекшихся и вернитесь к брату Антону на Высоте Найджела.", description = "Буду откровенен. Мы ведем войну с нечистью. Это зло, уничтожающее наш народ и оскверняющее нашу землю. Нежить нужно остановить, пока это возможно, иначе весь мир погрузится во мрак. Мы поклялись сражаться до последней капли крови, не щадя ни жизни, ни души.\n\nТы с нами? Тогда яви свое мужество и докажи свою доблесть: убей опустошителей-отрекшихся, бродящих по Пустошам на юге, в Долине Костей.\n\nСделай это, и братство Алого ордена примет тебя.", progress = "С каждым днем Плеть становится все сильнее и многочисленнее. Если ты действительно хочешь остановить ее, докажи это делом!", completion = "Тебе удалось доказать свою решимость. Братство Алого ордена благодарит тебя.\n\nЕсли тебя не страшит то, что ради правого дела приходится убивать, причем часто и много, тогда тебе с нами по пути.", rewards = "Вы получите:\n\n"},
[262] = {title = "Таинственный незнакомец", objective = "Отнесите книгу, обнаруженную на ферме Свена, в Темнолесье и покажите ее горожанам.", description = "Я должен узнать, кто таился в тени в ту ночь, когда была убита моя семья!\n\nПрошу тебя, <имя>, помоги мне. Ты не раз <творил/творила> настоящие чудеса. Выясни, кто это был. Мне нужно узнать его тайны!\n\nЯ рассказал тебе все, что мог, но возьми эту книгу, обнаруженную на ферме. Может быть, кто-то в городе опознает ее, и мы выясним имя владельца?", progress = "Если у тебя есть что-нибудь из вещей того незнакомца, которого ты разыскиваешь, покажи это мне. Может быть, я смогу понять, кто ее владелец.", completion = "Хмм... Кто-то совсем недавно держал эту книгу в руках. Этот человек одержим жаждой мести. Но увы, следы на ней, по крайней мере следы первого владельца, едва различимы.\n\nЯ могу сказать одно: он не из Темнолесья.", rewards = "Вы получите:\n\n"},
[263] = {title = "Защита королевских земель", objective = "Горный пехотинец Стенолом просит вас убить 10 шаманов из племени Камнедробов и 10 костегрызов из племени Камнедробов.", description = "Горные пехотинцы уверяют, что ты <силен и отважен/сильна и отважна>, <имя>. Нам <нужен/нужна> <раса> вроде тебя. Мы никак не можем справиться с троггами. Всех бойцов отозвали на фронт, и мы остались без защиты. Но раз среди нас <появился закаленный/появилась закаленная> в боях <класс>, то может быть, нам удастся выстоять.\n\nУбей 10 шаманов из племени Камнедробов и 10 костегрызов из племени Камнедробов. Посмотрим, не преувеличены ли слухи о твоей доблести, о Гроза троггов.", progress = "Уже вернулся? На всякий случай повторяю: я просил убить 10 шаманов из племени Камнедробов и 10 костегрызов из племени Камнедробов, Малагрис. В атаку, Гроза троггов!", completion = "Я сразу понял, Медведик, что Стальгорн будет тобой гордиться. Ты славно послужил королю Магни. Теперь, доказав, что ты верный защитник Королевства, можешь поговорить с капитаном. Может быть, он посвятит тебя в наши более насущные проблемы.\n\nХвала тебе, Медведик.", rewards = "Вы получите:\n\nЗернистое точило"},
[264] = {title = "Покуда смерть не разлучит нас", objective = "Положите подвеску Кларисы на могилу Юрива в Серебролесье.", description = "Скотина такая! Бросил меня ради своего клятого похода! Понимаете ли, \"Свет превыше всего, ибо он единственная наша защита от нежити!\"\n\nА как же дети?! А я?! Много ночей я терпеливо ждала его... я всегда была второй после его гребаного долга!\n\nИ посмотрите, <имя>, теперь на плоды борьбы за \"справедливость\"! Он мертв, а на меня обрушилось все то, чему он пытался помешать!\n\nВозьмите этот хлам и положите на его могилу в Гробнице. Мне не нужен больше этот мусор... и он сам тоже!", progress = "Каменная плита холодна на ощупь. Могила была осквернена: вокруг валяется мусор, барельеф на плите исцарапан, из него выбиты куски, надгробье зарастает травой.\n\nНикому нет дела до погребенного здесь, особенно если это жертва поветрия.", completion = "Вы кладете дешевую безделушку на могилу, и драгоценный камень в ней заметно тускнеет.\n\nКогда вы поднимаетесь, чтобы уйти, вы смотрите на подвеску – она лежит, тусклая и мертвая, в руках вырезанного на надгробной плите изображения. Ваши мысли прерывает порыв холодного ветра, пронесшегося по Гробнице. На мгновение все вокруг вас замирает.", rewards = "Вы получите:\n\n"},
[265] = {title = "Продолжение поисков незнакомца", objective = "Поговорите с горожанами о таинственном незнакомце.", description = "Вот твоя книга, <имя>, желаю удачи в расследовании. Если ты расспросишь других горожан, они могут рассказать тебе что-нибудь ценное.\n\nЯ же скажу одно: хотя автор этой книги не из нашего города, тетрадь для нее он купил здесь.", progress = "Иногда я продаю чистые тетради ученым и магам, а также тем, что хочет вести дневник.\n\nЯ помню всех покупателей за последние несколько месяцев...", completion = "Ах, да. Я продал эту тетрадь одному сомнительному типу. Он не представился, но явно нервничал, дергался, то и дело оглядывался через плечо. \n\nНадеюсь, что смог тебе помочь...", rewards = "Вы получите:\n\n"},
[266] = {title = "Расспросы в таверне", objective = "Найдите в таверне улики, связанные с таинственным незнакомцем.", description = "Вот твоя книга, желаю удачи в расследовании.\n\nСоветую заглянуть в таверну. Если человек, о котором ты говоришь, останавливался у нас в городе, скорее всего его кто-то видел.", progress = "Хотя \"Алый Ворон\" процветает не так, как раньше, путники гостят здесь и в наши дни.\n\nЕсли ты опишешь того, кого ищешь, может быть, я его вспомню.", completion = "Ах да, эту книгу я помню. Ее владелец снимал комнату на несколько дней и вечерами засиживался в баре, все писал.\n\nГород он покинул в спешке, бормоча под нос, что его преследует... что-то. В последний раз я видел его на дороге, ведущей на запад. Кажется, он собирался искать новое укрытие.\n\nПервое, что ему встретится на западе, – это Вороний холм...", rewards = "Вы получите:\n\n"},
[267] = {title = "Троггская угроза", objective = "Принесите 8 каменных зубов троггов капитану Ругельфассу.", description = "<класс>, не знаю, <слышал/слышала> ли ты о новой угрозе, нависшей над землями дворфов. Внутренние войска отправили на фронт, на охране осталась лишь горстка воинов. Мой полк приставлен к Вратам, и я не могу отойти от них, поскольку мы опасаемся вторжения врагов.\n\nИ все же необходимо усилить натиск на троггов, заселивших холмы. Если это задание тебе по плечу, проведи вылазку в их стан. Принеси в доказательство своих свершений 8 каменных зубов троггов.", progress = "Ты принес мне 8 каменных зубов троггов? Если нет, тебе есть чем заняться, Wrestlecake.", completion = "Отличная работа, Wrestlecake. Ты оказал всем дворфам великую услугу, защищая наши земли. Сам король Магни Бронзобород может гордиться тобой!", rewards = "Вы получите:\n\n"},
[268] = {title = "Возвращение к Свену", objective = "Отнесите Свену законченные записи Трясунчика.", description = "Я лишь наполовину успел закончить книгу, найденную тобой. Мне пришлось оставить ее на ферме Свена во время поспешного бегства…\n\nВот. Отнеси Свену все мои записи. Здесь подробно рассказывается о случившемся на ферме.\n\nХотя единственным моим сокровищем в последние несколько недель были только эти записи, я охотно расстанусь с ними, лишь бы не вставать на пути Свена!", progress = "Тебе удалось выяснить, что это за незнакомец?", completion = "Записи многое проясняют. Теперь мне ясно, что следует искать темных всадников! Я встречал их в Сумеречном лесу и видел, как они говорят с чародеем Морбентом Скверном у Покинутой усадьбы.", rewards = "Вы получите:\n\n"},
[269] = {title = "В поисках мудрости", objective = "Отдайте законченные записи Трясунчика епископу Фартингу в Штормграде.", description = "Отправляйся в Штормград и поговори с епископом Фартингом в Соборе Света. Отдай ему записи Трясунчика и сообщи, что собираешься бросить вызов Морбенту Скверну.\n\nХоть Штормград и бросил Темнолесье на произвол судьбы, Фартинг – добрая душа и мудрый человек. Он поможет тебе спасти нас.\n\nТебя ждет много опасностей... Однако поспеши, <имя>. С каждым часом в Сумеречном лесу сгущается тьма.", progress = "Отдохни пока, брат. Я вижу, у тебя позади долгий путь, и на тебя возложена тяжкая ноша. Скажи, что за тень пала на тебя?", completion = "*Епископ изучает записи...*\n\nЗло нашло лазейку в и без того обложенный со всех сторон Сумеречный лес. Хвала Свету, что отыскался герой вроде тебя.\n\nНо прежде чем смело двинуться навстречу испытаниям, тебе следует хорошо подготовиться... Некромант Морбент Скверн всегда был необычайно силен, а чтобы стать неуязвимым, наложил на себя могучие чары. Тебе не одолеть его без оружия, способного пробиться сквозь эти преграды.", rewards = "Вы получите:\n\n"},
[270] = {title = "Обреченный флот", objective = "Отправляйтесь в Гавань Менетилов в Болотине и поговорите с дворфом по имени Глорин Стальной Лоб.", description = "Много лет назад Третья флотилия Кул-Тираса затонула у берегов Болотины, огромной топи к северу от дворфийского королевства Стальгорна. Одно из судов было нагружено светлой сталью.\n\nЭтот металл представляет для нас большую ценность, поскольку изготовленное из него оружие и доспехи разят врагов силой святой истины. Если вы собираетесь противостоять Морбенту Скверну, вам именно такое оружие и понадобится.\n\nОтправляйтесь в Гавань Менетилов и переговорите с моим коллегой-дворфом по имени Глорин Стальной Лоб. Если утерянный груз еще можно найти – он сообразит, где нужно искать.", progress = nil, completion = "Светлая сталь – и впрямь драгоценный металл, но все говорит за то, что задание у тебя не из легких. Ты проделал длинный путь, братишка. Если тебе сильно повезет, ты можешь найти то, что ищешь.\n\nА если раздобудешь металл – я знаю, кто сможет выковать подходящее оружие против того некроманта в Сумеречном лесу, о котором ты говоришь.", rewards = "Вы получите:\n\n"},
[271] = {title = "Месть Вайрины", objective = "Убейте Старину Черношкура и принесите его голову Дэрилу Юному в Приюте странников.", description = "Не хочешь отплатить Его Смелости? Вынуждена признать, что Дэрил в самом деле многое умеет.\n\nГод назад весь Приют странников охотился на огромного медведя, но ни одному смельчаку не посчастливилось его одолеть. Тогда Дэрил решил выступить против зверя сам. Разумеется, он ничего не добился, да еще и получил этот уродливый шрам над глазом.\n\nУбей медведя, и не сомневаюсь, что даже Дэрил ненадолго лишится дара речи.\n\nСтарину Черношкура можно отыскать в логове в холмах над Телcамаром.", progress = "А, Вйнсент! Уже вернулся? Опять охотился? Не огорчайся, если тебя постигнет неудача. Неудачи заставляют нас работать над собой!\n\nВ любом случае тебе повезет больше, чем некоторым...", completion = "Э... что это? Судя по всему, медвежья голова.\n\n*Он невольно проводит пальцем по старому шраму.*\n\nЧто ж, интересная добыча. Не тот ли самый медведь...\n\n*Он умолкает и начинает заметно дрожать.*\n\nО, скорее убери ее! Убери отсюда эту страшную штуку!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[272] = {title = "Испытание Морского Льва", objective = "Найдите половинку подвески Ловкости водяного облика и половинку подвески Выносливости водяного облика. Поговорите с жителями Лунной поляны, чтобы узнать, где могут находиться эти предметы.\n\nСложите из половинок подвеску Морского Льва. Для этого вам надо находиться рядом со святилищем Ремулоса.\n\nОтнесите собранную подвеску Дендриту Блеску Звезд в деревню Ночная Гавань, что на Лунной поляне.", description = "Вот твое второе испытание – тебе понадобятся две половинки подвески Морского Льва. Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва. Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика.\n\nПоговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить. Сделав это, отнеси подвеску Дендриту Блеску Звезд.", progress = "Ты уже собрал подвеску, Иселор? Дай посмотреть. Если тебе нужна помощь, чтобы соединить половинки, обратись к местным жителям. Так ты не только узнаешь то, что тебе надо, но и познакомишься с этой чудесной, благословенной поляной.", completion = "Ты прошел испытание Морского Льва, Иселор. Прими мои поздравления.\n\nКаждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой. Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва.\n\nЗапомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик.", rewards = "Вы получите:\n\n"},
[273] = {title = "Снабжение экспедиции", objective = "Поговорите с Хальдаром.", description = "Еще не поздно, ты можешь поискать Хальдора. Вряд ли он ушел далеко; Миран и Сайан – крепкие ребята, но под грузом бочек ходят не слишком быстро.\n\nОни пошли к раскопу обычной дорогой – на юг от города, вдоль берега озера.\n\nНайти их будет несложно, если они еще не добрались до места назначения.", progress = nil, completion = "Хм, жалкой засаде Черного Железа не помешать мне доставить товар!\n\nНо Сайан... Никогда бы не подумал, что он сторонник этих предателей. Я с ним почти год работаю... должно быть, что-то упустил.\n\nЛадно, подумаю об этом позже.", rewards = "Вы получите:\n\n"},
[274] = {title = "Прямая и черная угроза", objective = "Сообщите главному инженеру Камнехмылу о нейтрализующем коллоиде.", description = "Это не простой взрывчатый порошок. Только взгляни на эти крошечные серебристые кристаллы. А характерный запах! Ясно, как день – это сефорий. Сам по себе он безобиден, но, намокнув, может взорвать весь Стальгорн!\n\nХимическую реакцию можно нейтрализовать, смешав четыре компонента: паучий яд, толченый кристалл Могроша, слезу кроколиска и нейтрализующий коллоид. Расскажи об этом Плотине, пока не поздно!", progress = "Что ты принес от Аслана?", completion = "Нейтрализующий коллоид? Для сефория? О небо!", rewards = "Вы получите:\n\n"},
[275] = {title = "Нарывы на теле земли", objective = "Убейте 12 трясинных ползунов и вернитесь к Ретилю Стражу Природы в Болотину.", description = "Болотину лихорадит, и я не знаю почему. Трясинные ползуны набирают силу. Это болезненные, гнойные нарывы на теле земли! И чтобы исцелить ее, нужно загнать трясинных ползунов обратно в болота, откуда они вылезли.\n\nПолзуны водятся у водоемов в Болотине.", progress = "Я слышу стон земли Болотины. Трясинные ползуны все еще оскверняют ее своим присутствием. Возвращайся, когда выполнишь мое поручение.", completion = "Скоро раны на теле земли затянутся, и лихорадка спадет. Я благодарю тебя и вручаю небольшой подарок...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОдеяние Хранителя ТопиЛесная кольчугаРастительный клинок\n\nВы также получите:\n\n"},
[276] = {title = "Вытоптанные луга", objective = "Убейте 15 гноллов  из стаи Мохошкуров и 10 полукровок  из стаи Мохошкуров. Вернитесь к Ретилю Стражу Природы в Болотину.", description = "Многие годы гноллы из стаи Мохошкуров мирно жили в Болотине, но теперь их поголовье увеличилось. Они вытаптывают наши прекрасные луга и вырубают лес на дрова!\n\nЧтобы спасти природу нашего края, придется истребить часть гноллов.\n\nУбей 15 гноллов  из стаи Мохошкуров и 10 полукровок  из стаи Мохошкуров. Они водятся на юге, возле дворфийских Врат Альгаза. Когда справишься с заданием, вернись ко мне.", progress = "Ты еще не выполнил мое задание, |3-6(Паладин).", completion = "Теперь наши земли спасены! Признаться, раньше я с недоверием относился к вашему брату... но твой подвиг, |3-6(человек), заставил меня задуматься. Спасибо тебе!", rewards = "Вы получите:\n\n"},
[277] = {title = "Запрет на огонь", objective = "Принесите Ретилю Стражу Природы 9 необработанных кремней.", description = "Гноллы из стаи Мохошкуров вырубают деревья Болотины и жгут древесину, греясь у костров. Я этого не потерплю!\n\nОтбери у гноллов их кремни, которыми они высекают огонь. Кремни есть у всего клана, кроме мелких гноллов и полукровок из стаи Мохошкуров.", progress = "Ты принес эти проклятые камни для высекания огня?", completion = "Спасибо. Я раскрошу их в порошок и выброшу в море, и их уже никогда не используют для того, чтобы жечь живую древесную плоть.", rewards = "Вы получите:\n\nГубчатые сморчки"},
[278] = {title = "Прямая и черная угроза", objective = "Принесите паучий яд, мо'грошский кристалл и слезу кроколиска главному инженеру Плотине.", description = "Немедленно принимайся за сбор материалов для нейтрализации взрывчатки, <имя>. Паучий яд ты найдешь у пауков у озера Лок Модан. Слезу кроколиска можно отыскать там же. А вот заполучить кристалл Могроша будет нелегко. Такие кристаллы добывают огры, живущие к северо-востоку отсюда, но и у огров они водятся нечасто.\n\nМы должны разминировать творение Черного Железа! Как только соберешь все материалы, сразу же возвращайся, и я подготовлю состав.", progress = "Ты принес все необходимое? Торопись!", completion = "Наконец-то, Великийгром!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[279] = {title = "Угроза из глубин", objective = "Убейте 12 мурлоков из племени Синежабрых.\n\nПрикончите Жруна и принесите его голову Карлу Борану в Гавань Менетилов.", description = "Мурлоки выходят из морских глубин и строят свои поселения на побережье. Они нападают на наших рыбаков и торговцев, и это уже переходит всякие границы. Их надо остановить.\n\nОдин из этих мурлоков, Жрун, придумал устраивать засады на наших купцов на дорогах. На мурлоков из племени Синежабрых нет никакой управы. Творят, что хотят, а потом прячутся в ближайших поселениях, и все – их уже не достать. Наши торговцы в опасности, и мы готовы хорошо заплатить тому, кто возьмется их защищать.\n\nЖрун промышляет в речном заливе к северу отсюда. Принеси мне его голову, а заодно перебей его сородичей.", progress = "Наши купцы смогут почувствовать себя в безопасности, только когда мы избавимся от Жруна и его сородичей.", completion = "Отлично, Wrestlecake!\n\nВот твои деньги, ты честно их заработал, выполнив все обязательства.", rewards = "Вы получите:\n\n"},
[280] = {title = "Прямая и черная угроза", objective = "Проплывите по реке к основанию дамбы, отыщите бочку с порохом и влейте в нее нейтрализующую смесь, чтобы предотвратить взрыв.", description = "Я только сегодня видел мятежников Черного Железа, которые тащили к Дамбе большую бочку. И рядом со мной не было ни одного горного пехотинца, поэтому никто их не остановил! Боюсь, они заложили сефорий у основания Дамбы, и она того и гляди взлетит на воздух! Дай-ка я смешаю все компоненты. Вот, у меня получилась нейтрализующая смесь.\n\nСкорее, возьми смесь и залей ее в бочку, пока не поздно. Торопись!", progress = "Крышка бочки медленно отвинчивается.", completion = "Вы вливаете нейтрализующую смесь, и из бочки доносится слабое шипение.", rewards = "Вы получите:\n\n"},
[281] = {title = "Украденные товары", objective = "Обыщите сундуки, бочки и ящики в поселениях мурлоков на побережье.", description = "Не так давно мурлоки напали на торговый корабль \"Слепая принцесса\". Корабль удалось спасти, но эти подлые твари растащили почти весь груз, в том числе и одну очень ценную вещь, статуэтку Теренаса Менетила. Ее надо вернуть во что бы то ни стало.\n\nОбыщи поселение мурлоков на побережье. Ищи сундуки, ящики, бочки – все, что может быть связано с украденным грузом. Найди статуэтку Менетила и верни ее мне.", progress = nil, completion = "Сундук отсырел, он весь исцарапан – это явно следы от когтей. Вы открываете сундук. Внутри – размокшая гнилая солома. Можно предположить, что здесь спрятана некая ценная вещь, требующая бережного обращения. Вы разгребаете солому...\n\n...и находите несколько бутылок из красного стекла.", rewards = "Вы получите:\n\nЛечебное зелье"},
[282] = {title = "Наблюдения Сенира", objective = "Поговорите с горным пехотинцем Талосом.", description = "Я собирался послать своего ученика к брату Сениру с отчетом, но парень он не слишком надежный, а мне нужен кто-то, на кого действительно можно положиться. Ну, то есть, конечно, если ты не будешь возражать.\n\nХм-м. Чтобы добраться до Караноса, тебе придется пройти по тоннелю. \n\nПеред тем как зайти в тоннель, заскочи к горному пехотинцу Талосу и поговори с ним – в тоннеле полным-полно троггов.\n\nСначала тебе нужно вернуться по дороге к Старой Наковальне, а потом направиться на восток. Рядом с тоннелем Талос и стоит – найти его будет несложно.", progress = "Приветствую! Я тебе вот что скажу, Эфром: ты в тоннеле Дун Морога будь поосторожнее, там полно троггов, так что дорога небезопасна.\n\nЯ тебе даже больше скажу: если у тебя нет неотложных дел в Дун Мороге, оставайся-ка лучше в Старой Наковальне, пока в тоннеле не станет поспокойнее.", completion = "Хм. Ну что ж, если Белобород послал тебя в Дун Морог по важному делу, то не мне тебя останавливать, верно?\n\nС другой стороны, пару советов-то я могу тебе дать...", rewards = "Вы получите:\n\n"},
[283] = {title = "Прямая и черная угроза", objective = "Кажется, нейтрализующая смесь сработала. Вернитесь к главному инженеру Плотине – принесите ему добрые вести.", description = "Бочка негромко шипит.", progress = nil, completion = "Огромное спасибо, Криворучка! Ты спас Каменную дамбу. Без твоей помощи террористы Черного Железа непременно разрушили бы это знаменитое сооружение. Королевство и Альянс гордятся тобой, отважный |3-6(Чернокнижник)!\n\nДамба снова в безопасности... по крайней мере, пока...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДворфийский двуручный дровоколКлинок-шип\n\nВы также получите:\n\n"},
[284] = {title = "Поиски продолжаются", objective = "Найдите статуэтку Менетила.", description = "Вы обыскиваете все поселение мурлоков в этом районе, но статуэтки Менетила здесь нет.\n\nМожет быть, стоит проверить ближайшие несколько жилищ к северу и северо-востоку отсюда?", progress = nil, completion = "Эту бочку, похоже, никто не трогал. Вы открываете ее...\n\nЗапах валит вас с ног. Сыр слегка заплесневел, но он вполне съедобен!", rewards = "Вы получите:\n\nДворфийский мягкий сыр"},
[285] = {title = "Поиски в поселениях мурлоков", objective = "Продолжите поиски статуэтки Менетила в поселении мурлоков.", description = "Вы обыскиваете еще несколько жилищ мурлоков. Вот досада – опять ничего!\n\n...Но вы уверены, что все получится.\n\nСтатуэтка Менетила наверняка где-то здесь, в одном из жилищ к северу.", progress = nil, completion = "Бочка наполовину утоплена в грязи и мокрой траве...", rewards = "Вы получите:\n\n"},
[286] = {title = "Возвращение статуэтки", objective = "Верните статуэтку Менетила Карлу Борану.", description = "Вы достаете бочку из грязи, открываете ее и видите серебряную статуэтку, укрытую соломой. Фигурка изображает юного длинноволосого паладина с воздетым над головою молотом.\n\nЭто, должно быть, и есть статуэтка Менетилова! Теперь вам надо вернуть ее Карлу Борану в Гавань Менетилов.", progress = "Ты принес статуэтку?", completion = "Капитан \"Слепой принцессы\" будет очень доволен, когда узнает, что мы сумели вернуть ценный груз. Ты сослужил нам хорошую службу и получишь обещанную награду.\n\nРадостно сознавать, что в этом мире еще есть надежные люди, на которых можно положиться, и особенно – в такое тяжелое и неспокойное время.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖезл-сосулькаМоряцкие сапоги\n\nВы также получите:\n\n"},
[287] = {title = "Форт Мерзлогривов", objective = "Обследуйте форт Мерзлогривов и убейте 5 охотников за головами из племени Мерзлогривов по просьбе Сенира Белоборода из Караноса.", description = "Я не успеваю с донесением, и твоя помощь, <имя>, мне бы пригодилась. Я сумел узнать, где засели тролли, но их там было столько, что я побоялся лезть туда.\n\nВот что мне нужно... Спустись в пещеру, порыскай там, прибей пару-другую троллей и возвращайся ко мне.\n\nОтправляйся из Караноса по северной дороге. Когда перейдешь через мост, следуй на запад по замерзшей реке, пока не доберешься до Заледеневшего озера. На западном берегу обнаружишь Поселок Пивоваров. Форт Мерзлогривов находится к юго-западу от него.", progress = nil, completion = "А, Wrestlecake! Я так и думал, что тебе будет несложно найти это место, ведь мои указания были предельно четки...\n\nДай-ка мне закончить донесение.\n\n*Он приносит бумагу и что-то быстро на ней пишет.*\n\nВот! Ха-ха, теперь это совсем забавно... Думаю, Wrestlecake, ты не откажешься помочь мне еще разок?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОдеяние Теплой ЗимыКаменный кулачный щит\n\nВы также получите:\n\n"},
[288] = {title = "Третья флотилия", objective = "Купите первому помощнику Фитсиммонсу кружку медовухи.", description = "Когда-то я был первым помощником на \"Владычице\", линейном корабле Кул-Тирасской Третьей флотилии. Обреченной флотилии... Во время последнего плавания на нас напали красные драконы. А ими правили орки!\n\nУ нас не было ни единого шанса спастись от драконьего огня, и все корабли были сожжены и потоплены у побережья. Я один уцелел в этом кошмаре.\n\nОх, как же раскалывается голова! Погоди, сейчас я выпью чего-нибудь, немного приду в себя и продолжу.", progress = "Трубы горят, сил нет! Добрый господин, не купишь бедному забулдыге чего-нибудь горячительного? Умираю!", completion = "Вот! И голова не болит, и язык развязался. Спасибо, приятель!", rewards = "Вы получите:\n\n"},
[289] = {title = "Проклятая команда", objective = "Убейте 13 проклятых матросов, 5 проклятых стражей бухты и первого помощника Снеллига. Принесите табакерку Снеллига первому помощнику Фитсиммонсу в Гавань Менетилов.", description = "*Приободрившись, Фитсиммонс продолжает рассказывать...*\n\nЯ единственный уцелевший из всех матросов злополучной Кул-Тирасской Третьей флотилии, погибшей у северного побережья. И хотя я последний из команды, чье сердце бьется и кто еще дышит, я не единственный, кто еще бродит по земле! На одном из наших кораблей хранилось великое, ужасное сокровище, и его потусторонняя зловещая сила держит души моих собратьев и не дает им покинуть гниющие остовы кораблей.\n\nЕсли ты сможешь их освободить, тогда, может быть, они избавятся от проклятия.", progress = "Мне снятся кошмары, в которых я слышу, как наяву, стоны моих обреченных собратьев! Заклинаю тебя, добрый сэр, освободи их от этого ужаса. Пусть их стоны и вопли умолкнут навечно.", completion = "Багодарю тебя, Rainon. И прими благодарность моих несчастных собратьев.", rewards = "Вы получите:\n\n"},
[290] = {title = "Очищение", objective = "Возьмите ключ от сейфа на \"Отважном\" у капитана Халиндора.\n\nОткройте сейф на \"Отважном\".", description = "Чтобы избавиться от проклятия и освободить моих верных товарищей, нужно найти и очистить эту... проклятую штуковину... спрятанную на моем корабле! Не знаю, что это такое, знаю только, что эта штука хранится в корабельном сейфе, а ключ от сейфа – у капитана Халиндора.\n\nСтарина капитан снится мне до сих пор. Я знаю, он сейчас на \"Отважном\" – нашем несчастном корабле. Постарайся добыть ключ от сейфа, открой его и возьми эту вещь.\n\nПотом отнеси ее в город и отдай жрецу Глорину Стальному Лбу.", progress = "Сейф заперт надежно.", completion = "Ключ насквозь проржавел, но замок открылся без труда.", rewards = "Вы получите:\n\n"},
[291] = {title = "Донесения", objective = "Отнесите донесение Сенира сенатору Бэрину Краснокамню в Стальгорн.", description = "Замечательно! Отнеси мое донесение сенатору Бэрину Краснокамню. Он мрачный тип, постарайся не заразиться от него унынием. Ты найдешь его в Стальгорне, в палате, где король Магни вершит суд.\n\nЧто? Не знаешь дороги в Стальгорн? От Караноса возьми к северу, перейди мост, затем иди по восточной дороге – там по обе стороны штандарты – и вверх по склону горы.\n\nКстати, будь <добр/добра>, не говори о том, как ты мне <помогал/помогала>. Понимаешь, я не хочу, чтобы подумали, будто я тут не тружусь в поте лица.", progress = "Хм... похоже, мои охранники потеряли хватку и пропускают ко мне кого попало. Ладно, что тебе надо? Говори быстрее.", completion = "*Он быстро просматривает донесение.*\n\nПо приказу КОРОЛЯ!? Магни совсем спятил! И еще этот проклятый Белобород... Значит, взял дела в свои руки? Сенат этому не обрадуется, вовсе не обрадуется.\n\nЧто, ты еще здесь? Иди отсюда, пока я охрану не вызвал!", rewards = "Вы получите:\n\n"},
[292] = {title = "Око Палета", objective = "Отнесите проклятое Око Палета Глорину Стальному Лбу.", description = "Внутри сундука лежит темный шар, источающий зловещее свечение. Это и есть то сокровище, о котором говорил Фитсиммонс: проклятое Око Палета.\n\nОтнесите проклятое Око Палета дворфийскому жрецу Глорину Стальному Лбу в Гавань Менетилов. Попросите его снять проклятие с Ока.", progress = "Тебя послал этот пропойца Фитсиммонс? Так скажи ему, что эль у меня закончился! Нечего ему разорять мои запасы.", completion = "Око Палета? Поразительно! Хмм... с ним явно что-то не так. Говоришь, ты нашел его среди обломков судна? Это многое объясняет! Но как же Око попало на корабль Третьей флотилии?..\n\nНеудивительно, что этот Фитсиммонс так перепугался. Проклятое Око Палета кого угодно выбьет из колеи.", rewards = "Вы получите:\n\n"},
[293] = {title = "Проклятое Око", objective = "Отнесите Око Палета архиепископу Бенедикту. Его можно найти в Соборе Света в Штормграде.", description = "Я не могу снять проклятие с Ока Палета. Это людское творение, и поэтому тебе следует направиться в Штормград. Найди того, кто сумеет тебе помочь. Обратись к архиепископу Бенедикту. Он главный в Соборе Света Штормграда, и сможет дать тебе наставления.\n\nНадеюсь, у тебя все получится.", progress = "Что это у тебя? Какой-то запачканный шар...", completion = "Это Око Палета. Определенно, оно видело много скорбей и печалей... может быть, стало свидетелем некоей ужасной, поистине ужасной трагедии.\n\nСейчас я очищу его, ибо Очи созданы для того, чтобы сиять ярким светом, и их сила становится опасной, если они запятнаны порчей.", rewards = "Вы получите:\n\nОко Палета"},
[294] = {title = "Месть Ормера", objective = "Убейте 10 крапчатых ящеров и 10 крапчатых крикунов.", description = "Придется признать, что положение отчаянное. Когда мы раскопали эти кости, ящеры немедленно атаковали нас. Многие из братьев были разорваны на месте, а мы с Меррин и бедолагой геологом оказались в ловушке здесь, наверху.\n\nПомоги очистить Болотину от ящеров, <имя>. Крапчатые ящеры и крапчатые крикуны водятся к западу от этого утеса. Убей по 10 тварей каждого вида.\n\nЭто будет началом моей мести.", progress = "Убей 10 крапчатых ящеров и 10 крапчатых крикунов, Рейнон. Мои погибшие товарищи не заслужили своей горькой участи. Пора свести счеты.", completion = "Я понимаю, что убийство – грязная и опасная работа, Rainon. Но если бы я не поклялся остаться рядом с геологом и Меррин, я бы и сам отправился с тобой.", rewards = "Вы получите:\n\n"},
[295] = {title = "Месть Ормера", objective = "Убейте 10 крапчатых смертехватов и 10 крапчатых острозубов. Вернитесь к Ормеру Сталеплету на раскоп Вельгара.", description = "Пора нанести им сокрушительный удар. Внизу бродят стаи крапчатых смертехватов и крапчатых острозубов. Убей по 10 гадов каждого вида!", progress = "Крапчатые смертехваты и крапчатые острозубы должны заплатить за все, что они с нами сделали. Ты уже убил по десятку этих мерзавцев?", completion = "Rainon, ты не представляешь, как ты мне помог!", rewards = "Вы получите:\n\n"},
[296] = {title = "Месть Ормера", objective = "Убейте Зарлозуба и принесите Ормеру Сталеплету один из когтей чудовища.", description = "Пока тебя не было, я заметил, что среди этих тварей есть один выдающийся экземпляр. Он крупнее остальных и отличается особой свирепостью. Могу поклясться, что он – их вожак, это он привел их сюда и подначил разорить шахту.\n\nСослужи мне последнюю службу, <имя>. Зарлозуба надо предать правосудию. А если принять во внимание тяжесть его преступлений, правосудие здесь может быть только одно: смерть на месте! Убей его и в доказательство принеси мне один из его когтей.", progress = "Зарлозуб мертв? Ты отомстил за смерть наших братьев?", completion = "Спасибо, Rainon. Мы не забудем того, что ты сделал для нас. Сколько ни в чем не повинных дворфов полегло в этой злосчастной шахте – а ведь они просто трудились на своих местах. Но ты отомстил за наших безвинно погибших братьев, и теперь ящеры дважды подумают, прежде чем нападать на владения короля Магни.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПогибель ящеровБроня Погибели ящеровКарьерный жезл\n\nВы также получите:\n\nРецепт: невероятно вкусный омлет"},
[297] = {title = "Сбор идолов", objective = "Принесите Магмару Рудоколу 8 резных каменных идолов.", description = "Незадолго до появления в раскопе троггов мы обнаружили множество странных резных идолов. Изучить их мы не успели, потому что вскоре после этого трогги вытеснили нас из развалин! А идолы оказывают на этих тварей странное воздействие – превращают их в берсерков!\n\nОтбей идолов у троггов и принеси мне – я хочу их изучить. Идолов ты найдешь у троггов – а их в раскопе более чем достаточно.", progress = "И где же идолы? Надо хорошенько изучить их и сообщить о результатах в Стальгорн!", completion = "Ты добыл их! Хвалю, Wrestlecake!\n\nИ хотя там полно троггов-берсерков, ты, кажется, не сильно пострадал. Я буду с интересом следить за твоей судьбой... Ты подаешь надежды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДворфийская спичкаТроггорезТелсамарский топор\n\nВы также получите:\n\n"},
[298] = {title = "Отчет о ходе раскопок", objective = "Отнесите отчет о ходе работ Джерну Шлеморогу в Телсамар.", description = "Мне нужно отправить в Телcамар отчет о ходе работ и запрос на получение нового груза пороха! Вот мой отчет. Отнеси его Джерну Шлеморогу, он наш представитель в Телcамаре.\n\nЗадание не сложное, но достаточно важное.", progress = "О, отчет о ходе работ на раскопе? Превосходно!", completion = "Ха! У Железняка проблемы с троггами. Интересно, порох ему нужен для продолжения раскопок или для войны с этими тварями...\n\nТак или иначе, он будет потрачен не зря!\n\nНо вот что странно, несколько недель назад я послал ему немало пороха. Интересно, куда он делся.", rewards = "Вы получите:\n\n"},
[299] = {title = "Тайны прошлого", objective = "Обыщите раскопки и найдите четыре недостающих фрагмента скрижали: Адос, Модр, Голм и Неру. Принесите их геологу Вельгару.", description = "Перед самым вторжением я обнаружил скрижаль с письменами, именуемую скрижалью Гоаз. Несколько кусков отломилось, и в четырех местах текст обрывается. Там говорится о некоем \"замысле богов\" и о \"проклятом пророчестве\".\n\nБоюсь, у нас мало времени. Я уже слишком стар, чтобы сражаться с этими тварями в раскопе. Но ты <молод и полон/молода и полна> сил.\n\nОбыщи раскоп и найди четыре недостающих фрагмента скрижали – Адос, Модр, Голм и Неру. Ищи среди древних артефактов или там, где почва разрыхлена. Найди эти фрагменты и принеси их сюда, и, быть может, тогда я сумею расшифровать письмена и разгадать эту тайну!", progress = "Ты нашел недостающие фрагменты, Rainon? Адос, Модр, Голм и Неру...", completion = "Итак, скрижаль Гоаз восстановлена! Ты хорошо потрудился, Rainon. Будем надеяться, теперь я сумею расшифровать письмена титанов. Я уже разбираю новые слова! Э... тут написано: \"Древние боги... томятся в цепях под землей\". Похоже, грядут грандиозные перемены.", rewards = "Вы получите:\n\nШелковое оплечье Гамна"},
[301] = {title = "Отчет в Стальгорн", objective = "Отнесите отчет Сталекрута о ходе работ геологу Грозовой Вершине.", description = "Мы не можем выдать Сталекруту новую партию взрывчатого порошка без одобрения Стальгорна. Тебе придется отнести его отчет в штаб-квартиру Лиги Исследователей.\n\nВот он. Отдай его геологу Грозовой Вершине, да не забудь сразу отскочить в сторону. Грозовая Вершина – горячая голова. Его совсем не порадуют новости о медленном продвижении работ.\n\nГрозовую Вершину можно найти в Зале исследователей.", progress = "Представители моего клана терпеть не могут, когда нас беспокоят по пустякам, |3-6(Паладин). Надеюсь, твои вести стоят моего драгоценного внимания.", completion = "Проклятый Железняк! Я послал ему целый воз пороха еще неделю назад, но он не потрудился упомянуть об этом в отчете.\n\nТак... куда делся порох?!?", rewards = "Вы получите:\n\n"},
[302] = {title = "Порох для Сталекрута", objective = "Поговорите с Джерном Шлеморогом в Телсамаре.", description = "Если Сталекруту нужен порох, то, именем короля Магни, он его получит! Я уже отправил вестника в Телcамар с соответствующим приказом Джерну Шлеморогу. Он подготовит груз пороха и прочих припасов для Сталекрута.\n\nИ еще одно: я хочу, чтобы ты лично <проследил/проследила> за доставкой груза. Последний груз не добрался до адресата, поэтому держи ушки на макушке и смотри в оба.", progress = nil, completion = "Что? Грозовая Вершина хочет, чтобы ты лично проследил за доставкой груза к Железняку?\n\nЯ... думаю, это неплохая идея, но беда в том, что Хальдар и носильщики, Миран и Сайан, уже вышли. Вы чуть-чуть разминулись, я отправил их совсем недавно.", rewards = "Вы получите:\n\n"},
[303] = {title = "Война с Черным Железом", objective = "Мотли Каменщик в Дун Модре просит вас убить 15 дворфов, 5 проходчиков, 5 саботажников и 5 подрывников из клана Черного Железа.", description = "Война свирепствует повсюду: и в наших краях, и в чужих землях тоже. Пока наши могучие воины не щадят своих жизней, сражаясь во имя Альянса вдали от дома, на наших собственных землях бесчинствуют дворфы Черного Железа. Они разрушили один из мостов Тандола, потом пал и Дун Модр.\n\nТебе нужно собрать добровольцев и сдержать натиск врагов. Если сумеешь убить 10 дворфов Черного Железа, 5 проходчиков, 5 саботажников и 5 подрывников, тогда, может быть, мы и продержимся до подхода подкрепления.\n\nИ поторопись! У нас мало времени.", progress = "Рогго не смог связаться с резервным отрядом. Нам нужно внести смятение в ряды неприятеля, |3-6(Чернокнижник). Возвращайся в лагерь Черного Железа и исполни свой долг перед королем Магни!", completion = "Ты все сделал как надо, |3-6(Маг). Ты доказал свою доблесть и преданность королю Магни, за что тебе честь и хвала! Боевой дух Черного Железа подорван, и у нас появилась возможность выгнать их с нашей земли навсегда... если этот треклятый резерв все-таки подойдет...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[304] = {title = "Мрачное поручение", objective = "Убейте Балгараса Нечистого и принесите его ухо Гриму Длинной Косе в Дун Модр.", description = "Сколько наших полегло в битве при Дун Модре! Мой родной брат погиб, когда обрушился западный мост Тандола. Да, дворфы Черного Железа – те еще бестии. Чертово племя, шайка головорезов. Рогго сумел разузнать, что их предводитель в Болотине – некий чернокнижник по имени Балгарас Нечистый. Трус и мерзавец, каких поискать. Посылает на битву своих солдат, а сам прячется у себя в лагере на Зловещем холме, к юго-востоку отсюда.\n\nРазыщи этого подлого слизняка, убей его, принеси мне его ухо, и получишь награду, <класс>.", progress = "Ты нашел Балгараса, |3-6(Паладин)? Сколько раз мы пытались его разыскать, но все тщетно.", completion = "Ну, вот и все. Балгарас Нечистый мертв. И хотя смерть мерзавца не воскресит наших безвинно погибших братьев, тем, кто уцелел, будет гораздо спокойнее. Теперь, когда Балгараса нет, мы без труда справимся с Черным Железом. Хотя надо поторопиться. Истребить этих гадов под корень, пока у них не появился новый предводитель!\n\nТы сослужил нам добрую службу, |3-6(Паладин).", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЩит с золотым львомКольцо Спокойствия\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[305] = {title = "Пропавшие ученые", objective = "Таррел Камнепряд просит отыскать Меррин Камнепряд на раскопках.", description = "Ты, должно быть, тот самый разведчик, которого мне обещал Длинная Коса? Знаешь... как-то мне неспокойно на сердце.\n\nМоя благоверная, Меррин, работает в изыскательской группе на раскопе Вельгара. Писала мне каждую неделю, весь прошлый месяц. А теперь вдруг пропала. Уже две недели ни слуху, ни духу. Наверняка что-то случилось!\n\nДлинная Коса обещал, что, если я вскорости не получу никаких известий, он пришлет мне разведчика, который проверит, что стало с экспедицией. Как я понимаю, ты и есть этот разведчик, <имя>. Разыщи Меррин на раскопе к востоку отсюда!", progress = nil, completion = "Слава богам, ты нас нашел!", rewards = "Вы получите:\n\n"},
[306] = {title = "Пропавшие ученые", objective = "Отнесите Таррелу Камнепряду записку от Меррин.", description = "Это было ужасно! Мы обнаружили несколько очень редких артефактов. Пока мы занимались раскопками, нам все чаще и чаще начали попадаться огромные кости.\n\nВсе случилось внезапно. На нас напали крапчатые ящеры, их было значительно больше, чем нас. Почти все наши погибли в неравной схватке.\n\nОстались только мы трое. Ормер – он такой храбрый, настоящий герой, – спас меня и проспектора, он прикрывал нас, пока мы бежали в укрытие. А теперь мы в ловушке, и вся наша работа пропала!\n\nВот, отнеси эту записку моему дорогому Таррелу. Я ему все написала подробно. Он разберется.", progress = "Ты сумел разыскать Меррин? Она просила мне что-нибудь передать?", completion = "Какая ужасная новость! Это счастье, что уцелели хотя бы трое. Когда же закончится эта череда злоключений?! Когда же наконец подданные короля Магни забудут, что значит жить в постоянном страхе?!", rewards = "Вы получите:\n\n"},
[307] = {title = "Грязные лапы", objective = "Принесите из Рудника у Серебряного ручейка 4 ящика оборудования горному пехотинцу Грозовой Вершине.", description = "Рудник у Серебряного ручейка давно выработан. Лига рудокопов превратила его в склад, но теперь туда забрались кобольды и наложили свои грязные лапы на дворфийские инструменты!\n\nРано или поздно мы искореним этих паразитов, но Лига хочет спасти оборудование, пока в шахту не спустились воины и не разнесли все к демонам. Задача твоя не из простых – помощники тебе не помешают.\n\nОборудование находится в ящиках лиги Рудокопов, разбросанных по всему руднику.", progress = "Ну как, принес инструменты?", completion = "Там много кобольдов? Жду не дождусь приказа очистить от них рудник. Как подумаю, что они там хозяйничают, аж киплю весь!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольчуга железного СердцаОдеяние ХранителяЖелезный кулачный щит\n\nВы также получите:\n\n"},
[308] = {title = "Отвлечь Ярвена", objective = "Ох! Сколько же тут выпивки, а у меня строгий приказ ничего не трогать. Мне бы хоть попробовать нашего громового эля... Я от него лучше соображаю, честное слово!", description = nil, progress = "Ох! Сколько же тут выпивки, а у меня строгий приказ ничего не трогать. Мне бы хоть попробовать нашего громового эля... Я от него лучше соображаю, честное слово!", completion = "Это мне? Ты мой спаситель, Бронгард!", rewards = nil},
[309] = {title = "Охрана груза", objective = "Убедитесь, что Миран и его груз добрались до раскопа, и сообщите об этом геологу Сталекруту.", description = "Что ж, в путь, <имя>?\n\nДля начала надо доставить Железняку порох. Вес немалый, а здесь небезопасно – кто знает, что еще замышляют дворфы Черного Железа.\n\nС тобой мне будет куда спокойнее.", progress = "Где мой порох, Рен? Он мне все нужнее и нужнее.", completion = "О, слава Свету, вот мой порох. Но новости и верно тревожные. Только подумать, что находятся сторонники Черного Железа, способные снабдить их первосортными материалами для выполнения гнусных замыслов.\n\nНо над этим пусть поломает голову кто-нибудь другой и не сегодня. А я найду этому пороху отличное применение.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПояс старшиныГрязеступы\n\nВы также получите:\n\n"},
[310] = {title = "Злейшие соперники", objective = "Замените один бочонок громового эля бочонком жгучего пива Ячменоваров в подвале \"Громоварки\" в Караносе.", description = "Не могу не признать, эти Громовары делают славные напитки. Но они должны понять, что не только у них это хорошо получается! Может, ты поможешь преподать им урок...\n\nВот, возьми-ка этот бочонок жгучего пива Ячменоваров. Проберись в подвал \"Громоварки\" в Караносе и подмени один бочонок их громового эля. И посмотрим, не скажут ли их заказчики, что мое пиво лучше, чем Громоваров!\n\nЕсли бочонки охраняются, тебе придется отвлечь стражу...", progress = "Дата на бочонке показывает, что скоро его откроют.", completion = "Вы быстро ставите бочонок жгучего пива Ячменоваров, что дала вам Марлетта, среди бочек громового эля.", rewards = "Вы получите:\n\n"},
[311] = {title = "Возвращение к Марлетте", objective = "Принесите бочонок громового эля Марлетте Ячменовар в Поселок Пивоваров.", description = "Подсунув бочонок жгучего пива Марлетты в подвал в подвал \"Громоварки\" в Караносе, вы хватаете бочонок громового эля в качестве доказательства...", progress = "Ну что, подмена удалась?", completion = "Неплохо, Бронгард! Тебе, небось, нелегко было проскользнуть мимо их охраны?\n\nДа все равно – прими мою благодарность, и если когда-нибудь тебе понадобится крепкое пивко с огоньком, вспомни Ячменевцев!", rewards = "Вы получите:\n\n"},
[312] = {title = "Ограбление тайника Тундры Макгранна", objective = "Добудьте из пещеры Старого Ледоборода вяленое мясо из краденого ларя Тундры Макгранна.", description = "У меня был месячный запас вяленой солонины на зиму. Я запер его в ларь, чтобы медведи не добрались. Но пока я охотился на оленей, этот изверг, Старый Ледобород, уволок мой мясной ларь! Он не смог, однако, взломать ториевый замок. Но я же с голоду помру, если не верну свое мясо!\n\nТы вроде посильнее меня будешь. Может, сумеешь вернуть мой запас? Нога моя совсем плоха – мне не суметь быстро забраться в пещеру и утащить оттуда ларь.", progress = "Тебе удалось заглянуть в мой мясной ларь, Wrestlecake?", completion = "Какая же ты добрая душа, Wrestlecake! Благодаря твоей отваге я не подохну с голоду, когда начнутся зимние бури.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖелезнокованные наручиШерстяные полуперчатки\n\nВы также получите:\n\n"},
[313] = {title = "Серая берлога", objective = "Принесите 8 грив вендиго пилоту Камнекожцу.", description = "Управлять осадным орудием не каждому по плечу. Тут нужна железная хватка и стальные нервы! К счастью, у меня есть и то, и другое! А у тебя? Кишка-то не тонка? Хочешь покаказать мне, на что ты <способен/способна>?\n\nЛадно... Я хочу сделать свою машинку, Троллеукладчика, малость поудобнее. Не добудешь ли ты мне охапку грив вендиго из Серой берлоги, что к западу от Караноса? Эти гривы будут прекрасной прокладкой для кабины Троллеукладчика!", progress = "Эй, Бронгард! Ну что, побывал в Серой берлоге? Эти вендиго – злющие тварюги.", completion = "О, эти гривы мне очень пригодятся! Ты крепкий орешек, |3-6(Охотник), бьюсь об заклад, я о тебе еще услышу!", rewards = "Вы получите:\n\n"},
[314] = {title = "Защита стада", objective = "Убейте Вагаша и принесите его клык Рудре Янтарлен на Бараний выгон.", description = "Мы услышали шум среди ночи. Поутру не досчитались в отаре двух баранов. Эта подлая тварь Вагаш покушается на наше единственное добро! Поскольку большая часть армии короля Магни сражается в дальних краях за дело Альянса, некому приструнить этого Вагаша.\n\nМожет, тебе достанет отваги найти эту тварь и прикончить? Принеси мне его клык, и я тебя награжу. Вагаш рыщет как раз вон над тем выгоном, но предупреждаю: это смертельно опасная тварюга.", progress = "Вагаш по-прежнему режет наше стадо! Пожалуйста, помоги убить эту мерзкую тварь!", completion = "Отлично! Верон будет так рад этой доброй вести! Убить Вагаша – дело непростое. Сдается мне, настанет день – и ты будешь сражаться вместе с воинами короля Магни на передовой Альянса!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБрюки фермераМягкий кожаный мундирМолот Холодной долины\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[315] = {title = "Всем портерам портер", objective = "Принесите 6 порций звездолиста Регольду Ячменовару из Поселка Пивоваров.", description = "Я тут по делу, а дело мое – создать самый лучший портер! Я знаю, я смогу – пивоварение у меня в крови. Просто надо составить правильный рецепт...\n\nТролльское племя Мерзлогривов высоко в восточных холмах выращивает одну травку, звездолист называется. Они используют ее в странных ритуалах своего племени. Нам, дворфам, она не особо нужна, но у нее неповторимый вкус... И я хочу поэкспериментировать с ней при варении пива!\n\nДобудь мне немного звездолиста – его можно \"отнять\" у ясновидцев племени Мерзлогривов или стянуть из тролльских корзинок с травами.", progress = "Ты добыл звездолист? Я уже приготовился сварить партию портера и хочу попробовать бросить в сусло эту травку.", completion = "Великолепно! Прямо не терпится испробовать эту травку в одном из моих рецептов. Думаю, вот в этом она особенно хорошо пойдет...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлащ из козьего мехаСплетенные из плюща наручи\n\nВы также получите:\n\n"},
[317] = {title = "Заготовка продовольствия", objective = "Принесите 4 куска кабанины и 2 толстых медвежьих шкуры пилоту Брюхинсу в Поселок Сталежара.", description = "Я веду подготовку к выполнению боевого задания Осадной бригады. Дело будет долгим, и мне нужно укомплектовать мой паровик провизией на месяц. Так что пока ребята из Стальной Решетки работают с моим танком, не отправишься ли ты на охоту?\n\nМне нужен мех, чтобы сделать кровать, и кабанина для еды. Кабаны – на мясо, медведи – на мех... Этих животных можно найти в снежных полях к югу от Серого логова.", progress = "Подготовка идет отлично. Как охота?", completion = "Клянусь бородой Магни, ты славно поохотился! Спасибо тебе, Бронгард.", rewards = "Вы получите:\n\n"},
[318] = {title = "\"Вечное сияние\"", objective = "Возьмите бочонок \"Вечного сияния\" у Регольда Ячменовара в Поселке Пивоваров.", description = "Регольд Ячменовар не боится экспериментировать со своим варевом. Продукт эксперимента порой хорош на вкус, а порой нет, а иногда... самого крепкого дворфа уложит в стельку.\n\nРедгольд живет в Поселке Пивоваров, к западу от Караноса, и один из его напитков, \"Вечное сияние\", – как раз то, что мне надо. Он согреет меня в пути.\n\nИ... этот благословенный напиток горит так, что я могу залить его в топку паровика – и будет такой силовой импульс! Эта тактическая уловка помогала мне выбираться из многих переделок.", progress = nil, completion = "Толступузу нужно \"Вечное сияние\"? Ну, ладно.", rewards = "Вы получите:\n\n"},
[319] = {title = "Услуга за \"Вечное сияние\"", objective = "Убейте 6 медведей-ледолапов, 8 старых скальных вепрей и 8 снежных леопардов. Вернитесь к Регольду Ячменовару в Поселок Пивоваров.", description = "У меня есть бочонок \"Вечного сияния\", но... не <мог/могла> бы ты оказать мне услугу? Поселку Пивоваров не помешала бы помощь в борьбе против дикого зверья, что бродит вокруг. Иногда они подходят слишком близко...\n\nМы не боимся этих медведей, кошек и кабанов – ни один уважающий себя дворф не станет их бояться, – но если бы ты <взял/взяла> это зверье на себя, у нас было бы больше времени на ремесло и пивоварение.", progress = "Ну, расправился со зверьем?", completion = "Спасибо тебе, Бронгард. Славно будет заняться ремеслом без этого рыка да хрюканья за околицей!", rewards = "Вы получите:\n\n"},
[320] = {title = "Возвращение к Толстопузу", objective = "Отдайте бочонок \"Вечного сияния\" пилоту Толстопузу в Поселке Сталежара.", description = "Вот твоя бочка \"Вечного сияния\", <имя>. И спасибо тебе за охоту.", progress = "Ну, привез \"Вечное сияние\"?", completion = "Ух ты! Пожалуй, открою-ка я его прямо сейчас да попробую...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОстрый топорКорявый короткий посохЛагерный нож\n\nВы также получите:\n\n"},
[321] = {title = "Светлосталь", objective = "Найдите груз с затонувшего корабля \"Орлик\" в Болотине.", description = "Эти обломки погибших кораблей – останки Кул-Тирасской Третьей флотилии, сожженной и потопленной красными драконами во время последней Великой войны.\n\nФлотилия вышла из Лордерона, и с ней шел эльфийский боевой корабль – \"Орлик\". Он вез груз светлостали и присоединился к Третьей флотилии, ища покровительства и защиты. По иронии судьбы, он был потоплен теми же драконами, от которых пытался спастись...\n\nЛадно, краткий исторический экскурс будем считать завершенным. \"Орлик\" затонул к югу от Гавани Менетилов. Если найдешь светлосталь, принеси ее мне.", progress = nil, completion = "Сундук весь размок, его обшивка сломана. На стенках внутри и снаружи видны глубокие следы когтей... как будто в нем шарились мурлоки и унесли все сокровища.\n\nНо в самом дальнем углу завалялся один-единственный слиток светлостали. К несчастью, этого мало. Для того чтобы выковать достойное оружие, вам нужно больше.", rewards = "Вы получите:\n\nСлиток светлостали"},
[322] = {title = "Достойное оружие", objective = "Отнесите сундук со слитками светлостали Гриманду Элмору в Штормград.", description = "В Квартале Дворфов Штормграда есть оружейник, мастер по светлостали. Зовут его Гриманд Элмор.\n\nМеталл, который ты <нашел/нашла>, я упакую в сундук. Отнеси его Гриманду и расскажи ему свою историю. Я уверен, он не откажет тебе в помощи и изготовит оружие – оружие, которого убоится сам Морбент Скверн!", progress = "Ты пришел по какому-то делу, |3-6(Паладин)?", completion = "Да, занятный рассказ. И светлосталь! Я уже много лет не работал с этим материалом. Для меня это будет великая честь. А когда все закончится, ты непременно зайди ко мне и расскажи о своей битве с некромантом.\n\nНо не будем опережать события. Первым делом -оружие, которым ты сокрушишь Морбента Скверна...", rewards = "Вы получите:\n\n"},
[323] = {title = "Доказательство силы", objective = "Убейте 15 скелетов-налетчиков, 3 скелетов-лекарей и 3 скелетов-хранителей и вернитесь к Свену.", description = "Морбент Скверн – могущественный некромант и союзник темных всадников. Я не могу послать тебя на битву с ним, не испытав прежде твою силу.\n\nХрабрость твою я не подвергаю сомнению, но если ты в самом деле хочешь выступить против некроманта, сразись сначала с его приспешниками.", progress = "Не опускай оружия, Аномалиус. Главное – не отчаиваться. Отчаяние – первейшее оружие сил зла.", completion = "Без сомнения, в бою тебе нет равных, Эфром. Благодаря твоей решимости мы сможем положить конец деяниям Морбента Скверна!", rewards = "Вы получите:\n\n"},
[324] = {title = "Утерянные слитки", objective = "Соберите 5 слитков светлостали и вернитесь к Глорину Стальному Лбу в Болотину.", description = "Вы забрали слиток светлостали из отсыревшего сундука, но похоже, что остальные слитки растащили мурлоки. Найдите мурлоков-налетчиков у остова \"Орлика\" и отберите у них светлосталь.", progress = "Ты уже собрал достаточно светлостали?", completion = "Ага, вот и материал! Ну что, пора бы пустить его в дело, а?", rewards = "Вы получите:\n\n"},
[325] = {title = "Вооружен и особо опасен", objective = "Принесите Проклятье Морбента Свену в Сумеречный лес.", description = "Вот оружие против твоего врага. <имя>, иди и сражайся. Удачи тебе, возвращайся со славой!", progress = "Привет, Бронгард. Вроде недавно виделись, но с тех пор в тебе что-то решительно изменилось!", completion = "О, это именно то, что сразит Морбента Скверна! Отлично!\n\nГотовься. Скверн теперь – не жилец.", rewards = "Вы получите:\n\n"},
[328] = {title = "Спрятанный ключ", objective = "Откройте сейф букмекера Герода маленьким латунным ключом.", description = "Хотя в записях нет ни слова о рядовом Торсене, в кожаном переплете одной из книг Герода обнаруживается маленький латунный ключ.\n\nПовнимательнее изучив записи, вы находите упоминания \"надежного сейфа\". Этот сейф спрятан внутри Схрона, системы пещер позади поселка Курцена.\n\nЕсли найти его, быть может, удастся разрешить загадку обнаружения Торсена.", progress = "Сейф окован бронзой. Выглядит он очень прочным и очень тяжелым.", completion = "Открыв сейф, вы понимаете, что именно здесь Герод хранил самые ценные монеты и прочие вещи.", rewards = "Вы получите:\n\nБукмекерский скипетр"},
[329] = {title = "Шпион найден!", objective = "Отнесите грязную записку лейтенанту Дорену в Лагерь повстанцев.", description = "Среди ценностей в сундуке оказывается грязная, торопливо написанная записка. Это сведения о рядовом Торсене – где он патрулирует, с кем он говорит и как проводит время среди повстанцев. Записка подписана лишь одной буквой – М.\n\nЯсно одно, ее автор очень близко знаком с Торсеном, а это значит, что предатель – среди повстанцев.", progress = "Тебе удалось выяснить, кому была известна тайна Торсена? Среди нас есть предатель?", completion = "Спасибо, Эфром. Эта записка позволит нам вычислить и уничтожить предателя!", rewards = "Вы получите:\n\n"},
[330] = {title = "Расписание дежурств", objective = "Поговорите с капралом Сетманом.", description = "Принесенная тобой записка подписана просто \"-М\".. Не пойму, что это значит.\n\nНо... в записке также говорится, что этот человек дежурил вместе с Торсеном на прошлой неделе. Значит, он и есть предатель!\n\nИди к капралу Сетману. Он занимается составлением расписания и скажет, кто дежурил с Торсеном.", progress = nil, completion = "А, да, я могу узнать. Посмотрим... на прошлой неделе…\n\n... Да, с Торсеном дежурил рядовой Мерль. Всю прошлую неделю у них совпадало расписание дежурств.", rewards = "Вы получите:\n\n"},
[331] = {title = "Доклад Дорену", objective = "Поговорите с лейтенантом Дореном в Лагере повстанцев.", description = "Не просил ли лейтенант Дорен доложить ему о собранной информации по дежурствам?", progress = nil, completion = "Мне больно слышать, что нас предал Мерль. Он был храбрым солдатом, и мне казалось, что верным. С другой стороны, хорошо, что мы его нашли – с таким шпионом в наших рядах... мы недолго продержались бы против полковника Курцена.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСандалии джунглепроходцаНаплечье Ледяного металла\n\nВы также получите:\n\n"},
[332] = {title = "Реклама винного магазина", objective = "Отправляйтесь на винокурню Галлины и принесите Сюзетте Галлине талон на вино, чтобы получить бутылку вина бесплатно.", description = "Если тебя интересует вино, так лучшее вино в Штормграде продает семейство Галлина! Это недалеко – в Торговом квартале, неподалеку от городских каналов.\n\nВозьми этот талон, отнеси его моей сестре Сюзетте и получишь бутылку нашего знаменитого \"Пино нуар\". Не пожалеешь!", progress = "Приветствую и добро пожаловать, мсье! Не желаете ли отведать наших знаменитых вин?", completion = "Вы знакомы с Ренато? В таком случае – только для вас, мсье... Бутылка нашего особого \"Пино нуар\"! Такого вы не попробуете больше нигде во всем Азероте!", rewards = "Вы получите:\n\nБутылка \"Даларан нуар\""},
[333] = {title = "Харлан нуждается в помощи", objective = "Отправляйтесь в магазин одежды в районе каналов и принесите Реме Шнайдер заказ на ткани от Харлана Багли.", description = "Кажется, мы уже встречались. Наверное, насчет покупки брони и походной одежды. Кстати, ожидается суровая зима...\n\nА сегодня меня постигло настоящее огорчение: раскупили всю вязаную одежду. Мне нужна еще одна партия от нашего поставщика.\n\nЕсли ты отнесешь это послание Реме Шнайдер в ателье \"Канал\", моя признательность будет весьма велика.", progress = "Вы принесли весточку от мистера Бэгли?", completion = "Говорят, бизнес Харлана пошел в гору. Хорошие новости, хотя… хотелось бы мне знать, для чего вдруг понадобилось столько брони. Неужели где-то поблизости скоро случится война? Благородные господа ничего не говорят нам об этом!\n\nНу что ж, спасибо тебе за помощь. Вот твоя плата, и я надеюсь, что с заказом Харлана все хорошо.", rewards = "Вы получите:\n\n"},
[334] = {title = "Посылка для Турмана", objective = "Отправляйтесь в суконную лавку Ларсона в квартал магов Штормграда, и передайте Турману Шнайдеру его набор для шитья.", description = "Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы. Конечно, <класс> вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать…\n\nПрошу вас, <имя>! Отнесите моему сыну его швейные принадлежности! Лавка Ларсона – один из двух магазинов одежды в квартале магов, и стоит она прямо рядом с башней магов.", progress = "Вы хотите купить одежду?", completion = "Ох, блин покровный! А я так надеялся, что забытые инструменты помогут мне увильнуть от работы. А теперь все-таки придется помочь Ларсону с шитьем...\n\nНу, ладно: делу – время, потехе – час...", rewards = "Вы получите:\n\n"},
[335] = {title = "Благородный напиток", objective = "Принесите Зардету Черному Когтю слезу Тиллоа из Темнолесья и мускусный корень из Болотины.", description = "Лорд Вишлок наделал немалого переполоху среди Благородных домов. Он прознал о наших делах и теперь собирается добиться полного расследования. У меня есть план, согласно которому можно занять Вишлока другим делом, но понадобится твоя помощь.\n\nЕсть один цветочек под названием \"слеза Тиллоа\", он растет в садах Сталвана поблизости от Темнолесья. Еще мне понадобится мускусный корень, который можно найти только у подножия Каменной дамбы в Болотине.", progress = "Вишлок скоро наберет достаточно сил, чтобы доставить нам кучу неприятностей. Ты уже раздобыл слезу Тиллоа и мускусный корень?", completion = "Отлично! Это ровно то, что нужно!", rewards = "Вы получите:\n\n"},
[336] = {title = "Благородный напиток", objective = "Отнесите портер \"Черный коготь\" лорду Вишлоку в Зал просителей.", description = "У лорда Вишлока, как у всех людей, есть свои маленькие слабости. Например, он совсем не дурак выпить. Удивительное лицемерие! Старый ханжа целыми днями сражается с заведениями вроде нашего, а ночи напролет проводит наверху, да еще и не платит по счету. Ну, посмотрим, как ему понравится придуманный мной специально для него напиток: портер \"Черный Коготь\"! С ног сбивает – точно тебе говорю, <имя>!\n\nОтнеси ему это пойло и посмотри, придется ли оно лорду по вкусу. Старый хмырь наверняка шатается вокруг Зала просителей.", progress = "Ты что, не видишь, как я занят? Я готовлю речь! Я значу очень много для будущего этой державы!\n\nО, а что это у тебя? Похоже на освежающий напиток...", completion = "Спасибо за чудесный портер! Вот, возьми пару монет. А теперь иди прочь и не мешай мне дегустировать!", rewards = "Вы получите:\n\n"},
[337] = {title = "Старый учебник истории", objective = "Вернуть книгу \"История Штормграда\" в библиотеку Штормграда.", description = "Хотя обложка книги исцарапана и заляпана грязью, на корешке все еще можно прочитать заглавие – \"История Штормграда\". Открыв ее, вы видите на первой странице печать библиотеки Штормграда.\n\nПохоже, кто-то взял почитать эту книгу, да так и не вернул...", progress = "О-о-о! Что это у вас за книга? Можно взглянуть?", completion = "О небо! Этой книги не видели на полках со времен восстановления Штормграда. Конечно, ее придется реставрировать, она в плохом состоянии, но я с радостью помещу ее в нашу коллекцию редких книг.\n\nБлагодарю вас, господин. Прошу, примите плату за возвращение книги!", rewards = "Вы получите:\n\n"},
[338] = {title = "Зеленые холмы Тернистой долины", objective = "Соберите все недостающие страницы романа \"Зеленые холмы Тернистой долины\". Когда у вас на руках окажутся все четыре главы, верните их Барнилу.", description = "Господин Эрнестуэй так расстроится, когда узнает об этом!\n\nОн доверил мне гранки романа \"Зеленые холмы Тернистой долины\". Все шло хорошо, но по лагерю пронесся сильный порыв ветра и разметал страницы!\n\nБольшую часть мне удалось собрать, но многие страницы унесло в джунгли. Найди все страницы, и мы снова соберем четыре главы.\n\nЯ сам все разложу! Когда соберешь все четыре главы, возвращайся.", progress = "Тебе удалось собрать все главы, Эфром?", completion = "Ты избавил меня от многих хлопот, Эфром. Не знаю, как и благодарить тебя. Вскоре книги господина Эрнестуэя появятся в библиотеках по всему свету!", rewards = "Вы получите:\n\nСапоги джунглейНакладки из плотной кожиМощное лечебное зелье"},
[339] = {title = "Глава I", objective = "Принесите 1, 4, 6 и 8 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Кубку, чтобы собрать всю первую главу.", description = "Первая глава была необычайно интересной. Мастер Эрнестуэй предваряет рассказ знакомством со своими товарищами по охоте, в том числе и со мной! \n\nНо речь не об этом. Посмотрим, каких страниц не хватает. Кажется, страницы 1, 4, 6 и 8 все еще в джунглях!", progress = "Тебе не удалось найти страницы 1, 4, 6 и 8? Именно их не хватает, чтобы собрать воедино главу I.", completion = "Наконец-то! Глава I собрана!", rewards = "Вы получите:\n\nЗеленые холмы Тернистой долины: глава I"},
[340] = {title = "Глава II", objective = "Принесите 10, 11, 14 и 16 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Кубку, чтобы собрать всю вторую главу.", description = "Вторая глава представляла собой сплошные увлекательные рассказы про охоту на пантер и тигров. Так и хочется самому себе наподдать за то, что упустил страницы!\n\nМне удалось собрать почти все, кроме 10, 11, 14 и 16.", progress = "Нам по-прежнему не хватает 10, 11, 14 и 16 страниц второй главы, Эфром.", completion = "Вторая глава полностью собрана! Молодец!", rewards = "Вы получите:\n\nЗеленые холмы Тернистой долины: глава II"},
[341] = {title = "Глава III", objective = "Принесите 18, 20, 21 и 24 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю третью главу.", description = "Глава III была моей любимой. В ней рассказывается о том, как сэр Эрлгедин и леди Руак впервые подстрелили зверя из дворфийского ружья. А какое захватывающее у нее окончание! \n\nПохоже, нам недостает страниц 18, 20, 21 и 24. Они должны быть где-то неподалеку...", progress = "Ну как, где страницы 18, 20, 21 и 24? Стоит их найти, и третья глава будет собрана.", completion = "Уф! Отличная работа, Эфром. Теперь у нас есть вся глава III!", rewards = "Вы получите:\n\nЗеленые холмы Тернистой долины: глава III"},
[342] = {title = "Глава IV", objective = "Принесите 25, 26 и 27 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Кубку, чтобы собрать всю четвертую главу.", description = "А, Глава IV, захватывающий финал! И как она закончилась! \n\nНам не хватает всего лишь трех страниц этой  главы. А именно – 25, 26 и 27. Стоит найти их – и последняя глава готова.", progress = "Нам не хватает всего лишь трех страниц главы IV. Ты принес страницы 25, 26 и 27?", completion = "Великолепно! Глава IV готова!", rewards = "Вы получите:\n\nЗеленые холмы Тернистой долины: глава IV"},
[343] = {title = "Кстати, о стойкости духа", objective = "Отправляйтесь в Королевскую библиотеку Крепости Штормграда и поговорите с Милтоном Снопом. Он даст вам книгу по металлургии, которая интересует брата Кристофа.", description = "Я готовлю важную лекцию по стойкости духа и хотел бы освежить в памяти несколько мест из важной работы в области металлургии, \"Как закалялось железо\". Копия этой книги должна быть в Королевской библиотеке Крепости Штормграда. Не могли бы вы заказать ее для меня? Да осенит вас благодать Света!\n\nКоролевская библиотека очень велика, но старший библиотекарь, Милтон Сноп, знает каталог как свои пять пальцев. Поговорите с ним, он принесет для вас книгу.", progress = nil, completion = "Металлургия? Да, конечно, у нас много книг по данной отрасли знаний, и мы будем рады помочь брату Кристофу в подготовке лекции! Какая же книга его интересует?", rewards = "Вы получите:\n\n"},
[344] = {title = "Брат Пакстон", objective = "Поговорите с братом Пакстоном из Аббатства Североземья.", description = "\"Как закалялось железо\"? Конечно, я знаю такую книгу. Отличная книга, лет двадцать назад написанная дворфом-горняком Маргульфом Благгоном. Он много времени провел в горах Каз Модана, добывая руду. Отличный парень!\n\nНо о чем это я? Ах, да... \"Как закалялось железо\"! Боюсь, что книга отправилась в Аббатство Североземья. Хранитель тамошней библиотеки, брат Пакстон, хотел сделать с нее копию для своей коллекции.\n\nУж сколько тому месяцев минуло... Интересно, почему он ее задерживает.", progress = nil, completion = "Коллега Шиф потерял свою книгу? Мда, неловко вышло... Книга действительно у меня, но я не закончил ее переписывать, так что мне пока что нужен оригинал!", rewards = "Вы получите:\n\n"},
[345] = {title = "Запас чернил", objective = "Поговорите со штейгером Ослоу из Озер и расспросите его о ретбанской руде.", description = "Я как раз собирался закончить свою работу над копией \"Как закалялось железо\", но...\n\nЯ пользуюсь только чернилами своего собственного изготовления. Они не текут, не выцветают и очень быстро сохнут. Увы, высыхают они тоже слишком быстро! Последняя моя бутылка чернил никуда не годится, а я еще не успел закончить работу… и сделать еще чернил я не могу!\n\nДля изготовления чернил мне нужна ретбанская руда из Красногорья. Штейгер Ослоу из Озер – мой верный поставщик…", progress = nil, completion = "Чего тебе надо? Ты, может, не замечаешь, но мы здесь немного заняты – и укрепления строим, и Приозерье латаем после нападения орков. Если тебе сдалась ретбанская руда, добудь ее сам!", rewards = "Вы получите:\n\n"},
[346] = {title = "Возвращение к Кристофу", objective = "Вернитесь к брату Кристофу на Соборную площадь. Отдайте ему книгу \"Как закалялось железо\".", description = "Я закончил перепись и могу вернуть оригинал \"Как закалялось железо\". Спасибо за помощь, и передай, пожалуйста, Милтону мои извинения за долгую задержку.", progress = "Тебе удалось найти книгу?", completion = "Это она! Спасибо, Бронгард! Да пребудет над тобой вечный сияющий Свет!", rewards = "Вы получите:\n\nСапоги путешественника"},
[347] = {title = "Ретбанская руда", objective = "Добудьте 5 кусков ретбанской руды и принесите их брату Пакстону в библиотеку Североземского аббатства.", description = "Ретбанская руда получила свое название по имени первооткрывателя, Барта Ретбана. Выплавленный металл мягче железа, но руда имеет приятный темный цвет, и многие переписчики используют ее для изготовления чернил. Добыть руду можно в пещерах Ретбана к северу отсюда.\n\nК сожалению, постоянные нападения орков отвлекают нас от добычи руды, и запасы наши иссякли. Скажу тебе еще вот что... Красногорские гноллы недавно поселились в пещерах Ретбана, и их работяги как раз добывают там руду.\n\nТак что если тебе нужна руда... ты знаешь, как добыть ее.", progress = "Как там моя ретбанская руда?", completion = "О, благодарю! Я наконец-то смогу приготовить чернила и закончить свою работу над копией \"Как закалялось железо\"!\n\nБлагодарю тебя, Бронгард!", rewards = "Вы получите:\n\n"},
[348] = {title = "Лихорадка Тернистой долины", objective = "Найдите знахаря Унбагва и попросите его вызвать Мокка Дикаря. Принесите сердце Мокка Фину Горемыку.", description = "Плохо... Мне... Т-т-т-ак п-п-лохо.\n\nП-подцепил.. Лихорадку Тернистой Д-долины... смертельный вирус…\n\n...единственное лекарство... это... съесть сердце М-м-м-мок-ка Д-дикаря... неуловимой белой гориллы…\n\n... Ищи знахаря Унбагва в с-с-скрытой пещере на южном мыслу...\n\n...спеши... умираю... умру...", progress = "...мама?\n\n…так холодно…\n\n...отправляюсь в Круговерть Пустоты... Об-бними меня, мама...", completion = "...сила возвращается..\n\nГде я? В Пиратской бухте? Ох! Мне снился странный сон…\n\n...слабость не полностью прошла...", rewards = "Вы получите:\n\nПокрывало лекаря"},
[349] = {title = "Лихорадка Тернистой долины", objective = "temp text 02 - log", description = "temp text 02 - description", progress = "Знахарь Унбагва знать что есть Мокк Дикарь. Да, да!\n\nМоя говорить с духами, и он приходи.\n\nНо другие гориллы-звери тоже любят, когда духи говорят. Охрани знахаря Унбагва, и моя позвать его.\n\nЗнахарь Унбагва кое-что хотеть сначала. Твоя принеси 10 клыков гориллы, и моя начинать говорить с духи!", completion = "Знахарь Унбагва любить клык горилла! Моя будет говорить с духи. Пусть придет Мокк Дикарь.\n\nТвоя защищать знахарь Унбагва от других горилл-зверей, или никакой Мокк не быть!", rewards = nil},
[350] = {title = "Помощь старого друга", objective = "Поговорите с Иллингом Триасом в Штормграде.", description = "Марзон наверняка поддерживает контакт с Братством Справедливости, и у него есть выход на Лесковара...\n\nТеперь, когда ван Клиф и Тредд погибли, Лесковара будет нелегко посадить на скамью подсудимых, потому что без их показаний твое свидетельство ничего не будет значить; стоит также принять во внимание благородное происхождение и хорошие связи Лесковара. Ему, в сущности, наплевать на закон.\n\nТебе понадобится помощь. Я, увы, оказать ее не могу, но знаю того, кто может нам помочь. Найди Триаса в Торговом квартале.", progress = nil, completion = "Опять Шоу?! Совести у него нет!..\n\nБратство Справедливости, говорите? Да вы просто мешок с хорошими новостями! Скажите еще, что Смертокрыл воскрес и напал на город...\n\nНу, ладно, выкладывайте все по порядку. И не пропускайте ни единой детали. Я хочу знать все.", rewards = "Вы получите:\n\n"},
[351] = {title = "Найди КПХ-17/TN!", objective = "Отнесите аварийный маяк к автономному роботу Карлса.", description = "Вы находите какой-то странный яйцевидный металлический предмет. Повозившись с кнопками, вы пробуждаете яйцо, и оно превращается в гномский робот! Изнутри доносится голос.\n\n\"Меня зовут Карлс, и мой автономный робот потерялся! За его находку полагается награда! Прошу, отнесите этот маяк к роботу. Я уже вычислил координаты. Он сломался возле Зияющей бездны в Танарисе.\"", progress = "Похоже, вы нашли обломки... механического цыпленка? Из яйца снова доносится голос:\n\n\"Да, отличная работа! Это в самом деле мой автономный робот, хотя судя по сенсорам, он нуждается в хорошей починке перед перелетом в Пиратскую бухту. Для начала поместите маяк внутрь аппарата. А остальное он сделает сам!\"", completion = "Вы помещаете яйцо... аварийный маяк... внутрь цыпленка... робота.\n\nИзнутри робота доносится жужжание и скрип – он пытается встреть. Когда робот оживает, изнутри доносится голос Карлса:\n\n\"По крайней мере, КПХ-17/TN работает, но нуждается в серьезном ремонте! Он слишком тяжелый, чтобы унести отсюда... впрочем, у меня есть идея. Не хотите присмотреть за ним?\"", rewards = "Вы получите:\n\n"},
[353] = {title = "Посылка для Грозовой Вершины", objective = "Доставьте посылку горному пехотинцу Грозовой Вершине в Лок Модан.", description = "Грозовая Вершина – уважаемый клан дворфов, известный своими изысканными и утонченными вкусами. Неудивительно, что Грингер Грозовая Вершина, горный пехотинец Стальгорна, обратился ко мне, когда ему понадобилось оружие.\n\nЗаказ выполнен, но Грингер служит далеко отсюда, в Лок Модане. Если вы собираетесь на север, не возьметесь ли доставить груз?\n\nПо моим последним данным, горный пехотинец Грозовая Вершина остановился в северной сторожевой башне в Лок Модане.", progress = "Вы прибыли прямиком из Штормграда? Я слышал, что в человечьих землях обострилась ситуация с орками и грабителями. Там сейчас можно неплохо подзаработать – правда, |3-6(Воин)?", completion = "Ага! Так Гриманд все-таки закончил мой топор! Мне уже не терпится опробовать его на троггах и кобольдах!\n\nБлагодарю, Wrestlecake. Эта посылка проделала такой долгий путь... Вот, примите это в благодарность за ваши услуги.", rewards = "Вы получите:\n\n"},
[354] = {title = "Смерти в семье", objective = "Принесите останки Грегора, останки Ниссы и останки Турмана Колману Фартингу в Брилл.", description = "Семья Агамондов была самой преуспевающей в Тирисфальских лесах. Я работал на их мельницах... еще до чумы.\n\nКогда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону. А мы были дураками, но дураками преданными...\n\nИз-за гордыни Агамондов мы стали нежитью, а сами они служат Плети!\n\nСослужи Отрекшимся службу – убей Агамондов, ставших жертвами Чумы, и принеси мне их останки.", progress = "Ты принес останки Агамондов? Эти проклятые твари уничтожены?", completion = "Месть сладка, не правда ли? Ты заметил хоть какие-то признаки свободной воли в Агамондах, когда убивал их? Надеюсь, что да. Надеюсь, они почувствовали страх, прежде чем упокоились навсегда.\n\nКонечно, глупо на это надеяться, но тем не менее.", rewards = "Вы получите:\n\n"},
[355] = {title = "Разговор с Севреном", objective = "Поговорите с мировым судьей Севреном в Брилле.", description = "Ты <принес/принесла> мне останки Агамондов и <утолил/утолила> мою жажду мести. Но мельницы этой проклятой семейки все еще представляют собой угрозу не только для меня, но и для всех Отрекшихся.\n\nЯ рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично.", progress = nil, completion = "Коулман хорошо отзывался о тебе, Веланокс, и рассказал о твоем успешном походе на мельницы Агамондов.\n\nОтрекшимся еще раз нужна твоя помощь...", rewards = "Вы получите:\n\n"},
[356] = {title = "Патруль в арьергарде", objective = "Убейте 8 кровоточащих ужасов и 8 странствующих духов, а потом доложите о своих успехах Линнее в ее лагере.", description = "Защитники Бастиона, охраняющие Тирисфаль со стороны Чумных земель, постоянно начеку, но порой Плеть проскальзывает мимо них.\n\nНаш успех на Бастионе зависит от битвы на один фронт: мы не можем допустить атаки с тыла и уж конечно не можем лишить наших защитников линии поставки припасов.\n\nПомоги Бастиону. Отправляйся на восток и убей любого приспешника Плети, которого встретишь. Особое внимание обрати на ферму Балнира на востоке – там настоящее гнездо Плети.", progress = "Ну что, как прошел обход?", completion = "Очень хорошо. Благодаря вашим усилиям Плеть еще долго не осмелится сунуться сюда. Я отправлю лестный отзыв моему начальнику, исполнителю Зуганду.", rewards = "Вы получите:\n\n"},
[357] = {title = "Личность лича", objective = "Принесите книгу лича Бетору Ледострелу в Подгород.", description = "На острове посреди озера Ясноводного, что к северу отсюда, обитает лич. Сам он - свободный Отрекшийся, но считает, что мы, да и вся остальная нежить, до сих пор находимся под контролем Плети, и велел своим прислужникам атаковать любого, кто приблизится.\n\nНо раз он Отрекшийся, он понадобится Королеве. А если он еще и специалист в некромантии, то его умения нам... весьма пригодятся.\n\nЧтобы понять, кто он и что умеет, мне нужно заглянуть в его книгу заклинаний. Прокрадись в его лагерь, достань ее, и принеси мне.", progress = "Соулнце, ты принес книгу?", completion = "Прекрасно, Соулнце. Я изучу эту книгу и узнаю многое об этом личе. Ты сослужил королеве добрую службу.\n\n*Бетор открывает книгу и внимательно смотрит на ее сияющие страницы…*\n\nНевероятно! Добытая тобой книга принадлежит не кому иному, как Гюнтеру Чародею!\n\nГюнтер и при жизни был искусным некромантом. До нашествия Плети мы были добрыми товарищами и братьями по оружию. Судя по книге, после смерти он достиг еще большего могущества.\n\nЕго искусство могло бы нам очень пригодиться.", rewards = "Вы получите:\n\n"},
[358] = {title = "Грабители могил", objective = "Убивайте грабителей могил и полукровок из стаи Гнилошкуров.\n\nПринесите мировому судье Севрену 8 образцов бальзамирующей лимфы.", description = "Братские могилы к юго-востоку от фермы Гаррена были вырыты, чтобы справиться с... внушительным количеством смертей в Тирисфале после прихода Чумы.\n\nТела в этих могилах еще не превратились в нежить, но теперь Плеть подослала гноллов-Гнилошкуров, чтобы они воровали из могил трупы и пополняли ими ряды их армии. Это недопустимо!\n\nУ тебя будет два задания: перебить гноллов-Гнилошкуров возле братских могил и фермы Гаррена, а также отобрать у них бальзамирующую лимфу, поддерживающую в них жизнь.", progress = "Ты сделал то, о чем я просил? Убил этих псов и забрал у них лимфу?", completion = "Отличная работа, Топот! Если силы Плети решили, что могут направлять этих мертвецов на нас, то они жестоко ошиблись. Что же касается жидкости, которую ты собрал с рабов Гнилошкуров, ее изучат наши аптекари. Возможно, они откроют какой-то секрет, который поможет нам в войне.\n\nСловом, ты отлично справился. Но война продолжается, и у тебя будет еще много шансов проявить себя перед Отрекшимися.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nРукавицы холодной сталиСапоги из кожи зомби\n\nВы также получите:\n\n"},
[359] = {title = "Обязанности Отрекшихся", objective = "Поговорите со стражем смерти Линнеей.", description = "Мне нужен свежий отчет с восточной базы наших стражей смерти.\n\nЯ хочу знать, не проникли ли новые силы Плети за Бастион, в Тирисфаль. На границе с Чумными землями нужно постоянно смотреть в оба! Нельзя, чтобы Плеть устроила здесь еще одну крепость.\n\nИди по дороге на юг, а на развилке сверни на восток, к базе. Поговори со стражем смерти Линнеей, у нее есть вся нужная мне информация.", progress = nil, completion = "Севрену нужен отчет? Ну что же, защитники Бастиона сдерживают силы Плети, но часть из них все же проникает время от времени.\n\nПлеть видели к востоку от нашей базы, возле Усадьбы Балнира.", rewards = "Вы получите:\n\n"},
[360] = {title = "Возвращение к чиновнику", objective = "Вернитесь к мировому судье Севрену в Брилл.", description = "Теперь возвращайся к мировому судье Севрену с той информацией, что я дала вам. Он очень ждет ее, так что поспеши.\n\nА если встретишь по пути приспешников Плети – немедленно убей их! Нечего им шастать по нашим землям.", progress = nil, completion = "Неприятно слышать, что Плеть просачивается через Бастион. Король-лич и его слуги не собираются сдаваться.\n\nНо и мы не уступим. Мы не позволим ему захватить нас снова!", rewards = "Вы получите:\n\n"},
[361] = {title = "Недоставленное письмо", objective = "Найдите Иветту Фартинг и вручите ей письмо от Турмана Агамонда.", description = "Это письмо, написанное Турманом, старшим сыном Грегора Агамонда. Оно адресовано Иветте Фартинг, но, похоже, так до нее и не добралось...", progress = "Да?", completion = "О... мой бедный Тармен! Я ведь просила его уйти с этих мельниц со мной и моим отцом, но его преданность семье оказалась сильнее... Так я и знала! Я знала, что Брэнд желает ему зла! Будь прокляты эти Чума и Плеть!\n\n*Лицо Иветты смягчается.*\n\nНо стенания – удел слабых. Я Отрекшаяся, у меня есть свои цели, и любовь не входит в их число. Спасибо за то, что принесли мне письмо от некогда любимого человека, теперь я хотя бы знаю, что с ним сталось.\n\nНо та жизнь для меня окончена. Навсегда.", rewards = "Вы получите:\n\n"},
[362] = {title = "Мельницы с привидениями", objective = "Убейте Девлина Агамонда и принесите его останки Колману Фартингу в Брилл.", description = "Девлин Агамонд был младшим из двух сыновей в семье, и более непохожих братьев найти было невозможно. Турман был высоким и учтивым, а его младший брат – слабым и острым на язык.\n\nКогда мельницы Агамондов пали во время нашествия Чумы, я не удивился, услышав, что Девлин погиб одним из первых. На дороге, ведущей к мельницам Агамондов, до сих пор можно услышать его безумное бормотание.\n\nЯ собираю останки Агамондов, и для полной коллекции мне не хватает лишь бедного Девлина. Найди его, уничтожь и принеси мне его кости.", progress = "Ты нашел Девлина?", completion = "Спасибо. Кости Девлина станут отличным украшением для моего плаща.\n\nЕсли что-то может согреть мое холодное сердце, то это мысль о том, что Агамондов больше нет. Они предали меня и мою семью, когда пришла Чума – а теперь я клянусь, что растопчу их кости ногами!", rewards = "Вы получите:\n\n"},
[363] = {title = "Резкое пробуждение", objective = "Поговорите с жрецом Тьмы Сарвисом.", description = "Ты вовремя <пришел/пришла> в себя. Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи. \n\nМеня зовут Мордо, я смотритель склепа Могильника. А ты больше не <раб/рабыня> Короля-лича. \n\nПоговори с жрецом Тьмы Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать.", progress = nil, completion = "А, еще один живой мертвец! Должно быть, это настоящий шок – очнуться в склепе, в котором тебя встречает лишь холод... и Мордо. \n\nЯ все это читаю по твоему лицу. Позволь мне объяснить тебе наше... эээ... положение. \n\nНас освободила из-под контроля Короля-лича наша новая предводительница, леди Сильвана. Темная Госпожа руководит нами в войне против ненавистной армии Плети и цепляющихся за эту землю людей, преследующих нас, словно ищейки.", rewards = "Вы получите:\n\n"},
[364] = {title = "Безмозглые твари", objective = "Жрец Тьмы Сарвис хочет, чтобы вы убили 8 безмозглых зомби и 8 презренных зомби.", description = "Мы, Отрекшиеся, ведем войну против армии Плети, ведомой Королем-личом: против поднятых некромантией войск нежити, против злобных зверей севера и истерзанных призраков. \n\nСеверную часть деревни оккупировали безмозглые твари Плети, их нужно уничтожить. Сокруши их, не давая пощады, пусть они и были прежде нашими братьями и сестрами. Падшие – всего лишь рабы Короля-лича.", progress = "В этой новой жизни ты далеко не продвинешься, если не в состоянии убить даже самых слабеньких зомби, Малагрис. И не возвращайся, пока не сможешь доложить об успешном выполнении.", completion = "Жаль, что нельзя привлечь Плеть на нашу сторону, ее несметные полчища пришлись бы как нельзя кстати в предстоящих битвах. \n\nНо так как договориться с ними нельзя, нам остается лишь уничтожить их.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВолоконные перчаткиИзношенный плащ\n\nВы также получите:\n\n"},
[365] = {title = "Поля горя", objective = "Украдите 10 тыкв с западной фермы, к северу от Могильника. Потом отнесите эти тыквы аптекарю Юхану в Брилл.", description = "Кто это тут? <Новенький/Новенькая>, да еще и <класс>? Если хочешь проявить себя перед Темной Госпожой, придется следовать обычаям Отрекшихся.\n\nК западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв.\n\nКак наберешь десяток, отнеси их аптекарю Юхану в Брилл.", progress = "Страж смерти Симмер сказал мне, что ты принесешь очень нужные реагенты. Ты уже собрал десять тыкв, Сиамнео?", completion = "Ты хорошо справился с заданием, |3-6(Разбойник), и тем самым доказал, что достоин примкнуть к армии Темной Госпожи.", rewards = "Вы получите:\n\n"},
[366] = {title = "Книга Гюнтера", objective = "Верните Гюнтеру книгу заклинаний. Его можно найти на острове, в приюте Гюнтера.", description = "Давным-давно Гюнтер, я и Тул Коготь Ворона, который стал теперь некромантом Плети, дружили и состояли в Кирин-Торе – сообществе магов Даларана.\n\nМы с Гюнтером оба пали жертвами Чумы, но я полагал, что он так и сгинул в небытие или встал под знамена Короля-лича. Я рад, что он остался свободным.\n\nМы должны привлечь его на свою сторону. Я наложил на эту книгу заклинание, которое докажет ему, что я тоже свободен от Короля-лича. Надеюсь, что, убедившись в этом, он станет одним из нас.", progress = "Твои хозяева глупцы! Незачем было подсылать тебя. Я никогда не стану рабом Плети!", completion = "Моя книга?! Так это ты украл ее!\n\nНо... что это за новые чары на ней... Бетор? Он в Лордероне?\n\nЕсли он все еще \"жив\", то, может быть, ему тоже удалось вырваться из холодных объятий Короля-лича...", rewards = "Вы получите:\n\n"},
[367] = {title = "Новая чума", objective = "Принесите аптекарю Юхану 5 склянок крови псов тьмы.", description = "Леди Сильвана обратилась к Королевскому фармацевтическому обществу. Темная Госпожа считает, что при помощи наших знаний и новейшей магии мы сумеем найти ключ к свержению Артаса. Она хочет, чтобы мы вывели новую чуму – смертоноснее любой болезни Азерота, чтобы она уничтожила всю армию Артаса.\n\nВ своих изысканиях я обнаружил, что для этого потребуется кровь животных. Принеси мне 5 склянок крови пса тьмы, чтобы я мог провести эксперимент.", progress = "Ты уже добыл 5 склянок крови псов тьмы, Веланокс? Время не ждет!", completion = "Ты хорошо справился, Веланокс. Благодарю тебя за старание.", rewards = "Вы получите:\n\nСлабое зелье тролльей крови"},
[368] = {title = "Новая чума", objective = "Принесите аптекарю Юхану из Брилла 5 чешуек мурлоков из племени Злобного Плавника из Тирисфальских лесов.", description = "Пока ты <собирал/собирала> для меня образцы, я провел исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты. Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее.\n\nМне потребуется 5 чешуек мурлоков из племени Злобного Плавника. Их можно найти на берегу к северу или к западу.", progress = "Веланокс, тебе удалось собрать для меня 5 чешуек мурлоков из племени Злобного Плавника?", completion = "Отличная чешуя, Веланокс. Именно то, что мне нужно для микстуры.", rewards = "Вы получите:\n\nСонный порошок"},
[369] = {title = "Новая чума", objective = "Принесите аптекарю Юхану из Брилла 4 образца яда злобного ночного кругопряда.", description = "Пока вы были заняты сборами, я обнаружил в одном из своих фолиантов старинный текст, в котором сказано, что древняя чума унесла тысячи невинных жизней. Позже открыли, что возбудитель болезни сохранился благодаря яду ночных кругопрядов.\n\nПринесите мне немного яда злобных ночных кругопрядов, чтобы я мог закончить эксперимент. Хочу посмотреть, как среагирует ядовитый элемент с моим новым составом. Говорят, что этих пауков можно найти в Восточных Тирисфальских лесах.", progress = "Вы уже нашли яд злобного ночного кругопряда, Веланокс? Это последний компонент, необходимый мне для испытания моего нового состава.", completion = "Да, этот яд великолепно подойдет, Веланокс! Я уже добавил все остальное в мой состав и вскипятил его. Наконец-то я испытаю эту смертельно опасную смесь!", rewards = "Вы получите:\n\nКушак ученика"},
[370] = {title = "Война с Алым орденом", objective = "Убейте капитана Перрина, 3 ревнителей и 3 миссионеров из Алого ордена по просьбе палача Зуганда.", description = "В документах палача Аррена содержится информация, нужная нам для того, чтобы истребить всех людей в наших землях. Судя по этим данным, Алый орден прислал в заброшенную башню на юго-западе от Брилла капитана Перрина с людьми.\n\nУбей Перрина, трех ревнителей и трех миссионеров, а потом доложи мне о своем успехе.", progress = nil, completion = "Темная Госпожа, без сомнения, обрадуется смерти капитана Перрина. Вы хорошо исполнили свой долг, |3-6(Воин).", rewards = "Вы получите:\n\n"},
[371] = {title = "Война с Алым орденом", objective = "Убейте капитана Вакона и пятерых келейников из Алого ордена по заданию палача Зуганда.", description = "У нас до сих пор война, а Алый орден набирает силу. В отчете палача Аррена сказано, что его участники под предводительством капитана Вакона совершают набеги из разрушенной башни в юго-восточном Тирисфале, близ фермы Балнира.\n\nУбей Вакона и 5 келейников из Алого ордена – это должно нанести ордену сокрушающий удар!", progress = nil, completion = "Смерть капитана Вакона значительно замедлит продвижение Алого ордена по Тирисфалю. Но есть и другие угрозы.", rewards = "Вы получите:\n\n"},
[372] = {title = "Война с Алым орденом", objective = "По просьбе палача Зуганда убейте капитана Мелраша и двух его телохранителей.", description = "Алый орден совершает набеги из своей разрушенной башни в северном Тирисфале, за могилой Фаола. Согласно нашей информации, отвечает за эти набеги жестокий капитан Мелраш.\n\nЯ даю вам особенное и очень важное задание – убить Мелраша и двух его телохранителей во имя Темной Госпожи.", progress = nil, completion = "Вы отлично справились, |3-6(Маг). Чем больше на стороне Отрекшихся таких безжалостных бойцов, как вы, тем ближе наша победа и свержение Артаса. У меня хорошие предчувствия на ваш счет.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПарадный ножУдарная секира\n\nВы также получите:\n\n"},
[373] = {title = "Неотправленное письмо", objective = "Доставьте письмо городскому архитектору Баросу Алекстону в Штормград.", description = "Обыскав труп Эдвина ван Клифа, вы находите, среди прочих предметов, неотправленное письмо. Адрес таков: \"Баросу Алекстону, главному архитектору Штормграда, в Ратуша на Соборной Площади\".\n\nОно кажется написанным совсем недавно, и печать еще свежая…", progress = "Да? Я могу вам чем-нибудь помочь?", completion = "Эдвин ван Клиф, говорите? Я бы скорее ждал письма от своей покойной бабушки... Так это вы его убили? Извините, конечно, но я сильно удивлен. В молодые годы он был просто непревзойденным бойцом. Ну, дайте-ка взглянуть, что он мне там написал после стольких лет...\n\n*Барос рассматривает письмо.*\n\nЭх, Эдвин… годы не изменили тебя ни на каплю. Все такой же идеалист и романтик. Представляете, Эфром, ему было все равно, кому мстить. Месть попросту поглотила его. Но, кажется, я его понимаю…", rewards = "Вы получите:\n\n"},
[374] = {title = "Доказательство верности", objective = "Принесите 10 алых перстней стражу смерти Берджесу в Брилл.", description = "Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими.\n\nВариматрас, подручный Темной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стерто с лица земли. Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден.\n\nПомоги нам истребить их, <класс>. Принеси мне десять алых перстней в доказательство твоей верности Вариматрасу и Темной Госпоже.", progress = "Ты собрал 10 Алых перстней, |3-6(Воин)?", completion = "Вариматрас будет гордиться тобой. Ты отлично служишь своим лидерам, |3-6(Воин).", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНаручи из кожи зомбиПояс с застежкамиСетеобразные перчатки\n\nВы также получите:\n\n"},
[375] = {title = "Смертельный холод", objective = "Принесите 5 шкурок сумеречницы и грубую нить Гретхен Дедмар в Брилл.", description = "Так холодно... Чума Нежити расползается по моим венам, как клубок ледяных змей, и скоро я впаду в беспамятство. Но никакой злой рок не помешает мне нести службу нашей Темной Госпоже. Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны.\n\nТеперь мои руки дрожат от холода. Если ты принесешь мне 5 шкурок сумеречницы и грубую нить, я сошью себе одеяло. Помоги мне, <имя>, чтобы я могла и дальше служить нашему делу.", progress = "Ты нашел для меня шкурки сумеречницы и грубую нить, Веланокс?", completion = "Спасибо за заботу, Веланокс. Надеюсь, когда-нибудь слух о твоей храбрости дойдет и до Сильваны...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлащ АдептаШвейные перчатки\n\nВы также получите:\n\n"},
[376] = {title = "Проклятые", objective = "Ученице Элрет нужно 6 лап падальщика и 6 крыльев сумеречницы.", description = "В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тьмы Сарвису, какая может потребоваться. \n\nПохоже, и ты будешь <записан/записана> к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю. В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесешь мне немного, я найду для тебя какой-нибудь доспех. К югу отсюда волков-падальщиков и летучих мышей предостаточно.", progress = "Постарайся остаться невредимым, пока я не найду для тебя каких-нибудь доспехов.", completion = "Спасибо, Сиамнео. Держи этот доспех. \n\nНадеюсь, тебе он послужит лучше, чем тому бедолаге, что носил его последним…", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВолоконные наручиСтарый кожаный пояс\n\nВы также получите:\n\n"},
[377] = {title = "Преступление и наказание", objective = "Принесите советнику Миллстайпу руку Декстрена Варда.", description = "Мало того, что столица бросила Темнолесье на произвол судьбы, теперь Благородные дома плюнули на решение городского совета Темнолесья и заточили Декстрена Варда в тюрьму Штормграда – вместо того, чтобы обезглавить злодея по приказу лорда Чернодрева.\n\nВард продавал тела с кладбища Морбенту Скверну. Подобное преступление карается смертью. И все же Штормград объявил Варда своим пленником.\n\nУбей Варда в тюрьме Штормграда, принеси мне его руку, и я тебя вознагражу.", progress = "Пока выродки вроде Декстрена Варда живут на этом свете, в мире нет места справедливости. Возвращайся, когда исполнишь приговор лорда Чернодрева. Тем самым мы утешим семьи покойных и – более того – преподадим урок Благородным домам.", completion = "Так значит, Декстрен Вард наконец-то расплатился за свои преступления против человечества? Чем меньше швали, тем лучше, я так считаю. Хвала тебе, друг мой! Ты не только утешил семьи покойных, ты преподал наглядный урок продажным бюрократам из Благородных домов. Штормград должен прислушиваться к нашему голосу, или мы восстанем против его тирании.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги послаКольчужные поножи Темнолесья\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[378] = {title = "Успокоить гневливого", objective = "Принесите голову Кама Гневливого Мотли Каменщику в Дун Модр.", description = "Ты <доказал/доказала> свою преданность королю Магни, <класс>. И ты, так же как я, ненавидишь мерзавцев Черного Железа всем сердцем.\n\nЯ бы сам взялся за эту работу, но я дал слово чести и должен быть рядом с Длинной Косой. Рогго говорит, что у него есть доподлинные доказательства: это Кам Гневливый организовал нападение на мост Тандола. А это значит, что Кам виноват в гибели брата Длинной Косы.\n\nПока что Кама Гневливого держат в тюрьме Штормграда. Но такие, как он, не достойны того, чтобы жить. Убей его, <имя>. Ради Грима! Принеси мне его голову!", progress = "Я не могу допустить, чтобы идиотская бюрократия людей мешала правосудию дворфов, Борро. Существуют неопровержимые доказательства, что за диверсией на мосту Тандола стоял Кам Гневливый. Из-за этого предателя погибли наши собратья. Если людям достаточно и того, чтобы Гневливый сгнил в тюрьме, это их дело... но я не смогу спать спокойно, пока мерзавец не будет убит.", completion = "Стало быть, Кам Гневливый на собственной шкуре узнал, каково это – принять мучительную смерть? Хорошо. С этими негодяями из клана Черного Железа только так и надо. Отлично потрудился, |3-6(Охотник). Жертвы атаки на мост Тандола – это не первые и не последние невинные жертвы в нашем мире, объятом смятением и раздираемым войнами. Но теперь семьи погибших хотя бы утешатся тем, что предатель наказан. Брат Длиннокоса отомщен.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПояс ОпорыГоловокрушитель\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[379] = {title = "Утолить жажду", objective = "Найдите 5 бурдюков с водой Скитальцев Пустыни главному инженеру Чепухастеру в Прибамбасск.", description = "Тебе нужен источник силы. Могу помочь. Что я хочу взамен? Пить! Принеси мне пять бурдюков с водой Скитальцев Пустыни, и я дам тебе 4711-FTZ.\n\nЗнаешь, где взять эти меха? Попробуй попросить их у кочевников Скитальцев Пустыни! Потом расскажешь, что из этого вышло.", progress = "Ну как, кочевники поделились с тобой водой?", completion = "Отлично, вот тебе источник энергии. Честно говоря, он создан совсем не для исследовательского набора вроде этого, поэтому у тебя будет не так уж много времени, а потом все данные кирдыкнутся!\n\nКак только соберешь, все, что нужно, принеси эту штуковину мне, чтобы я отключил ее как надо. У тебя не больше двух часов на все про все.\n\nЕсли ты не успеешь, я, конечно, продам тебе еще один источник энергии. Ключевое слово – продам!", rewards = "Вы получите:\n\nИсточник питания, модель 4711-ФТЗ"},
[380] = {title = "Паучья низина", objective = "Палач Аррен хочет, чтобы вы убили 10 молодых ночных кругопрядов и 8 ночных кругопрядов.", description = "Одна из наших самых серьезных проблем – это добыча природных ресурсов, необходимых для выживания. Золота было очень мало даже во времена расцвета Альянса. \n\nК северо-западу отсюда есть золотой рудник, но он весь кишит пауками. Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари. У меня не так много рабочих рук для этой задачи, так что придется действовать постепенно. \n\nОтправляйся туда – может быть, ты сможешь чем-то помочь нам, <имя>.", progress = nil, completion = "Ну что же, для начала неплохо. Очистка всей территории займет несколько недель или даже месяцев. А после этого, нам придется пойти туда с факелами, чтобы сжечь паутину. \n\nТы отлично справился, Седативщик, я уверен, что подыщу для тебя еще какую-нибудь работенку.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВолоконный жилетРваная кольчужная рубахаПоножи из кожи зомби\n\nВы также получите:\n\n"},
[381] = {title = "Алый орден", objective = "Принесите палачу Аррену 12 алых поручей, сняв их с новообращенных и посвященных из Алого ордена.", description = "Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. \n\nМои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! \n\nБудь <осторожен/осторожна>, нечестивое рвение делает их опасными противниками.", progress = "Они просто идиоты... копающие себе могилы.", completion = "Если б только они послушались доводов разума, а, Сиамнео? Может быть, мы могли бы уговорить их все серьезно обсудить... Как же! \n\nИдиоты, ослепленные Светом...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКинжал ОтрекшихсяКувалда ОтрекшихсяКороткий меч ОтрекшихсяПолуторный меч Отрекшихся\n\nВы также получите:\n\nОсвежающая ключевая вода"},
[382] = {title = "Красный гонец", objective = "Убейте гонца Мевена Коргала в лагере Алого ордена, а потом передайте перехваченные известия палачу Аррену.", description = "В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из их монастыря к Могильнику. Судя по этим сообщениям, гонец несет важную информацию. Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить! \n\nА ты, <имя>, наиболее квалифицированная особа, которую я могу послать на это задание. Найди гонца и принеси мне информацию, которую тебе удастся найти.", progress = "Как продвигается выполнение задания, Сиамнео?", completion = "Хмм... Ну-ка, посмотрим, что ты там нашел... \n\n&lt;Аррен пробегает глазами документы, принесенные вами.&gt; \n\nНовости об их успехах в борьбе с нами... Ценности не имеют. Донесения разведки... Новые приказы... \"Продолжайте организацию лагеря около разрушенного города...\" Ничего такого, о чем мы не знали бы... А это еще что? Карта местонахождения некоторых полевых командиров и агентов! Это можно будет использовать.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПосох палачаКулачный щит стража смерти\n\nВы также получите:\n\n"},
[383] = {title = "Важные разведданные", objective = "Отнесите бумаги Алого ордена палачу Зуганду в Брилл.", description = "Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл. Обладая этой информацией, он сможет нанести решающий удар по Алому ордену. Ты сильно <помог/помогла> нам здесь, в Могильнике, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдется более серьезная работа. \n\nИди по дороге из Могильника на север. Вскоре после того, как дойдешь до Тирисфаля, наткнешься на перекресток. Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье \"Остывший очаг\".", progress = "Да? Что тебе нужно?", completion = "О, прекрасно! Ты отлично потрудился, добывая эту информацию, Гульгор. Хмм... Имена офицеров в Тирисфальских лесах…\n\nПредставь, какой удар мы можем нанести по боевому духу этих фанатиков, если убъем всех их лидеров одним стремительным ударом.", rewards = "Вы получите:\n\n"},
[384] = {title = "Кабаньи ребрышки в пиве", objective = "Принесите 6 ребер скального вепря и кружку \"Болтливого пива\" Рагнару Громовару в Караносе.", description = "Завсегдатаи моей таверны больше всего любят кабаньи ребрышки в пиве! Беда в том, что местный охотник, который снабжал меня кабанятиной, теперь завербован в королевскую армию, чтобы помочь Альянсу.\n\nМожет, ты мне поможешь? Если принесешь мне шесть ребер скального вепря и \"Болтливое пиво\" вон из той таверны, я открою тебе фамильный рецепт моих знаменитых ребрышек в пиве, не говоря уж о дармовой порции! Вся соль – в пиве!", progress = "Мне нужно шесть ребер скального вепря и кружка \"Болтливого пива\", Эфром.", completion = "Сварено пиво, разлито по кружкам,\nЭй, не деритесь, друзья и подружки!\nКаждому выделим по половине\nВкуснейшей порции ребрышек в пиве!", rewards = "Вы получите:\n\nКабаньи ребрышки в пивеРецепт: кабаньи ребрышки в пиве"},
[385] = {title = "Охота на кроколисков", objective = "Принесите Мареку Железносерду в Приют Странников 5 кусков мяса кроколиска и 6 шкур кроколиска.", description = "Многие охотники приезжают к озеру Лок Модан поохотиться на знаменитых кроков. Всегда находятся торговцы, скупающие кроколисковые шкуры на одежду или доспехи, а есть и любители кроколискового мяса.\n\nМы тоже зарабатываем на этом, но не слишком много, потому что кроколисков не так просто одолеть, и к тому же они поселились на островах посреди озера Лок. Но если хочешь отправиться на охоту, я не стану тебя отговаривать. Это действительно незабываемо.\n\nЯ и сам в свое время...", progress = "Я не рассказывал, как кроколиск едва не откусил мне руку? Жуткая тварь была, зубы – как лезвия. Но мне повезло... Я заткнул ему пасть ножом. Этот нож я до сих пор храню...", completion = "Ты отлично поохотился, Wrestlecake. За хорошую работу и платят хорошо!", rewards = "Вы получите:\n\nРецепт: стейк из кроколискаРваная накидка"},
[386] = {title = "Что происходит?", objective = "Принесите голову Таргорра Ужасного стражнику Бертону в Приозерье.", description = "Таргорр Ужасный служил под началом Гат'Илзогга старшим палачом и даже среди жестоких орков отличался особой кровожадностью. По его прихоти отважных бойцов Королевства подвергали страшным пыткам. Его взяли в плен и поместили в тюрьму Штормграда, приговорив к смертной казни. Но происходит что-то странное. Один из знатных людей запретил его казнить. Уверен, дело нечисто.\n\nПоложи конец Таргорру Ужасному, <имя>. Отправляйся в тюрьму и обезглавь его, пока мы не пали жертвой предательства.", progress = "Ты уже побывал в тюрьме? Боюсь, что если предательство позволяет так долго сохранять жизнь Таргорру Ужасному, оно же может дать ему свободу. Он приговорен к смертной казни, Эфром, и не должен стать пешкой в руках интриганов.", completion = "Наконец-то Таргорр Ужасный получил по заслугам. Я рад, что злодей угодил в лапы Смерти. Молодец, Эфром. Иной раз подлинное правосудие можно отыскать лишь за стенами залов суда, вдали от замутненного взора политиканов.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДлинный меч ЛюцинаУпрочненный посох из корня\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[387] = {title = "Подавление бунта", objective = "Тюремщик Телвотер просит вас убить в тюрьме 10 узников из Братства Справедливости, 8 каторжников из Братства Справедливости и 8 мятежников из Братства Справедливости.", description = "Бунт должен быть подавлен! И ты мне в этом поможешь. Если станет известно, что в тюрьме случился бунт, я потеряю работу. Это исключительная подлость! Самое важное сейчас – немедленно взять тюрьму под контроль. Ради безопасности Штормграда.\n\nНаказание за бунт в тюрьме – смертная казнь. Убей несколько этих отщепенцев, это даст урок всем остальным, и ситуация войдет в норму.", progress = "Тюрьма по-прежнему под контролем бунтовщиков! Этим крысам  из Братства Справедливости нужно показать, что это им даром не пройдет! Возвращайся и задай им жару!", completion = "Эфром, ты отлично проявил себя в тюрьме. Эта проблема куда сложнее, чем выглядит на первый взгляд, но ты отлично поработал, и я тебе очень благодарен.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[388] = {title = "Цвет крови", objective = "Принесите Никове Раскол 10 красных шерстяных бандан.", description = "Кровь моя стынет в жилах от ужасного горя... Мой внук Мак… он был такой чудесный мальчик. Всего 14 лет. Когда армия ушла на фронт, он счел, что должен защитить город. Он был охранником в тюрьмe, куда прибыла партия заключенных из Братства Справедливости. Мак наказал некоторых заключенных за порчу шерстяного одеяла, из которого они изготовили головные повязки, знаки их банды. За это он получил нож в спину.\n\nЯ хочу мести. Принесите мне 10 этих проклятых шерстяных бандан. Они цвета крови...", progress = "Я вижу, вы вернулись, |3-6(Охотник). Вы уже собрали 10 красных шерстяных бандан, принадлежавших этому отродью, Братству Справедливости?", completion = "Значит, из-за этих жалких тряпиц они убили моего Мака... Ужасная, нелепая смерть!..\n\nУвы, мне не дано изменить прошлое. Но я благодарна вам, Бронгард, за то что вам удалось воздать по заслугам убийцам моего внука.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[389] = {title = "Базиль Тредд", objective = "Поговорите с надзирателем Телвотером в тюрьме.", description = "ван Клиф и я были членами гильдии каменщиков. Это мы восстанавливали Штормград после войны.\n\nКогда мы закончили работу, вельможи отказались платить нам за нее. Руководителям гильдии предложили места на государственной службе, но ван Клиф отказался, потому что превыше всего ценил интересы гильдии. Он поднял мятеж и покинул город, поклявшись отомстить.\n\nЕго лейтенант, Базиль Тредд, много знает о планах своего командира. Базиль содержится в плену в тюрьме.", progress = nil, completion = "Чего, во имя Света, тебе надо? Не видишь, тут и без тебя проблем хватает?\n\nБазиль Тредд?! Какое тебе дело до этого мерзавца? Или ты – из его поганых кровавых соратничков? Не будь у меня тут все камеры заняты, я бы тебя точно засунул в одну из них!", rewards = "Вы получите:\n\n"},
[391] = {title = "Бунтовщики в тюрьме", objective = "Убейте Базиля Тредда и принесите его голову Телвотеру в тюрьму Штормграда.", description = "Скажу тебе сразу, <имя>: я тебе ни капли не доверяю. Но в нынешней ситуации это не особо важно.\n\nЧто от тебя требуется: иди и поговори с Треддом. Если ты и вправду на нашей стороне, убей его и принеси мне его голову. А если ты на их стороне и не вернешься вовремя, то будешь долго, долго гнить заживо…", progress = "Или ты мне принесешь голову Тредда, или я тебе, Эфром, твою собственную оторву, ясно?", completion = "Без Тредда бунтовщики станут куда более управляемыми. Посмотрим...\n\nДолжен сказать, я уже через полчаса решил, что больше тебя не увижу… но, надо признать, я в тебе ошибся.\n\nДумаю, тебе не удалось из него ничего вытянуть... А вот я знаю пару вещей насчет деятельности Тредда, которые тебя могут заинтересовать.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[392] = {title = "Таинственный посетитель", objective = "Отнесите запечатанное описание посетителя Тредда Баросу Алекстону в Штормград.", description = "Во время первого года заключения Тредда никто его не навещал. Мне казалось, что братство отказалось от него, поскольку он стал бесполезен.\n\nНо пару месяцев назад его стали постоянно навещать – раз, два в неделю. Посетитель был весьма странный. Такой тихий тип. У меня возникли подозрения, но все его документы были в полном порядке.\n\nСогласно документам, звали его Мелик; вот его описание. Не думаю, что он еще когда-нибудь придет к Тредду.", progress = "Да, Бронгард? Что вы нашли?", completion = "Мелик? Нет, это имя мне незнакомо и даже ни на какие мысли не наводит. Это может быть кто угодно! Бывший каменщик, один из членов Братства Справедливости... Хотя если он тесно связан с ними, как предполагает Телуотер, кто-нибудь может опознать его. Мне нужно подумать.", rewards = "Вы получите:\n\n"},
[393] = {title = "Тень прошлого", objective = "Отнесите запечатанное описание посетителя Тредда Матиасу Шоу в Штормград.", description = "Знаете ли, <имя>, мне так ничего и не пришло в голову. Зато я придумал, кто может нам помочь; если так и случится, я буду гордиться собой, но не стоит на это закладываться. Матиас Шоу из ШРУ – его можно найти в казармах Старого города. Шоу знает все уголки и закоулки этого города, всю его подноготную и тайные делишки.\n\nЕсли кто-то и знает, о ком речь, то только он.", progress = "Приветствую. По какому делу вы ко мне явились, |3-6(Паладин)?", completion = "Что это? Да, думаю, что знаю этого человека, но его зовут вовсе не Мелик. Наемные убийцы носят много масок, зовутся множеством имен и забывают их, как только они становятся не нужны. Этот человек также известен под именем Марзон; вероятно, это его очередной псевдоним.\n\nВ общем, он – наемный убийца, и я о нем довольно много знаю.\n\nМарзон сейчас работает на Грегора Лесковара – человека с репутацией, дурной даже для коррумпированного лорда Штормграда.", rewards = "Вы получите:\n\n"},
[394] = {title = "Голова чудовища", objective = "Поговорите с Матиасом Шоу в Штормграде.", description = "Найдите Шоу в Старом городе. Дайте ему знать, что с Лесковаром покончено, и о вашей причастности к заговору лордов против города. Я думаю, он будет рад, что среди горожан Штормграда есть еще герои.\n\nДумаю, он отправит вас на встречу с принцем или другим лордом. Не позволяйте им запудрить вам мозги, <имя>. Власть имущие думают, что могут творить в городе что угодно, но пока они не всесильны.", progress = nil, completion = "Значит, мертв? Ты скор на расправу, Эфром. Не хотел бы я стать твоим врагом.\n\n*Смеется и кладет руку вам на плечо.*\n\nНе прими за осуждение, Эфром. Я же глава наемных убийц, как я могу осуждать тебя за чистое убийство? По правде сказать, ты оказал людям Штормграда огромную услугу, и я благодарю тебя за это.", rewards = "Вы получите:\n\n"},
[395] = {title = "Гибель братства", objective = "Поговорите с Баросом Алекстоном в Штормграде.", description = "Ах, да... Пока тебя не было, приходил Алекстон, хотел с тобой поговорить. Должно быть, это касалось Братства Справедливости.\n\n<имя>, позволь дать тебе совет: на твоем месте я бы по первой просьбе рассказал обо всем произошедшем в подробностях. Но при этом упомяни, что Лесковара сразила именно твоя рука. Можешь мне верить – я на таких вещах собаку съел.\n\nА что касается Триаса... ну, не говори о нем. Никогда. Если сможешь.", progress = nil, completion = "Приятно тебя видеть снова, Эфром. Мне довелось услышать о недавней кончине лорда Грегора Лесковара.\n\nЗначит, твоя миссия оказалась успешной. Я щедро награжу тебя за спасение и меня, и многих прочих от мести ван Клифа.", rewards = "Вы получите:\n\n"},
[396] = {title = "Аудиенция у короля", objective = "Доставьте доклад Бароса Алекстона из Братства Справедливости королю Вариану Ринну в Крепость Штормграда.", description = "Я готовлю донесение для короля. Надеюсь, ты сумеешь преподнести его величеству все в лучшем виде. Не переживай так, король обязательно оценит твое благородное служение народу Штормграда и достойно наградит тебя.\n\nСрок твоей аудиенции близок, так что поторопись, чтобы не опоздать в Крепость Штормграда.", progress = "Бронгард, верно? Барос Алекстон уже предупредил о вашем прибытии. Должен признаться, мне будет интересно вас выслушать.", completion = "Бронгард, я щедро награжу вас за службу Штормграду. Если ван Клиф преуспел в своих махинациях, то у нас еще будет немало трудностей. Этого мы должны избежать.\n\nВозьмите этот жетон в знак королевской благосклонности, |3-6(Охотник). Сожалею, что король не смог вручить его вам лично, но он сейчас занят на дипломатических переговорах и еще не освободился.", rewards = "Вы получите:\n\nПечать Ринна"},
[397] = {title = "За достойную службу", objective = "Поговорите с Згги, слугой Зардета Черного Когтя, чтобы получить награду.", description = "Я слышал, что Лорд Вишлок в восторге от напитка.\n\n<имя>, ты нам здорово <помог/помогла>. Теперь чернокнижники Штормграда смогут заниматься своим делом без помех. За свою службу ты получишь достойный подарок. Поговори с Згги, моим слугой.", progress = nil, completion = "Хозяин дал подарок для Блок. Згги хотел бы оставить его себе, но Згги знает, что будет, если предать хозяина.", rewards = "Вы получите:\n\nВолшебная шляпа Ужаса"},
[398] = {title = "Разыскивается: Червеглаз", objective = "Убейте Червеглаза и отнесите палачу Зуганду в Брилл его лапу.", description = "Разыскивается: Червеглаз!\n\nУжасное даже по меркам гноллов чудовище – Червеглаз – приговорен к смерти за его преступления против Отрекшихся. Этот гнусный злодей воровал трупы для армии Короля-лича. Червеглаза видели близ Фермы Гаррена, к северу от Брилла.\n\nГород Брилл предлагает награду всякому, кто сумеет прикончить негодяя и предъявить палачу Зуганду его лапу.\n\nМилосердие – удел слабых.", progress = "Да?", completion = "Наконец-то Червеглаз получил по заслугам. Пусть твой поступок запомнится всем, кто захочет навредить нашему народу! Благодарю тебя от имени всего города Брилла, Урога.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛатунные чешуйчатые штаныЖилет Румпеля\n\nВы также получите:\n\n"},
[399] = {title = "Скромные дары прошлого", objective = "Обыщите дом Бароса Алекстона в Западном Крае, найдите компас и вернитесь на Соборную площадь Штормграда.", description = "С тех пор как я мальчишкой работал на ферме в Западном Крае, прошла целая вечность. Говорят, нельзя вернуться в прошлое – и это верно. Дважды верно, если говорить обо мне – ведь мой родной дом был разграблен ворами и сожжен.\n\nЯ спросил у отца о судьбе некоторых моих вещей, например, о моем первом компасе. Отец не мог его захватить при бегстве, но сказал, что компас спрятан где-то на ферме.\n\nУсадьба Алекстона расположена к западу от Сторожевого холма. Может быть, ты найдешь мой компас?", progress = "Бронгард! Вы нашли компас?", completion = "Благодарю вас, Бронгард! Совершенно бесполезная вещь, не считая воспоминаний... Нет слов, как я благодарен за то, что принесли мне этот предмет; вам, конечно, трудно понять цену памяти о Западном Крае. Возьмите это в знак моей признательности...", rewards = "Вы получите:\n\n"},
[400] = {title = "Инструменты для Сталежара", objective = "Доставьте инструменты Белдину Сталежару.", description = "Белдин Сталежар владеет местной ремонтной мастерской, и он лучший техник по осадным машинам! Но своего инструмента он не жалеет. Могу побиться об заклад, его тангенциальные вращатели выходят из строя быстрее, чем мы успеваем поставлять ему новые!\n\nМы только что выполнили его очередной заказ. Если ты его доставишь, я уверен, мастер заплатит тебе за труды.\n\nТы сможешь найти Сталежара к северо-востоку от Караноса. Кстати, это излюбленное местечко ветеранов-водителей осадных машин, так что держи ухо востро, когда там будешь, – вдруг какая работенка подвернется.", progress = "Хм? Мал ты еще для водителя осадной машины. Ну да ладно... Тебе что-нибудь починить надо?\n\nВозьми номерок и жди своей очереди. Я сейчас работаю над парой машин, и времени на еще одну работу у меня не будет как минимум пару дней.\n\nИли ты тут по другому вопросу?", completion = "У тебя мои инструменты? Отлично, парень, отлично! Я только что сломал последний зубчатый храповик, и мне нужен другой, чтобы закончить ремонт осадной машины для пилота Камнекожца. Славно, что ты принес мне эти инструменты, Эфром.\n\nВот, возьми эти деньги; спасибо!", rewards = "Вы получите:\n\n"},
[401] = {title = "Ожидание перевода", objective = "Подождите немного и снова поговорите с Широй Фон-Инди.", description = "Я почти закончил работу над переводом записки. Она будет готова через несколько минут.", progress = nil, completion = "Ну вот. Готово…\n\n*Вокруг воцаряется душная тишина, словно на лес опустился темный тяжелый полог...*", rewards = "Вы получите:\n\n"},
[402] = {title = "Шира занят", objective = "Зайдите к Шире и выясните, занят ли он.Прости, но сейчас трудный момент в жизни нашего города. У меня есть другие дела. Может быть позже, если мы все выживем, я закончу перевод.", description = "Прости, но сейчас трудный момент в жизни нашего города. У меня есть другие дела. Может быть позже, если мы все выживем, я закончу перевод.", progress = nil, completion = nil, rewards = nil},
[403] = {title = "Охраняемый бочонок громопойла", objective = "Этот бочонок эля охраняет Ярвен Громовар. Пока он в подвале, до бочек не добраться.", description = nil, progress = nil, completion = nil, rewards = nil},
[404] = {title = "Грязная работа", objective = "Принесите 7 гнилых когтей стражу смерти Диллинжеру в Брилл.", description = "Плеть проникла в Тирисфальские леса и заполонила всю местность к западу от Брилла, возле старого моста.\n\nОтправляйся туда и загони этих гниющих мертвецов обратно в землю, откуда они вылезли. Разбросай их кости и принеси их гнилые когти – за них ты получишь награду от стражей смерти.", progress = "Ты выполнил задание, которое я тебе дал? Принес мне гнилые когти?", completion = "Отличная работа. Жаль, я не видел, как ты расправляешься с этими гнусными тварями!", rewards = "Вы получите:\n\n"},
[405] = {title = "Блудный лич", objective = "Отнесите приказы Севрена Бетору Ледострелу в Подгород.", description = "Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью. Ты, <имя>, как раз подходишь для этого.\n\nОтнеси эти приказы Бетору, а он расскажет, в чем состоит твоя миссия. Деталей я не знаю, могу сказать лишь то, что речь пойдет о вербовке заблудшего лича. Это очень опасное дело.\n\nПриготовься как следует, <класс>. Не подведи нас.\n\nБетора можно найти в квартале Магов Подгорода.", progress = "Здравствуй. Либо ты не знаешь, кто я, либо у тебя ко мне очень срочное дело.\n\nПотому что иначе ты не посмел бы меня беспокоить…", completion = "А, так тебя прислал мировой судья Севрен. Тогда да, дело у нас с тобой очень важное.\n\nУверен, Севрен выбрал того, кто справится с моим заданием, но… ладно, посмотрим.", rewards = "Вы получите:\n\n"},
[407] = {title = "Поля горя", objective = "Отнесите отравленную тыкву пленному ревнителю из Алого ордена, которого держат в погребе таверны \"Петля Висельника\".", description = "Безвредные тыковки, да? Это только так кажется. Если мы хотим победить силы Артаса на севере и нашествие людей на юге, нам нужно извлечь всю пользу из нашего дара нежития.\n\nЧуть-чуть смекалки, и простая тыква превратится в шпиона Темной Госпожи. С помощью моей последней формулы эта тыква станет лакомым блюдом.\n\nВот недавно мы поймали еще одного ревнителя из Алого ордена, сейчас он сидит в погребе таверны \"Петля Висельника\". Иди, отнеси ему эту тыкву.", progress = "Прочь, нечестивое созданье! Свет, защити меня! Алый орден избавит Азерот от таких...\n\nОй... Это что, еда для меня? Я умираю с голода...", completion = "Благословенный Свет! Наконец-то еда! Сладенькая тыквочка...", rewards = "Вы получите:\n\n"},
[408] = {title = "Семейный склеп", objective = "Убейте 8 стенающих предков и 8 гниющих предков.\n\nУбейте капитана Даргола и принесите его череп мировому судье Севрену в Брилл.", description = "Мельницы Агамондов превратились в крепость Плети. Самая важная точка – это семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом. С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас.\n\nТы не <должен/должна> допустить этого. Отправляйся в склеп Агамондов и убей их неупокоенных предков.\n\nА заодно принеси мне череп капитана Даргола.", progress = "Мы не можем позволить себе прохлаждаться, Веланокс. С каждым часом кольцо Плети вокруг Тирисфальских лесов сжимается все сильнее.", completion = "Твои действия нанесли Плети ощутимый удар! И твоя победа не будет забыта ни Отрекшимися, ни врагами.\n\nПродолжай бороться вместе с нами, Веланокс, и когда-нибудь мы изгоним Короля-лича из Азерота!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПосох ТемнолесьяКостолом\n\nВы также получите:\n\n"},
[409] = {title = "Доказательство преданности", objective = "Возьмите манящую свечу.\n\nВызовите Лилит Нефару и убейте ее.\n\nВернитесь на остров к Гюнтеру.", description = "Ты говоришь, что <неподвластен/неподвластна> воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают. Но прежде чем я поверю тебе,ты <должен/должна> доказать то, что являешься врагом Плети.\n\nНа южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара.\n\nВозьми из этого ящика манящую свечу, зажги ее на алтаре, и Лилит пробудится. Убей ее, и я поверю, что ты – враг Короля-лича.", progress = nil, completion = "Невероятно! Ты убил Лилит Нефару и тем самым доказал, что являешься врагом Плети!\n\nЯ думал, что я – единственный из нежити, обладающий свободой воли, но теперь вижу, что есть и другие, кто не поддался влиянию Короля-лича.", rewards = "Вы получите:\n\n"},
[410] = {title = "Спящая тень", objective = "Старый, побитый, окровавленный стол.", description = nil, progress = "Старый, побитый, окровавленный стол.", completion = "Вы ставите на стол Манящую свечу и зажигаете ее...", rewards = nil},
[411] = {title = "Возвращение блудного лича", objective = "Отнесите самоцвет Пустоты Бетору Ледострелу в Подгород.", description = "Отнеси этот самоцвет Пустоты моему старому товарищу Бетору. С его помощью мы сможем общаться, а мне очень многое надо ему сказать.", progress = "Ты вернул книгу Гюнтеру? Что он сказал?", completion = "Ты убедил его присоединиться к нам! Это огромная радость для всех Отрекшихся, Веланокс. Я доложу об этом Темной Госпоже.", rewards = "Вы получите:\n\nКостяной кулачный щит"},
[412] = {title = "Операция \"Перенаправление\"", objective = "Принесите Раззлу Шустрецу в Караносе 8 зубцов рестабилизации и 8 гиромеханических шестерней.", description = "При дальнейшем анализе гномреганской ситуации оказалось, что нам не только не удалось извести троггов, но мы случайно превратили большую часть представителей нашей расы в ужасающих, безмозглых, злобных лепрогномов!\n\nМы с Оззи намерены направить в обратную сторону ужасный эффект лепры при помощи нашего последнего изобретения – перенаправлятора. Эта машина почти закончена, но нам чрезвычайно нужны зубцы рестабилизации и гиромеханические шестерни. Добудь их у лепрогномов, которые обитают около Гномрегана, и принеси нам!", progress = "Перенаправлятор будет закончен и введен в эксплуатацию, как только у нас будет достаточно зубцов рестабилизации и гиромеханических шестерней.", completion = "Эти гиромеханические шестерни и зубцы рестабилизации прекрасно подходят к чертежу Оззи для устройства Перенаправления. Как только я залью гидросмазку во внутренние клапаны сгорания, подкручу кривохраповик и повышу вязкость электрогуммигеля, раса гномов будет возрождена.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки водителяЗаляпанный маслом плащ\n\nВы также получите:\n\n"},
[413] = {title = "\"Мерцающий портер\"", objective = "Отнесите бочонок \"Мерцающего портера\" горному пехотинцу Ячменовару.", description = "Хотелось бы мне, чтобы мой братец Велларт попробовал свежего \"Мерцающего портера\". Он горный пехотинец, их расквартировали в южной сторожевой башне, одной из двух на границе с озером Лок Модан.\n\nМожет, он и не такой пивовар, как остальные Ячменовары, но свое пиво он любит, и я знаю, что это тоже ему понравится.\n\nНе отнесешь ему вот этот бочонок \"Мерцающего портера\"?", progress = "Привет, |3-6(Паладин)! Что за дело привело тебя сюда?\n\nНадеюсь, что-нибудь стоящее. Я уже много дней не дрался хорошенько, да и этот бочонок эля уже почти пуст...", completion = "*Горный пехотинец Ячменовар пробует \"Мерцающий портер\"...*\n\nОх-х. Аж искры из глаз! Кажется, я даже в темноте видеть могу!", rewards = "Вы получите:\n\n"},
[414] = {title = "Портер для Кэдрелла", objective = "Отнести бочонок \"Мерцающего портера\" горному пехотинцу Кэдреллу.", description = "Я бы и еще отхлебнул \"Мерцающего портера\" с пивоварни моего братца – забористое же пойло! Но я хочу, чтобы мой приятель-пехотинец попробовал его. Зовут парня Кэдрелл, и он обычно патрулирует дорогу через Телcамар в озере Лок Модан.\n\nЧтобы добраться до Телcамара, иди на юго-восток через туннель, затем на развилке возьми на северо-восток. И по той дороге иди прямо до Телcамара.\n\nОтдай горному пехотинцу Кэдреллу этот бочонок \"Мерцающего портера\", и посмотрим, что он скажет!", progress = "Привет, |3-6(Паладин), добро пожаловать в Телcамар!", completion = "Ну-с, попробуем...\n\nКлянусь бородой Магни! Аж голова кругом пошла! И в теле легкость необыкновенная.\n\nСейчас полечу, как птичка!", rewards = "Вы получите:\n\n"},
[415] = {title = "Новое пиво Регольда", objective = "Поговорите с Регольдом Ячменоваром.", description = "Регольд Ячменовар, что живет в Поселке Пивоваров, спрашивал про тебя.\n\nОн хочет поговорить с тобой про свое новое пиво... Сказал вроде, что ты ему <помог/помогла>. Можешь самолично вернуться в Поселок Пивоваров и спросить, что ему надо.\n\nМожет, тебя дармовая выпивка ждет...", progress = nil, completion = "Рейнарт! Помнишь тот звездолист, что ты принес мне? Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно!\n\nВот, попробуй и скажи, как пошло...", rewards = "Вы получите:\n\nКружка \"Мерцающего портера\""},
[416] = {title = "Ловля крыс", objective = "Принесите 12 ушей кобольдов-туннельщиков горному пехотинцу Кэдреллу в Телсамар.", description = "К западу отсюда началось настоящее нашествие. Эти крысы, кобольды-туннельщики, обосновались в предгорьях, устроили там свои логовища и оскверняют нашу прекрасную землю!\n\nИх необходимо истребить. Перебей их как можно больше, принеси в доказательство уши и получишь награду.\n\nКобольды-туннельщиков поселились к западу от Телcамара вдоль горных склонов.", progress = "Приветствую тебя, Wrestlecake! Как идет ловля крыс?", completion = "Фу! Когда я просил принести уши, я не подозревал, что они так дурно пахнут!\n\nПрими награду, Wrestlecake. Молодчина.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОбгоревшие наручи из шкурыСапоги кавалериста\n\nВы также получите:\n\n"},
[417] = {title = "Месть пилота", objective = "Убейте Паршивого Когтя.\n\nПринесите его коготь и журнал Хилдельва пилоту Большеногу.", description = "Хилдельв пишет в своем журнале, что подвергся нападению Паршивого Когтя, \"огромного медведя-ледолапа\". Он отогнал тварь, но та успела страшно изранить его.\n\nСудя по состоянию трупа Хилдельва, Паршивый Коготь, видимо, вернулся и добил его.\n\nВ журнале Хилдельв записал свое последнее пожелание:\n\n\"Отомстить Паршивому Когтю.\"", progress = "Привет, Wrestlecake. Есть у тебя весточка от моего друга Хилдельва?", completion = "Злая весть. Хилдельв был хорошим другом. Жаль, что не довелось мне с тобой пойти на этого Паршивого Когтя!\n\nСпасибо тебе, Wrestlecake. Пилоты Осадной бригады Стальгорна тебя не забудут.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКинжал ремесленникаКомпактный молот\n\nВы также получите:\n\n"},
[418] = {title = "Телсамарские кровяные колбаски", objective = "Принесите Видре Жаркий Очаг в Телcамар 3 куска медвежатины, 3 связки кишок кабана и 3 порции паучьей лимфы.", description = "Едоки в Телcамаре не переводятся – еще бы, детей полным-полно, после трудового дня работники ужинать хотят. Мы славимся кровяными колбасками... Но ты ведь их еще не <пробовал/пробовала>? Нет? Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение.\n\nМне понадобится медвежатина, кишки кабана на оболочки и паучья лимфа для остроты. Добудь все это, а уж Видра сготовит все в лучшем виде!", progress = "Я давно собираюсь начать готовить; где же все компоненты?", completion = "Поверь, со стороны готовка выглядит куда сложнее, чем на деле, но...\n\nХоть я и не встречала никого, кому бы захотелось научиться делать колбаски, но на всякий случай рецептик я тебе все же дам. Бери! Ешь, пока рот свеж!", rewards = "Вы получите:\n\nКровяная колбасаРецепт: кровяная колбаса"},
[419] = {title = "Пропавший пилот", objective = "Найдите пилота Хилдельва.", description = "Мой друг и напарник, пилот Осадного орудия Мори Хилдельв, пропал в этих холмах. Мы искали там редкую руду, необходимую для высококачественного пороха, и во время поисков мы загнали его танк на крутой холм и он сломался!\n\nХилдельв, по-прежнему уверенный, что руда в тех горах есть, оставил меня охранять наши танки, а сам пошел дальше пешком.\n\nПрошло уже несколько дней, а я слышал ночью какой-то звериный вой в холмах. Мори – парень-кремень, но мне тревожно.\n\nПрошу тебя, <имя>, найди его.", progress = nil, completion = "Перед вами труп дворфа – изуродованный, застывший и сильно обглоданный горными хищниками. В руке он сжимает записную книжку с грубо нацарапанными записями Мори Хилдельва. Труп одет во все еще превосходно сохранившийся жилет бригадира.\n\nЭта мрачная сцена показывает, где встретил свой конец пилот Осадной машины.", rewards = "Вы получите:\n\nДружинный осадный жилет"},
[420] = {title = "Наблюдения Сенира", objective = "Доставьте донесение Грелина Сениру Белобороду в Караносе.", description = "Трогги, поселившиеся в тоннелях, крайне враждебны: они без раздумий нападают на любого, кто только осмелится туда сунуться. С другой стороны, что-то мне подсказывает, что у тебя хватит сил и умения, чтобы с ними справиться.\n\nЕсли тебе хочется побеседовать с Сениром, то его можно отыскать в Караносе.\n\nА добраться туда и вовсе просто: пройдешь весь тоннель насквозь, а дальше шагай себе по дороге до самого до города Караноса.", progress = "О, приветствую! Как дела? Не хочешь пропустить стаканчик? В такой холод только этим и спасаешься.", completion = "А что это у нас тут такое? О, донесение от моего братца! Хм-м...\n\nГоворил я ему, нечего поминать королевское имя всуе, да только станет он меня слушать! С другой стороны, кое-кому в Совете не мешает попортить кровь. Ха!\n\nКак бы то ни было, думаю, мне нужно и свое донесение отправить в Стальгорн. Как-то запоздал я с этим делом. Все этот проклятый холод!\n\nСлушай, если тебе это интересно, у меня скоро может найтись для тебя кое-какая работенка...", rewards = "Вы получите:\n\n"},
[421] = {title = "Проявить себя", objective = "Далар Ткач Рассвета в Гробнице хочет, чтобы вы убили 5 белоголовов Лунной Ярости.", description = "Леди Сильвана поручила Вариматрасу завоевать земли людей и дворфов к югу. \n\nНо этот идиот Аругал – даларанский шарлатан, а ныне проклятая тварь из крепости Темного Клыка – позволил своей бездумной магии нанести ущерб стратегической цитадели Серебряного бора. \n\nМне нужен кто-то, искушенный в воинском деле, чтобы разрубить узел, завязанный Аругалом. Убейте 5 белоголовов Лунной Ярости и докажите, что вы – тот, кого я ищу. Этих мерзких зверей легко можно встретить у самой дороги, внизу под холмом.", progress = "Если хотите достойно проявить себя, вы должны убить 5 белоголовов Лунной Ярости. Выполните это, и я позабочусь о том, чтобы ваши умения были востребованы в более серьезных заданиях.", completion = "Вы сослужили мне хорошую службу, |3-6(Разбойник). Для меня очевидно, что вы будете достойным помощником – я готовлюсь избавить Серебряный бор от проклятья Аругала.", rewards = "Следующее заклинание будет наложено на вас:\n\nЧародейский интеллект\n\nВы получите:\n\n"},
[422] = {title = "Безрассудство Аругала", objective = "Раздобудьте книгу \"Зелье Аругала\" и принесите ее Далару Ткачу Рассвета в Гробницу.", description = "Для меня загадка, каким образом Аругал вообще был принят в Кирин Тор. Его знания касательно применения заклинаний были просто мыльным пузырем. \n\nСейчас важно точно выяснить, какую магию применил Аругал, чтобы я мог использовать ее против него и обеспечить владычество Темной Госпожи в Серебряном бору. \n\nВначале Аругал останавливался на пшеничной ферме, что к северу от моста. Один из стражей смерти сообщил о том, что видел какие-то книги с заклинаниями, но не сумел их заполучить. Добудьте для меня ту из этих книг, которая называется \"Зелье Аругала\".", progress = "Чтобы понять, с чем мы имеем дело, |3-6(Чернокнижник), мне нужно внимательно изучить книгу \"Зелье Аругала\". Принесите его мне, или мне придется поискать себе достойного слугу", completion = "Да, это именно та книга, которую я искал, |3-6(Чернокнижник). Если ваша приверженность делу Темной Госпожи не ослабела, вас ждет неплохое будущее среди Отрекшихся.", rewards = "Следующее заклинание будет наложено на вас:\n\nЧародейский интеллект\n\nВы получите:\n\n"},
[423] = {title = "Безрассудство Аругала", objective = "Принесите Далару Ткачу Рассвета в Гробницу 6 наручей обжор Лунной Ярости и 3 наруча темных духов Лунной Ярости.", description = "Изучив деятельность Аругала я понял, что  мои наихудшие подозрения верны. Старый хрыч был недостоин даже ночные горшки выносить в Даларане, не говоря уж о том, чтобы представлять Кирин Тор в самый трудный час. Идиоты! \n\nДля усиления своей никудышной магии Аругал использовал заколдованные предметы. В первую очередь я должен изучить эти предметы. Отправляйтесь в путь и убивайте обжор Лунной Ярости и темных духов Лунной Ярости, пока не наберете достаточного для моих исследований количества их заколдованных наручей. Эти злобные создания обитают к северу и к востоку отсюда.", progress = "Мне понадобятся 6 наручей прожорней и 3 наруча темных духов, чтобы я мог полностью разобраться с ситуацией и определиться с окончательным решением по Аругалу. А теперь – за дело. Убивайте прожорней Лунной Ярости и чернозлобов Лунной Ярости, пока не наберете всего, что мне нужно.", completion = "Надеюсь, что смогу выжать достаточно энергии из столь ограниченного количества материала. Вероятно, мне следовало поручить вам добыть больше наручей. \n\nТем не менее, вы отменно проявили себя, собирая эти, |3-6(Чернокнижник).", rewards = "Следующее заклинание будет наложено на вас:\n\nЧародейский интеллект\n\nВы получите:\n\n"},
[424] = {title = "Безрассудство Аругала", objective = "Убейте Мрачнона Белесого и принесите его голову Далару Ткачу Рассвета в Гробницу.", description = "Мне потребуется больше времени на раскрытие темных тайн чар Аругала,чем я думал. \n\nНо тем временем мне нужно, чтобы вы помогли разрешить одну небольшую проблему, которую обнаружили наши разведчики. Похоже, Аругал распространил свою магию на Серебряный рудник, находящийся в холмах к юго-востоку отсюда. \n\nЭтот рудник стал бы ценным ресурсом для Вариматраса. \n\nЯ хочу, чтобы вы снесли голову с плеч пораженному скверной старшине рудника Мрачнону Белесому. После его смерти рудник будет нашим.", progress = "Убит ли Мрачнон Белесый? Вариматрасу вряд ли понравится, если мы проигнорируем его повеление.", completion = "Великолепно. Рудник обеспечит нас отменными ресурсами для наших сил по мере нашего продвижения по Серебряному бору и далее по Азероту.", rewards = "Следующее заклинание будет наложено на вас:\n\nЧародейский интеллект\n\nВы получите:\n\n"},
[425] = {title = "Ивар Нечистый", objective = "Убейте Ивара Нечистого и принесите его голову Ран Йорик на делянку Ивара.", description = "Нам с моим братом Квинном было поручено провести рекогносцировку в Серебряном бору и отчитаться перед верховным палачом Хадриком. Но далеко продвинуться мы не сумели: когда мы проходили через эту ферму, нас атаковал вурдалак Ивар Нечистый. \n\nНам удалось уйти от Ивара, но он успел как следует приложить Квинна. Мой брат поправляется от зелья, что вы ему дали, но Ивар может вернуться раньше, чем Квинн совсем встанет на ноги. \n\nУбейте Ивара, чтобы Квинн мог спокойно поправляться. Обычно Ивар торчит в том амбаре – поджидает, когда я утрачу бдительность.", progress = "Убит ли Ивар Нечистый? Если вы не готовы сделать это для меня и моего брата, убейте его ради Отрекшихся.", completion = "О, спасибо. Я очень благодарна вам, Гронгард. \n\nЯ упомяну ваше имя в отчете, который направлю своему вышестоящему начальству.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСтеганные наручиВидавший виды пояс\n\nВы также получите:\n\n"},
[426] = {title = "Нападение на мельницы", objective = "Соберите 5 зазубренных ребер и 3 почерневших черепа для стража смерти Диллинджера в Брилле.", description = "Плеть пытается основать базу на мельницах Агамондов. Если им это удастся, они продолжат свои нападения в Тирисфале.\n\nПоступил приказ уничтожить всю Плеть на мельницах.\n\nОтправляйся туда и собери зазубренные ребра костетрясов-солдат и костеголовых солдат, а также почерневшие черепа мрачнооких скелетов-заклинателей.\n\nЧтобы добраться до мельниц, иди по дороге на запад. После того как перейдешь мост, поверни на север, и скоро увидишь ветряные мельницы.", progress = "Наш бой с Плетью продолжается, Веланокс! Выполни свой долг и вышвырни эту мерзкую безмозглую нежить обратно в Чумные земли!", completion = "Твои старания не прошли даром, Веланокс! Я не буду благодарить тебя за исполнение долга, но стражи смерти Тирисфаля навсегда запомнят твое имя!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги могильного вораПрочные матерчатые брюки\n\nВы также получите:\n\n"},
[427] = {title = "Война с Алым орденом", objective = "Убейте 10 воинов из Алого ордена по просьбе палача Зуганда.", description = "Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом. Теперь мы знаем расположение всех их баз в Тирисфальских лесах.\n\nНо у стражей смерти есть заботы и поважнее: армия Короля-лича растет с каждой ночью. Нам нужен кто-то такой \"инициативный\", как ты, чтобы навсегда покончить с  Алым орденом.\n\nДокажи мне, что <способен/способна> служить Темной Госпоже: отправляйся на запад, к башне за фермой Соллидена, и убей 10 воинов из Алого ордена.", progress = nil, completion = "Замечательно, |3-6(Жрец). Ваши боевые умения не вызывают сомнений.", rewards = "Вы получите:\n\n"},
[428] = {title = "Пропавшие стражи смерти", objective = "Найдите стражей смерти Квинна Йорика и Ран Йорик.", description = "Пару недель назад двое наших стражей смерти – Ран и Квинн Йорик, ушли на разведывательное задание в северный Серебряный бор. С тех пор от них не было никаких известий. \n\nОни могли стать жертвами Плети, но даже если это так, мне нужно подтверждение. Найдите этих стражей смерти. \n\nИх первой целью была разведка на полях в северной части Серебряного бора. Начните свои поиски там.", progress = nil, completion = "Вы нашли нас! Еще чуть-чуть – и было бы уже поздно...", rewards = "Вы получите:\n\n"},
[429] = {title = "Звериные сердца", objective = "Соберите 6 обесцвеченных сердец ворга и принесите их аптекарю Ренферрелу в Гробницу.", description = "Мой брат Квинн был тяжело ранен вурдалаком, Иваром Нечистым, и я не знаю, сможет ли он как следует поправиться без помощи магии. Хотя я сама и не фармацевт, но знаю, что наши аптекари могут изготавливать исцеляющие зелья из обесцвеченных сердец воргов. \n\nСобери такие сердца и отнеси их аптекарю Ренферрелу к Гробнице, на юг отсюда. А потом возвращайся ко мне с зельем. \n\nМножество воргов водится между этим местом и садом Мальдена к востоку отсюда.", progress = "У меня мало времени, |3-6(Чернокнижник): Темная Госпожа возложила на меня тяжелую задачу.", completion = "*Ренферрел берет у вас сердца.*\n\nМеня тревожит известие о том, что наши стражи смерти потерпели неудачу в своей миссии. \n\nБудем надеяться, что таких неудач будет немного. \n\nЯ сейчас дам зелье, но вот вам рецепт – если стражам смерти понадобится дальнейшая помощь, быть может, вы сами сможете им ее оказать.", rewards = "Вы получите:\n\nРецепт: бесцветное лечебное зельеБесцветное лечебное зелье"},
[430] = {title = "Назад к Квинну", objective = "Отнесите зелье Квинна Квинну Йорику на делянку Ивара, к северу от Гробницы.", description = "Вот зелье, которое должно помочь Квинну Йорику поправиться. \n\nА теперь, простите, мне нужно продолжить одно очень важное дело...", progress = "Моя сестра сказала, что вы поможете нам. Это правда?", completion = "&lt;Квинн выпивает зелье.&gt;\n\nДа, я чувствую его действие. Вскоре я снова смогу передвигаться. \n\nВы оказали мне большую услугу, Гронгард.", rewards = "Вы получите:\n\n"},
[431] = {title = "Манящие свечи", objective = "Вы берете одну свечу и кладете ее в сумку.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nМанящая свеча"},
[432] = {title = "Проклятые трогги!", objective = "Убейте по просьбе штейгера Камнелоба 6 головоломов из племени Каменной Челюсти в карьере Гол'Болар.", description = "Эти проклятые Светом трогги перевернули все мое рабочее место! Ты только глянь, еще одну бочку пороха разворотили!\n\nОх, прямо руки чешутся спуститься к ним да головы поотрывать! Всех бы поубивал!\n\nНо здоровье не позволяет, да еще это потрясение и злость... Они ничего мне не оставили!\n\nЯ бы сам их перебил, да рука уже не так тверда! Иди в карьер и перебей грязных тварей! Я заплачу! Ты только задай им шороху, перебей их!", progress = "Гр-р-р… Как я зол!", completion = "Ох, на душе полегчало...\n\nНо я не успокоюсь, пока все трогги не будут уничтожены! Все до единого!", rewards = "Вы получите:\n\n"},
[433] = {title = "Слуга народа", objective = "Убейте 10 костегрызов из племени Каменной Челюсти по просьбе сенатора Мера Каменная Реликвия из карьера Гол'Болар.", description = "Будучи членом Сената и Лиги Исследователей, я взял на себя заботу об искоренении троггской заразы, наводнившей наши земли.\n\nОни ни за что ни про что разнесли карьер Гол'Болар. Чем глубже мы копаем, тем больше их лезет наружу, уничтожая наше оборудование и выгоняя горняков из шахт. У нас нет выбора, кроме как истребить их как можно больше, отстроиться заново и вернуться к работе.\n\nЕсли вы поможете мне разобраться с троггами, я с радостью возмещу вам затраты времени.", progress = "Если мы сможем изгнать троггов из карьера Гол'Болар, это будет первый шаг на долгом пути к избавлению от этой заразы.", completion = "Это только начало. Надеюсь, мы сможем воспользоваться преимуществом, и выделим небольшой контингент горных пехотинцев для защиты этого района. Тогда мы сможем начать восстановление инфраструктуры и вернуть горняков к работе.\n\nСпасибо тебе за помощь, Wrestlecake.", rewards = "Вы получите:\n\n"},
[434] = {title = "Нападение!", objective = "Спрячьтесь в саду и подслушайте разговор лорда Грегора Лесковара и Марзона Бесшумного Клинка. После этого убейте обоих и возвращайтесь к Иллингу Триасу в Штормград.", description = "Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару. Гвардия пропустит его без особых проблем.\n\nПока ты <собирал/собирала> для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром. Я даже подкинул ему пару ложных слухов.\n\nЛесковар отпустит свою охрану и будет дожидаться Марзона в саду. Начинай действовать, как только они заведут разговор о Братстве Справедливости. Убей обоих до возвращения гвардейцев! После этого поговори с Триасом.", progress = nil, completion = "Сделано? Отлично. Бронгард, благодарю вас за посильное участие. Вы оказали Штормовому Оплоту не одну услугу. С вашего позволения, я буду приглядывать за вами: вы можете славно послужить делу Альянса.\n\nПостарайтесь ни во что не вляпаться.", rewards = "Вы получите:\n\n"},
[435] = {title = "Сопровождая Эрланда", objective = "Проводите Эрланда, защищая его от волков, к Ран Йорик.", description = "Волки там, снаружи, никуда не уйдут, и они злобно смотрят на меня каждый раз, когда я выхожу из двери. Должно быть, они невероятно голодны, раз смогли счесть меня пищей. \n\nЯ должен доложиться своей коллеге, стражу смерти Ран Йорик. Но чтобы добраться до Ран, мне нужна помощь против этих волков.\n\nПожалуйста, проводите меня! Волков здесь очень много, так что наши шансы будут выше, если у вас есть готовые помочь друзья...", progress = nil, completion = "Спасибо за помощь, Соулнце. Я боялась, что Эрланда погубили опасности Серебряного бора. Но я вижу, что благодаря вашей помощи этого не произошло.", rewards = "Вы получите:\n\nКороткий меч стража смерти"},
[436] = {title = "Раскопки Сталекрута", objective = "Обратитесь к исследователю Удару Топора.", description = "Геолог Сталекрут возглавляет раскопки в древних руинах к востоку от озера. В последнее время дело продвигается медленно – и это учитывая, сколько мы послали туда припасов!\n\nСталекрут – надежный, честный дворф, который прежде всего болеет за результат, потому-то я и думаю, что кто-то решил ему помешать.\n\nОтправляйся к раскопкам Сталекрута и обратись к Магмару Рудоколу. Он ведет отчетность по раскопкам и сможет объяснить, чем вызвана задержка.\n\nЧтобы отыскать раскопки, обогни озеро с юга и направляйся на восток.", progress = nil, completion = "Значит, Джерн хочет узнать, чем вызвана задержка?\n\nЖелезняк как раз пишет подробный отчет о своих последних достижениях, но я буду краток.\n\nДело в троггах!!!", rewards = "Вы получите:\n\n"},
[437] = {title = "Мертвое поле", objective = "Убивайте гноллов из стаи Гнилошкуров на Мертвом поле. \n\nКогда появится банши Плеть Ночи, убейте ее. \n\nСущность банши принесите верховному палачу Хадрику в Гробницу.", description = "Первые отчеты наших разведчиков в Серебряном бору говорят о том, что Гнилошкуры устроили базу на заброшенном поле к северу отсюда – на Мертвом поле. Мы посылали против них небольшие группы, но им каждый раз помогала банши Плеть Ночи, которая своей магией обращала наших воинов в бегство. \n\nМы хотим уничтожить Плеть Ночи. \n\nОтправляйтесь на Мертвое поле и атакуйте Гнилошкуров. Убивайте их до тех пор, пока не покажется Плеть Ночи, а затем убейте и ее. \n\nСущность банши обратится в прах. Принесите мне этот прах в доказательство ее смерти.", progress = "Вы уже уничтожили Плеть Ночи, Гронгард? От этого зависит наш успех в борьбе против Гнилошкуров!", completion = "Я слышал о вашем успешном набеге на гноллов-гнилошкуров, Гронгард, а эта сущность является доказательством смерти банши Плеть ночи. \n\nСегодня Король-лич потерял еще одного прислужника. Вы становитесь еще более ценным союзником в глазах Отрекшихся.", rewards = "Вы получите:\n\nСапоги разведки"},
[438] = {title = "Старая переправа", objective = "Отправляйтесь к старой переправе. \n\nПоищите причину присутствия там сил Плети.", description = "<имя>, мы обнаружили еще одно место, где угнездилась Плеть: это старая переправа. Переправа находится к востоку от Гробницы, и ее патрулируют многочисленные гноллы-гнилошкуры и различная нежить. \n\nПолагаю, Плеть захватила это место неспроста. Отправляйтесь к старой переправе и выясните, в чем там дело.", progress = nil, completion = "В лодке находится куча спеленутых мертвых тел. А если смотреть на восток через озеро Лордамер, то напротив видна пристань на острове Фенриса. \n\nДолжно быть, разгадку этой тайны стоит искать на острове.", rewards = "Вы получите:\n\n"},
[439] = {title = "Необычная находка", objective = "Принесите кольцо Делии верховному палачу Хадрику в Гробницу.", description = "Из кучи трупов торчит обнаженная рука. Это рука женщины – тронутая чумой, но относительно свежая. \n\nНа пальце надето кольцо. Вы снимаете кольцо и, осмотрев его, обнаруживаете гравировку: \n\n\"Делии\".", progress = "Гронгард, вы вернулись. Я полагаю, ваше расследование дало результаты?", completion = "Говорите, это кольцо было надето на палец недавно погибшей женщины? \n\nВидимо, тело было поднято из общей могилы в Тирисфале, не иначе. Должно быть, гноллы-гнилошкуры таскают эти трупы на остров Фенриса!", rewards = "Вы получите:\n\n"},
[440] = {title = "Кольцо с гравировкой", objective = "Отнесите кольцо Делии мировому судье Севрену в Брилл.", description = "Если хотите найти мужа или возлюбленного Делии – того, кто подарил ей кольцо... поговорите с мировым судьей Севреном в Брилле. У него должны быть записи о недавних смертях и, если повезет, он сможет выяснить, кто такая Делия. \n\nНо я бы на это не рассчитывал. Тот, кто подарил ей кольцо, вероятно, уже мертв. Или, если он стал нежитью, то, возможно, ему больше нет дела до Делии.", progress = "Здравствуйте, Гронгард. Что привело вас обратно в Брилл?", completion = "Некая Делия жила в Брилле не так давно. Она была похоронена в общей могиле, но, если верить вашим словам, ее тело, должно быть, похитили гноллы из стаи Гнилошкуров и утащили в Серебряный бор. \n\nСтая Гнилошкуров, как и вся Плеть, должна быть уничтожена. Я верю, что ты предпримешь к этому надлежащие шаги.", rewards = "Вы получите:\n\n"},
[441] = {title = "Роли, который живет в Подгороде", objective = "Отнесите Роли кольцо Делии.", description = "У Делии был муж по имени Роли, проживающий ныне в Подгороде. Если кольцо действительно принадлежало Делии, которая жила здесь, в Брилле, то Роли узнает его. \n\nНайти Роли вы можете в Торговом квартале Подгорода.", progress = "Мы знакомы?", completion = "Да, это вещица моей жены. Ее постигла та же участь, что и всех, кому не удалось пережить эти суровые времена. Меня не трогает ее смерть, как не трогает и ваш рассказ о похищении ее тела. \n\nПодобные чувства давно остыли во мне. Но желание все еще клокочет в моем мертвом сердце, Гронгард. \n\nЖелание отомстить.", rewards = "Вы получите:\n\n"},
[442] = {title = "Атака на остров Фенриса", objective = "Принесите верховному палачу Хадрику в поселении Гробница голову Тула Когтя Ворона.", description = "А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса. \n\nТы снова <должен/должна> добраться до острова и уничтожить Тула Когтя Ворона. Мне нужна его голова!\n\nЯ посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача, <имя>. Ты <должен/должна> выйти <победителем/победительницей>!", progress = "Силам Плети нельзя позволить оставаться в Серебряном бору, Аггромашина. Возвращайся ко мне с доказательством смерти Тула.", completion = "Смерть Тула Когтя Ворона – значимое событие, Аггромашина. Ренферрел рассказывает, что потоки энергии, которые вы высвободили при уничтожении Тула, ощущались аж до Гробницы. \n\nТвои действия получили большой резонанс у Отрекшихся. Твоя ценность в наших глазах растет.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПарадное одеяние судьиУдар когтя\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[443] = {title = "Лимфа Гнилошкуров", objective = "Принесите 8 бутылок лимфы Гнилошкуров аптекарю Ренферрелу рядом с Гробницей.", description = "Прежде чем мы совершим нападение на остров Фенриса, мы должны понять, кто стоит за Гнилошкурами. Наши аптекари считают, что их особенности связаны со странной жидкостью, текущей по их жилам. \n\nОтправляйся на остров Фенриса, к востоку от старой переправы, и собери лимфу гноллов-гнилошкуров, которых вы там встретите. Образцы нужны аптекарю Ренферрелу, который стоит неподалеку от Гробницы.", progress = "Вы собрали лимфу Гнилошкуров, Гронгард?", completion = "Отлично. Эта лимфа поможет нам понять природу гноллов-гнилошкуров, а также сможет показать нам, в чем их слабость... \n\n...если она у них есть...", rewards = "Вы получите:\n\n"},
[444] = {title = "Происхождение Гнилошкуров", objective = "Отнесите образец лимфы Бетору Ледострелу в Подгород.", description = "Я выпарил лимфу, которую ты <принес/принесла> мне, и разложил ее на основные компоненты. Мои выводы еще не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией. \n\nПока я продолжу ее изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород. Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров.\n\nИди же. Бетора ты найдешь в Квартале Магов Подгорода.", progress = "Мои исследования требуют серьезной концентрации. Так что, надеюсь, ваш визит не праздный.", completion = "Эта субстанция наполнена могучими заклинаниями, с некоторыми из которых я не сталкивался вот уже долгое время... \n\nСекундочку – мне придется воспользоваться проясняющим заклинанием...", rewards = "Вы получите:\n\n"},
[445] = {title = "Доставка в Серебряный бор", objective = "Отнесите находки аптекаря Юхана аптекарю Ренферрелу в Серебряном бору.", description = "Время – это непозволительная роскошь для тех, кто служит леди Сильване. Ты это, конечно, уже и <сам понял/сама поняла>.\n\nЯ состою в Королевском фармацевтическом обществе и в мои обязанности входит обмен знаниями с коллегами, чтобы однажды нашими совместными усилиями появилась новая чума, которую так желает получить Темная Госпожа.\n\nОтнеси эти находки аптекарю Ренферрелу – его можно найти в Гробнице, это поселение в Серебряном бору. Если идти из Брилла – то на юг, а если из Подгорода – на юго-запад.", progress = "Что у вас за дело ко мне, |3-6(Воин)?", completion = "А, как хорошо, что аптекарь Юхан прислал мне результаты своих исследований! Здесь, в Серебряном бору, происходит столько всего, что я совсем забыл про материалы из Лордерона и с Тирисфальских лесов. Кстати, надо бы поскорей отправить те образцы в Некрополь...\n\nПрости, Топот. Задержись в Серебряном бору чуть подольше, такой |3-6(Воин), как ты, всегда нам пригодится.", rewards = "Вы получите:\n\n"},
[446] = {title = "Тул Коготь Ворона", objective = "Отнесите свиток Бетора аптекарю Ренферрелу в Серебряный бор, в селение Гробница.", description = "Эта лимфа была создана моим давним коллегой, Тулом Когтем Ворона. До великой войны он был молодым и многообещающим магом, но когда вошел в силу Король-лич, Тул предал своих братьев и перешел на сторону Плети. \n\nЯ и не думал, что он все еще жив, и уж тем более – что он возглавляет набеги Гнилошкуров на нас! \n\nЯ знаю многие из его заклинаний и могу помочь сварить зелье для того, чтобы им противостоять. Отнеси этот свиток обратно к аптекарю Ренферрелу. Там содержатся заклятья, необходимые для изготовления зелья.", progress = "Приветствую вас, Гронгард. Что сказал Бетор?", completion = "Этот свиток весь пронизан могущественной магией. Я никогда не использовал таких сил в зельях... это будет сильнодействующая микстура, и она должна сослужить тебе хорошую службу, если ты решишься атаковать Тула в его крепости на острове Фенриса.", rewards = "Вы получите:\n\nЗелье Бетора"},
[447] = {title = "Рецептура смерти", objective = "Соберите 6 сердец медведя и 6 образцов Летящей крови и принесите их мастеру-аптекарю Фаранеллу в Подгород.", description = "Силы Артаса неисчислимы. Но с Новой чумой мы могли бы раз и навсегда покончить как с армией Плети, так и с людьми. \n\nМои исследования показали, что паучья кровь в соединении с токсином, извлеченном из сердца бешеного медведя, дает смертельно опасный эликсир. Собери необходимые субстанции с пауков из Струящейся Тьмы к северо-западу отсюда и с медведей, бродящих по Серебряному бору. Принеси реагенты в Подгород мастеру-аптекарю Фаранеллу из Королевского фармацевтического общества.", progress = "Приветствую вас, |3-6(Воин). Какое дело у вас к Королевскому фармацевтическому обществу?", completion = "Аптекарь Ренферрел правильно сделал, что послал вас ко мне, Гронгард. Эти образцы действительно будут весьма полезны. Я немедленно начну изучить их отравляющие и инфицирующие свойства.", rewards = "Вы получите:\n\nКорень сенджины"},
[448] = {title = "Доложиться Хадрику", objective = "Доложите о себе верховному палачу Хадрику в поселении Гробница.", description = "Прежде чем вы нападете на остров Фенриса, доложитесь верховному палачу Хадрику. У него может быть дополнительная информация о том, что вам понадобится.", progress = nil, completion = "Если то, что говорит Бетор, – правда, то Тул Коготь Ворона представляет собой силу, с которой нужно разобраться, причем разобраться срочно. \n\nВ качестве помощи можете подобрать себе что-нибудь из нашего здешнего арсенала...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗернистое грузилоЗернистое точило\n\nВы также получите:\n\nНакладки из жесткой кожи"},
[449] = {title = "Отчет стражей смерти", objective = "Отнесите отчет стражей смерти верховному палачу Хадрику в Гробницу.", description = "Хотя раны Квинна заживают, я хотела бы доставить наш отчет верховному палачу Хадрику как можно скорее. В нем содержится информация, которая жизненно важна для захвата Серебряного бора Отрекшимися.", progress = "Удалось ли вам прояснить судьбу стражей смерти?", completion = "Я не ожидал ни такого количества Плети, с каким мы столкнулись в Серебряном бору, ни проблем, которые возникли перед стражами смерти в ходе разведывательной операции. \n\nВаша помощь нашим стражам смерти просто неоценима, Веланокс. Вы заслуживаете похвалы.", rewards = "Вы получите:\n\n"},
[450] = {title = "Рецептура смерти", objective = "Найдите в деревне Погребальных Костров записи Берарда и отнесите их в Гробницу аптекарю Ренферрелу.", description = "Вы можете еще послужить Королевскому фармацевтическому обществу, <имя>. \n\nКогда Аругал навел на лес свою никчемную магию, он наложил проклятие на одного из наших самых многообещающих сотрудников, аптекаря Берарда. Ставший безвольным слугой Аругала, теперь Берард для нас бесполезен. Но его находки могут быть ценными. Он изучал древнюю чуму, давным-давно погубившую всякую жизнь в озере Лордамер. \n\nРаздобудьте записи Берарда из его кабинета в таверне деревни Погребальных Костров и принесите аптекарю Ренферрелу.", progress = "Вижу, Вота, вы снова здесь.", completion = "Записи аптекаря Берарда! В смелости вам не откажешь, Вота. Теперь давайте посмотрим, чем занимался Берард прежде, чем сошел с ума...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[451] = {title = "Рецептура смерти", objective = "Принесите 6 образцов мха озерного ползуна, 6 образцов мха озерного тихохода и твердую опухоль мастеру-аптекарю Фаранеллу в Подгород.", description = "Согласно записям Берарда, мох озерных тихоходов и озерных ползунов может оказаться полезным для решения нашей задачи по изготовлению новой отравы. Эти твари обитают на островах на озере Лордамер на востоке. \n\nОн также упоминает об очень редкой субстанции – твердой опухоли, обнаруженной им у мурлока из племени Злобного Плавника. Очевидно, эта опухоль столь редка, что Берарду удалось раздобыть лишь одну. \n\nСоберите образцы моха, а также редкую твердую опухоль и отнесите их мастеру-аптекарю Фаранеллу в Подгород.", progress = "Что вновь привело вас в Подгород, Вота?", completion = "Потеря Берарда – серьезный удар для Королевского фармацевтического общества. Но благодаря вашим стараниям и усердным исследованиям аптекаря Ренферрела разработки Берарда по-прежнему будут полезны делу Темной Госпожи. \n\nМы находимся на пороге чего-то великого Вота. Если бы вы не были столь искусны в военном деле, я пригласил бы вас вступить в члены нашего Общества.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗелье Света в ночиПлащ защиты от кислоты\n\nВы также получите:\n\nСлабый эликсир стойкостиЗелье скорости"},
[452] = {title = "Засада в деревне", objective = "Помогите стражу смерти Фарлии уничтожить совет деревни Погребальных Костров.", description = "Вы очень вовремя добрались сюда, <имя>! \n\nСовет деревни Погребальных Костров вернется в любой момент. Аругалу же есть чем заняться в крепости. Он использует совет как марионеток, чтобы держать лишенных разума и воли приспешников в деревне под своим полным контролем. Но я уверена, что без руководства совета деревни Погребальных Костров сыновья Аругала взбунтовались бы против своего хозяина. \n\nЯ не могу справиться со всем в этим в одиночку. Мне нужна ваша помощь. Вместе мы сможем погубить совет, на благо леди Сильваны.", progress = nil, completion = "Вы бились достойно настоящего последователя Темной Госпожи, Жрендед. Теперь, когда члены Совета мертвы, может быть, мы сможем восстановить контроль над этой деревней раз и навсегда и выбить Аругала из крепости Темного Клыка. Честь имею!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЩит ФаэрлеиРастянутые кожаные брюкиМистическая шаль\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[453] = {title = "Поиски таинственного незнакомца", objective = "Отыщите незнакомца. Его приметы:\n\nОн родом не из Темнолесья.\n\nОн – нервный тип.\n\nОн сбежал из Темнолесья и двинулся на запад.", description = "Удачи, <имя>. Надеюсь, ты найдешь этого парня, причем живым.\n\nСбежав за пределы Темнолесья, он мог пасть жертвой диких зверей.", progress = "Кто ты?! Оставь меня в покое!", completion = "*Трясунчик вздыхает...*\n\nДа, автор этой книги – я. Сумел-таки отыскать меня?\n\nНо если ты прочитаешь мои записи, то узнаешь только половину истории!", rewards = "Вы получите:\n\n"},
[454] = {title = "После засады", objective = "Поговорите с Мираном.", description = "До этого... случая мы все время таскали туда-сюда бочки с порохом. Теперь придется поделить работу: Миран понесет часть бочек, а я присмотрю за остальными.\n\nМне не хочется отпускать Мирана одного. Когда он соберется в путь, проводи, пожалуйста, его.", progress = nil, completion = "Добрый день, |3-6(Охотник).\n\nТы проводишь меня до раскопа? Отлично... После случая с Сайаном и его компанией я не знаю, чего и ждать от клана Черного Железа.\n\nЯ почти готов, осталось только кое-что проверить. Когда ты соберешься в путь, скажи мне об этом.", rewards = "Вы получите:\n\n"},
[455] = {title = "Альгазская битва", objective = "Пройдите через Дун Альгаз.\n\nУбейте 8 разведчиков из клана Драконьей Пасти и 6 рубак из клана Драконьей Пасти.\n\nОб исполнении доложите Валстагу Сталезубу в Гавани Менетилов.", description = "Орки из клана Драконьей Пасти бесчинствуют по всей Болотине. А сейчас они двинулись на Дун Альгаз! Нельзя допустить, чтобы они здесь закрепились, иначе Лок Модан будет отрезан от Гавани Менетилов, нашего порта и крепости в Болотине.\n\nПопытайся прорваться сквозь Дун Альгаз в Болотине и убей столько орков, сколько сумеешь! Чем больше, тем лучше! Об исполнении доложишь Валстагу Сталезубу в Гавани Менетилов.\n\nНайти Менетилов несложно: пройдешь через Дун Альгаз, потом – по дороге на север, а на развилке свернешь на запад.\n\nМы очень надеемся на тебя, <имя>. Не подведи нас.", progress = nil, completion = "Да, нехорошие новости!\n\nКак я понимаю, орки Драконьей Пасти всерьез вознамерились двинуться на Альгаз. Обычно они сидят у себя на холмах и никуда не суются. Что их сподвигло идти на Альгаз? Для меня это загадка...\n\nСпасибо, Rainon. Может быть, нам понадобится твоя помощь, когда мы пойдем разбираться с орками.", rewards = "Вы получите:\n\n"},
[456] = {title = "Природное равновесие", objective = "Убейте 7 молодых ночных саблезубов и 4 молодых щетинистых вепрей и вернитесь к Опекуну Илталайну.", description = "Мои приветствия, <имя>. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия. \n\nВесенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают.\n\nК несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить. <Юный/Юная:c> <класс>, помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия.", progress = "Дел еще немало, Лошарик. Возвращайся ко мне, как только сократишь поголовье ночных саблезубов и щетинистых вепрей.", completion = "Ты хорошо исполнил свой долг, Радиум.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТренировочные перчатки лучникаНаручи Стеблелиста\n\nВы также получите:\n\n"},
[457] = {title = "Природное равновесие", objective = "Опекун Илталайн хочет, чтобы вы убили 7 облезлых ночных саблезубов и 7 щетинистых вепрей.", description = "Сокращение численности молодых особей, обитающих в Тенистой долине – это неплохо для начала, <имя>, однако нужно выполнить еще некоторую работу.\n\nЛесные ресурсы истощатся слишком быстро, если не решить эту проблему. Охота на диких зверей – это зло, необходимое для блага всех тех, кто обитает в этих землях. Отправляйся в лес и убивай облезлых ночных саблезубов и щетинистых вепрей ради равновесия.", progress = "Твоя работа еще не завершена, Лаваошкшк. Возвращайся ко мне после того, как убьешь 8 облезлых ночных саблезубов и 8 щетинистых вепрей.", completion = "Твои дела доказывают твою преданность природе, Радиум. Поверь, |3-6(Разбойник), несмотря на твою юность уже заметно, что тебя ждет блестящее будущее.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМятый плащЧерненый кожаный пояс\n\nВы также получите:\n\n"},
[458] = {title = "Защитница леса", objective = "Найдите дриаду по имени Тариндрелла.", description = "Какая отрада, что ты здесь, <класс>. Шепот лесных духов донес до моего слуха странные вести.\n\nТаинственная защитница леса, Тариндрелла, вернулась в Тенистую долину. Много лет эту дриаду не видели в лесах Калимдора. Что-то определенно не так, если она вновь появилась в этих землях. \n\nНайди Тариндреллу и узнай, что привело ее в наши рощи. Кто-то из Стражей сообщил о том, что ее видели к юго-западу от Альдрассила.", progress = nil, completion = "Я вижу, тебе удалось найти меня, юный |3-6(ночной эльф)! Друид Мелитар мудро поступил, отправив тебя сюда.", rewards = "Вы получите:\n\n"},
[459] = {title = "Защитница леса", objective = "Соберите 8 порций мха Скверны и принесите их Тариндрелле.", description = "Непонятное зло затаилось в лесу Тельдрассила. Взгляни на холмы, где некогда обитали мирные фурболги. Они покинули свои дома и объединились в племя Кривой Сосны.\n\nЛишь порча, вызванная зловещим мхом Скверны, могла быть причиной подобного изменения. Грелли и греллиды кишат в округе, представляя собой угрозу для жителей Тенистой долины. \n\nНапади на этих этих бесов, <имя>, и узнай, действительно ли они подпали под чары зловещего мха Скверны.", progress = "Помоги мне подтвердить или опровергнуть мои подозрения, Анудорини. Принеси мне 8 кусочков мха Скверны.", completion = "Твое служение обитателям Тенистой долины достойно награды, Анудорини.\n\nОднако мои опасения подтвердились. Если даже грелли попали под влияние мха Скверны, то можно вообразить, что случилось с фурболгами племени Кривой Сосны, некогда жившими здесь.\n\nДруид, если будешь в Доланааре, отыщи мудрого друида Атридаса Медвежью Шкуру. Он, как и мы, печется о благополучии леса.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШирокие поножиСапоги путникаЛозяные перчатки\n\nВы также получите:\n\nЦелебная трава"},
[460] = {title = "В целости и сохранности", objective = "Отнесите голову Аларика на его могилу.", description = "На вид ты не похож на гнилошкура. Это хорошо. А то я уже потерял надежду... \n\nМеня зовут Аларик, когда-то я был доверенным слугой и телохранителем Тула. Он использовал свою магию для \"защиты\" меня от Чумы Нежити, но вместо этого его заклинание повергло меня в нежитие – состояние, из которого я не могу уйти. А после создания этих проклятых гнилошкурых гноллов Туле обезглавил меня... и отдал гноллам мою голову в качестве игрушки! \n\nПожалуйста, воссоедини меня с телом. Я уверен, что гноллы закопали его в Крепости Фенриса, возле стойл, в ничем не примечательной могиле.", progress = "Видно, что эта могила была выкопана в спешке.", completion = "Спасибо, Аггромашина. Я опасался, что гноллы изуродовали мое тело. Приятно узнать, что это не так.", rewards = "Вы получите:\n\n"},
[461] = {title = "Замаскированный тайник", objective = "Отнесите Аларика к замаскированной нише.", description = "Я знаю об одной тайной нише в крепости, где хранится дорогой сердцу Тула и его давних коллег предмет. В ней также лежит нечто, что вы можете счесть полезным для себя. Возьмите меня туда! \n\nУглубление в стене находится в юго-западной башне крепости, позади пыльной полки. \n\nВозьмите мое тело, а сапоги оставьте здесь. Они мне все равно не по ноге...", progress = "Вот это место! Поднесите меня поближе...", completion = "Вот мы и на месте, здесь открыто. Оставьте меня здесь. Лучшие дни моей жизни я провел в этой крепости, и мысль об упокоении в этих стенах умиротворяет меня. \n\nХорошенько закройте нишу – я не хочу, чтобы эти гнилошкуры нашли меня. \n\nАх, да, и возьмите вот это. Вы это заслужили.", rewards = "Вы получите:\n\n"},
[463] = {title = "Страж Природы", objective = "Найдите Зеленого Стража.", description = "Ты ведь <слышал/слышала> рассказы о Зеленом Страже? Я даже подозреваю, что ты и разыскать его хочешь. Если так, то скажу тебе, что это чистое безумие! Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим.\n\nОн живет на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями.\n\nОставь-ка свои денежки мне – покойникам они все равно не нужны. Да и Зеленый Дядя может обломать зуб об твои золотые, когда будет перекусывать тебя надвое... Ты ведь не хочешь, чтобы бедняга потом мучился?", progress = nil, completion = "Что это за букашка ко мне пожаловала? Корни и папоротники говорят, что ты пришел с добрым умыслом... Меня по-разному называют, но не на всякое имя я откликаюсь. Зови меня Ретиль.\n\nА теперь внемли... Здешние земли уже давно страдают от множества недугов, и я поручу тебе исцелить их.", rewards = "Вы получите:\n\n"},
[464] = {title = "Боевые знамена", objective = "Принесите 8 боевых знамен клана Драконьей Пасти капитану Крепкому Кулаку.", description = "К концу Второй войны клан орков Драконьей Пасти потерял власть над красными драконами и был почти уничтожен. Драконы припомнили им все, гнали бывших хозяев аж до до самого Грим Батола. Затем орки скрылись в горах к востоку от раскопа Вельгара.\n\nОтсидевшись в горах, они вновь набрали силу и теперь разбили лагерь к северо-востоку от Менетила.\n\nНапади на этот лагерь, внеси панику в ряды орков. В доказательство содеянного принеси мне боевые знамена клана.", progress = "Ну что, ты показал оркам, почем фунт лиха?", completion = "Отличная работа, Бронгард. Ныне клан Драконьей Пасти уж не тот, что в былые времена, когда оркам служили драконы. Но все равно они опасные противники.\n\nКланом Драконьей Пасти руководит Нек'рош, сын Некросса – бывшего главы клана. Некросс владел могущественными заклинаниями, с помощью которых он управлял красными драконами. Но когда его силы иссякли... ну, ты уже знаешь эту историю.\n\nНекросс погиб, а его сын поклялся отомстить драконам, убившим его отца.", rewards = "Вы получите:\n\n"},
[465] = {title = "Гамбит Нек'роша", objective = "Уничтожьте катапульты Драконьей Пасти.", description = "Пока ты <сражался/сражалась> с кланом Драконьей Пасти, мы получили сведения об их планах.\n\nНек'рош строит катапульты и планирует взять Менетил в осаду! А у нас тем временем вовсю идет битва при Дун Альгаз, и подкрепления ждать неоткуда!\n\nУничтожь катапульты, прошу тебя. Они стоят в лагере Драконьей Пасти.\n\nВозьми вот этот трут. Пробейся к катапультам и подожги их.\n\nПосле этого найди и убей Нек'роша. Этот паршивец уже свое отжил...", progress = "Вот одна из катапульт. Поджигаем?", completion = "Вы подносите трут к катапульте и высекаете искру...\n\nПламя охватывает катапульту и мигом перекидывается на другие!", rewards = "Вы получите:\n\n"},
[466] = {title = "Поиски огневита", objective = "Принесите 6 партий огневитовой руды пилоту Камнекожицу в Дун Морог.", description = "Я слышал о редком виде руды – огневите. Его добывают в Болотине, в пещере к северо-западу от Врат Альгаза. Огневит очень неустойчив – чуть что, сразу взрывается. Однако я уверен, что если правильно его выплавить, то можно делать из него мощнейшие снаряды для пушек!\n\nРаздобудь для меня огневитовую руду, а я пока поищу добровольца, который согласится принять участие в опытах.\n\nАх да, чтобы добыть руду, тебе нужны познания в горном деле. Если у тебя нет необходимых знаний, то... отправь в шахту кого-нибудь из знакомых рудокопов!", progress = "Где руда, Терраформ?!", completion = "Как раз столько, сколько нужно для экспериментов! Молодец, Терраформ, я в тебя верил! Тут же отправлю материал на изучение. Надеюсь, что мой доброволец хотя бы до первых результатов доживет!", rewards = "Вы получите:\n\nЗаляпанные пивом перчатки"},
[467] = {title = "Найдите Камнекожца", objective = "Поговорите с пилотом Камнекожицем.", description = "Пилот Камнекожиц любит свою осадную машину, как и все пилоты осадных машин! И он всегда рад найти новый способ повысить огневую мощь своих орудий.\n\nДо него дошли слухи о редкой руде, и он ищет кого-нибудь, кто добудет ее. И если тебе уже не терпится взяться за это дело, то найди Камнекожица в поселке Сталежара в Дун Мороге и спроси, чего он хочет.", progress = nil, completion = "Привет, Барабаха. Ты тут по моему делу, да? Приятно видеть, как молодой |3-6(дворф) рвется на поиски приключений!", rewards = "Вы получите:\n\n"},
[468] = {title = "Отчитайтесь перед горным пехотинцем Рокхаром.", objective = "Поговорите с горным пехотинцем Рокхаром.", description = "Горный пехотинец Рокхар ищет добровольцев для похода через Дун Альгаз в Болотину!\n\nЕсли желаете омыть сапоги в болотной жиже и снискать приключений на свою голову – поговорите со Скальным Панцирником в Дун Альгаз. Это к северу отсюда, по дороге за сторожевой башней.", progress = nil, completion = "Паладин, ни больше, ни меньше! Желаешь отправиться с нами в разведку? Отлично!\n\nНадеюсь, у тебя есть все необходимое снаряжение, потому что эта \"разведка\" может обернуться и кое-чем похуже...", rewards = "Вы получите:\n\n"},
[469] = {title = "Ежедневная доставка", objective = "Отнесите стопку кроколисковых шкур кожевнику Джеймсу Халлорану в Гавань Менетилов.", description = "Привет тебе, <странник/путешественница>!\n\nНе лежит ли твой путь в сторону Менетила? Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт. Прелестный городок!\n\nНу а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана.\n\nЯ бы и сам отнес их, но дома последнее время то свара, то скандал. Не хочу попадаться жене на глаза.", progress = "Не интересуется ли добрый |3-6(Паладин) сапогами из кроколисковой кожи? Могу предложить отличные выделанные шкуры!", completion = "Хмм, да это же от Эйнара, да? Не вижу его уж который день, а шкуры присылает исправно. Опять поцапался со своей благоверной, к бабке не ходи!\n\nНадо бы подослать жену к Сиде – поговорить, чтобы та не выживала мужа из дому...", rewards = "Вы получите:\n\n"},
[470] = {title = "Прожорливый слизнюк", objective = "Отнимите сумку Сиды у неизвестного слизнюка возле гробницы Железноборода и верните ее хозяйке в Гавань Менетилов.", description = "Каждую неделю я хожу к Гробнице Железноборода, и в этот раз все было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась...\n\nЯ бросила в одного из них сумку, но он взял и засосал ее! Мне едва хватило времени, чтобы сбежать.\n\nА в сумке-то мои вещи!\n\nЯ даже не знаю, какой из этих гадов ее сожрал – они все одинаковые! Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что <согласился/согласилась> помочь!", progress = "Где же моя сумочка?", completion = "Спасибо большущее, Rainon! Я-то боялась, что ее больше не вернуть!\n\n*Она вытряхивает из склизкой сумки содержимое и собирает мелочь в кучку.*\n\nХм, чего-то я здесь самого нужного и не вижу... посмотри, может, тебе что-нибудь отсюда пригодится.", rewards = "Вы получите:\n\nСумка, покрытая грязью"},
[471] = {title = "Тяжкая судьба помощника", objective = "Принесите 6 шкур гигантских кроколисков Джеймсу Халлорану в Гавань Менетилов.", description = "Недавно я отправил помощника на болото за шкурами гигантских болотных кроколисков. Он не вернулся обратно, и я отправился на поиски... Скажем так: зрелище было не для слабонервных.\n\nЛекарь говорит, что мальчик выживет, и слава богу, но у меня-то работа стоит!\n\nЕсли у тебя есть желание поохотиться на кроколисков, я препятствовать не стану – особенно после того, что они сделали с моим помощником. Кроколиски водятся на побережье к северу отсюда, за поселением мурлоков.", progress = "Помощник мне – как сын родной! Трудно же ему придется в жизни, одноногому...\n\nА, это ты, Rainon? Как твоя охота?", completion = "Хмм... не думаю, что ты захочешь наняться ко мне в помощники, так ведь?\n\nХе-хе-хе! Да шучу я. Староват ты для этого, да и заметно, что у тебя на роду совсем другое написано. Благодарю тебя за помощь. Шкуры отменные – как раз подойдут мне для работы!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГибкие плетеные поножиЭластичное пончо\n\nВы также получите:\n\nРецепт: суп из кроколиска"},
[472] = {title = "Падение Дун Модра", objective = "Отыщите Грима Длинную Косу возле Дун Модра.", description = "Дворфы Черного Железа захватили Дун Модр!\n\nЯ тяжело ранен, <класс>. Почти все мои однополчане погибли! Подонки из клана Черного Железа набросились на нас, не успели мы оправиться после взрыва.\n\nНаш командир, Длинная Коса, протрубил сигнал к отступлению. Во время бегства мне в спину попал топорик. Я потерял сознание...\n\nОчнулся уже в Менетиле, но меня волнует судьба остальных солдат. Надежда умирает последней... Может быть, Длинная Коса тоже спасся! Иди в Дун Модр и отыщи его, <раса>!", progress = nil, completion = "Какие новости из Менетила принес нам добрый |3-6(Охотник)? Так-так-так, значит, тебя зовут Бронгард. Приятно познакомиться.\n\nЧто ж, весть добрая. Слава Свету, что молодой Харло выжил. Ранение у него было очень тяжелое, и нам пришлось отправить его в город на единственном уцелевшем скакуне.\n\nОднако в целом ситуация безнадежная: Дун Модр пал, а от нашего славного полка остались лишь воспоминания.", rewards = "Вы получите:\n\n"},
[473] = {title = "Доклад капитану Крепкому Кулаку", objective = "Найдите капитана Крепкого Кулака и поговорите с ним.", description = "<имя>. Орки из клана Драконьей Пасти совсем озверели. Им уже мало одного Альгаза. Капитан Крепкий Кулак просил направлять к нему всех, кто готов оказать нам содействие в войне против орков. Он сейчас в крепости, в зале Войны.", progress = nil, completion = "Rainon. Валстаг вкратце рассказал мне о твоих победах над орками Драконьей Пасти в Дун Альгазе. Ты – достойный |3-6(Человек). Нам такие нужны.\n\nИ у меня уже есть для тебя поручение.", rewards = "Вы получите:\n\n"},
[474] = {title = "Убить Нек'роша", objective = "Убейте вождя Нек'роша.\n\nПринесите голову Нек'роша капитану Крепкому Кулаку.", description = "Катапульты сожжены. Теперь найди и убей вождя Нек'роша.", progress = "Ты уже убил Нек'роша?", completion = "Чистая работа, Rainon. Ты нанес сокрушительный удар оркам из клана Драконьей Пасти. Они еще не скоро оправятся от него. К тому же их катапульты больше не угрожают Гавани Менетилов.\n\nТы – достойный |3-6(Человек), а Стальгорн не забывает о героях! Вот твоя награда.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДревний боевой мечОбдирающий жнец\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[475] = {title = "Ветер тревоги", objective = "Найдите Гароласа Талветрена в Деревне Звездного Ветра.", description = "Ветер тревоги веет над лесом.\n\nГэролас Талветрен служит Великим смотрителем за спящими друидами-воронами в обители Бен'этиль. Его долг – обеспечивать их безопасность, дабы их уговор с Изерой оставался в силе.\n\nНо вести от Гэроласа что-то задерживаются, и я начинаю волноваться. Отправляйся на восток в Деревню Звездного Ветра – мне нужен отчет Гэроласа, дабы я был спокоен, узнав, что мои братья и сестры спят спокойно.", progress = nil, completion = "Хвала лесным духам, ты здесь! Я знал, что Атридас забеспокоится и пришлет помощь.", rewards = "Вы получите:\n\n"},
[476] = {title = "Порча Кривой Сосны", objective = "Вернитесь к Атридасу Медвежьей Шкуре в Доланаар.", description = "Племя Кривой Сосны поражено порчей!\n\nЭти некогда мирные фурболги обратились против покровителей леса. Они подстерегли меня в засаде, когда я выходил из обители Бен'этиль и разграбили Деревню Звездного Ветра. Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны.\n\nЯ слишком изранен, чтобы донести до Атридаса эти страшные вести. Теперь это придется сделать тебе, <юный/юная:c> <класс>. Остается только надеяться, что безумные фурболги Кривой Сосны еще не уничтожили Бен'этиль!", progress = nil, completion = "Клянусь звездами! Воистину тревожные вести!", rewards = "Вы получите:\n\n"},
[477] = {title = "Пересечение границ", objective = "Раздобудьте содержимое одного из сундуков даларанских волшебников. Деревня Погребальных Костров находится на юге.", description = "Как вы, должно быть, знаете, в деревне Янтарная Мельница окопалась враждебная группа людей. Она держится там в основном за счет поддержки, которую они получают от волшебников Даларана. \n\nЯ не знаю, что они замышляют, но сам по себе интерес, проявленный ими к захолустной деревушке вроде Янтарной Мельницы, показывает, что она имеет немаленькое значение. \n\nОни отправляют повозкой из Хилсбрада сундуки. Многое из привезенного складируется в небольшом лагере к северу от деревни Погребальных Костров. Раздобудьте содержимое одного такого сундука и принесите мне.", progress = nil, completion = "*С любопытством открыв крышку ящика, вы находите в нем множество тщательно упакованных предметов. На самом верху лежит связка пожелтевших от времени карт, на которых, судя по всему, изображено Серебряный бор и другие области западного Лордерона. \n\nПод картами обнаруживается подвеска таинственно-волшебного вида.*", rewards = "Вы получите:\n\n"},
[478] = {title = "Карты и руны", objective = "Отнесите странную подвеску жрецу Тьмы Алистеру в Гробницу.", description = "*Вы быстро вытаскиваете подвеску из сундука и кладете крышку на место.*", progress = "Узнали что-нибудь полезное, Гронгард?", completion = "Карты и эта... эта подвеска? Интересно. \n\nОчевидно, что волшебники Даларана почему-то интересуются Янтарной мельницей, но их цель по-прежнему остается неизвестной. \n\nМожет быть, Далар сможет выяснить, что они там ищут.", rewards = "Вы получите:\n\n"},
[479] = {title = "Расследование в Янтарной Мельнице", objective = "Добудьте 8 подвесок Даларана и отнесите  жрецу Тьмы Алистеру в Гробницу.", description = "Далар пытается выяснить, каков источник магической силы этих волшебников. А пока что нам нужно замедлить их прогресс любым путем... \n\nМаги, окудники и заступники, несомненно, носят такие подвески. Добудьте их. \n\nЧтобы добраться до Янтарной Мельницы, идите на юг по главной дороге, а на развилке сверните на восток.", progress = "Надо торопиться, нельзя дать их планам претвориться в жизнь – или мы можем перестать владеть Серебряным бором.", completion = "Далар выяснил, что несмотря на замедление, процесс плетения чар зашел уже далеко. \n\nНекий очень могущественный волшебник направляет магическую энергию. Его нужно как можно скорее остановить.", rewards = "Вы получите:\n\n"},
[480] = {title = "Ткач", objective = "Убейте даларанского верховного мага, заберите его посох и отнесите жрецу Тьмы Алистеру в Гробницу.", description = "Верховный маг огромной силы отвечает за реактивацию энергетического узла. Они уже далеко зашли, так что единственный способ их остановить – это убить его. Это будет тяжело – безусловно, его защищают многочисленные маги и охранники. \n\nВам надо пойти и разобраться с ним, быстро. Когда он будет мертв, принесите мне его посох. Идите немедленно.", progress = "Быстрее, время на исходе, Соулнце!", completion = "Магия волшебников рассеивается, и энергетические узлы вновь засыпают. Ваши усилия оказались плодотворными, Соулнце, и мы сумели нанести нашим врагам и могучим волшебникам Даларана серьезный удар. \n\nОднако нужно не терять бдительности – ведь источник энергии находится совсем близко... Нужно разрабатывать планы на будущее.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКенарийский жезлМаскировочный мундир\n\nВы также получите:\n\n"},
[481] = {title = "Анализ Далара", objective = "Отнесите подвеску рунной надписи Далару Ткачу Рассвета в Гробницу.", description = "Отнесите подвеску Далару Ткачу Рассвета – может быть, он сможет пролить какой-то свет на планы волшебников.", progress = "Слушаю вас, |3-6(Чернокнижник). Что это?", completion = "Интересно – похоже, новые махинации Кирин Тора. Это могущественный артефакт. Такие часто использовали могучие волшебники Кирин Тора для передачи магической энергии. \n\nТо, что они так много таких вещиц доставляют в Янтарную Мельницу, указывает на то, что затевается что-то серьезное. \n\nПосмотрим, сумею ли я проникнуть сквозь защиту и поточнее разузнать об их намерениях.", rewards = "Вы получите:\n\n"},
[482] = {title = "Планы Даларана", objective = "Поговорите с жрецом Тьмы Алистером в Гробнице.", description = "Конечно! Как же я мог забыть?\n\nЯнтарная Мельница была одним из мест, отмеченных магами Кирин Тора, и примечательна тем, что на территории деревни находится спящий энергетический узел. Волшебники, должно быть, планируют реактивировать узел и использовать его энергию для какой-то более серьезной цели. \n\nМы не можем позволить этому случиться... \n\nЧтобы активировать энергии этого места, понадобится много сил, и мы можем осложнить им задачу, стащив у волшебников подвески. \n\nПередайте эту информацию Алистеру, он спланирует дальнейшие действия.", progress = nil, completion = "Вы принесли тревожные вести, Гронгард. Если Далар прав – а у меня нет оснований думать иначе – мы должны действовать быстро. \n\nМне нужно выработать совместно с ним план нашей атаки. А тем временем нужно замедлить их прогресс.", rewards = "Вы получите:\n\n"},
[483] = {title = "Реликвии Пробуждения", objective = "Добудьте реликвии Пробуждения и принесите их Атридасу Медвежьей Шкуре в Доланаар.", description = "Захватчиков Кривой Сосны видели в обители Бен'этиль на западе, они крушили там все подряд.\n\nСпящие друиды никогда не смогут выйти из Изумрудного Cна – они даже не понимают, в какую западню угодили, – если мы только им не поможем. Тонкий ритуал спячки нельзя нарушить без реликвий Пробуждения.\n\nОтправляйся в обитель и найди талисман Когтя Ворона, Черное перо, Небесный сапфир и руну Размещения. Друиды хранят их в священных ларцах. Принеси их мне, и я подготовлю ритуал пробуждения.", progress = "Анудорини, похищенные друиды-вороны навеки останутся в ловушке Изумрудного Сна, если мы не сумеем добыть реликвии Пробуждения из обители Бен'этиль, что на западе отсюда.\n\nЧем дольше мы медлим, тем неизбежнее их рок.", completion = "Тебе удалось это сделать, юный |3-6(Друид)! Славно! И как раз вовремя.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛубяные поножиПосох из обдирай-корня\n\nВы также получите:\n\n"},
[484] = {title = "Шкуры молодых кроколисков", objective = "Принесите 4 шкуры молодых кроколисков Джеймсу Халлорану в Гавань Менетилов.", description = "Ты, наверное, $Gслышал:слышала; обо мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему континенту!\n\nУже <встречался/встречалась> с Эйнаром? Он – один из охотников, приносящих мне шкуры.\n\nВ последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков.\n\nУчитывая обстоятельства, я готов заплатить высшую цену за стопку шкур. Молодые кроколиски водятся на болотах прямо за городом.", progress = "Wrestlecake, я ведь тебя посылал за шкурами? Где же они?", completion = "Отлично, превосходно! Прекрасные шкуры, Wrestlecake! Надо немедленно замочить их... но перед этим я хотел бы попросить тебя еще об одной услуге. Думаю, ты справишься.", rewards = "Вы получите:\n\n"},
[485] = {title = "Найти КПХ-9/HL!", objective = "Отнесите аварийный маяк к автономному роботу Карлса. Робот находится во Внутренних землях, в устье реки близ Осклизлой скалы.", description = "Вы обнаружили странный металлический предмет яйцевидной формы. Когда вы нажали на какую-то кнопку, яйцо вдруг ожило, открылось и превратилось в непонятный механизм, который проскрежетал механическим голосом:\n\n\"Меня зовут Карлс Пропеллерз, и мой автономный робот поврежден. Просьба найти робота, вставить в него этот маяк, а потом вернуть мне за вознаграждение\".\n\n\"Я вычислил координаты робота – он попал в аварию в устье реки близ Осклизлой скалы\".", progress = "Больше всего это похоже на обломки... механического цыпленка. Изнутри яйца снова раздается голосок: \"Да, отличная работа! Это мой автономный робот. Сенсоры показывают, что без подзарядки он не заведется и не долетит в Пиратскую бухту на починку... Иди вперед и положи маяк в робота – дальше он сам все сделает!\"", completion = "Вы помещаете яйцевидный аварийный маяк в механического цыпленка.\n\nС гудением и жужжанием робот поднимается на ноги, после чего из его механических внутренностей слышится голос Карлса:\n\n\"Что ж, по крайней мере, OOX-09/HL работает, но ему требуется капитальный ремонт! Он тяжелый, и нести его ты не сможешь, но вообще у меня есть одна мысль... Не хочешь ли присмотреть за ним еще немного?\"", rewards = "Вы получите:\n\n"},
[486] = {title = "Урсал Изверг", objective = "Убейте Урсала Изверга и возвращайтесь к Атридасу Медвежьей Шкуре в Доланаар.", description = "Настало время спасти друидов-воронов. Если сейчас мы потерпим неудачу, <имя>, их сон станет вечным.\n\nЯ подготовлю реликвии Пробуждения и совершу обряд. Но чтобы у меня все получилось, тварь, виновная в их злоключениях, должна быть уничтожена. Только тогда ритуал может быть выполнен.\n\nЭто Урсал Изверг разрушил дело наших братьев, и именно он должен теперь заплатить за свои злодеяния ради их освобождения. Отправляйся в Лагерь у Кривой Сосны на юго-западе и убей его.", progress = nil, completion = "Айлерон, ты проявил себя как весьма достойный и способный |3-6(Паладин). человек, следующий путем чести столь же неустанно, как ты, обязательно обретет великую славу в этом мире.\n\nДа будут благосклонны к тебе лесные духи всюду, куда бы ни завели тебя твои странствия.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТопор защитникаКорнешиповая дубина\n\nВы также получите:\n\n"},
[487] = {title = "Дорога в Дарнасс", objective = "Убейте 6 душителей из племени Кривой Сосны и найдите часового Амару Ночную Странницу возле Доланаара.", description = "Дорогу в Дарнасс нужно охранять. Путники, направляющиеся из Доланаара в Дарнасс, рассказывают о варварских нападениях пораженных порчей фурболгов из племени Кривой Сосны.\n\nКаждый день из Дарнасса и в Дарнасс поступают грузы и важные сообщения. Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам.\n\nВозьмись же за оружие во имя священного леса, <класс>. Их логово находится где-то под этим наблюдательным пунктом. Убей 6 душителей из племени Кривой Сосны и возвращайся ко мне.", progress = "На дороге все еще неспокойно, |3-6(Охотник). Ступай же и убей 6 душителей из Кривой Сосны, а потом возвращайся ко мне.", completion = "Ты славно послужил доброму народу Доланаара и Дарнасса, отважный |3-6(Друид). От имени всех часовых Тельдрассила воздаю тебе хвалу.", rewards = "Вы получите:\n\n"},
[488] = {title = "Просьба Зенна", objective = "Принесите Зенну Грязному Копыту, стоящему недалеко от Доланаара, 3 клыка ночного саблезуба, 3 пера островной совы и 3 мотка паутины чащобного тенетника.", description = "Вижу, ты работенку ищешь? Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце <наивному юнцу/наивной девчушке>... вроде тебя.\n\nВидишь ли, <имя>, я могу осчастливить тебя такими вещицами, что тебе и не снились. Но за это ты кое-что мне принесешь.\n\nМне часто бывают нужны определенные... ингредиенты. Принеси 3 клыка ночного саблезуба, 3 пера островной совы и 3 мотка паутины чащобного тенетника.\n\nИ пусть это все останется между нами, <раса>.", progress = "Ну что, Радиум, не запыхался? А я все думал, когда же ты принесешь то, что мне нужно…", completion = "Ха-ха! Хорошая работенка!\n\nКто бы мог подумать, что на меня, Зенна Грязное Копыто, будет работать |3-6(человек)? Я даже мечтать об этом не мог! Но раз уж так вышло... Наш милый мир полон неожиданностей.\n\nОбманули дурака на четыре кулака!", rewards = "Вы получите:\n\nОтломанный коготь Вуду"},
[489] = {title = "Искупление вины", objective = "Соберите 3 шишки Скверны и отдайте их Зенну Грязному Копыту близ Доланаара.", description = "Совет Леса узнал, что ты <помог/помогла> Зенну Грязному Копыту! Этот сатир – враг леса! И ты, как <раса>, <должен бы/должна бы> понимать, что оскверняешь лес, убивая созданий Природы!\n\nТы <должен/должна> искупить свою вину перед Советом, если хочешь оставаться другом Тельдрассилу! \n\nПреподай Грязному Копыту урок – и заслужишь прощение. Есть такие шишки Скверны – это семена, падающие с деревьев. Они испускают зеленый дым.\n\nСкорми несколько штук Грязному Копыту. Он подумает, что ему предлагают что-то вкусненькое.", progress = "Ой, Анудорини, ты мне что-то принес? Видать, что-то вкусненькое?", completion = "Ну что ты за лапочка! Я знал, что ты мне еще пригодишься!", rewards = "Вы получите:\n\n"},
[491] = {title = "Жезл для Бетора", objective = "Отнесите Сплетенный жезл Бетору Ледострелу в Квартал Магов Подгорода.", description = "Туле как-то рассказывал мне, что давным-давно он вместе с двумя товарищами создал магический жезл, сплетя его из трех принадлежащих им ученических жезлов. Он был символом их дружбы, и, хотя Тул презрел ее, с жезлом он расстаться не мог и не желал отдавать его другим. Поэтому он выкрал жезл и спрятал его в крепости Фенриса.\n\nЗдесь. Отнесите жезл Бетору Ледострелу, одному из прежних друзей Тула. Я уверен, он будет рад его получить.", progress = "Вота, ты сразил Тула Когтя Ворона?", completion = "... Что это?! У Туле был наш Сплетенный жезл? Я думал, он пропал, когда наша дружба пошла прахом, и Туле примкнул к Королю-личу! \n\nДолжно быть, он не обращался к силе жезла, потому что если бы он сделал это, я бы почувствовал. И хорошо, что Тул не использовал жезл... \n\nЭто удивительная находка. Я признателен за нее, Вота, и вознагражу тебя.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nИстоптанные брюкиРваные кольчужные перчаткиЗубчатый нож\n\nВы также получите:\n\n"},
[492] = {title = "Новая чума", objective = "Отнесите особый напиток Юхана пленному горному пехотинцу.", description = "Страж смерти сообщил, что недавно был захвачен еще один дворф-горный пехотинец. Стражи смерти обычно сажают пленных в погреб таверны \"Петля Висельника\", где им оказывается \"достойный прием\".\n\nПочему бы вам не пойти и не угостить пленника специальным напитком, который я приготовил? В нем есть небольшая примесь того, что Темная Госпожа готовит для всего Азерота.", progress = "Будь у меня моя верная винтовка, вы были бы уже мертвы, |3-6(Маг)! Погодите, скоро мне на помощь приедет бригада паровых танков!", completion = "Ах, наконец-то питье! Хоть это и не \"Болтливое пиво\", но я рад хоть чем-то промочить горло.", rewards = "Вы получите:\n\n"},
[493] = {title = "Путешествие в предгорья Хилсбрада", objective = "Отнесите находки аптекаря Ренферрела аптекарю Лидону в деревню Мельница Таррен в предгорьях Хилсбрада.", description = "Темная Госпожа давит на Королевское фармацевтическое общество, чтобы оно поскорее разработало Новую чуму. Мы упорно трудимся и добились значительного прогресса. Мы уверены, что успех был бы достигнут значительно быстрее, если бы мы могли распространять информацию среди членов общества. \n\nПоэтому я хотел бы, чтобы вы доставили мои последние находки аптекарю Лидону в Мельницу Таррен – небольшой городок, расположенный в предгорьях Хилсбрада. Путь туда неблизкий. \n\nНаправляйтесь на юг и держитесь поближе к дорогам. Строго следуйте дорожным указателям!", progress = "У вас ко мне какое-то дело?", completion = "А, отлично. Я в высшей степени уважаю аптекаря Ренферрела. Сгораю от нетерпения начать изучение его работы.", rewards = "Вы получите:\n\n"},
[494] = {title = "Время нанести удар", objective = "Отправляйтесь в Мельницу Таррен и доставьте послание стража смерти Леш верховному палачу Дарталии.", description = "Молчи и слушай, <класс>.\n\nМеня направили сюда для наблюдением за городом Хилсбрадом. У меня разведывательная миссия. А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен. Скажи, что страж смерти Леш передала следующие слова:\n\n\"Крик ворона на западе манит.\"\n\nСтупай по дороге на восток и обращай внимание на знаки. Торопись! Ступай в Мельницу Таррен со всей возможной скоростью!", progress = nil, completion = "Крик ворона на западе манит?\n\nОтличные новости! Пора напасть на Хилсбрад. Мы сможем воплотить наш план уничтожения жизни. Вариматрас будет доволен.", rewards = "Вы получите:\n\n"},
[495] = {title = "Корона Воли", objective = "Поговорите с Мелизарой в Мельнице Таррен в предгорьях Хилсбрада.", description = "Муг'тола и его отряд огров отправили в долину Альтерака за короной Воли для леди Сильваны. К сожалению, вместо того чтобы принести ее королеве, этот идиот решил ее примерить... наверное, огры не могут устоять перед блестящими побрякушками.\n\nЕго необдуманный поступок привел к неприятным последствиям. Корона Воли позволила Муг'толу воспротивиться заклинанию подчинения, наложенному на него леди Сильваной.\n\nТемная Госпожа хочет, чтобы это стало уроком для остальных. Отправляйся на мельницу Таррен в Хилсбраде и поговори с лейтенантом Мелизарой.", progress = nil, completion = "Тебя прислала Шарлиндра? Ну хорошо. Вскоре ты поймешь, что я не терплю пустой болтовни.\n\nМуг'тол – наглец, и с ним мы разберемся быстро, тщательно и безжалостно.", rewards = "Вы получите:\n\n"},
[496] = {title = "Эликсир Страдания", objective = "Аптекарь Лидон с мельницы Таррен попросил принести ему 10 языков серых медведей и немного лимфы паука-охотника.", description = "Ах, еще один мерзкий день на мельнице Таррен. От этого чистого воздуха у меня сразу портится настроение, <имя>.\n\nЧем скорее мы заразим здешних людей, тем лучше. Я провожу исследования различных смертоносных веществ, чтобы использовать их в моих составах, но собрать все времени не хватило.\n\nЕсли ты хочешь принести пользу, добудь для меня следующее: 10 языков серых медведей и очень редкую и труднодоступную лимфу паука-охотника. Медведи и пауки-охотники живут рядом с мельницей Таррен.", progress = "Я вижу, ты вернулся. Надеюсь, тебе удалось собрать нужные мне вещества. Еще один день без единой смерти совсем в тоску меня вгонит.", completion = "Отличные компоненты. Что ж, Ахахаха, ты умудрился внести хоть немного радости в мой тоскливый день. Благодарю тебя.", rewards = "Вы получите:\n\n"},
[498] = {title = "Спасение", objective = "Освободите Друлла и Тог'тара по поручению Круска с мельницы Таррен.", description = "Вождь послал нас с ребятами, чтобы добыть кое-что из Дарнхольда и разведать, что представляет собой так называемый Синдикат.\n\nМы пошли к Дарнхольду, поглядели, что к чему, тут на нас и напал большой отряд людей. Мы бились изо всех сил, но они сильно превосходили нас числом. В конце концов нескольких из нас взяли в плен, но мне удалось сбежать.\n\nДарнхольд находится на юго-востоке отсюда, по ту сторону реки. Там держат Друлла и Тог'тара, освободи их.", progress = "Торопись, |3-6(Маг). Мне страшно подумать, что люди могут сделать с Друллом и Тог'таром.", completion = "Значит, люди собирались поработить наших воинов? Мы еще им покажем!\n\nПохоже, они захватили Гол'дира, нашего вождя, и держат его в другом месте. Его тоже необходимо отыскать и спасти. Впрочем, пока неизвестно, где он…\n\nКогда у нас появится хоть какая-то зацепка, я немедленно скажу об этом тебе, Ахахаха.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖилет рубакиОркская боевая кольчуга\n\nВы также получите:\n\nРецепт: стейк из мяса большого медведя"},
[499] = {title = "Эликсир Страдания", objective = "Дайте Ампи эликсир Страдания.", description = "Мне понадобится совсем немного времени для создания того, что я хочу наречь эликсиром Страдания.\n\nВот, готово! Ах, ничто не доставляет столько радости в этих проклятых холмах, как принесение страдания в мир.\n\nПосмотрим, достигнут ли желанный эффект.\n\nДай попробовать моему помощнику Ампи то, что Темная Госпожа готовит людям и созданиям Плети.", progress = "Ква!", completion = "Квак!", rewards = "Вы получите:\n\n"},
[500] = {title = "Награда Раздробленного Хребта", objective = "Соберите 9 грязных бабок у огров из клана Раздробленного Хребта в Альтеракских горах. Принесите их маршалу Крассену в Южнобережье.", description = "Огры из клана Раздробленного Хребта раскопали курган в Альтеракских горах, неподалеку от разрушенного города. Разведчики доносят, что они и сами руины захватили.\n\nМы не дадим им там вольготно расположиться; если они решат, что хорошо устроились, то следующим шагом спустятся с холмов и окажутся прямо рядом с нами!\n\nСтупай на север, в Альтеракские горы и убей побольше огров. Принеси мне грязные бабки – кости, которые они таскают с собой, и получишь неплохую награду.", progress = "Ну как, Wrestlecake, ты охотишься на огров? Удалось собрать из бабки?", completion = "Отлично, Wrestlecake. Должно быть, тебе пришлось зарубить целые полчища, чтобы набрать столько бабок.\n\nТеперь они к нам не сунутся. По крайней мере, некоторое время.", rewards = "Вы получите:\n\n"},
[501] = {title = "Эликсир боли", objective = "Принесите 10 сосудов крови горного льва аптекарю Лидону с мельницы Таррен.", description = "О, <имя>... Луга Хилсбрада полны цветов, воздух свеж и приятен. Меня от этого просто тошнит! Я смотрю в мутное окно и мечтаю о наступлении дня, когда Новая чума принесет в мир заслуженную смерть!\n\nНо как бы мне ни хотелось сидеть и мечтать – прежде всего приказы Темной Госпожи. Помоги мне! В результате исследований я обнаружил, что из крови горного льва можно создать великолепный напиток смерти. Принеси мне немного крови, и мы повеселимся.", progress = "Я помню тебя, Ахахаха. Ты собирался помочь мне составить последний эликсир. Мне нужна кровь горного льва, и я внесу новую толику страдания в жизнь обитателей Хилсбрада.", completion = "Отличная работа, Ахахаха.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки БраунаПоходные сапогиСапоги Огнехода\n\nВы также получите:\n\nРецепт: острая отбивная из мяса льва"},
[502] = {title = "Эликсир боли", objective = "Напоите Стэнли эликсиром Боли.", description = "Ах, ничто так не радует, как запах свежей крови в предгорьях!\n\nСмешаем капелюшку этого и щепотку того, и пойдет веселье! Из этой крови я сделаю эликсир Боли. Если мои вычисления верны, то этот состав порадует леди Сильвану. Надо его испытать.\n\nОтнеси этот эликсир на самую северную ферму Хилсбрадских полей, что на юго-западе. Посмотрим, как мое \"угощение\" понравится собачке фермера Рея, Стэнли.", progress = "Ав?", completion = "Вы наливаете немного эликсира в ладонь и протягиваете ее Стэнли.", rewards = "Вы получите:\n\n"},
[503] = {title = "Гол'дир", objective = "Освободите Гол'дира и возвращайтесь к Круску в Мельницу Таррен.", description = "Судя по добытым тобой документам, Гол'дира держат на большой базе Синидиката, расположенной на севере, вероятно, в Альтеракских горах. Он уж очень давно томится там в плену, пора освободить его.", progress = "Дай мне ключ, |3-6(Охотник), и я сам отомкну замок.", completion = "Спасибо, Томпсон. По приказу Вождя я вел экспедицию из Дуротара, но, как видишь, наши планы несколько нарушились. Меня держали в плену в этом городе, заставляя работать – таскать тяжести и копать…\n\nВпрочем, неважно, что мне пришлось вынести. Куда важнее сведения, которые тебе необходимо доставить тем, кто сейчас возглавляет нашу группу.", rewards = "Вы получите:\n\n"},
[504] = {title = "Наемники клана Раздробленного Хребта", objective = "Убейте 15 солдат-наемников из клана Раздробленного Хребта и возвращайтесь к маршалу Редпату в Южнобережье.", description = "Ты уже <померился/померилась> силой с ограми Раздробленного Хребта, а теперь я хочу нанести им настоящий удар…\n\nСтупай в руины Альтерака и отыщи там наемников из клана Раздробленного Хребта. Убей побольше этих тварей – только так им можно показать, что лучше держаться подальше от земель Альянса.", progress = nil, completion = "Очень хорошо. Вот награда.\n\nКстати, охотясь на огров ты видел город Альтерак. Как он выглядит? Боюсь, что скверно. Огры не славятся своей чистоплотностью.\n\nК счастью, благодаря твоим усилиям они будут держаться подальше от Южнобережья.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГорящая щепкаЛунный кулачный щит\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[505] = {title = "Убийцы из Синдиката", objective = "Убейте 12 преступников и 8 воров Синдиката и возвращайтесь к чиновнику Генри Малебу в Южнобережье.", description = "Меня недавно назначили чиновником в Южнобережье. Моего предшественника убили, и виновников так и не нашли. Впрочем, расследование показало, что скорее всего их нанял Синдикат – группа воров под командованием злодеев-дворян, бывшей знати павшего королевства Альтерак.\n\nЛагерь Синдиката расположен на севере от занимаемой Ордой мельницы Таррен. Убей всех членов Синдиката, которых встретишь там.", progress = nil, completion = "Спасибо, Эфром. Хотя, быть может, они все еще шныряют неподалеку, будем надеяться, что некоторые из убитых воров и бандитов принимали участие в убийстве прежнего чиновника. Но даже если и нет, Синдикат – позор этой земли и человеческой расы.\n\nСмерть этих бандитов и воров – добрая весть для всего Южнобережья.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПояс рыцаряИзолирующие перчатки мудреца\n\nВы также получите:\n\n"},
[506] = {title = "Наследие Блэкмура", objective = "Отнесите собранные Гол'диром сведения Круску на мельницу Таррен.", description = "День или два назад ко мне пришел главарь этого Синдиката. Его звали Алиден Перенольд, и он нарек себя лордом этих земель. Он поверил мне свои планы о порабощении орков, выступивших против него, как и планировал его отец и учитель, ненавистный Блэкмур.\n\nКуда важнее то, что он привел с собой свою любовницу, девочку-тростинку по имени Элиза. У нее на шее висело ожерелье, который жаждет заполучить Вождь.\n\nСтупай, мне пора уходить, когда я закончу свои дела в лагере.", progress = nil, completion = "Надо же, какие наглецы эти люди! Мы покажем им, что орки не сдаются!\n\nОтныне это будет нашей целью наравне с тем украшением, которое стремится заполучить наш Вождь. Похоже, одной цели без другой не достичь.", rewards = "Вы получите:\n\n"},
[507] = {title = "Лорд Алиден Перенольд", objective = "Убейте лорда Алидена Перенольда и допросите его любовницу Элизу насчет ожерелья Тареты.", description = "Очевидно, что Перенольда необходимо убить, избавив мир от его гнусной сущности. Его поместье расположено к северу отсюда, на берегах озера Лордамер. Твой долг, <имя>, добыть медальон для Вождя и вернуться сюда.", progress = "Ч-что вам нужно?", completion = "Нет, прошу вас, не убивайте меня! Я не хотела причинять зло вашему народу, он взял меня против воли! Пожалуйста... Пощадите меня!", rewards = "Вы получите:\n\n"},
[508] = {title = "Подарок Тареты", objective = "Верните ожерелье Тареты Круску в деревню Мельница Таррен.", description = "Ожерелье? Конечно же, можешь его забрать... Да, забирай! Мне не нужны воспоминания о нем... Просто оставь меня в покое...", progress = "А, вот и ты, Томпсон. Сопутствовала ли тебе удача?", completion = "Странно, что вождь пошел на такие затраты ради этой мелочи. Я не всегда понимаю его мотивы, но я последую за ним, каковы бы ни были его приказы. Ты отлично поработал, Томпсон, и я не сомневаюсь, что вождь будет рад услышать о твоем успехе.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги богомолаНаплечье грабителя\n\nВы также получите:\n\n"},
[509] = {title = "Эликсир агонии", objective = "Принесите 6 цветков Грязного Рыла аптекарю Лидону с мельницы Таррен.", description = "Новый день, новый эликсир. Если бы я тут командовал, я бы позволил Плети и жалким людишкам сцепиться между собой. Им и так нравится убивать друг друга.\n\nУвы, Темная Госпожа хочет ускорить процесс, так почему бы не скрасить унылые дни распространением смерти и болезней по стране.\n\nВот мой план: иди-ка ты во Владение Нетандера на юге от мельницы Таррен и на востоке от реки и Южнобережья. Принеси мне 6 цветков Грязного Рыла для нового эликсира.", progress = "Как дела во Владении Нетандера?", completion = "А, отвратительная вонь цветков Грязного Рыла. Хоть для чего-то эти грязные гноллы годятся.", rewards = "Вы получите:\n\nЗелье скоростиЛечебное зелье"},
[510] = {title = "Зловещие планы", objective = "Отнесите зловещие планы чиновнику Южнобережья Малебу.", description = "Среди документов вы находите список необходимых припасов. В их число входят самые простые вещи (еда, оружие, одежда) и несколько необычные (маски, масло, яд).\n\nВпрочем, более всего привлекает внимание срочность запроса – согласно документу, доставить все необходимое следует как можно скорее, чтобы \"выполнить важную миссию, нацеленную против Южнобережья\".", progress = "Берш, вид у тебя обеспокоенный. Ты хочешь о чем-то рассказать?", completion = "*Малеб изучает документы.*\n\nДурные вести, Берш. Судя по сведениям, содержащимся в этих документах, и последним действиям Синдиката, эта банда головорезов объявила войну Южнобережью.", rewards = "Вы получите:\n\n"},
[511] = {title = "Зашифрованное письмо", objective = "Отнесите зашифрованное письмо хранителю мудрости Диббсу в Южнобережье.", description = "Одно из писем на столе зашифровано.", progress = "Да, господин? У тебя какое-то дело ко мне?", completion = "Что это? Минуточку... Дай-ка взглянуть поближе.\n\n...\n\nХм, никогда не встречался с таким шифром, но, признаться, в этой области я не очень сведущ.", rewards = "Вы получите:\n\n"},
[512] = {title = "Благородные смерти", objective = "Принесите 7 альтеракских перстней-печаток чиновнику Малебу в Южнобережье.", description = "Боюсь, что главари Синдиката жаждут гибели Южнобережья. Мы должны нанести удар первыми, пока они не успели воплотить свои планы.\n\nОтправляйся в руины Странбрада, в северной части Альтеракских гор. Мы полагаем, что именно там находится штаб-квартира Синдиката.\n\nНам известно, что эту шайку головорезов возглавляет бывшая знать Альтерака. Дворяне скрываются среди прочих посланников Синдиката, но отличить их можно по перстням-печаткам. Разумеется, прежде необходимо их убить.\n\nПринеси мне эти перстни.", progress = "Как охота на сторонников Синдиката? Где их перстни?", completion = "Лишившись знатных предводителей, Синдикат утратит волю к действию, превратившись в обычную банду разбойников.\n\nТы хорошо послужил Альянсу, Маладат.", rewards = "Вы получите:\n\n"},
[513] = {title = "Эликсир агонии", objective = "Отнесите состав Грязного Рыла мастеру-аптекарю Фаранеллу в Подгород.", description = "Я уже решил, что еще один день пройдет без капли радости, но тут ты <принес/принесла> мне цветки Грязного Рыла.\n\nДля начала я смешаю их и сделаю отличный состав. Потом нам понадобится помощь мастера-аптекаря Фаранелла из Подгорода. Он должен добавить туда коллоид разложения и тогда-то самое веселье и начнется!\n\nВот возьми этот состав Грязного Рыла и немедленно отнеси его мастеру-аптекарю Фаранеллу.", progress = "Видишь, я занят, |3-6(Маг)? Темная Госпожа велит вывести новую чуму, пока нас не одолела Плеть со стороны Нордскола. С юга же нас теснят люди, поэтому время сейчас – главная ценность. Надеюсь, ты не по пустякам меня тревожишь!", completion = "Тебя послал аптекарь Лидон? Что ж ты сразу не сказал!\n\nНевзирая на угрюмый нрав, аптекарь Лидон – один из наших самых преданных и умелых сотрудников.\n\nОн прислал состав Грязного Рыла, какой умница! Я знаю, что замышляет наш друг из Хилсбрада. И мне нравится ход его мысли. Темная Госпожа порадуется наступлению новой чумы.", rewards = "Вы получите:\n\n"},
[514] = {title = "Письмо Грозовой Вершине", objective = "Отнесите хитро зашифрованное письмо геологу Грозовой Вершине в Стальгорн.", description = "У меня есть коллега из Стальгорна, который может расшифровать это письмо. Ступай в Библиотеку в Зале Исследователей Стальгорна и поговори с геологом Грозовой Вершиной. Скажи ему, что тебя прислал я и покажи письмо. Если кто и может прочитать это во всех землях к северу от пика Черной горы, то это он.", progress = "Тебя прислал Диббс из Южнобережья? Как поживает старый книжный червь?", completion = "А, шифровка! Да, тут я спец. Дай-ка взглянуть...", rewards = "Вы получите:\n\n"},
[515] = {title = "Эликсир агонии", objective = "Отнесите микстуру Грязного Рыла, крепкое зелье тролльей крови, 5 чешуек нагов из клана Пронзающего Гребня и 5 глаз мурлоков из клана Рваный Плавник аптекарю Лидону в Мельницу Таррен.", description = "Состав Грязного Рыла? Гениально! Почему мне не пришло это в голову?\n\nПожалуй, я добавлю свой коллоид разложения в эту хитрую смесь.\n\nЧтобы активировать отраву в смеси, Лидону понадобится крепкое зелье тролльей крови, немного чешуи наги из клана Пронзающего Гребня и глаза мурлоков из клана Рваный Плавник с южного берега Хилсбрада. Когда ты принесешь ему все составляющие, он мигом все сделает. Ох, как мне не терпится узнать о результатах его эксперимента!", progress = "Я рад, что ты вернулся, Томпсон. Я уж совсем заскучал. Ни единого развлечения, сижу, травлю и заражаю Ампи, а потом воскрешаю ее. И так целый день.\n\nКак прошло путешествие в Подгород? Тебе удалось зарубить по дороге человечка-другого?", completion = "У меня даже голова закружилась от возбуждения! Какой эксперимент! Ты мне очень помог, Томпсон. Мы будем сеять болезнь и смерть по всем этим землям!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлащ верховного аптекаряКушак медитации\n\nВы также получите:\n\n"},
[516] = {title = "Погибель Берена", objective = "Найдите Погибель Берена, убейте 6 чернорабочих Когтя Ворона и 6 стражей Когтя Ворона, а затем вернитесь в Гробницу к жрецу Тьмы Алистеру.", description = "Я получил сообщение, что группа нежити спряталась и готовит атаку против нас. Вооруженные этой информацией, мы можем повернуть все другой стороной и напасть первыми, подавив их планы в самом зародыше. \n\nК сожалению, моя информация весьма обрывочная. Говорят, они скрываются в месте, называемом Погибель Берена. Точное местонахождение неизвестно, но, похоже, это пещера где-то в холмах, недалеко от участка, занятого даларанскими волшебниками. \n\nЯ доверяю вашей изобретательности. Отыщите их и нанесите им поражение.", progress = nil, completion = "Если наши разведчики и агенты продолжат предоставлять столь же ценную информацию, как эта, мы в мгновение ока очистим наши земли от армии Плети Короля-лича.", rewards = "Вы получите:\n\nЖезл Порчи"},
[517] = {title = "Эликсир агонии", objective = "Принесите бочонок \"Землекопского крепкого\" аптекарю Лидону с мельницы Таррен.", description = "Пришло время испытать новый эликсир. Но зачем же тратить хорошую, очень заразную болезнь на простых лягушек и собак? Давай устроим настоящее веселье во имя леди Сильваны.\n\nСтупай в Дун Гарок. Знаешь, это казармы, где вечно шныряют эти дворфики. Укради у них бочонок землекопского крепкого. Получив эту бочку, я устрою веселую вечеринку!", progress = "Иногда я впадаю в такую тоску в этом городишке, что открываю кувшин формальдегида и наслаждаюсь ароматом. Ампи начинает нервничать.\n\nНу что, удалось добыть бочку у дворфов? Честное слово, если я буду пялиться на этот эликсир целый день и ни на ком его не опробую, я закричу!", completion = "Наконец-то! Теперь мы готовы действовать!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[518] = {title = "Корона Воли", objective = "Убейте 14 извергов из клана Раздробленного Хребта по поручению Мелизары с мельницы Таррен.", description = "Муг'тол и огры Раздробленного Хребта захватили руины Альтерака. Наказать их всерьез будет нелегко, если не проредить сначала ряды огров.\n\nА уж потом мы продолжим.\n\nЯсно? Отлично. Выполняй.", progress = "Я вижу, что задание все еще не выполнено, Дэмрод. Сообщить ли мне Шарлиндре о твоей непригодности?", completion = "Снег стал алым от крови огров, но мы не должны останавливаться, пока не втопчем дух и тело огров Раздробленного Хребта в грязь и снег.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[519] = {title = "Корона Воли", objective = "Убейте Тарга, Навозера и Гломмуса и принесите их головы Мелизаре с мельницы Таррен.", description = "Тарг, Навозер и Гломмус – лейтенанты Муг'Тола. Они верны ему, хотя кто там разберет, что вынуждает огров быть верными.\n\nПринеси мне их головы, <имя>, и нам останется отрубить башку Муг'Толу вместе с короной.", progress = "Мне нужны их головы, а не оправдания.", completion = "...а я-то думала, что для начала огры зверски воняют.\n\nКогда ты принесешь мне голову Муг'Тола, я прикажу отнести ее вместе с этими на пики Альтерака. Неплохой памятник тем, кто идет против воли Темной Госпожи.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[520] = {title = "Корона Воли", objective = "Убейте Муг'Тола и принесите его голову и корону Воли Мелизаре на мельницу Таррен.", description = "Лейтенанты Муг'Тола мертвы, и нам остается только убить его самого и забрать корону Воли. Нет сомнений, ему не захочется с ней расставаться. Скорее всего, он ждет тебя, учитывая... уменьшение числа его товарищей.\n\nОтыщи Муг'Тола и принеси мне его голову вместе с короной. Положим конец сопротивлению Раздробленного Хребта.", progress = "Три головы у меня есть, а четвертой пока не видать. Это будет или голова Муг'Тола, или твоя. Уж поверь мне на слово.", completion = "Ты с честью выполнил свой долг, Томпсон. Голова Муг'Тола украсит высочайшую вершину среди руин Альтерака, и стражи смерти сотрут с лица земли остатки клана Раздробленного Хребта.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[521] = {title = "Корона Воли", objective = "Отнесите корону Воли Шарлиндре из Подгорода.", description = "Остается отнести корону Воли Шарлиндре в Подгород. Она уж передаст ее леди Сильване. Но даже не думай воспользоваться ей в личных целях, <имя>. Пусть тебе послужит уроком судьба Муг'Тола.", progress = "Да? О чем ты хочешь доложить?", completion = "Так значит, этой реликвией воспользовался огр, чтобы не исполнять волю Темной Госпожи…\n\nСтранно, когда в такой небольшой вещи заключается великая сила. Которая попала в такие неуклюжие руки. Молодец, Томпсон. Я отнесу корону леди Сильване и доложу ей о твоих подвигах.", rewards = "Вы получите:\n\nАстральный талисман"},
[522] = {title = "Контракт убийцы", objective = "Отнесите контракт убийцы чиновнику Малебу в Южнобережье.", description = "Это контракт на убийство мирового судьи Генри Малеба. Он был опечатан красным воском с характерным оттиском кольца.", progress = "Я смотрю, ты тяжело дышишь! Есть, о чем доложить?", completion = "*Малеб изучает контракт.*\n\nТеперь мне понятна подоплека последнего нападения на Южнобережье. Наверное, Синдикат хочет добраться до меня, как и до моего предшественника!", rewards = "Вы получите:\n\n"},
[523] = {title = "Смерть барона", objective = "Принесите голову барона Вардуса чиновнику Малебу в Южнобережье.", description = "Добытый тобой контракт был подписан бароном Вардусом, дворянином из бывшего королевства Альтерака, прославившегося холодным сердцем и необычайной жестокостью. Неудивительно, что за этим стоял барон.\n\nОтыщи его. Отыщи и сверши над ним суд. Должно быть, он прячется в одном из убежищ Синдиката – руинах Странбрада или долине на севере оттуда.", progress = "Пусть барон Вардус не надеется, что Южнобережье возволит ему безнаказанно подсылать к нам своих головорезов. Мне нужна его голова!", completion = "Спасибо, Маладат. У меня на душе полегчало, когда ты вышиб дух из этого злодея!", rewards = "Вы получите:\n\n"},
[524] = {title = "Эликсир агонии", objective = "Поставьте гниющий бочонок на ковер для плененных фермеров.", description = "За соседней дверью стражи смерти держат нескольких заложников-фермеров. Верховный палач Дарталия подозревает, что среди них скрывается один из военных-стратегов. Очевидно, его нашли мертвым в Чумных землях. Дарталия всегда заботится обо мне и решила передать пленников мне в руки.\n\nПора устроить этим фермерам вечеринку. Ох, повеселимся!\n\nПоставь гниющий бочонок на ковер у них в комнате. Чумной напиток для всех!", progress = "От ковра идет гнилостный запах.", completion = "Вы ставите гниющий бочонок на пыльный ковер.", rewards = "Вы получите:\n\n"},
[525] = {title = "Все больше тайн", objective = "Доставьте расшифрованное письмо чиновнику магистрата Южнобережья Малебу.", description = "Я расшифровал письмо, но не знаю, что с ним дальше делать. Вы нашли его у воров в предгорьях Альтерака? Очень странно...\n\nНадо доставить это письмо магистрату Южнобережья. Хотя письмо и зашифровано, это ближайший город к горам Альтерака, и если назревает какая-то опасность, то они должны об этом узнать.", progress = "Wrestlecake. Вы шли через предгорья и по горам? Какие вы принесли вести?", completion = "*Малеб читает письмо.*\n\nЭто расшифровка письма, найденного вами в лагере Синдиката? Оно написано не вором, и даже не альтеракским аристократом.\n\nПохоже, у Синдиката есть связи с другими силами, и мне страшно подумать, что это за силы могут быть.", rewards = "Вы получите:\n\n"},
[526] = {title = "Слитки светлостали", objective = "Найдите 5 слитков светлостали и вернитесь к Глорину Стальному Лбу в Болотину.", description = "Ты <нашел/нашла> только один слиток светлостали – этого не хватит, чтобы выковать что-нибудь стоящее.\n\nВернись и поищи еще слитки. Думается, их растащили мурлоки, разграбившие корабль.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[527] = {title = "Битва за Хилсбрад", objective = "Убейте 6 хилсбрадских батраков, 6 хилсбрадских фермеров, фермеров Рея и Гетца и возвращайтесь к Дарталии на мельницу Таррен.", description = "Когда говоришь со мной, стой по стойке \"смирно\", <класс>.\n\nЯ нахожусь под прямым командованием Вариматраса. Наша задача – сдерживать распространение людей, покуда аптекари работают над составом новой чумы.\n\nПо нашим сведениям город Хилсбрад очень уязвим. Твое первое задание – прервать снабжение едой и прочим.\n\nОтправляйся на запад. Устрой налет на самые северные фермы Хилсбрадских полей. И казни землевладельцев, фермеров Рея и Гетца.", progress = nil, completion = "Вольно, |3-6(Маг). Вижу, ты вернулся из боя. Мне доложили, что ты хорошо показал себя в Хилсбраде.", rewards = "Вы получите:\n\n"},
[528] = {title = "Битва за Хилсбрад", objective = "Убейте 15 хилсбрадских крестьян и вернитесь к Дарталии на мельницу Таррен.", description = "Слухи о нападении на северные фермы вызвали панику среди населения. Великолепно.\n\nНаши стражи смерти докладывают о крестьянах южного Хилсбрада, бегущих в поля. Эти глупцы надеются укрыться в садах, избежав гибели.\n\nПокажи им, как они заблуждаются, <имя>. Возвращайся в Хилсбрадские поля и отыщи там трусливых крестьян. Рази их направо и налево во имя Темной Госпожи.\n\n<Свободен/Свободна>!", progress = nil, completion = "Смерть все крепче сжимает костлявую руку на горле Хилсбрада. Битва идет хорошо.", rewards = "Вы получите:\n\n"},
[529] = {title = "Битва за Хилсбрад", objective = "Убейте кузнеца Верринтана и 4 хилсбрадских учеников кузнеца.\n\nПринести партию железа Дарталии на мельницу Таррен.", description = "Люди Хилсбрада оказывают нам неожиданное сопротивление. Кажется, проблема в кузнеце, снабжающем горожан оружием. Необходимо прервать цепь снабжения.\n\nУбей кузнеца Верринтана вместе с учениками и возвращайся с партией железа. Нам оно пригодится, когда мы одержим победу над Хилсбрадом и нападем на Южнобережье.", progress = "Удалось ли тебе выполнить приказ, |3-6(Воин)? Мертв ли кузнец Веррингтан и его подмастерья? И где партия железа?", completion = "Задание выполнено, |3-6(Воин). И, надо сказать, выполнено на славу.", rewards = "Вы получите:\n\n"},
[530] = {title = "Месть мужа", objective = "Убейте Валдреда Морая.\n\nПринесите его руки Роли Андреану в Подгород.", description = "Когда-то Валдред был моим лучшим другом, а потом убил мою жену. Горевать я уже не способен, но до сих пор жажду мести. Если ты убьешь Валдреда и принесешь мне его проклятые руки, я тебя награжу.\n\nПо последним слухам, он был у Стены Седогрива в южном Серебряном бору. Небось, пытается сбежать в королевство Гильнеас.", progress = "Где его руки, Кзар?", completion = "А, хорошо. Этими руками была убита моя жена, Делия. С тех пор я думал только о мести, и вот ты стал моим оружием.\n\nВозьми кольцо, которое вернул мне ранее. Делия так давно умерла, что я не нуждаюсь в этой безделушке. Лучше я оставлю себе эти руки в память о предательстве друга.", rewards = "Вы получите:\n\nКольцо Пренебрежения"},
[531] = {title = "Месть Вайрины", objective = "Принесите голову Старины Черношкура Вайрине Быстрый Ветер в Приют странников.", description = "Ради всего святого! Не приноси в Приют такое... это негигиенично, неприлично, не... не... негигиенично!\n\nСкорее убери ее отсюда! Никому здесь не нужны твои страхолюдные трофеи!", progress = "Молодец, Вйнсент! Мы его хорошенько проучили! Дай мне голову, я сама ей займусь.", completion = "Спасибо, что помог мне выполнить мой маленький план. Я много месяцев жаждала проучить этого надутого самовлюбленного мальчишку, а теперь нам это удалось! Вот, возьми, ты это заслужил.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОхотничья сумка для боеприпасовОхотничий колчан\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[532] = {title = "Битва за Хилсбрад", objective = "Убейте мирового судью Бернсайда и 5 членов совета Хилсбрада. Уничтожьте Хилсбрадское официальное объявление. Украдите регистрационную книгу Хилсбрада. Возвращайтесь к Дарталии на мельницу Таррен.", description = "В Хилсбраде царит паника. Думаю, он скоро падет. Но мы не должны ослаблять натиск, пока последние человеческие отродья не изжиты из этих холмов навеки.\n\nНевзирая на колоссальные потери, люди держатся вокруг своих вождей и не кладут оружия. Мы должны уничтожить их главу, чиновника Бернсайда, и весь городской совет. Заодно уничтожь и их главный документ, Хилсбрадское официальное объявление. И раз уж на то пошло, укради и городскую книгу регистрации.", progress = "Какие вести ты несешь?", completion = "Вести о твоих победах в Хилсбраде быстро разносятся. Отличная работа, |3-6(Воин).", rewards = "Вы получите:\n\n"},
[533] = {title = "Шпионская работа", objective = "Добудьте сведения о местонахождении Гол'дира для Круска с мельницы Таррен.", description = "Наконец-то до нас дошли сведения о местопребывании Гол'дира. Люди постоянно меняли места его заключения, но мы смогли сузить область поиска до большого лагеря Синдиката на севере отсюда.\n\nСтупай туда, <имя>, и заполучи все доступные сведения.", progress = "Ну как, удалось что-нибудь узнать? Боюсь, надежды для Гол'дира все меньше и меньше...", completion = "Наконец-то мы знаем, где держат Гол'дира. В лагере неподалеку отсюда. Будем надеяться, что на сей раз они не успеют подготовиться как прошлый раз, когда нас застали в расплох.", rewards = "Вы получите:\n\n"},
[535] = {title = "Валлик", objective = "Принесите кружку эля из Южнобережья Вэллику в лагерь Синдиката.", description = "Гр-рр... Раненый, умирающий, но не опускающий оружия.\n\nНе сомневаюсь, ты все равно убьешь меня, но если бы ты <принес/принесла> мне немного эля из Южнобережья – вы ведь такое тоже пьете? – я расскажу тебе то, что ты хочешь знать.", progress = "Так что, ты принес мне чего-нибудь выпить или $gпришел:пришла просто покончить со мной?", completion = "Принимая во внимание мою неминуемую смерть – думаю, могу с уверенностью сказать, что это самый вкусный напиток в моей жизни... Вот, возьми – когда я помру, мне это все равно не понадобится. \n\nНу, слушай!", rewards = "Вы получите:\n\nПослание Синдиката"},
[536] = {title = "На побережье", objective = "Убейте 10 волноловов из племени Порванного Плавника и 10 оракулов из племени Порванного Плавника по поручению лейтенанта Фаррена Оринеля из Южнобережья.", description = "Меня перевели в Южнобережье из городской стражи Штормграда. Непонятно, как тут вообще люди живут... А как воняет со стороны пристани и днем и ночью!\n\nДа еще старый Редпат на мою голову... Он хочет, чтобы я занялся мурлоками. Ха!\n\nЯ едва могу заставить себя подойти к этим рыбам-переросткам на Западном побережье. Если ты разберешься с ними вместо меня, я буду очень признателен.", progress = nil, completion = "Надеюсь, этого хватит, чтобы убедить Крассена, что я – ха! – выполняю его приказы и избавляю Южнобережье от страшной и ужасной угрозы, жутких мурлоков! Нет ничего страшнее ярости рыбы-переростка!", rewards = "Вы получите:\n\n"},
[537] = {title = "Темный совет", objective = "Убейте 4 темных магов Недремлющего Аргуса.\n\nПринесите голову Нагаза мировому судье Южнобережья Малебу.", description = "Это письмо от существа, называющего себя Нагазом, членом сообщества Недремлющего Аргуса. Не знаю, что это за Аргус, но если он в союзе с Синдикатом, то представляет собой угрозу.\n\nОтыщи Нагаза и упомянутых в письме темных магов Недремлющего Аргуса. Найди их и убей.\n\nИщи их в Высокогорье, на севере от Странбрада, где позиции Синдиката сильнее всего.\n\nЕсли повезет, ты найдешь там послов Недремлющего Аргуса.", progress = "Удалось ли найти послов Недремлющего Аргуса?", completion = "Молодец, Маладат. Не хотелось бы, чтобы Недремлющий Аргус присоединился к Синдикату.\n\nХотя тебе и удалось убить их главаря в этих землях, ясно, что Нагаз был чьим-то слугой. Похоже, Недремлющий Аргус пустил корни по всему нашему континенту.\n\nИли по всему миру.", rewards = "Вы получите:\n\n"},
[538] = {title = "Южнобережье", objective = "Поговорите с Хранителем мудрости Диббсом в Южнобережье.", description = "Доброго дня вам, <имя>. Если вы не против долгого путешествия, то у меня для вас найдется задание, которое поможет пополнить библиотеку Штормграда.\n\nВместе со старым королевством Альтерака во время войны погибла и огромнейшая библиотека. Жаль, что город разрушен, но вдвойне жаль, что пропал бесценный кладезь знаний! Мы должны восстановить все, что можем.\n\nЮжнобережье – ближайший к руинам Альтерака город. Отправляйтесь туда и поговорите с Хранителем мудрости Диббсом. Он направит вас к руинам, может быть, там вы сумеете найти книги...", progress = nil, completion = "Да, конечно, я помню Милтона. Такой типичный книжный червь, будь он здоров...\n\nИ он совершенно прав. Руины Альтерака по-прежнему полны драгоценных документов, которые находятся под угрозой исчезновения!\n\nТеперь-то в Альтераке обитают огры, а их совершенно не волнуют памятники культуры...", rewards = "Вы получите:\n\n"},
[539] = {title = "Битва за Хилсбрад", objective = "Убейте штейгера Бондса и 10 хилсбрадских шахтеров и доложите о проделанной работе Дарталии на мельнице Таррен.", description = "Согласно регистрационной книге Хилсбрада, Лазуритовый рудник находится в руках Альянса. Более того, львиную долю руды, идущей на вооружение Альянса, добывают именно там.\n\nХотя мы нанесли решительный удар по городу Хилсбраду, Альянс изо всех сил защищает свой рудник.\n\nРудник расположен на юге от Хилсбрада. Ступай туда и убей штейгера, человека по имени Бондс. Убей и его горняков. Альянс надолго запомнит этот урок.", progress = nil, completion = "Темная Госпожа будет рада услышать, что у нее появился новый рудник, который поможет вооружить ее бойцов.", rewards = "Вы получите:\n\n"},
[540] = {title = "Сохранение знаний", objective = "Найдите 5 фолиантов и потертую кожаную книгу, называемую \"Рука Гри'лека\", и принесите их хранителю мудрости Диббсу в Южнобережье.", description = "Мерзкие огры поселились в руинах Альтерака, и мне дурно при мысли, что они делают с драгоценными книгами из библиотеки. Спаси все, что можно!\n\nСтупай в руины Альтерака и поищи там манускрипты, украденные ограми. Собери все, что сможешь и принеси мне. Больше всего меня интересует одна книга – \"Рука Гри'лека\". В ней содержится древняя мудрость троллей, о которой я жажду узнать, а последняя копия этой книги находилась именно в руинах Альтерака.", progress = "Жаль, что я сам не могу поискать в руинах, но боюсь, старые кости не выдержат пути вверх по горам. А у тебя как идут поиски знаний, Маладат?", completion = "А, вот они! Великолепно! Я немедленно примусь за изучение \"Руки Гри'лека\".", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[541] = {title = "Битва за Хилсбрад", objective = "Отправляйтесь в Дун Гарок и убейте 10 горных пехотинцев, 8 стрелков, 4 жрецов и капитана Железную Гору. После возвращайтесь к Дарталии на мельницу Таррен.", description = "Дворфы пришли на помощь людям? Проклятые мелкие твари!\n\nЧто ж, испытаем силу так называемого Альянса. Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев. Мы отлично знаем, где скрывается их цитадель в этих краях.\n\nОни построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина. Это местечко зовется Дун Гарок. Последняя цель этой битвы – осадить Дун Гарок, <класс>. Глава дворфов, капитан Железная Гора, должен умереть.", progress = "Дун Гарок тебе не по зубам, а? А я-то думала, ты доказал свою доблесть в Хилсбраде.\n\nЕсли ты не в силах выполнить это задание, я найду другого, кто достигнет цели. Что до тебя, не сомневаюсь, Темной Госпоже не помешают новые гробокопатели в Тирисфальских лесах.", completion = "Твои подвиги на поле битвы достойны высочайшей хвалы.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[542] = {title = "Возвращение к Милтону", objective = "Отнесите фолианты Альтерака Милтону Снопу в Штормград.", description = "Мне понадобится время на изучение \"Руки Гри'лека\", хотя я не сомневаюсь, что Милтону не терпится вернуть книги в коллекцию Штормграда.\n\nВот книги, добытые тобой в руинах Альтерака. Они уже упакованы и каталогизированы. Отнеси их Милтону Снопу в Штормград, он несомненно будет тебе признателен.", progress = "Маладат, вы вернулись! Как ваша миссия в Альтераке? Вы что-нибудь принесли?", completion = "О небо! Глазам своим не верю! Неужели они пережили падение Альтерака? И всех этих огров!\n\nСпасибо, Маладат. Огромное спасибо! Вы помогли нам сохранить человеческие знания, и прибавили великолепия Королевской библиотеке Штормграда.", rewards = "Вы получите:\n\n"},
[543] = {title = "Тиара Перенольда", objective = "Доставьте тиару Перенольда Ремингтону Риджвеллу в Штормград.", description = "Тиара Перенольда – старая семейная реликвия одного из древнейших семейств Альтерака, входившего в правящие круги до падения королевства. Говорят, что ее изготовили мастера Стальгорна, украсив лучшими изумрудами.\n\nКогда Альтерак пал, тиара была утеряна, хотя поговаривали, что огрский маг Грел'борг Скряга нашел ее и теперь пытается разыскать на руинах Альтерака другие сокровища.\n\nМы надеемся, что вы отыщете тиару.", progress = "Приветствую, Маладат! Постарайтесь не наступить мне на отвороты брюк, костюмчик только что от портного.", completion = "О, чудесно. Конечно, тиару нужно почистить, но вы, Маладат, прямо-таки превзошли сами себя. Я велю привести тиару в порядок и немедленно помещу ее в нашу сокровищницу.\n\nПримите мою благодарность за пополнение коллекции семейных реликвий.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[544] = {title = "Взлом тюрьмы", objective = "Найдите предателей и отберите у них артефакты, а потом возвращайтесь к волхву Сиянью Бездны в Мельницу Таррен.", description = "Я прибыл в Мельницу Таррен с исследовательскими целями, а пришлось разрешать кризис. Видишь ли, четверо Отрекшихся несколько месяцев назад бежали из Подгорода. Они предали своих братьев, но что еще хуже... они украли кое-что у Темной Госпожи.\n\nЭти воры вломились в надежное хранилище и похитили четыре артефакта, необходимых нашим аптекарям для исследований. Сильвана жаждет вернуть эти артефакты.\n\nВоры бежали из Подгорода в Даларан, и волшебники спрятали их в Лордамерских выселках.", progress = "Удалось ли найти воров? И что куда важнее, вернуть похищенное?", completion = "Ты оказал Отрекшимся огромную услугу, Томпсон. Нам очень не хватало этих артефактов.\n\nХорошо, что Кеган и другие предатели получили по заслугам.", rewards = "Вы получите:\n\n"},
[545] = {title = "Даларанские патрули", objective = "Убейте 6 даларанских призывателей и 12 порабощенных элементалей. Затем возвращайтесь к волхву Сиянью Бездны на мельницу Таррен.", description = "Волшебники Даларана создали вокруг сердца своего города огромный магический купол. Некоторые говорят, что он призван защитить город от опасностей, которыми полнятся наши дни, другие же уверяют, будто волшебники захотели работать и строить планы в тишине и покое.\n\nМне лично наплевать, зачем соорудили этот купол. Меня интересуют развалины на окраинах города, где могут быть спрятаны ценные магические предметы.\n\nК сожалению, все окрестности патрулируют волшебники и порабощенные ими элементали.\n\nИтак, напади на них и возвращайся, когда существенно сократишь их число.", progress = nil, completion = "Замечательно. Теперь в руинах можно спокойно поискать артефакты, если быть осторожным.\n\nСпасибо, Томпсон.", rewards = "Вы получите:\n\n"},
[546] = {title = "Сувениры смерти", objective = "Страж смерти Самса с мельницы Таррен попросил принести 30 человеческих черепов Хилсбрада.", description = "Я слышал, что Дарталия призвала тебя в строй, чтобы выступить против людей Хилсбрада. Как я завидую…\n\nПока ты там развлекаешься – убиваешь людей, грабишь города, запугиваешь невинных – я торчу здесь, на страже мельницы Таррен.\n\nМожет, ты смилостивишься над старым стражем смерти? Видишь, я собираю коллекцию человеческих черепов, а тебе предстоит убить немало смертных. Набери в ходе битвы 30 черепов, принеси мне, и я тебе хорошо заплачу.", progress = "Итак, Томпсон возвращается? Сколько людей ты убил сегодня? Надеюсь, не одну сотню!\n\nТы несешь мне черепа?", completion = "Превосходные черепа! И какие красивые! Вот тебе обещанная плата, Томпсон!", rewards = "Вы получите:\n\nКольцо Черепа"},
[547] = {title = "Меч Гумберта", objective = "Найдите меч стража смерти Гумберта в Дун Гароке и верните его владельцу на мельнице Таррен.", description = "Верховный палач Дарталия послала меня наблюдать за Дун Гароком издалека. Я разбил лагерь подальше от дворфов. Но пришло утро, мне нужно было вскипятить воду, и я пошел за дровами.\n\nВернувшись, я обнаружил, что мои вещи пропали.\n\nОчевидно, ко мне заглянули дворфийские разведчики из Дун Гарока и украли их. Мне нужен мой меч! Если ты сможешь вернуть его, я буду очень признателен. Там так много дворфов... будет нелегко понять, кто же из них вор.", progress = "Тебе удалось добыть мой меч, Томпсон? Если верховный палач Дарталия узнает о моей небрежности, она прикажет меня повесить вниз головой!", completion = "Ты нашел его!\n\nАх, как приятно чувствовать в руке знакомую рукоять. Премного благодарен!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nРифленая кирасаПоножи наемника\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[549] = {title = "РАЗЫСКИВАЮТСЯ: сторонники Синдиката", objective = "Убейте 10 разбойников и 10 сторожей Синдиката и возвращайтесь за наградой к верховному палачу Дарталии в Мельницу Таррен.", description = "По приказу леди Сильваны все члены организации, именуемой Синдикат, приговариваются к смертной казни. Всех пленных казнят. В настоящий момент организация собирает силы в руинах крепости Дарнхольд на юго-востоке от мельницы Таррен.\n\nВсем, предоставившим доказательства своих подвигов верховному палачу Дарталии, будет дарована щедрая награда.", progress = nil, completion = "Великолепно, |3-6(Воин). Такими темпами мы мигом очистим эти земли от синдикатской швали.", rewards = "Вы получите:\n\n"},
[550] = {title = "Битва за Хилсбрад", objective = "Отнесите запечатанное рекомендательное письмо Дарталии Вариматрасу в Подгород.", description = "Поскольку ты <проявил/проявила> немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм. Пусть его прочитает высшее командование.\n\nОтнеси мое письмо Вариматрасу в Подгород. Можешь гордиться собой, <класс>.", progress = "Что же заставило |3-3(Маг) покинуть поле битвы и прийти в Подгород?", completion = "Так это ты знаменитый |3-6(Маг), нанесший сокрушительный удар по силам Альянса в Предгорьях Хилсбрада? Вести о твоих славных подвигах дошли до Подгорода.\n\nЕсли ты и впредь будешь проявлять подобный героизм, то тебя ожидает великое будущее в рядах бойцов Темной Госпожи.\n\nХотя наша главная проблема – наступление с севера Плети Короля-лича, человеческий вопрос тоже не решен и мешает строить планы битвы. Однако ты сумел доказать, что люди могут пасть. И они падут.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСвященные погребальные брюкиЩит Мертвого черепаРунический Черный клинок\n\nВы также получите:\n\nКольцо Подгорода"},
[551] = {title = "Заколдованный пергамент", objective = "Отнесите заколдованный пергамент Хранителю мудрости Диббсу в Южнобережье.", description = "На этот пергамент наложено заклинание, из-за чего надписи на нем невозможно расшифровать. Вы можете разобрать только одно слово вверху страницы: \n\n\nНагаз\n\n", progress = "Ого... Ты хочешь что-то мне показать? Надеюсь, какое-нибудь легендарное сокровище, найденное высоко в горах?..", completion = "Опять зашифрованные записки? \n\nХотел бы я уметь разгадывать шифры, чтобы разобрать все странные фрагменты записей, что доходят к нам из Альтерака. Но боюсь, мне не хватает знаний.", rewards = "Вы получите:\n\n"},
[552] = {title = "Месть Гелькулара", objective = "Отберите у йети жезл Гелькулара и отнесите его новобранцу Тайлванду на мельницу Таррен.", description = "Мастер Гелькулар почти превратился в Короля Мертвых, когда его ритуальное логово в холмах обнаружила разъяренная толпа людей и зверски убила его. Хуже того, они похоронили моего учителя на кладбище Южнобережья.\n\nНемыслимое неуважение к великому волшебнику. Я его ученик, и хочу отомстить ненавистному городу.\n\nПервым делом нам понадобится жезл Гелькулара. Его ритуальное логово захватили йети. Жезл несомненно находится у одного из них.", progress = "Удалось ли тебе вернуть жезл Гелькулара? Там так много йети, что найти его будет нелегко. И все же без него не обойтись.", completion = "Ты нашел его! Великолепно, Томпсон!", rewards = "Вы получите:\n\n"},
[553] = {title = "Месть Гелькулара", objective = "Зарядите Гелькуларов жезл силой пламени Азеля, пламени Вераза и пламени Узеля.\n\nВонзите заряженный жезл в гробницу Гелькулара в Южнобережье.", description = "Вот, возьми Гелькуларов жезл. Он тебе понадобится.\n\nГелькулар создал для своего заклятья 3 церемониальных погребальных костра. Пламя Азеля и пламя Вераза находятся в Пещерах предгорий. Пламя Узеля находится в пещере выше по склону, в северной части гор.\n\nГелькуларов жезл необходимо зарядить в каждом из этих костров. Завершив ритуал, вонзи жезл в гробницу Гелькулара в Южнобережье, надежно охраняемом человеческом городе на юге. Мы отомстим!", progress = "От гробницы Гелькулара исходит духовная энергия.", completion = "Из-под земли доносится глухой грохот.", rewards = "Вы получите:\n\n"},
[554] = {title = "Расшифровщик Грозовая Вершина", objective = "Отнесите заколдованный пергамент геологу Грозовой Вершине в Стальгорн.", description = "Геолог Грозовая Вершина – мастер дешифрования и декодирования. Если ты отнесешь найденный пергамент ему, то при удачном стечении обстоятельств он сможет его прочитать. В настоящий момент Грозовая Вершина работает в штаб-квартире Геологов в Стальгорне.\n\nЕсли увидишь его, сообщи о нашем разговоре – в последнее время я много работы на него свалил.", progress = "Опять мне мешают?\n\nА, на этот пергамент наложено очень тонкое, сложное заклинание. Разумеется, я смогу его распутать, но на это потребуется время. А время – деньги.\n\nМожет быть, мне просто купить его у тебя?", completion = "Мудрое решение. Все равно я не верю, что у других ученых хватит умения, чтобы перевести этот свиток. А если он окажется интересным, не бойся – я непременно пошлю за тобой.", rewards = "Вы получите:\n\n"},
[555] = {title = "Нежный черепаховый суп", objective = "Принесите 10 кусков черепашьего мяса и немного смягчающих пряностей шеф-повару Джессену в Южнобережье.", description = "Ты скоро поймешь, что в Южнобережье готовят лучше, чем во всех землях к северу от Штормграда!\n\nСкажем, возьмем мой секретный рецепт черепахового супа. Иногда ко мне захаживают из самого Темнолесья, чтобы насладиться миской-другой. Правда, в последнее время, мне не удавалось его сварить. Я бы сам пошел к озеру Лордамер у Даларана и поохотился на тамошних хрустогрызов, но это слишком опасно. Если ты принесешь мне черепашьего мяса и смягчающих пряностей, я мигом сварю этой вкуснятины.", progress = "Ну как, удалось найти нужные продукты? Да, скажу тебе, бывали времена поспокойнее. Ах, если бы не было войн...", completion = "Все будут в восторге – здесь снова подают нежный черепаховый суп шеф-повара Джессена!", rewards = "Вы получите:\n\nРецепт: нежный черепаховый супНежный черепаховый суп"},
[556] = {title = "Каменные талисманы", objective = "Отнесите 10 истертых каменных талисманов хранителю Бел'варилу с мельницы Таррен.", description = "Волшебники Даларана славятся своей связью с элементалями, могущественными созданиями из других измерений, которыми они управляют при помощи магических талисманов. Волхв Сиянье Бездны хотел бы изучить эти талисманы.\n\nСтупай на земли даларанских волшебников на западе от Хилсбрада и собери несколько талисманов.\n\nТакие талисманы носят многие жители Даларана, но я советую поискать их в выселках. Это гораздо безопаснее.", progress = "Где истертые каменные талисманы, Томпсон? Колдун хочет раскрыть их тайны.", completion = "Отличные талисманы. Хотя, кажется, из них немного выдохлась магия, оно и к лучшему. Пусть для начала наш колдун поэкспериментирует на менее активных образцах.\n\nСпасибо, Томпсон.", rewards = "Вы получите:\n\n"},
[557] = {title = "Сковывающие браслеты", objective = "Принесите 4 браслета Земли хранителю Бел'варилу с мельницы Таррен.", description = "Пока что колдун изучает каменные талисманы, но вскоре ему понадобится и другая часть – браслеты, связующие Стихии. Элементали носят их на запястье, что заставляет их выполнять волю мага.\n\nУбей побольше духов в руинах Даларана и собери с них браслеты Земли, и колдун будет доволен.", progress = "Здравствуй, Томпсон. Элементали – непростые противники, но я не сомневаюсь, что ты справишься. Ты несешь мне их браслеты?", completion = "Тебе удалось их найти. Надеюсь, элементали, с которых сняты эти браслеты не очень сопротивлялись?\n\nХм... После смерти у меня атрофировалось не только сердце, но и чувство юмора заодно.\n\nЧто ж, спасибо, Томпсон. Служа колдуну, служишь и Темной Госпоже, да.", rewards = "Вы получите:\n\n"},
[558] = {title = "Автограф Джайны", objective = "Отправляйтесь в Терамор и постарайтесь получить автограф Джайны Праудмур для своего подопечного.", description = "Говорят, что леди Джайна Праудмур из Терамора – одна из величайших героинь Альянса. Когда я вырасту, я тоже хочу стать героем Альянса!\n\nТы <знаком/знакома> с Джайной? Окажи мне услугу! Возьми у нее автограф! Я не знаю, как ее попросить, у нее нет времени для таких, как я... другое дело ты! Ты <такой же искатель/такая же искательница> приключений, как и она! Готов поспорить, что тебе получить у нее автограф – раз плюнуть!\n\nПожалуйста!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[559] = {title = "Доказательство Фаррена", objective = "Соберите 10 голов мурлоков на Западном побережье по просьбе лейтенанта Фаррена Оринеля из Южнобережья.", description = "Ты не поверишь, Крассена не устроили все убитые нами – не скромничай, ты тоже <приложил/приложила> к этому руку. Теперь он хочет от меня доказательств их смерти. Чтобы я отрубил холодные склизские мурлочьи головы и принес пред его очи!", progress = "Ты несешь мне головы, Бронгард?", completion = "Ох, во имя Света! С них же течет на землю какая-то дрянь.\n\nЯ к ним не притронусь! Рыбу еще можно терпеть, но если у нее вырастают ноги и она ходит взад-вперед... Я рыбы уже несколько недель не ел, и поверь мне, в Южнобережье это означает жизнь впроголодь.", rewards = "Вы получите:\n\n"},
[560] = {title = "Доказательство Фаррена", objective = "Отнесите мешок с головами мурлоков маршалу Крассену в Южнобережье.", description = "Знаешь, мне даже прикасаться к этим головам не хочется... Раз уж они у тебя, отнеси их Крассену от моего имени, а?", progress = "Приветствую тебя. Ты хочешь предложить свою помощь в поддержании порядка в Южнобережье?", completion = "Так ты мальчик на посылках у Фаррена?\n\nЕсли ты помог ему добыть эти головы, большое тебе спасибо. Южнобережье нуждается в защитниках.", rewards = "Вы получите:\n\n"},
[561] = {title = "Доказательство Фаррена", objective = "Поговорите с лейтенантом Фарреном Оринелем из Южнобережья.", description = "Пожалуйста, сообщи лейтенанту Оринелю, что я хотел бы, чтобы он занялся нагами, заселившими Восточное побережье. Когда он добьется результатов, пусть лично доложит о них мне.", progress = nil, completion = "Наги, значит. Похоже, Крассен получил те же сведения, что и я... Ха! Он не сможет возвыситься благодаря мне. Позволь объяснить.", rewards = "Вы получите:\n\n"},
[562] = {title = "Ха, Штормград!", objective = "Убейте 10 береговых охотников и 10 сирен из клана Пронзающего Гребня по просьбе лейтенанта Фаррена Оринеля из Южнобережья.", description = "Мой бывший наставник из городской стражи Штормграда послал мне сообщение, что верховное командование Альянса обоспокоено появление наг. По слухам, тот, кто хорошо проявит себя в этой области, получит повышение – или, по крайней мере, новое назначение.\n\nЕсть одна проблема... я не могу справиться с нагами. Разумеется, прекратить пьяную драку или скрутить воинственного вора я могу, но наги мне не по зубам. Помоги мне, <имя>!", progress = "Я уже и письмо написал майору Самуэльсону в Крепость Ветров. Теперь мне нужен результат.", completion = "Разобравшись с нагами в Южнобережье, я могу не сомневаться в новом назначении. Я вернусь обратно в Штормград... И больше не увижу этот забытый Светом порт.", rewards = "Вы получите:\n\nРыбный резак"},
[563] = {title = "Новое назначение", objective = "Отнесите донесение Фаррена майору Самуэльсону в Крепость Штормграда.", description = "Мне будет легко добиться, чтобы мое донесение прочитали. Новый капитан стражи, майор Самуэльсон, был моим учителем еще в Штормграде. Ему не составит труда перевести меня обратно в столицу. Но придется попросить тебя отнести мое донесение ему... Главное, чтобы старина Крассен ничего не узнал.", progress = "Приветствую тебя. Чем могу тебе помочь я, городской стражник Штормграда?", completion = "Что такое? А... Значит, мой внимательный ученик занялся проблемой наг Южнобережья. Спасибо, что принес это мне, я непременно приму это во внимание, пересматривая назначения в следующем месяце.", rewards = "Вы получите:\n\n"},
[564] = {title = "Серьезная угроза", objective = "Убейте 8 горных львов и 10 крупных горных львов по поручению Даррена Малвея из Южнобережья.", description = "Ничто так не злит меня так, как потеря отличных коней. И поверь, эти назойливые мертвяки, синдикатские бандюги и прочие ни на что не годные негодяи, лишили нас множества лошадок.\n\nНо я готов поклясться могилой моего прадедушки, что главный враг коней – горные львы Альтерака. Вечно осложняют мою жизнь!\n\nТы считаешь себя героем? Тогда пойди, разберись с ними!", progress = nil, completion = "Отличные новости! Надо было сразу же найти нормального героя войны, чтобы он разобрался со зверюгами. Твой папка гордился бы тобой, Пластырь.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nРемень пастыряПерчатки пастыря\n\nВы также получите:\n\nРецепт: сочный стейк из мяса льваСочный стейк из мяса льва"},
[565] = {title = "Плащ из меха йети", objective = "Принесите Бартоло Джинсетти из Южнобережья рулон шерсти, плащ жителя холмов, тонкую нить и 10 клоков меха йети.", description = "Я, великий Бартоло, сделаю для тебя знаменитый во всем Альянсе, да и во всем мире, плащ из меха йети!\n\nОбыщи весь белый свет, и нигде прекрасней нет! Что, что я слышу, <маленький/маленькая:r> <раса>? \"Бартоло, твои плащи лучше всех!\" Да, да! Мне не раз это говорили.\n\nБартоло нужен рулон шерсти, плащ жителя холмов от искусного кожевника, тонкая нить и мех йети, конечно! Принеси мне все составляющие, и ты станешь счастливым обладателем одного из моих плащей!", progress = "Итак, ты вернулся к великому Бартоло. Быть может, все материалы для плаща из меха йети собраны? Или просто хочешь постоять рядом со знаменитостью?", completion = "Пришло время для колдовской работы Бартоло! Мне не нужен ни посох волшебника, ни жезл мага. Ведь я, великий Бартоло, творю чудеса при помощи простой иглы и нити!", rewards = "Вы получите:\n\nПлащ из меха йети"},
[566] = {title = "РАЗЫСКИВАЕТСЯ: Барон Вардус", objective = "Убейте барона Вардуса и принесите его голову верховному палачу Дарталии на мельницу Таррен.", description = "По приказу верховного палача Дарталии, человек по имени барон Вардус разыскивается по обвинению в многочисленных преступлениях против Отрекшихся. Вардус является высокопоставленным членом преступной организации Синдикат.\n\nВ последний раз его видели в Высокогорье Альтеракских гор, к северу от мельницы Таррен.\n\nОн приговаривается к смертной казни. Для получения награды необходимо предоставить доказательства его гибели верховному палачу Дарталии.", progress = "А, Томпсон. Ты не за наградой за голову барона Вардуса?", completion = "Ты отлично работаешь, Томпсон. Барон Вардус мертв, и число главарей Синдиката стало меньше. Недолго им осталось лютовать.", rewards = "Вы получите:\n\nИнфернальное одеяние"},
[567] = {title = "Вооружены и очень опасны!", objective = "Верховный палач Дарталия с мельницы Таррен назначила награду за убийство клерка Горация Белоконя, гражданина Уилкса, шахтера Хакетта и фермерши Калабы.", description = "Внимание: вооружены и очень опасны!\n\nСледующие люди из Хилсбрада объявлены вне закона, и верховный палач Дарталия предлагает награду за их головы:\n\nКлерк Гораций Белоконь. Разыскивается за убийство стража смерти Томма.\n\nГорожанин Вилкс. Разыскивается за убийство аптекаря Эли.\n\nШахтер Хакетт. Разыскивается за убийство стража смерти Фрая.\n\nФермерша Калаба. Разыскивается за нападение из засады на караван с припасами из Подгорода.\n\nВсе перечисленные преступники скрываются, и найти их нелегко. Награда будет выдана при предъявлении доказательств их смерти.", progress = nil, completion = "Да ты неплохой охотник за головами, |3-6(Воин).", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛук ОграбленияКулачный щит караульногоОбгоревший жезл\n\nВы также получите:\n\nКлобук с капюшоном"},
[568] = {title = "Защита Гром'гола", objective = "Командир Агро'гош из лагеря Гром'гол поручил вам убить 15 ящеров-кнутохвостов.", description = "Тром'ка, <класс>!\n\nТы на удивление вовремя <оказался/оказалась> в Гром'голе. Как командир лагеря Вождя, я обязан защищать всех сторонников Орды в этих джунглях. Наша цель – обеспечить бесперебойное снабжение Каменора, а некоторые обитатели здешних мест нам мешают.\n\nЯ поручаю тебе сократить численность ящеров рядом с Гром'голом. Добившись заметных успехов, возвращайся, и я дам тебе новое задание.", progress = nil, completion = "Ты исполнил свой долг с честью, |3-6(Охотник).", rewards = "Вы получите:\n\n"},
[569] = {title = "Защита Гром'гола", objective = "Командир Агро'гош из лагеря Гром'гол поручил вам убить 10 огров-громил и 5 огров-знахарей.", description = "Отправляясь в джунгли, мы не собирались воевать с местными племенами. Главное – снабжение Каменора. Увы, возник ряд сложностей. Местные огры заняли руины Мизжа на юго-востоке от Гром'гола. Невзирая на многочисленные предупреждения, они продолжают нападать на наши караваны.\n\nЯ приказываю тебе разобраться с этими упертыми ограми.\n\nОтправляйся в развалины и попытайся выбить их оттуда. По крайней мере, преподай им хороший урок.", progress = "Как дела с ограми руин Мизжа, |3-6(Чернокнижник)?", completion = "Отлично. Ты с честью послужил вождю.", rewards = "Вы получите:\n\nКулачный щит Гром'гола"},
[570] = {title = "Чары Мок'тардина", objective = "Провозвестник Мок'тардин из лагеря Гром'гол попросил вас принести ему 8 когтей тенебрюхих пантер и безупречный тигриный клык.", description = "Орда должна узнать о силе магии джунглей и подчинить ее себе. Мне уже удалось добиться успеха, и я могу пользоваться могучими заклинаниями. Я сделаю для тебя особую вещь, <отважный/отважная:c> <класс>.\n\nПринеси мне когти тенебрюхих пантер и клык тигрицы. Учти, что клык должен быть безупречно ровным.\n\nЭти твари разгуливают по всем джунглям, но тебе не придется далеко ходить – просто перейди реку рядом с руинами Мизжа на юго-востоке.", progress = "Добрые ли вести ты несешь?", completion = "Ты превосходно знаешь джунгли, Томпсон. Отличная добыча! Я возблагодарю духов за то, что они пожертвовали таких зверей на благо Орды.", rewards = "Вы получите:\n\n"},
[571] = {title = "Чары Мок'тардина", objective = "Принесите сухожилие старой гориллы провозвестнику Мок'тардину в лагерь Гром'гола.", description = "Следующий компонент будет нелегко найти.\n\nЧтобы связать перья, когти и чистый клык, мне понадобится волшебный шнурок. Нам подойдет лишь сухожилие старой гориллы.\n\nЕго можно добыть только у старых горилл из Мглистой долины. Они кормятся к востоку от Пиратской Бухты.\n\nТолько сухожилие должно быть в идеальном состоянии. Быть может, тебе понадобится убить нескольких зверей, чтобы понять, что именно мне нужно, но результат того стоит.", progress = "Была ли удача на твоей стороне, Томпсон? Удалось ли тебе добыть сухожилие старой гориллы?", completion = "Превосходное сухожилие, Томпсон. Твои усилия скоро окупятся.", rewards = "Вы получите:\n\n"},
[572] = {title = "Чары Мок'тардина", objective = "Принесите 10 перьев тропических ловцов провозвестнику Мок'тардину в лагерь Гром'гол.", description = "То, что тебе удалось добыть у зверей из семейства кошачьих – лишь первое, что требуется для создания могущественного зачарованного предмета. Меж тем украшения джунглей, усиленные при помощи моих ритуалов, неплохо послужат тебе в деле помощи Орде и Вождю.\n\nТеперь же собери для меня перья тропических ловцов. Эти твари как правило прикрепляют перья на лапы. На юге от Гром'гола, недалеко от большой арены, есть такое племя ящеров.", progress = "Сопутствовал ли тебе успех в охоте?", completion = "Великолепно. Я немедленно их подготовлю.", rewards = "Вы получите:\n\n"},
[573] = {title = "Чары Мок'тардина", objective = "Провозвестник Мок'тардин из лагеря Гром'гол попросил вас принести ему воду Святого источника. Кроме того, он поручил вам убить 10 наг-исследователей.", description = "Остается лишь одно составляющее, и я смогу наложить чары на колье.\n\nК югу отсюда, близко от западного побережья, высоко над утесами, располагается Святой источник. Он вызывает множество конфликтов среди религиозных ученых. Все расы Азерота утверждают, что воды освящены именно для их народа.\n\nВот мое последнее поручение: принеси мне воду Святого источника. Соблюдай осторожность. Сейчас его окрестности захватили наги. С ними тоже следует разобраться.", progress = "Я готов к зачаровыванию. Ты выполнил мое поручение?", completion = "Ты принес мне воду Святого источника, и я могу наложить чары на церемониальное колье.\n\nНоси его с гордостью, во имя Вождя и мощи Орды.", rewards = "Вы получите:\n\nКолье Верховного шамана"},
[574] = {title = "Особые войска", objective = "Убейте 10 диверсантов и 6 охотников за головами Курцена.\n\nДоложите об этом лейтенанту Дорену в Лагере повстанцев.", description = "Теперь, после сокращения численности регулярных войск Курцена, тебе придется вступить в схватку с его особыми отрядами. Они либо выбираются в лес и убивают наших солдат, либо отсиживаются позади поселка Курцена, в пещере, называемой Схрон.\n\nЯ знакома со многими воинами Курцена, и все они отличаются прекрасной подготовкой, верностью и жестокостью. Задание непростое, <имя>.\n\nЕсли ты сможешь их одолеть, доложи об этом лейтенанту Дорену, моему командиру. Он захочет услышать об этом из первых уст.", progress = "Сержант Йохва говорит, что ты силен и отважен, |3-6(Чернокнижник). Докладывай!", completion = "Эфром. Сержант Йохва поверила в твои способности, а я поверил ей. Мы и надеяться не могли на подобный удар по силам Курцена. Я боялся, что мы, повстанцы, совсем одни, и не сможем справиться с гениальным полковником.\n\nБыть может, теперь у нас есть надежда.", rewards = "Вы получите:\n\n"},
[575] = {title = "Спрос и предложение", objective = "Принесите 2 шкуры большого речного кроколиска Дриззлику из Пиратской бухты.", description = "\"Лучший мастер-кожевник Южных морей и старого и нового мира.\" Вот как меня называют! Меня! Дриззлика! Лучшим коже... Кхе-кхе. Короче.\n\nМои товары славятся по всему свету как наилучшие по мнению всех экспертов!\n\nЯ только что получил заказ от директора Ридлвокса из Союза ремонтников на дюжину его любимых превосходных сапог. Не скрою, это самая популярная модель.\n\nЧтобы приступить к раскройке, мне нужны шкуры кроколисков. Их можно добыть у реки в северной части Тернистой долины.", progress = "У меня все готово, не хватает только шкур. Одно тебе скажу, не надо заставлять Ридлвокса ждать.\n\nНе стоит расстраивать главного изобретателя Союза ремонтников.", completion = "Эти шкуры отлично подойдут. Качество не слишком важно, учитывая, что они идут на внутреннюю отделку сапог, главное, чтобы носить было удобно.\n\nЕсли шкуры жестковаты, я вымочу их в тигриной крови. Вот они, секреты мастерства, да?", rewards = "Вы получите:\n\n"},
[576] = {title = "Смотри в оба", objective = "Диззи Одноглазый из Пиратской бухты попросил вас отобрать его глаз у пиратов Кровавого Паруса.", description = "Стой! Кто идет?\n\nАррр, кому я нужен без волшебного глаза. Мало того, что я лишился зрения в бою! Но тогда мне свезло, и один волшебник зачаровал для меня особый стеклянный глаз, и я снова мог видеть.\n\nА вчера на меня по дороге накинулись пираты Кровавого Паруса и отобрали у меня глаз! Кажется, эти типы чувствуют себя в Пиратской бухте как дома.\n\nНе поможешь старому морскому волку вернуть зрение?", progress = "Эгей, приятель! Может, я и не вижу ничего, но чую я тебя аж с другой стороны порта.\n\nГлаз бы мне не помешал. Капитан меня протащит под килем, если узнает, что моя гляделка в руках грязных пиратов Кровавого Паруса.\n\nКому нужен слепой впередсмотрящий? Я буквально жил на марсовой площадке... а теперь мне в лучшем случае поручат драить палубу.", completion = "Лопни моя селезенка! Разрази меня гром! Ты нашел мой прекрасный глаз! Проверим, годится ли он по-прежнему.\n\nХо! Я вижу, вижу!!!", rewards = "Вы получите:\n\nНакидка темного прилива"},
[577] = {title = "Добыча шкур", objective = "Отнесите 5 шкур кроколисков-хрустогрызов Дриззлику в Пиратскую бухту.", description = "Что ж, я раскроил основу сапог, получается превосходно, но на подбой шкур не хватит.\n\n\"Что же делать, Дриззлик?\" – спросишь ты. К счастью, ты говоришь со мной, и я скажу тебе, как мы поступим!\n\nПодбой все равно никто не видит, поэтому мы используем более толстую и дешевую шкуру кроков с озера Назферити.", progress = "Превосходные сапоги Дриззлика – отличная работа, стопроцентная кожа морских кроколисков. Лучше не бывает!\n\nОписания заманчивей не придумаешь, верно?\n\nРазве что ты принес мне шкуры?", completion = "Мои сапоги не хуже колбасы, Эфром. Выглядят отлично, на вкус прекрасны. Я говорю, что внутри сверхкачественное мясо и приправы, и вы едите их с удовольствием.\n\nТак куда приятнее – и вкуснее – если не заглядывать внутрь.", rewards = "Вы получите:\n\n"},
[578] = {title = "Камень приливов", objective = "По поручению барона Ревилгаза из Пиратской бухты найдите остров, населенный духами Воды.", description = "Если правду говорят о гоблине-маге и элементалях воды, живущих на острове, значит я могу заполучить Камень Приливов!\n\nНайди этот остров... И выясни, что происходит. И если ты хочешь узнать подробнее о Камне Приливов, отнеси эту записку в библиотеку Штормграда, они найдут тебе книгу, в которой я впервые прочитал эту легенду.\n\nНеужели Газбан в самом деле нашел Камень?..", progress = nil, completion = "Значит, легенды не лгут! Немыслимо!\n\nТеперь надо отыскать способ одолеть проклятье Камня Приливов, если мы хотим найти его. Проклятья – дело магов. Значит, надо обратиться к одному из них.", rewards = "Вы получите:\n\n"},
[579] = {title = "Библиотека Штормграда", objective = "Король Андуин уделяет огромное внимание просвещению и всемерно заботится о том, чтобы с ценных книг вовремя делались списки, доступные горожанам. Все просто: принесите мне библиотечный свиток, и я выдам вам копию любой имеющейся книги.", description = nil, progress = "Король Андуин уделяет огромное внимание просвещению и всемерно заботится о том, чтобы с ценных книг вовремя делались списки, доступные горожанам. Все просто: принесите мне библиотечный свиток, и я выдам вам копию любой имеющейся книги.", completion = "Какая книга вас интересует, Палео?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\n\"Роман о Моргане Ладиморе\"\"Легенды Гурубаши\", том 3"},
[580] = {title = "Потерянный грог Алкача Виски", objective = "Алкач Виски из Пиратской бухты попросил вас принести ему потерянные бутылки портвейна \"Пупелливербос\".", description = "На подходе к Отвесным скалам, как раз в тот момент, когда старые добрые Внутренние земли показались на горизонте, нас настигла жуткая буря. Мы думали – все, нам каюк, море нас проглотит.\n\nНо старый Алкач знает, что такое жидкая храбрость! У кэпа был ящик портвейна \"Пупелливербос\", который мы взяли трофеем у одного пирата по пути в Штормград.\n\nВ общем, когда с Внутренних земель налетел шторм, я налег на грог. И тут шхуну захлестнула большая волна и смыла бутылки за борт. Кэп всыплет мне по первое число, если ты не поможешь их найти.", progress = "Разрази меня гром! У меня почти кончилась выпивка! Кэп собирается поднять якоря, а старый Слим засохнет, как пустыня Танарис. А уж когда кэп узнает, что пропал его портвейн... лучше сразу за борт!", completion = "Лопни моя селезенка! Ты нашел грог кэпа!\n\nЯ по гроб жизни тебе обязан, друг.\n\nПохоже, снаружи разыгрался шторм. Пока он не пройдет, я согрею нутро грогом из одной из этих славных бутылочек...", rewards = "Вы получите:\n\nРом Рэмси"},
[581] = {title = "Поиски Йеннику", objective = "Принесите 9 клыков тролля из клана Кровавого Скальпа Нимбойе в лагерь Гром'гол.", description = "Нас постиг злой рок. И коснулось это младшего сына моего вождя. Как у нас и заведено, мы отдали его на воспитание племени Гурубаши в Зул'Гурубе, но после того, как племя Черного Копья последовало за орком Траллом, бедняга Йеннику оказался потерян для нас. Меня прислали в Тернистую долину из далекого Оргриммара на поиски сына вождя.\n\nЯ думаю, он в руках племени Кровавого Скальпа.\n\nЕсли ты хочешь помочь мне, напади на них. Они живут к северу отсюда. Собери их клыки и принеси мне.", progress = "Охотник. Докажи мне, что воины Кровавого Скальпа пали от твоей руки.\n\nГде твои трофеи?", completion = "Отличные клыки, Томпсон. Значит, у тебя хватило сил на сражение с племенем Кровавого Скальпа.\n\nИ это очень хорошо, потому что охота далеко не закончена.", rewards = "Вы получите:\n\n"},
[582] = {title = "Охота за головами", objective = "Принесите Нимбойе из лагеря Гром'гол 20 сушеных голов.", description = "Мы должны узнать, мертв ли Йеннику.\n\nУбей как можно больше охотников за головами из клана Кровавого Скальпа и забери у них сушеные головы. Набери как можно больше голов, и я осмотрю их, чтобы убедиться, что среди них нет головы Йеннику.\n\nЕсли племя Кровавого Скальпа убило Йеннику, да падет 600-летнее проклятье на душу их предводителя, Ган'зулаха!\n\nСтупай, <имя>. Охотников за головами можно найти в Руинах Зуулдая и Зул'Кунды, в северной части побережья.", progress = "Томпсон. Я боюсь за сына нашего вождя. Ты принес мне головы? Я хочу их осмотреть.", completion = "Спасибо, Томпсон. Я осмотрю эти головы и узнаю, пал ли бедняга Йеннику под ударом топора охотника за головами.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМанжеты племени Черного КопьяЗащитные наручи племени Черного Копья\n\nВы также получите:\n\n"},
[583] = {title = "Добро пожаловать в джунгли", objective = "Поговорите с Хемингом Эрнестуэем.", description = "Добро пожаловать в Тернистую долину!\n\nБыть может, ты не знаешь об этом, но этот дворф – единственный и неповторимый Хеминг Эрнестуэй, прославленный герой Альянса и великий охотник на крупную дичь. Он не слишком жалует гостей, но на твою долю, кажется, выпало немало приключений, <класс>?\n\nХеминг и сам многое повидал – может, вы с ним найдете общий язык.\n\nСтупай, поговори с ним. Вдруг он научит тебя охотничьим хитростям.", progress = nil, completion = "Приятно познакомиться, Эфром. Давно в наши края не забредал |3-6(Маг). Я здесь с одной-единственной целью – поймать крупного и хитрого зверя. Раз ты, так сказать, личность героическая, может, захочешь принять участие в охоте? Впрочем, сначала покажи, на что способен.\n\nЯ научу тебя охотиться на ящеров. Ажек – на тигров. А сэр Эрлгедин – мастер выслеживать пантер.\n\nПокажи нам свое искусство, и сможешь принять участие в большой охоте.", rewards = "Вы получите:\n\n"},
[584] = {title = "Головы племени Кровавого Скальпа", objective = "Принесите головы Ган'зулаха и Неззилока и положите их в бурлящий котел в лагере Гром'гол.", description = "Я не нашел Йеннику среди голов, хвала Великому Змею за это. Но мы не сильно продвинулись в наших поисках.\n\nНеобходимо выяснить правду, и, боюсь, она известна лишь вождю племени Кровавого Скальпа и его знахарю. Они враги племени Черного Копья, и просто так говорить не будут, поэтому мы должны вырвать правду из их мертвых губ!\n\nПринеси мне головы Ган'зулаха и Неззилока Зловещего и помести их в этот котел.\n\nЭти тролли живут в глубине руин Зул'Кунды. Принеси их головы... а уж говорить мы их заставим.", progress = "Зеленый отвар в котле бурлит.", completion = "Вы кладете в котел головы Ган'зулаха и Неззилока...", rewards = "Вы получите:\n\n"},
[585] = {title = "Разговор с Неззилоком", objective = "Принесите в лагерь Гром'гол трофей из Балиа'ма, трофей из Зиата'джаи и трофей из Зулмамбве и положите их в бурлящий котел.", description = "<Голова Неззилока начинает говорить.>\n\nЭто правда. Я знаю, куда увели дитя племени Черного Копья. Ты <одолел/одолела> меня и <связал/связала> мой дух, но я все равно не буду говорить даром!\n\nПлемя Кровавого Скальпа враждует с племенем Дробителей Черепов. Чтобы добиться от меня ответа, укради 3 трофейных черепа у племени Дробителей Черепов и положи их к нам, чтобы мой дух обрел рабов в Пустоте. Один череп возьми в Балиа'ма, другой – в Зиата'джаи, а последний – в Зулмамбве.", progress = "Я жду черепов...", completion = "Да. Ты сослужил мне добрую службу. Когда мой дух освободится, я войду в Пустоту и обрету трех отличных слуг!\n\nТы – гордость своего клана, |3-6(нежить), и умилостивил меня.", rewards = "Вы получите:\n\n"},
[586] = {title = "Разговор с Ган'зулахом", objective = "Убейте 8 охотников, 6 охотников за головами и 4 берсерков из клана Дробителей ЧЕрепов.\n\nПринесите разбитую броню Анатека к бурлящему котлу в лагере Гром'гол.", description = "*Голова Ган'зулаха начинает говорить.*\n\nБудь ты <проклят/проклята>! И будь прокляты твои предки!!!\n\nЛишь кровь и месть остудят мою ярость, поэтому если ты этого добиваешься, то... сделай вот что:\n\nОтправляйся в сердце владений Дробителей Черепов на востоке. Убей самых лютых воинов, и если выживешь... брось вызов их вождю, Анатеку Жестокому. Ха! Принеси мне его разбитую броню, если сможешь!\n\nДа оторвет он у тебя руки и ноги и бросит медленно гнить. Да станешь ты добычей падальщиков!", progress = "Хотя моя собственная плоть постепенно облезает с черепа, я чую твой страх.\n\nХа! Ты никогда не справишься с моим заданием...", completion = "Мне не хочется верить тебе, но увы, ты несомненно выполнил мое задание. Теперь, когда Анатек пал, гнев мой поостыл.\n\nТвоя сила приведет тебя к великим свершениям, Томпсон. Но однажды... Мы встретимся в Пустоте, и снова померяемся силой.\n\nЯ буду ждать тебя.", rewards = "Вы получите:\n\n"},
[587] = {title = "Понюшка табака", objective = "Диг из Пиратской бухты попросил принести ему 15 понюшек табаку.", description = "Ах, жизнь моряцкая! Не скажу, что она хороша, но это моя жизнь.\n\nПришвартовавшись в порту, я люблю выпить бутылочку грога и нюхнуть хорошего табачку. Вредные привычки, но что за пират без пороков, а?\n\nТолько представь, как я был разочарован, узнав, что местный травник распродал весь товар. Говорит, мол, новую поставку перехватили эти проклятые пираты Кровавого Паруса.\n\nГотов поспорить, что <бесстрашный/бесстрашная:c> <класс> вроде тебя сможет убедить их поделиться товаром, а?", progress = "Ну как, удалось найти товары, дружище?", completion = "Отличная работа, Эфром! И я даже в море отплыть не успел! Не знаю даже, как тебя благодарить.", rewards = "Вы получите:\n\n"},
[588] = {title = "Судьба Йеннику", objective = "Поговорите с Кин'вилаем.", description = "<Неззилок говорит.>\n\nТы <сумел/сумела> угодить и мне, и вождю, и я скажу тебе то, что ты хочешь знать…\n\nЮный Йеннику навеки потерян для своего клана.\n\nЕго забрал к себе знахарь Занзил Отверженный. Теперь Занзил полностью подчинил себе его тело и душу, и лишь сильнейшая магия может освободить его.\n\nТы такой магией не владеешь, <класс>.\n\nБыть может, племя Черного Копья, ваши союзники, могло бы подарить надежду на спасение Йеннику. Но лично я сомневаюсь.", progress = nil, completion = "Занзил Отверженный??\n\nЕсли Йеннику и правда попал в руки этого тролля, могущественного и злого знахаря, то надежды почти нет. Почти. Не больше букашечки.\n\nНо малая надежда лучше, чем совсем никакой.", rewards = "Вы получите:\n\n"},
[589] = {title = "Поющие кристаллы", objective = "Принесите 3 пульсирующих синих осколка Кин'вилаю в лагерь Гром'гол.", description = "Легенды повествуют о драгоценном камне, сокрытом в самом сердце Тернистой долины. Мы зовем его Оком Разума, и он хранит в себе великую мощь. Если добыть этот камень, быть может, удастся вернуть Йеннику из тьмы.\n\nЯ попрошу духов джунглей помочь нам в поисках Ока Разума. Тем временем отправляйся в рудник Хрустальной шахты на юго-востоке отсюда и добудь пульсирующие синие осколки из железозубых василисков. Осколки встречаются очень редко, но без их магии мы не сможем подчинить себе Око Разума.", progress = "Ты принес осколки, Томпсон? Без них нам не обойтись, даже когда удастся заполучить Око Разума.", completion = "Молодец, Томпсон. Эти осколки правильной формы, и я уже слышу их голос.\n\nПока тебя не было, я говорил с духами джунглей. Теперь я знаю, где находится Око Разума…\n\n...И кто его охраняет.", rewards = "Вы получите:\n\n"},
[590] = {title = "Выгодная сделка", objective = "Одержите победу в схватке с Кальвином Монтеччи в Могильнике.", description = "Что?\n\nЧТО?!\n\nДенег хочешь? Не должен я тебе никаких денег. \n\nПисьмо? Какое письмо? Может, еще и подеремся? Ну, <приятель/подружка>, давай! Вот еще, деньги я должен...", progress = nil, completion = "Невероятно! Какое мастерство! \n\nА я-то думал, ты будешь легкой добычей, Сиамнео. Да, хорошенько ты меня отделал. \n\nВот обещанные деньги... правда, не столько, сколько я сказал сначала, но должен же я был немного приврать.", rewards = "Вы получите:\n\n"},
[591] = {title = "Око Разума", objective = "Отнесите Око Разума Кинвилаю в лагерь Гром'гол.", description = "Око Разума находится у огра-мага на востоке отсюда, в глубине холма Мош'Огг. Этого мага зовут Май'Зот, и я помню его с тех пор, как племя Черного Копья обитало в Тернистой долине. Он жесток и силен.\n\nА если у него есть Око Разума, тем могущественней его магия.\n\nВступи с бой с Май'Зотом и отними у него Око Разума. Задание опасное, но лишь так мы можем надеяться спасти Йеннику.", progress = "Приветствую тебя, Томпсон. Духи поют хвалу твоей храбрости, но о победе над Май'Зотом они молчат.\n\nНесешь ли ты мне Око?", completion = "Тебе удалось добыть Око? Твою силу должно воспевать в легендах, Томпсон!\n\nКроме того, добывая око ты одолел Май'Зота и отправил его в Пустоту. Вот почему духи молчали о нем.\n\nХорошо, что он покинул мир плоти и крови, но боюсь, что теперь, в царстве духов он снова захватит власть.\n\nВпрочем, об этом будем беспокоиться в другой раз. А теперь я проведу ритуал, чтобы приспособить Око Разума для наших нужд...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[592] = {title = "Спасение Йеннику", objective = "Отнесите Нимбойе наполненный самоцвет Души.", description = "Я превратил Око Разума в самоцвет Души. Он послужит двоякой цели: оглуши при его помощи Йеннику, а затем помести самоцвет ему на голову, чтобы поймать его душу.\n\nПотом отнеси камень Нимбойе.\n\nЙеннику живет у Занзила Отверженного, в руинах Абораза на Хрустальном взморье далекого мыса Тернистой долины.", progress = "Харо. Кин'вилай сказал, что послал тебя за Йеннику.\n\nЭто правда? Тебе удалось поймать его душу?", completion = "Победа! Ты освободил Йеннику от воли Занзила и выполнил задание, которое я считал безнадежным.\n\nНаше племя будет воспевать твое имя, Харо, и мы на каменных плитах напишем повесть о тебе, чтобы она никогда не забылась.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТаинственный посох НимбойиМедаль за отвагу\n\nВы также получите:\n\n"},
[593] = {title = "Наполнение самоцвета Души", objective = "Йеннику стоит перед вами, и разум его витает далеко...", description = nil, progress = "Йеннику стоит перед вами, и разум его витает далеко...", completion = "Вы прикасаетесь к его лбу самоцветом Души. Он вздрагивает, когда волшебный предмет всасывает его разум, оставляя лишь тело, бездушную оболочку.", rewards = "Вы получите:\n\nНаполненный самоцвет Души"},
[594] = {title = "Послание в бутылке", objective = "Отыщите автора послания в бутылке.", description = "Записка написана красивым почерком. В ней значится:\n\nЛюбому, кто может мне помочь.\n\nПрошу тебя, не оставь меня в нужде. Великий Небогрив держит меня в плену на острове в Южных морях.\n\nПо ночам я смотрю на чужие звезды, полускрытые листвой деревьев, но в самую хорошую погоду на северо-западе я вижу Южное взморье и большие корабли на юго-западе.\n\nМолю тебя, мой будущий спаситель, помоги мне.", progress = nil, completion = "Ты явился, чтобы освободить меня?", rewards = "Вы получите:\n\n"},
[595] = {title = "Пираты Кровавого паруса", objective = "Первый помощник Кразз попросил вас осмотреть залив на севере от Пиратской бухты.", description = "Ты не прочь подзаработать, а, <приятель/подружка>? Понять не могу, зачем сухопутной крысе вроде тебя понадобилось помогать Разбойникам Черноводья, но не гнать же тебя в шею!\n\nМы только что бросили якорь в Пиратской бухте, и уже прослышали, что наши соперники – гнусные, подлые пираты Кровавого Паруса – пустили корни в южной части Тернистой долины.\n\nВсе мои ребята слишком увлеклись грогом и девками! А мне нужен разведчик.\n\nОсмотри залив на севере от Пиратской бухты рядом с Гибельным берегом и расскажи мне, что там творится.", progress = nil, completion = "На крышке бочки лежит карта, на которой торопливо нацарапана пара слов, и несколько монет.", rewards = "Вы получите:\n\n"},
[596] = {title = "Ожерелье кровавых костей", objective = "Принесите Кин'вилаю 25 ожерелий Кровавых костей в лагерь Гром'гол.", description = "Меня послали в Гром'гол на помощь Нимбойе, но... У меня здесь свои дела.\n\nПлемя Кровавого Скальпа – наш заклятый враг. Трофеи, собранные с врагов, дают власть над ними. Ты можешь помочь нашему племени, открыв охоту на врага.\n\nПлемя Кровавого Скальпа живет на севере отсюда. Убей побольше троллей этого племени и забери у них ожерелья Кровавых костей. Собери как можно больше, и я награжу тебя.", progress = "Когда-нибудь племя Черного Копья сокрушит Кровавый Скальп! Ты принес мне ожерелья наших врагов?", completion = "А, замечательно. Я сварю их, высосу из них силу и сотру в порошок, и дух наших врагов ослабеет!\n\nВот, Томпсон. Возьми это в знак благодарности.", rewards = "Вы получите:\n\nКольцо из окровавленной кости"},
[597] = {title = "Пираты Кровавого паруса", objective = "Отнесите находку первому помощнику Краззу в Пиратскую бухту.", description = "На карте Пиратской бухты нарисован красный крестик именно там, где вы стоите.\n\nНиже имеется подпись:\n\n\"Разбейте здесь лагерь и сидите тихо. Не нападайте, пока не получите сигнал с южного командного поста. Если заметите кого постороннего, сразу убивайте.\"", progress = nil, completion = "Конечно, я помню тебя, |3-6(Воин). Вижу, ты уже вернулся из разведки...", rewards = "Вы получите:\n\n"},
[598] = {title = "Ожерелье расколотых костей", objective = "Принесите 25 ожерелий Расколотых костей Кин'вилаю в лагерь Гром'гол.", description = "Раз ты <принес/принесла> трофеи от племени Кровавого Скальпа, у меня есть для тебя другое задание. На юго-востоке живет племя Дробителей Черепов, и мы воевали с ними много лет. Хотя племя Черного Копья давно не живет в Тернистой долине, мы не забыли раздоров с Дробителями Черепов.\n\nТак что начни на них охоту. Собери побольше ожерельев расколотых костей и принеси их мне. Помоги нам, и заслужишь признательность племени Черного Копья.", progress = "Клан Дробителей Черепов проклянет день, когда они выступили против нас! Ты справился с моим заданием?", completion = "Велика твоя сила, раз тебе удалось заполучить эти ожерелья, Томпсон. Клан Дробителей Черепов пал под твоими ударами, как молодые ростки под тяжелыми шагами василиска!\n\nХвала твоим деяниям.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБотинки племени Черного КопьяСапоги племени Черного Копья\n\nВы также получите:\n\n"},
[599] = {title = "Пираты Кровавого паруса", objective = "Сообщите о запланированном нападении Кровавого Паруса командиру флота Морскому Рогу.", description = "Лопни моя селезенка! Значит, пираты Кровавого Паруса собираются напасть на Пиратскую бухту? Вот наглость-то! Этот город испокон века был в руках Пиратов Черноводья!\n\nЗначит, дела обстоят хуже, чем я думал. Немедленно расскажи об этом командиру флота Морскому Рогу! Этот старый морской волк шатается где-то по городу...", progress = nil, completion = "Пираты Кровавого Паруса собираются напасть на Пиратскую бухту? С тем же успехом они могут сразу сброситься с Отвесных скал. И все же ты оказал моему флоту большую услугу, передав мне эти сведения. Прими благодарность Разбойников Черноводья.", rewards = "Вы получите:\n\n"},
[600] = {title = "Рудник Торговой Компании", objective = "Принесите Шиззи Пуззыриксу из Пиратской бухты 10 синих Поющих кристаллов.", description = "Торговая Компания ведет операции в Тернистой долине, которые не дают трудолюбивым гоблинам вроде меня честно зарабатывать деньги! Пожалуйста, помоги мне!\n\nТорговая Компания обосновалась возле  Хрустальной шахты к северу отсюда. Внутрь они проникнуть не могут из-за злобных василисков, но все равно умудряются добывать Поющие кристаллы в ближайших холмах.\n\nОтбери у них эти кристаллы, показав тем самым, что джунгли им не принадлежат.\n\nИ.. э... принеси в доказательство сами кристаллы!", progress = "Ты принес мне кристаллы?? Они мне нужны!!!\n\nТо есть... Мне нужно знать, что гнусную Торговую Компанию вскоре вытеснят из Тернистой долины. Потому что, э-э-э, нам, честным предпринимателям, надо зарабатывать на хлеб насущный!", completion = "Отлично! Чудесно! Я за них много выручу!!!\n\nТорговая Компания сунулась не в те джунгли, а? Нам всем станет лучше, если они уберутся отсюда, верно?\n\nСпасибо, Томпсон. Ты сделал доброе дело.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГоблинский поджигательСеребряный заступ\n\nВы также получите:\n\n"},
[601] = {title = "Элементали воды", objective = "Принесите барону Ревилгазу в Пиратскую бухту 6 браслетов элементалей воды.", description = "Элементалей воды несомненно призвал Газбан, гоблин-волшебник, который нашел Камень Приливов, если верить слухам. Мы знаем, что обретший этот камень оказывается проклят, и с тех пор то существует, то нет...\n\nБыть может, удастся снять проклятье. Один даларанский маг может исследовать следы магии на браслетах элементалей. Отправляйся на остров и принеси несколько штук.", progress = "Как дела, Wrestlecake?", completion = "Я не могу определить навскидку, какие из этих браслетов подойдут, но хотя бы один должен сгодиться. Отнеси их в Даларан, пусть на них посмотрит маг.\n\nНе могу же я, в самом деле, уехать из Пиратской бухты ради какого-то старого мага?\n\nНе то, чтобы я беспокоился, что кто-то попытается занять мое место и стать новым бароном. Никто не посмеет встать на пути у Ревилгаза.", rewards = "Вы получите:\n\n"},
[602] = {title = "Магический анализ", objective = "Отнесите браслеты элементалей воды верховному магу Ансарему Руноплету в Даларан.", description = "Насколько я знаю, маги Даларана заняты восстановлением своего разрушенного города. Несомненно, один из них найдет время посмотреть на браслеты. Я знаю про магов одно – они не смогут устоять перед возможностью разгадать запутанную магическую головоломку.\n\nВозьми сумку с браслетами элементалей воды и узнай, не прольют ли они свет на проклятье Камня. Лучше всего обратиться к верховному магу Ансарему Руноплету. Я уже имел с ним дело, и его знания велики.", progress = "Простите, но сейчас я очень занят.", completion = "Камень Приливов? Очень интересно. Быть может, вас это удивит – несколько лет назад я написал книгу, посвященную легендам империи Гурубаши. Я знаю об этом камне довольно много.\n\nПо крайней мере, на одном из этих браслетов я вижу остатки магии, которые явно поддаются анализу.\n\nПосмотрим...", rewards = "Вы получите:\n\n"},
[603] = {title = "Ключ Ансарема", objective = "Поговорите с Кателиной в Пиратской бухте.", description = "Маг, который владеет Камнем, может умножить его силу при помощи некой точки фокуса... вроде алтаря. Чтобы не допустить этого, необходим предмет равной силы.\n\nКак ни странно, я знаю одну очень подходящую вещь: древний кинжал, еще одну из тролльских реликвий. Только есть... небольшая проблема.\n\nЯ нашел этот кинжал, странствуя по Тернистой долине, и отдал его своей своевольной дочери, которая сбежала в Пиратскую бухту и стала пираткой.", progress = nil, completion = "Мой кинжал? Ты издеваешься?\n\nТы хочешь услышать, как я превратилась из лучшего бойца на ножах в Пиратской бухте в посмешище для всех пиратов?\n\nЯ проиграла схватку с одним из пиратов Кровавого Паруса – они редкие мерзавцы! – и он забрал мой кинжал в качестве трофея.\n\nОдним острым языком славу бойца не поддержишь...", rewards = "Вы получите:\n\n"},
[604] = {title = "Пираты Кровавого Паруса", objective = "Командир флота Морской Рог попросил вас убить 10 висельников из шайки Кровавого Паруса и принести ему карты и приказы Кровавого Паруса.", description = "Кразз высоко ценит твою преданность Разбойникам Черноводья. Я доверяю тебе задание, очень важное для нашего флота.\n\nПроникни на так называемый южный командный пост, который пираты Кровавого Паруса основали на Диком взморье. Разграбь весь лагерь и принеси мне их карты и записи приказов. Так мы выясним, что замышляют эти ублюдки.", progress = "Эгей, Эфром. Какие вести ты несешь из южного лагеря Кровавого Паруса?", completion = "Отлично, Эфром. Теперь, когда их планы нам известны, это лишь вопрос времени.\n\nПодумать только, эти глупцы бросили якорь недалеко от мыса.", rewards = "Вы получите:\n\n"},
[605] = {title = "Осколки Поющих кристаллов", objective = "Принесите Шиззи Пуззыриксу 10 осколков Поющих кристаллов.", description = "Поющие кристаллы добывают только в Тернистой долине, и некоторые покупатели готовы немало за них отсыпать. Кому их толкнуть, мне ясно, но проклятая Торговая Компания не дает собирать кристаллы честным предпринимателям вроде меня.\n\nЯ хочу тебя нанять.\n\nВасилиски Тернистой долины питаются этими кристаллами. Благодаря им у них прочная шкура, и иногда из нее можно добыть качественные кристаллы.\n\nГодится шкура любого василиска, но на северном побережье, южнее Зул'Кунды, они не такие свирепые.", progress = "Удалось добыть осколки? Процент с выручки получишь!", completion = "Ага! Отличные осколки, Эфром. То, что надо!\n\nВот твоя доля, и... с тобой приятно иметь дело.", rewards = "Вы получите:\n\n"},
[606] = {title = "Напугать трусишку", objective = "Отнесите 5 потрохов горилл из Мглистой долины Филиппу \"Трусишке\"  в Пиратскую Бухту.", description = "Вот кого я терпеть не могу, так это тех, кто не отдает карточные долги! Мне задолжали несколько партнеров по игре. Не поможешь собрать с них мзду?\n\nВо-первых, есть Филипп \"Трусишка\", который вечно торчит у причала. Он проиграл мне кругленькую сумму на прошлой неделе, и я хочу ее получить! Только для этого надо его хорошенько припугнуть.\n\nСтупай, поохоться на старых горилл из Мглистой долины. Набери из них потрохов и отнеси Трусишке. Только не говори, что они обезьяньи, пусть в штаны со страху наложит!", progress = "Эй, мне не нравится, как вы на меня смотрите, сударь.", completion = "Ох! Откуда у вас это? Нет, не говорите. Я не хочу знать!\n\nКто вас прислал? Морской волк?", rewards = "Вы получите:\n\n"},
[607] = {title = "Возвращение к МакКинли", objective = "Отнесите плату Трусишки \"Морскому волку\" Маккинли", description = "Вот, возьмите этот кошель и отнесите его Морскому Волку. И передайте, что я собирался ему заплатить! Клянусь!!!\n\nЯ всего лишь немного перебрал и заблудился по пути, и... знаете, как бывает. Он поймет – не нужно применять силу!", progress = "Ладно, Эфром. Где долг Трусишки?", completion = "Хе-хе, отличная работа! И как, сильно Трусишка перетрусил, когда ты показал ему потроха?\n\nХа! Я читаю его как раскрытую книгу! Играя с ним в карты, нельзя не выиграть!\n\nСпасибо за помощь, Эфром. Пришел твой черед получить плату...", rewards = "Вы получите:\n\n"},
[608] = {title = "Пираты Кровавого Паруса", objective = "Командир флота Морской Рог попросил вас убить капитана Штиллеца, капитана Кильвателя и командира флота Фираллона.", description = "Ну и наглец этот Фираллон! Он бы и Озеро Хрустальное на лодке не переплыл, куда ему вести против нас весь свой флот!\n\nПираты Кровавого Паруса поплатятся за свою беспечность. Теперь мы знаем все их планы и нападем первыми.\n\nХотя зачем посылать целый флот, если хватит отряда отважных искателей приключений? <имя>, возьми с собой самых опытных бойцов, ступай на место высадки Фираллона и лиши пиратов Кровавого Паруса всех командиров. Весь флот отправится на дно следом за ними...", progress = nil, completion = "Ах, что за великий день для Разбойников Черноводья! Трижды ура тебе, Томпсон!", rewards = "Вы получите:\n\nЧерноводский мундир"},
[609] = {title = "Должники вуду", objective = "Принесите деревянную ногу Моури, золотую подзорную трубу Джон-Джона и огромное кольцо Чаки \"Морскому волку\" Маккинли в Пиратскую бухту.", description = "Список сокращается, но должники все еще остались.\n\nДалее идут Моури \"Деревянная Нога\" Вилкинс, Джон-Джон Ворон и Чаки \"Недотепа\".\n\nЭти паршивые собаки просрочили платежи на много месяцев, я-то думал, они поэтому из города сбежали! Потом, правда, мне сказали, что их прокляли и заколдовали, и они бродят по развалинам в джунглях. Но меня их судьба не волнует – мне бы свое вернуть!\n\nИх видели на северо-востоке отсюда, в руинах Абораза и руинах Жубуваля. Отыщи их и забери у них мои вещи.", progress = "Ну что, нашел этих трех зараз? Забрал у них ценности?", completion = "Отлично! За это я выручу кругленькую сумму, особенно за то, что спрятано внутри ноги Моури! Спасибо, Томпсон!\n\nНадеюсь, эти трое усвоили урок: никогда не ставь на кон то, что не можешь отдать.\n\nМожет быть, они поняли это слишком поздно... Но надо было думать, с кем садишься играть.", rewards = "Вы получите:\n\n"},
[610] = {title = "\"Красавчик\" Дункан", objective = "Отберите меч Кателины у \"Красавчика\" Дункана.", description = "Так тебя прислал мой ОТЕЦ? Я думала, старик давно махнул на меня рукой.\n\nЭто он виноват, что я сбежала. С чего он взял, что я только и мечтаю о скучной жизни среди заплесневелых книг и седых, горбатых и надутых магов!\n\nЕсли тебе нужен мой кинжал, можешь отобрать его у \"Красавчика\" Дункана, одного из пиратов Кровавого Паруса. Приставь ему нож к спине, и он с радостью отдаст тебе мой клинок.", progress = "Ты знаешь, что меня раньше никто не побеждал? Да, бывало, ранили, без этого ни одна поножовщина не обходится, но он долбанул меня по голове, я и отключилась. Пришла в себя – а кинжала нет.\n\nПо моему прозвищу легко понять, что без кинжала мне не жизнь, и мне нужен именно этот кинжал.", completion = "Тебе удалось одолеть Дункана? Значит, ты не совсем салага, как кажется с первого взгляда.\n\nПожалуй, это означает и то, что мне не стоит в ближайшее время вызывать тебя на бой!", rewards = "Вы получите:\n\n"},
[611] = {title = "Проклятье приливов", objective = "Уничтожьте Алтарь Приливов при помощи меча Кателины, убейте Газбана и принесите Камень Приливов и меч Кателины барону Ревилгазу.", description = "Значит, ты ищешь какой-то алтарь? Я не так хорошо разбираюсь в развалинах, как мой отец, но мне приходилось слышать о затонувшем городе троллей рядом с островом, про который ты <спрашивал/спрашивала>. Посмотри там.\n\nТы <вернул/вернула> мне нож, поэтому можешь пока им воспользоваться... но не забудь принести его обратно, когда закончишь дела!", progress = "Тебе удалось добыть для меня Камень Приливов, Чиффнир? Я уже приготовил для него место и купил красивую подставку.", completion = "Поразительно! Камень Приливов! Он займет достойное место в моей коллекции древних артефактов троллей. Видишь, создается впечатление, что это и есть окаменевший прилив? Великолепно!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nОдеяние Прозрачных вод"},
[613] = {title = "Вскрыть ногу Моури", objective = "Принесите \"Морскому Волку\" Маккинли из Пиратской бухты ключ Моури.", description = "Проклятье! Этот Моури поставил на свою ногу замок, и я не могу ее открыть! Его сокровища внутри, и именно их он мне должен!\n\nМне необходим ключ, чтобы вскрыть этот замок. Мори нередко играл в кости с ограми Мош'Огг у них на холме на северо-востоке. Он успел рассказать мне, что ему пришлось спасаться бегством после прошлой игры, потому что больно много выиграл. Может быть, его ключ у огров.\n\nНо если так, придется убить целую толпу, чтобы его отыскать...", progress = "Эгей, Томпсон! Нашел ключ Моури?", completion = "Ты нашел его! Тысяча благодарностей. Ты мне так помог!\n\nВот, возьми – ты заработал это сполна!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКоллекционный щит"},
[614] = {title = "Сундук капитана", objective = "Верните Гекельберри Шмотту из Пиратской бухты его сундук.", description = "Когда-то у меня был корабль, на котором я ходил до самого Кабестана в Калимдоре, и репутация у меня была безупречная.\n\nПока…\n\nПока не появились проклятые морские великаны! Они разбили мой корабль, поубивали всю команду, а меня отправили на шлюпке в Пиратскую бухту. А один из гигантов, Горлаш, украл мой капитанский сундук, мол табакерка из него выйдет неплохая. Наглец!\n\nГоворят, Горлаш бродит по берегу к востоку отсюда. Найди его и верни мой сундук! Благодарность моя не будет знать предела.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nНаручи Кровавой повязки"},
[615] = {title = "Капитанская сабля", objective = "Поговорите с Салагой.После того как эти проклятые великаны уничтожили мой корабль, я купил еще один. Назвал его \"Месть Смоттса\", запасся продовольствием, нанял команду и отправился в поисках этих злодеев. Найти-то я их нашел, но... они снова мне надавали по шее. \"Месть Смоттса\" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку.\n\nУ другого великана, Неголаша, моя сабля.\n\nСразись с Неголашем и принеси мне мою саблю!\n\nМожешь поговорить со Салагой, поваром с \"Мести Смоттса\", который выжил в последней битве. Он поможет тебе найти великана.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "После того как эти проклятые великаны уничтожили мой корабль, я купил еще один. Назвал его \"Месть Смоттса\", запасся продовольствием, нанял команду и отправился в поисках этих злодеев. Найти-то я их нашел, но... они снова мне надавали по шее. \"Месть Смоттса\" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку.\n\nУ другого великана, Неголаша, моя сабля.\n\nСразись с Неголашем и принеси мне мою саблю!\n\nМожешь поговорить со Салагой, поваром с \"Мести Смоттса\", который выжил в последней битве. Он поможет тебе найти великана.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[616] = {title = "Остров духов", objective = "Поговорите с бароном Ревилгазом в Пиратской бухте.", description = "Барон Ревилгаз велел мне не упускать слухов о странных событиях и местах в округе Пиратской бухты и всей Тернистой долины. Обычно я не придаю большого значения историям про призраков и прочую чушь, но моряки в таверне говорили об острове элементалей недалеко от побережья. Мол, там духи Воды и сумасшедший призрак гоблина.\n\nЕсли тебе встретится Ревилгаз, перескажешь ему эту историю?", progress = nil, completion = "Интересно. Кажется, я недавно читал книгу, в которой говорилось о чем-то в этом духе…\n\nА, разумеется, легенды троллей. Если Кразек говорит правду, то вскоре к моей коллекции древних артефактов и реликвий добавится Камень Приливов.", rewards = "Вы получите:\n\n"},
[617] = {title = "Кипы акириса", objective = "Принесите каперу Блоудсу из Пиратской бухты 10 свертков со стеблями акириса.", description = "Ищешь работу, <имя>? Если ты не боишься трудностей, могу тебе предложить одно дельце.\n\nУ меня есть дружбан, Гроу, который зашибает бешеные деньги, продавая то, что наги называют стеблями акириса. Это очень ценная морская водоросль. Он за нее отлично платит.\n\nПритащи мне 10 стеблей этой травки, и мы сторгуемся. Наги живут на берегу к северу отсюда.", progress = "Если ты не по делу, вали отсюда, Эфром.", completion = "Молодец, Эфром. Не так уж трудно было добыть 10 стеблей акириса, а? Я вполне сочувствую нагам, но каждый как-то должен зарабатывать на жизнь.", rewards = "Вы получите:\n\nОбжигающий кушак"},
[618] = {title = "Бой с Неголашем", objective = "Отнесите 10 жареных крылышек канюка и 5 бутылок экзотического вина в спасательную шлюпку капитана Смоттса.\n\nУбейте Неголаша и отнесите абордажную саблю Смоттса хозяину в Тернистую долину.", description = "Неголаш – великан-обжора.\n\nКогда они уничтожили наш корабль, Неголаш бросился прямиком на кухню. В отличие от его товарищей, команда его не очень интересовала. Ему хотелось вина... и жареных крылышек канюка. Это мое коронное блюдо, рецепт я привез из самих Бесплодных земель!\n\nЕсли ты хочешь приманить великана, добудь вина и кучу крылышек канюка. Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда. Когда Неголаш почует запах еды, он непременно явится!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКомпас Шмотта"},
[619] = {title = "Приманка для Неголаша", objective = "Перед вами брошенная спасательная шлюпка. На борту у нее красуется полустертая поблекшая надпись:\n\n\"Месть Шмотта\".", description = nil, progress = "Перед вами брошенная спасательная шлюпка. На борту у нее красуется полустертая поблекшая надпись:\n\n\"Месть Шмотта\".", completion = "Вы нагружаете лодку едой и выпивкой...", rewards = nil},
[620] = {title = "Кушак с монограммой", objective = "Верните кушак с монограммой владельцу.", description = "Вдоль каймы кушака вышита монограмма \"ГШ\".Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[621] = {title = "Тайна Занзила", objective = "Принесите Шиззи Пуззыриксу из Пиратской бухты 12 образцов смеси Занзила.", description = "Занзил Отверженный и его приспешники живут в руинах Жубуваля и Абораза, на северо-востоке от Пиратской бухты. Его изгнали из племени. Почему? Ну…\n\nЗанзил научился подчинять себе разум других, и его страшатся собственные командиры. Он заставляет своих приспешников принимать смесь из тропических растений, которые подавляют их волю и укрепляют тела.\n\nЭта смесь пригодилась бы и другим, желающим подчинить себе других.\n\nПринеси мне образцы этой смеси, я найду им применение.", progress = "Ты принес мне образцы смеси Занзила?", completion = "А, отлично! Вот твоя плата.\n\nИ еще немного сверх... за молчание.", rewards = "Вы получите:\n\nПояс проклятия"},
[622] = {title = "Возвращение к капралу Калебу.", objective = "Отнесите целый горшок Крейвела капралу Калебу в Лагерь повстанцев.", description = "Пока тебя не было, я починил твой горшок и даже приделал к нему свисток. Больше того, смотри! На дне появился новый нож, который запросто рубит кости!\n\nДа-да, теперь этот горшок – настоящая радость повара! Не сомневаюсь, владелец будет доволен.", progress = "Привет, Бронетазик. Добрался до Пиратской бухты без приключений? Починил ли гоблин Кразек мой горшок??", completion = "Готово! Чудесно, я могу готовить обед! Большое спасибо, Бронетазик.\n\nНадеюсь, в Пиратской бухте с тобой ничего не случилось. Там всякое бывает... Говорят, иногда гоблины утаскивают пьяных моряков на галеры, приковывают цепями и увозят неизвестно куда...", rewards = "Вы получите:\n\nШапка Гармонии"},
[623] = {title = "Кипы акириса", objective = "Принесите сверток со стеблями акириса каперу Грою в Терамор.", description = "<имя>, раз уж ты здесь, я тебе вот что скажу. Пока тебя не было, я получил послание от Гроу. Его очень порадовала последняя поставка, и клиент немедленно захотел получить еще акириса.\n\nЯ собираюсь в Терамор не раньше, чем через неделю, но если ты не против двинуть в путь прямо сейчас, почему бы тебе не отвезти товар?\n\nХочешь поприключаться? Ты знаешь, где находятся Пылевые топи? Только будь <осторожен/осторожна>, в Тераморе может быть опасно.", progress = "А?", completion = "Что?! Мне некогда с тобой трепаться, |3-6(Маг). Если ты собираешься попусту тратить мое время, лучше сразу убирайся.\n\nЧто? Тебя прислал Блоудс, да?\n\n*Капер Грой внимательно рассматривает сверток.*\n\nНеплохо, неплохо. Еще один сверток – и клиент будет счастлив.\n\nДумаю, следующий вопрос будет про деньги, а? Ну разумеется!\n\nВот, бери монеты и совет в придачу: убирайся-ка подобру-поздорову.", rewards = "Вы получите:\n\n"},
[624] = {title = "Загадка Кортелло", objective = "Разгадай загадку!", description = "Есть мост, изукрашен резьбою, красивый на нем узор\nК востоку от Мертвого Ветра и к югу от Красногорья\nПод ним тебя ждет подсказка ль, улика ль – как назовешь.\nИ будет на Болоте Печали лежать, пока не найдешь.", progress = nil, completion = "Намокший пергамент дает вам новую подсказку...", rewards = "Вы получите:\n\n"},
[625] = {title = "Загадка Кортелло", objective = "Разгадай загадку!", description = "Калимдор далекий ждет тебя давно,\nГде надеждам к сроку сбыться не дано.\nТы в Степях почуешь вкус пыли на губах,\nНу а в топях пылевых – лишь печаль и страх.\nНо на юго-запад путь тебя манит,\nМрак пещеры тайну для тебя хранит.", progress = nil, completion = "Вы находите заплесневелый свиток.", rewards = "Вы получите:\n\n"},
[626] = {title = "Загадка Кортелло", objective = "Разгадай загадку!", description = "Спеши же в славный Лордерон! Давно тебя он ждет.\nТам с мором, гибелью и тьмой сражается народ. \nПусть не страшит тебя война и битвы шум и гам – \nЗато задание свое исполнить сможешь там. \nВот берег Внутренних земель, где шумный водопад, \nТам, там под водами его тебя ждет дивный клад!", progress = nil, completion = "Вы открываете сундук и обнаруживаете...", rewards = "Вы получите:\n\nРанец исследователя"},
[627] = {title = "Просьба Кразека", objective = "Принесите 4 партии бедной кровавой руды Кразеку в Пиратскую бухту.", description = "В Теснине Сухоусов - далеко на севере, в нагорье Арати - есть пещера. Там добывают редкие полезные ископаемые – кровавые камни. Да, они там не лучшего качества, но даже самые плохие кровавые камни высоко ценятся... теми, кто знает что с ними делать.\n\nЯ – знаю.\n\nЯ починю твой разбитый горшок, но пока я работаю над ним, принеси мне образцы кровавого камня. Если ты принесешь их достаточно, я награжу тебя.\n\nАх, да, если ты не умеешь добывать полезные ископаемые... попроси кого-нибудь помочь тебе!", progress = "Привет, Борро. Удалось добыть кровавые камни?", completion = "А, великолепно! Ты оказал мне большую услугу.\n\nВот твоя плата...", rewards = "Вы получите:\n\n"},
[628] = {title = "Эксельзиор", objective = "Принесите Дриззлику из Пиратской бухты шкуру большого морского кроколиска.", description = "Подбой готов, осталось сделать верхний слой. На него идут только наилучшие шкуры взрослых кроколисков. Они крепче и представляют собой лучшую основу для узоров, которыми славится линия превосходных сапог.\n\nХотя найти эту ценную шкуру нелегко, мне подходит лишь шкура старого солоноводного кроколиска. Эти твари выходят лишь на защиту молоди, поэтому может понадобиться убить несколько молодых зверей, чтобы выманить нужного.", progress = "Я где-то читал, что солоноводные кроколиски постепенно вымирают... это повредит моему делу, а?\n\nВпрочем, надеюсь, ты добыл мне шкуру старого солоноводного кроколиска!", completion = "Здорово! Благодаря твоей помощи я выполню этот заказ и отправлю его директору Ридлвоксу на следующем корабле в Нижнюю шахту. Быстрее, чем обещал!\n\nЯ сделал лишнюю пару, возьми ее за работу. Все за счет Дриззлика.\n\nИ помни, если нужны тебе сапоги, к Дриззлику ты поскорей прибеги!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nСапоги класса \"люкс\""},
[629] = {title = "Коварный риф", objective = "Принесите осколок таблички Кин'вилаю в лагерь Гром'гол.", description = "Давным-давно вода затопила древний город троллей рядом с Гибельным берегом. Мы зовем это место Коварным рифом, потому что в развалинах поселились мурлоки, которые нападают на всех, кто осмелится приблизиться.\n\nСреди руин есть древняя табличка, повествующая о древнем герое троллей, Гри'леке. Это сказание священно в племени Черного Копья, и хотя сама табличка слишком велика и ее не унесешь, я хочу получить хотя бы осколок, чтобы поместить его в святилище в нашем новом городе, Оргриммаре.", progress = "Я жду, когда ты принесешь мне осколок таблички, Томпсон.", completion = "Хорошо. Когда я вернусь в Оргриммар, этот осколок будет помещен в священное место. Он будет напоминать нам о силе и чести Гри'лека.\n\nСпасибо, Томпсон. Твои деяния говорят о крепнущей дружбе с племенем Черного Копья.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[630] = {title = "Послание в бутылке", objective = "Убейте Короля Муклу, возвращайтесь с ключом к принцессе Пубе и освободите ее.", description = "<имя>, ты и те, кого ты сможешь позвать мне на помощь – моя последняя надежда. Меня держит в плену великий Король Мукла. Он повелевает зверями на этом острове, и они держат меня здесь помимо моей воли на этой цепи. Если ты сможешь убить моего мучителя и отыскать ключ к кандалам, я буду навеки у тебя в долгу.\n\nЯ часто слышу шаги Короля Муклы на юго-восточной стороне острова. Соблюдай осторожность, справиться с ним нелегко.", progress = "Хвала предкам, кто-то пришел мне на помощь. Ты несешь мне ключ, а вместе с ним и свободу?", completion = "Ты спас меня от великого бесчестья, Ыгрок. Будь это в моей власти, я приняла бы тебя в свое племя. Пока же я могу лишь вручить тебе этот залог моей благодарности за проявленное мужество и благородство.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nНосовое кольцо Пубы"},
[631] = {title = "Мост Тандола", objective = "Найдите Ржавого Засова.", description = "Я помню, как горы содрогнулись от ужаснейшего взрыва. Не слабо рвануло, скажу я тебе!\n\nНа мосту Тандола погибли лучшие из наших солдат. Длинная Коса говорит, что дворфы Черного Железа еще заплатят нам за все до конца этой войны.\n\nНо сейчас у нас отчаянное положение, подкрепления все нет и нет. Длинная Коса отправил Ржавого Засова на разведку к восточному мосту – посмотреть, можно ли защитить мост теми силами, которые сейчас у нас есть.\n\nПрошло уже несколько дней. Мы не можем отправить солдат на поиски – Дун Модр осажден...\n\nБыть может, ты согласишься поискать нашего разведчика?", progress = nil, completion = "Вы натыкаетесь на труп дворфа. На шлеме отчетливо видна надпись: \"Эбенезер Ржавый Засов\".", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[632] = {title = "Мост Тандола", objective = "Принесите печальное известие Рагу Каменщику и отдайте ему пергамент, найденный возле трупа Ржавого Засова.", description = "Кажется, бедняга Ржавый Засов попал в засаду дворфов Черного Железа. Возле его остывшего тела лежит клочок пергамента.\n\nРасскажите Рагу Каменщику о случившемся и передайте ему пергамент.", progress = "Есть новости о Ржавом Засове, Эфром?", completion = "Какой ужас... Бедный, бедный Эбенезер.", rewards = "Вы получите:\n\n"},
[633] = {title = "Мост Тандола", objective = "Уничтожьте взрывчатку.", description = "Во имя Света, только не это! Бедняга Ржавый Засов. Ты меня <опечалил/опечалила>, <имя>.\n\nНо его жертва будет не напрасной! В пергаменте сказано, что Кам Гневливый – тот, кто организовал нападение, – приказал заложить взрывчатку под мостом Тандола на границе с нагорьем Арати.\n\nЕсли ему удастся очередная диверсия, то мы лишимся поставок с севера! Взрыв нужно предотвратить. Сделай все возможное, чтобы спасти мост Тандола, и возвращайся ко мне.\n\nТы – наша единственная надежда.", progress = "Умоляю, избавься от проклятой взрывчатки, пока не поздно!", completion = "Мост спасен! Ты помог не только мне и королю Магни, но и всему народу Каз Модана!\n\nТеперь нужно продержаться до прибытия подкрепления...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлащ дворфийского стражникаТрясинные брюки\n\nВы также получите:\n\n"},
[634] = {title = "Просьба о помощи", objective = "Найдите капитана Ниалс в Опорном пункте.", description = "Я попрошу тебя о еще одном одолжении, <класс>. Мы ожидаем подкрепление из Стальгорна. Рогго принес сведения о лагере воинов Альянса к северу отсюда. Они расположились на нагорье Арати, возле Опорного пункта.\n\nОтправься туда и отыщи капитана Ниалс. Спроси у очаровательного капитана, не выделит ли Альянс нам отряд солдат, чтобы помочь отбить Дун Модр и мост Тандола.", progress = nil, completion = "Передай мои соболезнования Длинной Косе и его солдатам. Я искренне опечален вестью о трагедии на мосту Тандола и падении Дун Модра...\n\nНо знайте, что и Стромгард пал! Именно поэтому мы сейчас стоим у Опорного пункта. Впереди – битва за наш великий город.\n\nДолг и честь не позволяют мне покинуть нагорье до тех пор, пока над Стромгардом не взовьется гордое знамя нашего короля! Придется Длинной Косе обходиться своими силами...", rewards = "Вы получите:\n\n"},
[635] = {title = "Горный кристалл", objective = "Найдите кристалл из видения.\n\nПрилагается предмет: \n", description = "Осколок пульсирует у вас в руках…\n\nВам кажется, что он молит о чем-то, пытается передать послание того, кто нуждается в вашей помощи.\n\nВам является видение – в северных горах Арати из земли торчит сияющий кристалл.\n\nВас так и тянет к этому месту.", progress = nil, completion = "Кристалл пульсирует, будто в него заключена живая сила.", rewards = "Вы получите:\n\n"},
[637] = {title = "Письмо Салли Балу", objective = "Отнесите письмо Салли Баллу Саре Баллу.", description = "Промокший и потрепанный конверт разваливается в руках, и в ладонях остается письмо на нескольких страницах. Каждая буковка выведена с удивительной аккуратностью.\n\nПисьмо адресовано некой миссис Саре Баллу из Стальгорна. Оно начинается: \"Дорогая Сара...\"", progress = "Похоже, на твою долю выпало немало странствий и нелегких битв, |3-6(Друид). Да, лихие настали времена. Что нового творится в мире?", completion = "Неужели ты видел моего Салли подо льдом? Прошу, скажи, что это не так!\n\nДай-ка я прочитаю, что он написал...", rewards = "Вы получите:\n\n"},
[638] = {title = "Троллебой", objective = "Отправляйтесь в Павший Молот и поговорите с Зенгу.", description = "Торас Троллебой мертв, а Стромгард разрушен. Вол'джин велел мне приложить все усилия, чтобы вырвать легендарный меч Трол'калар из рук людей. Тогда мы сможем воспользоваться им в грядущих битвах с троллями Зул'Гуруба.\n\nЗенгу, один из наших опытных охотников, отправился в Павший Молот в северо-восточной части нагорья Арати, чтобы проследить за этим.", progress = nil, completion = "Как дела, |3-6(Охотник)? Вол'джин дал нам непростое задание, и если ты хочешь предложить свою помощь, мы с радостью ее примем.", rewards = "Вы получите:\n\n"},
[639] = {title = "Печать Штрома", objective = "Добудьте печать Штрома для Зенгу в Павшем Молоте.", description = "В древние времена тролли воевали с Араторской империей и нашим самым могучим противником, лордом Игнеусом Стромским по прозвищу Троллебой. Он бросался в бой с мечом Трол'каларом в руке – \"убийцей троллей\", на их древнем наречии.\n\nНо теперь сыновья Троллебоя ослабели, а цитадель их разрушена.\n\nМеч защищен несколькими печатями, которые были распределены между выжившими защитниками Стромгарда, и мы должны их отыскать.\n\nПервую из печатей захватил Синдикат, должно быть, она находится у одного из их людей в Стромгарде.", progress = "Вы еще не выяснили местонахождение первой печати? Скорее всего, она находится у кого-то из посланников Синдиката в Стромгарде.", completion = "Отлично, дружище. Это хорошее начало для сбора всех печатей, которые нам понадобятся, чтобы извлечь Трол'калар из могилы Троллебоя.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[640] = {title = "Сломанная печать", objective = "Добудьте у защитников Стромгарда 11 фрагментов печати и принесите их Тор'гану в Павший Молот.", description = "Могила Тораса Троллебоя защищена тремя печатями, первую из которых вы уже раздобыли у Синдиката. Остальные две достать будет сложнее, поскольку ими владеет гораздо более сильное ополчение Стромгарда.\n\nПечать Торадина была разделена на одиннадцать частей сыном Тораса Галеном, а потом он распределил эти фрагменты между стромгардскими защитниками Соберите фрагменты и принесите их Тор'гану, троллю-шаману, – он сможет восстановить целостность печати.", progress = "Тром'ка, |3-6(Разбойник). Зенгу сообщил, что вам нужна моя помощь.", completion = "А, так вам нужно воссоздать печать! Это будет не слишком сложно... все фрагменты на месте, а магическую структуру будет легко преобразовать.\n\nПожалуй, вам бы лучше закрыть глаза.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[641] = {title = "Печать Торадина", objective = "Принесите восстановленную печать Торадина Зенгу в Павший Молот.", description = "Восстановление прошло без сучка и задоринки. Теперь печать можно использовать, чтобы отпереть могилу Троллебоя. Верните печать Зенгу. Несомненно, у него найдутся еще для вас задания.", progress = "Томпсон! У вас есть вторая печать?", completion = "Мы на полпути к тому, чтобы извлечь Трол'калар из могилы Троллебоя. Мы не вполне уверены в том, где находится третья печать, поскольку владеющие ею, похоже, много передвигаются по нагорью Арати. Но я верю, что вам удастся ее отыскать.", rewards = "Вы получите:\n\n"},
[642] = {title = "Пойманная принцесса", objective = "Соберите 12 крупиц Мощи Мизраэли и принесите их к радужным осколкам в Теснине Сухоусов.", description = "Меня зовут Мизраэль. Я принцесса духов земли, и мои пленители – гиганты – поймали меня в ловушку глубоко под нагорьем Арати. С миром на поверхности я могу говорить только при помощи этих кристаллов.\n\nПожалуйста, помоги мне. У союзников гигантов – кобольдов из племени Сухоусов – есть такие же кристаллы, они находятся в Теснине Сухоусов, к востоку отсюда. Чтобы объединить их силу, нужно отобрать у кобольдов крупицы Мощи Мизраэли.\n\nПрошу тебя, <имя>, помоги мне!", progress = "Эта группа кристаллов выглядит очень похожей на кристаллы Мизраэли. Однако они не излучают такое же чувство надежности и безопасности.", completion = "Ах, тебе удалось активировать те кристаллы. Я уже чувствую, что начинаю приходить в себя!\n\nНо, увы, до свободы еще далеко...", rewards = "Вы получите:\n\n"},
[643] = {title = "Печать Аратора", objective = "Добудьте Печать Аратора и принесите ее Зенгу в Павший Молот.", description = "Хотя принц едва ли может похвастаться властью над Стромгардом, не говоря уж обо всем нагорье Арати, тем не менее он разъезжает с остатками своей кавалерии по всей области. Я не могу сказать, зачем он это делает, но кто поймет, как мыслят эти люди?\n\nКакова бы ни была причина, более важно то, что он отдал одну из своих печатей лейтенанту Храброзову, командиру кавалерии. Найдите его и принесите мне эту печать.", progress = "Храброзова будет нелегко выследить, Дэмрод. Верхом он может перемещаться очень быстро. Тем не менее эта печать нам необходима.", completion = "Потеря командира кавалерийского отряда станет серьезным ударом для стромгардских защитников. К тому же – что еще лучше – это значит, что нам осталось найти лишь одну печать, чтобы заполучить себе Трол'калар.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[644] = {title = "Печать Троллебоя", objective = "Убейте принца Галена Троллебоя и принесите печать Троллебоя Зенгу в Павший Молот.", description = "Последняя из печатей, необходимых, чтобы отпереть могилу Тораса Троллебоя, хранится у его сына. Он обитает в Стромгарде, в часовне, в том районе, что контролируется ополчением. У принца Галена хорошая охрана, да и сам он боец не промах, так что это задание может оказаться наиболее сложным.", progress = "Вы вернулись, Дэмрод. Прерван ли род Игнеуса Троллебоя?", completion = "Удачный денек, |3-6(Шаман). Кровь рода Троллебоев больше не будет беспокоить мой народ, и печати, необходимые для извлечения Трол'калара, теперь у нас в руках. Скоро, очень скоро мы ударим по ненавистным троллям Зул'Гуруба.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[645] = {title = "Трол'калар", objective = "Достаньте Трол'калар из могилы Троллебоя в Стромгарде.", description = "Что это? Когда четыре печати оказались вместе, они соединились, образовав единую печать. Нет сомнений, что она сможет разбить охранные заклинания, наложенные на могилу Троллебоя.\n\nОстанки Троллебоя захоронены в святилище позади часовни в Стромгарде. Принесите же Трол'калар.", progress = "Углубления в камне на верхней стороне надгробия Троллебоя совпадают с сияющими линиями печати Игнеуса...", completion = "При совмещении линий на верхней стороне могилы Троллебоя с сияющими линиями печати Игнеуса вспышка света поглощает печать, и легендарный меч Трол'калар освобождается из каменных объятий.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[646] = {title = "Трол'калар", objective = "Отнесите меч Трол'калар Зенгу в Павший Молот.", description = "Медленно угасает свет. Меч Трол'калар, упрятанный в каменные ножны, освобожден.", progress = "Дэмрод! Вам удалось забрать меч?", completion = "Поколениями силы Штрома и Аратора истребляли троллей. Теперь их величайшее оружие – в наших руках. Больше мы не будем топтаться на месте во влажных лесах Зул'Гуруба.\n\nВы оказали нам серьезную помощь, Дэмрод, и тролли Черного Копья в долгу перед вами.\n\nЯ позабочусь о том, чтобы меч был доставлен Нимбойе в Гром'гол.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБроня кровавого оттенкаЩит воина бездны\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[647] = {title = "Самогон Маккрила", objective = "Отнесите самогон Маккрила мастеру-пивовару Бочкопузу в Южнобережье.", description = "Ох, и хлебнул я вчера самогона! Знай Длиннокос, что я отрубился на посту, он оторвал бы мне голову.\n\nБашка раскалывается, жуть. И в ушах гремит, будто осадные орудия вокруг грохочут.\n\nОй-ой, а времени сколько! Я обещал мастеру-пивовару Бочкопузу из Южнобережья вернуть должок своим самогоном.\n\nА осталось до истечения срока действия долга всего 15 минут! Отнеси ему самогон, будь другом! И поскорее!", progress = "Что хорошего скажешь, |3-6(человек)?", completion = "Ах, ничто не греет так, как глоток самогона Туманника Маккрила! А я-то думал, что этот паразит опять просрочит платеж. Спасибо, дружище! Огромное тебе спасибо!", rewards = "Вы получите:\n\n"},
[648] = {title = "Спасти КПХ-17/TN!", objective = "Сопроводите КПХ-17/TN в Порт Картеля, затем сообщить об этом Карлсу Пропеллерзу в Пиратской бухте.", description = "Из динамика снова слышится искаженный помехами голос гнома:\n\n\"Мне необходимо перегнать КПХ-17/TN в просторное и безопасное место, чтобы провести длительную процедуру наладки. Проводите робота из того места, где вы его обнаружили, в... ну, скажем, в Порт Картеля! Это самое подходящее место, и там достаточно просторно, чтобы подготовить аппарат к новому полету.\n\nПроводите робота в порт, а затем сообщите об этом мне. Я живу в Пиратской бухте, меня зовут Карлс Пропеллерз. Конец связи!\"", progress = nil, completion = "А, так это вы великий спаситель КПХ-17/TN! У меня просто слов нет, настолько я вам благодарен! Моя серия автономных роботов постоянно нуждается в усовершенствованиях, однако ваша помощь сберегла мне немало часов кропотливой работы, и дорогостоящих деталей вдобавок!\n\nПрошу вас, выбирайте любую из этих готовых моделей. Еще раз спасибо вам, Эфром! Мы с моими роботами – ваши должники!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОптоматический отражательТермовкусовой яичный таймер\n\nВы также получите:\n\n"},
[649] = {title = "За медовухой", objective = "Поговорите с Мальтоном Дрофферсом в Оргриммаре.", description = "Хочу я поручить тебе одно дельце. Если ты любишь добрую медовуху, как и я, оно тебе понравится. Медовуха!\n\nЭто напиток, балда!\n\nНа заброшенной заставе Орды хранится запас \"Медовой зыби\" Внутренних земель. Такого славного пойла нынче больше не делают! Один из этих балбесов, дружков Мальтона, знает туда дорогу. Сходи к нему, принеси бочонок медовухи и еще пару бутылок мне лично. Поговори с Мальтоном, он тебе все расскажет.", progress = nil, completion = "А, это насчет медовухи, которая нужна папаше? Он собирается торговать ею в таверне. За настоящую \"Медовую зыбь\" можно выручить много денег... Я знаю того, кто может ее добыть. Он живет во Внутренних землях. Но вот какая штука: он того... эльф он. Высший.\n\nНо ты не бойся, он хороший высший эльф, он не из Альянса. То есть он хороший, как выпьет. А это дело он любит. Очень любит.", rewards = "Вы получите:\n\n"},
[650] = {title = "За медовухой", objective = "Поговорите с Гилверадином Ловчим Солнца во Внутренних землях.", description = "Отправляйся к эльфу по имени Гилверадин Ловчий Солнца. Он так разбирается в винах, что умеет по запаху определить не только сорт вина, но и какого оно урожая! Он может прислать медовуху. Шесть бутылок на продажу, две отцу... а может, и больше – он не откажется! В общем, забери медовуху и возвращайся сюда.\n\nГилверадин живет неподалеку от пристанища Высших эльфов во Внутренних землях. С эльфами этими лучше не связываться, уж поверь мне!", progress = nil, completion = "А, ты знаешь Мальтона? Он мой старинный собутыльник! Понимаешь, я нашел средство, преодолевающее все искусственные границы и условности. Это – выпивка! Если бы разумные существа выпивали, вместо того чтобы воевать, мир сделался бы куда лучше и чище.\n\nВпрочем, боюсь, ты здесь не затем, чтобы слушать лекции о благословенных свойствах алкоголя.", rewards = "Вы получите:\n\n"},
[651] = {title = "Связывающие камни", objective = "Добудьте огненный ключ, резной ключ и громовой ключ с западного связывающего камня, восточного связывающего камня и внешнего связывающего камня.\n\nОтнесите ключи к внутреннему связывающему камню.", description = "Четыре связывающих камня разбросаны по нагорью Арати. Эти камни пригвоздили меня к земле.\n\nЧтобы оковы исчезли, нужно снять замок с самого мощного из них – с Внутреннего связывающего камня. А чтобы это сделать, придется собрать ключи с остальных трех камней.\n\nЭти камни охраняют стражи, но если у тебя хватит ума – или удачи, – тебе удастся найти возможность их нейтрализовать.", progress = "Перед вами внутренний связывающий камень. Это самый мощный из связывающих камней, и нужно открыть его, чтобы открылись замки остальных камней.", completion = "*Голос Мизраэли доносится из камня.*\n\nТы смог это сделать! Ты открыл замки! Я чувствую, как спадают мои оковы, и свобода все ближе.\n\nТы мой благородный спаситель, |3-6(Маг) Эфром!", rewards = "Вы получите:\n\n"},
[652] = {title = "Разбить ключ-камень", objective = "Найдите и убейте Фозрука. Принесите Жезл Порядка к ключ-камню на нагорье Арати.", description = "Открыв замки связывающих камней, ты <освободил/освободила> меня от большей части моих оков, но кое-что еще удерживает меня. Это ключ-камень, который ты видишь среди других камней круга. А ключ от него держит при себе один из моих пленителей, каменный страж Фозрук.\n\nВы должны заполучить у Фозрука этот ключ, который каменные стражи называют Жезлом Порядка, и использовать его для открытия ключ-камня.\n\n<имя>, вы так много сделали, чтобы мне помочь... Еще немножко... и моя благодарность потрясет все земные устои!", progress = "Ключ-камень заряжен сильнейшей геомантической энергией.", completion = "Вы вставляете жезл в ключ-камень. Земля под вами начинает дрожать...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[653] = {title = "Союзники Мизраэли", objective = "Поговорите с Герриком Костохватом в Заброшенном гроте в Стальгорне.", description = "*Говорит Мизраэль.*\n\nСвободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы.\n\nНо в должный час я пойду против гигантов, и они еще пожалеют о том, что отняли у меня свободу!\n\nВы <благородный союзник/благородная союзница>, <имя>. Через некоторое время мне вновь понадобится ваша помощь. Когда я буду готова, нужно, чтобы вы призвали меня на поверхность.\n\nПоговорите с Герриком Костохватом. Он обитает в Стальгорне, в Заброшенном гроте. Он знает, как меня можно призвать.", progress = nil, completion = "Госпожа сказала мне о вашем приходе, |3-6(Чернокнижник). Приветствую вас в моем обиталище – ведь вы, как и я, служите высшей цели.", rewards = "Вы получите:\n\n"},
[654] = {title = "Полевые испытания в Танарисе", objective = "Добудьте приемлемые образцы тканей 8 василисков, 8 гиен и 8 скорпионов. Отнесите набор для проведения испытаний главному инженеру Чепухастеру в Прибамбасск до окончания действия источника энергии.", description = "Вы подключаете источник энергии, и набор для полевых испытаний начинает светиться и вибрировать. Похоже, он работает как надо.\n\nПо словам главного инженера Чепухастера, у вас есть два часа на сборы образцов в пустыне Танарис. Если вы не успеете справиться за это время, то потеряете все данные и придется купить еще один источник энергии.\n\nВыполнив задание, возвращайтесь к Чепухастеру.", progress = "Ну что, все образцы успел собрать? Если не все, то помни, как только энергия закончится, все результаты пропадут и придется начать все с начала.\n\nЭй, не жди от меня сочувствия; я думаю только об интересах Водной компании Прибамбасска, а если мне придется продавать источники энергии до возобновления поставок с ледяных ключей Дун Морога, то да будет так!", completion = "Ну ладно, на удаление источника энергии мне понадобится пара секунд. После этого можешь делать все, что захочешь, не боясь потерять данные.", rewards = "Вы получите:\n\n"},
[655] = {title = "Павший Молот", objective = "Поговорите с Тор'ганом в Павшем Молоте.", description = "Воспоминания по-прежнему ярки, как будто это было вчера... Так много лет без надежды, прикованный к этому ужасному месту деревом и сталью. И вот наконец появился вождь. Молот Рока в своих полуночных доспехах, высоко поднят его боевой молот.\n\nЭто было... слишком ужасно... что удар труса мог сразить нашего величайшего героя. Враг наскочил сзади и пронзил его копьем... Я упал на колени. Какая могла быть надежда? Какая еще может быть надежда...", progress = nil, completion = "А, вы говорите о Гор'муле. Да, судя по вашим словам, похоже, он так и не оправился от смерти Молота Рока.\n\nГор'муль был пленником здесь, когда Тралл и Оргрим вели битву за освобождение лагеря, но когда затряслясь земля и наши братья сбежали, его оставили там. Лишенный малейшего проблеска надежды, он скитался, затерянный, в одиночестве, пока мы не вернулись сюда, чтобы вновь поселиться в Павшем Молоте.", rewards = "Вы получите:\n\n"},
[656] = {title = "Призыв принцессы", objective = "Отправляйтесь к кристаллам Мизраэли, вызовите принцессу и победите ее.\n\nЗаберите ее мистические оковы и присоедините их к кристаллам.", description = "Вы должны нанести поражение Мизраэли прежде, чем она обретет полную силу. Если вы этого не сделаете, то, как только она наберет достаточно сил, она кинется на своих пленителей! Есть такие, кто считает, что может ее контролировать, но если ее можно контролировать, с чего было гигантам с самого начала заковывать ее в цепи?\n\nПотрясающая логика, да?\n\nЧтобы сразить Мизраэль, призовите ее у ее кристаллов, где вы в первый раз говорили с ней. Нанесите ей поражение и заберите ее мистические оковы, а потом подсоедините их к кристаллам Мизраэли.\n\nСделайте так – и она вновь будет поймана в ловушку.", progress = "Кристаллы Мизраэли сейчас подозрительно спокойны.", completion = "Когда мистические оковы охватят кристаллы, из подземных глубин раздается нечеловеческий вой, переходящий в рык.\n\nКристаллы Мизраэли больше не излучают тепла и чувства безопасности, как это было раньше. Теперь они пульсируют неприкрытой угрозой... как если бы существо внизу, под ними, исходило злобой, направленной на поверхность.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nПульсирующий хрустальный осколок"},
[657] = {title = "Новая чума зарождается?", objective = "Поговорите с Кинелори.", description = "*Кви начинает просматривать папку.*\n\nЭто в самом деле интересно! Похоже, аптекарь Йорель проводил здесь, на ферме Го-Шека, какие-то смертельно опасные эксперименты. Я не знаю точно, какое это имеет отношение к Хилсбраду, но Фину не понравится, если мы проигнорируем такое дело.\n\nМы тут столкнулись с орками в ваше отсутствие, и теперь я не настолько хорошо себя чувствую, чтобы отправиться на помощь к Кинелори. Но если вы не против, проводите ее к ферме, где она собирается выкрасть результаты исследований, которые Йорель так и не отослал пока на Мельницу Таррен.", progress = nil, completion = "Если это успокоит Фина, я уничтожу каждого из Отрекшихся поодиночке. Он столько сделал для нас с тех пор, как началась чума. Мы и не надеялись, что когда-нибудь у нас снова будут друзья или семья.\n\nКогда будете готовы, дайте мне знать. Мы тотчас же двинемся в путь.", rewards = nil},
[658] = {title = "Новая чума зарождается?", objective = "Найдите Отрекшегося-курьера и принесите обнаруженную у него запечатанную папку Кви близ фермы Го'Шека.", description = "Так вас Фин послал узнать, как мы тут? Неудивительно – он слишком много беспокоится.\n\nМы уже много дней наблюдаем за этой фермой, и Кин уверяет, что недавно видела гонца, выходящего из вон того маленького домика с южной стороны.\n\nОна любительница поболтать, но я всегда доверяю ее ощущениям, когда мы бываем в опасных местах.\n\nА вы часом не следопыт, а? Мы думаем, что гонец может относить записки в деревню Мельница Таррен. Если бы мы могли заполучить эти документы, это пролило бы свет на события в Хилсбраде.", progress = "Мы признательны вам за помощь в поисках гонца, Эфром.\n\nПока вас не было, Кин увидела аптекаря, выходящего из того же дома к югу отсюда. Я уверена, что они замышляют что-то дурное – но мне нужны доказательства, чтобы не натворить чего-нибудь по неосторожности.\n\nА вам удача улыбнулась?", completion = "Отлично!\n\nПосмотрим, о чем тут идет речь...", rewards = "Вы получите:\n\n"},
[659] = {title = "Новая чума зарождается?", objective = "Найдите Кви и Кинелори у фермы Го'Шека на Нагорье Арати.", description = "Приветствую, <имя>, приятно познакомиться. Я руковожу группой смельчаков, расследующих странные происшествия в этом районе.\n\nМоим родственникам в Хилсбраде недавно пришлось избавиться от своей собаки Стэнли, потому что животное таинственным образом выросло до невообразимых размеров и стало кидаться на каждого прохожего.\n\nЯ уверен, что тут замешана нежить, и мы ищем доказательства.\n\nДве моих спутницы, Кви и Кинелори, отправились к ферме Го'Шека, что находится на Нагорье Арати, и давно не подавали о себе вестей. Найдете их? А то я начинаю беспокоиться.", progress = nil, completion = "Постарайся быть как можно незаметнее, путник.\n\nОркам не слишком нравится, когда за ними шпионят, а их тут больше, чем видно невооруженным глазом.", rewards = "Вы получите:\n\n"},
[660] = {title = "Новая чума зарождается?", objective = "Защищайте Кинелори, пока она не вернется к Кви.", description = "Ладно, <имя>. Если вы готовы, то и я тоже.\n\nПопробуем?", progress = "Время для болтовни закончилось. Защитите Кинелори, если вам небезразлична судьба народа Хилсбрада.", completion = "Вы оказали нам огромную услугу, Эфром. Благодарю вас.\n\nНадеюсь, Кин не доставила вам слишком мног хлопот. Она очень дружелюбна, но может быть и смертельно опасной, если вы ее враг.", rewards = "Вы получите:\n\n"},
[661] = {title = "Новая чума зарождается?", objective = "Найдите Фина Оделика в Южнобережье.", description = "После ночной гулянки в таверне Кинелори выглядела похуже, чем сейчас. Видно, вы неплохо ее защищали.\n\nТо, что она принесла с фермы, должно как минимум дать Фину представление о том, что происходит здесь, в Арати. Для того чтобы удоствоериться, что после вашей атаки не последует ответного удара, мы здесь ненадолго задержимся. Вы не откажетесь отправиться обратно в Южнобережье и поговорить с Фином?", progress = nil, completion = "Итак, эти две баламутки в конечном счете – в полном порядке? Ха-ха, рад слышать. Благодарю вас за вести об их местонахождении и состоянии – меня в высшей степени радует, что они еще живы; обе они – мои близкие подруги и незаменимые спутницы в путешествиях.\n\nНо... более важна моя благодарность за вашу помощь. Вот, примите это вместе с благодарностью от всей нашей группы.\n\nЕсли посчастливится, мы выясним, что затевают Отрекшиеся, и положим конец их замыслам.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПыльные одеянияПоножи легкой походки\n\nВы также получите:\n\n"},
[662] = {title = "Поиски на глубине", objective = "Первый помощник Нилзликс хочет, чтобы вы достали карты и судовые журналы кораблей \"Девичья Блажь\" и \"Дух Серебряного бора\".", description = "О'Брин повел корабли в бухту. Мы были уверены, что именно здесь будет найдено сокровище. \"Вестник\" причалил нормально, но когда \"Девичья Блажь\" и \"Дух Серебряного бора\" приблизились к берегу, вода начала быстро понижаться. Страннейшая вещь, я такого в жизни не видал!\n\nТе два корабля налетели на что-то... нечто вроде храма в рифе. Оба быстро затонули – это была настоящая трагедия.\n\nНужно найти судовые журналы и карты обоих кораблей, прежде чем мы отчалим. Мы не можем оставить эту информацию доступной для любопытных глаз!", progress = "Как успехи в поиске и спасении документов, Маладат? Нам и правда очень нужно забрать судовые журналы и карты с \"Девичьей Блажи\" и \"Духа Серебряного бора\".\n\nЕсли имеющиеся там сведения попадут в руки врагов, командир флота Морской Рок нас по палубе размажет.\n\nЭто если нам вообще удастся отсюда выбраться...", completion = "Известие о том, что теперь эти сведения в безопасности, немного успокоит наше начальство в Пиратской бухте. Хорошая работа, Маладат.", rewards = "Вы получите:\n\nБоевой молот Черной Воды"},
[663] = {title = "Эй, там!", objective = "Поговорите с капитаном О'Брином в бухте Фальдира.", description = "Ой, кого видит Лоло! Это ж крошка-<класс>! Лоло всегда начеку!\n\nДобро пожаловать в бухту Фальдира. Капитан О'Брин сказал, что мы задержимся тут лишь на несколько часов. Ровно настолько, сколько потребуется, чтобы добыть сокровище и отчалить обратно в Пиратскую бухту.\n\nНо Лоло думает, мы тут надолго засели. Из нашей эскадры мы потеряли два корабля. Беднягу \"Дух Серебряного бора\" и несчастную \"Девичью Блажь\". На дне морском они теперь!\n\nЛоло думает, вам бы переговорить с капитаном О'Брином, если вы тут и дальше слоняться собираетесь.", progress = nil, completion = "Хей, дружище.\n\nНу и жуть же была. Морской Рог отнимет у меня корабль, если проведает, что тут произошло.\n\nОдна из этих хитрых профессорских штучек указала на то, что поблизости от этой бухты лежит давно утерянный клад. Я привел \"Вестник\" к берегу, чтобы причалить, и сигнализировал \"Духу Серебряного бора\" и \"Девичьей Блажи\", чтобы они сделали то же самое.\n\nА потом вдруг море загрохотало. Вода понизилась, и оба корабля разбились, врезавшись в риф.\n\nНо это был не просто риф. Что-то было там, внизу...\n\nПомогите моей команде, и получите неплохое вознаграждение.", rewards = "Вы получите:\n\n"},
[664] = {title = "Затонувшие печали", objective = "Капитан Стальные Нервы из бухты Фальдира хочет, чтобы вы убили 10 налетчиков и 3 колдуний из клана Пронзающего Гребня.", description = "Ох, жизнь – ужасная штука. Я должен бы покоиться в водяной могиле, а не сидеть здесь у огня, наслаждаясь свежим воздухом.\n\nКоманда не жалела сил, чтобы спасти мою прекрасную \"Девичью Блажь\". Да упокоятся ребята в мире, благословенны их сердца.\n\nО'Брину удалось выбраться на берег, а нам не повезло. Море просто опрокинулось на нас, клянусь вам.\n\nВот мы плывем – и вот следующая волна обрушивается на нас. А эти твари! Они убили всех, кто выжил. Подлое нагово отродье. Я вырубился и пришел в себя уже здесь.\n\nЯ жажду их мерзкой холодной крови!", progress = nil, completion = "Славно потрудились, Маладат.\n\nЭти твари получили по заслугам. Хотя ничто не вернет мне мой корабль и мою команду, смерть этих наг дает хоть какое-то утешение.", rewards = "Вы получите:\n\nПерчатки Морского волка"},
[665] = {title = "Утонувшее сокровище", objective = "Проводите профессора Физзлторпа в пещеру и обратно.", description = "Теперь, когда мы настоящие полноценные разбойники Черноводья, мы должны помочь мистеру О'Брину разыскать пропавшее эльфийское сокровище.\n\nПочти невозможно найти драгоценные камни в море без посторонней помощи. Доктор сконструировал специальные очки, которые должны помочь. Ему нужно зарядить эти очки энергией, извлеченной из заколдованного камня в пещере, расположенной выше по холму.\n\nНо эта пещера проклята! Когда мы подошли к ней, на нас напали. Защитите меня, и я смогу вытянуть энергию из камня и направить ее в очки.", progress = "Некогда болтать! Нужно зарядить очки энергией камня!", completion = "Теперь очки работают превосходно! Отличная работа. Маладат.", rewards = "Вы получите:\n\n"},
[666] = {title = "Утонувшее сокровище", objective = "Доктор Драксельмер в бухте Фальдира хочет, чтобы вы собрали 10 эльфийских самоцветов и вернули ему очки Ловца сокровищ, когда закончите.", description = "Сокровища так долго лежали на дне морском, что покрылись известковым налетом, превратившись в большой камень. Но сила, влитая в эти очки, позволит вам легко определить их местонахождение.\n\nМаленькая гномья ловкость делает большие дела!\n\nВозьмите эти очки Ловца сокровищ, <имя>, посмотрите, может, вам удастся собрать какие-то из утерянных сокровищ для капитана О'Брина.\n\nЯ бы и сам поплыл туда, но... эм... ну, у меня есть серьезные научные задачи, требующие срочного решения на надежной, сухой земле... да... вот.", progress = "Ну, и как работают очки? Все функционирует как надо? Можно подрегулировать, если есть необходимость.\n\nАх да, эти очки понадобятся мне, когда вы закончите. Я уверен, что капитан О'Брин найдет им потом самое разнообразное применение.", completion = "Великолепно, Маладат! Капитан будет очень доволен! Погодите, вот еще весть долетит до флотовладельца Морского Рога!..", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГномский шокерСервомеханический кузнечный молот\n\nВы также получите:\n\n"},
[667] = {title = "Смерть со дна морского", objective = "Защитите Мураша О'Брина во время атаки наг.", description = "Это плохо. Похоже, клан Пронзающего Гребня готовится к нападению.\n\nНаги известны своей жестокостью в бою. Они не остановятся, пока я не умру.\n\nНе то чтобы я ценил свою жизнь выше, чем жизни членов команды, но вы должны помочь защитить меня. Я единственный, кто знает морские пути, – команда просто не сможет вернуться в Пиратскую бухту без меня.\n\nНаги придут с моря. Мне нужно, чтобы вы оставались здесь, со мной, чтобы отразить их атаку. Займите место у пушки и оттесните их.\n\nГотовы, <имя>?", progress = nil, completion = "Мы пережили их атаку!\n\nБез вас, Маладат, нам бы это не удалось. Мы отчалим, как только поднимется прилив. Если бы вы не были столь многообещающей героической личностью, я предложил бы вам место в своей команде. Но, конечно, вас ждет рыбка покрупнее.\n\nНесмотря на то, что вы всего лишь |3-6(человек)...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо Ледяной водыКольцо Морского Огня\n\nВы также получите:\n\n"},
[668] = {title = "Утонувшее сокровище", objective = "Отнесите эльфийские самоцветы капитану О'Брину.", description = "Не будем заставлять капитана О'Брина ждать. Он захочет первым увидеть эти драгоценности. В конце концов, для того мы и здесь!\n\nА через нескольо недель сотрудничества с этими пиратами мы с профессором поняли, что на нашем здоровье самым пагубным образом может сказаться, если нас застанут придерживающими их сокровища.\n\nВот, <имя>, отнесите все О'Брину.", progress = "Эй, |3-6(Воин). Что привело вас на мостик?", completion = "Так, значит, коротышки в конце концов оказались полезными? Я знал, что мы этих мальчиков-с-пальчик не напрасно взяли с собой!", rewards = "Вы получите:\n\n"},
[669] = {title = "Утонувшее сокровище", objective = "Доставьте образец эльфийского самоцвета командиру флота Морскому Рогу в Пиратскую бухту.", description = "Командир флота Морской Рог захочет сразу же услышать о нашей находке.\n\nНо, как видите, мы пока не в том положении, чтобы сняться отсюда. Не только прилив очень низок, но еще и эти проклятые твари, которым мы помешали, бдительно следят за нашими передвижениями.\n\nВы оказали бы большую услугу Пиратам Черноводья, если бы смогли сообщить флотовладельцу Морскому Рогу в Пиратскую бухту, что мы отыскали сокровища и работаем над тем, чтобы достать еще. А этот образчик отвезите ему в качестве доказательства.", progress = "Что привело вас в Пиратскую бухту, |3-6(Разбойник)?", completion = "А, узнаю старого доброго Мураша О'Брина! Я знал, что это подходящий капитан для такого задания!", rewards = "Вы получите:\n\n"},
[670] = {title = "Утонувшее сокровище", objective = "Отвезите письмо Морского Рога Мурашу О'Брину на нагорье Арати.", description = "Слушайте, <имя>, у вас лицо искателя приключений. Мой флот застрял в Пиратской бухте, пока мы не загрузимся.\n\nТам, да и не только там, творятся темные делишки, а мне нужно доставить кое-какую секретную корреспонденцию Мурашу О'Брину, пришвартовавшемуся к побережью Арати.\n\nМогу ли я доверить вам доставку этого сообщения в целости и сохранности и надеяться на вашу готовность хранить это задание в секрете?", progress = "Доволен ли Морской Рог? Держу пари, его ухмылка растянулась от Пиратской бухты до Кабестана!", completion = "Спасибо, что проделали такой долгий и опасный путь. Благодарю вас от имени разбойников Черноводья.", rewards = "Вы получите:\n\n"},
[671] = {title = "Зловещая магия", objective = "Принесите Тор'гану в Павший Молот 10 амулетов из кровавого камня.", description = "Я почувствовал что-то странное в воздухе... ощущение, будоражащее мою кровь. У меня возникли подозрения. Я твердо решил найти источник беспокойства и обнаружил на западе, у Северного поместья, остаточные следы призыва демона. Когда я приблизился, кровь буквально вскипела, и ярость разгорелась во мне.\n\nНа земле я заметил амулет из кровавого камня, какими пользуются, вызывая демона. Однако магическая сила найденного мной камня была уже полностью исчерпана. Мне нужен для изучения другой образец, но я не рискую возвращаться в поместье. Можете ли вы принести мне оттуда несколько амулетов?", progress = "Однажды проклятая кровь по-прежнему течет в моих жилах, Томпсон. Если кто-то... что-то... призывает демонов... его надо остановить.", completion = "Выявление истинных намерений Синдиката отнимет у меня некоторое время, но их очевидное сотрудничество с темными демоническими силами меня беспокоит. Я расскажу вам, когда разузнаю.", rewards = "Вы получите:\n\n"},
[672] = {title = "Вызов духов", objective = "Соберите 10 глаз ящеров нагорья с долгоногов и твердозубов нагорья, принесите их Тор'гану в Павший Молот.", description = "Мы пытались успокоить его, развеселить, рассказывать ему истории о нашем огромном городе Оргриммаре на Калимдоре, но его ничто не трогало.\n\nИстории о нашем молодом вожде, Тралле, который носит доспехи и молот Оргрима... но, быть может... Может быть! Демонстрация нашей новообретенной шаманской магии могла бы дать ему луч надежды. Попробовать стоит!\n\nМы могли бы сделать для него маленькую вещицу, да... Принесите мне несколько глаз раптора, и я посмотрю, что можно сделать.", progress = "Я создам амулет, который частично наделит Гор'муля силой ящеров. Может быть, это пробудит в нем огонь жизни...", completion = "Отлично. Духи ящеров, от которых взяты эти глаза, предоставят носящему этот амулет свою силу.", rewards = "Вы получите:\n\n"},
[673] = {title = "Зловещая магия", objective = "Добудьте сферу кровавого камня у чернокнижницы Марез Клобук и принесите ее Тор'гану в Павший Молот.", description = "У меня нет сомнений, что в стенах Стромгарда засел могущественный чернокнижник. Время от времени, используя обладающую магической энергией реликвию, этот чернокнижник призывал в больших количествах ужасных демонов. Мы должны отнять у него этот источник энергии.\n\nНайдите чернокнижника и убейте его. Принесите мне магический объект, который найдете при нем, чем бы он ни оказался. Я предприму шаги по разрушению реликвии и прослежу, чтобы ее мощь больше не использовалась для осквернения этой земли.", progress = "Кровь моя пылает... все сильнее. Чернокнижника нужно остановить.", completion = "Мои бессонные ночи наконец сменятся спокойным сном, когда я разрушу эту сферу. Спасибо вам, Томпсон. Это леденящее напоминание о той ужасной власти, которую демоны имели над орками, прежде чем Адский Крик освободил их от проклятья.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШапка из кожи белого драконаСветозарные серебряные наручи\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[674] = {title = "Вызов духов", objective = "Отдайте Гор'мулю амулет из когтя ящера.", description = "Вот, отнесите этот амулет Гор'мулю и посмотрите, пробудит ли сила ящера в нем тот боевой огонь, который некогда пылал в его крови.", progress = "Какая может быть надежда, если рукой труса может быть убит сильнейший из сильных? Какая надежда, ответьте мне!", completion = "Что это? Отполированный кусок кости... Что мне пользы от полированной косточки? Разве безделушка способна вернуть Орде ее былую славу?", rewards = "Вы получите:\n\n"},
[675] = {title = "Вызов духов", objective = "Поговорите с Тор'ганом.", description = "*Гор'муль бросает амулет на землю.*\n\nВас Тор'ган послал, да? Тьфу... Никак не могу понять, почему он жалеет меня. В сострадании мне было отказано, когда мне не позволили умереть вместе с моим вождем во время боя. Жестокий удар судьбы настиг меня...", progress = nil, completion = "Вижу, что не сработало. Тем не мение я чувствую, что демонстрация силы шаманов может помочь Гор'мулю вернуть веру в себя. Сила амулета была недостаточно велика, чтобы показать ему нашу новообретенную мощь.", rewards = "Вы получите:\n\n"},
[676] = {title = "Да падет молот", objective = "Убейте 8 огров из клана Тяжелого Кулака и 10 головорезов из клана Тяжелого Кулака, затем найдите Друма Скверного в Павший Молот на нагорье Арати.", description = "Слабаки... Все они слабаки. А ты, <класс>, куда смотришь? Думаешь, <особенный/особенная>? Проверим?\n\nНа форт Павший Молот напали враги. Если не помочь нашим, им не устоять.\n\nВпрочем, не спеши. Прежде надо испытать твое искусство. На северо-востоке от Стромгарда в Арати есть курган, который заселило огрское племя Тяжелого Кулака. Когда одолеешь тамошних огров и мародеров, доложи об этом Драму Желчному в Павшем Молоте.", progress = "У меня нет времени топор наточить, не говоря уж о том, чтобы покинуть форт и заняться теми тварями, которые убивают моих братьев.\n\nПохоже, опыта тебе не хватает даже для обычного рубаки, не говоря уж о полноценном |3-6(Друид). Что тебе нужно, Чебуратино?", completion = "Значит, ты думаешь, что тебе хватит сил помочь Павшему Молоту? Да будет так.\n\nСальный послал тебя в огрский курган или в надежде, что ты там погибнешь, или полагая, что сможешь помочь нам. Так или иначе, ты здесь, а мне нужны солдаты. Натиск на наш форт не ослабевает.\n\nЕсли ты собираешься остаться в Павшем Молоте, то отдохни, а потом приходи ко мне. Чего-чего, а сражений на твою долю хватит.", rewards = "Вы получите:\n\n"},
[677] = {title = "К оружию!", objective = "Убейте 10 метателей топоров из племени Сухокожих, 10 охотников за головами из племени Сухокожих и 8 знахарей племени Сухокожих, а затем возвращайтесь к Драму Желчному на заставу Павшего Молота.", description = "Тролли племени Сухокожих и огры клана Тяжелого Кулака с нагорья Арати стакнулись, чтобы выжить нас с этой земли, но мы не собираемся уступать ни им, ни кому угодно другому. Мы убьем их и покажем, что и мы здесь – у себя дома.\n\nТролли позорно бежали от нас; огры сожрали бы нас и спали бы на наших шкурах, если бы мы им позволили, – этим тварям не должно жить.\n\nМы начнем атаковать троллей Сухокожих к югу отсюда. Убивай их пачками и возвращайся только тогда, когда их поселения будут залиты кровью.", progress = "Если ты еще не выполнил мое задание – может быть, ты просто трус в душе и неумеха в бою.", completion = "Я вижу боевые отметины на твоих доспехах, и пот струится по твоему лбу. Неплохо, в самом деле неплохо.", rewards = "Вы получите:\n\n"},
[678] = {title = "К оружию!", objective = "Убейте 10 громил и 4 магов из клана Тяжелого Кулака, затем возвращайтесь к Драму Желчному на заставу Павшего Молота.", description = "Твоя сила очевидна, <имя>. Теперь посмотрим, как ты справишься с настоящим врагом.\n\nУ клана Тяжелого Кулака есть логово к юго-востоку отсюда по направлению к дворфийскому мосту, и, если я не ошибаюсь, их молотобойцы и маги должны стать для тебя более серьезным испытанием – по крайней мере, для нас они таковым являются по сию пору.\n\nУбей столько огров, сколько сможешь, и возвращайся ко мне во плоти, если добьешься успеха, или в виде призрака, если потерпишь неудачу. В любом случае я воздам хвалу твоей стойкости в бою.", progress = nil, completion = "Ты не слабее кодо, а твоя готовность к битве достойна восхищения.", rewards = "Вы получите:\n\n"},
[679] = {title = "К оружию!", objective = "Убейте 15 шаманов клана Тяжелого Кулака и 3 вождей клана Тяжелого Кулака, а затем возвращайтесь к Драму Желчному на заставу Павшего Молота.", description = "Зверю вот-вот отрубят голову... и все же для решающего удара требуется огромная сила, <имя>. Уверен, именно ты можешь помочь нам нанести этот последний мощный удар. Руководящие этими атаками устроили свое логово прямо в руинах Стромгарда – вот яркий пример человеческой слабости...\n\nНайди и убей вождей клана Тяжелого Кулака и их прислужников-шаманов, пытающихся выжить нас с этих земель.", progress = nil, completion = "Твой народ может гордиться тобой, Дэмрод. Угроза сильно уменьшилась, и я уверен, что мы начнем процветать здесь, на этом нагорье.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБесшумный охотникРассекатель черепов\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[680] = {title = "Настоящая угроза", objective = "Убейте Ор'Калара и принесите его голову Корин Желчной на заставу Павшего Молота.", description = "Вы отлично служите моему мужу, <класс>, но он не знает, почему Павший Молот подвергается атакам.\n\nОр'Калар – пешка в руках Муг'Тола в Стромгарде – яро ненавидит моего мужа и ничего так не желает, как его смерти – за то, что тот нанес ему поражение много лет назад.\n\nМои гадатели сообщают, что Ор'Калар устроил для мужа ловушку, поэтому я скрыла от него, что огр объявился в этих землях.\n\nМой муж ринется сломя голову, если узнает о местонахождении огра, а я хотела бы попросить вашей помощи в убийстве этой твари.", progress = "Возле Башни Аратора – вот где вы найдете Ор'Калара. С его смертью прекратятся атаки на Павший Молот, и жизнь моего мужа будет вне опасности.\n\nЯ вижу по вашим глазам, что вы считаете меня слабой – и даже бесчестной – из-за моего молчания. Однажды вы узнаете, что значит любить – как люблю я. Может быть, тогда вы поймете, что есть и другой вид силы и чести.\n\nА тем временем, выполните мою просьбу и убейте Ор'Калара.", completion = "Вы оказали мне огромную услугу, Дэмрод. Знайте, что жизнь моего мужа и безопасность Павшего Молота еще на некоторое время защищены благодаря вашим деяниям. Пожалуйста, примите это в качестве награды за вашу смелость.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКилт Туманной дымкиМеч Павшего Молота\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[681] = {title = "Северное поместье", objective = "Убейте 10 проходимцев из Синдиката и 6 наемников Синдиката.\n\nЗатем вернитесь к капитану Ниалс в Опорном пункте.", description = "Мы ведем войну за Стромгард и терпим в ней поражение. Мы делим наш некогда великий город с ограми и Синдикатом, каждая группировка бьется с другой, и конца этому не видно.\n\nНо наши силы иссякают, в то время как силы наших врагов – растут.\n\nНам нужна помощь из Южнобережья, но есть проблемы с доставкой припасов, поскольку Синдикат контролирует территорию между нами.\n\nИди на базу Синдиката в Северном поместье и перебей там всех. Тогда, может быть, давление на наши транспортные пути ослабеет, и доставлять припасы станет проще.", progress = nil, completion = "Очень хорошо, Эфром. Со смертью этих членов Синдиката нам должно стать полегче получать припасы из Южнобережья.\n\nБыть может, у нас еще есть надежда.", rewards = "Вы получите:\n\n"},
[682] = {title = "Знаки Стромгарда", objective = "Принесите знаки Стромгарда Капитану Ниалс в Опорный пункт.", description = "Синдикат в Стромгарде воюет с силами нашего ополчения. Чтобы побудить толпу биться с нашими более дисциплинированными войсками, руководство Синдиката объявило о награде за убийство наших солдат, предлагая золото за каждый знак Стромгарда, снятый с убитых ополченцев.\n\nМы хотим вернуть себе эти знаки – не можем же мы позволить головорезам брать трофеи с тел наших героически погибших ребят!\n\nОтправляйтесь в район Стромгарда, контролируемый Синдикатом, и отберите у их бойцов наши знаки.", progress = "Вы нашли знаки Стромгарда, Эфром? В Синдикате должны понять, что они не могут наживаться на смерти наших воинов.", completion = "Спасибо вам, Эфром. Мы известим семьи этих погибших солдат о том, что они пали в бою.\n\nЭто будут печальные вести, и все же это лучше знать о судьбе любимых людей, чем томиться неизвестностью.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКавалерийские поножи Стромгарда"},
[683] = {title = "Просьба Сары Балу", objective = "Отнесите прошение Сары Баллу королю Магни Бронзобороду в Стальгорн.", description = "<имя>, у меня есть к вам маленькая просьба.\n\nВозьмите прошение, которое я написала на имя нашего великого государя стальгорнского, короля Магни Бронзоборода. Это небольшой труд для <такого/такой>, как ты, <славного героя/славной девы>.\n\nМне в моем горе сейчас трудно будет предстать перед королем. Ты понимаешь меня.", progress = "Значит, вы – Wrestlecake-|3-6(Воин)? Я наслышан о вашей доблестной службе Альянсу.\n\nЧто за дело привело вас ко мне ныне?", completion = "Подожите минутку, я прочту письмо...", rewards = "Вы получите:\n\n"},
[684] = {title = "Разыскивается: Марез Клобук", objective = "Принесите капитану Ниалс в Опорный пункт голову Марез.", description = "Назначена награда за голову Марез Клобук, высокопоставленной советницы и агента Синдиката. В последний раз ее видели на контролируемой Синдикатом территории Стромгарда.\n\nНаграду можно будет получить у капитана Ниалс.\n\nПредупреждение: Марез – опытная и коварная чернокнижница, замеченная в связях с демонами. Вооружена и очень опасна!", progress = "Приветствую, |3-6(Маг). Вы хотите мне о чем-то сообщить?", completion = "Вы справились с Марез Клобук? Отличная работа, Эфром. В самом деле отличная!\n\nМарез была серьезной угрозой стромгардским защитникам, и ходят слухи, что она служила посредницей между Синдикатом и какими-то другими, темными силами. Мы рады узнать, что она больше не будет строить козни против нас.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЧародейские рунические наручи"},
[685] = {title = "Разыскивается: Отто и лорд Соколиный Шлем", objective = "Принесите головы Отто и лорда Фалконкреста капитану Ниалс в Опорный пункт.", description = "Ополчение Стромгарда уведомляет о назначении награды за головы лорда Соколиного Шлема и его телохранителя Отто. Соколиный Шлем руководит деятельностью Синдиката на нагорье Арати, и его смерть внесла бы большую сумятицу.\n\nЕго телохранитель Отто, хотя и не является стратегической целью, представляет собой опасного противника, на счету которого – смерть десятков наших воинов.\n\nНаграды за их головы можно получить у капитана Ниалс.", progress = "Приветствую, докладывайте.", completion = "Лорд Соколиный Шлем и Отто? Отлично!\n\nВот ваша награда, Эфром. Я с радостью выплачиваю ее.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖезл ПечалиНаручи Всадника Войны\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[686] = {title = "Королевские почести", objective = "Поговорите с главным каменотесом Мраморщиком.", description = "Вряд ли добрые дворфские вдовы вроде госпожи Баллу понимают, что нам приходится терпеть тяготы войны ради высшего блага нашего народа. Гибель ее мужа, как и гибель всех дворфов, что сражаются за дело Альянса, тяжким бременем лежит на моей душе.\n\nМне не под силу вернуть ее супруга из Круговерти Пустоты, но я могу хотя бы почтить его память.\n\nЯ намерен заказать главному каменотесу Стальгорна Мраморщику памятник в честь Салли Баллу.\n\nОтправляйтесь к нему сейчас же и передайте мои слова, <класс>. Вы будете моим вестником.", progress = nil, completion = "Значит, вас послал лично король Магни Бронзобород?\n\nПодумать только! Стало быть, дело важное!", rewards = "Вы получите:\n\n"},
[687] = {title = "Тельдарин Заблудший", objective = "Найдите Тельдарина Заблудшего.", description = "Тельдарин Заблудший некогда был членом нашего ордена Сумеречного Молота. Однако он сошел с ума и отверг наше учение. Перед побегом он украл cвиток Мизраэли! Мы не смогли поймать его, но ходят слухи, что он совсем спятил и прячется в Бесплодных землях.\n\nЧтобы переманить на нашу сторону Госпожу, необходимо найти свиток. А для этого – найти Тельдарина.", progress = nil, completion = "Привет. Привет, привет, привет, привет, привет, ПРИВЕТ!\n\nПрости... Нет, не прощай! Не груби мне!\n\nО нет, это бред сумасшедшего.\n\nНо иногда мое единственное утешение – в безумии.", rewards = "Вы получите:\n\n"},
[688] = {title = "Союзники Мизраэли", objective = "Поговорите с Заруком в Павшем Молоте.", description = "*Говорит Мизраэль.*\n\nСвободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы.\n\nНо в должный час я пойду против гигантов, и они еще пожалеют о том, что отняли у меня свободу!\n\nВы <благородный союзник/благородная союзница>, <имя>. Через некоторое время мне вновь понадобится ваша помощь. Когда я буду готова, нужно, чтобы вы призвали меня на поверхность.\n\nПоговорите с Заруком в Павшем Молоте. Он знает, как меня можно призвать.", progress = nil, completion = "Добро пожаловать, |3-6(Разбойник). Госпожа сообщила мне о вашем приближении, и если мы хотим вернуть ее на поверхность, нам нужно многое обсудить.", rewards = "Вы получите:\n\n"},
[689] = {title = "Королевские почести", objective = "Принесите главному каменотесу Стальгорна Мраморщику 5 кусков альтеракского гранита.", description = "Значит, наш добрый король решил построить памятник в честь солдата по имени Салли Баллу? И вы говорите, что бедный парень погиб на мосту Тандола?\n\nДа будет когда-нибудь мир в Азероте?\n\nКак бы то ни было, любое поручение нашего государя – дело первостепенной важности. Чтобы возвести действительно впечатляющий памятник на века, мне нужен самый лучший камень. Отправляйся на Холм Дарроу в Хилсбрад и привези мне альтеракского гранита.", progress = "Берш, Берш, Берш! Говорите же, привезли ли вы мне достаточно альтеракского гранита, чтобы начать творить шедевр в честь Салли Баллу?", completion = "Замечательно! Лучше, чем я представить мог!\n\nА воображение у меня, между прочим...", rewards = "Вы получите:\n\n"},
[690] = {title = "Просьба Малина", objective = "Найдите Скуэрто в Опорном пункте на нагорье Арати.", description = "Приветствую вас, <имя>. Вы похожи на искателя приключений, а у меня как раз есть задание, требующее склонности к авантюрам.\n\nВерховный маг Трелан, мой первый наставник, не так давно бежал из Стромгарда, что на нагорье Арати, и просил меня помочь ему вернуть несколько предметов, которые он там оставил.\n\nГород был осажден, и Трелан попытался защитить Башню Аратора, но потерпел неудачу. У меня на нагорье есть агенты, но они просили дополнительной помощи. Вы согласитесь мне помочь?", progress = nil, completion = "Так вас, значится, Малин прислал? А мне без разницы, пусть хоть сам Мурадин восстанет из мертвых и умчит вас отсюда на драконе... Я занят! Если вам что-нибудь нужно, обратитесь к Кретьену.", rewards = "Вы получите:\n\n"},
[691] = {title = "На вес золота", objective = "Найдите 10 клыков троллей клана Сухокожих, 4 лекарских сумки клана Сухокожих и нож Темного охотника и принесите их ученику Кретьену в Опорном пункте.", description = "Верховный маг Малин послал нас со Скуэрто собирать для него реагенты. Я был в полном замешательстве и не знал, как приступить к делу, но теперь, когда вы здесь, думаю, моя проблема решена.\n\nВот что мне нужно: клыки троллей из племени Сухокожих, лекарские сумки клана Сухокожих и нож темного охотника.\n\nНе могли бы вы добыть это все для меня? Племя Сухокожих обитает к юго-востоку от Арати.", progress = "Что-нибудь вам уже удалось, Эфром?\n\n*Кретьен в процессе чтения делает какие-то пометки в своем журнале.*\n\nЕсли мои исследования верны, клыки можно собирать с любых троллей из племени Сухокожих. Лекарские сумки должны быть у знахарей Сухокожих, а особые ножи даются самым лучшим темным охотникам племени, когда они проходят ритуал посвящения. Невозможно заранее сказать, у какого из темных охотников есть такой нож, пока не сразишься с ним.", completion = "Невероятно! Теперь я понимаю, почему Малин попросил вас присоединиться к нам – вы отлично потрудились!\n\nТакими темпами мы со Скуэрто очень скоро двинемся обратно в Штормград!\n\nЯ уверен, что мой спутник-дворф вернулся с разведки из Крепости Тяжелого Кулака; пообщайтесь с ним, когда будет время.\n\nПо нему заметно, что он затеял с ограми потасовку. Впрочем, не говорите ему об этом: он очень чувствителен к критике его навыков разведчика.", rewards = "Вы получите:\n\n"},
[692] = {title = "Утраченные фрагменты", objective = "Принесите рваный, мятый и обожженный фрагменты свитка Тэльдруину Потерянному.", description = "Свиток Мизраэли... Свиток Мизраэли?! Нет, уверяю вас, не стоит даже думать о нем! Его магия может вытащить Мизраэль на поверхность, и если вы это сделаете, нам грозит беда!\n\nИли... может быть, уже слишком поздно. Может быть, она уже свободна. Может быть, она уже собирается с силами, прежде чем обрушиться на нас. Если так, свиток вам НЕПРЕМЕННО ПОНАДОБИТСЯ!\n\n...как ужасно, что он уничтожен. Спятившие элементали похитили его и разорвали на клочки, а теперь дерутся за них.\n\nНо если бы вам удалось собрать эти фрагменты, может быть, нам удалось бы восстановить свиток...", progress = "Вы нашли фрагменты?! Вам непременно понадобится Свиток Мизраэли, если вы хотите вновь пленить ее, пока еще не стало слишком поздно!", completion = "А, вы их нашли! Отличная работа, Джэйлол! Это, может, единственный наш шанс противостоять злу, которое несет Мизраэль!\n\nДайте-ка я найду мой степлер – посмотрим, смогу ли я соединить эти клочки...", rewards = "Вы получите:\n\n"},
[693] = {title = "Оружие получше кулаков", objective = "Найдите заклинательный жезл Трелана и верните его Скуэрто в Опорный пункт.", description = "Здорово, <имя>.\n\nЯ выяснил, где оказалась первая вещь Трелана: Коргреш держит ее в Зале Тяжелого Кулака. И судя по тому, как он кидался в своих потоками льда, чтобы заставить их держать строй, он, должно быть, уже близко подошел к пониманию того, как использовать мощь жезла на полную катушку.\n\nЧтобы добраться до Зала Тяжелого Кулака, нужно идти на юг отсюда, а затем на восток от моста Тандола. Найдите этого огра и отберите у него жезл.\n\nА за время вашего отсутствия я соображу, что нам делать со Стромгардом.", progress = "Наша цель – жезл, Гимлипопенс. Пока сосредоточьтесь на этой задаче.", completion = "Блестяще, Гимлипопенс. Один предмет найден, и, по моему списку, осталось еще три. Все они находятся в Стромгарде.\n\nПередохните и восстановите силы – следующий этап моего плана потребует немного больше времени и усилий. Возвращайтесь ко мне, плотно покушав и отдохнув.", rewards = "Вы получите:\n\n"},
[694] = {title = "Оборона Трелана", objective = "Найдите лазурный агат и принесите его ученику Кретьену в Опорный пункт.", description = "Все отдохнули?\n\nВот наш следующий шаг: огры так и кишат вокруг башни Аратора в Стромгарде. Необходимо активировать защитные возможности башни, если вы хотите иметь хоть малейший шанс выстоять против них. Чтобы это сделать, нам понадобится несколько самоцветов, на которые наложил лапы шаман клана Тяжелого Кулака. Он стянул их из башни, но радость его преждевременна – камни недолго будут в его власти.\n\nДобудьте один из самоцветов и принесите его Кретьену – он знает заклинание, которое нужно наложить на эти камни, чтобы они работали как ключи.", progress = "Привет еще раз, Палео. Вы еще не нашли лазурный агат?", completion = "Вы меня просто поражаете, Палео. Снова отличная работа.\n\nМинутку, я применю подходящее заклинание, чтобы заколдовать самоцвет, и все будет готово.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[695] = {title = "Чары ученика", objective = "Поговорите со Скуэрто.\n\nПрилагается предмет: \n", description = "Вот, <имя>. Самоцвет нужно только прижать к одному из пьедесталов у основания башни, чтобы активировать ее защитные силы. Используйте его, когда будете готовы войти в башню и искать остальные принадлежащие Трелану предметы.\n\nУдачи вам. Я буду ждать вашего возвращения в лагере. Ах да, перед уходом поговорите со Скуэрто: он расскажет вам обо всем, что нужно.", progress = nil, completion = "Хорошо, хорошо.\n\nЕсли нас ничего больше не держит, может быть, начнем?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[696] = {title = "Атака на башню", objective = "Найдите талисман, сферу и угольный агат Трелана и принесите их Скуэрто в Опорный пункт.", description = "Вот что тебе нужно найти: талисман Трелана, сферу Трелана да угольный агат Трелана.\n\nВсе эти три предмета должны быть в сундуках в башне, и ты спокойненько откроешь эти сундуки; главное – берегись огров.\n\nЗащитники башни не будут ими заниматься; придется тебе свое оружие держать наготове. Эти огры сообразят, что ты там и пытаешься обокрасть их – ясное дело, они решат задать тебе взбучку.\n\nБудь <осторожен/осторожна> – и удачи!", progress = "Тебе все удастся сделать, и я уверен, Малин будет более чем доволен тобой.", completion = "Никого лучше Малин и найти не мог в помощь нам, Чиффнир. Потрясающая работа!\n\nОн будет рад увидеть, каким ошеломляющим успехом увенчалась наша миссия.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[697] = {title = "Просьба Малина", objective = "Отвезите запечатанное письмо верховному магу Малину в Квартал магов Штормграда.", description = "Отвезите это письмо обратно в Штормград и скажите Малину, что мы с Кретьеном скоро будем дома. Он хорошо вознаградит вас за помощь нам, <имя>, в этом-то я не сомневаюсь.\n\nДоброго пути!", progress = "Слушаю вас... Ваше лицо мне смутно знакомо. Прошу прощения, мы раньше нигде не встречались? У меня столько дел, что я просто теряюсь.", completion = "*Верховный маг Малин вскрывает письмо, и глаза его расширяются.*\n\nСветом клянусь, вам удалось! Трелан будет очень доволен. Я уверен, Кретьен и Скуэрто так же, как и я, радуются своему предстоящему возвращению в Штормград.\n\nБлагодарю вас, Исчезайка. Пожалуйста, примите это как помощь в ваших странствиях.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКулачный щит БдительностиКрылоносные сапоги\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[698] = {title = "Нехватка ресурсов", objective = "Принесите Ток'Кару в Болотах Печали 8 сырых боков острозубых кроколисков.", description = "Я стараюсь добыть припасы для нашего поста на побережье, к востоку отсюда. Ток'Кар делает, что может, но после несения караульной службы и приготовления пищи для солдат, времени у него остается немного.\n\nОни любят мясо острозубов, но у меня до сих пор не было возможности отправить им новую партию. Ты не <мог/могла> бы помочь?\n\nМолодые острозубые кроколиски не так вкусны, как взрослые особи, так что дай им еще год-другой подрасти.", progress = "Лок'тар, |3-6(Охотник). Путешествие через болота легким не назовешь. Ты действительно отважен, раз решился на это.", completion = "Прекрасно! Свежее мясо к ужину! Спасибо, Томпсон. \n\nНынешний вечерок будет куда приятнее прошлого – мы наедимся досыта. \n\nПускай Дар – орк на морду ужасный, зато добрый внутри.", rewards = "Вы получите:\n\n"},
[699] = {title = "Нехватка ресурсов", objective = "Принесите 6 когтей острозубого крепкохвата Ток'Кару на Болота Печали.", description = "Мурлоки на побережье представляют опасность, поэтому нас послали сюда отразить эту угрозу Каменору или, если силы врага окажутся слишком велики, поднять тревогу. Отдыхать нам особо некогда, и мы не откажемся от твоей помощи. \n\nИз когтей острозубого крепкохвата выходит неплохое оружие, если выделать их должным образом. Раздобудь немного для нас, и ты получишь оружие нашей работы в благодарность за свежее мясо и хорошую компанию.", progress = "Добрая медовуха, костер, армия орков и запас оружия – это то, что надо! Я не жалею, что нас послали сюда охранять Каменор, но было бы неплохо однажды сделать здесь хороший бункер или хотя бы поставить башню.", completion = "Рад видеть тебя живым и здоровым, Томпсон.\n\nЭти когти нам весьма пригодятся, ведь чем больше оружия у нас будет в момент атаки, тем лучше.\n\nНачну работу над твоим экземпляром как можно скорее, много времени это не займет, я уже наловчился его изготавливать.", rewards = "Вы получите:\n\n"},
[700] = {title = "Королевские почести", objective = "Доставьте известие королю Магни Бронзобороду.", description = "Ах, какой прекрасный камень доставляют из Лордерона! Как жаль, что этот край лежит в разрухе.\n\nНо памятник получился весьма хорош! Думаю, король будет очень им доволен.\n\nТеперь же, будьте добры, пошлите государю весть, что памятник выполнен, как он и просил.", progress = nil, completion = "Гранит – такая малость по сравнению с жизнью достойного дворфа. Но ни один дворф в этом мире не вечен.\n\nБудем надеяться, что этот мемориал станет напоминанием будущим поколениям великого Азерота. Мы никогда не забудем, что за них отдали жизнь отважные солдаты вроде Салли Баллу.", rewards = "Вы получите:\n\nКольцо Королевского обелиска"},
[701] = {title = "Коварство ящера", objective = "Добудьте для Тор'гана 12 сердец ящера, вырвав их у плотоглотов нагорья.", description = "При наличии дополнительных компонентов я смогу изготовить предмет, который наделит Гор'муля коварством ящера! Когда сила ящера проникнет в Гор'муля, он узнает о нашем новом могуществе, и спящий в его душе воин снова пробудится!\n\nДля того чтобы создать предмет и соответствующее заклинание, мне потребуются сердца ящеров.", progress = "Я все приготовил, теперь мне нужны лишь сердца ящера.", completion = "Да, эти отлично подойдут. Я перенесу силу и дух ящеров в эту сферу. Она наделит Гор'муля огненной силой и разумом ящеров.", rewards = "Вы получите:\n\n"},
[702] = {title = "Коварство ящера", objective = "Отдайте Гор'мулю сферу Тор'гана.", description = "Возьмите эту сферу и используйте ее энергию, чтобы дух ящера вселился в Гор'муля. Уверен, это взбодрит его дух и откроет новые горизонты жизни. Когда он вернется в нормальное состояние, мы сможем разъяснить ему, в каком положении находится нынче Орда, и тогда в наших непрекращающихся войнах мы сможем получить поддержку великого воина.", progress = "Вы опять вернулись? Только мне не хватало снова этой жалости Тор'гана.\n\nЧто вы принесли мне на этот раз? Может, цветную ниточку? Или, может, веревку, чтобы я мог покончить со своим жалким существованием?..", completion = "По крайней мере, на сей раз – что-то интересное. Оно излучает странную силу...", rewards = "Вы получите:\n\n"},
[703] = {title = "Жареные крылышки канюка", objective = "Принесите 4 крылышка канюка Ригглфаззу.", description = "О, жареные крылышки канюка, я их просто обожаю! Такие нежные, сочные, с густым соусом, ммм... Стоит только почуять запах, просто слюнки текут! \n\nЯ прекрасно их готовлю – пальчики оближешь, как раз собирался сварганить их сегодня на ужин, но... У меня есть все, кроме основного ингредиента – крылышек! Добудешь мне крылышек – может, поделюсь рецептом!", progress = "Привет, Томпсон! Ну что, что там с моими крылышками?", completion = "О, я примусь за готовку прямо сейчас! \n\nА вот тебе и рецепт, вдруг тоже придет настроение покулинарничать.", rewards = "Вы получите:\n\nЖареное крыло канюкаРецепт: жареное крыло канюка"},
[704] = {title = "Судьба Эгмонда", objective = "Принесите 4 резные каменные урны геологу Сталекруту в Лок Модан.", description = "Последний рапорт от Эгмонда был весьма тревожен, возможно, бедняги уже нет в живых! Он сообщил, что его землекопы обнаружили некие \"древние погребальные урны\" на раскопках близ Ульдамана. Боюсь, эта находка привлекла внимание троггов, так же как и идолы, найденные мною здесь. \n\nМне нужно получить эти урны для исследований. Отправляйся к раскопкам Ульдамана, собери урны и возвращайся ко мне", progress = "Ты нашел эти урны, Трансмастер? Надо разобраться, как они связаны с троггами!", completion = "Отличная работа! Упорный труд и толика удачи помогут нам выяснить, как связаны трогги с этими древними артефактами. \n\nСегодня ты оказал геологам неоценимую помощь, Трансмастер! Твои усилия не будут забыты. Как и бедняга Эгмонд, вечная ему память...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nПерчатки геолога"},
[705] = {title = "В поисках жемчуга", objective = "Принесите 9 синих жемчужин Ригглфаззу в Бесплодные земли.", description = "Бесплодные земли – неприятное местечко, кишащее коварными хищниками и стервятниками. Жуткое, жуткое местечко, особенно для маленького гоблина. Чтобы выжить, приходится постоянно изворачиваться. \n\nУ меня есть секрет изготовления световых бомб. Я использую их, чтобы отпугивать хищников. Сейчас у меня заканчивается запас ингридиентов, а именно: порошок синего жемчуга. Добудь мне его, и вознаграждение не заставит себя ждать. \n\nНадеюсь, обувь у тебя прочная? Синий жемчуг можно найти в раковинах моллюсков на Коварном рифе. \n\nДа-да, том самом Коварном рифе в Тернистой долине!", progress = "Ты принес мне жемчужины? У меня почти вышел запас световых бомб.", completion = "Отличный жемчуг! Теперь надо смолоть его в порошок, смешать тут кое с чем... \n\nНу, берегитесь стервятники! Я припас для вас бомбы!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСветовая винтовкаСветовой жезл\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nСветовая бомба"},
[706] = {title = "Чары яркого пламени", objective = "Принесите сердце черного дракона Сигруну Рудотесу.", description = "В бытность мою учеником Феранора Железной Лапы, я перенял у него технику усиления оружия с помощью наложения огненных чар. Слыхал, Феранор нынче работает в кузне при охотничьем отряде в Лордероне. \n\nНе буду пока забивать тебе голову подробностями, скажу только, что для наведения чар требуется очень редкий ингредиент – кровь из еще бьющегося сердца детеныша черного дракона. Мне надо занять себя чем-то в ожидании распоряжений из Стальгорна, так что если принесешь мне сердце, я продемонстрирую тебе свое умение. Драконов найдешь в долине Летлор.", progress = "Как охота, |3-6(Жрец)?", completion = "О, это прекрасно подойдет! Сейчас я немного поработаю над твоим оружием. И оно будет разить без пощады!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЧары яркого пламени"},
[707] = {title = "Вы нужны Сталекруту!", objective = "Поговорите с геологом Сталекрутом на раскопках Сталекрута близ озера Лок.", description = "<имя>. Я получил отче геолога Сталекрута о ходе раскопок в Лок Модане. Ему нужен курьер для осуществления контроля за другими нашими земляными работами.\n\nБольше ничего сказать не могу, но если желаешь ноги поразмять, отправляйся к Сталекруту.", progress = nil, completion = "Значит, тебя послал Грозовая Вершина, да? Хорошо.\n\nУ меня есть для тебя важное поручение...", rewards = "Вы получите:\n\n"},
[708] = {title = "Черный ящик", objective = "Отнесите заржавевший черный ящик в оружейную Стальгорна.", description = "Поверхность этого металлического черного ящика изъедена ржавчиной, как будто его погружали в кислоту – похоже, он долго пролежал в желудке гигантского кондора. \n\nНа днище ящика выбит какой-то символ и надпись под ним: \"Орудие #19 – Осадная бригада Стальгорна\".Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[709] = {title = "Лекарство от судьбы", objective = "Принесите табличку Рьюн'эха Тельдарину Заблудшему.", description = "О небеса милосердные! Сама судьба стучится в двери! Помяните мое слово! Рок! Фатум! \n\nНет, я не могу более ничего сказать... Не могу поминать их имен, чтобы они не услышали меня! Но если нам удастся хотя бы узнать о них больше... Может, мы сможем противостоять им! \n\nМожет быть... \n\nИди в Ульдаман – проклятье, я все же произнес это! Найди табличку...табличку Рьюнэха. Да, найди ее! Не заставляй меня повторять! \n\nОна там, в глубине, в древнем сундуке, более древнем, чем любая доселе найденная работа дворфов.", progress = "Ты нашел табличку? В ней должен содержаться ключ к нашему спасению!", completion = "О, судьба милосердна к нам! Благодарю тебя! Возможно, нам удастся спастись!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nОдеяние Вестника рока"},
[710] = {title = "Изучение стихий: Камень", objective = "Соберите 10 маленьких осколков камня и принесите Лотвилю Вериатусу в Бесплодные земли.", description = "Здесь, в Бесплодных землях, мне пришлось приостановить работу над моим последним изобретением – оковами Стихий. \n\nКогда они будут закончены, то позволят вызывать еще более мощных элементалей и управлять ими.Чтобы продолжить работу, мне нужны маленькие осколки камня, чтобы опробовать на них некоторые новые заклинания и механизмы. \n\nМаленькие осколки камня, которые можно собрать с младших каменных элементалей, как раз подойдут. Они водятся к западу отсюда, сбегай-ка туда быстренько.", progress = "Так, вот сюда будет в самый раз... Слушай, подержи-ка вот здесь эту штуку! Ага, вот так, только выровняй по нормали. О чем бишь я... Ах, да! Камни, мне нужны маленькие осколки камней... Удобный полигон и материалы для исследования – все, что нужно ученому...", completion = "О, вот это пойдет! Спасибо, Томпсон!.. Хмм... На выходе получается ощутимо больше песка, чем я предполагал. Надо бы изменить коэффициент трения. Хотя, нет! Величина трения будет пренебрежимо мала, если использовать масло льда! \n\n*Чуть слышно бормоча себе под нос, Лотвил опирается подбородком на сплетенные пальцы и погружается в раздумья...*", rewards = "Вы получите:\n\n"},
[711] = {title = "Изучение стихий: Камень", objective = "Принесите 3 больших куска камня Лотвилю Вериатусу в Бесплодные земли.", description = "<имя>, ты уже <проявил/проявила> себя более <способным/способной>, чем все мои ученики вместе взятые. \n\nТеперь мне потребуется сила твоих мускулов. У каменных элементалей при должной осторожности можно найти большие каменные глыбы. Они достаточно велики и тверды, чтобы отколоть от них куски, удобные для исследования. Ты найдешь их у подножия гор к западу или юго-востоку отсюда. \n\nМожешь не торопиться, я пока займусь исследованием более мелких кусочков, которые ты <принес/принесла> мне.", progress = "Ты чрезвычайно порадовал меня, Томпсон. Как я и предполагал, мелкие камни разрушились в ходе иследования. Если этот эксперимент будет вполовину столь удачен, как я предполагаю, то те элементали, которых я вызывал прежде, в сравнение не будут идти с теми, которыми я смогу повелевать!", completion = "Томпсон, я просто диву даюсь! Я думал, что только полудюжине тауренов под силу донести столько камней!", rewards = "Вы получите:\n\n"},
[712] = {title = "Изучение стихий: Камень", objective = "Принесите 5 браслетов Камня Лотвилю Вериатусу в Бесплодные земли.", description = "<имя>, мне нужно, чтобы ты <принес/принесла> мне еще кое-что – браслеты каменных элементалей. Полагаю, с помощью этих браслетов можно оценить прочность моих кандалов. \n\nВ магическом кристалле я видел нескольких каменных элементалей к юго-западу отсюда. Недалеко от них я заметил еще и нескольких огров. \n\nПринеси-ка мне 5 браслетов, чтобы было с запасом. Мой Серво славится умением перепутывать все реагенты и результаты исследований.", progress = "Большие камни, которые ты принес мне, просто чудесны, Томпсон! Люсьен доставит те, что останутся от экспериментов, в Каранос. Они мне еще пригодятся. \n\nНапример, устрою себе из них уютное маленькое убежище, когда начну, наконец, практические исследования в рамках междисциплинарного подхода к взрывчатым веществам широкого спектра действия... \n\n*Голос Лотвила стихает по мере того, как ученый вновь погружается в свои эксперименты*", completion = "Томпсон, а ты никогда не задумывался о карьере лаборанта? Нет? Честное слово, я не представляю, как смогу тут управиться, когда ты уйдешь. У меня прежде никогда не было ученика, сочетающего в себе острый ум, любознательность и физическую силу!", rewards = "Вы получите:\n\n"},
[713] = {title = "Охлаждение горячих голов", objective = "Найдите масло льда и принесите его Лотвилю Вериатусу в Бесплодные земли.", description = "Послушай, я расскажу тебе о масле льда – это лучшее средство для того, чтобы уберечь мотор или механизмы от перегрева. \n\nЕго охлаждающая способность просто потрясает, а его долговечность в качестве смазочного материала просто не имеет равных. И это еще не все: оно позволяет сохранять чары на магических предметах. \n\nМне нужен сосуд этого масла, чтобы усилить магический потенциал кандалов моей работы и сделать их достаточно мощными, чтобы вызванный нами дух не прикончил нас на месте.\n\nБрокин, мой друг-гоблин, научит тебя, как изготовить масло. Ты найдешь его в долине Альтерака.", progress = "Ты принес масло? Мне оно так нужно!", completion = "Великолепно! Оно послужит прекрасным охлаждающим компонентом для браслетов! И если эти чары падут раньше, чем через сто лет, клянусь, я просто отпишу все мое имущество Серво! \n\nВсе маги лиги будут изумлены, когда я закончу работу, Томпсон! Потерпи, и ты увидишь!", rewards = "Вы получите:\n\n"},
[714] = {title = "Гиро...чего?", objective = "Принесите гирохронатом Лотвилю Вериатусу в Бесплодные земли.", description = "<имя>, ты <справился/справилась> со своей работой выше всяких похвал.\n\n*Мысли Лотвила явно витают где-то в его экспериментах.*\n\nБудешь у нас в Караносе, приходи ко мне работать, приму в любое время с распростертыми...\n\nОп-ля! Лови-лови, скорей! Да, спасибо.\n\nА сейчас мне нужна всего лишь одна малость. Довольно маленькая штуковина, но очень важная: гирохронатом.\n\nЕсли сможешь мне его добыть, я, наконец, смогу закончить этот эксперимент.", progress = "Да-да, одну секундочку... <Лотвил продолжает ковыряться в каком-то хитроумном приспособлении>", completion = "ОГО! *Лотвил хватает гирохронатом*\n\nОтлично! Мы почти у цели! Нет, в самом деле! Это же мой самый приоритетный проект! Дай-ка я засуну эту штуку в положенное ей место, и ты увидишь плоды моих – наших! – трудов! Сейчас, надо только немного подождать... пару секунд... или минут... или часов... Ладно, разберемся.", rewards = "Вы получите:\n\n"},
[715] = {title = "Жидкий камень", objective = "Принесите зелье простой невидимости и лечебное зелье Люсьену Подай-Ключ в Бесплодные земли.", description = "Полагаю, все задачи, поставленные перед тобой Лотвилом, вскоре покажутся тебе очень простыми по сравнению с тем, что ждет впереди. С другой стороны, ты <доказал/доказала> свою приверженность наукам, которые так чтит Лотвил. Не поможешь ли ты, в таком случае, и мне? \n\nМне необходимо лечебное зелье и зелье невидимости. Похоже, и то, и другое может мне вскоре понадобиться, если Лотвил продолжит в том же духе. \n\nВзамен я дам тебе рецепт зелья, разработанный мной во время обучения у Лотвила. Рецепт основан на сведениях, собранных им во время экспериментов здесь, в Бесплодных землях.", progress = "Лотвил уже почти закончил. А как твои успехи?", completion = "УРА! \n\nТо есть, я хотел сказать, спасибо, Томпсон! Это мне понадобится для путешествия по Бесплодным землям.", rewards = "Вы получите:\n\nРецепт: простое зелье каменного щитаПростое зелье каменного щита"},
[716] = {title = "Камень – лучшая одежка!", objective = "Принесите украшенные узором бронзовые наручи Люсьену Подай-Ключ в Бесплодные земли.", description = "Я знаю, каким скупым бывает Лотвил, <имя>, поэтому хочу сам вознаградить тебя за труды. Возможно, мой подарок даже поможет тебе защититься от того, что сулит это его новое изобретение... \n\nЯ собрал все неиспользованные камни, которые ты <принес/принесла> и смогу сделать из них прекрасные наручи, которые наверняка тебе понадобятся. Разумеется, они будут магическими. \n\nНо мне потребуются украшенные узором бронзовые наручи, созданные кузнецом, чтобы я смог закончить работу.", progress = "Лучше бы тебе не тянуть, Томпсон.\n\nС Лотвилом никогда не знаешь, что случится в следующий миг.", completion = "А вот и твои браслеты, Томпсон. Ну-ка, примерь!", rewards = "Вы получите:\n\nЗачарованные наручи Каменной ткани"},
[717] = {title = "Дрожь земли", objective = "С помощью знака Земли активируйте алмазный, опаловый и аметистовый столпы и извлеките рунные камни. \n\nПоместите рунные камни на печать Земли и освободите драконов Бича Тьмы и Гематуса. \n\nУбейте драконов и принесите Гареку наручники Чернохлыста, цепи Гематуса и Знак Земли.", description = "Сейчас уже очевидно, что мы не можем быть уверены, что Чернохлыст и Гематус заключены в Летлоре надежно. Там обосновались черные драконы, кроме того, этим ограм удалось завладеть знаком Земли – а это значит, что требуются куда более серьезные меры. \n\nДраконье узилище заперто тремя рунными камнями, которые можно заполучить только с помощью знака Земли. Камни нужны, чтобы сломать печать на узилище. \n\nСломай печать и сделай так, чтобы драконы упокоились навек.", progress = "Мощная магия держит драконов под замком, и все же мы должны устранить даже малейшую возможность того, что они снова вырвутся на свободу!", completion = "Кирин Тор больше не будет беспокоиться по поводу грозных пленников Летлора. Я сообщу об этом своему господину. Красус, несомненно, будет доволен.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКираса Порыва ветраХауберк с призматической чешуейЗакаленная в битве бригантинаМедальон Пламени Разума\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[718] = {title = "Миражи", objective = "Верните ящик с припасами Сигруну Рудотесу.", description = "В спешке покидая Ульдаман, мы были вынуждены бросить не одну повозку и ящик с припасами. Местные огры из лагеря Кош набросились на них, как стервятники на падаль. Хотя воняют огры не лучше... чем падаль, я имею в виду. \n\nВ общем, они растащили все наши обозы с оружием и прочим скарбом и... Короче, мне даже неловко об этом говорить, но мы тут остались слегка совсем без еды... \n\nНе <мог/могла> ли бы ты нам помочь?", progress = "Да, пустыня не лучшее место для похудания... \n\nЭй, что это у тебя?", completion = "О, благодарю тебя, Эфром! Мы тут, надо сказать, уж было песок есть подумывали. \n\nНу да это дело прошлое. Сегодня будем пировать, как короли!", rewards = "Вы получите:\n\n"},
[719] = {title = "Дворф и его инструменты", objective = "Найдите счастливую кирку Ржанеца и верните ее геологу Ржанецу к югу от карьера Тяжелоступа.", description = "Будь <осторожен/осторожна>, <имя>! Повсюду шныряют дворфы Черного Железа – видимо, из клана Кузни Теней. \n\nОни только что напали на наш раскоп и почитай всех там вырезали, включая моего шефа Тяжелоступа. Я едва ноги унес.\n\nРаскоп прямо к северу отсюда. Я вот прикидываю, как бы выручить оттуда часть наших припасов, особенно мою счастливую кирку.\n\nКак думаешь – сумеешь помочь? Наверняка кто-нибудь из этих гадов Черного Железа спер мою кирку!", progress = "Не знаю, зачем эти дворфы Кузни Теней тут рыщут, но у них определенно есть какая-то цель...", completion = "Ты спас меня, |3-6(Жрец). Рад, что нашелся кто-то, способный преподать Кузне Теней урок.", rewards = "Вы получите:\n\nМолот Рейдола"},
[720] = {title = "Предвестник надежды", objective = "Найдите геолога Ржанеца и сообщите, что Грез Тяжелоступ жив.", description = "<Куском мела на карте нацарапаны слова.>\"Рейдол, они уводят меня в Ульдаман. Пришли помощь!\n-Тяжелоступ\"", progress = nil, completion = "Тяжелоступ жив?! Какое счастье!", rewards = "Вы получите:\n\n"},
[721] = {title = "Предвестник надежды", objective = "Найдите Греза Тяжелоступа в Ульдамане.", description = "<имя>, ты сможешь разыскать его? Ты разыщешь Тяжелоступа? \n\nПроклятые дворфы из Кузни Теней схватили его, чтобы выпытать, что он знает о раскопках поселения титанов. Если это случится, весь Стальгорн будет в большой опасности! \n\nДворфы Черного Железа уже давно разыскивают способы сотворения могущественных големов. Конечно, такова была цель и Тяжелоступа, но это только для того, чтобы остановить Черную Сталь!\n\nВозможно, они сохранят ему жизнь, пока не вытянут из него все секреты. Поспеши, быть может, его еще удастся спасти!", progress = nil, completion = "О, я так ослабел... *кашляет* Подойди ко мне, |3-6(Маг)?\n\nNебя прислал Рейдол? Клянусь Мурадином, парень вовсе не так туп, как кажется.*кашляет*", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[722] = {title = "Амулет тайн", objective = "Найдите амулет Тяжелоступа и верните его ему в Ульдаман.", description = "Тебе не занимать смелости, раз ты <явился/явилась> за мной в Ульдаман, <класс>.\n\nЕсли в самом деле хочешь помочь старику Тяжелоступу... *кашляет*... Найди мне мой амулет. \n\nЭто Чернотень... Его забрал Магреган Чернотень. Он здесь, в развалинах, я знаю... Этот амулет приведет их... *кашляет* прямо к свиткам, если их не остановить... Все в твоих руках, <имя>! Пожалуйста... верни амулет. \n\nЕсли свитки попадут к ним в лапы, Черное Железо сможет создавать еще более мощных големов. Я знаю, я это нутром чую!", progress = "Клан Кузни Теней очень опасен! Будь осторожен!*кашляет* Ты должен найти амулет.", completion = "Ха!*кхе, кхе* \n\nЯ знал, что ты справишься! *сморкается* Отличная работа, Гуреус.*кашляет*", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[723] = {title = "Клятва верности", objective = "Отнесите амулет Тяжелоступа геологу Ржанецу в Бесплодные земли.", description = "<Тяжелоступ едва дышит и, собрав последние силы, произносит слова.> \n\nНайди Рейдола, <имя>! Передай ему мой амулет... <кашляет> Он знает, что делать. <кашляет> Он знает, я искал истоки происхождения нашего народа, <кашляет> знает и то, что целью моей жизни было остановить клан Кузни Теней. Нельзя позволить, чтобы они нашли свитки... <кашляет>", progress = "Сегодня дурной день. Однако в Бесплодных землях каждый день убивает надежду.", completion = "Амулет Тяжелоступа! Если раньше в моем сердце еще теплилась надежда, что он жив, то теперь ничто не снимет с моей души этот камень. Этот амулет – дело всей его жизни. Нельзя допустить, чтобы его смерть была напрасной!", rewards = "Вы получите:\n\n"},
[724] = {title = "Клятва верности", objective = "Отнесите амулет Тяжелоступа историку Карнику в Стальгорне.", description = "К кому же обратиться за советом... \n\nИсторик Карник! Конечно! \n\nОн сейчас в Стальгорне – он точно сможет помочь! Он искал потерянные артефакты вместе с Тяжелоступом в Ульдамане. \n\nПолагаю, в Кузне Теней прознали, что эти двое располагают тайными сведениями. \n\nСообщи Карнику о том, как погиб Тяжелоступ, и передай ему амулет – а он расскажет, что делать дальше.", progress = "Так-так... Еще один путник, которому что-то нужно от дворфов... \n\nСтупай своей дорогой добрый господин у меня нет времени на праздную болтовню!", completion = "О, а вот это совсем другой разговор! Возможно, ты еще не осознал всей серьезности происходящего, ведь так? \n\nМы оплачем Тяжелоступа позже. \n\nСейчас я объясню тебе, почему этот амулет так важен.", rewards = "Вы получите:\n\n"},
[725] = {title = "Слухи об угрозе", objective = "Найдите советника Белграма и отдайте ему записку.", description = "<имя>, беги, найди советника Белграма как можно скорее. Расскажи ему, что <видел/видела>, и спроси, что нам делать дальше. Отдашь ему эту записку, я изложил в ней все как можно подробней. \n\nА я пока побеседую с духом Тяжелоступа. Возможно, ему известно нечто, что сможет помочь нам пресечь безумные действия Тенегорнских прихвостней в Бесплодных землях. Теперь нам остается только молиться.", progress = "Слушаю тебя, |3-6(Жрец).", completion = "А, весточка от историка Карника. Прекрасно. \n\nДля него у меня всегда найдется минутка.\n\n*Советник Белграм разворачивает записку и погружается в чтение.*", rewards = "Вы получите:\n\n"},
[726] = {title = "Слухи об угрозе", objective = "Поговорите с историком Карником.", description = "*Когда советник Белграм дочитывает письмо до конца, его глаза в ужасе расширяются*\n\nЭто дурные вести... \n\nПожалуйста, вернись к историку Карнику и извести его именем короля, что он должен действовать быстро и рассудительно. Он должен остановить Кузню Теней в Бесплодных землях.", progress = nil, completion = "Ты действуешь по этому делу с поспешностью, которая сделала бы честь и королю, Димиллион! \n\nХорошо. Я знаю, что делать с Кузней Теней. \n\nИх силы в Ульдамане будут рассеяны, если мы поразим их в самое сердце – ударим по крепости Ангор.", rewards = "Вы получите:\n\n"},
[727] = {title = "В Стальгорн за книгой Йагина", objective = "Отнесите печать Молота Геррику Костохвату в Заброшенный грот в Стальгорн.", description = "Эта табличка говорит о многом. И все же этого недостаточно! \n\nЕсть книга – древняя книга Йагина. Те, от кого я бежал... Они хранят эту книгу и самые мудрые из них изучают ее. Она содержит обширные знания, и в ней можно найти ключ к спасению! \n\nОтправляйся к Геррику Костохвату. Ты найдешь его в лавке в Стальгорне, в Заброшенном гроте. Покажешь ему эту печать, и он примет тебя за своего. Попроси у него книгу Йагина и принеси ее мне.", progress = "Приветствую! Добро пожаловать в мою лавку, только не трогайте что попало! \n\nЗнание может быть смертельно опасным!", completion = "О, рад видеть тебя брат.", rewards = "Вы получите:\n\n"},
[728] = {title = "В Подгород за книгой Йагина", objective = "Отнесите печать Молота хранителю Бел'дугуру в Подгород.", description = "Эта табличка говорит о многом. И все же этого недостаточно! \n\nЕсть книга – древняя книга Йагина. Те, от кого я бежал... Они хранят эту книгу, и самые мудрые из них изучают ее. Она содержит обширные знания, и в ней можно найти ключ к спасению! \n\nОтправляйся к хранителю Бел'дугуру в Лордерон. Покажешь ему эту печать, и он примет тебя за своего. Попроси у него книгу Йагина и принеси ее мне.", progress = "Ага, кто это у нас тут? Жаждущий знаний |3-6(Воин)! Пришел взглянуть на мою коллекцию? Милости прошу! \n\nНо помни: во многом знании много печали, и преумножащий знания преумножает скорбь...", completion = "Будь осторожен, |3-6(Воин). Многие на этом свете сомневаются в праведности наших дел. И многие из них сделали бы все возможное, чтобы уничтожить нас! \n\nТы должен всегда сохранять бдительность, осторожность и терпение...", rewards = "Вы получите:\n\n"},
[729] = {title = "Рассеянный геолог", objective = "Отправляйтесь на юг, найдите геолога Сомнамбулера и узнайте, как у него дела.", description = "Мне была оказана большая честь, когда мастер Седоус назначил меня работать под руководством великого геолога Сомнамбулера. В академии в Стальгорне все знают о грандиозных открытиях Сомнамбулера.\n\nНо геолог довольно... ммм... рассеян... порой кажется, что он не от мира сего.\n\nМы обнаружили признаки некогда крупного поселения. Из-под земли выскочили ужасные големы и заполонили весь раскоп. Но Сомнамбулер, казалось, так ничего и не заметил. Я побежала обратно в Аубердин за помощью.\n\nПрошу тебя, отправляйся на юг и посмотри, все ли в порядке с геологом!", progress = nil, completion = "Это ты, Холли? Мне нужна помощь, надо подолбить этот камень. Передай-ка мне мою щетку для камня – мне кажется, я тут что-то вижу.\n\nОй, да ты не Холли! Вряд ли ты видел мою щетку для камня...\n\nА, забудь об этом! Я обещал Лиге, что отошлю им ту таинственную окаменелость, что я нашел. Куда же делась Холли?\n\nТак много нужно сделать! И где ж эта таинственная окаменелость... и моя щетка... и Холли...\n\nИ ты кто будешь... правда, это неважно, если ты хочешь помочь.\n\nДай знать, когда сможешь начать поиски.", rewards = "Вы получите:\n\n"},
[730] = {title = "Неприятности на Темных берегах?", objective = "Отправьтесь в Аубердин и найдите следы дворфской изыскательской группы.", description = "Приятно видеть! <класс>, <интересующийся/интересующаяся:c> великими археологическими чудесами нашего мира!\n\nЧасто наши друзья из Альянса считают нашу работу чем-то вроде развлечения. Многие просто отказываются понимать. Великая, могущественная сила угрожает всему Азероту – от Лордерона до Калимдора.\n\nМеня очень беспокоит судьба группы, которую я отправил на Темные берега. От них уже несколько недель ни слова.\n\nОтправляйся в Аубердин и узнай, где они предположительно могут находиться.", progress = nil, completion = "Как же здорово, что главный археолог Седой Ус прислал вас...", rewards = "Вы получите:\n\n"},
[731] = {title = "Рассеянный геолог", objective = "Защищайте геолога Сомнамбулера, пока он ищет таинственную окаменелость, а затем вернитесь к археологу Холли в Аубердин.", description = "Итак, Холли... А, да, верно, ты же не Холли. А где Холли?\n\nАй, ладно, это к делу не относится. Мы должны найти эту щетку для камня... то есть я имею в виду таинственную окаменелость! Мы должны найти эту окаменелость. Лига исследователей в Дарнассе захочет узнать, чем я тут занимаюсь.\n\nДай мне знать, когда будешь <готов/готова>, и начнем поиски этой щетки... ну, то есть окаменелости! Мы найдем какой-нибудь документ, чтобы в Лиге остались довольны.\n\nТак что, <готов/готова>?", progress = nil, completion = "Слава звездам, геолог Сомнамбулер в безопасности! Я же говорила тебе, какой он рассеянный. Не могу поверить, что он твердо хочет остаться там, где рядом повсюду рыщут жуткие твари!", rewards = "Вы получите:\n\n"},
[732] = {title = "Дрожь земли", objective = "Принесите знак Земли Гареку.", description = "Сигрун сказал, что ты <оказал/оказала> ему неоценимую помощь. Возможно, мне она тоже понадобится. Меня прислал сюда мой господин, Красус из Кирин Тора, чтобы прекратить беспорядки в низине Летлор. \n\nЯ не имею права разглашать поставленные передо мной задачи, но можешь не сомневаться – они имеют самое первостепенное значение.\n\nШайка бродячих огров, которых видели близ лагеря Бофф, украла предмет, именуемый знаком Земли. Мне необходимо вернуть этот предмет. Принеси его мне, и я расскажу тебе больше.", progress = "Шайка бродячих огров кочует от лагеря к лагерю в Бесплодных землях. Пустынный ветер заметает их следы, и их перемещения крайне сложно отследить. Слыхал, их видели недавно близ лагеря Бофф. Попробуй поискать там.", completion = "Ты принес знак, Маладат, – это очень хорошая весть! Знак Земли был создан дворфами Черного Железа из Крепости Ангор, чтобы заключить в узилище двух беспощадных драконов-помощников Смертокрыла – близнецов Бича Тьмы и Гематуса.", rewards = "Вы получите:\n\n"},
[733] = {title = "Помогите кто чем может!", objective = "Принесите 7 кусков металлолома Сигруну.", description = "Да, туго нам придется, если мы не сможем раздобыть материалов для возведения простейших укреплений и других нужд. Заметил я, что у огров в этих землях полно металлолома. Возможно, легенды об осадных машинах, применявшихся в Бесплодных землях, не так уж далеки от истины...\n\nВ общем, проспектор очень беспокоится за состояние нашего маленького лагеря, так что надо приниматься за работу как можно скорее. \n\nГлавный лагерь огров расположен рядом с Гротом Гнилобрюхих, к западу отсюда. Учти – расстояние приличное!", progress = "Ну, мы тут состряпали кое-какое укрепления из подручных материалов, но... Как видишь, наскребли негусто. Удалось добыть что-нибудь?", completion = "Спасибо, Эфром! Думаю, это поможет нам дотянуть до распоряжения из Стальгорна или Лиги Исследователей.\n\nЭх, добыть бы теперь соли для закалки оружия...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЩит СалбакаПодкованные сапоги\n\nВы также получите:\n\n"},
[734] = {title = "Сложная задача", objective = "Поговорите с Люсьеном Подай-Ключ в Бесплодных землях.", description = "Пекрасно, прекрасно... \n\n*Лотвил на секунду отрывает взгляд от кандалов*\n\nСбегай-ка к Люсьену, <имя>. Мне нужен зубец#5. Принеси его мне.", progress = nil, completion = "Зубец #5, значит? Да, добром это не кончится...", rewards = nil},
[735] = {title = "Звезда, Длань и Сердце", objective = "Доставьте предметы, перечисленные в записке Костохвата, Геррику Костохвату в Стальгорн.", description = "Книга Йагина, да? Вы хотите написать в ней новую главу о нас? Ну да, не мне спрашивать.\n\nЯ помогу вам – у меня как раз есть дополнительный экземпляр. Мы ведь должны друг другу помогать, не так ли? Только так мы добьемся успеха.\n\nМне нужны три предмета силы. Принесите их мне – и получите книгу.\n\nНазваний преметов я вам не скажу – нас могут подслушивать. Но я их вам напишу.", progress = "Вы принесли то, о чем я вас просил?", completion = "На вас можно положиться, |3-6(Охотник). Воистину, вам предстоит вписать новую главу в книгу нашего ордена, и я уверен, что это будут славные страницы.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[736] = {title = "Звезда, Рука и Сердце", objective = "Прочитайте записку Бел'дугура. Принесите перечисленные в записке предметы Бел'дугуру в  Подгород.", description = "Тебе нужна книга Йагина? Планируешь собрать свое стадо? Ну, разумеется... и я с удовольствием помогу тебе, <брат/сестра>.\n\nВзамен я также попрошу тебя о помощи.\n\nМне нужны три предмета силы. Принеси их – и книга будет твоей.\n\nНазвать вслух эти предметы я не могу, но запишу их.\n\nДобудь мне все, что я укажу в списке. Если справишься с этим, значит, ты действительно <достоин/достойна> начать новую главу в истории нашего ордена.", progress = "Как продвигаются дела, |3-6(Разбойник)?", completion = "Поразительно! Ты обладаешь или великим искусством, или удачей, иначе тебе не удалось бы добыть эти реликвии. Так или иначе, ты очень помог нам.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[737] = {title = "Запретное знание", objective = "Отнесите книгу Йагина Тэльдруину.", description = "У меня есть для тебя книга, <имя>. Думаю, не стоит говорить, что с ней нужно обращаться очень бережно. И непременно держать подальше от рук врагов. \n\nВ этой книге содержится много секретов...\n\nОпасных секретов!", progress = "Ну вот и ты! Где пропадал? Принес книгу?", completion = "Вот она! О, проблеск надежды! \n\nБыть может, твои труды принесли нам спасение, Бумшакалака! Тебе нужно поставить памятник! Воздвигнуть святилище! Славить твое имя в сказаниях, пока у детей твоих детей не родятся правнуки! \n\nЕсли только... Если только ОНИ еще не вырвались на свободу. Потому что если это случится, можешь забыть о детях. \n\nЕсли ОНИ вырвались на свободу, мы все пойдем на корм червям.", rewards = "Вы получите:\n\nЧереп Надвигающегося Рока"},
[738] = {title = "Найти Эгмонда", objective = "Найдите Эгмонда.", description = "Проспектор Эгмонд вел раскопки в Бесплодных землях, на юго-западе. Я говорю \"вел\", потому что, к несчастью, от него нет вестей уже не одну неделю. Его нужно найти. \n\nВ последний раз его видели на самом южном раскопе Бесплодных земель – он расположен за Крепостью Ангор. Думаю, стоит начать поиски там.", progress = nil, completion = "Должно быть, этот скелет принадлежит Эгмонду. Его кости изломаны и выбелены солнцем.", rewards = "Вы получите:\n\nДраный пояс геологаНефритЗолотая руда"},
[739] = {title = "Мурдалок", objective = "Уничтожьте убийцу Эгмонда, Мурдалока. \n\nУбейте 12 костегрызов из племени Каменного Свода. \n\nСообщите геологу Сталекруту в Лок Модане обо всем, что произошло.", description = "Следы Эгмонда уводят на запад. Судя по кровавым следам на камнях и песке, дворф полз на коленях. \n\nИ здесь он умер. \n\nПод правой рукой мертвеца еле виднеется слово, нацарапанное на куске песчаника. \n\n\"Мурдалок,\" – гласит надпись.", progress = nil, completion = "Это горькая весть, Wrestlecake! Он был силен и славно управлялся с молотом. Не сомневаюсь, прежде чем он пал от лап троггов, он уничтожил не одну мерзкую тварь.", rewards = "Вы получите:\n\nКаменный распылитель"},
[741] = {title = "Рассеянный геолог", objective = "Отвезите таинственную окаменелость главному археологу Седоусу в Дарнасс.", description = "Так геолог хочет отослать эту таинственную окаменелость Лиге исследователей в Дарнасс? Мне не хотелось бы уезжать с Темных берегов без него.\n\nВот, <имя>, отвезите эту таинственную окаменелость главному археологу Седоусу в Дарнасс.", progress = "Чем могу помочь, |3-6(ночной эльф)?", completion = "Ух ты! Только геолог Сомнамбулер мог сделать такое открытие!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМолотобойные перчаткиВетрофетровые перчаткиРеликвия - пояс охотника\n\nВы также получите:\n\n"},
[742] = {title = "Большая охота", objective = "Поговорите с Сенани Громосерд на заставе Расщепленного Древа в Ясеневом лесу.", description = "Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!\n\nОрде удалось закрепиться в землях к северу от Степей. И два наших форпоста – застава Расщепленного Древа и застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на заставе Расщепленного Древа, к северу от Степей. Она ждет желающих принять участие в большой охоте!", progress = nil, completion = "Добро пожаловать на новое пограничье, Топблэйд. Ясеневый лес – край неограниченных возможностей, где юному |3-2(Воин) вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть.\n\nКак понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.", rewards = "Вы получите:\n\n"},
[743] = {title = "Опасности Ярости Ветра", objective = "Принесите 8 когтей гарпий из стаи Ярости Ветра Руулу Орлиному Когтю в деревню Кровавого Копыта.", description = "Спасибо, что <выбрал/выбрала> время поговорить со мной, <имя>. Я Руул, воин и учитель.\n\nПришло время пройти испытания и покинуть Мулгор.\n\nЕсли ты хочешь проверить свою силу, вызови на бой гарпий Ярости Ветра, живущих на юго-востоке. Они гнездятся вдоль гребня гор в стороне от дороги.\n\nЭти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе.", progress = "Гарпии из клана Ярость Ветра – наши смертельные враги. Их ярость в битве сравнится лишь с их жаждой сырой плоти.", completion = "Молодец, Коровкинг. Похоже, ты готов двинуться дальше. Попутного тебе ветра!", rewards = "Вы получите:\n\n"},
[744] = {title = "Подготовка к церемонии", objective = "Добудьте 6 лазурных перьев и 6 бронзовых перьев, и принесите их Эйану Орлиному Когтю в Громовой утес.", description = "<имя>, вскоре мой брат предстанет перед вождем Кровавым Рогом, и мне выпала большая честь сделать для него головной убор.\n\nМне хотелось бы попросить тебя об одолжении – надо сделать одно дело, пока я буду красить эти кожаные полоски. Я просто не успею добыть достаточное количество перьев – так не поможешь ли ты мне в этом?\n\nПерья нужной величины можно найти у гарпий, что живут далеко на севере и северо-западе от Громового Утеса. Мне нужно всего-то 6 лазурных и 6 бронзовых перьев, чтобы закончить работу.", progress = "Этот головной убор станет замечательным подарком моему брату!", completion = "Спасибо за помощь, Коровкинг.\n\nМое участие в церемонии в честь моего брата почти закончено. От меня требуется только подарить ему этот убор и быть свидетелем.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНеотчуждаемая портупеяПлеменной щит воина\n\nВы также получите:\n\n"},
[745] = {title = "Недобрые соседи", objective = "Убейте 10 дубильщиков, 8 шкуродеров и 5 браконьеров из стаи Блеклогривов и возвращайтесь к Бейну Кровавому Копыту в деревню Кровавого Копыта.", description = "<имя>, нашей земле причиняют боль раздоры ее обитателей. Я надеюсь, что тебе не суждено видеть столько войн, сколько выпало мне. И все же я вынужден просить тебя вступить в бой. Благодаря этому ты поймешь, что малая угроза, если не искоренить ее, со временем разрастается.\n\nГноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора.\n\nСлова бессильны остановить их.", progress = nil, completion = "Хорошо, что ты отнесся к моему заданию со всей серьезностью, Коровкинг. Очень важно уважать землю и ее обитателей. Жизнь и смерть – это вечный цикл... Необходимость. Одно не может существовать без другого. Обдумай это хорошенько и никогда не забывай.", rewards = "Вы получите:\n\nМелкая пулька"},
[746] = {title = "Дворфийские делишки", objective = "Соберите 5 кирок геолога.\n\nСломайте их в кузнице. \n\nОтнесите 5 сломанных инструментов Бейну Кровавому Копыту в деревню Кровавого Копыта.", description = "К северо-западу отсюда дворфы готовятся к раскопкам. Они думают, что тайны скрыты глубоко в земле, и это правда, но у нее надо учиться, а не осквернять бесконечными ямами.\n\nСобери инструменты дворфов, уничтожь их и принеси мне.\n\nЛомать инструменты можно в кузнице, которая есть в Громовом Утесе, но подойдет любая, даже та, что находится в дворфийском лагере.", progress = "Привет, Коровкинг. Ты принес сломанные инструменты? Дворфийские раскопки разъяряют мулгорских кодо. Пора положить конец осквернению нашей земли!", completion = "Спасибо, Коровкинг. Звери Мулгора успокоятся. И, если будет на то воля духов, дворфы познают, что бурение земли – не лучший путь к обретению знаний.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nУкрепленные наручникиГрубо сшитые поножи из шкуры кодо\n\nВы также получите:\n\n"},
[747] = {title = "Охота начинается", objective = "Принесите 7 перьев равнинных долгоногов и 7 кусков мяса равнинных долгоногов Груллу Соколиному Ветру.", description = "Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем. Возможно, вскоре тебя позовут в Громовой Утес. Но прежде чем это случится, тебе придется доказать моему отцу, вождю Соколиному Ветру, что ты $Gдостоин:достойна; этой чести. \n\nНа плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы. Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды. Покажи, на что ты <способен/способна>, – поохоться на равнинных долгоногов и принеси мяса в деревню.", progress = "Добыча пищи и перьев для племени – первый шаг на пути к завоеванию расположения вождя.", completion = "Таурены Нараче благодарят тебя, Коровкинг. Я  уверен, ты достигнешь больших высот.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПояс кочевникаОкрашенные плетеные перчатки\n\nВы также получите:\n\n"},
[748] = {title = "Отравленная вода", objective = "Принесите 6 лап койотов и 4 когтя равнинного долгонога Муллу Громовому Рогу в деревню Кровавого Копыта.", description = "Гоблины и их прислужники отравили наши священные колодцы! Это недопустимо.\n\nДля очищения колодцев придется создать тотемы, а ты пойдешь с ними к колодцам и проведешь очищающие ритуалы.\n\nНачнем мы с колодца Заиндевевшего Копыта. Земля сама поможет нам. Принеси мне лапы койотов и когти взрослых долгоногов. Эти звери живут на юго-западе.", progress = "Ты несешь лапы и когти, Коровкинг?", completion = "Молодец, Коровкинг. Я вплету силу принесенных тобой вещей в тотем Очищения.", rewards = "Вы получите:\n\n"},
[749] = {title = "Разграбленный караван", objective = "Морин Ловец Облаков попросил вас изучить содержимое ящиков с припасами в разграбленном караване.", description = "Несколько дней назад мы наткнулись на охраняемый караван Торговой компании, следовавший вдоль северного берега озера Каменного Быка. В предыдущей битве мы потеряли двоих, поэтому на сей раз мы напали без промедления и уничтожили караван.\n\nМы бросили их ящики с припасами, полагая, что наши факелы уничтожат все ценное, но учитывая, что возле сожженных телег видели мародеров Торговой компании, похоже, мы ошиблись.\n\nБыть может, ты сходишь к каравану и посмотришь, что в ящиках?", progress = nil, completion = "Все стороны ящика опечатаны знаками рудникового отдела Торговой компании. Сбоку прикреплены пометки, что содержимое должно быть обработано на одном из центральных заводов компании.", rewards = "Вы получите:\n\n"},
[750] = {title = "Охота продолжается", objective = "Принесите 10 шкур горных пум Груллу Соколиному Ветру.", description = "Любой искушенный в охоте таурен понимает, что ее смысл не заключается в убийстве любой подвернувшейся добычи. Живущие на равнине звери обеспечивают нас всем необходимым для выживания. Ты произведешь впечатление на старейшин, если принесешь им несколько шкур горных пум – они у нас очень высоко ценятся! \n\nНашим детям нужна одежда, да и шатры пора подлатать.", progress = "Если ты сможешь добыть шкуры, я замолвлю о тебе словечко перед отцом, вождем Соколиным Ветром.", completion = "Таурены из Нараче благодарят тебя за твои дары, Коровкинг. Твое охотничье искусство будет высоко цениться в Громовом Утесе.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНаручи кочевникаОкрашенный плетеный пояс\n\nВы также получите:\n\n"},
[751] = {title = "Разграбленный караван", objective = "Отнесите бумаги Торговой компании Морину Ловцу Облаков, которого можно найти неподалеку от Деревни Кровавого Копыта.", description = "Приоткрыв крышку, вы видите плотно упакованную руду и минералы – новое свидетельство деятельности Торговой компании в Мулгоре. Поверх руды и минералов лежит пачка бумаг.\n\nСо стороны восточных предгорий доносятся звуки работы и к небу поднимается дым от больших костров.", progress = "Привет тебе, Коровкинг. Удалось что-нибудь вызнать о планах Торговой компании и ее деятельности на нашей родине?\n\nЕсли они хотят творить в наших землях то же, что и в других, мы быстро с этим покончим.", completion = "Похоже, Торговая компания в самом деле замыслила лишить нас всех природных ресурсов. Хорошо знать это наверняка, пожалуй, пришло время действовать.", rewards = "Вы получите:\n\n"},
[752] = {title = "Скромная просьба", objective = "Поищите матушку вождя Соколиный Ветер у источника к юго-востоку от Лагеря Нараче.", description = "Все члены племени живут вместе в мире и гармонии. \n\nМы преданы друг другу и отвечаем друг за друга. Я обращаюсь к тебе со скромной просьбой. \n\nМоя матушка сегодня отправилась за водой к источнику к юго-востоку от Нараче. С тех пор прошло довольно много времени. Не поищешь ли ты ее, пока я занимаюсь делами племени?", progress = nil, completion = "Ты проделал такой путь, чтобы помочь старушке? Да, похоже ты чтишь традиции нашего народа.", rewards = "Вы получите:\n\n"},
[753] = {title = "Скромная просьба", objective = "Наберите кувшин воды из колодца.\n\nОтнесите кувшин вождю Соколиному Ветру в Лагерь Нараче, который находится к северо-западу от источника.", description = "В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше. Я еще могу принести пользу своему племени – просто иногда мне требуется чуть больше времени. \n\nДумаю, ты <достойный/достойная:c> <класс>. Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче. \n\nПомни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин.", progress = "Ты вернулся с равнины, как я понимаю? Есть ли вести от Великой матери Соколиный Ветер?", completion = "Ты принес мне этот кувшин по просьбе Великой матери Соколиный Ветер. \n\nТвоя готовность помочь другим и желание обеспечить тауренов Лагеря Нараче всем необходимым вселяет в меня уверенность, что придет день, когда мы будем гордиться тобой в Громовом Утесе.", rewards = "Вы получите:\n\n"},
[754] = {title = "Очищение колодца Заиндевевшего Копыта", objective = "Очистите колодец Заиндевевшего Копыта с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.", description = "Я создал тотем для очищения Колодца Заиндевевшего Копыта. Отнеси его к колодцу и произведи ритуал очищения. Колодец находится на юго-востоке, и его охраняют мерзкие гоблины!\n\nЗадание непростое, но кому-то придется это сделать, иначе мы не сможем набирать там воду.\n\nУдачи тебе, <имя>.", progress = nil, completion = "До меня только что дошли вести о твоем деянии – звери уже спешат к колодцу на водопой.\n\nТы оказал большую услугу нашему краю, Коровкинг. И всему народу тауренов.", rewards = "Вы получите:\n\n"},
[755] = {title = "Обряды Матери-Земли", objective = "Отправьтесь к провидцу Серой Пасти, который живет на юге от Лагеря Нараче.", description = "Твоя готовность выполнить скромную просьбу таурена из Нараче и твое желание обрести новые знания весьма похвальны, <имя>. Не сомневаюсь, придет день, и тебя, <класс>, назовут <одним/одной> из величайших. \n\nНо сначала ты <должен/должна> пройти три обряда Матери-Земли. \n\nПервым испытанием будет Обряд Силы. Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер. \n\nОбиталище провидца сокрыто в холмах к югу от Лагеря Нараче.", progress = nil, completion = "Тебя прислал вождь Соколиный Ветер? Обряды Матери-Земли гораздо сложнее, чем кажутся на первый взгляд...", rewards = "Следующее заклинание будет наложено на вас:\n\nЗнак дикой природы\n\nВы получите:\n\n"},
[756] = {title = "Тотем Громового Рога", objective = "Принесите 6 когтей охотников прерий и 6 когтей пум плоскогорья Муллу Громовому Рогу.", description = "Для создания Тотема очищения колодца Громового Рога тебе понадобятся когти хищников мулгорских равнин. Придется тебе убить несколько охотников прерий и пум плоскогорья, живущих на востоке и на западе, и принести мне их когти.", progress = "Ну как, ты добыл когти, как я велел? С каждым часом Колодец Громового Рога загрязняется все больше!", completion = "Спасибо, Коровкинг. Чтобы создать следующий очищающий тотем, тебе придется постичь, в чем разница между убийством ради пропитания и бессмысленной жестокостью.\n\nГоблинам же не дано понять разницу между захватом земли и жизнью в гармонии с ней.", rewards = "Вы получите:\n\n"},
[757] = {title = "Обряд Силы", objective = "Убивайте дыбогривов в Ежевичной лощине и принесите 12 их поясов вождю Соколиному Ветру в Лагерь Нараче.", description = "Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утеса.\n\nСначала ты <должен/должна> пройти обряд Силы. Чтобы выдержать это испытание, ты <должен/должна>  доказать свою храбрость, убивая врагов племени. \n\nВоины клана Вздыбленная Щетина из Ежевичной лощины вторгаются в земли нашего племени. Они нападают на наших охотников и грабят деревню по ночам. \n\nПокажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства.", progress = "Ты прошел обряд Силы, Коровкинг? Покажи мне доказательства твоей доблести, проявленной в войне против нашего врага – клана Вздыбленной Щетины.", completion = "Ты прошел первый из обрядов Матери-Земли. Племя гордится тобой!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСкальная палицаКаменный томагавкНож для выстругиванияПалка старейшиныТопор Отважного\n\nВы также получите:\n\n"},
[758] = {title = "Очищение колодца Громового Рога", objective = "Очистите колодец Громового Рога на севере от деревни с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.", description = "Тотем готов, <имя>. Остается лишь провести ритуал очищения.\n\nСтупай к колодцу Громового Рога на севере от деревни и проведи ритуал с помощью Тотема очищения колодца Громового Рога. После этого возвращайся ко мне.\n\nИ да пребудут с тобой духи.", progress = nil, completion = "Предки клана Громового Рога явились ко мне во сне и восхваляли тебя за очищение их колодца.\n\nОни просили передать тебе это в знак признательности…", rewards = "Вы получите:\n\nПлащ Громового рога"},
[759] = {title = "Тотем Буйногривых", objective = "Отнесите 8 зубов могучего волка прерий Муллу Громовому Рогу в Деревню Кровавого Копыта.", description = "Тебе осталось очистить лишь один колодец, названный в часть племени Буйногривых. Для этого тебе понадобятся зубы лютого хищника, могучего волка прерий. Ступай на север, убей его и возвращайся.\n\nМогучие волки прерий водятся неподалеку от славного города Громового Утеса.", progress = "Коровкинг. Несешь ли ты зубы волков?", completion = "Замечательно, Коровкинг. Увы, нашей земле приходится приносить в жертву своих детей, и я исполняюсь печали и гордости.", rewards = "Вы получите:\n\n"},
[760] = {title = "Очищение колодца Буйногривых", objective = "Очистите колодец Буйногривых с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.", description = "Духи говорят о твоих успехах в деле очищения колодцев племен Заиндевевшего Копыта и Громового Рога, <юный/юная:c> <класс>. Тотем Буйногривых готов, и ты можешь приступить к выполнению задания.\n\nКолодец Буйногривых расположен на севере от Громового Утеса. Проведи ритуал! Избавь нашу землю от гоблинского яда! Пусть вода вновь станет чистой!", progress = "Последний колодец все еще отравлен, Титано. Не мешкай!", completion = "Ты справился! Наши колодцы снова чисты, а земля исцелена. Деревня Кровавого Копыта признательна тебе, Коровкинг.\n\nПусть ветер шепчет о твоих подвигах сотни лет, а воды Мулгора остаются чистыми навек.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПарадный томагавкПосох Сновидца\n\nВы также получите:\n\n"},
[761] = {title = "Охота на перепелятников", objective = "Принесите 8 трофейных перьев перепелятника Харкену Тотему Ветра в Деревне Кровавого Копыта.", description = "Перепелятники – хитрые птицы. Их нелегко найти и убить. Связка перьев перепелятника – все равно что медаль для охотника, говорящая о его уме и решимости.\n\nЕсли ты хочешь взяться за это задание, ступай на равнины и убей нескольких перепелятников. \n\nПринеси мне их перья, и прославь свой клан этой победой.\n\nПерепелятники живут по всему Мулгору, но заметить их могут лишь очень зоркие глаза, а догнать – лишь резвые копыта.", progress = "Ну как, нашел перепелятников? А где их перья?", completion = "Я знаю, набрать достаточно перьев было нелегко. Но тем самым ты показал, на что способен. Хорошо, что ты живешь у нас в деревне.", rewards = "Вы получите:\n\n"},
[762] = {title = "Посланник зла", objective = "Убейте посла Инфернуса в Крепости Ангор и принесите доказательство его смерти советнику Белграму в Стальгорн.", description = "Посол Инфернус был отправлен в Крепость Ангор самим Рагнаросом, чтобы надзирать за поисками потерянных артефактов Кузней Теней в Ульдамане. \n\nНам и без того было непросто, а теперь я даже боюсь предположить, сколько артефактов они смогут найти и использовать против Стальгорна! \n\nЗадача проста, <имя>! Возвращайся в Бесплодные земли и уничтожь посла Инфернуса. Как только ты выполнишь это задание, возвращайся к советнику Белграму с доказательством своего успеха. \n\nТеперь все в твоих руках!", progress = "Время дорого, Лолкка! Рагнарос не будет ждать, когда мы подготовимся.", completion = "Лолкка, твоя преданность Стальгорну и народу дворфов не будет забыта. Благодарю тебя за помощь. \n\nЯ извещу историка Карника о твоих успехах письмом и отправлю рабочих в Бесплодные земли, чтобы они возобновили работы на раскопках как можно скорее. Еще раз благодарю тебя. \n\nПрежде чем ты уйдешь, выполни еще одну просьбу от имени короля Бронзоборода.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nМеч дворфийского капитана"},
[763] = {title = "Обряды Матери-Земли", objective = "Отнесите тотем Соколиного Ветра Бейну Кровавому Копыту в Деревню Кровавого Копыта. Следуйте по дороге из Лагеря Нараче.", description = "Чтобы продолжить прохождение обрядов Матери-Земли, ты <должен/должна> пройти еще два испытания. Тебе бы не помешало поднабраться опыта, <имя>.\n\nОтправляйся в Деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утеса. \n\nОтнеси этот тотем Бейну. Он узнает мою руку в этой резьбе и поможет тебе в твоем путешествии.\n\nСледуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!", progress = "Что привело тебя в мою деревню, |3-6(Друид)?", completion = "О, весточка от моего старого друга, вождя Соколиного Ветра! Смотри-ка, он пишет мне, что ты |3-6(таурен) особой породы!", rewards = "Вы получите:\n\n"},
[764] = {title = "Торговая компания", objective = "Убейте 14 рабочих Торговой компании и 6 бригадиров Торговой компании по поручению Морина Ловца Облаков из Деревни Кровавого Копыта.", description = "Теперь понятно, почему в Мулгоре появилось много сотрудников и оборудования Торговой компании. Эти гоблины... Компания слишком быстро растет, не жди добра. Как говорят, гоблинам палец в рот не клади.\n\nМаленькие жадины. К несчастью для их деловых операций, таурены не согласны терпеть их присутствие в своих землях. Ступай в их рудник на северо-востоке от разграбленного каравана и преподай им урок.", progress = "Торговой компании не дали прав на разработку полезных ископаемых в Мулгоре, но они не понимают по-хорошему. Мы, таурены, тоже не любим тратить слова понапрасну. Придется объяснить на понятном им языке.", completion = "Думаю, такой намек невозможно не понять, а? Торговая компания не будет впредь так легко относиться к тауренам или заносчиво полагать, будто мы без лишних слов позволим похищать наши полезные ископаемые.", rewards = "Вы получите:\n\n"},
[765] = {title = "Бригадир Шумовик", objective = "Убейте бригадира Шумовика и принесите его планшет Морину Ловцу Облаков в Деревню Кровавого Копыта.", description = "Согласно документам, которые ты <отыскал/отыскала> в караване, Торговая компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить.\n\nМне тошно слышать, на какую низость они готовы пойти ради достижения цели. Я хочу уничтожить того, кто разработал эти планы. Его зовут бригадир Шумовик, он сейчас в руднике Торговой компании на востоке от разграбленного каравана. Принеси мне его планшет, посмотрим, нет ли в нем чего полезного.", progress = "Меня душит злоба, как подумаю о мерзостях, которые была готова совершить Торговая компания во имя прибыли.", completion = "Ярость немного отступила при вести о гибели злодея Шумовика. Я пороюсь в его личных вещах, посмотрю, нет ли там дополнительных сведений о ближайших планах Торговой компании. Спасибо за помощь, Коровкинг.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКомпактный боевой ножГоблинский сокрушитель\n\nВы также получите:\n\n"},
[766] = {title = "Маззранач", objective = "Принесите сердце койота, бедренную кость пумы плоскогорья, чешую долгонога и потроха перепелятника Мауру Заклинателю Дождя в деревню Кровавого Копыта.", description = "Дедушка рассказывал мне истории о столкновениях с долгоногом Маззраначем. О его красных, как у демона, глазах, острых, как бритва, когтях и ядовитых укусах.\n\nИ вот ирония судьбы – он встретился мне во время странствий по равнинам и здорово укусил меня за плечо. Мой дед ничуть не преувеличил, описывая это жуткое создание. Теперь мне нужны редкие части животных, чтобы вылечить воспаленную рану: сердце койота, бедро пумы, чешуя равнинного долгонога и потроха перепелятника.\n\nТоропись, время не ждет.", progress = "Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед…\n\nТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.", completion = "А, спасибо. Из этих компонентов я сделаю лекарство, которое остановит распространение инфекции и излечит меня. Я обязан тебе жизнью.\n\nНо пронзительный крик Маззранача и блеск его безжалостного клюва мне никогда не забыть…\n\nБудь осторожен во время своих странствий.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСкалолазные сапогиНакулачники охотника прерий\n\nВы также получите:\n\n"},
[767] = {title = "Обряд прозрения", objective = "Поговорите с Зарельманом Две Луны в Деревне Кровавого Копыта.", description = "Обряд прозрения, один из обрядов Матери-Земли, поможет тебе завоевать уважение старейшин Громового Утеса.\n\nНаш народ твердо усвоил, что кормящая нас земля – священна. Чтобы принять участие в этом ритуальном прозрении, поговори с духовным вождем деревни, Зарельманом Две Луны.", progress = nil, completion = "Я предчувствовал, что ты придешь ко мне, |3-6(Друид). Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли.", rewards = "Вы получите:\n\n"},
[768] = {title = "Добывание шкур", objective = "Принесите 12 кусков тонкой кожи Верену Долгоногу в Громовой Утес.", description = "Привет тебе, <юноша/девица>. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться. Да принесешь ты честь своему клану!\n\nЯ работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утеса.\n\nЕсли принесешь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью.", progress = "Добро пожаловать еще раз! Поохотился? У тебя есть для меня кожа?", completion = "Ах, какая кожа! Из нее выйдут отличные товары.\n\nВот, Ахахаха. Возьми в знак благодарности...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПояс из звериной шкурыДвухслойные перчатки\n\nВы также получите:\n\n"},
[769] = {title = "Сумка из шкуры кодо", objective = "Принесите 4 куска легкой кожи и 4 мотка грубой нити Верену Высокому Страннику в Громовой Утес.", description = "Эти кодо из Мулгора – твари крепкие и упрямые, а мы такие качества уважаем. Если ты дока в кожевничестве и хочешь научиться делать сумки из шкуры кодо, то принеси мне необходимые для моего дела припасы.\n\nИ тогда я поделюсь с тобой своими знаниями.", progress = "Принес мои припасы, Серошкур?", completion = "Добро. Спасибо, Серошкур. Мое сердце распирает от гордости, когда я вижу молодежь, взыскующую мастерства в кожевничестве!", rewards = "Вы получите:\n\nВыкройка: сумка из шкуры кодо"},
[770] = {title = "Поцарапанный демоном плащ", objective = "Отыщите кого-нибудь, кто слышал о Призрачном Вое.\n\nПрилагается предмет: \n", description = "На потрепанной шкуре Призрачного Воя по-прежнему виден след от ужасной раны, полученной во время сражений волка с Пылающим Легионом.\n\nМожет быть, следует рассказать кому-нибудь в Деревне Кровавого Копыта о кончине Призрачного Воя...", progress = nil, completion = "Глазам своим стариковским не верю! Тебе удалось одолеть Призрачного Воя? Ты вырос в моих глазах, юный |3-6(Друид). Оказывается, ты превосходный охотник!\n\nПозволь предложить тебе кое-что. Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь мое оружие.\n\nПусть оно не знает промаха и дарует тебе славу.\n\nБудем надеяться, что дух Призрачного Воя упокоился с миром.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМолот СкорнаВинтовка Скорна\n\nВы также получите:\n\n"},
[771] = {title = "Обряд прозрения", objective = "Принесите 2 камня у источника и 2 янтарных семени Зарельману Две Луны в Деревню Кровавого Копыта.", description = "Чтобы пройти обряд Прозрения, тебе придется собрать некоторые реагенты для создания воды Провидцев.\n\nМне понадобятся камни, которых полно вокруг источников Мулгора. Я смешаю их с янтарным семенем, что роняют могучие деревья нашей земли.\n\nВ этих реагентах содержится магия, и если сварить их и выпить отвар перед костром племени, тебе явится видение. Следуй за ним, и оно приведет тебя к следующему этапу священного обряда.", progress = "Когда ты принесешь мне довольно камней и янтарного семени, я сделаю для тебя воду Провидцев.", completion = "Вижу, ты научился собирать дань с нашей священной земли. Мне понадобится совсем немного времени, чтобы приготовить воду Провидцев.", rewards = "Вы получите:\n\n"},
[772] = {title = "Обряд прозрения", objective = "Выпейте воду Провидцев перед костром племени в Деревне Кровавого Копыта и следуйте за видением.\n\nПрилагается предмет: \n", description = "Я вручаю тебе воду Провидцев.\n\nВыпей ее перед костром племени. Когда священные воды вольются в тебя, из огня навстречу тебе шагнет видение.\n\nПосле этого следуй за ним навстречу своей судьбе...", progress = nil, completion = "Не бойся, |3-6(Друид). Ты успешно прошел Обряд прозрения.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги ДождеходаВыцветший плащ\n\nСледующее заклинание будет наложено на вас:\n\nЗнак дикой природы\n\nВы также получите:\n\n"},
[773] = {title = "Обряд мудрости", objective = "Отправляйтесь в Красные Скалы на востоке от Громового Утеса и поговорите с духом предков.", description = "Чтобы завоевать признание старейшин Громового Утеса, тебе следует пройти Обряд мудрости.\n\nТы уже <прошел/прошла> Обряд прозрения, и духи Красных скал благословят тебя силой предков. Лишь те, кто испили воды Провидцев, могут обрести это благословение.\n\nСтупай на восток от Громового Утеса, к Красным скалам, и отыщи там дух предков.", progress = nil, completion = "Ты приложил много стараний, чтобы пройти обряды Матери-Земли, Коровкинг.\n\nМы, духи предков – память о могучих тауренах, отдавшие жизни за великий город Громовой Утес. Итак, я передаю тебе почетную обязанность хранить его от бед.\n\nТы прошел Обряд мудрости, юный |3-6(Воин). Отныне ты можешь с гордостью войти в Громовой Утес.", rewards = "Вы получите:\n\n"},
[775] = {title = "Путешествие в Громовой Утес", objective = "Поговорите с Кэрном Кровавым Копытом в Громовом Утесе.", description = "Отныне тебя будут почитать в стенах нашего великого города. <Прошедший/Прошедшая> обряды Матери-Земли заслуживает такой чести.\n\nВыполни последнее задание, отыщи благородного вождя Кэрна Кровавого Копыта, живущего на вершине высочайшего плато в Громовом Утесе.", progress = nil, completion = "Привет тебе, юный |3-6(Друид). Вижу, тебе удалось отыскать дорогу ко мне.", rewards = "Вы получите:\n\n"},
[776] = {title = "Обряды Матери-Земли", objective = "Кэрн Кровавый Рог из Громового Утеса попросил принести ему рог Арра'чеи.", description = "Ты <прошел/прошла> обряды Матери-Земли и <заслужил/заслужила> достойное место среди жителей Громового Утеса.\n\nЧтобы сохранить это таким трудом заработанное место, тебе придется и дальше служить своему народу.\n\nМы охотники, <имя>. Внизу, в Мулгоре, есть могучий кодо по имени Арра'чея. Выследи и убей его, проявив свое искусство охотника, и принеси мне рог Арра'чеи.", progress = "Ты уже выследил Арра'чею?", completion = "Отлично! Добрая охота.\n\nЯ пошлю отряд за тушей кодо, чтобы забрать шкуру и мясо.\n\nТы оказал своему народу услугу.", rewards = "Вы получите:\n\nПоножи охотника на кодо"},
[777] = {title = "Сложная задача", objective = "Принесите зубец #5 Лотвилу Вериатусу.", description = "Ну, теперь за дело! \n\nЯ буду здесь...в укрытии. \n\nЕсли хочешь, можешь присоединиться.", progress = "*Не отрывая взгляд от кандалов, Лотвил нетерпеливо протягивает руку.* \n\nНу? Давай сюда зубец!", completion = "Ага, прекрасно! Отойди-ка в сторонку и наблюдай, как вершится история! *Лотвил вновь погружается в работу.*", rewards = nil},
[778] = {title = "Сложная задача", objective = "Победите Стража Фам'ретора и верните оковы Стихий Лотвила Лотвилу Вериатусу.", description = "Ха! Сделано! \n\nЛюсьен, Серво, время пришло! \n\nТы <готов/готова> стать <свидетелем/свидетельницей> запуска в эксплуатацию совершенной смеси алхимии, инженерной науки и древних тайн, <имя>? \n\nСейчас я призову могущественного элементаля. Это величайший день для всех нас!", progress = "Да... Не совсем тот результат, на который я рассчитывал... Не вернешь ли ты теперь мне оковы?", completion = "Спасибо, Томпсон! Ну и денек! \n\nНе думал я, что так получится. Хорошо, что с помощью магии мне удалось загнать тварь туда, откуда она появилась...\n\nВот, это миллионная доля моей благодарности...", rewards = "Вы получите:\n\nИзящный секундомер"},
[779] = {title = "Печать Земли", objective = "Перед вами печать Земли.В ней вы видите три потайные ниши для аметистового, опалового и алмазного рунных камней.", description = nil, progress = "Перед вами печать Земли.В ней вы видите три потайные ниши для аметистового, опалового и алмазного рунных камней.", completion = "Как только рунные камни оказались в предназначенных для них нишах, земля задрожала и печать разрушилась.", rewards = nil},
[780] = {title = "Боевые вепри", objective = "Принесите 8 боков и 8 рыл боевых вепрей Груллу Соколиному Ветру.", description = "Боевые вепри из Ежевичной лощины, что к востоку отсюда, вторгаются в охотничьи угодья нашего племени. Их натаскивают свинобразы из племени Дыбогривов, наши заклятые враги. \n\nПойди и покажи гнусным тварям, кто хозяин в этих землях! Мы сварим из их боков и рыл славную похлебку для наших детишек!", progress = "То, что боевые вепри творят в наших землях, уже переходит всякие границы. Сумел ли ты приструнить этих зверей? А бока и рыла принес?", completion = "Прекрасно! Мы сварим отличную похлебку, а для проклятых дыбогривов потеря нескольких боевых вепрей послужит уроком.", rewards = "Вы получите:\n\nЖилет кочевникаЧерствая краюха хлеба"},
[781] = {title = "Нападение на Лагерь Нараче", objective = "Отнесите план нападения племени Дыбогривов вождю Соколиному Ветру в Лагерь Нараче.", description = "Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения клана Дыбогривов на Лагерь Нараче. \n\nВождь Соколиный Ветер непременно должен об этом узнать!", progress = "You have a look of concern about you, <имя>. What news do you bring?", completion = "This is quite alarming indeed! But with this information we can call on our brethren from Bloodhoof Village to help thwart the attack. You have saved the lives of many &lt;раса&gt;, &lt;имя&gt;.", rewards = "Вы получите:\n\nУтолщенный лубяной кулачный щит"},
[782] = {title = "Разорванные союзы", objective = "Убейте главаря То'груна и принесите знак Земли Горну в Каргат.", description = "От союзника Орды времен Второй войны, дракона Смертокрыла мы знаем, что два его лейтенанта, Чернохлыст и Гематус, были заточены в долине Летлор. Чтобы отстоять честь Орды и не допустить предательства, мы должны заставить замолчать наших растленных бывших союзников! \n\nМы наняли Тогруна и его шайку огров-наемников, чтобы они помогли нам получить знак Земли – ключ, необходимый, чтобы открыть драконье узилище. Но Тогрун предал нас, забрав знак себе. Отправляйся в лагерь Бофф и отбери знак!", progress = "Предательство То'груна... Неудивительно, что огры больше не в Орде. Более всего на свете я желаю их смерти и возвращения знака Земли! \n\nЕсли ты еще не расправился с их шайкой, поспеши в лагерь Бофф. Он расположен к юго-востоку от Каргата.", completion = "Теперь, когда от То'груна остался лишь голый скелет, обглоданный стервятниками и выбеленный солнцем и ветром, огры, лишенные главаря, рассеются по пустыне. Так малая победа принесла с собой великую! \n\nЗнак Земли снова у нас, и мы сможем отомкнуть узилище черных драконов в долине Летлор. Мы спасем их от уготованного им вечного заключения, хотя и свершим их судьбу!", rewards = "Вы получите:\n\n"},
[783] = {title = "Внутренняя угроза", objective = "Поговорите с маршалом Макбрайдом.", description = "Надеюсь, ты <готов/готова> к подвигам, <класс>, поскольку для тебя есть дело здесь, в Североземье.\n\nИ я имею в виду не мирные сельские заботы.\n\nСтража Штормграда с трудом поддерживает здесь мир: слишком многие из нас находятся в дальних краях, а тревожных вестей меньше не становится. И потому мы надеемся на помощь всех, кто готов защитить свой дом и своих близких.\n\nЕсли ты <готов/готова> откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом. Он здесь, в аббатстве у меня за спиной.", progress = nil, completion = "Отлично. Еще один доброволец. В эти дни у нас много таких, как ты.\n\nНадеюсь, нам хватит бойцов.\n\nЗемлям людей угрожают внешние враги, потому большая часть наших сил направлена к рубежам. И из-за этого бандитские шайки вольготно чувствуют себя в наших землях.\n\nНам приходится воевать на много фронтов... Готовьтся к долгой войне, Бронгард.", rewards = "Вы получите:\n\n"},
[784] = {title = "Бей предателей!", objective = "Убейте 10 моряков Кул-Тираса, 8 стражей бухты Кул-Тираса и лейтенанта Бенедикта и возвращайтесь к Га'Току на Колючий Холм.", description = "Люди из Кул-Тираса, ведомые адмиралом Праудмуром, вторглись в Дуротар, нарушив договор, который вождь заключил с Джайной Праудмур несколько лет назад, чтобы одолеть Архимонда.\n\nВторжение людей удалось отбить, крепость Тирагард пала. Но не так давно подкрепление под командой лейтенанта Бенедикта вновь захватило эту крепость. Нашей родине снова грозит опасность! Эти люди совершенно не чтут договоров!\n\nПокажи свою доблесть, <имя>. Отправляйся на юг, в крепость Тирагард, и уничтожь непрошеных гостей.", progress = "Ты слышал приказ, Зелтрес. Речь идет о безопасности Дуротара! Выполняй свою задачу – либо уходи с позором.\n\nПокажи свою доблесть, выбей людей из крепости Тирагард!", completion = "Твоя отвага скоро станет известна всем, |3-6(Воин)! Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара.", rewards = "Вы получите:\n\n"},
[785] = {title = "Стратегический союз", objective = "Разыщите Лара Ночного Клыка на западной окраине деревни Сен'джин.Тралл – весьма мудрый и благородный лидер. Его навыки дипломата могут сравниться лишь с его отвагой на поле брани.\n\nТролли Черного Копья оказались бесценными союзниками для всего орочьего рода. И мы, из верности и чести, заключили с ними договор о взаимной обороне.\n\nИ вот вождь приказал удостовериться, что нашим друзьям в деревне Сен'джин ничто не угрожает. Один из их самых опытных разведчиков, Лар Ночной Клык, охраняет их западные пределы.\n\nРазыщи Лара и спроси, не нужна ли ему помощь.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Тралл – весьма мудрый и благородный лидер. Его навыки дипломата могут сравниться лишь с его отвагой на поле брани.\n\nТролли Черного Копья оказались бесценными союзниками для всего орочьего рода. И мы, из верности и чести, заключили с ними договор о взаимной обороне.\n\nИ вот вождь приказал удостовериться, что нашим друзьям в деревне Сен'джин ничто не угрожает. Один из их самых опытных разведчиков, Лар Ночной Клык, охраняет их западные пределы.\n\nРазыщи Лара и спроси, не нужна ли ему помощь.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[786] = {title = "Предотвращение агрессии племени Колкар", objective = "Лар Ночной Клык из деревни Сен'джин хочет, чтобы вы уничтожили 3 плана нападения, которые хранятся в лагере кентавров, что в Утесе Колкара.", description = "Говори потише, <класс>! Кентавры из племени Колкар совсем близко, вон там, к западу от Утеса Колкара.\n\nПрошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара!\n\nНельзя допустить, чтобы они это сделали! Достаточно ли ты <храбр/храбра>, чтобы напасть на Утес Колкара и уничтожить их планы?\n\nЯ заметил, что они хранятся у трех лидеров кентавров.", progress = "Кентавры постоянно изводят Орду своими набегами. Они намерены взять нашу родину в осаду! Этого нельзя допустить!", completion = "Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть. Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь.\n\nА кровопролитий в эти смутные времена и без того хватает.\n\nТы хорошо послужил своему народу, |3-6(Воин).", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлащ опытного бойцаТяжелые шнуровые наручи\n\nВы также получите:\n\n"},
[787] = {title = "Новая Орда", objective = "Зайти в Логово к Горнеку.Тром'ка, <класс>! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов.\n\nОрда уже не такая, как раньше. Некогда я оставил ее: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти. Во время изгнания я попал в плен к людям, но вождь меня спас. Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся.\n\nГорнек скажет тебе, что делать дальше.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Тром'ка, <класс>! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов.\n\nОрда уже не такая, как раньше. Некогда я оставил ее: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти. Во время изгнания я попал в плен к людям, но вождь меня спас. Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся.\n\nГорнек скажет тебе, что делать дальше.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[788] = {title = "Кабаньи клыки", objective = "Убейте 10 пятнистых вепрей и вернитесь в Логово к Горнеку.", description = "Вот тебе первое поручение, чтобы ты <набрался/набралась> опыта и <показал/показала> себя. Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему.\n\nПожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда.", progress = "Не рано ли ты вернулся, а, Мову? Надеюсь, ты не будешь уверять, будто выполнил все, что тебе было поручено?", completion = "Ну что ж, Троллец, неплохо. Но не задирай носа: грядут бои с куда более серьезными врагами.\n\nОднако ты показал себя достойным бойцом. В следующем испытании тебе придется встретиться с более опасным противником, так что дополнительная защита не помешает.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМягкие шерстяные сапогиИссеченные кожаные перчатки\n\nВы также получите:\n\n"},
[789] = {title = "Жала скорпидов", objective = "Добудьте 10 хвостов рабочих скорпидов и принесите их в Логово Горнеку.", description = "Ядовитое жало скорпиона губит всех – и могучих воинов, и неопытных новичков. К северо-западу отсюда водится множество этих членистоногих. Принеси мне десять их хвостов, чтобы доказать свою воинскую доблесть.\n\nИз яда жал скорпионов можно изготовить противоядие. Мы всегда держим его под рукой, специально для неосторожных юнцов вроде тебя...\n\nНо тебе-то оно не понадобится, а?", progress = "У скорпиона панцирь прочный, но не настолько, чтобы сильный воин не сумел его пробить. Пусть рука твоя будет тверда, и душа не знает сомнений – тогда скорпионы окажутся легкой добычей!", completion = "Запомни раз и навсегда: любой противник, будь он мал или велик, может оказаться для тебя последним! В бою победа или поражение зависят от многого.\n\nНу что ж, Ахахаха! Я научил тебя всему, чему мог. Ты оказался хорошим учеником. Я буду с интересом следить за твоей карьерой.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМягкий шерстяной поясИссеченная в бою накидка\n\nВы также получите:\n\n"},
[790] = {title = "Саркот", objective = "Убейте Саркота и принесите его коготь Хана'зуа.", description = "<класс>! А я уж думаю, помру тут, никто и не узнает... Я охотился в долине на скорпидов, и попался мне один, особенно злобный. Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу.\n\nА вот жало застигло меня врасплох. Оно вонзилось мне в грудь, хлынула кровь... Прошу тебя, смой с меня позор! Убей этого скорпида! Я сражался с ним на плато, к югу отсюда...", progress = "Ох... Отец мой говаривал, что толку из меня не выйдет, и вот лежу я под деревом, помираю и думаю: прав был папаня…\n\nНо я хочу умереть, зная, что последний из моих врагов тоже мертв!", completion = "Да, убить его мне не удалось, но ранил я его серьезно. Пожалуй, мне есть чем гордиться. И это единственное, что утешает меня перед смертью. Как подумаю, как мало я сделал в жизни, такая злость берет!", rewards = "Вы получите:\n\n"},
[791] = {title = "Больше сумок – больше добычи!", objective = "Принесите 8 лоскутов холста Фурлу Хмурому Лбу, стоящему на сторожевой башне рядом с Колючим Холмом.", description = "Старость сделала меня бесполезным в бою. Теперь я служу Орде иным путем.\n\nЯ сижу здесь, на вышине, и смотрю, не появятся ли враги. Но по мере того, как наши силы растут, мне все реже и реже приходится трубить в сигнальный рог.\n\nА чтобы проводить время с пользой, я изготовляю разные вещи для молодых сильных воинов, которые защищают теперь нашу родину.\n\nЯ могу сделать тебе сумку для пожитков. Если такая вещь будет для тебя полезна, принеси мне отрез холста – эта ткань в ходу у людей и кентавров.", progress = "Когда мы заселяли эти земли, я гордо сражался плечом к плечу с вождем. Все мое тело покрыто шрамами.\n\nЯ отстаивал честь Орды своим боевым топором в день победы над Архимондом, когда по необходимости был заключен нечестивый союз с людьми и эльфами.\n\nНо моя должность стража открыла мне новый взгляд на вещи.", completion = "Отлично, Демонорох! Такая сумка пригодится любому хорошему бойцу.\n\nЯ отдаю честь твоей силе и решимости умереть во имя Орды!", rewards = "Вы получите:\n\nКожаная сумка ручной работы"},
[792] = {title = "Злобные фамильяры", objective = "Убейте 12 злобных фамильяров и вернитесь к Зурите Востроглазой, которая ждет вас у Логова.", description = "Что ж, <класс>, надеюсь, у нас ты многому научишься.\n\nМеня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не все ладно!\n\nВ долине Испытаний обосновался клан Пылающего Клинка. Эти твари скрываются в пещере на северо-востоке, и их злобные фамильяры выбираются оттуда и сеют хаос.\n\nИтак, вот твое первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне.", progress = nil, completion = "Спасибо тебе, Ахахаха!\n\nДа, злобные фамильяры для воинов клана Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предсказывает тебе великие дела!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПростая дубинаПростой клинокПростая секираПростая трость\n\nВы также получите:\n\n"},
[793] = {title = "Разорванные союзы", objective = "С помощью знака Земли активируйте алмазный, опаловый и аметистовый столпы и извлеките рунные камни. \n\nПоместите рунные камни на печать Земли и освободите драконов Бича Тьмы и Гематуса. \n\nУбейте драконов и принесите Горну наручники Чернохлыста, цепи Гематуса и Знак Земли.", description = "Печать Земли удерживают три рунных камня, сокрытые в долине Летлор. Один спрятан в алмазном столпе, другой – в опаловом, третий – в аметистовом. С помощью знака Земли ты сможешь извлечь рунные камни и разрушить печать Земли. \n\nНо будь <осторожен/осторожна>, <имя>, Чернохлыст и Гематус очень опасны. Ты <должен/должна> убить их и принести мне их наручники. \n\nДолина расположена к востоку от Бесплодных земель. Не теряй бдительности – в низине множество драконов!", progress = "Немногие создания сравнятся по мощи и хитрости с драконами, и немногие драконы сравнятся по свирепости с Чернохлыстом и Гематусом.", completion = "Черные драконы вступают в союз с отступниками – орками Черной Горы. И тех, и других должно вернуть в лоно Орды или уничтожить. Теперь, когда мы покончили с Гематусом и Чернохлыстом, мы можем обратить взор на запад, на пик Черной Горы.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКираса Порыва ветраХауберк с призматической чешуейЗакаленная в битве бригантинаМедальон Пламени Разума\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[794] = {title = "Медальон Пылающего Клинка", objective = "Принесите медальон Пылающего Клинка Зурите Востроглазой, стоящей у Логова.", description = "С помощью ворожбы я узнала, что в глубине грота Пылающего Клинка находится мощный магический предмет. Его стерегут звери и черная магия.\n\nЭтот предмет – медальон Пылающего Клинка. Твоя очередная задача – найти его и отнять у ковена.\n\nНо берегись: медальон может оказаться в руках одного из членов ковена, и этот чернокнижник будет куда могущественнее, чем фамильяры, с которыми тебе уже доводилось встречаться!\n\nСтупай, <имя>. Грот находится к северо-западу отсюда.", progress = "Ну что, Ммрргглл, задание выполнено? Удалось ли тебе раздобыть медальон Пылающего Клинка?", completion = "Он у тебя! Молодец!\n\nТеперь у нас есть возможность вытеснить приспешников Пылающего Клинка из долины Испытаний. Но, боюсь, этот грот – не единственный их оплот в наших землях.\n\nТак что эта встреча с ними была не последней.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗапыленные поножиПлетеный нагрудник с заусенцамиДраные штаны\n\nВы также получите:\n\nСлабое лечебное зелье"},
[795] = {title = "Печать Земли", objective = "Перед вами печать Земли. В ней вы видите три потайные ниши для аметистового, опалового и алмазного рунных камней.", description = nil, progress = "Перед вами печать Земли. В ней вы видите три потайные ниши для аметистового, опалового и алмазного рунных камней.", completion = "Как только рунные камни оказались в предназначенных для них нишах, земля задрожала и печать разрушилась.", rewards = nil},
[804] = {title = "Саркот", objective = "Расскажите Горнеку о том, что Хана'зуа в беде.", description = "То, что ты <сделал/сделала> ради меня, заставило меня воспрянуть духом. Я еще повоюю!\n\nНо пока что мне не добраться до Логова без посторонней помощи. Прошу тебя, <имя>, сходи в Логово, расскажи Горнеку, что я здесь. Может, он сумеет мне помочь.", progress = nil, completion = "Судя по твоему описанию, этим скорпионом был не кто иной, как Саркот! Неудивительно, что Хана'зуа с ним не справился. Не тревожься о нем, помощь уже в пути.\n\nОднако, нужно сказать, я тебя зауважал. Неужели тебе действительно удалось одолеть Саркота? Это немалый подвиг, Троллец, тебе есть чем гордиться. А твоя готовность сражаться по просьбе незнакомца тем более делает тебе честь.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМягкий шерстяной жилетИзношенные плетеные поножи\n\nВы также получите:\n\n"},
[805] = {title = "Деревня Сен'джин", objective = "Поговорите с мастером Гадрином в деревне Сен'джин.", description = "Твои испытания в борьбе с Пылающим Клинком подошли к концу... по крайней мере тут, в нашей Долине. Но я прошу тебя отнести известие о том, что ты теперь знаешь.\n\nСтупай в тролльскую деревню Сен'джин, отыщи там мастера Гадрина. Отправляйся на восток, на развилке поверни направо.\n\nРасскажи Гадрину о чернокнижниках из клана Пылающего Клинка и о том, что они уже проникли в долину Испытаний. Узнай, не видно ли их в Сен'джине.\n\nСтупай, <имя>, и не медли в пути! Боюсь, появление Пылающего Клинка в долине – это только первая ласточка...", progress = nil, completion = "Хм... Как это все не вовремя! Нет, у нас в Сен'джине Пылающего Клинка пока не видно, однако на побережье, на островах Эхо, обосновалось иное зло.\n\nОрки – друзья племени Черного Копья. Верные друзья. Мы хотели бы помочь оркам, но... сейчас нам самим нужна помощь!", rewards = "Вы получите:\n\n"},
[806] = {title = "Сгущаются черные тучи", objective = "Принесите коготь Пшикса Оргнилу Душегрызу из Колючего Холма.", description = "Нельзя допустить, чтобы Пылающий Клинок закрепился в Дуротаре! Нужно уничтожить этих чернокнижников, прежде чем распространяемое ими зло расползется по нашей земле!\n\nЯ провел расследование и выяснил, что один из чернокнижников из клана Пылающего Клинка, гоблин по имени Пшикс Черношквал, обосновался на Громовом хребте к северо-западу отсюда. Там он и его приспешники сеют хаос!\n\nНайди Пшикса, убей его и принеси мне его коготь в в качестве доказательства.", progress = "Ну что, Гронгард, удалось тебе найти Пшикса? Он и ему подобные должны быть изгнаны из наших земель!", completion = "Ага! Ты его убил!\n\nТвой клан может гордиться тобой, Гронгард. Благодаря тебе в Дуротаре стало одним приспешником зла меньше.", rewards = "Вы получите:\n\nСапоги из тигриной шкуры"},
[808] = {title = "Череп Миншины", objective = "Украдите череп Миншины из магического круга на островах Эха.\n\nПринесите его мастеру Гадрину в деревне Сен'джин.", description = "Я слышу голос моего брата, Миншины. Он взывает ко мне из снов.\n\nЕго захватил в плен Залазан, чернокнижник с островов Эха на востоке. И теперь Миншина мертв.\n\nНо смерть не принесла ему свободы! Залазан заточил дух Миншины внутри его собственного черепа. В снах я вижу его рядом с другими черепами, в магическом кругу на самом большом из островов Эха. Пока его душа находится в этом месте, она обречена не вечные страдания.\n\nПрошу тебя, <имя>, отыщи этот круг и похить череп Миншины. Принеси его мне.\n\nОсвободи его!", progress = "Ну что, Ахахаха, череп моего брата у тебя? Он наконец свободен?", completion = "Спасибо, Ахахаха! Тебе удалось спасти Миншину! Дух моего брата избавлен от рабства!", rewards = "Вы получите:\n\nТускло блестящий череп"},
[809] = {title = "Ак'Зелот", objective = "Поговорите с Ак'Зелотом в Степях.", description = "Со времен последней великой войны, когда Пылающий Легион потерпел поражение,  я ищу источники демонической порчи, что воздействует на общество орков. И принесенный тобой ошейник подтверждает мои опасения!\n\nОн принадлежит Пылающему Клинку, культу, объединенному вокруг предмета, который наделен демонической силой. Этот предмет называется Демоново Семя, и находится он в Степях, на вершине Багрового Тумана. Его необходимо уничтожить!\n\nОтправляйся на Дальнюю заставу на границе Степей, к западу, и поговори с моим помощником, Ак'Зелотом. Он скажет тебе, что делать дальше.", progress = nil, completion = "Вот как? Нииру хочет, чтобы Демоново семя было уничтожено? Странно…\n\nЧто ж, хорошо. Если такова его воля, я расскажу тебе, как уничтожить семя.", rewards = "Вы получите:\n\n"},
[812] = {title = "Нужда в исцелении", objective = "Найдите в Оргриммаре Кор'гхана и добудьте сыворотку от яда ядохвоста. Принесите сыворотку Ринагу на северо-западной границе Даротара.", description = "А, <имя>... Ты как нельзя вовремя! Надеюсь на твое проворство.\n\nЯ сражался с несколькими ядохвостами, и один из них смог меня ужалить. Я чувствую, как слабею с каждой секундой... Боюсь, мне осталось не больше часа. Мне срочно нужна твоя помощь!\n\nКоргхан из Оргриммара умеет изготовлять противоядие. Найди его... Быстрее, <имя>! Долго мне не протянуть. Ищи его в расселине Теней.", progress = "Я даже рад, что не могу сейчас вернуться в Сен'джин. Все смеялись бы над моей слабостью и глупостью!", completion = "Ты спас мне жизнь, Бифачу! Спасибо тебе. \n\nПрошу тебя, возьми эту вещь. Денег за нее не выручишь, но, надеюсь, она пригодится тебе в странствиях. Судя по тому, что ты говоришь, мне она пригодится нескоро. Кор'гхан подвергнет меня еще множеству своих ритуалов, пока я не сумею показать, на что способен. Снова охотиться на вепрей, собирать хвосты скорпидов... *вздыхает*", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШтурмовой кулачный щитЛегкий доспех Скорпида\n\nВы также получите:\n\n"},
[813] = {title = "Поиски противоядия", objective = "Принесите 4 ядовитых железы ядохвоста Кор'гхану в Оргриммаре.", description = "Ядохвосты – одни из опаснейших скорпидов в Дуротаре! Со стороны Ринага было очень глупо охотиться на них, не имея при себе противоядия. Впрочем, сейчас его вразумлять уже поздно.\n\nПринеси мне несколько ядовитых желез ядохвоста от любых ядохвостов, каких найдешь у входа в Оргриммар, и я сделаю ему противоядие.\n\nТоропись, <имя>! Одному из наших нужна твоя помощь!", progress = "Не забывай, если ты на какую-то тварь охотишься, первым делом надо как следует изучить ее повадки! Это может спасти тебе жизнь.", completion = "Вот противоядие, Мну. Отнеси его поскорее Ринагу, да смотри, осторожнее!", rewards = "Вы получите:\n\nСыворотка от яда ядохвоста"},
[815] = {title = "Хорошенький омлет", objective = "Принесите 3 яйца кнутохвостов повару Торке в Колючий Холм.", description = "Ба! А я и позабыл, что надо готовить завтрак.\n\nСлушай, <имя>, сбегай-ка, раздобудь мне по-быстрому несколько яиц кнутохвостов, как минимум три штуки.\n\nИмей в виду, кровопалые кнутохвосты – твари свирепые и вполне могут убить, защищая свою кладку. Иногда они зарывают яйца слишком глубоко, чтобы их можно было беспрепятственно раздобыть, но если ты отправишься на острова Эха, к юго-востоку от деревни Сен'джин, там эти яйца лежат повсюду.", progress = "Завтрак, обед, ужин! Какая, в сущности, разница? Все равно кто-то должен готовить еду, и этот кто-то – я!", completion = "Ну, может, ты и слабак но уж ловкости и проворства тебе не занимать, Демонорох!\n\nНа вот, возьми за труды и проваливай. Мне готовить надо!", rewards = "Вы получите:\n\nЧерствая краюха хлебаЖесткая солонина"},
[816] = {title = "Пропавший, но не забытый", objective = "Принесите известие о судьбе, постигшей Крона, Майше Тор'крен в усадьбу к северо-западу от Колючего Холма.", description = "Прошу тебя, <имя>, может, хоть ты сумеешь мне помочь? Мой сын, Крон, несколько дней тому назад отправился на охоту и до сих пор не вернулся! Он ушел на запад, в Степи, охотиться на кроколисков у реки Строптивой. Я опасаюсь худшего…\n\nКрон могуч, но гордость и упрямство всегда доводили его до беды. Я попросила его не охотиться на кроколисков, потому что они злобны и коварны! А он рассвирепел и хлопнул дверью.\n\nЕсли не сумеешь отыскать его – узнай хотя бы, что с ним случилось... даже если тебе придется заглянуть в брюхо каждому кроколиску на берегах Строптивой!", progress = "Я молюсь, чтобы Крон вернулся ко мне, но, боюсь, я уже знаю, что с ним случилось…", completion = "Ох, сыночек... милый мой сыночек…\n\nЧто ж, я не знала судьбы своего сына и потому терзалась понапрасну. Теперь же я хоть смогу его оплакать…\n\nСпасибо тебе, Ахахаха. Прошу тебя, возьми этот плащ. Я-то собиралась подарить его Крону, когда он вернется с добычей... А теперь, зная, что он погиб, я даже не смогу смотреть на него.", rewards = "Вы получите:\n\nСшитый вручную плащ"},
[817] = {title = "Полезная добыча", objective = "Принесите 4 шкуры дуротарских тигров Вель'рину Клыку в деревне Сен'джин.", description = "<имя>, у нас в большом ходу шкуры дуротарского тигра. Чего только из них не делают! И одеяла, и доспехи, и шатры. Вот почему мы охотимся на этих животных, но не истребляем их.\n\nВ общем, пришла пора в очередной раз сократить поголовье. Наши потребности растут, и запасов не хватает. Мне нужны новые шкуры.\n\nПринеси мне 4 шкуры дуротарских тигров, и получишь награду. Эти кошки водятся на островах к югу отсюда.", progress = "Как сейчас помню свою первую охоту на тигров! Я решил поохотиться на самом большом из островов Эхо. Я затаился в тени и ждал почти целый день.\n\nМои мускулы были напряжены, и я был готов выстрелить в любую секунду! Как же я торжествовал, когда мой первый тигр был повержен!", completion = "Молодец, Гронгард! Благодаря твоей помощи наш народ не останется без доспехов и не будет страдать от холода, когда наступит зима. \n\nСпасибо тебе.", rewards = "Вы получите:\n\n"},
[818] = {title = "Растворитель", objective = "Принесите 4 невредимых глаза макрур и 8 фиалов со слизью крабов мастеру Ворналу в деревне Сен'джин.", description = "Да, глаза меня порой подводят, но все же пока я вижу достаточно отчетливо. И все чаще приходится прибегать к помощи алхимии, чтобы творить заклинания, которые прежде давались мне без труда. И я не беру учеников. Нет нынче достойных ни среди троллей, ни среди орков.\n\nЧто? Ты <достоин/достойна>? Ну да, конечно... Это ты так думаешь.\n\nМне нужны кое-какие компоненты. Сумеешь ли ты их добыть?\n\nМне нужны невредимые глаза макрур и слизь крабов, которые водятся к югу отсюда. Вот принеси мне их, потом поговорим.", progress = "Вот-вот, сила и воля по-настоящему проявляются только со временем. Потеряешь терпение, дашь слабину – тут-то и вылезет твоя подлинная натура!", completion = "Отличная работа, Ахахаха! Ты молодец!", rewards = "Вы получите:\n\nСуперклей"},
[819] = {title = "Пустой бочонок Чэня", objective = "Отыщите кого-нибудь, кто знает о пустом бочонке Чэня.", description = "Маленькая табличка на торце одной из бочек гласит:\n\n\"Чэнь Буйный Портер – \n\nДа будет ваш дух горяч, а кружка – полной.\"", progress = "Да?", completion = "Ну, я…\n\nЭто был один из бочонков Чэня Буйного Портера. Давным-давно он путешествовал вместе с Рексаром. Я не видел его и не слышал о нем с незапамятных времен. Спасибо, что ты принес мне этот бочонок, Демонорох.", rewards = "Вы получите:\n\n"},
[821] = {title = "Пустой бочонок Чэня", objective = "Принесите 5 клыков равнинного льва, 5 почек долгонога и 1 рог рокочущей ящерицы пивовару Дрону в Кабестан.", description = "Хочешь попробовать напиток, придуманный Чэнем? Ах, до чего же хорош! Чэнь передал рецепт моему наставнику, ну а он – мне. Только для него понадобится несколько компонентов. Но он того стоит!\n\nПринеси мне 5 клыков равнинного льва, 5 почек долгонога и 1 рог рокочущей ящерицы. Из них выйдет прекрасный портер.\n\nВсе эти составляющие нетрудно отыскать в Степях.", progress = "Как идут поиски?", completion = "Ха-ха... Вот уж не думал, что снова сварю этот напиток!\n\nПрямо ностальгия охватила. Сразу вспомнилось, как я наварил троггского пойла. Спасибо, Ахахаха. От воспоминаний даже на душе посветлело.", rewards = "Вы получите:\n\nБуйный эль"},
[822] = {title = "Пустой бочонок Чэня", objective = "Принесите 5 грозовых желез, 1 слюнную железу грозового змея и 1 печень кодо пивовару Дрону в Кабестан.", description = "Отличный напиток, а? \n\nЯ научился у Чэня еще одному рецепту. Хочешь узнать? Много времени он не отнимает, а в жизни пригодится. \n\nПринеси мне 5 грозовых желез любых грозошкуров, 1 слюнную железу грозового змея от больших грозовых змеев и печень кодо от любого из кодо Степей.\n\nВставляет – не то слово. Это эль трогга, о котором я уже говорил.", progress = "Ну как, трудишься, ищешь все составляющие, Демонорох?", completion = "Ха-ха! Я знал, что ты не откажешься от этого напитка. Приходи, я еще тебе сварю. Главное – приноси все необходимое.", rewards = "Вы получите:\n\nТроггский эль"},
[823] = {title = "Явиться к Оргнилу", objective = "Поговорите с Оргнилом Душегрызом на Колючем Холме.", description = "У нас, в деревне Сен'джин, конечно, есть свои проблемы, и твоя помощь нам бы не помешала. Так что спасибо тебе. Однако принесенные тобой вести об Пылающем Клинке сулят неприятности всем.\n\nВ Колючем Холме есть один орк, Оргнил Душегрыз, в обязанности которого входит охранять Дуротар от таких напастей, как Пылающий Клинок. Ступай к Оргнилу и расскажи ему о нашем положении и о том, что ты <узнал/узнала> в долине Испытаний. Ему нужно это знать.\n\nКолючий Холм находится к северу отсюда.", progress = nil, completion = "Да? Тебе есть, о чем доложить? Ну так рассказывай, чего ты ждешь?!", rewards = "Вы получите:\n\n"},
[824] = {title = "Дже'неу из Служителей Земли", objective = "Отнесите оскверненную водяную сферу Дже'неу Санкри в форт Зорам'гар в Ясеневом лесу.", description = "Служители Земли – сообщество шаманов, посвятивших себя изучению и охране Стихий. Они забыли о безумных древних богах, древних легендах и преданиях больше, чем большинство ученых вообще знало.\n\nПовезло тебе, что я знаю кое-кого из Служителей Земли тут, в Ясеневом лесу. Иди в форт Зорам'гар на Зорамское взморье и покажи Дже'неу Санкри свою находку. Если кто и поймет, что это за шар, так это он.", progress = "А, привет. Я много времени трачу на изучение воды – вернее, всех Стихий – так много, что порой не замечаю никого вокруг.\n\nВ чем тебе помочь разобраться?", completion = "Этот шар... волнует он меня. Многие из наиболее могучих элементалей черпают силу и энергию при помощи таких устройств. Найти такую штуку неповрежденной – одно дело, а вот настолько оскверненной – совсем другое.\n\nЯ прослежу, чтобы этот шар как следует изучили Служители Земли. Возможно, мы сумеем положить конец такому осквернению стихий. Прошу – прими это в награду за то, что принес нам этот шар для изучения.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПояс ловкачикаЩит ползучих топейМягкая ивовая накидка\n\nВы также получите:\n\n"},
[825] = {title = "Обломки кораблекрушения", objective = "Га'Ток с Колючего Холма просит вас принести ему 3 комплекта инструментов гномов, найти которые можно в обломках кораблей у побережья.", description = "Один из моих лучших разведчиков принес сообщение, что обломки кораблей Праудмура все еще плавают около побережья Дуротара, к востоку от крепости Тирагард.\n\nНи для кого не секрет, что люди, будучи в союзе с этими маленькими уродцами, гномами, неплохо овладели механикой. Нам нужно знать все о нашем предполагаемом противнике! К тому же, эти знания пригодятся и нашему народу.\n\nСплавай к обломкам, <имя>, и добудь мне инструменты Альянса.", progress = "Когда мы узнаем, как люди управляют своей странной техникой, у нас будет куда больше шансов победить их в грядущих битвах.\n\nС новыми знаниями Орда станет сильнее!", completion = "Ты успешно выполнил поручение, |3-6(Воин). Я позабочусь о том, чтобы эти инструменты отправились в Оргриммар с ближайшим караваном.\n\nМолодец!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗагрязненные сапогиНакулачники Песчаного бегунаШирокий металлический ремень\n\nВы также получите:\n\n"},
[826] = {title = "Залазан", objective = "Убейте Залазана, убейте 8 троллей-вудуистов и 8 проклятых троллей.\n\nПринесите голову Залазана Гадрину.", description = "Знахарь Залазан живет на островах Эха на востоке. Эти острова мы когда-то называли родиной…\n\nА теперь он оттуда посылает троллей на материк, досаждая нашему народу и переманивая на свою сторону все новых приспешников.\n\nЕго нужно остановить!\n\nУничтожь Залазана и его слуг – бывших троллей из племени Черного Копья, ныне потерянных для нас! Принеси мне его голову – и я буду знать, что владычеству зла пришел конец.", progress = "Ну что, Гронгард, Залазан побежден?", completion = "Залазана больше нет, наше племя снова может спать спокойно!\n\nСпасибо, Гронгард. Племя Черного Копья многим тебе обязано. Если тебя мучает какой-нибудь недуг, обратись к моему помощнику, Бом'бею, который находится позади меня. Он силен в магии вуду…", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛегкие сапогиМаскировочные захваты\n\nВы также получите:\n\n"},
[827] = {title = "Скала Черепа", objective = "Отберите у фанатиков из Скалы Черепа обжигающие ошейники.\n\nПринесите их в лагерь Маргозу.", description = "<имя>! Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как скала Черепа. Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками.\n\nЯ подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами. Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников.\n\nСтупай к скале Черепа и отбери у фанатиков, которых там найдешь, их ошейники. Принеси их мне, и я раскрою их тайну!", progress = "Ну что, Гронгард, удалось тебе проникнуть в Скалу Черепа? Принес обжигающие ошейники?", completion = "Отлично! В этих ошейниках и таится секрет Пылающего Клинка. И я его раскрою!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗазубренный кинжалНеизменный полуторный мечЖалящая палица\n\nВы также получите:\n\n"},
[828] = {title = "Маргоз", objective = "Поговорите с Маргозом.", description = "Один из наших шаманов, Маргоз, многое знает о клане Пылающего Клинка. Как-то он рассказывал о пещере, которая называется скала Черепа, в горах у самого Оргриммара. Там окопалась большая шайка сектантов из клана Пылающего Клинка.\n\nПрежде чем отправиться к скале Черепа, поговори с Маргозом. Он мудр, и к его советам стоит прислушиваться.\n\nТы найдешь его на северо-востоке, между побережьем и Сухой лощиной.\n\nСледуй его советам, <имя>, но, что бы он ни сказал, я прошу тебя – уничтожь этих сектантов!", progress = nil, completion = "Здравствуй, Гронгард. До меня дошли слухи о твоем появлении и о твоих подвигах в Дуротаре.\n\nТы – многообещающий |3-6(Воин).\n\nНе сворачивай с этого пути, и великое будущее будет ждать тебя!", rewards = "Вы получите:\n\n"},
[829] = {title = "Нииру Огненный Клинок", objective = "Отнесите один обжигающий ошейник Нииру Огненному Клинку в Оргриммаре.", description = "Принесенные тобой обжигающие ошейники – это мощные инструменты демонов. И распознать их происхождение мне, как шаману, не под силу. Нужно, чтобы на них взглянул чернокнижник.\n\nОтнеси один обжигающий ошейник Нииру Огненному Клинку. Он искусный чернокнижник, но утверждает, что использует свою силу лишь затем, чтобы вредить демонам, а еще говорит, что его оккультные исследования идут на пользу Орде. Правда это или нет, а его помощь нам еще может понадобиться в борьбе с последователями демонов в Дуротаре.\n\nНииру можно найти в Оргриммаре, в Расселине Теней.", progress = "Мое почтение, |3-6(Воин). Чем могу я помочь тебе, брат?", completion = "О! Откуда у тебя это? Тебя прислал ко мне славный Маргоз из Колючего Холма, верно?\n\nНу-ка, дай взглянуть...", rewards = "Вы получите:\n\n"},
[830] = {title = "Приказы адмирала", objective = "Отнесите приказы адмирала Праудмура Га'току на Колючий Холм.", description = "Вы открываете потрепанный и выгоревший конверт и обнаруживаете документ официального вида. На нем – печать адмирала Праудмура.\n\nПохоже, это что-то важное. Может быть, Га'току, командиру Колючего Холма, эта информация пригодится...", progress = "У тебя озабоченный вид, |3-6(Воин). Что у тебя там?", completion = "Ничего хорошего это не предвещает... Очень хорошо, что ты принес это мне.", rewards = "Вы получите:\n\n"},
[831] = {title = "Приказы адмирала", objective = "Доставьте приказы адмирала Праудмура Назгрелу в зал приемов Тралла в Оргриммаре.", description = "Людям верить нельзя. Мы сражались плечом к плечу с ними, но в глубине души знали, что рано или поздно они нас предадут.\n\nАдмирал Праудмур был убит, но этого оказалось недостаточно, чтобы остановить предательство. Этот подлый человечишка успел изложить свои планы на бумаге, прежде чем встретил заслуженную смерть.\n\nЕго наследие не пропадет даже со смертью Бенедикта. Кто знает, когда следующая волна людей Праудмура обрушится на наши берега?\n\nЭти приказы нужно немедленно доставить в Оргриммар, Назгрелу! Ты найдешь его в зале приемов Тралла.", progress = "Ты что, не видишь? Я занят. Ну, докладывай. Но если дело не срочное...", completion = "О, сколько раз я умолял вождя не доверять людям! Однако тут речь не о личной гордости.\n\nТы достойно послужил Орде, |3-6(Воин).\n\nА теперь извини, мне нужно немедленно поговорить об этом с Траллом!", rewards = "Вы получите:\n\n"},
[832] = {title = "Пылающие тени", objective = "Отнесите этот амулет Нииру Огненному Клинку.", description = "<Слова из амулета плавно перетекают в ваш разум.> \n\nГазз'уз! \n\nГазз'уз, докладывай! \n\nО том, что ты нашел в Скале Черепа, уже стало известно. Готовься к нападению!\n\nГовори, Газз'уз! Говори, или я позабочусь о том, чтобы о твоем присутствии стало известно Нииру Огненному Клинку, а уж он-то тебя не пощадит!\n\nС Нииру тебе лучше не связываться...\n\nГазз'уз, ты меня слышишь?", progress = "Ты хочешь рассказать мне о чем-то важном, по глазам вижу!", completion = "*Нииру разглядывает Око Пылающей Тени.*\n\nЛюбопытно. Так ты говоришь, голос упоминал мое имя? Я, конечно, известен как непримиримый враг противников нашего вождя, но все же странно, что голос назвал именно меня. Тем более странно, что название секты, у членов которой ты нашел этот амулет, так похоже на мою фамилию.\n\nНадо изучить эту подвеску. Изучить и поразмыслить над тем, что значит это сообщение. \n\nСпасибо, Верлоз, что сообщил мне об этом. Ты оказал своему народу серьезную услугу.", rewards = "Вы получите:\n\n"},
[833] = {title = "Священное погребение", objective = "Сказитель Тотем Дождя попросил вас убить 8 злоумышленников из племени Дыбогривов в Красных cкалах.", description = "Лишь самых доблестных тауренов хоронят в Красных cкалах, на нашем священном кладбище. Эта честь выпадает лишь величайшим воинам, основавшим и защищавшим Громовой Утес, и тем, кто отдал свои жизни на благо племени и вождей. \n\nПохоже, теперь на эту священную землю пала тень. Могилы оскверняет отряд злоумышленников из племени Дыбогривов, а я слишком стар, чтобы отогнать их. \n\nПротив них поможет только сила, <класс>.", progress = "Мы должны изгнать злоумышленников из племени Дыбогривов со священных земель, Лонго.", completion = "Молодец. Ты проучил племя Дыбогривов. Теперь они дважды подумают, прежде чем осквернять святые для нас места.", rewards = "Вы получите:\n\n"},
[834] = {title = "Ветра пустыни", objective = "Добудьте 5 мешков припасов и верните их Резлаку близ Оргриммара.", description = "Я – Резлак, один из ребят Газлоу. Шеф послал меня на помощь оркам в  Дуротаре. Все бы хорошо, если бы не проблемы с караванами. Точнее, с охраной караванов. Как ты думаешь, можно ли работать, когда караваны все время грабят?\n\nПоследний караван – они мне клялись, что он-то уж точно дойдет! – перехватили гарпии Пыльного Ветра в... как же его... Каньоне Колючего Ветра!\n\nА мне этот груз позарез нужен, я без него как без рук! Ступай по большому каньону на юг, там будет расселина, идущая с запада на восток...", progress = "Не пойми меня неправильно, я мастер своего дела, но ведь это же просто смешно! Что мне тут делать, песочные замки строить?", completion = "О, то что надо! Наши припасы! Замечательно. Я смогу снова взяться за работу, как только найду кого-нибудь, кто донесет мне эти мешки.", rewards = "Вы получите:\n\n"},
[835] = {title = "Обеспечение безопасного сообщения", objective = "Убейте 12 дикарок из стаи Пыльного Ветра и 8 грозовых ведьм из стаи Пыльного Ветра, обитающих возле Сухой лощины, по просьбе Резлака.", description = "Газлоу мне как-то сказал: \"Резлак, запомни одну вещь: если хочешь, чтобы что-то было сделано хорошо, сделай это сам\".\n\nМы не можем и дальше терять караваны. Я вынужден взять дело в собственные руки. Сухая лощина находится в восточной части Каньона Колючего Ветра. Если перебить всех тамошних гарпий, дороги станут безопасными.\n\nРазумеется, Газлоу учил меня и другому: \"За соответствующую плату тебе сделают что угодно\". Ну что, <имя>, возьмешься?", progress = "Даже не верится, что такое мог говорить мой шеф, Газлоу, а ведь он мужик соображающий. \"Не бойся рисковать, когда надо\", – вот что он говорил.\n\nВедь гарпии так и будут нападать на нас и на караваны, пока мы что-нибудь с этим не сделаем, верно?", completion = "Ну все, теперь нашим караванам больше ничто не угрожает! Наконец-то я вздохну свободно. Твоя помощь пришлась как нельзя вовремя: со следующим караваном мне должны прислать партию занятных безделушек!\n\nТы, Гронгард, свое дело знаешь. Обратись к моему шефу в Кабестане. У него наверняка найдется для тебя работенка.\n\nАх да, не беспокойся, разумеется, я тебе заплачу за труды!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКрылорез гарпииКороткий лук из гикориЗапятнанный деревянный посох\n\nВы также получите:\n\n"},
[836] = {title = "Спасти КПХ-9/HL!", objective = "Сопроводите OOX-09/HL на побережье за Обзорными скалами, а потом доложитесь Карлсу Пропеллерзу в Пиратской бухте.", description = "Из робота снова раздается голос гнома:\n\n\"Нужно вывести OOX-09/HL на открытое и безопасное место, чтобы он мог взять нужный разбег и взлететь. У него есть система маскировки, но она, похоже, повреждена, поэтому вам придется проводить цыпленка до... ну, скажем, до побережья за Обзорными скалами! Местность там тихая и открытая, так что разбежаться он сумеет\".\n\n\"Пожалуйста, проводите робота на берег, а потом загляните ко мне в Пиратскую бухту. Карлс Пропеллерз, конец связи\".", progress = nil, completion = "О, да ты просто спас моего робота OOX-09/HL! Я прям даже не знаю, как тебя благодарить! Моих автономных роботов еще совершенствовать и совершенствовать, но ты избавил меня от многих лишних часов работы, а также от расходов!\n\nПожалуйста, выбери себе что-нибудь в награду. Спасибо тебе еще раз, Тузвколоде, я и мои роботы навеки у тебя в долгу.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги гнома-изобретателяГномье устройство, тонущее в воде\n\nВы также получите:\n\n"},
[837] = {title = "Вторжение", objective = "Убейте 4 свинобразов из племени Иглогривых, 4 разведчиков из племени Иглогривых, 4 пылебегов из племени Иглогривых и 4 боевых стражей из племени Иглогривых по просьбе Га'Тока из Колючего Холма.", description = "Когда мы поселились здесь, свинобразы Иглогривых владели большей частью этих земель и оказались сущей напастью! Большую их часть нам мало-помалу удалось вытеснить, но в некоторых районах они окопались прочно.\n\nОднако, с нас довольно! Ради нашей безопасности мы не можем больше терпеть присутствие Иглогривых в наших землях. Их лагеря – к западу отсюда. Они часто прячутся в зарослях колючек. Сегодня мы вытесним их из Дуротара – а завтра, глядишь, и из всего Калимдора!", progress = "Они, конечно, отчасти разумны и даже обладают зачатками общественного устройства, и все же меня не перестает удивлять тот факт, что иглогривы смогли захватить такие большие территории в Калимдоре. Быть может, они более хитры, чем мне кажется…", completion = "Я расскажу всем, что Иглогривы прогнаны со своих обжитых мест, и что их жилища надо сжечь. Теперь, когда племя Иглогривых изгнано из Дуротара, границы нашей новой родины станут значительно безопаснее.", rewards = "Вы получите:\n\n"},
[838] = {title = "Некроситет", objective = "Поговорите с аптекарем Дитерсом из Бастиона, что в Западных Чумных землях.", description = "На острове Каэр Дарроу располагается Некроситет – школа, которая одновременно служит цитаделью Плети. В ее недрах наши враги спокойно проводят исследования, делаясь все сильнее. Путь преграждают двери, и без подходящего ключа внутрь не войти.\n\nАптекарь Дитерс многое знает о Некроситете и придумал, как достать ключ. Ты <зарекомендовал/зарекомендовала> себя как человека с большими способностями, поэтому я доверяю тебе это задание. Обсуди подробности с аптекарем.", progress = nil, completion = "Да, |3-6(Охотник). Верховный палач упоминал, что тебе можно доверить тайну ключа. В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ, позволяющий отомкнуть двери в любой момент.\n\nДело, как всегда, будет непростым. Но судя по всему, тебя такими словами не напугать.", rewards = "Вы получите:\n\n"},
[840] = {title = "Новобранец Орды", objective = "Ступайте из Колючего Холма в Степи по западной дороге. Перейдите через мост.\n\nОстановитесь у орочьей заставы за мостом.\n\nОтдайте Каргалу Боевому Шраму ваше письмо о найме.", description = "Хм, <слабаком/слабенькой> тебя не назовешь…\n\nПослушай, моему приятелю Каргалу нужны новобранцы для службы в Степях. Ты ведь хочешь принести пользу Орде? Ну вот, это твой шанс.\n\nПередай Каргалу это письмо о найме – возможно, он его подпишет.", progress = "Чего тебе надо, молокосос? Если ты новобранец, давай сюда письмо, а иначе проваливай.", completion = "А, так тебя Такрин прислал? Он отличный разведчик, не знаю даже, что бы я без него делал…\n\nПисьмо-то я подпишу, но на самом деле воины нам нужны не здесь, а в Перекрестке.", rewards = "Вы получите:\n\n"},
[841] = {title = "Еще один источник энергии?", objective = "Принесите 10 бурдюков с водой Скитальцев Пустыни главному инженеру Чепухастеру в Прибамбасск в обмен на еще один источник энергии.", description = "Дай-ка я угадаю – ты не <успел/успела> осуществить свой страшный замысел, губительный для мироздания. Нет, еще лучше... Ты <уронил/уронила> его в песок! Короче, в любом случае я могу продать тебе еще один источник энергии. Только на сей раз он обойдется в десять, да, ДЕСЯТЬ, бурдюков с водой Скитальцев Пустыни!\n\nВремена настали тяжелые, а источники энергии не растут на деревьях! Хм, а что, если росли бы? Может, нам сконструировать дерево источников энергии...", progress = "И где мои десять мехов воды?", completion = "Ладно, вот еще один источник энергии. Очень советую применить его по назначению, если не хочешь добыть для меня еще десять мехов воды.", rewards = "Вы получите:\n\nИсточник питания, модель 4711-ФТЗ"},
[842] = {title = "Рекрутский набор Перекрестка", objective = "Ступайте по западной дороге от форпоста Каргала.\n\nНа развилке поверните налево и ступайте на юг.\n\nНайдите Сергру Черный Шип у перекрестка дорог в Перекрестке.", description = "Отнеси это подписанное письмо о найме в Перекресток.\n\nТам всем заправляет – Сергра Черный Шип, лопни ее шкура! Противная шаманка, заговорит тебя до посинения, прежде чем даст сделать что-нибудь толковое. Тралл уверен, что она замечательная, но мне что-то так не кажется.\n\nТак что разбирайся <сам, парень/сама> детка;...", progress = "Ну-с, и кто у нас тут? Неужели Каргал снизошел до того, чтобы прислать мне очередного рекрута?", completion = "Ладно, Гронгард. Не хочешь есть свой хлеб в Орде даром? Что ж, дел у нас предостаточно. Просто слушай внимательно и делай, что тебе скажут.\n\nИмей в виду, я по глазам вижу, что у тебя на уме. Наглости я не спущу! Тралл самолично заявил, что в Орде женщины во всем будут наравне с вами, мужиками. Только попробуй проявить ко мне неуважение – узнаешь, почем фунт лиха!", rewards = "Вы получите:\n\n"},
[843] = {title = "Ответный удар Ганна", objective = "Ганн Каменное Копье попросил вас убить 15 бейл'данских землекопов и 5 бейл'данских старшин.\n\nПринесите Ганну Каменному Копью записи Хазгорма.", description = "Ныне я брожу по дорогам родного края в одиночестве.\n\nДворфы Бейл Модана не чтят моих границ. Они постоянно устраивают взрывы, после которых остаются огромные ямы, а шумные механизмы разрывают мои холмы. Земли, некогда приютившие и питавшие мое племя, захвачены вредоносными дворфами.\n\nВсе попытки решить дело миром провалились. Пришло время для решительных действий.\n\nВыгони дворфов из раскопа в Бейл Модане и принеси мне записи Хазгорма, их главаря.", progress = "С появлением в Бейл Модане дворфов многие ни в чем не повинные таурены лишились жизни или покинули родину предков. Я должен вернуть свои земли!", completion = "Хазгорм заслужил свою судьбу. Мне нисколько его не жаль. Он явился в наши края незванным.\n\nБыть может, его смерть послужит предостережением тем, кто пытается нарушить наш покой.\n\nДай-ка я изучу записи этого дворфа...", rewards = "Вы получите:\n\n"},
[844] = {title = "Равнинные долгоноги", objective = "Принесите 7 клювов долгоногов Сергре Черный Шип в Перекресток.", description = "Первое задание будет совсем простым.\n\nРавнинные долгоноги, живущие к востоку отсюда, разоряют наши продовольственные склады – просто сил уже нет!\n\nПеребей несколько долгоногов и принеси мне их клювы.", progress = "Принес клювы долгоногов?", completion = "Хорошо, Ахахаха. Долгоногов перебили, и нам будет проще доставлять продовольствие. Надеюсь, и ты кое-чему научился, потому что следующая дичь не такая смирная, как долгоноги...", rewards = "Вы получите:\n\n"},
[845] = {title = "Жевры", objective = "Убивайте жевр-бегунов, пока не наберете 4 пары копыт жевры для Сергры Черный Шип в Перекрестке.", description = "Хотя жевры – не самые страшные звери в Степях, они посильнее равнинных долгоногов. Не беспокойся, в свое время тебе и покрупнее дичь достанется, но пока тебе еще надо малость поточить зубки. \n\nПоохоться на жевр на севере и на юге и собери их копыта. Принеси их мне, и, быть может, в следующий раз мы дадим тебе задание посерьезнее.", progress = "Сколько жевр тебе удалось убить?", completion = "Неплохо, Гронгард. У жевр сильные ноги. Одного меткого удара достаточно, чтобы отшвырнуть таурена в сторону!\n\nПохоже, в тебе тоже силы хватает. Ну что, готов пройти настоящее испытание?", rewards = "Вы получите:\n\n"},
[846] = {title = "Месть Ганна", objective = "Ганн Каменное Копье попросил вас принести ему 6 сосудов с нитроглицерином, 6 пучков древесной сердцевины и 6 образцов натриевой селитры.", description = "Очевидно, что шахтеры не могут обойтись без взрывчатки и шумных землеройных машин. Мы думаем, что скоро туда направят нового старшину.\n\nПусть проклятые дворфы отведают собственного угощения. Согласно схемам, если смешать нитроглицерин с древесной сердцевиной и натриевой селитрой, получится взрывной заряд. Все компоненты есть у ружейников, солдат и офицеров из Крепости.\n\nСобери все необходимое и принеси мне. Я создам заряд, который дворфы не скоро забудут!", progress = "Вижу, ты вернулся, Демонорох.\n\nХотя смерть Хазгорма и замедлила уничтожение холмов моих предков, полностью остановить разрушение не удалось.\n\nКрепость в Бейл Модане – угроза для нас всех. Она была построена для защиты раскопа, а теперь представляет собой грозную военную силу.\n\nЕсли ты принесешь мне все необходимое, я готов сделать заряд, после взрыва которого дворфы-торопыги передумают лезть в Степи.", completion = "Вижу, ты зря времени не терял, |3-6(Чернокнижник).\n\nОчень скоро дворфов ожидает неприятный сюрприз!", rewards = "Вы получите:\n\n"},
[847] = {title = "Коварство ящера", objective = "Поговорите с Тор'Ганом.", description = "Эта... эта сила... Это и есть мощь шаманов, которую Тор'Ган пытался мне показать? Должен сказать, весьма интересно. Скажите Тор'Гану, что он меня убедил... на данный момент. Я выслушаю то, что он хочет мне сказать.", progress = nil, completion = "Когда чары спадут, я поговорю с Гор'мулем. Благодарю вас за помощь в возвращении Гор'муля к жизни. Я не сомневаюсь, что и он очень благодарен вам.", rewards = "Вы получите:\n\nПризыв Ящера"},
[848] = {title = "Споры грибов", objective = "Принесите аптекарю Хелбриму в Перекресток 4 порции спор грибов.", description = "Оазисы Степей таят в себе тайну. В их водах разлита энергия жизни, питающая и укрепляющая растения и животных.\n\nИ меняющая их.\n\nНеподалеку от этих оазисов растет вид грибов, чьи споры мы, аптекари Лордерона, используем при создании снадобий.\n\nПринеси мне эти споры – и благодарность наша будет велика.", progress = "И где же споры? Мне надо сварить определенное зелье для коллеги из Громового Утеса, для этого и требуются споры...", completion = "Ах, да. Прекрасный материал. Действенный.\n\nЯ из Отрекшихся, а мы исполняем свои обещания. Вот твое вознаграждение, Гронгард.", rewards = "Вы получите:\n\n"},
[849] = {title = "Месть Ганна", objective = "Уничтожьте ветролет в Бейл Модане и возвращайтесь к Ганну Каменному Копью.", description = "Изучив схемы Хазгорма, можно без труда создать взрывчатку.\n\nНу вот, готово. \n\nА теперь, <имя>, я дам тебе особое задание. Возьми взрывчатку и подорви летающую машину в Бейл Модане.\n\nЭта машина не просто играет ключевую роль в снабжении раскопок, она служит и для военных целей. И что еще важнее – она воплощение мощи дворфов и оскорбление памяти моего племени.\n\nВыполни это задание, и я буду гордиться тобой! Ну и награду ты тоже получишь.", progress = nil, completion = "Отличная работа, Демонорох. В Громовом Утесе тебя будут чтить как защитника священных земель тауренов и поборника исчезнувшего племени.", rewards = "Вы получите:\n\nТотемное кольцо"},
[850] = {title = "Главари племени Колкар", objective = "Принесите Регтару Вратам Смерти, живущему на западе от Перекрестка, голову Барака.", description = "Сотни лет кентавры вставали на пути тауренов. В последнее время клан Колкар начал всерьез грозить безопасности Степей. Раньше им мешала побеждать их собственная неорганизованность, но недавно среди них появились новые вожди. Они создали из своих сородичей войско.\n\nЧтобы сохранить наши земли, мы должны убить вождей кентавров.\n\nПринеси мне голову Барака Кодобоя. Он живет в лагере неподалеку от Забытых прудов на севере.\n\nКогда одержишь над ним верх, возвращайся.", progress = "Привет, Гронгард. Принес голову Барака?", completion = "Молодец, Гронгард. Кентавры – примитивные и грубые создания, но некоторым из них была дарована мудрость и умение вести в бой. Они-то опаснее прочих.\n\nБарак таким и был. Хорошо, что он мертв.", rewards = "Вы получите:\n\n"},
[851] = {title = "Верог Дервиш", objective = "Принесите Регтару Вратам Смерти, живущему на западе от Перекрестка, голову Верога.", description = "Кентавр Верог Дервиш бродит по Пустошам, и найти его будет нелегко. Живет же он в командном шатре кентавров, в Застывшем оазисе на юго-востоке. Быть может, удастся заманить его туда.\n\nОтправляйся в Застывший оазис и напади на кентавров рядом с командным шатром. Это опасно, но если убить достаточно кентавров, кто-нибудь поднимет тревогу и явится Верог.\n\nПринеси мне его голову, и я помещу ее рядом с головой Барака Кодобоя.", progress = "Удалось найти Верога, Ахахаха?", completion = "Замечательно. Видно, ты взбаламутил кентавров – стражи заметили необычную активность неподалеку от Застывшего оазиса. Наверное, это твоя работа.\n\nМожешь гордиться своим подвигом, Ахахаха. Ты необыкновенно отважен.", rewards = "Вы получите:\n\n"},
[852] = {title = "Хэрзул Кровавая Отметина", objective = "Принесите Регтару Вратам Смерти, живущему к западу от Перекрестка, голову Хэрзула.", description = "Хэрзул Кровавая Отметина – глава кентаврского клана Колкар в Степях. Он свиреп, жесток и хитер. Одолев его, ты нанесешь серьезный урон всем Колкар, а значит, они станут меньше угрожать нам.\n\nИтак, убей его. Принеси мне его голову, как <принес/принесла> головы Барака и Верога.\n\nОн управляет своим народом из Цветущего оазиса на юге.", progress = "Так Хэрзул повержен?", completion = "Хвала тебе, Гронгард. Хотя кентаврам не хватает дисциплины, чтобы обрушить свою ярость на врагов, как орки, они все равно свирепые противники. Одержав над ними верх, ты доказал свою доблесть.", rewards = "Вы получите:\n\nКольцо охотника за головами"},
[853] = {title = "Аптекарь Зама", objective = "Отнесите топленые споры аптекарю Заме в Громовой Утес за отведенное время.", description = "Я сделал эмульсию из принесенных тобой спор, и теперь мне нужно доставить ее моей коллеге, аптекарю Заме. Если ты отнесешь ей мою посылку, она предложит тебе на выбор что-нибудь из своего запаса алхимических товаров.\n\nОна живет в Прудах Видений, пещере, расположенной ниже обиталища шаманов Громового Утеса. Путь к этой пещере хорошо скрыт, но начинается он на Вершине духов.\n\nПоспеши. Эмульсия хранится не очень долго, потому надо вскрыть и использовать ее до того, как она испортится.", progress = "Ты несешь мне посылочку от аптекаря Хелбрима?", completion = "А, споры, которые Хелбрим собрал в Степях. Он заручился твоей помощью при сборе? Хорошо.\n\nЭмульсия не успела испортиться, видать, ты время зря не тратил. Молодец, |3-6(Воин).", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСлабый эликсир стойкостиСлабый эликсир ловкостиСлабое зелье омоложенияЗелье скорости\n\nВы также получите:\n\nМешалка для котла"},
[854] = {title = "Путешествие в Перекресток", objective = "Поговорите с Торком на Перекрестке в Степях.", description = "Я знал, что ты придешь, <юный/юная:c> <класс>. Хотя, пожалуй, ты уже не так <юн/юна>.\n\nДумаю, тебе пора двинуться вглубь этих земель. Я чую, что тебе предстоят великие свершения. \n\nСтупай в Перекресток. Наша судьба тесно связана с судьбой орков, а им нужна помощь. Иди по дороге на восток, а потом сверни на север, к Перекрестку. Отыщи Торка в стенах города, ибо с ним пребывает благословение Матери-Земли.", progress = nil, completion = "Я рад, что нам на помощь прибыли союзники из самого Громового Утеса. Добро пожаловать!", rewards = "Вы получите:\n\n"},
[855] = {title = "Наручи кентавров", objective = "Принесите Регтару Вратам Смерти, живущему к западу от Перекрестка, 15 наручей кентавров.", description = "Клан Колкар угрожает завоеваниям Орды в Степях. Мы должны сократить численность их войск. В связи с этим у меня есть для тебя задание.\n\nОтправляйся в земли Колкар, перебей их воинов и принеси мне их наручи. Возвращайся с трофеями, и Орда тебя наградит.", progress = "Как идет охота, Демонорох?", completion = "Неплохо. Уверен, тебе удалось вселить страх в выживших кентавров. Если Колкар не полные идиоты, теперь они успокоятся и прекратят наступление.\n\nК сожалению, вряд ли им на это хватит ума. Что весьма плохо.\n\nПлохо для них, разумеется.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОркский боевой лукЗаточенный топорМолот Каменного леса\n\nВы также получите:\n\n"},
[857] = {title = "Слеза Лун", objective = "Фриглай Изгнанник попросил вас вернуть ему слезу Лун.", description = "Она была у меня в руках! В этих самых руках! И я хочу вернуть ее! Вернуть, говорю!\n\nЕе откопали эти грязные землекопы... и как она была прекрасна. Ее назвали слеза Лун. Первое серьезное открытие в Бейл Модане.\n\nОна должна достаться мне! Мне, говорю!\n\nГенерал Двукосса позавидовал силе, которую она мне давала, и запер ее в Крепости. Сказал, что эта вещь проклята. Дурак!\n\nЕе хотели заполучить и другие, мне пришлось их остановить. А этот ублюдок Двукосса прогнал меня.\n\nА я хочу ее вернуть. Вернуть, говорю!", progress = "Где слеза Лун? Она мне нужна! Нужна, говорю!", completion = "Наконец-то сила снова со мной! Со мной, говорю!", rewards = "Вы получите:\n\n"},
[858] = {title = "Зажигание", objective = "Добыв ключ зажигания, отнесите его Визлкранку.", description = "Тебя случайно не Пароклапан прислал? У меня проблемы. Я запрыгнул внутрь, не подумав, что для запуска резака нужен ключ. Один из операторов спросил меня, все ли в порядке, и я впал в панику! Вместо того чтобы сказать, что я потерял ключ, я заявил, что резак неисправен.\n\nНадо поскорее выбираться отсюда! Поднимись в комнату управления на вышке, у бригадира должен быть ключ от резака.\n\nВыручи меня!", progress = "Скорее, надо выбираться отсюда, пока никто ничего не заподозрил!", completion = "Ага, похоже, ключ подходит. Ну-ка, знаю ли я, как управлять этой штуковиной…\n\nХм... Управление вращением... Этот рычаг отвечает за скорость и равновесие... Управление манипулятором. Ну и ну! Поверить не могу, что Торговая Компания создала устройство, которое настолько лучше нашего. Надо доставить этот резак в Кабестан!", rewards = "Вы получите:\n\n"},
[860] = {title = "Сергра Черный Шип", objective = "Поговорите с Сергрой Черный Шип в Перекрестке.", description = "Ежели хочешь вступить на путь охотника, то тогда тебе надо идти в Степи. Тамошние твари упрямы и яростны. Охотясь там, ты многому научишься, и дух твой окрепнет.\n\nПоговори с Сергрой Черный Шип. Она будет первой твоей наставницей в Степях.\n\nСергра сейчас в Перекрестке. Чтобы туда добраться, иди на восток от Деревни Кровавого Копыта прямиком в Степи, затем на развилке сверни на север. И по дороге держи ухо востро – Степи весьма опасны для неопытных и беспечных.", progress = nil, completion = "Хочешь охотиться в Степях?\n\nГлаза у тебя горячие и молодые. Они еще не окосели от выслеживания добычи на тутошних пыльных равнинах.\n\nНо ты не бойся. Мы закалим твое тело и дух! И растолкуем, что охота – не просто выслеживание и добыча.\n\nГотовься. Твой путь начинается прямо сейчас.", rewards = "Вы получите:\n\n"},
[861] = {title = "Путь охотника", objective = "Принесите 4 когтя хищника плоскогорья Мелору Каменному Копыту в Громовой Утес.", description = "Вижу, ты любишь путешествовать. Когда-то и меня обуревала жажда странствий…\n\nСтранствий и охоты. Ведь охота – первая доблесть таурена.\n\nЕсли ты в самом деле желаешь избрать путь охотника, Мелор Каменное Копыто поможет тебе сделать первые шаги. Он живет в Громовом Утесе, на вершине Охотников.\n\nЧтобы показать свою решимость и умения, принеси ему когти хищника плоскогорья. Эти звери сильны и хитры – подходящая добыча для <молодого/молодой:c> <класс>, <избравшего/избравшей> путь охотника.", progress = "Приветствую. Вижу, ты хочешь о чем-то рассказать. У тебя ко мне какое-то дело?", completion = "Скорн Белое Облако – мудрый таурен. Он посвятил охоте много лет, и хотя уже слаб телом, дух его по-прежнему бодр. Мы высоко чтим его.\n\nЕсли тебя и правда прислал Скорн, то он разглядел в тебе будущего охотника. Добыть же эти когти было непросто, я знаю.\n\nБыть может, тебе пора вступить на избранный путь.", rewards = "Вы получите:\n\n"},
[862] = {title = "Крысиная похлебка", objective = "Принесите 8 пещерных крыс Грубу на востоке от Перекрестка.", description = "Должно быть, <класс> вроде тебя в Степях голодно. Я вот постоянно хочу есть.\n\nЗнаешь, приготовлю-ка я тебе отличную похлебку. Для этого мне понадобится несколько пещерных крыс.\n\nПохоже, эти грязные дворфы в Бейл Модане увлечены празднованием. Так что ступай в Бейл Модан, это на юге, и принеси мне несколько пещерных крыс.\n\nТебе не стать закаленным бойцом, пока не набьешь руку на крысах! Ха-ха!", progress = "Ну что, достаточно пещерных крыс притащил?", completion = "Обычно я не ем этих грызунов, пока они такие... такие... свежие. Им надо полежать несколько недель, чтобы мяско стало с душком. Но ты, похоже, голоден.\n\nДай-ка я сварю тебе похлебку из пещерных крыс. Ну вот, готово.\n\nКушай на здоровье!", rewards = "Вы получите:\n\nРецепт: похлебка из пещерной крысыПохлебка из пещерной крысыПерчатки аптекаря"},
[863] = {title = "Бегство", objective = "Охраняйте Зигзага и похищенный гоблинский резак по пути к Пароклапану в Кабестан.", description = "Полагаю, я буду учиться по ходу дела... Вряд ли это так сложно. Тут пара кнопок, там рычаг-другой. Ну что, поехали?", progress = nil, completion = "Надеюсь, нам удастся найти что-нибудь ценное в этом поломанном образце резака... Время на исходе! Я отправлю спасательную экспедицию на помощь к Визлкранку.\n\nА, вот тебе за труды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВспыхивающая дубинкаЗамасленные штаны ремонтника\n\nВы также получите:\n\n"},
[864] = {title = "Возвращение к аптекарю Зинг", objective = "Отнесите запечатанный набор для полевых испытаний аптекарю Зинг в Подгород.", description = "Ну вот, источник энергии извлечен, и твои данные сохранились. Что ж, счастливого пути и все такое. Надеюсь, зловещий научный эксперимент удался.\n\n*Гоблин отворачивается от вас и погружается в дела Водной компании Прибамбасска. Вы кладете запечатанный набор для испытаний в надежное место и готовитесь отбыть в Подгород. Вас и запечатанный набор ждет аптекарь Зинг.*", progress = "Добро пожаловать домой. Разумеется, в том случае, если ты несешь мне запечатанный набор для полевых испытаний. Если нет – я притворюсь, что не заметила твоей полной некомпетентности и не буду обрушивать на тебя свой гнев. Потому что ты пойдешь и сделаешь, что велено!", completion = "Я немедленно займусь анализом данных. Быть может, безумие Чанна обернется моей гениальностью.\n\nЧто до тебя... Ты мне полезен, а я хорошо обращаюсь с полезными существами. Прими эту вещь, эти монетки, а в придачу к ним – мою благодарность.\n\nЗаглядывай время от времени – думаю, что мы еще поработаем вместе.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки искусной обработкиНакидка аптекаряНаплечники Кожи мудрости\n\nВы также получите:\n\n"},
[865] = {title = "Рога ящера", objective = "Соберите 5 невредимых рогов ящера с ящерочешуйчатых смертехватов и отнесите их Мебоку Миззриксу в Кабестан.", description = "Ящеры Степей умнее, чем прочие. Мне кажется, весь ум в рогах! Если так, эти рога можно стереть в порошок и сделать из них \"умный напиток\". Я мог бы продавать его за баснословные деньги!!!\n\nТы можешь мне помочь. Принеси мне целые рога ящерочешуйчатых смертехватов. Они живут в южной части Степей и на севере, рядом с границей Ясеневого леса.", progress = "Ты принес рога, Демонорох? Я собираюсь сколотить состояние на этих тварях!", completion = "Здорово, тебе удалось их добыть! Остается стереть рога в порошок, смешать с вином и...", rewards = "Вы получите:\n\nПунш ЯщераПлащ бармена"},
[866] = {title = "Образцы корней", objective = "Принесите Мебоку Миззриксу из Кабестана 8 образцов корней.", description = "Таких трав, как в Степях, нет нигде. Свойства у них по большей части те же, но вода оазисов оказывает на них особое влияние, и они все же отличаются от подобных им, хоть и не сильно.\n\nЯ хочу выяснить, в чем же состоит разница... и нельзя ли ей воспользоваться!\n\nЕсли ты владеешь искусством травничества, собери для меня образцы корней растений Степей, и я сравню их с травами из других регионов.", progress = "Привет, Демонорох. Принес образцы корней?", completion = "Да-да, замечательно! Из этих корней я выращу травы и смогу изучить их. Надеюсь отыскать в них новые свойства. Скрытые ценные свойства...\n\nИ не беспокойся – ты узнаешь об этом первым. Потому что в таком случае мне понадобится много корней!", rewards = "Вы получите:\n\nСпороносный мундир"},
[867] = {title = "Гарпии-налетчики", objective = "Соберите 8 когтей Зачарованного Крыла.\n\nПринесите их Дарсоку Точному Ножу на Перекресток.", description = "Нет сил терпеть нападения на наши караваны со съестными припасами. Пора сократить число проклятых гарпий, перерезав горло десятку-другому.\n\nЯ пробрался к их гнездам и выяснил, кто есть кто. Начать надо с низов, а потом постепенно пробиваться наверх.\n\nДля начала займись гарпиями и разбойницами из стаи Зачарованного Крыла, поселившимися на северо-западе, и принеси мне 8 когтей Зачарованного Крыла. Будет уже неплохо...", progress = "Ну как, много ли гарпий удалось убить? Режь их, круши и бери трофеи. Мне нужно 8 когтей Зачарованного Крыла.", completion = "Прекрасные когти. Чудные. Отличная работа, Демонорох. Надеюсь, в ближайшем будущем мне снова доведется полюбоваться на твою работу.", rewards = "Вы получите:\n\n"},
[868] = {title = "Охота за яйцами", objective = "Принесите 12 яиц силитидов и вспарывающий коготь Коррану в Перекресток.", description = "Эй, <имя>. Меня отправили в Перекресток присматривать за этими землями и сообщать начальству в Оргриммаре, что тут творится.\n\nВ частности, мне велено наблюдать за насекомовидными тварями на юге в Полях Великанов. Нам о них почти ничего не известно, а я хотел бы узнать о них побольше. Кажется, они умнее обычных животных.\n\nВозьми вспарывающий коготь и принеси несколько яиц этих тварей из их курганов, но будь осторожнее: они нападут на тебя, если заметят, что ты творишь.", progress = "Осторожно, яйца хрупкие. Разбитые мне не нужны.", completion = "Порадовал ты меня, Демонорох. Молодец.\n\nВот твоя награда...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОдеяния арлекинаФиолетовая чешуя\n\nВы также получите:\n\n"},
[869] = {title = "Ящеры-воры", objective = "Принесите 12 голов ящеров Газрогу в Перекресток.", description = "Недавно из сторожевой башни был похищен груз серебра. Он предназначался в уплату стражам Перекрестка, и его необходимо вернуть.\n\nСамое странное... одного из воров мы поймали с поличным. И... это оказался ящер! Немыслимо!\n\nНе знаю, зачем ящерам серебро. Мне все равно: главное, чтобы у нас не воровали. Пусть сдохнут!\n\nОтправляйся на охоту в Степи. Принеси мне их головы!", progress = "Принес головы, Гронгард?", completion = "Тебе удалось избавить нас от ящеров!\n\nСпасибо, Гронгард. Ты – достойный |3-6(Воин).", rewards = "Вы получите:\n\n"},
[870] = {title = "Забытые пруды", objective = "Отыщите источник силы и доложите о нем Тонге Руническому Тотему.", description = "Давным-давно Степи были цветущим садом, полным жизни. Но этих земель коснулась карающая десница войны и катаклизма, обратив их в высохшую пустыню. Это наполняет мое сердце грустью, но так уж получилось.\n\nВпрочем, в последние годы в Степях образовалось несколько новых оазисов, а в них появилась жизнь. Мы, друиды, чувствуем, что из глубины к поверхности рвется какая-то сила.\n\nМы должны обнаружить ее источник. Отправляйся к Забытым прудам, к северу от Перекрестка. Отыщи в воде источник силы и возвращайся сюда.", progress = "Ты побывал у Забытых прудов, Варабэй? Удалось что-нибудь выяснить?", completion = "Там есть расселина, из которой выходят пузырьки газа? Странно. Может быть, это и есть ответ на наши вопросы, но уверенности нет. \n\nВпрочем, хоть какая-то зацепка. Спасибо, что нашел ее.", rewards = "Вы получите:\n\n"},
[871] = {title = "Прекратить набеги", objective = "Убейте 8 водоискателей, 8 терноплетов и 3 охотников племени Иглогривых и возвращайтесь к Торку с Перекрестка.", description = "Все свинобразы – наши враги, <имя>. Просто одни из них причиняют нам больше неприятностей, чем другие.\n\nКлан Иглогривых в последнее время нередко нападает на наши караваны из Дуротара, и терпеть это нет больше сил. Мои разведчики ищут главарей, но тем временем чем больший урон мы нанесем эти свиньям, тем лучше.\n\nСтупай на северо-восток, по направлению к Дуротару. Ты легко отыщешь их логова среди огромных колючих побегов, исходящих из земли. Отыщи их и убей, кого сможешь.", progress = nil, completion = "Отличная работа, Гронгард. Мерзавцы-иглоривы наконец-то научатся считаться с мощью Орды.", rewards = "Вы получите:\n\n"},
[872] = {title = "Конец бесчинствам", objective = "Убейте 8 геомантов и 8 защитников из племени Иглогривых и Кринига Грознорыла и возвращайтесь к Торку из Перекрестка.", description = "Один из разведчиков своими глазами видел нападение на караван из Дуротара, <имя>. Естественно, виноваты свинобразы из племени Иглогривых. Возглавляет нападения Криниг Грознорыл. Его видели на северо-востоке отсюда, южнее дороги на Дуротар. Пока Криниг жив, покоя не будет.\n\nНо чтобы окончательно прекратить разбой, надо как следует унизить мерзких иглогривов. Убей Кринига Грознорыла и его приспешников и принеси мне его клык.", progress = "Отрежь голову их вожаку, и воцарится хаос. Хорошенько усвой этот урок. Он пригодится тебе в будущем.\n\nЭти свиньи будут метаться без цели, и мы захватим все Степи.", completion = "Молодец, Гронгард. Криниг мертв, и число нападений на караваны сократится.\n\nТвой народ должен гордиться тобой.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОпоясывающий ременьПояс с застежкой\n\nВы также получите:\n\n"},
[873] = {title = "Иша Авак", objective = "Принесите сердце Иши Авака Марен Небесной Провидице.", description = "Великий Иша Авак – повелитель этих вод. Велика его сила, несокрушима гордость. Народ побережья страшится его, ибо он поглотил многих из их числа.\n\nНо я не боюсь его. Я благодарен провидению за то, что он есть. Бросить ему вызов – высокая честь, ибо он достойный противник.\n\nЕсли ты <готов/готова>, плыви на поиски Иши Авака, Рока Глубин.\n\nЕго дух содержится в сердце, и услышав, как оно бьется, можно узнать многое о своей судьбе.", progress = "Не бойся вод, |3-6(орк).", completion = "Теперь вы с Иши Аваком едины, Демонорох. Его дух живет в тебе. Он таится в твоих глазах…\n\nГлазах, которые однажды научатся видеть.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОбжигающий жезлСтраж долины\n\nСледующее заклинание будет наложено на вас:\n\nСила Иши Авака\n\nВы также получите:\n\nРемень повелителя зверей"},
[874] = {title = "Марен Небесная Провидица", objective = "Поговорите с Марен Небесной Провидицей.", description = "Ты <поохотился/поохотилась> на многих зверей Степей. Дух твой тверд. Но охотник должен быть готов ко всему, его не смутит никакой путь. Горы и болота не испугают его.\n\nИ даже море.\n\nНайди мою сестру, Марен. Она охотится на огромных водных тварей на побережье и многому научит тебя.\n\nИщи ее с осторожностью, потому что побережье Степей захвачено людьми.", progress = nil, completion = "Тебя прислал мой брат? Должно быть, ты произвел на него впечатление. А если тебя зауважал Джорн, то и я буду уважать.\n\nЖелаешь ли ты сделать следующий шаг на пути охотника?", rewards = "Вы получите:\n\n"},
[875] = {title = "Лейтенанты гарпий", objective = "Соберите 6 колец лейтенантов гарпий с душегубок из стаи Зачарованного Крыла и возвращайся к Дарсоку Быстрому Ножу.", description = "Ха-ха-ха, <имя>. Еще захотелось? Отлично, приятно слышать.\n\nНа сей раз я хочу, чтобы ты <убил/убила> несколько лейтенантов гарпий в Сухих холмах. Лейтенантами бывают только душегубки из стаи Зачарованного Крыла. Их можно отличить от других по характерным кольцам. Неприятные твари, да еще и приспешников их там полно. Убей шестерых и нанеси мощный удар по этому бабьему царству.\n\nИ пусть подыхают долго и мучительно. Это научит их не связываться с Ордой.", progress = "Ты уже принес 6 колец лейтенантов гарпий? Пора свершить над ними суд и положить конец их нападениям на Орду.", completion = "Прекрасная работа, дружище. Думаю, ты достигнешь высокого положения в Орде.", rewards = "Вы получите:\n\n"},
[876] = {title = "Серена Кровавое Перо", objective = "Убейте Серену Кровавое Перо и принесите ее голову Дарсоку Точному Ножу на Перекресток.", description = "Ты так хорошо <справился/справилась> с лейтенантами и приспешниками, что я хочу дать тебе еще одно поручение.\n\nСерена Кровавое Перо – сестра гарпии по имени Кровавое Перо, которую давным-давно прикончил Рексар. Очевидно, что нападения на обозы Орды обусловлены желанием отомстить за смерть сестры.\n\nПерережь ей горло и принеси мне ее голову. Я хочу прибить ее на переднюю телегу следующего каравана... Пусть проклятые гарпии задумаются, прежде чем снова нападать на нас.", progress = "Ты ничего не получишь, пока я не увижу голову Серены.", completion = "ХА! Молодец, Демонорох! Отличная работа... Я не был уверен, что ты справишься с заданием, но, оказывается, ты головорез, каких поискать. Еще раз спасибо за избавление от нашествия гарпий. Вот награда, используй ее с умом.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЭлегантный короткий мечЖиводер гарпииТопор Зовура\n\nВы также получите:\n\n"},
[877] = {title = "Застывший оазис", objective = "Внимательно осмотрите Застывший оазис и возвращайтесь к Тонге Рунному Тотему в Перекресток.", description = "Быть может, и в других оазисах Степей есть расселины вроде той, что тебе удалось обнаружить в Забытых прудах? Коли так, скорее всего именно эти расселины – источник жизни оазисов.\n\nНадо проверить.\n\nВот, возьми эти семена. Сейчас они мертвые и бесплодные. Отнеси их в Застывший оазис на юго-востоке. Если там есть расселина, помести в нее семена... и понаблюдай.", progress = nil, completion = "Удивительное открытие! Я дал тебе иссохшие, мертвые семена. Значит, то, что таится в этих оазисах, создает жизнь из ничего!\n\nНеобходимо исследовать это явление повнимательнее...", rewards = "Вы получите:\n\n"},
[878] = {title = "Воюющие племена", objective = "Убейте 6 водоискателей, 12 терноплетов и 12 геомантов из племени Дыбогривов и возвращайтесь к Кривозубу в Лагерь Таурахо в Степях.", description = "Отомсти моим врагам. *фыркает* Помоги Кривозубу и Иглогривым, ослабив племя Дыбогривов. Оба племени духовно связаны с землей и ее мощью. *фыркает* Она дарует нам силу, необходимую для всего... и прежде всего – для войны.\n\nЕсли ты в самом деле хочешь узнать, кто причинил Торку и Орде так много страданий, помоги Кривозубу! Напади на духовных вождей Дыбогривов на севере; подорви их мощь, чтобы Иглогривые одолели своих соперников и покорили Степи.", progress = "Орда получит сведения *фыркает*, только когда ты убьешь мудрецов племени Дыбогривов, |3-6(тролль). *фыркает* Ни минутой раньше! Кривозуб не дурак.", completion = "Да-да... Меня должна переполнять радость, *фыркает* ведь племя Дыбогривов испытало ту же боль, что и мой народ, |3-6(тролль). Но нет, радости нет места. *фыркает*\n\nТы помогаешь своим, и они чтят тебя. Кривозуб помогает своим – и что же? Они отвернулись от него. Его забыли, оставили гнить в клетке!\n\nЯ помогал им даже из-за решетки, но никто не пришел мне на помощь!", rewards = "Вы получите:\n\n"},
[879] = {title = "Предан своими", objective = "Убейте Нака, Куза и Лока Оркобоя и принесите их черепа Кривозубу в Лагерь Таурахо в Степях.", description = "Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, <раса>. *фыркает* Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрестке и в большей части Степей воцарится мир... *фыркает* по крайней мере, племя Иглогривых не будет на вас нападать. *фыркает*\n\nИмена этих главарей – Нак, Куз и Лок Оркобой. Они укрылись на юге Степей. Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем – *фыркает* воин. Убей их, <раса>, как они убили меня.", progress = "И как идет охота, |3-6(нежить)? *фыркает* Торк полагает, что знает, кто возглавляет набеги на его народ, *фыркает* но он поймет, как ошибался.\n\nМоя смерть неотвратима, но тебе удалось нанести серьезный урон моим врагам, и Кривозуб ни о чем не жалеет. *фыркает*", completion = "Дело сделано. Кривозуб считает, уж лучше так. *фыркает* Надо было убедиться *фыркает*, что я мертв, а не бросать меня здесь, во всеми забытой клетке.\n\nТебе осталось лишь одно дело, |3-6(нежить).", rewards = "Вы получите:\n\n"},
[880] = {title = "Измененные существа", objective = "Принесите 8 измененных панцирей зубастых черепах Тонге Руническому Тотему в Перекресток.", description = "Ты рассказываешь невероятные вещи, <имя>. Источник свойств этих оазисов явно сторонний. Или, быть может, вообще потустороннй.\n\nЯ хочу узнать, какое влияние расселины оказывают на зверей, приходящий на водопой.\n\nУбей несколько оазисных хрустогрызов в Цветущем и Застывшем оазисах. Принеси мне их панцири, и я их пристально изучу.", progress = "Как идет сбор панцирей? Много набрал?", completion = "Спасибо, Ахахаха. Изучая обитателей различных мест, узнаешь немало о самих местах. Посмотрим, о чем нам поведают панцири.\n\nПрошу тебя, прими благодарность за помощь... Быть может, эти монеты тебе не помешают. Мне они уже не нужны.", rewards = "Вы получите:\n\n"},
[881] = {title = "Ичияки", objective = "Принесите шкуру Ичияки Сергре Черный Шип на Перекресток.", description = "Ичияки, Белый Туман на языке тауренов, король кошачьих саванны. Он подкрадывается к жертвам так незаметно, что его уподобили белому туману, стелящемуся над землей. Убивает он одним ударом – жертва не успевает ни испугаться, ни ощутить боли.\n\nТаурены говорят, что он воплощает собой милосердие и смерть.\n\nТы узнаешь это на своем опыте, потому что я отправляю тебя охотиться на Ичияки. Его логово располагается на северо-востоке от Перекрестка, среди костей огромного кодо.\n\nСтупай. Добравшись до логова, протруби в этот рог. Протруби в рог, и он явится на зов.", progress = "Тебя ожидает великий кот, Демонорох.", completion = "Тебе удалось одолеть Ичияки, и хотя ему больше не суждено охотиться в саванне, дух его отныне пребудет с тобой. Он научит тебя обретать силу в хитрости, а честь в милосердии.\n\nПеред тобой долгий путь, |3-6(Чернокнижник). Хочется верить, что ты далеко пойдешь.", rewards = "Следующее заклинание будет наложено на вас:\n\nБлагодать Ичияки\n\nВы получите:\n\n"},
[882] = {title = "Ишамухал", objective = "Принесите клык Ишамухала Джорну Искателю Неба в Лагерь Таурахо.", description = "Ишамухал, или Копьезуб, – самый страшный из всех яркочешуйчатых ящеров Степей. Он охотится не ради еды и не для удовольствия. Охота – его страсть. Он убивает потому, что сам убийца по природе.\n\nИменно о его природе тебе и предстоит узнать многое, <имя>, ибо твой путь теперь поведет тебя по когтистым следам Ишамухала.\n\nНачинай охоту. Убей его излюбленную добычу – жевру – и принеси его тушу к мертвому дереву на северо-западе от Кабестана. Ишамухал почует тушу и явится на ее запах.\n\nБудь <готов/готова> к его появлению.", progress = "Удалось ли тебе одолеть Ишамухала, Ахахаха?", completion = "Клык – всего лишь символ, но символ очень важных вещей.\n\nТеперь в тебе есть сила Ишамухала, Ахахаха. Пользуйся ей, но соблюдай умеренность. Отныне это твоя ноша.\n\nИ это великая честь.", rewards = "Следующее заклинание будет наложено на вас:\n\nЯрость Ишамухейла\n\nВы получите:\n\n"},
[883] = {title = "Лакота'мани", objective = "Принесите копыто Лакота'мани Джорну в Лагерь Таурахо.", description = "Копыто Лакота'мани – символ силы великого кодо.", progress = "Мопедгоша, я вижу в твоих глазах сияние новой силы! Скажи, ты встретился с великим Лакота'мани?", completion = "Лакота'мани на нашем языке означает \"Землекрушитель\", ибо шаги его громоподобны. Теперь он пребывает с тобой, к тебе перешло все его мужество. Отныне ты не побоишься встретиться с любой опасностью.\n\nВерь в себя, Менгиле. Верь в себя, Землекрушитель.", rewards = "Следующее заклинание будет наложено на вас:\n\nГром Лакотамани\n\nВы получите:\n\n"},
[884] = {title = "Оватанка", objective = "Принесите хвостовой зубец Оватанки Джорну Искателю Неба в Лагерь Таурахо.", description = "При касании от хвоста Оватанки летят искры.", progress = "Гронгард, я вижу в твоих глазах сияние новой силы! Тебе удалось встретиться с могучей Оватанкой?", completion = "Имя рокочущей ящерицы Оватанки на языке тауренов означает \"синяя молния\", ведь о ее стремительности не стоит судить по размеру. Говорят, что Оватанку некогда поразила молния, и, напитавшись гневом небес, она стала воистину неутомимой.\n\nНыне ее неутомимость передалась тебе, Эпифантий. Теперь ты не отстал бы от Оватанки.", rewards = "Следующее заклинание будет наложено на вас:\n\nБыстрота Оватанки\n\nВы получите:\n\n"},
[885] = {title = "Ваште Пауни", objective = "Отнесите перо Ваште Пауни Джорну Заклинателю Небес в Лагерь Таурахо.", description = "Пера Ваште Пауни больно касаться.", progress = "Я вижу, ты исполнен решимости, Карандаш. Решимости, порожденной страданием…\n\nТебя тяготит гибель Ваште Пауни?", completion = "Грозовой змей нечасто встречается в Степях, и его смерть может означать большую удачу или тяжкий рок.\n\nНо смерть Ваште Пауни, что на языке тауренов означает \"кусающий дух\", не значит ни то, ни другое... Или оба сразу.\n\nБоль, испытанная тобой во время охоты на это существо, знакома всем, кто достигает величия великой ценой. Внутренние терзания же – следствие сожалений.\n\nВпрочем, я вижу, что ты справился с этими искушениями и познал, что сожаления обращаются в мудрость и лишь через страдания можно обрести силу.\n\nТы многое познал, Карандаш.", rewards = "Следующее заклинание будет наложено на вас:\n\nРешимость Ваште Пауне\n\nВы получите:\n\n"},
[886] = {title = "Оазисы Степей", objective = "Поговорите на Перекрестке с Тонгой Руническим Тотемом.", description = "Друиды Громового Утеса ощущают странную силу, просачивающуюся в Степи к, востоку от Мулгора.\n\nМы отправили найти источник этой силы Тонгу Рунического Тотема, но, похоже, ему нужна помощь.\n\nОтправляйся в Степи и поговори с Тонгой. Он будет в Перекрестке. Иди туда по дороге на восток от Деревни Кровавого Копыта. Как попадешь в Степи, сверни на развилке на север. И продолжай идти, пока не упрешься в Перекресток.\n\nС дороги не сходи, <имя>, ибо Степи – край суровый.", progress = nil, completion = "Мои собратья в Громовом Утесе мудро поступили, прислав тебя сюда, юный |3-6(Друид). Ибо тайну Степей мне в одиночку не раскрыть.\n\nБудем надеяться, что с твоей помощью мы найдем ответ на наш вопрос.", rewards = "Вы получите:\n\n"},
[887] = {title = "Флибустьеры Южных морей", objective = "Убейте 12 грабителей Южных морей и 6 канониров Южных морей по просьбе Газула из Кабестана.", description = "Жаль, что вице-адмиралу Греззлику не удалось добиться безопасности в наших водах для торговых кораблей. В торговый флот вложено столько денег, что я просто зверею, когда пираты как нечего делать нападают на мои корабли и похищают товары! \n\nГоворят, что флибустьеры Южных морей разбили лагерь к югу отсюда. Они мне как бельмо на глазу, и если ими не хочет заняться Греззлик, может быть, ты поможешь избавиться от них?", progress = "Мне даже думать тошно о том, сколько я денег потерял из-за проклятых пиратов. А теперь они еще и лагерь у меня под носом разбили? Это уже наглость. Надо что-то с этим делать.", completion = "Молодец, малыш. Побольше таких подвигов, и у меня станет одной проблемой меньше. Хочется верить, что они решат перенести свой лагерь.\n\nОстается одно – вернуть украденные товары!", rewards = "Вы получите:\n\n"},
[888] = {title = "Украденное добро", objective = "Верните Газлоу из Кабестана посылку с сапогами и линзу от телескопа.", description = "Хоть я и хотел бы вернуть все товары, думаю, это невозможно. Но некоторые из них мне очень нужны!\n\nКак видишь, моя обсерватория почти готова, но ей не хватает двух малых линз. Первая из них прибыла с караваном из Дуротара, но вторую везли на корабле, который ограбили пираты. Кроме того, до меня так и не дошла партия сапог от Дриззлика из Пиратской бухты!\n\nСтупай в пиратский лагерь и поищи их.", progress = "Ну что, удалось найти мои вещи?", completion = "Я так рад, что вернул свое добро! Спасибо за помощь, Гронгард. Знаешь, мне пригодились бы помощники вроде тебя. Если понадобится работа, не забывай, что Газлоу неплохо платит!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДорожные перчаткиСтеганые ламеллярные сапоги\n\nВы также получите:\n\n"},
[889] = {title = "Дух Ветра", objective = "Принеси Кривозубу 10 кровавых осколков, и он одарит тебя большой скоростью. Ты сможешь перегнать жевр, и даже ветер тебе позавидует.\n\nПодействует это недолго, но облегчит странствия по Степям.", description = nil, progress = "Принеси Кривозубу 10 кровавых осколков, и он одарит тебя большой скоростью. Ты сможешь перегнать жевр, и даже ветер тебе позавидует.\n\nПодействует это недолго, но облегчит странствия по Степям.", completion = "Хорошо. Да ведет тебя дух Агамаггана, |3-6(нежить). Возвращайся, если захочешь вновь соприкоснуться с магией Агамаггана.", rewards = "Вы изучите:\n\nДух ветра"},
[890] = {title = "Пропавший груз", objective = "Отнесите учетную книжку Газлоу управляющему пристанью Головокружилкинсу.", description = "Я уже сто лет жду последнего заказа из Пиратской бухты! Наверняка его перехватили флибустьеры, но на всякий случай сходи в порт и спроси у Дыбоволоса, вдруг товары без моего ведома отнесли на склад?\n\nВот, отнеси мою учетную книжку Головокружилкинсу, пусть сверит со своими записями.", progress = "Хочешь отправить товар со следующим кораблем, Демонорох?", completion = "А, так тебя прислал Газлоу? Минутку, дай-ка я загляну в свои записи, надо убедиться, что я не отправил товар Газлоу куда-то не туда.\n\nНебось, он ждет поставку сапог от Дриззлика...", rewards = "Вы получите:\n\n"},
[891] = {title = "Пушки крепости Северной Стражи", objective = "Капитан Тало'тас Сияющий поручил вам собрать 10 тераморских медалей и убить капитана Гордостанную, канонира Вессана и канонира Смайта.", description = "Вот и еще один мой корабль захватили рьяные людишки из крепости Северной стражи!\n\nПора разобраться с этими мерзавцами. Их паранойя перешла все мыслимые границы. Эти безрассудные любители спускать курок стреляют во все, что движется.\n\nОтправляйся на юг вдоль Торгового побережья, найди их крепость и брось вызов их силе. Принести в доказательство собственных подвигов медали их солдат. И во имя моего флота, убей капитана Гордостанную и ее рьяных канониров!", progress = "Мой флот в опасности! Капитан Гордостанная и ее проклятые канониры постоянно стреляют по кораблям из своей крепости Северной стражи. Я хочу, чтобы ее солдаты расплатились за наглость. Принеси мне полную горсть медалей, снятых с ее приспешников, и я буду знать, что мои павшие бойцы отомщены.", completion = "Ах, какая жалость, праведные пушки Альянса умолкли. Ты получишь награду за помощь, Ахахаха.\n\nКак бы теперь выручить тела наших погибших...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМушкет капераБрюки Морского волка\n\nВы также получите:\n\n"},
[892] = {title = "Пропавший груз", objective = "Верните Газулу из Кабестана его регистр.", description = "У меня в записях все в порядке, <имя>. Ступай к Газулу и скажи, что ему не повезло. Не удивлюсь, если его товары прибрали к рукам пираты. \n\nЯ ничем не могу ему помочь. А, да... Скажи, что у меня есть для него кое-что из Нижней шахты, пусть приходит и забирает.", progress = "Ну и что сказал Дыбоволос?", completion = "Вот непруха... Наверняка это корсары... Дыбоволос тут ни при чем, я уверен, он не стал бы так меня обманывать. В конце концов, он получает деньги за доставку.\n\nПохоже, мне придется вернуть себе кое-какие товары. Что скажешь?", rewards = "Вы получите:\n\n"},
[893] = {title = "Предпочитаемое оружие", objective = "Принесите стилет Иглогривых, обгоревший жезл Иглогривых и боевой щит Иглогривых Таттернаку Стальному Горну в Лагерь Таурахо в Степях.", description = "Хотя говорят, что у свинобразов племени Иглогривых за Полями Великанов нет искусных кузнецов, они научились делать серьезное оружие. Мне хотелось бы получить несколько образцов, чтобы изучить их технику работы.\n\nЕсли ты стремишься к подвигам во славу Орды, добудь для меня их оружие. Мне понадобятся кинжал, жезл и щит. Этого вполне хватит!", progress = "У меня тоже есть сомнения насчет того, что жалкие иглогривые могли научиться кузнечному делу, но я выполняю приказы вождя, и потому стараюсь узнать побольше о племени Иглогривых.\n\nУ меня бывали задания и попротивней, но я с радостью выполняю их, чтобы служить народу орков.", completion = "Прекрасные, прекрасные образцы.\n\nСвинобразы куда более умелый народ, чем мне казалось.\n\nВот, возьми это и убирайся. Мне надо получше изучить это оружие. Похоже, мы недооценивали врага, а такие ошибки недопустимы.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМолот УничтоженияСветильник Вечного света\n\nВы также получите:\n\n"},
[894] = {title = "Самофланж", objective = "Получите доступ к терминалу в исследовательском центре Торговой Компании.\n\nПрилагается предмет: \n", description = "Торговая Компания устроила к северу отсюда, в юго-западной части Нефтяного болота, небольшой исследовательский центр. Я не очень хорошо представляю, чем они занимаются, но до меня дошли сведения, что они проводят эксперименты со штукой под названием \"самофланж\".\n\nЧто еще за самофланж? Как бы то ни было, я хочу исследовать его, а значит, мне надо его заполучить.\n\nМне удалось достать копию их руководства пользователя. Почитай его, там наверняка написано, как вытащить самофланж из терминала.", progress = nil, completion = "На панели управления в беспорядке разбросаны кнопки, рычаги и мигающие лампочки. Судя по маленькому индикатору, устройство работает в оптимальном режиме, а контрольные клапаны 1-3 открыты. В нижнем правом углу панели управления имеется небольшая замочная скважина.", rewards = "Вы получите:\n\n"},
[895] = {title = "РАЗЫСКИВАЕТСЯ: Барон Дольноберег", objective = "Принесите Газулу в Кабестан голову барона Дольноберега.", description = "РОЗЫСК! \n\nРазыскивается Барон Дольноберег, капитан \"Безрассудной\".\n\nКапитан Дольноберег из Гильнеаса водит корабли корсаров Южного моря. Он разыскивается по обвинению в пиратских нападениях. Предоставленные останки должны быть пригодны для опознания!\n\n- Газул.", progress = "Что происходит? Чем могу служить? Отправить груз, или, может быть, инженер понадобился?", completion = "А! Вот какое у тебя дело. Знаешь, я однажды видел \"Безрассудную\" в открытом море. Впечатляющий корабль. Или судно? Эти моряки так придираются к словам!\n\nВ общем, она так скользила по водной глади, что дух захватывало. Я рад, что ее проклятый капитан перестанет тревожить мои корабли.", rewards = "Вы получите:\n\n"},
[896] = {title = "Удача шахтера", objective = "Заберите изумруд \"Кошачий глаз\" у одного из надзирателей или головорезов Торговой компании и отдайте его управляющему пристанью Головокружилкинсу в Кабестане.", description = "Хозяин причала в таком оживленном порту, как Кабестан, держит руку на пульсе происходящего. Я в курсе всего товарообмена между нашим городом и Пиратской бухтой.\n\nПоследние слухи касаются Каменного карьера, принадлежащего Торговой Компании, что на северо-востоке от Нефтяного болота. Один из шахтеров нашел изумруд размером с твой кулак. Я знаю несколько покупателей на такой товар и готов поделиться с тобой комиссией.", progress = "Если бы мы знали, кто именно нашел этот изумруд, дело выеденного яйца не стоило бы...", completion = "Только посмотри, какой он огромный, Демонорох! Теперь мы разбогатеем! Ну-ка, судя по расценкам на драгоценные камни, я могу прикинуть твою долю... Пятьдесят процентов, будь спок!\n\nПосчитаем... Да, примерно так. С тобой приятно иметь дело, Демонорох.", rewards = "Вы получите:\n\nМешочек с монетами"},
[897] = {title = "Жнец", objective = "Принесите голову Жнеца Джорну Заклинателю Небес.", description = "Это странное, похожее на насекомое существо выглядит так, будто попало в Степи случайно.", progress = "Тебя что-то тревожит, Жрецплети. Как твои уроки в Степях? Что тебя так обеспокоило?", completion = "Не могу ничего сказать о природе этого зверя, ведь духа его и след простыл. Но ты верно говоришь, он не из Степей. Боюсь, наш народ ожидают испытания…\n\nА пока готовься к худшему. Будем надеяться, что со временем мы разгадаем тайну этого существа.", rewards = "Вы получите:\n\n"},
[898] = {title = "Свобода!", objective = "Проводите Гилтареса Огненный Цветок к капитану Сияющему в Кабестан.", description = "Наконец-то! Кто-то пришел мне на помощь!\n\nПоверить не могу, что тебе удалось пройти мимо стражей. Фанатики из Терамора совсем спятили. Они потопили наш корабль и меня, единственного выжившего, взяли в плен. Меня назвали врагом и угрозой безопасности Альянса.\n\nЯ! Угроза великому и могучему Альянсу? Я был матросом на грузовом судне, возившем самогон из Кабестана в Пиратскую бухту.\n\nДовольно болтать. Ты ведь поможешь мне вернуться в Кабестан? Скажи, когда решишь тронуться в путь, и мы совершим побег.", progress = "Да?", completion = "Подумать только, мы полагали, что Огненный Цветок давно погиб!\n\nТы заслужил уважение всех Тало'данских каперов, Ахахаха.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги с пряжкамиКлепаные рукавицы\n\nВы также получите:\n\n"},
[899] = {title = "Огонь ненависти", objective = "Принесите Манкрику с Перекрестка 60 клыков иглосвинов из племени Дыбогривых.", description = "Быть может, тебе знакома мука неопределенности, а может, и нет. Но знай: каждый день я стою здесь от восхода до заката и выискиваю взглядом этих чудовищ. Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть. Быть может, мне стоило идти не на север к Перекрестку, а в Таурахо.\n\nТы, <класс>, <мог/могла> бы мне помочь.\n\nУбей их. Убей как можно больше тварей. Принеси мне их клыки, и мы вместе попируем на их могилах.", progress = "Иглогривы за все заплатят, Ахахаха. Клянусь.", completion = "Шаман, ты отнесся к моему заданию серьезно, спасибо тебе за это.\n\nХотя жажда мести не утолена, я могу хотя бы улыбаться при мысли о том, что и иглогривы испытали ту же боль, что и я.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНакидка охотника на вепрейЛуговой кушак\n\nВы также получите:\n\n"},
[900] = {title = "Самофланж", objective = "Закройте топливный распределительный клапан, перепускной клапан и главный клапан управления, а потом снова попытайтесь воспользоваться панелью управления.", description = "В настоящий момент открыты три контрольных клапана. Суда по надписям на панели управления, их надо закрыть, прежде чем выключать прибор.", progress = "Судя по мигающим лампочкам на панели управления, основные клапаны не закрыты.", completion = "Лампочки, относящиеся к трем управляющим клапанам, медленно гаснут. Зеленый огонек становится желтым, и теперь можно повернуть рычажок, выключающий прибор. Клапаны закрыты, и терминал можно отключить.", rewards = "Вы получите:\n\n"},
[901] = {title = "Самофланж", objective = "Возьмите у ремонтника Угрелова ключ от терминала и отоприте им панель управления.", description = "Прибор выключен, и вы можете открыть панель управления и достать самофланж из терминала. Все бы хорошо, но чтобы отпереть терминал, нужен ключ.", progress = "Лампочки на панели потухли, стрелки всех приборов на нуле, все бездействует.", completion = "Повернув ключ в замке, вы открываете панель управления. В верхней части терминала гаснет красная лампочка. Теперь он полностью обесточен.", rewards = "Вы получите:\n\n"},
[902] = {title = "Самофланж", objective = "Отнесите самофланж Пароклапану в Кабестан.", description = "Под панелью управления оказывается мешанина проводов, ламп и прочих загадочных механических объектов – кажется, большая часть там вообще не нужна. Отодвинув их в сторону и сунув руку поглубже, вы находите самофланж. Одного рывка хватает, чтобы вытащить его из паза.", progress = "А, вот и ты, Демонорох! Принес самофланж?", completion = "Это... Э... Любопытно... Да. Я пошлю его в Союз ремонтников Нижней шахты. Не сомневаюсь, что эту штуку исследуют и поймут, для чего она нужна.\n\nВпрочем, сначала надо самому посмотреть что к чему...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМолот инженераСварной щит\n\nВы также получите:\n\n"},
[903] = {title = "Хищники Степей", objective = "Принесите 7 когтей хищников саванны Сергре Черный Шип на Перекресток.", description = "Пришло время поохотиться на тех, кто может постоять за себя. Хищники саванны, живущие в Степях – сильные звери. Сильные, могучие, хитрые и опасные. Их можно найти в высокой траве на юго-западе от Перекрестка.\n\nСоблюдай осторожность, иначе можешь неожиданно превратиться из охотника в дичь.", progress = "Как успехи на охоте? Удалось найти хищников?", completion = "А, вижу, ты времени даром не терял, а прятался в траве, выслеживая хищников. Как ты думаешь, пришло ли время встретиться лицом к лицу с сильнейшим из них?", rewards = "Вы получите:\n\n"},
[905] = {title = "Разъяренные смертехваты", objective = "Поохотьтесь на яркочешуйчатых ящеров и соберите с них перья. Отнесите перья в 3 гнезда когтедеров. Возвращайтесь к Сергре Черный Шип в Перекресток.", description = "Что ж, <имя>, теперь твоя задача усложняется. Сначала тебе надо победить свою добычу, а потом отыскать ее логово.\n\nЯ предлагаю поохотиться на яркочешуйчатых ящеров, живущих на юге. Убей их и забери перья. Отнеси перья в их гнезда на юго-западе от Застывшего оазиса. Покажи их сородичам, что ты не боишься!", progress = nil, completion = "Значит, ты побывал возле гнезд и поместил в них перья? На это требуется немало мужества.\n\nТы чувствуешь, что стал сильнее, Гронгард? Выглядишь ты куда крепче, чем в тот миг, когда явился сюда в первый раз. Думаю, Степи сыграли в этом свою роль.", rewards = "Вы получите:\n\n"},
[906] = {title = "Предатель в наших рядах", objective = "Отнесите череп Лока Торку на Перекресток.", description = "Отнеси голову Лока Торку на Перекресток, <раса>. *фыркает* Он-то без слов должен знать, что случилось с моим племенем; ха, он ни за что не поверит, что Кривозуб помог в *фыркает* таких вещах. Но я не сомневаюсь, что он наградит тебя за совершенный подвиг. *фыркает*\n\nПока я сижу в этой клетке, я и дальше буду благословлять тебя силой Агамаггана. Пока же прощай.", progress = "Да, что такое?", completion = "Тебе удалось найти главаря племени Иглогривых и собственноручно убить его, Ахахаха? Поразительно.\n\nУ меня нет слов, но это не значит, что я не благодарен тебе. Жители Перекрестка должны уважать твою силу.\n\nДолжен признать, я считал, что возглавляет налеты на наши обозы другой свинобраз. Еще раз спасибо, Ахахаха.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛубяной мундирМундир Сухого Мха\n\nВы также получите:\n\n"},
[907] = {title = "Разъяренные рокочущие ящерицы", objective = "Отнесите 3 порции крови рокочущей ящерицы Джорну Искателю Неба в Лагерь Таурахо.", description = "Пришло время выступить против рокочущих ящериц. Они столь огромны, что земля дрожит под их шагами. Сражаясь с ними, соблюдай осторожность: один неверный шаг – и они стопчут тебя.\n\nЯщерицы живут в южной части Степей. Их называют грозорылами, грозошкурами и громоголовами. Возвращайся ко мне с победой.", progress = "Тебе удалось одолеть рокочущих ящериц, Гронгард?", completion = "Я рад, что ты принес доказательство своего торжества. И особенно здорово, что у тебя все кости остались целы.", rewards = "Вы получите:\n\n"},
[908] = {title = "Среди руин", objective = "Принесите глубинный сердечник Дже'нею Санкрия в форт Зорам'гар, что в Ясеневом лесу.", description = "Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны Непроглядной Пучины. Их присуствие приведет лишь к тому, что Стихии озлобятся на нас. Если это так и оставить, то они захватят эти места навсегда.\n\n<имя>, ступай в Непроглядную Пучину и найди в руинах глубинный камень. Он должен быть где-то поблизости в воде. В нем находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий. Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[909] = {title = "Барон Акванис", objective = "Принесите странную водяную сферу Дже'неу Санкри в форт Зорам'гар, что в Ясеневом лесу.", description = "Сраженный элементаль воды оставил после себя странную сферу. Вы предполагаете, что этот предмет каким-то образо подпитывал тварь энергией. Внутри сферы плещется грязная на вид жидкость. Сама сфера вроде бы не поддается никаким физическим воздействиям.\n\nЕсли кто и сможет понять, что это за штука, то это Дже'неу Санкри из Служителей Земли. Он находится в форте Орды Зорам'гар в Ясеневом лесу.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСабля беззаконникаВедьмин палец\n\nВы также получите:\n\n"},
[910] = {title = "В порту", objective = "Отведите своего подопечного в порт Кабестана в Степях.", description = "Я слышал, что между Кабестаном и Пиратской бухтой плавают огромные корабли! Вот бы мне поплавать по океану и принять участие в морских боях. Может быть, когда я вырасту, я стану великим моряком Орды! Да!\n\nПожалуйста, своди меня в Кабестан, посмотреть на порт. Обещаю, я не свалюсь в воду и буду хорошо себя вести – мне бы посмотреть на корабли и вдохнуть запах соленой морской воды! Да!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[911] = {title = "Врата пограничья", objective = "Отведите своего подопечного к Заставе Мор'шан в северной части Степей на границе с Ясеневым лесом.", description = "Говорят, что Ясеневый лес – это новое пограничье, а врата к нему – Застава Мор'шан. Здорово быть первооткрывателем, добывать все необходимое из первозданного леса! Говорят, что именно там будут греметь битвы между Ордой и Альянсом. Вот бы мне попасть туда!\n\nОтведи меня к заставе Мор'шан, посмотреть на новое пограничье! Я хочу посмотреть, как Орда выгонит оттуда вонючих ночных эльфов!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[912] = {title = "Маска троггов из племени Камнедробов", objective = "Вы получите:\n\n", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗнание: маскировка под трогга из племени Камнедробов"},
[913] = {title = "Крик грозового змея", objective = "Отыщите и убейте грозового змея. Принесите его крылья Джорну Заклинателю Небес в Лагерь Таурахо.", description = "Грозовой змей – лютый зверь, <имя>. И все же ты уже <готов/готова> бросить ему вызов. Ступай, отыщи его и принеси мне крылья в доказательство успешной охоты.\n\nВыполни мое задание, и твое обучение подойдет к концу.", progress = "Задание выполнено? Тебе удалось убить грозового змея?", completion = "Тебе есть чем гордиться, ведь ты одолел всех врагов, явив силу, мужество и честь.\n\nНе останавливайся, следуй дальше по своему пути, Гронгард. Более того, жизнь настоящего охотника – постоянная борьба. Ступай же с высоко поднятой головой по избранному тобой пути.\n\nПора.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКобальтовый кулачный щитПосох укротителя ветрокрылов\n\nВы также получите:\n\nПерчатки луны"},
[914] = {title = "Повелители Змей", objective = "Принесите камни Кобрана, Анакондры, Пифаса и Серпентиса Наре Буйногривой, на Громовой Утес.", description = "Друиды в Пещерах Стенаний, Друиды Клыка поражены порчей. Когда-то они были частью ордена друидов давшего обет исцелить Степи, но теперь они хотят перекроить эти земли в соответствии со своими извращенными мечтаниями.\n\nУ Друидов Клыка четыре предводителя и каждый обладает Камнем Сновидения. Даже теперь их лица преследуют меня в кошмарах. Убей предводителей друидов, принеси мне их камни и в Степях снова воцарится мир.\n\nИди, <имя>,  и разыщи их укрытия в Пещерах Стенаний.", progress = "Меня преследуют воспоминания о моих кошмарах, Торгад. Удалось ли тебе убить  отступников и завладеть их кристаллами?", completion = "Ты сделал это, Торгад. Ты убил друидов Клыка, теперь мои сны свободны от их присутствия. Ты спас Степи, и я благодарю тебя от своего имени, от имени друидов Громового Утеса и от имени этой земли.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПосох ПолумесяцаКрыло-клинок\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[915] = {title = "Женщинам – цветы, детям -...", objective = "Купите своему подопечному клубничное мороженое. Кажется, мальчик предпочитает мороженое Тигуле и Форора.", description = "МОРОЖЕНОЕ! Пожалуйста, пожалуйста, пожалуйста, добудь для меня немного мороженого!!! Я больше всего люблю клубничное, а самое лучше клубничное мороженое делают Тигуле и Форор! Это мое самое любимое мороженое на свете!\n\nЯ пробовал его только один раз, когда меня водили на гонки на Мерцающей равнине, но говорят, его сейчас продают у нас в городе! Пожалуйста! Пожалуйста-препожалуйста! Преогромное пожалуйста!!!!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[916] = {title = "Яд чащобного паука", objective = "Принесите 10 ядовитых желез чащобных тенетников Гилшалану Буйному Ветру, стоящему у Альдрассила.", description = "Я пришел в Тенистую долину, чтобы наблюдать за чащобными тенетниками, обитающими в Паучьем логове. Они – родичи более мелких разновидностей пауков. Полагаю, что Древо Жизни оказало на них сильное воздействие... Я хотел бы получить несколько вещей, чтобы изучить их и подтвердить свои догадки.\n\nДля начала мне понадобится немного их яда. Добудь ядовитые железы у пауков-тенетников в Паучьем логове и вокруг него, к северу отсюда. После этого я смогу изучить эти образцы и понять, есть ли у этого яда сходство с ядом их более мелких сородичей.", progress = "Тебе удалось собрать ядовитые железы, Айлерон?", completion = "Благодарю тебя, Айлерон. Когда я вернусь в Дарнасс, я первым же делом сравню образцы яда из этих желез с ядами других пауков. Полагаю, что некоторые свойства яда связаны с ростом нового Древа Жизни.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКувалда ЧертополохаКинжал ЧертополохаПосох ЧертополохаКлинок Чертополоха\n\nВы также получите:\n\n"},
[917] = {title = "Яйцо чащобного паука", objective = "Принесите яйцо чащобного тенетника Гилшалану, стоящему у Альдрассила.", description = "Теперь, когда у меня есть паучий яд, мне хотелось бы получить для изучения живой образец. Не волнуйся, я не могу просить тебя поймать гигантского паука живьем. Да и мне самому вряд ли удалось бы справиться с таким \"образцом\"!\n\nНо если ты принесешь яйцо, из которого еще не вылупился паучок, то получить образец будет куда легче, не говоря уж о том, чтобы содержать.\n\nВ глубинах Паучьего логова должно быть гнездо. Прошу тебя, найди его, возьми оттуда яйцо паука и принеси мне.", progress = "Тебе удалось проникнуть в Паучье логово, Айлерон? А найти паучье яйцо?", completion = "О, отлично. Я отправлю яйцо и яд в Дарнасс, а потом и сам вернусь туда, когда мои изыскания здесь будут завершены. Я многого ожидаю от этих образцов, Айлерон. Твоя помощь оказалась поистине бесценной.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЩит лесничегоМундир лесничегоОдеяния лесничего\n\nВы также получите:\n\n"},
[918] = {title = "Саженцы древесника", objective = "Принесите 8 саженцев древесников Деналану к озеру Аль'Амет.", description = "Древесники Тельдрассила – духи Природы. Они в какой-то мере отражают естественный порядок жизни растений и животных на нашем великом древе.\n\nПотому меня очень тревожит, что древесники становятся такими озлобленными.\n\nМне кажется, что дело в почве. Я разными методами выращивал растения, и мне хотелось бы испытать эти способы на саженцах древесников. Не <мог/могла> бы ты собрать для меня этих саженцев вокруг озера Аль'Амет?", progress = "Ты добыл саженцы? Мне не терпится посадить их.", completion = "Ты их добыл. Славно!\n\nЯ посажу их в специально подготовленную почву. Уверен, что ростки потянутся вверх и вырастут в древесников, гораздо более послушных. Может, позже ты еще увидишь результаты!", rewards = "Вы получите:\n\nШляпка лесного гриба"},
[919] = {title = "Ростки древесника", objective = "Принесите 12 ростков древесника Деналану к озеру Аль'Амет.", description = "Вокруг вод озера Аль'Амет прорастают маленькие древесники. Боюсь, им уже не помочь, нам придется выдернуть их из земли прежде, чем они станут слишком большими и начнут приносить беды.\n\nКогда будешь бродить вокруг озера, выдергивай каждый росток древесника, что попадется тебе по дороге. Помоги очистить нашу землю!", progress = "Добро пожаловать, Айлерон. Нашел ли ты ростки у озера?", completion = "Как много! Они распространяются с ужасающей скоростью. Надеюсь, мне удастся разгадать, что же за порча поразила их.\n\nБлагодарю за помощь, Айлерон. Этот край благодаря твоим усилиям стал чище.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСадовые перчаткиСерокаменные наручи\n\nВы также получите:\n\n"},
[920] = {title = "Зов Тенарона", objective = "Поговорите с Тенароном Хваткой Бури. Он ждет вас на вершине Альдрассила в Тенистой долине.", description = "Ты <имя>, не так ли? До меня доходили слухи, что тебя искал Тенарон. Ты отыщешь его в самой верхней комнате на вершине Альдрассила.\n\nХоть мы и живем долго, не стоит заставлять Тенарона ждать.", progress = nil, completion = "А, Радиум. Я думал, что ты быстрее откликнешься на мой призыв. У меня есть важное задание, которое я хочу поручить тебе.", rewards = "Вы получите:\n\n"},
[921] = {title = "Венец Земли", objective = "Наполните хрустальный фиал и отнесите его Тенарону Хватке Бури, обитающему на вершине Альдрассила.", description = "Пришло время тебе отправиться на поиски своей судьбы, <имя>. Но чтобы подготовиться к встрече с миром за пределами наших зачарованных лесов, тебе нужно больше узнать о нашей недавней истории.\n\nМногое изменилось для нашего народа со времен битвы за гору Хиджал. Нордрассил ныне – лишь бледная тень того, чем он некогда был, его сила ушла на то, чтобы одолеть Архимонда и отбросить прочь Пылающий Легион...\n\nТебе нужно исполнить важное поручение. Принеси мне воды из лунного колодца к северу от Альдрассила.", progress = "Лунные колодцы содержат воду Источника Вечности, древнего источника магии, который навлек на наш мир так много ужасов.\n\nДруиды пользуются свойствами колодцев, а Стражи чтят их как святилища Элуны, но использовать магию колодцев запрещено всем.", completion = "Тебе уже довелось услышать первую часть истории о последствиях битвы за гору Хиджал, однако еще многое нужно рассказать, и выполнение задания, данного мной тебе, будет продолжаться на протяжении всего твоего путешествия через Тельдрассил в Дарнасс.", rewards = "Вы получите:\n\n"},
[922] = {title = "Релиан Зеленый Костер", objective = "Принесите росток древесника Релиану Зеленому Костру в Дарнасс.", description = "<имя>, не <мог бы ты/могла бы ты> доставить один из тех ростков, что ты <принес/принесла> мне, моему другу, Релиану Зеленому Костру? Он друид из Дарнасса. Когда мы в последний раз общались, он проявил интерес к моей работе с древесниками. У него самого кое-какие идеи есть, и он будет очень рад поработать с таким образцом.\n\nБлагодарю тебя, <имя>. Твоя помощь просто неоценима. Надеюсь, что однажды ты увидишь плоды моих трудов.\n\nРелиана обычно можно найти на какой-нибудь из дорожек анклава Кенария в Дарнассе, он любит там гулять.", progress = "Привет тебе...\n\nЧем могу помочь?", completion = "А, росток древесника? Я хотел попытаться сам вырастить древесника, чтобы помочь Деналану в его изысканиях.\n\nК сожалению, я выяснил, что множество древесников поражено порчей, и ростки таких существ также наследуют ее от родителей. И не в моих силах это исправить.\n\nУ Деналана великий талант работать со всем, что растет. Если кто и найдет исцеление для будущих древесников, то это он. Возможно, он -  наша последняя надежда.", rewards = "Вы получите:\n\n"},
[923] = {title = "Опухоли", objective = "Принесите 5 мшистых опухолей Релиану Зеленому Костру в Дарнасс.", description = "Древесники становятся все более злобными. Мы пытаемся найти источник этой беды, но пока... чтобы уберечь Тельдрассил, нам приходится уничтожать древесников, которым уже не поможешь. Те, что бродят вокруг Родникового озера на севере, поражены порчей сильнее всего. Их надо уничтожить!\n\nУничтожь всех древесников, которых там найдешь, и собери растущие на них мшистые опухоли. Принеси их мне, чтобы я мог их сжечь.", progress = "Ты был у Родникового озера, Плашмет? Удалось поохотиться там на древесников?", completion = "Хорошая работа! Эти опухоли – симптом болезни древесников. Они наполнены ядом, от которого мы должны очистить наши новые земли.\n\nЯ уничтожу эти опухоли. Благодарю тебя, Плашмет.", rewards = "Вы получите:\n\nОбрезной нож"},
[924] = {title = "Демоново семя", objective = "Возьмите треснувший камень силы, возложите его на алтарь Огня до окончания его действия и возвращайтесь к Ак'Зелоту.", description = "Демоново семя – страшное оружие Пылающего Легиона. Оно хранится в пещере на Вершине Багрового Тумана, над демоническим алтарем Огня.\n\nЯ подготовил камни силы, которые разорвут связь Семени с Легионом.\n\nВозьми камень со стола и возложи его на алтарь Огня на Вершине Багрового Тумана. Отправляйся на запад, а на развилке сверни на север. Вершина окажется по левую руку от тебя. Безопаснее всего подниматься по северному склону. \n\nТоропись: сила камня постепенно иссякает.", progress = nil, completion = "Твоя цель достигнута. Тебе удалось уничтожить Демоново семя, как велел Нииру. Но это еще не конец…\n\nПосле уничтожения Демонова семени по всему астралу пошли волны небывалой силы. Их почувствовала не только я. Об этом узнают те, чью игрушку мы сломали…\n\nВпрочем, невзирая на грядущие испытания, я хочу вручить тебе кое-что. Нииру велел дать это в уплату и поблагодарить тебя.\n\nИтак, я благодарю тебя.", rewards = "Вы получите:\n\nБроня банши"},
[925] = {title = "Отпечаток копыта Кэрна", objective = "Отправляйтесь в Громовой Утес и постарайтесь получить отпечаток копыта Кэрна Кровавого Копыта для своего подопечного.", description = "Говорят, что леди Кэрн Кровавое Копыто – один из величайших героев Орды. Когда я вырасту, я тоже хочу стать героем Орды!\n\nТы <знаком/знакома> с Кэрном? Окажи мне услугу! Возьми у него отпечаток копыта! Я не знаю, как его попросить, у него нет времени на таких, как я... другое дело ты! Ты <такой же искатель/такая же искательница> приключений, как и он! Готов поспорить, что тебе получить у него отпечаток копыта – раз плюнуть!\n\nПожалуйста!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[926] = {title = "Треснувший камень силы", objective = "Эти камни исполнены магической энергии, но в каждом из них есть умышленный изъян. Они не слишком стабильные, и если взять их со стола, они быстро поглотят сами себя.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nТреснувший камень силы"},
[927] = {title = "Сердце, поросшее мхом", objective = "Принесите поросшее мхом сердце Деналану к озеру Аль'Амет.", description = "Сердце Черномшеца Злосмрадного поросло темным маслянистым мхом. Понять, что это сердце, можно лишь по тому, что оно медленно и ритмично пульсирует... Даже сейчас. \n\nВозможно, это заинтересует Деналана.", progress = "О, Айлерон! Ты что-то мне принес?", completion = "...Это еще что такое? Сердце древесника? Оно все поросло вонючим мхом!\n\nХорошо, что ты принес его мне, Айлерон. Я исследую это сердце и, если удача повернется ко мне лицом, выясню, что это за мох на нем.", rewards = "Вы получите:\n\n"},
[928] = {title = "Венец Земли", objective = "Отнесите частично наполненный сосуд Коритрасу Лунному Гневу в Доланаар.", description = "Я мог бы поведать тебе еще многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждет тебя. Я перелил воду из фиала, принесенного тобой, в этот сосуд, чтобы ты <отнес/отнесла> его Коритрасу.\n\nТы найдешь Коритраса у лунного колодца в Доланааре. Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернет на запад, следуй по пути, мощенному булыжниками.\n\nИ советую тебе не сходить с дороги, <имя>, – в последнее время в лесу появились опасные существа.", progress = "Привет тебе, |3-6(Друид). Чем обязан удовольствию встречи с тобой?", completion = "А, понятно. Тебя послал Тенарон. Ну что ж, похоже, нам о многом нужно поговорить, многое сделать – но времени мало.\n\nДумаю, лучше не медлить и приступить к делу сейчас же.", rewards = "Вы получите:\n\n"},
[929] = {title = "Венец Земли", objective = "Наполните нефритовый фиал и принесите его Коритрасу Лунному Гневу в Доланаар.", description = "Сначала позволь поведать тебе, какая стоит перед тобой задача. Друиды Дарнасса пользуются водой из лунных колодцев Тельдрассила, и временами их колодцы надо пополнять. При помощи этих специально изготовленных фиалов ты сможешь набирать воду из лунных колодцев.\n\nОтнеси этот сосуд к лунному колодцу у деревни Звездного Ветра на востоке и набери из него немного воды, а затем возвращайся ко мне. Когда ты выполнишь это задание, я продолжу свой рассказ с момента, на котором его прервал Тенарон...", progress = "С возвращением, Айлерон. Исполнил ли ты поручение?", completion = "После битвы за гору Хиджал мы не знали, что делать дальше. Нордрассил дымился, опаленный огнем, и наше бессмертие – сама сущность нашего бытия! – было утрачено. \n\nИменно в эту пору испытаний Предатель вырвался из заточения и исчез Шан'до Ярость Бури. Настали темные времена.", rewards = "Вы получите:\n\n"},
[930] = {title = "Светящийся плод", objective = "Принесите светящийся плод Деналану к озеру Аль'Амет.", description = "Под ветками этого светящегося растения висит большой круглый плод.\n\nВы уверены, что Деналану захочется его изучить.", progress = "Похоже, ты что-то хочешь мне рассказать, Криворучка? Ты что-то знаешь о древесниках?", completion = "Ты нашел его на Тельдрассиле? Как интересно... Такой необычный плод. Может, семена занесло издалека? Может, даже из Азерота! И что-то в нем есть такое... похоже, на него как-то странно повлияли почвы Тельдрассила.\n\nСпасибо тебе, Криворучка. Теперь извини, мне нужно попристальнее его поизучать...", rewards = "Вы получите:\n\n"},
[931] = {title = "Мерцающий росток", objective = "Принесите мерцающий росток Деналану к озеру Аль'Амет.", description = "Росток этого дерева мерцает в сумраке леса, распространяя вокруг себя изменчивое, пульсирующее свечение.\n\nНаверное. Деналана интересует именно такой образец.", progress = "Ты что-то мне принес?", completion = "Где ты это нашел? Я не видел таких растений с тех пор, как жил на Болоте Печали. А это было много десятилетий назад! Удивительно, как он попал в Тельдрассил. Да еще вырос до такой величины!\n\nСпасибо тебе, Атрор. Прости мою немногословность, но мне не терпится провести кое-какие опыты с этим ростком...", rewards = "Вы получите:\n\n"},
[932] = {title = "Извращенная ненависть", objective = "Убейте лорда Меленаса и принесите его голову Таллонкаю Гибкому Корню в Доланаар.", description = "Должен предупредить тебя, <имя>, что это должно остаться только между нами. Сатиры и так уже причиняют нам немало неприятностей, а этот уж слишком близко к нашему дому рыщет.\n\nЕго зовут лорд Меленас. Он живет по соседству, в Пещере Бесов, где собрал шайку греллей-воинов. Его сердце чернее ночи, а замыслы – омерзительны.\n\nНайди его в пещере, прямо к северу отсюда, и принеси мне его голову!", progress = "Ты еще не убил лорда Меленаса? Необходимо убрать его быстро и тихо, Айлерон. Его существование – угроза всем нам.", completion = "Теперь, когда лорд Меленас упокоился навек, я могу заняться и другими делами. Прими мою благодарность, Айлерон.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДикие наручиПлетеные сапоги\n\nВы также получите:\n\n"},
[933] = {title = "Венец Земли", objective = "Наполните турмалиновый фиал и вернитесь к Коритрасу Лунному Гневу в Доланаар.", description = "К юго-востоку от входа в Дарнасс, на берегу Арлитириэнских прудов есть еще один лунный колодец. Стражам трудно наблюдать за этими местами из-за все учащающихся нападений и все большей злобности фурболгов из племени Кривой Сосны. \n\nБудь начеку во время поисков колодца и держи оружие наготове.", progress = "Поначалу на донесения об обезумевших фурболгах не обращали внимания. Кто бы мог подумать, что эти миролюбивые людомедведи могут впасть в бешенство? Сколько еще бед должно свалиться на наши головы?", completion = "Шан'до Ярость Бури так и не вернулся, и новостей про него до сих пор не поступало. Друиды были в смятении. После пропажи Малфуриона верховный друид Фэндрал Олений Шлем взял на себя руководство друидами, убедив Круг Древних на Темных Берегах, что нашему народу пора снова заполучить былую мощь и бессмертие.\n\nС одобрения Круга Олений Шлем и самые могучие друиды вырастили Тельдрассил, новое Древо Жизни.", rewards = "Вы получите:\n\n"},
[934] = {title = "Венец Земли", objective = "Наполните аметистовый фиал и принесит его Коритрасу Лунному Гневу в Доланаар.", description = "Но не все было ладно с Тельдрассилом. Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие. Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила.\n\nОднако, пока я об этом говорить не буду. Тебе нужно посетить последний лунный колодец, к северо-западу от Поляны Оракула. Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[935] = {title = "Венец Земли", objective = "Отнесите наполненный сосуд верховному друиду Фэндралу Оленьему Шлему в Дарнасс.", description = "Без благословения Алекстразы Хранительницы Жизни и Ноздорму Хозяина Времени Тельдрассил вырос с изъяном. Странные твари лезут из-под его корней, и бешеные фурболги нападают на проходящих мимо путников.\n\nМогу только надеяться, что верховный друид быстро найдет то, что ищет. Я наполню все принесенные тобой фиалы, чтобы ты <доставил/доставила> их в Дарнасс.\n\nОтнеси их к Фэндралу Оленьему Шлему, ты найдешь его в роще друидов.", progress = "Я не звал тебя, так что не понимаю, зачем ты пришел отвлекать меня разговорами.\n\nЧто бы там ни было, пожалуйста, побыстрее.", completion = "О, да, это та вода, о которой я просил. Тенарон и Коритрас улучили минутку передать ее... хотя гонца, может, и не самого надежного выбрали... хм-м.\n\nОднако теперь я могу вернуться к работе. Бремя бед Тельдрассила тяжким гнетом лежит на моих плечах. Но скоро я избавлюсь от этого ярма.\n\nВот, возьми. Может, тебе пригодится.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЯсеневый лукМолот Чащобы\n\nВы также получите:\n\n"},
[936] = {title = "Помощь верховному друиду Руническому Тотему", objective = "Поговорите с верховным друидом Хамуулом Руническим Тотемом в Громовом Утесе.", description = "Извини, <класс>, можно тебя на минутку?\n\nКругу Кенария в Громовом Утесе требуются такие закаленные путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем.\n\nЕсли тебя это интересует, отправляйся в Громовый Утес на Вершину Старейшин и поговори с самим Хамуулом.", progress = nil, completion = "Привет тебе, |3-6(Охотник)! Рад, что ты хочешь помочь нам в наших исследованиях. Дел у нас много, и я оказал бы тебе дурную услугу, если бы не предупредил, что работа опасная. Надеюсь, тебя это не отпугнет... Впрочем, судя по твоему виду, тебе не впервой встречаться с опасностями.", rewards = "Вы получите:\n\n"},
[937] = {title = "Зачарованная поляна", objective = "Соберите 6 поясов Кровавых перьев и принесите из часовому Арании Проблеску Солнца на Поляну Оракула.", description = "Меня отправили сюда с небольшим отрядом Часовых для защиты древа-оракула от гарпий, что устроили себе гнезда по всей поляне. Мы стараемся потихоньку вытеснить их отсюда.\n\nКогда древо-оракул попыталось послать гонца в Дарнасс, на него напала стая гарпий и растерзала.\n\nЕсли ты считаешь, что это задание тебе по плечу, иди к их гнездовью и принеси их пояса в доказательство своего подвига.", progress = "Их безжалостные когти и острые клювы могут оказаться для тебя трудным испытанием, Плашмет, но я верю, что ты с честью выдержишь его.", completion = "Ты столького достиг за такое короткое время! Это очень впечатляет, Плашмет. Хотелось бы мне попросить тебя задержаться здесь и помочь мне по службе... но я понимаю, что тебя ждут великие дела.\n\nЯ заметила, что Древо-оракул только что сбросило кусок коры. Несомненно, оно хочет, чтобы ты выполнил какое-то поручение для него. Поговори с ним.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКандальный ременьИспятнанная дождем накидка\n\nВы также получите:\n\n"},
[938] = {title = "Туманна", objective = "Проводите Туманну к Стражу Арании Проблеску Солнца к лунному колодцу близ Древа-оракула.", description = "Мех самки саблезуба имеет характерный серый цвет, сливающийся с фоном окружающего леса. Вы видите, что она сильно пострадала: глубокие рваные раны видны на ее спине и брюхе.\n\nОна смотрит на вас, и в ее голубых глазах читается глубокая мудрость. Похоже, она хочет следовать за вами.", progress = nil, completion = "О, благодарю тебя, Айлерон! Я так боялась, что уж больше не увижу мою Туманну, скорбела всем сердцем о ее гибели, о том, что навек разлучилась с моей верной спутницей... Я в неоплатном долгу перед тобой! Прими мою вечную благодарность.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШнуровые наручиУтесный кулачный щитПлащ разведчика\n\nВы также получите:\n\n"},
[939] = {title = "Флейта Ксаварика", objective = "Принесите флейту Ксаварика и 5 образцов уз Скверны нефритового огня Эридане Грусти Ветра в южную часть Оскверненного леса.", description = "Вы рассматриваете простую деревянную флейту, которую подобрали, сразив Ксаварика.\n\nУзловатое дерево кажется твердым, но когда вы вертите ее в руках, все спирали и полоски на флейте вдруг начинают вращаться и двигаться. Вас внезапно охватывает нехорошее ощущение...\n\nВы встряхиваетесь, уверенные, что это просто игра воображения.\n\nНо, возможно, у других сатиров найдется разгадка тайны вашей находки. Отнесите ее друиду Эридане Грусти Ветра, которая живет в южной части Оскверненного леса.", progress = "Что такое, |3-6(Охотник)? У тебя встревоженный вид.", completion = "Я чувствую страдания Дерев, Драгунов...\n\nДержать в руках эти предметы почти невыносимо...", rewards = "Вы получите:\n\n"},
[940] = {title = "Тельдрассил", objective = "Передайте отчет древа-оракула верховному друиду Фэндралу Оленьему Шлему в Дарнасс.", description = "Шум леса донес до меня весть о твоих подвигах, <имя>. Когда я ощутила, что гарпии покинули свои гнездовья, великий покой распространился по лесу и его обитатели снова ощутили себя в безопасности. Я боялась посылать очередное сообщение верховному друиду, но теперь я знаю, что ты доставишь его ему в целости и сохранности.\n\nПередай ему письмо и знай, что лес будет охранять тебя по дороге в каменные джунгли.", progress = "Хм-м... В тебе силен дух леса, |3-6(Друид). Что у тебя за дело к верховному друиду кальдораев?", completion = "Я-то думал, почему Древо-оракул так долго не связывается со мной... Сдается мне, что как только мы решаем одну проблему, немедленно возникает другая, еще более сложная.\n\nБоюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернем себе бессмертие. \n\nТем не менее, ты славно справился с заданием Древа-оракула, и за усердие тебе положена награда.", rewards = "Вы получите:\n\n"},
[941] = {title = "Сердце-семя", objective = "Посадите запятнанное сердце в кадку Деналана.", description = "Я удалил этот смрадный мох с сердца, но оно все еще остается запятнанным...\n\nПопытайся посадить его в мою кадку. Она наполнена плодородной землей, которая может очистить и исцелить это сердце.", progress = "Кадка полна земли, специально подготовленной Деналаном.", completion = "Вы сажаете сердце в кадку, и оно быстро в нее зарывается!\n\nЧерез несколько секунд оно снова выкапывается из земли – уже очищенное. Оно тихонько пульсирует... и вам хочется взять его в руки.", rewards = "Вы получите:\n\nСердце очищенного древесника"},
[942] = {title = "Рассеянный геолог", objective = "Отвезите таинственную окаменелость археологу Бутылопузу в Гавань Менетилов.", description = "Эта окаменелость поразительно похожа на другую, которую я однажды видел в Стальгорне. Геолог по имени Бутылопуз приносил ее на ежегодную конференцию Лиги Исследователей. Он был уверен, что в этой окаменелости скрыта мощь, которую можно каким-то образом высвободить.\n\nПоследнее, что я слышал, что Бутылопуз обосновался в таверне \"Большая вода\" и ждет, чтобы его сопроводили к раскопу Вельгара. Найдите его и покажите ему окаменелость, найденную Сомнамбулером. Может быть, он сумеет раскрыть секреты прошлого.\n\nКорабль в Менетилов отходит из Аубердина.", progress = "Что это там у вас, дружище?", completion = "О боги! Так вы говорите, эта вещь происходит из далеких земель Калимдора?\n\nПоразительно! Просто поразительно!", rewards = "Вы получите:\n\n"},
[943] = {title = "Рассеянный геолог", objective = "Археолог Бутылопуз в Гавани Менетилов хочет, чтобы вы принесли ему камень Релу и окаменелость Бутылопуза.", description = "Геолог Вельгар, который сейчас находится на раскопе в Болотине, держит окаменелость у себя. Когда я обнаружил камень Релу, то был уверен, что это ключ к тайне окаменелости.\n\nПока я шел по дороге к Вельгару, на меня напали ящеры, и реликвия пропала. Не знаю, какая из крапчатых тварей проглотила ее, но если вам удастся ее вернуть, я смогу высвободить силу этих артефактов.\n\nПринесите мне и камень Релу, и окаменелость, хранящуюся у Вельгара.", progress = "При помощи камня Релу я смогу раскрыть тайны моей окаменелости, а также и окаменелости Сомнамбулера с Темного Берега, Вродехант.", completion = "Великолепно, Вродехант!\n\nТеперь посмотрим, смогу ли я использовать камень, чтобы распознать силы, скрытые в окаменелостях.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДревний клинокДолото для черепов\n\nВы также получите:\n\n"},
[944] = {title = "Меч Властителя", objective = "Соберите информацию, а затем используйте фиал виденья для создания гадальной чаши. С помощью чаши поговорите с Ону.", description = "Очень странно, что наги появились здесь, на Темных берегах. Но еще страннее – клан Сумеречного Молота. Они поклоняются старым, очень старым богам этой земли. Богам, давным-давно низвергнутым.\n\nМеч Властителя, что к югу отсюда, – место, где пал один из этих древних богов.\n\nПойди туда и поищи других культистов Сумеречного Молота.\n\nВозьми этот фиал виденья. Используй его для создания гадальной чаши, когда разведаешь все у Меча Властителя. Посредством этой чаши поговори со мной.", progress = "Меч Властителя, Модерам.\n\nОтправляйся туда, а потом снова свяжись со мной.", completion = "Так ты обнаружил клан Сумеречного Молота у Меча Властителя?\n\nПлохо.\n\nДревний бог, пронзенный мечом, давно мертв, но это не значит, что исчезли и остатки его могущества.\n\nДолжно быть, клан Сумеречного Молота пытается найти его силу.", rewards = "Вы получите:\n\n"},
[945] = {title = "Спасение Тирелин", objective = "Помогите Тирелин спастись, а потом сообщите Тересиль у святилища Эссины, что ее сестра в безопасности.", description = "Помогите!\n\nЯ бродила у Меча Властителя, как вдруг меня окружили эти жуткие культисты. Счастье, что я умею отлично прятаться!!!\n\nМожете помочь мне отсюда выбраться? И еще, мне нужно будет сообщить моей сестре Тересиль, что я в порядке. Она в Ясеневом лесу, к югу отсюда, у святилища Эссины.", progress = nil, completion = "Моя сестра была – где? Тирелин любит бродить по всяким местам, но все-таки! Это же очень далеко, да и Меч Властителя – вовсе не безопасное место...\n\nНу, спасибо вам, Wrestlecake. С вашей стороны было очень любезно сообщить мне, что с ней все в порядке.", rewards = "Вы получите:\n\n"},
[947] = {title = "Грибы из пещеры", objective = "Принесите 5 ножек струпника и 1 мертвянку Баритасу Лунному Сумраку в Аубердин.", description = "Я тут составляю одно зелье, для которого нужны редкие грибы, растущие в одной-единственной пещере. Пещера эта находится за водопадом Скалистый, к востоку и чуть севернее в горах.\n\nЯ бы и сам туда пошел, но в Роще Древних мне порекомендовали держаться подальше от того места. Наши почтенные союзники чувствуют, что в этой пещере таится какое-то незнакомое зло.\n\nПрошу вас, <имя>, соберите для меня эти грибы. А в процессе заодно приглядитесь: может быть, вы сможете подтвердить опасения Дерев.", progress = "Вы еще не собрали грибов для меня, Wrestlecake? В пещеру ходили?", completion = "Большое вам спасибо, Wrestlecake. Это отличные экземпляры!\n\nКстати, когда вы были у водопада Скалистый, заметили ли что-нибудь, что могло подтвердить опасения Дерев?\n\nДерева мудры, но я надеялся, что на сей раз они ошибаются.", rewards = "Вы получите:\n\nПлащ пустошейГриб с красной шляпкой"},
[948] = {title = "Ону", objective = "Поговорите с Ону в Роще Древних.", description = "Ону, Древо Мудрости из Рощи Древних, знает о вашем путешествии к Скалистому водопаду и хочет поговорить с вами. Роща расположена к югу отсюда, у подножья гор.\n\nДерева терпеливы и мудры, <имя>. Но если Ону ищет вашего совета касательно того, что вы видели у водопадов, то, боюсь, дело срочное.", progress = nil, completion = "Wrestlecake. Ты здесь.\n\nХорошо.\n\nНам есть... что обсудить. Тебе и мне.", rewards = "Вы получите:\n\n"},
[949] = {title = "Лагерь Сумеречного Молота", objective = "Найдите подсказку в лагере клана Сумеречного Молота, расположенном у Меча Властителя.", description = "Что замышляет клан Сумеречного Молота у Меча Властителя, неизвестно. Но наверняка что-то недоброе\n\nОбыщите их лагерь у Меча Властителя... Ищите то, что может помочь нам понять их намерения.\n\nВедь мы должны узнать об их целях раньше, чем они выработают план действий.", progress = nil, completion = "Книга написана от руки на древнем языке и прекрасно иллюстрирована.", rewards = "Вы получите:\n\n"},
[950] = {title = "Возвращение к Ону", objective = "Принесите Ону лист с безумными письменами.", description = "Вглядываясь в сумеречный фолиант, можно сойти с ума. Буквы начинают плыть и плясать перед глазами даже после мельком брошенного взгляда, и некогда прекрасный орнамент принимает гротескные формы.\n\nВырвать одну страницу с безумными каракулями – вот и все, что вам удается сделать, пока вы не потеряли сознание.", progress = "Wrestlecake. Ты вернулся.", completion = "Неизученная первобытная магия окружает этот пергамент с письменами. Я чувствую, что над ним потрудились древние силы.\n\nБудем надеяться, мы сумеем раскрыть цель деятельности клана Сумеречного Молота на Темном Берегу.", rewards = "Вы получите:\n\n"},
[951] = {title = "Реликвии Матистры", objective = "Принесите Ону в Рощу Древних 6 реликвий Матистры.", description = "Пергамент, который ты <обнаружил/обнаружила> близ Меча Властителя, – страница древнего текста... написанная эльфами! Она отягощена проклятиями и загрязнена порчей клана Сумеречного Молота, но похоже, что служители культа используют древнюю эльфийскую магию для того, чтобы вернуть в наш мир своих древних хозяев.\n\nНаправляйся к руинам Матистры, расположенным к северо-востоку отсюда, и поищи в траве и средь разбитых камней древние реликвии. Изучая их, мы сможем выяснить, каким образом в клане Сумеречного Молота намерены использовать магию эльфов.", progress = "Вилдан. Ну что, удалось ли тебе что-то раскопать в руинах Матистры?", completion = "Благодарю тебя. Эти реликвии относятся к поре расцвета Матистры. Этот некогда могучий оплот эльфов давно разрушен, но остатки магии еще попадаются в руинах. Будем надеяться, что нам удастся раскрыть тайны этого места раньше, чем это сделают наши враги.\n\nБудь настороже, Астерикс.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПалка из твердой древесиныМеч лесника\n\nВы также получите:\n\n"},
[952] = {title = "Роща Древних", objective = "Доставьте письмо Фэндрала Ону в Рощу Древних на Темные берега к югу от Аубердина.", description = "Если уж у тебя нашлось время передать письмо для Древа-оракула, то, мне кажется, для тебя не составит труда отнести донесение в Рощу Древних на Темный Берег, прямо к югу от Аубердина.\n\nТы наверняка сможешь свободно добраться туда на гиппогрифе, я уверен, что ты сумеешь это сделать. Отнеси это Ону, Древу Мудрости. Он ждет от меня вести, точно так же, как я ждал вести с Поляны Оракула.", progress = "А. Разбойник. Чем может тебе помочь Ону?", completion = "А. Спасибо, Каззакс. Тем не менее, это странно. Верховный друид всегда так торопится. Лес знает, что всему свое время. Шан'до Ярость Бури это понимал.", rewards = "Вы получите:\n\n"},
[953] = {title = "Падение Амет'Арана", objective = "Изучите таблички, рассказывающие об Амет'Аране и его падении, а затем возвращайтесь к часовому Тише Лунный Клинок, находящейся на Темных берегах.", description = "К востоку отсюда находятся руины Амет'Арана. Сейчас их населяют неупокоенные духи высокорожденных, некогда живших в его стенах, но когда-то Амет'Аран был местом, где слуги Азшары свободно практиковались в своей могучей магии.\n\nМеня послали исследовать эти руины, и я наткнулась на две большие таблички, на которых была неразборчиво начертана история Амет'Арана и его падения. Пока я пыталась прочесть руны, на меня напали призраки, и я сбежала.\n\nПожалуйста, если можете, отправляйтесь в руины и расшифруйте таблички вместо меня.", progress = "Когда вы изучите таблички и узнаете о падении Амет'Арана, я пойду с этой информацией в Аубердин и сообщу Кругу Древних.", completion = "У нас очень немного записей, относящихся ко времени Войны Древних, а особенно – к периоду разрушения Источника Вечности. Что неудивительно, если вспомнить о том, какие ужасные события и катаклизмы тогда происходили.\n\nСпасибо вам, Wrestlecake. С вашей помощью моя работа здесь окончена, и я смогу представить Кругу Древних полный доклад.", rewards = "Вы получите:\n\n"},
[954] = {title = "Башал'Аран", objective = "Найдите источник странного синего свечения в руинах Башал'Арана.", description = "Руины Башал'Арана, расположенные к востоку отсюда, населены демоническими служителями зла. Злые духи и сатиры, обосновавшиеся там, питаются магическими энергиями Башал'Арана, и силы их растут от постоянной подпитки энергией.\n\nНо при этом я заметил, что к одному святилищу они не приближаются. На западной стороне руин, на вершине небольшого утеса, распространяется странное синее свечение... Там и должно быть объяснение нежеланию демонов приближаться к этому месту.\n\nЯ хотел бы, чтобы вы его исследовали.", progress = nil, completion = "Ахх... Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, любезный |3-6(ночной эльф)? На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение...\n\nНо, прошу вас, пусть мой грубый язык не заставит вас уйти. Очень уж много лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания.", rewards = "Вы получите:\n\n"},
[955] = {title = "Башал'Аран", objective = "Соберите 8 серег греллей для Астериона в Башал'Аране.", description = "Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы пределы твоего терпения. Скажем так: в моей долгой жизни было много страданий, и существование в этом призрачном обличье, быть может, самая ужасная из моих мук.\n\nХотя мои слова могут показаться лицемерием, я уверяю тебя, что был бы невероятно благодарен, если бы ты <помог/помогла> мне найти то, что держит меня здесь. Некая печать связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на ее след.", progress = "Когда я получу серьги, я применю заклинание, чтобы обнаружить местонахождение связывающей меня печати. Веками я мечтал о свободе, которую принесло бы мне разрушение печати... Быть может, эти века таким грузом лежат на моем разуме, что я уже никогда не приду в себя...", completion = "И правда... Грелли Башал'Арана не владеют тем, что я ищу... Однако недавно они были в контакте с этим. Недавно... Я имею в виду по меркам твоего времени, не моего. Для меня \"недавно\" простирается глубоко в прошлое, почти что в другую эру...", rewards = "Вы получите:\n\n"},
[956] = {title = "Башал'Аран", objective = "Добудьте древнюю печать из лунного камня и принесите ее Астериону в Башал'Аран.", description = "Если грелли вступали в тесный контакт с той силой, что запечатывает мою вечную тюрьму, то, подозреваю, я знаю, в чем дело. Несомнено эта печать находится во владении сатира, предводительствующего ими.\n\nЯ убежден, что моя догадка верна, <имя>. Она наверняка у одного из сатиров. Если ты сможешь ее добыть, то ты почти откроешь дверь моей темницы. Мне не сдержать слез...", progress = "Столпы этого святилища для меня – тюремная решетка, Wrestlecake. У меня нет сил их разрушить, и нет такой магии, чтобы сокрушить их...\n\nБольше тысячи лет я смотрю на них и думаю: если я переживу этот камень, буду ли я свободен? Или меня держит незримая решетка?", completion = "Мне трудно поверить, что вещь, которую я сейчас держу в руках, так долго держала меня самого... Не будем тратить времени, Wrestlecake. Когда печать будет уничтожена, я снова вольно смогу бродить по лесам.", rewards = "Вы получите:\n\n"},
[957] = {title = "Башал'Аран", objective = "Уничтожьте древнюю печать из лунного камня у древнего огня в Амет'Аране, затем вернитесь к Астериону в Башал'Аран.", description = "Эта печать, заточившая меня, некогда была изготовлена руками одного из самых могущественных высокорожденных. В Амет'Аране – точно таких же руинах к югу отсюда – до сих пор горит древний синий огонь. В этом огне печать может быть уничтожена.\n\nБудь осторожнее в тех руинах, <имя>...", progress = "По правде говоря, Девяностый, я боюсь... Боюсь, что твой приход – и все это – лишь плод моего воспаленного воображения. Можешь ли ты понять, какая это мука? Я... Пожалуйста, ступай скорее.", completion = "Я свободен, Wrestlecake! Я могу собственными глазами видеть, какие изменения произошли с нашим миром... Я узнаю только отдельные фрагменты. Подумать только, что когда я в последний раз гулял на свободе, еще существовал Источник и высокорожденные держали совет с Азшарой, нашей любимой королевой.\n\nЯ чувствую, что мой тюремщик, мой бывший хозяин, Атрикус, еще жив... Мое осознание безнадежности вскоре сменится мыслями о мести.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖилет исследователяПоножи босякаЭльфийский жезл\n\nВы также получите:\n\n"},
[958] = {title = "Инструменты высокорожденных", objective = "Добудьте 7 реликвий высокорожденных для Тандриса Ветропряда в Аубердине.", description = "<класс>. Вот задание, которое я вам поручаю.\n\nВидели ли вы руины Амет'Арана? Если нет – их можно найти на востоке от главной дороги, несколько к югу отсюда. Когда-то Амет'Аран служил домом для многих могущественных высокорожденных, а теперь это – памятник разрушению, совершенному их жалкими подражателями.\n\nМне говорили часовые, что духи высокорожденных по-прежнему обитают там и что они используют свои древние магические приспособления. Эти реликвии нужно конфисковать, чтобы мы могли их уничтожить.", progress = "Если бы инструменты их гибели были разрушены во время катаклизма, уничтожевшего наш мир... Тем не менее мы должны сделать все возможное, чтобы ужасы нашего прошлого не повторились в будущем.", completion = "Хотя это, безусловно, лишь игра моего воображения, я чувствую себя так, будто бы ощущаю в этих реликвиях ядовитое дыхание магии высокорожденных. Я их уничтожу, чтобы давно уснувшее зло больше никогда не пробудилось.", rewards = "Вы получите:\n\nМанжеты Плюща"},
[959] = {title = "Неприятности в порту", objective = "Оператор крана Биггльфузз из Кабестана попросил вас отнять бутылку портвейна 99-летней выдержки у Безумного Магглиша, который прячется в Пещерах Стенаний.", description = "Ой! \n\nКак видишь, у меня сегодня приключилась неприятность! Утром из Пиратской бухты пришла поставка. И какая! Никогда не видел столько ящиков. Я хотел побыстрее закончить, поэтому поднимал больше, чем следовало. В конце концов все рухнуло на землю.\n\nНе успел я оглянуться, как эта тварь, Безумный Магглиш, схватил бутылку портвейна 99-летней выдержки и бросился наутек. Я гнался за ним до самых Пещер Стенаний, но внутрь я не ходок.\n\nМожет, тебе хватит пороху, чтобы найти его?", progress = "Портовый начальник не дает мне покоя с тех пор, как Безумный Магглиш скрылся с этой бутылкой. Судя по всему, портвейн предназначался в подарок Газлоу самим бароном Ревилгазом. \n\nЕсли у тебя довольно смелости и терпения для поисков Безумного Магглиша и похищенного портвейна, я щедро награжу тебя.", completion = "Великолепно! И ведь меня едва не уволили! Теперь надо поскорее отнести подарок Газлоу.\n\nCпасибо, Кзар. Отличная работа!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[960] = {title = "Размышление Ону", objective = "Я размышляю над твоим заданием, Цитромон. Размышляю над причинами присутствия здесь клана Сумеречного Молота и нагов.\n\nКогда будешь готов, используй фиал виденья для создания гадальной чаши. Затем свяжись со мной с ее помощью.\n\nЕсли ты потерял свой фиал виденья, то у меня есть еще.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nФиал Виденья"},
[961] = {title = "Размышление Ону", objective = "Обнаружение культистов клана Сумеречного Молота беспокоит меня. Я должен поразмыслить об их намерениях...\n\nКогда у тебя будет больше информации, поговори со мной посредством гадальной чаши. Если тебе для создания чаши нужен фиал виденья, то... у меня есть еще.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nФиал Виденья"},
[962] = {title = "Змеецвет", objective = "Аптекарша Зама из Громового Утеса просит вас принести ей 10 змеецветов.", description = "Королевское фармацевтическое общество из великого Подгорода Лордерона направило меня сюда с очень необычной целью, <имя>. Возможно, вы сумеете помочь мне, а, стало быть, и Темной Госпоже в трудах на благо Отрекшихся.\n\nНе так давно я изучала редкий образец флоры под названием змеецвет. Я уверена, что в большом количестве это растение таит в себе великие возможности.\n\nУвы, змеецвет можно найти только в самых темных закоулках Пещер Стенаний, опасной системе подземелий в Степях.", progress = "Мне очень надеюсь, что вам удастся добыть достаточно змеецвета в Пещерах Стенаний. Я многих туда посылала, но никто не вернулся.", completion = "Ах, замечательные экземпляры! Вы хорошо поработали, Демонорох.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nПерчатки аптекаря"},
[963] = {title = "Во имя вечной любви", objective = "Освободите дух Анайи Вестницы Рассвета и принесите ее подвеску Кириллиану Белому Когтю в Аубердин.", description = "После битв за Источник Вечности я узнал, что Амет'Аран разрушен, жители его погибли – в том числе и моя возлюбленная Анайя.\n\nЯ никогда не думал, что и через тысячи лет воспоминания об Анайе будут тревожить мои сны. Бродя в помрачении рассудка по лесам на Темном Берегу, я очутился в руинах Амет'Арана... где и увидел неупокоенный дух моей любимой.\n\nЕе нужно освободить, но у меня просто рука не поднимается. Нужно уничтожить ее призрак.", progress = "С неизбывной печалью в сердце я последовал за Шан'до Яростью Бури в долгий сон, и взял свою боль с собой в сны, и спал на протяжении тысячелетий.", completion = "Благодарю тебя, Айлерон. Может быть, было бы лучше... если бы я сам это сделал. Но даже после прошедших тысячелетий у меня нет сил поднять руку на свою возлюбленную.\n\nПожалуйста, оставь меня наедине с моим горем...", rewards = "Вы получите:\n\nСлеза Горя"},
[964] = {title = "Фрагменты скелетов", objective = "Принесите 15 фрагментов скелетов аптекарю Дитерсу в Бастион в Западных Чумных землях.", description = "Чтобы отомкнуть двери Некроситета необходим Костяной ключ. Его делают из остатков скелета – точнее, нескольких скелетов – и вплавляют в прочнейший из металлов в подходящей форме. Чтобы ключ заработал, необходим перстень власти одного из тех существ, что могут открыть портал данной им силой.\n\nНо не будем отвлекаться, для начала нам понадобятся фрагменты скелетов. Для этой цели подойдут скелеты внутри Андорала, да и те, что снаружи.", progress = "Убивай больше и чаще, |3-6(Охотник). Нам понадобится солидный запас фрагментов скелетов для создания внешнего слоя ключа. Его же не зря называли Костяным ключом.", completion = "Отличные образцы! Теперь моя очередь – я закалю их особым образом, чтобы они смогли вынести процесс отковки, через который им придется рано или поздно пройти.\n\nТеперь придется отыскать подходящую форму для отливки. Я знаю одного гоблина-кузнеца из Танариса, который в прошлом делал формы для не менее жутких вещей. Его девиз – как у всех гоблинов – кто платит, тот и музыку заказывает.", rewards = "Вы получите:\n\n"},
[965] = {title = "Башня Алталакса", objective = "Найдите Балтула Удар Тени возле башни Алталакса на Темном Берегу.", description = "Привет тебе, <юный/юная:r> <раса>. Меня зовут Элисса Звездный Ветер, и моя задача – защищать Аубердин от всякого вреда.\n\nС этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда.\n\nНо он уже давно должен был вернуться. Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью. Я была бы тебе очень благодарна, если бы ты <смог/смогла> найти его и удостовериться, что с ним все в порядке.", progress = nil, completion = "Тебя прислала Элисса? Это хорошо. У меня есть для нее тревожные вести, но не было возможности передать их ей.", rewards = "Вы получите:\n\n"},
[966] = {title = "Башня Алталакса", objective = "Соберите 4 свитка истрепанного пергамента для Балтула Удара Тени возле башни Алталакса.", description = "Группа чернокнижников обосновалась вокруг и внутри башни. Я хотел было вернуться в Аубердин и доложить Элиссе раньше, но побоялся, что могу что-то пропустить, пока буду отсутствовать.\n\nДелгрен подозревал, что подобная компания может собираться у башни, но не знал, зачем.\n\nНесколько обрывков свитков пергамента, которые носят с собой чернокнижники, попали в мои руки, но мне нужно знать больше, чтобы разгадать эту головоломку. Однако я предостерегаю вас от попытки вторгнуться в саму башню: чернокнижники, засевшие там, гораздо сильнее!", progress = "Нашли ли вы у них еще свитки? Я смогу составить более целостное представление об этом культе, если вы сможете их найти.", completion = "Большое спасибо, Айлерон. Это должно пролить некоторый свет на то, чем занимается это сборище чернокнижников...\n\nХмм... Клан Темной Нити... Никогда раньше не слышал о такой группе. Пока у нас нет никаких сведений об их истории, практически невозможно сказать, в чем могут заключаться их планы.\n\nБольше нельзя тянуть. Нужно немедленно предупредить Делгрена.", rewards = "Вы получите:\n\n"},
[967] = {title = "Башня Алталакса", objective = "Доставьте письмо Балтула Делгрену Очистителю в Ясеневый лес.", description = "Мой хозяин, Делгрен Очиститель – паладин, любезно предоставивший свою помощь в защите наших лесов от сил демонов и нежити. Он многое поведал мне о Божественном Свете и воинском искусстве.\n\nДелгрен должен немедленно узнать о деятельности клана.\n\nВы найдете его далеко на юге отсюда, на Заставе Мейстры в Ясеневом лесу. Поторопитесь – я боюсь, что угроза клана Темной Нити растет с каждым часом.", progress = "У вас ко мне какое-то дело, |3-6(Охотник)?", completion = "Если позволите, я вам скажу: слишком уж вы хорошо экипированы для простого посланца, не так ли? Предполагаю, Балтул хотел быть уверенным, что его письмо действительно попадет мне в руки. Посмотрим, что он там пишет...\n\nДа, это тревожные новости. Когда обнаруживаются силы демонов или нежити, я помогаю часовым уничтожить их.\n\nВначале мне были непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников.", rewards = "Вы получите:\n\n"},
[968] = {title = "\"Подземные Силы\"", objective = "Принесите книгу \"Подземные Силы\" Геррику Костохвату в Заброшенный грот в Стальгорне.", description = "Хотя книга ужасно истрепана и исцарапана, ее название на обложке все же можно разобрать:\n\n\"Подземные Силы\".\n\nВ книге перечисляются непроизносимые имена со зловещими титулами, способами почитания и предпочтительными жертвоприношениями... И среди этих жертвоприношений числятся живые разумные создания.\n\nНа внутренней стороне обложки написано: \"Руны и Жребии Костохвата, Заброшенный грот, Стальгорн. Владелец: Геррик Костохват\".\n\nЕсли Костохват торгует подобными книгами, может быть, он выкупит эту?", progress = "Приветствую, сударь.\n\nМогу ли я заинтересовать вас каким-то из моих фолиантов?", completion = "А, экземпляр \"Подземных сил\". Интересный текст, да уж. А кое-кто найдет его и полезным тоже...\n\nНо эта книга в ужасном состоянии. И поглядите-ка! Заметки на полях – почти на каждой странице!\n\nХм... Я помню этот экземпляр. Я продал его Болгару в прошлом году. Вы его... его друг? Да, должно быть, так. У вас в глазах такой же огонь горит!\n\nНу, по определению, друг Болгара – мой друг. А мы должны поддерживать близких людей, правда?", rewards = "Вы получите:\n\n"},
[969] = {title = "Да пребудет с тобой удача!", objective = "Соберите 10 кристаллов великанов Ледяного Молота для знахарки Мау'ари из Круговзора.", description = "Ах, одного взгляда на тебя достаточно, чтобы сказать: ты захочешь себе счастливый оберег. Мау'ари всегда все знает! \n\nНа юг пойди – найдешь ущелье, а в нем гигантов, сделанных из кусков льда. Кристаллы можно отобрать у гигантов, но можешь собирать их и <сам/сама> в ущелье. Эти кристаллы имеют отличную отражающую способность. \n\nПринеси мне 10 кристаллов великанов Ледяного Молота, и счастливый оберег станет твоим.", progress = "Принеси мне кристаллы – и я расскажу больше тебе!", completion = "О да… сейчас я сделаю для тебя этот оберег. Погоди-ка!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[970] = {title = "Башня Алталакса", objective = "Добудьте светящийся самоцвет Души и вернитесь к Делгрену Очистителю на заставу Мейстры.", description = "Письмо Балтула приводит меня в ужас. Этот клан Темной Нити – сущее бельмо у меня на глазу, и его надо устранить! Мне приходилось иметь дело с мерзавцами из Темной Нити к северо-востоку отсюда в Ордиль-Аране. У одного из них есть самоцвет Души, в котором, как я думаю, заключается секрет силы клана.\n\nПринеси его мне, а уж я сумею разгадать его тайну.", progress = "Ну, как, удалось добыть самоцвет души?", completion = "Хмм, этот самоцвет Души наполнен какой-то темной магией. Давай-ка посмотрим, что в нем таится...", rewards = "Вы получите:\n\n"},
[971] = {title = "Знание в пучине", objective = "Принесите манускрипт Лоргалиса Геррику Костохвату в Заброшенный грот в Стальгорне.", description = "Насколько вам известно, я собираю знания. Древние знания. Могучие знания. Знания, что отворяют пути, знания, что могут пробудить Тех-Что-Спят.\n\nХодят слухи о старинном манускрипте Лоргалиса, будто бы он покоится в Непроглядной Пучине Ясеневого леса. Некогда там жили эльфы, но они давно уже мертвы. Эльфы эти обладали великим знанием, до того как их город превратился в руины.\n\nНайдите манускрипт в Непроглядной Пучине Сделайте это, и я не забуду вашей услуги. Даже после... скончания дней.", progress = "Долог путь до Ясеневого леса, и задача ваша нелегка. Но если вы доставите мне манускрипт, Нортон... Велика будет ваша награда.", completion = "Вы нашли манускрипт! Что за радостный день! Мы сделаем с него копии и распространим, и древнее знание Лоргалиса станет достоянием наших братьев и сестер!\n\nВы даже не понимаете, какую услугу нам оказали, Нортон. Но я надеюсь, что этот дар покажет вам всю глубину нашей признательности нашим союзникам.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКольцо воодушевления"},
[972] = {title = "Сапта воды", objective = "Возьми сапту воды и отыщи оскверненную заводь в Серебряном бору. Я возлагаю на тебя большие надежды, Ахахаха.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nСапта воды"},
[973] = {title = "Башня Алталакса", objective = "Принесите фолиант Илкруда Магтрулла Делгрену Очистителю на заставу Мейстры.", description = "Илкруд Магтрулл. Да, я знаю о нем. Это могучий орочий чернокнижник, который поселился в Святилище Огненной Расщелины, месте великого зла на юго-западе Ясеневого леса.\n\nДоныне он был не более чем досадной помехой, потому я и не трогал его, но, похоже, пришла пора с ним разобраться.", progress = "У тебя немного ошарашенный вид, Нортон. С тобой ничего не случилось?", completion = "Сегодня ты сделал большое дело, Нортон. Гордись – ты сразил могущественного чернокнижника.\n\nА теперь посмотрим, что сказано в записях Илкруда.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо СвященниковПосох Очистителя\n\nВы также получите:\n\n"},
[974] = {title = "Найти источник", objective = "Выясните, где находится точка самой высокой температуры на Вулкане Огненного Венца, по просьбе Кракла из Кратера Ун'Горо. \n\nДля измерения температуры щелкните по термометру правой кнопкой мыши. Проверяйте все жаркие точки, пока не будет обнаружена точка с самой высокой температурой.", description = "Эти горячие источники всегда были для меня загадкой! Откуда берется жар? \n\nЕсли учесть, что источники расположены совсем недалеко от Вулкана Огненного Венца, можно предположить, что их подогревает вулкан. Я разработал термометр, чтобы измерять температуру вулкана, и теперь хочу выяснить, в какой точке она наиболее высока. Термометр дает результаты по шкале Кракленгейта. \n\nВот, держи, отправляйся на хребет и выясни, где там точка с самой высокой температурой!", progress = "Я бы и сам пошел, но уж больно боюсь элементалей Огня!", completion = "Да, корреляция температур вулкана и горячих источников очевидна. Конечно, надо бы еще раз проверить правильность уравнений, однако создается впечатление, что расстояние и температура... Хмм...", rewards = "Вы получите:\n\n"},
[975] = {title = "Сокровище Мау'ари", objective = "Еще раз поговорите со знахаркой Мау'ари через минуту, чтобы получить счастливый оберег.", description = "А теперь, прежде чем я дам тебе этот вот оберег, объясню, как им пользоваться. \n\nЕсли он у тебя с собой, окажется, что определенные предметы будут в добыче с тех созданий, с которыми ты бой вести будешь. А если нет, то и предметов не найдешь. Понятно? \n\nТы узнаешь их по имени – они называются э'ко. Если найдешь такие – приноси Мау'ари, она поможет тебе найти им применение. \n\nПостой-ка тут, пока я твой оберег доделаю.", progress = nil, completion = "Вот и готово, Томпсон. Помни, ты должен носить его с собой. Почему бы тебе не отправиться обратно на природу из города и не посмотреть, что ты там обнаружишь?", rewards = "Вы получите:\n\nСокровище Мау'ари"},
[976] = {title = "Поставка для Аубердина", objective = "Поговорите с Делгреном Очистителем на заставе Мейстры после того, как проводите Фиро через Ясеневый лес.", description = "Делгрен попросил меня доставить письма и припасы часовому Звездный Ветер в Аубердин, но мне очень не хочется ехать в одиночку. В лесу опасные враги, а я не хочу, чтобы эти припасы и информация попали не в те руки.\n\nЕсли ты с остальными согласитесь охранять меня, то я смогу уехать прямо сейчас. Под вашей защитой я точно доставлю все это в Аубердин.", progress = "Часовым чрезвычайно нужны припасы, чтобы закрепиться получше на Темном Берегу.", completion = "Ты сегодня славно поработал, |3-6(Маг). То, что мы отослали в Аубердин, срочно необходимо для отражения темной угрозы, наводнившей лес.\n\nПрими это вместе с моей сердечной благодарностью.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСветильник Вечного светаБригантина Кора\n\nВы также получите:\n\n"},
[977] = {title = "Йети где-то рядом…", objective = "Добудьте 2 безупречных рога Йети для Юми Румпельшникер из Круговзора.", description = "Теперь, когда мне есть чем прикрыть механические движущиеся части, мне нужна только одна вещь. Ну, точнее, две. Два рога! \n\nСамые большие рога – у патриархов и матриархов клана, так что, естественно, именно их-то я и хочу. Эта разновидность йети обитает в пещере к юго-востоку отсюда. Их там очень много, ты без труда их отыщешь. \n\nПомни, я хочу самые красивые рога – пожалуйста, не приноси ни побитых, ни сломанных!", progress = "Я уже почти закончила прикреплять мех, Томпсон. Пожалуйста, поскорее принеси мне рога, что я просила!", completion = "Просто не могу дождаться, чтобы скорее показать своим друзьям! Погоди секунду, пока я прикреплю рога… \n\nКласс!", rewards = "Вы получите:\n\n"},
[978] = {title = "Осененные луной дикие совухи", objective = "Соберите в Зимних Ключах 10 светолунных перьев, принести их Эреласу Янтарному Небу в деревню Рут'теран.", description = "Перья диких совухов из Внутренних земель, кажется, содержат следы магии. Эти силы… непохоже, что создания способны их контролировать, больше похоже на то, что магия просто является частью их сущности. \n\nЗа время моих исследований я слыхал, что большая популяция диких совухов населяет заснеженные земли Зимних Ключей. Вдруг у этих существ есть те же свойства? Пожалуйста, <имя>, помоги мне найти ответ. Отправляйся в Зимние Ключи, собери выпавшие перья и возвращайся с ними ко мне.", progress = "И откуда только берется эта магия? Думаю, что мы на правильном пути к отысканию ответа, Эфром.", completion = "Теперь я могу сравнить перья между собой… Посмотрим-ка…", rewards = "Вы получите:\n\n"},
[979] = {title = "В поисках Раншаллы", objective = "Найдите Раншаллу в восточной части Зимних Ключей.", description = "Да-да, на эти перья, похоже, наложены точно такие же чары, как и те, что я прежде заметил… Поскольку я совершенно не уверен в том, что именно мы нашли, я очень хочу, чтобы ты <продолжил/продолжила> поиск ответов, <имя>. \n\nМоя коллега недавно отправилась в Зимние Ключи изучать там диких совухов в их естественной среде обитания. Может, ты нагонишь ее и выяснишь, что ей удалось узнать?", progress = nil, completion = "Привет! Вас прислал Эрелас?? Здорово, я как раз собиралась отправиться в пещеры, и я отнюдь не возражаю против компании.", rewards = "Вы получите:\n\n"},
[980] = {title = "Новые источники", objective = "Отправьтесь в Зимние Ключи и побеседуйте с Доновой Снегонорой.", description = "Слыхал я, что существуют и другие горячие источники – в местечке Зимние Ключи, далеко к северу отсюда. И вот в чем загвоздка – в тех местах нет никаких вулканов! Очень любопытно... \n\nЧто ж, тут можно сделать лишь одно – отправиться в Зимние Ключи и поговорить с моей тамошней приятельницей. Ее зовут Донова Снегонора, она живет прямо рядом с источниками. \n\nНу, счастливой дороги! Еще раз спасибо за помощь с термометром.", progress = nil, completion = "Здравствуй, Томпсон! Да, Кракл был совершенно прав...", rewards = "Вы получите:\n\n"},
[981] = {title = "Башня Алталакса", objective = "Поговорите с Делгреном Очистителем на Заставе Мейстры.", description = "За всю проделанную вами работу вы заслужили хорошую награду. Возвращайтесь к Делгрену и скажите ему, что Атрикус Нарассин лежит, сраженный вашей рукой, а клан Темной Нити сокрушен, и остатки его рассеяны.", progress = nil, completion = "Я знал, что вы возьметесь за это задание, Фальк.\n\nЯ чувствую, вас ждут великие дела и что вам суждено исцелить многие недуги, что терзают наши земли. Примите мое благословение, Фальк, и этот дар.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБогоугодные бриджиУдар серафима\n\nВы также получите:\n\n"},
[982] = {title = "Безбрежное море, глубокий океан", objective = "Добудьте денежный ящик \"Серебряной Зари\" и денежный ящик \"Туманной Пелены\" для Горбольда Стальной Руки в Аубердине. Оба предмета можно найти в останках потерпевших крушение кораблей к северу от деревни.", description = "У побережья Темного Берега, к северу от нас, есть остатки двух потерпевших крушение кораблей – \"Серебряной Зари\" и \"Туманной Пелены\". Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина. Теперь корабли лежат на дне океана, став добычей мурлоков\n\nОба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в денежных ящиках. Я хотел бы, чтобы вы добыли их для нас; это много значило бы для членов команды.", progress = "Капитаны тех кораблей были славными ночными эльфами, и они заслужили лучшую участь, чем та, что им выпала. Может быть, внимание, проявленное к их личным ценностям, – наилучший способ позволить их душам обрести покой.", completion = "Вы оказали нам огромную услугу, юноша. Мы позаботимся о том, чтобы за этими личными вещами был надлежащий уход.\n\nЧто же касается вас, прошу вас принять это. Это самое маленькое, чем я могу отблагодарить за смелость, проявленную ради восстановления справедливости.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки КапельРукавицы Носохвата\n\nВы также получите:\n\n"},
[983] = {title = "Жужжалка 827", objective = "Добудьте 6 ножек крабов и поместите их в Жужжалку 827.", description = "Слушай! Помоги мне с моим последним изобретением, Жужжалкой. С ее помощью можно общаться на расстоянии!\n\nМожет быть, ты уже видел их – такие ящики с рычагами. С ними одна проблема – за ними нужен постоянный уход.\n\nУ каждой из них есть своя проблема, но я нашел хитрое решение. Я поместил все машины в районе обитания существ, части которых нужны для починки каждой конкретной машины. Сейчас неисправна Жужжалка 827. Она находится чуть южнее Аубердина, совсем рядом с ним. Чтобы ее починить, нужно 6 ножек краба. Я заплачу...", progress = "Жужжалка 827 хранит зловещее молчание. Единственный мигающий индикатор показывает, что в приемник нужно поместить 6 ножек крабов.", completion = "Когда вы кладете ножки крабов в приемник машины, то слышите, как шестерни начинают их перемалывать. По нескольким хлопающим звукам вы решаете, что ножки краба уже нашли свое место. Вскоре машина начинает жужжать, и вы слышите голосок, едва доносящийся из машины.\n\n\"Алло! Уфф... Алло! Ты ее починил! Кстати, это Бацбах. Спасибо большое... Эй, не откажешься починить еще одну машинку?\"", rewards = "Вы получите:\n\n"},
[984] = {title = "Насколько велика угроза?", objective = "Найдите оскверненный лагерь фурболгов на Темном Берегу и вернитесь к Терентису в Аубердин.", description = "Некоторые из моих собратьев спаслись от порабощенных порчей фурболгов в Тельдрассиле, а я пообещал остановить злодеяния, пока кровь не полилась рекой... или не произошло чего-то еще хуже.\n\nЯ уже вижу признаки присутствия скверны на Темных берегах, но она еще не так распространилась. Я думаю, было бы логично продолжить исследования фурболгов. Может быть, ты найдешь один из их лагерей, а затем вернешься ко мне, если увидишь следы порчи?", progress = nil, completion = "Это и вправду ужасные новости, Wrestlecake.\n\nПоскольку фурболги находятся так близко к Аубердину, нам придется приготовиться к неизбежному.\n\nСпасибо вам, Wrestlecake.", rewards = "Вы получите:\n\n"},
[985] = {title = "Насколько велика угроза?", objective = "Убейте 8 следопытов и 5 заклинателей ветра из клана Чернолесья, а затем вернитесь к Терентису в Аубердин.", description = "Вы уже поднаторели в разведке на вражеских территориях, <имя>. Но способны ли вы не только следить за врагами, но и биться с ними?\n\nНе все искатели приключений предпочитают честную битву лицом к лицу искусству скрытности и уклонения.\n\nЕсли вы считаете, что готовы к сражению, то наибольшую угрозу нашему народу представляют сейчас фурболги в лагере к югу от Аубердина. Вы найдете там фурболгов Чернолесья. Убейте 8 следопытов и 5 заклинателей ветра, а потом возвращайтесь сюда, ко мне.", progress = nil, completion = "Смойте кровь с ваших доспехов, Wrestlecake, и не мучайтесь из-за содеянного. Вместо этого вознесите благодарность судьбе. Вы уменьшили угрозу нашему народу здесь, в Аубердине, даже если весь Темный Берег пока еще находится в опасности из-за Мха Скверны.", rewards = "Вы получите:\n\n"},
[986] = {title = "Пропавший хозяин", objective = "Найдите 5 прекрасных шкур лунопарда и принесите их Терентису в Аубердин.", description = "<имя>, ваше мастерство уже один раз сослужило мне хорошую службу в сложной ситуации. Могу ли я вновь возложить на вас задачу помочь Мрачнокогтю и его хозяину Волкору? Я могу сделать для вас волшебный плащ, который позволит вам беспрепятственно ходить вблизи враждебных существ Темного Берега, пока вы будете искать Волкора.\n\nДля изготовления плаща, чтобы хватило материала, мне нужно 5 прекрасных шкур лунопарда, снятых со взрослых самцов или матриархов. Этих кошек можно найти около Петляющей реки, к югу отсюда, или еще дальше на юг, близ Ясеневого леса.", progress = "В здравом уме я не позволю вам идти искать Волкора, пока не сошью для вас тот плащ.", completion = "Эти шкуры отлично подойдут, Wrestlecake. Я немедленно приступаю к работе над плащом.\n\nДайте мне немного времени, а затем возвращайтесь.\n\nДа, еще кое-что: после того как вы задействуете чары, наложенные на плащ, вы будете ограничены в своем взаимодействии с другими лицами. Если сможете, ограничьтесь только разговорами. Все, что сверх этого, может развеять чары.", rewards = "Вы получите:\n\n"},
[990] = {title = "Путь в Ясеневый лес", objective = "Найдите в Ясеневом лесу Раэну Волкопас.", description = "<имя>, моя госпожа – Раэна Волкопас – ожидает тебя в городе Астранаар, что в Ясеневом лесу. Возможно, с твоей помощью мы сможем хотя бы немного ослабить порчу, пустившую здесь корни.\n\nОтправляйся отсюда на юг и держись дороги – ты легко найдешь путь, если будешь держаться этого направления.", progress = nil, completion = "А, |3-6(Воин) с Темного Берега. Хорошо, что Селарин прислала тебя так быстро, Маладат. Прости, что тебе пришлось так спешить. Но с твоей помощью мы, возможно, сможем исправить положение.\n\nЯ бы начала с разговоров с другими жителями Астранаара. Многим наверняка понадобится твоя помощь.", rewards = "Вы получите:\n\n"},
[991] = {title = "Раэна – санитар Ясеневого леса", objective = "Найдите в Ясеневом лесу Терониса.", description = "<имя>, один мой старый друг тоже помогает часовым здесь, в Ясеневом лесу, но он еще не вернулся.\n\nОн думает отыскать один предмет, который, по его мнению, ослабит нападения фурболгов на наш народ – это жезл, сделанный ныне покойным злым волшебником. \n\nПрежде чем уйти, он упомянул, что будет искать драгоценный камень для жезла.\n\nОн также говорил, что камень может находиться в святилище на озере Фалатим у подножия западных гор. Камень хранился там до того, как святилище было разрушено. \n\nНайди моего друга, <имя>, пожалуйста.", progress = nil, completion = "Покрытое ранами тело Терониса лежит на острове. По какой-то непонятной причине мурлоки бросили его здесь.\n\nГлубокие резаные раны явно оставлены оружием и когтями мурлоков.", rewards = "Вы получите:\n\n"},
[992] = {title = "Исследование воды", objective = "Воспользуйтесь нетронутым устройством для поиска воды возле пруда на Заставе Скорбных Песков. Забрав пробу, отнесите устройство старшему геодезисту Рудознатцу в Прибамбасск.", description = "У нас, в Водной компании Прибамбасска, образовалась вакансия на должность младшего геодезиста на временную работу. Интересуешься?\n\nКочевники захватили все наши колодцы, приходится искать альтернативные источники воды! В пустыне есть вода, надо только ее отыскать!\n\nВозьми это устройство для поиска воды и принеси мне пробу из пруда возле Заставы Скорбных Песков. Правда, это место на виду у троллей. Когда закончишь, принеси мне включенное устройство!", progress = "Рад тебя видеть, младший геодезист Эфром! Ты уже выполнил задание?", completion = "Что такое? На тебя напали какие-то мерзкие ползучие твари? Ох, плохо это для Водной компании Прибамбасска, ох плохо…\n\nНадо было раньше тебя предупредить насчет этих кошмарных насекомых, которые, кажется, выпивают всю воду в пустыне. Сначала я не придал им значения. Нам хватает проблем и с кочевниками, и мы решили, что это тоже их происки. Теперь мы знаем правду!", rewards = "Вы получите:\n\n"},
[993] = {title = "Пропавший хозяин", objective = "Найдите Волкора на Темных берегах и отдайте ему зачарованный плащ лунопарда.", description = "Плащ готов, <имя>. Пришло время найти Волкора. Я могу только надеяться, что мы успеем.\n\nМагия, скрытая в плаще, если ее пробудить, продержится недолго: может быть, минут пять. <Сам/Сама> решай, когда использовать: я бы предложил подождать, пока не найдешь Мрачнокогтя.\n\nЕсли то, что он сказал мне – правда, ты найдешь его хозяина в пещере к югу отсюда. Мрачнокоготь будет ждать тебя у дороги. Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину.", progress = nil, completion = "Чудесно! Терентис прислал мне помощь!\n\nО, посмотри-ка, еще и плащ... *кашляет* Ох... Больно. Спасибо, Маладат.\n\nФурболги ранили меня, прежде чем я сумел от них улизнуть. Дай мне еще минутку, и я буду в состоянии разговаривать дальше.", rewards = "Вы получите:\n\n"},
[994] = {title = "Спасение с помощью силы", objective = "Защищайте Волкора, пока не доберетесь до дороги, а затем поговорите с Терентисом в Аубердине.", description = "Ладно, <имя>, силой так силой. Давайте убираться отсюда, как только вы будете готовы. Мы пробьемся к дороге – Мрачнокоготь должен все еще ждать. А там мы уже сможем разделиться.\n\nТерентис сразу же захочет услышать ваш рассказ, поэтому вы направитесь в Аубердин, когда мы отсюда выберемся.", progress = nil, completion = "Келегорм! Рад видеть вас живым и здоровым. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Темном Берегу и за его пределами.", rewards = "Вы получите:\n\nКушак непреклонности"},
[995] = {title = "Спасение с помощью скрытности", objective = "Совершите побег из пещеры фурболгов и встретьтесь в Аубердине с Терентисом.", description = "Ну, ладно... Если вы уверены, попробуем выскользнуть отсюда. Мы уйдем, как только вы будете готовы.\n\nНе забудьте после бегства отсюда вернуться к Терентису в Аубердин. А я туда отправлюсь сам по себе, потому что, вероятно, буду двигаться быстрее вас.", progress = nil, completion = "Мишкин! Рад видеть вас живым и здоровым. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Темном Берегу и за его пределами.", rewards = "Вы получите:\n\nБрюки Скарабея"},
[996] = {title = "Оскверненный ветроцвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[997] = {title = "Земля Деналана", objective = "Отнесите горсть редкой земли Деналану к озеру Аль'Амет.", description = "Так ты идешь на юг? К озеру Аль'Амет? Если да, то не выполнишь ли ты одну мою просьбу...\n\nМой собрат Деналан стоит лагерем у восточной оконечности озера, где изучает жизнь растений Тельдрассила и проводит свои эксперименты. Ему нужна редкая земля из Дарнасса, но ее доставили в Доланаар с опозданием – только что.\n\nНе <мог бы/могла бы> ты отнести ему эту землю?", progress = "Ты что-то мне принес?", completion = "Наконец-то! Я уже давно жду эту редкую землю. Надеюсь, она еще свежая...\n\nСпасибо тебе за доставку, Айлерон. Ты – |3-6(человек), не жалеющий времени на благие дела!", rewards = "Вы получите:\n\n"},
[998] = {title = "Оскверненный ветроцвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[999] = {title = "Когда сны превращаются в кошмары.", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1000] = {title = "Новое пограничье", objective = "Обратитесь к верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин Громового Утеса по поводу помощи Кругу Кенария в исследовании границ Калимдора.", description = "Внимание, герои!\n\nКруг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора – запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!\n\nВсе заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Хамуулу Руническому Тотему на вершину Старейшин Громового Утеса!", progress = nil, completion = "Здравствуй, |3-6(Воин).\n\nЯ рад, что героям, подобным тебе, небезразлична судьба природы. Слава о твоих великих деяниях летела впереди тебя, и тебе здесь рады. Узрев тебя, я исполнился уверенности, что Круг Кенария обретет нужную ему помощь.\n\nНаши связи с Кругом Кенария Лунной поляны превыше расовых и политических предрассудков. Помни это, трудясь во славу Круга, и будет тебе благо.", rewards = "Вы получите:\n\n"},
[1001] = {title = "Жужжалка 411", objective = "Добудьте 3 глаза крепкозуба с крепкозубов Темного Берега, которые водятся в море неподалеку от Жужжалки 411.", description = "Тоненький голосок пробивается откуда-то из глубины машины.\n\n\"Бацбах у аппарата! Следующая Жужжалка находится к северу от Аубердина, прямо на берегу.\n\nИтак, номер той Жужжалки – 411, и для ее починки нужно три глаза крепкозуба. Эти твари водятся недалеко от берега! Крепкозубы Темного Берега... *И-ик!* Извини...\n\nКак и в прошлый раз, когда поместишь в Жужжалку то, что нужно, она выдаст тебе награду. *И-ик!* Что? Не, со мной все в порядке!\"", progress = "Приемник машины открыт и, кажется, ждет, когда в него поместят 3 глаза крепкозуба.", completion = "Жужжалка оживает вскоре после того, как вы помещаете в нее глаза крепкозуба. После коротких помех вы слышите знакомый голосок.\n\n\"Вино из крабов лучше всего...\"*И-ик!*\n\n\"Что? О, ты уже ее починил! Ух, какой ты бысшшштрый. Так шшшо, согласишшшься почшшшинить ешшше одну?\"\n\nВы уверены, что слышите, как жидкость льется в емкость, а затем – звучные глотки.", rewards = "Вы получите:\n\n"},
[1002] = {title = "Жужжалка 323", objective = "Добудьте 6 клыков лунупарда и поместите их в Жужжалку 323.", description = "Жужжалка издает треск статических помех, и вы слышите голос Бацбаха.\n\n\"Шшшледуюшшшая жужшшшалка – номер 323. Она к шшшеверу от Аубердина, но... а хде жшшше эль? Шшшо? О, она шшштоит на дороге, так шшшо ты легко ее найдешшшь около мосшшшт\".\n\nБацбах что-то неразборчиво бормочет, а потом вы слышите отчетливый звук глотка.\n\n\"В эту нужшшшно положшшшить клыки лунопардов... шшшесть\".", progress = "Хотя вы еще не поместили внутрь Жужжалки клыки лунопардов, вам кажется, что оттуда раздаются звуки статических разрядов и невнятное гномье бормотание. Может быть, кто-то уже успел починить машину?", completion = "Неожидано Жужжалка начинает работать, и вы отчетливо слышите, как клыки перемалываются внутри машины в муку.\n\n\"Так шшшо, ты это шшшделал! Отлишшшные новосшшшти... И шшшо жшшше... ты не уходишшшь? А! Можшшшет, хочешшшь ешшше поработать?\"", rewards = "Вы получите:\n\n"},
[1003] = {title = "Жужжалка 525", objective = "Соберите 4 седых скальпа с седых колючешерстных медведей к югу от Аубердина и положите их в Жужжалку 525.", description = "Сквозь булькающий шум и звуки капающей жидкости, исходящие от машины, вы слышите неверный голос Бацбаха.\n\n\"Шшшледуюшший далеко на юг по доррроге. Найти должно быть нетрудно... шшшразу рядом на обочшшине... возле огражшшдения. Думаю, я шшпрятал его в каких-то кусшшштах... Кусшшшты... Хи-хи... Да, Жужжшшалка 525 снимет сшшшедые шшшкальпы с этттих сшшшедых колючешшшшерстныхх медведей. Божшшшежшшш мой, шшшто за пойло. Гнусшшшные... Хи-хи-хи...\"\n\nВы слышите звуки жадных глотков, и машина выключается. Затем, совершенно неожиданно, вновь оживает.\n\n\"Четыре!\"", progress = "Вы слышите пение, раздающееся из Жужжалки 525.\n\n\"Хотя изшшш крабов сладкое винннцо, из млатозшшшуба эль хоть куда, и сшшшамогонка лунная вкусна, но нет ничшшего лучше пива медвежшшшьего, и сшшшкоро будет оно у меня!\"\n\nЗаслонка открыта и ждет добытых вами 4 седых скальпов, а песенка звучит снова и снова.", completion = "Так ты шшшшо, положшшил шшшкальпы внутрь? Хорошшшо... Шо? Агга, я шшшоображшшаю, шшшо могу разшшшговаривать шшш тобой и безшшш материалов в машшшине. Но я пррравду грил, когда шшшказшшшал, шшшо они шшшломались!\n\nШшшмотри, кроме шшшредшшштв коммунимакации эти жужжшшшалки ешшше варят и дишшштиллируют отличшшшное питье. Просшшшти зшшша обман, но Ночшшшные эльфы не одобряют торррговли моими напитками в сшшшвоих городах. Я оставлю нечшшшто осшшшобенное в этом яшшшике, шшшобы показать мою благодарносшшшть за твои усшшшилия. Насшшшлаждайся!", rewards = "Вы получите:\n\nДжутовый мешок ВизбангаОсобое пойло Визбанга"},
[1004] = {title = "Новое пограничье", objective = "Поговорите с верховным друидом Хамуулом Руническим Тотемом на Вершине Старейшин Громового Утеса об исследовании пограничья Калимдора.", description = "Внимание, герои!\n\nКруг Кенария ищет отважных, которые помогут исследовать новое пограничье Калимдора! К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши. Круг нуждается в доблестных помощниках!\n\nВсе заинтересованные лица могут обращаться в Круг Кенария. Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утеса.", progress = nil, completion = "Здравствуй, |3-6(Маг)!\n\nПриятно видеть, что таким, как ты, небезразлично благополучие природы. Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады. Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается.\n\nНаша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий. Помни это, когда будешь действовать от имени Круга, – и добьешься успеха.", rewards = "Вы получите:\n\n"},
[1005] = {title = "Шныряющие за стеной", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1006] = {title = "Что скрывается за стеной", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1007] = {title = "Древняя статуэтка", objective = "Принесите древнюю статуэтку Талену в его лагерь близ Зорамского взморья.", description = "Я хотел бы дать тебе поручение, <имя>.\n\nЯ на своей маленькой лодочке плыл над затопленными руинами Зорама, когда на меня напали наги, выныривая из воды и вцепляясь в меня когтями! Я убежал, унеся с собой все, что смог, и чего хватило лишь вот на этот жалкий лагерь.\n\nНо когда я добрался до берега и побежал... я потерял одну дорогую мне вещь.\n\nПрошу тебя, <имя>, найди место засады – это на побережье к северу – и отыщи древнюю статуэтку. Именно из-за нее я отважился подвергнуть себя опасностям Зорамского взморья.", progress = "Ты снашел статуэтку, Wrestlecake?", completion = "Ты ее нашел! Спасибо тебе, Wrestlecake!\n\nДревний город Зорам хранит неисчислимые тайны, и эта статуэтка может послужить ключом ко многим из них.", rewards = "Вы получите:\n\n"},
[1008] = {title = "Зорамское взморье", objective = "Принесите 20 голов наг из клана Зловещего Хвоста Шиндрелл Огненный Всполох в Астранаар.", description = "По нашему северо-западному побережью, известному как Зорамское взморье, расползается зло.\n\nТам покоятся руины злосчастного города Зорам, разрушенного при Расколе и поглощенного морем. Для ночных эльфов он был утрачен на много веков. Утрачен и почти забыт.\n\nТеперь туда вернулись наги, и мы не знаем, почему. Но причина не так важна – мы должны перебить этих тварей и загнать их обратно в глубины!\n\nВозвращайся, когда выполнишь поручение.", progress = "Мы не можем допустить, чтобы наги наводнили наше побережье, Wrestlecake. Жизненно важно, чтобы ты отправился на Зорамское взморье, дабы довершить свое дело.", completion = "Отлично, Wrestlecake. Твои деяния против наг на Зорамском взморье достойны похвалы.\n\nЯ знаю, что задание выполнить было нелегко, ибо сила и коварство наг прекрасно известны ночным эльфам. Мы это знаем, ибо у нас одна история.\n\nНо эту историю я вспоминать не желаю.", rewards = "Вы получите:\n\n"},
[1009] = {title = "Руузель", objective = "Принесите кольцо Зорама Талену на Зорамское взморье.", description = "Боюсь, тайна этой древней статуэтки так и останется нераскрытой, если не нати ключа к этому древнему замку.\n\nЭтим ключом является кольцо – кольцо Зорама. Оно принадлежало правителям этого города до того, как волны Раскола поглотили его.\n\nДолгие годы кольцо считалось утраченным, пока наги недавно не нашли его.\n\nИх предводительница, Руузель, живет на острове на северной окраине Зорама. Прошу тебя, <имя>, добудь мне это кольцо!", progress = "Говорят, что кольцо Зорама является ключом к любому замку в этом городе. Ты добыл его, Wrestlecake?", completion = "Ты добыл кольцо! Спасибо тебе, Wrestlecake. Прошу, возьми вот это в награду и знай, что я никогда не забуду того, что ты делал сегодня.", rewards = "Вы получите:\n\nОдеяния Старины"},
[1010] = {title = "Батранов волос", objective = "Принесите 5 стеблей Батранова волоса Орендилу Широколисту в Ясеневый лес.", description = "Есть одна травка, что росла некогда в древних руинах Убежища Батрана на севере. Звалась эта травка Батранов волос и славилась тем, что лечила болезни души.\n\nВ этой деревне болеет ребенок, и сдается мне, что это болезнь не телесная. Не сходишь ли ты в Убежище Батрана и не поищешь ли Батранов волос? Мне он может понадобиться, чтобы вылечить ребенка.\n\nУбежище Батрана лежит к северу от заставы Мейстры и прямо к югу от границы с Темным Берегом.", progress = "Ты добыл Батранов волос, Wrestlecake? Ребенок слабеет с каждым часом...", completion = "Ах, ты принес эту травку! Теперь я сварю лекарство для ребенка, и будем молиться, чтобы отвар подействовал.\n\nИ... В Убежище Батрана – Отрекшиеся? Очень тревожная весть. Поистине, очень тревожная...", rewards = "Вы получите:\n\n"},
[1011] = {title = "Чума Отрекшихся", objective = "Принесите бутыль заразы Кайнету Штилю в Лесную Песнь.", description = "Отрекшиеся, нежить из Орды, проникли в Ясеневый лес, и рыщут среди развалин и курганов. Мы уверены, что их цель – распространить чуму по землям ночных эльфов. Мы должны убедиться в этом!\n\nОтрекшиеся разбили лагерь к югу отсюда, рядом с Обителью Дор'Данил, где они готовят яды и заразу и разливают их по бутылкам. Проложи себе путь в этот лагерь и укради бутыль с заразой. Принеси ее сюда. Я исследую ее и узнаю, для чего она.", progress = "Ты нашел лагерь Найлок? добыл бутыль заразы?", completion = "Очень хорошо, Найлок. Теперь, когда я проанализирую содержимое бутыли, станут понятны цели Отрекшихся!", rewards = "Вы получите:\n\n"},
[1012] = {title = "Безумные друиды", objective = "Убейте друидов: Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца, затем возвращайтесь к Кайнету Штилю в Лесную Песнь.", description = "Когда я боролся с ядами Отрекшихся, мне было видение. Я узрел друидов Обители Дор'Данил, они были отравлены... убиты нежитью! Теперь они стали блуждающими духами, разлученными с телами и обезумевшими от этого.\n\nЧтобы души этих друидов обрели покой, ты <должен/должна> войти в Обитель Дор'Данил и уничтожить ее некогда могучих предводителей – Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца.\n\nСделай это и возвращайся ко мне.", progress = "Страдания друидов Дор-Даниля все еще тревожат мои сны, Малагрис. Ты должен уничтожить их предводителей!", completion = "Я ощутил, как утихает боль обители Дор-Даниль, и понял, что ты выполнил свою задачу.\n\nТяжелое дело выпало тебе, Кулер, ибо духи, которых ты уничтожил, всего лишь жертвы злобы Отрекшихся. Но с их погибелью, будем надеяться, и другие безумные духи обретут покой.", rewards = "Вы получите:\n\nКлеймо Эмиля"},
[1013] = {title = "Книга Ура", objective = "Принесите книгу Ура хранителю Бел'дугуру в Район Фармацевтов в Подгород.", description = "<имя>, в крепости Темного Клыка хранится книга – книга Ура, я хочу видеть ее в своей коллекции. Ур был великим магом Даларана до того, как оказался в рядах Плети, и его труды по иным мирам представляют большой интерес... для некоторых Отрекшихся.\n\nОтправляйся в крепость Темного Клыка и найди книгу. Принеси мне ее, и я сообщу о твоих заслугах Темной Госпоже.", progress = "Нашел книгу, Вота?", completion = "Прекрасно. Эта книга будет прекрасным дополнением моей коллекции трудов Ура. Знания его были велики, однако ограниченность его сознания не давало ему обрести настоящую силу. Именно поэтому он не смог противостоять Плети. \n\nМы, Отрекшиеся, не можем позволить себе роскошь быть слабыми – ведь тогда нам не выжить... \n\nИ уж тем более не обрести власть.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСерые сапогиНаручи со стальными застежками\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1014] = {title = "Смерть Аругалу!", objective = "Убейте Аругала и принесите его голову Далару Ткачу Рассвета в Гробницу.", description = "Аругал по-прежнему сидит в крепости Темного Клыка. Мы не можем считать Серебряный бор стратегическим оплотом Темной Госпожи до тех пор, пока Аругал жив. \n\nЯ позабочусь о том, чтобы искоренить его магию, <имя>. Но сделать так, чтобы Аругал встретил заслуженную смерть – это я оставляю вам. \n\nОтправляйтесь в крепость Темного Клыка и положите конец скверным деяниям Аругала раз и навсегда. И принесите мне голову этого злодея!", progress = "Со смертью Аругала мы сможем укрепить власть Темной Госпожи в Лордероне.", completion = "Наконец-то Серебряный бор избавлен от злодеяний Аругала. Вы сослужили огромную службу Темной Госпоже, Торгад. Ваша стойкость будет вознаграждена.", rewards = "Следующее заклинание будет наложено на вас:\n\nЧародейский интеллект\n\nВы получите:\n\nПечать Сильваны"},
[1015] = {title = "Новые границы", objective = "Поговорите с верховным друидом Фэндралом Оленьим Шлемом из дарнасского анклава Кенария относительно призыва Круга Кенария к изучению окраин Калимдора.", description = "Внимание, герои!\n\nКруг Кенария ищет смельчаков, готовых исследовать окраины Калимдора! Забытые пустоши, полные неизвестных опасностей, лежат к западу от Tанариса и Прибамбасска. Круг Кенария призывает храбрых героев изучить эти земли.\n\nВсе желающие должны пройти собеседование в Круге Кенария. Обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнассе!", progress = nil, completion = "С чего вы решили, что я собираюсь тратить время на таких, как вы, |3-6(Охотник)? Хотя погодите...Дайте мне разобраться с моими повседневными обязанностями, и тогда, может быть, у меня для вас найдется пара минут. Нет, ну разумеется, благо Дарнасса, да что там – Тельдрассила! – это такая ерунда по сравнению с вашим желанием получить новую побрякушку...\n\nЭти недоумки из Лунной поляны, с их призывом на помощь, тратят мое время – не представляю, как выдержу все это?!", rewards = "Вы получите:\n\n"},
[1016] = {title = "Браслеты элементалей", objective = "Соберите 5 неповрежденных браслетов элементалей, а затем задействуйте на них гадальный свиток. После отнесите разгаданный свиток Стражу Велене Звездный Всполох в Приют Серебряного Ветра.", description = "Бозьми этот гадальный свиток – он поможет определить создателя этих элементалей. Но тебе понадобится кое-что взять у этих духов для фокусировки магии свитка – их браслеты прекрасно подойдут.\n\nХватит нескольких неповрежденных браслетов с этих существ. Другие для наших целей бесполезны, но зато у торговцев за них можно кое-что выручить, если пожелаешь продать. Как только ты добудешь неповрежденные браслеты, попытайся использовать свиток. Возвращайся ко мне с результатами, и мы продолжим.", progress = "Поскольку тебе придется разрушить браслеты, чтобы убить элементалей, наверное трудно будет найти те самые, в которых содержится информация, которая нужна для гадального свитка. Ты можешь выменять нужные тебе браслеты у кого-нибудь другого, но, может, у тебя есть уже разгаданный свиток?", completion = "Хорошая работа, Wrestlecake, это даст нам информацию, необходимую для того, чтобы раскрыть преступника. Ты не против помочь нам схватить мага, который наполнил наши пруды порчеными элементалями? У меня сердце сжимается при виде оскверненного Ясеневого леса и других мест, и я просто сгораю от нетерпения схватить волшебника, который так старается еще сильнее навредить этому краю. Мы заставим его за все ответить.", rewards = "Вы получите:\n\n"},
[1017] = {title = "Маг-призыватель", objective = "Убейте Сарилуса Грязнорожденного и принесите его голову часовому Велене Звездный Всполох в Приют Серебряного Ветра.", description = "Есть только один маг из нежити в Степях, способный наслать порчу на стольких элементалей воды. И он единственный, кому хватит дури попытаться это сделать. Сарилус Грязнорожденный, наверное, сидит на вершине Вершины Багрового Тумана, да смеется надо мной. \n\n<имя>, тебе придется проникнуть на вражескую территорию и уничтожить этого мерзавца. Мне надоела его бестолковость, и надо показать ему, что бывает с теми, кто донимает часовых. \n\nУничтожь его и принеси мне его голову. Но соблюдай осторожность, Орда может подкараулить тебя.", progress = "Дело сделано? Сарилус Грязнорожденный мертв?", completion = "Теперь эта мерзкая ухмылка навсегда стерта с его лица. Славное, воистину славное дело, Найлок. Возьми – это Свет Элуны, испей его, когда будет казаться, что всему конец, и смерть неминуема. Он спасет тебя по воле Богини.", rewards = "Вы получите:\n\nСвет Элуны"},
[1018] = {title = "Новое пограничье", objective = "Поговорите с верховным друидом Хамуулом Руническим Тотемом на Вершине Старейшин Громового Утеса об исследовании пограничья Калимдора.", description = "Внимание, герои!\n\nКруг Кенария ищет отважных, которые помогут исследовать обширное новое пограничье Калимдора! К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши. Круг нуждается в доблестных помощниках!\n\nВсе заинтересованные лица могут обращаться в Круг Кенария. Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утеса.", progress = nil, completion = "Здравствуй, |3-6(Охотник)!\n\nПриятно видеть, что таким, как ты, небезразлично благополучие природы. Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады. Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается.\n\nНаша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий. Помни это, когда будешь действовать от имени Круга, – и добьешься успеха.", rewards = "Вы получите:\n\n"},
[1019] = {title = "Новое пограничье", objective = "Обратитесь в дарнасский анклав Кенария к верховному друиду Фэндралу Оленьему Шлему по поводу помощи Кругу Кенария в исследовании границ Калимдора.", description = "Внимание, герои!\n\nКруг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора -запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!\n\nВсе заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнассе!", progress = nil, completion = "С чего ты решил, что я буду утруждать себя беседой с таким, как ты, |3-6(Жрец)? Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу! Ведь благополучие Дарнасса – нет, всего Тельдрассила – в сравнение не идет с важностью поиска этой пустяковины для твоей коллекции!\n\nСначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я еще и это сносить должен?", rewards = "Вы получите:\n\n"},
[1020] = {title = "Лекарство Орендила", objective = "Принесите лекарство Орендила Пельтуру Белой Луне в Астранаар.", description = "<имя>, я изготовил лекарство, которое, надеюсь, поможет больному ребенку. Отнеси его в Астранаар отцу ребенка, Пельтуру Белой Луне.\n\nЧтобы добраться до Астранаара, ступай по дороге сначала на юг, потом на восток.", progress = "Прошу прощения, но у меня нет времени на разговоры. Мое дитя, моя Релара смертельно больна!", completion = "Это от Орендила?\n\nОн славен знанием трав и лекарским искусством. Это лекарство вселяет в меня надежду, которой прежде у меня почти не было...", rewards = "Вы получите:\n\n"},
[1021] = {title = "Сатиры коварны! Дриады в опасности!", objective = "Найдите в Ксавиане Анилию.", description = "Послушай, я не знаю, кто ты, но мне нужна помощь. Мои сестры отправились отнять у одного сатира Ветвь Кенария. Они сказали, что скоро вернутся, но уже целых два дня прошло!\n\n<имя>, ты <должен/должна> найти их! Они искали развалины храма ночных эльфов в Ксавиане на северо-западе. Не знаю, что и думать. Найди Анилию, это она повела их на поиски.", progress = nil, completion = "Судя по зияющей в боку ране, Анилия на грани смерти.", rewards = "Вы получите:\n\n"},
[1022] = {title = "Воющая Долина", objective = "Отправляйтесь в Воющую Долину, изучите фолиант Мел'Тандрис, затем возвращайтесь к часовому Мелирии Ледяной Тени святилище Эссины.", description = "Хотя мы затратили много средств и сил на то, чтобы вытеснить остатки демонов из Оскверненного леса на север, успехи наши невелики. Нам удалось не допустить большую часть демонов в Ясеневый лес.\n\nНа севере, у границы Оскверненного леса, разрушенное святилище Мел'Тандрис захватили загадочные волколюди. Из-за их пронзительных воплей это место называют теперь Воющей Долиной. Фолиант Мел'Тандрис, что хранится в святилище может пролить свет на появление там волколюдей.", progress = "Фолиант святилища – таинственный предмет. Это не книга в привычном смысле слова. Листы фолианта были благословлены самой Мел'Тандрис, и в нем записаны важные события.\n\nМне трудно объяснить. Если вы пойдете к святилищу, то поймете.", completion = "Фолиант Мел'Тандрис действует странным образом. События, которые он записывает, события, которые он показывает... Никто тольком не понимает, почему он делает то, что делает.\n\nТем не менее, понятно, что предмет, который получила жрица Звездная Песня – эта коса Элуны – требует дальнейшего исследования.", rewards = "Вы получите:\n\n"},
[1023] = {title = "Раэна – санитар Ясеневого леса", objective = "Найдите светящийся самоцвет и вернитесь к Раэне Волкопас в Астранаар с дневником Терониса.", description = "Осматривая вещи Терониса, вы находите дневник, который все еще в неплохом состоянии.\n\nВы берете дневник и оставляете труп Терониса. \n\nОстается только найти камень, который искал Теронис. Раэна говорила, что он где-то здесь. Возможно, его забрали мурлоки...", progress = "Добро пожаловать, Wrestlecake.", completion = "Это ужасно, Wrestlecake. Теронис мертв?!\n\nМы оплачем его, когда придет пора, но сейчас надо сосредоточить усилия на другом. Я отправлю часовых за телом Терониса как можно скорее.\n\nУ тебя дневник Терониса и камень, который он искал. Как думаешь – ты сумеешь завершить его дело? Моя душа успокоится, если я буду знать, что он погиб не напрасно.", rewards = "Вы получите:\n\n"},
[1024] = {title = "Раэна – санитар Ясеневого леса", objective = "Найдите Шаэлдрин у лунного колодца на северо-востоке.", description = "Тебе придется провести исследование самостоятельно, но, судя по заметкам Терониса, следующим твоим шагом, похоже, будет поиск остальных фрагментов созданного Дартолом жезла. Я бы начала поиск от лунного колодца к востоку от озера Ирис. Когда будешь <готов/готова>, ступай по этой дороге и сверни на север у небольшого местечка для отдыха слева от тебя.\n\nДриада Шаэлдрин будет тебе лучшим, чем я, проводником. Найди ее.\n\nВозьми с собой этот самоцвет – он может понадобиться Шаэлдрин, если она решит помочь тебе восстановить жезл.", progress = "Здравствуй. Как поживаешь?", completion = "О, так тебя послала Раэна? Тогда это и правда серьезное дело. Чем я могу тебе помочь?", rewards = "Вы получите:\n\n"},
[1025] = {title = "Лучшая защита – нападение", objective = "Убейте 1 дозорного, 2 ведмедей, 10 тотемистов и 12 воинов из племени Гиблой Чащи, а затем вернитесь к Раэне Волкопас в Астранаар.", description = "Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе еще одно поручение, прежде чем ты отправишься к лунному колодцу.\n\nНа дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников. Их извращенный разум питается страхом, а кровожадность утоляется кровью невинных жертв.\n\nПомоги часовым защитить эти края, отплати этим чудовищам их же монетой.\n\nДумаю, их лагерь находится к югу от дороги... будь <осторожен/осторожна>.", progress = nil, completion = "Славная работа, Wrestlecake. Спасибо тебе.", rewards = "Вы получите:\n\nПодмокший кукурузный хлебДынный сок"},
[1026] = {title = "Раэна – санитар Ясеневого леса", objective = "Найдите деревянный ключ и обломок жезла Дартола прежде, чем вернуться к Шаэлдрин у Лунного колодца.", description = "Хотелось бы мне, чтобы у тебя были более хорошие новости.\n\nРаэна права, я знаю о творении Дартола и  древнях этих краев – или знала прежде. Они теперь все осквернены, их природа искажена.\n\nЕсли твоя цель – найти еще один фрагмент жезла, то тебе придется найти ключ, чтобы отпереть сундук, в котором он лежит.\n\nДеревянный ключ – на одном из древней к северу отсюда, близ Оскверненного леса. Как только добудешь его, ищи небольшую лощинку к западу от дороги близ границы Оскверненного леса... Сундук должен быть спрятан где-то там.", progress = "Меня беспокоит то, что древни подверглись порче. Хотелось бы мне побольше сделать для них.", completion = "Я рада твоему возвращению, Wrestlecake.", rewards = "Вы получите:\n\n"},
[1027] = {title = "Раэна – санитар Ясеневого леса", objective = "Найдите последний фрагмент жезла Дартола и вернитесь к Шаэлдрин у лунного колодца.", description = "Последний фрагмент жезла был отдан на хранение друидам Дор-Даниля. Я понятия не имею, где они его спрятали. Сожалею, что больше ничем не могу тебе помочь.\n\nМогу только сказать, что тебе следует идти по дороге, что ведет в Степи. Друиды скрывались к востоку от этой дороги, но они тебе уже не помогут – недавно их перебили... мне не очень хочется об этом думать.\n\nКогда найдешь последний фрагмент, принеси его мне, и я помогу тебе воссоздать жезл.", progress = "Ты нашел последний фрагмент жезла, Терраформ?", completion = "Ты нашел последний фрагмент? Тебе очень повезло... И Раэне тоже.\n\nКак понимаю, нам надо попытаться собрать его, да?", rewards = "Вы получите:\n\n"},
[1028] = {title = "Раэна – санитар Ясеневого леса", objective = "Найдите потаенное святилище и снова наполните чарами жезл Дартола.", description = "Вот собранный жезл, <имя>. Восстановить его было просто... Труднее будет найти святилище, в котором жезл можно будет наполнить силой.\n\nНо при твоих целеустремленности и усердии, после всех твоих достижений тебе не слишком трудно будет его найти.\n\nСтупай на юго-восток – там очень мало торных дорог, так что будь осторожнее – и посматривай на север. Святилище скрыто в горах, что окружают эту долину.\n\nКак только ты окажешься там, положи жезл в святилище... а остальное сделает магия. Хе-хе.", progress = "Вы ощущаете ненавязчивую, но мощную силу в святилище и окружающих деревьях.\n\nВы кладете жезл в святилище, и вас окутывает тихий звон, а святилище начинает светиться...", completion = "Когда свечение угасает, вы видите в купели святилища заново наполненный чарами жезл.", rewards = "Вы получите:\n\nЖезл Преображения Дартола"},
[1029] = {title = "Раэна – санитар Ясеневого леса", objective = "Вернитесь к Раэне Волкопас в Астранаар.\n\nПрилагается предмет: \n", description = "Советую тебе найти Раэну и сказать ей, что жезл воссоздан. Я уверен, она знает, куда тебе направиться дальше. \n\nУдачи, <имя>.", progress = nil, completion = "Ты собрал жезл, который отправил тебя искать Теронис? Это приятно слышать.\n\nТеронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели.", rewards = "Вы получите:\n\n"},
[1030] = {title = "Раэна – санитар Ясеневого леса", objective = "Найдите не затронутого порчей фурболга и поговорите с ним при помощи жезла преображения Дартола.\n\nПрилагается предмет: \n", description = "Увы, не могу сказать, что у него было на уме.\n\nЕсли он сказал правду о силе жезла, то тогда ты сможешь принимать тот или иной образ. Какой – не знаю.\n\nМожет, он намеревался использовать его мощь, чтобы подобраться поближе к этим мерзостным фурболгам, но даже не затронутые порчей существа убили бы его, не будь он осторожен. Дартол, превращенный при помощи жезла, должен был бы поговорить с фурболгом, не подпавшим под порчу Мха Скверны.\n\nНа мой взгляд, надо начать поиски к юго-востоку от озера Мистраль.", progress = nil, completion = "Да-да... ты мой сородич, но ты здоровый. Пока еще чистый.\n\nНе знаю, как уж тебе удалось избежать тех злодеяний, что ночные эльфы обрушили на наш народ, но я рад, что больше я не одинок.\n\nНынче порча бежит в жилах наших сородичей, малыш, порча, насланная на нас спесивыми ночными эльфами. Это они с нами такое сделали... Они виноваты в том, что меня изгнали из племени.\n\nПо ночам я по-прежнему вижу костры в темноте.", rewards = "Вы получите:\n\n"},
[1031] = {title = "Ветвь Кенария", objective = "Убейте Гелтариса и верните Ветвь Кенария Иллиане в святилище Эссины.", description = "Анилия кладет руки вам на плечи и привлекает вас к себе. Задыхаясь, она показывает на находящуюся на севере арку, затем глаза ее закрываются, и из последних сил она шепчет: \"Он забрал ее... Гелтарис...\" И в душе вы понимаете, что Анилия умирает, жаждая, чтобы Ветвь Кенария была возвращена дриадам.", progress = "Ты нашел их? Что сказала Анилия? Где она?", completion = "Анилия умерла? Нет, этого не может быть! Кажется, только вчера мы вместе бегали и играли в лесах!\n\nСчастливые дни теперь миновали...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВолшебное оплечьеРемень из яркой чешуи\n\nВы также получите:\n\n"},
[1032] = {title = "Убийство сатиров!", objective = "Принесите 16 рогов сатиров Иллиане в святилище Эссины.", description = "Поверить не могу – Анилии нет! Как часто мы вместе резвились в лесах... Я почти ощущаю... печаль. \n\nЯ знаю, от чего мне станет лучше. Пожалуйста, убей сатиров, что отняли у меня Анилию! Принеси мне их рога в доказательство своего деяния, и я буду навек тебе благодарна.", progress = "Пожалуйста, помоги мне отомстить за смерть Анилии.", completion = "Спасибо тебе, добрый |3-6(ночной эльф). Душа моей сестры возрадуется твоим деяниям.", rewards = "Вы получите:\n\n"},
[1033] = {title = "Слеза Элуны", objective = "Принесите Слезу Элуны Пельтуру в Астранаар.", description = "Я надеялся, что лекарство Орендила спасет Релару, но, боюсь, оно лишь немного ослабило болезнь, поселившуюся в теле моей дочери. Мы должны найти более мощное средство! К счастью, Орендил говорил мне, какие еще он попытается применить лекарства, если первое не поможет.\n\nСлеза Элуны – это такой камень, который можно найти только в одном месте – на острове в озере Ирис к востоку от Астранаара. Орендил сказал, что этот камень снимает порчу... прошу тебя, <имя>, принеси мне Слезу Элуны, и да покончит она с болезнью моей дочери!", progress = "Wrestlecake, ты нашел озеро Ирис? Ты принес Слезу?", completion = "О, ты нашел ее! Я опущу Слезу в отвар и буду молиться, чтобы он помог ей.\n\nСпасибо тебе! Спасибо тебе, Wrestlecake!", rewards = "Вы получите:\n\n"},
[1034] = {title = "Руины Звездной Пыли", objective = "Принесите 5 горстей звездной пыли Пельтуру в Астранаар.", description = "Слеза Элуны немного облегчила страдания моей дочери. Кошмары стали реже ее мучить, хвала богине. Но... лихорадка все еще сжигает ее.\n\nОрендил рассказал мне о морозной пыли, которую находят среди руин Звездной Пыли. Может, она усмирит лихорадку Релары. Собери немного этой пыли, прошу тебя, и принеси ее мне.\n\nРуины Звездной Пыли находятся на юге, <имя>. Да ускорит твой шаг Элуна!", progress = "Ты уже принес звездную пыль, Wrestlecake?", completion = "Ты принес пыль! Я сделаю из нее припарки – они должны унять лихорадку Релары.\n\nЕще раз спасибо тебе, Wrestlecake. Без твоей помощи мое дитя несомненно умерло бы.", rewards = "Вы получите:\n\n"},
[1035] = {title = "Зеркало Небес", objective = "Отнимите лунный камень Упавшего Неба у Чащобного Оракула и принесите его Пельтуру в Астранаар.", description = "Лихорадка Релары прошла, но она еще очень слаба. Я не верю, что только время вернет ей былую силу. Мне кажется, тут нужна мощь лунного камня.\n\nМы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники.\n\nИх предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их. Ты <должен/должна> отнять лунные камни у Оракула.\n\nИ, боюсь, для этого тебе придется его убить.", progress = "Ты сразился с Чащобным Оракулом, Нортон? Если так, до дай мне, пожалуйста, лунный камень. Релара при последнем издыхании!", completion = "О, Нортон, ты спас мою дочь! Я знаю, что сила лунного камня вернет моей дочери силы!\n\nМне никогда не отблагодарить тебя за все, что ты для меня сделал, но... пожалуйста, возьми вот это. После Релары это самое дорогое, что есть у меня.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБроня Трескучего КлючаЗвериные оковыСветящийся нарамник\n\nВы также получите:\n\n"},
[1036] = {title = "Суши весла, сухопутная крыса", objective = "Поговорите с командиром флота Фираллоном на борту \"Кровавой завесы\" на побережье Тернистой долины.", description = "<имя>... Да, я слышал про тебя. Говорят, что ты не друг Пиратской бухте – как и мы, пираты Кровавого Паруса. Командир флота Фираллон ищет здоровых и крепких воинов, чтобы послать их на особое задание.\n\nЗвучит заманчиво? Тогда отправляйся на \"Багровый Парус\" и поговори с ним. Он в одной из кают. Корабль на стоянке на Диком берегу к востоку отсюда, рядом с \"Буруном\" и \"Госпожой Удачей\".Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1037] = {title = "Велинда Песнь Звезд", objective = "Поговорите с Тин'тель Танцем Клинка на террасе Воинов в Дарнассе.", description = "Велинда Песнь Звезд была моей предшественницей здесь, в Ясеневом лесу. Поначалу казалось, что она держдит под контролем ситуацию в Оскверненном лесу, но понемногу ее усилия стали сходить на нет. И однажды она просто исчезла.\n\nМеня послали сюда продолжить ее труды. Однако, боюсь, я ничего не знаю об этой жрице. Возможно, Тин'тель Танец Клинка, одна из командиров часовых, знает подробности ее исчезновения, о которых не знаю я.\n\nНаверняка она поймёт значение такой информации.", progress = nil, completion = "Велинда Песнь Звезд? То, что эта жрица пропала некоторое время назад, известно всем. Что касается событий, окружавших ее исчезновение... Чтобы поделиться такой информацией, мне нужна веская причина.", rewards = "Вы получите:\n\n"},
[1038] = {title = "Эффекты Велинды", objective = "Поищите в сундуке Велинды ее дневник, затем принесите его вместе с ключом Тинтэль Танцующий Клинок в Дарнасс.", description = "Значит, это ты вычитал в фолианте Мел'Тандрис? Думаю, ничего страшного не будет, если ты осмотришь ее вещи. Этот ключ позволит тебе отпереть сундук, в котором она держала свои пожитки в казарме часовых. Она вела дневник, и если что-то можно узнать, то только из него.\n\nДолжна тебе сказать, что часовые считают, что у нее была причина уйти, и ждут ее возвращения в любой момент. Эта жрица многими своими делами заслужила наше доверие.", progress = "Что удалось найти?", completion = "Похоже, что исчезновение Велинды – не столь безобидное дело, как казалось поначалу. Но я все равно не могу поверить, что она плохо кончила. Может, нам лучше будет найти ее?\n\nWrestlecake, раз уж ты проявил живой интерес к этому делу, то я была бы рада заручиться твоей поддержкой.", rewards = "Вы получите:\n\n"},
[1039] = {title = "Порт в Степях", objective = "Поговорите с управляющим пристанью Головокружилкинсом в Кабестане.", description = "Кабестан – единственный порт в Степях. Скорее всего, Велинда нашла там торговое судно, которое шло в бухту Черноводья в Азероте. Мы ограничили сделки с гоблинами, которые руководят портом, но смотритель пристани наверняка знает, какие пассажиры взошли на борт, а какие сошли на берег.\n\nСледуй по дороге на юго-восток через Ясеневый лес, и попадешь в Степи. Смотри по сторонам, <имя>, эти края патрулируют солдаты Орды. Но в порту ты будешь в безопасности.", progress = nil, completion = "|3-6(ночной эльф)? Должен сказать, твоих сородичей тут у нас нечасто увидишь. Кого-то ищешь, да? Минуточку, сейчас гляну в своих учетных списках.\n\nЧерез порт проходит куча народу, так что подожди минутку, сделай милость.", rewards = "Вы получите:\n\n"},
[1040] = {title = "Дорога до Пиратской бухты", objective = "Плывите в Пиратскую бухту и поговорите с караванщиком Раззготом.", description = "А, наконец-то, нашел. Надо было сразу сказать, что она проезжала здесь давно. Посмотрим.\n\nВелинда. Оплатила проезд до Пиратской бухты на \"Черной Скопе\". Никаких дополнительных пометок нет – значит, она благополучно добралась до места назначения. \n\nБольше ничем я помочь не могу, хотя она спрашивала, какие средства передвижения есть по ту сторону моря, и я упомянул Раззгота, водящего караваны из Пиратской бухты. Быть может, Велинда отправилась с ним. \n\nНу все, давай, иди. Не весь же день с тобой болтать.", progress = nil, completion = "Да? Не похоже, чтобы ты хотел отправить какой-нибудь груз, так что ты либо хочешь устроиться подработать в мой караван – а сейчас работы нет, – либо не к тому обратился.\n\nЯ угадал?", rewards = "Вы получите:\n\n"},
[1041] = {title = "Путь каравана", objective = "Поговорите с клерком Далтри из Темнолесья.", description = "Оказывается, я ошибался насчет тебя, а я это не часто признаю.\n\nОказывается, я помню эту Велинду. Не каждый день жрица ночных эльфов желает отправиться в путь со старым грязным – но превосходным для транспортировки товаров – караваном вроде моего.\n\nПо пути на север мы разделились, и она направилась в Темнолесье. Тамошний клерк ведет записи. Может, он знает что полезное.\n\nОсторожнее в джунглях, они даже в лучшие времена – опасное место.", progress = nil, completion = "В последние годы случилось много странного, и я стараюсь вести записи про всех чужаков. Никогда не узнаешь, что пригодится... Хотя когда эти записи оказываются нужны, добра не жди... Нет, про вашу Велинду я не хочу сказать ничего дурного.", rewards = "Вы получите:\n\n"},
[1042] = {title = "Семья Карвин", objective = "Поговорите с Джонатаном Карвином в Темнолесье.", description = "Нет, у меня не сохранилось записей о пребывании Велинды Песни Звезд в Темнолесье... Хотя, прошу прощения за прямоту, не могу представить, чтобы жрица ночных эльфов снимала комнату в гостинице, если ты понимаешь, о чем я.\n\nА вот о волко-людях я слышал, и не раз. Только недавно Калор явился в город, неся целую связку их голов. Он работает на Кэрвинов. Они охотятся на демонов и прочих чудовищ. Поговори с Джонатаном, он глава их дома.", progress = nil, completion = "Темные настали времена. Каждая ветвь в лесу нашептывает дурные вести, зло таится под каждым камнем.\n\nИ в такую пору незнакомец приходит в мой дом и задает вопросы про воргенов... Прощения за свои подозрения я просить не буду, зато потребую ответить на них.\n\nИ получу ответ.", rewards = "Вы получите:\n\n"},
[1043] = {title = "Коса Элуны", objective = "Отыщите признаки местонахождения Косы Элуны и вернитесь к Джонатану Карвину в Темнолесье.", description = "Кажется, ты говоришь правду... Я не до конца понимаю твои мотивы, но если ты <готов/готова> избавить Сумеречный лес хотя бы от небольшой части воргенов, я не буду допытываться. Важен результат.\n\nВоргены захватили рудник на юге. Они появились внезапно, но, насколько нам известно, нашествие началось именно с рудника.\n\nСтупай по своим делам, но если найдешь что-нибудь важное, расскажи об этом мне. Мы готовы принять любую помощь в нашей войне с силами зла.", progress = nil, completion = "Интересные вещи ты рассказываешь, |3-6(Друид). Хотя семья Карвин не настолько влиятельна, чтобы добраться до корня проблемы и решить ее раз и навсегда, мы делаем все, что в наших силах, чтобы уменьшить число воргенов в Сумеречном лесу.\n\nЯ уже велел Калору уделить этому первоочередное внимание.", rewards = "Вы получите:\n\n"},
[1044] = {title = "Полученные ответы", objective = "Вернитесь к Тин'тель Танцу Клинка в Дарнасс.", description = "Мы разберемся с воргенами, не беспокойся. Искореним зло, которое твоя подруга невольно принесла в наши леса. Мы не в обиде на нее. Странные вещи творятся в наши времена, <имя>, и тьма не ведает пощады.\n\nНе буду тебя задерживать. Уверен, многие захотят узнать о том, что ты <обнаружил/обнаружила> в рудниках Сумеречного леса.", progress = nil, completion = "Так вот какова судьба Велинды? Верховная жрица огорчится, услышав об этом – они очень дружили до исчезновения Велинды. И все же Коса Элуны несомненно была дарована Велинде нашей богиней, и очень плохо, что этот священный предмет попал в недобрые руки.\n\nВпрочем, это отдельный разговор. Я премного благодарна тебе за твои достижения.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛук ЛунарисаЖезл Лунного луча\n\nВы также получите:\n\n"},
[1045] = {title = "Раэна – санитар Ясеневого леса", objective = "Убейте Рэна Кровавого Клыка, 4 кровозубых стражей и вернитесь к Кролгу у озера Мистраль.", description = "Ночные эльфы стары, как время, но их надменность разрушает их собственный мир. А теперь еще и наши жизни. Но это уже никак не получится контролировать...\n\nЯ много в чем могу обвинять эльфов, но мы все равно отвечаем за свои деяния. Даже не подвергнувшись порче, мы способны творить великое зло.\n\nРэн Кровавый Клык – такое зло. Жаждущий мощи, алчный... порча только сделала его сильнее. Меня сжигает ненависть к эльфам, но я не хочу зла их детям, так что сами должны обуздать своих.", progress = "Ты еще не убил Рэна?\n\nДаже ночные эльфы не заслуживают его злобы. Его ненависть пылает даже ярче моей, но он уже не владеет собственным разумом. Он – угроза для всех исконных обитателей этого леса.", completion = "Хорошая работа.\n\nЛес все еще осквернен, но мы по крайней мере знаем, что сделали хоть немного для того, чтобы вернуть его прежнюю красоту. Если пожелаешь снова вернуться ко мне, я буду рад обществу сородича.\n\nУдачи тебе. Возможно, наши племена снова встретятся в не столь жестокие времена.", rewards = "Вы получите:\n\n"},
[1046] = {title = "Раэна – санитар Ясеневого леса", objective = "Принесите череп Рэна Кровавого Клыка и жезл Преображения Дартола Раэне Волкопас в Астранаар.", description = "Возвращайся в свое племя и поведай им о нашей победе.\n\nПокажи им свой трофей и насладись славой...", progress = "Часовые здесь, в Ясеневом лесу, делают что могут, но лишь благодаря таким |3-6(человек)s как ты, мы не сдаем своих позиций.", completion = "Значит, вот он – череп самого лютого фурболга в Ясеневом лесу?\n\nЯ более чем довольна твоими способностями, Wrestlecake. Не знаю даже, как часовым отблагодарить тебя. Надеюсь, в будущем мы снова сможем положиться на тебя, чтобы помочь нашему народу.\n\nЯ положу этот череп и жезл Дартола на почетное место, чтобы все их увидели. \n\nТеронис гордился бы тобой. Еще раз спасибо тебе.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛедовый жерновРазделочный клинок\n\nВы также получите:\n\nКольцо из чистого серебра"},
[1047] = {title = "Новое пограничье", objective = "Обратитесь в дарнасский анклав Кенария к верховному друиду Фэндралу Оленьему Шлему по поводу помощи Кругу Кенария в исследовании границ Калимдора.", description = "Внимание, герои!\n\nКруг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора -запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!\n\nВсе заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнассе!", progress = nil, completion = "С чего ты решил, что я буду утруждать себя беседой с таким, как ты, |3-6(Маг)? Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу! Ведь благополучие Дарнасса – нет, всего Тельдрассила – в сравнение не идет с важностью поиска этой пустяковины для твоей коллекции!\n\nСначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я еще и это сносить должен?", rewards = "Вы получите:\n\n"},
[1048] = {title = "В монастырь Алого ордена", objective = "Убейте Верховного инквизитора Вайтмейн, командира Могрейна из Алого ордена, воителя Герода из Алого ордена  и псаря Локси. Затем возвращайтесь к Вариматрасу в Подгород.", description = "Хотя Темную Госпожу больше всего тревожит продвижение Короля-лича на север, мое дело – заботиться о более насущных проблемах.\n\nИ главная из них – человечишки, зовущие себя Алым орденом. Тирисфальские луга кишмя кишат маленькими алыми муравьишками.\n\nОтправляйся в монастырь, <класс>, и избавь нас от Верховного инквизитора Вайтмейн и ее подчиненных.", progress = nil, completion = "Ты сослужил Темной Госпоже отличную службу, |3-6(Разбойник). Это задание было не из легких.\n\nЯ не забуду о твоей преданности Отрекшимся и стойкости в битве.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМеч ОменаПророческая палкаОжерелье Драконьей Крови\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1049] = {title = "\"Компендиум павших\"", objective = "Добудьте \"Компендиум павших\" из монастыря в Тирисфальских лесах и возвращайтесь к Ведуну Искателю Истины в Громовой Утес.", description = "Намерения Служителей Земли относительно наших пораженных болезнью братьев чисты. Но кому ведомы замыслы тех, кто нашептывает всякое Совету Старейшин?\n\nУ Отрекшихся, с которым мы ныне в союзе, вся история полна лжи. Слишком мы поторопились с союзом. Возможно, Кэрн прислушается к предупреждениям из Оргриммара.\n\nВ недрах Монастыря Алого ордена находится \"Компендиум павших\", который стерегут безумные фанатики-люди. В том, что они творят, сквозит безумие, однако их исследования могут оказаться для нас полезными.", progress = "Кэрн – отважный и благородный вождь, и я доверил бы ему свою жизнь. Но есть и те, кому я в нынешние времена нипочем бы не доверился.\n\nКак только смогу собрать все возможные сведения, я сумею дать вождю небезосновательный совет.\n\nТебе удалось добраться до Тирисфальских лесов? Удалось проникнуть в Монастырь Алого ордена? \"Компендиум павших\" – лишь кусочек сложной мозаики...", completion = "\"Компендиум павших\"! А я уж начал было сомневаться в том, что он вообще существует!\n\nТы сослужил добрую службу тауренам Громового Утеса, Томпсон. Твоя преданность не будет забыта.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПогибельная защитаКулачный щит КамнесилыСфера Омеги\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1050] = {title = "\"Мифология Титанов\"", objective = "Добудьте \"Мифологию Титанов\" из монастыря и принесите ее библиотекарю Мае Белокожке в Стальгорн.", description = "Будущее неотвратимо! Мы стремимся к нему подобно тому, как дождевые капли стремятся к Великому морю.\n\nНо, изучая прошедшее, мы узнаем, что ждет нас в грядущем, и готовимся к встрече с неведомым.\n\nПрежде чем великие беды обрушились на Лордерон, в Тирисфальских лесах находился оплот знаний. Ходят слухи, что в библиотеке старого монастыря хранится книга под названием \"Мифология Титанов\".\n\nПринеси ее мне – и, возможно, вместе мы сможем заглянуть в тайны прошлого!", progress = "Этот монастырь был духовной школой паладинов. Некогда он был цитаделью Света, а теперь попал в руки безумных фанатиков Алого ордена.\n\nОни считают, что у них благородная цель – очистить землю от нежити. Но безумие запятнало их деяния, и ныне они враги всем.\n\nПринеси мне \"Мифологию Титанов\", чтобы я могла изучить эту книгу. Я буду хранить ее здесь, в Стальгорне.\n\nОскверненные стены монастыря – не место для такого исторического сокровища.", completion = "Ты спас священный текст!\n\nТвое путешествие было долгим, а уж добыть такую книгу было несомненно трудно. Но дворфы Стальгорна от твоего успеха получат огромную выгоду.\n\nСпасибо тебе, Эфром, от лица всей Лиги Исследователей.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nАмулет Лиги Исследователей"},
[1051] = {title = "Месть Воррела", objective = "Верните обручальное кольцо Воррела Сенгутца Монике Сенгутц в Мельнице Таррен.", description = "Моя воля свободна, и все же я не могу более служить Темной Госпоже. Я чувствую, что время, отпущенное мне в Азероте, подходит к концу. Жизненные силы покидают меня.\n\nДознаватель Вишас всему виной! Он пытал меня много недель! Мало того, он отобрал у меня обручальное кольцо и нацепил его на палец своей жене! Чудовище!\n\nЯ жажду мести!\n\nЭтот глупец похвалялся своей прекрасной женой Нэнси, что живет у озера Лордамер. Я хочу, чтобы ты <отыскал/отыскала> ее и <вытряс/вытрясла> из нее душу вместе с моим кольцом! Верни кольцо моей жене Монике, она живет в Мельнице Таррен.\n\nИсполни мою последнюю волю.", progress = "Что тебе нужно, странник?", completion = "Воррел был мне добрым супругом... \n\nПроклятые смертные! \n\nНикогда нам более не быть вместе. По крайней мере, я найду утешение в свершенной тобой мести. Благодарю тебя. \n\nА теберь оставь меня наедине с моим горем.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОплечье горяНакидка Неумолимой стали\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nСапоги Воррела"},
[1052] = {title = "По пути Алых", objective = "Отнесите рекомендательное письмо брата Антона Ролею Благочестивому в Южнобережье.", description = "Мы, рыцари Алого ордена, заявляем свои права на укрепления от Дольного Очага до Тирисфальских лесов. Мы гордимся нашей борьбой за чистоту Лордерона!\n\nВы подтвердили свою репутацию, сражаясь против нежити в Пустошах. Но настоящая угроза исходит из Лордерона.\n\nОтправляйтесь в Восточные королевства, в город Южнобережье. Отнесите письмо с моими рекомендациями и печатью рыцарю Ролею Благочестивому. Он проводит вас в Монастырь Алого ордена.", progress = "Кто идет? Что вам от меня надо?", completion = "Брат Антон по-прежнему проповедует идеи Алого ордена? О-ох...", rewards = "Вы получите:\n\n"},
[1053] = {title = "Во имя Света!", objective = "Убейте Верховного инквизитора Вайтмейн, командира Могрейна из Алого ордена, воителя Герода из Алого ордена и псаря Локси, после этого вернитесь с докладом к Ролею Благочестивому в Южнобережье.", description = "Я всегда служил Алому ордену, гордился им и почитал служение за честь. Мне было чем гордиться, ведь мы спасали Азерот от нежити.\n\nНо после некоторого времени, проведенного в монастыре Тирисфальских лесов, я понял, что не ведал об истинных намерениях высшей иерархии ордена. Каждого, кто не принадлежит к ордену, они почитают грешниками. Невинных мужчин и женщин подвергают пыткам, полагая их нечистыми.\n\nВо имя Света, Алый орден должен быть сокрушен. И вам, <имя>, по силам остановить это чудовище.", progress = nil, completion = "Хотя путь Света не приемлет убийств и кровопролитий, но в подобных случаях кровавая жертва служит благу королевства и всего мира.\n\nВаши деяния в монастыре помогли спасти множество невинных жизней. Асмар, я восхищаюсь вашей решительностью.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМеч безмятежностиКостекусЧерная угрозаСфера Лорики\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1054] = {title = "Устранение угрозы", objective = "Принесите череп Дала Жилотяга Раэне Волкопас в Астранаар.", description = "Прямо к северу от Астранаара живут фурболги Колючего Меха. Мои разведчики доносят, что в последние несколько месяцев они чрезвычайно умножились числом. Если они слишком расплодятся, то могут набраться наглости напасть на Астранаар!\n\nУбей их, сколько сможешь, главное – принеси мне череп их предводителя в знак того, что их усилия напрасны...пока. \n\nЯ останусь в Астранааре и буду ждать вестей от тебя. Да пребудет с тобой Элуна.", progress = "Из-за этой фурболгской заразы дни славы Ясеневого леса остались далеко в прошлом.", completion = "Славная работа, Нортон.\n\nЭти фурболги постоянно угрожают нам. По счастью, теперь они некоторое время будут сидеть тихо.", rewards = "Вы получите:\n\nВосстанавливающий бальзам"},
[1055] = {title = "Раэна – санитар Ясеневого леса", objective = "Вернитесь к Шаэлдрин у лунного колодца.", description = "Воссозданный жезл у вас в руках. Шаэлдрин захочет услышать о ваших успехах.", progress = nil, completion = "У тебя получилось, Нортон! Великолепно!", rewards = "Вы получите:\n\n"},
[1056] = {title = "Путешествие к Пику Каменного Когтя", objective = "Отправляйтесь к хранителю Албагорму на Пик Каменного Когтя.", description = "Лесные духи говорят мне, что ты <отважен и легок на подъем/отважна и легка на подъем>.\n\nНа юге, неподалеку от озера Мистраль, находится туннель, именуемый Туннель Когтя. Через этот туннель ты попадешь в место, называемое Утес Ветрорезов, в Когтистых горах. Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберешься до Пика Каменного Когтя.\n\nТам ждет хранитель Албагорм. Выслушай его просьбу, <раса>.\n\nПутешествие будет опасным.", progress = nil, completion = "Наконец-то! Вижу, Фальдреас прислушался к  духам лесов...", rewards = "Вы получите:\n\n"},
[1057] = {title = "Возвращение Обугленной долины", objective = "Хранитель Албагорм с Пика Каменного Когтя просит вас убить 7 гарпий, 7 душительниц, 7 душегубок и 7 бродяжниц из стаи Кровавой Ярости.", description = "Несомненно, будучи защитником лесных духов, можешь догадаться, почему я так встревожен.\n\nЧтобы достигнуть этого пика, тебе пришлось пройти через горы, и, конечно же, от глаз твоих не ускользнуло искажение, постигшее эту землю. Алчность привела к уничтожению священных холмов.\n\nОбугленная долина на юге сожжена механической армией жадных промышленников. Хуже того, клан Смертельной Ярости, вторгшийся на эти земли, отказывается пропустить нас – а ведь мы могли бы начать восстановление тех краев!\n\nИзгони прочь злобных гарпий, <имя>!", progress = nil, completion = "Теперь, когда клан Смертельной Ярости понес большие потери, вероятно, и начнется истинная работа по восстановлению этих земель...", rewards = "Вы получите:\n\n"},
[1058] = {title = "Лесная магия Джин'Зила", objective = "Знахарь Джин'Зил из Малака'джина требует принести 5 порций слизи Каменного когтя, 5 сумеречных усиков, 30 глаз бегового оленя и чешуйку волшебного дракончика.", description = "Я в восхищении!\n\nТри маленьких клетки для трех маленьких эльфов. Ну-с, что бы нам сделать с нашими дорогими друзьями-древолюбами? Что ж, дадим им попробовать... как бы это они сказали... лесной магии!\n\nМне нужна добрая порция слизи Каменного Когтя. Принеси мне несколько сумеречных усиков этих ужасных кошек. И конечно же, потребуется множество глаз бегового оленя – глаз всегда не хватает! Да, и еще, последнее, чуть не забыл: драгоценную чешуйку волшебного дракончика.\n\nЖиво в Каменный Коготь, <имя>, чтобы я мог сварить немножко лесной магии!", progress = "Взгляни на наших маленьких друзей-эльфов! Заперты в клетках и не могут побродить по лесу!\n\nТебе удалось раздобыть для меня немного слизи? А как насчет усиков сумеречного бегуна? А разве у тебя еще нет чешуйки волшебного дракончика?\n\nА глаза? Мне нужно так много глаз! Невозможно составить доброе магическое лесное варево без хорошей порции глаз!", completion = "О, как счастливы будут эти маленькие лесные нимфы! Мы заставим их почувствовать себя как дома при помощи этого особого отвара!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОплечье вудуСглаженные наручи\n\nВы также получите:\n\n"},
[1059] = {title = "Возвращение Горелой Долины", objective = "Отправляйтесь к Фалфиндеру Хранителю Дорог, живущему на границе Тысячи Игл и Фераласа.", description = "Мы одержали победу над кланом Смертельной Ярости. Но они скоро соберут силы и вернутся, если не предпринять решительные действия. \n\nДалеко на юге Пустошей находится земля, известная как Тысяча Игл. Если идти на запад Тысячи Игл до тех пор, пока не достигнешь границ густого леса Фералас, то встретишь друида по имени Фалфиндер Хранитель Дорог.\n\nЭтот сильный и мудрый друид способен призвать великих лесных духов, которые помогут в восстановлении Обугленной долины.\n\nПоведай ему о нашей беде! Отправляйся на его поиски немедленно!", progress = nil, completion = "Хранитель Албагорм поступил мудро, прислав тебя со срочным известием.\n\nБудем надеяться, что мы успеем призвать помощь, и что эта помощь из великого леса прибудет в Обугленную долину не слишком поздно.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗакаленные наручиКулачный щит констебля\n\nВы также получите:\n\n"},
[1060] = {title = "Письмо Джин'Зилу", objective = "Отнесите письмо Дарсока Джин'Зилу в пещеру Малака'джин в Когтистых горах.", description = "Ты <сделал/сделала> мне много добра, <имя>. Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что еще.\n\nГарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе. Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин'Зилу.\n\nОн будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится. Занятное место.", progress = "На вид ты темная личность. Ты хочешь мне что-то показать?", completion = "А, письмо от Дарсока. Давно от него не было вестей.\n\nЗначит, последняя из Кровавых Перьев мертва? Отличные вести. Я хорошо помню, как мой друг Рохан пошел убивать ее старшую сестру с этим психом из Мок'Натала. Да, тогда я был молод, как ты сейчас.", rewards = "Вы получите:\n\n"},
[1061] = {title = "Духи Каменного Когтя", objective = "Поговорите с Сирит Камнелом в Когтистых горах.", description = "Духи Когтистых гор разгневаны: гоблины и их приспешники разоряют и выжигают земли. Земля возопила, и те, кто способен слышать – услышали.\n\nВ Когтистые горы отправилась Сирит Камнеломм, многообещающий шаман Орды. Она сообщает, что гоблины вырубили много леса, и просит о помощи.\n\nОтправляйся в Когтистые горы, найди там Сирит. Чтобы туда добраться, ступай от Перекрестка в Степях по дороге на запад. Сирит стоит лагерем близ Долины Высокого леса.", progress = nil, completion = "А, |3-6(Воин)! Очень кстати. Нам понадобится твоя помощь, чтобы управиться с этими лиходеями!", rewards = "Вы получите:\n\n"},
[1062] = {title = "Вторжение гоблинов", objective = "Убейте 15 лесорубов Торговой компании, затем вернитесь к Сирет Камнелом на границу Каменного Когтя и Степей.", description = "Торговая Компания, которой управляют гоблины, вторглась в Когтистые горы. Они валят деревья, выжигают большие участки леса. Духи этих земель вне себя от боли и ярости. Мы должны остановить Торговую Компанию!\n\nОтправляйсся на северо-запад, за Долину Высокого леса, к Утесу Ветрорезов. Ты найдешь гоблинов и их прислужников за работой – покажи же им, что Орда не позволит разорять Когтистые горы. Поговори с ними на том языке, который они лучше всего понимают...\n\nНа языке беспощадной силы!", progress = nil, completion = "Это подлинно отважное деяние, Ахахаха.\n\nВероятно, в конце концов нам понадобится мудрость тауренских старейшин, чтобы успокоить духов Каменного Когтя, но...\n\nПервый шаг в верном направлении сделан – Торговая Компания лишилась работников.", rewards = "Вы получите:\n\n"},
[1063] = {title = "Мудрая старуха", objective = "Поковорите с Магатой в Громовом Утесе.", description = "Чтобы узнать, как окончательно успокоить духов Когтистых гор, нам нужно посоветоваться со старейшинами тауренов.\n\nЯ мало знаю о том, кто предводительствует тауренами, но одно имя мне известно: Магата. Я слышала, что она очень стара и много знает. Если кто из тауренов и может оказать нам помощь касательно духов, то это она.\n\nМагата живет в главном городе тауренов Громовом Утесе, на Вершине Старейшин – это северо-восточная вершина города. Поговори с Магатой и расскажи ей о том, что творится в Когтистых горах.", progress = nil, completion = "Я приветствую тебя. Ты ищешь совета?", rewards = "Вы получите:\n\n"},
[1064] = {title = "Помощь Отрекшихся", objective = "Поговорите с аптекаршей Замой у Прудов Видений в Громовом Утесе.", description = "Таурены в сродстве с этой землей, и мне больно слышать о том, что творится в Каменном Когте. Но я боюсь, что для исцеления этой земли нам прежде придется справиться с той заразой, что терзает нас самих.\n\nРазве не удача, что Отрекшиеся теперь с нами? Они много знают о заразных болезнях. Я уверена, что они смогут помочь нам и тем укрепят доверие между нашими народами.\n\nПоговори с аптекаршей Замой. Она – ученая и представитель Отрекшихся. Ты найдешь ее у Прудов Видений под Уступом Духов.", progress = nil, completion = "Магата прислала о тебе весточку, Демонорох. Хотя сердце мое уже и не бьется, оно все же разрывается от горя по духам Каменного Когтя.\n\nОтрекшиеся готовы помочь всем, чем только можно.", rewards = "Вы получите:\n\n"},
[1065] = {title = "Путешествие на Мельницу Таррен", objective = "Принесите записку Замы аптекарю Лидону в Мельницу Таррен.", description = "Нам придется прибегнуть к чрезвычайным мерам, чтобы избавить Каменный Коготь от Торговой Компании. Но только без кровопролития.\n\nУ одного моего коллеги может найтись то, что нам как раз для этого случая и нужно. Его зовут Лидон, он живет в городе Мельница Таррен в предгорьях Хилсбрада, в далеком краю Лордерон.\n\nЧтобы добраться до Хилсбрада, отправляйся на дирижабле в нашу столицу, Подгород. Оттуда иди на север в Тирисфальские леса, что к юго-западу от Серебряного бора, а затем на юг, в Хилсбрад.\n\nНайди Лидона и передай ему эту записку. Там написано, что нам от него нужно.", progress = "Ага, вы доставили мне новых подопытных?", completion = "Записка от Замы? Наверняка ее сильно прижало, раз пишет в такую даль. Посмотрим...\n\nЗамечательно! Я знаю, что ей надо!", rewards = "Вы получите:\n\n"},
[1066] = {title = "Невинная кровь", objective = "Принесите 5 фиалов крови невинных аптекарю Лидону в Мельницу Таррен.", description = "Я создам яд, который остудит пыл Торговой Компании. Они станут слабыми и покорными. Это же решит проблемы Орды в Каменном Когте, да?\n\nНо для создания отравы мне понадобится кровь невинных, а ее нелегко найти.\n\nК счастью, Синдикат, группа грабителей, насчитывает в своих рядах несколько темных магов... а они собирают кровь невинных для своих нечистых целей.\n\nТемных магов Синдиката можно найти в крепости Дарнхольд на юго-востоке.", progress = "Тебе удалось найти темных магов Синдиката и принести кровь невинных?", completion = "Очень хорошо! Надеюсь, Синдикат не причинил тебе особых проблем?\n\nКак я и говорил, кровь невинных не так уж легко добыть. Нам повезло, что трудную часть работы взяли на себя маги Синдиката.\n\nА теперь подожди, я создам мой состав...", rewards = "Вы получите:\n\n"},
[1067] = {title = "Возвращение в Громовой Утес", objective = "Отнесите отраву Лидона аптекарю Заме в Громовой Утес.", description = "Вот отрава. Если воспользоваться ей против Торговой Компании, результаты должны оказаться весьма благоприятными – возможно, удастся добиться даже распростанения новой заразы. Мне не терпится испытать свою работу в деле!\n\nВпрочем, прежде отнеси ее аптекарю Заме. Она должна придумать наиболее эффективный способ использования отравы.", progress = "Ты вернулся, Ахахаха. Аптекарь Лидон пришел к нам на подмогу?", completion = "Отрава от аптекаря Лидона? Замечательно. Если я знаю Лидона, она очень хорошо подействует на Торговую Компанию...", rewards = "Вы получите:\n\n"},
[1068] = {title = "Механические измельчители", objective = "Уничтожьте шреддеры XT:4 и XT:9, затем вернитесь к Сирит Камнелом на границу Когтистых гор и Степи.", description = "Есть связь между духовной магией шаманов и природной магией друидов. Именно поэтому мы, шаманы, можем слышать мольбы духов Каменного Когтя. Я могу разобрать не все, что они шепчут, однако одно послание - одно видение - было четким...\n\nВ этом видении я узрела на Утесе Ветрорезов, на северо-западе Долины Высокого леса, две человекоподобные машины, которые валили деревья с невероятной скоростью. Этих металлических тварей нужно остановить!\n\nВ явленном мне видении я заметила, что машины эти отмечены странными символами:\n\nXT:4 и XT:9.", progress = "Духи деревьев плачут по своим погибшим собратьям, Грагхар. Тебе нужно уничтожить шреддеры XT:4 и XT:9, иначе, я боюсь, Каменный Коготь никогда не оправится от этого ужаса.", completion = "Уничтожение машин XT:4 и XT:9 успокоило многих духов Каменного Когтя, Ахахаха. Будем надеяться, что после потери этих машин Торговая Компания покинет эти горы.\n\nИбо если этого не произойдет, то бедствия, постигшие эти земли, могут оказаться бледной тенью того, что ждет нас впереди.", rewards = "Вы получите:\n\n"},
[1069] = {title = "Яйца мохового паука", objective = "Принесите Мебоку Миззриксу из Кабестана 15 яиц мохового паука.", description = "В Пиратской бухте фантастический спрос на омлеты из паучьих яиц! Проблема в том... что яиц в Бухте нет.\n\nЯ чую прибыль!\n\nНа Утесе Ветрорезов и в Сиширском каньоне, в Когтистых горах на северо-западе, живут моховые пауки. Принеси мне их яйца, и я неплохо заплачу!\n\nНа Утесе Ветрорезов паучьи кладки можно найти под оставшимися деревьями.\n\nВ Сиширском каньоне... хм, если у тебя слабый желудок, можешь собирать яйца только на Утесе Ветрорезов...", progress = "Принес яйца, Демонорох? Я уже заключил договор о транспортировке с управляющим пристанью Головокружилкинсом.", completion = "Ты принес мне яйца! Спасибо!\n\nЯ пошлю их Дыбоволосу, и он переправит мой товар в Пиратскую бухту!\n\nВот твоя доля, Демонорох. Без тебя мне бы не справиться.", rewards = "Вы получите:\n\n"},
[1070] = {title = "На страже в Когтистых горах", objective = "Найдите Келу Копье Тени, которая наблюдает за долиной, выходящей к Утесу Ветрорезов в Когтистых горах.", description = "Привет тебе, <имя>.\n\nСудя по виду, ты много путешествуешь. Тебе приходилось бывать в Когтистых горах? Эта земля опустошена Торговой компанией и прочими врагами ночных эльфов. \n\nНедавно часовой Волкопас послала туда мою подругу Келу Копье Тени, чтобы она узнала, что происходит в тех землях, однако до сих пор от нее нет вестей. Я еще беспокоюсь и потому, что Альянс отправил вместе с ней гнома-мага... это, несомненно, повод для тревоги.\n\nМожет быть, ты найдешь ее и пошлешь весточку мне?", progress = nil, completion = "А, так ты здесь по просьбе Тары из Ясеневого леса... я так скучаю по ней, по моей родине, по друзьям. Должно быть, ей хорошо среди часовых, раз прочие дела передает путникам. Я горжусь за нее.\n\nРада познакомиться с тобой, Wrestlecake.", rewards = "Вы получите:\n\n"},
[1071] = {title = "Отсрочка для гнома", objective = "Убейте 10 лесорубов и 10 лесозаготовителей Торговой Компании и вернитесь к Гаксиму Ржавошиппи в Каменный Коготь.", description = "Понимаешь ли, <имя>, я состою в Просвещенной Ассамблее Чародейства, Алхимии и Технических Наук, и моя цель... нет, мой ДОЛГ! – показать ночным эльфам, что единение магии, реактивов и механизмов поможет спасти их леса.\n\nОднако это тяжелая война, а гоблины, похоже, плодятся, словно кролики. У меня даже нет времени воплотить в жизнь свои новые изобретения!\n\nМне нужно время для планирования и организации. Но для этого мне потребуется твоя помощь – сдерживать натиск гоблинов у Утеса Ветрорезов к востоку отсюда...", progress = "Ну и как продвигаются дела, Вилдан?", completion = "Спасибо тебе за помощь, Wrestlecake. Да и вернуться тебе удалось как раз вовремя.\n\nКажется, я выработал идеальный план... взрывчатка. Нет, это не сам план, это его часть.\n\nПонимаешь ли, я использую сильные взрывчатые вещества – не волнуйся, они далеко не так опасны, как считается – для того, чтобы припугнуть гоблинов. Я смогу как следует нагнать на них страху, разместив в ключевых местах на границах горной местности заряды, однако в ближайшие несколько дней мне может не хватить материалов...", rewards = "Вы получите:\n\n"},
[1072] = {title = "Старый коллега", objective = "Поговорите с Ломаком Демонтирсом в Стальгорне.", description = "Устройство, о котором я думаю – моя самая продвинутая версия на сегодняшний день. Но мне нужно особое зелье, чтобы это устройство заработало. Я думаю, нам нужно добыть хороший состав, поскольку эта миссия может стать для тебя последней.\n\nА для этого нам нужно мощное взрывчатое вещество: нитромирглицероний.\n\nЕдинственный, кто может создать НГ-5, это мой старый приятель – Ломак Демонтирс. Поищи его в Городе Механиков.\n\nЕсли уговоришь его сделать для нас немного НГ-5, то я начну работать над размещением своих устройств.", progress = nil, completion = "А-а-а... Тебя послал Гаксим, вот как? А откуда мне знать, что ты не врешь? Ась? Ась?..", rewards = "Вы получите:\n\n"},
[1073] = {title = "Неумение + реактивы = потеха!", objective = "Принесите 4 крохотных флакона с зельем маны и 2 слабых эликсира стойкости Ломаку Демонтирсу в Стальгорн.", description = "Ха-ха-ха!.. Тебе нужен нитромирглицероний, чтобы остановить гоблинов, уничтожающих лес?!\n\nМне все равно, знаешь ты Гаксима или нет... я дам тебе этот состав, чтобы посмотреть, как кого-нибудь разнесет на мелкие кусочки: или тебя, или гоблинов.\n\nНо есть проблемка: у меня кончились химикалии.\n\nНо вот что я тебе скажу: принесешь мне нужные зелья, и я прямо сразу же смешаю для тебя составчик.\n\nПо крайней мере, ты докажешь, что кое-что понимаешь в алхимии, прежде, чем я передам тебе образец своего величайшего творения.", progress = "Я не могу сделать нитромирглицероний без этих зелий... они жизненно важны для его создания.", completion = "Вот это подойдет.\n\nНе знай я тебя, я бы сказал, что ты кое-что понимаешь в алхимии... Ладненько, ладненько... в мире есть не только мечи и колдовство, верно?", rewards = "Вы получите:\n\n"},
[1074] = {title = "Неумение + реактивы = потеха!", objective = "Отнесите нитромирглицероний Гаксиму Ржавошиппи в Каменный Коготь.", description = "Ну вот тебе, держи. Тока поосторожней... это летучая смесь.\n\nЕсли Гаксим тебе и вправду друг, передай ему от меня привет. А если нет – взлетишь на воздух, вот будет тебе потеха.", progress = "А, славно, славно, с возвращением.", completion = "Дело сделано, и сделано отлично, Бронетазик.\n\nНГ-5 незаменимый компонент для поджига повозок с динамитом.\n\nЧто? Да, динамит... целыми повозками. Это идеальный отвлекающий маневр, я тебе скажу... подожди и увидишь.", rewards = "Вы получите:\n\n"},
[1075] = {title = "Свиток от Маурена", objective = "Найдите в Штормграде Коллина Маурена.", description = "Теперь о том, что касается дистанционных взрывов, входящих в мой план... ах да, я, кажется, еще не объяснил этого?\n\nНу так вот, вкратце: задействовав немного магии, я смогу сделать так, чтобы взрыв произошел почти без твоего участия. Я соберу такое устройство, что тебе останется просто нажать кнопку, а где-то там взорвется НГ-5.\n\nНо мне нужно заклинание, которое есть у моего друга в Штормграде – его зовут Коллин Маурен. Ты сможешь отыскать его там в квартале магов. Он человек, так что будь <внимателен/внимательна>, не ошибись.", progress = nil, completion = "Да, вот то заклинание, которое тебе нужно – оно позволит производить взрывы на расстоянии... хмм.", rewards = "Вы получите:\n\n"},
[1076] = {title = "Демоны в Западном Крае", objective = "Принесите прах Пыледемона Коллину Маурену в Штормград.", description = "А, кажется, я понял. Заклинание послания... полагаю, именно этого эффекта он хочет добиться. \n\nМне нужно создать свиток с запечатленным на нем заклинанием. Для этого мне нужен прах Пыледемона.\n\nПока я собираю остальные компоненты, почему бы тебе не отправиться в Западный Край и не найти там одно из этих мерзких существ? Они опасны, но я уверен, что ты со всем справишься, если желаешь участвовать в одном из экспериментов Гаксима.\n\nКогда ты вернешься, я буду здесь.", progress = "Привет, Wrestlecake. Тебе удалось найти нужный мне компонент?", completion = "Подожди несколько секунд, и нужный тебе свиток будет готов.", rewards = "Вы получите:\n\n"},
[1077] = {title = "Особая посылка для Гаксима", objective = "Отнесите свиток с посланием Гаксиму Ржавошиппи в Каменный Коготь.", description = "Вот, <имя>. Это то, что нужно.\n\nКогда в следующий раз увидишь Гаксима, передай ему от меня привет. Хотелось бы мне узнать, как закончится эта история.\n\nВсего тебе хорошего.", progress = "Хо-хо, ты уже обратно? У тебя оно есть? Заклинание, в смысле?", completion = "Великолепно, Рабинович! Славная работа.\n\nЭто заклинание вместе с НГ-5 даст идеальную дистанционную взрывчатку.\n\nУ нас получится прекрасный отвлекающий маневр, и ты прокрадешься и сопрешь документы и инженерные планы Торговой компании.\n\nТогда они не смогут вырубать леса так быстро.", rewards = "Вы получите:\n\n"},
[1078] = {title = "Поиск для Маурена", objective = "Принесите 8 кристаллических чешуй Коллину Маурену в Штормград.", description = "Путешественники постоянно спрашивают меня о Когтистых горах. Похоже, все ищут там приключений, причем самых разных: кому-то нужны виверны, кому-то – элементали, а у кого-то дела с Торговой компанией.\n\nВ Обугленной долине, прячущейся среди пиков Когтистых гор, некогда обитали особые виды василисков: их чешуя, размолотая в порошок, была прекрасным реактивом для некоторых заклинаний, созданных мною. \n\nЕсли эти василиски еще живут там, мне надо заполучить хотя бы несколько чешуек.\n\nЕсли не очень торопишься, удели на это немного времени, я хорошо заплачу тебе.", progress = "И еще раз привет тебе, Бронетазик.\n\nТебе удалось побывать в той долине в Каменном Когте и добыть чешую?", completion = "Великолепно, Бронетазик. Спасибо тебе огромное.\n\nМожет быть, и я когда-нибудь смогу помочь тебе.", rewards = "Вы получите:\n\nЖезл изготовителя заклятий"},
[1079] = {title = "Секретная операция – Альфа", objective = "Добудьте технические чертежи Торговой компании с лесопилки на Утесе Ветрорезов.", description = "Так вот, <имя>, смотри и слушай внимательно. Все устройства доделаны и готовы к использованию.\n\nВозьми эти листы – здесь все объясняется про детонаторы, взрывчатку и про то, как их разместить.\n\nПомни, успех твоей миссии не зависит от того, сколько разрушений ты сможешь причинить. План \"Альфа\" увенчается успехом в том случае, если ты принесешь технические чертежи Торговой компании, находящиеся на лесопилке к югу от Скалистого Озера.", progress = "Тебе удалось раздобыть чертежи, Нортон?", completion = "Просто великолепно! Это сильный удар по Торговой компании.\n\nМы сможем узнать уязвимые места их машин, а также использовать их разработки для наших собственных целей. Поистине, это великий день.", rewards = "Вы получите:\n\n"},
[1080] = {title = "Секретная операция – Бета", objective = "Добудьте документы Торговой компании из Рудника Ветрорезов у восточного края Утеса Ветрорезов.", description = "План Бета – почти то же, что и план Альфа. <имя>.\n\nМы проводим отвлекающий маневр, а потом похищаем их драгоценные письма.\n\nГлавное – получить письма... помни это.\n\nНа листках, которые я дал тебе, сказано, где поместить взрывчатку. Не погибни и вернись с добытыми письмами...", progress = "Ну и как дела, Wrestlecake?", completion = "Великолепно, Wrestlecake! Каэла и часовые будут счастливы. При твоих умениях да моих творениях нас никто и ничто не остановит!", rewards = "Вы получите:\n\n"},
[1081] = {title = "Приглашение от Тиранды", objective = "Найдите в Дарнассе Тиранду Шелест Ветра.", description = "<имя>, я уверена, что Тиранда Шелест Ветра лично хотела бы поблагодарить тебя за участие в этой миссии.\n\nМожет быть, это и незаметно с первого взгляда, но деяния, совершенные с твоей помощью, способны помочь нам закрепиться в Когтистых горах.\n\nЕсли хочешь и далее помогать нам в борьбе, отправляйся на встречу с Тирандой в храм Луны в Дарнассе.", progress = nil, completion = "Приветствую тебя, Wrestlecake. Мне доводилось и прежде слышать твое имя, и я рада видеть, что, не взирая на твою молодость, ты уже избрал свой путь.\n\nТы окажешь мне великую честь, если примешь это как дар в знак нашего уважения к тебе.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЦветущее одеяниеСерый мундирДиколесская кольчуга\n\nВы также получите:\n\nКольцо эльфийской благодати"},
[1082] = {title = "Новости для часового Тенисил", objective = "Вернитесь к часовому Тенисил в Ясеневый лес.", description = "<имя>, твоя помощь здесь оказалась поистине бесценной.\n\nЧасовые Ясеневого леса вознаградят тебя, если ты уведомишь их, что я и Гаксим живы. Скажи им, что мы трудимся над тем, чтобы остановить Торговую компанию и исцелить эти земли.\n\nНайди в Астранааре Тару Тенисил, она обрадуется твоему возвращению и хорошим новостям.", progress = nil, completion = "Благодарю тебя, Бронетазик. Ты сослужил Стражам хорошую службу.\n\nЯ рада узнать, что Каэла... и даже Гаксим живы и здоровы.\n\nТы заслуживаешь нашего уважения.", rewards = "Вы получите:\n\n"},
[1083] = {title = "Разъяренные духи", objective = "Принесите 8 тлеющих углей от любых элементалей огня из Обугленной долины Келе Копье Тени в Когтистые горы.", description = "Не могу сказать точно, что Торговая компания сделала с Долиной, однако ясно, что обитающие там существа взяли над ними верх.\n\nПредставители Торговой компании подожгли лес, они использовали свои убийственные изобретения для того, чтобы как можно сильнее опустошить Долину.\n\nНо в невежестве своем они также освободили нечто иное: пылающих духов, элементалей огня, камня и ярости.\n\nИ этой земле никогда не узреть улыбку Элуны, пока эти существа бродят на свободе.\n\nПринеси мне их дымящиеся угли, дабы доказать, что тебе удалось сократить число разъяренных духов.", progress = "При первом взгляде на Горелую Долину на глаза мне навернулись слезы, Бронетазик.", completion = "Останки нашего врага... твоя сила сослужила нам добрую службу, Бронетазик. Благодарю тебя.", rewards = "Вы получите:\n\n"},
[1084] = {title = "Раны Дерев", objective = "Принесите образец ржавой шрапнели Келе Копье Тени в Каменный Коготь.", description = "Мне кажется очевидным, что защитники долины – древни – вели какие-то дела с Торговой компанией, прежде чем их оттеснили прочь. К несчастью, даже эти некогда великие охранители ныне впали в нечестие.\n\nГаксим полагает, что их падение каким-то образом связано с оружием, которое гоблины использовали во время отступления.\n\nЯ сказала ему, что возьму образец из тела раненого древня и отдам на изучение, чтобы понять, правда ли это.\n\nПринеси мне немного шрапнели, чтобы гном мог дать мне ответ...", progress = "По-моему, Гаксим найдет шрапнели применение вне зависимости от того, как Торговая компания использовала ее в прошлом.", completion = "Спасибо, Wrestlecake.\n\nЭтого должно быть более чем достаточно, чтобы Гаксим выяснил, каким образом скверна пала на древней. Я немедленно передам ему этот образец.", rewards = "Вы получите:\n\n"},
[1085] = {title = "На страже в Когтистых горах", objective = "Поговорите с Гаксимом.", description = "Положение здесь, в Каменном Когте, явно не способствует совместной работе ночного эльфа и гнома.\n\nТорговая компания опустошила эти земли, и большая часть моего времени уходит на то, чтобы положить предел уничтожению.\n\nНе суди Гаксима преждевременно; он понимает, что нам с ним необходимо трудиться вместе.\n\nЕсли ты хочешь помочь нам, то для начала поговори с Гаксимом.\n\nИзвини, что пока не могу отослать тебя обратно к Таре с хорошими новостямиI. Может быть, вскоре...", progress = nil, completion = "Предательская... предательская и опасная, вот какова эта земля.\n\nНо я тут для того, чтобы показать ночным эльфам, что ежели призвать на помощь старое доброе инженерное дело и чуточку магии, то так будет вернее.\n\nВидишь ли, если убрать магию совсем, то ночным эльфам это никак не поможет – они без нее не могут. И мир без нее не может. А вот если подкрепить магию инженерным делом да алхимией, то так оно будет правильнее. Возможностей просто масса.", rewards = "Вы получите:\n\n"},
[1086] = {title = "Аэропорт ветролетов", objective = "Отнесите распылитель ядовитого тумана в аэропорт Торговой компании и вернуться к аптекарю Заме.", description = "Отрава готова. Остается только ее доставить адресату. И это придется сделать тебе, <имя>.\n\nУ Торговой Компании есть средства доставки сообщений и легкого груза от штаб-квартиры до Когтистых гор. Скорее всего, это маленький аэропорт, подходящий не для дирижабля, а для ветролета. Обыщи все области Когтистых гор, находящиеся под контролем Торговой Компании, и найди этот аэропорт, если он существует. Как найдешь, помести туда отраву.\n\nПоложишь – беги оттуда.", progress = nil, completion = "Ты нашел аэропорт? Молодец, Ахахаха! Отличный сюрприз ждал гобинов! Будем надеяться, что яд доберется до их штаб-квартиры.\n\nТы оказал своему народу неоценимую услугу, и пусть тебя не мучает совесть из-за отравления Торговой Компании. Они еще не того заслуживают.\n\nИ вот какой мудрости союзникам Отрекшихся стоит поучиться:\n\nНе бойся темных дорог... если они ведут к победе.", rewards = "Вы получите:\n\n"},
[1087] = {title = "Наследие Кенария", objective = "Убейте 4 сыновей Кенария, 4 дочерей Кенария и 4 кенарийских ботаников по поручению Брайлин Огненной Длани из Приюта у Солнечного Камня.", description = "Ты и представить себе не можешь, как я ненавижу эти омерзительные земли! Отродья Кенария и кальдорайские друиды, обитающие на этом пике, используют свою жалкую силу, чтобы подавить поток магии, даже так далеко на юг от их гнусного обиталища... их драгоценных лесов.\n\nЯ так хочу вернуться в Джеденар и купаться в потоках магии, но мой господин не позволяет мне вернуться, пока моя работа здесь не будет завершена.\n\nНе сомневаюсь, что ты любишь ночных эльфов и их союзников не больше, чем я. Помоги мне, и мы оба внакладе не останемся.", progress = nil, completion = "Я уже это чувствую... да... прекрасная мощь... струящийся поток. Как же глупы кальдораи, что отвергают дары этого мира, не дают магии свободно, словно песня, струиться по жилам.\n\nКак же скучна и бесцветна жизнь без этого огненного потока!", rewards = "Вы получите:\n\n"},
[1088] = {title = "Гордан", objective = "Принесите голову Хорданиуса Брайлин Огненной Длани к Приюту у Солнечного Камня.", description = "Они думали, что могут остановить течение магии. Но они ошиблись. Они думали, что смогут спрятать Хорданиуса – но я заполучу его голову!\n\nМагия дает мне способность видеть истину. Да... вот он где. Скрещение путей... На вершине великого древа в Ясеневом лесу. Название... Приют в Ночных Лесах. Один из старших сыновей лесного бога. Они унесли его прочь с этого пика прежде, чем я смогла найти его, однако его время на исходе.\n\nПринеси мне его голову, и я поделюсь с тобой могуществом.", progress = "Когда мой повелитель отправил меня на Пик Каменного Когтя, мне казалось, что нужно будет лишь погубить ночных эльфов, которые ползают по руинам нашего древнего храма Азшары, оскверняя святость этого места... но Хорданиус ускользнул от меня.", completion = "Некогда, давным-давно, я знала Хорданиуса. Он был горд, как и все его сородичи, и ставил себя даже над высокорожденными.\n\nОднако теперь ему трудно так же высоко держать голову, не так ли, Ахахаха?\n\nЯ обещала тебе награду, и ты ее получишь. Слушай меня!", rewards = "Вы получите:\n\n"},
[1089] = {title = "Логово", objective = "Отправляйтесь к пещере на Пике Каменного Когтя. При помощи Ключа Хранителя Врат добудьте предметы, спрятанные друидами. Используйте эти предметы для того, чтобы открыть Сокровищницу Пещеры Когтей.", description = "В Пещере Когтей друиды построили Логово Когтя, где хранят множество могущественных предметов.\n\nОни продумали сложный план, чтобы не дать этим предметам попасть в чужие руки.\n\nК счастью, мне удалось... вытянуть некоторые подробности из одного из них.\n\nВ маленьком светильнике у входа в пещеру ты найдешь спрятанный там Ключ Хранителя Врат – с его помощью ты сможешь отворить тайники, расположенные вокруг логова. А предметы из этих тайников помогут тебе открыть сокровищницу, размещенную в одном из центральных помещений.", progress = "Три замочных скважины вырезаны в камне.", completion = "Когда три ключа вошли каждый в свое отверстие, посреди мерцающего сияния появились несколько предметов.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nСвященное кольцоПантеровая броняПоножи Джаггернаута"},
[1090] = {title = "Приказы Геренцо", objective = "Возьмите образец загадочной руды у Пузника после того, как он ее добудет.", description = "Знаешь, когда-то я был второй по важности персоной во всем этом деле. Все изменилось, когда главным стал Геренцо. Уволил моего начальника Зиза Физзикса, а меня послал работать в копях. Но Зиз велел мне оставаться здесь и собирать сведения. Его новое начальство хорошо заплатит нам, если мы узнаем, что планирует Геренцо.\n\nВ любом случае, я точно знаю, что Геренцо приказал добыть как можно больше этой золотисто-зеленой руды. Я могу раздобыть образец, а ты передашь его Зизу. Но пока я этим занимаюсь, следи, не покажется ли стража.", progress = nil, completion = "Спасибо, Мерандир. Тут выдалось несколько опасных моментов, да и мы, наверное, были не слишком-то внимательны.\n\nНо важно то, что у нас теперь есть образец руды, и мы должны как можно скорее доставить его Зизу.", rewards = "Вы получите:\n\n"},
[1091] = {title = "Новости для Каэлы", objective = "Отнесите документы Торговой компании Келе Копье Тени.", description = "<имя>,отнеси эти письма Каэле. Уверен, что она захочет это узнать. По крайней мере, часовые точно захотят.\n\nИ обязательно расскажи ей о наших успехах и о том, что мы не добились бы ничего без чуточки магии.", progress = "Да, Wrestlecake? Какое у тебя ко мне дело?", completion = "Это действительно интересно, Wrestlecake.\n\nВы с Гаксимом все сделали правильно. Благодарю.", rewards = "Вы получите:\n\n"},
[1092] = {title = "Приказы Геренцо", objective = "Доставьте Неопознанную Руду Зизу Физзиксу в Когтистые горы.", description = "Полагаю, мне тоже нужно убираться отсюда. Не пройдет много времени. как слухи о том, что произошло здесь, распространятся достаточно высоко, и вряд ли меня в следующий раз встретят там с добром да лаской.\n\nМне нужно выбраться наружу и встретиться с Зизом. Надеюсь, он мне подыщет новую работенку!!!\n\nЯ попытаюсь тут слегка подчистить за собой, но тебе придется доставить образец руды Зизу немедля. Он говорил мне, что разбил свой лагерь где-то за западном склоне Утеса Ветрорезов. Удачи!", progress = "Что это? Я могу помочь тебе?", completion = "А, я так и знал, что правильно сделал, когда сказал Пузнику остаться. Я уверен, что инженеры в Нижней шахте захотят на это взглянуть.\n\nКонечно, я собираюсь прихранить кусочек для себя, но если они чего-то не узнают, то это им и не повредит, верно?", rewards = "Вы получите:\n\nОтвальные сапоги"},
[1093] = {title = "Супер-дровосек 6000", objective = "Добудьте чертежи \"Супер-дровосека 6000\" для Зиза Физзикса с Когтистых гор.", description = "Ну, Торговая Компания и наломала дров! О чем они только думали? Гоблинская компания нанимает гнома!\n\nК счастью для меня, Пароклапан всегда может узнать гения с первого взгляда. Он нанял меня сразу же, как меня выгнали оттуда!\n\nМне сказали, что компания строит какие-то огромные лесорубные машины, и Клапан хочет, чтобы я украл для него чертежи. К несчастью, Геренцо – вот ведь злобный гном! – хочет меня убить... может быть, ты вместо меня украдешь чертежи? Они должны быть у кого-то из операторов компании.", progress = "Тебе удалось добыть чертежи? Я хочу порадовать нового начальника. Надеюсь, как только он убедится в моей верности – ну, насколько его вообще можно убедить... гоблинский гонор, и все такое... – он найдет достойное применение моему гениальному уму.", completion = "Эй, это то, что я думаю? Отлично!\n\nНу-с, посмотрим... и как мне понимать эту ерунду?.. и чем только думают эти гномы? Удивительно, что они хотя бы колесо сумели соорудить, не говоря уж об этих их обожаемых ветролетах.", rewards = "Вы получите:\n\n"},
[1094] = {title = "Дальнейшие указания", objective = "Доставьте запечатанный конверт Пароклапану в Степи.", description = "В этом конверте – все сведения, которые я смог собрать до того, как меня выпнули за дверь... Внутренние документы Торговой Компании, кое-какие руководства, технические бумажки... О, и, конечно, чертежи \"Супер-потрошителя 6000\".\n\nПаровой Клапан обосновался в Кабестане в Степях. Тебе не доставит труда разыскать его, это такой мелкий зеленый тип.", progress = "Эй, привет! Чем могу быть полезен?", completion = "Физзик, да? Не то, чтоб я ему верил, но, кажется, это правильные сведения. Что б я ни отдал, лишь бы Торговая Компания убралась подальше!\n\nХотя они притащили с собой кое-какие хорошие машины... не буду отрицать, что от их изобретений есть польза, когда эти изобретения применяем мы, а не кто-то другой...", rewards = "Вы получите:\n\n"},
[1095] = {title = "Дальнейшие указания", objective = "Отнесите Зизу Физзиксу в Когтистых горах новые приказы.", description = "В Нижней шахте было много разговоров про этого гнома, нанятого Торговой Компанией. Торговые олигархи не одобряют, что Раздунк связался с Геренцо.\n\nРидлвокс велел мне позаботиться об этой проблеме, и я не сомневаюсь, что это указание от одного из олигархов. Разумеется, директор мне об этом не говорил. Скажем так, у меня такое подозрение.\n\nКак бы то ни было, Геренцо необходимо устранить, и Физзику придется хорошо поработать.", progress = nil, completion = "Убрать Геренцо? Я только за!\n\nГномы вообще неприятный народ, но, судя по всему, этот Геренцо хуже других. Он был одним из главных инженеров Гномрегана и работал над тайным проектом – каким именно, нам так и не удалось узнать, хоть мы и пытались пробраться в Дун Морог. В докладах говорилось, что этот тайный проект буквально взорвался им в лицо.", rewards = "Вы получите:\n\n"},
[1096] = {title = "Геренцо Терминатрикс", objective = "Принесите механическую руку Геренцо Терминатрикса Зиззу Физзиксу в Когтистые горы.", description = "Один раз я встречал Геренцо и, скажу тебе, видок у него отвратнее некуда. Такое впечатление, что его плоть гниет и отпадает, части его тела заменены металлическими деталями и механизмами.\n\nК северо-востоку отсюда, высоко над Скалистым озером, вблизи водяного колеса находится пункт, откуда Геренцо наблюдает за всей местностью. Я не смог бы найти дорогу наверх, не говоря уж о том, чтобы справиться с Геренцо... Но тебе, кажется, это вполне под силу.\n\nЕсли ты убьешь его по моей просьбе, то получишь щедрое вознаграждение!", progress = "Паровой Клапан потребует какое-нибудь доказательство того, что Геренцо мертв. Полагаю, его механическая рука вполне сгодится.", completion = "Взгляни на эту штуковину... только гном мог с такой управляться. Не понимаю только, зачем отрезать руку и заменять ее этой штукой, если можно просто сохранить обе руки и приделать третью!\n\nГномы, я тебе скажу...\n\nГеренцо, по крайней мере, если и не мертв, то неисправен. Надеюсь, этого доказательства будет достаточно, и Пароклапан даст мне назначение в одну из мастерских Союза ремонтников в Прибамбасске или, может быть, даже в Нижней шахте.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nИнженерский плащСапоги чертежника\n\nВы также получите:\n\n"},
[1097] = {title = "Просьба Элмора", objective = "Поговорите с Гримандом Элмором.", description = "Дворфу-оружейнику Гриманду Элмору нужна помощь с доставкой ценного груза. Думаю, он хочет отправить посылку домой, на север.\n\nТы мне кажешься <опытным путешественником/опытной путешественницей>... Так что если ты не против взять с собой небольшой груз, то поговори с Гримандом; конечно, тебе и тут можно найти занятие, но мы стараемся поддерживать хорошие отношения с дворфами.\n\nГриманда Элмора можно найти в оружейной лавке в Штормграде, в Квартале Дворфов. Это в северо-восточной части города.", progress = nil, completion = "Ты поможешь мне с доставкой? Замечательно!", rewards = "Вы получите:\n\n"},
[1098] = {title = "Пропавшие стражи смерти", objective = "Найдите стражей смерти Адаманта и Винсента.", description = "Готовясь к нападению на крепость Темного Клыка, мы отправили на разведку двух стражей смерти. Они не возвращаются вот уже много дней, но без их отчета нам не организовать успешного нападения!\n\nИтак, вот твое задание, <имя>. Отправляйся в крепость Темного Клыка на юге и найди стражей смерти Адаманта и Винсента. Найди их и помоги им, если сможешь.\n\nЭто очень опасное и важное задание, <имя>. Не подведи нас.", progress = nil, completion = "Перед вами лежит израненное тело Винсента.\n\nСтраж смерти Адамант написал отчет Хадреку... Но что бы ни хотел добавить к его словам Винсент, он унес это с собой в могилу.\n\nВ мертвой руке зажата небольшая безделушка...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nПризрачное оплечье"},
[1099] = {title = "Гоблины победили!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПризовой сундучок гоблинов"},
[1100] = {title = "Дневник Хмурня", objective = "Прочитайте дневник Хенрига Хмурня.", description = "Вы медленно открываете потрепанный дневник Хенрига Хмурня...", progress = "Вас что-то беспокоит... Случилась какая-то неприятность?", completion = "Говорите, что нашли этот дневник у мертвого дворфа? Дайте мне на минутку, хочу взглянуть...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1101] = {title = "Хозяйка Лабиринтов", objective = "Принесите медальон Чарлги Остробок Фалфиндеру Хранителю Путей в Таланааре.", description = "Бедный Гералат! И этот дворф... Хмурень. Каким он был храбрецом!\n\nНельзя, чтобы их усилия пропали даром. Эта карга... Чарлга Остробок... нужно ее убить.\n\nРазумеется, поход в лабиринты Иглошкурых будет опасным, а за помощью в Дарнасс посылать некогда. Так что тебе, <имя>, придется собрать отряд самостоятельно.\n\nПринеси мне медальон Чарлги Остробок в доказательство ее смерти.", progress = "Пока Чарлга Остробок собирает свои силы в Лабиринтах Иглошкурых, эти земли будут в огромной опасности.", completion = "Наконец-то старая карга умерла. Это отличная новость, Аномалиус!\n\nВ наше опасное время всегда приятно встретить такого храбреца, как ты.\n\nТеперь, когда прислужники Остробок мертвы, мы сможем продолжить наши исследования той области. Возможно, теперь мы сможем узнать, почему место упокоения Агамаггана подверглось такому осквернению.\n\nОднако, боюсь, здесь не обошлось без предательства...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБерилловое оплечьеРемень Каменного КулакаУкрашенный мрамором кулачный щит\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nМушкетон \"Глаз мага\""},
[1102] = {title = "Отмщение грядет!", objective = "Принесите сердце Чарлги Остробок Ольду Каменному Копью в Громовой Утес.", description = "Кэрн – благородный вождь, объединивший наш народ здесь, в Громовом Утесе.\n\nНо я не могу так легко простить тех, кто изгнал нас с земель наших предков. Мой народ много десятилетий прожил в южных Степях. Те края для нас священны. Но нас изгнали многочисленные враги.\n\nМесть ждет старую ведьму Чарлгу Острый Бок, которая повелевает нечестивым воинством в Лабиринтах Иглошкурых.\n\nПринеси мне сердце этой ведьмы, <имя>, и я смогу спокойно умереть.", progress = "Как только я узнаю, что грязные твари Лабиринтов Иглошкурых изгнаны из их мерзкого логова, я упокоюсь с миром, зная, что месть свершилась.\n\nТы изгнал этих игрогривов из Лабиринтов? И подтвердишь свою весть, показав мне сердце этой ведьмы?", completion = "Теперь мерзкое племя Иглошкурых на себе испытает страдания моего народа! Пусть это будет им уроком.\n\nИзгнание целого народа из священной земли – этот грех заслуживает самой жестокой кары!\n\nБлагодарю тебя, Тузвколоде, за то, что откликнулся на мою просьбу.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБерилловое оплечьеРемень Каменного КулакаУкрашенный мрамором кулачный щит\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1103] = {title = "Зов Воды", objective = "Принесите Тьеву Мордуну, который находится в Серебряном бору, сапту воды, если вам не удалось поговорить с низшим воплощением воды.", description = "Привет, <братан/сеструха>! Ты тута, чтобы очистить воду и доказать Ислен, что не лыком <шит/шита>?\n\nЯ тока что прикончил оскверненного духа воды и как раз собираюсь сунуть его браслеты и остатки воды в жаровню.\n\nА эт што? А-а-а. Тьев понимает, бывает непруха. Что ж, Тьев нехило тебе поможет, если тебе снова нужен чистый водный дух.\n\nПринеси мне сапту воды от Ислен, покажи, что <готов/готова> к новому заходу, а я уж приготовлю тебе, че нужно.", progress = nil, completion = nil, rewards = nil},
[1104] = {title = "Яд Соляных равнин", objective = "Принесите 6 порций соленого яда скорпида Пшиксу Медноштифу на Мерцающую равнину.", description = "Я нарисовал уже столько чертежей нового болида! И все их надо непременно воплотить!!!\n\nЯ разрабатываю новое топливо, которое будет гореть жарко-жарко-прежарко! Пока что у меня не получается, но, кажется, я знаю, что мне может помочь...\n\nУ скорпидов с Мерцающей равнины совершенно особый яд, в нем чрезвычайно много солей. Он уникален! Как раз он-то мне и нужен.\n\nПринеси мне их яда и поверь: тогда наши болиды просто взлетят!", progress = "Привет-привет! Ну, где же яд?", completion = "Отлично! Этот яд как раз подойдет! Спасибо, Томпсон!\n\nТеперь надо его вскипятить, добавить скиппер-отомер и нега-катализатор и... Черт! Где мои записи?!", rewards = "Вы получите:\n\n"},
[1105] = {title = "Крепкие панцири", objective = "Принесите 9 крепких черепашьих панцирей Виззлу Медноштифу на Мерцающую равнину.", description = "Мой брат составляет новое топливо для болида. Он в этом деле просто гений! Правда, боюсь, его новое гениальное топливо разъест всю машину...\n\nПоэтому я хочу укрепить топливные баки.\n\nЗдесь, на равнинах, живут черепахи с очень прочными панцирями. Из них-то я и хочу сделать это покрытие – оно должно выдержать топливо моего брата.\n\nНу как, не желаешь ли взяться за эту работу и принести мне несколько панцирей?", progress = "Мой брат разрабатывает новое топливо, и это меня немного беспокоит... Мне нужно как можно быстрее сделать новый топливный бак!\n\nТомпсон, тебе удалось добыть черепашьи панцири?", completion = "Панцири! Спасибо, Томпсон!\n\nОго, да они еще тверже, чем я думал! Вот примусь с ними работать – так, поди, целый ящик инструментов погну!", rewards = "Вы получите:\n\n"},
[1106] = {title = "Мартек Изгой", objective = "Отнесите письмо Пшикса Мартеку Изгою в Бесплодные земли.", description = "Я разрабатываю новый двигатель, с которым мой болид помчится быстрее ветра! Помчится так, что даже сможет взлететь! Осталось мне сделать поршни, которые выдержат очень, очень высокое давление. Все мои испытания провалились потому, что я не смог сделать достаточно крепких поршней!\n\nНо есть тот, кто может мне помочь.\n\nЕго зовут Мартек Изгой. Он отличный кузнец и знает о металлах больше других. Вот, отвези ему это письмо, я знаю, он поможет мне!\n\nПравда, живет он далеко – в Азероте, в Бесплодных землях, в  одном лагере с гоблином!\n\nНайди его!", progress = "Что ж, вы нашли меня. Поздравляю.\n\nВы насчет топора, который я сделал для Гат'Илзогга? Или пришли защитить честь герцогини Пемей?\n\nА хотя какая разница... Если вы пришли драться со мной, то давайте скорее с этим покончим.", completion = "Тебя прислал Пшикс? Это все меняет! Разумеется, я помогу тебе. Пшикс и его брат – одни из немногих, кто не желает мне смерти.\n\nЗначит, Пшикс хочет сделать поршни, да? Да такие сильные, чтобы выдержали все, что он задумал, а зная Пшикса, могу точно сказать, что его новый болид – это вулкан на колесах!", rewards = "Вы получите:\n\n"},
[1107] = {title = "Средство против трения", objective = "Принесите 10 соленых хвостовых плавников Виззлу Медноштифту на Мерцающую равнину.", description = "Наш болид – это самая быстрая машина на равнинах! Она такая быстрая, что... я боюсь, что от трения ее разнесет на куски.\n\nЧтобы этого не произошло, мне нужен материал для покрытия движущихся частей машины. Он должен быть твердым, но не хрупким, и выдерживать соляную коррозию, иначе на Мерцающей равнине он долго не протянет.\n\nСлышали когда-нибудь про Коварный риф, <имя>? Это у побережья Тернистой долины. Там обитает племя мурлоков под названием Соляная Чешуя, и их хвостовые плавники как нельзя лучше подойдут для моего материала.", progress = "Эй, где там мои плавники? Если не защитить машину от ее же собственной скорости, долго она тут не протянет!", completion = "Спасибо, Томпсон! Осталось размолоть их, добавить кое-какие ингредиенты, и все будет готово. Тогда, по крайней мере, болид не пострадает от своей собственной скорости.\n\nЕще бы он от какого-нибудь препятствия не пострадал...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1108] = {title = "Индарилий", objective = "Принесите 10 пластин индарилия Мартеку Изгою в Бесплодные земли.", description = "Я здесь не только потому, что хочу держаться ото всех подальше. В Бесплодных землях очень много металла, <имя>, но добыть его сумеет не всякий.\n\nЭтот металл называется индарилий, и говорят, что он обладает удивительной сопротивляемостью к температуре и механическим воздействиям. Как раз то, что нужно Пшиксу для его машины.\n\nНо я должен все проверить. Принесите мне немного индарилия, а я исследую его свойства.\n\nНастоящая индарилиевая руда залегает глубоко в шахтах Ульдамана, но трогги из племени Каменного Свода иногда тоже носят с собой обломки индарилия. Принесите их мне.", progress = "Ну как, Томпсон, удалось добыть немного индарилия? Я тут уже свой горн раскочегарил, можно начинать плавить.", completion = "Да, то, что нужно. Положу их в горн и посмотрю, что будет.", rewards = "Вы получите:\n\n"},
[1109] = {title = "Груды гуано", objective = "Принесите 1 кучку гуано летучей мыши Лабиринтов мастеру-аптекарю Фаранеллу в Подгород.", description = "Как видишь, <имя>, в Королевском фармацевтическом обществе проводят весьма... любопытные эксперименты.\n\nПоскольку я мастер-аптекарь, в мои обязанности входит наблюдать за самыми интересными проектами. Работы полно, а времени в обрез!\n\nХоть ты и <класс>, но, судя по всему, немало <странствовал/странствовала>. Не поможешь мне?\n\nНам очень нужно редкое вещество. Оно на редкость мерзкое, и его получают только от особой разновидности летучих мышей, которые водятся в дыре под названием Лабиринты Иглошкурых. Принеси мне гуано летучих мышей Лабиринтов, и мы примемся за работу...", progress = "Вижу, ты вернулся. Удалось добыть гуано летучих мышей?", completion = "Превосходно! Этого нам и не хватало, Тузвколоде.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1110] = {title = "Обломки болидов", objective = "Принестие 30 деталей болида Крейвелу Углебраду на Мерцающую равнину.", description = "Хе-хе, да тут такие гонки бывают, как же без происшествий! Вы только оглянитесь – все Мерцающие равнины просто усыпаны обломками разбитых болидов.\n\nИ за все эти детали гномы и гоблины могут хорошенько заплатить. Они вечно ищут, какую бы еще рухлядь привинтить на свои тачки.\n\nСтупайте и принесите мне побольше деталей, а я вам хорошенько заплачу.", progress = "Томпсон, вы уже были на равнинах? Нашли какие-нибудь детали, которые я просил?", completion = "Ого, вы только посмотрите! Кое-что хорошее в этой горе металлолома еще есть. Наверняка я смогу продать это за кругленькую сумму.\n\nА... это что, оторванное ухо? Ой! Не хотел бы я быть на месте того пилота.\n\nСпасибо, Томпсон. Вот ваша плата. И еще бесплатный совет...\n\nДелайте вид, что вы круче всех – и тогда вам всегда удастся нагреть руки на чужой беде.", rewards = "Вы получите:\n\n"},
[1111] = {title = "Управляющий пристанью Головокружилкинс", objective = "Отнесите заказ на детали Крейвела управляющему пристанью Головокружилкинcу в Кабестан.", description = "Моя работа – выполнять запросы покупателей, а гномы заказали у меня набор деталей. Эти детали еще неделю назад прибыли в Кабестан, но я все никак туда не выберусь.\n\nМожет, ты туда смотаешься? Вот, надо будет найти управляющего пристанью Головокружилкинcа и отдать ему этот заказ.\n\nЕсли выполнишь мое поручение, я смогу доверить тебе и другие поручения.\n\nРазумеется, твой труд будет достойно оплачен.", progress = "Следующий! Так, ты отправитель или получатель?", completion = "Ах, да! Детали для Крейвела. Хорошо, что за ними пришли! Этот хлам валяется тут уже давно, я даже начал бояться, что он проржавеет!", rewards = "Вы получите:\n\n"},
[1112] = {title = "Детали для Крейвела", objective = "Отнесите Крейвелу Углебраду его детали на Мерцающую равнину.", description = "Вот посылка для Крейвела, <имя>. И когда отнесете, скажите ему... что если ему нужны еще особые заказы, то придется заплатить по всем счетам!", progress = "Вы уже забрали части из Кабестана?", completion = "Ура, детали! Надо отнести их гномам. Но сначала...\n\nВынем оттуда кое-что...", rewards = "Вы получите:\n\n"},
[1113] = {title = "Сердца Доблести", objective = "Мастер-аптекарь Фаранелл из Подгорода просит принести ему 20 сердец Доблести.", description = "Зачем мне редкий вид гуано, спросишь ты. Отвечаю. Я хочу выяснить в ходе эксперимента, какое воздействие окажут друг на друга два диаметрально противоположных химических вещества, особенно если оба смешать с токсичным реагентом, чтобы результаты были... погаже.\n\nВ северо-восточной части Тирисфальских лесов располагается Монастырь Алого ордена. В его стенах и за их пределами живут безумные последователи Алого ордена. Убей их и принеси мне их ревностные сердца\n\n.Наше варево будет поистине ужасающим.", progress = "Ты уже вернулся из Монастыря Алого ордена? Для этого восхитительного эксперимента мне понадобится много сердец!\n\nНе сомневаюсь, Вариматрас и Темная Госпожа будут рады, избавившись от алого сброда.", completion = "Сколько же на тебе кровищи, Блудикнайф! Я вижу, ты неплохо потрудился!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1114] = {title = "Заказ гномов", objective = "Отнесите хрупкие детали машины Пшиксу Медноштифу на Мерцающую равнину.", description = "Ну вот, у меня есть все, что нужно. Осталось только отнести эти детали Пшиксу Медноштифу. Он уже давно их ждет – полагаю, он даже не заметит отсутствие одной маленькой детальки. Не стоит даже упоминать, что я ее забрал.\n\nЭта деталька совсем маленькая и ненужная.\n\nПравда-правда.", progress = "Принес мне что-нибудь? Здорово! Ну-ка, посмотрим...", completion = "Вот они! Мои гидромеханизмы и усилительные болты! То, что нужно. Большое спасибо!", rewards = "Вы получите:\n\n"},
[1115] = {title = "Сплетник", objective = "Поговорите с Кразеком в Пиратской бухте.", description = "Ну вот, гномам услугу оказали, пора и гоблинам помочь!\n\nГоворят, что гоблинского пилота, Назза Парового Котла, раньше звали не так. Интересно, почему он сменил имя? Наверное, это секрет, и, скорее всего, он дорожит этим секретом.\n\nЕсли кто и знает правду, то только Кразек из Пиратской бухты, на южном мысу Тернистой долины. Поговорите с Кразеком и разузнайте у него про нашего пилота-гоблина.\n\nЕсли вам удастся добыть у него ценную информацию, то мы все сможем извлечь из нее прибыль.", progress = nil, completion = "Хотите узнать про Назза Парового Котла? Вроде это гонщик с Мерцающей равнины?\n\nДа, я могу кое-что разузнать про него, но это будет нелегко. И не сразу.\n\nИ не за бесплатно.", rewards = "Вы получите:\n\n"},
[1116] = {title = "Сонная пыль в болоте", objective = "Принесите 10 щепоток сонной пыли Кразеку в Пиратскую бухту. Сонную пыль можно собрать с дракончиков на Болоте Печали.", description = "Вытащить информацию из Назза – дело непростое, <имя>. Очень непростое. Но, раз уж вы ради этого приехали аж с Мерцающей равнины, то... не хотите ли попутешествовать еще немного?\n\nСобрали бы для меня кое-что, пока я буду связываться со своими источниками, а?\n\nХм... Что бы вам такое поручить? А, вот: сонная пыль с дракончиков из Болота Печали. Да, сонная пыль – это именно то, что мне нужно.\n\nПринесите мне ее, <имя>, а я взамен поделюсь с вами необходимой информацией.", progress = "Уже вернулись? И сонная пыль у вас есть?", completion = "Вот это да! Вы нашли сонную пыль!\n\nНу, и как там, на болотах? Говорят, горячей еды днем с огнем не сыщешь!", rewards = "Вы получите:\n\n"},
[1117] = {title = "Сплетни для Крейвела", objective = "Отнесите письмо с гоблинскими сплетнями Крейвелу Углебраду на Мерцающую равнину.", description = "Мне пришлось кое-кому оказать услугу, кое-кому подарить бутылку редкого эльфийского вина, а кое-что даже разузнать самостоятельно! Однако я добыл вам всю необходимую информацию.\n\nВот, я написал тут несколько интересных фактов касательно Назза Парового Молота. Делайте с ними что хотите, а для меня эта информация слишком опасна.\n\nИ не говорите никому, откуда вы ее достали!", progress = "Нашли что-нибудь на Назза Парового Молота? Есть у него какой-нибудь секрет?", completion = "Так-так! Интересно... Очень интересно. Хех, возможно, мне придется поздороваться с гоблинским пилотом при следующей встрече.\n\nЭта информация многого стоит, Маладат. Думаю, Назз согласится раскошелиться за то, чтобы его секрет не стал достоянием общественности.", rewards = "Вы получите:\n\n"},
[1118] = {title = "Назад в Пиратскую бухту", objective = "Отнесите план Крейвела Шиззи Пуззыриксу в Пиратскую бухту.", description = "<имя>, ты – <хороший/хорошая:c> <класс>, ты сможешь выполнить это задание и не болтать о нем налево-направо.\n\nЯ разрабатываю новый план. Он довольно рискованный, но если все получится, то мы озолотимся! А ты как раз отлично сможешь мне помочь.\n\nДля начала тебе надо вернуться в Пиратскую бухту. Прости, <дорогой/дорогая> <имя>. Я знаю, что ты уже <был/была> там по моему поручению, но в этот раз тебе надо будет поговорить с Шиззи Пуззыриксом.\n\nОтдай ему это письмо, а если он попросит помочь, то не откажи ему. Поверь, оно того стоит.", progress = "Здрасьте-здрасьте. Что такой благородный |3-6(Друид) делает в Пиратской бухте?", completion = "Понятно. Крейвел придумал очень хитрую схему. Он очень умен – в этом ему не откажешь.\n\nЗначит, вам нужно что-то для поднятия духа, так? Что-то сильнодействующее...\n\nДумаю, можно использовать смеси, которыми Занзил кормит своих зомби...", rewards = "Вы получите:\n\n"},
[1119] = {title = "Смесь Занзила и \"Дурацкое Крепкое\"", objective = "Отнесите \"Дурацкое Крепкое\" Крейвелу на Мерцающую равнину.", description = "Я понял, как смешать смесь Занзила с пивом, чтобы получилось убойное пойло – \"Дурацкое крепкое\"! Наверное, это именно то, что нужно Крейвелу. Отнесите ему, пусть попробует. Расскажете потом, как все прошло!\n\nКстати, <имя>, эту брагу надо употребить как можно скорее – смесь Занзила оказывает на пивную закваску не очень хороший эффект, так что оно очень скоро выдохнется.", progress = "Привет, Джакрозет. Кранк Шипучка согласился нам помочь?", completion = "Отлично! Гранк здорово помог нам! Обязательно отблагодарю его при встрече.\n\nИ вам спасибо, Джакрозет. Вы сделали большое дело, и оба мы заработаем на этом огромные деньги.", rewards = "Вы получите:\n\n"},
[1120] = {title = "Напоить гномов", objective = "Отнесите \"Дурацкое Крепкое\" начальнику гномского гаража.", description = "Надо напоить \"Дурацким Крепким\" одну из команд на пит-стопах.Хочешь посмотреть, как оно подействует на гномов? Тогда возьми эль и передай его начальнику гномского гаража.\n\nИ поторопись – эта бурда быстро выдыхается.", progress = "Привет! Есть что-нибудь для меня?", completion = "Крепкое пиво? Как мило! Спасибо большое!\n\nПеред гонкой, конечно, пить не стоит, но... Самую чуточку ребятам не повредит. Да и не такое уж оно крепкое, так ведь?", rewards = "Вы получите:\n\n"},
[1121] = {title = "Напоить гоблинов", objective = "Отнесите \"Дурацкое Крепкое\" начальнику гоблинского гаража.", description = "Надо напоить \"Дурацким Крепким\" одну из команд на пит-стопах.Хочешь посмотреть, как оно подействует на гоблинов? Тогда возьми эль и передай его начальнику гномского гаража.\n\nИ поторопись – эта бурда быстро выдыхается.", progress = "На что уставился?", completion = "Что это? Ах, выпивка?\n\nНу что ж, стаканчик-другой никогда не повредит...", rewards = "Вы получите:\n\n"},
[1122] = {title = "Возвращение к Пуззыриксу", objective = "Отнесите отчет о \"Дурацком Крепком\" Шиззи Пуззыриксу в Пиратскую бухту.", description = "\"Дурацкое Крепкое\" отлично сработало! Я сделал ставку на следующую гонку и... надеюсь, команда, которую вы напоили, не забыла поставить на своей машине номер.\n\nУ меня еще одно задание для вас: отнесите эту записку обратно Шиззи Пуззыриксу в Пиратскую бухту. Наверняка он захочет узнать, что эксперимент удался.\n\nНадо будет заказать у него еще этой выпивки для следующих гонок!", progress = "Здравствуйте, Джакрозет. Ну, как там сработала моя выпивка? Забористая штука, да?", completion = "Здесь сказано, что задумка с \"Дурацким Крепким\" удалась. Отличная новость!\n\nЕсли вам вдруг потребуется еще, дайте знать, и я отправлю вас добыть еще смеси Занзила.", rewards = "Вы получите:\n\n"},
[1123] = {title = "Рабин Сатурна", objective = "Поговорите с Рабином Сатурной в селении Ночная Гавань на Лунной поляне. Лунная поляна находится между Оскверненным лесом и Зимними Ключами, туда можно добраться по дороге, идущей от крепости Древобрюхов.", description = "Для этого эконом хранителя Лунной поляны Ремула – Рабин Сатурна – ищет помощи. Нужно обследовать обширные пустоши к западу от Танариса и Ун'Горо. Он живет в Ночной Гавани, главном поселении Лунной поляны.\n\nЯ хочу, чтобы ты <понимал/понимала> всю важность твоего присутствия там. Между ночными эльфами Дарнасса и Кругом Кенария Лунной поляны существуют трения. Но ты будь выше расовых предрассудков и прибегай к мудрости предков при общении с Кругом, <имя>. Да пребудет с тобой удача.", progress = nil, completion = "Я Рабин Сатурна. От лица хранителя Ремула и всех обитателей сего священного места привествую тебя.\n\nЯ ценю твою заинтересованность и горячую готовность помочь Кругу Кенария. Таурены не раз показывали стойкую приверженность принципам Кенария, и благодаря им Орда может пользоваться безопасностью Лунной поляны. Ведь благо Азерота – наша общая цель.\n\nЗдесь ты среди друзей, Томпсон.", rewards = "Вы получите:\n\n"},
[1124] = {title = "Пустошь", objective = "Поговорите с Лайо Зведным Всполохом близ кладбища Покой Доблестных в Силитусе и покажите ему письмо Рабина.", description = "К западу от Кратера Ун'Горо, за северо-западным гребнем, лежит суровый пустынный край – Силитус. Немногие помнят, что там в древности развернулась война между ночными эльфами и злобной, чужеродной силой. Зло было повержено и заключено в оковы, но мы подозреваем, что сейчас некие силы хотят пробудить этот... невыразимый ужас.\n\nНайди Лайо Звездный Всполох, одного из наших разведчиков в Силитусе. Ищи его в Покое Доблестных, последнеим приюте павших в этих пустынных краях. Передай ему это письмо, и он доверится тебе.", progress = "Эти земли не прощают беспечности, |3-6(Воин). Что привело тебя в пустоши Силитуса?", completion = "Так тебя послал Рабин? Что же, чувствуй себя как дома... если хоть кто-то может назвать домом этот богами забытый край.\n\nВо времена великих бед меня еще не было среди живых, но в этих краях есть места, которые наяву рисуют жуткую картину позабытого прошлого. С твоей помощью Круг Кенария, может быть, покончит с угрозой, которая, как мы думали, исчезла много поколений назад.", rewards = "Вы получите:\n\n"},
[1125] = {title = "Духи Южного Ветра", objective = "Освободите в деревне Южного Ветра души 8 истерзанных друидов и 8 истерзанных часовых и вернитесь к Лайо Звездному Всполоху на кладбище Силитуса, Покой Доблестных.", description = "На юго-западе находится очень грустное место – деревня Южного Ветра. Именно с нее мы и начнем, <имя>.\n\nСудя по всему, некогда она была базой ночных эльфов для военных действий в Силитусе. Ее давным-давно захватили силитиды. Страшно представить, что там творилось в момент захвата...\n\nПо руинам бесцельно бродят духи павших друидов и стражниц. Исследуй эти края и освободи страдающие души, как подобает.", progress = "Ни одно существо не должно мучиться, как неупокоенные души, неважно, Альянсу оно служило или Орде. Это доброе дело – освободить несчастных призраков, Лолкка.", completion = "Я подозревал, что немалую роль в гибели деревни сыграл огромный улей в башне неподалеку. Похоже, проделанная тобой работа подтверждает мои подозрения; улей представляет опасность для всей нашей деятельности.\n\nБлагодарю тебя за милость, оказанную душам павших. Я знаю, как нелегко это сделать. И все же я хочу вновь воззвать к тебе о помощи...", rewards = "Вы получите:\n\n"},
[1126] = {title = "Улей в башне", objective = "Осмотрите башню деревни Южного Ветра и отыщите способ разворошить улей. Принесите все необычное, что попадется при выполнении задания Лайо Звездному Всполоху на кладбище Силитуса, Покой Доблестных.", description = "Пора заняться ульем в деревне Южного Ветра, и мне кажется, я знаю, как это лучше сделать. Я знаю по опыту, что ульи силитидов очень чувствительны к окружающей среде; этим объясняется их нападения при звуках призрачного воя.\n\nСредоточие силы силитидов – башня, та самая, вокруг которой вьются осы. Ступай к этой башне и пробуди весь улей. Доложи обо всем, что удастся узнать, но соблюдай осторожность! Если попадется что-нибудь полезное, неси сюда.", progress = "Ну как, получилось? По крайней мере ты цел. Удалось что-нибудь отыскать?", completion = "Что за... Что это?\n\nОно имеет форму... ящика? А дрянью-то как заросло... Стой, здесь видна часть того, что внутри. Неужели под всей этой гадостью скрывается книга?\n\nКажется, тебе удалось найти кое-что интересное, Томпсон… по крайней мере, хочется на это надеяться. Может быть, это дневник или журнал, оставшийся с древних времен, лежавший в целости и сохранности под покровом хитиновой скорлупы.\n\nКажется, я знаю способ выяснить, что это.", rewards = "Вы получите:\n\n"},
[1127] = {title = "\"Дурацкое Крепкое\"", objective = "Принесите 12 порций смеси Занзила Шиззи Пуззыриксу в Пиратскую бухту.", description = "Говорите, вам нужно \"Дурацкое Крепкое\", да? Хотите снова отправиться на гонки?\n\nНу ладно, принесите мне еще смеси Занзила, и я наварю вам еще.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n\"Дурацкое Крепкое\""},
[1130] = {title = "Весть от Мелора", objective = "Поговорите с Мелором Каменным Копытом в Громовом Утесе.", description = "<имя>, Мелор Каменное Копыто узнал о ваших подвигах и наметил для вас путь.\n\nЕсли вы хотите пройти его, отправляйтесь в Громовой Утес и поговорите с Мелором. Его можно найти на вершине Охотников.", progress = nil, completion = "Итак, вы пришли, Демонорох... Значит, вы готовы к путешествию через дальние земли?\n\nРаз так, юный |3-6(Чернокнижник), то слушайте...", rewards = nil},
[1131] = {title = "Сталезуб", objective = "Принесите ребро Сталезуба Мелору Каменному Копыту в Громовой Утес.", description = "Иногда мы охотимся ради еды. Иногда – ради чести. А иногда мы охотимся для того, чтобы усвоить уроки Матери-Земли.\n\nНо охота, на которую я хочу отправить вас, не имеет с этими вещами ничего общего. Вам нужно будет убить существо, не подчиняющееся божественной воле Матери-Земли.\n\nГиена по кличке Сталезуб бродит по Тысяче Игл, к югу от Степей. К этой зверюге прибиваются другие гиены, и вместе они держат всех остальных более мирных животных в страхе.\n\nНайдите Сталезуба, <имя>. Найдите и убейте его.", progress = "Вы убили злобного Сталезуба, Торро?", completion = "Убив Сталезуба, вы избавили Тысячу Игл от страшной напасти.\n\nИ это, Торро, ваш урок на сегодня.", rewards = "Вы получите:\n\n"},
[1132] = {title = "Фиора Длинноушка", objective = "Поговорите с Фиорой Длинноушкой в Тераморе.", description = "О, как я хочу снова вернуться на море! Почувствовать поцелуй ветра, покачаться на волнах, как в детстве на руках у моей милой мамы!\n\nКак же вам повезло, <класс>, вы еще можете оказаться на морском берегу!\n\nЭто моя работа – рассказывать всем неутомимым искателям приключений Калимдора о море. Если хотите, садитесь на корабль и плывите в прелестный порт Терамор. Там поговорите с моей коллегой, эльфийкой по имени Фиора Длинноушка.\n\nОна отправит вас в незабываемое путешествие по Калимдору!", progress = nil, completion = "Добрый день! Вы приплыли из Гавани Менетилов по поручению мистера Флинта? О, мистер Флинт разбирается в людях! Если он послал вас сюда – значит, здесь ваше место.", rewards = "Вы получите:\n\n"},
[1133] = {title = "Путешествие в Астранаар", objective = "Поговорите с Шиндрелл Огненный Всполох в Астранааре.", description = "Если вы только что прибыли по морю из Менетила, отправляйтесь прямиком в Астранаар. Уверен, такому преданному члену Альянса будет, чем заняться в городе. Поговорите там с Шиндрелл Огненный Всполох и предложите ей свои услуги.\n\nНе стоит говорить ей, кто вас прислал. Шиндрелл меня не знает...", progress = nil, completion = "Эфром, вы здесь, чтобы предложить свою помощь Альянсу? Война уже добралась до этих мест, хотя Ясеневый лес все так же хранит свою красоту.", rewards = nil},
[1134] = {title = "Гордокрылы Каменного Когтя", objective = "Принесите 12 ядовитых желез славнокрыла Шиндрелл Огненный Всполох в Астранаар.", description = "Между нами и Ордой война не объявлена, однако мир между нами очень хрупок. Мы часто обнаруживаем, что среди нас тайно действуют их агенты. \n\nОб одной такой операции мы узнали из скрытых источников в Тераморе. Эти источники утверждают, что орки собирают яд славнокрылов поблизости от Мутного Озера в Когтистых горах, на юге. А потом орочьи убийцы используют этот яд для тайных смертоносных ударов против сил Альянса!\n\nЕсли это правда, мы обязаны остановить их, <имя>. Мы должны лишить их источника яда.", progress = "Тебе удалось добыть ядовитые железы славнокрыла, Wrestlecake? Мы не можем позволить оркам использовать яд этих тварей против нас!", completion = "Благодарю тебя, Wrestlecake. Мне не хотелось отправлять тебя убивать этих созданий, которые, возможно, не по своей воле помогали нашим врагам, однако это был мой долг.\n\nБыть может, друг мой, твое сердце оплакивает славнокрылов, которых тебе пришлось убить, однако пусть тебе принесет утешение то, что твои союзники больше не будут погибать от яда славнокрылов.", rewards = "Вы получите:\n\n"},
[1135] = {title = "Яд из Скального гнездовья", objective = "Принесите из Скального гнездовья 10 ядовитых желез для Фиоры Длинноушки в Терамор.", description = "Как вы уже знаете, орки часто приручают виверн в качестве ездовых животных. Но мало кто знает о том, что яд виверны порой может быть ценнее самого животного. Так что, если желаете немного поохотиться, то у меня есть для вас работа.\n\nВ Тысяче Игл – это к западу отсюда – есть место под названием Скальное гнездовье. Там живут виверны, яд которых очень силен и чрезвычайно высоко ценится.", progress = "Нашли Скальное гнездовье, Кинкс? Как вас встретили тамошние виверны?", completion = "О-о-о, некоторые чуть ли не лопаются от яда, Кинкс! Такие обычно собирают с очень юных виверн или с плодовитых самок. Наверное, нелегко вам пришлось в Скальном гнездовье!", rewards = "Вы получите:\n\nВетровой пояс"},
[1136] = {title = "Ледочрев", objective = "Принесите гриву Ледочрева Мелору Каменному Копыту в Громовой Утес.", description = "<имя>, настало время тебе отправиться в далекие земли. Ты <готов/готова> к этому путешествию. \n\nТебе поручается убить Ледочрева – йети, живущего в Альтеракских горах. Он отлично маскируется, его белая шкура сливается со снегами его горного обиталища. Увидеть его можно лишь изредка. \n\nНо я расскажу тебе, как приманить такое существо, как этот йети. Вот, возьми этот свиток: на нем я написал, как привлечь Ледочрева. \n\nА теперь ступай, <имя>. Путь предстоит долгий, впереди тебя ждут испытания. Задание будет выполнено, когда ты вернешься ко мне с гривой Ледочрева.", progress = "Был ли ты в Альтеракских горах, Томпсон? Ты встретился лицом к лицу с неуловимым йети Ледочревом?", completion = "Для того, чтобы найти и сразить Леочрева, нужно обладать силой и смекалкой, Томпсон. Оба эти качества у тебя есть. \n\nТвой путь привел тебя в долины Тысячи Игл и в высокие горы Альтерака. Однажды он проведет тебя по всем странам матери-земли – ведь именно таков путь охотника.", rewards = "Вы получите:\n\nГоловной убор охотника на духов"},
[1137] = {title = "Новости для Пшикса", objective = "Поговорите с Пшиксом Медноштифтом на Мерцающей равнине.", description = "Индарилий обладает невероятной сопротивляемостью нагреву! Наверняка он подойдет для поршней Пшикса. Но ему потребуется настоящая индарилиевая руда, а не эти пластинки...\n\nЭту руду нужно добывать в глубине Ульдамана, на северной границе Бесплодных земель, – там ее навалом.\n\nПередавайте Пшиксу Медноштифту привет и скажите ему все, о чем я поведал вам.\n\nСчастливого пути, <имя>. Думаю, мы с вами еще увидимся: как только Пшикс прознает про индарилий, он как пить дать отправит вас в Ульдаман.", progress = nil, completion = "Томпсон, ты вернулся! Ты нашел Мартека? Вы с ним поговорили? Что он сказал? Он поможет?\n\nГовори-говори-говори!!!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШустрая зажигалка ПшиксаПерчатки механика-гнома\n\nВы также получите:\n\n"},
[1138] = {title = "Дары моря", objective = "Соберите 6 кусочков отличного крабьего мяса для Груббера Блумпа в Аубердине.", description = "Мне нравятся крабы. Крабы – это деликатесные дары моря! Их можно печь, жарить на гриле, варить, делать из них бульон. Еще их можно жарить на сковороде, во фритюре и просто жарить. Есть крабовый салат, крабовый суп, краб тушеный, краб перченый, краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый десерт. Вот и... ну, и все.\n\nЯ здесь сейчас рыбу ужу, потому охотиться на сочных крабов мне некогда. Можешь извлечь кусочки отличного мяса из рифовых крабов и покрытых илом крабов. Их можно печь, жарить на гриле, варить...", progress = "...краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый сюрприз. Вот и... ну, и все.", completion = "Да-а-а, эти кусочки отличного крабьего мяса – как раз то, что мне нужно. Спасибо, Wrestlecake! Вот, это я обнаружил как-то, когда рыбачил, и мне оно без надобности. Может быть, ты сможешь как-то это использовать? В деликатесные блюда из крабов это уж точно не положишь.\n\nЯ ведь уже рассказывал тебе о крабах, правда?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛущеные перчаткиПанциревидные сапоги\n\nВы также получите:\n\n"},
[1139] = {title = "Утерянные таблички Воли", objective = "Найдите табличку Воли и принесите ее советнику Белграму в Стальгорн.", description = "Мы смогли сдержать клан Кузни Теней, отрезав их силы от пика Черной Стали, но задание Тяжелоступа еще не выполнено. Его смерть не должна быть напрасной. Он мечтал найти табличку Воли: камень, на котором высекли магические письмена сами титаны, чтобы вдохнуть жизнь в созданных ими существ, – по крайней мере, так гласят легенды. \n\nМы должны заполучить табличку Воли прежде, чем до нее доберется клан Кузня Теней. \n\nВозвращайся в Ульдаман, найди табличку и принеси ее мне незамедлительно.", progress = "Мы должны выполнить завет Тяжелоступа, Тарлемар! Я столь многим обязан ему. \n\nТвоя экспедиция в Ульдаман служет не только этой цели, но и благу всего рода дворфов! Если табличка попадет в руки Черного Железа, кто знает, какую армию големов они смогут создать!", completion = "*При виде таблички советник Белграм изумленно качает головой*\n\nТарлемар, это поразительно! Я прослежу, чтобы табличка была доставлена королевским магам как можно скорее. Они непременно пожелают проверить, что в легендах истина, а что ложь. Ты помог нашему народу более, чем я смел надеяться!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nМедаль за отвагу"},
[1140] = {title = "Башня Алталакса", objective = "Освободите заточенные души высокорожденных на Ночной поляне и Сатирнааре, затем вернитесь к Делгрену Очистителю на заставу Мейстры.", description = "Орочьи письмена немногим лучше детских каракулей. Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов. \n\nИз каракулей Илкруда можно понять, что у Атрикуса еще оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса.\n\nПоосторожнее там, <имя>, от вида кровавых храмов сатиров содрогнется даже <такой закаленный/такая закаленная:c> <класс>, как ты.", progress = nil, completion = "Возможно, мы слишком долго терпели сатиров в этом лесу. Я поговорю с Элиссой насчет этого, когда в другой раз поеду в Аубердин.\n\nТем не менее, раз самоцветы души уничтожены, сила Атрикуса сильно уменьшится. Мы должны воспользоваться этой возможностью и уничтожить его и его культ.", rewards = "Вы получите:\n\n"},
[1141] = {title = "Семья и рыболовная удочка", objective = "Поймайте 6 окуней Темного Берега для Груббера Блумпа в Аубердине.", description = "Мне нравится рыбачить. Семья Блумп славится своими рыбаками. Меня зовут Груббер Блумп. Я рыбак.\n\nЕсть одна рыбка, которую я хотел бы поймать в этих водах – местная разновидность окуня. Я раньше ходил на окуня на лодке, но с тех пор как побережье оккупировали эти противные мурлоки, ни одна лодка в море не выходит. Боюсь, они и окуней всех съедят.\n\nСлушай, хочешь помочь мне наловить окуней? Я б тебе от чистого сердца подарил фамильную удочку семьи Блумп! Это очень хорошая удочка!", progress = "Из окуней с Темного Берега можно приготовить множество вкусных блюд. Окуни хороши на вкус, но ловить их, я думаю, еще приятнее.\n\nТы еще не наловил окуней Темного Берега?", completion = "Какие отличные окуни, Эфром! Большое спасибо за помощь!\n\nТы как минимум такой же хороший рыбак, как моя драгоценная родственница Граун Блумп. У нее, правда, растет борода и от нее несет чем-то странным, но это для нее не причина перестать рыбачить. Думаю, ты обладаешь необходимыми качествами, чтобы пользоваться удочкой семьи Блумп.", rewards = "Вы получите:\n\nУдочка семейства Блумп"},
[1142] = {title = "Последнее желание", objective = "Найдите подвеску Трешалы и верните ее Трешале Бурый Ручей в Дарнасс.", description = "Мне недолго осталось жить... о, я так слаб...\n\nХмурен... храбрый дворф, он отправился... предупредить Фалфиндера...\n\nНо прежде, чем я умру... \n\nПожалуйста, верни моей жене ее подвеску... ее украл один из этих негодяев...\n\nПодвеска связывает нас... это очень важно... Пожалуйста, верни подвеску моей Трешале... в Дарнасс... \n\nИ расскажи ей... о моей смерти.", progress = "Что привело тебя ко мне, |3-6(ночной эльф)?", completion = "О нет! \n\nНе может быть! О, я не верю! О, жестокий мир! \n\nМне предстоит весь век нести в сердце горе... Я не позволю делу Гералата погибнуть вместе с ним! \n\nБлагодарю тебя за то, что ты проделал этот опасный путь, Борро. Но теперь оставь меня. \n\nЯ оплачу мужа в одиночестве...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТраурная шальУланские сапоги\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1143] = {title = "Башня Алталакса", objective = "Убейте Атрикуса Нарассина и принесите его голову Балтулу Удару Тени у башни Алталакса.", description = "Понятно. Ну если то, о чем ты говоришь, – правда, то сейчас самое время нанести удар. Я уверен, что Атрикус обосновался на самом верху башни. Однако будь начеку, его окружает множество сильных чернокнижников, гораздо более опасных, чем те, с кем тебе доводилось встречаться ранее.", progress = "Атрикус Нарассин – древний и могущественный чернокнижник. Может быть, нам стоило бы подождать, пока сам Делгрен не придет на помощь, но он, очевидно, очень сильно верит в вас, раз уж послал вас в одиночку.", completion = "Я надеюсь, что после смерти Атрикуса демонические силы в этом районе отступят. Я не сомневаюсь, что они перегруппируются и вернутся, но тогда мы будем еще лучше подготовлены, чтобы встретить эту угрозу лицом к лицу.", rewards = "Вы получите:\n\n"},
[1144] = {title = "Импортер Вилликс", objective = "Сопроводите Вилликса из Лабиринтов Иглошкурых.", description = "Наконец-то, помощь пришла!\n\nТы не представляешь, как долго я уже здесь торчу!\n\nВидишь ли, я предприниматель. Как говорится, всегда ищу выгоду. Вот, прослышал, что Мебок Миззрикс дает хорошую цену за растущий здесь корень краснолиста. Ну я и подумал, что на этом можно обтяпать неплохие денежки. Как видишь, жестоко ошибался!\n\nВытащи меня отсюда, я тебе хорошо заплачу!", progress = nil, completion = "Уф... спасибо, дружище! А вот и обещанная награда – за мной не заржавеет!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо ОбезьяныКольцо ЗмеиКольцо Тигра\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1145] = {title = "Рой растет", objective = "Отнесите запечатанную записку Коррана Белгрому Каменной Булаве в Оргриммар.", description = "Многие путешественники, приходившие в Перекресток, помогали мне собирать яйца на Полях Великанов, а потом рассказывали, какие страшные твари там живут. Мне хватило этих рассказов, чтобы убедиться в том, что мой хозяин недооценил этих насекомых, и что на самом деле они гораздо опаснее.\n\nМне нужен кто-то, кто отправится в Оргриммар и встретится там с Белгромом Каменной Булавой. Это очень серьезное дело, которое можно поручить только ответственному посыльному.\n\nБелгрома почти всегда можно найти у цехового дома воинов.", progress = "Я завидую вам, |3-6(Воин). Похоже, вы давно не бывали в Оргриммаре...\n\nЯ бы и сам отправился в путешествие, во славу Вождя, но Траллу я нужен здесь. Однако он очень мудрый правитель, и я верю ему. Я готов оставаться здесь столько, сколько буду ему нужен.", completion = "А, записка от Коррана. Он служит уже давно и очень преданно. Я как раз собирался узнать, как у него дела в Перекрестке.", rewards = "Вы получите:\n\n"},
[1146] = {title = "Рой растет", objective = "Доставьте запечатанное письмо Белгрома Моктару Крину в Тысячу Игл.", description = "Значит, Корран пришел к похожему заключению относительно этих насекомых: они представляют собой гораздо большую угрозу, чем мы думали.\n\nНесколько дней назад из Тысячи Игл ко мне вернулся полумертвый охотник. Его с отрядом отправили на Мерцающую равнину, чтобы выгнать оттуда бригаду дворфов-археологов, но во время боя на месте раскопок появились эти насекомые и чуть было не положили весь отряд.\n\nГлавным у них был Моктар Крин, и сейчас они разбили лагерь на границе Мерцающей равнины. Отнесите ему это письмо.", progress = "Нас привела на Мерцающую равнину война. А что привело вас сюда, Томпсон?", completion = "Не обращайте внимания на это грохочущее эхо. Это всего лишь гонка гномов и гоблинов на Равнинах – они носятся на кошмарных машинах, созданных по всем правилам так называемой \"науки\". Однако в Тысяче Игл есть куда более серьезные опасности, одна из которых недавно унесла жизни большей части моего отряда.\n\nНо мы останемся здесь до тех пор, пока не получим известие от Белгрома из Оргриммара. До этого мы будем держать позицию и стоять на страже.", rewards = "Вы получите:\n\n"},
[1147] = {title = "Рой растет", objective = "Убейте 5 силитидов-искателей, 5 силитидов-трутней и 5 силитидов-захватчиков, а потом вернитесь к Моктару Крину в Тысячу Игл.", description = "Хмм. Значит, Белгром считает этих монстров опасными и хочет, чтобы их загнали в те глубины, из которых они некогда выползли.\n\nЕму, значит, недостаточно того, что мы убили всех дворфов из Лиги Исследователей – надо посылать полумертвый отряд в новый бой! Сами мы не справимся, по крайней мере в таком состоянии. Карьер находится к югу отсюда, и дворфов там, скорее всего, больше нет. Не хочешь ли помочь нам своим клинком или посохом?", progress = "Куча народу приезжает на Мерцающие равнины, чтобы посмотреть гонки. Думаю, мы найдем достаточно искателей приключений для того, чтобы избавиться от этих насекомых. А до тех пор мой отряд не сможет покинуть этот пост.", completion = "Ха! Эта лимфа, которой ты покрыт с ног до головы, только красит тебя, Томпсон! Хотя воняешь ты так, что аж глаза режет... Не подходи слишком близко к кодом, а то они сбегут или набросятся на тебя.\n\nДумаю, мои товарищи согласятся принять этот запах за убедительное доказательство того, что ты помог нам справиться с этими мерзкими насекомыми. Спасибо, Томпсон.", rewards = "Вы получите:\n\n"},
[1148] = {title = "Части роя", objective = "Добудьте 1 сердце, 5 шпор и 3 целых силитидских панциря для Коррана из Перекрестка.", description = "Вы тщательно осматриваете панцирь. Повращав его в руках, вы видите, что полоски хитинового покрытия переплетены совершенно неповторимым образом, что делает панцирь невероятно прочным. Вы никогда в жизни не видели ничего подобного. Вы осматриваете останки дальше и понимаете, что эти существа очень сильны и высокоразвиты.\n\nЕще раз взглянув на эти останки, вы думаете, что Коррану было бы интересно обследовать этих существ поподробнее. Это помогло бы ему понять, кто они и откуда взялись.", progress = "Ага, давненько ты ко мне не заглядывал, Томпсон. Чем я могу тебе помочь? Похоже, на тебе еще не обсохла кровь врагов? Это хорошо. Хорошо и для вас, и для Орды, потому что чем больше битв вы пройдете, тем сильнее станете.", completion = "О, так вы недавно виделись с Моктаром? Он всегда заботился обо мне. Жаль слышать, что он тратит свое время на то, чтобы присматривать за своей группой, вместо того чтобы самому участвовать в бою... Но, думаю, ему нравится убивать членов Лиги Исследователей.\n\nХорошо, что вы принесли мне эти образцы, Томпсон. Мы собрали и другие яйца насекомых на Полях Великанов, так что теперь у меня есть хороший материал для изучения. Скоро я смогу узнать, что это за насекомые и чего они хотят.", rewards = "Вы получите:\n\n"},
[1149] = {title = "Испытание веры", objective = "Если ваша вера сильна, прыгните с досок над Тысячью Игл.", description = "Итак, ты <нашел/нашла> меня – или, возможно, тебя привела сама судьба? Это неважно. Теперь ты здесь, и перед тобой лежит новый путь.\n\nЛичность складывается из многих из многих граней: души, тела и разума. Некоторые из этих аспектов определяются культурными традициями, о наличии других мы можем только догадываться. Если согласишься, я испытаю некоторые присущие тебе качества.\n\nЕсли ты пройдешь испытание, то станешь сильнее, если же нет – познаешь всю бездну Пустоты.\n\nПервое испытание – это испытание веры.", progress = "Вера. Она куда важнее, чем считают многие.\n\nИногда не важно, во что ты веришь, главное – верить.", completion = "Истинную силу нашего духа мы можем познать лишь при встрече с непредвиденной бедой. Ты поверил в себя, хотя и не был уверен, что выживешь. Твой разум открыт, и твой дух готов встретить все, что ждет впереди.\n\nЕсли желаешь, можешь приступить к следующему испытанию.", rewards = "Вы получите:\n\n"},
[1150] = {title = "Испытание выносливости", objective = "Принесите коготь Гренки Дорну Вольному Ловчему в Тысячу Игл.", description = "Хорошо, что ты не теряешь смелости несмотря ни на что. Твоя вера крепка, и теперь настало время испытать твою силу.\n\nСначала тебе надо пройти испытание выносливости. Отправляйся в Логово Легкоперых – оно к западу от Заставы Вольного Ветра. Проберись в самое сердце логова и уничтожь там все запасы еды. К тому времени местные гарпии будут в ярости, и если ты останешься в живых, с тобой прилетит сразиться их предводительница – Гренка Кровавый Визг. Убей ее и принеси мне ее коготь, чтобы пройти это испытание.", progress = "Чтобы пройти все назначенные испытания, ты должен подготовиться морально, духовно и физически.\n\nМы слишком часто рвемся вперед неподготовленными. Я считаю своим долгом подготовить всех новичков, которые приходят ко мне, вне зависимости от их племени. Они должны знать, с чем им предстоит столкнуться за порогом родного дома.", completion = "Гренка была очень сильна даже для такого |3-1(нежить) как ты. Сегодня ты можешь по праву гордиться собой.\n\nВо время испытания веры ты показал силу своего духа, а сегодня подтвердил, что физически ты готов к битве. Гарпии Легкого Пера мертвы, и теперь настало время нового испытания.", rewards = "Вы получите:\n\n"},
[1151] = {title = "Испытание силы", objective = "Принесите фрагменты Рок'Алима Дорну Вольному Ловчему в Тысячу Игл.", description = "Во времена Древних богов элементалей можно было встретить повсюду. Они поклонялись Древним богам, а боги своей силой поддерживали связь духов с этим миром. Когда же Древние боги были изгнаны, элементали тоже покинули этот мир и теперь являются сюда только по зову могущественных магов.\n\nНо есть и исключения. Некоторые духи были достаточно сильны для того, чтобы остаться в этом мире, и одного из них зовут Рок'Алим.\n\nДля того чтобы испытать свою силу, найди в Тысяче Игл Рок'Алима и убей его.", progress = "Племена кентавров зовут Рок'Алима Крушителем – из-за грохота, который издают его кулаки, которые он обрушивает на тех, кто достаточно смел или глуп для того, чтобы оказаться у него на пути.", completion = "Испытание силы пройдено. Вы показали свою силу и храбрость и теперь готовы к последнему испытанию, после которого эти ритуалы завершатся.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1152] = {title = "Испытание знаний", objective = "Найдите Брауга Тусклый Дух возле входа в Туннель Когтя в Когтистых горах.", description = "Твои испытания почти закончились, но проверку знаний проводить буду не я. Тебе придется посетить другие места и усвоить там новые уроки.\n\nЕсли ты <готов/готова>, найди Брауга Тусклый Дух – это очень мудрый шаман. Внимательно выслушай его и выполни все, что он скажет, <имя>.\n\nБрауга можно найти около туннеля, соединяющего Когтистые горы и Ясеневый лес. И будь <осторожен/осторожна>, <имя>, ночные эльфы могут помешать тебе.", progress = nil, completion = "Гоблины терзают землю, ночные эльфы унижают младшие расы, а дни и ночи тем временем становятся все холоднее и холоднее. Отрекшиеся и орки – не единственные, кого нужно винить за конфликты, возникшие на землях Калимдора и Лордерона. Многие разумные расы причинили миру немало боли. Дорн знает об этом, и он отправил вас ко мне, потому что вы тоже способны это понять.\n\nСейчас вы стоите перед Браугом.", rewards = "Вы получите:\n\n"},
[1153] = {title = "Образец новой руды", objective = "Отберите неочищенный образец руды у землекопа или геодезиста из племени Камнерылов и принесите его Таттернаку Стальному Горну в Лагерь Таурахо в Степях.", description = "<класс>, раньше вы часто помогали мне в разных делах. Пока что вождь доволен моими успехами и просит меня продолжать с новой решимостью. По закону чести, я должен рассказать вождю обо всем, что вы сделали для нас, но вначале я хотел бы снова попросить вас о помощи.\n\nНедавно я встречался с путешественниками, которые пришли с юга, из места под названием Тысяча Игл. Там они убили кобольда, у которого при себе был образец необычной руды, но они отказались его продавать. А он мне очень нужен для исследования!", progress = "Потом я встретился с путешественниками снова – с теми самыми, что не продали мне образец руды. Я плюнул в них за то, что они не стали помогать вождю.\n\nПусть они умрут в бою как трусы, а не как благородные воины, вставшие на сторону Орды.", completion = "Хороший образец, Томпсон. Очень хороший.\n\nВы замечательно справились с заданием, и эти путешественники больше не смогут задирать передо мной нос.\n\nЯ немедленно начну работать с ней, и если руда окажется достаточно прочной, я изготовлю из нее оружие и отправлю вождю, чтобы он посмотрел на наши успехи.\n\nЯ не забуду вашей помощи, |3-6(Охотник).", rewards = "Вы получите:\n\nОркский боевой меч"},
[1154] = {title = "Испытание знаний", objective = "Найдите книгу \"Наследие Аспектов\" и вернитесь к Браугу Тусклому Духу ко входу в Туннель Когтя.", description = "Ты <прошел/прошла> испытание Дорна и хочешь пройти следующее? Что ж, хорошо. Но все предыдущие испытания были детскими играми. Физическую силу испытать легко – то ли дело сила разума!\n\nЛадно, объясню попроще: найди книгу, которую я назову, изучи ее и ответь на мой вопрос по ее содержимому.\n\nТы спросишь, что за книга? Она называется \"Наследие Аспектов\". Ее можно найти в глубине обители Дор'Данил, это в южном Ясеневом лесу. Книгу охраняют мертвые друиды и их убийцы.", progress = "Принеси мне книгу, когда прочитаешь ее. До этого я не буду задавать тебе вопросов.", completion = "Это та самая книга, о которой я говорил. Полагаю, тебе известен ответ на мой вопрос – если только ты не поленился изучить книгу.\n\nКак только будешь готов, обратись ко мне, и я задам тебе вопрос.", rewards = "Вы получите:\n\n"},
[1159] = {title = "Испытание знаний", objective = "Найдите Парквела Финталласа в Подгороде.", description = "Отличная работа, <имя>. Ты <прошел/прошла> первую часть испытания знаний, но еще один вопрос остался без ответа. Правда, задавать его буду не я.\n\nПоговори с Парквелом Финталласом в Лордероне – до того как пасть жертвой Чумы, он был великим историком среди людей. Он до сих пор стремится к просвещению, но уже по-другому.\n\nОн даст тебе задание, и только потом задаст вопрос – но до сих пор ты <справлялся/справлялась> хорошо, и, я уверен, трудностей у тебя не возникнет.", progress = nil, completion = "Тебя прислал Брауг? Невероятно.\n\n*Парквел критически осматривает вас.*\n\nСправился в Дор'Даниле, прошел испытание веры и совладал с могущественным элементалем? Ха! Да ты, наверное, наслушался разговоров в таверне и теперь нагло врешь мне! Думаешь, что сможешь пройти мое испытание? Ну что ж, хорошо... |3-6(Разбойник).", rewards = "Вы получите:\n\n"},
[1160] = {title = "Испытание знаний", objective = "Найдите книгу \"Истоки угрозы нежити\" и отнесите ее Парквелу Финталласу в Подгород.", description = "Я скажу тебе, что искать, и даже задам вопрос, но не потому, что тебе хочется проявить себя. Знания гораздо важнее силы. Даже если кто-то силой превосходит тебя, твои знания о мире могут оказаться куда полезнее.\n\nОтправляйся в монастырь на севере Тирисфальских лесов. В их библиотеке есть книга под названием \"Истоки угрозы нежити\" – по ней ныне обезумевшие паладины учатся истреблять моих собратьев.\n\nПринесите ее мне.", progress = "Надеюсь, ты доставил Алому ордену достаточно неприятностей перед тем, как украсть книгу.\n\nМое отношение к ним отнюдь не беспочвенно. Возможно, когда-то его участники и почитали Свет, но теперь они стремятся лишь уничтожить всех, кто не принадлежит к их религии. Они считают, что вся нежить – Отрекшиеся и все остальные – должна быть уничтожена, а тех, кто путешествует в земли нежити, они считают либо безумцами, либо рабами сильной магии. Идиоты. Идиоты и глупцы, все до единого.", completion = "Это та самая книга, которую я велел тебе найти.\n\n*Парквел нежно проводит рукой по обложке, разглядывая ее.*\n\nЗначит, ты хочешь, чтобы я задал тебе вопрос, чтобы ты мог доказать, что твой дух так же силен, как и тело? Если ты хорошо изучил книгу, то я задам тебе вопрос, и с испытаниями будет покончено.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1164] = {title = "Ограбить воров", objective = "Принесите головы Кенаты, Фардела и Марселя Дабири Генви Кэллоу в Подгород.", description = "Воровка! Свинья! Кената все еще жива, ее семья живет и процветает, а я страдаю. Вот уж действительно Отрекшаяся!\n\nВсю мою семью забрала чума. Все наше имение тоже разорили во время войны. И теперь она и ее мерзкие дети имели наглость похитить у меня последние ценные вещи.\n\nСами вещи мне уже не нужны. Теперь я жажду мести!\n\nУбей этих проходимцев! Ступай в усадьбу Дабири в Арати, на северо-востоке от Опорного пункта.", progress = "Убей их и принеси мне головы!", completion = "Ты стоишь передо мной, словно посланник Мести, и я склоняюсь в знак признательности.\n\nЖирная корова мертва, и я, зная, что ее потомки не будут топтать землю Азерота, могу потратить силы на что-нибудь более разумное. Надеюсь, прикончив их, ты ограбил усадьбу?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛютое наплечьеГалланские манжеты\n\nВы также получите:\n\n"},
[1166] = {title = "Заботы властителя Мок'Морокка", objective = "Принесите Мок'Морокку его грог, табак и сейф на Пыльную трясину.", description = "Твоя кланяться властитель Мок'Морокк!\n\nРексар назначить меня правителем клана Каменного Молота!\n\nМоя хороший вождь! Моя бережет свой клан!\n\nБольшие драконы прилетать и жечь наш старый дом. Моя – умный огр! Моя найти здесь новый дом для свой клан. \n\nБросать старый дом так быстро, что забыть моя вещи. <Маленький/Маленькая:r> <раса>, ты идти и приносить моя вещи. Идти на юг и приносить мой вкусный грог, мой табак и мой сейф. Я благодарить твоя, когда твоя сделать это. Твоя искать в Обители Пламени и в руинах Деревни Каменного Молота. Они быть там, моя уверен.", progress = "Моя хотеть свой грог. И свой табак. Где мой сейф? Твоя идти и приносить все властителю Мок'Морокку. Моя слишком занят, моя управлять ограми.", completion = "Хороший |3-6(нежить). Моя скучать по этим вещам. Моя теперь дружить с твоя.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nОгромные огрские сапоги"},
[1167] = {title = "Башня Алталакса", objective = "Поговорите с Балтулом Ударом Тени возле башни Алталакса.", description = "Прежде чем встретиться с Атрикусом, разумно было бы тебе посоветоваться с Балтулом. Не сомневаюсь, что он неусыпно следил за башней и может знать о недавних событиях.", progress = nil, completion = "А, приятно снова свидеться, Wrestlecake! Тут такие странные вещи творились, так что хорошо, что ты снова тут появился!\n\nОчень странные вещи, Wrestlecake. Все казалось как обычно – ну, насколько тут вообще все может быть обычно – и вдруг на верхнем этаже башни как полыхнет! Потом начались вопли. Вопли раскалывали воздух, а в землю порой били молнии. Что все это может значить?", rewards = "Вы получите:\n\n"},
[1168] = {title = "Армия Черного дракона", objective = "Убейте для Тхарга из Деревни Гиблотопь 15 Огнегривых Разведчиков, 10 Огнегривых Пеплохвостов и 5 Огнегривых чешуйчатых губителей.", description = "Мок'Морокк получил власть от Рексара. Но он больше любил власть, чем огров.\n\nЧерные драконы убили много огров. Убили жену Тхарга. Мок'Моррокк велел нам бежать. Заставил прийти сюда.\n\nОгры должны биться. Ограм плохо бегать. Мок'Морокк думает только о Мок'Морокке.\n\nМой дом в руинах Деревни Каменного Молота. Мне нравится там на юге. Здесь не наш дом.\n\nПомоги ограм победить войско черного дракона. Мы хотим отомстить. Мы хотим домой.", progress = nil, completion = "Ты убил многих из войска Черного дракона. Ты – отважный |3-6(нежить)! Тхарг счастлив!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШнуровка ТаргаДиск Тарга\n\nВы также получите:\n\n"},
[1169] = {title = "Корни угрозы", objective = "Принесите Драз'Зилбу в Деревню Гиблотопь 15 огненных языков и 15 пылающих сердец.", description = "Пока этот трусливый глупец Мок'Морокк упивается властью, а Тхарг борется с тоской и жаждой мести и оспаривает у него власть над кланом, – я, кажется, единственный, кто хочет установить источник бед, обрушившихся на нас.\n\nПочему ты так озадаченно смотришь на меня, <имя>? <Думал/Думала>, я буду говорить как неотесанный чурбан только потому, что я – огр?\n\nНо к делу. Принеси мне сердца и языки дракончиков, только что вылупившихся из яиц, и я найду корни этого зла.", progress = "Теперь я смогу узнать, что за тварь напустила на нас свои отродья. Возможно, зная больше о захватчике, мы сможем понять, как уничтожить его раз и навсегда и поднять деревню Каменного Молота из руин.\n\nКонечно, заставить Мок'Морокка оторвать свой толстый зад от земли, – уже само по себе героический поступок...", completion = "Рискованное было дельце, добывать все эти сердца и языки, а? Теперь я проникну в глубины тайн, чтобы выяснить, откуда на наш прежний дом свалилась такая напасть.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОпаленная накидкаПерчатки угонщика\n\nВы также получите:\n\n"},
[1170] = {title = "Выводок Ониксии", objective = "Поговорите с властителем Мок'Морокком в Деревне Гиблотопь.", description = "Деревня Каменный Молот была захвачена выводком Ониксии. Но почему дочь великого дракона Смертокрыла вторглась в наши земли? Вот что тревожнее всего!\n\nНеужели только для того, чтобы уничтожить небольшое поселение огров?\n\nПредупреди Мок'Морокка. Нельзя сидеть сложа руки!", progress = nil, completion = "Почему ты говорить с моя про драконы? Моя не любить драконы. Моя не хотеть здесь никакие драконы.", rewards = "Вы получите:\n\n"},
[1171] = {title = "Выводок Ониксии", objective = "Поговорите с Драз'Зилбом в Деревне Гиблотопь.", description = "Твоя уходить. Твоя идти и сказать Драз'Зилбу, мы оставаться здесь. Здесь нет никакой черный дракон.", progress = nil, completion = "Жалкий трус!\n\nМок'Морокк выказывал силу, пока нашим вождем был Рексар. Но после его ухода Мок'Морокк начал сам стремиться к власти. Он предпочитал требовать, вместо того чтобы руководить. Он не заботится о своих подданых, а наоборот хочет, чтобы мы заботились о нем.\n\nС этим надо что-то делать!", rewards = "Вы получите:\n\n"},
[1172] = {title = "Выводок Ониксии", objective = "Драз'Зилб из Деревни Гиблотопь хочет, чтобы вы уничтожили 5 яиц Ониксии.", description = "Выводок Ониксии расползся по всей Земле Драконов. Нельзя допустить, чтобы и остальные ее отродья вылупились на свет!\n\nПоспеши в Драконьи топи на юге Пылевых топей. Наверняка она устроила там свое логово. Найди яйца злой драконихи и уничтожь их!\n\nМы никогда не вернем себе деревню Каменного Молота, если вокруг будут продолжать плодиться драконы.\n\nА что касается Мок'Морокка... касательно этого червя у меня есть особые планы.", progress = "Тебе надо поспешать в Землю Драконов, Бумшакалака. Пока Драконья топь завалена яйцами Ониксии, они всегда будут превосходить нас числом. Поторопись же.\n\nУничтожь ее яйца! Не дай драконьей заразе расползаться по нашим землям!", completion = "Прекрасно! Теперь Ониксия не скоро отложит очередную кладку.\n\nБлагодарю тебя, Томпсон, от имени моего народа.\n\nЯ уже о многом просил тебя, но, может, ты окажешь последнюю услугу клану Каменного Молота.\n\nМок'Морокк не достоин править нами. Тхарг стал бы отличным вождем, но он стар и изранен. Изгони силой из этих мест Мок'Морокка. Только тогда мы сможем избрать нового вождя, который отведет нас на родину, в южные земли.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЭнкарминные сапогиСапоги Зула'тека\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1173] = {title = "Вызов властителю Мок'Морокку", objective = "Победите Мок'Морокка и сообщите об этом Драз'Зилбу в Деревне Гиблотопь.", description = "Ты осмеливаешься вызвать на поединок властителя Мок'Морокка?\n\nХа!\n\nМеня хочет сокрушить <жалкий/жалкая:r> <раса>!\n\nПриготовишься к трепке – скажи мне.", progress = nil, completion = "Эта трусливая туша, Мок'Морокк, сбежал как испуганный младенец при виде розги. Ты оказал нам огромную услугу, Томпсон.\n\nТеперь мой народ может выбрать себе нового лидера, того, кто поможет восстановить наши жилища и защитить их.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДьявольский стачивательХолодный рассекатель\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1174] = {title = "Гномы победили!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПризовой сундучок гномов"},
[1175] = {title = "Помехи на трассе", objective = "Убейте 10 просоленных василисков, 10 просоленных хрусталисков  и 6 просоленных взорней, после чего вернитесь к директору трассы Зерину на Мерцающую равнину.", description = "После того как гоблинский болид \"Красный Гром\" столкнулся с василиском, Кронкрайдер нанял меня присматривать за трассой. Не знаю, что жрут местные животные, но они вырастают просто огромными, и нужно постоянно отпугивать их, чтобы они не забредали на трек во время гонки.\n\nЗнаете, что? Если желаете немного заработать, ступайте и избавьте нас от нескольких василисков.", progress = "Убирать обломки с места аварии – тяжкий труд, а уж когда тебе мешают всякие твари, работа становится просто невыносимой.", completion = "Надеюсь, вы не убивали василисков прямо на трассе? Здесь тела разлагаются очень долго, а лопатой их убирать замучаешься.", rewards = "Вы получите:\n\n"},
[1176] = {title = "Уменьшение веса", objective = "Добудьте 10 полых костей падальщика для Поззика с Мерцающей равнины.", description = "На гонках имеет значение абсолютно все! Будь то малейшее изменение мощности, небольшое ослабление колец натяжения или уменьшение веса болида – любую мелочь надо принимать в расчет.\n\nМы используем в своих болидах кости стервятников – они очень крепкие и легкие. К тому же их очень легко найти. Уж чего-чего – а стервятников на Мерцающих равнинах хватает.\n\nПринеси мне немного костей, и я хорошо заплачу тебе.", progress = "Ну как, ты принес нужные кости? Я как раз хочу руль переделать, да неохота начинать, пока всех нужных запчастей нет.", completion = "Отлично! Моя команда сейчас же начнет работу! Спасибо, Томпсон.", rewards = "Вы получите:\n\n"},
[1177] = {title = "Моя голодный!", objective = "Принесите дробильщику Грязноногу, живущему на севере Пыльной Трясины, 12 голов мурлоков из клана Болотного Плавника.", description = "Моя – большой огр. \n\nМоя голодный.\n\nТвоя идти ловить рыба. Твоя принести Дробу еда.\n\nТвоя кормить Дроб, или Дроб есть твоя.", progress = "Дать мне еды или я есть твоя.", completion = "Моя любить рыбья голова!\n\nМоя пока твоя не есть.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКрушители МадаВысокие ботинки Грязнонога\n\nВы также получите:\n\n"},
[1178] = {title = "Гоблинская поддержка", objective = "Поговорите с Газлоу в Кабестане.", description = "Наша гоночная команда – это гордость всей расы гоблинов! Вы удивитесь, узнав, что за личности в той или иной мере покровительствуют нашей команде.\n\nЗнаете Газлоу? Он собирает для нас детали по всему миру, а однажды даже разработал для нас новые костюмы!\n\nНесколько недель назад он пообещал прислать новый топливный регулятор, но посылка пока не пришла. Странно, обычно Газлоу держит свое слово... Может, вы не прочь съездить в Кабестан и спросить у него? Я бы не настаивал, но эти гномы нас догоняют!", progress = nil, completion = "Вас прислал Поззик? Когда-то ведь он был одним из самых уважаемых механиков в Нижней шахте, но потом уволился и занялся гонками.\n\nПервое, что он сделал, придя в команду, – разработал две новых модели двигателей. Дела Союза ремонтников могут пострадать без Поззика, но ему уже нет до этого дела... Гонки для него все!", rewards = "Вы получите:\n\n"},
[1179] = {title = "Братья Латунный Болт", objective = "Принесите ящик с защитными шлемами Виззлу Медноштифу на Мерцающую равнину.", description = "Вы когда-нибудь слышали о Мерцающей равнине? Это огромное соляное плато в Калимдоре, южнее каньона Тысяча Игл. Это отличное место для гонок, потому что поверхность там совершенно... ну... равнинная!\n\nТам живет парочка гномов – мои друзья, они строят новый болид, и говорят, он жуть какой быстрый! Настолько быстрый, что их пилоты то и дело разбиваются и калечатся...\n\nОни заказали у меня несколько защитных шлемов, но у меня дела, и я не могу их отвезти.\n\nможет быть, вы мне поможете?", progress = "Смотри куда прешь! Эй, эй, эй! Тут все хрупкое и важное, не вздумай ничего портить, а то мы не выиграем гонку!", completion = "Ага! Длиннобородый прислал с вами наши шлемы! Ур-р-а-а-а!!!\n\nОсталось уговорить пилота сесть в наш болид...", rewards = "Вы получите:\n\n"},
[1180] = {title = "Гоблинская поддержка", objective = "Поговорите с хозяином причала Лозгилем в Пиратской бухте.", description = "Вернемся к делу. Я обещал Поззику привезти новый топливный регулятор, но так и не получил его. Ревилгаз из Пиратской бухты сказал, что выслал его, но, похоже, он куда-то улетучился.\n\nКоли так, ничего не попишешь, но по меньшей мере мы можем выяснить, отправляли его или нет.\n\nПоговори с управляющим пристанью Подгребаем по ту сторону моря, пусть заглянет в свои записи.", progress = nil, completion = "Поставки в Кабестан? Дай-ка я загляну в записи…\n\nНет, последний груз, отправленный в Кабестан, если не считать оборудования и припасов, – это сапоги от Дриззлика. Никаких запчастей для гонок.", rewards = "Вы получите:\n\n"},
[1181] = {title = "Гоблинская поддержка", objective = "Поговорите с бароном Ревилгазом в Пиратской бухте.", description = "Боюсь, тут я помочь уже не в силах, <имя>. Если ты хочешь узнать подробности, поговори с самим бароном. Никто не знает дела Ревилгаза лучше самого Ревилгаза.\n\nОн сейчас на верхнем этаже таверны на другой стороне залива.", progress = nil, completion = "А, разумеется, я понимаю, о чем ты. Нет, помочь не могу. Мои наемники должны были добыть чертежи топливного регулятора, но вернулись с пустыми руками.", rewards = "Вы получите:\n\n"},
[1182] = {title = "Гоблинская поддержка", objective = "Принесите чертежи топливного регулятора барону Ревилгазу из Пиратской бухты.", description = "Видишь ли, резаки Торговой Компании возле озера Назферити (в северной части Тернистой долины) оборудовали новой моделью топливного регулятора. Я подумал, что Поззик мог бы воспользоваться им, узнай мы, как он устроен. К сожалению, Коззл, тамошний штейгер, оказался несколько умнее, чем я полагал.\n\nМожет быть, тебе больше повезет, и удастся получить чертежи. Я знаю, что он хранит их в доме, но скорее всего под замком.", progress = "Мне не хочется это признавать, но гномская команда очень сильная. Нашим ребятам надо дать пинка, чтобы шевелились.", completion = "А теперь, дай-ка я срисую чертежи для личного пользования, а эти отвези Поззику. Не хотелось бы, чтобы он подумал, будто один из спонсоров оставил его без поддержки.", rewards = "Вы получите:\n\n"},
[1183] = {title = "Гоблинская поддержка", objective = "Отнесите чертежи топливного регулятора Поззику на Мерцающую равнину.", description = "Все должно быть готово. Передай Поззику мои наилучшие пожелания и скажи, что если ему что понадобится, стоит только попросить. Буду ждать вестей о его новых рекордах!", progress = "Томпсон! Удалось ли отыскать топливный регулятор?", completion = "Я надеялся, что он прибудет в готовом виде, зато теперь у нас есть уникальная возможность усовершенствовать конструкцию на этапе сборки. Спасибо, Томпсон. Я нарисую план улучшенного регулятора, сделаю его и установлю.", rewards = "Вы получите:\n\n"},
[1184] = {title = "Части роя", objective = "Вернитесь к Белгрому Каменной Булаве в Оргриммар.", description = "Вернитесь к Белгрому в Оргриммар и скажите, что Моктар в Тысяче Игл сделает все, что от него требуется. А еще скажите, что я постоянно учусь и набираюсь знаний. Он будет рад это услышать.", progress = nil, completion = "Я очень ценю ваши усилия, |3-6(Охотник). Вождю будет приятно услышать о том, как вы стараетесь для нас.\n\nО, разумеется, я назову ему ваше имя! Он часто говорит со мной и высоко ценит мое мнение.\n\nА теперь ступайте, у меня еще много дел. И если вдруг вы встретитесь с Корраном, и он расскажет вам что-нибудь еще об этих существах – сразу возвращайтесь ко мне. К этой угрозе нельзя относиться легкомысленно.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШтаны сухого листаКровавый полумесяц\n\nВы также получите:\n\n"},
[1185] = {title = "А под хитином было...", objective = "О, опять ты! В смысле, это ты – а ты, то есть, Лорегон! Да, это ты!\n\nСлушай-ка!\n\nТа штука, что ты нашел в Силитусе, оказалась книгой. Дневник, написанный на очень древнем диалекте того, что теперь называется дарнассийским. Это займет некоторое время, но я намерен как следует в нем разобраться. Мне показалось, что тебе следует знать, что твоя находка оказалась просто бесценной для Круга.\n\nМать-медведица в восхищении, и все такое!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1186] = {title = "Восемнадцатый пилот", objective = "Поговорите с Раззериком на Мерцающей равнине.", description = "Мне сейчас нужно приспособить этот новый регулятор топлива на один из наших болидов, но если вы хотите еще немного помочь нашей команде, поговорите с Раззериком. Это наш пилот, – гм, наш восемнадцатый пилот, если точнее, – и он тоже любит вносить в болид всяческие усовершенствования.\n\nОн, правда, малость двинутый, так что не удивляйтесь, если что.", progress = nil, completion = "Это ведь вы помогали Поззику, правда? Когда-то я тоже бегал по пит-лейну и выполнял мелкие поручения механиков.\n\nА теперь – взгляните на меня! Я – лучший пилот команды гоблинов!", rewards = "Вы получите:\n\n"},
[1187] = {title = "Настройки Раззерика", objective = "Найдите сефориевый ускоритель для Раззерика на Мерцающей равнине.", description = "Поззик – отличный механик, это я знаю, но он боится просто прибавить мощности и вырваться вперед! А вот я не боюсь.\n\nПосле того как он закончит работать с болидом, я внесу кое-какие изменения от себя: немного ослаблю ограничители, сниму кое-какие детальки с корпуса и добавлю побольше топлива!\n\nЯ заказал сефориевый ускоритель у Шрива. Он работает в Гизмориуме, в Прибамбасске, но дирижабль, на котором летел мой ускоритель, разбился в Пылевых топях! А мне он нужен, как воздух!", progress = "И как мне показаться на треке, если у меня нет никакого ускорителя? Это ж ерунда какая-то!", completion = "Ты только глянь на эту красотищу! Пятнадцать фунтов чистой сефориевой силы! Как только я прицеплю это к своему болиду, он понесется так, что я обгоню гномов на два круга!", rewards = "Вы получите:\n\n"},
[1188] = {title = "Безопасность превыше всего", objective = "Отнесите сефориевый ускоритель Шриву в Прибамбасск.", description = "Постойте-ка, что это? Шрив оставил включенным режим безопасности. Но это же ограничит мощность, которую я смогу выжать из этого ускорителя! Говорил же я ему, чтобы отключил! Плохо, плохо.\n\nВам придется отнести это в Гизмориум Прибамбасска и заставить Шрива все отключить!", progress = "Знаете, в Гизмориуме есть все для починки любых механизмов! Чем могу помочь?", completion = "Только Раззерик мог по одному взгляду определить, что я поставил сюда предохранитель. Этот ускоритель почти полностью состоит из взрывчатого сефория. Я модифицировал его так, что его мощность будет увеличиваться по мере использования, но Раззерик ведь не успокоится, пока не взорвется вместе со своим драндулетом!", rewards = "Вы получите:\n\n"},
[1189] = {title = "Безопасность превыше всего", objective = "Верните модифицированный сефориевый ускоритель Раззерику на Мерцающую равнину.", description = "Вот, я сделал то, что просил Раззерик. Но скажите ему, чтобы он действовал как можно осторожнее: если он допустит хотя бы малейшую ошибку, болид не покатится вперед, а превратится в кучку пепла на треке.\n\nА нам бы совсем не хотелось искать потом девятнадцатого по счету пилота!", progress = "Ты представляешь, Поззик подсунул мне в болид ведро с песком! Как я могу выжать максимальную скорость, если у меня под сиденьем целое ведро песка?", completion = "Так-то лучше! Вот бы увидеть рожи гномов, когда я стартую на этой малышке!\n\nЖалко, что я буду так занят установлением нового рекорда трассы!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПодогнанный пояс безопасности РаззерикаГоночные перчатки Раззерика\n\nВы также получите:\n\n"},
[1190] = {title = "Только вперед", objective = "Дождитесь, пока Замек устроит диверсию, украдите чертежи Риззла и отнестие их Поззику.", description = "Братья Медноштиф изобрели новый материал для изготовления машин – это единственное разумное объяснение. Их машины ездят быстрее прежнего, но их внешний вид и все остальные параметры ничуть не изменились.\n\nМы точно знаем, что Риззл Медноштиф никогда не расстается с чертежами своего изобретения.\n\nЯ скажу Замеку, чтобы устроил диверсию, – тогда ты сможешь выкрасть планы.", progress = nil, completion = "Свиток испещрен торопливыми пометками и рисунками, касающимися переработки какого-то сырья.", rewards = "Вы получите:\n\n"},
[1191] = {title = "Помеха Замека", objective = "Поехали!", description = nil, progress = nil, completion = nil, rewards = nil},
[1192] = {title = "Индарилиевая руда", objective = "Я хотел бы использовать индарилий в разных частях наших болидов, но сначала мне нужно создать эти части из большого количества этого материала.\n\nИндарилиевую руду можно найти в Ульдамане – это в Проклятых землях, на другом берегу моря в Каз Модане.\n\nГномы то и дело получают поставки индарилия, так что нам надо не отставать.", description = nil, progress = "Я хотел бы использовать индарилий в разных частях наших болидов, но сначала мне нужно создать эти части из большого количества этого материала.\n\nИндарилиевую руду можно найти в Ульдамане – это в Проклятых землях, на другом берегу моря в Каз Модане.\n\nГномы то и дело получают поставки индарилия, так что нам надо не отставать.", completion = "Замечательно! Моя команда немедленно начнет работу с необходимыми деталями для следующей гонки!", rewards = "Вы получите:\n\n"},
[1193] = {title = "Сломанная западня", objective = "Перед вами – большая сломанная западня. Судя по ее внешнему виду, огры даже пытались ее чинить, но безуспешно. Рядом с западней лежит небрежно нацарапанная записка. Как ни странно, в записке подробно объясняется, как починить западню: для этого нужно ториевое устройство и немного масла льда. Когда западня работает, любой проходящий мимо огр может в нее попасть, и тогда его можно будет благополучно миновать.\n\nОчевидно, огры читать не умеют...", description = nil, progress = "Перед вами – большая сломанная западня. Судя по ее внешнему виду, огры даже пытались ее чинить, но безуспешно. Рядом с западней лежит небрежно нацарапанная записка. Как ни странно, в записке подробно объясняется, как починить западню: для этого нужно ториевое устройство и немного масла льда. Когда западня работает, любой проходящий мимо огр может в нее попасть, и тогда его можно будет благополучно миновать.\n\nОчевидно, огры читать не умеют...", completion = "Ториевое устройство беспрепятственно встает на место, создавая канал, в который нужно влить масло льда. Как только последние капли масла падают в канал, западня готова к работе.\n\nИ горе неосторожному огру, который подойдет слишком близко!", rewards = nil},
[1194] = {title = "Чертежи Риззла", objective = "Отнесите образец индарилиевой руды Поззику на Мерцающую равнину.\n\nПрилагается предмет: \n", description = "В чертежах Риззла описывается процесс переработки индарилиевой руды. Из его каракулей можно понять, что эта руда добывается в недрах Ульдамана в Бесплодных землях.\n\nОстальные записи посвящены теплопроводным свойствам индарилия.\n\nПачка бумаг придавлена каким-то камнем – скорее всего, это и есть необработанная индарилиевая руда.", progress = nil, completion = "Индарилий? Интересно... Если он действительно способен выдерживать такой жар, то мне понятно, почему гоблины так отличились на последней гонке.\n\nБольшое спасибо за этот образец, он мне очень пригодится. Я проведу с ним кое-какие испытания, но для настоящего дела мне потребуется гораздо больше.", rewards = "Вы получите:\n\n"},
[1195] = {title = "Священное пламя", objective = "Принесите наполненный гравированный фиал Зангену Каменному Копыту в Громовой Утес.", description = "Кентавры племени Галак в Тысяче Игл хранят один предмет, сохранившийся еще со времен сотворения кентавров.\n\nНам бы хотелось его получить, но для этого нужен фиал воды из одного из лунных колодцев ночных эльфов.\n\nЧтобы набрать воды, тебе надо сначала добыть один из фиалов дриад, что живут близ Приюта в Ночных Лесах в сердце Ясеневого леса. Лунный колодец есть у западного берега реки Фалфаррен, к югу от главной дороги, у которой ты сможешь наполнить фиал.", progress = "Как только у нас будет наполненный фиал, мы отправим его моему помощнику, Рау, в Тысячу Игл. Он-то и просил фиал этой воды, так что ему лучше знать, что с ней делать.", completion = "Хорошо. Это как раз то, что просил Рау. Ты можешь отнести ему фиал? Тебе понравится в Иглах, честное слово!", rewards = "Вы получите:\n\n"},
[1196] = {title = "Священное пламя", objective = "Доставьте наполненный гравированный фиал Рау Скальному Бегуну на Заставу Вольного Ветра.", description = "Отнеси наполненный фиал Рау Скальному Бегуну на Заставу Вольного Ветра на юго-востоке Тысячи Игл. Туда ты можешь добраться на Великом подъемнике, что возле южного обрыва Степей.\n\nНе удивлюсь, если ты и в дальнейшем будешь нам помогать.", progress = "Хм, неужто тебя послал Занген?", completion = "Хм, да, этот фиал очень пригодится для наших целей. Поскольку дриады и кентавры происходят от одного корня, вода лунных колодцев поможет нам пробить брешь в стене неугасимого огня, что окружает реликвию кентавров.", rewards = "Вы получите:\n\n"},
[1197] = {title = "Священное пламя", objective = "Принестите раздвоенное копыто Рау Скальному Бегуну на Заставу Вольного Ветра.", description = "Водой, которую ты <принес/принесла>, можно будет затушить пламя, охраняющее реликвию кентавров. Однако оно погаснет лишь ненадолго, так что тебе придется поспешить.\n\nУтес Треснувшего Копыта – крепость кентавров – находится к северу отсюда. Огонь горит в оплоте Треснувшего Копыта – самой охраняемой части утеса.\n\nБудь <осторожен/осторожна> – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность.", progress = "Жду не дождусь, когда смогу получить это раздвоенное копыто. Вы уже добыли его?", completion = "От этого копыта исходит странная энергия... Не сомневаюсь, что при его изучении мы узнаем много нового о кентаврах.\n\nБлагодарю вас, Атеистфрост. Я немедленно приступлю к разгадке тайны, которую вы принесли мне.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛук меткости Скального БегунаЛазурный кушак\n\nВы также получите:\n\n"},
[1198] = {title = "В поисках Талрида", objective = "Найдите стража Талрида из ордена Серебряного Рассвета в Непроглядной Пучине.", description = "В нынешние дни много слухов ходит о союзе Сумеречного Молота и наг в Непроглядной Пучине на побережье Ясеневого леса.\n\nЯ должен собрать как можно больше сведений для Серебряного Рассвета, что бы мы могли понять, где и когда нужна наша помощь.\n\nУже много недель прошло, как я отправил разведчика выяснить, что происходит в Непроглядной Пучине. Страж Талрид из ордена Серебряного Рассвета до сих пор не вернулся.\n\nДругие мои разведчики заняты насущными делами.\n\nПомоги мне найти Талрида, <имя>.", progress = nil, completion = "Хорошо, что Рассветный дозорный Шедласс прислал вас. В этом испоганенном месте и правда затевается коварный план.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1199] = {title = "Наступление сумерек", objective = "Принесите 10 подвесок сумерек стражу Менадосу из ордена Серебряного Рассвета в Дарнасс.", description = "Черпая силу из старинных обрядов, посвященных Древним Богам Хаоса, Сумеречный Молот пытается вернуть своих темных покровителей и распространить смерть и ужас по всему миру.\n\nМы думаем, что Сумеречный Молот в союзе с нагами, и теперь они накапливают силы в Непроглядной Пучине на побережье Ясеневого леса.\n\nЧто бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться.\n\nОбъяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены.", progress = "В Непроглядной Пучине некогда был древний храм ночных эльфов. Одно время там находился самый мощный лунный колодец. Кто знает, какое зло ныне клубится там, когда храм в руках Сумеречного Молота?\n\nУдалось ли тебе проредить их ряды?", completion = "Нет сомнений – в тебе течет отважная и благородная кровь, Медведик. Серебряный Рассвет благодарит тебя за содействие силам добра.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nОреольные сапогиРемень Сердца Древа"},
[1200] = {title = "Злодейство в Непроглядной Пучине", objective = "Принесите голову повелителя сумрака Келриса Рассветному дозорному Селгорму в Дарнасс.", description = "Силы оставили меня. Мне необходима твоя помощь!\n\nВ давние времена на этом месте был храм Элуны. К несчастью, он был разрушен, когда порча Древнего бога просочилась из-под земли и осквернила священный Лунный колодец.\n\nАку'май, слуга Древнего бога, поднялся из глубин.\n\nСектанты Сумеречного Молота объединились с нагами в борьбе за эти земли. Сектанты, ведомые Келрисом, приносят Аку'май невинные жертвы.\n\nУбей Келриса и принеси его голову Сельгорму в Дарнасс, <имя>.", progress = "Время дорого, |3-6(Воин). \n\nМоя задача в Дарнассе – обеспечить процветание Серебряного Рассвета и поражение злых сил, вторгшихся в Калимдор. \n\nГовори, зачем пришел или уходи.", completion = "Келрису много раз удавалось ускользнуть от нас. \n\nМне кажется, он стоял за всем злом, происходящим в этих землях. \n\nПоложив конец его власти, ты спас жизнь многих. \n\nВо имя Света! Нет прощенья тем, кто приносит невинные жертвы Древнему Богу! \n\nТы совершил великий подвиг, Даски. Серебряный Рассвет этого не забудет.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНадгробный скипетрАрктический кулачный щит\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1201] = {title = "Тераморские шпионы", objective = "Убейте 9 тераморских шпионов, потом вернитесь к Назиру Кровавому Копью в деревню Гиблотопь.", description = "Орда с Альянсом сейчас находятся в состоянии шаткого перемирия. Тайные операции предпринимаются обеими сторонами, и наша обязанность – убедиться что Орда выйдет из них победителем!\n\nСейчас у нас есть шанс это сделать.\n\nАгенты Альянса заняли позицию к востоку от Деревни Гиблотопь. Они следят за деревней и докладывают о наших действиях в районе Терамора. Мы не станем этого терпеть.\n\nТвоя задача выследить этих шпионов и убить их. Этим мы ясно дадим понять их начальству, что не допустим шпионить у себя под носом.", progress = "Ты нашел шпионов, Тарчёк?", completion = "Отличная работа. Их шпионы хитроумны, но недостаточно, чтобы спастить от всевидящих глаз Орды.", rewards = "Вы получите:\n\n"},
[1202] = {title = "Доки Терамора", objective = "Принесите документы капитана Назиру Кровавому Копью в Деревню Гиблотопь.", description = "<имя>? Мы послылали двоих разведчиков украсть бумаги с корабля в одном из тераморских доков. Они добыли их, но были обнаружены, и им пришлось выбросить добычу в море.\n\nОдному из них удалось сбежать, но поднять документы со дна он не смог. Теперь я поручаю эту задачу тебе.\n\nБумаги лежат в сундучке, на дне моря возле тераморских доков. Найди их, <имя>, и принеси мне.", progress = "Ты нашел документы, Томпсон? Информация содержащаяся в них, жизненно важна для Альянса, а значит необходима разведке Орды.", completion = "Браво, Томпсон. Это было нелегко, но документы, которые ты добыл – весьма ценны.", rewards = "Вы получите:\n\n"},
[1203] = {title = "Ярлу нужен клинок", objective = "Принесите палаш лунной стаи Ярлу в Пылевые Топи.", description = "Мне предстоит жестокая рубка. С кем, я тебе сказать не могу, но вот то, что мне для этого просто необходим добрый клинок, это к гадалке не ходи.  Некоторые называют его палашом лунной стали, а я зову пляшущий клинок.\n\nПоможешь мне, а? Может, где в городе найдешь, а может, кузнец какой согласится его сделать.\n\nГлавное, поторопись, то что я собираюсь рубить, ждать не станет...", progress = "Ты достал мне клинок?", completion = "Это хороший клинок... Он хорошо танцует, – стал быть, это – хороший танцующий клинок! Спасибо-спасибо-спасибо!!! Таак. Теперь я его испробую...\n\nПозже. Я испробую его позже. Но все равно спасибо тебе!", rewards = "Вы получите:\n\nКольцо Спутанного тростникаБрюки мастерового"},
[1204] = {title = "Суп из илистой черепахи с жучками", objective = "Принесите 8 раздвоенных языков илистых черепах Моргану Штерну в Терамор.", description = "Я тут работаю над новым блюдом, оно будет называться \"Суп из илистой черепахи с жучками\". Мне все еще не хватает основных ингридиентов, но я не уверен, что перенесу еще одну прогулку по Пылевых топях. <имя>, ты не окажешь мне услугу? Прежде всего, мне нужны языки илистых черепах. Они водятся на побережье, в основном вокруг залива.\n\nНо мне не всякие языки сгодятся – я слышал, что у некоторых из этих черепах языки раздвоены. \n\nВот они-то и обладают тем непередаваемым вкусом, которым я хочу порадовать своих клиентов.", progress = "Ну как? Удалось добыть необходимые мне языки?", completion = "Отлично! Благодарю тебя, Маладат!\n\nТеперь надо подумать, как именно приготовить эти языки, чтобы наилучшим образом подчеркнуть их изысканный вкус.\n\nНаконец-то у меня есть блюдо, достойное завсегдатаев \"Синего отшельника\" в Штормграде.", rewards = "Вы получите:\n\n"},
[1205] = {title = "Зыбун", objective = "Принесите зуб кроколиска Зыбуна Мелору в Громовой Утес.", description = "Зыбун – старый кроколиск из Пылевых топей. Ему давно уже пора сдохнуть.\n\nСкрипя старыми костями он волочет свою огромную тушу по болоту. Хотя он все еще движется с силой и скоростью молодого животного, его неугасимый пламенный дух уже износил свое дряхлое тело.\n\nТы <должен/должна> освободить его от этой боли, <имя>. Дай ему покой.", progress = "Ты добыл зуб Зыбуна, Томпсон? Удалось ли тебе прекратить страдания этого существа?", completion = "Отлично, Томпсон. Я уверен – это было нелегкое испытание, но я рад, что мучения кроколиска наконец-то прекратились.", rewards = "Вы получите:\n\n"},
[1206] = {title = "Ярлу нужны глаза", objective = "Принесите 40 целых глаз пауков Мглистой пещеры Ярлу \"Болотному Глазу\" в сторожку \"Болотный Огонек\".", description = "Глазной сок очень вкусный, жаль только что большинство живых существ имеет всего по два глаза.\n\nНо вот у пауков их уже больше, гораздо больше. А сок из глаз пауков Мглистой пещеры обладает особенным мягким вкусом. Целехонькие паучьи глазки... прям уже чую их на языке.\n\nЭти пауки водятся к пещере к западу отсюда. Вот как ты думаешь, это пауки были названы по своей пещере или наоборот?", progress = "Ну и где мои глаза?", completion = "Ты принес вкусные глазки... Паучьи глаза чисты как слеза. \n\nИх едят, а они глядят…\n\nВот те, что глядят, съешь последними, а то на болотах-то другой компании и нет.\n\nПривет, глазки мои маленькие, привеет! На вкус лучше курочки, с солью, с приправками...\n\nМмм...", rewards = "Вы получите:\n\n"},
[1218] = {title = "Ароматные специи", objective = "Принесите 3 порции ароматных специй Ярлу \"Болотному Глазу\" в Пыльную трясину.", description = "Люблю болотную кухню. Жареные лягушачьи лапки и все такое...\n\nИ чтобы готовить, мне нужны специи. Ароматные специи. Тогда я смогу сделать славное жаркое, да и тебя угостить\n\nТы как насчет тушеной лягушатинки?", progress = "Специи. Без них жизнь была бы совсем пресной, как думаешь?", completion = "Ага, вот и специи. Вот теперь жабятина вполне готова.", rewards = "Вы получите:\n\nПохлебка из лягушачьих окорочков"},
[1219] = {title = "Орочье донесение", objective = "Доставьте орочье донесение тераморскому лейтенанту.", description = "Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. \n\nДонесение написано на орочьем... И по виду важное...", progress = "Вы что-то хотите мне сообщить?", completion = "Хм... Я не силен в орочьем, но это похоже... на отчет шпиона!", rewards = "Вы получите:\n\n"},
[1220] = {title = "Капитан Ваймс", objective = "Принесите шпионское донесение капитану Гаррану Ваймсу.", description = "Капитан Ваймс должен увидеть найденное тобой орочье донесение, <имя>. Он знает орочий язык, лучше чем кто либо из нас, и он должен быть осведомлен о том, что вблизи Терамора рыщут шпионы Орды.\n\nТы найдешь капитана в казармах в северо-восточной части острова Терамор.", progress = "У тебя что-то есть для меня?", completion = "Донесение орочьего шпиона! Как тебе удалось его раздобыть? Впрочем, неважно, – давай-ка посмотрим, о чем там говорится...", rewards = "Вы получите:\n\n"},
[1221] = {title = "Корни Синелиста", objective = "Возьмите ящик с дырками.\nВозьмите палочку-погонялочку для шмыгуносов.\nВозьмите справочник по шмыгуносам. \n\nВ Лабиринтах Иглошкурых выпустите шмыгуноса и воспользуйтесь стеком, чтобы он начал искать корни. \n\nПринесите 6 корней синелиста, стек и ящик с дырками Мебоку Миззриксу в Кабестан.", description = "Корень синелиста – признанный деликатес в любом уголке мира! Но растет он только здесь, в Пустошах, глубоко под землей в Лабиринтах Иглошкурых.\n\nК тому же клубни так сложно найти, если не знать точно где искать! Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землей. Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов!\n\nЗадачка, конечно, непростая, но если принесешь мне корней, я хорошо заплачу.", progress = "Ну что, принес корни, Шауе?", completion = "Прекрасно! О, я загоню их перекупщикам за очень хорошую цену! \n\nСпасибо за работу, Шауе. Ты вполне надежный поставщик!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nМаленькая шкатулка с самоцветами"},
[1222] = {title = "Спасение Вонючки", objective = "Сопроводите \"Вонючку\" Игнаца, затем пообщайтесь с Морганом Штерном в Тераморе.", description = "Ура! Наконец-то нашелся кто-то, кто не хочет меня съесть!\n\nНе могу отбиться от тутошнего зверья, а ты, <парень/подруга>, как раз мне в этом и поможешь.\n\nПовар Морган Штерн составляет рецепт нового блюда, и он послал меня сюда на поиски листьев болотного боба. Он, похоже, думает, что они вкусные.\n\nКак бы то ни было, пока я искал эти самые листья... меня окружили! Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать эти бобы!", progress = nil, completion = "Мистер Игнац не так давно приносил листья болотного боба, и он расказал мне, что вы помогли ему выбраться из весьма затруднительной ситуации.\n\nБлагодарю вас, Rainon. Я попрошу своего дядю принять вас по-королевски, когда вы в следующий раз окажетесь в \"Синем отшельнике\", в Штормграде.", rewards = "Вы получите:\n\nЭликсир стойкости"},
[1238] = {title = "Потерянный рапорт", objective = "Отнесите донесение шпиона Назиру Кровавому Копью в Деревню Гиблотопь.", description = "Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. \n\nЭто донесение шпиона, который провел многие недели в Тераморе.\n\nРасшифровав его, мы выяснили, что это донесение должно быть доставлено командиру орков-разведчиков в Деревню Гиблотопь.", progress = "У тебя что-то есть для меня?", completion = "Отлично, Томпсон. Наш агент Марг Ночной Соглядатай был отправлен на разведку в Терамор.\n\nЭто его последний рапорт и, видимо, уже окончательно последний – судя по твоим словам, я боюсь, Марг навсегда остался в болотах...", rewards = "Вы получите:\n\n"},
[1239] = {title = "Отрубленная Голова", objective = "Принесите голову строптивого орка Назиру Кровавому Копью в Деревню Гиблотопь.", description = "Стоило копнуть чуть глубже, и из земли показалась отрубленная голова орка. На его лице застыл оскал, а в темных глазах – вызов.", progress = "У тебя для меня еще что-то есть, Томпсон?", completion = "Это голова Марга Ночного Соглядатая! Этого-то я и боялся. Посмотри на эту рану у него на шее, – как думаешь, это какое-то оружие, или он пал от клыков и когтей какого-то зверя? \n\nМы должны выяснить это, Томпсон. Выяснить, не является ли его смерть делом рук Альянса.", rewards = "Вы получите:\n\n"},
[1240] = {title = "Тролль-знахарь", objective = "Принесите голову строптивого орка Кин'вилаю в лагерь Гром'гол в Тернистой долине.", description = "Мы должны выяснить обстоятельства смерти Марга! И единственный способ это сделать, <имя>, – воспользоваться магией троллей. \n\nОтнеси голову Марга Кин'вилаю в лагерь Гром'гол в Тернистой долине.\n\nКин'вилай – самый могущественный из знахарей племени Черного Копья, если кто-то и сможет вызвать дух Ночного Соглядатая – то это он.", progress = "Рядом с тобой вьется очень сердитый дух, брат. Что привело тебя к Кин'вилаю?", completion = "Да, теперь я вижу. Дух Марга застрял в нашем мире, потому что его задание не было завершено.\n\nНу что ж, давай поговорим с этим сердитым орком...", rewards = "Вы получите:\n\n"},
[1241] = {title = "Пропавший дипломат", objective = "Найдите Йоргена в Штормграде.", description = "Некоторое время назад один из наших дипломатов был отправлен в Терамор для встречи с Джайной Праудмур. Он не вернулся.\n\nЯ подозреваю, что к этому приложило руку Братство Справедливости, но уверенности у меня пока что нет. Пока что нам удается скрывать факт исчезновения дипломата, но так продолжаться не может.\n\nАгенты королевской службы рыщут по городам, но я хочу задействовать и свои связи.\n\nВ Аллее Героев вы найдете моего старого друга, его зовут Йорген. Передайте ему эту записку и во всем его слушайтесь.", progress = "Хм-м, ну, надеюсь, у вас есть действительно достойный повод оторвать меня от рыбалки. Я не подаю нищим и не покупаю ничего у разносчиков...", completion = "Хм-м... *Йорген смотрит на вас, прищурившись.*\n\nХорошо. Придется вам помочь, хоть и не очень-то хочется. Долг есть долг.\n\nИ запомните одну простую вещь: вы знаете куда больше, чем уместно в вашем случае. Храните наши маленькие секреты и не болтайте по тавернам о том, что обнаружите. Ясно вам?", rewards = "Вы получите:\n\n"},
[1242] = {title = "Пропавший дипломат", objective = "Доставьте запечатанную записку Йоргена Иллингу Триасу в Штормград.", description = "Возьмите записку для Иллинга Триаса. Ничего ему не рассказывайте, просто ведите себя вежливо и дождитесь ответа; не волнуйтесь, Триас ответит.\n\nЕще раз напоминаю вам, <имя>: дело серьезное, так что держите рот на замке.\n\nТриаса вы найдете в его магазине в Торговом квартале; магазин называется \"Сыры Триаса\". Удачи!", progress = "Здравствуйте, Бронгард. Могу ли я чем-нибудь вам помочь? Не хотите ли отведать \"Чеддер Триаса\"? Или кусочек \"Дарнассийского блю\"?", completion = "Извините, письмо мне? О... не так уж часто мне приходится получать что-то, кроме ящиков и бочонков, я ведь занят делом. Ну, давайте посмотрим, что там.\n\n*Открывая письмо, Эллинг смотрит на вас.*\n\nБронгард, вы выглядите возбужденно, с вами все в порядке?", rewards = "Вы получите:\n\n"},
[1243] = {title = "Пропавший дипломат", objective = "Отнесите запечатанное письмо дозорному Бакусу в Сумеречный лес.", description = "Йорген, ах ты старый мерзавец... Ну и что со всем этим делать?\n\nЛадно, я разберусь... Да чтоб ему в Круговерть Пустоты угодить раньше времени!\n\nНу что, <имя>, займемся делом? Я задействую все свои контакты, но вам придется побегать.\n\nОтправляйтесь в поселение Темнолесье, которое находится в Сумеречном лесу, и найдите там дозорного Бакуса; он обычно патрулирует северную дорогу за городской стеной. Просто скажите ему, что Братство Справедливости опять зашевелилось, а вы присматриваете за ним по моей просьбе – и он вам поможет, чем сможет.", progress = "По этим лесам путешествовать небезопасно, Эфром. Будьте осторожны, и если приметите опасность – немедленно обращайтесь к Смотрящим. Не пытайтесь разобраться самостоятельно. Иначе помощь может прийти слишком поздно...\n\nВпрочем, мы оба знаем, что вы плюнете на мои предупреждения и будете сражаться со всем, что выползет из сумерек, верно? Я знаю таких, как вы – настоящих приключенцев...", completion = "Вас послал Триас, да? Другое дело...\n\nМожете гонять чудовищ, сколько вам заблагорассудится. Уверен, что для вас это не составит особого труда, какой бы ужас ни вылез на вас из сумерек...\n\nТак чего же желает мой дорогой друг в этот пасмурный день?", rewards = "Вы получите:\n\n"},
[1244] = {title = "Пропавший дипломат", objective = "Найдите декларацию Братства Справедливости и верните ее дозорному Бакусу в Сумеречном лесу.", description = "Опять братство?! Они вечно что-то вытворяют; даже если они затихли, мы считаем это недвусмысленной угрозой.\n\nКстати, сейчас я вспомнил, что последнюю пару недель их агенты так и кишат вокруг участка Эддла. Это подозрительно – должно быть, назревает какая-то крупная заварушка.\n\nНе хотите порыскать там и установить, в чем же дело?\n\nФерма находится к югу от дороги из Западного Края как раз на входе в Сумеречный лес.", progress = "Будьте осторожнее, Бронгард. Хоть вас и прислал сюда Триас, но это не значит, что все чудовища из чащоб будут к вам благосклонны. Особенно учитывая, что ваше расследование связано с Братством Справедливости.", completion = "Вы вернулись, не вляпавшись ни в какие неприятности. Это само по себе достижение, не правда ли?\n\nНу, покажите, что принесли? Да, очень похоже на официальные документы Братства Справедливости. Но это может быть и подделкой, которую вам подсунули, чтобы одурачить и сбить со следа.", rewards = "Вы получите:\n\n"},
[1245] = {title = "Пропавший дипломат", objective = "Отнесите декларацию Братства Справедливости Иллингу Триасу в Штормград.", description = "О-ох, для обычной попытки ввести в заблуждение это слишком сложно. Отнесите этот документ Триасу, пусть поразмыслит над ним. И никому больше об этом не говорите. Кажется, это дело ни мне, ни ему не по плечу. Ну, посмотрим...\n\nИ, пожалуйста, <имя>, никому не говорите, что я вам помог. Если мое начальство поймет, что я о чем-то узнал и не поделился с ними, они могут меня запросто повесить.", progress = "Ой, да вы вернулись, и целиком, а не кусками в посылке! Разумеется, вы не за сыром явились, так давайте сразу перейдем к делу! Помог ли вам Бакус, или в Сумеречном лесу вы ничего не нашли?", completion = "Да-а... весьма интересно. Йорген и Делавей молодцы, что навели меня на это.\n\nКажется, Братство Справедливости всерьез взялось за воплощение своих планов. Хм, а это что? \"Кулак\"? Знакомое имя...", rewards = "Вы получите:\n\n"},
[1246] = {title = "Пропавший дипломат", objective = "Поговорите с Дашелем Каменным Кулаком в Штормграде.", description = "Вот что я об этом думаю... Дашель... Какой-то Дашель... Как его фамилия? Кулак! Дашель Каменный Кулак! В некоторых кругах его зовут просто Кулак, наверняка потому, что он не дурак подраться...\n\nЕго можно найти в Старом городе, прямо в центре. Поговорите с ним. Если понадобится, используйте меч или любой подручный тяжелый предмет, чтобы урезонить его, и не сомневайтесь. Если он так завязан в заговоре, как можно заключить по этим бумагам, то не расстанется с информацией по доброй воле...", progress = nil, completion = "Что?!\n\nМои дела тебя не касаются, ясно? Проваливай, нечего тебе здесь вынюхивать!", rewards = "Вы получите:\n\n"},
[1247] = {title = "Пропавший дипломат", objective = "Поговорите с Иллингом Триасом в Штормграде.", description = "Ну... м-м... да... Я кое-что знаю о встрече на участке Эддла. Она произошла несколько недель назад. Меня туда не приглашали, мое участие закончилось с провалом плана А, проклятие этим окаянным приключенцам...\n\nПарень, с которым связан план Б, пришел из Менетила. Его зовут Пронырой. Это все, что мне удалось узнать из запасного плана.", progress = nil, completion = "О, Бронгард, приятно видеть вас в живых. Значит, с Дашелем все прошло хорошо?\n\nЯ тут еще раз перечитал их планы, и хотя в тексте не упоминается имя дипломата, которого они преследовали, речь идет о плане Б, который вступил в действие после провала первой попытки захватить его.\n\nЭтот Проныра, о котором упомянул Дашель, кажется, не имеет другого имени – непонятно, кто он; но нам хотя бы известно, что он из Менетила.", rewards = "Вы получите:\n\n"},
[1248] = {title = "Пропавший дипломат", objective = "Поговорите с Михаилом из Болотины.", description = "Один из моих знакомых переехал в Болотину, в портовый город Менетил. Думаю, что он поможет вам, если вы передадите ему привет и скажете, что работаете на меня. Зовут его Михаил; перед отъездом он говорил, что хочет стать барменом.\n\nПоговорите с ним, найдите этого Проныру и попробуйте разузнать еще что-нибудь насчет похищенного дипломата. Мы должны узнать, где его держат или хотя бы имя похищенного. Увы, в декларации ничего не говорится о том, что похитители собираются сделать с пленником после захвата.", progress = nil, completion = "Привет-привет, дорогой Эфром. Рады вас видеть. Не желаете ли эля? Или баранины?\n\nСкажите, чего бы вам хотелось, и я постараюсь выполнить все ваши пожелания. Меня зовут Михаил, я буду рад услужить вам.\n\nЭ? Что это? Триас? Прошу вас, говорите потише. Моим посетителям не обязательно слышать, о чем мы с вами говорим.", rewards = "Вы получите:\n\n"},
[1249] = {title = "Пропавший дипломат", objective = "Перехватите Яна Проныру до его ухода и вернитесь к Михаилу.", description = "Значит, вас послал Эллинг? О, это повод десятикратно умножить мое гостеприимство! Просите всего, чего пожелаете, постараюсь выполнить любую вашу просьбу!\n\nХм-м, Проныра, говорите? Не скажу, что мне знакомо это имя, но постараюсь что-нибудь разведать...\n\n<имя>, не оборачивайтесь прямо сейчас, но вон тот господин около двери слишком внимательно смотрит на нас и прислушивается к нашему разговору. На вашем месте я бы попробовал изловить его прежде, чем он уйдет отсюда.", progress = nil, completion = "Поймали его, да? Отлично! Знаете, а ведь это и есть тот самый Проныра! Я и сам удивился.\n\nДа, не думал я, что буду так скучать по всяким тайным расследованиям и азартным погоням. Верно говорят: сколько волка ни корми... Только не обмолвитесь про это Эллингу – он наверняка потащит меня обратно в Штормград, узнав, что я затосковал по былым денькам.\n\nХорошо, что мне удалось оказать вам хотя бы небольшую услугу во время вашего пребывания в Менетиле. Если еще что-нибудь понадобится, просто попросите.", rewards = "Вы получите:\n\n"},
[1250] = {title = "Пропавший дипломат", objective = "Поговорите с Михаилом в Болотине.", description = "Братство Справедливости не столько мне платит, чтобы за них умирать. Они похитили короля. Да, настоящего короля Штормграда, а не какого-то там дипломата. Он направлялся в Терамор, чтобы побеседовать с Джайной Праудмур, это большая тайна и дело тоже нешуточное. Но тут встряло братство, у них был свой осведомитель.\n\nВ мои задачи входило только взять их человека на борт королевского корабля, когда он стоял у пристани. Парня звали Хендел, клянусь, это все, что я знаю!", progress = nil, completion = "КОРОЛЬ?! В смысле... король? Настоящий король? Вы шутите? Вы же не имеете в виду, что вы разыскиваете похитителей короля?! Я даже не в курсе, что он пропал. Теперь ясно, почему сейчас в Штормграде всем заправляет его сын.\n\nЯ прямо сейчас напишу Эллингу. Он должен знать, что вы встали на след.\n\nМне и в голову не приходило, что Джан может предать наш Штормград за деньги, пусть и немалые. Даже у вора должна быть честь!\n\nТеперь главное – найти этого Хендела – думаю, тут я могу помочь...", rewards = "Вы получите:\n\n"},
[1251] = {title = "Черный Щит", objective = "Прнинесите почерневший железный щит Крогу в Деревню Гиблотопь.", description = "Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остове камина – только это и осталось от таверны \"Последний привал\".\n\nЩит можно снять.", progress = "Что это у тебя там, Томпсон? Вещественное доказательство с руин \"Последнего привала\"?", completion = "Люди всегда отличались странными вкусами в области украшательства. Но на кой вешать над камином простой металлический щит? Может, его повесили туда те, кто спалил таверну?\n\nПредупреждение? Угроза?", rewards = "Вы получите:\n\n"},
[1252] = {title = "Лейтенант Павал Рит", objective = "Принесите бляху Рита капитану Гаррану Ваймсу в Терамор.", description = "Солнечный зайчик блеснул в глаза из-под обломков. Вы достаете из-под мусора бляху с золотым якорем на белой эмали – символом Терамора.\n\nПод якорем выбито имя владельца: \"Лейтенант Павал Рит\".", progress = "Ну как успехи с этой таверной? Удалось что-нибудь найти?", completion = "День, когда мне приносят бляхи погибших стражей, светлым не назовешь. \n\nИногда они гибнут в битве, и мне приходится сообщать об их участи семье и близким... Иногда мы так и не знаем, что с ними сталось. А иногда знаем, и это еще хуже...", rewards = "Вы получите:\n\n"},
[1253] = {title = "Черный Щит", objective = "Принесите почерневший железный щит капитану Гаррану Ваймсу в Терамор.", description = "Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остатках камина – только это и осталось от таверны \"Последний привал\".\n\nЩит можно снять.", progress = "Ты выяснил, что произошло с этой таверной?", completion = "Хмм... Я в устройстве оружия и доспехов не разбираюсь, я ими пользуюсь. \n\nЩит как щит, разве что огнем опалило.", rewards = "Вы получите:\n\n"},
[1258] = {title = "…и жуки.", objective = "Принесите 12 безупречных крабьих клешней Моргану Штерну в Терамор.", description = "Еще один компонент моего нового рецепта – клешни гигантского краба. К сожалению, те которые водятся в Пыльной трясине, – грязнокрабы, не годятся... Зато те, что живут на Болоте Печали, – в самый раз!\n\nОболочка клешни – важный элемент украшения блюда, поэтому они мне нужны целые и непоцарапанные. К сожалению, у краба всего две клешни, а то и одна, а мне для моих кулинарных экспериментов их нужно гораздо больше. Так что насчет небольшой прогулки, <имя>?", progress = "Я придумал чудесное блюдо из языков илистых черепах. Надеюсь, ваша охота прошла удачно?", completion = "Прекрасные экземпляры, Маладат. На самих клешнях ни царапинки, а мясо как и положено, розовое и нежное. У вас несомненный талант к этому делу! Не задумывались о карьере шеф-повара?", rewards = "Вы получите:\n\nБарочный фартук"},
[1259] = {title = "Лейтенант Павал Рит", objective = "Поговорите о Рите с адъютантом Тезораном в Тераморе.", description = "Лейтенант Павал Рит? Не припоминаю такого имени. Лучше всего вам будет поговорить с адъютантом Тезораном. У него хранятся все записи о тераморских стражниках – от их имен до предпочитаемого вооружения.\n\nУж он-то расскажет вам об этом Павале Рите.", progress = nil, completion = "Здравствуй, Эфром. Так тебе нужна информация об одном из нас? Как его бишь, Рит?\n\nСейчас проверю по своим записям.", rewards = "Вы получите:\n\n"},
[1260] = {title = "Морган Штерн", objective = "Поговорите с Морганом Штерном в Тераморе.", description = "Я составляю новое меню для ресторана. Сельская кухня с болотным душком. Думаю, посетителям \"Синего отшельника\" понравится!\n\nЯ послал своего племянника Моргана в Терамор, город на краю Пылевых топей. Там он собирает местные кулинарные рецепты, и мне хотелось бы знать, как его успехи.\n\nДолог путь до Терамора, и для меня тяжеловат. Но я думаю, что <такой молодой/такая молодая:c> <класс> с радостью ухватится за возможность совершить подобное путешествие.", progress = nil, completion = "А! Так вас послал мой дядя?\n\nНу что ж, я тут собирал для него рецепты и добился определенных успехов, но мне нужна помощь. \n\nНадеюсь, вы не боитесь ноги промочить?", rewards = "Вы получите:\n\n"},
[1261] = {title = "Марг говорит", objective = "Принесите изукрашенную Подвеску Назиру в Деревню Гиблотопь.", description = "Ах ты, проклятый грязнокраб! Ты меня не достанешь! Ой, да я ж покойник! Видать, он все-таки достал меня.\n\nА как же моя миссия?! Ты, <имя>, <должен/должна> закончить ее. Я наблюдал за силами Альянса, высадившимися на берегу возле Терамора. На одном из солдат была подвеска, на которой было столько драгоценных камней, что не всякий вождь может себе позволить.\n\nТой ночью я пробрался в лагерь и украл эту подвеску. Но когда я возвращался в свой лагерь, этот проклятый грязнокраб прикончил меня!\n\n<имя>, ты <должен/должна> найти эту тварь и вернуть подвеску.", progress = "Ты выяснил, что случилось с Маргом?", completion = "Эта подвеска была на солдате Штормграда??\n\nБлагодарю тебя, Томпсон, за то, что раскрыл загадку смерти Марга. Но эта подвеска... Это новая загадка. И, возможно, она несет угрозу и Орде и Альянсу.", rewards = "Вы получите:\n\n"},
[1262] = {title = "Сообщение для Зора", objective = "Отнесите изукрашенную подвеску Зору Одинокому Дереву в Оргриммар.", description = "Странно, что украденная Маргом была у простого солдата. Возможно ее владелец маскировался, или, что вероятнее, солдаты сами ее стащили. \n\nЧто бы там ни было, эта подвеска принадлежала лицу благородного происхождения, и мы должны найти ее хозяина, если хотим разрешить эту загадку.\n\nОтнеси эту подвеску Зору Одинокое Дерево в Оргриммар. Он хорошо разбирается в интригах Альянса и, возможно, он в курсе, если эта подвеска известна в Штормграде.", progress = "Ты шел сюда аж из Деревни Гиблотопь, что в Пыльной трясине? Как там поживает Назир, как его дела?", completion = "Эта подвеска сделана удивительно тнокой и искусной работы, Томпсон. Орку такое не нужно, но многие люди головы бы не пожалели за такую драгоценность.\n\nЯ изучу эту подвеску повнимательнее. Будем надеяться что в свое время мы все про нее узнаем.", rewards = "Вы получите:\n\n"},
[1263] = {title = "Сожженная Таверна", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1264] = {title = "Пропавший дипломат", objective = "Найдите командира Самаула в Пылевых топях.", description = "В начале каждого месяца стражи бухты Кул-Тираса получают жалованье и отправляются прочь из Терамора в отпуск. Многие из них приходят сюда – выпить, гульнуть, пообщаться с женщинами. Одна из таких компаний регулярно приходит в эту таверну. Мне кажется, что и этот Хендел был среди них.\n\nКомандир Самаул из Терамора может вам помочь в поисках Хендела, если тот до сих пор там. Самаул всецело верен леди Джайне, но если ты упомянешь при нем имя Эллинга, он должен стать... посговорчивее.", progress = nil, completion = "Рад встрече, Эфром. Я – командир Самаул, состою на службе в гвардии леди Джайны Праудмур в Тераморе.\n\nХотя я немного занят, вы можете задавать мне любые вопросы, которые вас интересуют. Не сочтите за повод для обиды, но я попрошу вас высказаться по возможности лаконично.\n\nНадеюсь, что вы проявите должную осторожность, если соберетесь за пределы города. Там, снаружи – огры, орки и мурлоки, а в южной части болота обитают черные драконы.", rewards = "Вы получите:\n\n"},
[1265] = {title = "Пропавший дипломат", objective = "Обыщите сторожевой пост, чтобы найти следы рядового Хендела.", description = "Хендел? Да, я его знаю, но почему вас интересуют мои солдаты?\n\nЭллинг отправил вас разыскать его? Звучит как-то странно. Эллинг не послал бы вас ко мне, если бы все было в порядке. Вы можете хранить свои секреты сколько угодно, только имейте в виду: мой долг – охранять эти земли. Если ваша деятельность может нарушить порядок, лучше сообщите заранее.\n\nДумаю, что Хендела вы найдете в первой по счету от Терамора башне. Будьте осторожны.", progress = "Да, Кирпичег?", completion = "Человека, известного вам как Хендел, здесь нет. Все остальное, что можно узнать от леди Праудмур, я думаю, вы уже знаете. Она просила меня найти вас и оказать вам помощь в расследовании. Если вы готовы принять мои услуги, я сообщу вам, где можно найти рядового Хендела. Вдвоем мы сможем предать его в руки правосудия.", rewards = "Вы получите:\n\n"},
[1266] = {title = "Пропавший дипломат", objective = "Найдите рядового Хендела в Пылевых топях.", description = "Рядовой Хендел находится к западу отсюда, в составе гвардии, охраняющей тераморских разведчиков во время отдыха. Они пытаются выяснить местоположение деревни Папоротники, базы Орды, а заодно и приглядывают за нашими границами.\n\nВы найдете его без труда, просто поищите в палатках у дороги.\n\nУ меня есть и другие дела, но я догоню вас так быстро, как смогу. При необходимости вы сможете найти меня в башне леди Праудмур.", progress = nil, completion = "Добрый день. Это опасное место для горожанина. Если вы цените свою жизнь, не стоит находиться здесь слишком долго.\n\nЗадавайте вопросы быстро, попробую вам помочь. Только смотрите по сторонам, не покажутся ли огры. По слухам, поблизости база Орды. Разведчики пытаются найти ее, но это дело небыстрое. Мы еще не добились успеха.", rewards = "Вы получите:\n\n"},
[1267] = {title = "Пропавший дипломат", objective = "Поговорите с леди Джайной Праудмур из Пыльной трясины.", description = nil, progress = nil, completion = "Сначала позвольте вас, Эфром, поблагодарить за все, что вы уже сделали. Вы оказали неоценимую услугу моим людям и всем обитателям Штормграда. Жаль, что наше знакомство не состоялось при более благоприятных обстоятельствах.\n\nНадеюсь, вы понимаете, что я не имею возможности публично выразить вам свою признательность, но знайте, что она поистине безгранична...\n\nВо время следующего визита в Терамор разыщите меня и я сделаю для вас все, что смогу.\n\nЭфром, позвольте еще раз поблагодарить вас.", rewards = "Вы получите:\n\nПерстень-печатка Джайны"},
[1268] = {title = "Подозрительные следы копыт", objective = "Доложите о подозрительных следах возле таверны \"Последний привал\" Крогу в Деревне Гиблотопь.", description = "Цепочка следов уходит от все еще дымящегося остова таверны \"Последний привал\". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчетливо.", progress = nil, completion = "Следы копыт... Это может быть иглогрив, или даже кентавр. То, что они пришли в Степи, что-то да значит, и, сдается мне, они вполне способны сжечь таверну.\n\nК тому же кто бы это ни был, они не только сожгли здание, жена и детеныш владельца были убиты. Плохо дело... \n\nЛадно, я пошлю Кагоро посмотреть куда ведут следы.", rewards = "Вы получите:\n\n"},
[1269] = {title = "Лейтенант Павал Рит", objective = "Принесите бляху Рита Крогу в деревню Гиблотопь.", description = "Солнечный зайчик блеснул в глаза из под обломков. Вы достаете из-под мусора бляху с золотым якорем на белой эмали – символом Терамора.\n\nПод якорем выбито имя владельца: \"Лейтенант Павал Рит\".", progress = "Удалось найти хоть какие-то намеки на то. Что случилось в таверне \"Последний привал\"?", completion = "Я знаю этого человека, Павала Рита. Жалкий даже по меркам собственного племени. Покинул своих товарищей и теперь скрывается в лесу. \n\nЯ послал Огрона выследить его. Некоторые подозревают, что он крал припасы. Я видел что Огрон направляется на юго-восток.", rewards = "Вы получите:\n\n"},
[1270] = {title = "Побег Вонючки", objective = "Сопроводите \"Вонючку\" Игнаца, затем пообщайтесь с Мебоком Миззриксом в Кабестане.", description = "Ура! Наконец-то нашелся кто-то, кто не хочет меня съесть!\n\nНе могу отбиться от тутошнего зверья, а т ы, <парень/подруга> как раз мне в этом и поможешь. Гоблину из Кабестана по кличке Мебок Миззрикс нужны листья болотного боба для зелья или еще какой надобности, – меня это, честно говоря, не колышет: он неплохо платит, а я неплохо знаю болота, потому и впрягся.\n\nВот только не успел я еще найти эти листья, как меня уже окружили. Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать для Мебока эти листья.", progress = nil, completion = "Вонючка недавно приносил тут мне травки, и он расказал, что ты помог ему выпутаться из мерзкой ситуации. Хорошая работа! Друг Вонючки и мой друг.\n\nПеред тем как вернуться обратно на болота, он просил передать тебе это, если мы вдруг увидимся.", rewards = "Вы получите:\n\nЭликсир стойкости"},
[1271] = {title = "Праздник в \"Голубом Отшельнике\"", objective = "Мой племянник сказал, что ты помог ему с его поисками в Пыльной трясине, а заодно и вытащил его компаньона из неслабой передряги. Мы, Штерны, держимся друг дружки и не забываем наших друзей!\n\nТак что мой руки, Маладат, сегодня пируем в твою честь!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nВлажная салфетка"},
[1272] = {title = "Найти Рита <CHANGE INTO GOSSIP>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1273] = {title = "Допрос Рита", objective = "Пойдите с Огроном и поговорите с Ритом, потом вернитесь к Крогу в Деревню Гиблотопь.", description = "Это было непросто, но я все-таки нашел этот Рит. Неплохо он прятаться... Для человек. \n\nОгрон боится, что человек свихнуться, – слишком много времени на болоте, Твоя идти с Огрон и спрашивать человека все, что хотеть.", progress = nil, completion = "Пфф. Это хорошо, что Рит больше не будет прятаться на болоте, но это плохо, что люди такие хрупкие существа, что могут помереть от одной маленькой стрелы.\n\nСдается мне, что мы зашли в тупик и нужно поискать разгадку где-нибудь еще.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГлазоколРазрывной аркебуз\n\nВы также получите:\n\n"},
[1274] = {title = "Пропавший дипломат", objective = "Найдите епископа Делавея в Крепости Штормграда.", description = "Простите, <сэр/мадам>. Епископ Делавей попросил меня разыскать любителя приключений, который мог бы помочь ему, оказав услугу весьма деликатного свойства.\n\nЕсли вы без лишнего шума проберетесь в Крепость Штормграда и обратитесь к епископу, он наверняка примет вашу помощь. Прошу вас, храните это в тайне, ибо все это дело большой важности.", progress = nil, completion = "Здравствуйте, Бронгард. Я – епископ Делавей.\n\nДайте-ка, я угадаю, почему вы здесь! Наверняка потому, что откликнулись на просьбу юного Томаса, который предложил вам оказать мне услугу. Он всегда стремится помочь мне.\n\nБоюсь, я еще не успел все сформулировать, так что простите мне некоторую невнятность изложения... И, прошу вас, храните все это в тайне.", rewards = "Вы получите:\n\n"},
[1275] = {title = "Исследование порчи", objective = "Гершал Шепот Ночи в Аубердине хочет, чтобы вы принесли ему 8 оскверненных стволов мозга.", description = "Безрассудные эльфы крови попали в западню демонической магии. Разве они не видели, что случилось с нагами и сатирами Калимдора?\n\nЯ боюсь, что эльфы крови могут претерпеть такую же трансформацию. Азерот не может позволить себе породить еще одну расу злобных монстров.\n\nЯ хотел бы изучить ствол мозга сатиров и нагов, чтобы понять, на что обрекают себя эльфы крови. И сатиров, и нагов вы найдете в Непроглядной Пучине, на побережье Ясеневого леса.\n\nПуть неблизкий, <имя>.", progress = "Когда у меня будет достачно образцов для изучения, я смогу начать настоящее исследование. Имея оскверненные стволы мозга как сатиров, так и нагов из Непроглядной Пучины, я смогу сопоставить их мутации.\n\nБыть может, полученные знания помогут нам не допустить окончательного перехода на сторону зла эльфов крови.", completion = "Вы проделали долгий путь и, несомненно, столкнулись с огромной опасностью.\n\nВаши действия были самоотверженными. Ваша помощь – на благо всему Азероту. Я благодарю вас, Даски, за все, что вы сделали.\n\nА теперь прошу меня простить, но мне нужно работать...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖучиные застежкиНакидка прелата\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1276] = {title = "Черный Щит", objective = "Покажите потемневший железный щит Мозарну из Громового Утеса.", description = "А, вспомнил! Мозарн – знаменитый кузнец из Громового Утеса. Я же помню, что слышал это имя прежде!\n\nЕсли мне не изменяет память, Служители Земли наградили меня оружием его работы, хорошее было оружие.\n\nВозможно, он расскажет тебе больше о щите, вышедшем из его рук.\n\nЯ не уверен, что эта информация важна, но, поскольку мы так и не знаем ничего о Рите, пренебрегать ей было бы неразумно.", progress = "Привет, |3-6(Охотник). Я могу чем-то помочь?", completion = "Да, ты прав Это моя работа.\n\nПравда, боюсь, что это все, что я могу тебе рассказать о нем, Томпсон. Из моих рук вышло столько щитов и прочего оружия, что вряд ли я смог бы запомнить их все.", rewards = "Вы получите:\n\n"},
[1281] = {title = "Песня Джима <CHANGE TO GOSSIP>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1282] = {title = "Зовут его Улыбка Джим", objective = "Поговорите с капитаном Гарраном Ваймсом в Тераморе.", description = "Ничего не могу с собой поделать, мне так жаль старину Джима... Он не всегда был таким... Когда-то он держал таверну на болотах, дивное было местечко.\n\nСлушай, я не в настроении говорить об этом. Если тебе нужна информация, поговори с капитаном Ваймсом.", progress = nil, completion = "Настоящее его имя – Джеймс Хьяль. Он открыл таверну на краю Степей, хотел сделать уютное местечко для отдыха путешественников. \n\nМожет, он слишком многого хотел, но некоторое время дела в таверне шли хорошо. Потом мы потеряли контроль за дорогами через болота, и здесь стали шататься огры, а Джеймс был слишком упрям, он не захотел бросить свое детище ради безопасности. Теперь таверна \"Последний привал\" сгорела до основания. Мы пытались разобраться, но особых успехов не достигли, поэтому твою помощь примем с благодарностью. Если хочешь помочь – посмотри, вдруг что найдешь на развалинах.", rewards = "Вы получите:\n\n"},
[1283] = {title = "Пожар в \"Последнем Приюте\"", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1284] = {title = "Подозрительные следы копыт", objective = "Доложите о подозрительных следах возле таверны \"Последний привал\" капитану Гаррану Ваймсу в Терамор.", description = "Цепочка следов уходит от все еще дымящегося остова таверны \"Последний привал\". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчетливо.", progress = nil, completion = "Следы копыт, говоришь? В последнее время в этих краях зашевелились кентавры. Наши разведчики во время вылазки в Степи заметили несколько их лагерей и поселений.\n\nЯ пошлю одного из наших охотников, Фальграна Гастила, посмотреть, куда ведут эти следы.", rewards = "Вы получите:\n\n"},
[1285] = {title = "Солдаты Даэлина", objective = "Вернитесь с информацией о Рите к капитану Гаррану Ваймсу в Терамор.", description = "Реддон... Редпат... А! Вот он! Лейтененат Павал Рит.\n\nВсупил в ряды тераморской стражи вместе с остальными новобранцами, которые пришли из-за моря вместе с леди Праудмур. Зачислен в морские пеходинцы Кул Тираса в возрасте шестнадцати лет. Отличная служба, поощрения...\n\nЧислится пропавшим без вести.", progress = nil, completion = "Пропал без вести? В переводе с языка Тезорана, это значит – предатель.\n\nНе сомневаюсь, что это один из тех глупцов, слепо преданных адмиралу Даэлину и готовых ради него предать собственную страну. Забавно, правда? Дезертиры обвиняют нас в предательстве дела Альянса.", rewards = "Вы получите:\n\n"},
[1286] = {title = "Дезертиры", objective = "Расспросите о Рите Балоса Хакена и его дезертиров в Пылевых топях.", description = "Удержаться здесь, на болотах, было нелегко. Но мы, со всей своей решимостью и отвагой, смогли возвести несколько оборонительных сторожевых башен в округе.\n\nПо последним донесениям наших разведчиков, группа дезертиров засела в Разрушенной башне, к юго-востоку от таверны. \n\nЗа главного у них, кажется, Балос Хакен. Посмотрим, может удастся получить от него какие-то сведения. \n\nНо будь с ним осторожнее, <имя>, он – тертый вояка.", progress = nil, completion = "Тебя Ваймс прислал? Вечно он спихивает на других всю грязную работу...", rewards = "Вы получите:\n\n"},
[1287] = {title = "Дезертиры", objective = "Поговорите с капитаном Гарраном Ваймсом в Тераморе.", description = "Рит? Этот трус?\n\nМы вышвырнули его из лагеря, потому что он настаивал на налете на деревню огров Гиблотопь, чтобы пограбить их запасы. Нас не так много, чтобы рассчитывать справиться с этими безмозглыми тварями. \n\nОн настолько часто зарывался, что мы решили, что с нас хватит, и прогнали его.\n\nВот, я помог тебе, почему бы теперь тебе не забыть о нашей встрече?", progress = nil, completion = "Я пошлю лейтенанта Келдвелла поговорить с дезертирами из Разрушенной башни. Вдобавок, я попрошу его поискать Рита. Болота не так уж велики и непроходимы, так что я уверен, он его отыщет.", rewards = "Вы получите:\n\n"},
[1288] = {title = "Донесение Ваймса", objective = "Отнесите донесение Ваймса леди Джайне Праудмур в Терамор.", description = "Хорошая работа, <имя>. Для любителя просто отличная. \n\nЛеди Праудмур просила, чтобы я держал ее в курсе, но я некоторое время не имел возможности с ней пообщаться.\n\nЯ собирался отправить ей рапорт позже, – но мне кажется уместным вместо этого послать к ней тебя. Ты куда лучше меня ответишь на все ее вопросы.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1290] = {title = "В поисках Мозарна", objective = "Говори.Поговори с бугаем Комаком. Но вопросов не задавай – убьет.", description = "Поговори с бугаем Комаком. Но вопросов не задавай – убьет.", progress = nil, completion = nil, rewards = nil},
[1301] = {title = "Джеймс Хьяль", objective = "Поговорите с Винсентом Хьялом в Гавани Менетилов.", description = "Перед тем, как перебраться сюда, в \"Синий Отшельник\", я обучался, у одного из лучших поваров которых я когда-либо встречал. Его звали Джеймс Хьяль, и все чего я добился в этой жизни, это только благодаря ему.\n\nИнтересно, как-то он там сейчас? Они вместе со своим братом Винсентом работали в таверне, в Гавани Менетилов, но я давно о нем ничего не слышал.\n\nЕсли вдруг ненароком встретишь его, кланяйся от меня.", progress = nil, completion = "Джеймс? Так он еще когда уехал отсюда. \n\nВолна патриотизма накрыла, наверное. Можно понять. Многие после всего этого безумия, творящегося в Лордероне, последовали за море за Джайной Праудмур.", rewards = "Вы получите:\n\n"},
[1302] = {title = "Джеймс Хьяль", objective = "Поговорите с клерком Лендри в Тераморе.", description = "Мой брат Джеймс ушел за море с леди Праудмур. Последнее, что я слышал, было то, что по окончании боев он открыл там таверну. Но, где бы он не находился, я уверен, что дела у него идут хорошо. Он ведь, знаете ли, великолепный повар.\n\nЯ некоторое время не имел о нем известий – видать, с гостиницей было много хлопот – но я уверен, что клерк в Тераморе сможет указать вам, где его искать.", progress = nil, completion = "Джеймс Хьяль, Джеймс Хьяль... Что-то знакомое...\n\nА, точно! Случай с \"Последним привалом\". Если ты хоть что-то об этом знаешь, то пойди и расскажи капитану Ваймсу. Он ведет расследование.", rewards = "Вы получите:\n\n"},
[1318] = {title = "Кое-какие дела с Гордоками", objective = "Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе.\n\nПо словам Давигрома, в \"старых байках\" говорится, что Тортелдрин – \"страшный эльф\", называющий себя принцем, – похитил эту рукавицу у одного из королей Гордоков.", description = "Ну, раз ты теперь король, может, попробуешь добыть сокровище Гордоков у того паскудного эльфа, который называет себя принцем, а? Тот король, что был до тебя, это дело профукал – так же, как и все прочие короли до него, с тех самых пор, как Тортелдрин, тот паскудный эльф, спер его у одного из королей!\n\nА вещица-то была ценная: латная рукавица Мощи Гордока! И в старых байках говорится, что воротить ее сможет только настоящий король Гордок. А еще говорится, что паскудный эльф до сих пор шляется где-то тут. Отыщи его, и будет тебе крутая рукавица, которую ты будешь носить по гроб жизни!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБоевые рукавицы клана ГордокРукавицы клана ГордокПерчатки клана ГордокПовязки клана Гордок\n\nВы также получите:\n\n"},
[1319] = {title = "Черный Щит", objective = "Покажите потемневший железный Щит Казу Дваждыдвацу из Терамора.", description = "Увы, но я не смогу помочь тебе, <имя>. Впрочем, я знаю, кто сможет. Каз Дваждыдвац – один из лучших наших кузнецов. Его можно найти на кузне.\n\nПокажи ему щит и послушай, что он скажет.", progress = "На что взглянуть?", completion = "Хмм... Интересная железяка. Это точно не моя работа, и я не знаю ни одного кузнеца по эту сторону моря, из чьих рук она могла бы выйти.", rewards = "Вы получите:\n\n"},
[1320] = {title = "Черный Щит", objective = "Поговорите с капитаном Гарраном Ваймсом в Тераморе.", description = "Чуть было не просмотрел... Кожаный ремень на тыльной стороне щита сгорел, но, сдается мне, он был приспособлен под крупную руку. Скорее всего, тауренскую.\n\nВот, в общем, и все, что я могу тебе сказать. Передай капитану Ваймсу, что я сожалею, но больше ничем не могу ему помочь.", progress = nil, completion = "Узнать удалось немного, но и это сгодится. Будем надеяться, что вскоре прояснятся остальные части этой головоломки, и мы сможем увидеть полную картину произошедшего.", rewards = "Вы получите:\n\n"},
[1321] = {title = "Черный щит", objective = "Покажите потемневший железный щит До'голу из Деревни Гиблотопь.", description = "Хмм... Я не вижу в этом щите ничего необычного. Нужно попросить До'гола, нашего кузнеца, взглянуть на него. Может быть, До'гол сможет рассказать нам больше, хотя я бы не надеялся на это...", progress = "Что это у тебя тут, |3-6(Охотник)?", completion = "Хороший щит. Крепкий, тяжелый, хороший... Но До'голу он не нужен. Догол делает щиты, а не покупает их, Томпсон.\n\nТеперь понятно?", rewards = "Вы получите:\n\n"},
[1322] = {title = "Черный Щит", objective = "Добудьте 6 ядовитых желез Паука Черного Тумана для До'гола из Деревни Гиблотопь.", description = "Хммм... Тут, на ободе щита, оказывается, есть надпись, но прочитать ее трудно, она почти вся обгорела.\n\nМне нужна кислота, чтобы отчистить ее. Яд пауков-темножвалов, обитающих в топях, подойдет. Принеси мне немного их ядовитых желез, и я смогу отчистить этот щит.", progress = "Ты добыл яд этих пауков?", completion = "Я не люблю слишком больших пауков – их не раздавишь.\n\nСпасибо, Томпсон. Теперь я вскрою железы и залью их содержимым щит…", rewards = "Вы получите:\n\n"},
[1323] = {title = "Черный Щит", objective = "Поговорите с Крогом в Деревне Гиблотопь.", description = "Сдается мне, что с кислотой я переборщил. Теперь осторожно потрем щит…\n\nХмм. Прочесть сложновато, но, похоже, тут написано имя: Мозарн. Никогда о таком не слышал. Надо спросить Крога, он знаком с кучей народу.", progress = nil, completion = "Мозарн? Звучит знакомо... Но поручиться не могу. Может быть вспомню попозже.\n\nСкорее всего, это имя не имеет значения. Щит мог попасть туда откуда угодно и с какой угодно целью.", rewards = "Вы получите:\n\n"},
[1324] = {title = "Пропавший дипломат", objective = "Победите рядового Хендела в Пылевых топях.", description = "Что?! Вы приходите сюда, обвиняете меня в пособничестве Братству Справедливости и надеетесь, что я буду стоять столбом и позволю себя убить? Меня, между прочим, давно насчет вас предупреждали...", progress = nil, completion = "Уверяю вас, что мы все огорчены текущими событиями, но просим позволить забрать его назад в Терамор, чтобы задать несколько вопросов. Это поможет в поисках короля.\n\nЛеди Праудмур отблагодарит вас за помощь. Обратитесь к ней при первой возможности.", rewards = "Вы получите:\n\n"},
[1338] = {title = "Заказ Грозовой Вершины", objective = "Отнесите заказ Грозовой Вершины Фьюрену Длиннобороду в Штормград.", description = "Есть один дворф-бронник, чья работа меня глубоко восхищает. Его зовут Фьюрен Длиннобород, и такого искусника еще поискать. Мне нужен новый щит, и я хотел бы сделать заказ у него!\n\nПроблема в том... что он живет далеко на юге, в Квартале Дворфов в Штормграде. В человеческих землях! Представления не имею, зачем он поселился так далеко от Стальгорна. Должно быть, люди платят немалую мзду, лишь бы удержать его у себя!\n\nЕсли ты любишь путешествовать и не прочь подзаработать, может, передашь мой заказ Фьюрену?", progress = "Письмо из дворфийских земель? Интересно, кто это пишет мне из такой дали…\n\nПозволь взглянуть на заказ.", completion = "А, заказ от дворфа Грозовой Вершины. Это гордый клан, славный крепкими, сильными дворфами. И их богатством.\n\nБольшое спасибо, Wrestlecake. Я сегодня же вечером займусь щитом для горного пехотинца Грозовой Вершины.", rewards = "Вы получите:\n\n"},
[1339] = {title = "Задание Грозовой Вершины", objective = "Поговорите с горным пехотинцем Грозовой Вершиной.", description = "Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие. Сможет ли <раса> вроде тебя справиться с его поручением?\n\nЕсли ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне.", progress = nil, completion = "Верно. У меня есть одно дельце, но самому мне недосуг – не могу покинуть пост. Путь неблизкий, придется поработать ногами.\n\nЗато отличная возможность поискать приключений!", rewards = "Вы получите:\n\n"},
[1358] = {title = "Образец для Хелбрима", objective = "Принесите препарат сердца волка аптекарю Хелбриму в Степи.", description = "Мой коллега на Калимдоре, аптекарь Хелбрим, исследует воздействие лордеронских ядов на тамошних зверей. Он наверняка хотел бы иметь препарат из волчьего сердца, что мне прислал Ренферрел. \n\nХелбрим обосновался в Степях, в деревне под названием Перекресток. Чтобы до него добраться, вам нужно будет на дирижабле добраться до орочьей столицы Оргриммара, а потом пешком проследовать на юг, в Дуротар. Направляйтесь на запад, в Степи, и вскоре дойдете до Перекрестка.", progress = "У вас есть для меня посылочка?", completion = "А, очень хорошо. Если первые результаты верны, токсические свойства этих сердец могут серьезно продвинуть нас в наших представлениях о ядах. \n\nЭто долгожданная посылка, Топот. Ваша награда за нее – совершенно заслуженная.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки пивовараДлинная накидка с драпировкой\n\nВы также получите:\n\n"},
[1359] = {title = "Посылка для Зинг", objective = "Отнесите препараты сердца волка аптекарю Зинг в Подгород.", description = "Волчьи сердца, которые вы собрали, обладают качеством, невиданным доселе в подобных образцах. Это сила яда, которая должна быть смертельной даже для тех самых волков, в груди которых бьются эти сердца! \n\nЭто просто невероятно, и мы должны продолжить исследование. Я сохранил несколько полученных препаратов. Отнесите их моей коллеге, аптекарю Зинг. Ее можно найти в главном представительстве нашего Общества в Подгороде.", progress = "Вы мне что-то принесли?", completion = "Ах да, препараты сердец, о которых говорил Ренферрел. Я хочу поскорее начать экспериментировать с ними... Обнаружение новых форм ядов всгда вызывает живейший интерес в Королевском фармацевтическом обществе.", rewards = "Вы получите:\n\n"},
[1360] = {title = "Возвращенное сокровище", objective = "Достаньте сокровище Крома Крепкорука из сундука в северном зале Ульдамана и принесите ему в Стальгорн.", description = "Я неплохо зарабатывал горнорабочим на ульдаманском раскопе в Бесплодных землях, пока не появились эти клятые трогги. Я едва сумел спасти свою шкуру, но в суматохе потерял самое дорогое, что у меня было. Уверен, что трогги не добрались до моего сокровища, поскольку оно в сундуке, но сундук-то в самой их гуще.\n\nЕсли ты принесешь его мне, то не поскуплюсь ни на деньги, ни на хвалу! Сундучок с моим именем находится в конце Северного зала. Вот туда тебе и надо попасть.", progress = "Ну, тебе удалось надавать этим троггам и добраться до моего сундука?", completion = "Ах, я снова счастлив! Спасибо тебе огромное.\n\nМожет, кому из дворфов дороже всего блеск металла, а кому – сверкание драгоценных камней, но Крепкорук без своей драгоценной пивной кружки вряд ли может считаться Крепкоруком!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1361] = {title = "Регтар Врата Смерти", objective = "Поговорите с Регтаром Врата Смерти.", description = "Регтар Врата Смерти, воин Орды, набирает агентов для похода в земли Пустошей. Любой желающий может поговорить с ним и попробовать записаться в отряд. Найти Регтара можно в Степях, в одном из укрытий к западу от Перекрестка.\n\nНе следует забывать, что в Пустошах не затихают битвы, поэтому без оружия там нечего делать.", progress = nil, completion = "Да, я набираю добровольцев. Тех, кто готов отправиться в Пустоши и сражаться с кентаврами. Я изложу ситуацию вкратце, чтобы ты скорее мог приступить к выполнению задания.", rewards = "Вы получите:\n\n"},
[1362] = {title = "Кентавры Пустошей", objective = "Найдите на Заставе Скитающихся Духов в Пустошах Фелгура Бью-Двоих и поговорите с ним.", description = "Кентавры из клана Колкар изначально жили в Пустошах, но теперь они все чаще появляются в Степях. Это известный факт, и Орда послала своих агентов разбираться с ними.\n\nОднако же пока клан Колкар силен в Пустошах, эти кентавры всегда будут для нас угрозой. Думаю, пора от них избавиться. Главное – безопасность!\n\nПоговори с Фелгуром Бью-Двоих: ты его найдешь на Заставе Скитающихся Духов в Пустошах. Его отправили туда для сбора информации о кентаврах. Думаю, он лучше всех знает, как справиться с кланом Колкар.", progress = nil, completion = "Тебя Регтар сюда прислал? Значит, ты и будешь решать проблему кентавров? Что ж, хорошо.\n\nНадеюсь, ты успел отдохнуть. Не знаю уж, удастся нам разобраться с этими тварями, или нет, но за то, что это будет долгая и тяжкая драка, могу ручаться.\n\nПрисядь и послушай меня...", rewards = "Вы получите:\n\n"},
[1363] = {title = "Задание Мазена", objective = "Поговорите с послушником Деллисом в Штормграде.", description = "Я слежу за тем, чтобы все фолианты и свитки в библиотеке Академии Тайных Наук и Искусств постоянно находились под присмотром. Кто знает, сколько глупостей может натворить непосвященный, заполучив тайные трактаты по магии?\n\nНапример, на прошлой неделе мой помощник Деллис допустил одну оплошность... Он неплохой работник и хорошо ориентируется в пределах библиотеки, но совершенно теряется, стоит ему выйти за ворота Штормграда... Пожалуйста, помогите Деллису разобраться с его затруднением.", progress = nil, completion = "Да не виноват я! Клянусь, не виноват!", rewards = "Вы получите:\n\n"},
[1364] = {title = "Задание Мазена", objective = "Верните \"Рассуждения Кадгара о пространственной сходимости\" и доставьте сочинение дозорному Махару Ба в Крепость Стражей Пустоты.", description = "Указания мастера Мазена были совсем простыми: доставить важное сочинение дозорному Махару Ба в Крепость Стражей Пустоты.\n\nНо мне раньше не доводилось бывать в Выжженных землях! Путешествие было просто ужасным...\n\nНеподалеку от Болота Печали я свернул куда-то не туда и оказался окружен жуткими тварями, похожими на растения. Они напали на меня, и я сбежал. Представьте себе, при этом я потерял сочинение! Думаю, его забрала одна из этих тварей.\n\nНе могу ли я попросить вас найти документ и доставить его Махару Ба?", progress = "Что привело вас в Крепость Стражей Пустоты, |3-6(дворф)?", completion = "Какое счастье!\n\nДо сего момента я считал, что мой запрос на \"Рассуждения Кадгара о пространственной сходимости\", который я отправлял в Академию Тайных Наук и Искусств, был отклонен мастером Мазеном.\n\nОн, должно быть, просто потонул в запросах, поскольку последнее время происходит множество странных событий.\n\nТеперь прошу меня простить – мне пора приступить к исследованиям. Понимаете, сама возможность прикоснуться к творению величайшего Кадгара повергает меня в трепет...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКушак наставникаСапоги Жажды странствий\n\nВы также получите:\n\n"},
[1365] = {title = "Вождь Дез'хеп", objective = "Принесиет Фелгуру Бью-Двоих голову вождя Дез'хепа.", description = "Племя Колкар – не единственные кентавры в Пустошах. На этих пустынных равнинах поселилось множество племен, ведущих друг с другом бесконечную войну. Наше счастье, что они дерутся между собой: кентавры сильны и яростны в битве, и, если бы они объединились, нам тяжело было бы выстоять против них.\n\nМы должны покончить с ними прежде, чем они объединятся.\n\nТвое первое задание – расколоть племя Колкар. Для этого нужно убить их предводителя Дез'хепа.\n\nДеревня клана Колкар находится к северо-востоку отсюда. Иди, и да пребудет с тобой удача.", progress = "Ну что, Томпсон, удалось тебе одолеть Дез'хепа?", completion = "Отлично. Быстрый и точный удар по клану Колкар стал весьма эффектной демонстрацией силы, а сила – это именно то, что кентавры понимают лучше всего.\n\nСмерть вождя клана Колкар не только расколет клан, но и станет предостережением для всех прочих кентавров.", rewards = "Вы получите:\n\n"},
[1366] = {title = "Награда за кентавров", objective = "Принесите в Пустоши 15 ушей кентавров и отдайте Фелгуру Бью-Двоих.", description = "Тебе удалось устрашить кентавров; теперь пришло время пустить им кровь. Странствуя по Безлюдью, охоться на кентавров. Их клан меня не волнует: просто убей их и принеси мне уши. Пригоршни ушей!\n\nЧем меньше кентавров, тем слабее их решимость: пусть навсегда расстанутся с мыслью завоевать эти земли!\n\nДоброй охоты, <имя>.", progress = "Как идет добыча ушей, Томпсон? Много нарезал?", completion = "Теперь-то кентавры навсегда запомнят твое имя! Уверен, они уважают и страшатся тебя. Уверен, благодаря тебе они не забудут и того знамени, под которым ты вступал в бой.\n\nЗнамя Орды!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСиреневый кушакСкрепленные боевые рукавицы\n\nВы также получите:\n\n"},
[1367] = {title = "Союз с племенем Маграм", objective = "Заслужите дружественное отношение племени Маграм, а затем поговорите с Варугом.", description = "Чтобы победить кентавров, мы должны обратить против них их же собственную ненависть. Мы заключим союз с одним из племен, и так найдем способ одолеть всех остальных.\n\nЕсли ты решишь заключить союз с племенем Маграм, уничтожь их кровных врагов – племя Гелкис. Так ты завоюешь уважение племени Маграм. Когда кентавры будут достаточно доверять тебе, постарайся встретиться с Варугом. Ты найдешь его на окраине деревни Маграм в юго-восточной части Пустошей.", progress = nil, completion = "Кентавры племени Гелкис кричат от ужаса, заслышав твое имя, Бифачу. Они страшатся и ненавидят тебя. Ненавидят так же, как племя Маграм!\n\nМожет, ты и не слабее нас. Может, ты даже достоин того, чтобы мы с тобой говорили. Посмотрим...", rewards = "Вы получите:\n\n"},
[1368] = {title = "Союз с племенем Гелкис", objective = "Заслужите дружественное отношение племени Гелкис, а затем поговорите с Утой Мудрой.", description = "Чтобы победить кентавров, мы должны обратить против них их же собственную ненависть. Мы заключим союз с одним из племен, и так найдем способ одолеть всех остальных.\n\nЕсли ты решишь заключить союз с племенем Гелкис, уничтожь их кровных врагов – племя Маграм. Так ты завоюешь уважение племени Гелкис. Когда кентавры будут достаточно доверять тебе, постарайся встретиться с Утой Мудрой. Ты найдешь ее на окраине деревни Гелкис в юго-западной части Пустошей.", progress = nil, completion = "Земля говорит со мной; земля говорит, что ты убил многих из племени Маграм. Это хорошо.\n\nЕсли хочешь быть другом племени Гелкис, слушай. Я буду говорить с тобой. У меня есть для тебя дело.", rewards = "Вы получите:\n\n"},
[1369] = {title = "Россыпи Слез", objective = "Для поддержания отношений с племенем Маграм принесите 3 кристалла Россыпи Слез Варугу в деревню Маграм.", description = "Племя Гелкис считает, что нас защищает матерь кентавров Терадрас. Они глупы. Кентавров никто не защищает. Маграм не нужна защита! Мы сильнее всех!\n\nПусть племя Гелкис поймет, насколько они глупы. Отправляйся в их деревню, прямиком к пещере. В этой пещере они хранят кристаллы – слезы Терадрас. Уничтожь эти кристаллы! Принеси мне их осколки!", progress = "Если ты нам не враг, то сделаешь то, о чем я прошу!", completion = "Ага! Вот они, Слезы! Теперь племя Гелкис поймет, что Терадрас не защитит их. Она не станет плакать, когда мы сокрушим их! Маграм будут править здесь!\n\nТы хорошо сделал, выбрав нашу сторону, Пластырь. Мы – самые сильные.", rewards = "Вы получите:\n\n"},
[1370] = {title = "Похищение припасов", objective = "Принесите 6 мешков недосушенного мяса в деревню Гелкис и отдайте Уте Мудрой.", description = "Когда мы не воюем, то охотимся, чтобы добыть мяса. Мясо дает нам силу. Сытый воюет лучше голодного. Сытый сильнее. Сытый победит.\n\nПлемя Маграм поступает так же. Они запасают мясо, чтобы воевать дольше. Если нападешь на их деревню на востоке и заберешь их припасы, Маграм станут слабыми.", progress = "Когда докажешь, что верен клану Гелкис, возвращайся. Будем говорить.", completion = "Хорошо. Я слышу, как урчит в брюхе у голодных Маграм! Слышу это даже здесь!\n\nЯ отдам это мясо племени Гелкис. Мы будем воевать много дней без отдыха.\n\nТо, что ты сделал, хорошо для племени Гелкис.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСеребряная звездаОперенная стрелаРазрывной патрон\n\nВы также получите:\n\n"},
[1371] = {title = "Игрушка для Варуга", objective = "Для поддержания отношений с племенем Маграм принесите усовершенствованный манекен-мишень Варугу в деревню Маграм.", description = "Давным-давно один маленький гном пришел в Пустоши со своей тележной, запряженной лошадью и нагруженной множеством странных вещей. Занятных вещей. Некоторые горели разноцветным огнем. Некоторые двигались, не будучи при этом живыми. Я убил этого маленького гнома, но перед этим... он заставил меня посмеяться.\n\nЯ оставил себе одну вещицу с его тележки – ту, которая понравилась мне больше всего. Это был деревянный человек, который махал на меня руками, пока я не ударил его, да так, что тот сломался.\n\nЯ хочу нового деревянного человека! Доставай его, где хочешь, но принеси мне!", progress = "Если ты нам не враг, то сделаешь то, о чем я прошу!", completion = "Да! Именно такой человек у меня и был! Он снова будет двигаться. Снова будет веселить меня!", rewards = "Вы получите:\n\n"},
[1372] = {title = "Правда и только правда", objective = "Поговорите с аптекарем Фаустином в Приюте Бродяги.", description = "По приказу Вариматраса нашу экспедицию направили на изучение нижнего Азерота.\n\nОтправившись на разведку, я заметил лазутчика, подобравшегося к Приюту Бродяги. Не успел я скрутить его, как некоторые наши орочьи... братья... захватили его и уволокли в Каменор, крепость на Болоте Печали.\n\nЯ хочу... помочь... нашим братьям-оркам. Они не заметили наш лагерь, но я все равно собираюсь оказать им услугу.\n\nФаустин поможет тебе сделать... сыворотку правды для нашего друга в Каменоре.", progress = nil, completion = "Зредус как раз перед твоим приходом рассказал мне об этом любопытном маленьком лазутчике.\n\nЭто и правда проблема. Нам вовсе не нужен нахал, вынюхивающий, что да как.\n\nУверен, орки Каменора с интересом выслушают его. Поскольку они, хм, наши союзники, мы должны помочь им добыть информацию от этого человека.\n\nПомоги мне, Томпсон, – и мы доставим в Каменор сыворотку правды.\n\nЗа Орду!\n\nЭ-э... я правильно выразился?", rewards = "Вы получите:\n\n"},
[1373] = {title = "Онгеку", objective = "Для поддержания отношений с племенем Гелкис принесите осколок дренейского аметиста Уте Мудрой в деревню Гелкис.", description = "Тебе еще предстоит свершить многое. Война племен Гелкис и Маграм тебя не затронет: в это время ты будешь далеко отсюда.\n\nЗемля раскрывает множество тайн тем, кто умеет слушать ее; и одна из них – тайна красного кристалла, который называют дренейским аметистом. Это камень нездешнего происхождения; он из тех земель, где горы парят в небе, где правят демоны...\n\nПринеси мне осколок дренейского аметиста: о, с ним сила моей магии возрастет во много раз!.. Осколок можно отыскать на Болоте Печали: его хранит один из Заблудших, Онгеку.", progress = "Докажи, что ты – подлинный друг племени Гелкис, Томпсон.", completion = "О да, это и есть тот осколок, о котором шептала мне земля... Я ощущаю его магическую силу – ту силу, которую я направлю против врагов племени Гелкис.\n\nТебе удалось исполнить еще одно наше задание, Томпсон. Возможно, со временем племя Гелкис сможет по праву считать тебя другом.", rewards = "Вы получите:\n\n"},
[1374] = {title = "Вождь Джен", objective = "Принесите голову вождя Джехна Уте Мудрой в деревню Гелкис.", description = "Земля говорит со мной. Земля знает, что племя Маграм утратил былую силу. Пришло время покончить с их вождем!\n\nПринеси мне голову Джехна, вождя племени Маграм!", progress = "Докажи, что ты – подлинный друг племени Гелкис, Томпсон.", completion = "Вождь Джехн был силен, но глуп. Он полагал, что наделен великой силой, но забыл, что магия Земли могущественнее любого смертного. Лишившись вождя, племя Маграм впадет в ничтожество, и племя Гелкис восторжествует!", rewards = "Вы получите:\n\n"},
[1375] = {title = "Вождь Шак", objective = "Для поддержания отношений с племенем Маграм принесите голову вождя Шака Варугу в деревню Маграм.", description = "Ты помогаешь племени Маграм. Это хорошо. Ты мне нравишься. А теперь пойди и убей вождя племени Гелкис! Вождь Шак – мне нужна его голова! Я хочу видеть его голову, я буду смотреть на нее и смеяться!", progress = "Делай то, что нужно племени Маграм, и я помогу тебе.", completion = "Вождь Шак мертв! Я насажу его голову на пику, чтобы любоваться ею каждый день! Пусть мертвые глаза Шака видят мощь племени Маграм!", rewards = "Вы получите:\n\n"},
[1380] = {title = "Вождь Храта", objective = "Для поддержания отношений с племенем Гелкис принесите фрагмент Ключа Мародина Уте Мудрой в деревню Гелкис.", description = "Ты <помог/помогла> нам справиться с племенем Маграм, <имя>; теперь помоги нам одолеть племя Мародин! Убей их предводителя! Убей Храту!\n\nЧтобы вызвать его на бой, ты <должен/должна> протрубить в боевой рог племени Мародин; а рог этот ты найдешь, поднявшись на высокий утес в Долине Копий.\n\nТолько запомни: чтобы протрубить в рог, тебе нужно разыскать мундштук, а это нелегко, потому что найти такие мундштуки можно только у кентавров, пользующихся особым доверием племени...\n\nО чем это я? Ах, да: когда ты протрубишь в рог, кентавры явятся на бой, и тебе придется убивать их, пока не доберешься до самого Храты.\n\nА у вождя Храты есть фрагмент... некоего ключа. Принеси его мне...", progress = "Надеюсь, вождь Храта мертв? А фрагмент ключа – он у тебя?", completion = "Он мертв! Вождь Храта мертв! Теперь племя Мародин падет! И когда этой землей станет править племя Гелкис – клянусь, мы не забудем тебя, Веленар. Духи земли будут вечно славить твое имя!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольчуга мародера из племени ГелкисПалец Утера\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1381] = {title = "Вождь Храта", objective = "Для поддержания отношений с племенем Маграм принесите фрагмент Ключа Мародина Варугу в деревню Маграм.", description = "Вождь племени Гелкис мертв; пришел черед племени Мародин! Убей их вождя, Храту!\n\nЕго не так просто отыскать, нет... Чтобы вызвать его на бой, ты <должен/должна> протрубить в боевой рог клана Мародин; а рог этот ты найдешь, поднявшись на высокий утес в Долине Копий. Только запомни: чтобы протрубить в рог, тебе нужно убить кентавра из племени Мародин и забрать у него мундштук.И вот когда ты протрубишь в рог, кентавры явятся на бой, и тебе придется убивать их, пока не доберешься до самого Храты. А у Храты есть фрагмент ключа. Он нужен мне, этот фрагмент. Принеси его. Принеси мне.", progress = "Сделай, что я говорю. Докажи, что ты – достойный союзник племени Маграм!", completion = "Вождь Храта мертв! Теперь Маграм – сильнейшее из племен! Мы сокрушим всех! Мы будем править в Пустошах!\n\nМы не забудем тебя, Джакрозет, и в тот час, когда сотни будут гибнуть под нашими копытами, мы пощадим тебя.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОхотничий пояс МаграмЦеремониальная попона кентавров\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1382] = {title = "Странный союз", objective = "Заслужите дружественное отношение племени Гелкис, а затем поговорите с Утой Мудрой.", description = "На наше счастье, племена кентавров постоянно враждуют. Если бы они объединились, никто не сумел бы их остановить. Да, нам сильно повезло – и мы должны обратить это везение себе на пользу.\n\nПлемя Гелкис ведет жестокую войну с племенем Маграм. Если мы атакуем поселение Маграм, то, возможно, сумеем заключить союз с племенем Гелкис.\n\nВ юго-западной части Пустошей, неподалеку от лагерей племени Гелкис, ты сможешь найти Уту Мудрую. Возможно, поговорив с ней, ты сумеешь заключить союз...", progress = "Прочь! Кентавры племени Гелкис не желают видеть тебя! Уходи!\n\nИди, убей Маграм, много Маграм – тогда будем говорить.", completion = "В племени Гелкис говорят о тебе. Твои руки в крови проклятых Маграм. Это хорошо.\n\nЯ буду говорить с тобой. Скажи, что ты можешь сделать для племени Гелкис – и что племя может сделать для тебя.", rewards = "Вы получите:\n\n"},
[1383] = {title = "Правда и только правда", objective = "Принесите аптекарю Фаустину в Приют Бродяги 5 сердец пантер тени, мох хозяина болота и опухоль странника глубин.", description = "Я знаю подходящую сыворотку. Она обойдется с правдой именно так, как с ней следует обходиться.\n\nЧтобы сделать ее, мне понадобится несколько сердец пантер Тени из болота. Кроме того, мне нужен мох хозяина болота, обитающего неподалеку. Не сомневаюсь, что ты сумеешь уговорить его поделиться с тобой.\n\nИ последнее, что необходимо мне для составления сыворотки, это опухоль странника глубин из отдаленных Пустошей. Эти гиганты редко болеют, а опухоли у них появляются еще реже.\n\nА теперь иди!", progress = "Лазутчик в Каменоре несомненно... расколется... после того, как напьется моей сыворотки. Ха-ха!\n\nОднако компоненты достать сложно. Пантеры Тени часто встречаются на Болоте, но собрать достаточно сердец – непростая задача. А хозяин болота может быть очень несговорчивым.\n\nДа и достать опухоль странника глубин – та еще задачка, но зато с ней можно провести такую реакцию, что мало не покажется.", completion = "Великолепно, Томпсон! И как раз вовремя. Судя по тому, что говорит Зредус, лазутчик оправился от ран и готов к допросу.\n\nПогоди, сейчас я приготовлю отра... то есть сыворотку правды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПлащ гнилиКувалда Утесного леса\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1384] = {title = "Набег на племя Колкар", objective = "Для поддержания отношений с племенем Гелкис принесите 10 грубых оберегов Уте Мудрой в деревню Гелкис.", description = "Кентавры из племени Колкар полагают, что сильны в магии. Они ничего не понимают в магии! Они не распознают ее, даже если их носом в магию ткнуть!..\n\nКто-то должен доказать им, что в отношении магии они просто дети неразумные. Думаю, этим кем-то будешь ты. Отправляйся в деревню Колкар, что на северо-восток отсюда. Отними у кентавров их обереги и принеси их мне. Я брошу их в огонь, и это согреет мне сердце.", progress = "Где обереги? Они у тебя? Теперь-то эти кентавры поняли, как они слабы?", completion = "Ты сделал доброе дело для племени Гелкис. Клан Колкар слаб: он обречен и сгинет. Их жалкая магия не поможет им. Ты показал им это – и страх сделает их еще слабее!\n\nВ этих землях слабаки долго не живут.", rewards = "Вы получите:\n\n"},
[1385] = {title = "Политика силы", objective = "Заслужите дружественное отношение племени Маграм, а затем поговорите с Варугом.", description = "Пустоши – земля, пожираемая огнем войны. Кентавры враждуют между собой; мы страшимся того, что победившее племя пойдет войной на наши крепости и разрушит их. Мы не можем этого допустить.\n\nМы должны научиться побеждать кентавров, а для этого нам придется заключить союз с одним из их племен. Племя Маграм издревле враждует с племенем Гелкис. Если ты начнешь войну с племенем Гелкис, возможно, племя Маграм задумается о том, что неплохо бы иметь такого воина на своей стороне.\n\nЗавоюй расположение племени Маграм, а затем отправляйся в деревню племени в юго-восточной части Пустошей и поговори с Варугом.", progress = "Уходи прочь, не то Маграм сокрушат тебя! Хочешь стать нашим другом – убивай кентавров племени Гелкис!", completion = "Многие из племени Гелкис пали от твоей руки. Мне это нравится. Может, ты сумеешь сделать что-то еще, что мне понравится. Может, ты сумеешь стать другом племени Маграм.", rewards = "Вы получите:\n\n"},
[1386] = {title = "Нападение на племя Колкар", objective = "Для поддержания отношений с племенем Маграм вы должны убить 12 кентавров из племени Колкар, 12 разведчиков из племени Колкар и 6 извергов из племени Колкар, а затем вернуться к Варугу в деревню Маграм.", description = "Клан Колкар полагает, что он силен; мы смеемся над ними – и убиваем их со смехом! Ты тоже их убиваешь. Покажи, что умеешь убивать их не хуже, чем мы. Клан Колкар должен умереть. Иди на север. Убей их. Убей их всех!", progress = nil, completion = "Теперь клан Колкар страшится тебя. Скажи, ты смеялся, когда убивал их? Когда убиваешь, надо смеяться: тогда враги увидят, что они слабы.", rewards = "Вы получите:\n\n"},
[1387] = {title = "Награда за кентавров", objective = "Принесите в город Высота Найджела 15 ушей кентавров и отдайте их капралу Мелкису.", description = "Раса кентавров состоит из множества кланов. У каждого из них – свой вождь и свои законы, но есть одна черта, которая объединяет их всех: жестокость.\n\nЕсли мы хотим обрести мир, нам следует изгнать кентавров из этих земель. Тебе предстоит исполнить это нелегкое задание.\n\nВ своих странствиях по Безлюдью ты будешь убивать кентавров и собирать их уши. Чем больше ушей, тем лучше. Принеси их мне.\n\nЕсли, <имя>, ты исполнишь это во славу и во имя Альянса, мы будем на шаг ближе к завершению этой войны.", progress = "Тебе есть что сообщить, Эфром?", completion = "Ах, уши... Уши! Что ж, прекрасно.\n\nБесспорно, услуги, оказанные тобой Альянсу, весьма велики, Эфром. Поверь, та кровь, что была пролита тобой в Пустошах, поможет спасти множество жизней.", rewards = "Вы получите:\n\nКольцо покоя"},
[1388] = {title = "Правда и только правда", objective = "Отдайте сыворотку правды Фаустина стражу смерти Зредусу в Приюте Бродяги.", description = "Все прошло точно по плану. Теперь отнеси эту сыворотку правды стражу смерти Зредусу, и он покажет, как ею... Правильно воспользоваться.\n\nХа-ха!", progress = "Не сомневаюсь, что ты очень помог нашему дорогому другу, аптекарю Фаустину.", completion = "Я знал, что старина Фаустин что-нибудь придумает! Ты ему очень помог, я даже не сомневаюсь.\n\nА теперь к делу, верно?", rewards = "Вы получите:\n\n"},
[1389] = {title = "Кристаллы дренейского аметиста", objective = "Принесите 6 кристаллов дренейского аметиста Магтуру в Убежище в Болоте Печали.", description = "Заблудшие, живущие в Болотном пристанище, на вид ничем от нас не отличаются, но на самом деле это чудовища... лишившиеся рассудка в пути до Азерота. Когда-то они были нашими братьями. Теперь они живут в Болотном пристанище, к востоку отсюда, захватывая и убивая любого, кто попадется под руку.\n\nСейчас они украли одну из наших святынь – кристаллы дренейского аметиста.\n\nУ нас не хватает сил ворваться в Святилище и вернуть себе нашу реликвию, но без нее... мы тоже вскоре утратим свой путь.", progress = "Ну, и где кристаллы?", completion = "Благодарю тебя, Томпсон. Мы перед тобой в долгу.", rewards = "Вы получите:\n\n"},
[1391] = {title = "Правда и только правда", objective = "Отнесите бражку Зредуса секретному агенту Марксену в Каменор.", description = "Мы должны действовать тайно. В конце концов ты же не можешь войти и заставить этого олуха выпить состав Фаустина?\n\nНо от выпивки ни один человек не откажется. Я возьму сыворотку Фаустина и замешаю ее в эль. Сомнений нет, бедняга без колебаний выпьет предложенную бурду.\n\nСпеши в Каменор на Болото Печали, <имя>. И никому не рассказывай о нашем задании...", progress = "Прошу, смилуйся надо мной! У меня есть сведения, которые не касаются Альянса. Хотя я не сторонник Орды, вы столкнулись с предательством, которое я хочу разоблачить!", completion = "Ты принес мне попить? Как мило с твоей стороны. Мне не давали даже губы смочить вот уже несколько дней. Позволь мне утолить жажду, и я расскажу обо всем, что узнал...", rewards = "Вы получите:\n\n"},
[1392] = {title = "Нобору Дубина", objective = "Принесите дубину Нобору главе Убежища на Болото Печали.", description = "Нобору много месяцев не давал житья дренеям Прибежища, и его дубина стала символом жестокости, которую они претерпели от рук Заблудших.", progress = "Приветствую. И добро пожаловать в Убежище!", completion = "Ты добыл оружие ужасного Нобору? Так значит он мертв? \n\nЭто праздник для всего Убежища! Нобору и его банда, многие годы терроризировали нас, бродя по болотам и убивая любого дренея, который попадался на пути. Он ставил под угрозу само наше выживание, но нам не хватало сил, справиться с ним самостоятельно. \n\nТы оказал нам большую услугу, Томпсон.", rewards = "Вы получите:\n\n"},
[1393] = {title = "Побег Галена", objective = "Выведите Галена из опасного места, затем найдите его лагерь на Болоте Печали и откройте его сейф.", description = "Помогите! Эти твари хотят меня съесть!\n\nЕсли ты поможешь мне выбраться отсюда, то получишь великое сокровище! Оно лежит в моем лагере, в болотах к северу от Каменора, но только я знаю, как открыть сейф, в котором оно находится.\n\nЕсли ты поможешь мне, я научу тебя, как открыть этот сейф.", progress = nil, completion = "Замочная скважина этого сейфа залита черной смолой. Открыть его невозможно.\n\nНо Гален рассказал вам о секретном замке на днище сейфа... \n\n... Быстро осмотрев сейф, вы находите задвижку. Задвижка отодвинута, и сейф открывается.", rewards = "Вы получите:\n\nПровидческий кулачный щит"},
[1394] = {title = "Финальное испытание", objective = "Поговорите с Дорном Вольным Ловчим в Тысяче Игл.", description = "Ты хорошо <справился/справилась>, <имя>. Ты <прошел/прошла> все мои испытания и те, что были до этого. Возвращайся к Дорну в Тысячу Игл. Он непременно заметит перемены, произошедшие с твоим телом, разумом и духом, и поймет, что твои усилия достойны награды.\n\nВсегда храни в себе ту гармонию, которой ты <достиг/достигла> в этих испытаниях, <имя>, и тогда в будущем Дорн сможет испытать тебя еще раз.", progress = nil, completion = "А, Томпсон. Давненько ты не заглядывал в мой дом. Кажется, прошло уже много лун с тех пор, как ты сделал первый шаг на своем пути.\n\nА теперь ты вернулся намного сильнее, чем раньше... И намного мудрее. Это хорошо. И тебе полагается достойная награда за все испытания.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМолот БуреветраТанцующее пламя\n\nВы также получите:\n\n"},
[1395] = {title = "Поставки для Стражей Пустоты", objective = "Отнесите ящик камней силы интенданту Лунгерцу прежде, чем камни утратят силу.", description = "Этот ящик с камнями силы нужно доставить в Крепость Стражей Пустоты, в Выжженные земли. Их сила будет сохраняться не так-то долго, так что мы не можем отправить их следующим караваном. \n\nТебе следует отнести их как можно скорее..\n\nОтдай их интенданту Лунгерцу в Крепости Стражей Пустоты. Чтобы достичь крепости, тебе следует направиться на восток через Первал Мертвого Ветра, затем далее через Болото Печали, потом свернуть на юг через Выжженные земли.\n\nОднако осторожнее, <имя>. Твой путь проляжет через опасные земли, но цель должна быть достигнута.", progress = "Приветствую! Не обращай внимания на всю эту суматоху, это обычное дело в Крепости Стражей Пустоты.\n\nУ тебя что-то для меня есть?", completion = "О, камни силы! Маги будут рады увидеть их!\n\nБольшое спасибо, Эфром. Я знаю, что твой путь из Темнолесья был нелегок.", rewards = "Вы получите:\n\n"},
[1396] = {title = "Атака тварей", objective = "Убейте 8 молодых острозубых кроколисков, 10 ткачей скорби и 10 болотных ягуаров и потом вернитесь к дозорному Биггсу на Болоте Печали.", description = "Мой караван направлялся к восточному побережью, но до места так и не добрался. Заблудшие атаковали нас, перебив стражу и уничтожив припасы.\n\nВыжить удалось только мне. Я обещал сохранить оставшиеся товары, но вокруг полно чудовищ. Прошу тебя, помоги мне защитить мой лагерь!", progress = "Болотные твари наседают, Драгунов! Ты должен спасти лагерь!", completion = "Судя по звукам, твари убрались. Благодарю тебя, Маладат. Теперь-то, надеюсь, они не вернутся!", rewards = "Вы получите:\n\n"},
[1398] = {title = "Плавник", objective = "Принести 8 кусков сухого плавника дозорному Биггсу на Болоте Печали.", description = "Я – твой должник,<имя>, В твоей груди бьется великодушное сердце. А теперь – смею ли еще раз попросить тебя о помощи?\n\nЧтобы добраться до Стражей Пустоты, я должен починить эту повозку, а для этого мне необходимо дерево. Сухое, прямое дерево, а те не рыхлые и скрюченные кусты, которые растут на болотах.\n\nОтправляйся на восточное побережье, поищи там плавник хорошо просущеный солнцем и принеси его мне.", progress = "Ты нашел хоть немного плавника, Маладат?", completion = "Дерево легкое, но крепкое. Спасибо, Маладат, это подойдет.", rewards = "Вы получите:\n\n"},
[1418] = {title = "Ника Алый Шрам", objective = "Поговорите с Никой Алый Шрам.", description = "Бесплодные земли суровы. Они примыкают к территории Альянса возле озера Лок Модан, потому сообщение между Каменором и форпостом Каргата часто оказывается перерезанным. <имя>, у тебя есть шанс проявить себя. Отправляйся в Бесплодные земли и поговори с Никой Алый Шрам, главой разведчиков Каргатского форпоста, а затем принеси мне ее доклад.", progress = nil, completion = "Хелгруму нужен доклад, а? Я посылала гонца в Каменор около трех дней назад. Он что, не добрался? Если в Каменоре нет моего донесения, сдается мне, гонец сгинул. Будем надеяться, что следующий, кого я пошлю, будет лучше подготовлен, ну или более удачлив.", rewards = "Вы получите:\n\n"},
[1419] = {title = "Койоты-воры", objective = "Принесите 30 челюстей койотов Нике Алый Шрам в Каргат.", description = "Ну и как тебе Бесплодные земли, <класс>? Жара, пылища, стаи всяких тварей? У тебя есть шанс прочувствовать все прелести этих земель еще лучше.\n\nCкальные койоты – наглые твари. Наглые настолько, что пробираются в Каргат и воруют наши припасы. Помоги нам избавиться от них!\n\nПринеси мне их челюсти, если ты соберешь достаточно много, я поверю, что ты и вправду знаешь Бесплодные земли.", progress = "Ты принес челюсти?", completion = "Впечатляющий набор челюстей, Томпсон. Теперь-то эти койоты поостерегутся подбираться к нашим припасам.\n\nОтлично! Койоты из Бесплодных земель – не такая уж легкая добыча. Теперь я уверена – ты сможешь тут выжить.", rewards = "Вы получите:\n\n"},
[1420] = {title = "Донесение Хелгруму", objective = "Отнесите донесение Ники Хелгруму Быстроногому в Каменор.", description = "Я написала новое донесение для Хелгрума из Каменора, отнеси его ему. \n\nИ если ты считаешь себя гонцом – не сбейся с пути и не попадись врагам!", progress = "Ты вернулся! Донесение при тебе?", completion = "Благодарю тебя, Томпсон. Из донесения Ники я понял, что Альянс озабочен собственными проблемами, и, может статься, что кое-какие враги у нас общие.", rewards = "Вы получите:\n\n"},
[1421] = {title = "Пропавший караван", objective = "Найдите похищенный из каравана сундук в Болотном пристанище, добудьте реактивы магов и принесите их дозорному Биггсу.", description = "Я был оглушен во время атаки Заблудших, но, прежде чем потерять сознание, я видел, как одну из наших повозок угоняли к Болотному пристанищу, поселению Заблудших на севере.\n\nВ этой повозке находился сундук с наиболее ценными реактивами, предназначающимися для магов Крепости Стражей Пустоты. <имя>, найди сундук, добудь эти реактивы и верни их мне.", progress = "Ты достал реактивы, Маладат?", completion = "Браво! С этими реактивами волшебники Крепости Стражей Пустоты смогут продолжить работу. Я не знаю, чем они там занимаются, знаю только, что это связано с Темным порталом в Бесплодных землях и напрямую касается безопасности всего Альянса.", rewards = "Вы получите:\n\n"},
[1422] = {title = "Угроза с моря", objective = "Поговорите с Катором на Болоте Печали.", description = "Пока я буду работть над твоим оружием, почему бы тебе не поговорить с Катором? Он, говорил, что ему нужна помощь с патрулированием побережья, и тебе бы лучше поддерживать боевую форму, а не напиваться с теми недоделками, что торчат в нашем лагере.", progress = nil, completion = "Помолчи немного, |3-6(Охотник). Даже сквозь глухой рокот моря  все еще слышно отвратительное бульканье, заменяющее рыболюдям речь", rewards = nil},
[1423] = {title = "Потерянные припасы", objective = "Принесите потерянные припасы интенданту Лунгерцу.", description = "Этот бочонок мал, зато прочен. Его швы заплиты желтым пахучим воском, а на торце выдавлены слова:\n\nИНТЕНДАНТ ЛУНГЕРЦ\n\nКРЕПОСТЬ СТРАЖЕЙ ПУСТОТЫ", progress = "У тебя что-то есть для меня?", completion = "Благодарю тебя, Димиллион. На пути из Темнолесья теряется так много провизии, Как хорошо, что кое-что удается вернуть.", rewards = "Вы получите:\n\nКоробка с припасами"},
[1424] = {title = "Озеро Слез", objective = "Соберите 10 артефактов Атал'ай для Фелзерула из Каменора.", description = "Вождь послал нас разузнать, что творится в Храме Атал'Хаккара.\n\nТролли Атал'ай – племя темных заклинателей, известных тем, что используют запретную магию. Можешь себе представить, как мы были поражены, когда узнали что храм затоплен.\n\nТеперь его сторожат зеленые драконы, которые утверждают, что они защитники Азерота.\n\nМы должны выяснить, что произошло. Исследуй окрестности озера Слез и собери артефакты Атал'ай. С их помощью я смогу собрать всю картину воедино.", progress = "Никто не знает, что темные обряды творились в Храме Атал'Хаккара. Но мы знаем, что там применялись мощные чары.\n\nИ мы должны выяснить все, что сможем, об этой магии. Возможно, заклинания Атал'ай будут полезны и Орде.\n\nКак только ты принесешь достаточно артефактов Атал'ай в окрестностях озера Слез, мы поймем, что замышляли тролли и что именно привело к такому исходу.", completion = "Твое усердие в происках артефактов Аталаи достойно похвалы, |3-6(Разбойник).", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1425] = {title = "Доставка груза", objective = "Доставьте груз в Крепость Стражей Пустоты интенданту Лунгерцу.", description = "Пока я чиню эту повозку, <имя>, выполни для меня еще одно, последнее задание. \n\nЯ собрал наиболее важные припасы, уцелевшие после набегов огров. Доставь их в Крепость Стражей Пустоты. Она выстроена в холмах, на севере Выжженных земель, для наблюдения за Темным порталом.\n\nДобраться туда можно по восточной дороге. Когда она разветвится, сверни на юг к Выжженным землям, а потом налево на следующей развилке. Не сходи с дороги,<имя>, и не теряй бдительности", progress = "У тебя ко мне какое-то дело?", completion = "Что? Груз из каравана Биггса? Мы думали, он пропал вместе с караваном.\n\nСпасибо, Маладат. Надеюсь там кристаллы Азоры, этот реактив, нам крайне необходим, а наш запас подходит к концу.", rewards = "Вы получите:\n\n"},
[1426] = {title = "Угроза с моря.", objective = "Убейте 10 болотных мурлоков, 10 болотных чернильщиков и 10 болотных трупоедов, затем вернитесь к Котору в Болото Печали.", description = "Мне не нравится ни море, ни твари, что лезут из его глубин. Море могущественно, но слепо, бесчувственно и жестоко. С какой радостью я истреблял бы этих рыболюдей сотнями, будь у меня возможность. Но мне принесет и некоторую радость зрелище их гибели от рук тех, кто выполняет волю Орды.\n\nОт твоих рук, <класс>. Скольких ты сможешь убить? Хочешь ли рискнуть и сразиться с сильнейшими из них?", progress = "Я терпелив. Терпелив и вечен как старая замшелая каменюга с Дренора. Рыболюди больше не протревожат наших границ, по крайней мере, пока я жив. Будь у меня армия, я бы очистил этот мир, как и прочие миры, от этих тварей. Мне противно даже говорить о них.", completion = "Море безбрежно и безжалостно, но ты запятнал его кровью его собственных порождений. Рыболюди знают, что такое боль. Их тупость заставит их сплотить ряды после того разгрома, который ты им учинил, и это хорошо.\n\nПусть из булькающие крики заглушают шум моря по ночам. А я буду улыбаться каждый раз как услышу, что кто-то из них замолк. \n\nВозвращайся ко мне, если вдруг захочется поубивать еще рыболюдей. Я с удовольствием тебя вознагражу за это.", rewards = "Вы получите:\n\n"},
[1427] = {title = "Угроза с моря.", objective = "Поговорите с Ток'Каром в Болоте Печали.", description = "Прежде чем пойти отдохнуть, пообщайся с Ток'Каром. Пока тебя не было, он, наверняка, закончил работу над обещанным тебе оружием. Было бы неплохо, если бы ты опробовал его на рыболюдях, когда созреешь...уж доставь мне удовольствие.", progress = nil, completion = "О! Томпсон, ты вернулся! Хорошо. Я как раз закончил партию оружия против мурлоков. За свежее мясо кусак и за то, что заставил Катара улыбаться, выбери себе одно.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПронзатель мурлоков Ток'КараСокрушитель мурлоков Ток'КараКолун мурлоков Ток'Кара\n\nВы также получите:\n\n"},
[1428] = {title = "Продолжающаяся угроза", objective = "Убейте 10 болотных чернильщиков, 10 болотных трупоедов и 10 болотных оракулов, затем вернитесь к Котору в Болоте Печали.", description = "Мне приятно видеть, что ненависть, которую ты испытываешь к рыболюдям, все растет, как и моя.\n\nНайди их на побережье, а потом когда битва будет закончена, возвращайся, и мы решим, как вознаградить тебя за усердие.", progress = "Только когда море и все его порождения, особенно эти отвратительные рыболюди упокоятся, я буду счастлив...", completion = "Отлично, |3-6(Охотник). Но мне мало этой крови. Пусть все рыболюди исчезнут с лица земли.", rewards = "Вы получите:\n\n"},
[1429] = {title = "Изгнанник Атал'ай", objective = "Принесите сверток с артефактами Атал'ай к изгнаннику Атал'ай во Внутренние земли.", description = "Пока ты <сражалась/сражался> с опасностями озера Слез, один из моих разведчиков вернулся со свитком из сушеного мяса с кровавыми письменами. Мне кажется это официальный приговор жрецу племени Атал'ай. Этот жрец был приговорен племенем к участи худшей, чем смерть, – он был изгнан на север во Внутренние земли, жить среди троллей племени Сухокожих. Я соберу эти артефакты, а тебе предстоит найти изгнанника и выяснить их назначение. После этого возвращайся ко мне.", progress = "Для того чтобы прийти сюда, нужна большая смелость. Ну или большая глупость...", completion = "Ты принес мне артефакты призыва Атал'ай? Я вижу, Джаммал'ан Пророк ведет своих последователей из Чертога Крови навстречу выбранному ими року. Интересно, вернулся ли Хаккар в свой храм? Встретили ли они свою судьбу?", rewards = "Вы получите:\n\n"},
[1430] = {title = "Свежее мясо", objective = "Принесите 10 ног чудовищного краба Дару на Болото Печали.", description = "Среди моих покупателей крайне высок спрос на сочное крабье мясо, особенно мясо чудовищного краба. \n\nЕсли ты планируешь направиться на побережье, то можешь еще и с выгодой прогуляться туда, если ты принесешь мне несколько крабьих ног, чтобы я переправил их в Оргриммар. \n\nПобережье находится к востоку отсюда, а крабы там просто кишат, что на берегу, что под водой.", progress = "У меня тут бочонок вина ожидает твоего возвращения, Томпсон, по мне товар прежде надо на вкус попробовать, а потом уж отсылать заказчику.", completion = "О! Замечательно, я жду не дождусь, когда попробую крабье мясо, должным образом приготовленное на открытом огне. Возьми с собой в дорогу малую толику, вкус просто несравненный!", rewards = "Вы получите:\n\nЖареные ножки королевского крабаКожаный пояс повара"},
[1431] = {title = "Отношения с Альянсом", objective = "Поговорите с Кельдрином в Оргриммаре.", description = "Слушай внимательно, <класс>. Мне нужно рассказать тебе кое-что, очень важное для нашего народа, но далеко не очевидное.\n\nМы – народ гордый, и война с людьми истощила даже терпение Тралла. Наш вождь мудр и рассудителен, и интересы нашего народа для него превыше всего. В то же время он тонкий дипломат. Он умеет обращаться с людьми.\n\nЕсли тебе это интересно, поговори с Кельдраном. Его лачуга стоит у западного входа в город.", progress = nil, completion = "Патанни, |3-6(Охотник)! Меня зовут Кельдран, я изучаю магию... и другие тайные искусства.\n\nДело, по поводу которого ты здесь, требует большей тонкости, чем те, которыми тебе приходилось заниматься раньше. Однако это не значит, что ты не можешь нам помочь.\n\nПожалуйста, устраивайся поудобнее. Я расскажу тебе, зачем вождю понадобилась моя... и твоя помощь.\n\nВсе начинается со впечатления, Томпсон. Какой себя видит Орда. Какими видят нас наши союзники. И, главное, какими нас видят наши враги.", rewards = "Вы получите:\n\n"},
[1432] = {title = "Отношения с Альянсом", objective = "Поговорите с Такатой Стальным Клинком в Пустошах.", description = "Альянс все расширяет свои владения в Калимдоре. Из-за этого может сложиться впечатление, что Орда вступает в союз с Пылающим Легионом. Вождь не может этого допустить. И я, с его благословения, буду отвечать за их изгнание.\n\nУ меня есть свои агенты в Пустошах, на Заставе Скитающихся Духов – это к северу от большого Кладбища кодо. Ступай на юг от Обугленной долины в Когтистых горах, и увидишь заставу. Когда прибудешь туда, разыщи Такату Стального Клинка.", progress = nil, completion = "Приветствую, |3-6(Чернокнижник)! У тебя есть вести из Оргриммара? Это хорошо.\n\nВ здешних краях все провоняло демонами – сильнее, чем кентавровым навозом. Конелюди вопят, что это их земли, но тут есть силы, с которыми им никак не справиться.\n\nПолучается, что мы вроде как помогаем кентаврам. Это мне не по нутру, но все это на благо Орды, так что я выполняю свой долг перед вождем, даже если ради этого приходится поддерживать чернокнижников.", rewards = "Вы получите:\n\n"},
[1433] = {title = "Отношения с Альянсом", objective = "Поговорите с Маурином Костоломом в Пустошах.", description = "Чернокнижники из клана Пылающего Клинка преданы злу до мозга костей. Души их осквернены, и единственный способ их остановить – это уничтожить.\n\nКельдрин отправил со мной Майрина, потому что он знает многое об Огненном Клинке и разбирается в уловках чернокнижников.\n\nОн борется с Клинком, а на мою долю остаются прочие козни демонов тут, в Пустошах.\n\nПоговори с Майрином, он посвятит тебя в свои планы.", progress = nil, completion = "Ах, да! Нам всегда пригодится помощь тех, кто предан вождю.\n\nМеня зовут Майрин. Я здесь по просьбе Кельдрина и нашего юного вождя, Тралла. Мальчику нужна помощь в борьбе против врагов, угрожающих его власти.\n\nПодойди-ка поближе, |3-6(Чернокнижник). Я изложу тебе свои планы касательно ликвидации этого гнойного нарыва, Пылающего Клинка.", rewards = "Вы получите:\n\n"},
[1434] = {title = "Опоганенные сатиры", objective = "Убейте 7 разбойников из племени Ярой Ненависти, 7 скверноподданных из племени  Ярой Ненависти, 7 предателей из племени Ярой Ненависти и 7 адских сатиров из племени Ярой Ненависти и вернуться к Такате Стальному Клинку в Пустоши.", description = "Влияние демонов возникает не на пустом месте. Нужен какой-то изъян, который позволяет злу войти в тебя.\n\nМожет быть, слабость духа, или излишнее стремление к власти, или жажда мести... Когда мы поддаемся боли, то позволяем злу взять над нами верх – такому злу, как сатиры.\n\nОни связаны с Пылающим Клинком, и Тралл хочет, чтобы их перебили. Разыщи их на северо-востоке и возвращайся ко мне, когда сумеешь их изгнать.", progress = "Спутник-таурен предупредил меня, что сатиры – не совсем то, чем кажутся. Он считает, что зло в них исказило их истинную природу. Но сам я такого не видел.\n\nЯ вижу только, как они безжалостно убивают слабых и оскверняют души тех, кто обращается к темным силам.\n\nИ я буду уничтожать их, пока вождь не поручит мне другое дело. Жалости к ним я не испытываю.", completion = "Молодец, |3-6(Охотник)! В тебе есть доблесть и преданность делу.\n\nКогда мы покончим с нашими делами в Пустошах, вождь непременно узнает о том, что ты помогал нам выполнять его волю.\n\nБлагодарю тебя!", rewards = "Вы получите:\n\n"},
[1435] = {title = "Сжигание душ", objective = "Верните пылающий самоцвет и 15 одушевленных самоцветов Маурину Костолому в Пустошах.", description = "Этих жалких тварей лучше всего предать смерти. Но, когда имеешь дело с теми, кто присягнул тьме, недостаточно просто убивать.\n\nВозьми этот самоцвет. Приведи его в действие, когда один из негодяев из клана Пылающего Клинка будет близок к смерти. Заклятие вытянет оскверненный дух из жертвы, и у тебя в руках окажется одушевленный самоцвет.\n\nПринеси мне эти одушевленные самоцветы, я с ними разберусь.\n\nСтупай же, и постарайся избегнуть смерти!", progress = "Я пытался сделать заклятие как можно более простым. Вытянуть душу твоей жертвы из умирающего тела должно быть детской игрой. Но не рассчитывай, что магия самоцвета сама убьет твоего врага. Активировать камень нужно только тогда, когда враг уже умирает, иначе ничего не получится.", completion = "А, ты вернулся с победой! Это хорошо. Давай сюда самоцветы, я их спрячу в надежное место…\n\nУ меня больше нет для тебя поручений, |3-6(Охотник). Отдохнешь – поговори с Такатой. Возможно, у него найдется для тебя дело – а может, он попросит тебя вернуться в Оргриммар и сообщить Кельдрану, как идут дела у нас в Пустошах.", rewards = "Вы получите:\n\n"},
[1436] = {title = "Отношения с Альянсом", objective = "Поговорите с Кельдраном в Оргриммаре.", description = "Дела идут на лад, <имя>. Быть может, если мы продолжим одерживать победы над демонами и их приспешниками, вождь разрешит нам вернуться домой еще до начала следующего сезона.\n\nВозвращайся к Кельдрану и расскажи, чего нам удалось добиться. Уверен, он вознаградит тебя за труды. Он будет горд, узнав, что вождь ценит его усилия.", progress = nil, completion = "Тебе удалось добиться успеха, да еще какого, Томпсон! Спасибо тебе.\n\nБлагодарю тебя за труды, за потраченное время и за то, что ты с пониманием отнесся к моей просьбе. Тралл стремится к миру между Ордой и Альянсом и потому заботится, чтобы мы выглядели достойно в глазах противника. Не следует провоцировать новые конфликты.\n\nЯ твой должник!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки капелланаНакидка скорохода\n\nВы также получите:\n\n"},
[1437] = {title = "Расследование Валарриэля", objective = "Отправляйтесь в Пустоши и попытайтесь отыскать повозку Тираниса и Далинды Малем.", description = "Приветствую тебя, <имя>. Я – Валарриэль. Я прибыл сюда, чтобы установить местопребывание двух пропавших торговцев из почтенной дарнасской семьи – дома Малем. Глава дома опасается самого худшего; я обязан выяснить все, что могу, о его пропавших детях. Правда, поиски Тираниса и Далинды я еще не начал, но надеюсь, что не задержусь здесь надолго.\n\nПоследнее, что мне довелось слышать о них – то, что несколько недель назад они миновали Когтистые горы.\n\nЕсли найдешь их повозку, прошу тебя, немедленно дай мне знать.", progress = nil, completion = "Судя по виду повозки, она подверглась воздействию как грубой силы, так и чар. Похоже, битва была короткой, и у одной из сторон не было никаких шансов – не было даже возможности отразить удар. Ни трупов, ни следов крови нигде не видно.\n\nКто бы ни напал на торговцев, действовал он весьма умело...", rewards = "Вы получите:\n\n"},
[1438] = {title = "Расследование Валарриэля", objective = "Найдите в Пустошах Далинду Малем.", description = "Постарайся разыскать Далинду и Тираниса. Начни поиски с той самой крепости, о которой ты <говорил/говорила>, а я пока что свяжусь с Дарнассом и изложу ситуацию. Что бы ты ни <обнаружил/обнаружила>, немедленно дай мне знать.\n\nЯ хотел еще кое-что сказать тебе, <имя>. Дело в том, что мое начальство весьма обеспокоено действиями Тираниса и причинами, которые заставили его отправиться сюда. Чрезвычайно важно найти Далинду и доставить ее домой. Целой и невредимой, по возможности. А вот Тираниса следовало бы сначала... проверить.", progress = nil, completion = "Благодарение Элуне, хоть кто-то пришел на помощь! Прошу тебя, |3-6(Чернокнижник), помоги мне. Орки Пылающего Клинка схватили меня и моего брата Тираниса и притащили сюда. Мне кажется, они собираются принести меня в жертву своим хозяевам-демонам!..\n\nЯ знала, что наше путешествие в Пустоши – это ошибка, но Тиранис так настаивал... в последнее время он особенно увлекся потаенными знаниями, хотя многим это не нравилось. Он решил отправиться в эти края именно после того, как узнал, что здесь появляются демоны...\n\nБоюсь, с ним случилось что-то скверное... очень скверное!", rewards = "Вы получите:\n\n"},
[1439] = {title = "Поиски Тираниса", objective = "Разыщите в безлюдье Тираниса Малема.", description = "Орки перебили нашу охрану и слуг, а потом приволокли нас сюда. Ты представить себе не можешь, что с ними сделали! Я думала, нас тоже прикончат на месте – но, как выяснилось, у орков были на нас другие планы.\n\nТиранис пытался поговорить с ними. Наверное, он думал, что его знания тайных искусств произведут на орков впечатление. Не знаю уж, почему.\n\nПрошу тебя, помоги! Я не могу уйти, пока не узнаю, что случилось с моим братом. Найди его – или хотя бы узнай о его судьбе. Умоляю!..", progress = "Боюсь, Тиранис попытается узнать тайны Пылающего Клинка и стать одним из них, если, конечно, они это позволят. Его всегда восхищала та власть, которую дает магия – и никогда он не думал о цене этой власти...\n\nНе знаю, как мне вернуться к семье, когда душа Тираниса подвергается такой опасности... Наш народ считает преступлением даже изучение подобной магии, а уж если Тиранис преобразится в одно из тех существ, с которыми му ведем войну...", completion = "Это ужасно!.. Но, полагаю, у тебя не было другого выхода. Если бы не ты, его все равно убили бы... Наверное, я должна поблагодарить тебя. Прости, если это звучит не слишком искренне: думаю, ты понимаешь, почему.\n\nТеперь, когда я знаю, какая судьба постигла моего несчастного брата, думаю, пора бежать отсюда. Если ты еще не передумал, я с радостью воспользуюсь твоей помощью и покину это страшное место.\n\nКогда будешь готов, скажи мне: мы тут же отправимся в путь.", rewards = "Вы получите:\n\n"},
[1440] = {title = "Возвращение к Валарриэлю", objective = "Выведите Далинду Малем из Крепости Громового Топора, а затем вернитесь в Пустоши к Валлариелю Истребителю Демонов.", description = "Итак, время пришло?.. Ценю твои усилия и благодарю тебя за все, что ты <сделал/сдалала> для меня и моей семьи. Что ж, если ты <готов/готова>, то и мне тут больше нечего делать. Отправимся в путь по первому твоему слову.", progress = nil, completion = "Благодарю тебя, Эфром. Далинда благополучно добралась до Высоты Найджела и чувствует себя гораздо лучше, чем я смел надеяться. Я даже не надеялся на столь благополучный исход! То, что ей удалось добраться сюда своими силами – добрый знак. Надеюсь, с тобой тоже все в порядке?..\n\nМне жаль, что Тиранис не вернулся; однако все, что с ним произошло, было плодом его собственных решений. Далинде придется с этим смириться – и, к тому же, разбираться с последствиями его действий, когда она вернется в Дарнасс.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПояс борцаПерчатки ПрозренияПлащ гарнизонаНарамник лунного сияния\n\nВы также получите:\n\n"},
[1442] = {title = "Поиск самоцвета Кора", objective = "Принесите самоцвет Кора Тандрису Ветропряду на Темных берегах.", description = "День добрый, <имя>. Чем могу помочь <идущему/идущей> путем Света?\n\nАх да, кузнец Стилвелл... давно не виделись. Я хорошо его помню, хотя давно о нем не слышал.\n\nОн никогда не казался мне злодеем, поэтому остается думать, что его стремление получить самоцвет Кора благородно.\n\nЕсли вам и правда нужен самоцвет, то придется направиться на северо-запад Ясеневого леса. Там, среди древних развалин, вы обнаружите Непроглядную Пучину. В их недрах таятся наги, и они до сих пор используют такие самоцветы. Не ходите туда в одиночку, <класс>.", progress = "Я с трудом поверил бы в чистые намерения того, кто ищет самоцвет Кора, не будь это искатель святого пути. Но таким, как вы, я доверяю даже больше, чем собственным сородичам. И я не стану судить о вашем ордене по деяниям ваших падших собратьев.", completion = "Действительно, это тот самый камень, который хочет получить Стилвелл, но, прежде чем я отдам его вам, надо очистить камень от скверны – мерзкие наги наполняют самоцветы силой, но своей, злобной силой.\n\nПусть Стилвелл знает, что мощь камня чиста, и он хорошо послужит в любом ритуале.\n\nЯ надеюсь, вы понимаете, что делаете, |3-6(Паладин), ибо в руках у вас не игрушка.", rewards = "Вы получите:\n\nОчищенный самоцвет Кора"},
[1443] = {title = "Облава", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1444] = {title = "Возвращение к Фел'зерулу", objective = "Вернитесь в Каменор к Фел'зерулу.", description = "Джаммал'ан Пророк приговорил меня к изгнанию из Храма Атал'Хаккара. Некогда я считал верховного жреца достойным главой храма.\n\nЕго непоколебимая вера в свое пророчество может привести к гибели Атал'ай, если уже не привела.\n\nНо стоило мне высказать мои сомнения, я был заклеймен как еретик и изгнан из храма.\n\nПринесенные тобой артефакты безопасны... Но если Джаммал'ан нашел нужный для ритуала призыва фетиш, то всему миру угрожает смертельная опасность.", progress = nil, completion = "Мы же виделись совсем недавно, |3-6(Воин). Надеюсь, твое путешествие было удачным. Что тебе поведал изгнанник-Атал'ай во внутренних землях ?", rewards = "Вы получите:\n\n"},
[1445] = {title = "Храм Атал'Хаккара", objective = "Соберите 20 фетишей Хаккара и принесите их  Фел'зерулу в Каменор.", description = "Так он говорил о пророчестве Джаммал'ана?\n\nДуховный вождь Атал'ай верит, что когда однажды, Хаккар вернется в Азерот из Пустоты, он дарует племени бессмертие.\n\nПо мне дураком надо быть, чтобы раньше срока вызывать светопреставление.\n\nНо ты говоришь, этот изгой упоминал о зачарованных амулетах? А вот это уже напрямую меня касается. Если среди них окажется ключ к ритуалу Атал'ай, который и привел ко всей этой заварухе, мы должны понять его тайную силу.\n\nОтправляйся в Храм и добудь амулеты!", progress = "Если фетиши Атал'ай способны призвать Хаккара и исполнить пророчество Джаммал'ана, мы должны заполучить их. Орда должна познать их силу!", completion = "Отважный |3-6(Воин), ты доказал, что являешься одним из лучших воинов Орды.\n\nТеперь-то мы разберемся с этими амулетами!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nТалисман-хранитель"},
[1446] = {title = "Джаммал'ан Пророк", objective = "Принесите изгнаннику Атал'ай из Внутренних земель голову Джаммал'ана.", description = "Мои товарищи из клана Сухокожих не любят, когда чужаки приходят к ним домой.\n\nЯ? А у меня и дома-то нет. Я жил в племени Атал'ай на Болоте Печали, но был изгнан оттуда.\n\nУ нашего духовного лидера по имени Джаммал'ан, было, как он сам говорил, \"видение\". Он решил, что если призвать бога Хаккара, то он дарует Атал'ай бессмертие.\n\nЯ настоятельно рекомендовал ему проявить осторожность, потому это это \"видение\" могло быть всего лишь манипуляцией, обманом!\n\nЯ хочу отомстить за свое изгнание. Принесите мне голову Джаммал'ана. Может быть, тогда мой народ освободится!", progress = "Теперь, когда Джаммал'ана нет, у меня появилась возможность вернуться к своему народу.\n\nС таким духовным лидером, как Джаммал'ан, племя Атал'ай было обречено.", completion = "Джаммал'ан безоговорочно верил своим бредовым видениям, и именно из-за них мой народ постигла такая страшная судьба.\n\nСпасибо, Хантор, что отомстил за мое изгнание. Я глубоко скорблю по своему народу. У меня нет дома, в который я мог бы вернуться.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПоножи Странника дождяШлем Изгнания\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1447] = {title = "Пропавший дипломат", objective = "Победите Дашеля Каменного Кулака в Штормграде.", description = "В Штормград приходили многие твои коллеги, <класс>, были среди них умные, были и круглые дураки, но подобных тебе нет, не было и не надо... \n\nЧего ты от меня хочешь?", progress = "Я вовсе не хотел тебя оскорбить, |3-6(Маг). Мы же друзья? Никаких проблем?", completion = "У тебя явно была причина прийти ко мне. Так в чем дело?", rewards = "Вы получите:\n\n"},
[1448] = {title = "В поисках Храма", objective = "Найдите Храм Атал'Хаккара и сообщите о его местонахождении Брохану Бочкопузу из Штормграда.", description = "Когда-то я был так же молод и полон сил, как вы, <класс>.\n\nТеперь я стар и не могу больше странствовать по миру. О, сколько я всего повидал!\n\nНо была одна загадка, которая до сих пор волнует меня. Во время моего последнего путешествия Лига Исследователей направила меня на поиски Храма Атал'Хаккара. Говорили, что он расположен где-то на Болоте Печали.\n\nПоскольку я уже был стар и немощен, то облетел эти земли на грифоне, но ничего не нашел.\n\nНе поможете ли старому дворфу? Может быть, вам повезет больше?", progress = "Я путешествовал по всему миру, от джунглей Азерота до снежных вершин Каз Модана.\n\nРаньше я никогда не попросил бы о помощи, но мои старые кости ноют и не позволяют пуститься в путь.\n\nЕдинственное, что позволит мне умереть со спокойной душой – знание о том, что я все же выполнил последнее задание Лиги Исследователей.\n\nЕсли вы поможете мне в поисках Храма Атал'Хаккара, то я буду вечно признателен вам, |3-6(Воин)!\n\nИсследуйте Болото Печали и возвращайтесь с рассказом о своих находках!", completion = "Храм Атал'Хаккара скрыт в глубинах озера Слез? И охраняется зелеными драконами?\n\nЭто чудесное открытие, |3-6(Жрец)! Очевидно, что-то ужасное случилось с этим храмом...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1449] = {title = "Во Внутренние земли", objective = "Поговорите с Верховным таном Фалстадом Громовым Молотом на Заоблачном Пике во Внутренних землях.", description = "Как я уже говорил, я пытался обнаружить храм, осматривая окрестности с высоты. Строго говоря, я был не один...\n\nЯ нанял грифона в небезызвестном питомнике на Заоблачном Пике во Внутренних землях. Птицей управлял один из лучших пилотов, но в воздухе он выпал из седла и свалился в болото...\n\nМоя старая дырявая память не сохранила его имени, но хозяин питомника должен понять, о ком идет речь.\n\nОтправляйтесь туда и найдите Фалстада Громового Молота.\n\nХорошо бы узнать, что случилось с тем пилотом...", progress = nil, completion = "Чего тебе, парень? Не видишь – и без тебя забот хватает? Чем болтаться тут без толку, лучше займись делом, |3-6(человек).\n\nЧто-что случилось... Тролли лезут из всех щелей, вот что! Ну говори уже, с чем пришел.", rewards = "Вы получите:\n\n"},
[1450] = {title = "Укротитель грифонов Разящий Коготь", objective = "Поговорите с укротителем грифонов Разящим Когтем в питомнике на Заоблачном Пике.", description = "Так, значит, ты <тот парень/та девчонка>, <которого/которую> наняли эти старые развалины из Лиги Исследователей?\n\nТак, слушай меня, <класс>. Я понятия не имею, кто у них там развлекался, летая над Азеротом! Я что, похож на Разящего Когтя? Похож?\n\nЕсли тебя интересуют грифоны, так поговори с укротителем! Если я увижу тебя без дела, то завалю по уши настоящей работой.\n\nДавай-давай, топай отсюда.", progress = nil, completion = "Да, конечно, я прекрасно помню о том, как послал одного из пилотов отвезти Брохана Бочкопуза.\n\nЛиге Исследователей всегда найдется место в моем сердце. Мой отец участвовал в экспедиции первой исследовательской команды, обнаружившей Ульдаман.\n\nС Броханом я отправил своего лучшего пилота по имени Рапсод Землекоп.\n\nАх, что за наездник это был! Ну, до поры...", rewards = "Вы получите:\n\n"},
[1451] = {title = "Рапсод Землекоп", objective = "Найдите Рапсода Землекопа во Внутренних землях.", description = "Рапсод всегда любил поддать лишнего. Не поймите меня неправильно: мы, дворфы этого питомника, все любим порой принять на грудь пинту-другую доброго эля.\n\nНо старина Землекоп любил это дело больше, чем грифоны любят летать – порой ужас что получалось. Никто не умел летать так, как Рапсод...\n\nАвария с этим вашим приятелем Броханом была только первым звоночком. После этого Землекоп покатился под горку, пришлось его уволить.\n\nГоворят, он открыл пивнушку к югу отсюда...", progress = nil, completion = "И-ик!\n\nЯ ж прям на вас смотрю, чего это вас так мотыляет из стороны в сторону? У меня аж морская болезнь начинается, ха-ха!\n\nИ-ик!\n\nО! Чувствуете, дорогуша? Земля так и ходит ходуном. Надо выпить!\n\nИк-к!", rewards = "Вы получите:\n\n"},
[1452] = {title = "Калимдорский коктейль", objective = "Принесите Рапсоду Землекопу 3 куска потрохов руха, 3 печени гроддока и 3 печени железномеха.", description = "Ик!\n\nВас послал этот старый пень Брохан? Как вспомню ту историю, так... И-ик!\n\nЧтобы рассказать, что там со мной случилось над этим болотом, понадобится выпить капельку для храбрости. Полный ужас, вы не поверите! Ик!\n\nВот что я скажу – притащите-ка мне индри... гринди... эн-гре-де-ен-ты для калимдорского коктейля, и вы обо всем услышите!\n\nЗначится, что нужно мне... Потроха руха из Танариса, печень гроддока, печень железномеха из Фераласа... Да.\n\nКалимдорский коктейль развяжет мне язык!", progress = "Пробовали болтливое пиво? Один из моих любимых сортов, надо сказать... Ик!\n\nНо если вы хотите, чтобы я вспомнил все детали того... ик... душераздирающего полета, потребуется что-то покрепче, и-ик, да...\n\nМне так представляется, что потрошка и печенки вы мне не торопитесь нести?\n\nИк!", completion = "Как я погляжу, у вас этих потрошков полные карманы! И какая беда принесла вас из Калимдора-то?\n\nСейчас подождите, я сделаю вытяжку, и тогда уж расскажу все, что вы пожелаете.\n\nИк!\n\nМеня дрожь пробирает, когда вспоминаю это клятое болото.\n\nИк!\n\nСейчас, сейчас, почти готово дело...", rewards = "Вы получите:\n\n"},
[1453] = {title = "Дела Поисковой корпорации в Пустошах", objective = "Поговорите с Крелдигом Унгором в Пустошах.", description = "Надо сделать одну работу в Пустошах, <имя>. Это жуткое место, опоганенное кентаврами и прочими грязными тварями. Но если ты ищешь честную работенку на неделю, то отправляйся туда, найди Крелдига Унгора и скажи, что это я тебя прислал.\n\nТы найдешь его на Высоте Найджела – он прячется в укромном лагере в горах северных Пустошей. Держись к востоку от выхода из Когтистых гор. Будь начеку, иначе можешь проскочить мимо лагеря.", progress = nil, completion = "Рад видеть, что у Горной корпорации нет недостатка ни в работе, ни в искателях приключений, готовых прийти на помощь.\n\nЯ – Крелдиг, Эфром. Это хорошо, что ты взялся помочь Горной корпорации. В эти дни все что-то ищут – кто фамильные драгоценности потерял, кто магический предмет, кто любимых. Да мало ли что. Но если за дело берется Горная корпорация, то по сходной цене она найдет все что угодно.", rewards = "Вы получите:\n\n"},
[1454] = {title = "Пожитки Карнитола", objective = "Найдите в Пустошах сундук Карнитола.", description = "Мое первое задание касается мага Карнитола – это какой-то тип из благородных, живет в Штормграде. Говорит, на его корабль напали морские великаны, и было это все у северо-западного берега Пустошей. Вместе со слугами этот тип попытался вытащить на берег один из самых ценных сундуков, но когда великаны набросились на них толпой, почел за благо телепортировать себя и своих слуг куда подальше, а сундук, натурально, бросил.\n\nТак вот, Карнитол хочет, чтобы мы нашли его сундук со всем содержимым и доставили ему в Штормград.", progress = nil, completion = "Похоже, сундук вовсе не пострадал от морской воды...\n\nОднако он взломан. Если тут и были магические охранные ловушки, то они явно успели сработать: края сундука обожжены.", rewards = "Вы получите:\n\n"},
[1455] = {title = "Пожитки Карнитола", objective = "Вернитесь в Пустоши к Крелдигу Унгору.", description = "Любопытно, кто – или что – все же открыло этот сундук?.. Судя по длинным глубоким царапинам на боках и крышке, это был не человек и не великан... Непохоже также, чтобы отметины оставил меч или кинжал.\n\nКроме всего прочего, сундук пуст. Абсолютно и непоправимо пуст.\n\nДелать нечего: остается только закрыть сундук и уйти. Крелдиг будет крайне разочарован.", progress = nil, completion = "Ну-с, Трансмастер, с возвращением на Высоту Найджела. Расскажи-ка, что тебе удалось обнаружить...\n\nКак?! Ничего?.. Ну, дорогуша, из ничего и не выйдет ничего: боюсь, за пустой сундук никто платить не станет.\n\nРасскажи-ка мне побольше об этих самых отметинах... царапинах, которые ты заметил.", rewards = "Вы получите:\n\n"},
[1456] = {title = "Пожитки Карнитола", objective = "Найдите сумку для книг, принадлежащую Карнитолу, и отнесите ее в Пустоши Крелдигу Унгору.", description = "Любопытно, очень любопытно...\n\nЧто ж, может, для нас еще не все потеряно.\n\nЕсли идти по тому же берегу на север, в сторону острова Раназьяр, там будут развалины построек ночных эльфов. Понятное дело, развалины эти теперь под водой; к тому же, там поселились наги из клана Скользящего Плавника. Сдается мне, эти наги замешаны в истории с сундуком.\n\nЕсли разведчики нагов решились зайти так далеко на юг, значит, по всей видимости, они очень сильны. Так что пожитки Карнитола, как мне кажется, надо поискать у сильнейших среди нагов: приливных охотников или морских ведьм.", progress = "Не знаю уж, кем там был этот Ниджел, но что в его лагере я провел самую паршивую ночь в своей жизни, это точно, уж можешь мне поверить, Wrestlecake.", completion = "Просто роскошно, Wrestlecake! Тебе удалось найти пожитки Карнитола!\n\nОт этих проклятущих нагов вечно одни проблемы. Я бы предпочел с Ордой воевать, чем с ними связываться, честно тебе говорю. Поверь, ты оказал Горной корпорации огромную услугу!", rewards = "Вы получите:\n\n"},
[1457] = {title = "Пожитки Карнитола", objective = "Отнесите сумку для книг, принадлежащую Карнитолу, в Стальгорн, и отдайте ее Ройттену Камнемолоту.", description = "Послушай, доставь-ка вещички Карнитола Ройттену в Стальгорн: он тебе неплохо заплатит.\n\nТолько ты с ним поосторожнее, не то ты ему понравишься сверх всякой меры и он решит тебя взять к нам, как это называется, на полную ставку!\n\nНет, я ничего не говорю, <имя>; ты молодчина!\n\nТолько будь поосторожнее на обратном пути и поторапливайся: Карнитол – не самый терпеливый тип... зато платит от души!", progress = "Слушай, Кинкс, дела идут полным ходом, деньги крутятся, так что мне не до болтовни. Оно, конечно, если у тебя что-то есть к Горной корпорации, тогда отойдем, поговорим, а если нет, то лучше пудри мозги кому-нибудь из моих подчиненных – они тебе ответят на все вопросы, только оставь меня в покое!", completion = "Ах да, Карнитол... Точно, было у него такое дело в Пустошах. Великолепно!\n\nИтак, сундук уничтожен, но все его содержимое тут, да? Что ж, поверим ему на слово, поверим... Тут какое дело? Если ко мне возникнут какие-то претензии, я всегда могу послать жалобщиков куда подальше. Они же от нас чего хотят? – правильно, чтобы мы нашли их вещи. Мы и находим, а уж сохранность и внешний вид находок – это второй вопрос.\n\nПрекрасная работа, Кинкс! Давай-ка посмотрим, что ты на этом заработал...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги беспокойстваНаплечье цвета крови\n\nВы также получите:\n\n"},
[1458] = {title = "Реактивы для Поисковой корпорации", objective = "Принесите 10 когтей и 10 рогов сатиров Ярой Ненависти в Пустоши Крелдигу Унгору.", description = "Одна из моих задач здесь – подбор реактивов для Скрытного Кудесника, гномского мага из Караноса. Ройттен-то, небось, думает, что это – раз плюнуть, коли уж мы все равно тут торчим, а дело-то не из простых, да и рук не хватает...\n\nПервые несколько реактивов добыть не так уж сложно, а я готов заплатить неплохие деньги тому, кто мне поможет.\n\nМне нужны рога и когти сатиров Ярой Ненависти: они тут недалеко обитают, на востоке. Ты мне их сначала принеси, а потом мы займемся остальным списком.", progress = "Отвратные они твари, эти сатиры, точно? Поговаривают, что они как-то связаны с ночными эльфами, но мне в это как-то не слишком верится.\n\nСдается мне, эти слухи пошли из-за того, что один эльф несколько лет назад втянул их в войну. После этой войны весь мир поменялся. Опаснее стал, да и страшнее тоже...", completion = "Отлично, Wrestlecake, отлично! Не то чтобы я был уверен в качестве этой дряни, но ежели этому Скрытному типу нужны были какие-то особые рога и когти, надо было мне об этом раньше сказать, а теперь уж пусть забирает, что дают, я так себе думаю.\n\nНу что, посмотрим, что там дальше по списку?", rewards = "Вы получите:\n\n"},
[1459] = {title = "Реактивы для Поисковой корпорации", objective = "Принесите 7 фиалов скорпионьего яда и 3 шкуры старого кодо в Пустоши Крелдигу Унгору.", description = "А следующее по списку Скрытного Кудесника у нас... Погоди-ка... А, да, вот оно.\n\nНу, не то чтобы это было большой редкостью, но тут наш дорогой друг сподобился дать подобные разъяснения. Ему понадобился яд скорпиона и шкура кодо. А вот тут вот, меленькими буковками, видишь? – тут написано, что яд-то может быть от любого скорпиона, а шкура ему нужна непременно со старого кодо, но ни в коем случае не с умирающего или дряхлого.\n\nОх уж эти мне маги... вечно у них какие-то заскоки.", progress = "Ты уж извини, что я тебе не сказал, где искать скорпионов и кодо. Я здешние места не особо знаю, да и времени у меня не было все тут обследовать...", completion = "Твоя помощь просто неоценима, Ыгрок. Благодаря тебе я проведу в этих проклятущих Пустошах вдвое меньше времени. Еще немного, и можно будет отправиться в Стальгорн: отдых мне не помешает...\n\nКогда мы покончим с этим списком и я вернусь домой, непременно загляни ко мне: я тебе поставлю пару пинт доброго эля!\n\nА пока-что давай займемся остальными реактивами, договорились?", rewards = "Вы получите:\n\n"},
[1462] = {title = "Сапта земли", objective = "Попросите у провидицы Воронье Перо еще одну сапту земли.", description = nil, progress = nil, completion = "Возьми это и помни – этот предмет священный.", rewards = "Вы получите:\n\nСапта земли"},
[1463] = {title = "Сапта земли", objective = "Поговорите с Канагой заклинателем земли, чтобы получить еще один сапту земли.", description = nil, progress = nil, completion = "Я даю тебе ее со спокойной душой. Твоя доблесть мне известна. Однако же впредь будь поосторожнее!", rewards = "Вы получите:\n\nСапта земли"},
[1464] = {title = "Сапта огня", objective = "Поговорите с Телфом Джоламом, чтобы получить еще одну сапту огня.", description = nil, progress = nil, completion = "Пусть огонь неугасимо пылает в твоем сердце, Шаматруль!\n\nСтихии ждут тебя.", rewards = "Вы получите:\n\nСапта огня"},
[1465] = {title = "Расследование Валарриэля", objective = "Принесите подвеску Малемов в Пустоши Валарриелю Истребителю Демонов.", description = "При осмотре повозки удается найти подвеску, а также следы, ведущие на юг – туда, где над фортом поднимается легкий дымок, заставляющий думать не о пожаре и горящих домах, а об очаге или костре, на котором готовится пища. Должно быть, если Малемы еще живы, их увели в том направлении.\n\nВаларриэль непременно должен увидеть подвеску – и об этих признаах жизни на юге ему тоже нужно рассказать...", progress = nil, completion = "Я в ярости! Подумать только, какой провал!..\n\nИ ведь этих двоих предупреждали, что здесь крайне опасно. А теперь они оба пропали... И хорошо, если живы.\n\nГоворишь, ты видел следы, ведущие к ближнему форту?.. Что ж, возможно, у нас все еще есть шанс...\n\nМестные жители говорят, что в этой крепости обосновались орки Пылающего Клинка – те, что служат демонам. Я вовсе не хочу сказать, что вся Орда придерживается подобных верований – но это сейчас неважно, а важно то, что эти орки непременно убьют тебя, если увидят, что ты пытаешься что-то разведать неподалеку от их форта.", rewards = "Вы получите:\n\n"},
[1466] = {title = "Реактивы для Поисковой корпорации", objective = "Принесите 10 мозгов гончих Скверны, 10 крыльев пустоты и 10 фиалов крови Тюремщика Судеб в Пустоши Крелдигу Унгору.", description = "Это последнее в списке. Врать не буду, задание не из приятных; к тому же оно наверняка займет у тебя больше времени, чем предыдущие.\n\nНу ладно, хватит болтать. Вот гляди: Скрытный Кудесник тут пишет, что ему нужны мозги любых пожирателей маны или охотников на магов... крылья Пустоты ему еще нужны, от любой Девы, Сестры или Колдуньи Пустоты... и еще... кровь Тюремщика Судеб ему еще нужна, от лорда или капитана – не важно.\n\nПростенькое такое заданьице, точно? Слушай, я тебе вот что скажу: если ты откажешься, я пойму.", progress = "Я даже и представить себе не мог, что все эти демонические твари обитают тут, в Пустошах. Мне все как-то казалось, что после ухода эльфов тут кентавры живут...\n\nИнтересно, как здесь эти твари оказались и чего им тут надо?", completion = "Честно говоря, не думал, что тебе это удастся. Ты – это что-то, Маладат! Надо же, и демонов покромсал для чокнутого мага, и живым вернулся! Вот это класс!\n\nКак вернусь в Стальгорн, лично расскажу о тебе старине Ройттену!", rewards = "Вы получите:\n\n"},
[1467] = {title = "Реактивы для Поисковой корпорации", objective = "Доставьте коробку Скрытного Кудесника в Стальгорн Ройттену Камнемолоту.", description = "Хочешь плату получить? Так за этим тебе придется вернуться в Стальгорн и потолковать со стариной Ройттеном. Думаю, он будет рад отделаться, наконец, от коробки Кудесника. Отдашь ему вот это, и получишь свою награду. \n\nДа ты не беспокойся: когда я вернусь, то всяко замолвлю за тебя словечко. Мне тоже не больно-то хочется торчать в этих самых Пустошах.", progress = "Рад тебя видеть, Маладат. Бизнес процветает, Молоты звенят по наковальням, меха раздувают огонь, а моя жена готовит мне пирог на десерт... Жизнь прекрасна, не так ли?", completion = "О, а вот и посылка для Скрытного Кудесника, прямиком из Пустошей! Прекрасно! Ценю твою работу, |3-6(Воин): к тому же, тебе удалось уложиться в срок. Приятно было с тобой работать.\n\nВот тут твоя плата. И пусть все знают, что Горная корпорация всегда оплачивает услуги своих работников по высшему разряду!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗолотистые наручиРукавицы огня бури\n\nВы также получите:\n\n"},
[1468] = {title = "Детская неделя", objective = "Чтобы поговорить с ребенком, за которым вы будете присматривать, используйте сиротский свисток.\n\nПрилагается предмет: \n", description = "Можешь ли ты помочь нам позаботиться о сиротах? <Благословен будь, друг/Благословенна будь> дева;: помощь твоя во время Детской недели неоценима.\n\nВозьми этот свисток. Ты сможешь использовать его только во время Детской недели. Свистни в него – и сможешь поговорить с ребенком, о котором будешь заботиться. Свистни еще раз – ребенок уйдет.\n\nВсе очень просто, <имя>: используй свисток и заботься о ребенке. Любой сирота будет рад встрече с тобой.", progress = nil, completion = "Э... ну, привет. Меня зовут Рандис, ты будешь за мной присматривать, да? А ты – искатель приключений? Мама и папа тоже были такими. Значит, ты меня поймешь!\n\nДавай играть! Воспитатели мне сказали, что ты мне будешь вроде старшего брата. Это здорово! Если бы у меня были настоящие братишки и сестренки...", rewards = nil},
[1469] = {title = "Рапсодия о болоте", objective = "Отнесите фрагмент таблички Атал'ай Брохану Бочкопузу в Штормград.", description = "Перед тем как лететь, я выпил полный бочонок портера. Ик!\n\nЧто это был за полет! Я несся по воздуху, а Брохан болтался за моей спиной, но храма мы не видели. Ик!\n\nИ не нашли бы мы его никогда, если бы я не нагрузился так, что сверзился из седла. Упал в воду, пошел прямо на дно. А тут, откуда ни возьмись, целое стадо отвратительных троллей! Конечно, я постарался убраться оттуда как можно быстрее. Еле выбрался, однако прихватил с собой вот этот сувенир. Держите, отнесете его Брохану и расскажете, что храм этот его – там, под водой. Ик!", progress = "Наконец-то вы вернулись, Пластырь! Давненько мы не виделись, я было подумал, что вы забыли о моем поручении...\n\nВы нашли этого хитроумного всадника? Он что-нибудь сказал?", completion = "Рапсод Землекоп! Точно! Как я мог забыть такое имя?\n\nТак он все это время знал о том, что храм затонул? Что ж, это точно сэкономит вам время.\n\nНо предмет, сделанный Атал'ай... Вот это находка!", rewards = "Вы получите:\n\n"},
[1470] = {title = "Приоткрывая завесу", objective = "Принесите Вении Мартанд 3 черепа скелетов-костетрясов.", description = "Приветствую тебя, дитя. Вижу, ты только вступаешь на пути чернокнижия, мощь его не дается тебе пока. Я чувствую, как велико твое желание учиться. \n\nДа, ты будешь учиться. \n\nВ невежестве нет силы. Знание – вот залог нашего могущества. Знания позволяют нам контролировать хаотическую магию и тварей Бездны, склоняя их к своей воле. \n\nЯ покажу тебе, как подчинять себе слугу, но сначала принеси мне три черепа скелетов-костетрясов, бродящих близ покинутой кузницы.", progress = "Твои силы пока малы, но мне кажется, что ты уже начинаешь ощущать скрытые возможности. \n\nДаже мертвый может почувствовать себя живым, когда эта сила циркулирует в нас.", completion = "Хотя ты еще не прошел испытаний и находишься в самом начале ученичества, ты доказал, что силы у тебя достаточно, чтобы суметь призвать беса и подчинить его своей воле. Пусть тебя не обманывают его небольшие размеры. Физической силы ему не хватает, зато хватит магического могущества и разума, чтобы хорошо служить тебе.\n\nСлушай меня внимательно, Кзар, потому что повторять я не буду, и тогда придется все осваивать самостоятельно.", rewards = "Вы изучите:\n\nПризыв беса\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание беса\n\nВы также получите:\n\n"},
[1471] = {title = "Оковы", objective = "При помощи Рун Призыва вызовите и подчините себе демона Бездны, а потом верните Руны Призыва Карендину Халгару в Квартале Магов Подгорода.", description = "Ты наверняка уже <видел/видела> круг призыва. Только в его пределы ты можешь вызвать демона Бездны.\n\nПри помощи этих рун ты вызовешь его, а потом подчинишь себе силой оружия и магии.\n\nПодчиненный демон Бездны будет неразрывно связан с тобой. Выполнив задание, возвращайся ко мне, я научу тебя заклинанию призыва. Ты сможешь пользоваться им, когда захочешь.", progress = "Надеюсь, ты преуспеешь в своих начинаниях, Эккетзул. Впрочем, если тебе не удастся задуманное, мое недовольство покажется тебе сущим пустяком.", completion = "Великолепная работа, Эккетзул. Теперь я научу тебя заклинанию, позволяющему призвать демона Бездны.\n\nТы сможешь обратить силу, которую недавно испытал на себе, против своих врагов.", rewards = "Вы изучите:\n\nПризыв демона Бездны\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание демона Бездны\n\nВы также получите:\n\n"},
[1472] = {title = "Пожирательница душ", objective = "Поговорите с Годриком Фарсаном в Храме Проклятых.", description = "Сайаады – пожиратели душ, разбивающие сердца и вводящие в искушение. Существа, исполненные зла и изощренной хитрости.\n\nСказания из уст что праведников, что грешников говорят одно: их женщин называют суккубами, а мужчин – инкубами.\n\nПросто так их в наш мир не выманишь. Сайаад не сможет устоять перед сердцами добрых и любящих смертных. Когда он явится в Азерот, можно побороть его и подчинить себе.\n\nСтупай в храм и поговори с моим помощником Годриком Фарсаном. Он поможет тебе подобрать приманку.", progress = nil, completion = "Тебя прислал Карендин? Говоришь, ты Вий?\n\nНе думай, что я просто беспомощный слепец. Я вижу истинную суть вещей с недоступной прежде ясностью, и то, что было моим проклятьем, обернулось благословением.", rewards = "Вы получите:\n\n"},
[1473] = {title = "Создание Бездны", objective = "Найдите гримуар Эгалина и отнесите его Карендину Халгару в Храм Проклятых.", description = "Похоже, ты <готов/готова> призвать демона Бездны.\n\nЭти твари появляются из Круговерти Пустоты, лежащей за пределами мира. Если ты не сможешь подчинить себе вызванного демона, он разорвет тебя на части.\n\nПервого демона Бездны сумел вызвать Эгалин, и это подробно описано в его гримуаре.\n\nК сожалению, агент Алого ордена похитил гримуар и спрятал его в башне к западу отсюда. Принеси книгу, и я наделю тебя знаниями.", progress = "Эгалин был моим учителем. Он повелевал вызванным им демоном Бездны без малейших затруднений.\n\nКогда пришел мой черед подчинить себе эту тварь, я был слишком самоуверенным. Не обманывайся своим мнимым могуществом, Эккетзул, с этой тварью ни на секунду нельзя терять бдительности.", completion = "А, великолепно. Вероятно, Перрин не догадывался, какие знания скрывает в себе этот фолиант.\n\nМы больше не допустим хищения книги. Смотри: вот схема заклинания, объясняющая, как следует направлять энергию.", rewards = "Вы получите:\n\n"},
[1474] = {title = "Оковы", objective = "При помощи Чистых Сердец призовите и подчините себе суккуба, а потом верните Чистые Сердца Карендину Халгару в Квартале Магов Подгорода.", description = "При помощи этих сердец наложи заклинание на круг призыва, чтобы открыть дверь в наш мир для суккуба. Твои силы возросли, и они понадобятся тебе, чтобы одолеть демоницу.\n\nОстерегайся ее чар, <имя>, даже сила воли может не защитить от них. Если ты победишь, суккуб вернется в Бездну, а я научу тебя заклинанию, которое позволит тебе вызывать ее в любой момент.", progress = "Суккуб – один из самых опасных обитателей Бездны, поскольку быстро подчиняет себе слабых духом.\n\nНикогда не забывай об этом.", completion = "И снова ты справился с заданием. Давно мне не встречались чернокнижники с такими задатками. Не сомневайся, я буду следить за твоими успехами и помогу тебе подготовиться к ожидающим тебя испытаниям.\n\nА теперь я хочу научить тебя заклинанию призва личного суккуба.", rewards = "Вы изучите:\n\nПризыв суккуба\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание суккуба\n\nВы также получите:\n\nМалая сума душ"},
[1475] = {title = "В Храме Атал'Хаккара", objective = "Соберите 10 табличек Атал'ай для Брохана Бочкопуза из Штормграда.", description = "Храм Атал'Хаккара посвящен древнему божеству Хаккару Свежевателю Душ. Храм охраняет злобное племя троллей Атал'ай, и он, если верить слухам, неприступен.\n\nТеперь, когда он затонул, добывать в нем артефакты стало еще сложнее. Но это именно то, о чем я вас прошу, <имя>.\n\nПомогите мне собрать целые таблички Атал'ай. Принесите их мне, и я вернусь в Лигу Исследователей героем. Вместе мы добьемся успеха!", progress = "Поскольку для меня наступили не лучшие времена, я обращаюсь к вам, Кавару. Если б только мои старые кости позволяли мне преодолеть Болото Печали и добраться до затопленного храма, я бы непременно сражался рядом с вами!\n\nВ былые времена гордость не позволила бы мне просить вас о помощи, но ныне я слишком стар, чтобы справиться сам. Прошу, помогите мне! Я хочу уйти в отставку, выполнив последнее поручение Лиги Исследователей.", completion = "Таблички Атал'ай! Благодарю, Кавару!\n\nКогда я доставлю их в Лигу Исследователей, наши имена войдут в историю. Вы помогли старому дворфу выполнить его последнее задание, и я бесконечно признателен вам за это!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nТалисман-хранитель"},
[1476] = {title = "Чистые сердца", objective = "Принесите сердца Далина Искусника и Кормы Виллард Карендину Халгару в Храм Проклятых.", description = "Чтобы поймать суккуба, нужно чистое сердце. Но разве остались среди смертных непорочные сердца?\n\nПосле долгих поисков и расспросов мне удалось найти только двоих.\n\nПервый из них – Далин Искусник. Он посвятил свою жизнь заботе о лордеронских беженцах, которых отказалась принять родня у Стены Седогрива.\n\nВторая – Корма Виллард. Она скорбит об утраченной дружбе и бродит по Болотине в поисках подруги.\n\nПринеси их сердца Карендину. Но сначала я покажу тебе твои жертвы.", progress = "Я приятно удивлен тем, как быстро ты справляешься с заданиями, Мидари. Принеси мне сердца, и я преисполнюсь еще большего уважения.", completion = "А с виду доброе сердце ничем не отличается от любого другого, да?\n\nМожет быть, мы просто... по-другому смотрим на мир. Но эти сердца прекрасно подойдут. Не сомневаюсь, их чистота привлечет суккуба.", rewards = "Вы получите:\n\n"},
[1477] = {title = "Важные поставки", objective = "Поговорите с начальником стражи Соригелом.", description = "Наши маги проводят исследования в Крепости Стражей Пустоты, в Выжженных землях – исследования, жизненно важные для понимания Темного портала. Они почти постоянно требуют поставок, однако доставлять что бы то ни было в крепость крайне сложно.\n\nМы просим твоей помощи в обеспечении прибытия поставок в Крепость Стражей Пустоты. Сдай рапорт начальнику стражи Соригелу в Темнолесье и сделай то, о чем он попросит. Но это задание приведет тебя во враждебные земли, <имя>. Приготовься к любым опасностям.", progress = nil, completion = "Тебя послал Андромах? Очень хорошо. У меня для тебя важное задание...", rewards = "Вы получите:\n\n"},
[1478] = {title = "Призыв Халгара", objective = "Поговорите с Карендином Халгаром в Подгороде.", description = "А, <имя>! Я только что получил новости от Карендина Халгара – он хочет поговорить с вами насчет дальнейшего обучения.\n\nМожете гордиться собой! Не каждый день мастер Халгар решает самолично проинструктировать юного чернокнижника.\n\nЕго можно найти в Квартале Магов Подгорода, возле Храма Проклятых.", progress = nil, completion = "Хорошо, я вижу, Агерон нашел вас, Тухловатый. Давайте не будем тратить время на болтовню и церемонии, а сразу же перейдем к вашему обучению. Вам еще очень много надо узнать.", rewards = "Вы получите:\n\n"},
[1479] = {title = "Купина Вечности", objective = "Отведите сироту к банку Дарнасса. Банк находится в дупле дерева, которое называется Купина Вечности.", description = "Я слышал, что Ночные эльфы устроили банк прямо внутри дерева, которое похоже на медведя! Круто! Ночные эльфы очень милые, а как они любят природу! Но медведи это совсем здорово!\n\nСводи меня посмотреть на древо-медведя в Дарнасс! Пожалуйста! Мы можем доплыть дотуда на корабле, много времени это не займет. Пожалуйста, пожалуйста, пожалуйста!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1480] = {title = "Осквернитель душ", objective = "Отнесите рваную демонскую кожу Майрину Костолому в Пустоши.", description = "Эта рваная кожа пахнет гнилью, и она на удивление мягкая и гибкая для такого сухого и хрупкого на вид материала.\n\nЕсли ее развернуть, на ней видны красные письмена на непонятном наречии. А внизу – очень отчетливый отдельный символ, должно быть, подпись.\n\nМожет быть, Майрин сумеет объяснить, что это такое?", progress = "Чернокнижники Пылающего Клинка начинают понимать, насколько они бессильны. Их магия не внушает ничего, кроме презрения.\n\nВсей своей силой они обязаны тем, кому служат, а вовсе не истинному знанию и пониманию законов магии.", completion = "Да, Томпсон, это действительно чужой язык, и весьма древний. Он отчасти напоминает эредан, но отличия несомненны. Если не ошибаюсь, это нечто вроде договора... Да, вот этот символ – подпись демона: лорд Азреток.", rewards = "Вы получите:\n\n"},
[1481] = {title = "Осквернитель душ", objective = "Принесите скальп тенелова Маурину Костолому в Пустошах.", description = "Пожалуй, я сумею отыскать этого повелителя демонов, если найду нужные реагенты.\n\nОднако, если он действительно так могуществен, мне понадобятся предметы, собранные со смертельно опасных тварей...\n\nПрежде всего мне придется снять заклятия, которые защищают его от соглядатаев. Для этого нужен скальп сатира, но не первого попавшегося, а тенелова из племени Ярой Ненависти.\n\nИщи их в древних развалинах на северо-востоке Пустошей.", progress = "Смотри, |3-6(Друид), принеси именно тот скальп, что надо! Мы оба погибнем, если используем неправильные реагенты. Повелитель демонов наверняка защищен заклинаниями, которые убивают непрошеных соглядатаев!\n\nДовольно с меня былых мучений.", completion = "Что, |3-6(Друид), тенеловы тебя не убили? Неплохо, очень неплохо.\n\nДа, этот скальп мне подходит. Пока тебя не было, мне удалось собрать остальные необходимые реагенты.\n\nЯ почти готов. Мне необходима только точка приложения заклинания – тот предмет, в котором мы увидим повелителя демонов и место, где он находится.", rewards = "Вы получите:\n\n"},
[1482] = {title = "Осквернитель душ", objective = "Принесите кристалл оракула Маурину Костолому в Пустоши.", description = "Кристалл оракула нам подойдет. Их делают наги для своих оракулов.\n\nК северо-западу отсюда, на побережье, есть обширный коралловый риф, где поселились наги. Там можно найти и оракулов. Но Скользящий Плавник смертельно опасен и встретит тебя отнюдь не с распростертыми объятиями. Так что смотри, осторожнее, и постарайся убраться оттуда побыстрее.\n\nА когда вернешься, мы попробуем отыскать этого лорда Азретока.", progress = "Мне нужен кристалл оракула, |3-6(Чернокнижник). Если мы найдем и уничтожим этого лорда Азретока, вождь будет весьма признателен нам обоим. Так что давай работать вместе, чтобы быстрее управиться с этим делом и добиться расположения вождя.", completion = "Драгоценный кристалл оракула! Безупречный... великолепный…\n\nЧто ж, начнем немедленно. Нам следует отыскать этого повелителя демонов.\n\nОтступи на шаг, |3-6(Чернокнижник), и давай посмотрим, как выглядит Азреток и где его искать.", rewards = "Вы получите:\n\n"},
[1483] = {title = "Зиз Физзикс", objective = "Поговорите с Зизом Физзиксом на Утесе Ветрорезов.", description = "Торговая Компания переманила лучшие гоблинские умы, но порой у нас появляется возможность вернуть свое. \n\nНекоторое время назад подразделение Торговой Компании в Когтистых горах приняло на работу Геренцо Терминатрикса – гнома! Это так ошарашило другого инженера, Зиза Физзикса, что он умолял меня найти ему новую работу в Союзе ремонтников. Я дал ему несколько заданий, но ему может понадобиться помощь.\n\nНе навестишь его? Он живет у западного края Утеса Ветрорезов.", progress = nil, completion = "Я думал, что начальство Торговой Компании – настоящие тираны, но потом я познакомился с Пароклапаном, он хуже их всех!\n\nХа! И все же это лучше, чем сидеть без работы... Или, хуже того, работать с этим Геренцо. Если ты хочешь мне помочь, дело для тебя найдется.", rewards = "Вы получите:\n\n"},
[1484] = {title = "Осквернитель душ", objective = "Поговорите с Такатой Стальным Клинком в Пустошах.", description = "Это существо куда опаснее, чем мне казалось! Неудивительно, что Таката сомневается, что мне удастся его одолеть. Он будет оскорблен, если не сообщить ему о том, что случилось.\n\nПоговори с мечником, скажи, что хочешь убить демона, если он разрешит, но особо не настаивай. Пусть думает, будто это его собственная идея.", progress = nil, completion = "Да, я видел, что только что произошло между Майрином и повелителем демонов! Похоже, это существо, даже в видении, обладает куда большим могуществом, чем мой соратник-чернокнижник. Сумеет ли он одолеть этого монстра? Лучше бы я занялся этим сам... Но вождю я нужен здесь. Я опозорю свой клан, если оставлю свои здешние обязанности и отправлюсь добывать себе славу.", rewards = "Вы получите:\n\n"},
[1485] = {title = "Злобные фамильяры", objective = "Принесите Рузану 6 голов злобных фамильяров.", description = "Чернокнижники, бывшие здесь до нас, внушили Орде недоверие к нам. Нас терпят, но недолюбливают.\n\nОднако это не заставило чернокнижников сплотиться. Многие предпочитают жить и заниматься магией в уединении. Я не буду принуждать тебя избрать тот или иной путь, а всего лишь помогу тебе сделать очередной шаг.\n\nНо прежде чем я научу тебя искусству призывания, принеси мне шесть голов злолбных фамильяров из той пещеры на северо-востоке.", progress = "Важно уметь контролировать существ, которых ты будешь призывать с помощью магии. Интересующихся ремеслом чернокнижников и так мало, поэтому я не позволю тебе рисковать жизнью прежде, чем увижу, что ты к этому готов.", completion = "Во время обучения ты научишься вызывать самых разных существ. Все они по-своему полезны, даже если на первый взгляд это не очевидно.\n\nПусть малый рост беса тебя не смущает. Ты уже знаешь, как опасны они бывают.", rewards = "Вы изучите:\n\nПризыв беса\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание беса\n\nВы также получите:\n\n"},
[1486] = {title = "Шкуры загадочных существ", objective = "Принесите 20 искаженных шкур Налпаку в Пещерах Стенаний.", description = "Пока Наралекс погружался в свои кошмары все глубже, из-под Степей в Пещеры Стенаний пришли какие-то странные животные.\n\nЭти искаженные существа наделены странными, потусторонними силами. В то время как зло в их природе, я уверен, что из их существования можно извлечь некоторую пользу здесь в Калимдоре. Я верю, что из их кожи наши кожевники смастерят что-нибудь стоящее.\n\nЕсли эта задача тебе по вкусу, отправляйся в пещеры и принеси мне немного искаженных шкур.", progress = "Я весьма заинтересован в том, чтобы исследовать шкуры этих тварей, наводнивших Пещеры Стенаний. Как успехи, |3-6(Воин)?", completion = "Твои услуги не останутся незамеченными. Протеже.\n\nСпасибо тебе за твою неоценимую помощь.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПоножи из искаженной чешуиСума из искаженной шкуры\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1487] = {title = "Искоренение Скверны", objective = "Убейте для Эбру 7 загадочных опустошителей, 7 загадочных гадюк, 7 загадочных шаркунов и 7 загадочных страхозубов.", description = "Цели у Наралекса были самые благие.\n\nНаш лидер стремился впасть в Изумрудный сон, и  вновь превратить эти выжженные земли в тот пышный лес, которым они когда-то являлись. Но что-то пошло не так.\n\nМечта Наралекса превратилась в кошмар, и порченые твари заселили пещеры.\n\nВ то время как некоторые приспешники Наралекса стремятся пробудить нашего мастера, я забочусь о том, чтобы избавить эти пещеры от заполонивших их тварей.\n\nОтправляйся туда, <имя>. и уничтожь порченое семя.", progress = nil, completion = "Как послушник Наралекса я не могу не отметить твоей храбрости. Твоя помощь – это всего лишь первый шаг в очищении Степей от порчи.\n\nБлагодарю тебя, и да пребудет тобой удача.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВыкройка: пояс из отражающей чешуиШипящее древкоРукавицы Грязнотопи\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1488] = {title = "Осквернитель душ", objective = "Убейте лорда Азретока и Джуккара Грим'рода и вернитесь к Такате Стальному Клинку в Пустоши.", description = "Я ничего не знаю об этом лорде Азретоке, однако согласен с Маурином: его следует остановить, особенно если он пытается подчинить себе Пылающий Клинок.\n\nТвое стремление служить вождю уже не требует доказательств, и я готов доверить тебе собрать отряд, чтобы убить Азретока и его слугу чернокнижника.\n\nКогда будете готовы выступать, отправляйтесь на юг, а покончите с ними – возвращайтесь ко мне.", progress = "Слава Орде! Смерть врагам!\n\nИлиторий, демоны Пустошей сейчас сделались опаснее, чем когда бы то ни было. Моя надежда вернуться к вождю тает: этих злобных тварей становится все больше и больше!\n\nАх, если бы нам приходилось иметь дело с одними только кентаврами!", completion = "Эта победа очень важна для нас, Томпсон. Все мы радуемся вашему успеху. Теперь я думаю, что наше будущее не так беспросветно, как мне казалось.\n\nДемоны будут повержены, Пылающий Клинок потерпит крах, и в один прекрасный день у нас снова будет свой дом!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБазальтовый кулачный щитНаплечье головореза\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1489] = {title = "Хамуул Рунический Тотем", objective = "Поговорите с Хамуулом Руническим Тотемом.", description = "На раковинах, что ты мне принес, присутствует порча, которой я никогда раньше не видел. Я уверен, что причины ее возникновения кроются в воде оазиса, и я уже предчувствую, чем это грозит этим землям.\n\nИсточник этой порчи в Пещерах Стенаний, но прежде чем отправиться туда, поговори с Хамуулом Руническим Тотемом, старшим друидом. Я послал ему весточку о том, что творится в Степях. Он мудр и сможет дать тебе дельный совет.\n\nНайдешь его в Громовом Утесе, на Вершине Старейшин.", progress = nil, completion = "Приветствую тебя, Демонорох, добро пожаловать. И лучше бы тебе собрать всю волю в кулак, потому что дело, порученное тебе, будет крайне нелегким.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1490] = {title = "Нара Буйногривая", objective = "Поговорите с Нарой Буйногривой.", description = "Я вошел в сновидения и увидел там орден друидов, обитающих в Пещерах Стенаний. Когда-то их цели были благородными. Но теперь они отклонились от первоначального пути и стали слугами порчи просачивающейся из Степей.\n\nЯ уже стар, и мои силы не бесконечны. Я не мог дольше оставаться в сновидениях, хотя и хотел узнать больше об этих друидах. Но Нара молода и сильна духом, и она осталась там, когда я вынужден был уйти.\n\nПоговори с ней, <имя>, ты найдешь ее в дальней палатке.", progress = nil, completion = "Все верно, я знаю о друидах из Пещер Стенаний. Я видела их исковерканные, покрытые чешуей лица. Я знаю об их злодеяниях, и самое главное, мне известны их планы.\n\nТы должен остановить их, Демонорох.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1491] = {title = "Умный напиток", objective = "Принесите 6 порций воющей субстанции Мебоку Миззриксу в Кабестан.", description = "Ладно, рога ящеров не подошли. Ничего страшного, с первого раза никому не удается разбогатеть. Кроме того, мне удалось придумать кое-что получше! \n\nСуществует вещество, именуемое воющей субстанцией, и мне кажется, именно из-за него в Степях такие странные растения и животные. Принеси мне немного субстанции, и я попробую добавить ее в напиток!\n\nНасколько я знаю, это вещество накапливается в эктоплазматических существах в Пещерах Стенаний на западе. Убей несколько существ из пещер и собери из них субстанцию.", progress = "Где моя воющая субстанция?", completion = "Здорово, ты принес ее! Не терпится опробовать напиток. Я знаю, он принесет мне много денег!\n\nСпасибо, Слантер. Вот тебе деньги, и, разбогатев, я пришлю тебе еще, клянусь!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1492] = {title = "Управляющий пристанью Головокружилкинс", objective = "Отнесите надежный ящик управляющему пристанью Головокружилкинcу в Кабестан.", description = "Мне нужно послать ящик зелий, реактивов и прочего своим партнерам из Старого Света. У меня нет времени лично относить их в порт Кабестана, а последний караван уже отбыл.\n\nНе <мог/могла> бы ты отнести ящик управляющему пристанью Головокружилкинcу? А он в свою очередь погрузит его на первый же корабль, идущий в бухту Черноводья.", progress = "Желаешь отплыть на ближайшем корабле или послать товар на ту сторону света?", completion = "Небольшой ящик. Да, пожалуй, для него найдется место на корабле. Он отплывет в ближайший прилив, это достаточно скоро? Великолепно. Надо только записать его в мой регистр.\n\nНу вот, все готово. Пока, |3-6(Воин).", rewards = "Вы получите:\n\n"},
[1498] = {title = "Путь защиты", objective = "Принесите 5 оплавленных чешуек Уззеку на Дальнюю заставу в Степях.", description = "Одна из основных задач воина... защита. Мы – щит Орды, заслоняющий собой наших более слабых братьев. Если ты хочешь вступить в наши ряды, докажи мне, что не струсишь.\n\nСтупай в Дуротар, на Громовой хребет, где живут бурешкуры и рокочущие ящерицы. Поохоться на них, докажи, что ты сильнее их! Выстой против них и принеси мне в доказательство побольше оплавленных чешуек.\n\nКак только принесешь, я возьмусь тебя учить.", progress = "Ну как, принес чешуйки? Если ты не можешь выстоять против рокочущих ящериц, я не буду тебя учить.", completion = "А, вижу, тебе удалось справиться с рокочущими ящерицами, значит, ты крепкий парень. А теперь я покажу тебе, как можно сделаться почти неуязвимым для противника благодаря толстой шкуре и ловкости.\n\nУчись хорошенько, Гронгард. Вскоре тебе предстоит новый урок.", rewards = "Следующее заклинание будет наложено на вас:\n\nПуть защиты\n\nВы получите:\n\n"},
[1499] = {title = "Злобные фамильяры", objective = "Поговорите с Зуритой Востроглазой.", description = "Зурита часто посылает таких новичков, как ты, приструнить этих тварей. Тебе уже доводилось сражаться с коварными фамильярами.\n\nДумаю, тебе не помешает набраться опыта, помогая Зурите. Не забудь ей сказать, что ты <помогал/помогала> разобраться с бесами – возможно, у нее найдется для тебя награда.", progress = nil, completion = "Молодец, Демонорох!\n\nДа, злобные фамильяры для воинов Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предсказывает тебе великие дела!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПростой клинокПростая трость\n\nВы также получите:\n\n"},
[1500] = {title = "Пробуждение Наралекса", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1501] = {title = "Создание Бездны", objective = "Добудьте табличку Верги для Ган'рула Кровавого Глаза в Оргриммаре.", description = "Чернокнижников осталось так мало... Мы многим рискуем, но наш риск оправдан! Если ты хочешь принести пользу Орде и вождю, пора тебе научиться новому заклинанию призыва.\n\nДля начала добудь табличку Верги. Чернокнижники из клана Пылающего Клинка похитили ее и хранят у себя в логове, под скалой Черепа к востоку от города. После этого я покажу тебе руны, необходимые для призыва демона Бездны.", progress = "Ну что, Демонорох, табличка Верги у тебя? Пока ты ее не добудешь, я с тобой и разговаривать не стану!", completion = "Молодец. Надеюсь, во время твоего визита в логово чернокнижники из клана Пылающего Клинка сильно пострадали?\n\nОни причинили немало вреда вождю, да и нам, чернокнижникам, тоже.", rewards = "Вы получите:\n\n"},
[1502] = {title = "Тун'грим Огневзор", objective = "Поговорите с Тун'гримом Огневзором из Степей.", description = "Воину пристало владеть хорошим оружием. Самое лучшее оружие делает орк по имени Тун'грим Огневзор. Это отшельник, который живет на вершине холма к востоку от Перекрестка.\n\nЕсли тебе нужно оружие, воин, отправляйся к Тун'гриму. Чтобы добраться до его жилища, дойди до Перекрестка и сверни на восток, в сторону холмов. Он разбил лагерь на самой вершине.", progress = nil, completion = "Я так долго глядел на пламя горна, что у меня высохли глаза, но кое-что я по-прежнему вижу. Например, тебе что-то от меня нужно.\n\nИ раз ты добрался до моего жилища, то я могу предположить, что именно.", rewards = "Вы получите:\n\n"},
[1503] = {title = "Стальные слитки", objective = "Принесите стальные слитки Тун'гриму Огневзору из Степей.", description = "Я дам тебе оружие, <имя>, но прежде помоги мне. Несколько дней назад с северо-запада на меня напало племя Иглогривых. Биться со мной они побоялись, но зная, какое у меня плохое зрение, одни отвлекли меня своим пофыркиванием, а другие ограбили мой лагерь! Трусы!\n\nОни украли железный сундук, в котором лежали стальные слитки. Если ты сможешь вернуть их, я дам тебе нужное оружие.\n\nНайди мой сундук в одном из лагерей иглогривов и принеси мне стальные слитки.", progress = "Ты принес мне стальные слитки?", completion = "Вот они! И все мои слиточки на месте, что и неудивительно. Откуда иглогривым знать, что делать с такой отличной сталью.\n\nСпасибо, Гронгард. Вот твоя награда. Пусть она служит тебе верой и правдой.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТопор ТунгримаПалица Тун-ГримаКинжал ТунгримаМеч Тун'грима\n\nВы также получите:\n\n"},
[1504] = {title = "Связывание", objective = "Используя знаки Призыва, призовите и подчините своей воле демона Бездны. Верните знаки Призыва Ган'рулу Кровавому Глазу в Оргриммаре.", description = "Посмотри на табличку Верги. Изображенные на ней знаки понадобятся тебе для призыва. Отнеси это в круг в шатре Нииру Огненного Клинка на другом конце пещеры. Там ты сможешь вызвать демона Бездны.\n\nТебе нужно будет одолеть его любыми физическими и магическими средствами. А после этого возвращайся ко мне со знаками призыва, и я покажу тебе, как подчинить это существо своей воле.", progress = "Демон Бездны – создание могущественное! Я помню, как боролся с ним, когда был в твоем возрасте, Демонорох. С годами мой демон стал меньше сопротивляться – но подозреваю, он просто надеется, что я утрачу бдительность.\n\nНе забывай этого, Демонорох!", completion = "Молодец, Демонорох! Я покажу тебе, как вызывать демона Бездны, подобного тому, которого тебе только что пришлось одолеть.\n\nЗнай, мы на тебя очень рассчитываем, и пока что ты оправдываешь все наши надежды!\n\nОднако пусть успех не кружит тебе голову. Впереди куда более сложные задачи!", rewards = "Вы изучите:\n\nПризыв демона Бездны\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание демона Бездны\n\nВы также получите:\n\n"},
[1505] = {title = "Ветеран Уззек", objective = "Поговорите с Уззеком на Дальней заставе.", description = "Орда чтит своих воинов, потому что никто не сомневается в их силе. Но истинному величию чуждо самодовольство. Никогда не упускай случая поучиться новому.\n\nОтыщи Уззека. Он прошел через много сражений и теперь обучает молодых воинов боевым приемам. Он живет на юге от Дальней заставы, орочьего гарнизона на границе Степей и Дуротара.", progress = nil, completion = "Привет, юноша. Ты учиться пришел?", rewards = "Вы получите:\n\n"},
[1506] = {title = "Призыв от Ган'рула", objective = "Найдите Ган'рула Кровавого Глаза в Оргриммаре и поговорите с ним.", description = "Эй, ты! Ты ведь <имя>, верно?\n\nНадеюсь, сейчас у тебя нет никаких срочных дел, потому что тебя немедленно хочет видеть Гарнул. Ты найдешь его среди старших чернокнижников в расселине Теней.\n\nНасколько я знаю Ган'рула, это сулит тебе либо что-то очень хорошее, либо что-то очень плохое.", progress = nil, completion = "Ага, хорошо. Я опасался, что Офек не сумеет с тобой связаться.\n\nТебе пора продолжить свое обучение на чернокнижника. Все прочие дела пока отложи.\n\nНадеюсь, с этим проблем не будет?", rewards = "Вы получите:\n\n"},
[1507] = {title = "Пожирательница душ", objective = "Поговорите с Казулом в расселине Теней.", description = "Пора тебе научиться новому колдовству. Ты научишься вызывать сайаада, чьи чары порабощают разум. Это существо способно зачаровывать и подчинять себе слабых духом. Но не бойся! Я уверен, тебя ему не одолеть.\n\nЧтобы приманить сайаада, нужен предмет, в котором воплощена искренняя любовь и преданность. Тебе нужно найти такую вещь.\n\nГде? Ну, потолкуй с Казулом. Чего не знает этот старый чернокнижник, того и знать не стоит.", progress = nil, completion = "Хм... Демонорох. Ты еще новичок, но я чую в тебе большие способности.\n\nУ тебя врожденный дар к чернокнижию, Демонорох. Такими вещами не разбрасываются.", rewards = "Вы получите:\n\n"},
[1508] = {title = "Слепой Казул", objective = "Поговорите с Занкайей в Оргриммаре.", description = "Раз Ган'рул отправил тебя ко мне, ты, должно быть, хочешь вызвать суккуба, женщину-сайаад, и ищешь приманку...\n\nНу, если ты <готов/готова> довериться слепому поводырю, <имя>, то слушай. Среди утесов Оргриммара, к западу от башни ветрокрылов, живет Занкайя. Она ждет, когда к ней вернется близкий друг.\n\nСтупай к ней.", progress = nil, completion = "У тебя есть весточка от Дограна? Он должен был вернуться уже несколько дней тому назад, а о нем до сих пор ни слуху, ни духу...", rewards = "Вы получите:\n\n"},
[1509] = {title = "Вести о Догране", objective = "Поговорите с Газрогом в Перекрестке.", description = "Моего супруга, Дограна, не так давно отправили служить в Перекресток. Это было повышение по службе, он так гордился…\n\nМне, конечно, было грустно, но ему я этого не показывала. Грустно и тревожно. Степи – не Оргриммар, это опасное место, и я боялась худшего…\n\nОн должен был вернуться неделю назад, а от него до сих пор нет никаких вестей!\n\nМожет, ты сходишь в Перекресток, разузнаешь о нем? Он служил вместе с Газрогом, и Газрог, наверное, до сих пор там...", progress = nil, completion = "Занкайя? Жена Дограна, да?\n\nСлышать-то я о нем слышал, но это не те новости, которые стоит ей передавать.\n\nДа нет, не убили его. Но он ранен и сейчас в плену у иглогривов.", rewards = "Вы получите:\n\n"},
[1510] = {title = "Вести о Догране", objective = "Поговорите с Кен'зиглой в Малака'джине.", description = "Он был в Лагере Таурахо, где мы пытались извести иглогривов. Он повел нескольких рубак на одно из их стойбищ, и там его тяжело ранили. Остальные вернулись и попытались его выручить. Но он был в плохом состоянии, раны загноились, и ребята побоялись его трогать.\n\nОни отправили сюда послание, просили троллей из Малака'джина у Когтистых гор прислать целительное зелье. Мы послали за зельем, но гонец пока не вернулся.", progress = nil, completion = "Орк? Надеюсь, ты не за тем, другим? А то он добрался не очень... благополучно. Общение с гоблинами не довело его до добра.\n\nОн успел сказать, что приехал за целительным зельем, но больше ничего вразумительного.", rewards = "Вы получите:\n\n"},
[1511] = {title = "Зелье Кен'зиглы", objective = "Отнесите зелье Кен'зиглы рубаке Логмару в Лагерь Таурахо.", description = "Я так и думал, что за зельем явится кто-нибудь еще!\n\nВот оно, <имя>, бери. Имей в виду, сразу все ему не давай, пусть выпьет половину! Этого ему хватит, чтобы передвигаться. А иначе он истечет кровью. На следующее утро пусть выпьет вторую половину.\n\nОтнеси это Логмару в Лагерь Таурахо. Судя по тому, что сказал мне первый гонец, Логмар знает, где Догран.", progress = "Да, чего тебе?", completion = "О, как нельзя более кстати! А то Догран уже умирает там, в плену.\n\nЭто нужно доставить ему немедленно. Но большинство моих рубак сейчас на задании...", rewards = "Вы получите:\n\n"},
[1512] = {title = "Дар любви", objective = "Отнесите подвеску, испачканную грязью, Ган'рулу Кровавому Глазу в Оргриммар.", description = "Занкайя молода и красива. Зачем ей калека? Несправедливо это будет.\n\nОставь меня, <имя>. Спасибо тебе. Я предпочел бы умереть в славной битве, а не влачить это жалкое существование.\n\nИ прошу тебя, не говори об этом моей супруге... Не хочу, чтобы она чувствовала себя виноватой.", progress = "А, вот и ты! Ну что, готов встретиться с суккубом?", completion = "Ну, если ты говоришь, что этого достаточно, я тебе верю, Демонорох. Дай-ка я ее оботру... Да, вот такая, блестящая и чистенькая, она будет куда соблазнительней для суккуба.", rewards = "Вы получите:\n\n"},
[1513] = {title = "Связывание", objective = "Призовите и подчините суккуба с помощью подвески Дограна. Вернуть подвеску Ган'рулу Кровавому Глазу в Оргриммаре.", description = "Отнеси это к кругу призыва в шатре Нииру, <имя>. Вызови гнусного суккуба и покажи ему, кто здесь хозяин. Я верю в силу твоей магии. Но все же будь осторожнее: гордость и самоуверенность погубили немало многообещающих чернокнижников.\n\nКогда подчинишь суккуба, верни подвеску мне. Нужно будет сообщить Занкайе о случившемся.", progress = "Когда я вижу суккуба, мое сердце поет... Но в то же время я буквально чувствую, как моя душа иссыхает, утекает, как песок между пальцев.\n\nБудь осторожнее!", completion = "Получилось! Впрочем, я ничего другого и не ждал, ведь ты – мой лучший ученик.\n\nТеперь я с радостью покажу тебе, как вызывать усмиренного суккуба. Ступай, тебе многому нужно научиться. Я рассчитываю, что к нашей следующей встрече ты уже по-настоящему подчинишь своего суккуба.\n\nС печальной историей Дограна и Занкайи разберутся те, кто постарше тебя. Но ты ее не забывай: она послужит хорошей защитой от хитростей темного демона, который явился к тебе сегодня.", rewards = "Вы изучите:\n\nПризыв суккуба\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание суккуба\n\nВы также получите:\n\nМалая сума душ"},
[1514] = {title = "Оскверненный ветроцвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[1515] = {title = "Догран в плену", objective = "Отнесите зелье Кен'зиглы Дограну в Степях.", description = "Ну, раз уж ты здесь и хочешь завершить свое дело, останавливать тебя я не буду. Но своих воинов я с тобой отпустить не cмогу, ступай в одиночку.\n\nДограна держат в лагере иглогривов, к северу отсюда. Ищи две хижины, стоящие рядом. Иглогривы его стерегут – если, конечно, его еще не убили, или он не умер от ран.\n\nУдачи тебе!", progress = "Ууф-ф...", completion = "Тьфу, гадость…\n\nОднако сил у меня прибавляется. Пожалуй, я теперь смогу уковылять отсюда... Однако похоже, что ногу мне придется отнять. И руку тоже.", rewards = "Вы получите:\n\n"},
[1516] = {title = "Зов земли", objective = "Принесите Канаге заклинателю земли 2 копыта ловцов Скверны.", description = "Что ж, <класс>, пора! Ты <набрался/набралась> сил, твой дух стоек, как сама Земля. А то, что тобою избран путь шамана – само по себе доказательство твоей мудрости.\n\nСтихия земли будет управлять твоей судьбой, станет частью тебя. <Готов/Готова> ли ты? Тебе придется предстать перед самой Землей. И тогда ты увидишь многое, что ведомо лишь шаманам.\n\nРазыщи на севере ловцов скверны и добудь два их копыта. А потом возвращайся ко мне, и мы обсудим твое будущее.", progress = "Терпение – вот величайшая добродетель! Все на земле меняется: горы превращаются в пустыни, реки становятся ущельями. И лишь сама Земля остается неизменной. Она не любит нетерпеливых.\n\nТеперь Земля зовет тебя: приближается время решительной схватки! Когда ты достигнешь успеха и вернешься ко мне, ты будешь куда ближе к целостности.\n\nДругие будут завидовать твоей мудрости и ненавидеть тебя за свое невежество.", completion = "Великолепно! Твой успех доказывает: ты действительно готов.\n\nСреди стихий именно Земля – основа всего сущего. Это твоя сила, твоя выносливость и твое терпение. Земля защитит тебя, если ты будешь относиться к ней с должным почтением. Но и Земля, как все прочие стихии, может быть своенравной.\n\nТеперь я сделаю для тебя сапту. Прими ее – и постигнешь свой путь!", rewards = "Вы получите:\n\n"},
[1517] = {title = "Зов земли", objective = "Найдите Священный Камень и выпейте рядом с ним сапту Земли.\n\nПрилагается предмет: \n", description = "Сапта – это напиток, который связывает душу со стихией. Сама магия растворена в нем. И сильные духом благодаря ему способны зреть стихии, которых никто более не видит. Твой дух будет связан со стихией сапты. Лишь немногие избранные шаманы знают рецепт этого напитка.\n\nЗапомни: сапту можно пить лишь в священном месте, и нигде более!\n\nОтыщи Священный Камень к юго-западу отсюда. Он находится в конце Потайной тропы. Выпей там сапту, а дальше... увидишь!", progress = nil, completion = "Ах... Ахахаха... Земля ликует от того, что ты пришел сюда. \n\nТеперь ты связан с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твое терпение, и весь мир – основа твоей сущности. \n\nДля прохождения этого обряда довольно было смиренно предстать перед землей. Но другие обряды потребуют более активных действий. Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе.", rewards = "Вы получите:\n\n"},
[1518] = {title = "Зов земли", objective = "Отнесите необработанный кварц Канаге заклинателю земли в долину Испытаний.", description = "Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы с тобой встречались. Он создаст тотем для тебя, и этот камушек будет сердцем тотема. Он невелик, но со временем ты поймешь, что размер не имеет значения. Иногда малое оказывается долговечнее большого.\n\nБудь <терпелив/терпелива>, <имя>. Оставайся <сильным/сильной>. И ищи мудрости. В конце концов ты станешь единым целым с Землей – чти же ее, и она будет чтить тебя.", progress = "Вот ты и встал на первый из четырех путей, которые в конце концов приведут тебя к твоему предназначению!\n\nЕсли у тебя с собой тот камушек, что дала тебе Земля, ты получишь от меня обещанный тотем.\n\nА если нет – убирайся до тех пор, пока не обретешь путь!", completion = "Великолепно!\n\nТотем, который я создам для тебя, – не просто символ нового статуса. Он обладает тайными возможностями. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретешь, тем больше способностей земли станет тебе доступно.\n\nНаставники скажут тебе, когда ты будешь готов к новым знаниям.\n\nА пока возьми этот тотем Земли.", rewards = "Вы изучите:\n\nТотем каменной кожи\n\nСледующее заклинание будет наложено на вас:\n\nТотем каменной кожи\n\nВы также получите:\n\nТотем земли"},
[1519] = {title = "Зов земли", objective = "Принесите 2 порции ритуальной мази провидице Воронье Перо в Лагерь Нараче.", description = "Время настало, <юный/юная: c> <класс>. Тело твое возмужало, а дух закалился, как сама земля. Я вижу, ты <обрел/обрела> мудрость.\n\nЗемля ведет и хранит наш народ, она говорит с нами, как однажды станет говорить с тобой. Но тебе придется пройти испытания. Если ты <готов/готова>, твоему взору откроется то, о чем известно лишь нашему народу. \n\nНайди шаманов из племени Дыбогривов в их лощине на востоке и возьми у них мазь, которую они используют в своих ритуалах. Возвращайся ко мне, когда соберешь достаточно мази для изготовления зелья.", progress = "Земле не занимать терпения, она будет ждать, покуда ты не будешь готов, ибо она знает, что с течением времени все разрушается и возрождается вновь. Это круговорот бытия. Горы превращаются в пустыни, реки становятся каньонами. Земля – самая упрямая и самая мудрая из стихий.\n\nТы должен прежде всего научиться терпению и выносливости. Земля призывает тебя, потому что знает – ты готов. Если ты преуспеешь, то родишься заново и навсегда распрощаешься со своим невежеством.", completion = "Отлично, Серошкур. Ты вернулся – а значит, готов к следующему шагу. \n\nСтихия земли – это основа всех вещей. Это твоя сила, твоя выносливость и твое терпение. Мать-Земля защитит тебя, но к ней должно относиться с уважением. Она – основа жизни, и следуя ее законам, ты приумножишь мудрость. Никогда не забывай тайны, которые она разделит с тобой. \n\nТеперь я приготовлю для тебя сапту земли, который откроет перед тобой новые пути.", rewards = "Вы получите:\n\n"},
[1520] = {title = "Зов земли", objective = "Найдите Дольмен Кодо и выпейте сапту земли.\n\nПрилагается предмет: \n", description = "Сапта – это напиток, призванный объединить твой дух со стихиями. Сотворенное с помощью магии зелье позволит тем, чье сознание открыто, видить стихии так, как их никто не видел ранее. Твой дух будет навеки связан со стихией, для которой был создан сапта – и лишь немногим из нашего племени известен секрет его изготовления. \n\nСапта должна быть выпита в только в священном месте и более нигде. \n\nНайди шаманское святилище к востоку отсюда и выпей сапту там.", progress = nil, completion = "Ах... Локтарогар... Земля ликует от того, что ты пришел сюда. \n\nТеперь ты связан с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твое терпение, и весь мир – основа твоей сущности. \n\nДля прохождения этого обряда довольно было смиренно предстать перед землей. Но другие обряды потребуют более активных действий. Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе.", rewards = "Вы получите:\n\n"},
[1521] = {title = "Зов земли", objective = "Отнесите грубый кварц провидице Воронье Перо в Лагерь Нараче.", description = "Возьми этот грубый кварц и отнеси его провидице Воронье Перо в доказательство того, что мы говорили с тобой. Она создаст для тебя тотем, и этот камень станет его сердцем. Тебе может показаться, что он мал, но со временем ты поймешь, что размер не имеет значения. Иногда малое оказывается долговечнее большого.\n\nБудь <терпелив/терпелива>, <имя>. Оставайся <сильным/сильной>. И ищи мудрости. Так угодно земле. В конце концов ты станешь единым целым с землей – чти же ее, и она будет чтить тебя.", progress = "Приветствую тебя, Шаматруль. Ты бы не вернулся ко мне, если бы не выполнил задания. Позволь мне первой поздравить тебя с выбором первой дороги – первой из четырех, которым отныне ты будешь следовать во всех своих путешествиях. \n\nЕсли у тебя есть камень, который дала тебе земля, я отдам тебе обещанный тотем. Если же нет, мне жаль тебя. Посвятившему себя служению стихиям должно иметь гордость.", completion = "Прекрасно! \n\nТотем, который я сделаю для тебя – не просто символ. Он обладает тайными свойствами. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретешь, тем больше способностей земли станет тебе доступно.\n\nНаставники в Калимдоре скажут тебе, когда ты будешь готов к новым знаниям.\n\nА пока возьми этот тотем Земли...", rewards = "Вы изучите:\n\nТотем каменной кожи\n\nСледующее заклинание будет наложено на вас:\n\nТотем каменной кожи\n\nВы также получите:\n\nТотем земли"},
[1522] = {title = "Зов огня", objective = "Найдите в Степях Кранала Фисса.", description = "Огонь с тобой, дружище! Шо, я смотрю, пути Земли тебе уже знакомы? Значит, пора тебе перетереть с Крэналом.\n\nКрэнал живет к северу от Перекрестка, в Степях. По части стихий он очень крут, и путям Огня тебя научит на раз... если ты, конечно, <готов/готова> к этому.\n\nНайти его – как нефиг делать, только смотри, слишком далеко не ходи, а не то к эльфам занесет.", progress = nil, completion = "Что, тебя Сеарн прислал, да?\n\nНу, на Сеарна положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня.\n\nДа, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Однако, имей терпение, Когтик. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.", rewards = "Вы получите:\n\n"},
[1523] = {title = "Зов огня", objective = "Найдите в Степях Кранала Фисса.", description = "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание, <имя>! Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты <готов/готова> платить за это.\n\nОтыщи в Степях Кранала Фисса. Он живет в небольшой хижине к северу от Перекрестка. Только осторожнее: если промахнешься, можешь очутиться в землях ночных эльфов!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1524] = {title = "Зов огня", objective = "Отнесите факел Дремлющего Пламени Телфу Джуламу в Дуротаре.", description = "У тебя достаточно сил, чтобы управлять тотемом огня, но это еще не значит, что ты <готов/готова> к этому.\n\nВдоль реки Строптивой в Дуротаре, у Великого моря, лежит тайная тропа, ведущая к одному из высочайших пиков в нашей стране. Отыщи путь на вершину, и найдешь одно из наших святилищ, которое оберегает Телф Джулам – святилище Спящего Пламени.\n\nОтнеси ему этот факел – это знак, что ты пытаешься приручить огонь. Верни мне этот факел зажженным от жаровни в святилище, и я позабочусь, чтобы тебе был дан тотем огня.", progress = "Привет тебе, Ахахаха! Ты находишься в святилище Дремлющего Пламени. Только те, кто достаточно сведущ в шаманском искусстве, способны постичь тайны этого места и силу, которую оно содержит. Мне жаль отсылать тебя ни с чем после того, как тебе пришлось проделать весь этот путь – ведь он отнюдь не безопасен! – однако я – хранитель святилища, и не могу позволить бродить здесь кому попало.", completion = "А, Ахахаха, я ошибся! Прошу прощения. Я не знал, что у тебя с собой этот факел. Очень рад познакомиться.\n\nСюда забредает немало путешественников, которые ищут клады или охотятся на невиданных зверей, и мне приходится прогонять их из этого святилища, которое кажется пустым. Но мы-то с тобой знаем истину, не так ли, Ахахаха?\n\nЭто святилище скрывает от несведущих великую тайну. Для нас эта тайна священна!", rewards = "Вы получите:\n\n"},
[1525] = {title = "Зов огня", objective = "Принесите 1 порцию огненной смолы и 1 мешочек с реагентами Телфу Джуламу в Дуротаре.", description = "Но ты ведь здесь не затем, чтобы выслушивать лекции по истории, верно? Тебе нужно Неугасимое Пламя и тотем Огня!\n\nПервый шаг – это создать сапту, чтобы связать тебя со стихией огня.\n\nЯ могу изготовить тебе сапту, но для этого нужны две вещи. Во-первых – огненная смола, распространенное вещество, которое обычно носят при себе заклинатели Иглогривых в восточных Степях.\n\nА вот второй компонент добыть куда сложнее: это мешочек с реактивами, какие носят чернокнижники из клана Пылающего Клинка. Их можно отыскать в пещере над ущельями к северо-востоку от Колючего Холма.", progress = "У меня достаточно ингредиентов, чтобы изготовить сапту огня, если ты только раздобудешь мешочек с реактивами и немного огненной смолы. Фанатики из клана Пылающего Клинка носят при себе большую часть необходимых компонентов, так что разыскивать что-то еще обычно не приходится.\n\nСапты всегда изготовляются из ингредиентов, тесно связанных с соответствующими стихиями. Нашу задачу упрощает то, что чернокнижники всегда имеют дело с огнем.", completion = "Это как раз то, что надо, Ахахаха.\n\nОгонь – это не просто хаос и разрушение. Запомни это хорошенько! Огонь – это еще и жизнь, и творение! Все в мире взаимосвязано подобным же образом. Противоборствующие силы противостоят друг другу, но при этом не могут существовать поодиночке. Они взаимно уничтожаются, но придают друг другу смысл. Помни об этом!\n\nОдновременное использование различных видов магии говорит не только о подлинном искусстве, но и о большой мудрости.", rewards = "Вы получите:\n\nСапта огня"},
[1526] = {title = "Зов огня", objective = "Сразитесь с низшим воплощением огня и поместите светящийся уголек в жаровню в святилище Неугасимого Пламени.", description = "Сапта огня готова. Пришло тебе время встретиться лицом к лицу со стихией пламени! Выпей сапту в святилище и отправляйся на вершину горы, чтобы увидеть там проявление. Оно не нападет на тебя, пока ты не будешь <готов/готова> к этому, однако оно поймет, что ты его видишь.\n\nПостарайся поразить его как можно быстрее, <имя>, ибо чем дольше ты будешь тянуть, тем больше мощи оно наберет! Когда одолеешь его, положи оставшиеся от него тлеющие уголья в жаровню и зажги факел.", progress = "Жаровня высотой примерно в треть вашего роста выглядит вполне обычной, если не считать того, что она покрыта письменами. Металл блестит, как новенький, чаша вверху жаровни прохладная на ощупь...", completion = "Когда вы бросаете уголек в жаровню, в чаше вспыхивает жаркое белое пламя. Вы ощущаете, как по телу разливается огонь сапты, перед глазами ритмично бьется пламя. \n\nВы опускаете факел в чашу, и он мгновенно вспыхивает.", rewards = "Вы получите:\n\nФакел Вечного Пламени"},
[1527] = {title = "Зов огня", objective = "Принесите факел Неугасимого Пламени Краналу Фиссу в Степи.", description = "Крепко сжимая факел, вы отступаете от жаровни, оборачиваетесь и окидываете взглядом весь Дуротар. Вас охватывает восторг. Пламя факела рвется и трепещет на ветру.\n\nИ вот вы начинаете спускаться обратно по тропе, ведущей в Степи, возвращаясь к Краналу Фиссу.", progress = "Да, Ахахаха? Что у тебя там?", completion = "Твой дух пылает ярче любого факела, Ахахаха! Тебе есть чем гордиться.\n\nНе сходи с избранного пути, и стихии будут повиноваться тебе, а наши собратья станут искать у тебя советов и наставлений. Позволь мне первым поздравить тебя и вручить тебе новый тотем...", rewards = "Вы изучите:\n\nОпаляющий тотем\n\nСледующее заклинание будет наложено на вас:\n\nОпаляющий тотем\n\nВы также получите:\n\nТотем огня"},
[1528] = {title = "Зов воды", objective = "Отыщите в Степях Ислен Заклинательницу Воды.", description = "Вода – твое будущее, дружище. Вижу, ты уже <покорил/покорила> огонь и, кажись, <готов/готова> поговорить с Ислен.\n\nИслен живет на побережье ентих Степей. Топай на юг, вдоль реки Строптивая, не промахнешься – ищи нехилую акулу! Ислен – великая повелительница духов, и она научит тебя сути воды... если ты <готов/готова>.\n\nТы ее запростяк найдешь, только на юг слишком далеко не заходи: Ислен живет рядом с Кабестаном.", progress = nil, completion = "Ветер следует за тобой, по земле ты шагаешь твердо, а дух уже согрет огнем – я бы сказала, что пришло время познать чистоту воды.\n\nПуть твой был долог, и сила духа позволит тебе пройти еще дальше. Но первый шаг делать тебе.", rewards = "Вы получите:\n\n"},
[1529] = {title = "Зов воды", objective = "Отыщите в Степях Ислен Заклинательницу Воды.", description = "Много воды утекло со времени последнего испытания. Ты <проявил/проявила> немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды.\n\nОтыщи Ислен Заклинательницу Воды. Она живет в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, <имя>.", progress = nil, completion = "Ветер следует за тобой, по земле ты шагаешь твердо, а дух уже согрет огнем – я бы сказала, что пришло время познать чистоту воды.\n\nПуть твой был долог, и сила духа позволит тебе пройти еще дальше. Но первый шаг делать тебе.", rewards = "Вы получите:\n\n"},
[1530] = {title = "Зов воды", objective = "Отыщите Брин в южной части Степей.", description = "Первым делом ты <должен/должна> понять, что вода означает возрождение. \n\nВода течет, разрушает и очищает все сущее. Ты увидишь, что вода – великий целитель, но только чистая вода.\n\nПознав, что оскверненная вода разрушает все кругом, ты поймешь и то, как вода важна для мироздания.\n\nЕсли же ты хочешь получить сапту воды, отыщи Брин в южной части Степей. На ее дом постоянно нападают иглогривы.", progress = nil, completion = "Да?\n\nМ-м-м, у меня такое чувство, что я заранее знаю твой вопрос: кому взбредет в голову жить в сердце Степей в ожидании нападения иглогривов и без защиты? У всех нас свои причины действовать так или иначе. У меня другой вопрос – что заставило простого |3-1(тролль) отправиться в сердце Степей разговаривать с женщиной, которую не заботит собственное благополучие?\n\nГотова поспорить, что мы оба знаем ответ на этот вопрос.", rewards = "Вы получите:\n\n"},
[1531] = {title = "Зов воздуха", objective = "Найдите Пратту Заклинательницу Туч в Тысяче Игл.", description = "Ты делаешь успехи, дружище. Я верю, что ты <достоин/достойна> тотема воздуха, но сначала надо отыскать Пратту Заклинательницу Туч в Тысяче Игл. Отнесись к ней с уважением, и она расскажет, как получить тотем.\n\nИди на юг, через Степи, а когда попадешь в Тысячу Игл, сверни на восток. Пратт прячется в пещере вместе со своим парнем. Ха-ха! Только не рассказывай ей, что я проболтался тебе об этом, а то она рассердится.", progress = nil, completion = "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотем. Возвращайся, когда будешь готов продолжить обучение.", rewards = "Следующее заклинание будет наложено на вас:\n\nБыстрый ветер\n\nВы получите:\n\nТотем воздуха"},
[1532] = {title = "Зов воздуха", objective = "Найдите Пратту Заклинательницу Туч в Тысяче Игл.", description = "Все ветра Калимдора спешат к тебе навстречу, и скоро ты займешь достойное место среди наших самых выдающихся <братьев/сестер>. Я чрезвычайно горжусь твоими успехами и вижу, что тебя ждет великое будущее.\n\nДух воздуха покорить нелегко, но я верю, что ты сумеешь преодолеть любые препятствия на своем пути.\n\nОтправляйся на самый юг Степей, в Тысячу Игл. Там, на востоке, ты найдешь Пратту Заклинательницу Туч, и она продолжит твое обучение.", progress = nil, completion = "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотем. Возвращайся, когда будешь готов продолжить обучение.", rewards = "Следующее заклинание будет наложено на вас:\n\nБыстрый ветер\n\nВы получите:\n\nТотем воздуха"},
[1533] = {title = "*NYI* Зов воздуха", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1534] = {title = "Зов воды", objective = "Наполните пустой синий бурдюк для воды в руинах Звездной Пыли и отнесите воду Брин из Степей.", description = "Возьми этот бурдюк и ступай в густой лес, который ночные эльфы зовут Ясеневым. Он находится далеко на севере от Степей.\n\nДобравшись до леса, отправляйся в его западную часть. Возле гряды, отделяющей Когтистые горы от Ясеневого леса, за озером Мистраль, располагается священное место, руины Звездной Пыли. В центре озера, на островке, есть маленький фонтан. Прежде чем возвращаться к Ислен, принеси мне воду из этого источника.", progress = "Ты уже несешь мне воду, Ахахаха? Говорят, что руины охраняют огромные порождения природы, которые не жалуют гостей, но, вероятно, это всего лишь легенды, призванные отпугивать врагов ночных эльфов.\n\nИ все же соблюдай осторожность.", completion = "Чудесно. Теперь у меня есть все три пробы воды, и я могу наполнить фиал чистейшей водой, которую только способно найти живое существо. Она понадобится тебе на следующем этапе.\n\nЯ рада, что среди избравших наш путь есть такие, как ты, Ахахаха. Все шаманы гордятся тобой, и я надеюсь вскоре услышать о твоих подвигах.", rewards = "Вы получите:\n\n"},
[1535] = {title = "Зов воды", objective = "Наполните пустой коричневый бурдюк для воды в источнике ниже хижины Брин и отнесите ей воду.", description = "Чтобы обрести понимание и получить от меня сапту, тебе предстоит отыскать чистейшую воду. Принося мне образцы, обращай внимание на окружающий мир – какие существа зависят от этой воды и охраняют ее. Как она влияет на леса и пустыни. Ты увидишь, как влага, дающая жизнь сущему, вынуждает различных существ отнимать эту жизнь у других.\n\nНачнем с малого: ниже моего домика есть пруд с драгоценной влагой.", progress = "Я готова дать тебе следующее задание. Ты уже наполнил бурдюк?\n\nЯ знаю, как ревниво иглогривы относятся к водопоям. Ведь даже малый источник для них – настоящее сокровище. Они устраивают пир, если Степи осчастливит хоть небольшой дождь. Вода для них священна, ведь здесь ее очень мало. Ясно?", completion = "Я предполагала, что если ты возьмешься набирать воду, кровопролития не избежать. Жаль, что иглогривы не понимают, что все живые существа связаны между собой, а жадность лишь усиливает боль и страдания их собственного народа. О, сколь многого они достигли бы, забыв о спорах и объединившись.\n\nДа, для них это плохо, но для других обитателей Степей – скорее хорошо.", rewards = "Вы получите:\n\n"},
[1536] = {title = "Зов воды", objective = "Наполните пустой красный бурдюк для воды в Мельнице Таррен и отнесите воду Брин в Степи.", description = "Давным-давно мы с несколькими спутниками отправились в предгорья Хилсбрада. Нам пришлось отбиваться от навязчивых людей, поселившихся в тех краях, и в итоге мы оказались в городке, захваченном Отрекшимися, – Мельнице Таррен.\n\nИ удивительное дело – в центре города обнаружился маленький источник свежей родниковой воды. Не думаю, что пораженные чумой жители города осознают его ценность – это малый луч света в царстве тьмы.\n\nНабери воду из этого источника в этот бурдюк и принеси мне.", progress = "Источник, оставшийся чистым в центре такого города, напомнил мне о сказках, услышанных в детстве. Даже во времена великой боли и скорби остается место надежде, пусть самой малой. Тралл – последняя надежда орков. Он выжил, пройдя сквозь суровые испытания, и вывел наш народ из тьмы собственной силой и решимостью.\n\nНе думаю, чтобы на долю хотя бы одного орка выпало столько страданий, но в то же время ни одному орку не была дарована такая сила.", completion = "Хорошо, Ахахаха. Ты изо всех сил стараешься выполнить порученные тебе задания и добиваешься успеха.\n\nЕще одна проба воды, и я смогу создать реактив, необходимый для сапты. Ислен будет довольна.", rewards = "Вы получите:\n\n"},
[1538] = {title = "*NYI* Зов воздуха", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1558] = {title = "Каменная дамба", objective = "Отведите сироту к Каменной дамбе у озера Лок Модан. Пусть постоит в центре дамбы и полюбуется огромным водопадом.", description = "В Стальгорне живут все дворфы и гномы. Рядом есть местечко, которое зовется озером Лок Модан, и именно там дворфы отгрохали ЗДОРОВЕННУЮ дамбу. Говорят, это одна из самых больших построек в мире. Во как!\n\nПожалуйста, своди меня к озеру Лок Модан, посмотреть на дамбу! Как она называется? Кажется, Каминная дамба? Нет, камин – это что-то не то. В общем, она большая. И на огромный водопад хочется посмотреть. Обещаю, я не буду к нему наклоняться!", progress = nil, completion = "Ух ты! Она еще БОЛЬШЕ, чем я думал! Я собственного голоса не слышу из-за грохота воды! Эй, а вода там не закончится? Ой, а что будет, если дамба рухнет! Вот это было бы страшно!\n\nСпасибо, что показал мне дамбу. Мне понравилось. Я же говорил, что буду хорошо себя вести!", rewards = "Вы получите:\n\n"},
[1559] = {title = "Секрет изготовления световой бомбы", objective = "Так ты у нас инженер, да? Ну что ж, за то, что нашел для меня жемчужины, вот тебе секрет изготовления световых бомб. \n\nТы с ними только уж поосторожней, как бы самому не ослепнуть!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЧертеж: световая бомба"},
[1560] = {title = "Задание Тооги", objective = "Сопроводите Тоогу к его жене, Торте.", description = "Я заблудился!\n\nМоя жена, Торта, отправила меня за обедом, но я не туда свернул.\n\nОтведи меня обратно к Торте! Она ждет меня на юге от Порта Картеля.", progress = "Где Тоога?", completion = "Он что, сам не смог найти дорогу? Как обычно.\n\nДа, видно тебе надо дать что-нибудь за труды...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nХелонийские манжетыКольцо Великой Черепахи\n\nВы также получите:\n\n"},
[1578] = {title = "Помощь фронту", objective = "Отнесите 6 медных топоров и 6 медных плетеных поясов Торвальду в южную сторожевую башню озера Лок Модан.", description = "Горная пехота озера Лок Модан без передышки сражается с троггами! Им нужен постоянный подвоз новых доспехов и оружия, иначе с троггами не справиться.\n\nМой коллега Торвальд как раз и поехал туда – за тем чтобы у солдат было доброе снаряжение. Так что если бы вы могли изготовить несколько медных топоров и плетеных поясов и доставить их Торвальду, он был бы очень вам благодарен. Он даже может поделиться с вами своими знаниями.\n\nТорвальда вы найдете в южной сторожевой башне озера Лок Модан.", progress = "У меня нет времени на болтовню. Говори, какое у тебя ко мне дело?", completion = "Ох, прости! Я и не понял, что ты пришел помочь в деле вооружения наших войск. Изготовленные тобой вещи очень нам помогут!\n\nВот чертежи кое-каких доспехов. Надеюсь, они тебе пригодятся.", rewards = "Вы получите:\n\nЧертеж: медный плетеный нагрудник"},
[1579] = {title = "Суперразъемы", objective = "Принесите Бацбаху Кривошипу в Аубердин 8 суперразъемов.", description = "Я прибыл в Аубердин в поисках тишины и покоя. Я хочу заниматься своими изобретениями там, где царит покой, потому что после ночных попоек мне совсем не нравится гомон Стальгорна!\n\nТак что я отправился на корабле в Аубердин... и по дороге слегка перебрал. Я уронил за борт мой ящик с суперразъемами!\n\nТочно не знаю, где я их потерял, но если ты попытаешься выловить их в океане, может, тебе повезет...", progress = "Нашел мои суперразъемы, Криворучка? Без этих суперразъемов я не могу приспособить шатуны!", completion = "Ах, не могу поверить, что тебе удалось их найти! Должно быть, ты самый везучий |3-6(гном) на Калимдоре!", rewards = "Вы получите:\n\n"},
[1580] = {title = "Электропеллеры", objective = "Принесите 12 электропеллеров Бацбаху Кривошипу в Аубердин.", description = "Мы знаем, что тебе везет, но... насколько сильно везет, <имя>?\n\nОднажды ночью я бродил по дорогам Темного Берега. Я искал речку или озеро, пригодные для испытания моей самодвижущейся и взрывающейся подсадной утки и, думаю, был слегка пьян... поскольку потерял сознание и пришел в себя в Аубердине спустя несколько часов. Мои волосы были опалены, а сумка с электропеллерами исчезла! Должно быть, я уронил ее в воду!\n\nМне нужны эти электропеллеры! Может быть, тебе удастся выловить их из какого-нибудь водоема на Темном Берегу?..", progress = "Ну как, нашел хоть один электропеллер? Они нужны мне, чтобы продолжить мои ислледования о подсадных утках...", completion = "Глазам не верю! Ты их нашел! Ты лучший рыбак на моей памяти!\n\nСпасибо тебе, Медведик. И вот, возьми это. Хотя ты, наверное, в этом и не нуждаешься, оно послужит тебе подспорьем при ужении.", rewards = "Вы получите:\n\nАквадинамическая блесна"},
[1581] = {title = "Эликсиры для клана Режущего Листа", objective = "Доставьте 6 эликсиров Львиной силы и 2 слабых эликсира защиты Сирел Остролист в Доланаар.", description = "Наша лавочка трав и алхимических снадобий процветает, но мой муж проводит столько времени за изготовлением эликсиров, что почти забыл про личную жизнь!\n\nТы нам не поможешь?\n\nЕсли ты привезешь мне партию уже готовых эликсиров, я охотно куплю их у тебя. У меня есть некоторые редкие травы, которые могут оказаться полезными для тебя.", progress = "Ну, привет тебе, Айлерон. Привез эликсиров на продажу?", completion = "Прекрасные снадобья! Ты проявил исключительную щепетильность, Айлерон,  что очень важно для алхимика!\n\nВот твои травы, я только-только их собрала. Пусть они тебе пригодятся!", rewards = "Вы получите:\n\nЗемлекореньМагороза"},
[1582] = {title = "Жилет Лунного сияния", objective = "Принесите 1 пару тисненых кожаных перчаток, 5 пар тисненых кожаных сапог и 5 тисненых кожаных плащей Лотериас в Дарнасс.", description = "У нас, жителей Дарнасса, в особенности у ремесленников, работы невпроворот. Молодым искателям приключений неймется испытать себя во всякой глухомани, так что нам постоянно нужен подвоз материалов.\n\nЕсли ты поможешь мне выполнить заказ на кожаные изделия, я, может, научу тебя более совершенной технике работы с кожей.", progress = "Приветствую, Скирди.", completion = "Да, славные изделия. У тебя искусные руки и острый глаз. Из тебя может получиться неплохой кожевник.\n\nСлушай, Скирди. Давай-ка я покажу тебе выкройку жилета Лунного сияния.", rewards = "Вы получите:\n\nВыкройка: жилет лунного сияния"},
[1598] = {title = "Украденная книга", objective = "Принесите книгу \"Силы Бездны\" Друзилле ла Салле.", description = "Ах, это ты! Тебя зовут <имя>, верно?\n\nНадеюсь, ты точно <уверен/уверена>, что желаешь стать $Gчернокнижником:чернокнижницей;, поскольку если ты не умеешь постоять за себя, среди нас тебе делать нечего.\n\nЯ буду тебя обучать, но сначала я должна убедиться, что ты достаточно <силен/сильна>.\n\nВ здешнем аббатстве обучался один послушник, который сбежал и вступил в Братство Справедливости. Почему меня это волнует? А потому, что он стянул из аббатства кое-какие важные книги.\n\nОдну из них я сама хотела бы иметь. Братство прячет эту книгу – \"Силы Бездны\" – в своем шатре на виноградниках. Принеси ее мне.", progress = "Было бы слишком опасно самой пытаться украсть эту книгу из аббатства. Какая удача, что этот простофиля сделал всю грязную работу за меня!", completion = "Замечательно... Мне никогда не удавалось добраться до этой книги, его держали в охраняемом крыле библиотеки, и было бы подозрительно, если бы я стала рыскать вокруг.\n\nЛадно, ты отлично потрудился, и я уверена, что ты сумеешь справиться со своим собственным бесом. Пора показать тебе, как его вызывать!", rewards = "Вы изучите:\n\nПризыв беса\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание беса\n\nВы также получите:\n\n"},
[1599] = {title = "В начале славных дел", objective = "Добудьте 3 оберега из перьев и отнесите их Аламару Мрачнну в Старую Наковальню.", description = "Тут все шепчутся о каком-то новом чернокнижнике; наверное, это ты и есть. Должно быть, ты вызываешь кое у кого сильную симпатию, раз меня попросили отвлечься от моих изысканий и посвятить некоторое время занятиям с тобой.\n\nНе беспокойся: я не ставлю это тебе в вину.\n\nЧто ж, самое простое из заклинаний призыва позволяет вызвать беса. Однако, прежде чем я преподам тебе этот урок, мне хотелось бы получить доказательства того, что у тебя достаточно как физической, так и магической силы...\n\nПринеси мне три оберега из перьев. Ты получишь их, если расправишься с новобранцами племени Мерзлогривов в пещере, что к юго-западу отсюда.", progress = "Обереги из перьев наделены своего рода магической силой. Было бы интересно провести соответствующие исследования... Да уж, троллям удалось меня удивить.", completion = "Прекрасно, прекрасно! В самом деле, Асмерт, неплохая работа. Возможно, те, кто тебя рекомендовал, и не ошиблись...\n\nВпрочем, это не мне решать. Поживем – увидим. Будем надеяться, что первый же вызванный бес не вырвет тебе сердце и не сожрет внутренности – думаю, подобное могло бы серьезно повредить твоей карьере. Пока у меня есть основания полагать, что в качестве чернокнижника ты сумеешь прожить хотя бы несколько месяцев.\n\nКстати, Асмерт, хотел тебе дать тебе совет по поводу бесов. Запомни, размер – еще не главное: даже самый глупый таурен знает, что бесы наделены весьма сильной магией.", rewards = "Вы изучите:\n\nПризыв беса\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание беса\n\nВы также получите:\n\n"},
[1618] = {title = "Экипирование Красногорья", objective = "Отнесите 4 рунных медных пояса и 4 тяжелых медных кувалды Вернеру Осгуду в Красногорье.", description = "Не только мы, дворфы, сражаемся денно и нощно – люди, наши союзники, тоже не прохлаждаются!\n\nНа Красногорье время от времени устраивают налеты орки Черной Горы, а снаряжения туда всегда мало поставляется. Если ты им поможешь, то местный кузнец Вернер Осгуд наверняка научит тебя паре хитростей.", progress = "Надеюсь, ты принес добрые вести из Стальгорна? Я уже не знаю, что мне делать!", completion = "Спасибо, Маладат. Это чрезвычайно мне поможет. Орки Черной Горы нападают со стороны крепости Каменной Стражи, а гноллы Красногорья шныряют в северных предгорьях, и мне постоянно приходится чинить доспехи и делать новое оружие для наших войск.\n\nТо, что ты принес, даст мне хоть небольшую передышку. И у меня будет время кое-чему тебя научить...", rewards = "Вы получите:\n\nЧертеж: стальгорнская кираса"},
[1638] = {title = "Обучение воина", objective = "Поговорите с Гарри Берлгардом.", description = "Ты в самом деле неплохой воин, <имя>, но лет тебе мало, и еще многому придется научиться.\n\nПоговори с Гарри Берлгардом – обычно он сидит в \"Свинье и Свистке\", в Старом городе Штормграда. Гарри опытный боец и неплохой учитель. Он покажет тебе несколько приемов, глядишь, и подольше проживешь.", progress = nil, completion = "О-хо! Выпей со мной, парень. С первого взгляда ты кажешься крепким, посмотрим, что с тобой сделает несколько кружек крепкого пива!!!\n\nИли... А, да ты поучиться хочешь?", rewards = "Вы получите:\n\n"},
[1639] = {title = "Бартлби Пьянь", objective = "Поговорите с Бартлби.", description = "Да, я могу заняться твоим обучением, но сначала хочу взглянуть, на что ты годишься.\n\nВидишь, в конце бара стоит выпивка? Бартлби тоже видишь? Добудь эту кружку.\n\nХа, если ты <знаком/знакома> с ним, то догадаешься, что так просто он ее не отдаст.", progress = nil, completion = "Эй, красавчик! Что таким как ты делать в \"Свинье и свистке\"? Осторожнее, неровен час, ноготь сломаешь...", rewards = "Вы получите:\n\n"},
[1640] = {title = "Побить Бартлби", objective = "Побейте Бартлби и снова поговорите с ним.", description = "Что ты хочешь? Да ты <спятил/спятила>!\n\nЭту кружку ты получишь только через мой труп...", progress = "Эту кружку ты получишь только через мой труп...", completion = "А ты крепче, чем кажешься с первого взгляда.", rewards = "Вы получите:\n\n"},
[1641] = {title = "Фолиант Божественности", objective = "Здесь, в Штормграде, я – наставник паладинов. Я – тот, кто ведет их стезей добродетели к Истинному Свету, дабы они защищали Азерот от нашествия нежити и иных бедствий.\n\nИ для тебя пришло время сделать первый шаг на пути праведности. Если ты решишься принять этот путь, я дам тебе Фолиант Божественности. Изучая его, ты узнаешь кое-что о Свете и о том, чего от тебя ожидают. Постигнув мудрость, заключенную в этой книге, ты откроешь в себе новые, удивительные способности.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nФолиант Божественности"},
[1642] = {title = "Фолиант Божественности", objective = "Найдите в Штормграде Даториана Ралла и поговорите с ним.", description = "Во всех своих деяниях паладин должен быть достоин того Света, которому мы служим и который дарует нам силу. Для таких, как мы, стремление к божественности не означает желания стать богами: мы лишь стремимся творить добро.\n\nНыне наступили тяжелые времена: мы избраны для того, чтобы сражаться со злом и повергнуть его. Однако помни: не борьба со злом отличает нас от прочих жителей Азерота. Сострадание, терпение, отвага и помощь ближним – для паладина все это значит не меньше, чем искусство воина.\n\nНикогда не забывай об этом!", progress = nil, completion = "И снова рад приветствовать тебя, Мэйнард. Как идет изучение Фолианта Божественности?\n\nПомни: тебе предстоит пройти испытание. Каждого из нас ждет множество свершений – как в городе, так и в иных землях. Всегда есть люди, нуждающиеся в помощи, сострадании и понимании; всегда есть враждебные твари, которых необходимо уничтожать во благо людей.\n\nДокажи, что ты можешь помогать своим ближним – в особенности тем, кому меньше повезло в жизни. Тем самым ты докажешь, что твои помыслы чисты и что ты воистину служишь Свету.", rewards = "Вы получите:\n\n"},
[1643] = {title = "Фолиант Божественности", objective = "Обыщите Торговый квартал и найдите Стефани Тернер.", description = "Итак, <имя>, твоя задача – найти в Штормграде того, кто нуждается в помощи. Того, кто чист сердцем и помыслами. Возможно, это тот, кто сам помогает другим. Возможно – тот, кто нуждается в наставнике. Как бы то ни было, намерения того, кого ты ищешь, будут благородны, и он во всем будет полагаться на тебя.\n\nТы возвратишься ко мне, когда исполнишь это задание, и мы поговорим о твоем пути – а равно и о том, что значит быть паладином Света.", progress = nil, completion = "О, привет, милашка. Что, все ищешь приключений? Я так рада, что у тебя все в порядке!\n\nЯ? А что я? Ну, с учетом обстоятельств, у меня тоже дела идут неплохо...\n\nПравда, торговцев у нас тут прибавилось, а пожертвований на сиротский приют стало меньше: зачем отдавать даром то, что можно продать? Но ничего, мы справимся. Под \"нами\" я имею в виду себя и своего мужа, конечно. Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей...", rewards = "Вы получите:\n\n"},
[1644] = {title = "Фолиант Божественности", objective = "Принесите 10 отрезов льна в Штормград и отдайте Стефани Тернер.", description = "Да будут благословенны эти несчастные! Многие из них потеряли родных во время набегов нежити...\n\nМой муж Джон помогает мне доставать ткань, чтобы я могла шить сироткам одежду, но увы, на это у меня не хватает времени, ведь их нужно сначала накормить и дать им кров.\n\nЧто? Правда? Ты хочешь мне помочь? Благодарение Вечному Свету! Благодарю тебя, <имя>!\n\nЕсли бы у меня был лен на одежки малышам, их жизнь стала бы хоть немного легче...", progress = "Надеюсь, моему Джону в Стальгорне повезет. Он терпеть не может дальние поездки – ведь ему приходится оставлять меня одну с детьми, – но знает, что это необходимо. У Джона такое доброе сердце...\n\nИногда нам бывает и полегче, но этот год поистине выдался самым тяжелым на моей памяти. Возможно, это знак того, что в мире что-то меняется, кто знает?..", completion = "Ах, Мэйнард, благодарю, благодарю тебя!\n\nДетишки так рады будут, да и у меня будет побольше времени на них. Надеюсь, теперь Джон сможет возвратиться поскорее.\n\nПрими мою искреннюю признательность, Мэйнард. Я всегда верила, что в сердцах людей есть место милосердию. Да пребудет с тобой Извечный Свет.", rewards = "Вы получите:\n\n"},
[1645] = {title = "Фолиант Божественности", objective = "Приятно встретить тебя, Палсдубиной. Я направляю паладинов на путь высших добродетелей, когда они посвящают себя Свету и защите Азерота от Плети и прочих бед.\n\nПришла пора сделать первый шаг по пути истинных добродетелей. Если ты принимаешь этот путь, я дам тебе Фолиант Божественности. Изучая его, ты узнаешь кое-что о Свете и о том, что тебя ждет. Если ты это поймешь и окажешься способным учеником, то откроешь путь к великим возможностям.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nФолиант Божественности"},
[1646] = {title = "Фолиант Божественности", objective = "Поговорите с Тизой Кузнебой в Стальгорне.", description = "Паладин во всех делах своих должен быть проявлением Света, который есть источник нашей силы. Стремление к божественности для нас не означает стремления стать божеством – мы стремимся к добру во всех деяниях наших.\n\nХотя в эти тяжелые времена мы призваны сокрушать зло, тебе всегда следует помнить: лишь помогая другим, ты выделяешься среди других обитателей Азерота. Сочувствие, терпение, отвага – все эти достоинства значат для паладина не меньше, чем сила в сражении.\n\nУсвой же это и помни всегда.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1647] = {title = "Фолиант Божественности", objective = "Найдите во внешнем круге Стальгорна Джона Тернера.", description = "Твоя задача, <имя>, найти в Стальгорне кого-нибудь, кто нуждается в помощи. Того, кто чист душой и помыслами. Может быть, того, кто сам помогает другим. Того, кто нуждается в совете. Кто бы то ни был, у него должны быть благородные стремления и он должен полагаться на твою доброту.\n\nСделай это и по выполнении возвращайся ко мне. Тогда мы еще поговорим о твоем пути и о том, что значит быть паладином Света. Я останусь в храме до твоего возвращения. Мое наставничество нужно и другим паладинам.", progress = nil, completion = "СИРОТСКИЙ ПРИЮТ ШТОРМ... о, простите, я вовсе не хотел кричать на вас, сударь,\n\nМеня зовут Джон Тернер. Как поживаете?\n\nРад, искренне рад слышать, что у вас все хорошо. А у меня был трудный день, я тоскую по жене, но такова цена, которую приходится платить, чтобы накормить голодные рты и одеть нагих.", rewards = "Вы получите:\n\n"},
[1648] = {title = "Фолиант Божественности", objective = "Принесите 10 отрезов льняной ткани Джону Тернеру в Стальгорн.", description = "Мы с женой держим в Штормграде сиротский приют, по большей части для детей, потерявших родителей во время нападений Плети в последние десять лет. Я приезжаю в Стальгорн примерно раз в месяц и занимаюсь сбором средств у здешних горожан, а также прошу помощи у различных организаций.\n\nНынешняя поездка была мучительно медленной и не слишком продуктивной.\n\nЕсли бы мне удалось добыть еще немного льняной ткани для одежды, я бы смог, наконец, отправить посылку домой.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1649] = {title = "Фолиант Отваги", objective = "Поговорите с Даторианом Раллом в Штормграде.", description = "Отвага и сопутствующие ей достоинства подобны драгоценным металлам. Нужно беречь их, когда находишь, ибо цена их велика, но также необходимо копить и приумножать их. Тогда они образуют крепчайший сплав, зачастую выдерживающий даже самые сильные удары.\n\nТвои сила, вера и храбрость должны быть испытаны. Тебе надлежит научиться хранить веру в любых обстоятельствах и понять, что с помощью сил Света ты сможешь преодолеть те препятствия, которые не по силам другим.", progress = nil, completion = "Ты просишь испытать твою отвагу? Прекрасно!\n\nДля тебя в городе и в окрестностях найдется немало заданий. Нам как раз нужен кто-нибудь с твоими способностями.\n\nЭто испытание не будет легким, Rainon! Оно, как и многое в нашей профессии, может привести к гибели. Церковь всегда готова поддержать своих слуг, но без жертв невозможно определить, достоин ли паладин служить правому делу.\n\nЧувствуешь ли ты в себе готовность к испытанию?", rewards = "Вы получите:\n\n"},
[1650] = {title = "Фолиант Отваги", objective = "Найдите Дафну Стилвелл в Западном Крае.", description = "Отлично! Отсутствие сомнений говорит о твоей готовности к испытаниям. Да будет так!\n\nВ самом конце Долгого Берега стоит небольшой домик с окнами на океан. Там живет чета Стивеллов. Джордан – великолепный кузнец, и сейчас он собирается в Стальгорн, чтобы навестить дворфов. Но его жена Дафна остается дома одна, без защиты...\n\nДонесения говорят, что Братство Справедливости захватило почти весь край. Дафне может понадобиться защита от злодеев. Отправляйся туда.", progress = nil, completion = "Здравствуй, Rainon. Я полагаю, что со всем этим оружием в руках ты хочешь либо захватить мои земли, либо Церковь наконец-то послала мне защитника на время поездки Джордана.\n\nПозволь представиться: я – Дафна Стилвелл. Очень приятно!\n\nТвое прибытие очень кстати: с восхода солнца я уже прикончила с полдюжины этих мерзавцев. До этого они не особо торопились, но сейчас они наверняка заметили тебя, а значит, будут здесь с минуты на минуту...", rewards = "Вы получите:\n\n"},
[1651] = {title = "Фолиант Отваги", objective = "Защитите Дафну Стилвелл от нападения Братства Справедливости. Проследите, чтобы ни ее, ни ваша душа в случае смерти не покинули свои тела, иначе испытание не будет засчитано.\n\nПосле победы поговорите с Дафной Стилвелл.", description = "Бьюсь об заклад, они скоро вернутся – так что приготовься.\n\nВ доме есть пистолет, я возьму его и при необходимости помогу тебе, но лучше рассчитывай только на свои силы.\n\nНе знаю, сколько их будет, но уверена, что больше, чем в прошлый раз.\n\nМоли Свет благословить тебя, потому что… Слышишь? Они идут!\n\nУкроемся за домом!", progress = "Укроемся в доме!", completion = "Rainon, мы победили! Благодарю тебя за помощь. Это было просто великолепно! Я и не думала, что паладин может справиться с таким количеством врагов зараз.\n\nТвоя выдающаяся храбрость перед лицом превосходящих сил потрясла меня...", rewards = "Вы получите:\n\n"},
[1652] = {title = "Фолиант Отваги", objective = "Поговорите с Даторианом Раллом в Штормграде.", description = "Прошу, возвращайся к Даториану и передай ему, что теперь со мной все в порядке – благодаря тебе и Церкви.\n\nОн пошлет весть в Стальгорн, чтобы мой Джордан не волновался за меня.\n\nОх, как я соскучилась по своему мужу! Жду не дождусь его возвращения...", progress = nil, completion = "Вот мы и встретились снова. Я вижу, что дух твой бодр. Дом четы Стивеллов теперь в безопасности, а из твоего рассказа ясно, что ему теперь еще долго ничего не будет угрожать. Отлично!\n\nДафна и Джордан немало помогли Церкви. Отправить тебя на их защиту – весьма скромная ответная услуга.\n\nТы получишь награду за проявленную отвагу.", rewards = "Вы изучите:\n\nЧутье на нежить\n\nСледующее заклинание будет наложено на вас:\n\nЧутье на нежить\n\nВы также получите:\n\nБастион Штормграда"},
[1653] = {title = "Испытание доблести", objective = "Поговорите с Джорданом Стилвеллом в Стальгорне.", description = "Вообще я не сомневаюсь, что Джордан захочет лично отблагодарить тебя, и раз уж мне надо сообщить ему, что его жена в безопасности, то, думаю, лучше всего тебя посланником и отправить.\n\nДжордан был паладином Света, до того как приверженность отцовскому ремеслу увлекла его на другой путь, – а потому он хорошо знает наш образ жизни и считается одним из самых надежных наших приверженцев.\n\nОн должен еще быть в Стальгорне – он любит работать днем за воротами, там где с гор тянет холодным воздухом.", progress = nil, completion = "Добрый день, Rainon. Вижу, ты служишь Свету?\n\nЧто это? Тебя послал Даториан?! Моя жена, как она? Я так и знал – стоит уехать, сразу беды нагрянут. Скажи мне, она... о, хвала Свету. Я так счастлив, что она в безопасности. Это Братство Справедливости было опасным еще до нынешних своих налетов, но теперь уж королевские советники не смогут этой угрозы отрицать.\n\nЧто еще велел передать Даториан?\n\nИменно ты и назначен был оберегать мою жену? Тогда еще раз прими мою благодарность, Rainon. Не могу придумать лучшего испытания доблести, чем это.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1654] = {title = "Испытание доблести", objective = "Возьмите список Джордана, добудьте немного древесины белокаменного дуба, партию очищенной руды Бэйлора, кузнечный молот Джордана и самоцвет Кора и отдайте их Джордану Стилвеллу в Стальгорне.", description = "Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар. Пойми меня правильно, все будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода.\n\nЯ скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света. Но тебе придется добыть необходимые для ковки предметы. Я уже набросал список, так что остается только, чтобы некто отважный и искусный принес их мне. Что скажешь, <класс>?", progress = "Предметы эти нелегко добыть, но, смею тебя заверить, оружие, которое я для тебя сделаю, сторицей окупит твои труды.\n\nЭто будет лучшая моя работа и лишь малая награда за все, что ты сделал для меня.", completion = "Великолепно! Ты добыл все необходимое.\n\nТеперь я легко изготовлю для тебя великолепное оружие! Я и так собирался когда-нибудь его выковать, просто не было возможности достать все необходимое. Спасибо тебе, Гельевич.\n\nКак же приятно снова держать в руке молот моих отцов... и самоцвет Кора – я и не думал, что когда-нибудь увижу его собственными глазами!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1655] = {title = "Партия руды Балора", objective = "Доставьте партию руды для Джордана Балору Крепкоруку к озеру Лок Модан.", description = "Ох, и <испугал ты меня, парень/испугала ты меня> дамочка;! Не видишь, что я в размышлениях?\n\nЭто что еще? Поставка Джордану... Стальгорн. А, да, я понял, о чем речь. Мо'грошские огры ограбили меня, и нет у меня руды для старого друга. Караван шел сюда из Болотины и попал в засаду. Охранник, что уцелел, помер пару дней назад – целитель не поспел вовремя.\n\nЕсли хочешь найти эту партию руды, то придется тебе двинуться на север, за озеро Лок. Она где-то там.", progress = "Ну, что, удалось? Огры получили от тебя по полной, да?", completion = "Ну-ну, надо же! Знал бы я, что ты и правда прямо туда и пойдешь и навтыкаешь этим ограм, я бы дал тебе целый список, что оттуда принести. Но ведь ты тут не за тем, чтобы за меня работу делать, верно?\n\nА сделка есть сделка. Джордан хотел получить свою руду, и он ее получит.\n\nПередай ему приветик от меня, и доброй тебе дороги, |3-6(Паладин).", rewards = "Вы получите:\n\nПартия очищенной руды Джордана"},
[1656] = {title = "Незаконченное задание", objective = "Отнесите сверток мехов хозяину таверны Кауту в Деревню Кровавого Копыта.", description = "<имя>, умоляю, помоги мне! У меня еще есть дело здесь, на плато - я прохожу обряд Силы, - а мой отец требует, чтобы я срочно доставила эти меха в таверну в деревне Кровавого Копыта! \n\nКак же мне выполнить сразу обе задачи - завершить ритуал и отнести меха?! Не отнесешь ли ты их вместо меня?\n\nТаверна - такое милое и уютное местечко, там есть все, чего может пожелать притомившийся путник. Даю слово, тебе понравится!", progress = "Приветствую! Чем Каут может вам помочь?\n\nПуть сюда от самого плато неблизок: кто-то всю дорогу думает об уставших мышцах и стертых ногах, а кто-то наслаждается великолепными пейзажами... А вы что скажете?", completion = "О, а вот и мои меха! Благодарю вас.\n\nВы доставили их даже быстрее, чем я ожидал. Они послужат отличными одеялами для моих постояльцев.\n\nПрошу вас, гостите в таверне, сколько пожелаете. Наши двери всегда открыты, и мы рады каждому. Не стоит недооценивать значение полноценного отдыха - особенно если впереди дальняя дорога.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЧерствая краюха хлебаОсвежающая ключевая вода\n\nВы также получите:\n\n"},
[1657] = {title = "Чем пахнет в Южнобережье", objective = "Бросить три бомбы-вонючки Отрекшихся в центр Южнобережья в Хилсбраде и вернитесь к Янке Зовущей Тьму на фестиваль Плетеного человека на Тирисфальских лугах.", description = "Сделайте ваш праздник Тыквовина незабываемым... насолив нашим врагам на Южнобережье!\n\nВозьмите специально собранную бомбу-вонючку – она наполнена невероятно зловонным веществом, запах которого не вынесет ни одно тупое животное, включая людей. Вам нужно будет бросить ее в самый центр Южнобережья, так что готовьтесь к драке с Альянсом!\n\nА когда сделаете этот шаг к нашему освобождению, возвращайтесь ко мне!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТыквовинская конфета"},
[1658] = {title = "Сорвать праздник Плетеного человека", objective = "Отыщите место проведения фестиваля Плетеного человека в Тирисфальских лугах и возвращайтесь в Южнобережье к сержанту Дыгалу.", description = "Мне нужны храбрецы, готовые отправиться в Тирисфальские луга на фестиваль Плетеного человека. Не скрою, это очень опасно. Стража на фестивале будет особенно бдительна и свирепа. И все же надо выяснить, велик ли в этом году фестиваль, и сколько бед Отрекшиеся причинят нам во время Тыквовина.\n\nЕсли тебе хватит пороху, ступай в Тирисфаль и разведай, что да как. Я прослежу, чтобы тебе хорошо заплатили за принесенную информацию.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТыквовинская конфета"},
[1661] = {title = "Фолиант Благородства", objective = "Поговорите с Даторианом Раллом в Штормграде.", description = "Приветствую тебя, <имя>! Я несказанно рад тому, что могу называть тебя <Братом/Сестрой>: твое посвящение – радость для всех нас.\n\nПришло время вручить тебе великий дар. Но знай: сейчас я даю его тебе, не требуя ничего взамен; но потом настанет час, когда всем паладинам придется немало потрудиться для того, чтобы получить его.\n\nПриходи в любое время – я отдам тебе твой подарок.", progress = nil, completion = "Поздравляю! Да пребудет с тобой Свет!", rewards = "Вы изучите:\n\nВызов боевого коня\n\nСледующее заклинание будет наложено на вас:\n\nПризыв боевого коня"},
[1665] = {title = "Кружка Бартлби", objective = "Отнесите кружку Бартлби Баргарду.", description = "Ладно, бери мою кружку. Стой! Дай-ка я хотя бы допью... Ну вот. Бери.", progress = "Я наблюдал за твоей дракой с Бартлби. Неплохо! Удалось отобрать кружку?", completion = "А вот и кружка! Да уж, он не хотел с ней расставаться, но ты умеешь настоять на своем. Молодец.\n\nПриступим к обучению...", rewards = "Следующее заклинание будет наложено на вас:\n\nПуть защиты\n\nВы получите:\n\n"},
[1666] = {title = "Маршал Хаггард", objective = "Поговорите с маршалом Хаггардом.", description = "Ты <освоил/освоила> несколько новых приемов, но без хорошего оружия тебе не обойтись. Думаю, тебе мог бы помочь маршал Хаггард.\n\nОн живет в своем поместье в Элвиннском лесу, возле лесозаготовок Восточной Долины. Он ушел в отставку, но за время службы собрал недурную коллекцию оружия.\n\nСкажи, что тебя прислал я, и если повезет, он поделится лишним оружием.", progress = nil, completion = "Кто это? Баргард, это ты? Подойди поближе. Глаза у меня уже не те. Ты так подкрался, что я принял тебя за гнолла!", rewards = "Вы получите:\n\n"},
[1667] = {title = "Джек Мертвозуб", objective = "Добыть знак маршала Хаггарда из лагеря Джека Мертвозуба и вернуться к маршалу Хаггарду.", description = "Тебя ведь прислал Баргард? Да, у меня есть запасное оружие, но сначала я хочу дать тебе задание…\n\nНекоторое время назад меня обманул злодей из Братства Справедливости, Джек Мертвозуб. Он пришел в темноте, одетый в гербовую накидку Штормграда, и я принял его за маршала Дугхана. Джек сказал, что ему нужен мой старый знак маршала, и я, не раздумывая, отдал его... а потом он захохотал и сбежал, прежде, чем я успел его схватить!\n\nВерни мне мой знак! Джек Мертвозуб наверняка прячет его в лагере на юге.", progress = "Мой знак у тебя? Страшно подумать, какие преступления может совершить Джек с его помощью.", completion = "Ура, мой знак у тебя! Я боялся, что лишился его навсегда, а шваль из Братства Справедливости получила возможность изображать из себя представителей власти. Тебе же удалось предотвратить невиданный разгул преступности.\n\nВот мое оружие, которое лежит без дела с тех времен, как я был маршалом. Я его регулярно чистил его, и оно в отличной форме, выбирай!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТопор ХаггардаМолот ХагградаКинжал ХагградаМеч Хаггарда\n\nВы также получите:\n\n"},
[1678] = {title = "Веджрек", objective = "Принесите голову Веджрека Марену Грозовой Вершине в Стальгорн.", description = "Хорошему воину пристало быть стойким. Я научу тебя новым приемам, но прежде докажи, что сможешь справиться с серьезными противниками.\n\nВеджрек – один из самых сильных троллей в наших краях. Ему-то ты и бросишь вызов. Он живет в хижине в предгорьях, чуть южнее форта Мерзлогривов.\n\nПринеси мне голову Веджрека, и я поверю, что ты не лыком <шит/шита>.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПуть защиты\n\nВы получите:\n\n"},
[1679] = {title = "Марен Грозовая Вершина", objective = "Поговорите с Мареном Грозовой Вершиной.", description = "Привет тебе, воин! Ты <наделен/наделена> многими талантами, но тебе предстоит многому научиться, и лучше учителя, чем Марен Грозовая Вершина, не найдешь.\n\nМарен в Оружейной, в Палатах Войны Стальгорна. Как только ты решишь сделать очередной шаг на пути воина, поговори с ним.", progress = nil, completion = "А, Фокстун. Я слышал твое имя от воинов Дун Морога. Надеюсь, ты не все время проводишь в пивных?", rewards = "Вы получите:\n\n"},
[1680] = {title = "Тормус Подземная Кузня", objective = "Поговорите с Тормусом Подземной Кузней.", description = "Ты уже <освоил/освоила> несколько приемов, пора заняться твоим оружием. Поговори с Тормусом Подземной Кузней. Он скует тебе оружие по вкусу.\n\nТормус живет здесь, в Стальгорне, в Великой Кузне.", progress = nil, completion = "Тебя прислал Марен? Да, я могу сковать тебе превосходное оружие... Но услуга за услугу.\n\nНе бойся. Конечно, задание будет опасным, ты можешь погибнуть, но разве не к этому стремятся все воины?", rewards = "Вы получите:\n\n"},
[1681] = {title = "Мастерская Сталекрута", objective = "Принесите мрачную руду Тормусу Подземной Кузне в Стальгорн.", description = "У моего наставника, Стурги Сталекрута, была мастерская на юге от озера Хельмова ложа в восточной части Дун Морога. Он был лучшим учителем кузнечного дела.\n\nНо однажды ученики принесли ему странную руду. Мастер Сталекрут назвал ее мрачной рудой и с радостью с ней работал, но увы, вскоре на них напал отряд дворфов Черного Железа. Они поубивали всех!\n\nСтупай в мастерскую Сталекрута, <имя>, и отомсти за смерть моего учителя. И принеси мне груз мрачной руды.", progress = "Тебе удалось пробраться в поселок Сталекрута? А мрачная руда у тебя?", completion = "Ты нашел ее! Молодец!\n\nНадеюсь, что в ходе поисков ты убил целую толпу дворфов Черного Железа. Боюсь, нам придется столкнуться с ними не только в мастерской Сталекрута.\n\nВпрочем, спасибо за руду, Хрофтгор. Я с радостью поработаю с ней и исследую ее свойства.", rewards = "Вы получите:\n\n"},
[1682] = {title = "Оружие из серой стали", objective = "Вот тебе оружие, только что с наковальни. На него пошла добытая тобой мрачная руда!\n\nЧто же, Хрофтгор, выбирай!", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМрачный топорМрачная палицаМрачный кинжалМрачный меч\n\nВы также получите:\n\n"},
[1683] = {title = "Ворлус Подлое Копыто", objective = "Принесите рог Ворлуса Эланарии из Дарнасса.", description = "Прежде чем браться за твое обучение, я хочу испытать твою храбрость.\n\nСатир Ворлус Подлое Копыто обнаружил один из наших лунных колодцев, тот, что на юго-востоке от обители Бен'этиль. Он плещется в его светлых водах, оскверняя их своим присутствием.\n\nОтыщи Ворлуса и убей его. В доказательство принеси мне его рог, и я возьмусь учить тебя.\n\nОтыскать дорогу к колодцу очень трудно, но тот, кто ищет, тот всегда найдет.", progress = "Ты добыла рог, Ашалисс? Очищен ли наш колодец от скверны Ворлуса?", completion = "Спасибо тебе, Ашалисс. Приятно знать, что Ворлус мертв, а наш колодец снова чист, и не менее приятно видеть молодых воинов, которые хотят очистить наш любимый Тельдрассил от порчи.\n\nПриступим к обучению...", rewards = "Следующее заклинание будет наложено на вас:\n\nПуть защиты\n\nВы получите:\n\n"},
[1684] = {title = "Эланария", objective = "Поговорите с Эланарией.", description = "Приветствую тебя, воин. Ты растешь над собой, но профессия воина не так проста, как кажется. Тебе нужен хороший учитель.\n\nВ Дарнассе, на террасе Воинов, живет Эланария. Поучись у нее.", progress = nil, completion = "Приветствую тебя, Ашалисс. В Дарнассе говорят, что ты подаешь надежды. Впрочем, скоро мы узнаем, хватит ли тебе силы воли, чтобы следовать путем воина.", rewards = "Вы получите:\n\n"},
[1685] = {title = "Приглашение Гакина", objective = "Встретьтесь с Гакином Темнопрядом в квартале магов Штормграда.", description = "И вот так всегда. Я разыскивал тебя весь день, но так и не смог найти; а сейчас, когда я вовсе этого не ожидал, ты появляешься как из-под земли.\n\nЯ уже и так слишком много времени потратил на твои поиски, так что буду краток. Наставник Гакин призывает тебя для дополнительных занятий – и, думаю, тебе стоит поторопиться.\n\nТы найдешь его в подвале таверны \"Забитый ягненок\". К слову сказать, не стоит много болтать об этом месте...", progress = nil, completion = "Наконец-то ты здесь. Мне следовало послать за тобой кого-нибудь более расторопного, чем Ремен.\n\nНу, неважно.\n\nКогда у тебя было последнее занятие? Слишком давно, слишком... А ты знаешь, что у плохо обученного чернокнижника мало шансов сохранить голову на плечах?", rewards = "Вы получите:\n\n"},
[1686] = {title = "Тень Элуры", objective = "Принесите 8 партий элунитовой руды и медальон Элуры Эланарии из Дарнасса.", description = "Ты многому <научился/научилась>, <имя>. Пора создать для тебя настоящее оружие. Оружие воина.\n\nТебе придется отправиться за ним на Темный берег.\n\nДавным-давно один корабль разбился о камни рядом с Аубердинским маяком, и по дну моря рассеялось множество сундуков с элунитовой рудой.\n\nДля начала тебе придется одержать верх над стражем элунита, тенью Элуры. Она была капитаном затонувшего корабля, а после смерти сама обрекла себя на то, чтобы стать последним стражем груза. Победи ее, забери у нее медальон и собери со дна ящики с элунитом.", progress = "Тебе удалось одолеть тень Элуры, Ашалисс? А достать со дна элунитовую руду?", completion = "Да, отваги тебе не занимать, Ашалисс.\n\nТень Элуры наконец-то обрела покой, а из добытого элунита тебе скуют прекрасное оружие.", rewards = "Вы получите:\n\n"},
[1687] = {title = "Маяк с привидениями", objective = "Отведите сироту к маяку на побережье Западного Края.", description = "Попечительницы сирот рассказывают нам сказки на ночь. Иногда даже про привидений. Это особенно КРУТО! Мне запомнилась история про призрак, живущий в маяке Западного Края. Говорят, он был капитаном пиратского корабля, но корабль захватили другие пираты. Правда, интересно?\n\nОтведи меня к этому маяку! Я хочу посмотреть на призрак капитана! Обещаю не отходить от тебя ни на шаг!", progress = nil, completion = "Надо же, настоящий призрак! Потрясающе – мне не терпится рассказать ребятам из приюта. Капитан Грейсон... И выглядел точно как пират! Когда я вырасту, я тоже стану пиратом-призраком!\n\nСпасибо, что сводил меня в Западный Край, я знаю, что вокруг полно всякой жути. Надеюсь, я не очень усложнил тебе жизнь. Ты просто чудо!", rewards = "Вы получите:\n\n"},
[1688] = {title = "Сурена Каледон", objective = "Верните колье Кровавого камня Гакину Темной Вязи в Штормград.", description = "У меня была ученица по имени Сурена Каледон. Помню, она стояла как раз там, где сейчас стоишь ты… Просила меня научить ее искусству чернокнижия, а у самой даже капли таланта к этому не было. Хм, зато она была молода и довольно миловидна. Если бы я видел тогда, что это за вероломная дрянь!\n\nРаспутная девка сбежала с одним из членов Братства Справедливости по имени Эрлан Драджмур. Об этой потере я нисколько не сожалею, однако колье Кровавого камня, которое я подарил ей, мне все еще нужно.\n\nЕе жизнь для меня больше ничего не значит. Ты найдешь девку на тыквенной ферме Бреквеллов. Верни мне мое имущество!", progress = "Старики и мудрецы тоже подвластны чарам молодости и красоты, Кхалдун. Это совет, который стоит запомнить на всю оставшуюся жизнь.", completion = "Сурена была талантлива, но не настолько, чтобы овладеть чарами самостоятельно. Печально видеть, как погибают молодые и талантливые, но иногда без этого нельзя.\n\nНадеюсь, усилия, вложенные в тебя, прахом не пойдут...", rewards = "Вы получите:\n\n"},
[1689] = {title = "Связывание", objective = "С помощью колье Кровавого камня призовите и подчините демона Бездны, затем верните колье Кровавого камня Гакину Темнопряду.", description = "Вернув мое колье и обманув Сурену, ты <доказал/доказала>, что не уступаешь ей в таланте.\n\nПоэтому я уверен, что тебе не помешает обучение. Ты можешь управлять потоками магической энергии, но чернокнижник должен уметь намного больше.\n\nЯ научу тебя управлять демоном Бездны, но прежде тебе нужно призвать его в круг призыва и покорить, используя любое оружие, которое имеется в твоем распоряжении. Используй магию колье в кругу призыва.", progress = "Я не могу показать тебе, как управлять демоном Бездны, пока ты не подчинишь его своей воле.", completion = "Тебе удалось даже больше, чем я ожидал, Кхалдун. На это я и надеялся. Теперь ты можешь научиться управлять покоренным тобой демоном. Он станет твоим помощником в предстоящих испытаниях. Сейчас мне нечему больше учить тебя, но я уверен, что мы с тобой, Кхалдун, еще увидимся...", rewards = "Вы изучите:\n\nПризыв демона Бездны\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание демона Бездны\n\nВы также получите:\n\n"},
[1690] = {title = "Расправа над Скитальцами Пустыни", objective = "Убейте 10 бандитов и 10 воров из шайки Скитальцев Пустыни на востоке от Прибамбасска и возвращайтесь к главному инженеру Чепухастеру.", description = "Эй, ты! Пора оказать услугу Водной компании Прибамбасска.\n\nКочевники Скитальцев Пустыни захватили почти все колодцы пустыни Танарис! Без них у нас мигом закончится вода. Если ты хочешь заслужить нашу признательность, расправься с этими варварами!\n\nСтупай на восток и прикончи 10 бандитов и 10 воров из шайки Скитальцев Пустыни, а на обратном пути доложись мне. Никому не миновать расправы... или как там говорится... А, неважно, иди себе!", progress = nil, completion = "Ну, вот это называется эффективность! Ты помог нам сократить число кочевников, и мы начинаем подумывать о том, чтобы отбить наши колодцы.\n\nВодная компания Прибамбасска благодарит тебя за помощь, но мы еще не разобрались с этими проклятыми кочевниками. Слушай внимательно – вот что нам понадобится теперь...", rewards = "Вы получите:\n\n"},
[1691] = {title = "Еще одна расправа над Скитальцами Пустыни", objective = "Убейте 10 темных магов, 8 разбойников и 6 убийц из шайки Скитальцев Пустыни по поручению главного инженера Чепухастера из Прибамбасска.", description = "Теперь тебе придется схватиться с кочевниками посильнее. Ты неплохо <поработал/поработала>, но если отбивать у этих гадов наши колодцы, лучше бы противников было поменьше!\n\nНа сей раз выступи против разбойников, убийц и темных магов. Их можно найти на востоке и юго-востоке отсюда.\n\nНе буду тебе лгать – справиться с ними нелегко. Зато в случае успеха мы очень скоро сможем вернуть себе принадлежащее нам по праву!", progress = "Ну что, удалось одолеть кочевников, о которых я говорил? Все планы Водной компании Прибамбасска зависят от твоего успеха! Не подведи нас...", completion = "Первоклассная работа, Эфром… первоклассная! Число кочевников сократилось настолько, что мы можем бросить им вызов!\n\nТы уже поговорил с оператором крана Тормозиллером? Он предлагает награду за меха с водой, которые могли тебе попасться во время битвы с кочевниками!", rewards = "Вы получите:\n\n"},
[1692] = {title = "Кузнец Матиль", objective = "Отнесите сундук элунита кузнецу Матилю.", description = "Я сложила собранный тобой элунит в сундук. Отнеси его кузнецу Матилю, мы сделаем из него элунитовое оружие.\n\nМатиль на юге отсюда, на другой стороне этого здания.", progress = "Привет тебе, юный воин. Чем могу тебе служить?", completion = "А, элунитовая руда. Работать с этим металлом – одно удовольствие, ведь он благословлен самой богиней Элуной. Выковать элунитовое оружие – великая честь.\n\nПодожди, я сейчас примусь за работу...", rewards = "Вы получите:\n\n"},
[1693] = {title = "Оружие из элунита", objective = "Это оружие я выковал из принесенного тобой элунита. Можешь взять себе любое.\n\nБольшое спасибо. Работать с элунитом – не только удовольствие, но и великая честь.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЭлунитовый топорЭлунитовый молотЭлунитовый кинжалЭлунитовый меч\n\nВы также получите:\n\n"},
[1698] = {title = "Йорус Ячменовар", objective = "Поговорите с Йорусом Ячменоваром.", description = "Йорус Ячменовар бросил вызов всем воинам Альянса. Он ждет в таверне Приозерья, что в Красногорье, и сулит щедрую награду всем, прошедшим испытание.", progress = nil, completion = "Ха! Значит, до тебя дошли вести о моем вызове, а?\n\nЧто ж, садись и слушай. Пей и наслаждайся... Может быть, это твоя последняя выпивка в этой жизни.", rewards = "Вы получите:\n\n"},
[1699] = {title = "Ретбанский вызов", objective = "Войдите в пещеры Ретбана, доберитесь до первой развилки и вернитесь к Йорусу Ячменовару за отведенное время.\n\nВы не должны умирать и освобождать свой дух.", description = "Я называю мое испытание Ретбанским вызовом. Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться. Элементарно! Есть, правда, несколько \"но\"…\n\nВернуться тебе придется в течение часа.\n\nТам полно красногорских гноллов.\n\nПеред тем, как тронуться в путь, тебе придется глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменевец!\n\nЧто скажешь? Пещеры Ретбана находятся в холмах на севере от Озер. Ты <готов/готова> принять Ретбанский вызов?", progress = "Ты теряешь время, Груль. На твоем месте я бы поторопился.", completion = "Ты справился! Молодец! Трижды ура Злорфи!", rewards = "Вы получите:\n\n"},
[1700] = {title = "Гриманд Элмор", objective = "Отнесите записки Фьюрена Гриманду Элмору.", description = "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Гриманду Элмору. Он живет здесь, в Квартале Дворфов, в оружейном магазине. Он гордится своим искусством, и совсем не обрадуется моему открытию...", progress = "Приветствую, добро пожаловать. Чем могу помочь?", completion = "Это написал Фьюрен? Как он смел! Да я его всему сам научил! Яйца курицу не учат! Нахал!\n\nХм-м-м... Но в этих записях что-то есть... Надо попробовать...", rewards = "Вы получите:\n\n"},
[1701] = {title = "Закаленный доспех", objective = "Соберите все необходимые материалы для Фьюрена Длинноборода и отнесите их в Штормград.", description = "Ну вот, я дал тебе отличный щит, но это еще не все. Я знаю секрет изготовления очень прочного доспеха. Это нелегко, и мне потребуются редкие материалы, но если тебе не лень за ними поохотиться, доспех получится несравненный.\n\nЧто скажешь? Если ты не боишься трудностей, я выдам тебе список необходимых материалов и где их искать.", progress = "Как охота на падальщиков? Удалось добыть нужные материалы?", completion = "Тебе удалось добыть все необходимое? Вот это да! Я опасался, что химеры слопают тебя с потрохами!\n\nЧто ж, займемся доспехами...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1702] = {title = "Щитник", objective = "Отнесите бочонок жгучего пива Фьюрену Длиннобороду.", description = "Да, приняв Ретбанский вызов, ты <показал/показала>, на что <способен/способна>. Я свое слово держу. Ты получишь обещанную награду…\n\nТолько она в Штормграде.\n\nПоговори с моим другом, Фьюреном Длиннобородом. Он живет в Квартале Дворфов. Его щиты славятся во всей округе, а мне он должен услугу.\n\nВот, отнеси Фьюрену этот боченок жгучего пива Ячменевца и попроси взамен щит. Он плохого не даст.", progress = "Привет! Меня мучает жажда, а тебя?", completion = "А, жгучее пиво Ячменевца. Отличный напиток! Значит, ты от Йоруса, а?\n\nКонечно я дам тебе щит, да еще какой! Такого нигде не найти, честное слово!", rewards = "Вы получите:\n\nЛюбезность Фьюрена"},
[1703] = {title = "Матиль", objective = "Отнесите Матилю записки Фьюрена.", description = "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Матилю. Он живет довольно далеко, в Дарнассе, но несомненно будет рад, если я поделюсь с ним своими открытиями.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1704] = {title = "Клацморт Гайкокрут", objective = "Отнесите записки Фьюрена Клацморту Гайкокруту.", description = "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Клацморту Гайкокруту. Он живет в Стальгорне, и когда услышит о моем открытии... Он бороду себе выдернет от восторга!", progress = "Добрый день, или утро, или вечер. Какая разница! Ты ко мне по делу?", completion = "Ну и ну! Поразительные записи мне прислали! Больше того... Они ошеломляющие и невероятные, я едва на ногах стою от восторга!\n\nФьюрен совершил прорыв в кузнечном деле! Да-да, самый настоящий прорыв! Мне не терпится испробовать новую технологию!", rewards = "Вы получите:\n\n"},
[1705] = {title = "Пылающая кровь", objective = "Принесите 20 сосудов горящей крови и 1 горящий камень Гриманду Элмору из Штормграда.", description = "Может, этот Фьюрен и совершил открытие, но мне надо проверить, так ли это. Попробую-ка я сделать такие доспехи. Если ты поможешь добыть все материалы, можешь забрать доспех себе.\n\nМне понадобится горящая кровь и горящий камень.\n\nЕдинственное место, где можно добыть эти материалы – Сумеречный лес. Горящая кровь есть у воргенов из стаи Ночной Погибели из пещеры Роланда, а горящий камень хранит у себя их главарь, Кишкодер.\n\nИ не мешкай, во имя Света.", progress = "Ну как, удалось добыть горящую кровь и камень? Без них доспехов не сделаешь.", completion = "Недурно! А теперь, прошу прощения, мне тоже надо поработать...", rewards = "Вы получите:\n\n"},
[1706] = {title = "Доспехи Гриманда", objective = "Глазам своим не верю! Технология Фьюрена оказалась удачной, и этот доспех способен выдержать серьезную нагрузку.\n\nДержи, Ишт. И огромное тебе спасибо. Если бы ты не принес мне все необходимые материалы, я бы так и не поверил в открытие Фьюрина.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗакаленный огнем капюшон"},
[1707] = {title = "Награда за воду", objective = "Принесите 5 бурдюков Скитальцев Пустыни оператору крана Тормозиллеру в Прибамбасск.", description = "Привет тебе, <имя>. Меня зовут Живец, и у меня есть для тебя важная работа! Ура!\n\nЯ опытный оператор крана, и ничто не порадует меня так, как бурдюки с водой Скитальцев Пустыни, которые могут попасться тебе в пустыне, у кочевников. Все равно это наша вода – мерзкие кочевники ее украли! Водная компания Прибамбасска предлагает в награду полевой набор за каждые пять бурдюков. А главное, ты поможешь Прибамбасску!", progress = "Ты принес все пять бурдюков? Если да, то лечебный набор Водной компании Прибамбасска, модель 103-ХВ, твой!", completion = "Великолепно! Чем больше мехов с водой нам удастся добыть, тем ниже вероятность катастрофы! Можешь таскать их сотнями, и за каждые пять будешь получать все ту же награду.", rewards = "Вы получите:\n\nПолевой набор Водной компании Прибамбасска"},
[1708] = {title = "Железный коралл", objective = "Принесите 20 партий выжженного коралла Клацморту Гайкокруту в Стальгорн.", description = "Я хочу опробовать технологию Фьюрена Длинноборода на собственных доспехах. Раз ты <помог/помогла> Фьюрену, а он мне, я разрешу тебе забрать их себе!\n\nЧтобы довести работу до конца, мне необходим особый коралл, выжженный. Он растет лишь в одном месте, вдоль побережья Гавани Менетилов в Болотине.\n\nПринеси мне побольше таких кораллов, и я примусь за работу. И поторапливайся, <имя>, у меня руки чешутся, так хочется взяться за дело.", progress = "Привет-привет, Даски! Ты несешь мне выжженные кораллы? Мне не терпится взяться за работу!", completion = "Вот, то что нужно! Молодец! А теперь дай-ка я их расплавлю и расплющу. Попробую совместить технологию Фьюрена с моей, и посмотрим что из этого выйдет!\n\nНу-ну, я предчувствую, что доспехи получатся очень-очень-очень прочные!", rewards = "Вы получите:\n\n"},
[1709] = {title = "Творение Клацморта", objective = "Вот твои доспехи, Бронетазик. Идея Фьюрена отлично сработала. Идеально! Чудесно, если правду сказать!\n\nПо этой броне можно осадные орудия прокатить, и она сохранит форму!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗакаленные огнем рукавицы"},
[1710] = {title = "Высохшая скорлупа", objective = "Принесите 20 кусков высохшей на солнце скорлупы Матилю из Дарнасса.", description = "Мой коллега, Фьюрен Долгобород, совершил многообещающее открытие. Я хотел бы испытать его на новых доспехах, мне кажется, результат превзойдет все ожидания.\n\nНе поможешь? Если ты принесешь мне все необходимые материалы, я и для тебя сделаю такие доспехи.\n\nМне понадобится высохшая на солнце скорлупа яиц виверн Скального Гнездовья из Тысячи Игл. Скорлупу можно найти под их гнездами. Как наберешь достаточно, возвращайся.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1711] = {title = "Доспехи Матиля", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗакаленные огнем поножи"},
[1712] = {title = "Циклониан", objective = "Принесите Бат'ра Ветростражу все предметы из его списка.", description = "Я давно наблюдаю за этими местами, в надежде дожить до падения великого Циклониана. Увы, мне до сих пор не встретился герой, готовый схватиться с повелителем ветра.\n\nМожет быть, этим героем окажешься ты?\n\nДокажи, что ты великий воин – собери все предметы, необходимые для призыва Циклониана. Тогда, быть может, тебе удастся одолеть его и завладеть сердцем Вихря.\n\nЕсли это свершится, я вложу силу сердца в оружие и вручу его тебе.\n\nВот список нужных компонентов.", progress = "Ты уже все собрал, Wrestlecake? Принеси все компоненты, иначе я не поверю, что тебе хватит сил одолеть Циклониана.", completion = "Ты сумел собрать все необходимое для заклинания призыва, доказав тем самым свою силу и ловкость. Но следующий шаг будет гораздо опаснее.\n\nБудем надеяться, что сила тебя не покинет.", rewards = "Вы получите:\n\n"},
[1713] = {title = "Призыв", objective = "Отнести сердце Вихря Бат-ра Ветростражу.", description = "Я готов провести ритуал призыва Циклониана. Потом тебе предстоит победить его и забрать у него из груди сердце Вихря. После этого я создам оружие, которое вберет в себя силу Циклониана.\n\n<имя>, <готов/готова> ли ты выступить против повелителя ветра?", progress = "Wrestlecake, мне нужно сердце Вихря!", completion = "Ты справился! Циклониан повержен, а у тебя в руках сердце Вихря!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1714] = {title = "Субстанция Изгнанников", objective = "Котел бурлит, и его пары так и манят...", description = nil, progress = "Котел бурлит, и его пары так и манят...", completion = "Обереги медленно опускаются на дно котла…\n\nИз глубины поднимается большой пузырь воздуха, лопается и…\n\n... на поверхности оказывается оплавленный камень.", rewards = "Вы получите:\n\nСубстанция Изгнанников"},
[1715] = {title = "Забитый ягненок", objective = "Обратитесь к Гакину Темнопряду в квартал магов Штормграда.", description = "Хмм. В прежние времена все чернокнижники Каз Модан обучались под присмотром мастеров Гномрегана, но теперь, когда все мы вынуждены ютиться в этой крысиной норе под названием Стальгорн и Магни решил не спускать с нас глаз, нам приходится отсылать наших новичков на обучение в Штормград.\n\nПо счастью, Гакин не растяпа, так что ты все равно узнаешь все, что тебе надо, но я просто киплю!\n\nКороче, ты найдешь Гакина в подвале \"Забитого ягненка\" в Штормграде.", progress = nil, completion = "Так тебя послал Зловещая Отвертка? Нет, пора бы уже этим стальгорнским растяпам как-то разобраться с ситуацией. Штормград не резиновый, и наставников тут сколько есть, и не больше. Если сюда повалит народ, то рано или поздно мы привлечем к себе внимание.", rewards = "Вы получите:\n\n"},
[1716] = {title = "Пожирательница душ", objective = "Поговорите с Такаром Провидцем в Степях.", description = "Сайаады – пожиратели душ, подавляющие волю и вводящие в искушение. Порождение чистого зла.\n\nВ легкомысленных историях этих демонов называют суккубами, если речь о женщинах, и инкубами, если это мужчины.\n\nПримани демона символом любви, победи его – и он будет тебе служить.\n\nНо найти подходящий символ непросто. Поговори с Такаром Провидцем. Ты найдешь его в калимдорских Степях возле лагеря Таурахо.", progress = nil, completion = "Вйнсент, как вы добрались? Вы проделали долгий путь, чтобы поговорить со мной. Но не бойтесь: я знаю, зачем Гакин прислал вас. Это было мудро с его стороны, потому что я могу вам помочь.", rewards = "Вы получите:\n\n"},
[1717] = {title = "Приглашение Гакина", objective = "Обратитесь к Гакину Темнопряду в квартал магов Штормграда.", description = "<имя>! Не ожидал увидеть тебя в этих краях, но мне велели за тобой приглядывать.\n\nТы давненько уже не <проходил/проходила> очередного обучения, так что тебе следует зайти к Гакину, когда в следующий раз будешь в Штормграде. Он будет тебя ждать.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1718] = {title = "Островитянин", objective = "Поговорите с Кланноком Маклеодом.", description = "Ты становишься недурным воином, <имя>. Пришло время помериться силой с братьями по оружию.\n\nНедалеко от побережья Степей, к югу от Кабестана, есть остров. Он называется Островом Битв. Это место встречи воинов.\n\nМесто встречи и дружеских схваток.\n\nПоговори со старшим воином острова, Кланноком Маклеодом. Если он сочтет тебя достойным дальнейшего обучения, то поможет тебе сделать очередной шаг на пути воина.\n\nДо Острова Битв можно добраться по песчаной отмели вдоль Торгового побережья.", progress = nil, completion = "Привет тебе, воин. Хорошо, что тебе удалось добраться до Острова Битв. Надеюсь, он тебе нравится...", rewards = "Вы получите:\n\n"},
[1719] = {title = "Побоище", objective = "Убейте Большого Билла и поговорите с Кланноком Маклеодом на Острове Битв.", description = "Если ты хочешь учиться у меня, тебе придется пройти испытание, Побоище. Через него проходят все молодые воины, вообразившие себя великими. А величие надо доказывать.\n\nДля начала пройди сквозь ту толпу и встань на решетку. Это будет знак Пруттику Плоскоголову, что ты готов. Он сразу пошлет тебе поединщика.\n\nКогда ты одолеешь всех, он позовет Большого Билла. Убей его и вернись ко мне за отведенное время.", progress = "Ты уже прошел испытание?", completion = "Молодец, Wrestlecake. Ты прошел испытание Побоищем!\n\nТы могучий воин, и учить тебя – великая честь...", rewards = "Следующее заклинание будет наложено на вас:\n\nПуть берсерка\n\nВы получите:\n\n"},
[1738] = {title = "Сердцедрево", objective = "Раздобудьте в Ясеневом лесу сердцедрево и принесите его Гакину Темнопряду в Квартал магов Штормграда.", description = "Готовясь к твоему приходу, я на скорую руку оглядел весь мир, проник взглядом сквозь пелену времени и нашел то, что тебе нужно.\n\nВо время Войны Древних двое влюбленных вместе пали в битве. Там, где перестали биться их сердца, выросло дерево, известное как сердцедрево – символ их бессмертной любви.\n\nЭтого должно быть достаточно, чтобы привлечь суккуба. Руины Ордиль-Арана, где растет сердцедрево, находятся в северо-западной части Ясеневого леса.", progress = "Как проходят поиски, Вйнсент?", completion = "Да, сердцедрево нам подойдет. Дай-ка я немного обработаю древесину...\n\nТакар – настоящий кладезь премудростей; с таким не пропадешь, правда? Если б я только мог убедить его вернуться к цивилизации...", rewards = "Вы получите:\n\n"},
[1739] = {title = "Связывание", objective = "Призовите и подчините суккуба, используя сердцевину сердцедрева, затем верните сердцевину сердцедрева Гакину Темнопряду. Он будет ждать вас в \"Забитом ягненке\".", description = "С помощью сердцевины сердцедрева ты сможешь открыть портал и призвать суккуба в круг призыва. Круг находится в подвале.\n\nНе забывай об осторожности, <имя>, суккубы подчиняли себе и самых стойких заклинателей.\n\nПосле того как вызовешь демона и вернешь его обратно в Бездну, возвращайся ко мне и я научу тебя, как обращаться с суккубом.", progress = "Иногда я удивляюсь, как же Сурена, которая не была суккубом, ухитрилась так заморочить мне голову? Эх... Может быть, дело и не только в ней...", completion = "Неплохо, Вйнсент, неплохо... Я не ошибся, когда решил обучать тебя. Твои успехи меня не разочаровывают.\n\nПора научить тебя обращению с только что подчиненным суккубом. Только не забывай про осторожность!", rewards = "Вы изучите:\n\nПризыв суккуба\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание суккуба\n\nВы также получите:\n\nМалая сума душ"},
[1740] = {title = "Шар Соран'рука", objective = "Соберите 3 фрагмента Соран'рука и 1 большой фрагмент Соран'рука и принесите их Доану Кархану в Степи.", description = "Когда демоны Легиона попадают в немилость, их души заключают в сферы и раздают магам и чернокнижникам.\n\nМногих из них носили на Азероте их слуги. Даже расколотые на части, эти сферы хранят в себе силу демонов, заключенных внутри. Шар Соран'рука был расколот надвое. Одну из частей раздробили на еще более мелкие фрагменты послушники Сумеречного Молота в Непроглядной Пучине. А другая, большая часть, досталась волшебнику из крепости Темного Клыка. Найди их, и я смогу воссоздать этот шар.", progress = "Мне понадобилось много лет, чтобы собрать все части сферы Заргейна, но она служит мне верой и правдой, как будет служить тебе шар Соран'рука", completion = "Да... Этот шар не так уж сильно раскололи, и передо мной почти все осколки. Воссоздать их, сделав Соран'рука единым целым, несложно.\n\nЯ посвятил всю жизнь изучению и восстановлению сфер Пылающего Легиона. Ты оказал мне большую услугу, позволив изучить эти осколки, и я верну их тебе, полностью восстановив, придав им любую форму по твоему выбору.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСфера Соран'рукаПосох Соран'рука\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[1758] = {title = "Фолиант Заговора", objective = "Поговорите с Кромом Крепкоруком в Стальгорне.", description = "Простой круг призыва не поможет тебе вызвать на бой охотника скверны.\n\nЯ и трое моих послушников поможем тебе создать магические круги. Тебе также понадобится фолиант Заговора, который мы давно утратили. Его написала первая группа чернокнижников, умудрившихся вызвать охотника скверны без посторонней помощи.\n\nС этим тебе поможет Крому Крепкоруку. Теперь он – главный чернокнижник, и целыми днями он сидит в библиотеке Стальгорна, оберегая древние тексты.", progress = nil, completion = "Фолиант Заговора? Хм-м... Знакомое название. Я его никогда не видел – а уж поверьте, я помню все прочитанные книги.\n\nХм…\n\nА, да! Я видел ссылки на этот фолиант в библиотечных каталогах.", rewards = "Вы получите:\n\n"},
[1778] = {title = "Фолиант Божественности", objective = "Поговорите с Тизой Кузнебой в Стальгорне.", description = "Я намереваюсь скоро вернуться домой. Надеюсь, у Стефани в Штормграде дела идут хорошо. Не терпится снова увидеться с ней. До следующей встречи, <класс>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1779] = {title = "Фолиант Божественности", objective = "Возьмите знак жизни и поговорите с Майридоном Кузнебоем в Стальгорне.\n\nПрилагается предмет: \n", description = "Я хочу, чтобы ты <взял/взяла> это, <имя>. Это называется знак Жизни.\n\nТы <показал/показала> свое милосердие и терпение, а теперь я хочу, чтобы ты <проявил/проявила> себя не только как воин, но и как <целитель/целительница>.\n\nМой супруг Майридон Боевая Кузня недавно вернулся после стычки с дворфами Черного Железа. Он едва ноги унес – сейчас лечит свои раны у одного из наших жрецов.\n\nВозьми Символ и поговори с ним. Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор. Да пребудет с тобой Свет.", progress = nil, completion = "*кашляет*\n\nДоброго тебе здравия, |3-6(Паладин). Не волнуйся о моих ранах, добрый жрец сумеет вылечить Майридона. Так что сила твоего знака Жизни пока мне не нужна.\n\nЗначит, моя женушка тебя послала потолковать со мной, да? Славно, славно. У меня найдется времечко поговорить с тобой, я расскажу тебе в точности, что произошло с Майридоном и его лучшим другом Нармом, паладином вроде тебя.", rewards = nil},
[1780] = {title = "Фолиант Божественности", objective = "Найдите в Штормграде Даториана Ралла и поговорите с ним.", description = "Я сегодня же отнесу это детям. Ты можешь не тревожиться, <класс>. Конечно, такие, как ты, нечасто показываются в городе, но ты без сомнения <доказал/доказала>, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается.\n\nДоброго пути!", progress = nil, completion = "Ты уже здесь, Мэйнард? Однако, странствия заняли у тебя не так много времени, как я полагал. И что же тебе удалось свершить за время, проведенное вдали от Храма? Может быть, тебе довелось сражаться за справедливость? Или удалось постичь смысл милосердия? Или помочь кому-либо из нуждающихся жителей Азерота? Расскажи мне все...\n\nЧто ж, Мэйнард, это производит впечатление. Поверь, это поистине поступки того, кто следует путем Света и ставит благо других выше своего собственного.\n\nРано или поздно такое самопожертвование всегда вознаграждается.", rewards = "Вы получите:\n\n"},
[1781] = {title = "Фолиант Божественности", objective = "Отнесите знак Жизни Газину Тенорму в Штормград.\n\nПрилагается предмет: \n", description = "Прими этот знак Жизни, <имя>.\n\nТебе удалось обрести милосердие и терпение: пришло время узнать, хватит ли у тебя сил, чтобы воспользоваться одним из величайших даров Света. \n\nМой друг Газин недавно вернулся из Элвиннского леса с острова Героев, где он едва не расстался с жизнью после стычки с магами Братства Справедливости. Сейчас он у алтаря: надеюсь, служителям удастся исцелить его раны.\n\nВозьми этот Символ и поговори с Газином. Если сумеешь помочь ему, мы продолжим нашу беседу. Да пребудет с тобой извечный Свет!", progress = nil, completion = "*кашляет*\n\nЯ рад встрече с тобой, |3-6(Паладин). Не обращай внимания на мои раны: добрые служители Света смогут обо всем позаботиться. Сила знака Жизни, которого ты держишь в руках, мне без надобности... по крайней мере пока.\n\nЗначит, Даториан послал тебя поговорить со мной, да? Что ж, это правильно. Я тебе расскажу, что случилось со мной и моим другом Хензом. Если нам повезет и тебе хватит сил и умения, ты еще сможешь всех нас спасти...", rewards = nil},
[1782] = {title = "Доспехи Фьюрена", objective = "Вот твои доспехи, Ишт. Они выдержат любой удар, не будь я Фьюрен Длиннобород!\n\nИ спасибо большое. Я многому научился, работая с принесенными тобой материалами. Думаю, в один прекрасный день я совершу новое открытие!\n\nА результаты этого я отправлю другим кузнецам Альянса.\n\nЯ скажу им, что ты мне очень помог, может быть, они тоже решат отблагодарить тебя.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗакаленный огнем хауберк"},
[1783] = {title = "Фолиант Божественности", objective = "Возьмите знак Жизни и воскресите Нарма Фолка в Дун Мороге.", description = "Мы выслеживали дворфов Черного Железа, что окопались к югу от озера Хельмово Ложе. Мы знали, что они затевают недоброе, потому мы с Нармом решили подобраться поближе, чтобы посмотреть, как их капитан раздает приказы своим воинам.\n\nМы с Нармом воспользовались случаем и пристукнули нескольких, но они оказались крепче, чем мы думали, и набросились на нас толпой. Нарм велел мне бежать за помощью, и вот я здесь.\n\nНарму нужна помощь. И я не успокоюсь, пока он ее не получит.\n\nТы ведь поможешь ему, <имя>?", progress = nil, completion = "Не знаю, как мне отблагодарить тебя, брат!\n\nВидать, тебя прислали мне в подмогу Тиза с Майридоном, раз на тебе знак Жизни.\n\nДа, это правда, я пал в бою с дворфами Черного Железа, пытаясь получить одну из их бумаг. Я довольно долго продержался и дал Майридону уйти, но я почти уже погрузился в Свет, когда ты появился. То, что тебе хватило мощи воспользоваться знаком, очень многое значит, но мы поговорим об этом позже.", rewards = "Вы получите:\n\n"},
[1784] = {title = "Фолиант Божественности", objective = "Добудьте приказ клана Черного Железа у дворфов из клана Черного Железа возле Хельмова Ложа и вернитесь к Майридону Кузнебою в Стальгорн.", description = "Прежде чем я пал в бою, мы с Майридоном почти одолели одного из соглядатаев из клана Черного Железа возле того небольшого домика. Мы видели, как их капитан раздавал им бумаги с приказами, и хотели убить его и забрать эти бумаги.\n\nКое-кто в совете Стальгорна до сих пор не верит в присутствие дворфов Черного Железа в Дун Морог. Захватив одну из этих бумаг, мы не только получим доказательства их вылазок, но и поймем, что они затевают.\n\nДобудь один из приказов и отнеси Майридону, <имя>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1785] = {title = "Фолиант Божественности", objective = "Поговорите с Тизой Кузнебой в Стальгорне.", description = "Вижу, моя женушка прямо пышет гордостью. Я бы на твоем месте поскакал прямо к ней. Сдается, она хочет перекинуться с тобой парой слов.\n\nДа хранит тебя Свет, <славный/славная:c> <класс>. Я буду искать тебя на поле боя против Плети и клана Черного Железа, когда придет пора.", progress = nil, completion = "Сегодня ты оказал большую услугу Стальгорну, Хорнфел. Я горда, что ты среди нас, и если ты готов, я хотела бы благословить тебя этим свитком. Знак Жизни подействовал бы только в руках паладина, готового принять одну из самых великих благостей Света, – силу возвращать умерших к жизни.\n\nЯ научу тебя возрождать к жизни твоих соратников. Используй это умение мудро, Хорнфел, и прими благодарность от меня, моего мужа и всего Стальгорна.", rewards = "Вы изучите:\n\nИскупление\n\nСледующее заклинание будет наложено на вас:\n\nИскупление\n\nВы также получите:\n\n"},
[1786] = {title = "Фолиант Божественности", objective = "Возьмите знак Жизни, пойдите в Элвиннский лес и воскресите Хенза Фолка.", description = "Мы с Хензом добрались до острова Героев – он находится посреди Озера Каменных Столбов, в северо-восточной части Элвиннского леса. Мы слышали, что Братство Справедливости проникло в наши земли, и должны предоставить доказательства этого вторжения королевским советникам.\n\nМы засекли двоих из этих подонков, когда они просматривали кое-какие документы, и напали на них. Увы, магов было больше, и нас заставили отступить.\n\nХенз прикрывал меня, и мне удалось бежать... проклятый глупец, отвагу проявить решил!..\n\nИ вот он там так и остался. Хенз, я имею в виду. Может, ты сумеешь помочь, <имя>?", progress = nil, completion = "Прими мою благодарность, брат.\n\nВ твоих руках я вижу знак Жизни – тебя послал Даториан или Газин.\n\nМы с Газином пытались похитить планы Братства Справедливости, но на нас напали их чародеи. Мне удалось продержаться достаточно долго для того, чтобы Газин успел скрыться, но в конце концов я был побежден...\n\nНо тебе удалось вернуть меня – а далеко не всем дана способность управлять знаком Жизни, Мэйнард, можешь мне поверить. Это свидетельство крепости твоей веры...", rewards = "Вы получите:\n\n"},
[1787] = {title = "Фолиант Божественности", objective = "Найдите волшебников из Братства Справедливости в Элвиннском лесу, заберите у них бумаги и отнести Газину Тенорму в Штормград.", description = "У нас еще будет время поговорить о Символе. Сейчас важнее заполучить те бумаги, которые мы видели у Братства Справедливости. Если бумаги будут у нас, мы сможем доказать, что братство проникло в Элвиннский лес – а может, и узнать что-нибудь о его планах.\n\nУвы, <имя>, навряд ли я сейчас могу считаться воином. Сможешь ли ты пойти в бой в одиночку? Сумеешь ли ты добыть то, что нам так необходимо?\n\nЕсли это тебе удастся, отнеси бумаги Газину и сообщи ему, что со мной все хорошо.", progress = "А, это ты, Мэйнард? С Хензом все в порядке? Тебе удалось добиться успеха?\n\nЯ вижу, острову Героев не страшно никакое братство, пока в твоих руках оружие, а с нами пребывает сила Света. Однако решение за королем и его советниками...", completion = "Великолепно! Тебе удалось спасти Хенза и выполнить задание. Теперь я знаю: воистину, Свет озаряет твой путь, Мэйнард!", rewards = "Вы получите:\n\n"},
[1788] = {title = "Фолиант Божественности", objective = "Найдите в Штормграде Даториана Ралла и поговорите с ним.", description = "После того как Даториан ознакомится с этими бумагами, я передам их королевским советникам; однако прежде тебе стоит поговорить с Даторианом. Думаю, он тоже хотел бы поблагодарить тебя.\n\nТвоя помощь поистине неоценима, <имя>. Надеюсь, это не последняя наша встреча. Я горжусь нашей дружбой.", progress = nil, completion = "Что ж, Мэйнард, полагаю, ты можешь гордиться своими свершениями.\n\nСкажу больше: ты можешь также гордиться своими способностями. Далеко не каждый может использовать силу, которой наделен знак Жизни. Если в твоих силах призвать исцеляющую силу Света, ты достоин того, чтобы принять величайший дар паладинов, – дар воскрешения.\n\nТы сможешь возвращать к жизни павших спутников так же, как вернул к жизни Хенза.\n\nГорний Свет озарил тебя, Мэйнард, открой же ему душу.", rewards = "Вы изучите:\n\nИскупление\n\nСледующее заклинание будет наложено на вас:\n\nИскупление\n\nВы также получите:\n\n"},
[1789] = {title = "Знак Жизни", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗнак жизни"},
[1790] = {title = "Знак Жизни", objective = "Поспеши, Болвар! Слишком много жизней зависит от твоего успеха или неудачи.\n\nЕсли ты не сумеешь помочь Газину и Хензу, возвращайся: я дам тебе новый знак Жизни.\n\nНе думай, что я помогаю тебе просто так, нет: тебе, как и всякому другому паладину, нужно доказать, что ты достоин своего звания. Постоянные неудачи – не лучшая рекомендация...", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗнак жизни"},
[1791] = {title = "Ветростраж", objective = "Поговорите с Бат'ра Ветростражем.", description = "Что ж, ты <освоил/освоила> стойку берсерка, теперь нужно подобрать тебе оружие.\n\nПоговори с Бат'ра Ветростражем, троллем-отшельником, живущим между Альтеракскими горами и Западными Чумными землями. Он опытный оружейник и могущественный шаман.\n\nЕсли ты захочешь встретиться с Бат-ра, отправляйся к реке, что течет вдоль восточного края мельницы Таррен. Иди вдоль нее на север – Бат'ра разбил лагерь рядом с руинами на берегу реки.", progress = nil, completion = "Тебе пришлось проделать долгий путь, юный воин. Как у тебя горят глаза! Тебе ведь нужно мощное оружие?\n\nЯ помогу тебе... в обмен на твою помощь.", rewards = "Вы получите:\n\n"},
[1792] = {title = "Оружие Смерча", objective = "У меня есть сердце Вихря, и я могу подобрать ему вместилище по твоему выбору.\n\nВозьми любое оружие, и знай, что его сила – сила Циклониана.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТопор СмерчаМеч СмерчаБоевой молот Сердца Вихря\n\nВы также получите:\n\n"},
[1793] = {title = "Фолиант Отваги", objective = "Теперь доказано, что ты – приверженец сил Света, Палинус, но времена наступают все более опасные, и поэтому важно знать, какая сила скрывается в твоем сердце. Когда демоны, драконы или какое другое зло ступят на нашу землю, тогда и подвергнется испытанию твой дух. Достанет ли у тебя сил?\n\nХрабрость в любой ситуации – такая же неотъемлемая часть сущности паладина, как Свет, доспех и оружие. Необходимость защищать слабых и не терять веры – вот еще два урока, которые ты должен усвоить, пока проходишь обучение в Соборе Света.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nФолиант Отваги"},
[1794] = {title = "Фолиант Доблести", objective = "Что же, теперь нет сомнений, что благодать Света пребывает с тобой, Отхилюотпорю, но чем опаснее времена, тем важнее знать, какую силу скрывает плоть. Когда на твои земли ступят демоны, драконы или иное зло, твоя доблесть подвергнется испытанию. Достанет ли тебе сил?\n\nНе бывает паладина без отваги в любой ситуации, как не бывает паладина без Света, доспеха и оружия. Защищай слабых, не теряй веры – вот два урока, которые тебе следует усвоить во время обучения в Соборе Света.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nФолиант Отваги"},
[1795] = {title = "Связывание", objective = "Призовите и одолейте охотника скверны при помощи фолианта Заговора и верните фолиант Страхаду Фарсану из Кабестана.", description = "Если ты <готов/готова>, давай приступим. Начну с объяснений.\n\nСначала мы создадим основной круг призыва. После этого мои послушники создадут больший круг при помощи жезлов направления.\n\nЗатем ты прочтешь заклинание из фолианта Заговора, и на зов явится охотник Скверны. Будь <осторожен/осторожна>, <имя>. Охотник Скверны – сильный враг, не теряй головы.", progress = "Каждый чернокнижник должен иметь в своем распоряжении охотника скверны. Хотя их сложно приручить, обретенное могущество стоит затраченных усилий.", completion = "Впечатляюще, Терраформ. Когда я сражался с охотником скверны, то едва выжил. Предчувствую, что ты станешь одним из сильнейших чернокнижников нашей эры.", rewards = "Вы изучите:\n\nПризыв охотника Скверны\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание охотника Скверны\n\nВы также получите:\n\nКоробка душ"},
[1796] = {title = "Материалы для зачарованной золотой кроводежды", objective = "Принесите одеяния Аркана Менаре Расщепительнице Бездны в Степи.", description = "Первым делом я помогу тебе создать одеяние. Ты принесешь мне несколько необходимых составляющих, а уж работать над ними будем вместе. В итоге, если ты справишься, разумеется, ты получишь первый из многих предметов, которые одарят тебя могуществом и помогут в борьбе против сил Тьмы.\n\nДля начала тебе нужны одеяния Аркана. Их может сшить портной или их можно купить... еще лучше сделать их самому, но это сложно. Короче, для начала принеси мне эти одеяния.", progress = "Как идут поиски одеяния, Блок? Удалось создать его самостоятельно? Когда делаешь что-то сам, куда приятнее наполнять этот предмет магией. Получаешь большее удовлетворение. Но я пойму, если ты предпочтешь более легкий путь – заказать одеяние. Подобная... целеустремленность тоже хороша.", completion = "То, что нужно, Блок.\n\nВ основе всех волшебных предметов должна лежать вещь высокого качества. Чем больше усилий и искусства вложить в предмет, тем легче напитать его магией. Редкие и дорогие составляющие также лучше держат магию. Не жалей об утрате этого одеяния: когда мы закончим, оно станет куда лучше.", rewards = "Вы получите:\n\n"},
[1798] = {title = "В поисках Страхада", objective = "Поговорите со Страхадом Фарсаном в Степях.", description = "Пришло время научить тебя вызывать охотника скверны, <имя>. Здесь у меня нет ни реагентов, ни предметов, необходимых для обучения, так что придется тебе найти другого учителя – Страхада Фарсана.\n\nОн проживает в гоблинском порту Кабестане. Я извещу его о том, что ты появишься.", progress = nil, completion = "Блок? Ах да, конечно. Наше новое чудо. Но, боюсь, настоящее чудо вряд ли успеет стать легендой при жизни.\n\nВпрочем, неважно – ты здесь для того, чтобы пройти обучение, а не слушать, как я шучу сам с собой.", rewards = "Вы получите:\n\n"},
[1799] = {title = "Части шара Орахила", objective = "Поговорите с послушниками Менары в башне над Кабестаном и изберите свой путь.\n\nПосле этого принесите Табете в Пыльную трясину сферу Подземного огня.", description = "Отлично, приступим.\n\nПервым делом ступай внутрь и поговори с моими послушниками. Тебе предстоит избрать свой путь – они объяснят подробнее.\n\nПотом придется отправиться в Пустоши и отыскать сферу Подземного огня у одного из чернокнижников Поля Маннорок. Именно эту сферу необходимо очистить при помощи мага по имени Табета в южной части Пылевых топей. Она поможет тебе ради меня.\n\nИ не возвращайся, пока не выполнишь оба задания.", progress = "Ты явно не маг, и я не уверена, что тебе можно доверять. Я ощущаю в тебе колдовскую силу, но кажется, тебя не затронула скверна, столь легко берущая верх над вашим братом.\n\nДа, |3-6(Чернокнижник)… |3-6(Чернокнижник) пришел просить меня о помощи.\n\nИтак, что тебе нужно, Свояк?", completion = "А, так тебя послала Менара. Ну, хорошо... Располагайся, чувствуй себя как дома. Впрочем, ты, должно быть, спешишь? Быть может, ищешь утраченную силу? Может, я ошибаюсь, и скверна все же коснулась тебя.", rewards = "Вы получите:\n\n"},
[1800] = {title = "Тронный зал Лордерона", objective = "Отведите своего подопечного в старый тронный зал Лордерона, который находится как раз у входа в Подгород.", description = "Если мы хорошо себя ведем, то попечительницы сирот рассказывают нам на ночь сказки про славные сражения и про мирные времена. В одной из легенд говорилось о том, как пал Лордерон и как злобный Артас отнял жизнь у собственного отца, чтобы захватить трон.\n\nБесчестный человек! Когда я вырасту и стану великим воином Орды, мной будет править лишь закон чести, а не зло!\n\nПокажи мне его тронный зал! Он находится как раз перед входом в Подгород.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1801] = {title = "Фолиант Заговора", objective = "Поговорите с Джорахом Аннисоном в Подгороде.", description = "Простой круг призыва не поможет тебе вызвать на бой охотника Скверны.\n\nЯ и трое моих послушников поможем тебе создать магические круги. Тебе также понадобится фолиант Заговора, который мы давно утратили. Его написала первая группа чернокнижников, умудрившихся вызвать охотника Скверны без посторонней помощи.\n\nС этим тебе поможет Йорах Аннисон. Он работает в Подгороде картографом, но все равно знает о древних текстах куда больше моего.", progress = nil, completion = "Картография! Картинки, далекие от реальности. Они мне не нужны. \n\nКниги – повествование, описание! В них и только в них следует искать правду. Я обменял бы все свои карты на одну книгу о возвышении некромантии или сагу о торжестве Темной Госпожи.", rewards = "Вы получите:\n\n"},
[1802] = {title = "Фолиант Заговора", objective = "Добудьте заплесневелый фолиант и потрепанный манускрипт для Крома Крепкорука из Стальгорна.", description = "Он был утрачен, но есть кое-какие соображения насчет того, где он может находиться сейчас.\n\nС него сделали только одну копию и отнеслись к ней совершенно по-варварски: большая часть книги была вырвана из переплета. Ходят слухи, что она каким-то образом попала в руки одного кентавра из Тысячи Игл.\n\nОстальное было утрачено в прибрежных краях к западу от Южнобережья, откуда книгу должны были переправить морем в Гавань Менетилов. Судно так и не прибыло.\n\nА за мои сведения я попрошу одно: когда найдешь книгу, дай мне заглянуть в нее хотя бы одним глазком.", progress = "Так слухи оказались верны, Терраформ?", completion = "С ума сойти! Теперь я один из немногих, что сумел хоть мельком заглянуть в нее.\n\nНе терпится повнимательнее изучить этот текст. Какой великий день, Терраформ! Позволь мне еще раз заглянуть в нее прежде, чем уйдешь. Уверен, что Страхад охотно пришлет мне копию.", rewards = "Вы получите:\n\n"},
[1803] = {title = "Фолиант Заговора", objective = "Отыщите заплесневелый фолиант и потрепанный манускрипт для Йораха Аннисона из Подгорода.", description = "А! Вижу, наши вкусы сходятся. Поиски фолианта Заговора – достойное занятие. Знаешь ли ты, что он некогда хранился в стенах Лордерона? Правда, эти варвары поглумились над ним, вырвали больше половины страниц. Кто мог совершить такую мерзость?\n\nИтак, половина потеряна, хотя говорят, будто она попала в руки кентавров из Тысячи Игл.\n\nОстальную часть должны были перевезти в Стальгорн, но она потерялась при перевозке где-то на берегу озера к западу от Южнобережья.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[1804] = {title = "Фолиант Заговора", objective = "Принесите восстановленный Фолиант Заговора и три жезла направления Страхаду Фарсану в Кабестан.", description = "Как же не хочется его выпускать из рук! Но ты его <нашел/нашла> и, конечно же, свершишь при его помощи куда более важные дела. Только, сделай милость, не забудь сказать Страхаду, что я хочу получить копию.\n\nПока тебя не было, он прислал для тебя письмо. Он пишет, что для призыва духов необходимо достать три жезла направления.\n\nОн-то не знает, где их искать, но зато я знаю! Последний раз их использовали орки клана Драконьей Пасти в Болотине. Я бы поискал у их заклинателей!", progress = "Давно не видел тебя здесь. Ты нашел фолиант и жезлы?", completion = "Отлично! Фолиант Заговора и три практически нетронутых жезла направления.\n\nЗабавно выходит. Давно молодые чернокнижники не приручали охотников Скверны.", rewards = "Вы получите:\n\n"},
[1805] = {title = "Фолиант Заговора", objective = "Принесите восстановленный фолиант и три жезла направления Страхаду Фарсану в Кабестан.", description = "Это один из самых интересных текстов, что мне приходилось изучать за последние несколько лет. Выбор здесь небогат – большинство книг посвящено географии, и я все до дыр зачитал. Надеюсь, Страхад пришлет мне копию.\n\nКстати, он прислал весточку, пока тебя не было. Чтобы выполнить очередную задачу, тебе понадобится три жезла направления.\n\nВ благодарность за то, что ты <дал/дала> мне взглянуть на этот текст, открою тайну: жезлы можно найти у орков клана Драконьей Пасти в Болотине.", progress = "Да, Ариакан? Чем я могу тебе помочь?", completion = "Отлично! Фолиант Заговора и три практически нетронутых жезла направления.\n\nЗабавно выходит. Давно молодые чернокнижники не приручали охотников Скверны.", rewards = "Вы получите:\n\n"},
[1806] = {title = "Испытание доблести", objective = "Подождите, пока Джордан Стилвелл не закончит изготовление оружия.", description = "Почему бы нам не пойти прямо в кузню и не начать работу? Я уже ждал тебя и подготовился, так что времени это много не займет.\n\nКогда все будет закончено, ты будешь гораздо лучше <подготовлен/подготовлена> к защите дела Света, уж за это я ручаюсь.\n\nНе утаю, <имя>, я даже немного завидую твоим деяниям. Но осознание того, что я по-своему помогу тебе, и немало помогу, все же радует меня.", progress = nil, completion = "Вот оно, Гельевич. Оружие, достойное защитника Света вроде тебя. Я дал ему имя в честь великого дворфского паладина, моего друга. Его звали Вериган... Бош Вериган. Прошу, прими его в благодарность от меня и моей жены. Мы очень обязаны тебе. Мир станет лучше, если по земле ходят такие, как ты!", rewards = "Вы получите:\n\nБоевая перчатка Веригана"},
[1818] = {title = "Разговор с Диллинджером", objective = "Поговорите со стражем смерти Диллинджером в Брилле.", description = "Мне сказали, что у стража смерти Диллинджера есть работа для таких, как ты. Если ты хочешь доказать свою ценность Темной Госпоже, немедленно отправляйся к нему.\n\nСтраж смерти Диллинджер стоит на посту в западном конце Брилла, рядом с кладбищем.", progress = nil, completion = "Ты хочешь получить задание? Отлично. У меня есть одно. Довольно важное. Заодно и свою силу нам покажешь... И решимость защищать дело Отрекшихся.", rewards = "Вы получите:\n\n"},
[1819] = {title = "Улаг Колун", objective = "Убейте Улага Колуна и поговорите со стражем смерти Диллинджером.", description = "Когда Тирисфальские луга наводнили воины Плети, мы поймали одного из них и подвергли пристальному изучению. Он обладал свободной волей и звал себя Улаг Колун. Впрочем, несмотря на свободу воли, его подчинил себе Король-лич.\n\nМы надеялись избавить Улага от чар, но не смогли. Довольно ему томиться в темнице плоти. Освободи его.\n\nДля этого его придется убить.\n\nВоспользуйся переключателем в мавзолее к северу отсюда. Это позволит снять с Улага магические путы.\n\nСними их и... будь <готов/готова>!", progress = nil, completion = "Молодец, Некротанг. Улаг был серьезным сторонником Плети. Тебе удалось доказать стражам смерти и через них Темной Госпоже, что ты опытный и умелый воин и заслуживаешь дальнейшего обучения.", rewards = "Следующее заклинание будет наложено на вас:\n\nПуть защиты\n\nВы получите:\n\n"},
[1820] = {title = "Разговор с Колманом", objective = "Поговорите с Колманом Фартингом.", description = "Тебе удалось услужить Темной Госпоже, пришло время услужить одному из ее подданных.\n\nКолману Фартингу нужен воин, который сможет отомстить врагам Отрекшихся.\n\nКоулман сидит в таверне \"Петля висельника\", в восточной части Брилла.", progress = nil, completion = "Да, это правда. Мне нужна помощь закаленного воина. Средств у меня немного, зато ты послужишь не только мне, но и делу Отрекшихся. Так что если ты справишься, наградой будет почет.", rewards = "Вы получите:\n\n"},
[1821] = {title = "Наследие Агамондов", objective = "Принесите Колману Фартингу фамильный топор Агамондов, фамильный меч Агамондов, фамильную палицу Агамондов, фамильный кинжал Агамондов.", description = "При жизни я служил семье Агамондов, и именно из-за них и умер! Поделом им, они стали теперь безмозглыми прислужниками Короля-лича.\n\nМне же хочется лишить их остатков чести. Ступай в Семейную усыпальницу Агамондов и принеси их фамильное оружие: меч, топор, кинжал и палицу.\n\nСклеп находится севернее мельниц Агамондов. Его стерегут бойцы Плети и сами неупокоенные Агамонды.", progress = "Тебе удалось принести фамильное оружие?", completion = "А! Вот оно! Итак, проклятые земли Агамондов лишены остатков чести и памяти. Отныне семьи воистину не существует!", rewards = "Вы получите:\n\n"},
[1822] = {title = "Фамильное оружие", objective = "Я оставлю принесенное тобой оружие на память о понесенных потерях. Впрочем, ты можешь выбрать наиболее полюбившуюся тебе вещь и оставить ее себе.\n\nДа послужит она тебе лучше, чем прежним проклятым владельцами.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nФамильный топорМолот-наследиеКинжал-наследиеМеч-наследие\n\nВы также получите:\n\n"},
[1823] = {title = "Разговор с Ругой", objective = "Поговорите с Ругой Тотемом Гнева.", description = "Ты уже опытный воин, и имя твое на слуху у многих. Может быть, ты хочешь пройти испытание Руги Тотема Гнева? Коли так, отправляйся в Лагерь Таурахо, в Степи.\n\nОн ждет всех воинов, что готовы принять его вызов.", progress = nil, completion = "Ты хочешь пройти испытание, Гронгард?", rewards = "Вы получите:\n\n"},
[1824] = {title = "Испытание на Полях Великанов", objective = "Принесите 5 дергающихся усиков Руге Тотему Гнева в Лагерь Таурахо.", description = "Чтобы пройти это испытание, тебе придется отправиться на юг, к Полям Великанов. Там ты встретишь полчища ползучих существ, похожих на насекомых. Они явились в Степи незванными, и мне они совсем не нравятся.\n\nПринеси их усики. Главное, чтобы они все еще дергались, поэтому тебе придется поторопиться. Добудь мне усики за отведенное время, и я сочту, что испытание пройдено.", progress = "Ну как, усики у тебя? Коли так, давай их скорее сюда, а то они скоро перестанут дергаться...", completion = "Отличная работа, Гронгард! Ты прошел испытание на Полях Великанов, сделав тем самым еще один шаг по тропе воина.", rewards = "Вы получите:\n\nОплот Руги"},
[1825] = {title = "Разговор с Тун'гримом", objective = "Поговорите с Тун'гримом Огневзором из Степей.", description = "Слухи о твоих доблестных подвигах во славу Орды дошли до знаменитого орочьего кузнеца, Тун'грима Огневзора. Он хотел бы сделать для тебя доспехи, но тебе надо как можно скорее с ним встретиться.\n\nТун'грим живет на востоке от Перекрестка, что в Степях.", progress = nil, completion = "Да, ты пришел. Отлично, нам с тобой многое придется обсудить.", rewards = "Вы получите:\n\n"},
[1838] = {title = "Доспехи Жестокости", objective = "Принесите Тун'гриму Огневзору 15 закопченных железных слитков, 10 мер толченого азурита, 10 железных слитков и сосуд флогистона.", description = "Я наслышан о твоей силе и доблести и хочу сделать для тебя броню, которая охранит тебя в бесчисленных сражениях.\n\nВпрочем, создание такой брони – само по себе подвиг. Мне понадобится твоя помощь, а также помощь других кузнецов Орды.\n\nВозьми этот список. Я составлял его не одну ночь, напряженно вглядываясь в пергамент почти незрячими глазами. Принеси мне все перечисленное, и я создам тебе первую часть доспеха.", progress = "Ты все предметы из списка принес?", completion = "Ты принес все, что я просил. Теперь дело за мной...", rewards = "Вы получите:\n\n"},
[1839] = {title = "Ула'елек и рукавицы Жестокости", objective = "Поговорите с Ула'елеком из Дуротара.", description = "Кузнец-тролль по имени Ула'елек готов выковать для тебя рукавицы жестокости. Он живет в Дуротаре, в деревне Сен'джин, вместе со своими собратьями из племени Черного Копья, и с нетерпением ждет твоего прихода.", progress = nil, completion = "Привет тебе, Коммибро. Старый Тунгрим предупредил меня о твоем приходе, но умолчи он, я не удивился бы твоему появлению.\n\nДухи следят за каждым твоим шагом, юный воин, и они говорят, что от твоей руки пало немало врагов.", rewards = "Вы получите:\n\n"},
[1840] = {title = "Орм Каменное Копыто и шлем Жестокости", objective = "Обратитесь к Орму Каменному Копыту из Громового Утеса.", description = "Искусство Орма Каменного Копыта пользуется заслуженным уважением. Он и сделает тебе шлем Жестокости.\n\nЕго можно найти в Громовом Утесе, рядом с прудом и центральным тотемом города.", progress = nil, completion = "Привет тебе, воин. Я Орм. Тунгрим сказал, что тебе нужен шлем. Это правда?", rewards = "Вы получите:\n\n"},
[1841] = {title = "Велора Нители и Набедренники Жестокости", objective = "Поговорите с Велорой Нители из Подгорода.", description = "Говорят, что при жизни Велора Нители была одним из лучших кузнецов Лордерона. Кажется, она и после смерти не лишилась таланта. Поговори с Велорой, она сделает тебе набедренники Жестокости.\n\nВелора трудится в Подгороде Лордерона, в торговом квартале.", progress = nil, completion = "Тебе нужны набедренники? Отлично!\n\nХм... Тогда кто из нас будет их делать?\n\nШутка. Смешно? Я вот не понимаю... Чувство юмора я утратила одновременно с обонянием. Примерно в те времена, как перестала дышать.", rewards = "Вы получите:\n\n"},
[1842] = {title = "Копыта сатиров", objective = "Принесите 7 нераздвоенных копыт сатиров Ула'елеку в Дуротар, в деревню Сен'джин.", description = "Я могу сделать для тебя пару рукавиц Жестокости, напитав их магической силой. Но прежде тебе придется добыть эту самую силу.\n\nВ северо-восточной части Ясеневого леса живут сатиры. Их привлекла туда сила леса. Они питаются его первозданной чистотой, искажая и оскверняя ее. Сатиров, вобравших в себя особенно много магии Ясеневого леса можно отличить от других по разбухшим, нераздвоенным копытам.\n\nВ этих копытах содержится великая сила. Они понадобятся мне для создания рукавиц.", progress = "Копыта уже у тебя? Помни, они полны сильнейшей магии.", completion = "Ага, вот и они! Сатиры похитили силу Ясеневого леса, а их сила вольется в мое творение...", rewards = "Вы получите:\n\n"},
[1843] = {title = "Рукавицы Жестокости", objective = "Спасибо, Коммибро. Эти рукавицы – мое величайшее достижение. Возьми их. Ты окажешь мне честь, если пойдешь в них в бой.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nРукавицы Жестокости"},
[1844] = {title = "Рог химеры", objective = "Принести Орму Каменному Копыту из Громового Утеса гальванизированный рог.", description = "Я сделаю тебе шлем, но прежде докажи, что <достоин/достойна> его.\n\nВ северной части Когтистых гор лежит Обугленная долина. Некогда она была цветущей рощей, но теперь от деревьев остался лишь пепел, а все живущие там существа исполнены боли и отчаяния.\n\nТуда тебе и придется отправитьcя, <имя>.\n\nСтупай в Обугленную долину и найди там химеру-матриарха. Избавь ее от страданий. Принеси в доказательство ее гибели гальванизированный рог, и я сделаю тебе шлем.", progress = "Ну и где рог? Ты избавил матриарха от страданий?", completion = "Что же, задание выполнено, Коммибро. Теперь я не сомневаюсь в твоей решимости и храбрости. Ты заслужил шлем...", rewards = "Вы получите:\n\n"},
[1845] = {title = "Шлем Жестокости", objective = "Возьми этот шлем.\n\nТебя привели ко мне великие свершения, и если Матери-земле будет угодно... тебе предстоит немало подвигов.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nБезжалостный шлем"},
[1846] = {title = "Берцовые кости", objective = "Принесите 8 крепких берцовых костей Драконьей Пасти Велоре Нители в Подгород.", description = "Чтобы создать набедренники Жестокости, мне понадобятся прочные берцовые кости. У орков из клана Драконьей Пасти крепкие ноги. Они-то мне и нужны.\n\nНо только самые прочные. Непременно проверь их, прежде чем счесть подходящими. Если ты сможешь сломать их голыми руками, значит, они не достаточно прочные.", progress = "Я жду, когда ты принесешь берцовые кости. Из них выйдет отличная основа для набедренников.", completion = "Молодец! На вид они крепкие. Пожалуй, подойдут. Орки не возражали? Сильно жаловались?\n\nОпять я пошутила. Ты не смеешься.\n\nЧто-то у меня не так с чувством юмора...", rewards = "Вы получите:\n\n"},
[1847] = {title = "Набедренники Жестокости", objective = "Вот твои набедренники, Большойзмей. Ну как, подходят? Или надо что-то менять? Мне хочется угодить заказчику! По крайней мере всегда хотелось.\n\nТеперь ремесло утратило прежнюю прелесть. Но все лучше, чем быть безмозглым рабом Плети!\n\nНаверное.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nНабедренники Жестокости"},
[1848] = {title = "Хауберк Жестокости", objective = "Тебе несомненно пришлось пролить немало крови, чтобы справиться с моим заданием, Коммибро. Вот плод твоих трудов.\n\nНоси с удовольствием. Как-нибудь заходи, расскажешь, как он тебе пригодился в бою.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nБезжалостный хауберк"},
[1858] = {title = "Изувеченная Длань", objective = "Украдите ключ Тазана, откройте сумку Тазана и отнесите содержимое сумки Терзоку в расселину Теней в Оргриммаре.", description = "Загляни в сумку Тазана и принеси мне то, что найдешь внутри. Замок там непростой, так что постарайся раздобыть ключ.\n\nНа трупе Тазана ключа не было? Значит, он его кому-то отдал... Ах, ну да, конечно. У него был помощник, Гамон. Он пьяница, так что ищи его в тавернах. Возможно, тебе удастся потихоньку утащить у него ключ.", progress = "Не ужасно ли это: держать в руках то, что тебе нужно, и не иметь возможности его достать?", completion = "Так-так, интересно... Что ж, Лайбах, ты полностью оправдал мое доверие. Отныне можешь считать себя членом клана Изувеченной Длани. И возьми это. Думаю, он тебе очень пригодится в будущем.", rewards = "Вы получите:\n\nКлинок хитрости"},
[1859] = {title = "Терзок", objective = "Поговорите с Терзоком в расселине Теней в Оргриммаре.", description = "Говори тише, <имя>! Ну да, я знаю твое имя. Мне сказали, чтобы я ждал одного орка, и дали описание твоей внешности.\n\nСудя по тому, что о тебе рассказывают, ты неплохо держишься в открытом бою, но можешь прибегнуть и к хитрости, верно?\n\nВ общем, сходи в Оргриммар, поговори с Терзоком. У него есть для тебя предложение.", progress = nil, completion = "А, это ты! Очень хорошо, что Каплак сумел тебя перехватить.\n\nНам нужно поговорить кое о чем, не в последнюю очередь – о твоем будущем в Раздробленной Руке.", rewards = "Вы получите:\n\n"},
[1860] = {title = "Поговорите с Джиннией", objective = "Поговорите с Джиннией Пушкой в Штормграде.", description = "У нас, магов, есть одна задача, которая жизненно важня для безопасности Штормграда и Элвиннского леса.\n\nПодробности ты можешь узнать у Джиннии Пушки. Она работает в Башне магов, в районе магов в Штормграде. Не мешкай.", progress = nil, completion = "Тебя послали мне на подмогу, Баши? Хорошо. Приятно видеть, что молодые маги рады внести свой вклад в общее дело…\n\nКакое дело, спросишь ты? Вырастешь – узнаешь. Обязательно узнаешь... со временем.", rewards = "Вы получите:\n\n"},
[1861] = {title = "Зеркальное озеро", objective = "Отнесите пробу воды из Зеркального озера Джиннии Пушке из Штормграда.", description = "Этот мир пал жертвой магических войн, в результате которых нарушилось течение магической энергии. Мы попытались просчитать дальнейшие последствия, и многие из нас опасаются худшего!\n\nНо об этом мы поговорим позже. Для начала надо собрать все доступные сведения.\n\nВозьми этот сосуд, отправляйся к подножию водопада у Зеркального озера, что на юго-западе от Врат Штормграда, и принеси мне пробу тамошней воды. Я хочу исследовать ее на предмет заражения тлетворной магией.", progress = "Ты принесла мне пробу, Нерлисс? Магические потоки Штормграда и Элвиннского леса ощутимо изменились, и я должна знать, что проникает в нашу воду.", completion = "Спасибо, Нерлисс. Я исследую магические свойства этой воды. Будем надеяться, что их не окажется, а то, неровен час, окажется, что магия повлияла на всех, кто пил много воды из Зеркального озера.\n\nВозьми эту сферу или этот посох в знак моей благодарности за услугу. Пускай они служат тебе верой и правдой.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСфера ЗалогаПосох залога\n\nВы также получите:\n\n"},
[1878] = {title = "Награда за воду", objective = "Опять ты здесь? Если ты несешь еще пять бурдюков с водой Скитальцев Пустыни, то тебя ждет еще один именной полевой набор!", description = nil, progress = "Опять ты здесь? Если ты несешь еще пять бурдюков с водой Скитальцев Пустыни, то тебя ждет еще один именной полевой набор!", completion = "Великолепно! Чем больше мехов с водой нам удастся добыть, тем ниже вероятность катастрофы! Можешь таскать их сотнями, и за каждые пять будешь получать все ту же награду.", rewards = "Вы получите:\n\nПолевой набор Водной компании Прибамбасска"},
[1879] = {title = "Поговорите с Бинк", objective = "Поговорите с Бинк из Стальгорна.", description = "<имя>! Бинк, моя коллега-гном из Стальгорна, прислала мне весточку. У нее возникла небольшая проблема, а обращаться за помощью ни к кому, кроме мага, она не хочет. Ты <готов/готова> ей помочь, <имя>?\n\nЕсли да, то поговори с ней. Бинк проводит большую часть времени в Зале Тайн в Палатах Магии Стальгорна.", progress = nil, completion = "О, я вижу в тебе неплохие задатки, да-да! Но чтобы стать хорошим магом, одних задатков мало. А не сликшом хороший маг – плохой маг. А из-за плохих магов и возникают все проблемы!\n\nОй, кажется, я немного забегаю вперед. Начнем сначала!", rewards = "Вы получите:\n\n"},
[1880] = {title = "Маг-тастический гизмонитор", objective = "Верните Бинк маг-тастический гизмонитор.", description = "Мы, маги, не просто щелкаем пальчиками и создаем забавные искорки! Мы контролируем поток магической энергии, основной ткани мироздания! Для этого требуется осторожность и решимость. И знания... Невероятно много знаний!\n\nОдно из моих устройств, маг-тастический гизмонитор, позволяет собирать и хранить множество знаний! Но увы, он утрачен! Когда мы бежали из Гномрегана, я оставила его в сундуке в одном из домишек за пределами города. Теперь там кишмя кишат лепрогномы!\n\nПрошу тебя, <имя>, верни мне гизмонитор!\"", progress = "Тебе удалось найти мой гизмонитор? Нужно найти его, пока источник питания не разрядился!", completion = "О, радость! Создавая гизмонитор, я и не догадывалась, в какую зависимость от него попаду! Теперь я могу возобновить свои исследования.\n\nСпасибо, Рискем! Вот, смотри. Это мой первый набор магических инструментов. Они не так блестят, как новые, зато проверены временем. Выбирай любой из них – все они могут тебе пригодиться.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЧародейский шарЧародейский посох\n\nВы также получите:\n\n"},
[1881] = {title = "Разговор с Анастасией", objective = "Поговорите с Анастасией Хартвелл.", description = "У Анастасии Хартвелл есть задание, которое тебе как раз по плечу. Поговори с ней. Она живет в квартале магов в Подгороде. Готовься выполнить первое задание для магов Отрекшихся.", progress = nil, completion = "Привет тебе, Веланокс. Ты правильно поступил, откликнувшись на мой зов, но еще правильнее будет меня выслушать...", rewards = "Вы получите:\n\n"},
[1882] = {title = "Ферма Балнира", objective = "Принесите львиный зев Бальнира Анастасии Хартвелл в Магический Квартал Подгорода.", description = "Чумные земли – гнусное место, творение Короля-лича. Он отравил землю, осквернил и убил все живое. Хотя в убийственной силе чумы есть что-то привлекательное, мы, маги Отрекшихся, считаем ее неуправляемой и недопустимой.\n\nДля начала надо понять, проникла ли она в Тирисфаль. Отправляйся на ферму Балнира в восточной части Тирисфаля. В саду растут цветы – львиный зев. Собери их и возвращайся.", progress = "Ну и где львиный зев? Этот цветок вбирает в себя магическую энергию, поэтому изучение этих растений поблизости от Чумных земель даст нам возможность понять, добралась ли чума нежити до Тирисфальских лесов.", completion = "Отличные цветы. Я отправлю их на изучение нашим аптекарям. Пусть поищут в них скверну Проклятых земель.\n\nМолодец, Веланокс. Я предлагаю тебе выбрать награду – сферу или посох. И то, и другое может тебе здорово пригодиться.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЧародейский шарЧародейский посох\n\nВы также получите:\n\n"},
[1883] = {title = "Разговор с Ун'Тувой", objective = "Поговорите с Ун'Тувой.", description = "Ун'Тува, маг деревни Сен'джин, обнаружил изменения в потоках магической энергии Дуротара и просит тебя о помощи. Поговори с ним и сделай все, что сможешь.\n\nПриди к нему на помощь, и со временем тебе откроются великие тайны.", progress = nil, completion = "Привет тебе, Тузвколоде. Хвала тебе, ибо ты ответил на мой зов о помощи. Будем надеяться, что ты справишься с заданием...", rewards = "Вы получите:\n\n"},
[1884] = {title = "Груды джуджу", objective = "Уничтожьте 4 груды джуджу и вернитесь к Ун'Туве из деревни Сен'джин.", description = "Оказывается, нормальное течение магической энергии в Дуротаре нарушил чернокнижник Залазан с островов Эха. Для этого он разместил оскверненные фетиши, груды джуджу, среди домов центрального острова Эха.\n\nИз-за этого болеет здешнее зверье, а чернокнижники и пришельцы из преисподней, таящиеся во тьме, набираются силы.\n\nНеобходимо уничтожить эти груды джуджу, <имя>, прежде чем наши земли изменятся до неузнаваемости.", progress = "Торопись, Вудупипл. Уничтожь проклятые груды джуджу!", completion = "Я чувствую, что груды джуджу уничтожены. При удаче все труды Залазана пойдут насмарку и в Дуротаре восстановится нормальное течение магической энергии.\n\nТвой подвиг во имя Орды достоин всяческой хвалы!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСфера ЗалогаПосох залога\n\nВы также получите:\n\n"},
[1885] = {title = "Меннит Каркад", objective = "Поговорите с Меннитом Каркадом в Квартале Разбойников Подгорода.", description = "<имя>? Вот уж не ожидал вас увидеть после того, как вами заинтересовался сам Каркад. Ничего нельзя сказать наперед...\n\nВ любом случае, вам лучше встретиться с ним, и поскорее. Лучше вам не знать, что стало с теми несколькими глупцами, которые проигнорировали вызов от него.", progress = nil, completion = "Хм. Несомненно, вы пришли сюда по первому моему зову, так? Не ожидал ничего иного от перспективного стража смерти.", rewards = "Вы получите:\n\n"},
[1886] = {title = "Стражи смерти", objective = "Принесите рекомендательное письмо Астора Менниту Каркаду в Квартал Разбойников Подгорода.", description = "Чтобы вступить в ряды стражей смерти, элитной охраны лорда Вариматраса, тебе придется сперва доказать свои способности.\n\nНе буду лгать: это задание может окончиться твоей гибелью.\n\nМне нужна помощь в нескольких вопросах. Во-первых, принеси мне личные вещи Астора Хадрена – это вестник, путешествующий между Серебряным бором и Подгородом. Как ты это сделаешь - тебе решать.\n\nПока что это все, что тебе следует знать. Справишься - узнаешь больше.", progress = "Пришел доложить об успехе?", completion = "Неплохо, Бифачу. Первая часть испытания пройдена. Надеюсь, Андрон ничего не узнал о твоих действиях, и ты сможешь убедить его, что ты и есть тот вестник, которого он ждет.", rewards = "Вы получите:\n\n"},
[1898] = {title = "Стражи смерти", objective = "Поговорите с Андроном Гантом в Подгороде.", description = "Рекомендательное письмо должно убедить Андрона, что ты – тот самый гонец, которого он ждал. Мне приходилось встречаться с Андроном, он не настолько умен, чтобы заподозрить неладное.\n\nЛорд Вариматрас подозревает, что Андрон тайно помогает другой группировке, и тебе предстоит выяснить, какой именно. Хорошо бы также получить доказательства.\n\nПоговори с Андроном и вытяни из него эти сведения. Его можно найти в лавке неподалеку от Района Фармацевтов.", progress = "Добрый день. Чем могу помочь?", completion = "Ах да, я ждал тебя. Полагаю, наши общие знакомые довольны переданными сведениями?\n\nБоюсь, тебя спрашивать без толку, вряд ли тебя обременяют лишними знаниями. К чему доверять гонцу слишком много тайн?", rewards = "Вы получите:\n\n"},
[1899] = {title = "Стражи смерти", objective = "Отнесите гроссбух Андрона Менниту Каркаду в Квартал Разбойников Подгорода.", description = "Гроссбух с необходимой твоим нанимателям информацией стоит на книжной полке за моей спиной. Передай его заказчикам вместе с поклоном от меня и сообщи, что, если они оценят полученные сведения и захотят продолжить наше сотрудничество, я предпочел бы иметь дело с тобой.", progress = "Как твои успехи?", completion = "Ну и ну, я и не рассчитывал вытянуть столько информации из Андрона. Дай-ка я изучу этот гроссбух повнимательнее и дам тебе следующее задание.", rewards = "Вы получите:\n\n"},
[1918] = {title = "Оскверненная стихия", objective = "Отнесите оскверненную водяную сферу Мистоку Райльшипу на заставу Расщепленного Древа в Ясеневый лес.", description = "Из убитого элементаля выпала ярко светящаяся сфера воды. Содержимое шара в лучшем случае отвратительно. Можно с уверенностью сказать, что то, что заразило воды озера Мистраль, находится в этой сфере.\n\nТак сразу и не скажешь, кого может заинтересовать эта находка – возможно, подскажет тот, кто послал вас к этому озеру, а именно Мисток Райльшип с заставы Расщепленного Древа.", progress = "Да, в чем дело?", completion = "Ты нашел какой-то грязный шар с водой и решил принести его мне? Я кто, по-твоему – представитель Служителей Земли или что? \n\nВообще-то, у меня появилась кое-какая идея... может, тебе и правда понадобится помощь Служителей Земли. В смысле, если это поможет разрешить ситуацию на озере, то я к твоим услугам.\n\nТы знаешь, кто такие Служители Земли, Эпифантий?", rewards = "Вы получите:\n\n"},
[1919] = {title = "Задание Джиннии", objective = "Поговорите с Джиннией Пушкой в Штормграде.", description = "Ты набираешься знаний и опыта, <юный/юная> <имя>. Ты <готов/готова> приступить к подлинному обучению и принять участие в непрекращающейся тайной войне?\n\nЕсли да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда. У нее есть для тебя задание, которое впервые приоткроет окно в невидимый мир.", progress = nil, completion = "Эфром, у меня есть для тебя задание. Да-да, прямо здесь, в квартале магов. Слушай внимательно, не будем терять время даром.", rewards = "Вы получите:\n\n"},
[1920] = {title = "Синий Отшельник", objective = "Возьмите свиток заклинания Проявления и ящик с шкатулками-духоловками за спиной у Джиннии Пушки. Принесите 3 заполненных шкатулки-духоловки Джиннии в Башню магов.", description = "Сообщают о беспорядках в таверне \"Синий отшельник\", что в квартале магов. Там бродят странные невидимые существа, чувствую там образовался провал Маны.\n\nОтправляйся туда и поймай этих тварей. Чтобы они стали видимыми, воспользуйся заклятьем Проявления, одолей их и посади в шкатулки-духоловки. Как только наберешь достаточно этих тварей, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием.", progress = "Тебе удалось поймать этих тварей, Корван? Их необходимо изучить, чтобы выяснить, почему они появились в городе.", completion = "Ну ты молодец! Я займусь изучением этих существ, и при удаче пойму, как они ухитрились пробраться в наш мир.\n\nТы приносишь сообществу магов все больше пользы, Корван.", rewards = "Вы получите:\n\n"},
[1921] = {title = "Сбор материалов", objective = "Отнесите 10 кусков льна и 6 заряженных самоцветов Расселины Уинн Ларсон в Штормград.", description = "За верную службу своим собратьям-магам тебе полагается одеяние волшебника. Его вполне может сшить Уинн Ларсон, если ты принесешь ей все необходимое.\n\nСамо одеяние шьется из льна, который легко найти, но кроме него понадобятся заряженные самоцветы Расселины, а их добывают исключительно в Руднике у Серебряного ручейка у озера Лок Модан. Горняки дворфов не смогли забрать их, и они лежат в ящиках по всему руднику.\n\nНабери льна, добудь самоцветы и принеси их Уинн Ларсон в суконную лавку Ларсона в район магов.", progress = "Привет, Баши. Джинния предупредила меня о твоем появлении. Что ты мне несешь?", completion = "Да, превосходный лен. Из него выйдет отличная ряса. А после того, как я разошью ее самоцветами, получится настоящее одеяние для мага!", rewards = "Вы получите:\n\n"},
[1938] = {title = "Трактат Ура по темной магии", objective = "Принесите трактат Ура по темной магии верховному колдуну Андромату из Штормграда.", description = "Давным-давно в этой башне жили три мага, и один из них поддался искушению и занялся темными искусствами. Его уговаривали отказаться от черной магии, но тщетно. И он был изгнан.\n\nНовое пристанище изгнанного мага – башня Илгалара в Красногорье. Он унес с собой ценную книгу – Трактат Ура по темной магии.\n\nМы, маги Штормграда, хотим вернуть себе эту книгу. Отправляйся в башню Илгалара, найди этот фолиант в библиотеке и принеси мне.", progress = "Тебе удалось добыть книгу? Ее тайны не для глаз непосвященных, и если слишком углубиться в нее, можно обречь себя на гибель.", completion = "Я опасался, что Моргант спрятал книгу где-то еще или же нашел способ открыть ее и прочесть.\n\nХорошо, что он не успел, и что все печати, наложенные на этот трактат, сохранились в целости.", rewards = "Вы получите:\n\n"},
[1939] = {title = "Верховный колдун Андромат", objective = "Поговорите с верховным колдуном Андроматом.", description = "С тобой хочет поговорить верховный колдун Андромат. Он находится на верхнем этаже Башни магов, в квартале магов Штормграда.\n\nОбязательно поговори с ним, ведь Андромат – один из самых могущественных магов за пределами Даларана. Его совет стоит десяти других.", progress = nil, completion = "Привет тебе, Эфром. Рад тебя видеть. Надеюсь, у тебя найдется время выслушать старика...", rewards = "Вы получите:\n\n"},
[1940] = {title = "Безупречная паутина", objective = "Принесите 8 кусков безупречной паутины Уинн Ларсон в Штормград.", description = "Пожалуй, следует наградить тебя за безупречную службу. Пора тебе обзавестить одеянием, которое пристало носить магу твоего уровня. Если тебе удастся собрать все необходимые материалы, одеяние у тебя будет.\n\nСтупай в Сумеречный лес и убей побольше пауков, падальщиков-отшельников. Набери их паутины, только учти, годится лишь самая лучшая. Набрав достаточно паутины, отнеси ее Уинн Ларсон, которой принадлежит магазин \"Суконная лавка Ларсона\" в Квартале Магов. Она сошьет тебе одеяние.", progress = "Ах, да. Маги из Башни магов предупредили меня о твоем приходе. Ты несешь мне нужную паутину?", completion = "Неплохая паутина. Я немедленно примусь за работу!", rewards = "Вы получите:\n\n"},
[1941] = {title = "Одеяние из ткани маны", objective = "Вот твое одеяние. Один из моих шедевров! Носи на здоровье, а если тебя спросят, кто шил... Посоветуй им обратиться в суконную лавку Ларсона!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nОдеяние из ткани маны"},
[1942] = {title = "Одеяние волшебного плетения", objective = "Твое одеяние готово! Отличный шелк тебе достался... Ты уж прости, одеяние получилось довольно короткое, часть шелка я себе оставила.\n\nШучу, шучу. Оно тебе идеально подойдет, причем будет уместно смотреться как в бою, так и на торжественном обеде. Наслаждайся!", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОдеяние волшебного плетенияРубашка волшебного плетения\n\nВы также получите:\n\n"},
[1943] = {title = "Разговор с Дейно", objective = "Поговорите с Дейно.", description = "Магу Дейно нужна твоя помощь, <имя>. Она живет в Оргриммаре, в пристанище Темнотерна.", progress = nil, completion = "Хорошо, что ты здесь. Я хочу дать тебе довольно сложное задание. Оно жизненно важно для всего сообщества магов. Помоги мне, и маги отплатят тебе сторицей.", rewards = "Вы получите:\n\n"},
[1944] = {title = "Воды Ксавиана", objective = "Принесите пробу воды из Ксавиана Дейно в Оргриммар.", description = "В восточной части Ясеневого леса раскинулся прославенный город Ксавиан. Ученые всех народов слышали легенды о хранимом в нем древнем знании. Говорят, что воды Ксавиана содержат немало магической энергии.\n\nМне нужна проба воды из Ксавиана.\n\nВозьми этот сосуд и ступай туда. Набери воды у подножия самого большого водопада и возвращайся ко мне. Соблюдай осторожность – руины древнего города заполонили сатиры, им не нравится, когда в их дела встревают маги.", progress = "Хорошо, что сосуд уцелел. А вода в нем есть? Мне не терпится изучить ее свойства.", completion = "А, отлично. Надеюсь, сатиры Ксавиана тебе не слишком сильно помешали?\n\nСпасибо, Тузвколоде. Я немедленно займусь изучением пробы воды из Ксавиана.", rewards = "Вы получите:\n\n"},
[1945] = {title = "Смеющиеся сестры", objective = "Принесите 12 волос Смеющихся сестер Кил'хале с Перекрестка.", description = "За верную службу тебе полагается новое одеяние, если ты принесешь все необходимые материалы.\n\nТебе придется вернуться в Ясеневый лес за локонами волос Смеющихся сестер – дриад, бродящих возле Приюта в Ночных Лесах.\n\nДобыв их волосы, отнеси их Кил'хале, троллю-портному с Перекрестка, что в Степях. Он-то и сошьет тебе одеяние.", progress = "Привет тебе, Атеистфрост. Дейно предупредила меня о твоем появлении. Она сказала, что ты принесешь волосы Смеющихся сестер. Это правда?", completion = "А, из этих волос выйдет отличное одеяние. Жаль, что приходится убивать Смеющихся сестер ради добычи волос, впрочем, добровольно они их все равно не отдали бы.\n\nЖаль, но не очень.", rewards = "Вы получите:\n\n"},
[1946] = {title = "Одеяние из кружева Пустоты", objective = "Вот твое пустокружево. Оно прочное и удобное и хранит в себе магию волос Смеющейся сестрички.\n\nНаслаждайся. Если понравится, не забудь упомянуть об этом в разговоре с Дейно. Вот уж с кем бы не хотелось ссориться...", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОдеяние из кружева ПустотыМундир из кружева Пустоты\n\nВы также получите:\n\n"},
[1947] = {title = "Путь в болото", objective = "Поговорите с Табетой.", description = "Пришло время заслужить магический жезл. Для начала поговори с отшельницей из Пылевых топей, человеком по имени Табета. Она живет в хижине в глубине болота, на западе от Терамора.\n\nЕе познания велики, и она сможет дать тебе добрый совет. Хижина Табеты находится чуть севернее руин Деревни Каменного Молота.", progress = nil, completion = "Тихо! Не беспокой меня, сейчас очень ответственный момент!\n\nМинуточку...", rewards = "Вы получите:\n\n"},
[1948] = {title = "Волшебные предметы", objective = "Принесите 1 нефрит и шипастый жезл Молний Табете в Пыльную трясину.", description = "Создать жезл мага не так-то просто. Приходится собирать редкие компоненты, да и конструировать его надо так, чтобы он вмещал побольше магической энергии. Собери все необходимое и принеси мне.\n\nЯ составил список компонентов и заодно указал, где их искать. Буквально следуй моим указаниям, в противном случае при попытке создать жезл может случиться большая неприятность!", progress = "Здравствуй, Сипсик. Ты все компоненты принес?", completion = "Ага! Тебе удалось найти нефрит и сделать шипастый жезл! Молодец!\n\nУ тебя что, из ушей дым идет? Наверное, ты подошел слишком близко, когда молния била в заготовки. Такое случается. Не расстраивайся, получить удар молнии – хорошая примета!", rewards = "Вы получите:\n\n"},
[1949] = {title = "Великие тайны", objective = "Поговорите с волхвом Тиртом на Мерцающей равнине.", description = "Для создания жезла мне нужно прочитать некоторые разделы одной книги. Называется она \"Ритуалы Силы\", а написал ее волхв Тирт.\n\nУ меня ее нет, да и ни в одной библиотеке ее не сыскать. Поэтому придется тебе найти Тирта и взять ее у него.\n\nУдачи. Когда-то он был великим магом и ученым, но теперь большую часть времени проводит на гоночном поле на Мерцающей равнине, пьет и играет в азартные игры.", progress = nil, completion = "Что? Говори громче! У меня не такой острый слух, как бывало.\n\nНадеюсь, ты несешь мне кружку свежего эля или верные сведениями о следующей гонке! Если нет, проваливай... А то у меня наготове жезл превращения!", rewards = "Вы получите:\n\n"},
[1950] = {title = "Волшебное слово", objective = "Узнайте волшебные слова, отпирающие сейф Тирта и вернитесь к Тирту.", description = "Я помогу тебе с книгой, но сначала окажи мне услугу!\n\nНужная тебе книга заодно и магический сейф. Он открывается особой фразой, и ее-то я и забыл! Обычно мне напоминает помощник, но он куда-то запропал.\n\nЕсли тебе нужна книга, найди моего помощника! Поспрашивай у зрителей, при удаче кто-то мог его видеть. Притащи его сюда или выбей из него волшебные слова!", progress = "Чего ты ждешь? Мне нужны волшебные слова!", completion = "Ах да, припоминаю…\n\nЯ и правда наложил на Джонсона проклятье. Не помню, зачем я это сделал, но так ему и надо, маленькому нахалу!", rewards = "Вы получите:\n\n"},
[1951] = {title = "Обряды силы", objective = "Принесите книгу \"Обряды силы\" Табете в Пыльную трясину.", description = "Хм... Оказывается, книги-то у меня и нет! Видишь ли, мне пришлось отдать последнюю копию за игорные долги какому-то жрецу...\n\nОдному из Алого ордена. Наверное, он унес ее в монастырь в Тирисфальские леса!\n\nЕсли тебе так нужна книга, придется сходить за ней в монастырь. Прости за доставленные неудобства. Я в последнее время сам не свой...", progress = "Приветствую, Берш. У тебя ли книга \"Обряды силы\"?", completion = "Вот она! То что нужно для последнего обряда создания жезла! Надеюсь, поиски были не слишком сложными?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1952] = {title = "Магический жезл", objective = "Поговорите с Табетой по завершении ритуала.", description = "Пойду, займусь созданием жезлов.", progress = nil, completion = "Ну вот, жезлы готовы. Выбирай любой!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖезл Ледяной яростиЖезл силы ПустотыЖезл Бущующего пламени\n\nВы также получите:\n\n"},
[1953] = {title = "Назад в болото", objective = "Поговорите с Табетой.", description = "Пришло время поговорить с Табетой... отшельницей из Пылевых топей. Она научит тебя создавать могущественные магические инструмены.\n\nХижина Табеты находится в глубинах Пылевых топей, западнее Терамора.", progress = nil, completion = "Ах, да. Тебе нужна сфера или жезл? Ну, хорошо. Я помогу тебе.\n\nВпрочем, знай. Это очень опасно и может привести к твоей гибели.\n\nИли моей гибели. В общем, кому-то умереть придется…\n\nБудем надеяться, что не нам, а?", rewards = "Вы получите:\n\n"},
[1954] = {title = "Сфера Подземного огня", objective = "Принесите сферу Подземного огня Табете из Пылевых топей.", description = "Первым делом тебе нужно заполучить сферу силы. У чернокнижников из клана Пылающего Клинка очень подходящие сферы... Жаль, что в каждой из них заключен демон! Но это поправимо, и очень даже.\n\nОтправляйся в Пустоши и отбери сферу подземного огня у призывателя из клана Пылающего Клинка. Призыватели живут на поле Маннорок.\n\nКак получишь сферу, возвращайся.", progress = "Сфера Подземного огня у тебя?", completion = "Ага, недурная сфера. Не в том смысле недурная, как охлажденная вода с соком в жаркий день.\n\nБолее того, она вовсе НЕ недурная, если посмотреть повнимательнее. Да не вода, сфера!\n\nСосредоточься, Тузвколоде! Иначе с этим заданием не справиться!", rewards = "Вы получите:\n\n"},
[1955] = {title = "Поединок с демоном", objective = "Убейте демона сферы, а потом поговорите с Табетой.", description = "У нас есть сфера призывателя, остается изгнать из нее демона.С этим я легко справлюсь.\n\nТебе придется куда труднее. Как только демон изойдет из сферы, убей его.\n\nГлавное – не медлить. Если ты провозишься слишком долго, он вернется в сферу и нам придется начать сначала!\n\nГотовься к схватке, <имя>. Вспомни самые сильные заклинания и держи под рукой зелья. Если у тебя есть друг, можешь позвать его. Сражение будет нелегким.", progress = nil, completion = "Великолепно, Сипсик. Тебе удалось преподать этому демону урок, который он надолго запомнит.\n\nТеперь он трижды подумает, прежде чем вновь сунуться в наш мир. Однако если это произойдет, единственной целью демона будет найти того дерзкого смертного, что одолел его когда-то. Скорее всего, он вернется с приятелями. Огромными, жуткими приятелями, жаждущими твоей крови \n\nНу что, Сипсик, тебе уже страшно?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1956] = {title = "Сила Ульдамана", objective = "Добудьте обсидиановый источник силы и принесите его Табете в Пыльную трясину.", description = "Демон уничтожен, остается завладеть источником энергии. К сожалению, самые лучшие источники энергии – старые, и заполучить их нелегко. Судьба любит над нами подшутить, а?\n\nИтак, тебе придется отправиться в Ульдаман и победить тамошнего обсидианового часового. Он большой и сильный, а уж какой у него источник энергии!\n\nУдачи тебе, <имя>. Ну, а если она от тебя отвернется... приятно было познакомиться.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[1957] = {title = "Волнолов маны", objective = "Убейте 12 волноловов маны за отведенное время.", description = "Мы почти закончили, осталось самое опасное.\n\nНужно вдохнуть силу в пустую сферу призывателя. Для этого придется обуздать энергию провала Маны. Я произнесу заклинание, оно временно создаст нужный нам провал, из которого хлынут твари, волноловы маны. Тебе придется одолеть их, и тогда я смогу собрать воедино их силу.\n\nТвоя задача – убить достаточно волноловов маны, пока провал открыт, а я уж соберу всю энергию в твою сферу.", progress = nil, completion = "Надо же, ты справился! Я в тебе не сомневалась! Ну ладно, чуть-чуть сомневалась, даже не чуть-чуть... Но не так уж сильно.\n\nЧестно.", rewards = "Вы получите:\n\n"},
[1958] = {title = "Небесная сила", objective = "Тебе есть, чем гордиться, Кусачаявода. Побежденные тобой существа убили многих магов.\n\nНебесный шар готов. Если хочешь, я могу водрузить его на посох. Выбор за тобой. Лично я взяла бы шар, но советов давать не буду.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНебесная сфераНебесный посох\n\nВы также получите:\n\n"},
[1959] = {title = "Задание Анастасии", objective = "Поговорите с Анастасией Хартвелл.", description = "Маги Подгорода заметили в городе выплеск магической энергии и обратились к чародеями Орды с просьбой выяснить, что же происходит.\n\nПодробности тебе расскажет Анастасия Хартвелл. Поговори с ней, она живет в Квартале Магов Подгорода.", progress = nil, completion = "Это правда. В нашем городе произошел выплеск магической энергии. Мы не поняли, что именно произошло, и даже к добру это или к худу. Не хватает информации…\n\nЧто подводит нас к разговору о задании.", rewards = "Вы получите:\n\n"},
[1960] = {title = "Лавка алхимика", objective = "Возьмите свиток заклинания Проявления и ящик с шкатулками-духоловками за спиной у Анастасии Хартвелл. Принесите 3 заполненных шкатулки-духоловки, ящик со шкатулками духоловками и заклинание Проявления Анастасии в Подгород.", description = "В лавке алхимика Алжернона, что в Районе Фармацевтов, происходит что-то странное. Там бродят странные невидимые существа, сотканные из магической энергии.\n\nВозьми у меня за спиной шкатулки-духоловки и свиток с нужным заклинанием. Воспользуйся свитком в лавке, подчини этих существ и загони их в шкатулки. Как только наберешь достаточно, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием.", progress = "Ну, в чем же там дело, Чёрнобог? Тебе удалось поймать невидимых тварей?", completion = "Отлично, Чёрнобог. Лучшие умы Подгорода займутся изучением невидимых тварей. Мы выясним, откуда они взялись в нашем городе.\n\nЕсли дело в возникновении провала Маны, потребуется определить, случайно он возник или нет. Если не случайно,а в результате действий враждебных сил, нам придется готовиться к появлению более серьезных противников.", rewards = "Вы получите:\n\n"},
[1961] = {title = "Сбор материалов", objective = "Принесите 10 кусков льна и 6 самоцветов маны Даралана Джозефу Грегориану.", description = "Тебе пора обзавестись первым облачением мага, <имя>. Одеяние – знак твоего особого положения, свидетельство твоего достоинства.\n\nДля создания нужного одеяния тебе понадобятся самоцветы маны от даларанских магов из Серебряного бора. Они верят примерно в то же, во что и мы, поэтому убивать их нехорошо, но раз они не могут противостоять нам, значит жизни они не заслуживают.\n\nОтнеси камни и несколько кусков льна Джозефу Грегориану в суконную лавку Квартала Магов.", progress = "Анастасия предупредила меня о твоем приходе. Я готов сшить тебе одеяние. Где же лен и самоцветы?", completion = "Отличный материал. Оценить качество самоцветов я не могу, но вскоре мы узнаем, подходят ли они для создания одеяний из чароткани...", rewards = "Вы получите:\n\n"},
[1962] = {title = "Одеяние из чароткани", objective = "Вот твое новое одеяние, Тузвколоде. Носи на здоровье.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПростые одеяния из чароткани"},
[1963] = {title = "Изувеченная Длань", objective = "Убейте Тазана и принесите его сумку Терзоку в расселину Теней в Оргриммаре.", description = "Вождь слишком хитрит и осторожничает. Он не хочет пускать в ход всю мощь Орды. Изувеченная Длань вернет Орде былую гордость!\n\nМы тайно копим силы и исподтишка наносим удары неосторожным врагам. Докажи свою доблесть, выполни мое задание!\n\nТролль по имени Тазан торгует с пиратами близ Кабестана. У него есть нужные мне сведения. Убей его и принеси мне его сумку.", progress = "Только глупец может подумать, будто открытый удар топором опаснее кинжала в спину!", completion = "Хм. Я, конечно, рад слышать, что Тазана больше нет в живых, однако от запертой сумки проку мало. Нам нужно то, что внутри!\n\nВот и второе задание для того, кто стремится вступить в клан Изувеченной Длани!", rewards = "Вы получите:\n\n"},
[1978] = {title = "Стражи смерти", objective = "Отнесите гроссбух Андрона Вариматрасу в Зал Темной Госпожи в Подгороде.", description = "Синдикат? Никогда бы не подумал. Низко же пали владыки Альтерака после предательства.\n\nЛорд Вариматрас будет доволен, и раз именно ты <совершил/совершила> это открытие – тебе и сообщать о нем.\n\nАх да, как я мог забыть?\n\nДобро пожаловать в ряды стражей смерти.", progress = "Да?", completion = "Хм, любопытно. Стражи смерти превосходно справились со своими обязанностями.\n\nСудя по всему, ты ждешь благодарности за свои подвиги. Скоро это станет для тебя привычным делом, Соулнце. Стражам смерти не помешают талантливые новички.", rewards = "Вы получите:\n\nКлинок хитрости"},
[1998] = {title = "Фенвик Татрос", objective = "Убейте Фенвика Татроса и принесите его голову Менниту Каркаду в Квартал Разбойников Подгорода.", description = "Лорд Вариматрас сообщил мне о грозящей Отрекшимся опасности, с которой следует немедленно разобраться. Во всем виноват Фенвик Татрас, вождь нежити, поселившейся в Серебряном бору.\n\nЯ немедленно вспомнил о тебе, <имя>, и сразу понял, кому следует доверить это задание. Ты не <обделен/обделена> талантами и выполнишь поручение безукоризненно.\n\nПо последним сведениям от стражей смерти, Татроса видели неподалеку от разрушенной пристани озера Лордамер.", progress = "Я целиком положился на тебя. Выполни распоряжение лорда Вариматраса.", completion = "Прекрасно, Саехримнир. Ты оказался достойным помощником, а посему настало время продолжить твое обучение темным искусствам.", rewards = "Вы получите:\n\n"},
[1999] = {title = "Предметы торговли", objective = "Отыщите отчет о состоянии Даларана и отдайте его Менниту Каркаду в Квартале Разбойников Подгорода.", description = "Маги братства Кирин-Тора в Янтарной Мельнице хранят важные документы, касающиеся положения дел в Даларане. Эти сведения удалось вытянуть из одного пленника. Лорд Вариматрас поручил стражам смерти добыть эти документы.\n\nЧесть выполнить это задание выпала тебе, <имя>. Для задания понадобится кое-какое снаряжение и умение вскрывать замки. Поговори с Эстеллой Джендри, она поставляет нам обмундирование. Попроси у нее набор инструментов, перед тем как отправляться в путь.", progress = "Удалось отыскать документы, Саехримнир?", completion = "Прекрасно, Саехримнир. Тебе удалось освоить искусство вскрытия замков куда быстрее, чем я ожидал.\n\nВижу, я был прав, положившись на тебя. Поверь, мальчик мой, ты далеко пойдешь.", rewards = "Вы получите:\n\n"},
[2018] = {title = "Испытание Рокара", objective = "Убейте надзирателя Глибби и отдайте его свисток Рокару Тени Клинка в Дуротаре.", description = "Что, очередной ученик Терзока? Ну, может, я и впрямь смогу тебя кое-чему научить. Не то, чтобы мне было до тебя дело, просто неохота, чтобы твоя смерть была на моей совести.\n\nНо сначала докажи, что ты этого <достоин/достойна>.\n\nДолжен тебе сказать, <имя>, что я недолюбливаю эту Торговую Компанию. Здешние земли напоминают мне Дренор, а эти гоблины их губят. Может быть, если убить их наблюдателя в Нефтяном болоте, их планы потерпят крах?Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[2019] = {title = "Профессиональные инструменты", objective = "Вернитесь к Терзоку в Расселину Теней в Оргриммаре.\n\nПрилагается предмет: \n", description = "Ну вот, <имя>. Думаю, они тебе пригодятся. Я их сделал своими руками, так что могу поклясться: лучших отмычек не бывает.\n\nМожешь не рассказывать, зачем они тебе. Планы Терзока меня не интересуют, я теперь в отставке и хочу жить спокойно.\n\nЕсли вдруг тебе понадобятся новые отмычки, приходи ко мне. Но лучше береги эти!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[2038] = {title = "Пропавшее снаряжение Бинглза", objective = "Найдите и верните Бинглзу гаечный ключ Бинглза, отвертку Бинглза, молот Бинглза и сорвиголовку Бинглза.", description = "Мало того, что они вторглись в наши края, эти трогги атаковали меня с ближайшего острова и украли мои инструменты и особую взрывчатку – сорвиголовку Покрышкинса. Без вертолета и взрывчатки движению не обойтись!\n\nВерни мне инструменты и отыщи сорвиголовку, <имя>. За Гномреган!", progress = "Rainon! Где мои вещи?!", completion = "Ты оказал движению огромную услугу, Rainon. Скоро трогги и лепрогномы узнают, что такое воздушная атака!", rewards = "Вы получите:\n\nПолетные перчатки Бингла"},
[2039] = {title = "Найти Бинглза", objective = "Найдите Бинглза Покрышкинса в Лок Модане.", description = "Мы потеряли связь с Бинглзом! Он был отправлен в разведывательный полет над Гномреганом, и уже неделю от него нет никаких известий. Я знаю только то, что он отправился в разведку и потерпел крушение.\n\nПоследний раз его видели над озером Лок. Возможно, вы сможете выяснить, что с ним, <имя>.", progress = nil, completion = "Значит, Гноарн сомневается во мне как в разведчике? Интересно, почему...\n\nЛадно, не берите в голову, мне нужна ваша помощь! Нет! Ваша помощь нужна нашему общему делу!", rewards = "Вы получите:\n\n"},
[2040] = {title = "Битва под землей", objective = "Принесите Шони Молшунье в Штормград зубчатый спрек-механизм гномов из Мертвых копей.", description = "Гномреган захватили трогги! Ситуация крайне тяжелая, но, быть может, вы cможете помочь, <имя>.\n\nГлубоко под землей, в Мертвых копях, находится действующий гоблинский резак. Найдите его и принесите его источник питания. С его помощью мы сможем обеспечить наши автогиробуроройки достаточной энергией, чтобы пробиться через каменные границы Гномрегана и открыть дорогу армии гномов!", progress = "Вы нашли зубчатый спрек-механизм гномов, Хрофтгор?", completion = "Хорошая работа, Хрофтгор. Благодаря вам день освобождения Гномрегана приблизился еще на шаг!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСнежные рукавицыСоболий жезл\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[2041] = {title = "Разговор с Шони", objective = "Поговорите с Шони Молшуньей в Штормграде.", description = "Возможно... Возможно, вы поможете нам в битве за Гномреган.\n\nВ Штормграде вы найдете командира нашей подземной штурмовой группы, Шони Молшунью. Шони нужна помощь в сооружении автогиробуророек.\n\nВы найдете ее среди дворфов в Штормграде.\n\nУдачи, <имя>.", progress = nil, completion = "Вы с известиями от центрального командования?", rewards = "Вы получите:\n\n"},
[2078] = {title = "Месть Гиромачта", objective = "Найдите первого помощника Гелхака, Бешенатора 4100, и отведите его к Гелхаку.", description = "Эй, сухопутное создание, нужно, чтоб ты <нашел/нашла> моего первого помощника.\n\nБерешь этот ключ, вставляешь ему в башку и ведешь сюда, чтобы он опять служил своему кэпу.\n\nЭтим мурлокам и их главарю не шибко понравится, когда ими займется мой первый помощник!", progress = "И где есть мой первый помощник, Рабинович? Пойдешь на корм акулам, если не поторопишься!", completion = "Да-а-а... А ты, оказывается, больше, чем желторотая собачья акула, крыса ты сухопутная.\n\nКэп тебя, может, даже пустит палубу драить, если так и дальше пойдет...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЭликсир водного дыхания"},
[2098] = {title = "Помощь Гиромачту", objective = "Отыщите три фрагмента ключа и отнесите их Гелхаку Гиромачту.", description = "Жизнь пирата нелегка, сухопутное ты создание. Это не только грабежи да пьянки! Увы, мой корабль затонул совсем рядом с берегом из-за этих мерзких жесткозубов.\n\nПервое, что мне нужно, – это чтоб мой первый помощник был в рабочем состоянии!\n\nКогда меня вынесло на берег, ключ от моего первого помощника сломался от удара о скалы, и его части растащили обитающие на Темном Берегу звери. Краем глаза я заметил разъяренных крабов, свирепых лесных долгоходов и мурлоков, обшаривающих останки корабля...", progress = "Эй, сухопутник, еще не нашелся мой сломанный ключ?", completion = "Ах ты ж, акула собачья! Тебе удалось все найти! Скоро мой первый помощник будет в полном порядке, и эти звери не знают, что их тогда ждет!\n\nА кстати, ты не видел моего первого помощника?", rewards = "Вы получите:\n\n"},
[2118] = {title = "Зачумленные земли", objective = "Поймайте бешеного колючешерстного медведя отведите его Тарнариуну.\n\nЕсли вам не удастся поймать зверя и вы потеряете ловушку, вернитесь к Тарнариуну Целителю Деревьев и попросите у него еще одну.", description = "Болезнь расползается по Темному Берегу, захватывая сознания и тела всех, до кого добирается.\n\nНа медведей-осотников она подействовала особенно жестоко. Некогда благородные звери стали инструментами разрушения, бешеными и неистовыми. Возможно, у меня есть средство от этой напасти.\n\nОтнеси в лес эту ловушку и положи ее на землю. Любой бешеный колючешерстный медведь, попавший в нее, станет на короткий период времени послушным. В таком состоянии он будет следовать за тобой. Приведи его сюда, <имя>.", progress = "Вы привели ко мне больного зверя, Борро?\n\nЕсли вам не удалось захлопнуть ловушку, не беспокойтесь – надежда Тарнариуна живет вечно. Если вам нужна еще одна ловушка, отмените ваше задание и вновь обратитесь ко мне.", completion = "Наша работа только начинается, Wrestlecake. Вы готовы к следующему заданию?", rewards = "Вы получите:\n\n"},
[2138] = {title = "Избавление от заразы", objective = "Очистите лес от 20 бешеных колючешерстных медведей и возвращайтесь к Тарнариуну Исцелителю Деревьев на Темный Берег.", description = "Как я и боялся, целительное средство не действует.\n\nМеня очень печалит, что я вынужден приговаривать к смерти создания природы, но больных колючешерстных медведей придется истребить.\n\nВозвращайтесь в лес и уничтожьте 20 бешеных колючешерстных медведей, <имя>. Скорее всего, это не остановит зло, но хотя бы ненадолго замедлит наступление заразы на наш лес и его обитателей.", progress = nil, completion = "Вы сослужили большую службу Аубердину, Wrestlecake, но ваша работа на этом не закончена.\n\nОтдохните, а затем возвращайтесь ко мне.\n\n...И, Wrestlecake, укрепитесь духом и разумом для дальнейшего кровопролития.", rewards = "Вы получите:\n\n"},
[2139] = {title = "Надежда Тарнариуна", objective = "Найдите и убейте мать-медведицу.", description = "За выживание нашего народа и безопасность наших земель мы платим высокую цену, <имя>.\n\nВы пролили кровь слуг природы; вы сразили множество больных зверей. Народ Аубердина в долгу перед вами, поскольку боль истерзанного леса немного утихла – пусть и ненадолго.\n\nУ меня есть для вас последнее задание, но предупреждаю: вам снова придется убивать. Надеюсь, это последний раз, когда мне приходится побуждать вас к этому, <имя>. В пещере к северо-востоку отсюда, близ Башал'Арана, живет мать-медведица. Убейте ее.", progress = nil, completion = "Вы с честью и мужеством сражались на благо Аубердина, Wrestlecake. В наших измученных войной землях смерть и отчаяние стали нормой. Многие уже не пытаются встретить лицом к лицу испытания в нашем новом доме, их выбор – либо скрываться в своих жилищах, либо бежать в более укрепленные и безопасные земли Альянса.\n\nСпасибо вам, Wrestlecake. Может быть, вскоре мы с вами будем плечом к плечу биться против другого врага.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВечнозеленые перчаткиНакидка лесов\n\nВы также получите:\n\n"},
[2158] = {title = "Отдых и покой", objective = "Побеседуйте с Фарли, хозяином \"Гордости льва\".", description = "Каждому путнику рано или поздно нужно отдохнуть и восстановить силы – а для этого нет места лучше, чем таверна \"Гордость льва\".\n\nТам всем заправляет мой лучший друг Фарли. Скажи ему, что ты от меня – может, он даже скидки тебе даст на еду и выпивку.\n\nНайти \"Гордость льва\" несложно: нужно просто идти по дороге на юг. Не бойся, с пути не собьешься!", progress = nil, completion = "Наш девиз – покой и отдых для всех усталых и продрогших! Прошу, садись у огня, отдохни с дороги.\n\nХочешь – отведай, чем у нас кормят, да и выпить чего-нибудь тебе не помешает...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМаленькая тыкваОсвежающая ключевая вода\n\nВы также получите:\n\n"},
[2159] = {title = "Посылка в Доланаар", objective = "Отнесите посылку хозяину таверны Кельдамиру в Доланааре.", description = "Привет тебе, <юный/юная:c> <класс>. Не окажешь ли ты мне услугу? У меня тут сверток с травами, который надо доставить в Доланаар. Но я еще не закончил кое-какие дела с друидами Тенистой долины и пока что не могу отлучиться.\n\nНе отнесешь ли ты посылку? Ее надо доставить Кельдамиру – хозяину таверны в Доланааре. Таверна стоит у дороги к югу отсюда.", progress = "Чем я могу тебе помочь, юноша? Желаешь отдохнуть на постоялом дворе? Или тебе нужен камень возвращения?", completion = "Ах да, травы из Тенистой долины! Жаль, что Портанниус сам не смог ее доставить – нам с ним много что надо обсудить. Но я все равно рад получить эту посылку и познакомиться с тобой.\n\nПокуда ты здесь – чувствуй себя как дома. Герои должны быть крепки телом и духом, так что если выпадает возможность отдохнуть и подлечиться, надо ей пользоваться! Забота о теле и духе только приблизит тебя к победе!\n\nТак что располагайся поудобнее...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДарнассский блюОсвежающая ключевая вода\n\nВы также получите:\n\n"},
[2160] = {title = "Припасы для Таннока", objective = "Отнесите ящик с припасами хозяину таверны Танноку Молоту Стужи в Караносе.", description = "Похоже, тебе не впервой путешествовать, и трудности в дороге тебя не пугают. Что ж, раз уж ты все равно собираешься в путь, может, заодно прихватишь и посылочку в Каранос? Ее нужно отдать хозяину таверны.\n\nТы ведь собираешь заглянуть в таверну, верно? После всего, что тебя ожидает в пути – а ожидает тебя много чего, уж можешь мне поверить, – ты наверняка захочешь отдохнуть и перевести дух.\n\nТак вот, я тебя и прошу – передай кое-что помощнику хозяина; его зовут Таннок Молот Стужи. Я сам в одиночку до Караноса не доберусь, а патруля горных пехотинцев еще ждать и ждать...", progress = "А, привет-привет! Заходи, садись у огня: тут и согреешься, и доброго эля выпьешь, с дороги-то...", completion = "О, гляди-ка, Ручник Ржавозубчик все-таки прислал припасы! Я уж начинал беспокоиться: с тех пор, как тут поселились трогги, из Старой Наковальни вести почти и не доходят.\n\nЯ тебе очень благодарен, Бронгард, просто словами не передать, как. Ты тут располагайся, будь как дома, дорога-то была не из легких!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖесткая солонинаОсвежающая ключевая вода\n\nВы также получите:\n\n"},
[2161] = {title = "Ноша батрака", objective = "Отнесите сумку Укора хозяину таверны Гроску в Колючий Холм.", description = "Извини... Ты не <мог/могла> бы мне помочь?\n\nУ меня тут тяжеленная сумка с припасами. Я шел по дороге, на меня нападали и скорпиды, и пауки, и еще более страшные твари! Я нес припасы в долину Испытаний, потому что думал, что они там нужны, а я люблю помогать. Но оказалось, что припасы им не нужны! И вот мне придется тащить эти припасы обратно в Колючий Холм, а я так боюсь опасных тварей, обитающих тут...\n\nНе <мог/могла> бы ты отнести посылку вместо меня? Я ведь простой батрак, а ты-то – <герой/героиня>! Ты, небось, ничего не боишься...\n\nОтнеси эту сумку хозяину таверны Гроску. Спасибо тебе большое!", progress = "Добро пожаловать в Колючий Холм!", completion = "А-а, это припасы, которые Укор понес в долину Испытаний! Что, не пригодились? Ну да, конечно, они любят морить голодом  молодых героев вроде тебя. Говорят, будто это закаляет дух!\n\nСпасибо, что принес припасы обратно. Пусть пока полежат на полочке... Погоди, не уходи, дай я тебя сначала чем-нибудь угощу!\n\nИ не забудь отдохнуть у нас на постоялом дворе. Конечно, ты отважен и готов горы свернуть, но если не отдохнешь, силенок не будет, а это не пойдет на пользу ни тебе, ни Орде!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЧерствая краюха хлебаОсвежающая ключевая вода\n\nВы также получите:\n\n"},
[2178] = {title = "Спокойная жизнь долгоногов", objective = "Принесите 5 кусков мяса долгонога Аландариан Песне Ночи в Аубердин.", description = "Чувствуете этот восхитительный аромат? Это мой секретный рецепт, <имя> – свежесваренная похлебка из долгонога. Настоящий деликатес!\n\nНе хотите ли узнать рецепт?\n\nНо прежде, чем я вас научу готовить это блюдо, вы должны доказать мне, что умеете управляться с долгоногами.\n\nНет, я вовсе не жду, что вы пойдете, приручите себе одного и приедете ко мне на нем верхом! Но если бы вы могли убить несколько птиц и принести мне их сочного мяса, это, пожалуй, убедило бы меня показать вам, как же готовится похлебка из долгонога.", progress = "Мой горшок пуст, а я проголодалась! Что ж вы так долго?", completion = "Фантастика! Попробуйте сами и скажите, что вы думаете об этом, Wrestlecake!", rewards = "Вы получите:\n\nРецепт: похлебка из долгоногаПохлебка из долгонога"},
[2198] = {title = "Порванное ожерелье", objective = "Найдите создателя ожерелья, чтобы узнать, чего оно стоит.", description = "Вы нашли потускневшее ожерелье, хотя даже то, что оно потускнело, не может исказить искусную, даже отчасти магическую работу создателя. Ожерелье было разрушено, поскольку в собранном виде в нем явно не хватает трех драгоценных камней. На обратной стороне ожерелья – почти стершаяся печать Стальгорна. Ниже печати – выгравированы три небольших буквы: \"ТдК\".\n\nЕсли вы хотите восстановить ожерелье, вы будете должны узнать о его происхождении. Возможно печать и эти буквы, помогут вам в этом.", progress = "Ты ошибся гномом, приятель! Меня там и близко не было. Ты ничего не докажешь!\n\nПодожди, а тебе вообще, чего надо??? Что за... Где ты это взял?", completion = "Да, я – тот ювелир, который создал это ожерелье. Но больше ты из меня ничего клещами не вытянешь. За все надо платить, приятель, и информация не исключение. Если ты хочешь, чтобы я тебе помог, придется сначала помочь мне.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2199] = {title = "Мудрость за деньги", objective = "Принесите пять серебряных слитков Талвашу де Кисселю в Стальгорн.", description = "Я прославленный в нашем Стальгорне ювелир! Ну, был прославленным... У меня сейчас трудные времена, и все из-за козней конкурента! Дурная репутация в нашем ремесле приводит к финансовому краху. И в результате мое доброе, но недавно опороченное имя теперь медного гроша не стоит.\n\nЯ хочу, чтобы ты <принес/принесла> мне пять серебряных слитков, чтобы я сумел закончить заказ – первый за целую вечность!\n\nЕсли ты принесешь мне серебряные слитки, я отвечу на твои вопросы по поводу ожерелья.", progress = "Ты принес мне пять серебряных слитков, как я просил? Я поделюсь с тобой моей печальной повестью об ожерелье, коим ты ныне владеешь... Но только после того, как я получу слитки! Неужели ты не поможешь бедному гному?", completion = "Для меня теперь нет дороже друга, и плевать, что скажут другие... шучу, шучу! Правда, спасибо тебе огромное!\n\nИтак, ожерелье, которое теперь у тебя, – одно из лучших моих творений, но в нем не хватает трех драгоценных камней, что помогали удерживать в нем магическую силу. Некоторое время назад я сделал его для одного паладина. Он по личному побуждению отправился в поход, дабы выжечь \"злую скверну\" с раскопа в Бесплодных землях, в месте, называемом Ульдаман.\n\nВ общем... этот паладин погиб в Ульдамане, и это стало началом моих горестей.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2200] = {title = "Назад в Ульдаман", objective = "Выясните, где именно в Ульдамане находится ожерелье Талваша. Убитый паладин, о котором он упоминал, был последним владельцем этого ожерелья.\n\nПрилагается предмет: \n", description = "Мой конкурент распустил слухи, что мое ожерелье проклято и что оно-то и сгубило паладина. Нечего и говорить, что покупателей на проклятые ювелирные изделия больше не нашлось.\n\n<имя>, я предлагаю тебе сделку – найди драгоценные камни, и я восстановлю ожерелье, а ты расскажешь всем, что на моих изделиях НЕТ никакого проклятия!\n\nПопытайся найти разгадку гибели паладина в Ульдамане – может, его тело все еще там, ведь он последний владел этим ожерельем! Когда ты найдешь камни, воспользуйся вот этим – так ты сможешь связаться со мной в Стальгорне.", progress = nil, completion = "В дневнике говорится, что после больших усилий паладин выяснил, где находятся все три камня:\n\nРубин спрятан дворфами Кузни Теней на огражденной завалами территории во время сражения с троггами за контроль над Ульдаманом.\n\nТопаз трогги спрятали в вазе, под боком у несколько неожиданных поселенцев Ульдамана – дворфов Альянса!\n\nНаконец, сапфир забрал себе старейшина троггов.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2201] = {title = "Время собирать камни", objective = "Найдите рубин, сапфир, и топаз, которые спрятаны в разных местах Ульдамана. Когда найдете, свяжитесь с Талвашем де Кисселем, используя фиал Видения, который он предоставил.\n\nИз дневника вы узнали следующее:\n*Рубин укрыт в забаррикадированной Кузне Теней.\n*Топаз спрятан в урне в одной из областей, занятых троггами, недалеко от расположения дворфов Альянса.\n\n*Сапфир присвоил себе Гримлок, лидер троггов.", description = "Дневник паладина дает, скорее всего, единственную подсказку, о том, где искать камни из ожерелья. Если верить записям паладина, то придется иметь дело с дворфами Стальгорна и троггами, борющимися за контроль над раскопками в Ульдамане.\n\nВооружившись этим знанием, отнесись к поискам этих камней серьезно. Когда ты найдешь камни, сообщи об этом Талвашу через фиал Видения и следуй полученным от него инструкциям.", progress = "Образ Талваша появляется на поверхности воды в чаше.\n\n\"Ого! Да ты еще жив! Удалось ли тебе найти камни? Я так надеюсь, что тебе удастся спасти мою репутацию. Умоляю тебя, скажи, что ты не терял времени даром и вызываешь меня не для того, чтобы просто поболтать. Подобные сеансы стоят недешево, а я сейчас весьма стеснен в средствах.\"", completion = "Ух ты! Да это и вправду три потерянных камня. Отличная работа! Но, к сожалению, это еще не все.\n\nНет, я не пытаюсь тебя надуть, поверь мне, |3-6(Жрец). Дело в особенностях создания магической бижутерии - настоящей магической бижутерии от Талваша де Кисселя! Для того чтобы создать подобную вещь, нужен большой запас магической энергии, которой в этом ожерелье уже не осталось.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2202] = {title = "В Ульдаман за реактивом", objective = "Принести 12 грибов-малиновиков Джаркалу Замшелому Клыку в Каргат.", description = "Мне рассказали о недавно открытом растении, грибе-малиновике. Этот гриб растет целыми колониями на раскопках Ульдамана, в самой глубине. Наверное, встречается еще где-то, но мне известно только одно место. Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься.\n\nОтыщи эти грибы и принеси мне дюжину. Только учти: они могут выпустить облако ядовитых спор, если ты их случайно встряхнешь.\n\nЕсли выполнишь мое поручение, я сделаю для тебя один из моих знаменитых восстановительных эликсиров!", progress = "Ты принес грибы-малиновики для моих алхимических исследований? Нет грибов – нет награды!", completion = "Молодец, Снатяжкой, ты снова показал, на что способен! Эти грибы очень пригодятся для моих исследований!\n\nА теперь, как я и обещал, можешь насладиться вкусом одного из самых действенных восстановительных составов из моих личных запасов...\n\nЕсли ты тоже увлекаешься алхимией, мы можем вдобавок поговорить о других делах. В любом случае, благодарю за помощь!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nПриводящее в сознание зелье"},
[2203] = {title = "Пробежка по Бесплодным землям-2", objective = "Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Джаркалу Замшелому Клыку в Каргат.", description = "Ты <оказал/оказала> мне неоценимую помощь, <класс>. Надо бы в награду дать тебе рецепт эликсира, который ты <пробовал/пробовала>... Но прежде я дам тебе еще одно опасное задание. Вот моя просьба.\n\nВ этом сундучке находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опаленного дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне.\n\nДобудь мне кровь дракона, и я отдам тебе рецепт.", progress = "Ты уже наполнил сосуды кровью опаленных драконов-стражей? Знаю, задание опасное... но в случае успеха тебя ждет рецепт восстановительного эликсира. Игра стоит свеч, мой друг... игра стоит свеч...", completion = "Между нами, алхимиками, говоря, ты просто герой! Вот, возьми этот рецепт. Пусть он принесет тебе успех и богатство, как и мне!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриводящее в сознание зелье\n\nВы получите:\n\n"},
[2204] = {title = "Восстановление ожерелье", objective = "Добудьте источник энергии из самого мощного волшебного создания, которое найдете в Ульдамане и доставьте его Талвашу де Кисселю в Стальгорн.", description = "Тебе понадобится немного \"магической силы\" для ожерелья, и Ульдаман – лучшее место, чтобы ее раздобыть. Там бегает множество магических созданий. Поймай самое крупное и злобное, вынь из него источник магической силы и принеси его мне. Я уверен, что смогу вплавить его в ожерелье.\n\nБез источника силы, ожерелье починить невозможно. Возвращайся ко мне в Стальгорн, когда раздобудешь что-нибудь подходящее и мы быстро наладим для тебя эту вещь.", progress = "Ты не останавливался даже чтобы привести себя в порядок после Ульдамана, так ведь? Пришел прямо сюда благоухая подземельными ароматами. Что ж будем надеяться, что все эти жертвы были принесены не напрасно.\n\nУдалось тебе добыть источник силы для ожерелья?", completion = "Отлично! – Я рад видеть и тебя и этот источник силы в целости и сохранности. Теперь, когда драгоценные камни возвращены на сове место, восстановить само ожерелье, займет не больше минуты... Как только я это сделаю, оно станет твоим!\n\nВолнуешься, да? просто дрожишь от нетерпения? Тааак, на чем я в прошлый раз сосредотачивал фокус заклинания...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2205] = {title = "Выход на ШРУ", objective = "Доставьте пакет от Керина Сильвиуса мастеру Матиасу Шоу в казармы Штормграда.", description = "Значок? А, это ерунда, рыбка – ничего такого, что было бы тебе не по силам. Ты выглядишь так, что Матиас может принять тебя за <торговца/торговку> сыром. Тебя, детка, вряд ли можно счесть настоящим разбойником. Однако у меня есть для тебя работа, и я хочу, чтобы она была выполнена.\n\nК делу! Доставь этот пакет Матиасу: возможно, у него тоже найдется для тебя пара заданий.\n\nНе задерживайся!", progress = "Чем могу служить, |3-6(Разбойник)?", completion = "Итак, тебе удалось меня отыскать. Глядя на тебя, я бы сказал, что для тебя это было серьезным испытанием как физических сил, так и умственных способностей.\n\nНу что, попросить Рензика показать тебе, где здесь постоялый двор, или ты сразу приступишь к работе?", rewards = "Вы получите:\n\n"},
[2206] = {title = "Держи-хватай!", objective = "Найдите портового начальника из Братства Справедливости и добудьте расписание поставок для мастера Матиаса Шоу.", description = "Наши полевые агенты сообщают о серьезной активности Братства Справедливости к югу от Златоземья. В этих донесениях указывается, что братство захватило лагерь Джерода и теперь использует его как перевалочный пункт для переправки больших партий контрабанды из Красногорья в Западный Край.\n\nМне нужно, <имя>, чтобы вы проникли в доки и добыли мне расписание поставок. Скорее всего, портовой начальник носит его при себе.\n\n...и кстати, <имя>, если вас обнаружат – вы никогда не слышали о ШРУ...", progress = "С каждой минутой, что вы ошиваетесь тут, в казармах, ваша жизнь становится короче на 60 секунд.", completion = "Я потрясен... Потрясен, что Керин наконец-то нашла новобранца, из которого действительно может выйти толк. Возьмите этот клинок, Хэллпер. Придет день, когда ШРУ вновь призовет вас на службу. Совершенствуйте свое мастерство, пусть глаза ваши будут всегда открыты, а клинок – наточен.\n\nВы не заметите нас, но почувствуете, когда мы будем рядом...", rewards = "Вы получите:\n\nКлинок хитрости"},
[2218] = {title = "Путь к спасению", objective = "Поговорите с Хальфданом Чернобородом в Стальгорне.", description = "Еще одна заблудшая душа, стало быть, ищет наставничества? Полагаю, ты хочешь найти смысл жизни – смысл твоей жизни. Я тысячу раз видел, как другие герои искали работу.\n\nЧто же, сегодня тебе повезло. У Хограла найдется лекарство для твоего недуга.\n\nВот что ты сделаешь: иди по этой дороге до Стальгорна и там зайди в Заброшенный грот. Как окажешься там, найди воровскую гильдию и переговори с Хальфданом Чернобородом. Он укажет тебе путь к спасению.", progress = nil, completion = "Стало быть, ты считаешь себя настоящим мерзавцем? Достойным оказаться среди немногих избранных ребят Черной Бороды – стать офицером Тайного Круга?\n\nТолько настоящий прохвост так высоко себя ценит!\n\nТаких мы и ищем! Добро пожаловать, Скирди!", rewards = "Вы получите:\n\n"},
[2238] = {title = "Простая уловка", objective = "Найдите Онина Макмолота в Гномрегане.", description = "Понимаешь, король выгребает из шахты руду и камни. Таких богатств ни один гном за десять жизней не увидит.\n\nУ Тайного Круга есть свои жизненные ценности, <имя>. И эти ценности – драгоценности. Просекаешь?\n\nТеперь сдается нам, что королю надо бы поделиться, но так чтобы \"Вонючая Борода\" не знал, что мы берем свою долю, – ты улавливаешь нить?\n\nНам надо, чтобы ты <переговорил/переговорила> с Онином Макмолотом в Гномрегане и <вернулся/вернулась> с ответом. Этот хитрый дворф спрятался среди прокаженных. Так что поосторожнее.", progress = nil, completion = "Тсссс! Тише, балда. Нас подслушивают.", rewards = "Вы получите:\n\n"},
[2239] = {title = "Донесение Онина", objective = "Доставьте донесение Онина Хальфдану в Стальгорн.", description = "Рудник? Да, видел я, как эти жуткие бронированные паровые танки проходят к этому пункту каждый день.\n\nМои информаторы с востока доносят, что танк выходит из Стальгорна, заходит в карьер Гол'Болар, останавливается на перезаправку в Караносе, а потом орк знает зачем делает большой крюк вокруг Гномрегана, прежде чем вернуться в Стальгорн и разгрузиться.\n\nВсе в этом донесении, <раса>. Отнеси его Хальфдану, чтобы он смог обдумать следующий шаг.", progress = "Ну, как тебе запашок лепрогнома? Чего ухмыляешься?\n\nНу, какие вести от Онина?", completion = "Большой крюк? Клянусь собственной бородой!\n\nТы постарался на славу, Плашмет. Возьми вот этот кинжал и ступай. Круг призовет тебя снова, когда будет готов третий шаг.\n\nЧто такое третий шаг? Да тот, что идет после второго, а именно – хороший пинок тебе под зад.\n\nХочешь?", rewards = "Вы получите:\n\nКлинок хитрости"},
[2240] = {title = "Потайной чертог", objective = "Прочитайте журнал Бейлога, исследуйте, потайной чертог и потом доложите об увиденном геологу Грозовой Вершине.", description = "Теперь вернемся к насущным задачам.\n\nТебе предстоит исследовать чертог Хаз'Мула. Проблема в том, что он находится за огромной, запертой дверью! К счастью, я знаю, как ее открыть.\n\nЯ записал все в своем дневнике, здесь на столе. Моя группа и я заперты здесь... Так что ты, <имя>, <должен/должна> найти для нас чертог Хаз-Мула!\n\nПрочитай мой дневник и отправляйся в чертог. Потом доложи геологу Грозовой Вершине в Стальгорне.", progress = nil, completion = "Вы видели чертог Хаз'Мула? Потрясающе! Бейлог был уверен, что он существовал, но я, честно говоря, сомневался.\n\nСпасибо, Эфром. Теперь то, что вы обнаружили сподвигнет наших лидеров приложить все усилия к тому, чтобы отвоевать Ульдаман. А когда это место снова вернется под руку Стальгорна, все тайны Чертога Хаз'Мула будут нашими!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДворфийский натискПутеводная звезда Лиги исследователей\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[2241] = {title = "Катись, яблочко...", objective = "Отнесите розу Джаннока Сиарне в Дарнасс.", description = "Говорят, что я обезумел от любви.\n\nДа, я все время думаю о Сиарне. Да, мой дом полон рисунков и картин, с которых на меня смотрит Сиарна. Да, я часто целыми днями крошки в рот не беру, не сплю, не пью, а все плачу о нашей несбывшейся любви. Что в этом плохого?\n\nИ вот теперь она отказывается меня видеть. МЕНЯ! Я пытался письма ей писать, так она не желает ни с кем разговаривать, если только это не разбойник.\n\nНе отнесешь ли ты ей от меня этот цветок? И не забудь сказать ей, что он от Джаннока.", progress = "Какая прелесть! Ты принес цветочки на собственную могилу!", completion = "Если собрать все цветы, что присылает мне этот зануда Джаннок, впору цветочную лавку открывать! Ладно, как бы там ни было, нынешний посланец Джаннока может мне пригодиться...\n\nНе хочешь ли подрядиться на одно дельце, |3-6(Разбойник)?", rewards = "Вы получите:\n\n"},
[2242] = {title = "Зов судьбы", objective = "Найдите Сетира Древнего и принесите все, что сумеете найти, Сиарне.", description = "Нам кажется, что одно существо могло бы помочь нам понять, что происходит с лесами Тельдрассила. Увы, уговорить это существо может оказаться опасным делом.\n\nЭто сатир. Он скрывается на ветви на опушке Поляны Оракула. Пока всех, кто подходил к этому сатиру - с угрозами или добрым словом, - постигала мрачная судьба. Может, надо подкрасться к нему незаметно, <имя>?\n\nУзнай, что у Сетира Древнего в сумках, и возвращайся ко мне.", progress = "Ну так что там у Сефира Древнего обнаружилось, Плашмет?", completion = "Дурные вести, Плашмет. Похоже, что зараза, охватившая леса и реки Темного Берега, начинает расползаться и по нашему дому.\n\nТы сослужил добрую службу, но больше ты уже ничем не поможешь. Прими этот клинок в награду за службу Тельдрассилу.", rewards = "Вы получите:\n\nКлинок хитрости"},
[2258] = {title = "Пробежка по Бесплодным землям", objective = "Принесите 5 вторых желудков канюка, 10 клыков скального койота и 5 осколков каменных элементалей Джаркалу Смешанному Лишайнику в Каргат.", description = "<имя>, я хотел бы воспользоваться твоими услугами. Я довольно известный алхимик, и мне понадобились кое-какие реактивы, которые можно отыскать в Бесплодных землях.\n\nВот что мне нужно: 5 вторых желудков канюка, 10 клыков скального койота и 5 осколков каменных элементалей. Очевидно, что их можно добыть у самих тварей, но если ты не <любитель/любительница> сражений, можешь попросить о помощи друзей.\n\nЯ неплохо заплачу, если ты принесешь мне все необходимое.\n\nЧто скажешь?", progress = "Ты принес все необходимое? Пока не принесешь, платить не буду.", completion = "Молодец, Томпсон. Этого мне должно хватить на некоторое время. Вот обещанная плата.\n\nЕсли ты не против получить новое задание, то вот – мне нужны еще кое-какие реактивы. Некоторые из них можно найти только в глубинах ульдаманского раскопа. Добыть их нелегко, но и плата за помощь будет немалая.\n\nМожет быть, кое-что получше блестящих монет!", rewards = "Вы получите:\n\n"},
[2259] = {title = "Эрион Шепот Тени", objective = "Встретьтесь в Дарнассе с Эрионом Шепотом Тени.", description = "Не бойся, <имя>, я не стану посылать тебя к Сиарне. Эрион требует твоего присутствия в Анклаве Кенария. Не медли!", progress = nil, completion = "Пора идти дальше, |3-6(человек), – мир ждет.", rewards = "Вы получите:\n\n"},
[2260] = {title = "Директива Эриона", objective = "Отправляйтесь в Штормград и посоветуйтесь с Рензиком Ножом.", description = "Весть о ваших деяниях  получила широкую огласку, <имя>. Настолько далеко, что даже разведка Штормграда желает лично побеседовать с вами.\n\nДорога не беспошлинная и небезопасная, но возможность стажироваться в ШРУ – это вам не жук чихнул!\n\nВас ждет целый новый мир, <имя>. Отправляйтесь в Старый город Штормграда и поговорите с Рензиком Ножом в штаб-квартире ШРУ.", progress = nil, completion = "Вы откликнулись на призыв ШРУ, Рейнарт, и проделали долгий путь от дальних берегов, чтобы вступить в наши ряды. Однако вам многому предстоит научиться.", rewards = "Вы получите:\n\n"},
[2278] = {title = "Платиновые Диски", objective = "Поговорите с каменным Стражем и запомните все, что он передаст вам. Когда он закончит свой пересказ событий древности, активируйте диски Норганнона.", description = "Главные сокровища этого чертога – четыре огромных платиновых диска, каждый из которых украшен многочисленными символами неизвестного происхождения. Когда ты касаешься их, у тебя покалывает пальцы, и перед тобой возникает Каменный Страж.\n\n\"Приветствую тебя! Я – хранитель знаний. Создание земельников было подробно описано и сохранено на Дисках Норганнона.\"\n\nТы раскрыл сокровищницу никому прежде неизвестных знаний!", progress = "Голос каменного стража, кажется, проникает прямо в твою душу:\n\n\"Ты должен сначала дождаться распознания данных Дисков Норганонна; как только ты выполнишь это требование, тебе будет разрешено получить портативную версию сохраненных данных. Пожалуйста убедись, что ты полностью исследовал информацию в пределах этого хранилища.\"", completion = "Прослушав инструкции каменного Стража, ты снова получаешь доступ к Дискам Норганнона, теперь уже зная историю создания земельников, троггов и дворфов. Слабый, краткий гул доносится из глубины дисков. Каменный страж говорит: \n\n\"Теперь Диски синтезировались. Дотронься до них еще раз, чтобы получить личную копию.\"", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2279] = {title = "Платиновые Диски", objective = "Отнесите миниатюрную копию дисков Норганнона в Лигу Исследователей в Стальгорне.", description = "Ты прикасаешься к Дискам Норганнона, и пальцы снова покалывает. Диски издают странный скрежещущий гул, и твой мешок вдруг становится тяжелее. Внутри ты обнаруживаешь миниатюрную копию Дисков.\n\nНесомненно, для увлекающихся историей Азерота, это – неслыханная ценность. Лига Исследователей из Стальгорна как раз из таких. Возможно, они найдут применение этим дискам.", progress = "Да, могу я вам чем-нибудь помочь? Я, вообще-то занят, в настоящий момент, делом, которое представляет немалую важность для всей Лиги. Но я весь внимание.", completion = "Что это у вас там... ох мать моя... Откуда вы это взяли?\n\nНет, правда?\n\nВы кому-нибудь еще об этом расказывали?\n\nПРАВДА?!\n\nМой дорогой |3-6(Жрец), Вы, возможно, только что совершили открытие года в области археологии! Богов ради! Кого я пытаюсь надуть, открытие столетия! Если эти диски – то, о чем я думаю, то они будут тем ключом, который мы так долго искали! Теперь мы сможем раз и навсегда доказать магическое происхождение дворфов!", rewards = "Вы получите:\n\n"},
[2280] = {title = "Платиновые Диски", objective = "Отнесите миниатюрную копию дисков Норганнона кому-то из мудрецов с Громового Утеса.", description = "Ты прикасаешься к Дискам Норганнона, и пальцы снова покалывает. Диски издают странный скрежещущий гул, и твой мешок вдруг становится тяжелее. Внутри ты обнаруживаешь миниатюрную копию Дисков.\n\nНесомненно, для увлекающихся историей Азерота, это – неслыханная ценность. Лига Исследователей из Стальгорна как раз из таких. Возможно, они найдут применение этим дискам.", progress = "Мой юный друг, я видел, как ты решительно направляешься к моей палатке. То дело, ради которого ты ищешь моего совета, имеет значение для всей Орды? Или ты хочешь, чтобы перед тобой открылась вся мудрость вселенной?", completion = "Что это у нас тут?\n\nНевероятно, мой юный друг! На этих дисках записаны древние и давно утерянные тайны. Ты поступил мудро, принеся их мне.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2281] = {title = "Встречи в Красногорье", objective = "Пойдите к Приозерью в Красногорье и поговорите с Люцием.", description = "Посылать тебя в бой равноценно убийству. Рензику не нужны лишние покойники. Но тебе, <имя>, бояться нечего: для тебя найдется не такое опасное дело.\n\nОтправляйся в Красногорье и поговори там с Люцием – этот тип связан с ШРУ. Он постоянно отирается у пристани в Приозерье вместе с остальными бездельниками.", progress = nil, completion = "Что, Сурьма, не слишком-то у тебя ловкие пальчики, верно? Ну, да не беспокойся: я и не из таких делал отличных разбойников!", rewards = "Вы получите:\n\n"},
[2282] = {title = "Лесопилка Альтера", objective = "Откройте сундук Люция, достаньте Руну Воровства и вернитесь к Люцию в Приозерье.", description = "Я долгие годы обучал молодых воров. В конце концов не всякому плуту от рождения достается ловкость и проворство, как у старого Люция.\n\nРядом с дорогой стоит лесопилка Альтера. Я оставил там сундук, а в нем – кое-что важное. Принеси его мне! Возвращайся с добычей, и получишь Воровской сертификат.", progress = "Я забыл предупредить тебя насчет орков?\n\nГоворят, в последнее время они все время толкутся вокруг мельницы.", completion = "Сумел открыть, да? Неплохая работа, Вивн.\n\nТеперь если ты погибнешь, то исключительно по глупости, а не от отсутствия опыта.", rewards = "Вы получите:\n\nВоровской сертификат"},
[2283] = {title = "Пропавшее ожерелье", objective = "Найдите на раскопках Ульдамана драгоценное ожерелье (возможно, поврежденное) и принесите его в Оргриммар Драну Дрофферсу.", description = "У нас есть для тебя работа – если у тебя, конечно, хватит пороху за нее взяться!\n\nВ глубине Бесплодных земель есть раскопки Ульдамана. Говорят, недавно там откинул копыта какой-то идиот-паладин. При нем было очень ценное ожерелье с тремя самоцветами: рубином, сапфиром и топазом.\n\nКороче, нам нужно это ожерелье, и мы готовы за него заплатить – чистым серебром! Если оно попорченное – ничего, как-нибудь починим.", progress = "Ну что, оно у тебя, это ожерелье? Если его у тебя нет, не получишь ни гроша!", completion = "О-о, добыча! Отсюда чую, оно здесь... Дай-ка взглянуть…\n\nЭй, что это ты нам подсовываешь? Тут же камней не хватает. Ты что думал, мы не заметим? Даже Мальтон увидел бы, что камней нету!\n\nНу, может, это и не ты их спер... Но ведь ожерелье без них ничего не стоит! Не-ет, твоя работа еще не окончена!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2284] = {title = "Пропавшее ожерелье, этап 2", objective = "Разыщите ключ к местонахождению самоцветов в глубинах Ульдамана.", description = "Эти камни наверняка остались где-то в Ульдамане! Это так же верно, как то, что Мальтон – балбес. Вернись и разыщи их!\n\nКак я уже говорил, если то, что нам рассказывали, правда, в нем были рубин, сапфир и топаз. Найди их и вставь обратно в ожерелье.\n\nГде они? А кто ж их знает? Может, тебе повезет отыскать труп того паладина. Может, они до сих пор при нем – если его, конечно, не обчистили.", progress = nil, completion = "Похоже, вам-таки удалось отыскать останки паладина, о которых говорил Дран. Обыскав их, вы находите дневник паладина. Дневник в плохом состоянии, большая часть страниц перепачкана запекшейся кровью. Но и оставшийся текст – сплошная галиматья. Похоже, это язык людей.\n\nПридется вам найти кого-то, кто сможет это перевести.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2298] = {title = "Королевская облава", objective = "Отправляйтесь в Штормград и найдите Рензика Ножа.", description = "И вот собрались мы уже разрабатывать фазу III, когда вломились несколько болванов Магни, стали нести какую-то чушь насчет воровства и что они арестуют некоторых членов Тайного Круга.\n\nДа только поди возьми старика Черную Бороду! Разборка пошла нешуточная, и каким-то образом всплыло твое имя!\n\nХочешь совет? Бери первого грифона из Стальгорна и дуй в Штормград. Иди в Старый город и там переговори с моим старым приятелем Рензиком Ножом.", progress = nil, completion = "Всегда рад видеть в наших рядах ребят Хальфдана!", rewards = "Вы получите:\n\n"},
[2299] = {title = "К Хальфдану!", objective = "Отправляйтесь в Стальгорн и поговорите с Хальфданом Чернобородом.", description = "Где тебя носило, <имя>? Хальфдан всюду тебя искал. Мы уж подумали, что король забил тебя в кандалы.\n\nДуй в Стальгорн как можно быстрее и поговори с Хальфданом!", progress = nil, completion = "Говори тише, Рейнарт, стража может услышать.", rewards = "Вы получите:\n\n"},
[2300] = {title = "ШРУ", objective = "Отправляйтесь в Штормград и разыщите Рензика Ножа.", description = "Слушай, рыбка, тебя тут Рензик искал.\n\nНа твоем месте я не заставлял бы его ждать – все-таки он правая рука Матиаса...", progress = nil, completion = "Как насчет того, чтобы приступить к работе? Или хочешь сначала вздремнуть?", rewards = "Вы получите:\n\n"},
[2318] = {title = "Трудности перевода", objective = "Найдите кого-нибудь, кто сможет перевести для вас дневник паладина. Ближайший к вам такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных Землях.\n\nПрилагается предмет: \n", description = "Зайдя в окончательный тупик, ты приходишь к выводу, что тебе нужна книга, написанная на понятном тебе языке. Перевести ее, к сожалению, может далеко не каждый. Ближайший к тебе такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных Землях. Начать, пожалуй, стоит оттуда.", progress = nil, completion = "Могучий|3-6(Жрец), я знаю зачем Вы здесь, в Бесплодных землях. Я знаю, что Вам нужны мои умения по части языков. Вы – в поисках частей того ожерелья, которое вы нашли в Ульдамане.\n\nУдивлены? Не стоит – знать такие вещи – моя работа. Вместо этого давайте обсудим, что Вы сделаете для того, чтобы перевести дневник. Доверяйте мне – я – единственный, кто может перевести его.\n\nТак что позвольте мне сделать вам лучшее предложение, чем может Дран Дрофферз и можете без помех продолжать переговоры с ними. Заинтригованы?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2338] = {title = "Трудности перевода", objective = "Одолжите ожерелье Джаркалу. Взамен он переведет дневник.", description = "Скупщикам Дрофферсу и Сыновьям не хватит умения, чтобы восстановить чары на ожерелье, а вот я могу это сделать. Только дай мне изучить его, чтобы я научился делать подобные. Одолжи мне его на время, а я переведу для тебя дневник. Пока будешь искать камни, я как раз успею изучить ожерелье. \n\nЭто выгодно нам обоим. Ну, что скажешь?", progress = "Молодец, умненький |3-6(Жрец), чуешь свою выгоду! Так мы оба получим то, что нам нужно, а скупщики Дрофферс и Сыновья будут думать, что и они получили свое.", completion = "Благодарю тебя, секрет ожерелий разгадать несложно, если иметь достаточно времени, чтобы изучить всего одно из них. \n\nА теперь погоди еще минутку, я произнесу заклинание, чтобы быстро перевести дневник с человеческого языка на понятный тебе. Я тролль слова, спроси кого хочешь в Орде, и тебе скажут: Джаркалу Замшелому Клыку можно доверять! Ну-с, приступим...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2339] = {title = "Найти самоцветы и источник энергии", objective = "Добудьте все три самоцвета и источник энергии для ожерелья из Ульдамана и принесите их Джаркалу Замшелому Клыку в Каргат. Джаркал считает, что источник энергии можно найти у самой сильной твари в Ульдамане. \n\nИз дневника следует... \n* Рубин спрятан на огражденной завалами территории Кузни Теней. \n*Топаз спрятан в урне на территорях троггов под боком у дворфов Альянса.\n*Сапфир забрал Гримлок, старейшина троггов.", description = "Вот и перевод, ты можешь <сам/сама> прочесть его. Там говорится, что рубин спрятан дворфами, топаз спрятали трогги, а сапфир прикарманил трогг по имени Гримлок. \n\nПослушай-ка, тебе потребуется источник энергии, чтобы ожерелье вновь заработало. Дран Дрофферс об этом даже не подозревает. Чтобы найти такой источник, отправляйся в Ульдаман, спустись в самую глубину и убей самую сильную тварь, которую сможешь найти. \n\nУверен, у нее ты и найдешь источник энергии!", progress = "Путешествие в Ульдаман в твоих интересах – тебе нужны самоцветы и источник энергии, чтобы вернуть ожерелью волшебную силу. \n\nТы доставишь камни головорезам в Оргриммар, а я сохраню источник энергии, поскольку именно он заставит ожерелье снова работать...", completion = "Отлично, |3-6(Воин)! Скоро мы пожнем плоды наших трудов. Я закончил работу над ожерельем и уверен, что теперь смогу создать такое же. \n\nНо сначала я использую специальное заклинание, чтобы быстро исследовать эти самоцветы, прежде чем ты унесешь их и ожерелье в Оргриммар. Это займет всего пару минут.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2340] = {title = "Принести самоцветы", objective = "Доставьте ожерелье и драгоценности Драну Дрофферсу в Оргриммар.", description = "Ожерелье будет работать, только если самоцветы будут в сродстве с металлом оправы. Этот источник энергии поможет вернуть ожерелью магическую силу... Надеюсь. \n\nЯ с удовольствием предоставлю тебе камни, подходящие к ожерелью, если окажется, что источник энергии действительно работает. \n\nОтправляйся в Оргриммар и выполни, что <обещал/обещала> скупщикам Дрофферсу и Сыновьям. Никому не сообщай о наших договоренностях, и, возможно, к твоему возвращению я приготовлю сюрприз.", progress = "Смотри-ка, кто пришел, кто потратил свое драгоценное время, чтобы заглянуть к Драну Дрофферсу! Будем надеяться, твой визит не станет пустой тратой времени для меня. Пока не получу, что просил, платить не буду, имей это в виду. И можешь не сомневаться – перепроверю все, что ты принес дважды и трижды!", completion = "Ну, все в порядке. Я могу оставить себе и мешок? Спасибо, премного благодарен.\n\nИ все же лучший трофей – это ожерелье! Не строй такую кислую мину, оно было бы тебе не к лицу! \n\nСделка есть сделка, поэтому вот твоя награда за принесенные трофеи. Что ж, с этим покончено, можешь заглядывать иногда, если понадобится работа. А пока будь любезен, покинь помещение!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2341] = {title = "Пропавшее ожерелье, этап 3", objective = "Навестите Джаркала Замшелого Клыка в Каргате.", description = "Полдела сделано. Дран и Мальтон Дрофферсы уже ссорятся из-за новой добычи. Теперь нужно сходить в Бесплодные земли – возможно, у Джаркала Замшелого Клыка из Каргата найдется для вас особая награда...", progress = nil, completion = "Источник силы, полученный от тебя, превзошел все мои ожидания! Мне удалось сделать два ожерелья – тебе и мне, – и в нем осталось достаточно энергии, чтобы сделать как минимум еще три! Я на этом неплохо наживусь, а семейка Дрофферсов ничего и не узнает!\n\nВот, держи. Я тебе очень благодарен... а это знак моей благодарности!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nОжерелье Усиления Джаркала"},
[2342] = {title = "Возвращенные сокровища", objective = "Принесите Патрику Гарретту в Подгород фамильное сокровище из сундука в Южном зале Ульдамана.", description = "Гарреттам не пристало мести загоны для летучих мышей такой метлой! Мерзкая работенка позволила мне заработать немного денег, и я хочу истратить их на улучшение своего положения.\n\nФамильное \"оружие\" Гарреттов заперто в нашем сундуке в Южном зале Ульдамана. Там наша семья трудилась долгие годы. Без него я застряну тут навеки – в буквальном смысле – и буду мести за проклятыми летучими мышами до скончания веков.\n\nПринеси мне наше сокровище! Помоги вернуть то, что положено мне по праву рождения!", progress = "Уборке нет конца... летучие мыши смеются надо мной и моей метлой. Скажи, ты ведь принесешь мне фамильное сокровище? Я готов отдать тебе все мое серебро – неужели этого недостаточно?!", completion = "Наконец-то – метла, достойная Гарретта. Не зря я потратил на тебя деньги!\n\nВы слышите меня, летучие мыши? Теперь у меня есть истинное оружие семьи Гарреттов! Трепещите, проклятые пискуны!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2358] = {title = "Рога Нез'ры", objective = "Верните рога Незры тени Арантира в Приозерье.", description = "Много лет назад рога Незры были похищены из поместья Черный Ворон. Я искал их по всем морям и континентам и только теперь выяснил, что они все время находились у этих ничтожных тварей.\n\nУбей всех орков Черной Горы, которые встретятся тебе на пути, забери у них рога Незры и возвращайся ко мне в Приозерье.\n\nОкажи мне эту услугу, и заслужишь благодарность всех Черных Воронов.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nАртишоковый чай"},
[2359] = {title = "Башня Клейвена", objective = "Добудьте ключ Башни Братства Справедливости, проберитесь в башню и выясните, каково содержимое сундука из Сумеречного леса. Отнесите найденные вещи Матиасу Шоу в Штормград. Почитайте дневник Кеарнен, чтобы больше узнать о башне.", description = "Я за этой башней уже не первую неделю наблюдаю, <имя>. Недавно прошла крупная поставка из Сумеречного леса, а вместе с ней явились эти стражи.\n\nКто такие? Мы можем только гадать. Одно я тебе скажу: это не люди.\n\nКак бы то ни было, там был сундук – и, как я полагаю, эта мерзость именно его и охраняет. А ключ от сундука – у того зомби с шипами.\n\nДобудь этот ключ, проберись в башню и выясни, что находится в том сундуке. Находку отнесешь Матиасу.", progress = "Есть какие-то новости от посланницы Кеарнен?", completion = "Это объясняет присутствие мертвяков из Братства Справедливости, которых вы с Кеарнен видели рядом с башней. Это может объяснить и вовлеченность Торговой Компании в дела Братства Справедливости и эти странные поставки из Сумеречного леса.\n\nКак явствует из этой книги, тролли Занзила в Тернистой долине нашли возможность поднимать мертвых с помощью зелий... выражаясь точнее – ядов.\n\nВы бесполезны для ШРУ, если у вас нет четкого представления о ядах, Скирди, особенно когда рецепт того, как поднимать нежить, почти у нас в руках.", rewards = "Следующее заклинание будет наложено на вас:\n\nЯды\n\nВы получите:\n\nРецепт: артишоковый чай"},
[2360] = {title = "Матиас и Братство Справедливости", objective = "Найдите посланницу Кеарнен в Западном Крае и поговорите с ней.", description = "Произошло то, чего я ожидал, <имя>. Разведотдел ШРУ сообщает, что Братство Справедливости что-то затевает в Западном Крае.\n\nСкладывается впечатление, что братство захватило покинутую сторожевую башню Альянса к юго-востоку от Сторожевого Холма и использует ее как базу для ввоза контрабанды из Красногорья.\n\nОтправляйтесь в Западный Край и свяжитесь с посланницей Кеарнен для подробного доклада. Она там прячется, неподалеку от башни.\n\n... и кстати, <имя>, если вас раскроют – вы никогда не слышали о ШРУ...", progress = nil, completion = "Наконец-то Матиас прислал еще одного агента мне в помощь. Ну, надеюсь, он готов к вороху неприятных новостей.", rewards = "Вы получите:\n\n"},
[2361] = {title = "Восстановление ожерелья", objective = "Я с великой радостью вручаю тебе это ожерелье, могучий |3-6(Жрец). Ты оказал мне неоценимую услугу, и я благодарен тебе за это. Носи же его с гордостью и не забывай при этом все время упоминать о том, кто сделал его для тебя!\n\nДа, если еще добавишь, что на ожерелье нет проклятия, это будет великолепно.", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nОжерелье Усиления Талваш"},
[2378] = {title = "Поиски Изувеченной Длани", objective = "Отправляйтесь в Оргриммар и поговорите с Шентулом в Расселине Теней.", description = "Ты много <сделал/сделала> для стражей смерти, но пришло время двигаться дальше. У тебя талант к искусству обмана и скрытности, но этот талант еще следует развить.\n\nУ стражей смерти есть союзники в Изувеченной Длани. Поищи среди них тех, кто готов помочь нам. Для начала поговори с Шентулом в Оргриммаре.", progress = nil, completion = "Так вот кого могучие союзники прислали Шентулу... Не впечатляет…", rewards = "Вы получите:\n\n"},
[2379] = {title = "Зандо'зан", objective = "Поговорите с Зандо'заном в расселине Теней.", description = "Одной твоей решимости еще недостаточно, чтобы преодолеть препятствия, которые ждут впереди.\n\nПоговори с Зандо'заном, чтобы начать учиться на агента Изувеченной Длани.\n\nЛишь овладев навыками незаметности и коварства, ты сможешь сделать следующий шаг.", progress = nil, completion = "Быть может, Зандо'зан ошибся. Зандо'зан просит прощения.", rewards = nil},
[2380] = {title = "В Оргриммар!", objective = "Поговорите с Шентулом в расселине Теней в Оргриммаре.", description = "Ты, конечно, далеко еще не специалист по скрытности и всяким уловкам, однако же тебе есть куда расти. По крайней мере, начальство явно обратило на тебя внимание: сам великий Шентул запомнил твое имя!\n\nСтупай на север – эта дорога ведет в Оргриммар. Отыщи там в расселине Теней Шентула и поговори с ним.", progress = nil, completion = "Очень важно, чтобы Изувеченная Длань сохраняла бдительность перед лицом перемен, которые Тралл намеревается ввести в Орде. Числом тут не возьмешь – для нас главное незаметность и разнообразные уловки!", rewards = "Вы получите:\n\n"},
[2381] = {title = "Грабь награбленное", objective = "Принесите Рениксу Презренному из Кабестана сокровище Южного моря. Не забудьте взять из гизмотронного аппарата Реникса ХОЧУ и отмычки. Они понадобятся для выполнения задания.\n\nЕсли на вас нападут необычайно враждебные попугаи, воспользуйтесь ХОЧУ!", description = "Не хочу тебя пугать, <имя>, но последние пять воров, которым я поручил похитить сокровище Южного моря, не вернулись. Потом их нашли... Частично.\n\nВ южной части побережья пришвартован пиратский корабль, \"Стрела прилива\". В трюме у него хранится то самое сокровище. На второй палубе устроен пиратский притон, в котором они натаскивают своих воров.\n\nПроникни на этот корабль, похить сокровище и принеси его мне. Если тебе надо поднатореть в воровском искусстве, можешь заглянуть в притон, но соблюдай осторожность!", progress = "Что ж, по крайней мере, ты пока цел. А сокровище нашел?", completion = "Немыслимо! Невероятно! Поразительно! Да ты талант, Соулнце. Или же ты самый везучий парень на свете!\n\nВот твоя доля. Думаю, ты найдешь ей лучшее применение, чем я.", rewards = "Вы получите:\n\nАртишоковый чай"},
[2382] = {title = "Реникс из Кабестана", objective = "Поговорите с Рениксом Презренным в Кабестане.", description = "Зандо'зан это видел! Да, день близок! Смерть Тралла... кинжал в его спине, яд в его кубке... Но Зандо'зан слишком много болтает.\n\n<имя>! У Зандо'зана есть поручение для тебя! <имя> <должен/должна> отправиться в Кабестан, к востоку от Перекрестка, и поговорить с Рениксом Презренным. Ступай!", progress = nil, completion = "Как, опять? Предыдущие пятеро, кого прислал ко мне этот чокнутый тролль, пошли на корм акулам. Ну что ж, будем надеяться, что тебе повезет…", rewards = "Вы получите:\n\n"},
[2383] = {title = "Записка на пергаменте", objective = "Прочтите пергамент и поговорите с Франгом в долине Испытаний.", description = "А, <имя>! Меня тут попросили передать тебе этот пергамент.b\nПрочитай его, когда время будет. Это, кажется, от Франга, наставника воинов. Думаю, тебе стоит с ним поговорить. Он обычно сидит в тени у входа в Логово.", progress = "Что у тебя там? Пергамент? Ты что, грамотный?", completion = "А-а, да, это я тебе написал... Я слышал, что ты скоро тут появишься, Гронгард. Рад, что тебе удалось добраться сюда невредимым – будем надеяться, что ты переживешь и грядущие испытания. Наберешься сил – приходи ко мне. Я сделаю все, чтобы из тебя получился настоящий воин.\n\nУдачи, Гронгард! Возвращайся, когда будешь готов.", rewards = "Вы получите:\n\n"},
[2398] = {title = "Потерянные дворфы", objective = "Найдите Бейлога в Ульдамане.", description = "Раскопки в Ульдамане не всегда были захвачены троггами. Изначально мы, дворфы Стальгорна, вели здесь работы, но потом... Потом появились эти твари. Они прибыли столь быстро и в таком количестве, что дворфы не смогли ничего поделать.\n\nЧестно говоря,  их нападение было настолько внезапным, что многие наши люди могли не успеть вырваться из осады. Боюсь, они по сей день остаются в ловушке в тылу врага.\n\nМой друг Бейлог руководил небольшим отрядом дворфов в глубине раскопа прямо перед нападением троггов. Если он и его ребята живы, то я хочу, чтобы ты <нашел/нашла> их.", progress = nil, completion = "Ты как раз вовремя! Я уже боялся, что проспорю Олафу!\n\nОн бился об заклад, что его борода достанет до колен, прежде чем мы увидим живое лицо, |3-6(гном).\n\nИ вот, ты здесь, а бороде Олафа еще до колен осталась пара дюймов.\n\nСпасибо, Эфром! Я обязательно поделюсь с тобой выигрышем.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2399] = {title = "Росток папоротника", objective = "Папоротник, который Деналан посадил у себя в саду, проклюнулся и вырос. Ростки так и просят, чтобы их скорее собрали...", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nРосток папоротника"},
[2418] = {title = "Камни Силы", objective = "Принесите 8 дентриевых камней Силы и 8 энелиевых камней Силы Ригглфаззу в Бесплодные земли.", description = "Есть у меня зуб на этих дворфов Кузни Теней! Пару лет назад они пригласили меня в Крепость Ангор, чтобы я исследовал для них два образца прелюбопытнейших камней, привезенных с ульдаманского раскопа. Я провел исследования, и вообрази, что это было? Энергия! Каждый камень был мощнейшим источником энергии в сжатом, потенцированном виде – нужно только знать, как правильно высвободить ее! Чего только не найдешь в Ульдамане... \n\nВ общем, как только я рассказал об этом дворфам, они вышвырнули меня из крепости и направились в Ульдаман за чудесными камнями. \n\nМне бы такие, знаешь ли, тоже пригодились. Принеси мне несколько обоих видов, и я щедро вознагражу тебя.", progress = "Ну, что там с камнями? Мне нужен источник питания для моей механической мышки...", completion = "Прекрасно, ты принес их! Ты самый благонадежный |3-6(дворф), которого мне приходилось встречать! \n\nНемедленно опробую эти камни на моих последних механизмах! Нутром чую, с этими камнями можно создать вечный двигатель!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗаряженный круглый каменьДюрациновые наручиДолговечные сапоги\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[2438] = {title = "Изумрудный ловец снов", objective = "Принесите изумрудного ловца снов Таллонкаю Гибкому Корню в Доланаар.", description = "Некогда Гэролас Талветрен, страж друидов обители Бен'этиль, подарил мне изумрудного ловца снов. Этот могучий амулет способен выкачивать энергию из Изумрудного Сна, принося удачу тому, кто его носит.\n\nУвы, мне не удалось забрать его из моего шкафчика в деревне Звездного Ветра... Хотя эта деревня некогда была спокойным местом, ныне она поражена порчей фурболгов, что поселились там.\n\nМожет, тебе удастся добыть моего ловца снов, <класс>?", progress = "Прошу, быстрее. Могу лишь надеяться, что фурболги не повредили моего ловца снов.\n\nТы еще не добыл его, Айлерон?", completion = "Мой изумрудный ловец снов очень много для меня значит. Такие подарки лишь немногим дарят. Прими мою благодарность за его возвращение, Айлерон.", rewards = "Вы получите:\n\n"},
[2439] = {title = "Платиновые диски", objective = "Отнесите наградной сертификат Дините Каменной Мантии в хранилище Стальгорна.", description = "Это невероятная находка. Согласно этим дискам, Древние Титаны, или Создатели, имеют отношение к нашему чудесному возникновению! Нам нужно уделить как можно больше времени их изучению.\n\nА вас, <героический/героическая:c> <класс>, прошу принять этот сертификат и отнести его Дините Каменной Мантии в хранилище. По нему вы получите то, что, на мой взгляд, будет достойной наградой за такую находку!\n\nКогда будете готовы, возвращайтесь ко мне – у Лиги Исследователей еще много работы для вас!", progress = "Добро пожаловать в хранилище Стальгорна, Эфром. Чем могу помочь?", completion = "Ах, сертификат Лиги Исследователей... и весьма ценный, смею заметить.\n\nЛига Исследователей дает мне полномочия предложить вам выбрать себе награду прямо из хранилища. Награда ваша, так что выбирайте – либо пять наилучших целебных зелий, либо пять сильных зелий маны.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМощное лечебное зельеСильное зелье маны\n\nВы также получите:\n\nСума из мягкой кожи"},
[2440] = {title = "Платиновые диски", objective = "Отнесите наградной сертификат Бене Заиндевевшее Копыто в Громовой Утес.", description = "Я сосредоточу свои усилия на исследовании этих дисков, и со временем они раскроют мне свою тайну.\n\nА тебя <имя>, я награжу за то, что ты <обратил/обратила> на них мое внимание. Отнеси этот сертификат Бене Заиндевевшее Копыто, наставнице алхимиков в Громовом Утесе. Она даст тебе один интересный предмет, который наверняка тебе понравится, а еще она даст тебе на выбор зелий из моих личных запасов.\n\nВозвращайся поскорее, ибо я чувствую, что мы стоим на пороге великого открытия.", progress = "Привет тебе, |3-6(Маг)! Ты пришел сюда учиться алхимии или за чем-то еще?", completion = "Что же, Тарчёк, ты, видать, угодил Ведуну Искателю Истины, принеся ему ту штуку. Так что вдобавок ты получишь в награду зелья из его личного хранилища. Можешь выбрать или 5 наилучших целебных зелий, либо 5 сильных зелий маны.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМощное лечебное зельеСильное зелье маны\n\nВы также получите:\n\nСума из мягкой кожи"},
[2458] = {title = "Надежное прикрытие", objective = "Отыщите башню Торговой компании к северу от Нефтяного болота и вступите в контакт с тайным агентом Изувеченной Длани, надсмотрщиком Физзулом.\n\nВозле башни выстрелите из сигнального ружья ДВА раза, потом подойдите к надсмотрщику Физзулу и продемонстрируйте приветствие Изувеченной Длани (команда /честь).\n\nВсе нужно делать строго по порядку – Физзул убивает всех, кто кажется ему подозрительным.\n\nПрилагается предмет: \n", description = "Торговая Компания... Доводилось тебе слышать про такую?\n\nМы в течение года пытались внедрить агента в их ряды. Это было непросто, но мы преуспели.\n\nНедавно мы получили сведения, что Торговая Компания затевает что-то крупное. Ступай к башне Торговой Компании, которая стоит к северу от Нефтяного болота, и свяжись с нашим тайным агентом, надсмотрщиком Физзулом.\n\nКогда найдешь башню, используй это сигнальное ружье, потом подойди к Физзулу и покажи ему приветствие Изувеченной Длани.", progress = nil, completion = "Приятно видеть в здешних местах еще одного агента Изувеченной Длани! Вот только боюсь, как бы твоих вспышек не заметил кто-то лишний.\n\nВ следующий раз, как тебе нужно будет со мной поговорить, дважды свистни в этот свисток, и я пойму, что это свои.", rewards = "Вы получите:\n\nСвисток Физзла"},
[2459] = {title = "Фероситас Пожиратель Снов", objective = "Таллонкай Гибкий Корень из Доланаара хочет, чтобы вы убили 7 мистиков из племени Кривой Сосны и нашли пропавший самоцвет.", description = "Изумруд... Он пропал! Мой ловец снов поврежден!\n\nК северу от деревни Звездный Ветер засела шайка мистиков из племени Кривой Сосны. Я слышал, что их вожак, Фероситас Пожиратель Снов, носил ожерелье, которое светится зеленым в ночи. Теперь, глядя на своего ловца снов, я уверен, что это он украл мой изумруд... Он не понимает, что его сила для него бесполезна.\n\nНайди этот пропавший драгоценный камень, <имя>. И раз уж ты здесь, истреби заодно и этих зловредных мистиков.", progress = "Пусть Фероситас и эти мистики Кривой Сосны вернут то, что принадлежит мне! Прошу тебя, отними у них изумруд, чтобы я мог восстановить своего ловца снов.", completion = "Теперь я восстановлю своего ловца снов! Спасибо тебе, Хлебало.", rewards = "Вы получите:\n\n"},
[2460] = {title = "Приветствие Изувеченной Длани", objective = "Повторите приветствие Раздробленной Руки вслед за Шентулом.", description = "Теперь, когда ты – разбойник Изувеченной Длани, тебе следует обучиться особому приветствию. Это знак, по которому мы опознаем своих.\n\nСмотри и повторяй за мной.", progress = "Повтори!", completion = "Молодец, Соулнце! Теперь мы можем продолжать.", rewards = "Вы получите:\n\n"},
[2478] = {title = "Миссия: выполнима, но с трудом", objective = "Украдите ключ от башни у штейгера Силиксиза, убейте двух мертвяков-мутантов Торговой компании, двух патрульных Торговой компании и двух смотрителей Торговой компании.\n\nЛиквидируйте старшего мастера Галливикса, взломайте замок на его ящике и украдите запас измененной смеси Занзила. Отнесите запас смеси и голову Галливикса Шентулу в Оргриммар и получите следующие указания.", description = "Тебе придется украсть ключ от башни у штейгера Силиксиза. Смотри не потеряй его: он мне еще пригодится.\n\nНе забудь: яд ослабил всех в этой башне. Покажи, на что ты <способен/способна>, неси хаос и разрушение в стены башни. Убей всех – жалости тут нет места!\n\nКогда внутри останутся лишь кровавые ошметки, возьми денежный ящик Галливикса и укради из него запас смеси Занзила. Отнеси голову Галливикса и смесь Шентулу в Оргриммар.", progress = "Докладывай, Соулнце.", completion = "Бедный Физзул, он был прекрасным агентом, одним из лучших. Увы, мы заплатили за победу высокую цену, Соулнце. Да, работа агента Изувеченной Длани опасна.\n\nНо ты отлично справился с заданием, |3-6(Разбойник). Хорошо, что тебе удалось выжить. Ты ведь можешь и дальше служить нам.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nРецепт: артишоковый чай"},
[2479] = {title = "Помощь Хинотта", objective = "Пойдите на Мельницу Таррен в предгорьях Хилсбрада и доставьте образчик смеси Занзила Сержу Хинотту.\n\nСядьте на дирижабль, идущий до Подгорода, и летите вдоль дороги на юг, через Серебряный бор в сторону Хилсбрада. Следите за знаками.", description = "Отнеси образчик этой смеси Сержу Хинотту на Мельницу Таррен.\n\nЕсли кто сможет тебя исцелить, так это Серж. Он тебя обучит всему, что связано с ядами, – если, конечно, выживешь.", progress = "Это что такое???", completion = "О, |3-6(Разбойник), какой ты бледненький! А чем это от тебя так мерзко благоухает? Я должен выяснить!", rewards = "Вы получите:\n\n"},
[2480] = {title = "Помощь Хинотта", objective = "Дождитесь, пока Серж Хинотт доделает лекарство.", description = "Никогда не видел таких отличных результатов действия яда! Занзил, говоришь? Не слыхал о таком... Однако пора уже приступать к созданию состава.\n\nИтак, я должен вылечить тебя и научить пользоваться этим ядом?\n\nДай мне пару минут на изучение токсина, <имя>.", progress = nil, completion = "Лекарство готово! Выпей это противоядие, и наступление безумия остановится. Впрочем, с запахом ничего не поделаешь.", rewards = "Следующее заклинание будет наложено на вас:\n\nЯды\n\nВы получите:\n\nМасло Хинотта"},
[2498] = {title = "Возвращение к Деналану", objective = "Релиан Зеленый Костер хочет, чтобы вы поговорили с Деналаном у озера Аль'Амет.", description = "Я только что получил известие, что Деналан с озера Аль'Амет узнал, что могло послужить причиной возникновения опухоли, поражающей древесников. Пожалуйста, поговори с ним и скажи, что тебя прислал я.\n\nТоропись, <имя>, ему нужна наша помощь.", progress = nil, completion = "Ах, так, значит, Релиан послал тебя мне в помощь. Хорошо, что ты так скоро пришел.\n\nЯ обнаружил нечто чрезвычайно тревожное!", rewards = "Вы получите:\n\n"},
[2499] = {title = "Дубохмур", objective = "Деналан с озера Аль'Амет хочет, чтобы вы сняли гигантскую опухоль с Дубохмура.", description = "В пещере на южном берегу озера засел древесник по имени Дубохмур и заражает порчей всех существ, для которых окрестности озера Аль'Амет – дом родной.\n\nЯ не осмелился подходить к нему близко, но даже издалека хорошо видно: Дубохмур поражен опухолью, какой я в жизни не видывал... Она просто гигантская!\n\n<имя>, ты и так уже достаточно <помог/помогла> мне в моих трудах, но я попрошу тебя еще об одной услуге. Найди Дубохмура и сними эту опухоль. Избавь мою землю от источника порчи!", progress = "Тебе удалось найти Дубохмура, |3-6(человек)?", completion = "Я так и знал, что ты сумеешь избавить озеро от этой чудовищной твари.\n\nПечальная история – Дубохмур некогда был великим вождем своих сородичей... но порча поражает всех подряд – и подлых, и благородных.\n\nВеличина этой опухоли в дрожь бросает, но я обязан исследовать ее, чтобы понять, какая зараза терзает древесников.\n\nПрими мою благодарность, Айлерон.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПояс Грязного ДреваЗамшелые рукавицы\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[2500] = {title = "За реактивами в Бесплодные земли", objective = "Добудьте в Бесплодных землях реактивы для Гхака Целителя и отнесите их ему в Телcамар.", description = "<класс>, я хотел бы воспользоваться твоими услугами. Я довольно известный алхимик, и мне понадобились кое-какие реактивы, которые можно отыскать в Бесплодных землях.\n\nВот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей. Очевидно, что их можно добыть у самих тварей, но если ты не <любитель/любительница> сражений, можешь попросить о помощи друзей.\n\nЯ неплохо заплачу, если ты принесешь мне все необходимое.\n\nЧто скажешь?", progress = "Ты принес все необходимое? Пока не принесешь, платить не буду.", completion = "Молодец, Бронетазик. Этого мне должно хватить на некоторое время. Вот обещанная плата.\n\nЕсли ты не против получить новое задание, мне нужны еще кое-какие реактивы. Некоторые из них можно найти только на ульдаманском раскопе. Добыть их нелегко, но и плата за помощь будет немалая.\n\nМожет быть, кое-что получше блестящих монет!", rewards = "Вы получите:\n\n"},
[2501] = {title = "За реактивами в Бесплодные земли II", objective = "Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Гхаку Целителю в Телcамар.", description = "Ты не раз меня <выручал/выручала>, <имя>. Я хотел бы дать тебе в награду рецепт зелья, которое ты уже <пробовал/пробовала>, но взамен попрошу выполнить опасное поручение.\n\nВ этом сундучке находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опаленного дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне.\n\nДобудь мне кровь дракона, и я отдам тебе рецепт.", progress = "Ты уже наполнил сосуды кровью опаленных драконов-стражей? Знаю, задание опасное... но в случае успеха тебя ждет рецепт восстановительного эликсира. Игра стоит свеч, мой друг... игра стоит свеч...", completion = "Между нами, алхимиками, говоря, ты просто герой! Вот, возьми этот рецепт. Пусть он принесет тебе успех и богатство, как и мне!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриводящее в сознание зелье\n\nВы получите:\n\n"},
[2518] = {title = "Слезы Луны", objective = "Жрица А'моора из дарнасского храма Луны хочет, чтобы вы принесли ей серебряные паутинные железы леди Сатры.", description = "Некогда леди Сатра была дорога Элуне. Эта изящная и чистая душой паучиха ткала серебряные свои нити под светом луны, ловя в свои сети вечерний туман. Его серебристые капли обладали великой целительной силой, их хранили в этом храме.\n\nНо недавно Сатру постигло безумие. Теперь и ее потомство под угрозой.\n\nНайди леди Сатру, <имя>, и положи конец ее страданиям. Она обитает у северных границ Тельдрассила, близ Родникового озера. Возьми ее серебристые паутинные железы и принеси их мне.", progress = "В великой печали даю я тебе это поручение, но у нас нет надежды исцелить леди Сатру.\n\nМы надеемся, что если принести серебряные паутинные железы в жертву Элуне, то она благословит Сатру, и та возродится с покоем в душе.", completion = "Лес оплакивает леди Сатру, но это надо было сделать.\n\nБлагодарю тебя, Айлерон.", rewards = "Вы получите:\n\n"},
[2519] = {title = "Храм Луны", objective = "Сестра Аквинна хочет, чтобы вы поговорили со жрицей А'моорой из Храма Луны.", description = "Одному некогда великому существу из нашего леса нужна помощь, <раса>. \n\nЭто трудное дело, но его надо сделать.\n\nПожалуйста, разыщи нашу жрицу А'моору, она все тебе объяснит. Ищи ее к юго-востоку отсюда, в Храме Луны.", progress = nil, completion = "Стало быть, тебя прислала сестра Аквинна?", rewards = "Вы получите:\n\n"},
[2520] = {title = "Жертвоприношение Сатры", objective = "Жрица А'моора просит вас положить серебряные паутинные железы леди Сатры у фонтана в храме и затем вернуться к ней.", description = "Теперь ты <должен/должна> закончить дело, порученное тебе. Возьми эти паутинные железы и принеси их в жертву во имя Элуны. Пусть великая паучиха обретет покой.\n\nВнутри этого храма ты найдешь центральный фонтан. Там ты оставишь жертвоприношение. Святые воды смоют порчу, что повергла Сатру в безумие.\n\nКогда закончишь дело, возвращайся ко мне.", progress = nil, completion = "Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновленным духом.\n\nДа примет Элуна ту жертву, что ты принес ей.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКружевные штаныСмягченные сапоги\n\nВы также получите:\n\n"},
[2521] = {title = "Служба для Кум'иша", objective = "Если в своем путешествии по Выжженным землям вы найдете безупречную сферу из дренейского аметиста, отнесите ее Кум'ише Коллекционеру. \n\nБудьте внимательны – этот камень – один из самых редких кристаллов во всем Азероте. Любое существо в этих землях может владеть безупречной сферой из дренейского аметиста. \n\nВы будете вознаграждены за каждую безупречную сферу из дренейского аметиста, которую доставите Кум-ише.", description = "<раса>, может ли твой ничтожный мозг понять уникальность безупречной сферы из дренейского аметиста? Некоторые дренеи тратили всю свою жизнь на поиски одного-единственного кристалла – и все лишь для того, чтобы встретиться с ужасной судьбой, не достигнув своей цели.\n\nИ вот ты стоишь перед Кум-ишей, знаешь, что требуется Кум-ише. Ты все еще желаешь помочь? Отлично, <раса>... В любой момент своего путешествия через эти земли, если ты найдешь безупречную сферу из дренейского аметиста, верни ее мне и я вознагражу тебя так, как тебе не грезилось в самых безумных мечтаниях.", progress = "Я посвятил свою жизнь поискам безупречной сферы из дренейского аметиста. Всю жизнь, |3-6(дворф)!", completion = "Не обманывают ли меня глаза? Невозможно! Откуда... Каким образом...\n\nБыть может, теперь откроется разлом и мы сможем вернуться на родину.", rewards = "Вы получите:\n\nСундук, украшенный изумрудами"},
[2522] = {title = "Попытки Кум'иша", objective = "Найдите безупречную сферу из дренейского аметиста и верните ее Кум'ише Коллекционеру.", description = "Хотя заклинание портала ни к чему не привело, я по-прежнему надеюсь, что моя следующая попытка будет успешной.\n\nНадежда дренеев столь же сильна, как твоя жадность до безделушек, <раса>. Возвращайся в те проклятые земли и найди еще одну безупречную сферу из дренетиста.\n\nНу конечно же, брать или не брать на себя эту задачу – выбираешь только ты *усмешка*.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСундук, украшенный изумрудами"},
[2523] = {title = "Оскверненный песнецвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[2541] = {title = "Спящий друид", objective = "Принесите шаманский оберег вуду Обену Яростному Когтю в обитель Бен'этиль.", description = "Шаман племени Кривой Сосны, который живет в этих местах, нашел способ разлучать дух спящего друида с физическим телом. Этот фурболг оживил мое тело и заставил его нападать на любого, кто пытается обследовать обитель Бен'этиль. Теперь мне не выйти из Изумрудного Сна, и я не могу прекратить это!\n\nПомоги мне! У шамана Кривой Сосны есть при себе странный оберег, который он использует во время ритуала, и я хотел бы исследовать его. Прошу тебя, <имя>, принеси его мне!", progress = "Если бы я смог осмотреть этот оберег, я смог бы понять суть чар. Удалось тебе его найти?", completion = "Прими мою благодарность, Айлерон.\n\nКакая странная вещица... Я чувствую злую ауру, которую она излучает. Очень мощное заклятие...", rewards = "Вы получите:\n\n"},
[2561] = {title = "Друид-медведь", objective = "Обен Яростный Коготь просит, чтобы вы уничтожили его лишенное души тело, а затем воспользовались оберегом вуду.", description = "Изучив этот оберег, <имя>, я понял, что надо сделать. Пожалуйста, возьми его и сделай, как я прошу.\n\nТебе придется собраться с духом и проникнуть в самые глухие закоулки обители Бен'этиль. Там ты найдешь мое лишенное души тело... Хотя я и скорблю о том, что мне сейчас придется поведать тебе, я не вижу другого способа освободиться от власти племени Кривой Сосны.\n\nЧтобы я мог сбежать от них, ты должен уничтожить мое физическое тело. Как только это будет сделано, обрати на мой труп силу амулета вуду. После этого возвращайся ко мне.", progress = "Мишкин, будь осторожен с моим телом: на него наложены могучие чары.", completion = "Наконец-то я свободен от власти племени Кривой Сосны! Спасибо тебе, Эльстан.\n\nОтныне мой дух обретет вечный покой в объятиях Изумрудного Сна.\n\nВозможно, однажды мы снова встретимся, юный |3-6(Разбойник). Но пока прими эту награду в знак моей благодарности.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНочная рубашкаКустарниковый клинок\n\nВы также получите:\n\n"},
[2581] = {title = "Челюсти гиены-хохотуна", objective = "Принесите три челюсти гиены, два обожженных легких вепря и одну клешню скорпока магу Крови Дразиалу.", description = "Хорошо известно, что челюсти гиены невероятно сильны, но чтобы они были способны прокусить три дюйма ториевой стали? Невозможно, невероятно, и тем не менее я видел это своими глазами.\n\nОтправляйся в Выжженные земли и принеси мне три челюсти гиены-ухмыльника. А пока ищешь гиен, высматривай также кабанов и скорпоков: для дополнения к изначальной эссенции требуется также два обожженных легких вепря и одна клешня скорпока.", progress = "Отвратительно пахнешь, Эфром. Что серные поля – такое милое место для прогулки? И где мои компоненты?", completion = "Как самочувствие, Эфром? Ты излучаешь ауру гиены-ухмыльника – силу, с которой никто из смертных не сравнится!\n\nК несчастью, из принесенных тобой компонентов я смогу сделать эссенции только на одну таблетку. Если тебе понадобится еще одна таблетка, мне нужно будет больше компонентов.", rewards = "Следующее заклинание будет наложено на вас:\n\nЯрость веков\n\nВы получите:\n\nС.И.Л.А."},
[2582] = {title = "Вековая ярость", objective = "Принесите три челюсти гиены, два обожженных легких вепря и одну клешню скорпока магу Крови Дразиалу.", description = "О, <имя>, добро пожаловать, давно не виделись. Похоже, тебе понравился эффект крепкого, действенного зелья, извлеченного из гиены-ухмыльника. Однако осторожнее: если непосредственным эффектом является титанический прилив сил, то долгосрочный эффект, сказывающийся на твоем духе и рассудке, может быть опасным. \n\nКстати говоря, тебе нужно еще зелья? Тогда принеси мне еще три челюсти гиены, два обожженных легких вепря и одну клешню скорпока.", progress = "Тебе удалось добыть органы этих тварей?", completion = "Вот, возьми! И помни, что использовать это зелье надо расчетливо. Если понадобится еще, приходи ко мне после того, как израсходуешь порцию, которую я тебе только что выдал.", rewards = "Вы получите:\n\nС.И.Л.А."},
[2583] = {title = "Жизненная сила вепря", objective = "Принесите три обожженных легких вепря, две клешни скорпока и один мозг василиска волшебнице крови Дразиале.", description = "В этих опаленных землях водятся два вида кабанов: углегривый кабан и зловепрь.\n\nСудя по всему, стойкость этих тварей такова, что делает их почти неуязвимыми, поскольку другие животные считают, что вепрей слишком трудно убить, следовательно, на них не стоит даже тратить усилий.\n\nНам нужно провести дальнейшие исследования, <имя>. Если ты принесешь мне три обожженных легких вепря, две клешни скорпока и один мозг василиска, я создам отличный эликсир на основе вытяжки из этого материала. И первым делом проверю на тебе!", progress = "Так где органы, Эфром!?", completion = "Дух вепря озаряет твое существование, Эфром! Может быть, ты веришь, что тебе дарована неуязвимость, как и этим тварям?", rewards = "Следующее заклинание будет наложено на вас:\n\nДух вепря\n\nВы получите:\n\nКоктейль \"Легкое дыхание\""},
[2584] = {title = "Дух вепря", objective = "Принесите три обожженных легких вепря, две клешни скорпока и один мозг василиска магу Крови Дразиалу.", description = "Когда я впервые выдал тебе этот эликсир, <имя>, я уже понимал, что одна-две порции не удовлетворят твой аппетит. Даже сейчас я вижу в твоих глазах этот голод. Сей состав имеет одно побочное свойство – он дает привыкание, которому, похоже, не может сопротивляться даже самая сильная воля.\n\nЧто ж, пусть так! Если тебе требуется еще порция смеси с легочной вытяжкой, отправляйся обратно в пустоши и принеси мне три обожженных легких вепря, две клешни скорпока и один мозг василиска.", progress = "Так где органы, Мард!?", completion = "Хочу предупредить тебя, Мард, не пытайся смешивать созданные мною составы. Химические свойства состава, недавно принятого тобою, всегда возобладают над предшествующими заклинаниями; таким образом, эффект другого зелья будет сведен на нет.", rewards = "Вы получите:\n\nКоктейль \"Легкое дыхание\""},
[2585] = {title = "Решительный удар", objective = "Принесите три клешни скорпока, две единицы потрохов стервятника и одно обожженное легкое вепря волшебнице крови Дразиале.", description = "Тебе приходилось видеть их сражение, <имя>? Я имею в виду скорпоков. Видеть грациозность и ловкость, с которой они движутся? Решительность, с которой они наносят удары?\n\nЕсли бы мы только могли выделить эту ловкость и заключить ее в оболочку, мы были бы богаты вне всякого... я хочу сказать... это было бы благо для всего научного соообщества. \n\nПомоги мне, <имя>, и я выделю для тебя порцию настойки.\n\nДля того чтобы создать стабильное вещество, мне потребуется три клешни скорпока, две меры потрохов стервятника и одно обожженное легкое вепря.", progress = "Так где органы, Эфром!?", completion = "Потрясающе. Анализ этой эссенции был самым сложным. \n\nВозьми щепотку этой солевой вытяжки и положи ее под язык. Ты испытаешь легкое чувство эйфории, после которого наступит состояние невероятной ловкости и быстроты.", rewards = "Следующее заклинание будет наложено на вас:\n\nУдар Скорпока\n\nВы получите:\n\nНастойка Скорпока"},
[2586] = {title = "Скорпоковая соль", objective = "Принесите три клешни скорпока, две меры потрохов стервятника и одно обожженное легкое вепря волшебнице крови Дразиале.", description = "Ты <жив/жива>! Это поистине хорошая новость! Полагаю, тебе нужно еще скорпоковой настойки?\n\nОтлично, <имя>, тогда снова ступай в пустоши и не возвращайся, пока не заполучишь три клешни скорпока, две меры потрохов стервятника и одно обожженное легкое вепря.", progress = "Так где органы, Несмеро!?", completion = "Отличная работа, Несмеро. Вот одна мера настойки для тебя, а оставшиеся девять будут использованы для моих исследований. \n\nВ любой момент, когда тебе понадобится скорпоковая настойка, возвращайся ко мне, и мы заключим сделку.", rewards = "Вы получите:\n\nНастойка Скорпока"},
[2601] = {title = "Укус василиска", objective = "Принесите десять мозгов василиска и потроха двух стервятников волшебнице крови Линоре.", description = "Эти пустоши кишат василисками Красного камня, <имя>. Эти василиски отлично приспособились к местным условиям, их тут больше, чем любых других диких животных. \n\nЯ наблюдала издали, как они охотятся и ведут свою повседневную жизнь – мыслительный процесс у этих тварей, похоже, куда более сложный, чем у некоторых из тех существ, которых мы называем разумными.\n\nЯ должна изучить их мозги!\n\nРаздобудь для меня десять их мозгов, <имя>. Однако для опытов мне понадобятся еще потроха двух стервятников, которые дадут основу для раствора.", progress = "Удалось ли тебе добыть нужные органы?", completion = "Замечательно, Томпсон! Предлагаю тебе отведать на вкус внутреннюю суть василисков красного камня.\n\nЕсли этот состав тебе понравится, всегда можно сделать еще... за определенную плату.", rewards = "Следующее заклинание будет наложено на вас:\n\nНепогрешимый разум\n\nВы получите:\n\nЭликсир Мозгового штурма"},
[2602] = {title = "Непогрешимый разум", objective = "Принесите десять мозгов василиска и потроха двух стервятников волшебнице крови Линоре.", description = "Твое сосредоточение ушло так скоро? Нужно провести еще больше исследований!\n\nАх да, <имя>, цена остается прежней. Отправляйся в Выжженные земли и возвращайся ко мне с десятью мозгами тварей Красного Камня и потрохами двух стервятников.", progress = "Удалось ли тебе добыть нужные органы?", completion = "Да, да, Бхт, дай мне минутку, и нужные тебе составы будут готовы к употреблению.\n\nВот, возьми... и помни, Бхт, что нельзя даже пытаться употреблятьь эти экспериментальные составы слишком часто. Результат будет катастрофическим.", rewards = "Вы получите:\n\nЭликсир Мозгового штурма"},
[2603] = {title = "Стойкость стервятника", objective = "Принесите потроха десяти стервятников и две челюсти гиены волшебнице крови Линоре.", description = "В этих опаленных землях смерть воистину крылата, <раса>.Я много раз наблюдала, как черные убийцы и костеглоды пируют на телах павших исследователей – иногда пожирая наиболее отвратительные и разложившиеся останки трупов. Удивительно все же, как их внутренние органы справляются с заразой, царящей в этих землях?\n\nПомоги мне в моих исследованиях, <имя>! Мне нужны потроха! Понадобятся также две челюсти гиены в качестве основы для состава.\n\nТвои усилия будут вознаграждены вдвойне.", progress = "Не трать зря мое время, Виаджеро. Нам нечего обсуждать, пока ты не принесешь то, что мне требуется.", completion = "Превосходно! Я немедленно приступаю к работе. Возможно, удастся найти лекарство от множества недугов, существующих в этом мире!\n\nАх да, твоя награда – конечно, если тебе опять понадобится зелье, возвращайся ко мне, я дам тебе новое поручение.", rewards = "Следующее заклинание будет наложено на вас:\n\nДуховное превосходство\n\nВы получите:\n\nЗелье из потрошков"},
[2604] = {title = "Духовное господство", objective = "Принесите потроха десяти стервятников и две челюсти гиены волшебнице крови Линоре.", description = "Я вижу, внутреннее пламя угасло. Как по-твоему, длилась ли эта духовная эйфория хотя бы час?\n\nЕсли ты желаешь получить еще зелья из потрошков, то изволь снабдить меня сырьем! Отправляйся обратно, <имя>. И не возвращайся, пока не наберешь десять мер потрохов и две челюсти.", progress = "Не трать зря мое время, Тунфокс. Нам нечего обсуждать, пока ты не принесешь то, что мне требуется.", completion = "Возможно, когда-нибудь я смогу выделить активные компоненты этой эссенции и получить куда более эффективный результат. К несчастью, пока тебе придется довольствоваться тем, что я в состоянии сделать на настоящий момент. Если понадобится еще зелье из потрошков, возвращайся ко мне.", rewards = "Вы получите:\n\nЗелье из потрошков"},
[2605] = {title = "Жаждущий гоблин", objective = "Добудьте насыщенную влагой железу и принесите ее Синю Гогельмогелю в Прибамбасск.", description = "Слышь, у меня возникла мысль. Я слышал о странных тварях, собирателях росы, живущих на юго-западе... Говорят, они хранят воду в особых железах.\n\nМне кажется, что из этих желез я бы сделал напиток, который утолил бы мою жажду! Ты не поможешь мне, <имя>?\n\nПоищи кактусовый сад, <имя>, именно там пасутся собиратели росы.", progress = "Прошу, скажи мне, что ты нашел собирателей росы!", completion = "Чудесно! Дай мне железу – я хочу выпить ее!", rewards = "Вы получите:\n\n"},
[2606] = {title = "Хороший вкус", objective = "Поговорите с Поливалкой в Прибамбасске по поручению Синя Гогельмогеля.", description = "Фу! Ну и гадость! Да, идея была неудачная…\n\nСтой, что такое? О, знаю, ты считаешь, что не стоит отказываться от этой штуки. Ладно.\n\nЭээ... У меня есть идея! Гениально! Отнеси эту росу моей подруге Поливалке – она отличный повар. Скажи, что мы тут задумали, пусть придумает, как улучшить вкус.\n\nЯ хочу сказать, что такая дрянь по крайней мере, должна пробирать до мозга костей... А пока ей до мозга далеко...", progress = "Значит, старый Синь опять за свое? Из чего сделан этот состав?", completion = "Синь отличный парень, не пойми меня превратно – только немного... эксцентричный, что ли.\n\nИ разумеется, ему опять нужна моя помощь.", rewards = "Вы получите:\n\n"},
[2607] = {title = "Прикосновение Занзила", objective = "Поговорите с Доком Миксиль-Пиксилем в подвале казарм.", description = "Похоже, что информации у вас даже больше, чем я ожидал. Как-то странно все оборачивается, <имя>.\n\nЛекарство? Хм-м... Спуститесь в подвал и поговорите с Доком Миксиль-Пиксилем – он, вероятно, сможет помочь.", progress = nil, completion = "Как раз вовремя! Просто положите сыр на стол и проваливайте. Осборн заплатит вам на выходе.", rewards = nil},
[2608] = {title = "Прикосновение Занзила", objective = "Лягте на землю (действие /lay) для осмотра Доком Миксиль-Пиксилем – он не сможет подобрать лекарство, пока не найдет причину болезни.", description = "Ох, вы так выглядите – точь-в-точь мертвец. Поправочка – я видел мертвецов, вы выглядите еще хуже. Вы, <сударь/детка>, будете предсмертной отрыжкой самой смерти.\n\nХа! Слышал, Ноарм? Запиши-ка это!\n\n*Кашляет.* Хмм, да, чтобы я мог помочь, мне нужно будет взять у вас немного крови. Не беспокойтесь, больно лишь первые... раз пятьдесят или около того... Ложитесь, и приступим к лечению, <имя>!", progress = nil, completion = "Позвольте, я минутку посовещаюсь со своими коллегами, Скирди. Доктор Монтгомери, мистер Ноарм, все на консилиум!", rewards = "Вы получите:\n\n"},
[2609] = {title = "Прикосновение Занзила", objective = "Принесите Доку Миксиль-Пиксилю один букетик простых полевых цветов, одну освинцованную колбу, одну бронзовую трубку и одну катушку светлого зеленовато-желтого шелка. Чтотит, знаете ли, сам собой не проходит.", description = "Однозначно, <имя>. У вас чтотит.\n\nК счастью, от чтотита у меня есть средство.\n\nИ вот что мне понадобится для его изготовления: букетик простых полевых цветов, одна освинцованная колба, одна бронзовая трубка и последнее – но немаловажное! – нитка светлого зеленовато-желтого шелка. Старушка Эмма оставила для меня катушку таких ниток в \"Тончайшей пряже\". Эту лавку можно найти, если идти вдоль каналов.\n\nА теперь поспешите, <имя>, и постарайтесь ни к кому не прикасаться, пока вас не вылечат. Кстати, доктор Монтгомери сказал, что вам нужно душ принять... это его слова, не мои!", progress = "Если хотите вылечить свой чтотит, придется приложить побольше усилий, Скирди. Где компоненты исцеляющего средства?", completion = "Что я делаю? А на что похоже то, что я делаю? Я продумываю, как вылечить ваш чтотит! И нечего так возмущенно на меня смотреть, Скирди! Еще несколько секунд... Готово! Побрызгайте на себя этим лечебным средством с... эээ... необыкновенным запахом – и вы в полном порядке!", rewards = "Вы получите:\n\nО-де-Миксиль-пиксиль"},
[2621] = {title = "Опозоренный", objective = "Поговорите с командиром разведотряда Руагом в Каменоре.", description = "Сожалею. Это все, что у меня есть. Одно неверное решение, приведшее к массе плохих последствий. Если бы я только дождался тех приказов! Может быть, там было бы сказано подробно обо всех ужасах, ожидающих нас в этих проклятых землях? Может быть, нам дали бы другое задание или выслали бы подкрепление? Но в конечном итоге, это моя вина. Все это – моя вина. \n\nИ вот я стою здесь, ожидая приказов. Я должен знать. Я должен знать, каковы эти приказы. \n\nКомандир-посланник Руаг находится в Каменоре. Найди его и узнай, что стало с приказами.", progress = nil, completion = "Хватка Тралла... Эта история все еще свежа в моей памяти.\n\n*Командир Руаг качает головой.*\n\nУжасная вещь – то, что случилось с этим подразделением. Орда потеряла немало своих лучших солдат, когда этот батальон был уничтожен.", rewards = "Вы получите:\n\n"},
[2622] = {title = "Пропавшие приказы", objective = "Поговорите с Бенгором.", description = "Приказы? Зачем тебе понадобились эти приказы?\n\nЧто ты подразумеваешь, <имя>? Конечно, я передал эти приказы! Солдаты, с которыми я их послал, попали в засаду и были безжалостно забиты до смерти мурлоками. Выжил только один – если это называется выжить. Он едва может говорить, не может ходить, его приходится кормить через трубку. Если хочешь знать, что случилось с приказами, поговори с Бенгором. Я знаю, он где-то неподалеку... и вот еще что, <имя>, следи, куда суешь свой нос – его ведь и откусить могут.", progress = nil, completion = "Болот... ный... гово... говорун...", rewards = "Вы получите:\n\n"},
[2623] = {title = "Болотный говорун", objective = "Заберите приказы Вождя и верните их павшему герою Орды.", description = "Приказы были отданы командиром-посланником. Мы приняли... приняли приказы. На пути в Выжженные земли – засада.\n\nМурлоки... много мурлоков... Одного звали Болотный Говорун. Вырвал приказы у меня из рук, ударил копьем мне в голову. Восток... пещера...\n\n*Бенгор теряет сознание.*", progress = "Ожидаю приказов.", completion = "Это хуже, чем я ожидал. Девятнадцать моихх соратников были бы избавлены от мучений, которым они подвергаются. Если бы я только действовал не столь неразумно!\n\nПомоги им, Томпсон! Я бессилен что-либо сделать.", rewards = "Вы получите:\n\n"},
[2641] = {title = "Маленький секрет Поливалки", objective = "Найдите фиалковый траган и вернитесь к Поливалке в Прибамбасск.", description = "Когда я была маленькая, у нас в семье готовила моя сестра. Это было ужасно! Половину ее творений я даже в рот взять не могла... пока не отыскала свой \"маленький секрет\"! Добавь его в любую еду и... получится вкуснятина!\n\nЧто за секрет, спросишь ты. Это гриб, называемый фиалковый траган. Если хочешь помочь мне превратить эту дрянь во что-то съедобное, отправляйся во Внутренние земли и поищи там маленькое озерцо.\n\nИ не забывай, фиалковый траган растет только под водой.", progress = "Фиалковый траган можно найти только в озере, под водой. Надеюсь, ты умеешь задерживать дыхание!", completion = "Ага, вот и он!\n\nОтлично выглядит, хоть сейчас... Ха-ха, шучу!", rewards = "Вы получите:\n\n"},
[2661] = {title = "Посылка для Синя", objective = "Отнесите фиалковый порошок Синю Гогельмогелю в Прибамбасск.", description = "Вот фиалковый порошок, <имя>. Отнеси его Синю и скажи ему, что он мой должник!", progress = "А, вот и ты, Томпсон. Что ты мне принес?", completion = "Фиалковый порошок, значит? Дай-ка попробую – хуже все равно не будет, это ясно!", rewards = "Вы получите:\n\n"},
[2662] = {title = "Эликсир Гогельмогеля", objective = "Синь Гогельмогель хочет поговорить с вами после завершения работы над эликсиром.", description = "А теперь вмешаем этот порошок в росу.\n\nЗаходи через пару минут... когда я доведу до совершенства великолепный эликсир Гогельмогеля!", progress = nil, completion = "Попробуй! Невероятно вкусно!!!\n\nЯ знал, что у меня все получится... Еще раз спасибо за помощь, Томпсон, только встань в сторонке! Ты не даешь прохода будущим покупателям. Я заработаю миллионы на неподражаемом эликсире Гогельмогеля, миллионы!\n\nЧто такое? Поливалка говорит, что я ее должник? Ох, такая шутница эта Поливалка!", rewards = "Вы получите:\n\nЭликсир Гогельмогеля"},
[2681] = {title = "Камни, что связывают нас", objective = "Освободите девять Слуг Разелиха, трех Слуг Севины, трех Слуг Аллистария и трех Слуг Грола. Когда ваша задача будет выполнена, возвращайтесь к павшему герою. Вы должны оставаться поблизости от камней, иначе процесс не будет завершен.", description = "Одних лишь твоих сил не хватит, чтобы одолеть Разелиха и его приспешников.\n\nСобери подходящую группу искателей приключений и освободи моих подчиненных от вечных мук! Тебе нужно разбить восемнадцать камней.\n\nСражайся отважно и умри с честью, <имя>.", progress = "Это нелегкая задача, Зомбяк. Не сдавайся!", completion = "Тебе это удалось, Томпсон! Несчастные, истерзанные души наконец-то обретут покой.\n\nНо наша работа еще не завершена, Томпсон. Нам еще многое нужно обсудить и еще больше сделать.", rewards = "Вы получите:\n\n"},
[2701] = {title = "Герои древних времен", objective = "Откройте шкатулку и возьмите награду.", description = "Пожалуйста, забери отсюда реликвию древности. Мы больше ни на что не можем использовать ее.\n\nМожет быть, она послужит тебе в борьбе против Легиона.", progress = nil, completion = "Искристый блеск на какое-то время ослепляет вас.", rewards = "Вы получите:\n\nСфера Треснувшего Копыта"},
[2702] = {title = "Герои древних времен", objective = "Поговорите с капралом Тундом Треснувшее Копыто.", description = "Твои благородство и героизм – высокая честь для меня, <имя>.\n\nИ для тебя – не менее высокая...", progress = nil, completion = "Поистине, ты оказываешь честь нам всем. Одних лишь благодарностей будет недостаточно.", rewards = "Вы получите:\n\n"},
[2721] = {title = "Кирит", objective = "Узнайте, что стало с лейтенантом Киритом.", description = "Как только завершается одна часть твоих приключений, <имя>, начинается другая.\n\nОдин из моих подчиненных пропал без вести – затерялся где-то в Выжженных землях. Я, конечно же, говорю о лейтенанте Кирите. \n\nКак я упоминал ранее, мы оба были в плену у Аллистария и подвергались мучениям, но увы несчастному Кириту – его сила воли оказалась недостаточно велика. Из своей клетки я слышал происходящее: крики боли разносились по пещерным залам. С тех пор Кирита и след простыл.", progress = nil, completion = "Требор? Тебя послал Требор?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2741] = {title = "Супер Яйц-О-Матик", objective = "Супер Яйц-О-Матик – последнее изобретение Кургль Поскакушки. Очень впечатляющее устройство.\n\nПриближаясь к панели управления, вы слышите, как машина яростно гудит.", description = nil, progress = "Супер Яйц-О-Матик – последнее изобретение Кургль Поскакушки. Очень впечатляющее устройство.\n\nПриближаясь к панели управления, вы слышите, как машина яростно гудит.", completion = "Вы кладете в машину яйцо гиппогрифа. Раздается несколько гудков и странный механический шум.\n\nПохоже, яйцеметр взвесил, измерил и упаковал ваше яйцо. Вот это называется быстрое обслуживание!", rewards = "Вы получите:\n\nЯщик для яиц"},
[2742] = {title = "Рин'джи в ловушке", objective = "Выведите Рин'джи из Сторожки Кель'Данил, а потом найдите то, что он спрятал в Отвесных скалах, на востоке.", description = "Эй, <раса>!\n\nРин'джи потерял топор, и его схватили! Пожалуйста, помоги Рин'джи сбежать. Я знаю, что не <каждый/каждая:r> <раса> любит троллей, но я тебя очень прошу! Мне надо выйти отсюда!\n\nУ меня кое-что есть, и очень хорошее, если поможешь мне, я тебе это подарю...\n\nРин'джи спрятал свой секрет у Отвесных скал.", progress = nil, completion = "Эта табличка, наверное, и есть тот самый \"секрет\", о котором говорил Рин'джи.\n\nОна покрыта странными письменами, которые вам совершенно не знакомы.", rewards = "Вы получите:\n\n"},
[2743] = {title = "Покров Тьмы", objective = "Вернитесь к павшему герою Орды со своими находками.", description = "Не будем тратить слов, <раса>; мое время здесь ограничено.\n\nТебе следует уничтожить троицу силы, связанную с повелителем демонов Разелихом. Это деяние не настолько просто, как задача по освобождению проклятой души.\n\n*Кирит ухмыляется.*\n\nВидишь ли, каждый из прислужников Разелиха носит на шее треть амулета, при помощи которого был создан Разелих. Тот же самый амулет понадобится тебе для призвания сего архидемона.\n\nВозвращайся к Требору и поведай ему, что требуется для призвания Разелиха. Он подскажет тебе, что делать дальше.", progress = nil, completion = "Повелитель демонов проявляет хитрость почти столь же расчетливую, как и его жестокость, Томпсон.", rewards = "Вы получите:\n\n"},
[2744] = {title = "Охотник на демонов", objective = "Поговорите в Азшаре с Лорамусом Многоногом.", description = "Эта троица находится под покровительством Разелиха.\n\nВ обмен на их службу Разелих даровал каждому из них почти безграничную власть над Выжженными землями. Кусочки амулета связаны с жизненной силой их владельцев и дают им бессмертие. Пока они остаются в Выжженных землях, их нельзя убить и их жизнь продлится до конца мира.\n\nНо есть некто, способный оказать тебе помощь в дальнейшем, <имя>. Отправляйся в Азшару и найди там охотника на демонов, Лорамуса Многонога. Поиск следует вести на островах.", progress = "Что ты здесь делаешь?", completion = "Я помогу тебе. Однако мне кажется, что ты не совсем понимаешь, против чего сражаешься.", rewards = "Вы получите:\n\n"},
[2745] = {title = "Проникновение в крепость", objective = "Поговорите с Тирионом в Крепости Штормграда.", description = "Хм-м, интересная история, причем не из тех, на которые можно наплевать. Да, помочь-то я вам могу, но то, что вам нужно будет сделать, это свершить правосудие... частично незаконным путем, если уж вы хотите довести дело до конца.\n\nС Лесковаром и Марзоном нужно разобраться – и быстро. Как думаете, вы на это способны?\n\nРешать вам. Если да, то поскорее отправляйтесь в крепость и найдите там моего старинного друга – гнома по имени Тирион. Он уже пару недель как наблюдает за Лесковаром. Он сможет помочь вам покончить с этим делом.", progress = nil, completion = "Какого?! Не подкрадывайтесь ко мне вот так! И говорите тише! На кой вы, спрашивается, во имя Теней, так ко мне подкрадываетесь? Не видите, что ли – я занят, безмозглое вы создание!\n\nЧто вы имеете в виду, спрашивая, что я делаю? Жду открытия следующего Темного портала, а вы что подумали? Выкладывайте, с чем пришли, и валите отсюда... пока стражники не заметили, что мы тут вдвоем в кустах прячемся. Мне нужно блюсти репутацию.", rewards = "Вы получите:\n\n"},
[2746] = {title = "Все по порядку", objective = "Принесите Тириону в Штормград 3 отреза шелка и 2 свежих яблока Клары.", description = "Триас хочет поторопить события, так? Ладно, мы это сделаем, но сейчас я не готов. И, кстати, сложную часть я беру на себя, а ручки пачкать будете вы, это понятно? Отлично.\n\nЗначит, мне нужно, чтобы вы мне кое-что принесли, чтобы я смог воплотить в жизнь свой план. У меня есть мысль об отличной маскировке, при помощи которой этот робот-шпион пройдет мимо стражников.\n\nПринесите мне немного шелка и пару яблок. Где достать шелк – думайте сами, а вот подходящие яблоки есть у Клары в ее маленьком хозяйстве сразу за городской чертой.", progress = "Я наблюдаю за Лесковаром вот уже две недели. Триас никогда ему не доверял, но мы и не подозревали, что он втянут во что-то, связанное с Братством Справедливости. Мы отслеживали то, что могло связывать его с Сумеречным Молотом. В любом случае, он становится более опасным, чем допустимо для этого города, и тут-то мы и вступаем в дело.\n\nПринесите мне указанные предметы, и мы сможем осуществить мой план.", completion = "Это отлично подойдет, Бронгард. Прекрасная работа.\n\nВся остальная амуниция у меня в сумке... Слава Свету, у меня есть приятель-портной, сшивший мне шелковую сумку. А то мне бы уже некуда было рассовывать свои вещи.\n\nПрежде чем мой робот-шпион отправится куда надо, давайте обговорим детали, чтобы вы знали, что вам нужно будет делать.", rewards = "Вы получите:\n\n"},
[2747] = {title = "Необычное яйцо", objective = "Редко удается принести яйца из Фераласа в таком необыкновенном состоянии. Они очень редко встречаются...", description = nil, progress = "Редко удается принести яйца из Фераласа в таком необыкновенном состоянии. Они очень редко встречаются...", completion = "Значит, ты смог добыть такое яйцо – поразительно!\n\nСегодня ты совершил настоящий подвиг!", rewards = "Вы получите:\n\nКоробка со сластями"},
[2748] = {title = "Хорошее яйцо", objective = "Из хороших яиц при правильных условиях вылупляются гиппогрифы, не пораженные заклинаниями огров клана Гордунни.", description = nil, progress = "Из хороших яиц при правильных условиях вылупляются гиппогрифы, не пораженные заклинаниями огров клана Гордунни.", completion = "Очень хорошо, Томпсон. Скоро я пошлю это яйцо в Дарнасс, надеюсь, из него вскоре вылупится гиппогриф!\n\nПрими это в знак моей благодарности.", rewards = "Вы получите:\n\nКоробка с заклинаниями"},
[2749] = {title = "Обычное яйцо", objective = "Обычные яйца гиппогрифа вылупляются только в половине случаев. Мы будем тщательно ухаживать за ними, и при удаче кто-нибудь из них вылупится.", description = nil, progress = "Обычные яйца гиппогрифа вылупляются только в половине случаев. Мы будем тщательно ухаживать за ними, и при удаче кто-нибудь из них вылупится.", completion = "Значит, ты нашел обычное яйцо? Пожалуйста, дай его мне... Будем надеяться на лучшее.\n\nПрими эту награду, это все, что у меня есть. Если снова окажешься в Фераласе, помни, что я всегда готова купить найденные тобой яйца.", rewards = "Вы получите:\n\nКоробка с пайками"},
[2750] = {title = "Плохое яйцо", objective = "Яйца вроде этого не спасти – из них никто не вылупится.", description = nil, progress = "Яйца вроде этого не спасти – из них никто не вылупится.", completion = "Боюсь, я тебя не порадую. Это яйцо уже не спасти. Я могу забрать его у тебя и поступить с ним, как должно.\n\nНе огорчайся, всех нам все равно не спасти. Если ты снова окажешься в Фераласе, попробуй еще раз. Принеси еще одно яйцо для Супер Яйц-О-Матика!", rewards = "Вы получите:\n\n"},
[2751] = {title = "Варварские доспехи", objective = "Принесите 2 узорчатых бронзовых боевых браслета, 2 бронзовых больших меча и 2 острых когтя Орокку Омошу в Оргриммар.", description = "Двадцать поколений Омошей держали в руках этот молот, <имя>! Сколько тонн металла мы перековали! Но, увы, на мне наш род завершится. У меня нет потомства.\n\nЯ не могу допустить, чтобы тайные чертежи и приемы Омошей умерли вместе со мной!\n\nДокажи Орокку, что ты годишься в кузнецы, <имя>. Принеси ему 2 узорчатых бронзовых боевых браслета, 2 бронзовых больших меча и 2 острых когтя. Принеси их Орокку, и мы продолжим обучение.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЧертеж: варварская железная кираса"},
[2752] = {title = "За железными наплечниками", objective = "Принесите Орокку Омошу в Оргриммар 4 бронзовых боевых топора и 4 бронзовых боевых молота.", description = "У тебя внимательные глаза, <имя>. Ты вбираешь мудрость Омошей, точно губка!\n\nТри урока дам я тебе.\n\nВернись к наковальне и сделай для Орокка 4 бронзовых боевых топора и 4 бронзовых боевых молота. Лишь тогда узнаешь ты, как изготовить железное оплечье!", progress = "Продемонстрируй мне свое усердие, |3-6(орк)!", completion = "Орокк гордится тобой, Фаршбрингер. Вот, читай, как изготовить железное оплечье!", rewards = "Вы получите:\n\nЧертеж: варварские железные наплечники"},
[2753] = {title = "Тяжелая поступь", objective = "Принесите 4 зеленых железных шлема, 4 пары зеленых железных наручей и 2 пары зеленых железных поножей Орокку Омошу в Оргриммар.", description = "Орокк научит тебя еще двум вещам, <имя>. Да, я знаю, тебе тяжело, но надо продолжать – во имя Омошей!\n\nПринеси 4 зеленых железных шлема, 4 пары зеленых железных наручей и 2 пары зеленых железных поножей – и я научу тебя тому, что будет страшить твоих врагов!", progress = "Их черепа будут трещать под твоими сапогами!", completion = "Ты напоминаешь Орокку его деда, Горокка Омоша! Вот, читай, учись делать железные сапоги.", rewards = "Вы получите:\n\nЧертеж: варварские железные сапоги"},
[2754] = {title = "Рога безумия", objective = "Принесите Орокку Омошу в Оргриммар 2 твердых железных кувалды, 2 пары посеребренных бронзовых сапог и 2 пары посеребренных бронзовых рукавиц.", description = "Это последнее, чему научит тебя Орокк, <имя>. Но прежде принеси Орокку 2 твердых железных кувалды, 2 пары посеребренных бронзовых сапог и две пары посеребренных бронзовых рукавиц.\n\nТы узнаешь, как приятно видеть страх в глазах врагов при одном твоем появлении!", progress = "Ну-ка, Фаршбрингер, покажи железу, кто тут главный!", completion = "Потрясающе, Фаршбрингер! Теперь ты знаешь все секреты Омошей!", rewards = "Вы получите:\n\nЧертеж: варварский железный шлем"},
[2755] = {title = "Радости Омоша", objective = "Научитесь танцу Радости Омошей.", description = "Нет, <имя>, Орокк не плачет. Это сажа в глаз попала.\n\n*Орокк утирает слезу.*\n\nОстался последний секрет семьи Омошей, которому научит тебя Орокк.\n\nВыучи танец радости Омошей, и научишься ковать железный кулак!", progress = nil, completion = "*Орокк шумно отдувается.*\n\nДавненько Орокк не плясал танец Радости Омошей! Ну, Фаршбрингер, смотри и учись!", rewards = "Вы получите:\n\nЧертеж: варварские железные перчатки"},
[2756] = {title = "Старые обычаи", objective = "Принесите 4 стальные кирасы и 4 стальных латных шлема Атурку Наковальне в Оргриммар.", description = "В былые легендарные времена Атурк сокрушил бы черепа своих врагов и истер кости в мелкий порошок! Но эти дни давно миновали, <раса>. Вождь требует мира между кланами, и старых врагов мы теперь даже пальцем тронуть не смеем.\n\nДаже не верится! Но такова воля Тралла.\n\nНу, довольно жалоб! Ты здесь, чтобы учиться – и ты будешь учиться! Принеси 4 стальные кирасы и 4 стальных латных шлема, и узнаешь вкус войны!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nИзучить орочьи боевые поножи\n\nВы получите:\n\n"},
[2757] = {title = "Вперед, в Пиратскую бухту!", objective = "Поговорите с Макгеваном в Пиратской бухте.", description = "Слышь, будешь болтаться здесь – так ничему и не научишься!\n\nВот я знаю мужика, который знает мужика, который ошивается возле кузницы в Пиратской бухте. Покажи ему этот значок, и он тебе про мифрил все расскажет!\n\nЧего-чего? Оставь это грудным младенцам, <имя>, тебе пора двигаться дальше!\n\nЕсли тебя это интересует, его звать Макгеван.", progress = "Экий редкий зверь к нам пожаловал! Ну-ка, покажи свой значок...", completion = "Клянусь задницей Черного Копыта! Наконец хоть кто-то достойный Ордена мифрила!", rewards = "Вы получите:\n\n"},
[2758] = {title = "Происхождение кузнечного искусства", objective = "Принесите 6 пар золотых чешуйчатых наручей Ханку Молоту в Штормград.", description = "Когда я был примерно в твоем возрасте, дворф по имени Гальван взял меня под свою опеку и обучил меня способам ковки доспехов. Перед своим отъездом в Пиратскую бухту он заставил меня пообещать, что я буду до конца дней своих обучать всех, у кого будет желание и решимость овладеть кузнечным ремеслом. Так я и поступил.\n\nИтак, теперь настало твое время чему-нибудь научиться. Сделай мне шесть пар золотых чешуйчатых наручей – и узнаешь, откуда есть пошло кузнечное дело, <имя>.", progress = "Может быть, ты станешь одним из наследников Гальвана!", completion = "Отлично, Маладат! Слушай и впитывай.\n\nМастерство кузнеца никогда не исходит отсюда! *Хэнк указывает на молот.*\n\nМастерство кузнеца никогда не исходит и отсюда! *Хэнк указывает на наковальню.*\n\nТолько отсюда происходит мастерство кузнеца! *Хэнк указывает себе на сердце.*\n\nТеперь ты знаешь, каково происхождение кузнечного искусства.", rewards = "Вы получите:\n\nЧертеж: золотые чешуйчатые рукавицы"},
[2759] = {title = "В поисках Гальвана", objective = "Поговорите с Макгеваном в Пиратской бухте.", description = "Хотя Гальван покинул Пиратскую бухту много лет назад, члены ордена по-прежнему остаются в городе, надеясь однажды найти кого-нибудь, достойного внимания мастера.\n\nВозьми этот знак и отдай его Макгевану в Пиратской бухте.\n\nЕсли ты действительно с этим справишься, он поймет, что ты <достоин/достойна>. Я в тебя верю, <имя>!", progress = "Редкая ты, должно быть, птица, дружище. Дай-ка мне глянуть на этот знак...", completion = "Клянусь гривой Черного Копыта – наконец-то появился хоть кто-то, достойный Ордена мифрила!", rewards = "Вы получите:\n\n"},
[2760] = {title = "Орден Мифрила", objective = "Поговорите с Гальваном Древним в Тернистой долине.", description = "Большинство наших новобранцев так и не добрались до Пиратской бухты, <имя>. Блеска эмблемы оказывается достаточно, чтобы пробудить алчность даже в самых стойких кузнецах. Дураки, эмблема эта – капля в море по сравнению со стоимостью предметов, которые ты увидишь!\n\nНайди Гальвана Древнего и покажи ему эту булавку. Он живет далеко на севере, междук Зул-Гурубом и холмом Мош'Огг.", progress = "Приветствую! Подойди ближе; покажи Гальвану, что у тебя.", completion = "А, прошло много лет, с тех пор, как я в последний раз видел достойных принятия в Орден мифрила. Начнем же!", rewards = "Вы получите:\n\n"},
[2761] = {title = "Плавим, не плавим, плавим, не плавим…", objective = "Принесите сорок мифриловых слитков и сорок железных слитков Гальвану Древнему из Тернистой долины.", description = "Многие кузнецы считают, что горное дело и кузнечное ремесло – две разные вещи; но что за кузнец без металла? Как же, это невозможно! Опытный кузнец должен быть и опытным горняком.\n\nПокажи Гальвану, на что ты <способен/способна>, <имя>. Принеси мне сорок слитков железа и сорок слитков серебра. За это Гальван научит тебя создавать изысканные мифриловые штаны!", progress = "Когда хорошо поработаешь, мышцы ноют и тело ломит!", completion = "Твои работы безупречны! Ты начинаешь понимать основы минералогии Гальвана! Возьми это и научись всему, чему сможешь.", rewards = "Вы получите:\n\nЧертеж: изысканные мифриловые штаны"},
[2762] = {title = "Обманное серебро", objective = "Принесите сорок мифриловых слитков и сорок слитков истинного серебра Гальвану Древнему из Тернистой долины.", description = "Говорят, что истинное серебро прочнее мифрила. Гальван не будет спорить с такой оценкой, но вопреки названию, истинное серебро далеко от истины! Мифрил куда благороднее! ХА! И тем не менее, на сей раз тебе придется найти это обманное серебро.\n\nПринеси мне сорок мифриловых слитков и сорок слитков истинного серебра. Взамен я научу тебя искусству изготовления изысканных мифриловых перчаток, и что куда важнее, ты узнаешь, что истинное серебро – это лжец.", progress = "Когда хорошо поработаешь, мышцы ноют и тело ломит!", completion = "Нелегко с ним справиться, а? Я об истинном серебре. Гальван потратил не меньше десяти лет в горах Альтерака, прежде чем усвоил этот урок. Возьми это и научись, чему сможешь!", rewards = "Вы получите:\n\nЧертеж: изысканные мифриловые перчатки"},
[2763] = {title = "Могущество камней", objective = "Принесите сорок мифриловых слитков и 4 цитрина Гальвану Древнему из Тернистой долины.", description = "Для нашего ремесла очень важно научиться добывать дракоценные камни. Немногие камни драгоценнее цитрина. Он во много раз усиливает ту магию, которую мы вкладываем в наши творения.\n\nНа сей раз мы усилим сорок слитков мифрила четырьмя цитринами. В результате ты получишь лучшее представление о магической гемологии и научишься создавать изысканные мифриловые наплечники.", progress = "Когда хорошо поработаешь, мышцы ноют и тело ломит!", completion = "Да, от такой красоты взгляда не оторвешь, Маладат. Цитрин – великолепный камень.\n\nА теперь смотри внимательно, вот чему можно научиться!", rewards = "Вы получите:\n\nЧертеж: изысканный мифриловый наплечник"},
[2764] = {title = "Лучший ученик Гальвана", objective = "Поговорите с Трентоном Молотом Света из Прибамбасска.", description = "Если ты <готов/готова> покинуть Гальвана, отправляйся в Прибамбасск.\n\nТам живет мой лучший ученик, Трентон Молот Света. Он научит тебя обращению с изысканным мифрилом. Впрочем, можешь остаться здесь и поучиться еще!\n\nАх да, Прибамбасск находится в Танарисе!", progress = nil, completion = "Тебя прислал Гальван Древний?\n\n*Трентон кланяется*\n\nЭто большая честь – познакомиться с еще одним из его учеников!", rewards = "Вы получите:\n\n"},
[2765] = {title = "Кузнец-умелец!", objective = "Получите награду у Гальвана Древнего!", description = "Я с первого взгляда понял, что ты станешь <одним из моих лучших учеников/одной из моих лучших учениц>! Ты без колебаний <отдал/отдала> Макгевану вещь, наделенную силой, лишь бы только встретиться со мной. Подобная слепая вера и преданность искусству должна быть вознаграждена.\n\nТы <стал/стала> настоящим экспертом в кузнечном деле. Насладись же наградой!", progress = nil, completion = "Что ж, ты в самом деле заслужил украшение, наделенное большей силой, чем то, которым пришлось пожертвовать на пути сюда. Пользуйся на здоровье, Маладат.", rewards = "Вы получите:\n\nПерстень Умения"},
[2766] = {title = "Найти ККX-22/FE!", objective = "Отнесите аварийный маяк к автономному роботу Карлса, в пещеру рядом с Долиной Свирепого Утеса.", description = "Перед вами странный металлический предмет яйцевидной формы. Вы понажимали на кнопочки – и внезапно яйцо ожило и раскрылось. Очевидно, это какой-то гномский приборчик! Из механического яйца раздается искаженный разрядами голос:\n\n\"Меня зовут Карлс Пропеллерз. Мой автономный робот попал в аварию! Обнаруживший его получит награду! Прошу вас, доставьте этот маячок к роботу!\n\nЯ вычислил координаты робота – он находится в пещере рядом с Долиной Свирепого Утеса!\"", progress = "Вы обнаружили какие-то обломки... робота-цыпленка? Металлическое яйцо снова оживает:\n\n\"Да-да, отлично! Это действительно мой автономный робот. Однако, если верить моим сенсорам, ему потребуется мощный толчок, чтобы он мог долететь до Пиратской бухты для починки. Давайте, поместите маяк внутрь аппарата – дальнейшее маяк сделает сам!\"", completion = "Вы помещаете яйцо... то есть аварийный маяк... внутрь цыпленка... то есть автономного робота.\n\nВнутри робота слышится гудение и жужжание. Он пытается подняться на ноги. После того как робот оживает, снова слышится голос Карлса, но на этот раз изнутри робота:\n\n\"Ну что ж, по крайней мере, OOX-22/FE работает. Однако он нуждается в серьезном ремонте! Нести его вы не сможете, он слишком тяжелый... О! У меня идея! Не согласитесь ли вы его проводить?\"", rewards = "Вы получите:\n\n"},
[2767] = {title = "Спасти ККX-22/FE!", objective = "Проводите OOX-22/FE в порт на Забытом Берегу, затем сообщите об этом Карлсу Пропеллерзу в Пиратской бухте.", description = "Из динамика снова слышится искаженный разрядами голос гнома:\n\n\"Мне необходимо перегнать OOX-22/FE в просторное и безопасное место, чтобы начать длительную процедуру подготовки к взлету. Проводите робота из того места, где вы его обнаружили, в... ну, скажем, в порт на Забытом берегу! Это самое подходящее место, и там достаточно просторно, чтобы аппарату было где развернуться.\n\nПроводите робота в порт, а затем сообщите об этом мне. Я живу в Пиратской бухте, меня зовут Карлс Пропеллерз. Конец связи!\"", progress = nil, completion = "О, спаситель! Вы доставили на место OOX-22/FE! У меня просто слов нет, настолько я вам благодарен! Моя серия автономных роботов постоянно нуждается в усовершенствованиях, однако ваша помощь сберегла мне немало часов кропотливой работы, и дорогостоящих деталей вдобавок!\n\nПрошу вас, выбирайте любую из этих готовых моделей. Еще раз спасибо вам, Эфром! Мы с моими роботами – ваши должники!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПроваленный эксперимент полетаКольчужное полотенце\n\nВы также получите:\n\n"},
[2768] = {title = "Изыскательский стержень", objective = "Принесите изыскательский cтержень главному инженеру Чепухастеру в Прибамбасск.", description = "Сержант Блай обокрал меня! Он сказал, что он только одолжит, но он украл мой драгоценный изыскательский стержень!!! Без этого стержня как я буду знать, где бурить новые скважины под воду??\n\nНайди Блая и принеси мне мой стержень! Я услышал, что он вынудил его компашку низкопробных авантюристов идти за сокровищами в Зул'Фаррак, – город, расположенный на западе. Держу пари, там ты его и найдешь.\n\nНадеюсь, что он уже повстречался с троллями, потому что если тебе придется драться с ним за мой стержень, то схватка выйдет нешуточная.", progress = "Ты нашел Блая? Ты принес мой изыскательский стержень?", completion = "Ты сделал это, Эфром. Пришлось ли тебе убить Блая? Надеюсь, ты задал ему и его прихвостням хорошую трепку!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо Масонского братстваГоловной убор Гильдий\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[2769] = {title = "Братья Латунный Болт", objective = "Поговорите с Виззлом Медноштифом на Мерцающей равнине.", description = "Вы еще не встречались с братьями Латунный Болт? Они на Мерцающей равнине в Калимдоре гоняют на своем болиде наперегонки с гоблинами. Обычно они выигрывают, что неудивительно: гоблинские машины взрываются так часто, что едва дотягивают до финишной черты!\n\nНо братья Латунный Болт все равно постоянно ищут новые способы сделать свою машину еще более скоростной, и Виззл сказал мне, что ему нужен очень редкий компонент для очередных экспериментов.\n\nПохоже, ему надо с этим помочь. Спросите его на этот счет.", progress = nil, completion = "Так ты хочешь мне помочь? Отлично!\n\nМне для эксперимента нужна одна штука, и отважный |3-6(Охотник) вроде тебя добудет ее без труда!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2770] = {title = "Газ'рилла", objective = "Принесите искрящую чешую Газ'риллы Виззлу Медноштифу на Мерцающую равнину.", description = "В пустыне Танарис есть город троллей – Зул'Фаррак, в глубине которого находится священный бассейн. Из этого бассейна тролли призывают огромное чудовище, Газ'риллу! Злобная энергия пронизывает это чудовище насквозь, до самых кончиков его чешуи. И именно эту энергию я хочу использовать в своей машине!\n\nПринеси мне наэлектризованную чешую Газ'риллы.\n\nНо только помни, что тролли держат способ призывания этого монстра в тайне, и просто так они с ней не расстанутся.", progress = "Вы принесли чешую? Мне не терпится извлечь из нее максимум пользы!", completion = "Ого, да это же чешуя! Спасибо, Эфром. Сейчас же начну работать с ней.\n\nТак значит, ты видел Газ'риллу? Эта тварь и правда такая большая, как про нее говорят?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nМорковка на палочке"},
[2771] = {title = "Голова на плечах", objective = "Принесите два мифриловых капюшона и один изысканный мифриловый наплечник Трентону Молоту Света.", description = "Похоже, таков был замысел учителя. Меня он научил делать одни предметы, а тебя другие.\n\nУчитель мудр, <имя>! Мы обучим друг друга!\n\nНаучи меня делать мифриловые капюшоны и изысканные мифриловые наплечники, а я покажу тебе, как куется изысканный мифриловый шлем.", progress = "Ты сделал все необходимые предметы, Вброне?", completion = "Великолепно! Даже я говорю, что это отличный результат. Смотри и учись, Вброне!", rewards = "Следующее заклинание будет наложено на вас:\n\nИзучить изысканный мифриловый шлем\n\nВы получите:\n\n"},
[2772] = {title = "Мир у твоих ног", objective = "Принесите две пары тяжелых мифриловых сапог и одни изысканные мифриловые штаны Трентону Молоту Света.", description = "На прошлогодних соревнованиях по кузнечному делу все зрители видели, как трусливый пес из Торговой компании подставил мне подножку. Им и невдомек, как я умудрился выиграть соревнования: правильно, благодаря изысканным мифриловым сапогам!\n\nНа соревнованиях этого года мне понадобятся изысканные мифриловые штаны, потому что в конкурсе участвует крошшер Торговой компании! Научи меня делать штаны, а я научу тебя делать сапоги!", progress = "Ты сделал все необходимые предметы, Шшишш?", completion = "Мир будет у твоих ног, Шшишш! Пусть все падут ниц перед твоим величием!", rewards = "Следующее заклинание будет наложено на вас:\n\nИзучить изысканные мифриловые сапоги\n\nВы получите:\n\n"},
[2773] = {title = "Мифриловый парень", objective = "Принесите две тяжелых мифриловых кирасы и одни изысканные мифриловые перчатки Трентону Молоту Света.", description = "В этих краях меня зовут Мифриловым Парнем. Я продаю изысканный мифрил искателям приключений со всего света.\n\n*Трентон переходит на шепот.*\n\nИм и невдомек, что я не умею делать изысканные мифриловые перчатки. Ш-ш-ш! Пусть это останется между нами.\n\nНаучи меня делать такие перчатки, а я взамен покажу тебе последнее, чему обучил меня Гальван: изысканную мифриловую кирасу.", progress = "Ты все вещи сделал, Вброне?", completion = "Спасибо за науку, Вброне. Скоро в твоих руках окажется король изысканного мифрилового доспеха.\n\nСмотри!!!", rewards = "Следующее заклинание будет наложено на вас:\n\nИзучить изысканную мифриловую кирасу\n\nВы получите:\n\n"},
[2781] = {title = "РАЗЫСКИВАЕТСЯ: Калиф Жало Скорпида", objective = "Принесите голову Калифа Жало Скорпида главному инженеру Чепухастеру в Прибамбасск.", description = "РАЗЫСКИВАЕТСЯ: Калиф Жало Скорпида!\n\nВодная компания Прибамбасска предлагает награду за голову Калифа Жало Скорпида, главы Скитальцев Пустыни. Он обвиняется в:\n\n1. Убийстве сотрудников Водной компании Прибамбасска!\n2. Похищении ресурсов Водной компании Прибамбасска!\n3. Захвате собственности Водной компании Прибамбасска!\n\nПринесите доказательство гибели Калифа Жало Скорпида главному инженеру Чепухастеру и получите награду!", progress = "Да, |3-6(Воин), я официальный представитель Водной компании Прибамбасска. Чем могу быть полезен?", completion = "Наконец-то – правосудие свершилось! Ты нанес суровый удар подлым кочевникам! Жало Скорпида мертв, может быть, это отпугнет этих надоед от колодцев Прибамбасска!\n\nОт лица Водной компании Прибамбасска я вручаю тебе эту награду. Ты оказал нам большую услугу.", rewards = "Вы получите:\n\n"},
[2782] = {title = "Секрет Рин'джи", objective = "Отнесите табличку Оран Змеиные Кольца в Квартал Магов Подгорода. Оран – известная ученая, изучающая троллей из племени Сухокожих, и она наверняка сумеет прочесть надписи на табличке.", description = "Табличка покрыта письменами троллей из племени Сухокожих. Да, секрет Рин'джи и впрямь оказался очень загадочным.\n\nВозможно, эта табличка представляет собой немалую ценность, хотя может быть и с точностью до наоборот. Тролль из племени Сухокожих в беде мог пообещать что угодно, лишь бы его спасли...", progress = "Хм, и что же это?", completion = "Хм, какая необычная табличка... Где вы ее взяли, Томпсон?", rewards = "Вы получите:\n\n"},
[2783] = {title = "Мелкие раздоры", objective = "Поговорите с павшим героем Орды на границе Выжженных земель и болот.", description = "Мы сражаемся не с тем врагом, <имя>.\n\nИстинная сила этих земель продолжает наращивать свою мощь и численность, пока мы ссоримся с орками из-за сожженной земли. \n\nПродолжим ли мы воевать в этих землях против Орды, только чтобы в один ужасный день быть сметенными силой Пылающего Легиона? Это тщетно.\n\nНадо отбросить прочь различия, <имя>, и поговорить с павшим героем Орды. Он знает правду о Выжженных землях.", progress = nil, completion = "Альянс желает помочь?\n\nЯ не думал, что этот день когда-либо наступит вновь. День, когда Альянс будет сражаться плечом к плечу с Ордой против общего врага.\n\nДа будет так... мы объединимся.", rewards = "Вы получите:\n\n"},
[2784] = {title = "Попавший в немилость", objective = "Послушайте, как павший герой Орды рассказывает свою историю.", description = "Выслушай мою историю, <раса>.", progress = "Послушай, что я скажу.", completion = "Будучи духом, я бессилен что-либо сделать. Помоги мне, Томпсон. Дай мне возможность снова обрести свою честь.", rewards = "Вы получите:\n\n"},
[2801] = {title = "Горестная повесть", objective = "Послушайте, как павший герой Орды рассказывает свою историю.", description = "Прежде чем мы продолжим, тебе следует услышать мою историю.", progress = "Послушай, что я скажу, Лавмэйкер.", completion = "Настало время действовать, Томпсон.", rewards = "Вы получите:\n\n"},
[2821] = {title = "Знак качества", objective = "Принесите 10 толстых шкур йети Пратту Макгруббену в Крепость Оперенной Луны.", description = "У меня принцип простой: если что делаешь, делай как можно лучше – и никаких компромиссов! А тот, кто станет говорить, будто качество не имеет значения, того гляди, продаст тебе недвижимость в Дун Мороге с видом на море!\n\nИ вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети. Йети – это существа, которые водятся в Фераласе. Особенно много их в Долине Свирепого Утеса. За каждые десять шкур ты получишь одно из моих кожаных изделий. Ну что, по рукам?", progress = "Принеси десять толстых шкур йети – и получишь любое из моих изделий! А мои вещи на редкость добротные, это все знают!\n\nЕсли не знаешь, где отыскать йети, я тебе подскажу. Ищи у Забытого берега, близ Долины Свирепого Утеса.", completion = "Ну что, видишь, каковы эти шкуры? Надо тебе сказать, что после специальной обработки они делаются прочнее железа! Немногие про это знают, а вот я, с помощью своих особых дубильных составов, смогу делать из них вещи несравненного качества! Ну да, и все это – благодаря тебе.\n\nПожалуйста, Коэн, выбирай себе любое из моих готовых изделий.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги ручной работы ПраттаПерчатки ручной работы Пратта\n\nВы также получите:\n\n"},
[2822] = {title = "Знак качества", objective = "Принесите 10 толстых шкур йети Джангору Быстрому Страннику в Лагерь Мохаче.", description = "Я горжусь своим мастерством. Мои вещи сразу видно! А тот, кто станет говорить, будто качество не имеет значения, пожалуй, захочет убедить тебя и в том, будто земля не хранит тайн!\n\nИ вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети. Йети – это существа, которые водятся в Фераласе. Особенно много их к западу отсюда, в Долине Свирепого Утеса. За каждые десять шкур ты получишь одно из моих кожаных изделий. Ну что, по рукам?", progress = "Ну что, удалось тебе добыть десять толстых шкур йети? Мои кожаные изделия не знают себе равных, и ты получишь в уплату одно из них, только принеси шкуры.\n\nЕсли не знаешь, где отыскать йети, я тебе подскажу. Ищи к западу отсюда, у Забытого берега, близ Долины Свирепого Утеса.", completion = "О, отлично! Надо тебе сказать, что эти шкуры после специальной обработки делаются прочнее железа! Правда, подобрать состав для дубления не так-то просто, но все равно, я уверен, что мои вещи, изготовленные из них, будут еще лучше прежнего.\n\nЧто до тебя, Томпсон, – ты воистину бесценный помощник! Пожалуйста, выбирай себе любое из моих готовых изделий.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги ручной работы ДжангораПерчатки ручной работы Джангора\n\nВы также получите:\n\n"},
[2841] = {title = "Техновойны", objective = "Добудьте в Гномрегане чертежи боевой машины и код от сейфа Термоштепселя в Гномрегане и принесите их Ноггу в Оргриммар.", description = "О-о, гномьи технологии! Еще пару лет назад они использовались в основном в анекдотах. Да уж, времена изменились! Теперь они выстроили такую машину, которая лучше, чем все наши резаки вместе взятые! Мне нужны ее чертежи, <имя>!\n\nУвы, эти бумаги хранятся в сейфе Мекжинера Термоштепселя. А хуже всего, что код от сейфа известен только самому Мекжинеру Термоштепселю!\n\nДелай что хочешь, <имя>, но добудь этот код, открой сейф и достань оттуда эти чертежи!", progress = "Не вижу чертежей! Они спрятаны у тебя под одеждой или ты вернулся с пустыми руками и только понапрасну меня раздражаешь?", completion = "Да, Блудикнайф, я знал, что у тебя все получится! А вот Совик все сомневался…\n\n*Ногг прочищает горло.*\n\nНу, теперь, когда чертежи у нас в руках, разобраться в этих гномьих нововведениях – всего лишь вопрос времени. Эти изобретения очень пригодятся нам, гоблинам, для новых моделей резаков!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОдеяния СивинадаШаровары бегунаДвойные усиленные поножи\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[2842] = {title = "Главный инженер Скути", objective = "Поговорите со Скути в Пиратской бухте.", description = "Как только Керноби сообщил нам о новой гномьей машине, мы со Скути принялись строить \"Транстелепорт-6000\" – лучший способ добраться до Гномрегана.\n\nОн уже готов, <имя>. Если хочешь его испытать, ступай в Пиратскую бухту и поговори со Скути у Гнезда Крыльев Ветра. Из Кабестана туда можно добраться на лодке.\n\nНет, разумеется, ты можешь попробовать добраться до Гномрегана через горы Дун Морог, кишащие дворфами!", progress = nil, completion = "Ну, разве она не красавица? Вершина гоблинских транспортных технологий! И десяти раз не взрывалась!\n\nТы не бойся, Блудикнайф. Больше она не взорвется, я там все отладил. Ну, а если тебе не повезет, ты хотя бы умрешь быстро и безболезненно!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2843] = {title = "Поехалиии!", objective = "Дождитесь, пока Скути настроит гоблинский импульсный повторитель.", description = "Пока импульсный повторитель у тебя с собой, стоит только ступить на площадку, и перенесешься в Гномреган.\n\nМожет быть, ощущения будут необычные, но ни одно из них не останется навсегда... Теперь.\n\nЧуть не забыл самое главное – как вернуться назад. Когда ты решишь уносить ноги, поднимись на площадку транстелепорта в Гномрегане!\n\nА теперь я настрою импульсный повторитель на твой рост и вес.", progress = nil, completion = "Готово! Когда соберешься с духом, просто ступи на площадку.", rewards = "Вы получите:\n\nГоблинский импульсный повторитель"},
[2844] = {title = "Великан-опекун", objective = "Найдите потерявшуюся ночную эльфийку.", description = "Нет от меня никакого толку, <имя>! Я должен был стеречь мою маленькую подружку, Шай, а она взяла и убежала! Я даже не знаю, как это вышло: в последний раз, как я ее видел, мы шли через развалины к северу отсюда.\n\nВсе было хорошо, а потом я поворачиваюсь, а ее нет!\n\nИ теперь я даже и не знаю, чего мне делать-то. Что мне делать, <имя>? Я так переживаю!\n\nСлушай, а может, ты сходишь ее поищешь? У тебя-то ноги куда резвее моих!", progress = nil, completion = "Ой, как хорошо, что ты меня нашел! По правде говоря, я немножко заблудилась... Но тут очень красиво, правда?", rewards = "Вы получите:\n\n"},
[2845] = {title = "Шай-бродяжница", objective = "Достаньте из сундучка колокольчик Шай.\n\nПроводите Шай Листогон в лагерь Камнедробителя.", description = "Не поможешь ли ты мне отыскать моего друга, Камнедробителя? Он должен был следить за мной... Но со мной иногда случается, что я ухожу, куда глаза глядят. Вокруг столько интересного, я увлекаюсь, забываю обо всем на свете, и…\n\nНо есть одна вещь, которая обязательно привлекает мое внимание.\n\nВ этом сундучке хранится колокольчик. Он мне очень дорог. Мне ужасно нравится его звон. Так что, если я вдруг куда-нибудь уйду, позвони в колокольчик, и я тотчас прибегу обратно!", progress = "Ох, я так из-за тебя переволновался! Спасибо большое, Ишт, что привел Шай домой!", completion = "Шо? Так говоришь, этот колокольчик помогает найти Шай, когда она убежала? Вот это да!\n\nНу, Ишт, раз я стольким тебе обязан, на, держи!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГранитные захватыКушак виноградной изгороди\n\nВы также получите:\n\n"},
[2846] = {title = "Тиара глубин", objective = "Принесите Тиару Глубин Табете в Пыльную Трясину.", description = "Давным-давно у меня была, прекрасная драгоценность, Тиара Глубин. Это была не просто красивая безделушка, она была наделена великой силой, предназначенной для тех, кто умел с ней обращаться.\n\nКогда слух о моей тиаре достиг ушей гидроманта Велраты, она решила заполучить ее и послала своих подручных выкрасть ее у меня!\n\nЯ хочу вернуть то, что принадлежит мне. Отправляйтесь в Зул'Фаррак, город троллей в пустыне Танарис, найдите там Велрату и заберите у нее мою тиару. Возвращайтесь ко мне и заслужите мою вечную благодарность.", progress = "Ты принес тиару, Эфром? Велрата поняла, что значит переходить мне дорогу?", completion = "Чудно! Ты нашел ее! И, что ее важнее, Велрата ее лишилась! Благодарю тебя, Эфром. И... Если я прежде высказывалась несколько резко, не бери в голову. К тем, кто не пытается меня обокрасть, я отношусь гораздо дружелюбнее.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЖезл Смены заклятийНаплечье Драгоценной скорлупы"},
[2847] = {title = "Дикарские кожаные доспехи", objective = "Принесите 10 кусков плотной кожи Пратту Макгруббену в Крепость Оперенной Луны.", description = "<имя>, ты уже <опытный кожевник/опытная кожевница>. Я владею искусством изготовления того, что весьма пригодилось бы и тебе. Это дикарские кожаные доспехи. В них используются загадочная и непостоянная сила дикого винограда, который можно отыскать в густых зарослях или получить от некоторых существ. Другого подобного доспеха мастер твоего уровня изготовить не в силах.\n\nЯ научу тебя делать эти доспехи, но для этого тебе придется потрудиться. Для начала мне нужно просто десять кусков плотной кожи. Принеси ее, потом обсудим дальнейшее.", progress = "Как я уже говорил, пока ты овладеваешь искусством изготовления дикарских кожаных доспехов, ты будешь работать на меня. Дикий виноград – растение мощное, но непостоянное, и потому оно придает изготовленной тобой прочной броне дополнительную прочность, которая, однако, проявляется лишь время от времени. Однако все эти знания дались мне не даром!\n\nПервоначальная плата за обучение составляет десять кусков плотной кожи.\n\nНу, а когда ты их добудешь, мы поговорим о работе, которую тебе следует выполнить.", completion = "Ну что ж, Медведик, я рад, что ты теперь у меня в подмастерьях. Ты поступил разумно, избрав ремесло кожевника: когда ты научишься изготовлять дикарские кожаные доспехи, у тебя отбою не будет от тех, кто одевается в кожу.\n\nНу, за работу! С чего мы начнем?", rewards = "Вы получите:\n\n"},
[2848] = {title = "Дикарские кожаные наплечники", objective = "Принесите 6 наборов для усиления брони из толстой кожи и дикий виноград Пратту Макгруббену в Крепость Оперенной Луны.", description = "Дикарские кожаные наплечники обеспечивают превосходную защиту как плеч, так и верхней части руки. Как и все дикарские кожаные доспехи, они прошиты диким виноградом, что придает им мощные, но непостоянные магические свойства.\n\nДля изготовления изделия по этой выкройке мне потребуется шесть наборов для усиления брони из толстой кожи и дикий виноград. Для тебя это не слишком сложное задание...", progress = "Ну что, принес ли ты шесть наборов для усиления брони их толстой кожи и дикий виноград, как я просил?\n\nИзготовление брони из толстой кожи – дело непростое и трудоемкое, но это помогает набить руку перед тем, как взяться за более сложные вещи, например, дикарские кожаные доспехи.\n\nТак что если я заставляю тебя всем этим заниматься, то не просто так...", completion = "Да, Маркуру, это хорошие, надежные наборы для усиления брони. Если я чего требую не только от себя, но и от своих подмастерьев, так это высокого качества!\n\nТы неплохо потрудился, и заслуживаешь того, чтобы получить эту выкройку. Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне.", rewards = "Вы получите:\n\nВыкройка: дикарские кожаные наплечники"},
[2849] = {title = "Дикарский кожаный жилет", objective = "Принесите 2 черепашьих чешуйчатых кирасы, 2 пары черепашьих чешуйчатых перчаток и дикий виноград Пратту Макгруббену в Крепость Оперенной Луны.", description = "Дикарский кожаный жилет – основа любых дикарских кожаных доспехов. Основа жилета переплетена диким виноградом, что дает максимальную защиту торса и позволяет использовать мощную магию растения.\n\nДля изготовления изделия по этой выкройке мне потребуется две черепашьих чешуйчатых кирасы, две пары черепашьих чешуйчатых перчаток и дикий виноград. Изготовить это непросто, но, думаю, ты справишься.", progress = "Ну что, где те черепашьи чешуйчатые кирасы и перчатки, что я велел принести? И не забудь про дикий виноград!\n\nЕще работая с простейшими выкройками, мы понимаем, что сложное и простое строится по одним и тем же принципам. Таким образом, изготовление черепашьих чешуйчатых кирас подготавливает тебя к созданию дикарского кожаного жилета.\n\nЧто до перчаток... ну, перчатки пригодятся мне самому! Не забывай, ты работаешь на меня!", completion = "Да, Маркуру, неплохие вещицы! За одно умение и старание, вложенное в них, можно получить несколько лишних серебряных монет.\n\nНу что, мой приказ выполнен, вот и твоя награда. Теперь ты умеешь изготовлять дикарские кожаные жилеты!", rewards = "Вы получите:\n\nВыкройка: дикарский кожаный жилет"},
[2850] = {title = "Дикарский кожаный шлем", objective = "Принесите 2 ночных мундира, 2 ночных головных повязки и дикий виноград Пратту Макгруббену в Крепость Оперенной Луны.", description = "Дикарский кожаный шлем обеспечивает лучшую защиту головы, при этом не менее удобен, чем обычные шлемы. Как и во всех дикарских кожаных доспехах, в основу шлема вплетен дикий виноград, наделяющий его мощными, но непостоянными магическими свойствами. Тем, кто ходит в кожаных доспехах, эта вещица наверняка пригодится!\n\nНо для изготовления изделия по этой выкройке мне понадобятся 2 ночных мундира, 2 ночных головных повязки и дикий виноград. Принеси это все, и выкройка твоя!", progress = "Мне нужны эти мундиры и головные повязки, а также дикий виноград, прежде чем я поделюсь с тобой секретом дикарского кожаного шлема!\n\nЛюбому искателю приключений необходима защита для головы, будь это простейшая головная повязка или глухой шлем. Ну и, разумеется, принцип изготовления шлемов всегда один и тот же, какими бы финтифлюшками ты его ни украшал.", completion = "Да, это Ночное снаряжение – именно то, что я просил тебя принести, Маркуру. Впрочем, от кожевника твоего уровня я другого и не ждал.\n\nТы достоин уметь изготовлять дикарские кожаные шлемы. Вот тебе выкройка. Надеюсь, ты применишь ее с пользой.", rewards = "Вы получите:\n\nВыкройка: дикарский кожаный шлем"},
[2851] = {title = "Дикарские кожаные сапоги", objective = "Принесите 2 пары ночных штанов, 2 пары ночных сапог и 2 экземпляра дикого винограда Пратту Макгруббену в Крепость Оперенной Луны.", description = "Тебе известно уже немало, <имя>. Однако многое еще остается постичь. Теперь ты узнаешь о дикарских кожаных сапогах – ведь без обуви не обходится ни один доспех.\n\nНоге в них удобно и приятно, и дальний путь в них не так тяжел. Мягкая же подошва позволяет при необходимости ступать беззвучно.\n\nДля их изготовления по выкройке мне потребуются две пары ночных штанов и две пары ночных сапог. И два экземпляра дикого винограда – запомни, два, а не один! Добудешь все это – дай мне знать.", progress = "Прежде чем ты получишь выкройку, Медведик, тебе следует выполнить мой заказ! Что, у тебя все готово?\n\nС самой первой модели сапог, которую мы изучаем, мы постигаем общий принцип изготовления сапог. При изготовлении качественной обуви должен соблюдаться тонкий баланс между удобством и функциональностью. В хорошей обуви ее хозяин, не уставая, пройдет расстояние вдвое большее, чем то, от которого владелец дешевой обувки свалится с ног.", completion = "И снова ты выполняешь непростой заказ с искусством опытного профессионала! Ты заслужил эту выкройку, равно как и мою благодарность.", rewards = "Вы получите:\n\nВыкройка: дикарские кожаные сапоги"},
[2852] = {title = "Дикарские кожаные поножи", objective = "Принесите два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей и два экземпляра дикого винограда Пратту Макгруббену в Крепость Оперенной Луны.", description = "Ну, <имя>, теперь, когда с простыми предметами покончено, мы можем перейти к более сложным вещам. Дикарские кожаные поножи – одна из наиболее прочных и надежных разновидностей кожаного доспеха. Они отлично защищают и живот, и ноги, и прочие важные части тела. А поскольку в них вшит еще и дикий виноград, дающий дополнительную защиту, любой искатель приключений скажет тебе спасибо за такие поножи.\n\nДля изготовления изделия по этой выкройке мне понадобятся два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей, и два экземпляра дикого винограда.", progress = "Ну что, готовы ли черепашьи чешуйчатые наручи и шлемы? И не забудь, теперь мне нужно два экземпляра дикого винограда!\n\nТеперь ты начинаешь осознавать, какое могущество заложено в дикарских кожаных доспехах. Умение изготовлять такие универсальные доспехи для кожевника почти что бесценно! Единственное ограничение – это наличие нужных ресурсов. А качество готового доспеха границ не имеет!", completion = "Ну что, мой приказ снова выполнен отлично. Может, в один прекрасный день уже я явлюсь к тебе, как ученик к учителю, а, Медведик?\n\nВот выкройка поножей, а с ней и моя благодарность. Пусти полученные знания в дело, и пусть твои изделия будут достойны твоих способностей!", rewards = "Вы получите:\n\nВыкройка: дикарские кожаные поножи"},
[2853] = {title = "Мастер школы Дикаря", objective = "Отдайте письмо Пратта Телонису, главному кожевнику Дарнасса.", description = "Что ж, <имя>, ты – образец прилежания. Остался только один предмет из дикарских кожаных доспехов, который ты не умеешь изготовлять. Я не стану заставлять тебя трудиться, чтобы ее получить: ты и так сполна <расплатился/расплатилась> за все. Однако же сам я тебе его дать не могу. Ты получишь награду от моего наставника, того, кто посвятил в тайны нашего ремесла меня самого. \n\nОтнеси эту записку Телонису. Он обучает кожевников в Дарнассе. Покажи ему записку, и пусть он приветствует тебя как <равного/равную>, подобно мне самому.", progress = "Приветствую, |3-6(ночной эльф)... Судя по твоему внешнему виду, ты – кожевник, как и я. Ты пришел, чтобы учиться, или у тебя ко мне другое дело?", completion = "А, ты от Пратта! Он, конечно, человек, но временами напоминает мне нас, ночных эльфов. Он действительно гениальный кожевенник! И если он тебя так расхваливает, это говорит в твою пользу.\n\nНасколько я понимаю, он обучил тебя секретам дикарских кожаных доспехов? Позволь же, я завершу твое обучение, дав тебе вот эту выкройку. Пользуйся ею с умом: немного на свете тех, кто владеет тайной изготовления дикарских кожаных плащей!", rewards = "Вы получите:\n\nВыкройка: дикарский кожаный плащ"},
[2854] = {title = "Дикарские кожаные доспехи", objective = "Принесите 10 кусков плотной кожи Джангору Быстрому Страннику в Лагерь Мохаче.", description = "<имя>, ты уже <опытный кожевник/опытная кожевница>. Я владею искусством изготовления того, что весьма пригодилось бы и тебе. Это дикарские кожаные доспехи. В них используется загадочная и непостоянная сила дикого винограда, который можно отыскать в густых зарослях или получить от некоторых существ. Другого подобного доспеха мастер твоего уровня изготовить не в силах.\n\nЯ научу тебя делать эти доспехи, но для этого тебе придется потрудиться. Для начала мне нужно просто десять кусков плотной кожи. Принеси ее, потом обсудим дальнейшее.", progress = "Чтобы не было недоразумений: пока ты овладеваешь искусством изготовления дикарских кожаных доспехов, ты считаешься моим учеником. Дикий виноград – растение мощное, но непостоянное, и потому оно придает изготовленной тобой прочной броне дополнительную прочность, которая, однако, проявляется время от времени. Однако все эти знания дались мне не даром!\n\nПервоначальная плата за обучение составляет десять кусков плотной кожи.\n\nНу, а когда ты их добудешь, мы поговорим о работе, которую тебе следует выполнить.", completion = "Ну что ж, Шкек, я рад, что ты теперь мой ученик. Ты поступил разумно, избрав ремесло кожевника: когда ты научишься изготовлять дикарские кожаные доспехи, у тебя отбою не будет от тех, кто одевается в кожу.\n\nНу, за работу! С чего мы начнем?", rewards = "Вы получите:\n\n"},
[2855] = {title = "Дикарские кожаные наплечники", objective = "Принесите 6 наборов для усиления брони из толстой кожи и дикий виноград Джангору Быстрому Страннику в Лагерь Мохаче.", description = "Дикарские кожаные наплечники обеспечивают превосходную защиту как плеч, так и верхней части руки. Как и все дикарские кожаные доспехи, они прошиты диким виноградом, что придает им мощные, но непостоянные магические свойства.\n\nДля изготовления изделия по этой выкройке мне потребуется шесть наборов для усиления брони из толстой кожи и дикий виноград. Для тебя это не слишком сложное задание...", progress = "Ну что, принес ли ты шесть наборов для усиления брони из толстой кожи и дикий виноград, как я просил?\n\nИзготовление комплектов для усиления брони – дело непростое и трудоемкое, но это помогает набить руку перед тем, как взяться за более сложные вещи, например, дикарские кожаные доспехи.\n\nКаждый урок имеет свою цель, Шкек. И к любому заданию следует относиться ответственно.", completion = "Да, Шкек, это хорошие, надежные доспехи. Если я чего требую не только от себя, но и от своих учеников, так это высокого качества!\n\nТы неплохо потрудился, и заслуживаешь того, чтобы получить эту выкройку. Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне.", rewards = "Вы получите:\n\nВыкройка: дикарские кожаные наплечники"},
[2856] = {title = "Дикарский кожаный жилет", objective = "Принесите 2 черепашьих чешуйчатых кирасы, 2 пары черепашьих чешуйчатых перчаток и дикий виноград Джангору Быстрому Страннику в Лагерь Мохаче.", description = "Дикарский кожаный жилет – основа любых дикарских кожаных доспехов. Основа жилета переплетена диким виноградом, что дает максимальную защиту торса и позволяет использовать мощную магию растения.\n\nДля изготовления предмета по этой выкройке мне потребуется две черепашьих чешуйчатых кирасы, две пары черепашьих чешуйчатых перчаток и дикий виноград. Изготовить это непросто, но, думаю, ты справишься.", progress = "Ну что, где те черепашьи чешуйчатые кирасы и перчатки, что я велел принести? И не забудь про дикий виноград!\n\nЕще работая с простейшими выкройками, мы понимаем, что сложное и простое строится по одним и тем же принципам. Таким образом, изготовление черепашьих чешуйчатых кирас подготавливает тебя к созданию дикарского кожаного жилета.\n\nЧем дальше ты продвигаешься, тем больше твое ремесло становится сродни искусству!", completion = "Да, Бубен, неплохие вещицы! Судя по умению и старанию, с какими они изготовлены, ты всерьез относишься к своему ремеслу.\n\nНу что, мой приказ выполнен, вот и твоя награда. Теперь ты умеешь изготовлять дикарские кожаные жилеты!", rewards = "Вы получите:\n\nВыкройка: дикарский кожаный жилет"},
[2857] = {title = "Дикарский кожаный шлем", objective = "Принести 2 ночных мундира, 2 ночных головных повязки и дикий виноград Джангору Быстрому Страннику в Лагере Мохаче.", description = "Дикарский кожаный шлем обеспечивает лучшую защиту головы, при этом не менее удобен, чем обычные шлемы. Как и во всех дикарских кожаных доспехах, в основу шлема вплетен дикий виноград, наделяющий его мощными, но непостоянными магическими свойствами. Тем, кто ходит в кожаных доспехах, эта вещица наверняка пригодится!\n\nНо для изготовления изделия по этой выкройке мне понадобятся 2 ночных мундира, 2 ночных головных повязки и дикий виноград. Принеси это все, и выкройка твоя!", progress = "Мне нужны эти мундиры и головные повязки, а также дикий виноград, прежде чем я поделюсь с тобой секретом буйного кожаного шлема!\n\nЛюбому искателю приключений необходима защита для головы, будь это простейшая головная повязка или глухой шлем. Ну и, разумеется, принцип изготовления шлемов всегда один и тот же, какими бы финтифлюшками ты его ни украшал.", completion = "Да, это Ночное снаряжение – именно то, что я просил тебя принести, Шкек. Впрочем, от кожевника твоего уровня я другого и не ждал.\n\nТы достоин того, чтобы изготовлять дикарские кожаные шлемы. Вот тебе выкройка. Надеюсь, ты применишь ее с пользой.", rewards = "Вы получите:\n\nВыкройка: дикарский кожаный шлем"},
[2858] = {title = "Дикарские кожаные сапоги", objective = "Принесите 2 пары ночных штанов, 2 пары ночных сапог и 2 экземпляра дикого винограда Джангору Быстрому Страннику в Лагере Мохаче.", description = "Тебе известно уже немало, <имя>. Однако многое еще остается постичь. Теперь ты узнаешь о дикарских кожаных сапогах – ведь без обуви не обходится ни один доспех.\n\nНоге в них удобно и приятно, и дальний путь в них не так тяжел. Мягкая же подошва позволяет при необходимости ступать беззвучно.\n\nДля изготовления их по выкройке мне потребуются две пары ночных штанов и две пары ночных сапог. И два экземпляра дикого винограда – запомни, два, а не один! Добудешь все это – продолжим.", progress = "Прежде чем ты получишь выкройку, Хантор, тебе следует выполнить мой заказ! Что, у тебя все готово?\n\nС самой первой модели сапог, которую мы изучаем, мы постигаем общий принцип изготовления сапог. В качественной обуви должен соблюдаться тонкий баланс между удобством и функциональностью. В хорошей обуви ее хозяин, не уставая, пройдет расстояние вдвое большее, чем то, от которого владелец дешевой обувки свалится с ног.", completion = "И снова ты выполняешь непростой заказ с искусством опытного профессионала! Ты заслужил эту выкройку, равно как и мою благодарность.", rewards = "Вы получите:\n\nВыкройка: дикарские кожаные сапоги"},
[2859] = {title = "Дикарские кожаные поножи", objective = "Принесите два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей и два экземпляра дикого винограда Джангору Быстрому Страннику в Лагерь Мохаче.", description = "Ну, <имя>, теперь мы можем перейти к более сложным вещам. Дикарские кожаные поножи – одна из наиболее прочных и надежных разновидностей кожаного доспеха. Они отлично защищают ноги. А поскольку в них вшит еще и дикий виноград, дающий дополнительную защиту, любой искатель приключений скажет тебе спасибо за такие поножи.\n\nДля изготовления изделия по этой выкройке мне понадобятся два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей, и два экземпляра дикого винограда.", progress = "Ну что, готовы ли черепашьи чешуйчатые наручи и шлемы? И не забудь, теперь мне нужно два экземпляра дикого винограда!\n\nТеперь ты начинаешь осознавать, какое могущество заложено в дикарских кожаных доспехах. Умение изготовлять такие универсальные доспехи для кожевника почти что бесценно! Единственное ограничение – это наличие нужных ресурсов. А качество готового доспеха границ не имеет!", completion = "Ну что, мой приказ снова выполнен отлично. Может, в один прекрасный день уже я явлюсь к тебе, как ученик к учителю, а, Бубен?\n\nВот выкройка поножей, а с ней и моя благодарность. Пусти полученные знания в дело, и пусть твои изделия будут достойны твоих способностей!", rewards = "Вы получите:\n\nВыкройка: дикарские кожаные поножи"},
[2860] = {title = "Мастер школы Дикаря", objective = "Отдайте письмо Джангора Уне, главному кожевнику Громового Утеса.", description = "Что ж, <имя>, теперь ты знаешь все, чему я мог тебя научить. Однако остался еще один предмет из дикарских кожаных доспехов, выкройки которого у тебя нет. Я не стану заставлять тебя трудиться, чтобы ее получить: ты и так сполна <расплатился/расплатилась> за все. Однако же отдать тебе его сам я не могу.\n\nТы получишь награду от моей наставницы, той, которая посвятила в тайны нашего ремесла меня самого. Отнеси эту записку Уне. Она обучает кожевников в Громовом Утесе. Покажи ей записку, и пусть она приветствует тебя как <равного/равную>, подобно мне самому.", progress = "Приветствую, |3-6(нежить)... Судя по твоему внешнему виду, ты – кожевник, как и я. Ты пришел, чтобы учиться, или у тебя ко мне другое дело?", completion = "А, ты от Джангора! Приятно видеть, что у одного из моих лучших учеников теперь свои ученики…\n\nДжангор – очень талантливый и добросовестный кожевенник. И если он тебя так расхваливает, это говорит в твою пользу.\n\nНасколько я понимаю, он обучил тебя секретам дикарских кожаных доспехов? Позволь же, я завершу твое обучение, дав тебе вот эту выкройку. Пользуйся ею с умом: немного на свете тех, кто владеет тайной изготовления дикарских кожаных плащей!", rewards = "Вы получите:\n\nВыкройка: дикарский кожаный плащ"},
[2861] = {title = "Миссия Табеты", objective = "Поговорите с Табетой в Пылевых топях.", description = "Ходят слухи, что у Табеты, мага, живущего в Пылевых топях, серьезный зуб на одну песчаную троллиху из Зул'Фаррака. Если ты поговоришь с Табетой, она, конечно, расскажет тебя больше.\n\nИ захвати с собой друзей, <имя>. Если она пошлет тебя в Зул'Фаррак, а, скорее всего, так и будет, то лучше тебе там в одиночку не появляться.\n\nТы найдешь дом Табеты к западу от Терамора и к северу от руин Каменного Молота.", progress = nil, completion = "Да. Верно. У меня большой зуб на эту троллиху. И не один.\n\nХочешь помочь мне?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2862] = {title = "Война с племенем Древолапов", objective = "Принесите 10 грив гноллов-древолапов Хадокену Быстрому Страннику в Лагере Мохаче.", description = "О, эти гноллы... Сказать, что они отравляют нам жизнь – значит ничего не сказать! Мы здесь постоянно живем под угрозой нападения! Я не знаю, всегда ли они жили в Фераласе, или пришли сюда откуда-то еще, но если мы не будем противостоять им достаточно решительно, нам здесь не жить.\n\nА в последнее время гноллы совершенно озверели! Нам необходима твоя помощь, чтобы сократить их численность. Принеси мне десяток их грив, и я щедро вознагражу тебя за труды.\n\nСтупай!", progress = "Мы отражаем их нападения, а они все лезут и лезут! Их явно что-то гонит... Или, может быть, кто-то? А, Томпсон, ты уже вернулся? Ну что, гривы при тебе?", completion = "Неплохое начало, Томпсон! Таких воинов, как ты, еще поискать!\n\nЯ ведь давал такое задание не только тебе. И до тебя немало бойцов сражались с гноллами, и в былые времена наших усилий хватало, чтобы заставить их отступить. Однако в последнее время они упорно прут на север, в наши земли. Гноллы бьются так отчаянно... как будто им некуда отступать!\n\nОднако у меня есть один план. Возможно, он позволит раз и навсегда покончить с этой войной...", rewards = "Вы получите:\n\n"},
[2863] = {title = "Истребление вожаков", objective = "Убейте в течение часа 5 вожаков стаи Древолапов и вернитесь к Хадокену Быстрому Страннику.", description = "План состоит в том, чтобы одним махом истребить всех предводителей гноллов. Если нам удастся это сделать, в рядах гноллов воцарится хаос. А возможно, до этих блохастых тварей даже дойдет, что с нами лучше не связываться!\n\nТебе, <имя>, я поручаю истребить пятерых вожаков гноллов. Только сделать это нужно в течение часа, иначе весь план пойдет насмарку!", progress = "Время на исходе, Вий! Если ты в ближайшее время не доложишь о выполнении задания, значит, ты впустую тратишь время!", completion = "Тебе удалось выполнить мою просьбу. Молодец, Томпсон! Вот, прими эту небольшую награду за свои труды.\n\nТеперь, когда число гноллов сократилось, и их вожаки перебиты, эти твари дважды подумают, прежде чем решатся снова напасть на лагерь! Однако проблемы это не решает...\n\nГноллы не могли так озвереть безо всякой причины! И я хочу выяснить, в чем дело, прежде, чем они пришли в себя.", rewards = "Вы получите:\n\n"},
[2864] = {title = "Тран'рек", objective = "Поговорите с Тран'реком в Прибамбасске.", description = "У моего кузена Тран'река сейчас большие проблемы. Он обещал мне, партию панцирей скарабея, еще неделю назад, но так и не поставил. Он – мой кузен, так что не хотел бы я посылать кого-то в Прибамбасск, выколачивать из него свои деньги или груз.\n\nМожешь поговорить с ним для меня? Скажите ему, что он должен мне эту поставку ну или придется отвечать как всем остальным... \n\nПрибамбасск находится на севере пустыни Танарис в Калимдоре.", progress = nil, completion = "Привет!\n\nТак ты общался с моим кузеном Кразеком? Ну и как он там? Надеюсь, что в Бухте контрабандистов к нему хорошо относятся…\n\nПанцири скарабея, говоришь? Дай мне рассказать тебе одну историю.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2865] = {title = "Панцири скарабеев", objective = "Принести 5 целых панцирей скарабея Тран'реку в Прибамбасск.", description = "У скарабеев Танариса очень твердый панцирь, достаточно твердый, чтобы использовать их как строительный материал много для чего. Очень много!\n\nЭти панцири, настолько полезная вещь, что ради них скарабеев извели практически под корень.\n\nЯ знаю, где они еще водятся, и я поделюсь с тобой, если ты пообещаешь принести мне их панцири, обещаешь?\n\nТак вот. Колония скарабеев находится в Зул'Фарраке. Видимо до троллей еще не дошло, насколько полезны их панцири.\n\nТак что все твои! Отправляйся в Зул'Фаррак и принеси мне целых панцирей скарабеев.", progress = "Принес? Мой кузен в Пиратской бухте очень ждет этих панцирей. А он не любит ждать!", completion = "Урра! Ты достал их!\n\nСпасибо, Эфром, ты мне просто жизнь спас!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2866] = {title = "Руины Соларсаля", objective = "Обследуйте руины Соларсаля на предмет присутствия наг.", description = "К югу от нас находятся руины Соларсаля. Это развалины очень древнего города. Мы уже обследовали руины, но пока не нашли там ничего примечательного и оставили их в покое.\n\nОднако не так давно в этих развалинах поселились наги из клана Гребня Ненависти, причем в угрожающих количествах. Поначалу мы решили, что они готовят нападение. Возможно, они его действительно готовят, но нам кажется, что там происходит что-то еще.\n\nСтупай туда, осмотри развалины и обрати внимание на все, что покажется подозрительным. Удачи, <имя>!", progress = nil, completion = "Внимательно изучив беседку, вы обнаруживаете следующее. \n\nВо-первых, беседка явно новая, и не похожа на окружающие руины. Во-вторых, столбы беседки исписаны мелкими значками. Значки повторяются, но что это за письмена и что они означают, вам непонятно. Ну и, в-третьих, камень беседки – теплый на ощупь.\n\nДа, все это, несомненно, подозрительно!", rewards = "Вы получите:\n\n"},
[2867] = {title = "Возвращение в Крепость Оперенной Луны", objective = "Вернитесь в Крепость Оперенной Луны к Шандрисе Оперенной Луне и доложите о находке.", description = "Теперь, когда вы обнаружили странную беседку в глубине руин Соларсаля, настало время вернуться в Крепость Оперенной Луны и доложить генералу Шандрисе Оперенной Луне о своем открытии.", progress = nil, completion = "С возвращением, Эфром! Обнаруженная тобой беседка действительно весьма... подозрительна. Очевидно, что даже если наги и не замышляют нападения, их присутствие не сулит нам ничего хорошего. Ну, как бы то ни было, вот твоя заслуженная награда.\n\nСудя по всему, Крепость Оперенной Луны отчаянно нуждается в помощи для борьбы с нагами из клана Гребня Ненависти. Я бы хотела дать тебе еще одно поручение, если ты не против...", rewards = "Вы получите:\n\n"},
[2869] = {title = "Борьба с Гребнем Ненависти", objective = "Принесите 10 штук чешуи наг из клана Гребня Ненависти Латроникусу Лунному Копью в Крепость Оперенной Луны.", description = "На данный момент самое разумное – рассчитывать на то, что наги в любом случае попытаются захватить остров. И нам нужно предотвратить эту угрозу, пока не стало поздно.\n\nПринеси мне десять штук чешуи Гребня Ненависти. Как их добыть – думаю, ясно? У тебя будет случай поохотиться на наг, и количество их воинов на острове Сардор уменьшится. И то, и другое нам на пользу!", progress = "Если ты здесь затем, чтобы отчитаться о выполнении задания, Эфром, то отлично: где мои десять штук чешуи? А если ты просто так, поболтать, то мне сейчас не до этого.\n\nЗнай, мы, ночные эльфы – народ мирный! Мы стремимся лишь к поддержанию мира и гармонии. Однако это не значит, что мы не готовы защищать свои интересы. Это мой долг перед генералом Лунное Перо, и перед всей крепостью!", completion = "Да-да, эта чешуя вполне годится. Думаю, мы отправим ее Пратту. Может быть, он сумеет изготовить из нее что-нибудь полезное.\n\nА для тебя у меня есть еще одно задание. Но сначала вот твоя награда за труды. Твоя служба генералу и всей Крепости Оперенной Луны очень ценна перед лицом грозящей нам опасности.", rewards = "Вы получите:\n\n"},
[2870] = {title = "Борьба с лордом Шалзару", objective = "Убейте лорда Шалзару и принесите обнаруженную им таинственную реликвию Латроникусу Лунному Копью в Крепость Оперенной Луны.", description = "<имя>, мы получили новые донесения разведчиков, и теперь неплохо представляем себе, как устроено войско наг. Высшее командование состоит из особ королевской крови. Именно они-то всем и заправляют.\n\nНам стало известно имя одного из самых жестоких нагов, лорда Шалзару. Разведка докладывает, что во время недавних раскопок, которые наги проводили в пещере к югу от основных руин на острове Ужаса, он лично обнаружил некую загадочную реликвию.\n\nЕго необходимо остановить. Убей его, и принеси мне этот предмет, чтобы мы могли его изучить.", progress = "Смерть лорда Шалзару заставит их отложить выполнение своих планов на несколько недель, если не на несколько месяцев. Кроме того, обнаруженная им реликвия весьма любопытна…\n\nНу что, Эфром, удалось тебе выполнить задание?", completion = "Отлично, Эфром! Гибель лорда Шалзару повергнет наг в смятение – надолго, если не навсегда. Так что теперь они представляют значительно меньшую угрозу, чем прежде, и все это – благодаря тебе!\n\nВот тебе новая награда из сокровищницы замка. Эта награда заслужена тобой – вся, вплоть до последней монеты! Добро пожаловать в Крепость Оперенной Луны в любое время, друг мой.\n\nДа, Эфром, и прежде, чем ты уйдешь... еще одна просьба...", rewards = "Вы получите:\n\n"},
[2871] = {title = "Доставка реликвии", objective = "Доставьте таинственную реликвию Вестии Лунное Копье в Крепость Оперенной Луны.", description = "Не возьмешься ли ты доставить эту реликвию моей жене Вестии? Я был бы тебе очень признателен. Она не только почтенная жрица, но и одна из наиболее сведущих ученых. Я лично не пойму, что это за штука, хоть меня озолоти. Но уж если моя жена в ней не разберется, значит, не разберется никто.\n\nОна вон там, неподалеку. Занимается, небось. Спасибо, <имя>!", progress = "Да, чем могу помочь? Постой-постой, это ты – тот самый |3-6(Жрец), который помогает генералу Лунное Перо и моему Латро разобраться с нагами? Я – Вестия, жена Латро... то есть Латроникуса. Очень рада познакомиться!\n\nНо прошу прощения – ведь ты, конечно, здесь по делу? Ты мне что-то принес?", completion = "Интересно... Так говоришь, это вещь из руин Соларсаля? Ну да, Латро прав: мне следовало на это взглянуть... Такое впечатление, что эта вещь – не оттуда. С другой стороны, на работу наг это тоже не похоже. Далеко не столь чуждое…\n\nМне потребуется некоторое время на то, чтобы с ней разобраться. А когда я завершу свои исследования, возможно, ты мне снова пригодишься – если ты, конечно, окажешься в это время поблизости.\n\nНа, возьми это – у нас таких вещиц много, а тебе она, думаю, пригодится!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНагрудник Рассветного всадникаШлем часового\n\nВы также получите:\n\n"},
[2872] = {title = "Долг Столи", objective = "Поговорите со Столи из Порта Картеля.", description = "Мой давний приятель Столи должен мне особую бутылку рома. Он держит бар в Порту Картеля в Танарисе, и клялся, что ром у него крепче, чем во всей Пиратской бухте. Он даже заявил, что удвоит свой долг мне, если я попробую его напиток и не соглашусь с ним!\n\nДумаю, он потом пожалел о своих словах, потому и не шлет мне ром. Но я ничего не забываю, поэтому поговори с ним вместо меня...", progress = nil, completion = "А, ты уже поговорил с МакКинли!\n\nОн ошибается! Я вовсе не боюсь угостить его Картельским ромом…\n\nПросто рома у меня нет!", rewards = "Вы получите:\n\n"},
[2873] = {title = "Посылка Столи", objective = "Отыщите партию товара Столи и возвратите ее хозяину в Порт Картеля.", description = "Я должен старине МакКинли из Пиратской бухты немного рома. Проблема в том, что ром у меня закончился! Капитан Куэрго украл последнюю партию и прячет в стенах огороженного пиратского поселения на юге.\n\nЕсли ты отыщешь мою партию рома, я смогу доказать МакКинли, что калимдорская выпивка в сто раз лучше пойла из Пиратской бухты!", progress = "Ну что, Эфром? Удалось тебе отыскать партию рома?", completion = "Здорово, спасибо за помощь! Теперь я наконец-то выиграю пари у МакКинли.", rewards = "Вы получите:\n\n"},
[2874] = {title = "Ром для Маккинли", objective = "Отнесите бутылку Столи \"Морскому волку\" МакКинли в Пиратскую бухту.", description = "Еще раз спасибо за помощь, <имя>. Вот тебе бутылка Картельского рома. Отнеси ее МакКинли, пора развеять его заблуждения относительно рома из Пиратской бухты.", progress = "Ну что, Столи раскошелился?", completion = "Попробуем…\n\nПрямо не верится! Ужасный напиток! Потрясающий!\n\nПожалуй, придется простить Столи долг. Он не обманул меня насчет Картельского рома. Эта штука густая как соус и жжет как лава!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКушак ЩитоломаПинательные сапоги\n\nВы также получите:\n\n"},
[2875] = {title = "РАЗЫСКИВАЕТСЯ: Андре Огнебородый", objective = "Принесите голову Андре Огнебородого начальнику отдела безопасности Чепухастеру в Порт Картеля.", description = "Злобный пират Андре Огнебородый разыскивается за преступления против Картеля Хитрая Шестеренка и Прибамбасска.\n\nСогласно указу правящего совета, все лица, прочитавшие данный документ, уполномочены применять любые меры при задержании Андре и его пособников.\n\nСогласно следующему указу, если Андре скончается или по иным причинам не сможет предстать перед судом, его может представлять его голова. Предоставление упомянутой головы начальнику отдела безопасности Чепухастеру повлечет за собой заключение весьма выгодного и ответственного контракта.", progress = "Вид у тебя ошеломленный. Ты что, наши юридические документы почитал?", completion = "А, голова Андре. Значит, суд над ним все-таки состоялся!\n\nБольшое спасибо, Эфром. А теперь распишись тут, и я займусь оплатой твоих услуг.\n\nИ не беспокойся из-за надписи мелким шрифтом. Ничего страшного там нет, и... Не думаю, что найдется такое маленькое увеличительное стекло, все равно ее не прочитаешь.", rewards = "Вы получите:\n\n"},
[2876] = {title = "Расписание кораблей", objective = "Сообщите о корабельном расписании руководству Порта Картеля.", description = "В свитке приводится список рейсов между Портом Картеля и Пиратской бухтой. Там перечислены все прошлые и будущие грузы с указанием названий кораблей, везущих их. Напротив некоторых стоит большой крестик, напротив других заметки \"ОТЛИЧНАЯ ДОБЫЧА\" и \"СИЛЬНАЯ ОХРАНА\".\n\nКое-кто из Порта Картеля очень заинтересуется этим документом.", progress = "Я смотрю, ты тяжело дышишь! У тебя какие-то новости?", completion = "Ох, похоже это список рейсов, причем здесь указаны дни и часы отбытия и прибытия! Если эти сведения попали в руки капитана пиратского корабля, у нас будут большие неприятности!\n\nТы их у пирата нашел? Дурные вести…\n\nСпасибо, Эфром. Я рад, что ты нашел этот документ и отправил пирата кормить рыб!", rewards = "Вы получите:\n\n"},
[2877] = {title = "Зачистка Осклизлой скалы", objective = "Убейте 10 зеленых слякочей и 10 нефритовых слизнюков, после чего доложитесь Фраггару Громовой Мантии на Заоблачном Пике.", description = "Мы, клан Громового Молота, помним прошлое куда лучше, чем наши собраться из Стальгорна. Если вы хотите, чтобы к вам тут хорошо относились, то не должны бояться грязной работы!\n\nОрда забросила одну из своих баз во Внутренних землях, она находится на Осклизлой скале. Сейчас эту базу заполонили слизнюки и пиявки, у нас были на нее планы, но пока там кишат эти твари, мы не можем занять эту позицию.\n\nВот вам, собственно, и работка! Отправляйтесь туда и убейте по 10 зеленых слякочей и нефритовых слизнюков, а потом доложите мне, как все прошло. Бегом!", progress = nil, completion = "Нет, подумать только, как вы здорово помогли Громовому Молоту! Вы отлично работаете, а мы это ценим.\n\nВаша маленькая зачистка куда важнее, чем может показаться на первый взгляд. Осталось еще истребить слизнюков и пиявок, и тогда мы сможем распространить свое влияние еще дальше. Новые друзья на Заоблочном Пике – это, конечно, хорошо, но, как говорится, не дружбой единой, так что вот вам еще кое-что, вдобавок.", rewards = "Вы получите:\n\n"},
[2878] = {title = "Оскверненный песнецвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете песнецвет некоторым количетсвом кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[2879] = {title = "Посох равноденствия", objective = "Зарядите посох Трояса и отыщите Монолит Равноденствия.", description = "Это, должно быть, посох Равноденствия! Этот посох, на самом деле, является ключом, которым некогда отмыкали Монолит Равноденствия в Руинах Яростного Ветра, на материке к западу от Сонных Ветвей.\n\nОтыщите четыре огня, которые все еще пылают среди руин: Самха, Имбел, Бильтан и Лахасса. Добудьте их суть, встаньте перед Монолитом и зарядите посох их силой. Если это действительно посох Равноденствия, вы сумеете отпереть Монолит и достать из него священный артефакт.", progress = "Монолит Равноденствия безмолвно высится среди руин. Что же может быть внутри него?", completion = "Заряженный посох буквально вырывается из рук. Невероятная мощь отдается дрожью во всем теле.\n\nВы касаетесь холодной поверхности Монолита…\n\nОтворяется небольшая дверка, за ней виднеется артефакт.\n\nВсе пространство вокруг Монолита Равноденствия озаряется светом.", rewards = "Вы получите:\n\nИскрящийся камень"},
[2880] = {title = "Ожерелья троллей", objective = "Принесите 5 тролльих ожерелий Фраггару Громовой Мантии на Заоблачный пик.", description = "Я скажу прямо, <имя> – мы НЕ принадлежим к Альянсу! Клан Громового Молота – это независимая организация, и мы относимся хорошо только к тем, кто заслужил это своими делами, а не пустой высокопарной болтовней!\n\nЕсли вы хотите, чтобы вас тут уважали, – докажите, что вы достойны! В холмах Внутренних земель поселились мерзкие тролли, которые иногда носят племенные ожерелья. Принесите мне пять таких ожерелий, и тогда я, возможно, поверю, что с вами можно иметь дело.", progress = "Мне нужно пять ожерелий, которые носят эти тролли. Если непонятно, то поясню, что проще всего снять ожерелье с мертвого тролля.\n\nДокажите, что вы друг Громового Молота.", completion = "Вот, о чем я и говорил! Эти ожерелья доказывают, что вы не боитесь черной работы, а клан Громового Молота это ценит.\n\nПродолжайте в том же духе, и заслужите наше уважение.", rewards = "Вы получите:\n\n"},
[2881] = {title = "Ожерелья троллей", objective = "Вы уже выполнили мое задание, но если вы захотите принести мне еще тролльих ожерелий, то я с радостью приму их. Это поможет вам заслужить хорошее отношение Громового Молота – если вы нам помогаете, то и мы с радостью поможем вам!\n\nПриносите по пять ожерелий, Медведик.", description = nil, progress = "Вы уже выполнили мое задание, но если вы захотите принести мне еще тролльих ожерелий, то я с радостью приму их. Это поможет вам заслужить хорошее отношение Громового Молота – если вы нам помогаете, то и мы с радостью поможем вам!\n\nПриносите по пять ожерелий, Медведик.", completion = "Чем больше ожерелий, тем меньше троллей во Внутренних Землях! Вы молодец, Медведик. Так держать!", rewards = nil},
[2882] = {title = "Золото Куэрго", objective = "Найдите золото Куэрго!", description = "На карте изображена южная часть берега, а ниже имеется элегантная подпись…\n\n\nЮжней Шестеренки,\nНа юге от дома\nНайдешь ты флаг, мачту и кости – знакомо?\nКопай прямо там, если смелости хватит –\nЗа все тебе злато Куэрго отплатит. \nПоищешь ты ключ и конечно найдешь,\nНо прежде немало крови прольешь.", progress = "Сундук заперт!", completion = "Вас ждут скрытые сокровища капитана Куэрго!", rewards = "Вы получите:\n\nСпрятанное сокровище Куэрго"},
[2902] = {title = "Разведка планов Древолапов", objective = "Найдите гноллские боевые планы в гноллских лагерях к югу от Лагеря Мохаче.", description = "Гноллы, конечно, умом не блещут, но в последнее время в их деятельности прослеживаются признаки тщательного планирования. Если бы удалось добыть эти планы, возможно, нам было бы проще понять, отчего они так зашевелились в последнее время.\n\nПрошу тебя, вернись в лагеря Древолапов и попытайся найти что-нибудь похожее на боевые планы. Наверняка у них есть что-то в этом духе: в последнее время они действуют чересчур согласованно. Отыщи эти планы, и возвращайся ко мне.", progress = nil, completion = "Да, это те самые планы, которые просил отыскать Хадокен Быстрый Странник. Множество стрелок, очевидно, обозначают передвижения войск, однако большая часть этих стрелок направлена не на север, к Лагерю Мохаче, а на юг.\n\nВ углу карты нарисовано нечто вроде крупного насекомого, окруженного разнообразными значками. Судя по всему, гноллов действительно донимают какие-то насекомые...", rewards = "Вы получите:\n\n"},
[2903] = {title = "Планы битвы", objective = "Отнесите планы битвы Древолапов Хадокену Быстрому Страннику в Лагерь Мохаче.", description = "Теперь, когда планы гноллов добыты, вам остается только вернуться с ними в Лагерь Мохаче к Хадокену Быстрому Страннику. Быть может, он или еще кто-нибудь сумеет разобраться, что замышляют гноллы?", progress = "С возвращением, Томпсон. Ну что, удалось тебе обнаружить какие-нибудь планы?", completion = "О, это именно то, что нам нужно! Я, правда, не мастак разбирать всякие каракули, однако я на своем веку повидал достаточно планов битв, чтобы понять, что творится у гноллов. Похоже, сейчас они ведут войну на два фронта. Один противник – это мы... но, судя по всему, основные их силы брошены на юг.\n\nТут все не так просто! Возможно, пора выяснить, с кем же они воюют.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБарьер ЗемлехватаСапоги Спешащего хребта\n\nВы также получите:\n\n"},
[2904] = {title = "Катавасия", objective = "Отведите Керноби к Часовому ходу. Затем отправляйтесь с донесением к Скути в Пиратскую бухту.", description = "<Керноби стонет> Э-э... Что случилось?\n\nПоследнее, что я помню, это как меня похитили дворфы Черного Железа, избили до полусмерти и бросили сюда, к этим омерзительным троггам.\n\nВытащи меня отсюда, <имя>!\n\nСделаем так: выведи меня к выходу; если нам удастся выбраться живыми, пойдешь в Пиратскую бухту и скажешь Скути, что я был в Кабестане и предупредил Оловеня, что дворфы Черного Железа тоже как-то связаны с работой над супер-роботом.\n\nИдем!", progress = nil, completion = "Ты достоин награды за то, что вернул Керноби целым и невредимым, Россети. Если твой дальнейший путь ведет в Гномреган, вот это поможет тебе расправиться с никчемным предателем, Мекжинером Термоштепселем.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОгнесварные наручиВолшебнокрылое оплечье\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[2922] = {title = "Промыть мозг Техботу", objective = "Принесите ядро памяти Техбота мехмастеру Замыкальцу в Стальгорн.", description = "Когда пал наш родной город Гномреган, с Техботом, видимо от расстройства, приключилось короткое замыкание. Бедный мой маленький друг! Он так помогал мне и моим коллегам! В него встроена куча полезных прибамбасов на все случаи жизни, объем памяти просто огромен, но все все это теперь совершенно бесполезно – его мозг из позитронного стал негатронным! Все заложенные в него программы теперь работают наоборот. Мой бедный сумасшедший робот теперь бродит по Гномрегану.\n\nМожет, тебе удастся изловить его и извлечь его ядро памяти. Тогда я смогу разобраться в причинах поломки и, возможно, устраню ее.", progress = "Ну как, нашел Техбота?", completion = "О, какое счастье! Спасибо, Бронгард! Я немедленно начну разбираться с поломкой! \n\nБедный мой Техбот! Потерпи, я тебя вылечу. \n\nТак, куда же я засунул свой гидропневмогайковерт...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2923] = {title = "Мехмастер Замыкалец", objective = "Поговорите с механомастером Большой Искрой.", description = "Мехмастер Замыкалец крайне опечален судьбой своего творения – Техбота. Помнится, Техбот был когда-то для гномов весьма полезным инструментом, однако теперь Большая Искра говорит, что он сломан.\n\nОчень жаль. Однако, быть может, его еще возможно починить.\n\nПоговори об этом с Мехмастером Замыкальцем в Городе Механиков в Стальгорне. Он будет рад любой помощи.", progress = nil, completion = "Да, это правда. Мой Техбот совсем вышел из строя! Ты сможешь мне помочь?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2924] = {title = "Базовый элемент", objective = "Принесите 12 базовых элементов Клацморту Гайкокруту в Стальгорн.", description = "Базовый элемент – практически универсальный механизм, широко используемый механиками и кузнецами Гномрегана. Однако в спешке покидая город, никто из нас не догадался прихватить запас этих механизмов с собой. Мне просто необходимо пополнить мои запасы!\n\nПожалуйста, отправляйся в Гномреган и добудь мне побольше таких механизмов. Думаю, их можно найти в подземельях нашего города – обычно они хранятся в контейнерах-экстраполяторах.\n\nУмоляю тебя, поторопись!", progress = "Ну как, нашел механизмы?", completion = "Прекрасно! Теперь я могу продолжить свои эксперименты! \n\nНе знаю как благодарить тебя, Бронгард! Ты спас будущее гномьей науки!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2925] = {title = "Базовые элементы Клацморта", objective = "Поговорите с Клацмортом Гайкокрутом в Стальгорне.", description = "Мой друг, гном Клацморт Гайкокрут из Стальгорна, прислал мне письмо, в котором сообщает, что ему необходима помощь. Ему нужно отправиться в Гномреган, некогда величайший город гномов, который был осквернен, и теперь его населяют лишь безумные гномы и их жуткие изобретения.\n\nЯ не могу покинуть Дарнасс, но душа моя болит за друга. Если ты сможешь помочь ему вместо меня, благодарности моей не будет предела.\n\nТы найдешь Клацморта в Городе Механиков в Стальгорне.", progress = nil, completion = "Да! Да! Мне очень нужна помощь в Гномрегане! И |3-6(Маг) вроде тебя как раз подойдет!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2926] = {title = "Новая формула", objective = "Соберите радиоактивный осадок, оставляемый облученными захватчиками и облученными погромщиками в пустой свинцовый фиал для образцов. Принесите полный фиал Оззи Триггервольту в Каранос.", description = "С самого дня нашего бегства из города Гноарном думает только о том, как выставить троггов из Гномрегана и очистить город от заражения.\n\nУ нас с Раззлом есть некоторые идеи на этот счет, однако похоже, что воплотить их в жизнь сможет только настоящий безумец. Мы еще не знаем, сработает ли наш замысел – надо все как следует проверить! Для этого нам потребуются радиоактивные осадки, оставляемые облученными троггами в Гномрегане. Это зеленая светящаяся субстанция. Наполни ею этот фиал и принеси мне!", progress = "Разве не понятно?! Мы пытаемся спасти целый народ! Нам необходимо изучить радиоактивный осадок! Ради будущего всех гномов!", completion = "Прекрасно! Теперь пришла пора опробовать нашу новую формулу. Если этот метод сработает, я не только смогу вылечить этого несчастного лепрогнома, но и вернуть свою утраченную шевелюру! Ну-ка, отойди в сторонку!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2927] = {title = "На другой день", objective = "Поговорите с Оззи Триггервольтом в Караносе.", description = "Вы ведь не думаете, что я всегда был лысым? Нет, <сударь/сударыня>! Эту трагическую утрату волос вызвала утечка радиации в Гномрегане. До тех пор я был единственным кудрявым гномом во всем Азероте.\n\n*Гноарн потрясает в воздухе кулаком.*\n\nБудь прокляты эти проклятые грязные трогги, будь они все прокляты!!!\n\nМожет, еще не поздно, <имя>. Мы еще можем исправить дело – я хочу сказать, спасти город! Поговорите с Оззи Триггервольтом в Караносе. Они со своим партнером Раззлом как раз пытаются решить эту проблему.", progress = nil, completion = "Я думал, что утрата волос нашим выдающимся главой убьет его, так нет, выжил!\n\nЯ стоял рядом с ним, когда тот схватил дозу. И эти замечательные коричневые локоны посыпались на пол прядями! Клочьями! Ужас произошедшего только усилился, когда у Гроана крыша поехала! Да! Гроан, не веря глазам своим, коснулся лысой головы, и во взгляде его загорелась месть, Эфром! И тогда он обрушился на троггов!\n\n*Оззи ежится.*", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2928] = {title = "Сооружение автогиробуророек", objective = "Принесите Шони в Штормград 24 горсти механических внутренностей роботов.", description = "Это ужасно, <имя>. У нас, видно, не хватит запчастей, чтобы собрать всю партию автогиробуророек, которую пора отправить в Дун Морог.\n\nЧто нам точно нужно – так это детали, <имя>. И для добычи этих деталей не найти места лучше, чем Гномреган! Я слышала, что роботы и механизмы, оставшиеся там, бродят по городу как овцы на вольном пастбище.\n\nЯ хочу от вас, чтобы вы отправились в Гномреган и распотрошили этих роботов на запчасти. Двух дюжин деталей должно хватить.", progress = "Если бы речь шла о гонках, вы бы уже проиграли.", completion = "Это отлично подойдёт, Бронгард. Считайте, что одна автогиробуроройка отремонтирована. Осталось еще 398.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОбезоруживающий инструмент ШониПолуперчатки Нерешительности\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[2929] = {title = "Великое предательство", objective = "Отправляйтесь в Гномреган и убейте Мекжинера Термоштепселя. Вернитесь к Главному Механику Меггакруту.", description = "Я доверял Термоштепселю, <раса>. Никогда я не думал, что он предаст меня и весь гномий род. И ради чего? Ради власти? Богатства? Все это он и так со временем получил бы. Теперь мы лишились родного дома, а этот безумец остался там править. Король пустого места...\n\nМы вернем себе Гномреган, <имя>. Мы не остановимся, пока город снова не станет нашим! Если ты хочешь присоединиться к нашей борьбе, выполни совсем простое поручение – убей предателя. Уничтожь Мекжинера Термоштепселя.", progress = nil, completion = "Я рад, что последнее, что он видел в своей жизни, была твоя стопа, попирающая его преступную голову, |3-6(человек)! Теперь, когда Термоштепсель мертв, наши планы по возвращению Гномрегана на шаг приблизились к осуществлению!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОдеяния СивинадаШаровары бегунаДвойные усиленные поножи\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[2930] = {title = "Спасение данных", objective = "Принесите призматическую перфокарту главному механику Чугунотрубзу в Стальгорн.", description = "Когда мы бежали из Гномрегана, то оставили там столько данных! Жизненно важных данных!\n\nМне нужны данные с призматической перфокарты чрезвычайно секретного терминала матричного перфографа 3005-D, что находится в глубинах Гномрегана. Вам нужно добраться до терминала, но сначала надо получить допуск... а для этого надо добраться до терминалов низшего уровня защиты – моделей -A, -B и -C. А для ЭТОГО вам понадобятся перфокарты допуска, начиная с белой... а все перфокарты остались в городе.\n\nЭто же катастрофа! Вы можете помочь нам?", progress = "Вы принесли призматическую перфокарту?", completion = "У вас получилось! Вы нашли призматическую перфокарту и восстановили утраченные данные! Жизненно, критически, безмерно важные данные, без которых мы просто не смогли бы жить!\n\nВашу услугу гномы запомнят надолго, Бронгард.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nНакидка ремонтникаТрубомолот махника"},
[2931] = {title = "Поручение Чугонотрубза", objective = "Поговорите с главным механиком Чугунотрубзом в Стальгорне.", description = "Стальгорнский главный механик Чугунотрубз ищет искателей приключений! Он собирает отряд для проникновения в Гномреган с целью возвращения данных чрезвычайной важности и секретности.\n\nХотя Чугунотрубз и не состоит в Просвещенной ассамблее чарологии, алхимии и инженерных наук, подобно мне, но он гном толковый, и если он считает это дело важным, то, по моим подсчетам, оно с вероятностью 84 процента важное!\n\nШансы хорошие!", progress = nil, completion = "Я готовлю миссию в Гномреган для возвращения важных данных. Если вы пришли помочь, то слушайте!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2932] = {title = "Предупреждение", objective = "Соберите черепа троллей из клана Сухокожих и насадите их на пику Нимбойи, после чего установите пику с тролльими черепами в центре тролльей деревни и возвращайтесь к Нимбойе в Тернистую долину.", description = "Когда-то тролли из племени Сухокожих были на стороне Орды, но потом они предали Тралла... и это не должно сойти им с рук!\n\nВот, возьмите мою пику и отправляйтесь во Внутренние земли, это далеко на севере. Сначала найдите Мельницу Таррен – поселение наших союзников, Отрекшихся, а оттуда идите на северо-восток.\n\nВо Внутренних землях убейте 20 троллей из племени Сухокожих, насадите их черепа на мою пику и воткните ее в землю в одной из их деревенек – Хири'вата или Зун'вата.\n\nПусть видят, что за свои действия надо отвечать!", progress = nil, completion = "До меня дошли вести о ваших подвигах. Это жестокий поступок, но почетный. Надеюсь, тролли Сухокожих внимут нашему предупреждению.", rewards = "Вы получите:\n\n"},
[2933] = {title = "Бутыли с ядом", objective = "Принесите бутылку яда аптекарю на Мельницу Таррен.", description = "В этих бутылках содержится очень сильный зеленый яд.\n\nСудя по количеству бутылок в деревне, тролли Сухокожих очень дорожат им. Возможно, аптекарь на Мельнице Таррен тоже заинтересуется этим ядом.", progress = "Приветствую, милый |3-6(Разбойник)! За весь этот длинный день у меня не было ни одного удачного эксперимента. Надеюсь услышать от вас хорошие новости.", completion = "О, что это? Похоже на яд... яд какого-то паукообразного, да? Где же вы его взяли?", rewards = "Вы получите:\n\n"},
[2934] = {title = "Неповрежденная ядовитая железа", objective = "Принесите неповрежденную ядовитую железу аптекарю Лидону на Мельницу Таррен.", description = "Мне нужен свежий образец того яда, что вы приносили мне. Пауки, с которых он был собран, водятся во Внутренних землях – охотьтесь на них, пока вам не удастся добыть неповрежденную ядовитую железу, а потом принесите ее мне. Больше всего пауков живет в тролльем городе Шадра'Алоре.\n\nИ не задерживайтесь, <имя> – ядовитая железа нужна мне предельно свежей.", progress = "Ну как, удалось добыть неповрежденную ядовитую железу, Томпсон? Мне не терпится начать эксперименты с этим ядом, и у меня есть для этого целый выводок маленьких миленьких животных!", completion = "О, замечательно! Яд свежий и, я уверен, чрезвычайно смертоносный! Спасибо!", rewards = "Вы получите:\n\n"},
[2935] = {title = "Разговор с мастером Гадрином", objective = "Поговорите с мастером Гадрином в деревне Сен'джин.", description = "Яд этих пауков не так силен, как тот, что вы приносили раньше. Наверное, тот яд был от другого паука.\n\nМне нужен свежий образец того яда, а чтобы узнать, откуда он, нужно поговорить с троллем, который много знает о племени Сухокожих – это мастер Гадрин в деревне Сен'джин. Отправляйтесь в Дуротар и поговорите с ним. Он вполне может знать, откуда тролли племени Сухокожих берут этот яд.", progress = nil, completion = "А, так вам нужен свежий яд пауков Сухокожих? Ну что ж, присядьте... вам не понравится то, что я сейчас скажу.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2936] = {title = "Паучья богиня", objective = "Прочитайте надписи на табличке Теки, узнайте имя паучьей богини, которой поклоняются тролли Сухокожих, а потом возвращайтесь к мастеру Гадрину.", description = "Тролли Сухокожих поклоняются паучьей богине, и самый сильный яд берут у нее. Так что если вам нужен этот яд, нужно будет призвать ее.\n\nДля этого требуется знать ее истинное имя – оно начертано на табличке в тролльем городе Зул'Фарраке, это в Танарисе. Табличка находится у гробницы, которую охраняет Тека Мученик.\n\nСразитесь с Текой и прочитайте на табличке имя паучьей богини, а потом возвращайтесь ко мне.", progress = nil, completion = "Элорта но Шадра... Произносите это имя лишь шепотом, потому что один его звук повергает духов в смятение.\n\nЯ напишу его на бумаге и сотворю для вас заклинание призыва.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2937] = {title = "Призыв Шадры", objective = "Убейте Шадру у алтаря Шадра'Алора и принесите ее яд аптекарю Лидону на Мельницу Таррен.", description = "Возьмите этот пергамент и прочитайте написанное на нем заклинание около алтаря Шадра'Алора – это в самом сердце владений клана Сухокожих. Это заклинание призовет Шадру – паучью богиню.", progress = "Достали яд?", completion = "Лучше и быть не могло!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2938] = {title = "Яд в Подгород", objective = "Отнесите сверток мастеру-аптекарю Фаранеллу в Подгород.", description = "Этот яд, который вы нашли у троллей Сухокожих, просто поразителен! Одной капли хватило, чтобы убить две дюжины кроликов. Ну, конечно, эти кролики были такие маленькие, что все уместились у меня на ладони, так что и организмы их особо не могли сопротивляться токсину... Но, тем не менее, яд просто убойный!\n\nЯ хотел бы отправить образец моему коллеге, аптекарю Фаранеллу в Подгород. Наверняка он захочет испытать его самостоятельно.", progress = "Мне сказали, что вы скоро будете, Шшишш. Принесли мне письмо?", completion = "Очень хорошо. Лидон говорил, что яд в этом свертке – самый смертоносный из тех, что ему встречались, и теперь он в срочном порядке ищет способ его применения.\n\nНадеюсь, применений ему найдется немало.\n\nСпасибо, Шшишш. Вы оказали Королевскому Фармацевтическому Обществу неоценимую услугу.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОдеяние королевского родаНагрудник почетного караулаЭгида Битвы\n\nВы также получите:\n\n"},
[2939] = {title = "В поисках знаний", objective = "Поговорите с Дарин Добрый Ветер в деревне Рут'теран.", description = "Руины Фераласа могут быть очень опасны, но зато они способны немало рассказать нам о том, что здесь произошло.\n\nВот, к примеру, несколько дней тому назад, копаясь в развалинах к югу отсюда, я обнаружил одну вещицу. На вид – обычный посох, но меня не покидает ощущение, что посох этот не простой. Мы с Ангелас уже давно корпим над книгами, но так ничего о нем и не узнали.\n\nУ меня есть коллега в Дарнассе, которая, возможно, сумеет сообщить нам что-нибудь полезное. <имя>, быть может, вы сходите к ней и попросите нам помочь?", progress = nil, completion = "А, так ты от Трояса Лунного Бриза?\n\n*Бормочет себе под нос* Вот вечно он меня донимает: ему все время кажется, что он обнаружил что-то чрезвычайно важное…\n\nПослушай, Эфром, я буду говорить откровенно. Троясу каждый раз кажется, будто он нашел в этих развалинах невесть какую диковинку. На самом же деле все, что там было ценного, давно уже растащили огры либо гарпии.\n\nТы, конечно, можешь порыться в библиотеке, но не думаю, что ты сумеешь найти что-то, что тебе пригодится.", rewards = "Вы получите:\n\n"},
[2940] = {title = "\"История Фераласа\"", objective = "Попросите Дарин Добрый Ветер одолжить вам книгу.", description = "Книга выглядит так, как будто ее не открывали годами. Переплет потерт и запылен, страницы пожелтели... Тем не менее, проглядев ее, вы убеждаетесь, что это именно то, что нужно было Троясу.\n\nВы берете книгу, но соображаете, что неплохо было бы спросить разрешения прежде, чем ее уносить.", progress = nil, completion = "Ты хочешь взять \"Историю Фераласа\"?\n\nДай подумать…\n\nХорошо, я разрешу тебе позаимствовать эту книгу, Эфром, если ты сначала окажешь мне одну услугу.", rewards = "Вы получите:\n\n"},
[2941] = {title = "В обмен на книгу", objective = "Отнесите письмо Кургль Поскакушке в Танарис.", description = "Я в свое время занималась самыми разными предметами, а вот сейчас меня очень интересуют хрустогрызы, которые обитают на побережье Внутренних земель. Мне особенно хочется посмотреть на одного из них: гигантскую черепаху, которую зовут Гаммерита. Я бы отправилась туда сама, но не могу отвлекаться от своих исследований. Добудь мне хотя бы изображение, ладно?\n\nОтнеси это письмо Кургль Поскакушке, которая живет в Танарисе. Она изобрела для меня машинку, которая может делать картинки. Кажется, Гурдл называет это \"снимками\"...", progress = "Письмо – мне?", completion = "А, ты один из студентов Дарин? Она очень сведущий историк, Эфром. Тебе повезло, что ты занимаешься под ее руководством.\n\nНу, давай я покажу тебе свой супер-хвататель. Он тебе понравится!", rewards = "Вы получите:\n\n"},
[2942] = {title = "Завтрашний камень", objective = "Верните искрящийся камень и посох Равноденствия Троясу Лунному Бризу в Крепость Оперенной Луны.", description = "Как только артефакт извлечен из Монолита, вы ощущаете, что энергия посоха Равноденствия идет на убыль.", progress = "Я рад, что вы вернулись, Ишт! Ну что, удалось вам что-нибудь найти?", completion = "Я с самого вашего ухода не отрывался от книги, Ишт. Так вот: добытый вами камень называется Завтрашний камень. Для чего он нужен, я пока точно не знаю, однако понятно, что пустяковую вещь так прятать не стали бы.\n\nЯ буду продолжать свои исследования. Надеюсь, что я и в будущем смогу на вас рассчитывать, Ишт. Спасибо вам за все!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОтщеп курганного камняКольцо Сева\n\nВы также получите:\n\n"},
[2943] = {title = "Возвращение к Троясу", objective = "Доставьте книгу Троясу Лунному Бризу в Крепость Оперенной Луны.", description = "Вот книга, <имя>. Пожалуйста, обращайся с ней бережно!\n\nНу, ступай. Наверно, Трояс тебя уже заждался.", progress = "А, Ишт! Ну что, вы побывали в Дарнассе?", completion = "Книга у вас! Чудесно!", rewards = "Вы получите:\n\n"},
[2944] = {title = "Супер-хвататель ФХ", objective = "Сделайте снимок Гаммериты с помощью супер-хватателя ФХ и вернитесь к Дарин Добрый Ветер в деревне Рут'теран.", description = "Ты – <первый/первая>, кто увидит мое новое изобретение, <имя>! Тебе нужно только навести его на предмет, который ты хочешь запечатлеть, и нажать на кнопку!\n\nКак там называется то существо из Внутренних земель, которое тебе нужно? Гаммерита? На вот, бери и снимай. Я уверена, что Дарин будет в восторге от снимка.\n\nПриятного суперхватания!", progress = "А, Революшен, вот наконец и ты! У тебя с собой прибор, который изготовила для меня Гурдл? Отлично!", completion = "О да! Изобретение Гурдл оправдало все мои ожидания!\n\nТы только не зазнавайся, Революшен, но имей в виду, что я тобой довольна.\n\nТак, где же я оставила эту книгу...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2945] = {title = "Кольцо, покрытое грязью", objective = "Придумайте, как отчистить кольцо, покрытое грязью.", description = "С тела одного из дворфов Черного Железа вы сняли предмет, напоминающий кольцо. Сложно сказать, что это за кольцо, поскольку оно покрыто толстым слоем окаменевшей грязи. Носить его едва ли возможно. Однако вы уверены, что под слоем грязи скрывается драгоценный металл, а может, еще и самоцвет.\n\nПожалуй, стоит попытаться отчистить всю эту грязь.", progress = "Перед вами гномий механизм, к которому прикреплена табличка с названием \"Чистер 5200\". Судя по инструкции под табличкой, эта машина начищает предметы до зеркального блеска, устраняя все виды загрязнений. Машина снабжена щелью для монет, в которую требуется опустить три серебряный монеты, после того как предмет, нуждающийся в очистке, помещен внутрь. \n\nПохоже, стоит опробовать это приспособление на вашем кольце.", completion = "Вы опускаете кольцо и три монеты в Чистер 5200.\n\nМашина с яростным гудением принимается за работу, скрипя и вибрируя. Сложно представить, что происходит внутри...\n\nНаконец Чистер 5200 замирает и окошко премника со звоном открывается. В нем лежит маленькая аккуратно завернутая коробка с красным бантиком. Похоже, Чистер 5200 также предоставляет подарочную упаковку!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта"},
[2946] = {title = "Посмотрим, что будет дальше", objective = "Принесите миниатюрные платиновые диски к воротам Ульдума в Танарисе и проверьте, имеют ли диски отношение к воротам.", description = "Мы хотим, чтобы вы доставили диски, обнаруженные вами, к запечатанным воротам Ульдума. Мы... мы не знаем, что с вами там может случиться.\n\nДа, мы знаем, что звучит рискованно. Но может ведь и ничего не случиться? Может, вам придется что-то с этими дисками сделать. Возможно, эти диски откроют ворота. Не бойтесь экспериментировать и будьте готовы ко всему.\n\nКогда справитесь с заданием, возвращайтесь в Стальгорн. Нам будет что проанализировать!", progress = "Какой знакомый постамент. Возможно, он тут неспроста...", completion = "Когда вы прикасаетесь к постаменту, ульдаманские диски в вашем заплечном мешке начинают гудеть и светиться. Знакомое покалывание ощущается в руках, и перед вратами Ульдума оживает изваяние Каменного стража.\n\n\"Приветствую вас. Я – страж входа. Среди дисков доступа не хватает Ульдумских пластин. Пожалуйста, дополните набор дисков этими пластинами и повторите последовательность доступа. Благодарю за внимание\".", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2947] = {title = "Возвращение кольца", objective = "Вы можеть оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца.", description = "Открыв коробку, вы видите именно то, что и предполагали – сияющее кольцо! Вы чувствуете исходящие от него волны магической силы.\n\nНа внутренней стороне кольца стоит маленькое, но вполне различимое клеймо Стальгорна, а рядом с ним выгравированы инициалы: \"ТдК\". Это могут быть инициалы владельца, а может – изготовившего кольцо ювелира... Оставить кольцо себе или вернуть владельцу... Непростое решение!", progress = "Эй-эй! Кто тут ломится? Я уважаемый предприниматель! Нечего устраивать истерики, наверняка курьер с деньгами просто задержался в пути... А, прошу прощения, я принял вас за моего арендодателя! \n\nВы пришли к лучшему ювелиру Стальгорна, который НИКОГДА не создает проклятых предметов! \n\nТак что вам угодно?", completion = "Кольцо, говорите? Ну конечно, это я его сделал! \n\nДо падения Гномрегана у меня была там небольшая мастерская. Видимо, кольцо осталось там, когда пришлось очень быстро давать деру. Довольно простое кольцо – я сделал таких несколько. \n\nГоворите, сняли с дворфа Черного Железа? Занятно, занятно – дело пахнет весьма запутанной интригой... Возможно, следует дать знать властям; такие вещи не для нашего брата... \n\nЧто касается кольца...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2948] = {title = "Гномское усовершенствование", objective = "Принесите блестящее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Талвашу де Кисселю в Стальгорн.", description = "Слушайте <имя>, конечно, это ваше кольцо... но я вам лучшее сделаю! Дизайн, как я уже сказал, уж очень прост. Теперь я уже намного искуснее, и всего за каких-то тридцать серебряников я вам из него шедевр сделаю! Ну, чуть побольше тридцати, честно говоря...\n\nСейчас я в затруднении, все мои запасы материалов иссякли. Если вы принесете мне слиток серебра и моховой агат, то я нанесу на кольцо решетчатый узор из серебра и агата, и оно станет гораздо более стильным!\n\nПоверьте мне!", progress = "Вы принесли нужные материалы? Я бы не стал просить, если бы удача не покинула меня...", completion = "Ах, именно то, что нужно! Когда нибудь, когда я выберусь из этой ямы, в которую так незаслуженно попал, я сделаю для вас, для ВСЕХ лучшие украшения во всем Азероте! А пока благодарю вас за хлопоты. Обычно я прошу в десять раз больше, чем я взял с вас за кольцо такого качества...\n\nКстати, о кольцах – вот ваша обновка!", rewards = "Вы получите:\n\nЗолотое кольцо Талваша"},
[2949] = {title = "Возвращение кольца", objective = "Вы можеть оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца.", description = "Открыв коробку, появившуюся в окошке Чистера 5200, вы видите сияющее кольцо! Надев кольцо на палец, вы чувствуете исходящие от него волны магической силы.\n\nНа внутренней стороне кольца стоит маленькое, но вполне различимое клеймо Оргриммара, а рядом с ним выгравированы три буквы: \"НОГ\" – это явно начало имени, но даже после чистки прочесть его целиком невозможно. Это могут быть инициалы владельца, а может – изготовившего кольцо ювелира... Оставить кольцо себе или вернуть владельцу... Непростое решение!", progress = "Ничего, уж мы найдем управу на этих мерзких маленьких гномов. Я даже не сомневаюсь, что это они сперли у нас эту машину! Проклятые создания... А? Чего изволите?", completion = "Кольцо из Гномрегана? Очень любопытно... Нет, его сделал не я. \n\nГномреганская штучка – н-да, неплохо для горстки болванов. Подумать только, эти ходячие недоразумения вдруг научились делать машины лучше нас... \n\nЧто, кольцо было у дворфа Черного Железа? Еще интереснее... Возможно, гномы сперли и подправили чертежи их жутких големов – я бы этому совсем не удивился. Значит, теперь дворфы жаждут мести. Очень любопытно... \n\nЧто же о кольце...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2950] = {title = "Переделка кольца", objective = "Принесите блестящее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Ноггу в Огргиммар.", description = "Нет-нет-нет, я не собираюсь утверждать, что это моя работа! Обычно я такого не делаю. Но твое сообщение насчет дворфов Черного Железа чрезвычайно полезно. Так и быть, я переделаю для тебя это кольцо, и оно станет куда лучше, чем мог предполагать его создатель. Наверно, это был какой-нибудь гном...\n\nПринеси мне слиток серебра, моховой агат и тридцать серебряных монет – за труды. Я украшу кольцо серебряной решеткой, вправлю в него агат, и это значительно усилит его магические свойства. Интересует?", progress = "Ну что, есть у тебя нужные материалы? Без того, о чем я просил, я это кольцо улучшить не смогу!", completion = "Вот оно, твое кольцо, лучше прежнего. Еще раз спасибо за сведения об этих дворфах Черного Железа. Это объясняет, откуда вдруг у гномов взялись гоблинские идеи...", rewards = "Вы получите:\n\nЗолотое кольцо Ногга"},
[2951] = {title = "Чистер 5200!", objective = "Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200.", description = "Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений. Небольшая табличка, прикрепленная к устройству, гласит: \"Чистер 5200\".\n\nВаши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер 5200 легко справится с этой проблемой! Опустите в щель приемника три серебряные монеты и подождите пару минут, пока Чистер 5200 наводит лоск на ваши украшения.", progress = "Похоже, что в механизм следует положить предмет, нуждающийся в очистке, и три серебряных монеты.", completion = "Вы кладете покрытый грязью предмет и три серебряные монеты в Чистер 5200, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует.", rewards = nil},
[2952] = {title = "Чистер 5200!", objective = "С проглотив кольцо, машина несколько минут с гудением вертит его в своих недрах и наконец останавливается, звенящим звуком оповестив вас о том, что работа закончена. Окошко приемника открывается, и вы видите в нем аккуратно завернутую коробочку. Видимо, машина выдает очищенные предметы в подарочной упаковке. Ну, даже если кольцо не удалось очистить, вы получили довольно миленькую коробочку за свои деньги... \n\nЧто ж, посмотрим...", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКоробка, упакованная \"Чистером\""},
[2953] = {title = "Работа для Чистера", objective = "Приемник Чистера 5200 пуст. Чтобы машина заработала, требуется загрязненный предмет и три серебряные монетки.", description = nil, progress = "Приемник Чистера 5200 пуст. Чтобы машина заработала, требуется загрязненный предмет и три серебряные монетки.", completion = "Чистер 5200 с яростным гудением принимается за работу. Въевшаяся грязь растворяется под воздействием гномьих чистящих средств. \n\nНаконец Чистер 5200 перестает вибрировать. Окошко премника со звоном открывается – в нем лежит аккуратно завернутая коробка.", rewards = "Вы получите:\n\nКоробка, упакованная \"Чистером\""},
[2954] = {title = "Каменный Страж", objective = "Узнайте назначение Каменного Стража Норганнона, затем коснитесь пьедестала Ульдума в пустыне Танарис.", description = "Приветствую. Я охраняю вход. Если в вашем наборе дисков нет Ульдумских пластин, вы не сможете посетить комплекс Ульдум.\"\n\nДолжно быть, появление Каменного Стража Норганнона и есть та реакция, на которую рассчитывали те, кто послал вас в пустыню Танарис с платиновыми дисками. Прежде чем продолжить путь, вам предстоит узнать историю Каменного Стража.", progress = "Чтобы продолжить, следует узнать назначение Каменного Стража...", completion = "В голосе Каменного Стража звучит сила и власть:\n\n\"Когда ты коснешья пьедестала, диски вернутся к тебе. Получив же Ульдумские пластины и воссоединив их с имеющимися дисками, ты сможешь войти в Ульдум.\"", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2962] = {title = "Сильное зеленое свечение", objective = "Отправляйтесь в Гномреган и принесите высокорадиоактивные образцы. Внимание: отходы нестабильны и довольно быстро разрушаются.\n\nВерните Оззи тяжелую освинцованную склянку для проб, когда задача будет выполнена.", description = "Этого образца не только недостаточно для опытов, он еще и загрязнен.\n\nНам нужно более сильное зеленое свечение. Для наших целей эти трогги явно недостаточно облучены. Вам придется отправиться в Гномреган и принести некоторое количество радиоактивных образцов прямо с носителей. Я говорю об облученных слизнюках, шнырюках и ужасниках. Будьте начеку: образцы хранить очень трудно. Возможно, придется сделать несколько попыток, пока вы не принесете достаточное количество образцов.", progress = "Хм, вы не светитесь. Хороший знак.", completion = "*Оззи рассматривает вас.* Впечатляюще, у вас не отвалилась ни одна конечность! Ну-с, посмотрим, на что сгодится эта проба!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2963] = {title = "Ульдумские чудеса", objective = "Поговорите с историком Карником в Зале Исследователей в Стальгорне.", description = "И снова примите мои поздравления, <имя>! Ваша ульдаманская находка привела всю Лигу Исследователей в такое возбуждение! Лига пыталась разгадать тайны найденных вами миниатюрных платиновых дисков. Ваше неожиданное прибытие сюда, в Зал, дает мне возможность сказать вам, что мы, похоже, наткнулись на нечто великое!\n\nИсторик Карник нашел важные сведения по поводу истинного происхождения Долины Стражей в пустыне Танарис. Он хочет поговорить с вами как можно скорее!", progress = nil, completion = "Я счастлив, что вы не оставляете интереса к исследованиям, Эфром! Ваши прирожденные талант и отвага помогут нам приоткрыть завесу таких тайн, что мы и надеяться не смели!\n\nДиски Норганнона из Ульдамана служили хранилищем обширных знаний. Вы, так сказать, только чуть копнули. У Создателей, как говорят, в Азероте имелись и другие хранилища. Это подводит нас к проблеме Ульдума...", rewards = "Вы получите:\n\n"},
[2964] = {title = "Новое задание", objective = "Поговорите со старшим исследователем Магелласом в Стальгорне.", description = "Что сказать, <имя>… мы зашли в тупик. Мы знаем, что нам нужно – Ульдумские пластины – но где их взять, не имеем ни малейшего понятия. Необходимо провести серьезное исследование и выработать план действий. У меня есть пара идей, и я надеюсь, что вскоре мы наймем тебя и отправим за пластинами.\n\nОб этом необходимо сообщить старшему исследователю; он без сомнения пожелает лично поблагодарить тебя за помощь Лиге.", progress = nil, completion = "Значит, мы все согласны – лучший план действий – это выждать, пока мы сможем сузить зону поиска. Мы зашли настолько далеко благодаря тебе, Эфром, и я надеюсь, что именно ты сумеешь отомкнуть для нас Ульдум!\n\nПозволь вручить тебе заслуженный гонорар и небольшую премию. Заглядывай к нам время от времени... Ульдум ждет тебя!", rewards = "Вы получите:\n\n"},
[2965] = {title = "Ульдумские чудеса", objective = "Поговорите с Нарой Буйногривой на Вершине Старейшин Громового Утеса.", description = "Ах, <имя>, как удачно, что ты снова <пришел/пришла> ко мне! Твоя ульдаманская находка вызвала ожесточенные споры среди мудрецов. Я сам только что спорил с друидом, Нарой Буйногривой, когда меня вдруг осенило – ее недавние приключения могут быть весьма важны в смысле определения следующего нашего шага в разгадке этой тайны!\n\nЯ бы хотел, чтобы ты <поговорил/поговорила> с ней о ее путешествии в Долину Стражей в пустыне Танарис. Она ждет теба на Вершине Старейшин.", progress = nil, completion = "В глубине пустыни Танарис есть место, называемое Долиной Стражей. Эти диски, что ты нашел... в переводе иероглифической надписи на них упоминается место под названием Ульдум. Многие считают, что это миф.\n\nНо я-то знаю, что Ульдум существует. Я была там. Ну... хотя бы рядом постояла.\n\nНо вот в чем загадка, Шушпанк – мы думаем, что есть связь между этими дисками и Ульдумом, потому мы хотим, чтобы ты отправился туда.", rewards = "Вы получите:\n\n"},
[2966] = {title = "Посмотрим, что будет дальше", objective = "Принесите миниатюрные платиновые диски к воротам Ульдума в Танарисе и проверить, имеют ли диски отношение к воротам.", description = "Мы с Ведуном Искателем Истины хотели бы, чтобы ты <доставил/доставила> эти миниатюрные диски к запечатанным воротам Ульдума. Мы... мы не знаем, что может после этого случиться.\n\nДа, мы понимаем, это может показаться рискованным. Но может ведь и ничего не случиться? Может, тебе придется что-то с этими дисками сделать. Возможно, эти диски откроют ворота. Не бойся испытать их и будь <готов/готова> ко всему.\n\nУзнай, что получится, и возвращайся ко мне. Нам есть много о чем поговорить.", progress = "Какой знакомый постамент торчит из горячего песка. Возможно, он тут неспроста...", completion = "Когда вы прикасаетесь к постаменту, улдаманские диски в вашем заплечном мешке начинают гудеть и светиться. Знакомое покалывание ощущается в руках, и перед вратами Ульдума оживает изваяние Каменного стража.\n\n\"Приветствую вас. Я – страж входа. Среди дисков доступа не хватает Ульдумских пластин. Пожалуйста, дополните набор дисков этими пластинами и повторите последовательность доступа. Благодарю за внимание\".", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2967] = {title = "Возвращение в Громовой Утес", objective = "Поговорите с Нарой Буйногривой в Громовом Утесе.", description = "Вы снова вступаете на пьедестал; неожиданно у вас в заплечном мешке опять материализуются платиновые диски.\n\nОбретя знания Каменного Стража и вернув себе диски, вам пора возвращаться в Громовой Утес к Наре Буйногривой, сообщить ей о совершенных открытиях.", progress = "Добро пожаловать, Нигилум. Ну как, пригодились диски?", completion = "Тебе не хватило дисков? Забавно. Похоже, диски Норганнона – всего лишь часть полного набора, один из ключей в связке.\n\nЕсли нам удастся найти Ульдумские пластины, мы можем получить доступ в сам Ульдум! Не знаю, радоваться такой возможности или ужасаться.\n\nБыть может, нам придется пожертвовать всем ради сохранения глубинных тайн земли, грозящих нам всем великими опасностями, хм, в тайне.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2968] = {title = "Новое задание", objective = "Поговорите с Ведуном Искателем Истины в Громовом Утесе.", description = "Что сказать, <имя>… мы оказались в тупиковой ситуации. Мы знаем, что нам нужно – Ульдумские пластины – но где их взять, не имеем ни малейшего понятия. Необходимо провести серьезное исследование и выработать план действий. У меня есть пара идей, и я надеюсь, что вскоре мы наймем тебя и отправим за пластинами.\n\nОб этом необходимо сообщить Мудрому Искателю Правды; он без сомнения пожелает лично поблагодарить тебя за услышанный зов.", progress = nil, completion = "Значит, мы все согласны – лучший план действий – это выждать, пока мы сможем сузить зону поиска. Мы зашли настолько далеко благодаря тебе, Вираэлий, и я надеюсь, что именно ты сумеешь отомкнуть для нас Ульдум!\n\nПозволь вручить тебе заслуженный гонорар и немного сверхурочных. Должно покрыть все непредвиденные расходы. Заглядывай к нам время от времени... Ульдум ждет тебя, юноша!", rewards = "Вы получите:\n\n"},
[2969] = {title = "Свободу всем живым существам!", objective = "Освободите летучих хамелеонов из вольера в лагере Зловещего Тотема с помощью ключа от бамбуковой клетки. Необходимо, чтобы Кайдел Лунный Ткач и как минимум 6 хамелеонов остались живы.\n\nУ вас в запасе 6 минут. После этого Кайдел решит, что пора отступать, и задание останется невыполненным.", description = "Гнусные таурены из клана Зловещего Тотема ловят лесных дракончиков, <имя>! Мы с Джер'Кай понятия не имеем, что они собираются с ними делать, но явно ничего хорошего!\n\nУ нас просто не хватит сил, чтобы прорваться в лагерь и освободить пленных дракончиков, но, может быть, с твоей помощью...\n\nЕсли ты согласишься помочь, и у тебя есть надежные товарищи, отопри клетку вот этим ключом и выпусти бедных зверушек на волю! Только постарайся, чтобы все сумели улететь живыми... Конечно, я тоже буду с тобой! А Джер'Кай останется здесь.", progress = nil, completion = "Слава Элуне! Чиффнир, ты настоящий подарок судьбы! Нам с Джер'Кай в одиночку никогда бы не удалось спасти бедных дракончиков.\n\nПожалуйста, поговори теперь с Джер'Кай. А мне нужно приготовиться к мести! Если дракончики на свободе, это еще не значит, что таурены не наловят новых! Так что мы с Джер'Кай собираемся перейти в наступление.", rewards = "Вы получите:\n\n"},
[2970] = {title = "Небольшое возмездие", objective = "Убейте 12 натуралистов из племени Зловещего Тотема, 10 налетчиков из племени Зловещего Тотема и 6 шаманов из племени Зловещего Тотема, а затем вернитесь к Джер'Кай Лунный Ткач в Фераласе.", description = "Как тебе уже говорила Кайдел, мы с ней собираемся напасть на тауренов из клана Зловещего Тотема. Мы без труда уложим несколько тауренов, не подвергаясь опасности сами, но мы были бы очень рады, если бы и ты <присоединился/присоединилась> к нам.\n\nТот лагерь, что внизу, тебе известен, но дальше на восток есть еще несколько. Постарайся причинить тауренам максимальный ущерб. Ну, а после того, как они отведают стрел Кайдел и твоего собственного оружия, мы можем встретиться здесь снова.", progress = "Кайдел нужно время, чтобы подготовиться, но у нас с тобой и так счет идет на десятки! Клан Зловещего Тотема обнаружил наше присутствие, и теперь они закопошились, как гадюки!\n\nОни сделают все, что в их силах, чтобы избавиться от нас. Так что смотри, осторожнее! Теперь, когда ты с нами, они будут охотиться и на тебя.", completion = "Да, Wrestlecake, Кайдел была права насчет тебя: у тебя талант к этому делу! Ты – куда более опытный искатель приключений, чем мы обе. Спасибо, что ты с нами!\n\nЭтот клан Зловещего Тотема куда опаснее остальных тауренов. Подозреваю, что их боятся даже собственные сородичи! \n\nВпрочем, об этом потом.", rewards = "Вы получите:\n\n"},
[2972] = {title = "Небольшое возмездие", objective = "Отнесите перстень-печатку Джер'Кай верховной жрице Тиранде Шелест Ветра в Дарнассе.", description = "Здесь, в глуши, у нас с Кайдел нет особых возможностей тебя вознаградить. Но разумеется, без награды мы тебя не отпустим! Вот, возьми мой перстень с печаткой. Если когда-нибудь окажешься в ветвях Тельдрассила, зайди в храм в центре Дарнасса. Там ты найдешь нашу верховную жрицу, Тиранду Шелест Ветра. Кольцо будет для нее знаком, что с нами все в порядке, и что тебе можно доверять.\n\nМы обе благодарим тебя, <имя>!", progress = "Привет тебе, дитя мое! Мы рады видеть в нашем храме столь закаленных искателей приключений. Если у тебя есть время, быть может, ты поделишься парочкой историй с менее опытными странниками? Многим из них наверняка пойдет на пользу твоя мудрость.\n\nОх, прости меня! Как это неучтиво с моей стороны! Ведь ты пришел в наш храм за помощью, а я пристаю к тебе с пустяками... Прости меня, пожалуйста. Чем могут тебе помочь служители Света?", completion = "Прекрасная история, Татаки! Мы очень рады, что ты помог не только драконьему племени, но и одной из наших жриц. Джер'Кай поступила правильно, прислав тебя к нам. Я позабочусь о том, чтобы вернуть ей ее кольцо – в Фералас в ближайшее время отправятся наши разведчики. Пусть заодно разведают и это...\n\nСпасибо тебе еще раз. Чувствуй себя у нас, как дома!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНарукавье огненной ивыРемень из ночной чешуи\n\nВы также получите:\n\n"},
[2973] = {title = "Новый сверкающий плащ", objective = "Принесите 10 радужных крыльев летучих хамелеонов Кригу Головорубу в Лагерь Мохаче.", description = "Приятно познакомиться, <класс>. Мы с товарищами прибыли сюда, в Фералас, по заданию из Оргриммара.\n\nМоя супруга, Коррин, очень любит новые наряды. Я хочу пошить ей новый плащ из прозрачных крылышек лесных дракончиков. Не согласишься ли ты мне помочь? Те летучие хамелеоны с роскошными крыльями, что мне нужны, водятся к западу от Лагеря Мохаче.", progress = "Летучие хамелеоны могут быть очень опасны, когда на них нападают. Так что смотри в оба, |3-6(Воин)! Тем более, опасаться приходится не только дракончиков, но и тамошних ночных эльфов. \n\nКогда наберешь нужное количество крыльев, дай мне знать, уж я в долгу не останусь!", completion = "Отлично, |3-6(Воин)! Да, это то, что надо. Этого вполне хватит на плащ для Коррин, а может, и останется! Спасибо тебе.\n\nНу что, надеюсь, охота была не очень опасной? А то ведь Фералас ошибок не прощает.\n\nСпасибо еще раз, |3-6(Воин)!", rewards = "Вы получите:\n\n"},
[2974] = {title = "Зловещее открытие", objective = "Принесите 20 рогов Зловещего Тотема Кригу Головорубу в Лагерь Мохаче.", description = "Как? Таурены, здесь, в этих краях? Да ты шутишь! И как они выглядели?\n\nКлан Зловещего Тотема! Тебе повстречались именно они. Белгром, один из наших старших, очень ими интересуется... Даже награду за них назначил!\n\nВозвращайся туда, <класс>! Возвращайся, и принеси мне их рога – чем больше, тем лучше! С кланом Зловещего Тотема шутки плохи, и недооценивать их не стоит. Ступай и перебей их, сколько сможешь. Пусть реки Фераласа побагровеют от их темной крови!", progress = "Клан Зловещего Тотема – злой клан, |3-6(Воин). Я серьезно. Если тебе удалось обнаружить их гнездо, самое лучшее – нанести упреждающий удар, прежде, чем они попытаются захватить наши владения и сравнять с землей наши деревни.", completion = "Отличные рога, |3-6(Воин)! Молодец! Я заберу их у тебя и сообщу о твоих деяниях Белгрому, как только вернусь в Оргриммар. Ты помог мне уже дважды, и я тебя запомню. Быть может, когда-нибудь и я тебе помогу! Удачи.", rewards = "Вы получите:\n\n"},
[2975] = {title = "Огры Фераласа", objective = "Убейте 10 огров из клана Гордунни, 10 огров-магов из клана Гордунни и 5 громил из клана Гордунни по просьбе Роки Орхан из Лагеря Мохаче.", description = "Присутствие огров из клана Гордунни не может оставаться незамеченным. Оглядись вокруг, <имя>! Само их существование уродует эту землю. Необходимо оттеснить их назад, пока они не продвинулись еще дальше в Фералас.\n\nСтупай на север вдоль реки, и увидишь их заставу. Задай им жару, <имя>! Пусть видят, что им тут не рады.", progress = nil, completion = "Отлично, Томпсон! Еще немного, и эта земля исцелится. Мы не сдадимся!", rewards = "Вы получите:\n\n"},
[2976] = {title = "Зловещее открытие", objective = "Отнесите ящик с рогами клана Зловещего Тотема Белгрому Каменной Булавы в Оргриммар.", description = "Чего еще?\n\nАх, я говорил о награде? Ну что ж, поделом мне – пора бы и научиться держать язык за зубами…\n\nНу, в конце концов, это ты <сделал/сделала> всю работу, тебе и награда полагается. Забирай рога. Я велю упаковать их в ящик. Отыщи на Аллее Чести Белгрома Каменной Булавы. Он расспросит тебя о том, что ты <видел/видела>, и выдаст заслуженную награду.\n\nПока, <класс>! Еще раз спасибо за все.", progress = "Поживей, |3-6(Воин)! У меня сегодня еще много дел.", completion = "Клан Зловещего Тотема?! Интересно... Так говоришь, ты наткнулся на них во время охоты в Фераласе? В самом деле?\n\nТвои новости очень важны для нас, |3-6(Воин). Расскажи все как было, а я пока отсчитаю твою награду.\n\nДа, и пока ты не ушел: имей в виду, я тебе очень признателен за эту информацию.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНакидка сраженияСфера Нефритовой луны\n\nВы также получите:\n\n"},
[2977] = {title = "Возвращение в Стальгорн", objective = "Поговорите с историком Карником из Стальгорна.", description = "Вы снова вступаете на пьедестал; неожиданно у вас в заплечном мешке опять материализуются платиновые диски.\n\nОбретя знания Каменного Стража и вернув себе диски, вам пора возвращаться в Стальгорн и сообщить Лиге Исследователей о совершенных открытиях.", progress = "Добро пожаловать, Эфром. Ну как, пригодились диски или дело ничем не закончилось?", completion = "Тебе не хватило дисков? Забавно. Похоже, диски Норганнона – всего лишь часть полного набора, один из ключей в связке.\n\nЕсли нам удастся найти Ульдумские пластины, мы можем получить доступ в сам Ульдум! Только представь – у нас появится возможность исследовать место, где трудились Создатели, не роясь в земле!\n\nХотя землю рыть тоже неплохо... вполне...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2978] = {title = "Свиток Гордунни", objective = "Отнести свиток Гордунни Роке Орхан в Лагерь Мохаче.", description = "Вы берете в руки запачканный свиток и обнаруживаете, что на нем изображена какая-то встреча или церемония. Рока Орхан наверняка заинтересуется этим свитком и тем, что он означает для Гордунни...", progress = "Что это?", completion = "Этот свиток... Ты нашел его в Поселении Гордунни?", rewards = "Вы получите:\n\n"},
[2979] = {title = "Темный обряд", objective = "Добудьте сферу Гордунни по просьбе Роки Орхан из Лагеря Мохаче.", description = "<имя>, похоже, они готовят какой-то темный обряд! Насколько я понимаю, проводить его будут маги-лорды из клана Гордунни.\n\nОтыщи одного из таких магов-лордов, и добудь у него магическую сферу.\n\nВ такой сфере сокрыта великая мощь, и она поможет нам больше узнать об этом обряде и о магии, которой владеют Гордунни.", progress = "Нам нужно понять, почему Гордунни здесь, Томпсон.", completion = "Эта сфера поможет нам получить информацию о Гордунни... И мы используем эту информацию, чтобы разгромить их!", rewards = "Вы получите:\n\n"},
[2980] = {title = "Огры Фераласа", objective = "Убейте 10 шаманов из клана Гордунни, 10 чернокнижников из клана Гордунни и 5 извергов из клана Гордунни по просьбе Роки Орхан из Лагеря Мохаче.", description = "Теперь, когда ты <показал/показала> себя настоящим бойцом, я надеюсь, тебе хватит мужества выполнить и следующее задание.\n\nОтправляйся в Высокогорные  дебри, к юго-западу отсюда. Это земля, которая некогда принадлежала ночным эльфам. Там увидишь заброшенные и разрушенные здания. Когда увидишь среди руин засохшие деревья и оскверненную почву, знай: там и живут Гордунни. Прогони их прочь!\n\nЭти огры куда опаснее тех, с которыми тебе, <имя>, доводилось сталкиваться прежде. Так что будь осторожнее!", progress = nil, completion = "Да, Томпсон, ты воистину надежный и верный союзник!", rewards = "Вы получите:\n\n"},
[2981] = {title = "Опасность в Фераласе", objective = "Поговорите с Рокой Орхан в Лагере Мохаче.", description = "Что, <класс>, хочешь показать себя? Фералас для этого самое подходящее место! Главная сила там – племя огров, именуемое Гордунни, и их становится все больше и больше. Их надо остановить, пока они не вытеснили из Фераласа нас!\n\nВ Лагере Мохаче в Фераласе живет моя знакомая воительница по имени Рока Орхан. Ступай к ней. Она подробнее расскажет тебе о создавшемся положении.", progress = nil, completion = "А, тебя прислал Белгром! Ты как нельзя более вовремя, |3-6(нежить).\n\nЯ расскажу, что у нас тут творится, а ты уж решай, по зубам ли тебе это... Хотя если тебя прислал Белгром, значит, сомневаться в твоей доблести не приходится.", rewards = "Вы получите:\n\n"},
[2982] = {title = "Высокогорные дебри", objective = "Убейте 8 чернокнижников из клана Гордунни, 8 шаманов из клана Гордунни и 8 громил из клана Гордунни по просьбе Ангелас Лунный Бриз.", description = "Места там опасные, и все же мы с Троясом исследовали руины в лесах Фераласа.\n\nНо в последнее время Трояс ходил в Высокогорные  дебри в одиночку. Я серьезно за него беспокоюсь! Эти земли захвачены ограми из клана Гордунни, а они не дают спуску тем, кто забредает на их территорию!\n\nЯ надеялась, что вы, может быть, согласитесь побывать в развалинах на юго-востоке и перебить часть огров? Тогда эти места станут не такими опасными. Я вам буду очень признательна!", progress = nil, completion = "О, как я вам благодарна!\n\nТолько, пожалуйста, Троясу об этом ни слова!", rewards = "Вы получите:\n\n"},
[2983] = {title = "Зов огня", objective = "Найдите в Степях Кранала Фисса.", description = "Много времени прошло с тех пор, как ты <прошел/прошла>  последнее испытание, <имя>. Пока тебе хватало терпения в твоих занятиях, однако пришло время обрести новую силу... подлинную силу! Стихия огня – твоя, если только ты <готов/готова> заплатить за это знание.\n\nОтыщи в Степях Кранала Фисса. Он живет в небольшой хижине к северу от Перекрестка. Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!", progress = nil, completion = "Что, тебя Сварт прислал, да?\n\nНу, на Сварта положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня.\n\nДа, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение, Сонноекопыто. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.", rewards = "Вы получите:\n\n"},
[2984] = {title = "Зов огня", objective = "Найдите в Степях Кранала Фисса.", description = "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание, <имя>! Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты <готов/готова> платить за это.\n\nОтыщи в Степях Кранала Фисса. Он живет в небольшой хижине к северу от Перекрестка. Только осторожнее: если промахнешься, можешь очутиться в землях ночных эльфов!", progress = nil, completion = "Что, тебя Нарм прислал, да?\n\nНу, на Нарма положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня.\n\nДа, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение, Язнаюкаратэ. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.", rewards = "Вы получите:\n\n"},
[2985] = {title = "Зов воды", objective = "Отыщите в Степях Ислен Заклинательницу Воды.", description = "Похоже, ты <готов/готова> к новому испытанию, <имя>. Ты <проявил/проявила> немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды.\n\nОтыщи Ислен Заклинательницу Воды. Она живет в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, <имя>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[2986] = {title = "Зов воды", objective = "Отыщите в Степях Ислен Заклинательницу Воды.", description = "Много воды утекло со времени последнего испытания. Ты <проявил/проявила> немало упорства в учении и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды.\n\nОтыщи Ислен Заклинательницу Воды. Она живет в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, <имя>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[2987] = {title = "Кобальт Гордунни", objective = "Добудьте 12 образцов кобальта Гордунни для Орвина Гиззмика из Лагеря Мохаче.", description = "Я только что прибыл сюда, в Фералас. Я слышал, что у огров из клана Гордунни, обитающих в здешних чащобах, попадаются интересные минералы. Неизвестно, к чему они им, но уж, разумеется, по доброй воле они ими делиться не собираются! Наоборот, норовят спрятать, чтобы бизнесменам вроде меня труднее было до них добраться.\n\nЕсли вы согласитесь помочь, то вот вам моя лопатка. Ступайте в Поселение Гордунни к северу отсюда и накопайте мне образцов кобальта Гордунни. Ищите: где блеснет синим, там и ройте!", progress = "Ну что, вперед, за работу!\n\nА мне надо много где побывать, много кого повидать... Время – деньги!", completion = "Отлично! Захвачу это с собой, когда снова отправлюсь в путь. Я наверняка сумею найти кого-то, кто выложит за эти образцы кругленькую сумму!\n\nБлагодарю вас, Томпсон. Вот, возьмите за труды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги МахаришиПлащ звездочета\n\nВы также получите:\n\n"},
[2988] = {title = "Тролльи клетки", objective = "Проверьте клетки в двух деревнях Сухокожих и возвращайтесь к дрессировщику грифонов Разящему Когтю.", description = "Пропал сын нашего самого лучшего грифона! Наследник Быстрокрыла, Остроклюв, пропал несколько дней назад, когда охотился вместе с родителями. Я думаю, его похитили тролли!\n\nПомогите нам! Остроклюва могут держать в клетке в одной из двух деревенек Сухокожих.", progress = nil, completion = "Остроклюва в деревнях нет? Хм... это плохо. От этого грифона должно было произойти их следующее поколение, и если он погибнет, то наш флот понесет огромные потери...", rewards = "Вы получите:\n\n"},
[2989] = {title = "Алтарь Зула", objective = "Осмотрите вершину Алтаря Зула и возвращайтесь к укротителю грифонов Разящему Когтю.", description = "У троллей племени Сухокожих Остроклюва нет... Значит, его забрали тролли из клана Порочной Ветви. Поищите детеныша грифона у Алтаря Зула – это на западной границе территории этого клана.", progress = "Скорее, Димиллион! Племя Порочной Ветви держит у себя Остроклюва, нужно немедленно освободить его!", completion = "Остроклюва там не было? Это плохая, но и хорошая новость...\n\nХорошо, что его не было на алтаре Зула – там тролли из клана Порочной Ветви совершают свои жертвоприношения.\n\nСпасибо за помощь, но, боюсь, вам предстоит еще одна, более тяжелая работа.", rewards = "Вы получите:\n\n"},
[2990] = {title = "Тадиус Мрачная Тень", objective = "Принесите перо Остроклюва Тадиусу Мрачной Тени в Выжженные земли.", description = "Отнесите это перо Тадиусу Мрачной Тени, прорицателю. Он давно ушел с Заоблачного Пика в поисках темных знаний, но в душе он все еще с нами, с кланом Громового Молота!\n\nВозможно, он поможет нам разыскать Остроклюва.\n\nЭто перо нашли в гнезде, где был детеныш грифона, и если вы отдадите его Тадиусу, то он сможет при помощи своего прорицания узнать, где находится сам Остроклюв.\n\nУдачи, <имя>. Тадиуса можно найти в Выжженных землях, в башне магов в Крепости Стражей Пустоты.", progress = "Трансмастер, вы пришли с подарком?", completion = "Ах, да. Это перо грифона, но не обычного, а великого, способного на великие дела... Если, конечно, он доживет до зрелого возраста.\n\nХотите найти его? Что ж, тогда слушайте, храбрый |3-6(Разбойник).", rewards = "Вы получите:\n\n"},
[2991] = {title = "Медальон Некрума", objective = "Отнесите медальон Некрума Тадиусу Мрачной Тени в Выжженные земли.", description = "Я найду вам вашего грифона, но вначале вы должны кое-что сделать для меня. В Зул'Фарраке живет тролль по имени Некрум Кишкожуй, и мне очень-очень нужен его медальон, для изучения. Принесите мне тот медальон, а я найду вам Остроклюва.\n\nЗул'Фаррак лежит за океаном, на западе, в пустыне Танарис.", progress = "Вы достали медальон Некрума, Кавару? В нем сокрыта сила, которую мне не терпится изучить.", completion = "А, медальон Некрума. Говорят, он дарует троллям удивительное долголетие, но за определенную цену. Надеюсь, мне удастся заполучить силу этого медальона и избежать его... побочных эффектов.\n\nВы оказали мне огромную услугу, Кавару. Мне осталось лишь выполнить свою часть соглашения.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2992] = {title = "Прорицание", objective = "Дождитесь, пока Мрачная Тень не закончит ритуал прорицания.", description = "Посторонитесь-ка, мне нужно место, чтобы выполнить ритуал прорицания. Я установлю связь между этим пером и его владельцем, а потом попытаюсь найти и самого Остроклюва.\n\nЕсли все пойдет по плану, то должно получиться, а если нет... Вы, на всякий случай, закройте глаза.", progress = nil, completion = "Ритуал прошел успешно. Я видел Остроклюва и могу сказать, где его найти.", rewards = "Вы получите:\n\n"},
[2993] = {title = "Назад во Внутренние земли", objective = "Поговорите с укротителем грифонов Разящим Когтем.", description = "Остроклюва держат в клетке, на самом верху Джинта'Алора, что во Внутренних землях. Ключ от его клетки находится у коварной жрицы племени Порочной Ветви Ведьмисы.\n\nНу вот, я закончил. Желаю удачи в бою, <имя>.", progress = nil, completion = "Вы поговорили с Мрачной Тенью? Что он сказал?\n\nЧто? Остроклюв у троллей Порочной Ветви? Это немыслимо! Мы непременно должны его спасти!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[2994] = {title = "Спасение Остроклюва", objective = "Пробейтесь в верхнюю часть Джинта'Алора, убейте коварную жрицу Ведьмису, возьмите у нее ключ от клетки и освободите Остроклюва.", description = "Мы должны спасти Остроклюва!\n\nПробейтесь в верхнюю часть Джинта'Алора, отберите ключ у коварной жрицы Ведьмисы, а потом найдите и освободите Остроклюва!", progress = nil, completion = "Быстроветр и Острокоготь минуту назад вернулись вместе со своим детенышем, и теперь от него не отходят. Ох, как гляну на них, аж слеза прошибает...\n\nЯ даже не знаю, чем мы можем отблагодарить вас, Кавару. Грифоны Заоблачного Пика и их всадники навсегда запомнят ваше имя.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМолот наездника на грифонахПоножи наездника на грифоне\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[2995] = {title = "Линии связи", objective = "Оран Змеиные Кольца из Подгорода просит вас отправиться во Внутренние земли и сжечь отчет Высокодолья, заметки Высокодолья и записи Высокодолья.", description = "Сторожка Кель'Данил – центр сообщения Высших эльфов Внутренних земель. Их посланники пытаются установить отношения с другими расами и делятся с ними сведениями о троллях из племени Сухокожих, обитающих в южной части Внутренних земель. Все документы, связанные с этим, хранятся в сторожке.\n\nМы не хотим, чтобы Высокодолье заключало союзы с другими народами, <имя>.\n\nУничтожь документы Высокодолья. Есть мнение, что рукописи не горят… у тебя есть шанс проверить, так ли это.", progress = nil, completion = "Великолепно. Пока эльфы будут восстанавливать утраченную информацию, мы сможем еще навсегда отрезать их от остального мира…", rewards = "Вы получите:\n\n"},
[2996] = {title = "На поиски Страхада", objective = "Поговорите со Страхадом Фарсаном в Кабестане.", description = "Я многому тебя научил, теперь тебе нужен новый наставник. Он живет в Кабестане, его зовут Страхад. Он человек, но он отнюдь не слаб. Он невелик ростом, но силен! Ты уже можешь вызывать более могущественных существ, и он научит тебя этому. Ступай к нему. Он живет в Кабестане, над портом, рядом с башней.", progress = nil, completion = "A busy day in Ratchet, isn't it? How I enjoy watching the toil of a port city. So much mystery, so much adventure... so much ignorance.\n\nIs that hatred I see in your eyes, &lt;имя&gt;? Good, we will put that to good use.", rewards = "Вы получите:\n\n"},
[2997] = {title = "Фолиант Божественности", objective = "Поговорите с Тизой Кузнебой в Стальгорне.", description = "Привет, <имя>. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морога, но когда тебе выпадет свободная минутка, посети Стальгорн и поговори с одной из самых почитаемых наших сестер – Тизой Кузнебой. Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от тебя.\n\nТы можешь найти ее на верхнем этаже Зала Тайн, что в Палатах Магии. Удачи тебе, <имя>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[2998] = {title = "Фолиант Божественности", objective = "Найдите Даториана Ралла в Штормграде и поговорите с ним.", description = "Приветствую тебя, <брат мой/сестра моя>. Даториан Ралл, один из самых влиятельных паладинов Оплота, недавно говорил о тебе. Он считает, что тебе пора пройти некое испытание... Он вообще весьма неплохо о тебе отзывался, надо сказать.\n\nНа твоем месте я бы отправился в Штормград и поговорил с ним – разумеется, если у тебя найдется на это время. Ищи его в Соборе Света: там он проводит большую часть времени.", progress = nil, completion = "Как красив Штормград, не правда ли?..\n\nТвой визит в это время более чем уместен, Rainon.", rewards = "Вы получите:\n\n"},
[2999] = {title = "Фолиант Божественности", objective = "Поговорите с Тизой Кузнебой в Стальгорне.", description = "Привет, <имя>. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морога, но когда тебе выпадет свободная минутка, поднимись наверх и поговори с одной из наших самых почитаемых сестер – Тизой Кузнебой. Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что от тебя ожидается.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[3000] = {title = "Фолиант Божественности", objective = "Поговорите с Тизой Кузнебой в Стальгорне.", description = "Привет, <имя>. Я знаю, что ты рук не покладаешь, помогая жителям Азерота, но когда тебе выпадет свободная минутка, вернись в Стальгорн и поговори с Тизой Кузнебой. Она одна из тех, к кому обращаются самые молодые дворфские паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от всех нас.\n\nYТы можешь найти ее на верхнем этаже Зала Тайн, что в Палатах Магии.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[3001] = {title = "На поиски Страхада", objective = "Поговорите со Страхадом Фарсаном в Кабестане.", description = "Я многому тебя научил, и теперь тебе нужен новый наставник. Он живет в Кабестане, его зовут Страхад. Это человек, но отнюдь не слабый. Также у нас нет причин смотреть на него как на потенциального врага... по крайней мере, пока что. Он обладает силой и заслуживает уважения. Я чувствую в тебе готовность призывать более могущественных существ, и он может обучить тебя этому.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[3002] = {title = "Сфера Гордунни", objective = "Отнести сферу Гордунни Утель'наю в Пристанище Темнотерна в Оргриммаре.", description = "Я, конечно, хорошо знаю своих врагов, и все же я – только воительница, <имя>. Я даже приблизительно не представляю, на что способна эта сфера.\n\nНо я знаю одного мага в Оргриммаре, который сможет рассказать нам о ней больше. Отнеси сферу к нему!", progress = "Что это у тебя, |3-6(орк)?", completion = "Да, Томпсон, занятная вещица…\n\nЭтот шар весьма могуществен, но и очень опасен!", rewards = "Вы получите:\n\n"},
[3022] = {title = "Не кантовать!", objective = "Отнесите тщательно упакованный ящик Эреласу Янтарному Небу в деревню Рут'теран.", description = "<имя>, я вижу, как ты <предан/предана> сему достойному делу. Да, конечно, ты можешь мне помочь!\n\nОтнеси этот ящик с яйцами Эреласу Янтарному Небу. Он друид, и заботится об этих яйцах, помогает вылупиться маленьким гиппогрифам и обучает их. Его можно найти в Тельдрассиле, в маленькой деревушке Рут'теран на юге.", progress = "Еще одна посылочка от Гургл?", completion = "Спасибо за помощь, Эфром. Если бы не мы, гиппогрифы уже вымерли бы. Впрочем, тебе случалось бывать в Фераласе, и ты знаешь не понаслышке, как опустошили землю Гордунни.\n\nЧто ж, ты видишь, как я занят. Можешь идти.\n\nЕще раз спасибо, Эфром.", rewards = "Вы получите:\n\n"},
[3042] = {title = "Троллье месиво", objective = "Принесите 20 фиалов с Тролльим месивом.", description = "Тролли племени Песчаной Бури в Зул'Фарраке делают состав для закалки из песчаника, и я бы не отказался заполучить себе немного этого состава. Он весьма ценится мастерами, так что если ты принесешь мне достаточно, то и вознаграждение будет щедрым.\n\nЗул'Фаррак находится к северу от Прибамбасска. Удачи!", progress = "Принес?", completion = "Отлично! Так много и все отборные! Этот запас я буду расходовать долго…\n\nБлагодарю тебя, Эфром. Прими это в качестве оплаты.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3062] = {title = "Темное сердце", objective = "Принесите темное сердце Эданы Коготь Ненависти Тало Терновому Копыту.", description = "Эдана Коготь Ненависти – царица гарпий из стаи Студеных Ключей, что обитают в руинах к западу отсюда. Эдана – это воплощенное зло. Я слышал, что сердце у нее каменное. Она не ведает иных чувств, кроме ненависти, которую питает ко всему живому. Сразись с Эданой и принеси мне ее темное сердце!\n\nЯ слышал, что гарпии носят при себе рог. Если затрубить в него у камней Когтя Ненависти, в северной части руин, появится царица.\n\nПредставь, как она удивится, когда обнаружит, что это был зов не ее сородичей, но самой смерти!", progress = "Ненависть, которую распространяет вокруг себя Эдана, необходимо остановить!", completion = "Ну, вот теперь я точно знаю, что Эдана мертва! А это сердце я оставлю себе на память о твоем подвиге, Томпсон. Спасибо тебе!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки КрылогребняРемень Крепкорога\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[3063] = {title = "Месть стае Студеных Ключей", objective = "Убейте 4 гарпий из стаи Студеных Ключей, 4 разбойниц из стаи Студеных Ключей, 4 зовущих из стаи Студеных Ключей и 4 убийц из стаи Студеных Ключей по просьбе Тало Тернового Копыта.", description = "В свое время я был закаленным охотником. Не было на свете такого зверя, которого я бы боялся. До тех пор, пока…\n\nЯ был один в лесу, точил свой клинок после жаркой битвы, и тут на меня напали из засады! Меня окружили гарпии, я еле сумел добраться до безопасного места.\n\nЯ еще и теперь как наяву слышу их вопли...\n\nИ с тех пор я уже никогда не мог стать прежним. В душе у меня кипит ненависть – все эти годы я жажду сквитаться с ними!\n\nГарпии из стаи Студеных Ключей водятся к западу отсюда. Отомсти за меня, <имя>.", progress = nil, completion = "Спасибо тебе, Томпсон. Ты возвращаешь покой душе старого таурена.", rewards = "Вы получите:\n\n"},
[3065] = {title = "Простая табличка", objective = "Прочтите простую табличку и поговорите с Франгом в долине Испытаний.", description = "А, <имя>! Тебе тут пергамент прислали, пока тебя не было.\n\nПрочитай, когда время будет. Это, кажется, от Франга, наставника воинов. Он хочет с тобой поговорить. Он обычно сидит в тени у входа в Логово.", progress = "А, еще один |3-6(тролль) в наших рядах! Ты мне подходишь.\n\nС топором тебе пока не управиться, но копье тоже сгодится.\n\nДобро пожаловать в долину Испытаний!", completion = "Наша долина – подходящее место, чтобы упражняться в воинских навыках. Будут вопросы – не стесняйся задавать их кому угодно, а когда решишь, что готов продолжать обучение – возвращайся ко мне. Я ничем не уступаю любому из здешних воинов и охотно обучу тебя всему... хотя и не бесплатно!", rewards = "Вы получите:\n\n"},
[3082] = {title = "Каменная табличка", objective = "Поговорите с Джен'шан в долине Испытаний.", description = "А, <имя>! Тебе тут табличку прислали, пока тебя не было.\n\nПрочитай, когда время будет. Это, кажется, от Джен'шан, наставницы охотников. Она хочет с тобой поговорить.", progress = "Джен'шан видит перед собой могучего охотника! Духи довольны.\n\nТропа охотника – один из древнейших путей этого мира. Орда обратилась к нам, когда пыталась выжить на Азероте. Ее воины попросили обучить их, открыть им наши тайны. Да, они уже были сильны: среди них были и грозные шаманы, и отважные воины. Но путь охотника еще не был их путем...", completion = "Теперь мы учим их пути охотника, а они учат нас другим вещам. Мы теперь одна раса... почти. Мы давнишние союзники. Не забывай об этом, а Джен'шан не забудет о тебе.\n\nДжен'шан научит тебя ремеслу охотника – хорошо научит! Помни: охотника в племени всегда уважают. И тебя ждет большое будущее – помни это!\n\nБудет надо – приходи к Джен'шан. Она тебя научит всему, чему сможет, когда ты будешь готов.", rewards = "Вы получите:\n\n"},
[3083] = {title = "Табличка с письменами", objective = "Прочтите табличку с письменами и поговорите с Руагом в долине Испытаний.", description = "А, <имя>! Тебе тут табличку прислали, пока тебя не было.\n\nПрочитай, когда время будет. Это, кажется, от Руага, наставника разбойников. Он хочет с тобой поговорить.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[3084] = {title = "Руническая табличка", objective = "Поговорите с Шикрик в долине Испытаний.", description = "А, <имя>! Тебе тут табличку прислали, пока тебя не было.\n\nПрочитай, когда время будет. Это, кажется, от Шикрик, наставницы шаманов. Она хочет с тобой поговорить.", progress = "А, Когтик! Рада видеть тебя здесь. У меня немало дел, и учеников хватает, но каждый раз, как ко мне является кто-то из твоего племени, я чувствую, что круг замкнулся: ведь когда-то я сама училась у одного из ваших шаманов!", completion = "Ты, вероятно, уже знаешь, что могущество нам дают стихии. Огонь, земля, вода и воздух – вот наши орудия.\n\nНаша сила исходит от духов предков. Мы должны вести наш народ. Для городов и деревень, где мы бываем, мы должны стать тем же, чем стал Тралл для всей Орды. У нас будут просить совета и защиты. Но чтобы этого добиться, тебе потребуется немало трудов. Когда ты почувствуешь, что у тебя накопилось достаточно сил, приходи ко мне, и я научу тебя всему, чему смогу.", rewards = "Вы получите:\n\n"},
[3085] = {title = "Освященная табличка", objective = "Прочтите освященную табличку и поговорите с Кен'джаем у Логова в долине Испытаний.", description = "А, <имя>! Тебе тут табличку прислали, пока тебя не было.\n\nПрочитай, когда время будет. Это, кажется, от Кен'джая, наставника жрецов. Он хочет с тобой поговорить.", progress = "А-а, ты здесь! Хорошо-хорошо! Духи предупреждали меня, что скоро ты явишься повидаться с Кен'джаем. Я рад приветствовать тебя в долине Испытаний. Это место недолго будет тебе домом, но постарайся научиться здесь всему, чему можно.", completion = "Почаще пускай в ход полученные знания и увидишь, что духи повинуются тебе все лучше и лучше... В какой-то момент тебе поможет старый Кен'джай! Приходи потолковать с мной, когда будешь готов. И если духи согласятся, мы научим тебя кое-чему еще... но только если они согласятся!\n\nНу, ступай, потолкуй со другими здешними жителями. И про меня не забывай.", rewards = "Вы получите:\n\n"},
[3086] = {title = "Табличка с тайными знаками", objective = "Прочтите табличку с тайными знаками и поговорите с Май'ах у входа в Логово в долине Испытаний.", description = "А, <имя>! Тебе тут табличку прислали, пока тебя не было.\n\nПрочитай, когда время будет. Это, кажется, от Май'ах, наставницы магов. Она хочет с тобой поговорить.", progress = "Ага, Ммрргглл, ты уже нравишься Май'ах! Неплохо, неплохо. Уважай Май'ах, и Май'ах будет уважать тебя. Ну, хватит про это. Ты здесь, чтобы учиться магии, а не слушать болтовню Май'ах.\n\nЧему Май'ах тебя не сможет научить, так это одному: как остановить демонов.", completion = "Да, Ммрргглл, скоро ты станешь очень могущественным! И все это узнают... некоторые – на собственной шкуре!\n\nНо берегись! Бойся не орков, не эльфов и не дворфов. Бояться надо тех, кого не увидишь простым глазом. Магия могуча. И иногда заставляет творить то, чего не хочется. А иногда заставляет считать себя сильнее, чем ты есть. Будь терпеливее. Будь умнее.\n\nКогда решишь, что готов учиться, возвращайся к Май'ах. Она тебя всему научит, не беспокойся!", rewards = "Вы получите:\n\n"},
[3087] = {title = "Пергамент с письменами", objective = "Прочтите пергамент с письменами и поговорите с Джен'шан в долине Испытаний.", description = "А, <имя>! Тебе тут пергамент прислали, пока тебя не было.\n\nПрочитай, когда время будет. Это, кажется, от Джен'шан, наставницы охотников. Она хочет с тобой поговорить.", progress = "А, вот и ты! Хорошо. Дженшан тебя ждала.\n\nМногие думают, что путь охотника прост, но Джен'шан тебе скажет: это неправда. На то, чтобы совладать со зверями Дуротара и других земель, нужно не меньше искусства, чем на то, чтобы плести чары или говорить с предками.\n\nБыть может, стрелять из лука или ружья не так опасно, как применять заклинания, но твоим врагам от этого будет не легче.", completion = "Когда мы закончим беседу, поговори с остальными обитателями долины. Они будут просить тебя что-нибудь сделать для них – и каждое такое задание будет для тебя проверкой на прочность.\n\nНаберешься мудрости и опыта – приходи к Джен'шан, она научит тебя новым приемам и навыкам. Возвращайся к Джен'шан как можно чаще.", rewards = "Вы получите:\n\n"},
[3088] = {title = "Исписанный пергамент", objective = "Прочтите исписанный пергамент и поговорите с Руагом в долине Испытаний.", description = "А, <имя>! Тебе тут пергамент прислали, пока тебя не было.\n\nПрочитай, когда время будет. Это, кажется, от Руага, наставника разбойников. Он хочет с тобой поговорить.", progress = "Тс-с, тише! Не доверяю я этому Нартоку. С тем, кто норовит забиться в пещеру глубже меня, лучше не связываться.\n\nНадеюсь, тебе без труда удалось меня отыскать?", completion = "Клан Изувеченной Длани просил меня позаботиться о тебе. Они хотят, чтобы я обучил тебя и сообщал тебе о том, что им нужно. Даже если ты пока не стремишься им помогать – хотя это было бы глупо с твоей стороны, – я обучу тебя всему, чему смогу... за умеренную плату. Возвращайся ко мне, когда решишь, что готов, и мы посмотрим, чему можно тебя научить.", rewards = "Вы получите:\n\n"},
[3089] = {title = "Рунический пергамент", objective = "Прочтите рунический пергамент и поговорите с Шикрик в долине Испытаний.", description = "А, <имя>! Тебе тут пергамент прислали, пока тебя не было.\n\nПрочитай, когда время будет. Это, кажется, от Шикрик, наставницы шаманов. Она хочет с тобой поговорить.", progress = "А, пришел наконец-то! А я уж думать начала, долго ли мне тебя еще ждать. Я отправила пергамент довольно давно, но не была уверена, что его тебе доставили.\n\nНу ладно, довольно болтать. Ты здесь потому, что был избран стать духовным наставником нашего народа.", completion = "Ты станешь тем, через кого говорят предки. Сила стихий будет в твоей власти – достаточно лишь будет протянуть руку. Внести смятение в ряды врагов будет проще простого, а исцелять союзников станет так же просто, как дышать. Помни об этом, когда встретишься с новыми испытаниями. Возвращайся ко мне, если понадобится. Я буду учить тебя новым заклинаниям и наставлю на верный путь, когда ты будешь готов.", rewards = "Вы получите:\n\n"},
[3090] = {title = "Гниющий пергамент", objective = "Прочтите гниющий пергамент и поговорите с Нартоком в Логове в долине Испытаний.", description = "А, <имя>! Тебе тут пергамент прислали, пока тебя не было.\n\nЯ лично стараюсь не иметь дела с чернокнижниками, однако ты его все-таки прочитай, когда время будет. Это, кажется, от твоего нового наставника, Нартока. Он хочет с тобой поговорить.", progress = "Ага, вот и ты... тебя никто не заметил по дороге? Это хорошо.\n\nНаш мир полон глупцов, Демонорох. Даже у великого Тралла есть свои недостатки. Он отказывается от могущества, которое необходимо, чтобы полностью подчинить эти земли! Мы ведь уже не марионетки порождений Пустоты. Мы сами себе господа. Мы горды и могущественны!", completion = "Теперь и ты в наших рядах! Но не обманывайся, Демонорох. Да, ты имеешь доступ к могуществу, которому многие завидуют, но это не означает, что к тебе будут относиться с почтением. Тралл пускает нас в Оргриммар, ведь мы его сородичи – а иначе мы стали бы такими же жалкими, как люди, что держали его в рабстве. И все же будь осторожен. Да, в твоих руках могущество, но если будешь глуп, – погибнешь.\n\nПонадобятся новые заклинания – приходи ко мне.", rewards = "Вы получите:\n\n"},
[3091] = {title = "Простая записка", objective = "Прочтите простую записку и поговорите с Харуттом Громовым Рогом в Лагере Нараче.", description = "Привет, <имя>! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставника воинов Харутта. На твоем месте я бы прочитал ее поскорее.", progress = "А, вот наконец-то и ты, |3-6(Воин). Я не солгал тебе в записке, Коровкинг. Мы тоже таурены особой породы, не как шаманы и друиды нашего племени. Мы не менее важны. Мы те, кто защищает границы, охотится на кентавров и воюет.", completion = "Каждый из нас играет свою роль в племени. Каждый из нас должен проходить одни и те же обряды. Никогда не позволяй гордыне ослепить тебя и заставить думать иначе.\n\nЯ тут обучаю новых воинов, желающих снискать славы в битве и последовать по пути своих предков. Возвращайся ко мне, когда будешь готов, и я научу тебя всему, что умею. Иди, и да пребудет с тобой благословение племени, Коровкинг!", rewards = "Вы получите:\n\n"},
[3092] = {title = "Нацарапанная записка", objective = "Прочтите нацарапанную записку и поговорите с Ланко Дальнострелом на Плато Красного Облака.", description = "Привет, <имя>! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставника охотников Ланко. На твоем месте я бы прочитал ее поскорее.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[3093] = {title = "Руническая записка", objective = "Прочтите руническую записку и поговорите с Милой Рассветной Странницей в Лагере Нараче.", description = "Привет, <имя>! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставницы шаманов Милы. На твоем месте я бы прочитал ее поскорее.", progress = "И вот ты пришел ко мне, быстрее, чем вода падает с неба. Мне приятна твоя поспешность. Она говорит о том, что ты понимаешь, как важен наш разговор и твое присутствие здесь. Я понимаю стихии и говорю с духами нашего народа, не стремясь при этом выбиться в лидеры. Я смогу научить тебя тому же.", completion = "Мы еще не раз встретимся с тобой, и каждый раз ты будешь уходить от меня чуть более сильным... чуть более подготовленным. Твой дух будет пылать подобно Неугасимому пламени.\n\nА теперь ступай, Серошкур, испытай себя! Возвращайся, если тебе понадобится моя помощь.", rewards = "Вы получите:\n\n"},
[3094] = {title = "Зеленая записка", objective = "Прочтите зеленую записку и поговорите с Гартом Вестником Туманов в Лагере Нараче.", description = "Привет, <имя>! Слушай, минуту назад ко мне подошел посыльный и передал вот эту записку для тебя. Думаю, она от наставника друидов Гарта. На твоем месте я бы прочитал ее поскорее.", progress = "Вот и ты! Очень хорошо. Духи предков по всему Мулгору вдруг стали беспокойны, и никто не может понять, что послужило этому причиной. Отныне ты всегда должен будешь прислушиваться к духам природы и становиться их воплощение. Помни это.", completion = "Хоть у нас и ночных эльфов есть что-то общее, не стоит ждать от них хорошего отношения. Гордыня ослепляет их, но это не твоя забота. Сосредоточь свой разум на уроках Матери-Земли, а я научу тебя тому, что знаю, когда ты будешь готов. \n\nПриходи ко мне почаще, Лонго. Ты узнаешь, что Мать-Земля дарует величайшие способности тем, кто полностью посвящает себя ее учению.", rewards = "Вы получите:\n\n"},
[3095] = {title = "Простой свиток", objective = "Прочитайте простой свиток и поговорите с Данналом Штерном в Могильнике.", description = "А, вот и ты! Пока ты <разбирался/разбиралась> с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника воинов Даннала. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", progress = "Итак, ты прибыл. Хорошо. Я слышал, что еще нескольким удалось избежать \"смерти\" и они направляются сюда. Возможно, подобная живучесть пригодится им и в будущем. \n\nБлагодари Сильвану за свою свободу... свободу тела и духа. Хотя тебя по-прежнему мучают чума и ее последствия, ты можешь теперь передвигаться свободно – на вид ты в полном порядке.", completion = "Я здесь, чтобы обучать тебя по мере того, как ты будешь набираться опыта... приходи как только захочешь. Я беру минимальную плату за уроки и научу тебя всему, чему смогу, чтобы ты был достойным бойцом. \n\nА теперь иди и проверь свои боевые навыки. Многое ты поймешь сам со временем, а кое-что я и вовсе не вправе поведать тебе. Просто знай, что в будущем Сильване потребуются помощники – такие, как ты. Ты станешь главной опорой нашего освобождения. Помни об этом.", rewards = "Вы получите:\n\n"},
[3096] = {title = "Зашифрованный свиток", objective = "Прочитайте зашифрованный свиток и поговорите с Давидом Триасом в Могильнике.", description = "А, вот и ты! Пока ты <разбирался/разбиралась> с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника разбойников Давида Триаса. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", progress = "Значит, тебе все же удалось!.. Отлично, с течением времени нам требуется все больше разбойников. Тенеохотники, возможно, захотят отыскать тебя, когда решат, что настал нужный момент, так что не пропадай и не делай ничего такого, о чем мог бы потом пожалеть. Им нужны способные агенты... а не жалкие карманники и дураки.", completion = "Большую часть времени я провожу здесь, в таверне, присматриваясь к новым лицам и новым возможностям. Не суй свой нос, куда не следует, а я сделаю все возможное, чтобы научить тебя кой-чему. Возвращайся ко мне, когда захочешь – посмотрим, будешь ли ты готов выучить пару новых трюков.", rewards = "Вы получите:\n\n"},
[3097] = {title = "Священный свиток", objective = "Прочитайте священный свиток и поговорите с темным священником Дьюстеном в церкви Могильника.", description = "А, вот и ты! Пока ты <разбирался/разбиралась> с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника жрецов Дьюстена. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", progress = "Итак, меж огня, чумы, беспорядков и еще худших бед, еще один \"верный\" стучит в мою дверь. Что ж, позволь поприветствовать тебя, |3-6(Жрец). И дай мне минутку, чтобы я объяснил тебе пару вещей, прежде чем ты решишь, что пора отправляться на поиски того, что притягивает тебя: Священный Свет позабыл о тебе, духи твоих предков – всего лишь сказки, а создания Пустоты не желают тебя. \n\nТы понимаешь, о чем я?", completion = "Есть лишь одно, что ты должен знать: мы выжили благодаря лишь силе воли. В нас есть вера, отличающая нас от других, и с помощью нашей силы мы сможем в корне изменить весь Азерот. Слабые придут, чтобы положиться на тебя. Прокаженные будут звать тебя Господином. А невежественный будет просить тебя об обучении. Моя обязанность – обеспечить тебя необходимыми инструментами, чтобы, когда придет время, ты был готов. По мере накопления опыта навещай меня. Я научу тебя большему, когда настанет время.", rewards = "Вы получите:\n\n"},
[3098] = {title = "Свиток, покрытый письменами", objective = "Прочитайте свиток, покрытый письменами, и поговорите с Изабеллой в церкви Могильника.", description = "А, вот и ты! Пока ты <разбирался/разбиралась> с безмозглыми тварями Плети, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставницы магов Изабеллы. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", progress = "Я знал, что ты придешь ко мне, Жупелица. Не потому, что тебе не хватает духа следовать собственному пути, а потому что мы – родственные души. Мы оба познали боль. Мы оба страдали. А теперь хотим обладать силой, чтобы вернуть принадлежащее нам по праву: эту землю, нашу жизнь и нашу судьбу. Но тебе еще многому предстоит научиться.", completion = "Тебе стоит возвращаться ко мне почаще, если ты хочешь обрести достаточно сил для уничтожения наших недругов. Законы магии по-прежнему относятся и к тебе, Жупелица. Ты узнаешь, что скверна следует за тобой по пятам, аки тать в ночи. Ты узнаешь, что ее прикосновение сродни пагубной страсти. Она будет льнуть к тебе, как трепетный любовник. И все же ты можешь избежать ее. Скверна обретет власть над тобой, только если ты ей это позволишь. \n\nА сейчас иди... возвращайся, когда силы твои возрастут.", rewards = "Вы получите:\n\n"},
[3099] = {title = "Нечистый свиток", objective = "Прочитайте нечистый свиток и поговорите с Максимиллионом в Могильнике.", description = "А, вот и ты! Пока ты <разбирался/разбиралась> с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника чернокнижников Максимиллиона. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.", progress = "Приветствую тебя, брат. Я знал, что твое появление – лишь вопрос времени. \n\nТо, что я сказал, заинтересовало тебя, не правда ли? Я задел правильную струну... нечто внутри тебя знало, что сказанное мною – правда. Хорошо. \n\nЗнай же: я не предаю Сильвану. Если уж на то пошло, она сама признала бы мою правоту, потому что ее собственные воззрения поставили Отрекшихся в то положение, в каком они находятся сейчас.", completion = "Я говорил, что раб всегда останется рабом, кто бы ни был хозяином. Помнишь? Мы оба знаем, что именно этот тип контроля – этот самый вид силы – зовет нас. Мы хотим, чтобы существа служили нам. Мы знаем, что мы более могуществены и заслуживаем большего уважения, чем другие оказывают нам... и теперь мы хотим взять свое. \n\nЯ буду твоим союзником в этой борьбе – борьбе за нашу собственную свободу. Свободу искать своих собственных союзников. Когда почувствуешь, что время настало, возвращайся ко мне – и я научу тебя всему, что знаю.", rewards = "Вы получите:\n\n"},
[3100] = {title = "Обычное письмо", objective = "Прочитайте обычное письмо и поговорите с Лланом Бишером в Аббатстве Североземья.", description = "Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Ллана, местного наставника воинов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.", progress = "А, так ты получил мое письмо, Мойгильдбанк... Это хорошо.\n\nВ последнее время в Элвине прямо-таки наплыв воинов. Для Штормграда это хорошо, а вот местным кобольдам и бандитам из Братства Справедливости приходится несладко, ха-ха.", completion = "Разберись в обстановке, изучи местность и возвращайся, как только тебе потребуется обучение. Я тут в любое время дня и ночи.\n\nРыцари Серебряной Длани постарались, чтобы эти места стали почти безопасными, но если ты поговоришь с горожанами, то, думаю, заметишь, что у всех найдутся проблемы, с которыми без помощи воина не разобраться. Удачи!", rewards = "Вы получите:\n\n"},
[3101] = {title = "Благословенное письмо", objective = "Прочитайте благословенное письмо и поговорите с братом Самуэлем в Аббатстве Североземья.", description = "Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать брата Самуэля, местного наставника паладинов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.", progress = "Наконец-то! Вот мы и встретились, брат мой. Приветствую тебя в Североземье! Это место будет твоим домом, пока ты не усвоишь азы нашего дела, но знай, что Штормград недалеко, и рано или поздно твой путь приведет тебя туда. Ну а пока наберись терпения... рыцарь Серебряной Длани.", completion = "Тебе следует усвоить еще пару вещей. Для многих в этих краях ты станешь примером для подражания, поэтому веди себя соответственно. Отблеск Благодати лежит на тебе – это видят и друзья, и враги.\n\nКроме того, когда ты наберешься опыта, тебе надо будет овладеть новыми способностями. Вот тут я тебе и пригожусь. Когда ты почувствуешь, себя готовым, приходи ко мне, и я научу тебя тому, что тебе, по моему мнению, пора будет узнать. Удачи тебе, |3-6(Паладин)!", rewards = "Вы получите:\n\n"},
[3102] = {title = "Зашифрованное письмо", objective = "Прочитайте зашифрованное письмо и поговорите с Джориком Керриданом в стойлах за Аббатством Североземья.", description = "Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Джорика, одного из наших местных наставников. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.", progress = "Ты добрался сюда в целости и сохранности, и вроде бы тебя никто не заметил. Это хорошо – не люблю лишнее внимание... Думаю, ты меня понимаешь.\n\nЕще ни во что не успел вляпаться? Нет? Здорово! Но ничего, все впереди.", completion = "Многим очень нужны наши умения, Маркроу. Искатели приключений, ШРУ... ха, даже Братство Справедливости не прочь заслать пару-другую шпионов в Штормград. Но не забывай: ты сам себе хозяин. И не давай никому втягивать тебя в то, что тебе не по нраву! Кроме того, у нас все козыри... по крайней мере, пока не кончена игра. Смекаешь?\n\nКороче, я хотел всего лишь представиться и дать тебе понять, что если тебе понадобится обучение, я всегда здесь. Приходи в любое время.", rewards = "Вы получите:\n\n"},
[3103] = {title = "Святое письмо", objective = "Прочитайте святое письмо и поговорите с жрицей Анеттой в Аббатстве Североземья.", description = "Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Анетты, местной наставницы жрецов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.", progress = "Ах, наконец-то ты пришел. Я знала, что ты меня найдешь. Отблеск света Благодати лежит на тебе и избранном тобой пути. Нынешние времена суровы – Пылающий Легион все еще оскверняет своим присутствием Азерот, Калимдор ищет пути избавления от собственных несчастий, и ты должен будешь помогать нуждающимся в меру своих сил.", completion = "Как только ты наберешься опыта, возвращайся ко мне, и я, как сумею, поделюсь с тобой своими знаниями. А пока ступай с милосердием в сердце, и пусть мудрость ведет тебя. Помни, мир станет лучше, только если мы сами исцелим его.", rewards = "Вы получите:\n\n"},
[3104] = {title = "Символьное письмо", objective = "Прочитайте символьное письмо и поговорите с Кельденом Бременом в Аббатстве Североземья.", description = "Меня попросили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем стоит печать Келдена, местного наставника магов. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве.", progress = "Привет, Архимарус. Я – Келден. Чем могу помочь?", completion = "Ха-ха, я знал, что не ошибусь адресом! Значит, ты готов принять свою судьбу? Готов бросить вызов богам и любым другим силам, что встанут на твоем пути к знаниям и могуществу?\n\nНе скрою, Архимарус, тебя будут не только уважать, но и бояться. Но знай и то, что я буду ждать тебя здесь, когда тебе понадобится обучение. Приходи ко мне, когда станешь опытнее.", rewards = "Вы получите:\n\n"},
[3105] = {title = "Тайное письмо", objective = "Прочитайте тайное письмо и поговорите с Друзиллой ла Салле возле Аббатства Североземья.", description = "Меня просили передать тебе это письмо, как только ты вернешься из лагеря кобольдов. Похоже, что на нем печать Друзиллы, одной из наших местных наставниц. На твоем месте я немедленно прочел бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь, в аббатстве.", progress = "Наконец-то ты пришел, Войдус. Представляешь, только что мимо проходили стражники и очень подозрительно на меня косились... жалкие тупицы.", completion = "Чем могущественнее ты будешь становиться, тем сильнее будет искушение... так что не забывай обуздывать себя. Ладно, скажу тебе прямо: любой, кто занимается тайными искусствами, может пасть. Особенно тот, кто имеет дело с тварями из Круговерти Пустоты. Будь терпелив и благоразумен... но не давай благоразумию подавлять твои амбиции.\n\nКак только ты станешь опытнее, возвращайся ко мне, и я открою тебе тайны нашего мастерства.", rewards = "Вы получите:\n\n"},
[3106] = {title = "Простая руна", objective = "Изучите простую руну. Найдите в Холодной долине Трана Кормана и поговорите с ним.", description = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне.", progress = "Холодно сегодня, правда? Кажется, этот снег никогда не растает.\n\nДумаю, сложно не заметить, что в нашем городе поселились гномы, так ведь, Хрофорт? А все почему? Да потому, что они подорвали свой собственный дом, вот и прибились к нам. Но знаешь что? Я их не осуждаю. Если бы в Стальгорн пролезла подобная пакость, я бы тоже стал подумывать о взрывчатке...", completion = "Я думаю, ты это уже знаешь, но на всякий случай скажу: в бою дворфы используют магию вместо ружей. Кое-кто из нас чтит Священный Свет – так же, как и некоторые люди, и даже трогги. А вообще, тебе еще многое предстоит узнать.\n\nЯ буду учить тебя воинскому мастерству. Если захочешь узнать пару новых приемов, приходи сюда, и мы посмотрим, что я могу для тебя сделать.", rewards = "Вы получите:\n\n"},
[3107] = {title = "Священная руна", objective = "Изучите священную руну. Найдите в Холодной долине Бромоса Груммнера и поговорите с ним.", description = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Бромос, наставник паладинов. Если представится случай, отыщи его в Старой Наковальне.", progress = "Итак, ты здесь – и очень вовремя. Нам многое предстоит сделать в Холодной долине – а может, и за ее пределами. Мне понадобится твоя помощь, а тебе, несомненно, будет нелишней моя.\n\nТеперь ты рыцарь Серебряной Длани: не забывай об этом!", completion = "Люди многое поведали нам о Священном Свете и о том, как орден паладинов необходим им – и всему Азероту. Мы испытываем огромное уважение к традициям ордена. Поистине поразительно, что один человек, одна жертва может обратить погибель в спасение.\n\nДумаю, нам обоим придется немного поработать вместе. Когда ты решишь, что время пришло, возвращайся ко мне: тебе нужно будет научиться кое-чему новому, прежде чем браться за дело. Негоже отправляться в далекие странствия неподготовленным, верно?", rewards = "Вы получите:\n\n"},
[3108] = {title = "Гравированная руна", objective = "Изучите гравированную руну. Найдите в Холодной долине Торгаса Мрачнона и поговорите с ним.", description = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Торгас, наставник охотников. Если представится случай, отыщи его в Старой Наковальне.", progress = "Ага, наконец-то ты пришел! Рад тебя видеть, честное слово! Надеюсь, тебе не пришлось распутывать следы, чтобы меня найти? Ха-ха!\n\nНаша профессия основана на древних традициях, которые мы свято чтим, Свинцемёт. Чтобы научиться понимать природу и выслеживать медведя в горах – да и просто чтобы выжить в одиночку, – требуется мужество, ум и хитрость. Как ты думаешь, у тебя есть все это?", completion = "Всегда нужно помнить об уважении к тому миру, в котором мы живем. Звери, которые решат сражаться на твоей стороне, сияние клинка, тяжесть брони, пронизывающий холод ветра – без всего этого твоя жизнь будет не полна.\n\nЯ сделаю все, что смогу, чтобы познакомить тебя с ремеслом охотника, но знай: самое главное зависит от тебя. Когда ты решишь, что готов, приходи ко мне, и мы займемся твоим обучением.", rewards = "Вы получите:\n\n"},
[3109] = {title = "Зашифрованная руна", objective = "Изучите зашифрованную руну. Найдите в Холодной долине Сольма Харгрина и поговорите с ним.", description = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне.", progress = "Ага! Ты наконец-то пришел! Прекрасно!\n\nУ нас тут такие дела творятся! Любая помощь пригодится, уж ты мне поверь. Раз уж ты здесь, то наверняка знаешь, что нет ничего лучше холодной клинка в руке и тени, защищающей получше любой брони, так ведь?", completion = "Я вот думаю: если ты собираешься шататься по Холодной долине, рано или поздно тебе потребуется усовершенствовать свои навыки, согласен? Так вот, если тебе это будет нужно, приходи, и я научу тебя тому, что знаю: обманный выпад,  хитрый приемчик... Понимаешь, о чем я? Эти трюки позволят тебе остаться в живых и заработать несколько звонких монет.\n\nДа, и приглядись повнимательнее к гномам: им несладко приходится с тех пор, как Гномреган был... скажем так, захвачен. Думаю, наша помощь им пригодится.", rewards = "Вы получите:\n\n"},
[3110] = {title = "Благословенная руна", objective = "Изучите благословенную руну. Найдите в Старой Наковальне Бранстока Халдера и поговорите с ним.", description = "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи ее, когда будет время. Думаю, руну прислал Брансток, наставник жрецов. Если представится случай, отыщи его в Старой Наковальне.", progress = "А, вот и ты, Хэллка! Отлично!\n\nЧестно говоря, я уже почти утратил веру в то, что ты придешь... Почти утратил веру, понимаешь? Ну, это шутка была… Что? Не смешно? А, забудь! В любом случае, ты ведь шла сюда не за тем, чтобы слушать мои шутки.", completion = "Я – тот, кто будет заниматься твоим обучением. Когда будешь готова, приходи ко мне: может быть, одно-два новых заклинания помогут тебе быстрее очистить долину от этих отвратительных троггов.\n\nСвет на твоей стороне, Ягамля, а с ним и весь Стальгорн... Эй, ты что разволновалась? Это тебя ни к чему не обязывает... ну, почти ни к чему...", rewards = "Вы получите:\n\n"},
[3112] = {title = "Записка", objective = "Прочитайте записку и поговорите с Траном Корманом в Старой Наковальне.", description = "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне.", progress = "О, а вот и еще один гном, отправляющийся на поиски приключений... Решимость в глазах, сжатые кулаки...\n\nНу ладно, ладно, успокойся, я вовсе не собирался тебя дразнить. Я, не поверишь, даже уважаю твою решимость. Судьба гномов мне отнюдь не безразлична – я вместе с вами скорблю о потере Гномрегана.", completion = "Да-да, теперь я окончательно понял, чего хотят гномы. И знаешь что? Даю слово, я сделаю все возможное, чтобы ты и твои родичи смогли отвоевать свой дом.\n\nДа, вот  еще что: когда почувствуешь, что готов к обучению, приходи к старине Трану – я с радостью поделюсь с тобой всем, что знаю. Конечно, не за просто так, но ты можешь не беспокоиться: цена невысока. Ну, до встречи!", rewards = "Вы получите:\n\n"},
[3113] = {title = "Зашифрованная записка", objective = "Прочтите зашифрованную записку. Найдите Сольма Харгрина в Старой Наковальне и поговорите с ним.", description = "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне.", progress = "Рад тебя здесь видеть – это значит, мое послание нашло адресата. Прости, что заставил тебя поверить, будто это послание от кого-то свыше. Понимаешь, таким, как мы, сейчас лучше держаться вместе.\n\nМногим кажется, что двум разбойникам в одном городе не ужиться, но я думаю, мы отлично сработаемся. Как ты считаешь?", completion = "Я стараюсь не привлекать к себе особого внимания, так что если где-то что-то и пропадает, наша репутация от этого не страдает. Если тебе потребуется чему-нибудь подучиться или еще что, приходи в любое время.\n\nНу, мы ведь с тобой друг друга понимаем? Мы-то знаем, что бывают времена, когда верить можно только семье... и такие времена сейчас настали, верно? Гномреган... захвачен, и, думаю, это была не последняя беда, которая на нас свалилась... но мы с тобой всегда прикроем друг другу спину, да?", rewards = "Вы получите:\n\n"},
[3114] = {title = "Таинственная записка", objective = "Прочитайте таинственную записку. Найдите в Старой Наковальне Маррайка Нуррибита и поговорите с ним.", description = "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Маррайк, наставник магов. Если представится случай, отыщи его в Старой Наковальне.", progress = "Ну да, |3-6(гном), я слушаю. В чем дело? Давай же, говори, в конце концов! Только учти, что после пары-тройки стаканов слух у меня становится не очень.", completion = "О, да! Тайная магия... Конечно-конечно...\n\nПервое, что тебе следует усвоить, Даларон, – это очень простой урок: не ищи неприятностей. Поверь, они найдут тебя сами. А если ты сбережешь несколько монет, то сможешь купить мне кружку эля... или какое-нибудь заклинание для себя. Да, еще совет: держись подальше от Гномрегана. Пока, думаю, с тебя хватит. Доброго тебе пути! Захочешь подучиться – приходи в любое время.", rewards = "Вы получите:\n\n"},
[3115] = {title = "Гниющая записка", objective = "Прочтите гниющую записку. Найдите в Старой Наковальне Аламара Мрачнна и поговорить с ним.", description = "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Аламар, наставник чернокнижников. Если представится случай, отыщи его в Старой Наковальне.\n\nДа, <имя>, вот еще что... будь осторожнее. Таким, как ты, тут не слишком-то доверяют.", progress = "Wonderful! You got my memorandum obviously.\n\nIgnore the fools around you, <имя>. The Holy Light?! The sword and shield?! These aren't paths for ones as open minded as us. Look at what \"normal\" magic did to our home. Coupled with  those damned tinkerers, our race almost became extinct. And now we have to rely on the dwarves-- they'd rather spend time allying with humans than help us rebuild our own home. We're like second-class citizens. Have you seen the way they look at us?", completion = "But none of that matters. What matters is that you've seen your own Holy Light! You know where power truly comes from. You realize that having our own allies is much more... prudent. Special allies. Allies that, no matter the task, will obey till their last breath.\n\nAnd that's where I come in, &lt;имя&gt;. I can train you in the beginnings of those special powers. Seek me out often and I will do what I can to teach you more spells.", rewards = "Вы получите:\n\n"},
[3116] = {title = "Простой знак", objective = "Изучите простой знак и поговорите с Алайссией в Тенистой долине.", description = "Этот знак был передан мне посланником нашей наставницы воинов, Алайссии. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Алайссии.", progress = "Я рада, что ты здесь.\n\nМногое случилось за последние годы, Ашалисс: создание Тельдрассила, порча, павшая на множество лесных обитателей здесь и в округе, обнаружение земель, которые мы считали для себя потерянными, например, Фералас... так много, и все за столь короткое время. Но это лишь некоторые из причин, по которым мы здесь, важнее всего – защитить наш род от зла.", completion = "Вскоре ты увидишь на ветвях нашего дома представителей других рас – но не поддавайся предубеждению. Они здесь приняты как гости. Они помогут нам, когда смогут помочь. Не все они действуют из альтруизма, однако всем им можно в некоторой степени доверять. \n\nНо все это сейчас не в счет. Мы должны подумать о тебе и о том, как ты сможешь помочь нашему народу. Я здесь именно ради этого. Я буду учить тебя действовать как воин по мере того, как ты будешь обретать силу. Возвращайся ко мне, когда пожелаешь, – и я сделаю все возможное, чтобы помочь тебе.", rewards = "Вы получите:\n\n"},
[3117] = {title = "Выгравированный знак", objective = "Изучите выгравированный знак и поговорите с Аянной Вечнобродкой на верхушке Альдрассила в Тенистой долине.", description = "Этот знак был передан мне посланником нашей наставницы охотников, Аянны. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Аянне.", progress = "Ты наконец-то здесь, Снайперметкй, хотя и не так скоро, как я надеялась. Добро пожаловать в Тенистую долину.\n\nНадеюсь, ты получила мое послание, будучи в добром здравии и расположении духа?\n\nКак я говорила ранее, я намереваюсь обучить тебя охотничьему мастерству: приручению зверей, которые помогут тебе в бою, стрельбе из лука с безукоризненной меткостью и уважению к землям, которые мы зовем домом, так и к тем, что лежат за очерченными нами пределами.", completion = "Когда обретешь достаточно опыта в Тенистой долине, приходи ко мне – я помогу тебе постичь умения охотника и осознать твои собственные возможности.\n\nЭто опасные времена, Снайперметкй, и даже умения твоих питомцев нельзя принимать как должное – в мире существуют вещи куда более опасные, нежели ты можешь вообразить. Да хранит тебя Элуна, Снайперметкй, я буду ждать твоего возвращения.", rewards = "Вы получите:\n\n"},
[3118] = {title = "Зашифрованный знак", objective = "Прочтите зашифрованный знак и поговорите с Фрагуном Шепотом Тени в Тенистой долине.", description = "Этот знак был передан мне посланником нашего наставника разбойников, Фрагуна. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Фрагуну.", progress = "Привет, Юли. Рад, что тебе удалось меня найти, а то я уж думал, что ты заблудилась по пути.\n\nНа самом деле в Тенистой долине ничего особенного не случилось с тех пор, как я послал знак, но, пожалуй, сбором информации тебе лучше заняться самой. Поговори с остальными эльфами, живущими около Альдрассила.", completion = "Но до тех пор знай, что в эти трудные времена услуги разбойников востребованы гораздо больше, чем обычно. Мирные отношения с другими расами могут рухнуть в любой момент, к тому же ходят слухи о представителях Орды, ищущих, как бы посеять семена еще большего недоверия. Помни об этом.\n\nПо мере того как будешь становиться более опытной и обретать силы, приходи сюда, и я позабочусь о твоем обучении. Тебе важно знать, помимо всего прочего, как обращаться с выбранным оружием.", rewards = "Вы получите:\n\n"},
[3119] = {title = "Благословенный знак", objective = "Прочтите благословенный знак и поговорите с Шандой в Альдрассиле.", description = "Этот знак был передан мне посланником нашей наставницы жрецов, Шанды. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Шанде.", progress = "Рада видеть, что тебя ничто не задержало в пути, Болотниту. Добро пожаловать.\n\nТебе, наверное, доводилось слышать, что в Тельдрассил постоянно прибывают новые путешественники. Даже членам Альянса было позволено ступать на ветви Тельдрассила для того, чтобы встретиться с другими кальдораями, готовящимися к грядущим приключениям.", completion = "Пока что не беспокойся о мире за пределами Тельдрассила – еще успеешь. Иди теперь и поговори с остальными, живущими в Тенистой долине, – они расскажут тебе о том, что тут происходит. Помогай им в том, в чем сможешь, и в любой момент, когда тебе нужно будет обучение, возвращайся сюда, и я научу тебя всему, что знаю сама.", rewards = "Вы получите:\n\n"},
[3120] = {title = "Зеленый знак", objective = "Прочтите зеленый знак и поговорите с Мардантом Крепким Дубом на древе Альдрассил в Тенистой долине.", description = "Этот знак был передан мне посланником нашего наставника друидов, Марданта. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Марданту.", progress = "А, это ты, юный |3-6(Друид). Вижу, ты желаешь продолжить свое обучение. Это хорошо.\n\nСкажи, известно ли тебе, что такое Изумрудный Сон? Хотя, возможно, ты еще к этому не готов... Ну ладно, всему свое время.\n\nПока что обсудим другие вопросы.", completion = "Отныне я буду твоим наставником. Мой долг не только научить тебя истолковывать то, что вещают нам духи, но и дать тебе представление о сложностях и тайнах Изумрудного Сна.\n\nПо мере обучения ты узнаешь больше о нашем сонном трансе. Но пока что приходи ко мне так часто, как сочтешь нужным, и я обучу тебя всему, следуя традициям ночных эльфов.", rewards = "Вы получите:\n\n"},
[3121] = {title = "Странная просьба", objective = "Отнесите сушеную голову Нииру Огненному Клинку в Оргриммар.", description = "Для начала мне понадобится помощь Нииру Огненного Клинка из Оргриммара! Он изготовил состав, который нужен мне для... ну, потом увидишь.\n\nВ общем, ступай в Оргриммар. Да, и захвати с собой вот это. Это мумифицированная голова, которую я обещал Нииру в обмен на его травки. Какой-то злосчастный дворф, с которым я повстречался в лесу... Думаю, Нииру останется доволен.\n\nИщи его в расселине Теней.", progress = "Да?", completion = "О, я давно ждал, когда Узери ее пришлет…\n\nА вот и смесь трав, которую я изготовил для его... экспериментов.", rewards = "Вы получите:\n\n"},
[3122] = {title = "Возвращение к знахарю Узер'и", objective = "Отнесите знахарю Узер'и в Фералас мешочек для трав Нииру.", description = "Вот травы, <имя>. Отнеси их знахарю Узер'и.\n\nИ, пожалуйста, передай ему, что сушеная голова – то, что надо.", progress = "Ну что, поговорил с Нееру?", completion = "Да, Томпсон, это именно то, что мне нужно, чтобы изготовить сосуд уменьшения! Скоро увидим, так ли могущественны мои последние заклинания, как я рассчитывал!\n\nТак, минутку... Мне надо совершить ритуал и использовать травы...", rewards = "Вы получите:\n\n"},
[3123] = {title = "Испытание сосуда", objective = "Отправляйтесь во Внутренние земли, найдите диких совухов, убейте 10 особей и используйте сосуд уменьшения, чтобы уменьшить и пленить павших диких совухов.\n\nОтнесите 10 уменьшенных диких совухов знахарю Узер'и в Фералас.", description = "Это будет испытание – испытание созданного мною ритуала, и твоих способностей тоже. Возьми этот сосуд, <имя>. С его помощью ты сможешь уменьшать и помещать внутрь него разных существ.\n\nОтправляйся во Внутренние земли и отыщи существ, которых называют дикими совухами. Они некогда были питомцами богини Элуны, которую почитают ночные эльфы. Коварные и дикие совухи станут твоей первой добычей, <имя>. Убей 10 и с помощью сосуда уменьшения возьми их души в плен, пока они не успели ускользнуть.", progress = "Ну что, удалось тебе взять в плен дикосовухов?\n\nЕсли тебе это удастся, мы сможем подчинять себе и других существ Фераласа...", completion = "Дух существа, преданного насильственной смерти, может вырваться на волю и попытаться отомстить. А помещая их в сосуд уменьшения, мы препятствуем духу вырваться на свободу. И теперь мы можем использовать его, как нам угодно!", rewards = "Вы получите:\n\n"},
[3124] = {title = "Уменьшенный гиппогриф", objective = "Убейте 10 блеклоперых гиппогрифов любого вида, затем используйте сосуд уменьшения, чтобы уменьшить и пленить их.", description = "Ты уже <доказал/доказала>, что на тебя можно положиться, и ты умеешь обращаться с сосудами уменьшения. Теперь я попрошу тебя пленить другое создание.\n\nГиппогрифы в течение многих лет были верными спутниками ночных эльфов, и души их тверды и преданны.\n\nТвоя задача – убить 10 блеклоперых гиппогрифов, быстро уменьшить их и загнать в сосуды, чтобы сохранить таким образом их души. Гиппогрифов можно найти в Высокогорных дебрях, к югу отсюда.", progress = "Ну что, удалось тебе взять в плен гиппогрифов?", completion = "Если мы убьем существо и позволим его духу ускользнуть, оно может превратиться в куда более могущественное создание! И тогда оно будет вечно грозить нам местью.\n\nЯ поручил тебе опасную работу, Томпсон. Но тебе удалось с ней справиться.", rewards = "Вы получите:\n\n"},
[3125] = {title = "Уменьшенный лесной дракончик", objective = "Убейте 8 летучих хамелеонов или радужных дракончиков. Используйте сосуд уменьшения, чтобы пленить павших лесных дракончиков.", description = "<имя>, теперь я попрошу тебя отловить существо, которое на вид кажется довольно хилым, но дух его могуч, а это – именно то, что нам надо. Лесные дракончики, о которых я говорю, были союзниками ночных эльфов. Нам надо поймать такого дракончика, чтобы Орда тоже могла воспользоваться силой его духа.\n\nУбей 8 летучих хамелеонов или радужных дракончиков, и плени их души. Эти существа водятся к западу отсюда.", progress = "Ну что, удалось тебе наловить лесных дракончиков?", completion = "Спасибо, Томпсон! Теперь нам будет доступна сила духа лесных дракончиков.\n\nНадеюсь, ты не откажешься поработать на меня еще немного?", rewards = "Вы получите:\n\n"},
[3126] = {title = "Уменьшенный древень", objective = "Убейте 3 бродячих лесных древней. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших древней.", description = "Следующей нашей добычей, <имя>, станут бродячие лесные великаны, живые деревья. Ночные эльфы считают древней своими союзниками в борьбе против Орды. Движения древней медлительны, но в качестве защитников они незаменимы!\n\nИ вскоре мы сможем использовать их мощь в своих целях.\n\nОтыщи 3 бродячих лесных древней, убей их и используй этот сосуд уменьшения, чтобы пленить их души!", progress = "Ну что, удалось тебе взять в плен души бродячих древней?", completion = "Спасибо, Тузвколоде! Наше собрание уменьшенных существ почти готово...", rewards = "Вы получите:\n\n"},
[3127] = {title = "Уменьшенный горный великан", objective = "Убейте 7 сухопутных бродяг или скальных великанов. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших скальных великанов.", description = "Последнее, что от тебя потребуется – это отправиться на северо-запад и отыскать основного противника.\n\nКогда Пылающий Легион явился в мир, горные великаны спустились с гор, чтобы помогать ночным эльфам. Ты без труда обнаружишь их: они огромного роста, и когда они поблизости, земля начинает дрожать под ногами.\n\nЯ жажду подчинить себе подобную мощь! Убей 7 горных великанов и используй сосуд уменьшения, чтобы пленить их могучие души!", progress = "Ну что, удалось тебе взять в плен горных великанов?", completion = "Только представь себе, Томпсон, какими возможностями мы теперь обладаем! С теми материалами, которые тебе удалось собрать, я могу сколько угодно уловлять души этих созданий.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3128] = {title = "Природные материалы", objective = "Принесите 2 расколотых бревна, 6 минералов, покрытых коркой, 20 кусков упругих сухожилий и 40 металлических фрагментов знахарю Узер'и в Лагерь Мохаче.", description = "Для выполнения моего замысла мне нужны некоторые материалы... Будешь выполнять другие мои поручения – поищи заодно и то, что я тебя попрошу.\n\nВо-первых, расколотый ствол фераласского древня. Во-вторых, покрытые коркой минералы – эти можно добыть у горных великанов и волшебных драконов на западе. Кроме этого, добудь мне упругих сухожилий совухов из Внутренних земель либо гиппогрифов из Фераласа. И, наконец, мне потребуется большое количество металлических фрагментов, какие найдутся у любого из перечисленных созданий.", progress = "Ну что, удалось тебе собрать нужные материалы?", completion = "Отлично! Все это, вкупе с духами животных, позволит мне изготовить именно то, что нужно!", rewards = "Вы получите:\n\n"},
[3129] = {title = "Оружие духа", objective = "Подождите, пока знахарь Узер'и готовит оружие.", description = "Вселить дух животного в оружие – процесс непростой! Теперь, когда у меня есть все необходимые материалы и души пойманных тобой созданий, я могу приступить к делу. Погоди немного, я скоро вернусь.", progress = nil, completion = "Ну что ж, Томпсон, выбирай, что тебе больше по нраву! В это оружие навечно заточены души могучих созданий.\n\nТеперь их сила – твоя сила.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСила ГиппогрифаДух лесного дракончикаСила древняЗавещание Горного великана\n\nВы также получите:\n\n"},
[3130] = {title = "Борьба с Гребнем Ненависти", objective = "Явитесь к Латроникусу Лунному Копью в Крепость Оперенной Луны.", description = "В данный момент я собираюсь направить тебя к своему заместителю, Латроникусу. Он следит за боевыми приготовлениями наг. Сама же я буду продолжать осуществлять общее наблюдение. Как бы мне ни хотелось нанести им удар всеми имеющимися у нас силами, оставить крепость беззащитной перед атаками Орды – а может быть, и кого-то похуже, – не представляется разумным.\n\nКак бы то ни было, Латроникус тебя ждет. Пока что ты <показал/показала> себя молодцом, <имя>. Продолжай в том же духе!\n\nМожешь идти.", progress = nil, completion = "Что ж, Эфром, отлично: я ценю готовность сражаться в тех, с кем имею дело.\n\nГенерал Лунное Перо поручила мне подготовить нападение на наг. Мои планы состоят из двух частей: во-первых, мы ослабим их силы и лишим командования, а во-вторых, выясним, что же они делают в этих развалинах. С твоей помощью мы сумеем задать нагам перцу, не ослабляя защиты крепости.", rewards = "Вы получите:\n\n"},
[3141] = {title = "Лорамус", objective = "Послушайте, как Лорамус Многоног рассказывает свою историю.", description = "Так ты хочешь вступить в сражение с демонами? Тебе лучше для начала услышать то, что я скажу.", progress = nil, completion = "Да будет так...", rewards = "Вы получите:\n\n"},
[3161] = {title = "Газ'ридианские украшения", objective = "Марвон Клепальщик из Танариса поручил собрать 30 газ'рилловых украшений.", description = "Я ученый, но в душе – кладоискатель!\n\nДавным-давно, когда в этих землях жили тролли, они обожествляли Газ'риллу, огромную гидру, и создали множество украшений в форме ее тела. Их вырезали из особого материала, я называю его \"газ'риллий\" в честь богини-гидры.\n\nЯ и сам ухитрился найти несколько образцов, но для исследований этого не хватает – может, ты мне еще принесешь?\n\nЯ даже создал детектор, позволяющий мигом обнаружить газ'риллий! Надень его и приступай к поискам!", progress = "У тебя возникли затруднения?\n\nГаз'рилловые украшения можно найти по всему Танарису, Тузвколоде, так что разуй глаза!", completion = "Отлично; как раз то, что нужно для исследований. Огромное спасибо за помощь, Тузвколоде.\n\nМожно, я заберу свой шлем?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМундир геодезистаПосох Знаний\n\nВы также получите:\n\n"},
[3181] = {title = "Рог чудовища", objective = "Отнести гигантский рог Маргола горному пехотинцу Щебеночке.", description = "Гигантский рог испещрен многочисленными сколами и царапинами, кроме того, из него торчит непонятный металлический предмет. \n\nОсмотрев рог более внимательно, вы понимаете, что металлический предмет есть ничто иное как обух секиры, сорванный с рукояти. На нем виднеется гравировка:\n\n\"Принадлежит горному пехотинцу Щебеночке\".\n\nКогда вы пытаетесь вытащить обух секиры из рога, он рассыпается на кусочки. \n\nОпаньки...", progress = "Нет, я не открою тебе ворота.", completion = "Что это у тебя? Бессовестная подделка, вестимо! \n\nЯ встречалась с Марголом один на один, и могу ответственно заявить тебе – рог у него раз в восемь больше, чем вот эта твоя закорючка! Небось, выдрал ее из какого-нибудь несчастного грозорыла в Степях. Нет, милый, ты не обманешь Щебеночку!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3182] = {title = "Доказательство собственности", objective = "Отнесите гигантский рог Маргола куратору Ториусу в Стальгорн.", description = "Ты думаешь, я поверю этим россказням? Если бы это был настоящий рог, из него до сих пор торчал бы обух моей секиры.\n\nВот что, неси-ка свою подделку куратору Ториусу в Стальгорн. Если он признает, что твои слова – правда, он даст тебе доказательство. Принеси его мне, и я дам тебе ключ к Тлеющему ущелью.\n\nИди, иди!", progress = "Приветствую вас, молодой человек! Желаете экскурсию по музею?", completion = "Что это? \n\nЯ не могу поверить! Вы понимаете, что это, |3-6(дворф)? Это же рог Маргола Яростеня! Маргола, причины гибели множества археологов, оказавшихся в Тлеющем ущелье. \n\nМожно мне оставить его себе?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3201] = {title = "Наконец-то!", objective = "Отнесите доказательство содеянного горному пехотинцу Щебеночке.", description = "Не может быть, чтобы Щебеночка усомнилась в подлинности рога. Между нами говоря, думаю, она просто ревнует. Я знаю, она хотела убить чудовище сама.\n\nТак вам, значит, нужно доказательство. Разумеется, вы принесли музею столь ценный дар, что я почту за честь написать для вас свидетельство. \n\n*Куратор Ториус начинает заполнять огромный документ* \n\nНу вот, можете показать его Щебеночке.", progress = "Глазам своим не верю.", completion = "Не понимаю, как мог такой слабак, как ты, одолеть Маргола, но я хозяйка своего слова. \n\nНо если после этого с тобой случится что-то нехорошее, пеняй на себя!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКлюч от Тлеющего ущелья"},
[3221] = {title = "Беседа с Ренферрелом", objective = "Поговорите с аптекарем Ренферрелом в Гробнице.", description = "Пока вы отсутствовали, помогая нашим стражам смерти, за вами приходил аптекарь Ренферрел. Он не рассказывал мне подробностей, но хотел поговорить с вами о волчьих сердцах, что вы ему передали.", progress = nil, completion = "О, хорошо, что вы пришли. Касательно тех волчьих сердец, что вы мне ранее принесли – есть один момент, требующий вашего внимания.", rewards = "Вы получите:\n\n"},
[3261] = {title = "Джорн Заклинатель Небес", objective = "Поговорите с Джорном Заклинателем Небес в Лагере Таурахо.", description = "Вот и закончились наши уроки, <имя>. Не останавливайся на достигнутом, ступай в Лагерь Таурахо на юге и поговори с Джорном Заклинателем Небес. Он станет твоим новым учителем.", progress = nil, completion = "Приветствую тебя, юноша. Ты избрал путь охотника?\n\nЗамечательно. Начнем с азов.", rewards = "Вы получите:\n\n"},
[3281] = {title = "Похищенное серебро", objective = "Принесите украденное серебро Газрогу в Перекресток.", description = "Ящеров-то ты <убил/убила>, но похищенное серебро необходимо вернуть! Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров. Скорее всего они утащили похищенное серебро именно туда.\n\nОтправляйся логово мерзких тварей и поищи наше серебро. Как найдешь – сразу возвращайся ко мне.", progress = "И где серебро?", completion = "Ага! Значит, ящеры все же утащили его в свое логово. Трудно понять, зачем этим тварям серебро. Быть может, в байках об их уме есть зерно правды!\n\nСпасибо, Гронгард. Прими награду за услуги и помни, что стражи перекрестков получили свою месячную оплату лишь благодаря тебе.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги бродягиПоножи поселенца\n\nВы также получите:\n\n"},
[3301] = {title = "Муура Рунический Тотем", objective = "Поговорите с Муурой Руническим Тотемом в Гробнице.", description = "Одна из моих соплеменниц, Муура Рунический Тотем, отправилась в Серебряный бор на помощь нашим союзникам-нежити. Серебряный бор – больной, вымирающий лес, и Муура надеялась вдохнуть в него новую жизнь. Может быть, необычные обитатели Степей подскажут ей, как лучше выполнить задачу.\n\nВозьми образец добытых тобой панцирей и отнеси его Мууре в Серебряный бор. Она остановилась в Гробнице. При удаче, осмотрев панцирь, она придумает, как исцелить это погибающее место.", progress = "Я чувствую, от тебя пахнет пылью Степей, |3-6(Чернокнижник). Ты издалека пришел.", completion = "Что это? Панцирь светится изнутри, словно в нем по-прежнему теплится жизнь. Удивительно! Надо изучить его внимательнее. \n\nСпасибо, Аггромашина. Быть может, в этом панцире сокрыта тайна исцеления бедной израненной земли Серебряного бора.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПояс из хлебного дереваПахарский плащ\n\nВы также получите:\n\n"},
[3321] = {title = "Не ее ли ищете?", objective = "Дождитесь, пока Трентон закончит работу.", description = "Ты много <сделал/сделала> для Ордена, <имя>. Обычный искатель приключений не выдержал бы такой нагруки. Ни я, ни Гальван не сомневаемся, что ты <стал одним/стала одной> из нас.\n\nПоэтому мне кажется, что ты заслуживаешь награды. Сущий пустяк, побрякушку. Может быть, ты знаешь о ее свойствах. Должно быть, именно из-за них ты и <пришел/пришла> к нам.", progress = "Сегодня мы отпразднуем твое вступление в Орден.", completion = "Войди же в круг равных, кузнец Ордена Мифрила.", rewards = "Вы получите:\n\nМерцающий мифриловый талисман"},
[3341] = {title = "Да сгинет Хладовей", objective = "Эндрю Браунелл поручил вам убить Амненнара Хладовея и принести его череп.", description = "В Степях есть уголок, заросший кошмарными колючками. Он называется Курганы Иглошкурых. Хотя с первого взгляда это место не показалось нам опасным, по последним сведениям все куда серьезнее…\n\nЖивущие в холмах свинобразы поддались злому влиянию Плети. Теперь их действиями руководит лич по имени Амненнар Хладоносец.\n\nУ Амненнара прямая телепатическая связь с Нер'зулом; мы должны прервать ее, <имя>. Да сгинет Хладовей!", progress = "Это очень важное дело, Батявернулся. Мы должны предотвратить попытки Плети пополнить свои ряды.", completion = "Никто не смеет пойти против воли лича, Батявернулся. Однако, такая верность может привести лишь к погибели.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nМеч ПокорителяТалисман Янтарного света"},
[3361] = {title = "Беда беженца", objective = "Принести в Старую Наковальню ларец Феликса, сундук Феликса и ведро с винтиками и вручить все это Феликсу.", description = "Мы изгнали троггов из Гномрегана и уж было собрались праздновать победу, но тут все пошло наперекосяк! Только представь: радиация кругом, а гномы – те, кто еще жив – разбрелись по Дун Морогу...\n\nЯ так торопился, что все свои вещи бросил, да и все инструменты в придачу. Вот тролли – те не растерялись: им что радиация, что грибной дождик... Прибрали все к рукам: и сундук, и ларец, и даже ведро с винтиками не постеснялись прихватить! Все, все уволокли к себе в лагерь, куда-то к юго-западу от Старой Наковальни...\n\nПутешественник из меня никудышный, так я вот тут подумал: может, ты у них заберешь мои вещи и вернешь их мне?", progress = "Я тебе вот что скажу, Айлерон: таким, как я, в этом городе не место. И в Гномрегане-то всякой пакости хватало до того как... Ну, ты меня понимаешь. Вот теперь и тут покоя не дают...\n\nКак насчет моих вещей, а? Представить себе не могу, что с ними могли сделать эти мерзавцы-тролли!", completion = "Ага! Есть! Есть! Тебе удалось найти мои вещи! Я спасен!.. Вот, держи: это, конечно, сущие пустяки, но должен же я тебя хоть чем-то вознаградить за все испытания.", rewards = "Вы получите:\n\n"},
[3362] = {title = "Долина Кактусов", objective = "Тран'рек из Прибамбасска просит вас убить 8 бугристых шипошкуров и 8 корнеплетов из долины Кактусов.", description = "Ты когда-нибудь <был/была> в долине Кактусов? Это опасное место, <имя>.\n\nТам такие жуткие твари, я им ни на минуту не верю! Бугристые шипошкуры и корнеплеты, кажется так они зовутся…\n\nТак или иначе, я хочу попасть в эту долину, но пока там столько шипошкуров, ноги моей там не будет. Вот зачем ты мне <нужен/нужна> – если выкосить часть этих тварей, я могу и решиться на поход. Что скажешь, <имя>? Поможешь мне?", progress = nil, completion = "Они такие огромные? Нет, план меняется…\n\nНо ты-то выполнил свою часть сделки, поэтому вот, держи обещанное.", rewards = "Вы получите:\n\n"},
[3363] = {title = "Оскверненный песнецвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[3364] = {title = "Жгучая бражка", objective = "Отнести жгучую бражку в Старую Наковальню и передать ее Дарнану Мехорезу. Это надо сделать за пять минут, пока бражка не остыла!", description = "Я уже давно должен был доставить эту отличнейшую жгучую бражку в Старую Наковальню Дарнану Мехорезу, да только сначала мне нужно было завезти немного Грелину. Боюсь, к тому времени, как я доберусь до Старой Наковальни, остынет бражка-то!\n\nТы на ногу полегче моего будешь, как я погляжу; вот я и подумал... эта кружка останется горячей еще минут пять, а Дарнан вовсе не охлажденную бражку заказывал, – не пиво, чай! – так что отправляйся-ка ты в путь. Старая Наковальня – это такое поселение в скалах к северо-востоку отсюда.\n\nБлагодарю заранее... и вот еще что, <имя>: не забудь вернуть мою кружку!", progress = "Ну да. Я и есть Дарнан Мехорез. И какое у тебя ко мне дело?", completion = "Отлично! Это именно то, что нужно! Ты погоди пока, эту штуку пить надо, пока не остыла, иначе вкуса того не будет.", rewards = "Вы получите:\n\n"},
[3365] = {title = "Возвращение кружки", objective = "Отнесите кружку хозяину – Нори по прозвищу Гордый Штрек.", description = "Ох, хорошо-то как! Все эти прохладительные напитки – полная ерунда: в морозный денек нет ничего лучше глотка горячей бражки! Даже на душе теплее становится!\n\nВот, держи, <имя>; сделай доброе дело, отнеси эту кружку Нори, ладно?", progress = "Я так понимаю, жгучая бражка попала к старине Дарнану как раз вовремя! А как моя кружка? Надеюсь, ты не забыл, что ее надо было принести обратно?", completion = "Спасибо, Эфром! Ты удивишься, если я расскажу тебе, сколько народу забывает сделать самое простое – вернуть назад кружку. А кружки-то, между прочим, на деревьях не растут! Ну, по крайней мере, в наших краях.\n\nТут у меня есть кое-что для тебя. Я так думаю, усердие нужно вознаграждать, верно ведь?", rewards = "Вы получите:\n\n"},
[3366] = {title = "Светящийся осколок", objective = "Отправляйтесь в Кабестан и выясните, какие секреты скрывает кристалл кошмаров.", description = "Блестящий осколок ярко-зеленый, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство.\n\nПожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[3367] = {title = "Камни Сунтары", objective = "Помогите Дориусу вернуться в Стальгорн.", description = "<Из груди Дориуса вырывается стон> \n\nЯ тяжело ранен, <раса>. Ужасно кружится голова... Думаю, у меня внутреннее кровотечение... \n\nМне нужно добраться обратно в Стальгорн. Помоги мне, <имя>.", progress = "Мне не дойти...", completion = "Письмо выронил Дориус, когда падал.", rewards = "Вы получите:\n\n"},
[3368] = {title = "Камни Сунтары", objective = "Доставьте опаленное письмо Ториусу в Стальгорн. Его можно найти в Зале Исследователей.", description = "Брат! \n\nЕсли ты читаешь эти строки, меня уже нет в живых. Не знаю, кто доставил тебе письмо, но непременно поблагодари и вознагради его. \n\nТеперь о камнях: они существуют и сейчас находятся у клана Черного Железа. С помощью этих камней их главарь, Латорик Черный, удерживает моих соратников по экспедиции в плену. Лишенные рассудка, они день и ночь трудятся над созданием монстра, именуемого Обсидионом. \n\nСпаси их, брат. Это моя последняя воля. \n\nДориус.", progress = "*По лицу Ториуса катятся слезы*", completion = "*Ториус утирает слезы*. \n\nКлянусь Светом, его воля будет исполнена. Клянусь!", rewards = "Вы получите:\n\n"},
[3369] = {title = "Кошмары", objective = "Принесите осколок кошмара Хамуулу Руническому Тотему на Вершине Старейшин.", description = "Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Однако, это осколок не сна, а скорее кошмара.\n\nНе хочу тревожить тебя, <имя>, но лучше будет, отдать его кому-то из старших друидов, как только сможешь.\n\nХамуул Рунический Тотем с Вершины Старейшин, вот кого тебе надо найти. Отправляйся на Громовой Утес, точнее сказать не могу.", progress = "Могу я тебе чем-то помочь?", completion = "Тебя послала Фалла? Давай-ка, взглянем на этот осколок…\n\n*Хамуул вглядывается в осколок.*\n\nОх... Боги…\n\nСпасибо, что принес это мне. О таких вещах вслух не говорят, но я все же предупрежу тебя, есть вещи, с которыми ты можешь не справиться.\n\nЗапомни, в Изумрудном сне все не то, чем кажется...\n\nВозможно в будущем мы встретимся вновь.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОплечье ТалбарТрясинные галоши\n\nВы также получите:\n\n"},
[3370] = {title = "Кошмары", objective = "Принесите осколок кошмара Матренгилу Медвежьей Лапе в Дарнасс.", description = "Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Однако, это осколок не сна, а скорее кошмара.\n\nНе хочу тревожить тебя, <имя>, но лучше будет, отдать его кому-то из старших друидов, как только сможешь.\n\nМатренгил Медвежья Лапа из Круга Кенария, вот кого тебе надо найти. Отправляйся в Дарнасс, точнее сказать не могу.", progress = "Могу я тебе чем-то помочь?", completion = "Тебя послала Фалла? Давай-ка, взглянем на этот осколок…\n\n*Матренгил вглядывается в осколок.*\n\nОх... Боги…\n\nСпасибо, что принес это мне. О таких вещах вслух не говорят, но я все же предупрежу тебя, есть вещи, с которыми ты можешь не справиться.\n\nЗапомни, в Изумрудном сне все не то, чем кажется...\n\nВозможно в будущем мы встретимся вновь.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОплечье ТалбарТрясинные галоши\n\nВы также получите:\n\n"},
[3371] = {title = "Правосудие дворфов", objective = "Вернитесь в Тлеющее ущелье и найдите археологов Дориуса.", description = "Теперь в груди моей зияет черная дыра – там, где было когда-то сердце... Я никогда не смогу смириться с гибелью Дориуса, <имя>. Я сделаю все, чтобы его последняя воля была исполнена – тех, на ком его кровь, должна настигнуть суровая кара. \n\nВозвращайся в Тлеющее ущелье и исполни волю Дориуса – освободи его соратников.", progress = nil, completion = "Оставь меня, спасай остальных!", rewards = "Вы получите:\n\n"},
[3372] = {title = "Отпусти их", objective = "Найдите таинственный артефакт, охраняемый идолослужителями Сумеречного Молота в северо-западной области Тлеющего ущелья.", description = "Отпусти их, <раса>. Даже когда их тела совсем обессилеют, власть Сунтары заставляет их достичь цели любой ценой. \n\nВсе дело в алтаре Сунтары. Отправляйся на северо-запад, там, в холмах над пещерой... Сумеречный Молот хранит реликвию. Добудь ее и возложи на алтарь Сунтары.\n\n*С этими словами умирающий археолог испускает дух*.", progress = "Алтарь пуст.", completion = "Вы возлагаете таинственный артефакт на алтарь Сунтары.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3373] = {title = "Сущность Эраникуса", objective = "Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме.", description = "Вы касаетесь камня и слышите голос, звучащий в вашем сознании.\n\n\"Услышь мою мольбу, о <смертный/смертная>. Имя мне Эраникус из народа зеленых драконов. Мои попытки положить конец богохульным деяниям троллей закончились неудачей. Я вдохнул частицу своей души в этот кристалл. Однако я чувствую, что моя связь с Изумрудным Сном теряется, и меня поглощает хаос. Пожалуйста, помести этот кристалл с купель сущности в моем логове – пусть магия очистит мое сознание от скверны и спасет меня!\"", progress = "Приблизившись к купели, о которой говорил Эраникус, вы снова слышите его голос. \n\n\"Да, смертный эта купель освободит неоскверненную частицу моего разума, заключенную в этот камень. Помести его в купель и позволь магии зеленых драконов очистить мою сущность от скверны. только тогда я обрету истинную свободу и только тогда драконы вновь обретут власть над Аталаи.\"", completion = "Вы помещаете камень в купель сущности. \n\n\"Благодарю тебя, смертный теперь я... О нет! Не может быть! Скверна проклятого бога проникла даже в эту купель! Умоляю! Я чувствую, как сознание покидает меня! БОЛЬНО! Я чувствую, как мою душу поглощает вечный кошмар!\"\n\n\"Умоляю тебя, смертный, Найди одного из зеленых драконов, чтобы он смог прекратить мои мучения! Помоги мне! Я обречен на вечную агонию... Пощади!\"", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nСкованная Сущность Эраникуса"},
[3374] = {title = "Сущность Эраникуса", objective = "Принесите камень Клятвы драконьего выводка Изеры и скованную сущность Эраникуса на Болото Печали. Там вам придется сделать выбор: помогать Драконам Изеры или нет.", description = "Вы приводите в действие Камень клятвы и с его помощью Итар мысленно заговаривает с вами.\n\n\"Приняв силу, заключенную в камне Клятвы, ты соглашаешься помочь мне и драконьему выводку Изеры освободить истерзанную душу Эраникуса. Первая из многих жертв, на которую придется пойти и тебе, и мне – это передать мне камень, в котором заключено то, что осталось от свободной воли Эраникуса.\n\nСделай это, <имя>, и дальше мы будем действовать вместе, чтобы освободить достойную многих жертв душу.\"", progress = "Вот мы снова и на распутье, Кавару. Пришло время делать выбор. Что ты решил, смертный?", completion = "Выбор сделан, начало положено. Пока, на мой взгляд, ты выбирал верный путь. С нынешнего момента от твоих деяний будет зависеть, будет ли так и впредь.", rewards = "Вы получите:\n\n"},
[3375] = {title = "Запасной фиал", objective = "Принесите зелье маны, уголь и сладкий нектар Талвашу де Кисселю в Стальгорн. Получите запасной фиал виденья Талваша.", description = "Хм... тебе нужен еще один фиал виденья? Шутишь? А куда ты <дел/дела> прежний?! У нас и так забот полон рот, <раса>. Эти фиалы на деревьях не растут! Хорошо бы, чтобы росли, я тогда пошел бы да сорвал, потому как другого-то у меня нет!\n\nА чтобы сделать тебе новый, мне нужно следующее: зелье маны, кусок угля и немного сладкого нектара. И не спрашивай зачем, просто принеси, я и тебе сделаю новый.", progress = "Чтобы сделать еще один фиал, мне нужно зелье маны, кусок угля и немного сладкого нектара.\n\nИ безграничное терпение.", completion = "Могучий искатель приключений все принес. Слава мне! Кстати, я соврал – у меня был запасной фиал. Вот.\n\nА чего ты ожидал?! \"Нате-пожалуйста вам другой! Мне, дураку, делать больше нечего, кроме как задарма раздавать магические устройства связи искателям приключений!\" Но ты не беспокойся, все, что ты мне дал, пойдет на изготовление для тебя очередного фиала, когда ты и этот посеешь.\n\nПожалуйста, пусть я ошибусь в тебе – не потеряй еще и этот, ладно?", rewards = "Вы получите:\n\nФиал виденья Талваша"},
[3376] = {title = "Сразить Остроклыка!", objective = "Принесите голову вождя Остроклыка Терновой Мантии Храбрецу Перу Ветра на плато Красного Облака.", description = "<имя> – я слыхала о тебе, <имя>. Возможно, именно тебе удастся то, что не удалось другим. \n\nМы, таурены, сделали это место своим домом, но это далось нам дорогой ценой. Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами. Я хочу, чтобы ты <принес/принесла> мне голову их вождя! \n\nТы найдешь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда.", progress = "Остроклык больше не будет угрожать нам, если ты прнесешь мне его голову, Коровкинг.\n\nМы, таурены, живем охотой, а самая захватывающая охота – та, где ты и сам можешь стать жертвой. Если ты преуспеешь в этом задании, то поймешь, о чем я говорю.", completion = "Само правосудие сегодня направляло твою руку, Коровкинг. Да будет твое деяние предостережением для всех, кто осмелится угрожать нашему дому! \n\nТы заслужил эту награду, юный |3-6(Воин).", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОкрашенные плетеные поножиПерчатки кочевника\n\nВы также получите:\n\n"},
[3377] = {title = "Молитва Элуне", objective = "Выслушайте Зимаэля.", description = "Мне нужна твоя помощь, <смертный/смертная>. Выслушай меня!", progress = "Дай мне закончить.", completion = "Я смирился с тем, что отныне моя судьба – эта клетка, но молитву нужно найти!", rewards = "Вы получите:\n\n"},
[3378] = {title = "Молитва Элуне", objective = "Найдите молитву Элуне и принесите ее Астарии Ловцу Звезд в Дарнасс.", description = "Ты поможешь мне, <смертный/смертная>? Ты отыщешь молитву Элуне?\n\nКак я говорил, молитва выгравирована на золотой табличке, которая теперь, видимо, у одного из этих мерзких идолопоклонников. \n\nЕсли ты сможешь отыскать ее, отнеси табличку Астарии Ловцу Звезд в Дарнасс. Пусть я пришел к вере после того, как совершил много зла этому миру и его обитателям, моя молитва должна быть услышана. А на прощение своих грехов я не надеюсь...", progress = "Что привело тебя в Храм Луны, Революшен?", completion = "Элуна улыбается тебе, Революшен. Ты возвратил к ней потерянную душу. Прими это в знак нашей благодарности.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНаплечники КайлариТяжелые наручи из рунической стали\n\nВы также получите:\n\n"},
[3379] = {title = "Мастер Тени", objective = "Убейте банду похитителей тенешелка, хозяйничающую в Тлеющем ущелье. Нилит полагает, что их пятеро. Вернитесь к Нилит по выполнению задания.", description = "Пауки, которые водятся в Тлеющем ущелье, производят бесценный тенешелк. Как ты знаешь, тенешелк необходим для нашего ремесла. \n\nНе так давно в этих землях появилась шайка браконьеров, бессовестно убивающих пауков в погоне за сиюминутной прибылью. Твоя задача проста: найти их и прикончить. \n\nНачни поиски с северных пределов. \n\nЕсли потребуется помощь, обращайся к Пожару.", progress = nil, completion = "Отличная работа, Вилдан. Прими это в награду – уверена, подобной работы из тенеткани тебе еще не встречалось!", rewards = "Вы получите:\n\nСмутные наручи"},
[3380] = {title = "Затонувший храм", objective = "Найдите Марвона Клепальщика в Танарисе.", description = "Этот мир полон беспокойных духов, <имя>. Среди них есть такие, которые оказались скованы в местах, в которых таится древнее зло, и были поражены скверной.\n\nСлыхал я о храме, сокрытом в глубинах болот – он был погружен туда силами, величие которых недоступно сознанию простого смертного.\n\nЕсли хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Он облазал многие развалины и останки древних поселений. Слыхал я, что недавно он отправился изучать развалины строений троллей в Танарисе.", progress = nil, completion = "О да, я видел затонувший храм собственными глазами. Хочешь узнать о нем побольше? \n\nУж я сразу узнаю настоящего искателя приключений!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3381] = {title = "Встреча с господином", objective = "Принесите 2 неповрежденных пера гиппогрифа Санату Лим-Йо в в Азшару, если хотите говорить с его господином.", description = "О, <юный/юная:r> <раса> <почтил/почтила> визитом Саната. О, это прекрасный день! Я так польщен! Благодарю тебя... \n\nНадеюсь, ты не столь <самонадеян/самонадеяна>, чтобы принять мой сарказм за чистую монету? Скажу прямо: ты мне не нравишься. Однако, речь сейчас не о том, хочу ли видеть тебя я, но о том, желает ли видеть тебя мой господин. \n\nПринеси мне пару перьев гиппогрифа для моих стрел, и я пропущу тебя к господину. Он принимает только тех, кто доказал, что на что-то годен.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nТелепорт в башню Азшары\n\nВы получите:\n\n"},
[3382] = {title = "На абордаж!", objective = "Защитите капитана Ванессу Белтис, ее команду и пассажиров \"Покорителя Горизонтов\" от нападения наг. Капитан Ванесса Белтис должна выжить.", description = "Мы плыли вдоль берега, в поисках места, где бросить якорь. Солнце зашло не более часа назад, и тут они на нас напали. Проклятые наги! \n\nНе знаю, что им было нужно, но они явно этого не нашли. Почему я в этом уверена? Потому что они вернулись! Я оставила пару своих людей охранять долину, чтобы они предупредили нас в случае атаки. \n\nМне жаль, что ты <оказался втянутым/оказалась втянутой> в эту заварушку, но увы, ничего уже нельзя сделать. \n\nТы <готов/готова> биться не на жизнь, а на смерть?", progress = "Это будет жаркая битва...", completion = "Победа! Спасибо тебе! Уф... это был самый жаркий бой за всю мою жизнь. Не знаю как тебя благодарить! \n\nКак жаль, что так много моих людей погибло в этой схватке. \n\nПожалуйста, поговори с моими пассажирами. Многие прибыли сюда по делу и наверняка кому-то из них понадобится помощь. Возможно, тебе будет это интересно. Еще раз благодарю тебя!", rewards = nil},
[3385] = {title = "Черный рынок", objective = "Убейте торговца Ковица и его прихвостня Лязгуна. Снимите с тела сумку и вернитесь к Нилит.", description = "Они называют себя Черным рынком – шайка головорезов, которые готовы купить, продать и украсть что угодно, если цена будет подходящей.\n\nИ что еще хуже, <имя>, они устроили себе логово в Тлеющем ущелье. Искусный торговец Ковиц – их главарь. У него есть связи с местными дворфами клана Черного Железа.\n\nМы должны нанести по ним мощный удар и недвусмысленно дать понять, что здесь им не рады. Убей торговца Ковица и его прихвостня Лязгуна. Принеси мне сумку торговца.\n\nОтправляйся в Котел немедля!", progress = "Торговец еще коптит небо?", completion = "Ты нанес решающий удар по Черному рынку. Теперь эти бандиты дважды подумают, прежде чем отправлять сюда кого-то из своих. \n\nЯ осмотрела сумку – в ней нет ничего полезного. Если тебе приглянется что-то из его барахла, можешь смело оставить себе.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nСмутный поясСумка с товаром Ковиса"},
[3402] = {title = "Черный рынок", objective = "Поговорите с Визгликом в Прибамбасске.", description = "Мне нужно, чтобы ты лично <донес/донесла> весть о кончине Ковиса Визглику в Прибамбасск. Он будет так рад, что непременно щедро наградит тебя.", progress = nil, completion = "Ковис убит? О, счастье! Столько лет этот прохвост творил что хотел, обтяпывал незаконные сделки, устанавливал бессовестно низкие цены, разоряя нас, честных тружеников!", rewards = "Вы получите:\n\nВыкройка: тенетканая маска"},
[3421] = {title = "Возвращение", objective = "Теперь я отправлю тебя назад к лагерю Саната. \n\nНе обращай внимание на его манеры – он груб со всеми, кроме собственного господина. Возможно, однажды его заносчивость сыграет с ним злую шутку.", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nТелепорт из башни Азшары"},
[3441] = {title = "Божественное воздаяние", objective = "Выслушайте Веларока Ветрореза.", description = "Выслушай меня, <cтранник/странница>.", progress = "Дай мне закончить, |3-6(гном).", completion = "Тебе все ясно, |3-6(нежить)? Ты готов действовать?", rewards = "Вы получите:\n\n"},
[3442] = {title = "Неугасимое пламя", objective = "Принесите 4 сердца пламени и 4 меры масла големов Велароку Ветрорезу.", description = "Ты <принял/приняла> правильное решение, <имя>. \n\nНадо нанести удар по самому уязвимому месту – четырем сторожевым башням. \n\nТебе потребуется особый факел, чтобы поджечь их. Над его изготовлением придется потрудиться, кроме того, нужно добыть необходимые ингредиенты. \n\nПринеси мне четыре сердца пламени и четыре меры масла големов, и тогда я сделаю для тебя факел, чье пламя будет неугасимым. \n\nЧтобы достать эти ингредиенты, ищи големов и элементалей.", progress = "Ты принес мне ингредиенты?", completion = "Прекрасно, Чернобог. Все готово к работе.", rewards = "Вы получите:\n\n"},
[3443] = {title = "Древко факела", objective = "Принесите 8 окованных торием кинжалов Велароку Ветрорезу.", description = "Чтобы удержать неугасимое пламя факела, нам необходимо создать особое древко и наложить защитные чары. Начнем с древка.\n\nВ Котловане надсмотрщики и работорговцы из клана Черного Железа используют оружие из зачарованного тория – особенно прочного сплава. Если ты принесешь мне восемь окованных торием кинжалов, я смогу выплавить торий и использовать его для укрепления древка.", progress = "Восемь, Чернобог, мне нужно восемь кинжалов!", completion = "Отличная работа, Чернобог, я просто поражен! Ты не задумывался о смене профессии? Чтобы стать, скажем, детективом? Ну или старьевщиком? Или примкнуть к этим глупеньким гномам, ползающим по побережьям с металлоискателями в поисках сокровищ? Это ведь наверняка твое призвание!", rewards = "Вы получите:\n\n"},
[3444] = {title = "Круглый камень", objective = "Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане.", description = "Мне приходилось бывать в преддвериях затонувшего храма. Зло, таящееся в этом жутком месте окутывает всякого, кто входит туда. Я едва смог выбраться обратно, увязая в липкой грязи, покрывающей пол. Помню, есть там огромный круглый зал со множеством высеченных из камня змей.\n\nНе так давно мне попал в руки круглый камень, на котором была высечена подобная змея. Я велел послать его в мою мастерскую в Кабестане. Забери его оттуда, в возможно, я смогу ответить на твои вопросы.", progress = "Кабестан отсюда совсем недалеко, Томпсон. Дорога туда не займет много времени.", completion = "Да, это тот самый камень. \n\nЗатонувший храм так и стоит у меня перед глазами...", rewards = "Вы получите:\n\n"},
[3445] = {title = "Затонувший храм", objective = "Найдите Марвона Клепальщика в Танарисе.", description = "Слыхал я о храме, сокрытом в глубинах болот – он был погружен туда силами, величие которых недоступно сознанию простого смертного.\n\nЕсли хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Также как и мы с Троясом, он облазал многие развалины и останки древних поселений. Слыхал я, что он отправился изучать развалины строений троллей в Танарисе.\n\nУдачи в поисках, о нем давненько ничего не слышали!", progress = nil, completion = "О да, я видел затонувший храм собственными глазами. Хочешь узнать о нем побольше? \n\nУж я сразу узнаю настоящего искателя приключений!", rewards = "Вы получите:\n\n"},
[3446] = {title = "Во глубине болот", objective = "Найдите алтарь Хаккара в затонувшем храме на Болоте Печали.", description = "В храме я видел зал круглый зал с шестью галереями, каждую из которых украшала змея, высеченная из камня. Я всего лишь дотронулся до одной из них и угодил в ловушку! Произошел сильнейший взрыв – мне несказанно повезло, что остался цел. Лежа там, на краю галереи, я заметил еще одну статую в самом низу зала – что-то вроде алтаря. Алтарь Хаккара, полагаю.\n\nПоложи на алтарь этот знак – думаю, это поможет открыть его секреты.", progress = "Осмотрев статую со всех сторон, вы замечаете небольшое углубление, по форме и размеру совпадающее со знаком, который дал вам Марвон.", completion = "Вы помещаете круглый камень в углубление и слышите негромкий щелчок. \n\nТеперь камень на положенном ему месте... Но что же делать дальше? \n\nПожалуй, стоит осмотреть алтарь...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3447] = {title = "Тайна камня", objective = "Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй.", description = "Все, что я видел в храме, сохранилось в моей памяти лишь урывками, но я постараюсь рассказать тебе все как можно подробней. Круг статуй, сокрытый в храме – весьма опасное место, но я уверен, что там спрятан ключ к великим сокровищам.\n\nКогда я подошел к главному алтарю, в зале зажглись огни. Если тебе удастся разгадать, что они значат, возможно, сумеешь понять и тайны, которые скрывает эта комната.\n\nОднако я должен предупредить тебя, <имя>. В храме заключено великое зло. Какие бы сокровища там не скрывались, древние силы будут яростно защищать их от посягательств.", progress = nil, completion = "Глаз идола ярко сияют даже в полумраке, царящем в храме. Кажется, внутри спрятано что-то блестящее. Вы просовываете руку внутрь статуи и хватаете то, что там лежит. Теперь сокровище Аталаи – ваше!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nУрна Хаккари"},
[3448] = {title = "Передача поручения", objective = "Поговорите с Тимором в Стальгорне.", description = "Недавно мне доверили задачу исследования Азшары – некогда прекрасного края, который эльфы называли домом. Это было в те времена, когда они занимались магией. Теперь же это место скорее опасно, чем прекрасно, но это не остановит нас. Мы перевернем его по камушку, чтобы разгадать загадки нашего прошлого.\n\nМой товарищ Тимор предложил мне помощь в исследованиях, поскольку это и его самого особенно интересует.\n\nУ него здесь в городе есть небольшой дом рядом с Залом Тайн.", progress = nil, completion = "Ах, так вас послал Карик? Я как раз ждал от него известий. Я тут такое узнал об Азшаре... Я знаю, что ночные эльфы живут невероятно долго, но все порой забывают о некоторых... неприятных событиях в их жизни. Это не критика, всего лишь замечание.\n\nДавным-давно там существовали города, возведенные эльфами, которые много знали о магии и других утраченных искусствах. Поскольку я такие вещи изучаю, я начал свои исследования. И открытия мои просто ошеломляющи.", rewards = "Вы получите:\n\n"},
[3449] = {title = "Чародейские руны", objective = "При помощи готовальни сделайте прорисовки руны Бет'Амары, руны Джин'йаэль, руны Маркри и руны Саэл'Хаи. Отправляйтесь на маленький островок близ южного полуострова Азшары и дайте сигнал пилоту Хиггсу Зажигателю забрать их.", description = "Некоторые эльфы в старину почитали магию не меньше самой Элуны. Их самые могущественные маги создали руны и таблички, в которых были перечислены законы чародейства и разгадки их открытий. Они, как правило, выставляли их на всеобщее обозрение, чтобы все могли над ними поразмышлять.\n\nЯ был бы очень рад получить прорисовки этих рун из руин Эльдарата. Чтобы сделать прорисовки, я дам вам готовальню, но найти их должны вы сами. Будьте осторожны, не только лига Исследователей имеет свои интересы в Эльдарате.", progress = "О, рад, что вы сюда добрались, Кавару. Вы сделали эти картинки для Тимора?\n\nХотя местечко опасное, на побережье особого шевеления нет. Может, потому что наги кишат под водой, но это уже не моя проблема... Я небеса патрулирую.", completion = "Рад видеть вас в целости и сохранности, Кавару. Надеюсь, дело оказалось для вас не слишком трудным.\n\nДоставлю их Тимору прямо сейчас. Он просто с ума сойдет от радости.\n\nДа выбросьте вы это сигнальное ружье... оно все равно вам уже ни к чему, да у меня и другое есть.", rewards = "Вы получите:\n\n"},
[3450] = {title = "Легкая доставка", objective = "Поговорите с Хиггсом Зажигателем в Стальгорне.", description = "Я хочу, чтобы эти прорисовки были доставлены мне в башню, но вам незачем лично проделывать весь этот путь. Пусть их просто доставят из Азшары по воздуху.\n\nУ Хиггса Раздувателя Горна есть перед мной должок, к тому же он скоро окажется в тех местах – он назначен патрулировать побережье. Поговорите с ним перед отъездом. Он даст вам сигнальное ружье, чтобы вы могли подать ему сигнал. Когда добудете прорисовки, отправляйтесь в условленное место и отдайте их ему, чтобы он доставил их в мою башню в целости и сохранности. Он должен быть в ангаре в Палатах Войны.", progress = nil, completion = "Чем могу помочь, Эфром? Я как бы занят сейчас – готовлю аппаратик свой к долгому полету. Я тут зашел поговорить с водителями танков – мне нужны гривы вендиго, чтобы кабину утеплить, а у них обычно есть.\n\nТак что уделить вам могу не больше минуты... один парень только что пошел в депо Поселок Сталежара, чтобы посмотреть, найдутся ли у них для меня гривы.", rewards = "Вы получите:\n\n"},
[3451] = {title = "Сигнал \"Взять на борт!\"", objective = "Поговорите с Хиггсом Зажигателем в Стальгорне и получите от него сигнальное ружье.", description = "А, так вас послал Тимор? Да, есть у меня перед ним должок. Это что? Ах, поганец! Ладно, я ему помогу. Значит, вам нужны сигнальное ружье и условленная точка... да легко.\n\nБлиз южного мыса Азшары есть небольшой островок, где мы соорудили посадочную площадку. Берете ружье и даете оттуда сигнал. Я вижу сигнал и прилетаю забрать это... ну, что ему надо.", progress = nil, completion = "Вот вам сигнальное ружье. Когда дадите сигнал, запаситесь терпением – в нем всего два патрона, а мне потребуется несколько минут, чтобы добраться до вас, в зависимости от того, насколько далеко над морем я буду. Выстрелите из ружья – и полюбуйтесь на море.", rewards = "Вы получите:\n\nОбычное сигнальное ружье"},
[3452] = {title = "Защита пламени", objective = "Найдите знак Рагнароса и принесите его Велароку Ветрорезу.", description = "Работа над факелом близится к завершению. Не хватет лишь одного компонента. \n\nВ горах к северо-западу отсюда есть большой лагерь Сумеречного Молота. Говорят, они носят при себе некие символы и идолов в дань уважения своему богу. Полагаю, в этих символах и идолах заключены чары достаточной силы для создания магической брони. Принеси мне знак Рагнароса, и я попытаюсь извлечь из него его магическую силу, чтобы создать защитные чары для факела.", progress = "Факел воздаяния не будет работать без источника магической энергии.", completion = "Символ источает злые чары – именно они и требуются для завершения работы над факелом.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3453] = {title = "Факел воздаяния", objective = "Подождите, пока Веларок Ветрорез закончит факел воздаяния.", description = "Мне нужно несколько минут, чтобы сложить вместе все части и наложить чары.", progress = nil, completion = "Есть еще одно, последнее задание, которое ты должен выполнить.", rewards = "Вы получите:\n\n"},
[3454] = {title = "Факел воздаяния", objective = "Возьмите факел воздаяния.", description = "Факел готов и отныне связан со своим владельцем. Возьми его, <имя>.", progress = nil, completion = "Вы хватаете факел обеими руками и ощущаете исходящие от него волны гнева и ненависти.", rewards = "Вы получите:\n\nФакел воздаяния"},
[3461] = {title = "Возвращение к Тимору", objective = "Принесите Тимору его готовальню назад в Стальгорн.", description = "Тимор не оставил мне ничего, чтобы вам заплатить, потому предлагаю вам обсудить награду лично с ним, когда вернетесь в Стальгорн. Я уверен, что он до сих пор у себя в Палатах Магии. Постучитесь и потребуйте щедрой платы, потому как местечко-то не для пикника... это уж точно.\n\nВсе же благодарю вас, что вы ему помогли, и желаю удачи.\n\nОй, готовальня мне ни к чему. Почему бы вам просто не отдать ее лично Тимору, когда вы с ним встретитесь?", progress = "Вы вернулись! Замечательно. А готовальню мою принесли?", completion = "Отлично! Я так рад это слышать.\n\nКак мне не терпится вернуться в мою башню и поработать над прорисовками... Я так завидую вам! Побывать в Азшаре... думаю, это мечта всех изучающих чародейские науки.\n\nЛадно, хотя мы и не говорили о награде, поскольку вы работаете на лигу Исследователей, но вы ее заслуживаете.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНаголенники СталевараСфера Заклятого черепа\n\nВы также получите:\n\n"},
[3462] = {title = "Оруженосец Малтрейк", objective = "Поговорите с оруженосцем Малтрейком.", description = "Поговори с моим посыльным, оруженосцем Малтрейком. Он объяснит тебе, как использовать факел.", progress = nil, completion = "Ты готов нанести удар?", rewards = "Вы получите:\n\n"},
[3463] = {title = "Задай им жару!", objective = "Подожгите северную, южную, восточную и западную сторожевые башни с помощью факела воздаяния.", description = "Слушай меня внимательно, <имя>. Четыре башни нельзя разрушить, но если поджечь их с помощью факела воздаяния, пламя не угаснет очень долго – и это пламя нельзя будет унять никакими силами. \n\nПока башни горят, ни один страж или караульный не сможет подняться на них – а значит, первая линия обороны противника фактически будет прорвана. \n\nТы <должен/должна> пробраться в башни и поджечь их с помощью факела воздаяния. И берегись патрульных клана Черного Железа, <имя>!", progress = "Ты потерял дорогу, Танетти?", completion = "Отлично! С тобой можно идти в разведку, Томпсон!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДраконьи поножиШлем Пламени драконаТопор Эбенового дракона\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[3481] = {title = "Безделушки...", objective = "Откройте сундук.", description = "Похоже, сундук заперт.", progress = nil, completion = "Замок открывается, как только вы прикасаетесь к нему. Любопытно, сколько же может быть внутри сокровищ? Есть только один способ узнать.", rewards = "Вы получите:\n\nСокровищница черных драконов"},
[3483] = {title = "Сигнал \"Взять на борт!\"", objective = "Еще одно сигнальное ружье, да? Это можно.\n\nИ не забудьте – южная оконечность Азшары. Этот крохотный островок переделан в посадочную площадку. Вы ее не пропустите, если окажетесь в нужном месте.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nОбычное сигнальное ружье"},
[3501] = {title = "Счет идет на большие числа", objective = "Принесите Кум-ише несовершенные фрагменты дренейского аметиста и получите награду за каждый из них.", description = "Быть может, ты никогда не найдешь безупречную сферу из дренейского аметиста, однако во время скитаний по этим землям тебе, несомненно, удастся обнаружить различные несовершенные фрагменты дренейского аметиста. \n\nХотя сомнительно, что Кум-иша сможет использовать эти несовершенные фрагменты для возвращения домой, эти осколки могут сослужить иную, весьма полезную службу для дренеев.\n\nПринеси любой несовершенный фрагмент дренейского аметиста, который найдешь, и я вознагражу тебя.", progress = "Повезло ли тебе в поисках?", completion = "Ты разочаровываешь меня, |3-6(человек). Такой большой, а роняет слюни над грудой хлама? Какое жалкое зрелище! Забирай свою награду и прочь с глаз моих!", rewards = "Вы получите:\n\nБарахло Кум'иши"},
[3502] = {title = "Дренейский хлам...", objective = "Принесите Кум-ише несовершенные фрагменты дренейского аметиста. У любого вида монстров в Выжженных землях могут быть эти фрагменты.", description = "Ну-с, узрев проявление этой ненасытной жадности, я не могу сдержать отвращение.\n\nИ тем не менее я не намерен долго задерживаться на твоем пристрастии к материальным благам.\n\nЗа каждый несовершенный фрагмент дренейского аметиста, который ты принесешь, я вознагражу тебя каким-нибудь хламом. Моя груда хлама будет уменьшаться, а твоя – расти. На Дреноре такая ситуация называлась \"все в выигрыше\".", progress = "Ну? Дренейский аметист? Помнишь?\n\n*Кум-иша сжимает кулак и стучит тебя по голове.*\n\nЕсть кто-нибудь дома?", completion = "Ты разочаровываешь меня, |3-6(ночной эльф). Такой большой, а роняет слюни над грудой хлама? Какое жалкое зрелище! Забирай свою награду и прочь с глаз моих.\n\nЗнакомые слова? А как же – я повторяю их тысячу раз на дню.\n\nО, как мне отвратителен этот мир!", rewards = "Вы получите:\n\nБарахло Кум'иши"},
[3503] = {title = "Встреча с господином", objective = "Да, уж не вернуть тех дней, когда я мог требовать с желающих видеть моего господина все, что заблагорассудится. Теперь-то я отправляю к нему любой сброд – только попроси! \n\nКак меня это бесит! Но приказы не обсуждаются. Я могу потешить себя лишь глумясь над твоей безвкусной одеждой и жалким выражением лица. Впрочем, мне и это уже наскучило! \n\nИ необходимость трепаться тут с тобой меня бесит! Будешь телепортироваться к господину или нет?!", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nТелепорт в башню Азшары"},
[3504] = {title = "Предательница", objective = "Отнесите запечатанное письмо Аг'тору Кровопалу в Азшару.", description = "Предательница и воровка! Других слов для нее у меня нет!\n\nНаверное, я сделал большую ошибку, <имя>. Я доверился эльфу крови.\n\nОна уверяла, будто в Азшаре хранятся несметные сокровища... могущественные артефакты... Все, что нужно, – это отправить с ней нескольких воинов для охраны, и она меня щедро вознаградит. Ну, и кто остался в дураках? Она их всех перебила!\n\nЯ жажду мести, <имя>. Но посылать туда других воинов я уже не могу. Найди Аг'тора в Храбростане, к северу от лагеря Халдарр. Он тебе скажет, что делать дальше.", progress = "А-а, Белгром наконец-то прислал кого-то стороннего, не из своих солдат?\n\nРаньше в этом лагере было двенадцать воинов, Томпсон, но теперь они все мертвы! Эта магичка, Римтори, погубила всех! Белгрома она обвела вокруг пальца... собственно, она его соблазнила. Не мое это дело, но, между нами говоря, стерва она изрядная. Потому я и продолжаю помогать Белгрому. На его месте я бы, наверное, сделал то же самое.", completion = "Мы уже многих посылали против нее и ее приспешников, но они слишком сильны! Никто из посланных не вернулся. Наверное, некоторые погибли, но большинство, подозреваю, просто сбежали. Трусы!\n\nОднако теперь, когда прибыло подкрепление, у нас снова появилась надежда. Быть может, мы все-таки сумеем с ней разобраться.\n\nНу так что, ты с нами?", rewards = "Вы получите:\n\n"},
[3505] = {title = "Предательница", objective = "Убейте 10 эльфов крови-землемеров и 10 эльфов крови-геодезистов, потом разыщите лагерь волхва Римтори. В лагере найдите что-нибудь важное для мага, из-за чего она могла бы ринуться в бой.", description = "Так я и думал.\n\nМы начнем наступать на ее приспешников от южных утесов северного полуострова Азшары. Убивайте их, не зная пощады – пусть знают, кого предали!\n\nНасчет ее самой пока не тревожьтесь – она проводит большую часть времени, рыская по Азшаре вместе со своими телохранителями. После того как перебьете ее работников, стоит отыскать ее личный лагерь. Нужно сначала разведать, откуда можно на нее напасть. Может быть, стоит как-нибудь выманить ее из лагеря...", progress = "Заглавие этой книги написано золотом по черной кожаной обложке: \"кальдорайский фолиант Призыва\". Открыв книгу, вы обнаружили, что она древняя, но превосходно сохранилась.\n\nТекст, по-видимому, на каком-то древнем языке... кальдорайском, наверное?\n\nИнстинкт подсказывает вам, что, когда вы покончите с местью, сюда стоит вернуться снова.", completion = "Вы начинаете листать страницы и обнаруживаете, что одна из них заложена узкой ленточкой черного шелка.\n\nВы пытаетесь разобрать непонятные слова и видите на одной из страниц схему. Присмотревшись, вы понимаете, что кристаллы, круг и некоторые другие компоненты, лежащие на земле, расположены так же, как на рисунке.", rewards = "Вы получите:\n\n"},
[3506] = {title = "Предательница", objective = "Уничтожьте кристалл средоточия чар, связанный с волхвом Римтори, затем убейте ее. Отнесите голову Римтори Аг'тору Кроволапу в Азшаре.", description = "Вы поразмыслили еще немного, и вам на ум пришло сразу несколько идей, одна из которых заставила улыбнуться: возможно, если вы уничтожите кристаллы, подлая эльфийка, погубившая стольких орков, достаточно разозлится?\n\nВы продолжаете разбирать текст и рисунки и понимаете, что один из кристаллов связан с создателем круга – прочие же связаны с куда более жуткими тварями.\n\nВы закрываете книгу и начинаете прикидывать, какой из кристаллов следует уничтожить.", progress = "Ну что, Томпсон, много тебе удалось перебить этих эльфов-предателей?\n\nЯ надеюсь, что именно у тебя хватит сил поставить эту мерзавку на колени! За все, что она натворила, она заслуживает самой мучительной смерти!", completion = "Ага!!! Невероятно!\n\nТебе это удалось! То-то Белгром обрадуется! Наконец-то души десятков наших воинов упокоятся в мире. Спасибо тебе, Томпсон.", rewards = "Вы получите:\n\n"},
[3507] = {title = "Предательница", objective = "Поговорите с Белгромом Каменной Буловой в Оргриммаре.", description = "Вернись в Оргриммар к Белгрому. Он захочет увидеть ее голову своими глазами! Мы там тоже скоро будем.\n\nУдачный у нас денек! Спасибо за помощь, <имя>.", progress = "Да, |3-6(Охотник), я тебя помню. Я просил тебя отправиться в Азшару и уничтожить ту негодяйку, которая предала меня! Кажется, будто это было много лун тому назад... Только не говори мне, что Аг'тор и остальные тоже мертвы!", completion = "Ха-ха-ха! Вот и ты, жалкая девчонка! Я плюю на твои останки!\n\nСпасибо, Томпсон. Я благодарю тебя от всей души! Это воистину великий день!\n\nБудь это в моей власти, я наградил бы тебя целым королевством! Но, может быть, ты согласишься на это?\n\n*Белгром смотрит на голову мага, который предал его.*\n\nХа-ха! Глупая эльфийка! Вот что с тобой стало! В парусиновом мешке, голова отдельно, тело отдельно! Не надо было предавать Белгрома!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОгнекаменная сфераБоевой молот Белгрома\n\nВы также получите:\n\n"},
[3508] = {title = "Минуя охрану", objective = "Подождите, пока Лорамус завершит заклинание просветления.", description = "Тебе свойственна безрассудная храбрость, <имя>. Это ценное качество твоего рода – слепо кидаться в битву, почти не имея шансов на успех. Я помогу тебе, хотя бы только ради того, чтобы увидеть смерть приспешников Разелиха. \n\nОднако для того, чтобы пробиться через охранные чары, окружающие их, требуется время, равно как и использование редких артефактов.\n\nНе нарушай тишину, я должен исполнить ритуал просветления. Сведения, которые я получу, помогут мне отковать оружие великой мощи.", progress = nil, completion = "Необходимо отыскать имя зверя.", rewards = "Вы получите:\n\n"},
[3509] = {title = "Имя Зверя", objective = "Поговорите в Азшаре с лордом Арккоросом. Начните поиски у кромки воды, чтобы найти Храм Арккоран.", description = "Существует лишь один способ причинить вред повелителю демонов и его приспешникам. Следует выковать оружие силы, несущее его истинное имя.\n\nКогда такое оружие будет выковано, демон и все, кем он повелевает, станут уязвимы. \n\nВ Азшаре обитает меньшее божество: лорд Арккорос. Тебе следует найти его. Однако осторожнее: его слуги не остановятся ни перед чем, чтобы убить тебя, если обнаружат.\n\nНесомненно, за такие сведения придется заплатить.", progress = nil, completion = "Повелитель демонов?\n\n*Лорд Арккорос смеется.*\n\nБыть может, кое-кто сможет помочь тебе этими сведениями; но сначала ты должен помочь кое-кому.", rewards = "Вы получите:\n\n"},
[3510] = {title = "Имя Зверя", objective = "Убейте Хетайру и принесите окровавленную голову Хетайры, разбитую голову Хетайры и покрытую синяками голову Хетайры лорду Аккоросу.", description = "Она убивает моих детей. Она называет себя повелительницей океанов. Фальшивая богиня, и ничего более. Сокруши ее и принеси мне все ее головы.\n\nЗа это ты получишь то имя, которое тебе нужно, и кое-что еще, не менее важное.\n\nОна бродит вокруг гнезда... Она зовется Хетайра.\n\n*Лорд Арккорос указывает на юго-запад.*\n\nИди!", progress = "*Лорд Арккорос склоняется, чтобы лучше видеть тебя.*\n\nГде они?", completion = "Наконец-то хоть кто-то достойный мудрости Арккороса!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3511] = {title = "Имя Зверя", objective = "Отнесите состав для закалки Лорамусу Многоногу.", description = "Как и обещал, я открою тебе имя Повелителя демонов Разелиха Осквернителя. Однако сначала я должен приготовить кое-что необычайно важное для твоего путешествия.\n\nДля создания оружия, которое ты ищешь, необходим состав для закалки. Подожди немного, я выжму кровь из этих голов.\n\n*Лорд Арккорос сжимает головы между своими гигантскими ладонями, выдавливая из них кровь.*\n\nДоставь этот состав для закалки Лорамусу вместе с именем зверя: Рах'лих.", progress = "С возвращением! Я рад видеть тебя, |3-6(орк). Тебе удалось узнать подлинное имя?", completion = "Этот состав содержит протравку, необходимую нас для отковки оружия. Это еще один шаг к созданию сего оружия.", rewards = "Вы получите:\n\n"},
[3512] = {title = "Судя по словам Эраникуса...", objective = "Отправляйтесь в восточную часть Зимних Ключей и поговорите с Умбрансом Ищущим Духов.", description = "<имя>, нашим первым шагом будет разработка способа связаться с Эраникусом через этот камень. Он сейчас находится на зыбкой грани между сном и смертью, в сетях кошмаров. Хотя принесенная тобою сущность сильно поражена порчей, все еще есть шанс, что мы дотянемся до Эраникуса.\n\nТебе придется отправиться далеко на север, и к востоку от Зимних ключей разыскать нашего смертного союзника, Умбранса Ищущего Духов. Это человек, медиум, говорящий с мертвыми. Хотя Эраникус и не вполне мертв, этот человек все же сможет нам помочь.", progress = nil, completion = "Хорошо, что Итар послал тебя ко мне. Хотя Эраникус и не мертв в общем смысле этого слова, я смогу поговорить с ним. Но прямо сейчас я не могу помочь тебе...\n\nЯ с удовольствием это сделаю, но сначала мне самому нужна помощь того, кто, в отличие от меня, не скован старческой немощью. Мой наиболее ценный гадальный инструмент был у меня украден, и, пока я не заполучу его обратно, я бессилен помочь Эраникусу.", rewards = "Вы получите:\n\n"},
[3513] = {title = "Свиток с рунами", objective = "Отнесите свиток с рунами в северную сторожевую башню Степей.", description = "Свиток официального вида перевязан серебристой лентой. Несомненно, кому-то он был бы весьма интересен, но кому?\n\nНа севере, рядом с границей Ясеневого леса, есть застава, и если в свитке идет речь о ночных эльфах, именно туда его и надо отнести.", progress = "Что это?", completion = "Та-ак... И где ты это нашел?", rewards = "Вы получите:\n\n"},
[3514] = {title = "Мощь Орды", objective = "Убейте предводительницу Пещеры Когтей, Ринтариэль Хранительницу Ключей.", description = "Это послание от коварной дриады Ринтариэль, Хранительницы Ключей Пещеры Когтей на Пике Каменного Когтя.\n\nОна уже не встретится с гонцом, у которого ты нашел этот свиток, хе-хе, но так просто им это не пройдет. Орда не потерпит такого нахальства.\n\nСтупай в Пещеру Когтей, <имя>. Убей Ринтариэль и покажи это всем. Возьми с собой флаг Орды и установи его в Пещере Когтей у всех на виду. В другой раз они трижды подумают, прежде чем снова соваться в наши земли.", progress = nil, completion = "Да ты силен! Это большое дело – лишить Логово Когтя Ринтариэль. Наши противники не сразу оправятся от потери, и в ближайшее время в Степи будет проникать меньше лазутчиков Альянса. Они подумают дважды, чем прежде чем снова соваться к нам.\n\nСпасибо.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги первооткрывателяДжутовые перчатки\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[3517] = {title = "Тайненькое знаньице", objective = "Найдите таблички Бет'Амары, Джин'яэль, Маркри и Саэль'Хай и принесите их Джедиге в Азшару.", description = "Ты знаешь, <имя>, я, в общем, неплохо устроилась в Азшаре. У наказания Белгрома, обрушившегося на мою голову, есть свои положительные стороны. \n\nЯ тут полазала по окрестностям и обнаружила просто уйму ценностей, валяющихся без дела. \n\nЕсли интересно, могу рассказать подробнее и даже поделюсь прибылью, если поможешь мне добыть кое-что. \n\nВ руинах Эльдарата к востоку отсюда сокрыты четыре таблички. Каждая из них носит имя мага высокорожденных. Принеси мне их, и мы поговорим о дальнейшем сотрудничестве.", progress = "У меня есть знакомые, которые готовы отвалить за таблички неплохой куш. Я скажу тебе, кому нужно их доставить. Только без дураков, получишь свою долю после того, как принесешь мне расписку от клиента. \n\nПоторапливайся, время не ждет! А не то найду еще кого-нибудь в помощники!", completion = "Отлично, Томпсон, ты принес все таблички, и они в хорошем состоянии. Мы получим за них хорошую цену. \n\nНу, не будем тратить время зря. Пора обменять таблички на денежки!", rewards = "Вы получите:\n\n"},
[3518] = {title = "Доставка Магате", objective = "Отнесите табличку Бет'Амары Магате в Громовой Утес.", description = "Первую табличку нужно отнести таурену по имени Магата. Ты найдешь ее среди старейшин Громового Утеса. Она самая ярая сторонница заключения союза тауренов с Отрекшимися, ибо считает, что именно таурены и их обычаи могут помочь Отрекшимся вновь найти путь к обретению человеческой природы. \n\nОтнеси ей табличку Бет'Амары. Тауренка считает, что может найти в табличке способ, как помочь Отрекшимся... ну да, по крайней мере она в это верит.", progress = "Приветствую тебя, Томпсон. Чем я могу помочь тебе? Говори быстрее, у меня много дел.", completion = "О, наконец-то! Табличка Бет'Амары! А я уж гадала, неужели орк не сдержала обещания, или, чего доброго, бедняжка нашла кончину в Азшаре. Я рада, что ей удалось. \n\nБет'Амара был одним из самых могущественных алхимиков высокорожденных. Говорят, что он единственный овладел искусством трансмутации металлов.", rewards = "Вы получите:\n\n"},
[3519] = {title = "Друг в беде", objective = "Поговорите с Диранией Серебряным Сиянием в Тенистой долине.", description = "Ох... меня сильно покусала паучиха по имени Гитьис Зловещая, когда я обследовал паучиную пещеру. Похоже, я серьезно отравлен. Помоги мне!\n\nПожалуйста, дай знать Дирании Серебряному Сиянию. Она сможет помочь мне.\n\nСпеши... Как голова кружится…", progress = nil, completion = "Ох, какая беда, а я-то думала, что это сегодня Иверрона не видно... Предупреждала же я его насчет пауков!", rewards = "Вы получите:\n\n"},
[3520] = {title = "Духи крикунов", objective = "Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе'кинье в Порт Картеля.", description = "Мне нужны духи дольных крикунов из Фераласа. Они родственники старого-престарого бога и напрямую связаны с ним.\n\nВозьми ежевичный посох и ступай в Фералас. Отыщи в южной и центральной части дольных крикунов и одержи над ними верх. Потом помаши моим посохом над их телами. Таким образом ты выманишь их души. Коснись каждой из душ и собери их сущности.\n\nПринеси мне посох и собранные сущности, и я расскажу тебе о том старом боге.", progress = "Ты несешь мне сущность дольных крикунов, Эфром?", completion = "Молодец, Эфром. Пожалуй, пришло время рассказать тебе правду…\n\nУ троллей существует пророчество о возвращении на землю убитого бога, Хаккара Свежевателя Душ. Некоторые говорят, что пришествие Хаккара принесет троллям радость и славу, другие же ждут лишь конца всего сущего.\n\nЯ не верю в этот миф, но не сомневаюсь, что сущность Хаккара таит в себе великую силу, которая не должна попасть в руки недостойных...", rewards = "Вы получите:\n\n"},
[3521] = {title = "Противоядие для Иверрона", objective = "Соберите 7 гиацинтовых грибов, 4 лунные лилии и 1 порцию лимфы чащобного тенетника и принесите Дирании Серебряное Сияние в Тенистую долину.", description = "Мы могли бы помочь Иверрону: я знаю противоядие, которое нейтрализует действие яда. Но для него мне нужны некоторые ингредиенты.\n\nМне понадобятся гиацинтовые грибы. Их можно найти под деревьями или добыть у греллей к югу отсюда – похоже, они им по вкусу. Еще мне нужны лунные лилии, что растут только вокруг прудов.\n\nПоследний ингредиент добыть сложнее всего. Это лимфа тех самых чащобных тенетников, что отравили Иверрона.", progress = "Пожалуйста, принеси мне все эти ингредиенты, Радиум. Иверрону нужна наша помощь!", completion = "Хвала Элуне – ты так быстро собрал все ингредиенты!\n\nПодожди минутку, сейчас я приготовлю противоядие.", rewards = "Вы получите:\n\n"},
[3522] = {title = "Противоядие для Иверрона", objective = "Отнесите противоядие Иверрону, прежде чем оно потеряет свои целебные свойства. Иверрона можно найти около пещеры, что к северу отсюда.", description = "Противоядие готово, <имя>. Пожалуйста, проследи, чтобы Иверрон его выпил.\n\nИ запомни – это важно: противоядие будет обладать своими целебными свойствами в течение пяти минут. Необходимо доставить его до истечения этого времени.\n\nПоторопись, во имя Элуны!", progress = "О... Айлерон, какое счастье, что ты вернулся...", completion = "Что это, Айлерон?\n\nЯ знал, что Дирания поможет мне!\n\n*Иверрон выпивает противоядие.*\n\nЯ все время попадаю в переделки, а Дирания постоянно меня из них вытаскивает.\n\nМне стало намного лучше, хотя, пожалуй, я немного посижу тут, пока совсем не приду в себя. Что ж, надеюсь, ты расчистил мне дорогу через этот лес, полный мерзостных чащобных тенетников...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБрюки из осокиЛубяной кольчужный жилет\n\nВы также получите:\n\n"},
[3523] = {title = "Плеть в холмах", objective = "Если вы хотите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы, который он дал вам.", description = "Благодарю, что <спас/спасла> меня! Имя мне Белнистраз. Не хотелось бы закончить жизнь столь бесславно – быть сожранным одной из омерзительных тварей Плети. Да-да, ты не <ослышался/ослышалась>, Плеть вступила в союз с местными свинобразами.\n\nПослушай... вместо того, чтобы бежать, спасая собственную жизнь, я бы предпочел вступить с врагом в бой, чтобы защитить невинных. Нек желаешь ли ты мне помочь? Это опасно, но ты явно не из тех, кто пасует перед трудностями.", progress = "Я далек от политики. Мне нет дела до того, связан ли ты с Ордой или Альянсом. Все, чего я хочу – уничтожить прямую и неотвратимую угрозу всем расам этого мира. \n\nЕсли ты хочешь стать героем для всех народов, отдай мне Камень клятвы, который получил от меня в знак своего согласия. Я... не из здешних мест; у нас принято скреплять договоренности Камнем клятвы.", completion = "Весьма похвально, Эфром. Я знал, что из тех, кто захочет взяться за это непростое и опасное дело. Не скрою, нам предстоит тяжелая работа. Но мы должны приложить все усилия и справиться с ней. \n\nПослушай, я введу тебя в курс дела...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3524] = {title = "Останки на берегу", objective = "Соберите кости морской твари, выброшенной на берег к югу от Аубердина, и принесите их Гвеннид Блай'Леггонд в Аубердин.", description = "Громадные морские твари выбрасываются на пески Темного Берега и лежат там, пока не умирают. В последнее время останки этих тварей выносит на берег все чаще и чаще. Меня послали сюда из Храма Луны для расследования ситуации, но наличие мурлоков у береговой линии затрудняет мою задачу.\n\nОдни такие останки лежат на юге от Аубердина, совсем рядом, но вокруг очень много злобных мурлоков из клана Серой Мглы. Не могли бы вы сходить туда и принести мне для изучения кости этой твари?", progress = "Эти морские твари только недавно стали приплывать на отмели Темного Берега в таких тревожно больших количествах. Не могу сказать точно, но думаю, что это своего рода дурное предзнаменование. Извлечение образцов костей такой твари, что лежит к югу отсюда, поможет нам в Дарнассе оценить ситуацию!", completion = "Я надеюсь, что мурлоки не слишком досаждали вам, пока вы собирали для нас эти кости! Я непременно следующим же гиппогрифом доставлю их в Дарнасс. Храм Луны снабдил меня некоторыми средствами, которыми я могла бы расплачиваться за помощь; пожалуйста, примите немного денег вместе с нашей благодарностью.\n\nВаш успех побуждает меня предложить вам возможность и дальше оказывать помощь Храму Луны, если вы заинтересованы в этом...", rewards = "Вы получите:\n\n"},
[3525] = {title = "Уничтожить идола", objective = "Сопроводите Белнистраза к идолу свинобразов на Курганах Иглошкурых. \n\nЗащищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола.", description = "Рядом с входом ты увидишь идола – свинобразы используют его как жертвенный очаг. Эти твари на самом деле пожирают своих пленников из Степей. Я должен разбить идола, чтобы они более никогда не могли его использовать, но мне потребуется твоя помощь. Сопроводи меня к идолу. Там я проведу ритуал, но при этом я даже не смогу говорить с тобой, не говоря уж о том, чтобы самому защитить себя. Тебе придется держать оборону, пока я буду проводить ритуал. Если меня убьют раньше, чем я закончу, это будет означать крах всех наших планов.\n\nТы <готов/готова>?", progress = nil, completion = "Белнистраз исчезает, оставив на месте себя пылающее зарево. Вы видите в пламени очертания огромного крылатого красного дракона. Рокочущий голос Белнистраза наполняет ваше сознание.\n\n\"Я всегда верил в вашу смелость, смертные. Благодаря тебе кровавым делам, вершимым здесь этими тварями, пришел конец. Моя вера в мужественность смертных созданий сегодня укрепилась. Прими эту награду – она достойна героя.\"", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКольцо Драконьего когтя"},
[3526] = {title = "Гоблинское инженерное дело", objective = "Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.", description = "Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской. Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую. Покори же мир с помощью отборной взрывчатки и фантастических механизмов!\n\nПрочитай этот учебник, <имя>. Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске. Помни: сделав выбор единожды, ты не сможешь передумать. Поэтому хорошо подумай, прежде чем браться за задание Никса.", progress = "Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?", completion = "Что же, Шушпанк, ты нашел подходящего учителя! Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган. Требуется острый ум и верная рука (повторяю: ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела.\n\nДержи ушки на макушке, Шушпанк, тогда чему-нибудь научишься.", rewards = "Вы получите:\n\n"},
[3527] = {title = "Пророчество Мошару", objective = "Принесите первую и вторую таблички Мошару Йе'кинье в Танарис.", description = "Древнее пророчество Мошару повествует о том, как взять в плен сущность бога Хаккара. Пророчество записали на двух табличках и отнесли в тролльский город Зул'Фаррак, что к западу от Прибамбасска.\n\nПринеси мне таблички Мошару!\n\nПервая табличка находится у давно умершего тролля Теки Мученика. Говорят, что его истязатели превратились в скарабеев и до сих пор ползают по его святилищу.\n\nВторая табличка – у гидроманта Велраты, рядом со священным озером Газ'риллы.\n\nДобудешь таблички – сразу приходи.", progress = "Ты несешь мне таблички пророчества Мошару?\n\nЯ хочу изучить их и понять, как сковать сущность Хаккара!", completion = "О, замечательно. Я соединю эти таблички и раскрою их секреты.\n\nЯ давно твой должник, Тузвколоде. И, боюсь, мой долг будет только расти.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3528] = {title = "Бог Хаккар", objective = "Отнесите заполненное яйцо Хаккара Йе'кинье в Танарис.", description = "Пришло время брать в плен сущность аватары Хаккара.\n\nОтнеси яйцо Хаккара в святилище Падшего Бога в Затонувшем храме Азерота. Призови силу яйца и разбуди мертвого бога.\n\nОн пошлет против тебя своих прислужников. Одолей их и нацеди из них крови Хаккари. Угаси при помощи этой крови вечный огонь, в котором заключен дух Хаккара. Когда пламя погаснет, в мир войдет аватара Хаккара.\n\nПобеди его и помести его сущность в яйцо Хаккара.", progress = "Тебе удалось победить аватару Хаккара, Хантор? Заряжено ли это яйцо его сущностью?", completion = "Значит, сущность Хаккара заключена в яйцо! Смотри, как в Яйце пульсирует жизнь! Неужели мифы о Хаккаре правда?\n\nНе может быть, ведь в таком случае Хаккар может возродиться. Я буду хранить это яйцо как зеницу ока, чтобы оно не попало в недобрые руки.\n\nНаша совместная работа подошла к концу, Галдар. Ты прикоснулся к легенде, быть может, твои подвиги однажды изменят облик нашего мира.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШлем АвангардаКортик ЖизнесилыДрагоценный венец\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[3541] = {title = "Доставка Джес'римону", objective = "Отнесите табличку Джин'яэль Джес'римону в Оргриммар.", description = "В Оргриммаре есть у меня скупщик краденого. У него притон в Волоке. Этого скользкого типа нелегко найти, если не знать точно где искать. Запомни: искать следует в одном из самых высоких знаний. \n\nТолько сделай мне одолжение, не ори на весь Калимдор, где он и чем занимается – это было бы... весьма неприятно для нас обоих. \n\nОн готов заплатить очень хорошую цену за табличку Джин'яэль. Не знаю, зачем уж она ему сдалась, но <видел/видела> бы ты, как у него загорелись глаза, когда я упомянула, что знаю, где ее найти!", progress = "Ну, что тебе нужно, тля? У меня на сегодня уйма дел, и ты в их число не входишь. Впрочем, если будешь путаться под ногами, найдется и на тебя минутка!", completion = "Ага, Джедига прислала мне посылку... Великолепно, я ждал ее. \n\nДа, Джедига славная бабенка! Свирепая как волчица... что может быть лучше? \n\nКак я погляжу, табличка в целости и сохранности. А что это значит, Томпсон? Значит, посыльный получит на магарыч!", rewards = "Вы получите:\n\n"},
[3542] = {title = "Доставка Андрону Ганту", objective = "Отнесите табличку Маркри Андрону Ганту в Подгород.", description = "Теперь ты отправишься к Андрону Ганту. Он обретается в Подгороде, недалеко от Района Фармацевтов. \n\nЭтот был более многословен, когда я спросила, зачем ему нужна табличка. Маги Подгорода хотят изучить некоторые тайные заклинания высокорожденных. Они считают, что табличка им в этом поможет. Маркри был очень талантлив в чарах призыва различных существ, особенно элементалей. \n\nОтнеси ему табличку Маркри и возвращайся за своей долей.", progress = "Ого... *ик* вот так сюрприз! *ик* Да у меня гости! *ик* Чем, так сказать, могу?.. *ик*", completion = "Вот, возьми пару монет... *ик*... купи себе новую броню... или шляпу. \n\nНичего не жаль для хороших посыльных!", rewards = "Вы получите:\n\n"},
[3561] = {title = "Доставка верховному магу Ксилему", objective = "Отнесите табличку Саэль'Хай верховному магу Ксилему в Азшару.", description = "Последнюю табличку надлежит доставить весьма опасному человеку, <имя>. Можешь не сомневаться, я доверяю ему куда меньше,чем кому-либо из тех, к кому я тебя отправляла. \n\nВерховный маг Ксилем живет в башне в холмах, возвышающихся над Азшарой. Он человек, однако он не похож на людей, которых мне приходилось встречать... или убивать. Он необычайно властен. Я не смею спросить его, что он собирается делать с табличкой. \n\nОн сказал мне, что страж его, Санат, поможет мне попасть в его башню, когда я буду готова предстать перед ним. Ищи Саната на севере.", progress = "Чем ты явился ко мне, Томпсон?", completion = "О, табличка Саэль'Хай... как давно я мечтал изучить ее! \n\nБлагодарю тебя, Томпсон. Скажи Джедиге, что я доволен работой. Орк заслужила свою награду.", rewards = "Вы получите:\n\n"},
[3562] = {title = "Плата Магаты Джедиге", objective = "Отнесите записку Магаты Джедиге в Азшару.", description = "Отнеси это послание Джедиге. Скажи ей, что я заплачу ей лично, когда она придет ко мне.\n\nСтупай скорее, <имя>. Скажи своей госпоже, что награда ожидает ее.", progress = "Что сказала Магата? Старая карга наверняка выбрала словечко покрепче...", completion = "А, отлично. Она поступила вполне разумно. По крайней мене по отношению к тебе. Я побаивалась, что она сделает с тобой что-нибудь неприятное, чтобы наказать меня за высокомерие. Она любит, чтобы к ней являлись лично, а не отправляли мальчиков на побегушках. Похоже, она действительно обрадовалась табличке. \n\nЧто ж, посмотрим.", rewards = "Вы получите:\n\n"},
[3563] = {title = "Плата Джес'римона Джедиге", objective = "Доставьте записку Джес'римона Джедиге в Азшару.", description = "Отнеси это послание Джедиге. Скажи ей, что я доволен ее работой.\n\nСкажи, чтобы скорее возвращалась в Оргриммар – Джес'римон достойно наградит ее. \n\nПередай ей это, и, возможно, впредь я буду давать тебе поручения, <имя>.", progress = "Ты говорил с Джес'римоном? \n\nСреди троллей он реальный кабан, однако за работу платит хорошо и аккуратно. \n\nЕсли сможешь выдержать его манеры, непременно заработаешь хороший барыш на выполнении его поручений.", completion = "Судя по этому письму, Джесримон весьма доволен нашей работой... \n\nЗнал бы он как я довольна работой, которую он мне дает... Ну, теперь у меня есть еще одна причина задержаться в Азшаре. \n\nВот, забирай свою долю.", rewards = "Вы получите:\n\n"},
[3564] = {title = "Плата Андрона Джедиге", objective = "Доставьте записку Андрона Джедиге в Азшару.", description = "Вот *ик!* держи *ик!* Это для Джедиги. И ты это, *ик* заходи, если что!", progress = "Ну что, ты говорил с Андроном? Он редко покидает Подгород, так что не думаю, что его будет сложно найти.", completion = "Отлично... ого, это еще что! \n\nХа-ха! Что ты сказал ему, когда отдавал табличку, Томпсон? Он заплатил нам едва ли не дважды сверх уговоренного! Нет, я конечно, не жалуюсь... Ты сказал ему, что я изменила условия сделки? Или этот пьянчуга опять шары залил и не соображал, что делает? \n\nНу, уже неважно. Вот, держи свою долю – с премией!", rewards = "Вы получите:\n\n"},
[3565] = {title = "Плата Ксилема Джедиге", objective = "Доставь записку Ксилема Джедиге в Азшару.", description = "Что еще? Ах да, оплата. Конечно. \n\nВот, возьми и выметайся. Уверен, Джедига ждет не дождется твоего возвращения.", progress = "Ну, что сказал тебе Ксилем? Ничего с тобой не сделал? Не пытался заманить тебя к себе в услужение?", completion = "Что, в самом деле не случилось ничего неприятного? И он отдал тебе деньги не торгуясь? Ушам не верю... Я, честно признаться, ожидала какого-то подвоха. Похоже, с ним все же можно иметь дело. \n\nВот, держи свою награду. Спасибо за помощь.", rewards = "Вы получите:\n\n"},
[3566] = {title = "Восстань, Обсидион!", objective = "Убейте Латорика Черного и Обсидиона и принесите голову Латорика и сердце Обсидиона Ториусу в Стальгорн.", description = "Это... была... ловушка... \n\nПрости... меня... \n\nУбей предателя... Отомсти за нас... За Ториуса...", progress = "Я не верю! Ты можешь доказать, что это не ложь?", completion = "*Ториус бледнеет.*\n\nЭтого не может быть... Мой единокровный брат! Неужели он мог это сделать?! \n\n*Лицо Ториуса искажает ярость*\n\nОн предал меня, он предал Стальгорн! Видимо, влияние Древних Богов еще сильно в этих землях.Боюсь, если даже мой брат – некогда благородный и уважаемый человек – так легко поддался воле Рагнароса, никто их нас не может чувствовать себя в безопасности!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНожные латы центурионаПолный шлем ЛордрекаКольцо стойкости\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[3567] = {title = "Умный в гору не пойдет...", objective = "Хочешь посмотреть, какой вид открывается во-он оттуда, с тех Двух Колоссов? Могу тебя туда отправить, |3-6(нежить).\n\nТолько подумай заранее, как потом будешь спускаться. Это путешествие в один конец!", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nТелепорт Двух Гигантов"},
[3568] = {title = "Разносчик порчи", objective = "Наполните все 4 пустых фиала из приливных заводей в руинах Эльдарата и возвращайтесь к химику Карабосу.", description = "Видишь этого несчастного таурена? Она недавно побывала в Азшаре. Среди руин Эльдарата она была ранена в бою с нагами.\n\nОтбившись от них, она решила отдохнуть на берегу и попила водички из приливной заводи. Теперь ее тошнит... помимо всего прочего.\n\nМне нужно выяснить, что она пила. Возьми этот ящик, в нем несколько помеченных фиалов. Наполни их из разных заводей и возвращайся.", progress = "Ты ведь догадываешься, к чему все идет, Томпсон? Ей не выжить... видно с первого взгляда. Лучшее, что она может сделать, – это помочь нам отыскать лекарство от чумы. Быть может, в воде, которую она пила, мы найдем намеки на то, как можно получить рецепт? Если все равно помирать, почему бы не сделать перед смертью доброе дело для своего народа? Ты согласен?", completion = "Чудесно. Ты успел вернуться до ее гибели. Славно, славно.\n\nЗначит, пора приступать.\n\nЯ некоторое время изучал симптомы ее болезни, и теперь дело совсем плохо. Удивительно, как она на ногах держится. Ее уже три или четыре раза вырвало... запах просто чудесный.\n\nДай-ка я состряпаю что-нибудь для нашей... подруги.", rewards = "Вы получите:\n\n"},
[3569] = {title = "Разносчик порчи", objective = "Дайте эликсир Карабоса Терсе Песне Ветра в Подгороде.", description = "Отнеси эликсир Терсе – вдруг он ей поможет? Пока она не выпьет его, точно не скажешь.", progress = "Я пришла в Подгород, потому что слышала, что алхимики давно работают над созданием лекарств, которые могут исцелить их собственную болезнь. Я надеялась, что они и мне помогут.\n\nХотя я чувствую себя не в своей тарелке, выбора нет – боль раздирает меня изнутри, и мне срочно нужна помощь.", completion = "Химик Карабос – само гостеприимство... даже не по себе стало. Но если он говорит, что есть шанс излечиться, выбора нет. Искать другие лекарства нет времени. Ни жрецы, ни шаманы не смогли мне помочь.\n\nБудем надеяться, что Мать-земля сохранит мою душу.", rewards = "Вы получите:\n\n"},
[3570] = {title = "Разносчик порчи", objective = "Я и не думал, что эликсир сработает так быстро. Спасибо, Томпсон. Займусь-ка работой над остальными образцами. Уверен, вскоре леди Сильвана и Отрекшиеся будут их активно использовать.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[3601] = {title = "Оскорбленный Ким'джаель", objective = "Обыщите Талассийское поселение и найдите компас, прицел, плюшевого цыпленка и центробежный растягиватель Ким'джаеля. Верните все это Ким'джаелю в Азшару.", description = "Ким'джаель оскорблен до глубины души! Знаешь, что на самом деле Ким'джаель значит для эльфов крови, <имя>? Я для них всего лишь букашка! Маленькое безвредное создание, на которое можно и наступить – не жалко! \n\nОни наняли меня, чтобы я обшарил для них место, где, как они сказали, спрятано сокровище. Ну ты понимаешь, при слове \"сокровище\" я утратил бдительность и купился на их посулы! Конечно же, они предали меня и даже пытались прикончить! \n\nНикогда нельзя верить мерзким эльфам крови! \n\nМне удалось уйти живым, но у негодяев осталось все мое снаряжение! Пожалуйста, забери его у них!", progress = "Мерзкие эльфы крови! Да-да, если бы я был таким же большим и сильным, как ты, уж я бы научил их хорошим манерам. Я поскольку я может и сильный, но легкий, я лучше заплачу тебе, чтобы ты сделал это за меня.", completion = "Ха! Так им и надо! \n\nВот это круто! Теперь-то они знают, что значит предавать своих партнеров! Особенно гоблинов! \n\nНу, теперь о твоей награде... я же сказал, значит, заплачу. \n\nВот, держи... может, пригодится.", rewards = "Вы получите:\n\nОсколочная граната M73"},
[3602] = {title = "Азшарит", objective = "Найдите в южной Азшаре двадцать кристаллов азшарита. Вы можете использовать Гончих Скверны, которые помогут вам \"вынюхивать\" местонахождение хорошо сокрытых залежей. \n\nКогда задача будет завершена, возвращайтесь к Лорамусу Многоногу.", description = "Древние скальные великаны из южных регионов Азшары для поддержания существования поглощают камни и каменные образования. Продуктом переработки такой \"пищи\" являются чрезвычайно податливые, но при этом необычайно прочные кристаллы, известные как азшарит. \n\nНа южной гряде находятся целые залежи азшарита, однако его почти никому не удавалось добыть из-за чрезвычайной жестокости великанов.\n\nТебе следует отправиться на юг и раздобыть азшарита столько, чтобы его хватило для создания оружия. Мои гончие скверны помогут в розыске кристаллов.", progress = "Зло не спит, и глуп тот, кто думает иначе. Отдохнешь после смерти. Принеси же мне кристаллы.", completion = "Твои задачи в Азшаре завершены. Теперь я должен подготовить все необходимое для следующего шага твоего пути.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3621] = {title = "Создание отравы Скверны", objective = "Отнести груз Гальвану Древнему в Тернистую долину.", description = "Оружие готово к отковке. Тебе следует отнести закаленный азшарит к тому, кто может обуздать энергию скверны.\n\nВ Тернистой долине живет такой кузнец. Гальван Древний, глава Ордена Мифрила, создаст оружие по твоему заказу. Ты можешь найти его становище между Зул'Гурубом и холмом Мош'Огг.\n\nПусть решительность и вера помогут тебе пройти это испытание. А если ты погибнешь, знай, что твой Бог тебе улыбается.", progress = "Вот как, Лорамус? Прошло много лет с тех пор, как я в последний раз слышал это имя.", completion = "Могу лишь вообразить, через что тебе пришлось пройти, чтобы раздобыть эти материалы. Немногим удавалось вернуться живыми из Азшары, не говоря уж о том, чтобы встретиться лицом к лицу с полубогами и демонами.", rewards = "Вы получите:\n\n"},
[3625] = {title = "Зачарованное азшаритовое оружие, отравленное Скверной", objective = "Подождите, пока Гальван закончит отковывать оружие.", description = "<имя>, для создания оружия необходимо время.\n\nВдобавок, ты можешь использовать силу оружия Проклятия Скверны лишь раз в три минуты. Длительность действия, ослабляющего Разелиха Осквернителя и его приспешников, может быть различной. Именно поэтому следует высвобождать силу Проклятия Скверны лишь в нужный момент!\n\nТеперь дай мне время на создания оружия для тебя, <имя>.", progress = "Если вмешиваться в процесс, то оружие может получиться с изъяном. Терпение, Бронетазик.", completion = "*Гальван вытирает пот со лба..*\n\nНикогда еще не существовало более подходящего оружия для убиения демона, Томпсон.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗачарованный азшаритовый отравленный Скверной кинжалЗачарованный азшаритовый посох СкверныЗачарованный азшаритовый меч Скверны\n\nВы также получите:\n\n"},
[3626] = {title = "Возвращение в Выжженные земли", objective = "Вернитесь к Павшему герою Орды.", description = "Час возмездия близок, <имя>. Тебе следует вернуться в Выжженные земли вместе с твоим новообретенным оружием и поговорить с Павшим героем Орды о том, как достичь твоей главной цели.", progress = nil, completion = "Похоже, сражения закалили тебя, Томпсон. Но достаточно ли в тебе силы и решимости, чтобы противостоять Разелиху и его приспешникам?", rewards = "Вы получите:\n\n"},
[3627] = {title = "Воссоединить расколотый амулет", objective = "Убейте Грола Разрушителя, леди Севину и верховного мага Аллистария. С их трупов заберите Амулет Грола, Амулет Севины и Амулет Аллистария.\n\nПомните о том, что нужно использовать зачарованное азшаритовое оружие, отравленное Скверной, чтобы ослабить троицу! Их нельзя убить иначе – но используйте оружие разумно...", description = "Чтобы добраться до Осквернителя, тебе следует сначала уничтожить троицу силы и собрать осколки амулета. Когда у тебя в руках будут все три осколка, возвращайся ко мне, и я скажу, что делать дальше.\n\nИди, <имя>! В Выжженные земли! Севина, Аллистарий и Грол должны погибнуть!", progress = "Три должны образовать один, один должен осветить путь.", completion = "Амулет Разелиха Осквернителя наконец-то собран воедино. Но Разелих чует, что цепь его власти порвана. Он знает, что ты собираешься убить его...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3628] = {title = "Ты – Рах'лих, демон!", objective = "Уничтожьте Разелиха Осквернителя и вернитесь к Павшему герою Орды с Отрубленным Рогом Осквернителя. Вам также понадобится вернуть Оберег Осквернителя, чтобы Павший герой мог уничтожить его, дабы оберег не попал к тому, кто использует его во зло.", description = "Логово Разелиха находится на вершине самой высокой горы Выжженных земель. Единственный способ достигнуть логова – это использовать телепортирующие руны поблизости от горы. Пока у тебя есть этот амулет, ты свободно можешь переместиться в логово. А достигнув логова, призови зверя. Ключ к этому – твой амулет, <имя>. Используй его на Алтаре Осквернителя.\n\nЕсли одолеешь Осквернителя, принеси его рог. Он станет символом надежды для всех, кто увидит его – доказательством того, что в этом раздираемом войнами мире еще есть герои!", progress = "Больше нечего бояться.", completion = "Сегодняшний день останется в памяти навеки. Демонический повелитель Выжженных земель наконец-то пал!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nОжерелье УбежищаКровь демонаМешок из шкуры демона"},
[3629] = {title = "Гоблинское инженерное дело", objective = "Если вы хотите узнать больше о гоблинском инженерном деле, отнесите справочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.", description = "В инженерном деле есть две дисциплины: гномская и гоблинская. Я – честный учитель, и только поэтому упомянул гоблинское инженерное дело. Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер.\n\n<имя>, почитай этот справочник. Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск. Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[3630] = {title = "Гномское инженерное дело", objective = "Если вы хотите узнать больше о гномском инженерном деле, отнесите справочник по инженерным дисциплинам мехмастеру Замыкальцу в Стальгорн.", description = "В инженерном деле есть две дисциплины: гномская и гоблинская. Гномское инженерное дело пока что зарекомендовала себя лучшей из двух. В ней речь идет о конструировании чудесных штучек и приспособлений, которые украшают жизнь!\n\n<имя>, почитай этот справочник. Если ты захочешь больше узнать о гномском инженерном деле, то отнеси его мехмастеру Замыкальцу в Стальгорн. Помни – выбор твой не подлежит пересмотру, и изучить другую дисциплину ты не сможешь, так что удостоверься в своем выборе, прежде чем выполнять его задание!", progress = "Да-да, чем могу служить? Времени у меня теперь более чем достаточно; ведь все, что я делаю – это стою здесь, пока наш любимый город охвачен смертельным радиоактивным облаком.", completion = "А, молодой инженер, заинтересованный в освоении единственно верной школы инженерного дела! Что ж, дружище, прости мне мою мелодраматичность. Пока ситуация наша остается тяжелой, день всегда кажется светлее, когда встречаешь собрата по ремеслу, откликнувшегося на трубный призыв истинного инженерного дела!", rewards = "Вы получите:\n\n"},
[3631] = {title = "Призывание коня Скверны", objective = "Поговорите в Кабестане со Страхадом Фарсаном.", description = "Хммм. Я сказал бы, что ты еще <не готов/не готова>, но тут не мне решать. Страад думает иначе, а решает он... пока.\n\nОн хочет с тобой говорить, причем срочно. Он пока все еще в Степях над Кабестаном, в своей маленькой башне со своими учениками.\n\nДолго не тяни.", progress = nil, completion = "Значит, ты снова решил пожаловать меня своим визитом. Очень мило с твоей стороны.\n\nМои помощники все гадали – придешь или нет? Я говорил им – несомненно, придет. Когда речь заходит о могуществе, летишь как мотылек на свечу.", rewards = "Вы получите:\n\n"},
[3632] = {title = "Гномское инженерное дело", objective = "Возьмите Справочник по инженерным дисциплинам и отнесите его мехмастеру Замыкальцу в Стальгорн.", description = "На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Гномская намного сильнее! Она занимается конструированием чудесных штучек и устройств, которые делают лучше нашу жизнь!\n\n<имя>, прочтите эту инструкцию. Если вы желаете узнать побольше о гномском инженерном деле, отнесите этот справочник мехмастеру Замыкальцу – он здесь, в Стальгорне. Помните: если выберете гномское инженерное дело, то это с концами, другим направлением вы заниматься не сможете, так что подумайте хорошенько, прежде чем выполнить его поручение!", progress = "Да-да, какие ваши запросы я могу удовлетворить ныне? Воистину, времени у меня много, ибо я только и делаю, что ошиваюсь здесь, когда наш возлюбленный город лежит, окутанный смертоносным радиоактивным облаком!", completion = "А, юный инженер желает изучать единственное истинное направление в инженерном деле! Простите мне мою горячность, любезный друг. В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!", rewards = "Вы получите:\n\n"},
[3633] = {title = "Гоблинское инженерное дело", objective = "Если вы хотите узнать о гоблинском инженерном деле, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.", description = "Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской. Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую. Покори же мир с помощью отборной взрывчатки и фантастических механизмов!\n\nПрочитай этот учебник, <имя>. Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске. Помни: сделав выбор единожды, ты не сможешь передумать. Поэтому хорошо подумай, прежде чем браться за задание Никса.", progress = "Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?", completion = "Что же, Тушканчег, ты нашел подходящего учителя! Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган. Требуется острый ум и верная рука (ключевое слово – ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела.\n\nДержи ушки на макушке, Тушканчег, и чему-нибудь научишься.", rewards = "Вы получите:\n\n"},
[3634] = {title = "Гномское инженерное дело", objective = "Если хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите мехмастеру Замыкальцу в Стальгорн.", description = "На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Она занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.\n\n<имя>, прочти эту инструкцию. Если ты желаешь узнать побольше о гномском инженерном деле, отнеси этот справочник мехмастеру Замыкальцу в Стальгорн. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься другим направлением, так что подумай хорошенько, прежде чем выполнить поручение Замыкальца!", progress = "Да-да, какие ваши запросы я могу удовлетворить ныне? Воистину, времени у меня много, ибо я только и делаю, что ошиваюсь здесь, когда наш возлюбленный город лежит, окутанный смертоносным радиоактивным облаком!", completion = "А, юный инженер желает изучать единственное истинное направление в инженерном деле! Простите мне мою горячность, любезный друг. В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!", rewards = "Вы получите:\n\n"},
[3635] = {title = "Гномское инженерное дело", objective = "Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую бухту.", description = "На высоких уровнях инженерное дело расходится на два направления: гномскую и гоблинскую. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Гномы занимаются конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.\n\n<имя>, прочти этот учебник. Если ты хочешь научиться делать металлические пресс-папье, отнеси его Карлсу Пропеллерзу в Пиратскую бухту. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько, прежде чем выполнить поручение Карлса!", progress = "Эй, ты! Если собираешься жаловаться, что мой автономный робот пробил стену твоего дома, можешь сразу обращаться к адвокату. Или ты по другому поводу?", completion = "Значит, тебе захотелось поучиться гномскому инженерному делу? Что ж, я очень подходящий гном. Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решетку.\n\nМы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней. Если ты – способный ученик, я обучу тебя всему, что знаю.", rewards = "Вы получите:\n\n"},
[3636] = {title = "Нести свет", objective = "Убейте Амненнара Хладовея на Курганах Иглошкурых.", description = "Плеть постоянно досаждает силам Альянса. Думаю, <имя>, ты знаешь об этом не хуже меня. В последнее время нам удалось сделать пару интересных находок.\n\nВ Степях есть жуткие заросли терновника, называемые Курганы Иглошкурых. Сначала казалось, что там обитают только иглогривы, но теперь выясняется, что в этих зарослях гнездятся самые разнообразные чудовища. Управляет ими лич по имени Амненнар Хладовей.\n\nВо имя Света, <имя>! Изгони зло с холмов Иглошкурых!", progress = nil, completion = "Спасибо, Билз. Теперь Плеть подумает дважды, прежде чем выпускать на нас своих гадов.\n\nДа хранит тебя Свет!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nМеч ПокорителяТалисман Янтарного света"},
[3637] = {title = "Гномское инженерное дело", objective = "Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую бухту.", description = "На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Она занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.\n\n<имя>, прочти этот учебник. Если ты хочешь научиться делать металлические пресс-папье, отнеси его Карлсу Пропеллерзу в Пиратскую бухту. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько прежде, чем выполнить поручение Карлса!", progress = "Если собираешься жаловаться, что мой автономный робот врезался в стену твоего дома, можешь сразу обращаться к адвокату. Или ты по другому поводу?", completion = "Значит, тебе захотелось поучиться гномскому инженерному делу? Что ж, я очень подходящий гном. Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решетку.\n\nМы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней. Если ты – способный ученик, я обучу тебя всему, что знаю.", rewards = "Вы получите:\n\n"},
[3638] = {title = "Договор о неразглашении", objective = "Если вы согласны заниматься гоблинским инженерным делом, щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к Никсу Шепружину в Прибамбасске.", description = "Гоблинское инженерное дело нацелена на получение высоких прибылей и огромной взрывной силы! Наши чертежи позволяют нам создавать мощные бомбы и прочее оружие, и в справочнике, что у тебя в руках, об этом написано.\n\nНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только ты займешься гоблинским инженерным делом, то все. Доступа к гномскому инженерному делу не будет.\n\nЕсли ты по-прежнему хочешь заняться гоблинским инженерным делом, подпиши этот документ о пожизненном неразглашении тайн и снова обращайся ко мне. Но сначала подумай хорошенько.", progress = "Если ты подписал документ и готов отдать его мне, тогда вот что я скажу. Предупреждаю в последний раз – это билет в один конец. Если ты готов – добро пожаловать в наши ряды!", completion = "Добро пожаловать в клуб, Цинабал! Скоро ты получишь доступ к наиболее передовым разработкам во всем Азероте.\n\nТеперь, когда ты решил посвятить себя этому искусству, пора познакомиться с гоблинским инженерным делом. С этого мгновения мы будем помогать тебе разрабатывать план предельного раскрытия талантов гоблинского инженера!", rewards = "Вы получите:\n\n"},
[3639] = {title = "Покажи свою работу", objective = "Принесите 20 больших железных бомб, 20 шашек плотного динамита и 5 взрывоопасных овец Никсу Шепружину в Прибамбасск.", description = "Как твой наставник, я желаю увидеть образцы твоей работы. Ты опытный инженер, тут вопросов нет, <имя>. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гоблинскоориентированную технику для будущих трудов. Мне нужны следующие образцы: двадцать больших железных бомб, двадцать шашек плотного динамита и пять взрывоопасных овец – и смотри <сам/сама> не подорвись!\n\nСдай мне эти предметы, и я выдам твой собственный членский билет гильдии гоблинов-инженеров – он нужен для допуска ко всем наставникам гоблинского инженерного дела!", progress = "Как только я получу на рассмотрение твои инженерные изделия, я выдам тебе настоящий членский билет гильдии гномов-инженеров! Пока он будет действителен, ты будешь иметь неограниченный допуск к любому наставнику по гоблинскому инженерному делу в мире.", completion = "Вот твой первый членский билет гильдии гоблинов-инженеров!\n\nБилет оплачивается вперед за четырнадцать дней. Через две недели срок действия истечет. Когда это произойдет, то для продления заплати очередную пошлину любому наставнику гоблинской инженерного дела. Без билета твое членство будет временно приостановлено, и ты не будешь иметь доступа к новым чертежам.\n\nЭто никак не повлияет на уже обретенные знания: если уж стал гоблинским инженером, то это навсегда.", rewards = "Следующее заклинание будет наложено на вас:\n\nГоблинское инженерное дело\n\nВы получите:\n\nЧленский билет гильдии гоблинов-инженеров"},
[3640] = {title = "Договор о неразглашении", objective = "Щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к мехмастеру Замыкальцу в Стальгорне.", description = "Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам! Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у вас в руках, об этом написано.\n\nНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только вы займетесь гномским инженерным делом, то все. Доступа к гоблинскому инженерному делу не будет.\n\nЕсли вы по-прежнему хотите заняться гномским инженерным делом, подпишите этот документ о пожизненном неразглашении тайн и снова обратитесь ко мне. Хорошенько подумайте, <имя>.", progress = "Если вы подписали документ и готовы отдать его мне, тогда вот что я вам скажу.\n\nТайны, которые я вам доверю, настолько важны, что подписание Договора о неразглашении просто жизненно необходимо. Я сам такой подписывал, как и мои брат и сестра. Вы попадете в очень приятную компанию, инженер Август!", completion = "Добро пожаловать в клуб, Август! Скоро вы получите доступ к наиболее передовым разработкам во всем Азероте.\n\nТеперь, когда вы посвятили себя этому искусству, пора испытать ваши навыки гномского инженерного дела. С этого мгновения мы будем помогать вам разрабатывать план предельного раскрытия ваших талантов гномского инженера!", rewards = "Вы получите:\n\n"},
[3641] = {title = "Покажи свою работу", objective = "Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени мехмастеру Замыкальцу в Стальгорн.", description = "Как ваш наставник, я желаю увидеть образцы вашей работы. Вы опытный инженер, тут вопросов нет, <имя>. Но я надеюсь проанализировать ваши работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.\n\nСдайте мне эти предметы, и я выдам вам ваш собственный членский билет гильдии гномов-инженеров – он нужен для допуска ко всем наставникам гномского инженерного дела!", progress = "Как только я получу на рассмотрение ваши искусные инженерные изделия, я выдам вам настоящий членский билет гильдии гномов-инженеров! Пока он будет действителен, вы будете иметь неограниченный допуск к любому наставнику по гномскому инженерному делу в мире.", completion = "Вот ваш первый ччленский билет гильдии гномов-инженеров!\n\nБилет оплачивается вперед за четырнадцать дней. Через две недели срок действия истечет. Когда это произойдет, вы заплатите очередную пошлину любому наставнику гномской инженери и получите продление. Без билета ваше членство будет временно приостановлено, и вы не будете иметь доступа к новым чертежам.\n\nЭто никак не повлияет на уже обретенные вами знания: если уж стал гномским инженером, то это навсегда.", rewards = "Следующее заклинание будет наложено на вас:\n\nГномское инженерное дело\n\nВы получите:\n\nЧленский билет гильдии гномов-инженеров"},
[3642] = {title = "Договор о неразглашении", objective = "Если вы согласны заниматься гномским инженерным делом, щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к Карлсу Пропеллерзу в Пиратской бухте.", description = "Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам! Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у тебя в руках, об этом написано.\n\nНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только ты займешься гномским инженерным делом, то все. Доступа к гоблинскому инженерному делу не будет.\n\nЕсли ты по-прежнему хочешь заняться гномским инженерным делом, подпиши этот документ о пожизненном неразглашении тайн и снова обращайся ко мне. Но сначала подумай хорошенько.", progress = "Если ты подписал документ и готов отдать его мне, тогда вот что я скажу.\n\nХотя я не согласен с политикой Гномрегана – и особенно этого глупца, мехмастера Замыкальца – с политической точки зрения, документ о неразглашении превыше всего! Ты должен избрать свой путь и следовать им всю свою жизнь.", completion = "Добро пожаловать в клуб, Томпсон! Скоро вы получите доступ к наиболее передовым разработкам во всем Азероте.\n\nТеперь, когда вы посвятили себя этому искусству, пора испытать ваши навыки гномского инженерного дела. С этого мгновения мы будем помогать вам разрабатывать план предельного раскрытия ваших талантов гномского инженера!", rewards = "Вы получите:\n\n"},
[3643] = {title = "Покажи свою работу", objective = "Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени Карлсу Пропеллерзу в Пиратскую бухту.", description = "Как ваш наставник, я желаю увидеть образцы вашей работы. Вы опытный инженер, тут вопросов нет, <имя>. Но я надеюсь проанализировать ваши работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.\n\nСдайте мне эти предметы, и я выдам вам ваш собственный членский билет гильдии гномов-инженеров – он нужен для допуска ко всем наставникам гномского инженерного дела!", progress = "Как только я получу на рассмотрение твои инженерные изделия, я выдам тебе настоящий членский билет гильдии гномов-инженеров! Пока он будет действителен, ты будешь иметь неограниченный допуск к любому наставнику по гномскому инженерному делу в мире.", completion = "Вот твой первый членский билет гильдии гномов-инженеров!\n\nБилет оплачивается вперед за четырнадцать дней. Через две недели срок действия истечет. Когда это произойдет, то для продления заплати очередную пошлину любому наставнику гномского инженерного дела. Без билета твое членство будет временно приостановлено, и ты не будешь иметь доступа к новым чертежам.\n\nЭто никак не повлияет на уже обретенные знания: если уж стал гномским инженером, то это навсегда.", rewards = "Следующее заклинание будет наложено на вас:\n\nГномское инженерное дело\n\nВы получите:\n\nЧленский билет гильдии гномов-инженеров"},
[3644] = {title = "Продление членского билета", objective = "Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.", description = nil, progress = "Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.", completion = "Поскольку ты занимаешься гоблинским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский билет. Это даст тебе доступ к гоблинским чертежам соотвествующих наставников.\n\nБилет будет действителен две недели, по истечении которых придется снова заплатить.", rewards = "Вы получите:\n\nЧленский билет гильдии гоблинов-инженеров"},
[3645] = {title = "Продление членского билета", objective = "Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.", description = nil, progress = "Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.", completion = "Поскольку ты занимаешься гномским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский билет. Это даст тебе доступ к гномским чертежам соотвествующих наставников.\n\nБилет будет действителен две недели, по истечении которых придется снова заплатить.", rewards = "Вы получите:\n\nЧленский билет гильдии гномов-инженеров"},
[3646] = {title = "Продление членского билета", objective = "Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.", description = nil, progress = "Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.", completion = "Поскольку ты занимаешься гоблинским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский билет. Это даст тебе доступ к гоблинским чертежам соответствующих наставников.\n\nБилет будет действителен две недели, по истечении которых придется снова заплатить! Если ты хочешь иметь доступ к чертежам, не просрочивай платежи.", rewards = "Вы получите:\n\nЧленский билет гильдии гоблинов-инженеров"},
[3647] = {title = "Продление членского билета", objective = "Чтобы продлить членский билет, вам придется заплатить два золотых в качестве пошлины за продление.", description = nil, progress = "Чтобы продлить членский билет, вам придется заплатить два золотых в качестве пошлины за продление.", completion = "Поскольку ты занимаешься гномским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский билет. Это даст тебе доступ к гномским чертежам соотвествующих наставников.\n\nБилет будет действителен две недели, по истечении которых придется снова заплатить.", rewards = "Вы получите:\n\nЧленский билет гильдии гномов-инженеров"},
[3661] = {title = "Любимцы Элуны?", objective = "Собрерите во Внутренних землях 15 перьев диких совухов и отнесите их Эреласу Янтарному Небу в деревню Рут'теран.", description = "Дикие совухи – очень непредсказуемые существа, <имя>. Они могут быть мягкими и пушистыми, но если что-то дорогое для них окажется под угрозой, в них проснется настоящий зверь!\n\nГоворят, что этих животных создала сама Элуна, и я хочу узнать, правда это, или нет.\n\nМного диких совухов обитает во Внутренних землях – целые популяции примитивных, злобных существ. Не хочешь отправиться туда и принести мне их перьев?", progress = "Старайтесь избегать их, Эфром. Дикосовухи могут счесть вас за врага.", completion = "Спасибо за перья, Эфром.\n\nЧто вам удалось узнать о дикосовухах?\n\nВозможно, эти перья помогут узнать больше и сказать, являются ли они кровожадными монстрами или просто одичавшими питомцами. Надеюсь, когда-нибудь я узнаю правду.\n\nЯ продолжу свои исследования, а вы, пожалуйста, по истечении некоторого времени зайдите ко мне снова.", rewards = "Вы получите:\n\n"},
[3681] = {title = "Фолиант Божественности", objective = "Разыщите в Штормграде Даториана Ралла и поговорите с ним.", description = "Я вынужден прервать твое путешествие, <раса>. Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения.\n\nЕсли бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов.\n\nНайди Даториана Ралла в Штормграде. Он обучает паладинов в Соборе Света.", progress = nil, completion = "Добро пожаловать в Собор Света, |3-6(Паладин).", rewards = "Вы получите:\n\n"},
[3701] = {title = "Дымящиеся руины Тауриссана", objective = "Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессону.", description = "Отправляйтесь в дымящиеся руины Тауриссана в Пылающих степях и соберите как можно больше информации.\n\nГоворят, все руины просто усыпаны таинственными реликвиями. Возможно, вам надо начать поиски здесь, <имя>. Опасайтесь таурисанских стражей-убийц, что стерегут руины, охраняя все тайны, какие там могут быть.", progress = nil, completion = "Ох ты! Эта информация многое объясняет касательно Тауриссана.\n\nНо предстоит узнать еще больше!", rewards = "Вы получите:\n\nКольцо Аристократа"},
[3702] = {title = "Дымящиеся руины Тауриссана", objective = "Узнайте от королевского историка Аркессона историю Тауриссана.", description = "Не желаете ли услышать краткий обзор истории дворфов Черного Железа?", progress = "Позвольте мне закончить рассказ об истории Тауриссана.", completion = "Продолжим?", rewards = "Вы получите:\n\n"},
[3721] = {title = "Собственный ККХ", objective = "Тебе удалось выручить всех трех моих роботов серии ООХ! Ты сделал все, что требовалось и даже больше, поэтому я хочу особым образом отблагодарить тебя за помощь. Это миниатюрная версия того же робота, с которым ты провел так много времени и полюбил, ООХ!\n\nОбычно я никому не дарю такие опасные устройства, но ты оказал мне неоценимую помощь. Кроме того у этой тварюшки отключены боевые механизмы и устройство самонаведения.\n\nА в остальном это полноценный ООХ!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nМеханическая курица"},
[3741] = {title = "Ожерелье Хилари", objective = "Найдите ожерелье Хилари и верните его Хилари в Приозерье.", description = "Моя подруга Хилари потеряла ожелелье, и мы никак не можем отыскать его. Мы весь день сидели на одном и том же месте, удили рыбу, и уже все кругом обыскали. Наверное, оно упало в воду. Родители не разрешают нам плавать в озере... Мама говорит, что под водой водятся чудовища, но вы ведь их не боитесь, правда?\n\nПожалуйста, достаньте нам ожерелье.", progress = "Привет. Я очень переживаю из-за пропажи ожерелья. Ведь его мне папа привез! Кстати, он говорит, что в озере водятся чудовища. Вы уже их победили?", completion = "Спасибо, что достали мне ожерелье, господин |3-6(Паладин)... Вы очень добры! Моя кошечка тоже хочет сказать \"спасибо\" – верно, Эфси?", rewards = "Вы получите:\n\n"},
[3761] = {title = "Почва Ун'Горо", objective = "Принесите 20 образцов земли из Кратера Ун'Горо Геду на Вершину Старейшин Громового Утеса.", description = "Говорят, что почва из Кратера Ун'Горо наделена мощными магическими свойствами. Кругу Кенария нужно много этой почвы для исследований. Ступай в страшные окрестности Ун'Горо и добудь земли побольше.\n\nЭта богатая почва порой лежит большими грудами, а иногда ее находят у некоторых тварей. Относи землю к Геду – ищи кучки земли и таурена, раздающего команды. Он не злой, просто постарайся его не слишком донимать.", progress = "Вольно, рядовой. Если ты собираешься выгрузить землю из Ун'Горо – то жди команды! Если нет – кругом и марш отсюда!", completion = "Ладно, рядовой Томпсон, и не пытайся помогать мне сваливать эту землю в кучу! Если бы Великие духи этого хотели, то прямо тут и устроили бы чудо, что, не так?!\n\nВерховный друид Рунический Тотем опять хочет с тобой говорить, но чтобы выполнить его очередное поручение, тебе нужно разбираться в травничестве на уровне подмастерья. Но если ты еще не доучился, он все равно тебе дельце подберет.", rewards = "Вы получите:\n\n"},
[3762] = {title = "Помощь верховному друиду Руническому Тотему", objective = "Поговорите с верховным друидом Хамуулом Руническим Тотемом в Громовом Утесе.", description = "Извини, <класс>, можно тебя на минутку?\n\nКругу Кенария в Громовом Утесе требуются такие закаленные путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем.\n\nЕсли тебя это интересует, отправляйся в Громовый Утес на Вершину Старейшин и поговори с самим Хамуулом.", progress = nil, completion = "Привет тебе, |3-6(Маг). Я рад, что ты хочешь помочь нам в наших исследованиях. Сделать предстоит многое, и я дурно поступил бы, если бы сказал, что труды наши не сулят опасности. Надеюсь, это тебя не отпугнет... но, судя по твоему виду, тебе и прежде приходилось сталкиваться с опасностями.", rewards = "Вы получите:\n\n"},
[3763] = {title = "Помощь верховному друиду Оленьему Шлему", objective = "Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнассе.", description = "Простите, <класс>, не уделите ли вы мне крупицу вашего времени?\n\nДарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит не кто иной, как сам верховный друид Фэндрал Олений Шлем.\n\nПрошу вас, если вам интересно, поговорите с ним лично в анклаве Кенария в Дарнассе.", progress = nil, completion = "Что же, |3-6(Охотник)... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли.\n\nИ раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.", rewards = "Вы получите:\n\n"},
[3764] = {title = "Почва Ун'Горо", objective = "Принесите 20 образцов земли из кратера Ун'Горо Дженалю в дарнасский анклав Кенария.", description = "Говорят, что почва из Кратера Ун'Горо наделена мощными магическими свойствами. Я хочу знать, насколько эти слухи преувеличены. Ступай в заросший кратер Ун'Горо и добудь хороших образцов земли для наших исследований.\n\nТебе может показаться, что это дело не достойно тебя, но такое поведение не завоюет тебе приязни ни с моей стороны, ни со стороны Круга Кенария. Принеси образцы земли Дженалю, который наверняка сидит без дела вон за тем деревом – ищи кучки земли, и найдешь его. Снабжением занимается он, не я.", progress = "А, опять эта грязь. Верховный друид требует с каждого искателя приключений по двадцать кучек – двадцать кучек ему и будет. И пусть те, кто строит нам козни, топает по обочине!", completion = "Наконец-то ты сможешь избавиться от своего драгоценного груза, благородный |3-6(Маг). Тяжкая, наверное, ноша... не легче ноши созерцателя, вроде меня... Вот гонорар за работу, назначенный самим верховным дуидом.\n\nВерховный друид Олений Шлем опять хочет видеть тебя, Эфром, но ты получишь помощь при выполнении следующего его задания, если только будешь разбираться в травознании не хуже подмастерья. Но если даже ты и вовсе не травник, ты все равно можешь помочь Кругу!", rewards = "Вы получите:\n\n"},
[3765] = {title = "Проблема за морем", objective = "Отправляйтесь в Аубердин к Гершалу Шепоту Ночи.", description = "Штормград – невероятно суматошный город.\n\nЯ прибыл сюда издалека в поисках помощи. Говорят, отважные искатели приключений нередко бродят по этим улицам.\n\nМой брат Гершала на Темном Берегу нуждается в помощи. Он обитает в приморском городке Аубердине.\n\nЭто путешествие будет долгим и насыщенным. Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, <класс>.", progress = nil, completion = "О, вас прислал мой брат Аргос? Должно быть, вы устали от долгого пути. Но нам очень о многом нужно поговорить.", rewards = "Вы получите:\n\n"},
[3781] = {title = "Изучение рассветницы", objective = "Отнесите расписку верховного друида в получении семян Матренгилу Медвежьей Лапе в дарнасский анклав Кенария.", description = "При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун'Горо. Из этих семян проросло множество редких полезных трав. И одна из них – рассветница, таинственное растение, о котором мы мало что знаем. Я намерен разгадать его тайну.\n\nОтнеси это вниз, Матренгилу, и он даст тебе семена, чтобы ты <мог/могла> начать работу. Если все израсходуешь, тебе придется купить у него еще семян.", progress = "Да пребудут с тобой мир и спокойствие. Как понимаю, ты с поручением от самого верховного друида?", completion = "Да, расписка на двадцать пакетиков семян. Если все изведешь, еще достанем. Хотя производить семена Тарлендриса в большом количестве – дело, увы, недешевое. Потому Круг Кенария и просит помощи в частичном возмещении стоимости.\n\nТе, кто находит рассветницу и приносит нам, видит, что награда верховного друида с лихвой окупает труды.", rewards = "Вы получите:\n\nПакет семян Тарлендриса"},
[3782] = {title = "Изучение рассветницы", objective = "Отнесите расписку в получении семян Башане Руническому Тотему в Громовой Утес.", description = "При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун'Горо. Из этих семян проросло множество редких полезных трав. И одна из них – рассветница, таинственное растение, о котором мы мало что знаем. Я намерен раскрыть его тайну для Круга.\n\nОтнеси эту расписку моей дочери Башане Рунный Тотем, и она даст тебе семена, чтобы ты <мог/могла> начать работу. Если все израсходуешь, тебе придется купить у нее еще семян.", progress = "Да пребудет мир с тобой, друг. Как понимаю, ты здесь по делу от самого верховного друида?", completion = "Да, расписка на двадцать пакетиков семян. Если все израсходуешь, у меня есть еще на продажу. \n\nУвы, Томпсон, производить семена Тарлендриса в большом количестве дорого. Потому Круг Кенария и просит помощи в частичном возмещении стоимости.\n\nТе, кто находит рассветницу и приносит нам, видит, что награда верховного друида с лихвой окупает труды.", rewards = "Вы получите:\n\nПакет семян Тарлендриса"},
[3783] = {title = "Йети где-то рядом…", objective = "Соберите 10 толстых кусков меха йети для Юми Румпельшникер из Круговзора.", description = "У моих друзей всегда замечательные идеи. Я никогда не думала, что смогу сравниться с ними… до сегодняшнего дня! У меня созрел потрясающий план! Если обещаешь никому не говорить, я расскажу тебе его по секрету… \n\nЯ хочу сделать механического йети! Мои друзья с ума сойдут, когда увидят, что я смогла смастерить!\n\nДля начала мне понадобится толстый мех йети с холмов Ледополоха. Ты мне поможешь? Йети водятся к юго-востоку отсюда.", progress = "Мне так много нужно всего собрать, чтобы начать! Пожалуйста, принеси мне эти меха как можно скорее!", completion = "Это отличные меха, Эфром. Это чудесное начало воплощения моего плана!", rewards = "Вы получите:\n\n"},
[3784] = {title = "Помощь верховному друиду Руническому Тотему", objective = "Поговорите с верховным друидом Хамуулом Руническим Тотемом на Уступе Древних Громового Утеса.", description = "Извини, <класс>, можно тебя на минутку?\n\nКругу Кенария в Громовом Утесе требуются такие закаленные путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем.\n\nЕсли тебя это интересует, отправляйся в Громовый Утес на Вершину Старейшин и поговори с самим Хамуулом.", progress = nil, completion = "Приветствую, |3-6(Разбойник)! Я рад, что тебя заинтересовало наше исследование. Дел очень много, и я обманул бы тебя, сказав, что речь идет о безопасном задании. Надеюсь, тебя так просто не напугать... По твоему виду можно предположить, что тебе приходилось сталкиваться с опасностями.", rewards = "Вы получите:\n\n"},
[3785] = {title = "Изучение рассветницы", objective = "При помощи сумы вечного цветения, пакетика семян Тарлендриса и двух порций земли Ун'Горо попытайтесь прорастить рассветницу.\n\nПринесите 10 рассветниц Матренгилу Медвежьей Лапе в Дарнасс.", description = "Это сума вечного цветения для семян Тарлендриса. Еще тебе понадобится почва из Кратера Ун'Горо как удобрение для семян. Когда достанешь все, что надо, просто используй суму, она позаботится обо всем.\n\nКогда у тебя будет достаточно рассветницы, принеси ее мне сюда в анклав. И не утруждай верховного друида: он эльф занятой, не стоит отрывать его от дела всякий раз, как кто-то приносит очередную порцию зерна!", progress = "Ну что, Эфром, удалось вырастить рассветницу для архиважных исследований верховного друида? Его труды во благо Круга Кенария чрезвычайно важны, и твоя помощь будет весьма кстати!", completion = "Очень хорошо, Эфром, я непременно отнесу их лично верховному друиду, когда они ему понадобятся. А пока прими это в знак признательности от Круга Кенария. \n\nНам рассветница нужна всегда. Если ты желаешь и дальше помогать нам, приноси любую рассветницу, какую сумеешь вырастить.", rewards = "Вы получите:\n\nТайник Круга Кенария"},
[3786] = {title = "Изучение рассветницы", objective = "При помощи сумы вечного цветения, пакетика семян Тарлендриса и двух порций земли Ун'Горо попытайтесь прорастить рассветницу.\n\nПринесите 10 рассветниц Башане Руническому Тотему в Громовой Утес.", description = "Вот сума вечного цветения для семян Тарлендриса. Еще тебе понадобится почва из Кратера Ун'Горо как удобрение для семян. Когда достанешь все, что надо, просто используй суму, а уж она сама позаботится обо всем.\n\nКогда у тебя будет достаточно рассветницы, принеси ее мне сюда на Вершину Старейшин. И не утруждай верховного друида – он очень занят исследованиями, да и других забот у него полон рот.", progress = "Добро пожаловать Тузвколоде. Ты вырастил рассветницы для наиважнейших исследований верховного друида? С каждым днем таинственные свойства Кратера Ун'Горо становятся все понятнее благодаря помощи таких, как ты!", completion = "Очень хорошо, Тузвколоде, я непременно отнесу их лично верховному друиду, когда они ему понадобятся. А пока прими это в знак признательности от Круга Кенария. \n\nНам рассветница нужна всегда. Если ты желаешь и дальше помогать нам, приноси любую рассветницу, какую сумеешь вырастить.", rewards = "Вы получите:\n\nТайник Круга Кенария"},
[3787] = {title = "Просьба друида", objective = "Поговорите с Квинтисом Ночным Костром в Крепости Оперенной Луны.", description = "Простите, <друг мой/уважаемая госпожа>...\n\nМой коллега хотел бы поговорить с вами касательно проводимых вами совместно с Кругом Кенария исследований. Он друид, зовут его Квинтис Ночной Костер, и живет он в Крепости Оперенной Луны в Фераласе. Он хотел бы посоветоваться с вами насчет рассветницы... и он очень хотел бы, чтобы этот разговор не дошел до ушей верховного друида.\n\nЕсли вы заинтересовались, поговорите с Кинтисом; не сомневайтесь, он расскажет вам все подробно.", progress = nil, completion = "Благодарю вас за ваш визит, усталый путник! Позвольте представиться: я – Квинтис Ночной Костер, друид и скромный слуга Малфуриона и Круга Кенария. Мои коллеги (генерал Шандриса Оперенная Луна и Протекторат – вы, может быть, о нас слыхали) и я хотели бы поговорить с вами о той работе, которую вы проводите для Фэндрала Оленьего Шлема в Дарнассе.\n\nПрежде чем мы пойдем дальше, я хотел бы попросить вас, чтобы этот разговор остался строго между нами. Если вы с этим согласны, мы можем продолжать.", rewards = "Вы получите:\n\n"},
[3788] = {title = "Кинтис Пламень", objective = "Поговорите с друидом по имени Квинтис Ночной Костер в Крепости Оперенной Луны.", description = "Простите, друг мой…\n\nОдин мой коллега хотел бы побеседовать с вами об исследованиях, которые вы ведете в сотрудничестве с Кругом Кенария. Это друид по имени Квинтис Ночной Костер. Он проживает здесь же, в Крепости Оперенной Луны. Он хотел бы поговорить с вами насчет рассветницы... а главное, очень просит вас, чтобы эта беседа не дошла до ушей верховного друида.\n\nЕсли вас это интересует, поговорите с ним, и вам все станет ясно.", progress = nil, completion = "Благодарю вас, что явились ко мне, усталый путник! Позвольте представиться. Я – Квинтис Ночной Костер, друид и смиренный служитель Малфуриона и Круга Кенария. Мои коллеги (генерал Шандриса Оперенная Луна и Протекторат – быть может, вы о нас слышали), и я хотел поговорить с вами о работе, которую вы ведете в Дарнассе по поручению Фэндрала Оленьего Шлема.\n\nНо прежде, чем мы продолжим наш разговор, я хотел бы вас попросить, чтобы эта беседа осталась между нами. Если вы не против, то мы можем перейти к делу.", rewards = "Вы получите:\n\n"},
[3789] = {title = "Помощь верховному друиду Оленьему Шлему", objective = "Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнассе.", description = "<класс>, простите, но нельзя ли отвлечь вас на минутку от ваших дел?\n\nКруг Кенария в Дарнассе приглашает искателей приключений для участия в жизненно важном проекте. Я не знаю всех подробностей, собственно, могу сказать только, что верховный друид Фэндрал Олений Шлем рассылает это приглашение.\n\nЕсли вас это интересует, обратитесь к нему напрямую, вы найдете его в дарнасском анклаве Кенария.", progress = nil, completion = "Что же, |3-6(Маг)... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли.\n\nИ раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.", rewards = "Вы получите:\n\n"},
[3790] = {title = "Помощь верховному друиду Оленьему Шлему", objective = "Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнассе.", description = "Простите, <класс>, не уделите ли вы мне крупицу вашего времени?\n\nДарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит ни кто иной, как сам верховный друид Фэндрал Олений Шлем.\n\nПрошу вас, если вам интересно, поговорите с лим лично в анклаве Кенария в Дарнассе.", progress = nil, completion = "Что же, |3-6(Жрец)... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли.\n\nИ раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.", rewards = "Вы получите:\n\n"},
[3791] = {title = "Тайна рассветницы", objective = "Принесите 10 рассветниц друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны.", description = "<имя>, я буду с вами откровенен. Меня интересует – точнее, тревожит вопрос, почему верховный друид в Дарнассе пользуется именем и возможностями Круга Кенария для того, чтобы добывать огромное количество рассветницы. Я – исследователь, и специализируюсь на проклятиях. И я слышал, что рассветница в соответствующих условиях приобретает те же свойства, что и прочие травы, используемые в примитивных проклятиях.\n\nЯ хотел бы узнать об этом подробнее. И мне нужна ваша помощь. Принесите мне десять рассветниц, и я буду у вас в долгу!", progress = "Мне нужно десять рассветниц – этого должно хватить как минимум для первоначальных исследований. Конечно, поначалу немалое количество материала будет потрачено на тупиковые эксперименты, но такова уж природа научного исследования!", completion = "Какое... какое странное ощущение вызывают у меня эти растения! Во имя Элуны, что же затеял Олений Шлем?\n\nНу, как бы то ни было, спасибо вам за помощь. Вот кое-что... ну, понимаете, за труды. Мои исследования, несомненно, затянутся, и мне потребуется еще немало такой травы. Раз уж я этим занялся, пожалуй, стоит проверить, пригодна ли рассветница для использования в алхимии. И тем не менее мне не по себе от этих растений...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nИсследовательские перчатки КвинтисаНаплечье Железной коры\n\nВы также получите:\n\n"},
[3792] = {title = "Рассветница для Крепости Оперенной Луны", objective = "А, здравствуйте, Мерандир! Мои исследования продвигаются неплохо, но, если у вас найдется еще пять рассветниц, я бы с удовольствием их у вас приобрел. Хотя, конечно, с удовольствием – это только фигура речи: чем больше я имею с нею дело, тем сильнее мне не по себе. И тем не менее я не намерен отказываться от дальнейших экспериментов!", description = nil, progress = "А, здравствуйте, Мерандир! Мои исследования продвигаются неплохо, но, если у вас найдется еще пять рассветниц, я бы с удовольствием их у вас приобрел. Хотя, конечно, с удовольствием – это только фигура речи: чем больше я имею с нею дело, тем сильнее мне не по себе. И тем не менее я не намерен отказываться от дальнейших экспериментов!", completion = "Спасибо, Мерандир. Я их пока припрячу. У меня, конечно, нет таких значительных средств, как у Оленьего Шлема, однако я все же способен вознаградить вас за труды! Тем более, кто знает, что может случиться, если Олений Шлем будет получать все больше рассветницы... Тут что-то нечисто, помяните мои слова!\n\nНе забывайте, что от лишней рассветницы я никогда не откажусь. Приносите по пять штук за раз, и я их возьму.", rewards = "Вы получите:\n\nПакет семян Тарлендриса"},
[3801] = {title = "Наследие Черного Железа", objective = "Чтобы получить ключ от города, поговорите с Франклорном Искусником.Привет тебе, <имя>. Я Франклорн Искусник. Да, тот самый Франклорн Искусник, который придумал, как тесать камень. За долгие странствия по терзаемому войнами миру тебе несомненно случалось проходить сквозь мои творения или стоять на них.\n\nДолжно быть, тебе интересно, откуда я здесь и что мне от тебя нужно. Логичные вопросы.\n\nРазумеется, мне нужна твоя помощь. В обмен на нее я дарую тебе ключ, открывающий путь в глубины моего проклятого города.", description = "Привет тебе, <имя>. Я Франклорн Искусник. Да, тот самый Франклорн Искусник, который придумал, как тесать камень. За долгие странствия по терзаемому войнами миру тебе несомненно случалось проходить сквозь мои творения или стоять на них.\n\nДолжно быть, тебе интересно, откуда я здесь и что мне от тебя нужно. Логичные вопросы.\n\nРазумеется, мне нужна твоя помощь. В обмен на нее я дарую тебе ключ, открывающий путь в глубины моего проклятого города.", progress = nil, completion = "Жадность ли привела тебя сюда или слепая верность, от твоего предприятия будет благо нам всем.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3802] = {title = "Наследие Черного Железа", objective = "Убейте Точеня Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника.", description = "Точень Темнострой находится за Кольцом Закона в Зале Ремесла. Убей ничтожную тварь и забери Железного Друга.\n\nОтнеси Железного Друга в святилище Тауриссана и помести молот в предначертанное ему место: в руки статуи, воздвигнутой в мою честь.\n\nПосле этого откроется тайное отделение, в котором я спрятал главный ключ. А главное, Железный Друг навеки останется в моих руках. Если они предпримут попытку забрать его, то статуя и молот рассыплются и исчезнут вовек.", progress = "Статуя зловеще нависает над вами.", completion = "Молот легко встает на место, в руку массивного монумента Черного Железа. У основания статуи открывается тайное отделение. Внутри оказывается...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКлюч Тенегорна"},
[3803] = {title = "Рассветница для Дарнасса", objective = "Верховному друиду постоянно не хватает рассветницы для проведения исследований Круга Кенария. Мы принимаем ее партиями по десять пучков и в награду даем несколько полезных вещей. Когда соберешь десять пучков, сообщи мне, и я достойно награжу тебя.", description = nil, progress = "Верховному друиду постоянно не хватает рассветницы для проведения исследований Круга Кенария. Мы принимаем ее партиями по десять пучков и в награду даем несколько полезных вещей. Когда соберешь десять пучков, сообщи мне, и я достойно награжу тебя.", completion = "Великолепно! Верховный друид, несомненно, обрадуется этой рассветнице. Правда, должен признать... даже находиться рядом с ней с ней не особо приятно. Представляю, как тяжело верховному друиду все время возиться с этой травой!\n\nА это для тебя, Рысяниус. Круг Кенария благодарит тебя за безотказную помощь.", rewards = "Вы получите:\n\nТайник Круга Кенария"},
[3804] = {title = "Рассветница для Громового Утеса", objective = "Верховный друид постоянно ищет дополнительные источники рассветницы для исследовательского проекта Круга Кенария в Кратере Ун'Горо. Мы берем их партиями по десять штук и в награду даем несколько полезных вещей. Когда наберешь десять штук, сообщи мне, и я достойно награжу тебя.", description = nil, progress = "Верховный друид постоянно ищет дополнительные источники рассветницы для исследовательского проекта Круга Кенария в Кратере Ун'Горо. Мы берем их партиями по десять штук и в награду даем несколько полезных вещей. Когда наберешь десять штук, сообщи мне, и я достойно награжу тебя.", completion = "Великолепно – эта рассветница несомненно поможет нам в будущем! Мы знаем, что и ночные эльфы проводят подобные исследования трав, хотя непонятно, для чего будут они использовать результаты – если, конечно, что-нибудь найдут. Верховный друид считает, что рассветница будет нам нужна до тех пор, пока мы на узнаем тайну этого растения.\n\nА это для тебя, Скрепыш. Круг Кенария благодарит тебя за неустанную помощь.", rewards = "Вы получите:\n\nТайник Круга Кенария"},
[3821] = {title = "Скала Молота Ужаса", objective = "Отправляйтесь в Пылающие степи и выясните, что сталось с Ша'ни Гордым Клыком.", description = "Несколько недель назад Ша'ни была отправлена в Пылающие степи, чтобы исследовать странные ритуалы огров клана Огненного Чрева – что-то эти огры зашевелились в последнее время. \n\nКлинозуб сообщил мне, что от ее группы с тех пор не было вестей, и что главное сейчас – заняться неотложными делами. Представляешь?! А речь, между прочим, о моей жене! \n\nЯ не вправе оставить свой пост, но я должен знать, что случилось с Ша'ни! Отправляйся в Пылающие степи и найди ее!", progress = nil, completion = "Бедный мой Талтрак... \n\nА мы ведь хотели уехать во Внутренние земли вместе с родителями, когда закончим службу. Теперь этим мечтам не суждено сбыться!", rewards = "Вы получите:\n\n"},
[3822] = {title = "Кром'Грул", objective = "Заберите ноздревое кольцо Ша'ни у Кром'Грула и верните его Тал'траку из Каргата. Обыщите различные пещеры и рудники скалы Молота Ужаса.", description = "Они захватили весь мой взвод, <имя>. И всех, кроме меня, убили.\n\nИх главарь, Кром'Грул, оставил меня для совершения какого-то обряда.\n\nМеня приковали к этому алтарю и жестоко пытали. Через час мучений мое физическое тело умерло. Тогда эта тварь вырвала у меня из носа обручальное кольцо и напялила на свой палец. В жизни не встречала подобного варварства!\n\nНайди Кром'Грула и убей его! отнеси мое кольцо Талтраку.\n\nИ <имя>, скажи ему, что мы снова встретимся... в следующей жизни.", progress = "Тебе удалось найти Ша'ни? С ней все в порядке?", completion = "*Талтрак опускается на пол.*\n\nМы собирались уехать во Внутренние земли. Она рассказывала? Это было ее последнее задание.\n\n*Талтрак плачет.*\n\nОно мне не нужно, Томпсон. Оставь его себе или выброси, мне все равно! Теперь кольцо ничего для меня не значит. Без нее оно ничто...", rewards = "Вы получите:\n\nКольцо Ша'ни"},
[3823] = {title = "Угасание Огненного Чрева", objective = "Убейте 15 огров-магов, 7 огров и 7 громил из клана Огненного Чрева. По выполнении задания вернитесь к Орелиусу.", description = "Мы должны нанести удар первыми!\n\nБуду краток.\n\nОгры Огненного Чрева – союзники орков Черной Горы в Пылающих степях. Рука об руку они охраняют богатую полезными ископаемыми скалу Молота Ужаса и линиии снабжения.\n\nОставь свой след в истории, <имя>. Смети их охрану и возвращайся ко мне.\n\n*Орелиус хватается за воздух, будто кого-то душит.*\n\nЯ тебя прибью, Винкей!", progress = nil, completion = "Потрясающе, солдат! Оркам и ограм понадобится несколько минут или даже часов, чтобы оправиться от удара!", rewards = "Вы получите:\n\n"},
[3824] = {title = "Гор'теш Жестокий", objective = "Найдите Гор'теша на западе от скалы Молота Ужаса. Убейте Гор'теша и отнесите его голову Орелиусу в Пылающие степи.", description = "Говорю же, они колеблются! Пора нанести решительный удар.\n\nМы должны убить жестокого вождя, Гор'теша. И что еще важнее, мне нужна его голова для третьей фазы операции против огров Огненного Чрева.\n\nИ помни, солдат, Гор'теш правит не из скалы Молота Ужаса, но из строения орков Черной Горы на западе от нее.\n\nИтак, приказы тебе даны ясные. Найди Гор'теша и отруби ему башку. Потом возвращайся ко мне.\n\nЗАТКНИСЬ, Винкей!", progress = "О радость, о счастье! Ты несешь его голову?", completion = "Только посмотрите на нее. Какая мерзость! Когда остатки огров Огненного Чрева увидят этот жирный чайник на вершине собственной скалы, начнется паника!\n\n*Орелиус хохочет.*", rewards = "Вы получите:\n\n"},
[3825] = {title = "Голова огра на палочке = вечеринка", objective = "Отнесите голову Гор'теша на вершину скалы Молота Ужаса. Поищите кучу рыхлой земли и воткните в нее пику.", description = "Осталось только одно задание, солдат.\n\nЯ позволил себе вольность – нанизал голову Гор'теша на пику. Тебе остается отнести ее на вершину скалы Молота Ужаса и воткнуть в землю. Стоит только сделать это, как трусливые огры бросятся куда глаза глядят! Когда ты повеселишься от души, возвращайся ко мне, и я награжу тебя за проделанную работу.\n\n*Кажется, Орелиус теряет связь с реальностью.*", progress = "Ну как? Ты зарисовал повальное бегство огров?", completion = "Отличная работа, солдат! Поразительная! Ах, я получу медаль за храбрость, то есть, я хочу сказать, ты получишь недурную награду!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБесящие рукавицыКольцо Удушья\n\nВы также получите:\n\n"},
[3841] = {title = "Бездомный сиротка", objective = "Поговорите с Квентином в Тысяче Игл.", description = "О, <имя>, привет! Я так рада видеть тебя снова! Как твое путешествие в Дарнасс?\n\nА у нас тут приятные новости! Пока тебя не было, мы сумели многого добиться. Мы даже спасли целую кладку яиц! К сожалению, самка погибла прежде, чем мы подоспели…\n\nСлушай, хочешь себе такого дракончика? Детеныши скоро должны вылупиться, и им понадобится <хороший папа/хорошая мама>. Ну, что скажешь?\n\nЕсли тебя это действительно интересует, возьми одно из яиц и ступай к Квентину, который находится на Мерцающей равнине, возле гоночной трассы. Он тебе скажет, что делать дальше.", progress = "А, |3-6(Охотник), привет!\n\nТы не думай, я тут не ради гонок... хотя зрелище, конечно, занимательное.\n\nЯ прибыл сюда, в Тысячу Игл, чтобы выяснить, можно ли спасти эти земли. Для меня это своего рода личный подвиг: добиться, чтобы эта пустыня вновь расцвела и зазеленела! Может быть, мне все же удастся обнаружить неподалеку источники воды...\n\nТы ведь не мог не заметить, какой резкий переход наблюдается между Фераласом и Тысячей Игл? Тут наверняка не обошлось без магии...", completion = "О, яйцо летучего хамелеона! И вот-вот должно проклюнуться, если я не ошибаюсь. Удивительно, как тебе удалось его добыть, да еще в таком хорошем состоянии? В Фераласе в наше время эти животные почти не делают кладок... Насколько я понимаю, в тамошних лесах развелась уйма браконьеров, которые охотятся на этих прекрасных созданий и убивают их. Какая жалость, не правда ли?\n\nНо откуда у тебя это яйцо?", rewards = "Вы получите:\n\n"},
[3842] = {title = "Инкубатор", objective = "Принесите 2 эликсира стойкости Квентину в Тысячу Игл.", description = "Кайдел и Джеркай? Занятно... Жаль, что летучие хамелеоны не смогут оценить все, что эти девушки для них делают. Очень, очень способные девочки…\n\nТак значит, они дали тебе это яйцо в подарок? Что ж, теперь оно твое и ты за него отвечаешь. Оно, похоже, вот-вот проклюнется, но нужно еще позаботиться о том, чтобы детеныш вылупился здоровым.\n\nДля заклинания, которое будет защищать яйцо, мне требуется только два эликсира стойкости. Остальные компоненты у меня уже есть.", progress = "Чем дольше я здесь нахожусь, тем сильнее мне хочется поучаствовать в этих гонках, Мерандир. Просто крышу сносит…\n\nНу что, удалось тебе добыть эликсиры? Как только я смогу поручиться за здоровье детеныша, я верну яйцо тебе, и оно останется у тебя, пока не проклюнется.\n\nСообщи мне, как добудешь их.", completion = "Великолепно! Это то, что надо. Сейчас, я смешаю все компоненты, и мы поглядим, как будет себя чувствовать детеныш...", rewards = "Вы получите:\n\n"},
[3843] = {title = "Новый член семьи", objective = "Отнесите хрупкое яйцо летучего хамелеона во Внутренние земли и поговорите с Агнаром Зверопасом. У вас есть на это всего 1 час. В противном случае детеныш в яйце умрет.", description = "Великолепный экземпляр, <имя>! Если это создание благополучно вылупится на свет, у тебя будет прекрасный, здоровый питомец!\n\nНо если ты рассчитываешь оставить его себе, я бы посоветовал сделать еще одну вещь. Отправляйся на Заоблачный Пик во Внутренних землях, и поговори там с дворфом по имени Агнар Зверопас. Он большой специалист по дрессировке животных, и объяснит тебе, что нужно делать дальше.\n\nТолько ступай скорее, <имя>, яйцо хрупкое и без должного ухода долго не протянет!", progress = "Привет, Мерандир! Чем могу пригодиться?", completion = "Так-так-так... Таких мелких я даже и не видел. Лесной дракончик, если не ошибаюсь... точнее, летучий хамелеон. Отлично, отлично!\n\nНу, чтобы этот малыш благополучно выжил и вырос крепким и здоровым, нужно раздобыть для него еды! Хорошо, что ты вовремя до меня добрался!", rewards = "Вы получите:\n\n"},
[3844] = {title = "Тайна, покрытая мраком", objective = "Осмотритесь и попытайтесь выяснить, кому мог бы принадлежать разбитый плот.", description = "На берегу вы видите разбитый плот. Если учесть, что пруд очень мал, непонятно, как мог оказаться в нем плот, да еще такой побитый непогодой. Хотя, более пристальный взгляд на деревья дает возможность предположить, что уровень воды здесь не постоянный... \n\nВозможно, если приглядеться повнимательней, можно отыскать ключ к загадке...", progress = nil, completion = "На дне пруда виднеется какой-то сверток.", rewards = "Вы получите:\n\n"},
[3845] = {title = "Тайна, покрытая мраком", objective = "Изучите найденное в сумке и верните владельцу.", description = "Вы вытаскиваете сумку на берег, в надежде, что ее содержимое укажет вам на то, откуда она могла взяться и кому бы могла принадлежать. \n\nВсе же немногие путники забредают в Укрытие Маршалла...", progress = "Приветствую! Простите, а мы не встречались раньше? Ваше лицо выглядит знакомым...", completion = "О, а вот это, похоже, и в самом деле мне знакомо!", rewards = "Вы получите:\n\n"},
[3861] = {title = "Куд-кудаааа!", objective = "Найдите немного цыплячьего корма и вернитесь к вашей курочке-подружке. Когда найдете ее, /поклонитесь ей прежде, чем накормить ее специальным цыплячьим кормом.", description = "\"... Кудах... кудах... Куд-кудааааа!\n\nКудах...кудах-тах-тах... \"\n\nКурица смотрит на вас и начинает что-то царапать на земле лапой. Вам кажется, что это какое-то слово,но вы не уверены, какое именно. Может... С-А-Л-Ь-Д-Е-А-Н? Прежде чем вы успеваете спросить, курица уходит по своим делам.", progress = "Курица смотрит на вас темным холодным и голодным взглядом и ждет.\n\n\"Куд-кудаааа!\n\nКудах...кудах-тах-тах.\"", completion = "\"Куд-кудааа!!!\"\n\nКурица начинает жадно клевать корм, который вы рассыпали перед ней.\n\nЧерез несколько мгновений она испуганно оглядывается по сторонам. Начинает скрести лапой и суетиться. Она что, яйца снести хочет? Вы думаете, что надо бы заглянуть под нее.", rewards = "Следующее заклинание будет наложено на вас:\n\nВызов куриного яйца"},
[3881] = {title = "Спасение экспедиции", objective = "Принесите ящик с провизией и исследовательское оборудование Виллидену Маршалу в Кратер Ун'Горо.", description = "Не знаю, какими судьбами ты <оказался/оказалась> здесь, но ты для нас <желанный/желанная> <гость/гостья>! Меня зовут Виллиден Маршал, я здесь с самостоятельной исследовательской экспедицией. Последняя и самая важная наша кампания столкнулась с многочисленными трудностями. Пожалуй, наиболее существенным нашим просчетом было то, что мы недооценили опасность, которую несет в себе дикая природа Кратера Ун'Горо. \n\nНам пришлось в спешке покинуть наши базовые лагеря в северо-восточной и юго-западной областях кратера, побросав жизненно-важные припасы. Ты выглядишь весьма внушительно – не поможешь ли нам вернуть их?", progress = "Если мы вообще хотим выжить в этом жутком месте, нам нужна провизия. А спасение хоть каких-то из наших исследовательских инструментов было бы просто манной небесной!", completion = "О, ты привез нам и нашу провизию, и наши инструменты! Ты не просто спас экспедицию, ты спас нам жизнь! Теперь-то мы сможем здесь продержаться! Не знаю, как благодарить тебя! \n\nХоть мы тут небогаты, без награды ты не останешься. Знай, Томпсон, в экспедиции Маршала у тебя есть друзья, готовые помочь в любую минуту!", rewards = "Вы получите:\n\n"},
[3882] = {title = "Игра в кости", objective = "Принесите 8 костей динозавра Искру Пустокопу в Кратер Ун'Горо.", description = "Думаешь, раз в экспедиции Маршала я ответственный за раскопки, то мне страшно нравится копаться в земле? Нет, я, конечно, мог бы придумать более паршивое занятие, но сейчас что-то ничего не приходит в голову.\n\nМы должны были вести раскопки в местечке под названием Путь Ужаса – неплохое название, не находишь? Искать, значит, там дохлых стегодонов и деметродонов... А их там, между прочим, и живых полным полно! Вил и Хол, видишь ли, хотят изучать это гиблое место, поэтому мы должны исправно поставлять им кости динозавров. Между нами говоря, живые для этих целей сгодились бы не хуже!", progress = "Можешь думать обо мне что хочешь, но эти лабораторные крысы даже не поймут, принадлежат ли принесенные им кости древним динозаврам или тем, которые пытались сожрать нас вместе с палатками прошлой ночью! Выбраться бы отсюда живым...", completion = "Прекрасно, отличные кости, ну просто прелесть, что за кости!\n\nСПАСИБО, ЧТО ВЫРЫЛ ДЛЯ НАС ЭТИ ДРЕВНЕЙШИЕ КОСТИ И НЕ ОХОТИЛСЯ НА ЖИВОТНЫХ, ЧТО МОГЛО БЫ НАНЕСТИ НЕПОПРАВИМЫЙ УЩЕРБ ОКРУЖАЮЩЕЙ СРЕДЕ! \n\nТихо, тихо, не спорь со мной, мне совершенно неинтересно, где ты на самом деле их взял, так что давай замнем этот вопрос за ясностью. Вот, возьми это в награду и держи рот на замке, хорошо?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nРаскопные сапоги археологаРабочий пояс кладоискателя\n\nВы также получите:\n\n"},
[3883] = {title = "Экология чужих", objective = "Воспользуйтесь фиалом для образцов, чтобы взять образец материала стены улья из одного из инкубаторов Гориши в Кратере Ун'Горо. Ищите в ульях комнаты со свисающими гроздьями личинок. \n\nПринесите образец материала стены улья Холании Маршал в Кратер Ун'Горо.", description = "То, что мы потерпели неудачу, еще не значит, что не значит, что исследования надо прекратить! Мы изучали насекомых Гориши в южной части кратера, прежде чем были вынуждены ретироваться сюда. Их присутствие чуждо для экологии Ун'Горо, и мы должны разобраться почему. \n\nВ их ульях должны быть инкубаторы для личинок. Эти места можно определить по свисающим гроздьям личинок. Возьми образец стены улья рядом с инкубатором вот в этот фиал и принеси его мне на исследование. Но будь <осторожен/осторожна>!", progress = "Ты принес мне образец для исследования, Томпсон?", completion = "О, прекрасно, ты очень помог мне. Хотелось бы мне дать тебе большую награду, но жизнь на лоне дикой природы накладывает свои ограничения. Однако могу заверить, без твоей помощи наши исследования были бы невозможны.", rewards = "Вы получите:\n\n"},
[3884] = {title = "Дневник Вилидена", objective = "Верните дневник Виллидену Маршалу, который находится где-то в Кратере Ун'Горо.", description = "Вы обнаружили изорванный дневник. Кое-какие страницы еще можно прочесть, в том числе и форзац, на котором значится имя Виллидена Маршала. Если верить написанному в дневнике, Виллидена можно найти где-то на севере кратера, куда он и его товарищи были вынуждены бежать от диких зверей, напавших на их базовый лагерь.", progress = "Приветствую! Мы с коллегами рады видеть собрата по разуму после стольких недель общения с диким зверьем! Что привело тебя в Кратер Ун'Горо?", completion = "Вы только взгляните на это! Мой дневник! Я думал, он утерян навсегда, как в все, что нам пришлось бросить в базовом лагере. Спасибо, что вернул мне его!", rewards = "Вы получите:\n\n"},
[3901] = {title = "Игрушки-погремушки", objective = "Убейте 12 скелетов-костетрясов, а затем вернитесь к жрецу Тьмы Сарвису в Могильник.", description = "Ты уже <продемонстрировал/продемонстрировала> свой потенциал в обычных обстоятельствах, <имя>, а теперь давай посмотрим, как ты будешь действовать под давлением. \n\nСкелеты-костетрясы – еще одни безмозглые приспешники Короля-лича – более серьезные враги, чем зомби, с которыми ты <сталкивался/сталкивалась> до этого. Я попрошу тебя уменьшить их количество и проявить себя среди Отрекшихся. Не мешкай! Когда все будет сделано – возвращайся ко мне.", progress = nil, completion = "Отличная работа, Сиамнео. Ты показал, что достоин свободы, которая была тебе дана. Многие будут ненавидеть тебя за то, кем ты стал, но знай: что бы они ни замышляли против нас, мы свободны, и никто не сможет вновь поработить Отрекшихся. \n\nВот, возьми это и ступай своей дорогой. Тебя ждут великие дела, |3-6(Разбойник).", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВолоконные сапогиМундир падальщикаПоножи скитальца\n\nВы также получите:\n\n"},
[3902] = {title = "Поиски старой одежды", objective = "Обыщите Могильник и его окрестности и найдите 6 ящиков с добычей и передайте их стражу смерти Салтену.", description = "Эй, ты! Если ищешь, что бы такого сделать полезного, слушай сюда! \n\nНам нужны свеженькие рекруты, только что из могилы, которых можно направить в Могильник, чтобы они поискали там что-нибудь стоящее из экипировки. Скорее всего, там будут груды ящиков. Мы надеемся, что вскоре поднимутся новые рекруты, а поскольку нам вовсе не надо, чтобы они слонялись тут голыми, надо бы поскорее чем-нибудь поживиться! \n\nА теперь за работу, несчастный ты мешок с костями! Я не собираюсь платить тем, кто еле двигается.", progress = "Тебе удалось найти что-нибудь стоящее? Нет ничего постыдного в повторном использовании выброшенных вещей. Никто не станет ничего давать нам – мы, Отрекшиеся, сами себя обеспечим!", completion = "Отличная работа, Сиамнео, я так и думал, что ты не совсем бесполезное существо. А это тебе – одна из лучших вещичек среди тех, что мы собрали.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВолоконный поясНаручи из ржавого металлаНакидка сумеречницы\n\nВы также получите:\n\n"},
[3903] = {title = "Милли Осворт", objective = "Поговорите с Милли Осворт.", description = "Ты <показал/показала> себя <надежным/надежной:c> <класс>, <имя>. Да и тяжелой работы не боишься, не правда ли?\n\nУ меня есть подруга, Милли Осворт. У нее какие-то проблемы. Она вместе со своим фургоном находится по другую сторону аббатства, у стойл. Думаю, ей очень пригодится твоя помощь.", progress = nil, completion = "О, заместитель судьи Виллем просил тебя поговорить со мной? Он отважный человек и всегда готов помочь, но дела не дают ему покинуть Аббатство Североземья, да к тому же, боюсь, нынешняя моя проблема ему не по плечу.\n\nВозможно, ты мне поможешь.", rewards = "Вы получите:\n\n"},
[3904] = {title = "Урожай Милли", objective = "Принесите 8 корзин с виноградом Милли Осворт в Аббатство Североземья.", description = "Шайка бандитов, это Братство Справедливости, проникла в Виноградники Североземья во время сбора урожая! Я сообщила об этом стражникам, и они заверили меня, что разберутся с этим делом, но... я боюсь за виноград! Если мой урожай не украдут грабители, так наши стражники потопчут!\n\nПрошу тебя, помоги мне! Я собрала большую часть винограда в корзины, но оставила их в виноградниках на юго-востоке.\n\nПринеси мне мой виноград, пожалуйста!", progress = "Ты принес мой виноград, Маркроу?", completion = "Ох, спасибо тебе, Маркроу! Ты спас мой урожай! И, надеюсь, ты показал этим бандитам, что тут им хозяйничать не позволят!\n\nМожет, стражи нам тут нынче и не достает, но зато у нас есть такие герои, как ты!!!", rewards = "Вы получите:\n\n"},
[3905] = {title = "Уведомление о поставке винограда", objective = "Отнесите уведомление о поставке винограда брату Нилзу в Аббатство Североземья.", description = "Теперь, когда мой урожай спасен, отнеси это уведомление о поставке винограда брату Нилзу. Он ведает съестными припасами в Североземье, и я уверена, что он обрадуется, узнав, что у него будет свежий виноград.\n\nБрата Нилза ты найдешь в аббатстве, в звоннице – он там любит... дегустировать вино.", progress = "Сдается мне, ты в хорошем настроении! Сядь, отдохни тут немножко. Хочешь вина?", completion = "Так, что у нас тут...\n\nХвала Свету! Виноград Милли спасен! Когда она сказала мне, что эти бандиты разнесли ее виноградники, я чуть не впал в уныние, но моя вера в Свет не дрогнула!\n\nИ благодаря твоей отваге теперь у нас есть виноград для вина! Да хранит тебя Свет, Хрофтгор!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗаляпанный вином плащПояс с пряжкой\n\nВы также получите:\n\n"},
[3906] = {title = "Дисгармония пламени", objective = "Отправьтесь в карьер у Черной горы и уничтожьте Подчинителя Пирона. По выполнению вернитесь к Громосерду.", description = "Старейшины говорят, духи стихий в последнее время неспокойны. Дворфы Черного Железа вызвали в наш мир злобного духа, и теперь он угрожает вечной засухой нашим землям. Мы должны найти причину беспокойства духов. \n\nОтправляйся к Черной горе, через пропасть Пламени, прямо в карьер. Найди там владыку огня – Подчинителя Пирона – и положи конец его злодеяниям!", progress = "Духи стихий все еще пребывают в беспокойстве, Тушканчег.", completion = "Не может быть... Не может быть! Уничтожение Пирона лишь приоткрыло завесу над истинным положением вещей. В глубинах Черной горы скрываются еще более коварные силы.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3907] = {title = "Дисгармония пламени", objective = "Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию.", description = "Я чувствую скверну в воздухе, <имя>! Источник ее скрывается в глубинах Черной горы. \n\nИмя его в стонах земли и ветра: лорд Опалитель... Но это еще не все: кто-то или что-то повелевает им. Сам он – лишь инструмент в более могущественных руках. \n\nНайди его и выясни, где скрывается его повелитель. Возвращайся ко мне, когда все разузнаешь.", progress = "Вскоре пламя поглотит эти земли. Торопись, Большеезло!", completion = "*Громосерд хватает табличку Каринья* \n\nРагнарос... здесь... \n\nСтарейшины были правы, страшась зла, исходящего от Черной горы. Могущественный служитель Древних Богов! В НАШЕМ МИРЕ! Мы должны оценить наши позиции здесь, в Каргате. Нужно решить, стоит ли остаться и драться или бежать в страхе перед новым Расколом. \n\nЛучше больше не приближайся к Черной горе, Большеезло. В ее глубинах кроется куда более великое зло, чем все, что встречалось тебе раньше.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСолнечная накидкаСумрачные перчаткиНаручи демона склепаСтойкий поясок\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[3908] = {title = "Тайна, покрытая мраком", objective = "Отнесите меч Линкена Донове Снегоноре.", description = "Видишь ли, я совершенно не представляю, как здесь оказался – просто тайна, покрытая мраком! Мне кажется, я вообще ничего не помню...\n\nЭти вещи все же кажутся мне знакомыми... \n\nМой меч. Я должен был как-то укрепить его, но совершенно не помню зачем? Мне жаль, что не могу сказать тебе больше, но я и в самом деле ничего не помню. \n\nВ любом случае, я знаю куда это отнести – к Донове Снегоноре в Зимние Ключи. Она может закалить меч в местных горячих источниках.", progress = "Ого! Неужели Линкен наконец-то собрался прислать мне свой меч?", completion = "Ну конечно, я могу закалить меч. А пока я работаю, расскажи мне, что так задержало Линкена. Обычно он не забывает о важных вещах.", rewards = "Вы получите:\n\n"},
[3909] = {title = "Эликсир Видере", objective = "Найдите Грегана Пивоплюя на севере Фераласа. Выясните у него, как получить эликсир Видере, и вернитесь к Донове Снегоноре.", description = "Что такое? Линкен ЗАБЫЛ ВСЕ? \n\nЯсно, потеря памяти... \n\nВот его меч. Он не закончен. Я знаю, кто может закончить его, но... Поговорите с ним – непростая задача. \n\nОднако, я знаю, кто сможет тебе помочь. Не буду вдаваться в подробности прямо сейчас, скажу только, что тебе необходимо любым способом заполучить эликсир Видере. Единственный, кто может помочь тебе в этом – Греган Пивоплюй. Его нелегко отыскать, но говорят, что недавно его видели в лесах Фераласа.", progress = "Уже вернулся?", completion = "Мне нужна одна склянка эликсира, чтобы проверить, правильный ли это состав... Да, это он.", rewards = "Вы получите:\n\n"},
[3911] = {title = "Последний элемент", objective = "Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности стихий. Стоит начать поиски с големов и их создателей. Вивиан Лягроб также бормотала что-то про элементалей.", description = "У меня есть работа для тех, кто не боится сунуться в глубины, <имя>! \n\nКлан Черного Железа научился создавать чрезвычайно мощных големов. \n\nИсходя из отчетов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим гоблинам невероятную разрушительную силу. \n\nПодумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют... Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без нее можешь не возвращаться! По усердию и награда.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПечать Лаграва"},
[3912] = {title = "Встречаемся на кладбище", objective = "Отправляйтесь на кладбище на окраине Прибамбасска и выпейте там эликсир Видере. Далее, следуя инструкциям Доновы, найдите Гаэриана.\n\nПрилагается предмет: \n", description = "Этот эликсир позволит тебе говорить с существами, которые обычно незримы. \n\nВозьми эликсир Видере и меч Линкена и отправляйся на кладбище на окраине Прибамбасска в Танарисе. Будешь на месте, выпей эликсир. Результат может показаться тебе неожиданным, но не впадай в панику. \n\nВ том обличье, которое ты примешь, отправляйся на север, в горы. Тот, кто тебе нужен, скрывается в скалистых ущельях. Его имя Гаэриан. \n\nПомни, ты сможешь поговорить с ним только переменив облик...", progress = nil, completion = "Давненько никто не говорил со мной...", rewards = "Вы получите:\n\n"},
[3913] = {title = "Замогильная история", objective = "Воскресните, найдите могильный камень, о котором говорил Гаэриан.", description = "Когда вернешься на кладбище, <имя>, увидишь там могильный камень, стоящий особняком. Под ним скрываются многие секреты! \n\nОтодвинь его, и тайны откроются тебе!", progress = "Похоже, это тот самый камень, о котором говорил Гаэриан.", completion = "Камень отодвинут в сторону, под ним находится небольшое углубление. Положив в него меч Линкена, вы понимаете, что меч идеально ложится туда.", rewards = "Вы получите:\n\n"},
[3914] = {title = "Меч Линкена", objective = "Доставьте превосходный меч Линкена Линкену в Кратер Ун'Горо.", description = "Вокруг меча вспыхивает ослепительно яркое пламя. После того как оно угасло, вы можете снова взять меч. Он изменился!", progress = "О! Твое лицо мне знакомо! Постой, я угадаю!", completion = "Мой меч, он закончен! \n\nВспомнить бы еще, на что он мне сдался... \n\nДай-ка я пока заплачу тебе за работу.", rewards = "Вы получите:\n\n"},
[3921] = {title = "Венаки Бенике", objective = "Отнесите сломанный самофланж Венаки Бенике.", description = "Мне кажется, я сломал самофланж. Это плохо, потому что я успел рассказать о нем нескольким коллегам из Нижней шахты, и они очень заинтригованы. Надо починить его!\n\nОтнеси сломанный самофланж Венаки Бенике, который живет на юге от заставы Мор'шан, лагеря Орды между Степями и Ясеневым лесом. Она очень умная и любопытная. Покажи ей самофланж, и я не сомневаюсь, что она не упустит возможности починить его.", progress = "Я очень занята, |3-6(Воин). Если ты пришел не по важному делу, иди своей дорогой...", completion = "Что это? Самофланж, говоришь? Что такое самофланж??\n\nА... Посмотри, как он вибрирует, когда берешь его в руки. А внутри жужжат сложные шестеренки. Ух ты! Мне хочется починить его и узнать, зачем он тебе?", rewards = "Вы получите:\n\n"},
[3922] = {title = "Металлические заготовки", objective = "Принесите 15 металлических заготовок для деталей Венаки Бенике в Степи.", description = "Я готова заняться самофланжем, но для этого мне понадобятся запчасти. У меня кончились семнадцати с половиной миллиметровые заготовки для деталей, а для работы понадобится целая куча.\n\nПроще всего их достать у Нефтяного болота на востоке. Торговая Компания обычно хранит их в ведрах с инструментами. Ступай туда и поищи эти штуковины, а набрав достаточно, возвращайся.", progress = "Несешь заготовки, Демонорох? Я все посматриваю на самофланж, и мне не терпится им заняться.", completion = "О, ты принес их! Теперь я могу приступить к работе...", rewards = "Вы получите:\n\n"},
[3923] = {title = "Рилли Грязегоб", objective = "Отнесите разбитый и сломанный самофланж Рилли Грязегобу в Оргриммар.", description = "Увы, у меня ничего не вышло. Я добавила в самофланж несколько новых индикаторов, чтобы проверить его структурную целостность, и согласно им, структурная целостность на нуле. Я могу добавить пару циферблатов и рычаг-другой, но... Думаю, станет только хуже.\n\nОтнеси самофланж Рилли Грязегобу. Он работал на Торговую Компанию, и уж если Рилли не сможет починить эту штуку, то пиши пропало.\n\nОн работает в механической мастерской Ногга в Оргриммаре, в Аллее Чести.", progress = "Осторожно! Голову береги! Не стой под стрелой!", completion = "Что это? Надо же, самофланж. Откуда он у тебя? Неужели ты рыскал по владениям Торговой Компании в Степях?\n\nИнтересно, это говорит о смелости или о глупости?", rewards = "Вы получите:\n\n"},
[3924] = {title = "Руководство по самофланжу", objective = "Отнесите руководство по самофланжу Рилли Грязегобу в Оргриммар.", description = "Думаю, я смогу починить самофланж, но для этого мне понадобится руководство пользователя. В Торговой Компании у меня был соперник, начальник Медноклин. Он ревностно хранил тайны самофланжа и лишь частицы знания доверял самым надежным своим сторонникам. Я не входил в число избранных...\n\nНачальник Медноклин работает в северо-восточной части Степей, на Каменном карьере.", progress = "Где руководство?", completion = "Ты принес руководство! Мне не терпится узнать, как починить самофланж! Я говорил с Пароклапаном из Кабестана, и он просил поблагодарить тебя за услуги и вознаградить за них.\n\nЯ тоже весьма признателен, и если починю-таки эту штуку, сразу тебе сообщу...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГаечный ключ ТоркаОтвертка самофланжа\n\nВы также получите:\n\n"},
[3941] = {title = "Помощь гномов", objective = "Найдите Джей Ди Колли в Укрытии Маршалла.", description = "Думай, голова! Думай, шапку подарю... Я помню, что явился сюда с какой-то очень серьезной целью. Но совсем не помню с какой!\n\nЕсть идея, <имя>! Вон там, в пещерах живет гномесса по имени Джей Ди, я помню, она была очень добра ко мне, когда я впервые оказался здесь. Может, она сможет что-то рассказать. \n\nСпроси ее! Только осторожней, она все время возится с этими ужасными светящимися кристаллами, которых полно в этом кратере. Не знаю, зачем уж он ей нужны...", progress = nil, completion = "Стой на месте, не шевелись... Я испытываю новую комбинацию кристаллов...", rewards = "Вы получите:\n\n"},
[3942] = {title = "Память Линкена", objective = "Найдите Эридану Грусть Ветра на юге Оскверненного леса.", description = "О, Линкен? Да, смешной парень... Когда он впервые оказался здесь, бормотал всякую ерунду. Наверное, кто-то как следует двинул бедняге по голове! \n\nОднако кое-что из той чепухи, которую он нес, крепко засело у меня в памяти. Помню, он говорил, что делает какой-то тотем, и что ему необходимо поговорить с какой-то Эриданой Грустью Ветра... кажется, в месте, называемом Оскверненный лес. Думаю, если хочешь узнать больше, тебе следует отпрявиться прямиком к этой Эридане.", progress = nil, completion = "Приветствую тебя, |3-6(Воин). Могу ли я чем-то помочь тебе?", rewards = "Вы получите:\n\n"},
[3961] = {title = "Приключения Линкена", objective = "Отнесите серебряный тотем Аквамонтоса Линкену в Укрытие Маршалла.", description = "Лично я полагаю, что Линкен явился сюда, чтобы избавить нас от Яропламеня... Он кажется простым парнем, однако он совсем не интересуется моими экспериментами и механизмами, как большинство гномов. Должно быть, в глубине души он истинный воин. \n\nОтдай тотем ему. Возможно, это поможет ему вспомнить, зачем он пришел сюда.", progress = "О, привет, Томпсон!", completion = "Джей Ди вообще хоть чем-нибудь помогла тебе?", rewards = "Вы получите:\n\n"},
[3962] = {title = "Один в поле не воин", objective = "Отправляйтесь к Вулкану Огненного Венца, к югу от Укрытия Маршалла. \n\nНайдите Яропламеня и разрушьте его защитную ауру с помощью тотема. Когда дух будет сражен, заберите из пещеры Золотое пламя.", description = "<имя>, я наконец-то вспомнил... Я пришел сюда, чтобы сразиться с Яропламенем! Это и есть цель моего путешествия! \n\nНо я больше не герой... потому что герой стоит передо мной. Теперь ты <должен/должна> закончить начатое. \n\nЯропламень стережет артефакт, именуемый Золотым пламенем. В нем кроется сила более мощная, чем что-либо мне известное, поэтому этот артефакт не должен попасть в дурные руки.\n\nИ мой тебе совет – не ходи <один/одна>. Один в поле не воин.", progress = "Яропламень почти неуязвим благодаря защитной ауре, создаваемой Золотым пламенем. Только тебе под силу разрушить ауру с помощью серебряного тотема Аквамонтоса.", completion = "Спасибо, Томпсон. \n\nТеперь Золотое пламя будет возвращено на мою родину, где мы сможем защитить его от посягающих на него негодяев. \n\nЕсли бы не ты, я до сих пор не помнил бы, кто я такой и зачем пришел! Я хочу отблагодарить тебя! \n\nБери все что нравится!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМеч мастерства ЛинкенаПризрак Аквамонтоса\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nБумеранг Линкена"},
[3981] = {title = "Командир Гор'шак", objective = "Найдите командира Гор'шака в Глубинах Черной горы. \n\nСудя по рисунку в записке, искать следует в темнице где-то вроде того.", description = "Бедняга Гаргал... Он даже не успел ничего понять как – бац! – стрела вонзилась прямо ему в башку... Он и прежде гением не был, а теперь уж... \n\n*Гэлмав скорбно морщится.* \n\nКогда мы вытащили стрелу, заметили записку, прикрученную к древку. В ней не было ничего, кроме грубо нацарапанной картинки, изображающей, видимо, орка за решеткой, и подписи командира Гор'шака. \n\nЕсли он еще жив и находится в Глубинах, ты <должен/должна> отыскать его. \n\nЛовушка? Проклятье, какая еще ловушка, что ты несешь?! Отправляйся немедленно!", progress = nil, completion = "У нас мало времени. Слушай внимательно, |3-6(нежить). Сведения, которые я сообщу тебе, совершенно секретны и не подлежат разглашению.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[3982] = {title = "Что происходит?", objective = "Защитите Горшака.", description = "Меня прислал сюда Тралл, и я нахожусь под его покровительством. Неужели ты думаешь, что эти фигляры смогли бы меня поймать? Я разведчик, и я им поддался специально, чтобы собрать информацию.\n\n*Горшак понижает голос.*\n\nИмператор Тауриссан похитил принцессу Стальгорна. Она сейчас здесь, в этом городе! Надо думать, когда старый Магни об этом узнал, его чуть удар не хватил.\n\n*Горшак смеется.*\n\nТихо! Слышишь? Это стражники! ЗАЩИЩАЙСЯ!", progress = "Защищайся, придурок!", completion = "На этот раз все обошлось. Но теперь они поднимут тревогу... и пришлют за тобой еще стражников.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4001] = {title = "Что происходит?", objective = "Поговорите с дворфом по имени Каран Могучий Молот и соберите информацию о похищении принцессы Мойры Бронзобород. Передайте информацию Траллу в Оргриммар.\n\nКарана держат в темнице напротив.", description = "Пока что мне не удалось толком поговорить с Караном из темницы напротив. Однако я все-таки смог убедить его в том, что я – то есть мы – не обидим его и не сделаем ему ничего плохого.\n\nПоговори с ним и попробуй узнать о принцессе и ее похитителях. Всю информацию, которую удастся собрать, передай вождю.\n\nТралл не хочет, чтобы с принцессой что-то случилось. У него даже есть план, как вернуть ее в целости и сохранности в Стальгорн, и Карану все это уже известно... Иди!", progress = "Что привело тебя в это мрачное место?", completion = "Сейчас у Орды есть шанс изменить политическую ситуацию в нашем мире, истерзанном войной. Причем изменить радикально. Раз и навсегда. Слушай внимательно, Двар.\n\nПостарайся, чтобы все получилось. Провал в этом деле смерти подобен.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4002] = {title = "Восточные королевства", objective = "Поговорите с Траллом.", description = "Принесенные тобой сведения чрезвычайно ценны, <имя>.\n\nЯ – вождь, и мой долг – действовать на благо Орды, так, чтобы грядущие поколения не были обречены на безнадежное прозябание!\n\nИ вот нам выпала возможность определить судьбу будущих союзов. Выступив на помощь дворфам, мы значительно укрепим свои взаимоотношения с Восточными королевствами. Вот почему твой долг – вернуться с победой!\n\n<Готов/Готова> ли ты?", progress = nil, completion = "Все, Надей. Отныне пути назад нет.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4003] = {title = "Спасение принцессы", objective = "Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия.", description = "Этот удар, нанесенный дворфам Черного Железа, способен потрясти их королевство до основания.\n\nПринцесса находится под контролем императора Тауриссана. Чтобы ее освободить, необходимо убить императора. Имей в виду, твоя задача вдвойне опасна: пока принцесса находится во власти императора, она нападет на тебя, не раздумывая.\n\nНи в коем случае не причиняй ей вреда!!!", progress = nil, completion = "Что ты наделал!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4004] = {title = "Спасенная принцесса", objective = "Вернитесь к Траллу.", description = "Ты <убил/убила> моего мужа, <раса>! Мой ребенок родится на свет без отца!\n\n*Принцесса Мойра указывает на вас.*\n\nИстинно говорю тебе, это дитя станет следующим королем Стальгорна. И тогда берегись! Этим преступным деянием ты <навлек/навлекла> на себя проклятие. Возмездие настигнет тебя и твой род. Всех вас будут травить до скончания дней!\n\n*Вы уверены, что принцесса Мойра до сих пор пребывает под действием чар Тауриссана.*\n\nОставь меня, <раса>. Поторопись к своему нанимателю. Наверняка он с нетерпением ждет вестей об исполнении его гнусных замыслов.", progress = nil, completion = "*Тралл поражен вашим рассказом. Он явно не ожидал ничего подобного.*\n\nСтало быть, надо ждать новой угрозы. Магни уже немолод, кто знает, сколько ему осталось. А если Магни не станет, дорога к трону Стальгорна будет открыта для еще не рожденного отпрыска Черного Железа.\n\nТы исполнил мое поручение и получишь награду.\n\nА теперь оставь меня, Надей! Мне надо посовещаться с Сильваной и Кэрном.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nРешимость ТраллаОко Оргриммара\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4005] = {title = "Аквамонтос", objective = "Отнесите книгу Аквора, серебристые когти и сердце Железнолесья в Танарис. \n\nВоспользуйтесь книгой для призыва Аквамонтоса. \n\nПо получении тотема, отнести его Джей Ди Колли в Укрытие Маршалла.", description = "Возьми этот мешок с припасами и отнеси в Танарис. Отправляйся в Бухту Сорванных Парусов и найди круг камней. \n\nВстав в этот круг, прочти заклинание из книги Аквора и вызови единственное создание, способное превратить собранные тобой предметы в тотем, с помощью которого можно сразить Яропламеня! \n\nАкваментас не любит, когда его будят, но помни, ты <должен/должна> быть внутри круга, когда будешь читать заклинание!", progress = "Так ты вернулся... Хмм... Дай-ка мне взглянуть...", completion = "Яропламень, говоришь...\n\nДа, я знаю, этот могучий элементаль обитает в опаленном центре кратера. Мы все стараемся держаться от этого места подальше – никому не удавалось проникнуть сквозь ауру этого создания. Многие смельчаки нашли свою смерть в расщелинах сердца кратера.", rewards = "Вы получите:\n\n"},
[4021] = {title = "Контратака!", objective = "Принесите кусок знамени Кром'зара Регтару Вратам Смерти. Его можно найти на западе от Перекрестка.", description = "Орда благодарит тебя за неустанную борьбу с кланом Колкар, но сами кентавры в ярости. Я получил сообщение, что отряд клана Колкар прибыл в Степи, оставив свой дом в Пустошах, жаждая мести. Более того, они прямо сейчас подбираются к нам с запада!\n\nВыступи против захватчиков из племени Колкар и положи конец опасности, грозящей Степям. Убивай их, пока не появится их вождь, предводитель Кром'зар. Одолей его и принеси в доказательство кусок его знамени.\n\nНе подведи меня, <имя>.", progress = "Где знамя?", completion = "Получилось! Ты победил клан Колкар!\n\nЯ непременно сообщу Траллу о твоих подвигах, Ахахаха.\n\nМожешь гордиться собой, ты – достойный сын Орды.", rewards = "Вы получите:\n\n"},
[4022] = {title = "Вкус пламени", objective = "Покажите Цирусу Раскаивателю сброшенную кожу черного дракона, полученную от Веларока Ветрореза.", description = "Стая знает о твоей работе в Тлеющем ущелье.\n\nПокажи ее, <раса>. Шкуру, <кретин безмозглый/кретинка безмозглая>.", progress = "*Глаза Цируса вспыхивают, как две пылающих сферы.*", completion = "*Цирус изучает шкуру.*\n\nНу что ж, тебе удалось доказать, что ты хоть на что-то пригоден, смертный.", rewards = "Вы получите:\n\n"},
[4023] = {title = "Вкус пламени", objective = "Покажите Цирусу Раскаивателю доказательство своих деяний.\n\nВозникает чувство, что Цирус заранее сомневается в ваших качествах.", description = "Ты ищешь Стаю? Принеси мне доказательства того, что ты <достоин/достойна> этого знания, <смертный/смертная>.", progress = "*Глаза Цируса вспыхивают, как две пылающих сферы.*", completion = "*Цирус изучает шкуру.*\n\nНу что ж, тебе удалось доказать, что ты хоть на что-то пригоден, смертный.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4024] = {title = "Вкус пламени", objective = "Отправьтесь в глубины Черной горы и убейте Бейл'Гора.\n\nИзвестно лишь то, что великан живет в глубинах. Воспользуйтесь измененной сброшенной шкурой черного дракона и возьмите из останков Бейл'Гора сущность Огня.\n\nОтнесите пойманную сущность Огня Цирусу Раскаивателю.", description = "Я хочу попробовать обжигающие языки пламени огненной горы. Чтобы сквозь меня текла лава Черной горы. Я жажду этого обжигающего тепла.\n\nБаэл-Гар живет в глубинах Черной горы. Он воплощение пламени, порождение огня Рагнароса.Убей Бейл'Гора и возьми из его дымящихся останков частицу его внутреннего огня.\n\nЧтобы взять, не обжигаясь, этот огонь, воспользуйся драконьей шкурой.\n\nДобейся успеха, и награда будет велика.", progress = "Пал ли от твоей руки великан?", completion = "*Цирус выхватывает сущность Огня у вас из рук.*\n\nДА!\n\nБери награду и убирайся. Долой с глаз моих!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНакидка Глинистой кожиНаплеч из шкуры змеяВальконийский кушак\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4041] = {title = "Эликсир Видере", objective = "Эликсир Видере? Ну да, смогу, конечно, только принеси сначала мне эвокорень.\n\nВ травках и алхимии я разбираюсь неплохо... Вот послушай, как я однажды трансмутировал в золото сыр, которым собирался пообедать... Эй, ты куда?", description = nil, progress = "Эликсир Видере? Ну да, смогу, конечно, только принеси сначала мне эвокорень.\n\nВ травках и алхимии я разбираюсь неплохо... Вот послушай, как я однажды трансмутировал в золото сыр, которым собирался пообедать... Эй, ты куда?", completion = "Ну что, удалось тебе обойти старого Миблона, а?", rewards = "Вы получите:\n\nЭликсир Видере"},
[4061] = {title = "Восстание машин", objective = "Отправляйтесь в Пылающие степи и соберите 10 осколков элементалей для верховной жрицы Теодоры Мальвадании. \n\nТеодора упоминала, что осколки можно найти у элементалей и големов.", description = "Впервые мы увидели эти машины, когда начали набеги в Тлеющее ущелье. Потом выяснилось, что их привозят из Пылающих степей, вероятно, из глубин Черной горы. Нам нужна твоя помощь, <имя>. \n\nДля выполнения первого задания отправляйся в Пылающие степи и извлеки осколки элементалей из каменных машин и малых каменных созданий, которых там найдешь. Когда соберешь достаточно, возвращайся ко мне, и я попробую разобраться, откуда они происходят.", progress = "Отнесись к этому заданию со всей серьезностью, Томпсон!", completion = "*Теодора раскладывает перед собой осколки и рассматривает их в огромную лупу.* \n\nПрелюбопытно... На каждом из этих осколков выгравированы... инициалы.", rewards = "Вы получите:\n\n"},
[4062] = {title = "Восстание машин", objective = "Отнесите образец осколка элементаля Лотвилю Вериатусу. \n\nТеодора упоминала, что его лагерь находится на востоке.", description = "Г.Л.А. \n\nЭти инициалы выгравированы на осколках элементалей. Под ними выгравирована надпись, видимо, указующая на ранг машины. Механизмы, уничтоженные тобой в Пылающих степях, имели четвертый ранг. Полагаю, это один их низших рангов. \n\nВозьми этот образец осколка и отнеси его Лотвилю Вериатусу в лагерь на востоке. Он ученый, весьма признанный в сферах изучения cтихий. Возможно, он поможет нам советом.", progress = "Что это у тебя, |3-6(нежить)?", completion = "*Лотвил неожиданно бледнеет* \n\nЯ узнаю эти знаки...", rewards = "Вы получите:\n\n"},
[4063] = {title = "Восстание машин", objective = "Найдите и убейте повелителя големов Аргелмаха. Принесите его голову Лотвилу. Также соберите 10 невредимых ядер стихий с беспощадных големов и созданий-завоевателей, охраняющих Аргелмаха. Информация передана посредством телепатии.", description = "Неужели это Аргелмах? Не может быть! Он же мертв уже много лет! Почему я так в этом уверен? Да потому что это я убил его! \n\nЭтот презренный дворф имел маниакальную страсть к извращению моих изобретений – над которыми я, к слову, корпел годами! – и использованию их для своих мерзких делишек. Надо же, самые мерзкие создания всегда самые живучие! \n\nЕсли это и правда работа Аргелмаха, то он должен быть уничтожен. И мне потребуются образцы его последних творений. Если у меня будут образцы, возможно, я смогу придумать, как подавить восстание. Видимо, Аргелмах теперь в глубинах Черной горы под охраной своих творений.", progress = "Так это и в самом деле был он? Так он жив?", completion = "Что это?! Голова... Она не из плоти и крови! Это какое-то создание из черного железа! Аргелмах был ЕЩЕ ОДНОЙ машиной! Полагаю, в таком случае нам рано праздновать победу – на его место вскоре придет другой!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛазурный лунный нарамникПелерина Заклинателя ДождяБазальтовая чешуйчатая броняЛавовые рукавицы\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4081] = {title = "УНИЧТОЖИТЬ НА МЕСТЕ: Дворфы Черного Железа", objective = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! \n\nПо приказу полководца Клинозуба уничтожьте 15 охранников, 10 надсмотрщиков и 5 пехотинцев из клана Ярости Горна. Вернитесь сразу по выполнении задания.", description = "По приказу полководца Клинозуба, командира каргатского экспедиционного отряда: \n\nВсе силы генерала Кузни Гнева в Глубинах Черной горы должны быть истреблены. \n\nКлан Кузни Гнева – беспощадные убийцы, ответственные за уничтожение 109-ого подразделения каргатского экспедиционного отряда. Необходимо сохранять бдительность. \n\nТот, кто сможет разбить передовые войска генерала Кузни Гнева в Глубинах Черной горы, будет представлен к награде.", progress = nil, completion = "Небось, после такого Кузня Гнева в штаны наложил! Теперь проходи, проходи, солдат. У меня еще масса дел!\n\nСмотри внимательно на объявления, для тебя может найтись еще работенка.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4082] = {title = "УНИЧТОЖИТЬ НА МЕСТЕ: Высокопоставленные чины Черного Железа", objective = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! \n\nПо приказу полководца Клинозуба уничтожьте 10 медиков, 10 солдат и 10 офицеров из клана Ярости Горна. Вернитесь сразу по выполнении задания.", description = "Приказ полководца Клинозуба, командира Каргатского экспедиционного корпуса: \n\nГлава разведывательного подразделения Каргатского экспедиционного корпуса, гроссмейстер Лекслорт вернулся с рапортом о месторасположении высокопоставленных чинов Черного Железа. В центре города, за закрытыми воротами они обучают своих солдат уничтожать наших собратьев. Отправляйся в Глубины Черной горы и уничтожь их! \n\nВ случае успешного выполнения задания будешь <представлен/представлена> к награде.", progress = nil, completion = "Не сомневаюсь, генерал Кузня Гнева теперь... в гневе. Возвращайся ко мне, когда получишь третью награду, и мы приступим к операции \"Смерть Кузне Гнева\". Пока не буду вдаваться в детали, но могу заверить наперед, что точно кто-нибудь умрет!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4083] = {title = "Призрачный кубок", objective = "Призрачный кубок парит в воздухе, медленно поднимаясь и опускаясь... как будто следуя ритмам биения умирающего сердца.", description = nil, progress = "Призрачный кубок парит в воздухе, медленно поднимаясь и опускаясь... как будто следуя ритмам биения умирающего сердца.", completion = "Драгоценные камни беззвучно падают в глубину кубка...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4084] = {title = "Серебряное сердце", objective = "Добудьте 11 серебристых когтей и 1 сердце Железнолесья для Эриданы Грусти Ветра.", description = "Я не знаю, о ком ты говоришь, <имя>. \n\nОднако если твой друг искал меня, я знаю, что ему было нужно. \n\nВ сердце Кратера Ун'Горо скрывается зло в чистейшей его форме – это элементаль, именуемый Яропламень. Он защищен аурой, разрушить которую не под силам никому... \n\nНикому, кроме обладателя еще большей силы. Я научу тебя, как справиться с этой задачей, <имя>. \n\nСначала сделай, что я попрошу. Собери и принеси мне 11 серебристых когтей и 1 сердце Железнолесья – ты найдешь их у созданий Оскверненного леса.", progress = "Я расскажу тебе о том, как сразить Яропламень, но прежде принеси мне то, что чем я просила тебя.", completion = "Прекрасно, Томпсон. Вижу, ты всегда готов помогать друзьям.", rewards = "Вы получите:\n\n"},
[4101] = {title = "Очищение Оскверненного леса", objective = "Принесите 15 кровавых янтарей Аратандис Серебряному Небу в Оскверненный лес.", description = "Растения дают жизнь Оскверненному лесу, но даже они поражены порчей. Я знаю способ исцелить их, но эти знания я не могу передать тому, к кому не питаю доверия или кого не знаю. Докажи мне, что ты от чистого сердца помогаешь Кругу Кенария!\n\nК северу отсюда лежат пещеры Железнолесья. Тамошние криводревы-элементали поражены порчей так, что исцелить их уже нет надежды. Прошу тебя – принеси мне их застывший сок – его называют кровавым янтарем – чтобы я могла изучить его в надежде спасти другие формы здешней жизни.", progress = "Оскверненный лес страдает, Кавару – а вместе с ним и я! Я должна быть уверена во всем – если мои знания попадут в злые руки, это обернется бедой для всего Оскверненного леса.\n\nПринеси мне кровавый янтарь с убитых Криводревов-элементалей, и я поверю, что ты искренне помогаешь мне в поисках средства борьбы с порчей.", completion = "Этот кровавый янтарь поможет мне найти средство борьбы с порчей, поразившей Оскверненный лес. Ты доказал мне, что готов сделать все для Круга Кенария. Теперь я доверяю тебе.\n\nМожет показаться странным, что доказательством твоей преданности послужило истребление элементалей, но наша цель – спасение бесчисленных живых существ – оправдывает средства. Теперь мы с тобой можем заняться спасением жизней при помощи бальзамов, которые я смогу сделать.\n\nПришла пора исцелить Оскверненный лес, Кавару.", rewards = "Вы получите:\n\n"},
[4102] = {title = "Очищение Оскверненного леса", objective = "Принесите 15 кровавых янтарей Майбессе Речному Ветру в Оскверненный лес.", description = "Растения дают жизнь Оскверненному лесу, но даже они поражены порчей. Я знаю способ исцелить их, но эти знания я не могу передать тому, к кому не питаю доверия или не знаю. Докажи мне, что ты от чистого сердца помогаешь Кругу Кенария!\n\nК северу отсюда лежат пещеры Железнолесья. Тамошние криводревы-элементали поражены порчей так, что исцелить их уже нет надежды. Прошу тебя, принеси мне их застывший сок – его называют кровавым янтарем, – чтобы я могла изучить его в надежде спасти другие формы здешней жизни.", progress = "Оскверненный лес страдает, Мулганус – а вместе с ним и я! Я должна быть уверена во всем – если мои знания попадут не в те руки, это обернется бедой для всего Оскверненного леса.\n\nПринеси мне кровавый янтарь с убитых Криводревов-элементалей, и я поверю, что ты искренне помогаешь мне в поисках средства борьбы с порчей.", completion = "Этот кровавый янтарь поможет мне найти средство борьбы с порчей, поразившей Оскверненный лес. Ты доказал мне, что готов сделать все для Круга Кенария. Теперь я доверяю тебе.\n\nМожет показаться странным, что доказательством твоей преданности послужило истребление элементалей, но наша цель – спасение бесчисленных живых существ – оправдывает средства. Теперь мы с тобой можем заняться спасением жизней при помощи бальзамов. которые я смогу сделать.\n\nПришла пора исцелить Оскверненный лес, Мулганус.", rewards = "Вы получите:\n\n"},
[4103] = {title = "Лекарство из охотничьих трофеев", objective = "Тот, кто имеет при себе Маяк Кенария, может оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.\n\nЗа эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений.", description = nil, progress = "Тот, кто имеет при себе Маяк Кенария, может оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.\n\nЗа эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений.", completion = "Очень хорошо, вот тебе кенарийский бальзам. Ищи в Оскверненном лесу пораженные растения, Димиллион! Когда найдешь, исцеляй их при помощи моего целебного бальзама.", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[4104] = {title = "Лекарство из минералов", objective = "Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.\n\nЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.", description = nil, progress = "Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.\n\nЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.", completion = "Что же, прекрасно! Вот тебе кенарийский бальзам. Если при разработках жил металлов в Оскверненном лесу найдешь еще порченого купороса, не забудь принести его мне! Чем больше найдешь, тем больше бальзама я смогу сделать.", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[4105] = {title = "Лекарство из оскверненных трав", objective = "Маяк Кенария позволяет опытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться превращать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.\n\nВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие \"Маяк Кенария\". За то, что ты мне принесешь, я дам тебе уже готового кенарийского бальзама.", description = nil, progress = "Маяк Кенария позволяет опытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться превращать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.\n\nВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие \"Маяк Кенария\". За то, что ты мне принесешь, я дам тебе уже готового кенарийского бальзама.", completion = "Отличная работа, Димиллион – все это после очищения пойдет на исцеление Оскверненного леса. Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес. Исцеление этого края от порчи не терпит отлагательств!", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[4106] = {title = "Лекарство из оскверненных шкур", objective = "Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженных порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!\n\nКогда соберешь порченые клочки, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.", description = nil, progress = "Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженных порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!\n\nКогда соберешь порченые клочки, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.", completion = "То что нужно! Вот, бери этот бальзам для исцеления растений и лечи им Оскверненный лес от порчи! Мы не должны сдаваться, Кавару!", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[4107] = {title = "Лекарство из распыленных предметов", objective = "Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.\n\nМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам бальзама исцеления Кенария. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!", description = nil, progress = "Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.\n\nМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам бальзама исцеления Кенария. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!", completion = "Вот тебе кенарийский бальзам, и за него я прошу только одну порцию малой субстанции Пустоты, Тунфокс. Субстанция эта – вещество самое мощное из тех, что я применяю при перековке мечей на орала. Если тебе понадобится еще бальзам, ищи меня тут!", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[4108] = {title = "Лекарство из охотничьих трофеев", objective = "Обладание Маяком Кенария позволяет увидеть оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.\n\nЗа эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений.", description = nil, progress = "Обладание Маяком Кенария позволяет увидеть оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.\n\nЗа эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений.", completion = "Очень хорошо, Вот тебе кенарийский бальзам. Ищи в Оскверненном лесу пораженные растения, Антизог! Когда найдешь, исцеляй их при помощи моего целебного бальзама.", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[4109] = {title = "Лекарство из минералов", objective = "Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.\n\nЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.", description = nil, progress = "Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.\n\nЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.", completion = "Что же, прекрасно! Вот тебе кенарийский бальзам. Если при разработках жил металлов в Оскверненном лесу найдешь еще порченого купороса, не забудь принести его мне! Чем больше найдешь, тем больше бальзама я смогу сделать.", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[4110] = {title = "Лекарство из оскверненных трав", objective = "Маяк Кенария позволяет опытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться превращать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.\n\nВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие \"Маяк Кенария\". За то, что ты мне принесешь, я дам тебе уже готового кенарийского бальзама.", description = nil, progress = "Маяк Кенария позволяет опытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться превращать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.\n\nВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие \"Маяк Кенария\". За то, что ты мне принесешь, я дам тебе уже готового кенарийского бальзама.", completion = "Отличная работа, Ксаер – все это после очищения пойдет на исцеление Оскверненного леса. Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес. Исцеление этого края от порчи не терпит отлагательств!", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[4111] = {title = "Лекарство из оскверненных шкур", objective = "Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженной порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!\n\nКогда соберешь испорченные куски, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.", description = nil, progress = "Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженной порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!\n\nКогда соберешь испорченные куски, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.", completion = "То что нужно! Вот, бери этот бальзам для исцеления растений и лечи им Оскверненный лес от порчи! Мы не должны сдаваться, Тириус!", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[4112] = {title = "Лекарство из распыленных предметов", objective = "Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.\n\nМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам кенарийского бальзама исцеления. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!", description = nil, progress = "Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.\n\nМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам кенарийского бальзама исцеления. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!", completion = "Вот тебе кенарийский бальзам, и за него я прошу только одну порцию простой субстанции Пустоты, Хафф. Субстанция эта – вещество самое мощное из тех, что я применяю при перековке мечей на орала. Если тебе понадобится еще бальзам, ищи меня тут!", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[4113] = {title = "Оскверненный песнецвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4114] = {title = "Оскверненный песнецвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете песнецвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4115] = {title = "Оскверненный ветроцвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4116] = {title = "Оскверненный песнецвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4117] = {title = "Оскверненный кнутокорень", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4118] = {title = "Оскверненный песнецвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете песнецвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4119] = {title = "Оскверненный ночной дракон", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4120] = {title = "Сила порчи", objective = "Убейте 12 гризли злобных когтей и 12 опустошителей-сквернолапов в Оскверненном лесу по просьбе Тало Тернового Копыта из лагеря Мохаче.", description = "Я – охотник, и всегда стремлюсь превзойти силой своих противников. Запомни, <имя>: всегда можно обратить ситуацию в свою пользу, если хорошо знаешь врага.\n\nК северу от Ясеневого леса есть место, называемое Оскверненный лес. Тамошние звери запятнаны веществом, которое именуется скверной. Медведи и волки от него совершенно взбесились, но в то же время скверна сделала их сильнее обычного.\n\nСтупай, <имя>. Отправляйся в Оскверненный лес, чтобы встретиться с этими тварями лицом к лицу.", progress = nil, completion = "Судя по твоему описанию, эти твари отличаются безоглядной свирепостью…\n\nОставайся начеку, Томпсон. Тебе стоит как можно больше узнать о порче. Врага нужно знать в лицо!", rewards = "Вы получите:\n\n"},
[4121] = {title = "Опасное положение", objective = "Отконвоируйте пленника, Грарка Лорктуба, через Пылающие степи и Черную гору к Тлеющему ущелью.\n\nЛекслорт что-то говорил насчет того, что по другую сторону будут ждать его ребята, которые уведут Грарка в тюрьму.\n\nТакже отдайте Лекслорту ториевые оковы.", description = "Ты в самом деле надеешься добраться до точки встречи, держа меня в плену? Ты и правда рассчитываешь, ворвавшись в крепость Черной горы и похитив главную ценность клана, удрать незамеченным?\n\nДа тебя в порошок сотрут!", progress = "Давай сюда этого предателя, Кастрол.", completion = "Твой подвиг не пропадет втуне. Ты заслужил эту награду. Теперь Вождь поведает тебе о последнем задании.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4122] = {title = "Грарк Лоркруб", objective = "Отправьтесь в Пылающие степи и найдите Грарка Лоркруба. Лекслорт упоминал, что в последний раз предателя видели в крепости Черной горы. \n\nПо обнаружении Грарка Лоркруба закуйте его в ториевые оковы и затем доставьте его от Черной горы к Тлеющему ущелью, Лекслорт и его подчиненные займутся допросом преступника.\n\nПрилагается предмет: \n", description = "Я шел за ним через Тлеющее ущелье, через горы и Пылающие степи. Предателя поймали на месте преступления, когда тот передавал оркам Черной горы сверхсекретную информацию о деятельности нашего отряда. Я говорю о Грарке Лоркрубе. \n\nОн теперь в Пылающих степях, под их надежной охраной – по крайней мере, он сам так думает. \n\nВозьми эти оковы, <имя>. Найди Грарка, надень на него эти оковы и доставь сюда. Награда будет достойной.", progress = nil, completion = "Разве ты не понимаешь, какую силу можно обрести, присоединившись к армии Черной горы?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4123] = {title = "Сердце горы", objective = "Принесите сердце горы Максворту Суперблеску в Пылающие степи.", description = "Сколько лет я ищу этот камень! Он называется \"сердце горы\". Размером как раз с твой кулак. Дворфы Черного Железа прячут его в своих тайных подвалах. Я пытался его купить, предлагал им хорошую цену, но они не продают!\n\nПридется забрать его силой, другого способа я не вижу.\n\nТебе надо пробиться на нижний ярус Глубин Черной горы, взломать потайной сейф и забрать сердце. Для того чтобы добраться до тайника, тебе придется сразиться с тамошним стражником. Его зовут Хватка Смерти, и он появится только тогда, когда ты вскроешь все сундуки и сейфы!\n\nУдачи.", progress = "Ты принес сердце горы? Для меня его ценность поистине безгранична.", completion = "Ты добыл Сердце! Великолепно! Оно даже прекраснее, чем мне представлялось!\n\nПрошу тебя, Исчезайка, прими это в уплату за свои труды!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4124] = {title = "Пропавший курьер", objective = "Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.", description = "Моему соратнику, Гинро Пылающему Очагу, нужна помощь. Он ищет курьера и пакеты, которые тот вез. Курьер пропал примерно неделю назад; наши собственные поиски результата не дали. Мы зашли в тупик. Пришлось объявить курьера пропавшим без вести.\n\nЕсли у тебя есть свободное время, пожалуйста, поговори с Гинро. Он должен быть где-то здесь. Возможно, он у себя.", progress = nil, completion = "Ты от Латро, я так понимаю? Я думаю, что дело глухо, но готов принять любую помощь. Должен признаться... я буду рад, когда вопрос решится хоть как-то. Я каждое утро выезжаю в лес разыскивать следы Раскала, и каждый вечер возвращаюсь домой с пустыми руками!", rewards = "Вы получите:\n\n"},
[4125] = {title = "Пропавший курьер", objective = "Отыщите лодку курьера, которая должна находиться где-то на побережье Фераласа.", description = "Прошла примерно неделя с тех пор, как Раскал, курьер, отправился в Таланаар. Фералас он знает, как свои пять пальцев – он был здесь с нами с самого начала, с тех пор, как генерал Лунное Перо привела сюда экспедиционный корпус. Я знаю, что он собирался взять весельную лодку и проплыть вдоль побережья Фераласа, чтобы миновать лагерь Орды.\n\nЕго лодки я так и не обнаружил – но, возможно, тебе это удастся. Может быть, она спрятана либо потонула. А между тем именно лодка может помочь выяснить, где Раскал. Если найдешь что-нибудь, дай мне знать.", progress = nil, completion = "Вы обнаружили затонувшую лодку. Сквозь мутноватую воду видны дыры, зияющие в левом борту. Кажется, будто лодка буквально ободрана до своего деревянного остова. Такое впечатление, что лодку пытались перекусить пополам. На правом борту нарисован небольшой герб Крепости Оперенной Луны.\n\nВ иле, скопившемся на дне лодки, блеснул металл...", rewards = "Вы получите:\n\n"},
[4126] = {title = "Харли Пьянодых", objective = "Найдите украденный рецепт громоварского и верните его Рагнару Громовару в Каранос.", description = "Подонки Черного Железа под предводительством гнусного Харли Пьянодыха украли рецепт нашего лучшего громоварского светлого! Подлые твари! Они не достойны такого прекрасного напитка!\n\n<имя>, у меня есть для тебя работа. Отправляйся в Глубины Черной горы в Пылающих степях, уничтожь все бочонки с громоварским светлым, какие сумеешь найти, и забери у мерзавцев наш рецепт!\n\nПереверни все Глубины, но найди этот рецепт!", progress = "Ты нашел рецепт, Малгриин? Меня передергивает от одной мысли о том, что эти наглецы будут пить наш фамильный напиток!", completion = "Рецепт у тебя! Ты молодец! Надеюсь, ты задал жару этим подонкам и Харли Пьянодыху? Так им и надо, мерзавцам!\n\nНаше семейство перед тобой в неоплатном долгу, Малгриин. Ты настоящий герой!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПалка молниеносного удараРасчленитель\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nТемное дворфийское пиво"},
[4127] = {title = "Разбитая лодка", objective = "Вернитесь в Крепость Оперенной Луны и покажите Гинро Пылающему Очагу выброшенный нож, который вы нашли.", description = "Копаясь в иле, вы нащупываете рукоятку ножа. Похоже, тот, кто плыл на лодке, его потерял. Рядом валяются обломки самой лодки…\n\nВы берете нож с собой: Гинро Пылающий Очаг из Крепости Оперенной Луны велел вам принести ему все, что может помочь разгадать тайну. Однако вас не покидает ощущение, что вы тут не одни...", progress = "А, Эфром! С возвращением. Надеюсь, тебе удалось узнать что-нибудь о судьбе Раскала? Даже если его судьба трагична...", completion = "Интересно... Похоже, это нож Раскала. Так говоришь, он валялся на дне, рядом с обломками его лодки? Ну, может быть, этой находки и недостаточно, чтобы делать какие-то выводы. Но у нас есть один необычный способ узнать побольше…\n\nДоводилось ли тебе слышать о сверхзнании?", rewards = "Вы получите:\n\n"},
[4128] = {title = "Рагнар Громовар", objective = "Переговорите с Рагнаром Громоваром.", description = "Здравствуй, <имя>. Ходят слухи, что кто-то украл у Рагнара Громовара его драгоценный эль. Бедолага рвет и мечет! Ему нужен отважный и дерзкий наемник, который возьмется за это дело. Рагнар готов хорошо заплатить.\n\nЕсли тебе интересно, переговори с ним. Он сейчас в своей \"Громоварке\" в Караносе. Это в Дун Морог.", progress = nil, completion = "Да, ты прав, я не просто рассержен. Я в бешенстве! Меня обокрали! Эти скоты сперли наш старый фамильный рецепт! Да как они только посмели?! Я и раньше-то их ненавидел... этих поганых дворфов из клана Черного Железа! А теперь... ох, как я зол!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4129] = {title = "Тайна ножа", objective = "Отнесите выброшенный нож к друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны.", description = "У нас в крепости живет друид, Квинтис Ночной Костер, который умеет... много всего. В частности, он владеет сверхзнанием – способностью узнавать на ощупь историю предмета. Не спрашивай, как он это делает – я в этом не разбираюсь, и разбираться не хочу. Я знаю только две вещи: во-первых, я видел, как это работает, а во-вторых, мужик у меня в долгу.\n\nКороче, тащи этот ножик к Кинту, в его жилище на дереве, и передай, что должок, который за ним числится, будет уплачен, если он разберется с этой штукой.", progress = "Ты от Гинро, да? Ох, нелегкая это работа... впрочем, долг платежом красен. А они еще издеваются, говорят, мол, не везет в карты – повезет в любви... Впрочем, мне везет скорее в постижении тайн природы.\n\nНет, конечно, я это сделаю. Возможно, это именно то, чего нам недостает, чтобы узнать о судьбе Раскала. Давай сюда нож, и возьмемся за дело.", completion = "Спасибо, Эфром.\n\nКонечно, сверхзнание точным искусством не назовешь, с какой стороны ни взгляни, но все же в былые времена я не раз с его помощью разбирался в ситуациях, которые все прочие сочли безнадежными. Думаю, на этот раз оно поможет нам хотя бы отчасти понять, что произошло с Раскалом.\n\nВремени это много не займет, но легким и приятным это дело не назовешь. Так что будь готов прийти мне на помощь.", rewards = "Вы получите:\n\n"},
[4130] = {title = "Сверхзнание", objective = "Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.", description = "Извини, меня до сих пор немного пошатывает. Как бы то ни было, я сумел увидеть несколько полезных вещей.\n\nРаскал вытащил два больших кожаных заплечных мешка из своей лодки и направился прочь от воды. Однако потом вернулся к лодке. Вижу скальпы гноллов... он наткнулся на гноллов – кажется, это тот клан, который называют Древолапами. Он чем-то очень озабочен, даже вроде бы напуган. Раскал настолько поглощен своими мыслями, что не замечает, как у него за спиной материализуются элементали воды. И... и все. Больше я ничего не увидел.\n\nИзвини, <имя>. Мне необходимо отдохнуть. Расскажи Гину о том, что я видел. Ему следует это знать...", progress = nil, completion = "Спасибо, что рассказал мне о видениях Кинта, Эфром. Так и быть, в следующий раз, как мы с ним сядем за карты, постараюсь быть к нему подобрее.\n\nНу, в бою Раскал никому не уступит, и гноллы – не те, кто может его обеспокоить, тем более, напугать. Но, может быть, эти новые сведения тебе все же пригодятся?", rewards = "Вы получите:\n\n"},
[4131] = {title = "Гноллы из стаи Древолапов", objective = "Обыщите лагеря Древолапов в южном Фераласе в поисках вещей курьера либо самого курьера.", description = "Возможно, Раскала сцапали наши \"друзья\" из клана Древолапов, но что-то мне подсказывает, что дело было не так. И все равно начать лучше всего с их лагерей.\n\nКонечно, хотелось бы иметь более отчетливые сведения, но пока что у нас нет ничего, кроме смутного указания на лагеря гноллов. Я знаю, что гноллы хранят у себя награбленное и дерутся из-за добычи. Возможно, они просто наткнулись на заплечные мешки, которые упоминал Кинт. Прежде я не рисковал соваться к гноллам, но теперь, когда у нас есть сведения, полученные от Кинта, попробовать стоит.", progress = nil, completion = "На ближайшем дереве висят два больших кожаных мешка. На обоих виднеется метка Крепости Оперенной Луны...", rewards = "Вы получите:\n\n"},
[4132] = {title = "Операция:смерть Кузне Гнева", objective = "Отправляйтесь в Глубины Черной горы и убейте генерала Кузню Гнева. Вернитесь к полководцу Клинозубу по выполнении задания.", description = "Ты <проделал/проделала> отличную работу, <имя>! Теперь пришло время для последнего задания. \n\nГенерал Кузня Гнева, ответственный за атаки Черного Железа на 109-ое подразделение Каргатского экспедиционного корпуса и масовые убийства наших солдат, должен понести наказание. \n\nЭто непростое задание, но в случае успеха труды окупятся сторицей.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nМедальон Завоевателя"},
[4133] = {title = "Вивиана Лягроб", objective = "Переговорите с тенемагом Вивиан Лаграв в Каргате.", description = "Тенемагу Вивиан Лаграв нужна твоя помощь. Она сейчас в Бесплодных землях, на сторожевой заставе Каргат. Там недавно прошел слух о небезызвестном напитке, сваренном дворфами Черного Железа в Глубинах Черной горы, – вот она и отправилась проверить.\n\nПоговори с Вивиан. Она тебя ждет.", progress = nil, completion = "Спасибо, что ты пришел, Томпсон. Это место не лишено своеобразного сурового очарования, но ему не хватает утонченности Района Фармацевтов.\n\nВпрочем, я позвала тебя не для того, чтобы вести светские беседы. Давай сразу к делу.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4134] = {title = "Украденный рецепт громоварского", objective = "Принесите рецепт громоварского светлого Вивиан Лягроб в Каргат.", description = "Ходят слухи, что Харли Пьянодых из клана Черного Железа украл рецепт эля. Говорят, этот эль, громоварское светлое, придает великую силу и храбрость тому, кто его употребит. Нам хотелось бы изучить состав этого напитка. Может быть, мы найдем и другое применение его удивительным свойствам... подходящее для целей Отрекшихся.\n\nОтправляйся в Глубины Черной горы, найди Харли, забери у него рецепт громоварского светлого и принеси его мне.\n\nВозможно, тебе придется выманить Харли из укрытия. Для этого пригрози ему уничтожением его драгоценного эля.", progress = "Ты добыл рецепт, Стиммакс?", completion = "Вот и славно. Я отошлю рецепт в Район Фармацевтов. Его там изучат, и со временем мы раскроем его секреты. И, возможно, придет такой день, когда дворфы Альянса с удивлением обнаружат, что волшебные свойства их тайного напитка против них же и обернулись!\n\nПо-моему, это будет забавно. Видимо, смерть как-то странно влияет на чувство юмора... ты не находишь?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПалка молниеносного удараРасчленитель\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nМощное лечебное зельеСильное зелье маны"},
[4135] = {title = "Гудящая Бездна", objective = "Продолжайте поиски Раскала (или его останков) в Гудящей Бездне. Согласно записке, Гудящая Бездна находится к югу от лагерей стаи Древолапов.\n\nПрилагается предмет: \n", description = "В рюкзаках находится два предмета: во-первых, посылка, адресованная в Таланаар, а во-вторых – записка, адресованная неизвестно кому.\n\nВ записке, набросанной торопливым почерком, говорится об обнаружении коварных насекомоподобных существ к югу от лагерей гноллов, в лесах, известных как \"Гудящая Бездна\". Автор сообщает, что намерен лично проникнуть туда, поскольку речь может идти о серьезной опасности, грозящей всему Фераласу. Записка подписана \"Раскал из Оперенной Луны\".\n\nПохоже, вам наконец-то удалось выяснить, куда делся Раскал...", progress = nil, completion = "Вам удалось обнаружить огромный кокон непонятного происхождения. Сам кокон мягкий и слизистый, но изнутри в разных местах выпирает что-то твердое. Размеры кокона позволяют предположить, что внутри может находиться гуманоид среднего роста... и сквозь стенки кокона действительно просвечивают очертания фигуры гуманоида!", rewards = "Вы получите:\n\n"},
[4136] = {title = "Риббли Крутипроб", objective = "Принесите голову Риббли Юке Крутипроб в Пылающие степи.", description = "Мой братец Риббли всегда только и делал, что тянул денежки из семьи и тратил их на какие-то поганые махинации.\n\nПохоже, последний его проект оказался поганее прочих, потому что барон Ревилгаз из Пиратской бухты назначил награду за голову бедняжки Риббли. Ты даже не представляешь, как возрадовались все Винтокраны! Наш малыш Риббли наконец хоть чего-то да стоит!\n\nНо сейчас он скрывается в Глубинах Черной горы. Найди его и приведи ко мне!\n\nА если он не пойдет добром... ну что ж, не пойдет – и не надо... тогда принеси мне его голову.", progress = "Ты привел Риббли? Хотя меня больше интересует не столько он сам, сколько его голова.", completion = "Ага! Ты нашел его! И... как я понимаю, мой маленький братец не пожелал возвращаться в семью. Очень жаль. Посмотрела бы я на его рожу, когда он услышал о том, что мы собираемся сдать его Ревилгазу.\n\nСпасибо, Стиммакс. Ты даже не представляешь, как порадовал все наше семейство. И Риббли сейчас такой тихий и славный... он никогда таким не был.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги ОзлобленияНаплеч карыСтальноосколочная броня\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4141] = {title = "Майджин и Ларион", objective = "Соберите 15 кровоцветов и принесите их Майджину.", description = "Видишь Лариона вон там? Это ОН виноват, что мы застряли здесь! \n\nЯ говорил ему, что мы идем не туда, но разве он меня слушал? И представляешь, после этого он еще и не желает со мной разговаривать! Ну, пока он не передумает, я позабавлюсь! \n\nТы <заметил/заметила> здесь таких странных созданий, похожих на цветы? На самом деле это довольно умные зверушки. Думаю, их можно надрессировать на всякие фокусы. \n\nВ первую очередь, мне нужны образцы для изучения. Сможешь принести мне несколько?", progress = "Ну, Ларион, ты сам нарвался...", completion = "Надеюсь, они не доставили тебе забот, Эфром? Крайне дикие создания! \n\nОднажды я попытался перепрыгнуть через один такой цветочек, так он напал на меня! Растения не должны так себя вести...", rewards = "Вы получите:\n\n"},
[4142] = {title = "Визит к Грегану", objective = "Отнесите кровоцвет Грегану Пивоплюю в Фералас.", description = "Не знаю, что и сказать тебе, <имя>. У этих растений, видимо, имеются зачатки разума. \n\nВпрочем, я не специалист. Однако знаю, к кому обратиться за действительно профессиональным мнением. \n\nОтправляйся в Фералас и найди там моего приятеля по имени Греган Пивоплюй. Он на таких вещах собаку съел. \n\nУверен, Греган сможет дать нам действительно дельный совет. Думаю, искать его лучше где-нибудь в лесу – парень никак не городской житель.", progress = "Я живу здесь, в лесу... Очень, знаешь ли, спокойно и благостно. \n\nПо крайней мере я сам так думал. Теперь ко мне шастает столько гостей, сколько я не видал в худшие дни в Стальгорне! Просто проходной двор какой-то!", completion = "Кровоцвет, говоришь? Хмм... В общем, сначала расскажи мне, что собираешься делать, а уж потом я скажу тебе, смогу ли помочь.", rewards = "Вы получите:\n\n"},
[4143] = {title = "Туман зла", objective = "Соберите 5 образцов тумана Аталаи и принесите их Майджину в Кратер Ун'Горо.", description = "Честно говоря, <имя>, мне никогда прежде не доводилось видеть подобных растений. Возможно, имеет смысл наведаться в этот кратер... \n\nВ любом случае, думаю, что знаю, что именно ищет Майджин. Ему нужен туман Аталаи. Это жуткая субстанция, которую весьма сложно собрать, однако именно этот туман необходим ему, чтобы управлять маленькими монстрами. \n\nТебе нужно найти Храм Атал'Хаккара на Болоте Печали. Туман Аталаи можно собрать с обитающих там глубинных скрытней, мракочервей и слизнюков. Удачи тебе, <имя>!", progress = "Ларион все еще не разговаривает со мной! Надо же, надулся, как мышь на крупу.", completion = "Признаю, мне очень боязно прикасаться с этой штуке, Драгунов! Но раз Греган утверждает, что она работает, надо попробовать.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4144] = {title = "Побеги кровоцвета", objective = "Слушай мой план, Драгунов: пойди и собери для меня немного побегов кровоцвета – молодых, которые еще не успели полностью развиться. А потом посмотрим, как они отреагируют на туман Аталаи. \n\nТы думаешь, я слишком злопамятен? Ну, в общем так и есть. \n\nНа самом деле, я знаю дорогу отсюда, но пока Ларион не признает мою правоту, я отсюда не уйду. \n\nНу, иди, принеси мне побегов, и мы славно повеселимся!", description = nil, progress = "Слушай мой план, Драгунов: пойди и собери для меня немного побегов кровоцвета – молодых, которые еще не успели полностью развиться. А потом посмотрим, как они отреагируют на туман Аталаи. \n\nТы думаешь, я слишком злопамятен? Ну, в общем так и есть. \n\nНа самом деле, я знаю дорогу отсюда, но пока Ларион не признает мою правоту, я отсюда не уйду. \n\nНу, иди, принеси мне побегов, и мы славно повеселимся!", completion = "Ну, приступим, Драгунов! Уж это привлечет внимание Лариона, будь уверен!", rewards = "Вы получите:\n\n"},
[4145] = {title = "Ларион и Майджин", objective = "Уничтожьте 5 кровоцветов-хлестунов, 5 кровоцветов-крепкозубов, 5 кровоцветов-живодеров и 5 кровоцветов-звероловов по просьбе Лариона из Укрытия Маршалла.", description = "Видишь там Майджина? Это ОН виноват, что мы потерялись! \n\nЯ знал дорогу, но он настоял на том, чтобы пойти \"коротким путем\" и вот! Мы застряли в этой дыре! \n\nЧто еще хуже, он теперь взялся натравливать на меня этим проклятых паразитов – кровоцветы! Я так зол, что не собираюсь говорить с ним. А эти паразиты – просто последняя капля! \n\nДумаю, в первую очередь мы перекроем ему снабжение! Пойди-ка, поохоться на кровоцветы, а потом возвращайся ко мне.", progress = nil, completion = "Спасибо за помощь, Томпсон, однако боюсь, у меня плохие новости...", rewards = "Вы получите:\n\n"},
[4146] = {title = "Питание для шокера", objective = "Доставьте незаряженный шокер и 5 образцов тумана Аталаи Лариону в Укрытие Маршалла.", description = "Тебе повезло, <имя>! Я тут работал над кой-какими собственными изобретениями, пока Марвон в отъезде. И вот моя последняя разработка – антижучиный шокер ближнего действия! Его надо совсем чуть-чуть поправить, и можно смело использовать против кровоцветов-паразитов. С удовольствием подарю тебе одну из моих тестовых моделей, однако для нее необходимо питание – туман Аталаи. Его можно собрать в Храме Атал'Хаккара с обитающих там трясинных скрытней, мракочервей и слизнюков.", progress = "Эти твари меня достали, Галдар! Просто достали!", completion = "Так Марвона там не было? И что же ты оттуда принес?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4147] = {title = "Мастерская Марвона", objective = "Отправьтесь к Марвону Клепальщику в его мастерскую в Кабестане.", description = "Мне удалось проследить за Майджином – он и впрямь выращивает эти проклятые растения! \n\nДумаю единственным решением будет... Нет, говорить с ним бесполезно, надо готовиться к ответному удару! \n\nНам потребуется помощь моего друга Марвона, у него мастерская в Кабестане.", progress = nil, completion = "Марвона здесь давно нет, Томпсон. Он отправился в Танарис, изучать развалины древних поселений троллей. \n\nА зачем он был тебе нужен?", rewards = "Вы получите:\n\n"},
[4148] = {title = "Антикровоцветный шокер", objective = "Чтобы шокер заработал, необходим образец его цели – кровоцвета. Отправляйся в кратер и принеси мне побег кровоцвета, а я уж настрою прибор на милых маленьких дружков Майджина... \n\nЕсли бы он не был так упрям, мы давно уже выбрались бы из этого проклятого места... Но пока я должен показать ему, что его шуточки меня ничуть не беспокоят!", description = nil, progress = "Чтобы шокер заработал, необходим образец его цели – кровоцвета. Отправляйся в кратер и принеси мне побег кровоцвета, а я уж настрою прибор на милых маленьких дружков Майджина... \n\nЕсли бы он не был так упрям, мы давно уже выбрались бы из этого проклятого места... Но пока я должен показать ему, что его шуточки меня ничуть не беспокоят!", completion = "Похоже, это устройство прекрасно сработает, Мард. Помни, как только заметишь где-нибудь этих паразитов, немедленно используй шокер!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nАнтикровоцветный шокер"},
[4161] = {title = "Рецепт кальдораев", objective = "Принесите 7 маленьких паучьих лапок Заррину в Доланаар.", description = "Давным-давно ночные эльфы назывались кальдораями, \"детьми звезд\". Изучение прошлого – важный шаг на пути <класс>, <имя>, так что слушай внимательно все, что я расскажу тебе.\n\nКальдораи всегда гордились тем, что живут в гармонии с природой. Это означает, что мы берем у природы только то, что нам необходимо, и воздаем ей сторицей. Это равновесие позволяло нам вершить многое, <имя>.\n\nСтупай же и принеси мне семь маленьких паучьих лапок – не более – и возвращайся ко мне.", progress = "Помни о равновесии, Анудорини. Желаю тебе открыть в себе понимание и любовь к живым лесам.", completion = "Всегда помни то, что я ныне показал тебе, Анудорини. Ты – часть того равновесия, которое ночные эльфы стремятся поддерживать даже в тревожные времена.", rewards = "Вы получите:\n\nРецепт: кальдорайский шашлык из паукаКальдорайский шашлык из паука"},
[4181] = {title = "Гоблинское инженерное дело", objective = "Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.", description = "В инженерном деле есть две дисциплины: гномская и гоблинская. Я – честный учитель, и только поэтому упомянул инженерное дело. Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер.\n\n<имя>, почитай этот справочник. Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск. Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого.", progress = "Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?", completion = "Что же, Цинабал, ты разумно поступаешь, прося у меня наставничества! Любой дурак может стать экспертом в азах инженерного дела – что прекрасно видно на примере гномов и их радиоактивного Гномрегана. Для овладения гоблинским инженерным делом требуется крепкая соображаловка и твердая (повторяю – ТВЕРДАЯ) рука.\n\nДержи ушки на макушке, Цинабал, может, что и усвоишь.", rewards = "Вы получите:\n\n"},
[4182] = {title = "Драконья угроза", objective = "Убейте 15 детенышей черного дракона, 10 черных драконидов, 4 черных драконид и 1 черного дракона. По выполнении задания вернитесь к Хелендису Речному Мысу.", description = "Жизнь в Пылающих степях никогда не бывает спокойной.\n\nТолько посмотри вокруг! Мы не знаем, что случилось с этими строениями, но до большого взрыва все это было частью Красногорья.\n\nНо довольно скулить! У нас есть более насущная проблема. Может быть, ты <заметил/заметила> драконов под этим хребтом. Необходимо вынудить их отступить. Убей как можно больше и возвращайся. Если ты добьешься успеха, я дам тебе другое задание.", progress = nil, completion = "Добрая охота, Эфром. Ну, раз ты можешь справиться с драконами и их прихвостнями, пора поговорить о более насущных проблемах.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4183] = {title = "Подлинные хозяева", objective = "Отправьтесь в Приозерье и доставьте письмо Хелендиса Речного Мыса мировому судье Соломону.", description = "Мы всегда думали, что орки Черной Горы такие жестокие от природы. Оказывается, дело обстоит иначе.\n\nДа, их и правда ведет в бой жажда крови и любовь к сражениям, но руководят ими черные драконы. Мы подозреваем, что именно они возбуждают в них ярость и злобу.\n\nОтнеси это письмо мировому судье Соломону. Он скажет, что делать.\n\n*Хелендис протягивает вам запечатанное письмо.*", progress = "Приветствую тебя, Эфром. Мы уже встречались? Твое лицо кажется мне знакомым.", completion = "*Мировой судья Соломон распечатывает письмо от Хелендиса и начинает читать.*", rewards = "Вы получите:\n\n"},
[4184] = {title = "Подлинные хозяева", objective = "Передайте обращение Соломона верховному лорду Болвару Фордрагону.\n\nБолвар Фордрагон пребывает в Крепости Штормграда.", description = "Дурные вести, <имя>. Нетрудно прийти в отчаяние, узнав, что твои смертельные враги – всего лишь пешки куда более страшного противника. Приозерью не пережить натиска орков Черной Горы и черных драконов. Если падет Приозерье, следующим будет Темнолесье, а что потом? Златоземье? Сам Штормград?\n\nНемедленно отнеси это сообщение Верховному лорду Болвару Фордрагону в Штормград! Если мы и этим не добьемся от столицы помощи, то не добьемся никакими силами, и все пропало.", progress = "Что привело тебя в Крепость Штормграда?", completion = "Драконы? Быть того не может!", rewards = "Вы получите:\n\n"},
[4185] = {title = "Подлинные хозяева", objective = "Поговорите с Верховным лордом Болваром Фордрагоном после беседы с леди Катраной Престор.", description = "Грустную картину нарисовал Соломон. Тем не менее, мы не можем позволить себе посылать наши и без того скудные войска на помощь Приозерью, основываясь только на догадках. Мне понадобится доказательство правоты его заявлений, прежде чем я смогу предпринять какие-то действия.\n\nПоговорите с леди Престор, <имя>. Она женщина ученая и много чего знает о драконах и драконидах. Возможно, она сможет пролить какой-то свет на эту ситуацию.", progress = "*Болвар пристально смотрит на вас.*", completion = "*Болвар подпирает рукой подбородок, как бы глубоко задумавшись.*\n\nВ то время как я уважаю позицию леди Престор, я уверен, что для этой дилеммы есть решение, которое могло бы развеять все наши тревоги.", rewards = "Вы получите:\n\n"},
[4186] = {title = "Подлинные хозяева", objective = "Отнесите указ Болвара мировому судье Соломону в Приозерье.", description = "Я намерен наделить вас полномочиями представителя, действующего от имени Штормграда, <имя>.\n\nВозвращайтесь к мировому судье Соломону в Приозерье и передайте ему этот указ.", progress = "Есть какие-то новости от лорда Болвара?", completion = "Ну, полагаю, могло быть и хуже...\n\n*Мировой судья изучает вас взглядом.*\n\nПохоже, что судьба Озер ложится теперь на ваши плечи.\n\n*Вы замечаете, что мировой судья часто-часто моргает. Кажется, он плачет.*", rewards = "Вы получите:\n\n"},
[4201] = {title = "Приворотное зелье", objective = "Принесите 4 листа крови Грома, 10 огромных серебряных слитков и наполненный сосуд Нагмары госпоже Нагмаре в Глубины Черной горы.", description = "О, терзания и муки неразделенной любви! Мои чары не действуют на возлюбленного. Рядовой Камнеузл отвергает меня! Это невыносимо!\n\nТы <должен/должна> мне помочь! Мы, суккубы, хорошо разбираемся в любовных делах, и я могу приготовить волшебное зелье, которое разрушит железную стену вокруг непреклонного сердца Каменного Узла. Для того чтобы сварить это зелье, мне нужна трава кровь Грома, серебряные слитки скальных великанов Азшары и вода из источников Голакка в Кратере Ун'Горо. Воду можешь набрать в этот сосуд.\n\nПрошу тебя, <имя>, помоги моей бедной истерзанной душе обрести радость и счастье!", progress = "Ты принес все, что нужно? Боль в моем сердце растет с каждым днем!", completion = "Ты все принес! Теперь я смогу приготовить волшебный напиток, и Каменный Узел воспылает ко мне любовью!\n\nСпасибо, Тыж. Ты – истинный рыцарь любви!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКандалыПояс-хлыст Нагмары\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4221] = {title = "Оскверненный ветроцвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4222] = {title = "Оскверненный ветроцвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4223] = {title = "Подлинные хозяева", objective = "Поговорите с маршалом Максвеллом в Пылающих степях.", description = "*Мировой судья вздыхает.*\n\nВозвращайся в Пылающие степи, <имя>. Как представитель Штормграда ты <должен/должна> предстать перед маршалом Максвеллом. Удачи.", progress = nil, completion = "&lt;Маршал Максвелл смеется.&gt;", rewards = "Вы получите:\n\n"},
[4224] = {title = "Подлинные хозяева", objective = "Поговорите с Джоном-Оборванцем и узнайте о судьбе маршала Виндзора. По выполнении задания вернитесь к маршалу Максвеллу.\n\nКажется, маршал Максвелл говорил, что Джона следует искать в пещере на севере.", description = "Что? Думаешь, ты <первый/первая>? Сколько же еще мы должны потерять солдат прежде, чем Штормград начнет шевелиться?\n\nМы собрали целую кучу разведданных касательно угрозы со стороны клана Черной горы до того, как потеряли нашего командира, маршала Виндзора. С ним пропала и вся наша бесценная прнформация.\n\nНам просто необходимы эти документы. Поговори с Джоном-Оборванцем, <имя>. Он был при Виндзоре, когда на них налетел рейд клана Черной горы. Последний раз его видели в пещере к северую отсюда.", progress = "Ты уже поговорил с Джоном?", completion = "Я мог бы тебя предупредить, но разве это интересно?", rewards = "Вы получите:\n\n"},
[4241] = {title = "Маршал Винздор", objective = "Отправляйтесь на Черную гору на северо-западе и войдите в ее глубины. Узнайте, что сталось с маршалом Виндзором.\n\nКажется, Джон-Оборванец говорил о том, что Виндзора утащили в темницу.", description = "Значит, этот жалкий трус говорит, что Виндзор жив?\n\nГотовься, тебе предстоит отправиться на его поиски. Если Виндзор жив, спаси его. Если мертв – принеси мне доказательства его гибели.\n\n*Максвелл смеется.*\n\nТебе, наверное, надоело это слышать?", progress = nil, completion = "Где он! Я убью его!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4242] = {title = "Утраченная надежда", objective = "Сообщите маршалу Максвеллу плохие новости.", description = "Болвар – жалкий дурак. Я собирал все его драгоценные \"доказательства\" только для того, чтобы засунуть их ему же в глотку.\n\nНедоумок! Слепой идиот! Доказательство стоит в двух шагах от него, а он ушами хлопает.\n\nЧто касается собранных мною сведений – вся информация утрачена, причем безвозвратно.\n\nЕсли я все-таки найду Железогубитель и выберусь из этого лабиринта, я первым делом отправлюсь в Штормград и вломлю ему молотом промеж глаз, этому подлому змею.\n\nОставь меня, <имя>.", progress = nil, completion = "Вполне очевидно, что он повредился рассудком.\n\n*Максвелл скорбно склоняет голову.*\n\nПечально, когда благородный и доблестный воин превращается в невменяемого идиота. Как я понимаю, мы зашли в тупик...\n\nНо ты хорошо потрудился, Сарт. И получишь награду.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШлем ОхранителяЩитолатные башмакиПоножи Ветрорезов\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4243] = {title = "В поисках Чи-Та 3", objective = "Найдите Чи-Та 3 в Кратере Ун'Горо.", description = "Увы, что-то случилось с одним из моих величайших изобретений. Ты ведь <видел/видела> моих механических белок? Так вот, чтобы подобраться поближе к обезьянам, обитающим в Кратере Ун'Горо, я создала механическую обезьяну, которая должна была смешаться со стаей. Я назвала ее Чи-Та 3. Ее глаза были сделаны из магических кристаллов, так что я могла видеть все, что видит она. Она успела добраться до Пещеры Лишайников – это логово обезьян к востоку отсюда – и там я потеряла с ней контакт. Последним, что я видела, был вожак стаи, который подбежал поздороваться с ней. \n\nТы поможешь мне разыскать ее?", progress = nil, completion = "Осмотрев Чи-Та 3, вы обнаруживаете две глубоких вмятины в творении инженерного искусства Карны. Одна вмятина украшает плечо робота, другая зияет на голове. \n\nПохоже, энергии в машине не осталось.", rewards = "Вы получите:\n\n"},
[4244] = {title = "В поисках Чи-Та 3", objective = "Найдите мифриловую обшивку и вернитесь к Чи-Та 3 в Кратер Ун'Горо.", description = "Внимательно осмотрев робота, вы замечаете отодвигающуюся панель, над которой значится: \"Заменить мифриловую обшивку, затем выключить и включить питание\". \n\n\"Сомнительно, что такую серьезную поломку можно устранить так легко... \n\nНе попробуешь – не узнаешь.", progress = "Панель, в которую необходимо вставить мифриловую обшивку, все еще закрыта. Чи-Та 3 лежит неподвижно.", completion = "Вы снова отдвигаете панель на спине Чи-Та 3 и осторожно вынимаете обгоревшую мифриловую обшивку, заменяя ее новой. Если действительно считать, что это и была основная причина поломки, то осталось лишь включить питание.", rewards = "Вы получите:\n\n"},
[4245] = {title = "В поисках Чи-Та 3", objective = "Доставьте Чи-Та 3 назад Карне Сомнамбулер в Кратер Ун'Горо.", description = "Установив тумблер в положение \"выкл.\", вы оглядываетесь, чтобы удостовериться, что все готово к тому, чтобы доставить Чи-Та 3 назад к Карне Сомнамбулер. Убедившись, что горилл поблизости нет, вы собираетесь включить робота. \n\nЭто ваш последний шанс. Вы уверены, что хотите сделать именно это?", progress = nil, completion = "Ах, тебе удалось, какое счастье! Спасибо, Вий! \n\nО, моя бедняжечка! Как тебе досталось! Ничего, я починю тебя, будешь как новенькая! \n\nЕще раз благодарю тебя, Вий, твоя помощь неоценима.", rewards = "Вы получите:\n\n"},
[4261] = {title = "Древний дух", objective = "Сопроводите Арая в безопасное место, затем поговорите с Кайнетом Штилем в Лесной Песне на востоке Ясеневого леса.", description = "Оскверненный лес был некогда местом мирным и безмятежным... Пока сюда не пришел Легион. Эти инферналы, разрушения, хаос...\n\nЧереп Гул'дана сделал так, что ничто не смогло уберечься от порчи. \n\nДаже сейчас, будучи духом, я ощущаю себя в ловушке, ощущаю страдания этого края. Помоги мне найти путь домой. Прошу тебя, <имя>, пообещай, что ты уведешь древний дух отсюда, туда, где я, наконец, обрету покой.\n\nКак только я освобожусь, найди Кайнета Штиля, друда, что живет в Лесной Песне, к востоку отсюда.", progress = nil, completion = "Да, Мяуыч. Оскверненный лес пережил много горестей. Спасибо тебе за все.\n\nОднажды мы очистим Оскверненный лес от скверны, и каждое доброе дело приближает этот миг.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНакидка астрального туманаОплечье Плывущих облаков\n\nВы также получите:\n\n"},
[4262] = {title = "Подчинитель Пирон", objective = "Убейте подчинителя Пирона и вернитесь к Джалинде Тирлипуньке.\n\nКажется, Джалинда говорила, что Пирон охраняет каменоломню. Может, поискать его там?", description = "Последние пять магов, которые отправились на разведку к Черной горе вернулись довольно хрустящими и с перманентной завивкой – или хуже того.\n\n*Джалинда берет с земли щепотку пепла и пускает по ветру.*\n\nА больше всего неприятностей нам причиняет один тип, подчинитель Пирон. Необходимо остановить этого элементаля, чтобы наша экспедиция могла пробраться в глубины Черной горы.\n\nОн охраняет вход в каменоломни Черной горы.", progress = nil, completion = "Опалитель? О, небо…", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4263] = {title = "Опалитель!", objective = "Отыщите и уничтожьте лорда Опалителя в глубинах Черной горы!", description = "Ты <уверен/уверена>, что Пирон сказал перед смертью \"Опалитель\"?\n\n*Джалинда судорожно сглатывает.*\n\nВедь лорд Опалитель – прислужник Рагнароса! О небо, небо... Что же нам делать?\n\nКак ты думаешь, справишься с еще одним заданием? Мне больше некого послать, <имя>!\n\nНам никогда не одолеть врагов, если Опалитель будет и дальше воскрешать Пирона из пепла.\n\nТебе придется отыскать и уничтожить лорда Опалителя!", progress = nil, completion = "О небо! Ты уверен, что Опалитель сказал перед смертью \"Рагнарос\"?*Джалинда протягивает вам что-то и морщит лоб в раздумье.*", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСолнечная накидкаСумрачные перчаткиНаручи демона склепаСтойкий поясок\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4264] = {title = "Измятая записка", objective = "Не исключено, что ваша находка заинтересует маршала Виндзора. Может быть, все не так плохо, и надежда еще жива.", description = "Лист помят и испачкан, и текст почти не читается, но вам все-таки удалось разобрать несколько фраз:\n\n\"...по иронии судьбы...\n\n...упадок распавшегося Альянса...\n\n...если бы не усердие генерала Кузни Гнева, мы никогда не сумели бы найти ключ к шифру...\n\n...Аргелмах почти завершил расшифровку записок Виндзора.\n\nНаш владыка восстанет из бездны и сокрушит всех, кто остался...\n\nИмператор Дагран Тауриссан\".", progress = "*Маршал Виндзор заметил смятый листок у вас в руке.*\n\nЧто это там у тебя, Эст?", completion = "*Маршал Виндзор читает записку.*", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4265] = {title = "Освобожденный из улья", objective = "Освободите Раскала из улья Цуккаш.\n\nВернитесь к Гинро Пылающему Очагу в Крепости Оперенной Луны и сообщите ему, что Раскал жив и здоров.", description = "Когда вы прикасаетесь к кокону, он немного раскрывается, и вы видите внутри ночного эльфа, который, как ни странно, все еще жив, и даже, кажется, цел и невредим, только в глубоком обмороке. Когда вы вытаскиваете его из кокона, он шевелится и приходит в себя.\n\n\"Слава Элуне! Я спасен! Спасибо тебе, друг. Я... Меня зовут Раскал. Эти жуки парализовали меня, и очнулся я уже в коконе. Тебя из крепости прислали, да?\"\n\nПохоже, вы нашли пропавшего курьера...", progress = nil, completion = "С возвращением, Эфром! Раскал не так давно явился ко мне и сообщил обо всем, что произошло.\n\nЯ... да что там, вся наша крепость не знает, как тебя благодарить за твои подвиги. Раскал погиб бы, если бы не твоя своевременная помощь. А ведь ты помогаешь нам не ради платы, как какой-нибудь наемник! Ты – подлинный герой. Знай, что отныне Гинро Пылающий Очаг – твой друг до скончания веков!", rewards = "Вы получите:\n\n"},
[4266] = {title = "Благодарность за отвагу", objective = "Поговорите с Шандрисой Оперенной Луной в Крепости Оперенной Луны.", description = "<имя>, генерал Шандриса Оперенная Луна хотела бы поговорить с тобой лично. Несомненно, она хочет поблагодарить тебя за все, что ты <сделал/сделала> для крепости, но, насколько я знаю, она также хотела бы поговорить с тобой о тех насекомоподобных тварях, которых вы с Раскалом видели в южном Фераласе. Сообщения об этих насекомых, которых именуют Цуккаш, звучат... скажем так: устрашающе.\n\nГенерал Лунное Перо ждет тебя в главном здании.", progress = nil, completion = "Эфром, я от души благодарю тебя за всю оказанную тобой помощь. Твоя отвага перед лицом превосходящих сил противника достойна награды в тысячу раз большей. Тем не менее, я надеюсь, что ты примешь в дар от всей крепости хотя бы это.\n\nА теперь, если можно... я хотела бы попросить тебя еще об одной услуге. Сейчас, когда здесь, в Фераласе, обнаружен улей Цуккаш, думаю, это задание следует поручить именно тебе...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПарадный клинокРитуальный жезл\n\nВы также получите:\n\n"},
[4267] = {title = "Появление силитидов", objective = "Отнесите донесение Раскала Грацине Силе Духа в Дарнассе.", description = "Я доверяю тебе копию отчета Раскала о вторжении в юго-восточный Фералас. Полный доклад будет отправлен на хранение в Дарнасс, а эту копию отнеси, пожалуйста, представителю Протектората. Ее зовут Грацина Сила Духа; это жрица, которая живет в храме Луны в Дарнассе. Она обладает обширными познаниями о подобных существах, так что, если она ознакомится с этим докладом, это пойдет на пользу всем нам.\n\nМожешь идти, <имя>. Удачи тебе, и да хранит нас Элуна!", progress = "Добро пожаловать в наш благословенный храм! Я узнала о твоем приходе из предсказания. Тот доклад, что просила тебя отнести Шандрисе Оперенной Луне, у тебя с собой?", completion = "Нам, ночным эльфам, немало известно об ужасах, описанных в этом докладе. Сандрис поступила мудро, отправив ко мне доклад – и тебя с ним.\n\nЭти твари стремительно заполонят весь Фералас. Можно сказать, что это одна из самых страшных опасностей, какие нам когда-либо грозили! Насекомые, с которыми столкнулись вы с курьером, называются силитидами. Они – всего лишь орудие одной из величайших угроз, с какими встречались как Альянс, так и Орда.\n\nМолюсь, чтобы у нас хватило решимости разгромить их прежде, чем они уничтожат нас!", rewards = "Вы получите:\n\n"},
[4281] = {title = "Посылка в Таланаар", objective = "Отнесите недоставленную посылку Хранителю дорог Фалфиндеру в Таланаар.", description = "Сверток, который вы нашли в лагере гноллов-древолапов, следовало доставить в небольшой путевой лагерь Таланаар на юго-востоке Фераласа. Неизвестно, какая судьба постигла курьера, однако сверток так и остался недоставленным!\n\nОсмотрев пакет, вы видите на нем имя \"Хранитель дорог Фалфиндер\". Возможно, это имя адресата?", progress = "Добро пожаловать в Таланаар, |3-6(Охотник). Тебе нужна какая-нибудь помощь?", completion = "Слава Элуне! Наконец-то пришла посылка из Крепости Оперенной Луны!\n\nНо раз ее принес ты, значит, с нашим курьером, Раскалом, что-то случилось? Надеюсь, что все уладится... Насколько я знаю, в последнее время гноллы из клана Древолапов очень боятся чего-то, что происходит на юге. Может быть, Раскал заблудился в глуши? Будь осторожнее.\n\nНу, как бы то ни было, спасибо тебе еще раз. А вот и плата за доставку!", rewards = "Вы получите:\n\n"},
[4282] = {title = "Проблеск надежды", objective = "Верните маршалу Виндзору утерянную информацию.\n\nМаршал уверен, что информацией завладели повелитель големов Аргелмах и генерал Кузня Гнева.", description = "*Маршал Виндзор возбужденно потрясает запиской.*\n\nТы понимаешь, что это значит, <имя>?\n\nМожет быть, еще не все потеряно! Насколько я понял, информацией завладели два дворфа Черного Железа – генерал Кузня Гнева и повелитель големов Аргелмах. Однако есть у меня подозрение, что они ее не отдадут, даже если мы их очень вежливо попросим.\n\nНадеюсь, ты <готов/готова> сражаться.\n\nРазыщи этих двоих негодяев! Убей их обоих и верни мне утерянную информацию.", progress = "Уже очень скоро все это закончится.", completion = "*Маршал Виндзор выхватывает у вас из рук таблички.*\n\nУходим!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4283] = {title = "ПЯТЬДЕСЯТ! АГА!", objective = "Орелиусу нужны 50 медальонов Черной горы. Скорее всего их можно найти у орков Пылающих степях.", description = "Открою тебе тайну, солдат. Подойди-ка поближе.\n\nЯ ЕДИНСТВЕННЫЙ, КТО ЕЩЕ НЕ СПЯТИЛ!\n\nПосмотри на остальных. Ты веришь, что они ненормальные? А так оно и есть! ПСИХИ! СУМАСШЕДШИЕ!\n\n*Орелиус понижает голос.*\n\nНо пусть это останется между нами – тобой, мной и мим приятелем, капитаном Винкеем.\n\n*Орелиус хватается за воздух и будто прижимает кого-то к себе.*\n\nВ общееем... помимо ушей огров, я собираю их содатские медальоны. Сегодня на повестке дня орки. Пятьдесят штук. ИДИ!\n\n*Орелиус трубит в рог.*\n\nЗАТКНИСЬ!", progress = "*Орелиус говорит в довольно большое отрезанное ухо огра.*\n\nПылающие степи – центру. Центр, прием.", completion = "Ты справился! И вот твоя награда: ПОЧЕШИ МНЕ ЖИВОТИК! ДАВАЙ! ЧЕШИ!", rewards = "Вы получите:\n\n"},
[4284] = {title = "Кристаллы Силы", objective = "Соберите по 7 кристаллов Силы каждого цвета: красных, синих, желтых и голубых. Принесите их Джей Ди Колли в Укрытие Маршалла.", description = "Уверена, ты <видел/видела> их, <имя>. Они повсюду! \n\nТы не понимаешь, о чем я? О кристаллах, конечно! Большинство их просто игнорирует, но я чувствую, что в них заключена какая-то сила. Я уже давно провожу с ними эксперименты, но пока, видимо, так же далека от разгадки, как и в первые дни исследований... Впрочем, я не теряю надежды! \n\nСейчас у меня почти вышел запас кристаллов. Не поможешь ли мне его восполнить?", progress = "Я чувствую, что близка к разгадке, Эфром!", completion = "Теперь я продолжу эксперименты. Спасибо, Эфром!", rewards = "Вы получите:\n\n"},
[4285] = {title = "Северный пилон", objective = "Отыщите Северный хрустальный пилон в Кратере Ун'Горо.", description = "Что бы это могло быть? Я все время думаю об этой загадке! \n\nЭти слухи о хрустальных пилонах просто сводят меня с ума! Можешь считать меня наивной дурочкой, но я верю почти всему, что мне рассказывают. \n\nВ общем, слыхала я, что один из пилонов находится совсем неподалеку отсюда – где-то на севере. Пожалуйста, разыщи его, <имя>! Я уверена, пилоны существуют!", progress = nil, completion = "Я знаю, что все эти рассказы – правда, Томпсон.", rewards = "Вы получите:\n\n"},
[4286] = {title = "Хороший товар", objective = "Отправьтесь в глубины Черной горы и принесите 20 поясных сумок дворфов Черного Железа. По выполнении задания вернуться к Орелиусу. Предположительно поясные сумки можно отобрать у дворфов Черного Железа в глубинах Черной горы.", description = "Капитан Винкей уверяет, что дворфы Черного Железа в глубинах Черной Скалы загребли все лучшее добро. Верно, Винкей?\n\n*Орелиус, как может, изображает пирата.*\n\nВот видишь? Иди туда и принеси мне образцы их добра.\n\nТряхни стариной и отправляйся вглубь!", progress = "Не беспокой меня, Трансмастер. Нам с Винкей надо кое с кем встретиться.", completion = "*Орелиус роется в груде поясных сумок.*\n\nВЕЛИКОЛЕПНО!\n\n*Орелиус сует нос в кучу и принюхивается.*\n\nВОСХИТИТЕЛЬНО! Только посмотри на это добро!\n\nВозьми одну себе, здесь их полно.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЗакопченная сума-жестянка"},
[4287] = {title = "Восточный пилон", objective = "Отыщите Восточный хрустальный пилон в Кратере Ун'Горо.", description = "За время моего пребывания здесь, до меня не раз доходили странные слухи о таинственных хрустальных пилонах, сокрытых в кратере. Полагаю, они довольно велики. \n\nНе могу отделаться от мысли, что в этих слухах есть доля истины, и эти пилоны как-то связаны с обнаруженными нами кристаллами... \n\nУдовлетвори мое любопытство, поищи пилон в восточной области кратера.", progress = nil, completion = "Ун'Горо такое странное место, Томпсон! Входишь – и будто оказываешься в другом мире!", rewards = "Вы получите:\n\n"},
[4288] = {title = "Западный пилон", objective = "Отыщите Западный хрустальный пилон.", description = "Мои опыты пока не принесли никаких положительных результатов, <имя>. Теперь я возлагаю надежды лишь на то, что ты сможешь найти один из пилонов, о существовании которых я слыхала. \n\nВозможно, если смешать определенные цвета... Впрочем, я тороплю события. Необходимо сначала найти его. \n\nИсследуй западную область кратера, <имя>, говорят, пилон находится именно там.", progress = nil, completion = "В стенах кратера много ниш и пещер. Попробуй обыскать извилистые тропинки в тех местах, если больше ничего не можешь придумать.", rewards = "Вы получите:\n\n"},
[4289] = {title = "Обезьяны Ун'Горо", objective = "Принесите 2 шкуры Ун'Горской гориллы, 2 шкуры Ун'Горского топтуна и 2 шкуры Ун'Горского рокотуна землепроходцу Торве к входу в Кратер Ун'Горо.", description = "В этом кратере встречается множество странных зверей – они похожи на тех, что водятся на моей родине, но выглядят более... породистыми. Я не могу объяснить это, но мне кажется, это место – средоточие силы Матери-Природы. Я воздаю ей хвалу всякий раз как встречаю одно из ее прекрасных созданий в этом кратере. \n\nЕсли ты тоже хочешь достигнуть просветления, отправляйся на север. Там ты найдешь огромных обезьян, помериться силами с которыми сочтет за честь самый искусный воин. Принеси мне их шкуры, докажи свою силу!", progress = "Что, неужели сдался, Томпсон? \n\nНе падай духом. Выследить и сразить обезьяну Ун'Горо – не простая задача, даже для великого охотника.", completion = "Значит, тебе хватило сил одолеть обезьян Ун'Горо. Это славно. Конечно, это не такая сложная задача, как сражение с Лар'корви, и все же немалая победа. \n\nМое племя обрадуется шкурам, из них получатся прекрасные одежды! Ты помог мне и показал себя достойным. \n\nПрежде чем ты отправишься далее, воздадим хвалу Матери-Земле и поблагодарим духов обезьян, убитых тобой – они должны знать, что их смерть была не напрасна!", rewards = "Вы получите:\n\n"},
[4290] = {title = "Добыча Лар'корви", objective = "Найдите последнюю добычу Лар'корви, украдите кусок трупа жесткозуба и вернитесь к землепроходцу Торве в Кратер Ун'Горо.", description = "Однажды мой брат имел неосторожность отрезать кусок мяса от добычи Лар'корви, когда того не было рядом. Однако оказалось, что Лар'корви наблюдал за моим братом из укрытия. Он преследовал моего брата долгие недели, разрушая все на своем пути. Наконец, брат мой в страхе решил покинуть кратер. \n\nНо Лар'корви настиг его недалеко от этого места и убил его. \n\nЕсли хочешь привлечь к себе внимание Лар'корви, найди его свежеубитую добычу и отрежь от нее кусок мяса. \n\nЗатем возвращайся ко мне.", progress = "Не относись к этому заданию легкомысленно, Томпсон. Если ты и вправду желаешь встретиться с чудовищем, ты должен быть очень осторожен и рассудителен. Необходима немалая сила и сноровка, чтобы победить Лар'корви.", completion = "Этот кусок послужит хорошей приманкой, Томпсон. Похоже, удача в охоте сопутствует Лар'корви. Однако странно, где он смог найти жесткозуба в этих краях... \n\nЯ сохраню это для тебя до тех пор, пока ты не будешь готов встретиться с чудовищем. Не волнуйся за меня – полагаю, ты уже успел так разозлить Лар'корви, что он не станет убивать меня раньше, чем вкусит твоей плоти.", rewards = "Вы получите:\n\n"},
[4291] = {title = "Запах Лар'корви", objective = "Принесите 2 феромонные железы равазавра землепроходцу Торве в преддверие Кратера Ун'Горо.", description = "Я удивлен, что Лар'корви не вышел к тебе, <имя>! И все же у меня есть задумка, как выманить его. \n\nПоскольку Лар'корви – доминирующий самец в своей стае, он может выбирать любую самку. А выбирает он многих! Ты найдешь много кладок равазавров к западу отсюда. Подберись к ним поближе и спровоцируй самок атаковать тебя. В их головах находятся железы, источающие жуткий запах – так эти твари оповещают своих самцов о готовности к размножению. Принеси мне две такие железы.", progress = "Будь остороженТомпсон. Когда подберешься близко к яйцам, самки ринутся защищать их. Они могут быть не менее опасны, чем сам Лар'корви, если почувствуют угрозу своему потомству. Но если тебе удастся добыть железы, мы точно сможем выманить Лар'корви из его логова.", completion = "Это отличные образцы, Томпсон. С их помощью мы сможем выманить Лар'корви. Мне не терпится узнать, чем закончится твой бой с чудовищем. Это огромная тварь с зубами, подобными булатным клинкам. Ты посмотришь в его глаза и познаешь, каков взгляд смерти.", rewards = "Вы получите:\n\n"},
[4292] = {title = "Приманка для Лар'корви", objective = "С помощью предметов из мешочка Торвы выманите Лар'корви и сразите его. Принесите голову Лар'корви землепроходцу Торве ко входу в Кратер Ун'Горо.", description = "Это самая сложная часть нашего плана. К северу отсюда есть узкая тропинка, ведущая в горы. Именно там я в последний раз видел Лар'корви. Ты легко узнаешь это место – там повсюду разбросаны дочиста обглоданные кости крупных животных, имевших неосторожность подойти слишком близко к логову Лар'корви. Положишь там принесенное с собой мясо. Затем полей мясо вот этим составом. Если это не выманит к тебе Лар'корви, то я не знаю, чем еще его можно заманить.", progress = "Не дай своему страху побороть тебя, Томпсон! Страх – великий предатель, с ним нужно бороться. \n\nВозьми это мясо и потри его железой самки чудовища. И тогда сама смерть предстанет перед тобой.", completion = "Хвала Матери-Земле! Ты справился!Ты показал себя великим, Томпсон. Твой дух силен. Твоей храбрости нет равных. А сила твоя укрепилась. Я склоняюсь пред твоим мастерством. \n\nТолько самым великим из моих предков были под силу подобные свершения.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМундир равнинного бродягиПоножи всадника\n\nВы также получите:\n\n"},
[4293] = {title = "Проба слизи...", objective = "Возьмите на пробу образцы слизи из Оскверненного леса. Воспользуйтесь тестовым оборудованием химика Барабоса в Катакомбах, чтобы отобрать 5 наиболее чистых образцов и отдайте их ему.", description = "Оскверненный лес находится далеко на севере от Степей – даже дальше, чем Ясеневый лес. Вокруг тамошних заводей, благословленных касанием Скверны, полно слизнюков. Плеть наводнила эти земли инферналами и прочими демонами. Судя по всему, в это время слизнюки и полезли из-под земли.\n\nСобери образцы слизнюков Оскверненного леса – мы проверим их при помощи моего оборудования и создадим контрольную группу, чтобы сопоставить ее с другими принесенными тобой образцами.", progress = "Мне нужно не меньше пяти проб слизи для контрольной группы. Продолжай собирать образцы слизи, пока не предоставишь мне все необходимое. Так велела леди Сильвана...", completion = "Великолепно. Эти пробы прекрасно подойдут. Благодарю за помощь.\n\nСобрав все образцы слизи, мы сможем двинуться дальше. Я начинаю подозревать, что леди Сильвана не зря заинтересовалась этими существами. Более того, сама того не зная, она, похоже, оказалась на грани великого открытия. Эти пробы очень интересны. А как они прореагировали с моими препаратами... хм, да, нам есть над чем поработать.", rewards = "Вы получите:\n\n"},
[4294] = {title = "...и образцы слизнюков", objective = "Возьмите на пробу образцы слизи из кратера Ун'Горо. Воспользуйтесь тестовым оборудованием химика Барабоса в Катакомбах, чтобы отобрать 5 наиболее чистых образцов и отдайте их ему.", description = "Тебе приходилось слышать о Кратере Ун'Горо? Он расположен рядом с пустыней Танарис. Великолепное место: тамошние буйные заросли буквально кишат жизнью! А какие там растения…\n\nИменно туда тебе и следует отправиться. До меня дошли слухи, что в этих местах сохранилась практически девственная природа. Исследователи лишь недавно добрались до них, и далеко не все тайны еще раскрыты.\n\nЯ хочу, чтобы ты <принес/принесла> мне образцы живущих там слизнюков. Если слухи правдивы и их не тронула порча, я смогу узнать, откуда появились эти существа.", progress = "Да, Томпсон? Как успехи?", completion = "Удивительно! Кратер Ун'Горо таит куда больше секретов, чем я думал. Интересно, какие еще открытия нас ждут?\n\nПоразительно... Изумительно чистые образцы. Хм, что бы это значило? Похоже, по природе они относятся скорее к стихиям... но непростым. Они напоминают мне... о Древних богах. Мы находили их следы по всему Азероту – вдруг и эти существа каким-то образом связаны с ними?\n\nНадо продолжать исследования.", rewards = "Вы получите:\n\n"},
[4295] = {title = "Эль для Каменного Узла", objective = "Кружечка доброго эля Черного Железа была бы сейчас очень кстати! Быстрее, а то я уже начинаю трезветь! А когда я трезвею, у меня сразу мутится зрение... и все расплывается... и ты почему-то становишься очень похожим на того |3-6(человек), которого я грохнул на прошлой неделе.", description = nil, progress = "Кружечка доброго эля Черного Железа была бы сейчас очень кстати! Быстрее, а то я уже начинаю трезветь! А когда я трезвею, у меня сразу мутится зрение... и все расплывается... и ты почему-то становишься очень похожим на того |3-6(человек), которого я грохнул на прошлой неделе.", completion = "Это что? Ага! Пахнет элем Черного Железа! Пусть я пьян и мало что соображаю, но скажу тебе, добрый сэр: ты настоящий друг!", rewards = nil},
[4296] = {title = "Табличка Семерых", objective = "Принесите переписанный с таблички текст Максворту Суперблеску в Пылающие степи.", description = "Я прибыл в Пылающие степи из-за легенд о Семерых. Это были дворфы, прославленные знаниями и силой, а значит – и богатством.\n\nИменно к богатству я и стремлюсь!\n\nУзнай мы побольше про Семерых, могли бы оба разбогатеть. Говорят, что в руинах Тауриссана есть табличка Семерых, содержащая знания древних дворфов. Найди ее, перепиши текст и принеси мне. И мы оба узнаем ее тайны!", progress = "Удалось переписать мудрость Семерых? Раскрыла ли табличка их тайны?", completion = "А, ты нашел табличку! И как хорошо переписан текст! Ты точно |3-6(Охотник), а не переписчик?\n\nВот, возьми, Томпсон. Это обещанные деньги.", rewards = "Вы получите:\n\n"},
[4297] = {title = "Покормить малыша", objective = "Принесите 5 окороков среброгривого бродяги Агнару Зверопасу во Внутренних землях.", description = "Летучие хамелеоны всеядны: это значит, что они питаются как животной, так и растительной пищей. Твое яйцо вот-вот проклюнется, и мы должны быть к этому готовы. Лучшая еда для этих малявок – это мясо, свежее, сочное мясо! Хочешь – верь, хочешь – нет. Почему – я так и не выяснил, но, кажется, это имеет какое-то отношение к замыслу Элуны относительно эльфов. Возможно, они должны были быть защитниками... не знаю.\n\nЯйцо я пока покараулю, а ты сходи и добудь мне свеженьких окороков среброгривых бродяг. Ими-то мы и покормим малыша, когда он вылупится.", progress = "Ну что, Мерандир, добыл ли ты мясо? А то твой дракончик вот-вот вылупится. И если он не поест как следует, едва появившись на свет, он и недели не проживет, а это будет жаль.\n\nПо правде говоря, Мерандир, мне вообще жаль отдавать тебе это яйцо. Так не заставляй меня жалеть об этом еще больше!", completion = "Да, это мясо вполне годится. А тем временем, если я не ошибаюсь, твой дракончик начинает вылупляться! Ну, как тебе это? В смысле, каково быть папой? Груз ответственности не давит пока?", rewards = "Вы получите:\n\n"},
[4298] = {title = "У вас появился малыш!", objective = "Поговорите с Агнаром Зверопасом во Внутренних землях.", description = "Ух ты, да он уже вылупляется!", progress = nil, completion = "Вот, бери яйцо... Тебе лучше держать его при себе, чтобы вылупившийся детеныш сразу привязался к тебе. Тогда он будет считать тебя своим папочкой.\n\nНу все, Мерандир, поздравляю! У тебя теперь все равно что собственный ребенок!", rewards = "Вы получите:\n\nЯйцо летучего хамелеона"},
[4300] = {title = "Костяные клинки", objective = "Принесите 8 белых когтей равазавра Джес'римону в Оргриммаре.", description = "Да, если так подумать, то, пожалуй, для тебя есть работенка. Джес'римону пригодится твоя помощь.\n\nВ Кратере Ун'Горо водятся ящеры – с когтями острыми, как бритва. У большинства ящеров когти черные, как смерть, но у некоторых ящеров они белые. У Раздробленной Руки имеются... клиенты, которые очень ценят оружие, изготовленное из таких когтей. Принеси побольше белых когтей, и Джес'римон заплатит тебе по совести. А если сделаешь это быстро, то получишь кое-что сверху.", progress = "Клиенты недовольны, Томпсон. Где же обещанные когти?", completion = "Да, это то, что надо! Спасибо, Томпсон. И тебе удалось уложиться в срок... это замечательно.\n\nБыть может, мы сумеем изготовить из этих когтей оружие и для тебя. Что скажешь?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо Белой КостиБелый костяной шредерБелое костяное копье\n\nВы также получите:\n\n"},
[4301] = {title = "Могучая Уча", objective = "Принесите шкуру Учи землепроходцу Торве ко входу в Кратер Ун'Горо.", description = "Пока ты <исследовал/исследовала> Ун'Горо, я встретил и других созданий, охота на которых доставит удовольствие такому мастеру как ты. Одно из них – огромная обезьяна, я видел ее в стае других обезьян к северу отсюда. Ты уже <бывал/бывала> в этой пещере раньше, однако не могу ручаться, что выйдешь из этой схватки <живым/живой>, если действительно возьмешься за это задание. \n\nЯ назвал эту обезьяну Уча, она одна из самых могучих детей Матери-Природы. Убей ее, и я буду отстаивать твое право называть себя <великим охотником/великой охотницей>.", progress = "Уча... Это был великолепный зверь. Она была огромной и рыжей, а зубы ее были подобны кинжалам. Ее руки толщиной спорили со стволами деревьев, а двигалась она так быстро, что ей позавидовал бы и горный лев! Тебе повезло встретить столь мощное создание для испытания своей храбрости – многим поколениям в моем племени не посчастливилось повстречать ничего подобного.", completion = "Отлично, Томпсон! Я доволен. Сегодня ты совершил великое деяние. \n\nУча была одной из самых огромных обезьян, виденных мною за всю жизнь. То, что ты смог сразить ее, говорит о твоей собственной силе и храбрости. \n\nПрими это в знак моего уважения. Ты заслужил это.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗверосокрушительЗверобой\n\nВы также получите:\n\n"},
[4321] = {title = "Давай-ка разберемся", objective = "Поговорите с Джей Ди Колли через пару минут.", description = "То, что ты <рассказал/рассказала> мне о пилонах, весьма интересно... \n\nДай мне минутку, мне нужно сделать некоторые расчеты... Зайди ко мне через пару минут, я смогу дать ответ на твой вопрос.", progress = nil, completion = "Так вот, Томпсон! Все это очень интересно... Надюсь, мои диаграммы верны! Я собрала все сведения в эту книгу и отдам ее тебе. \n\nПолагаю, теперь я могу ответить на все твои вопросы о кристаллах, Томпсон.", rewards = "Вы получите:\n\nИнструкция по эксплуатации пилонов"},
[4322] = {title = "Побег!", objective = "Помогите маршалу Виндзору забрать вещи и освободить его друзей, после чего вернитесь к маршалу Максвеллу и получите дальнейшие инструкции.", description = "Пора выбираться отсюда, <имя>. Помоги мне забрать мои вещи со склада и освободить моих друзей. Если у нас все получится и нам удастся отсюда сбежать, отправляйся в Дозор Моргана и расскажи обо всем маршалу Максвеллу. Он тебе скажет, что делать дальше.", progress = nil, completion = "Поразительно, Револлюшен. Просто невероятно. Виндзор был здесь буквально перед твоим приходом. Ворвался, как ураган, весь такой разгоряченный и буйный. Его притязания поистине грандиозны, но он заявляет, что у него есть на то основания. Сейчас он направляется в Штормград и собирается бросить вызов Болвару и... госпоже Престор.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКлинок РасчетовКвалифицированный боевой клинок\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nОберег Стихий"},
[4324] = {title = "Юка Крутипроб", objective = "Переговорите с Юкой Крутипроб в Пылающих степях.", description = "Риббли, мой младший братец, всю жизнь был никчемным придурком и позором для всей семьи, но в итоге оказалось, что он тоже чего-то да стоит и может пригодиться. Но понимаешь, какое дело... чтобы приставить его к работе, нам понадобится твоя помощь.\n\nМоя сестра Юка искала его почти месяц, и в итоге ей удалось узнать, что он прячется в Пылающих степях. Ей нужен наемник, и она обратилась ко мне за помощью.\n\nНе хочешь взяться за это дело? Если берешься, тогда тебе надо переговорить с сестрой. Ты найдешь ее в Пламенеющем Стяге, в пещере к северо-западу от скалы Молота Ужаса.", progress = nil, completion = "Да, я ищу брата. Его надо найти и вернуть.\n\nПриведи его ко мне. А если он будет сопротивляться... тогда принеси мне хотя бы его голову.", rewards = nil},
[4341] = {title = "Каран Могучий Молот", objective = "Пойдите в Глубины Черной горы и найдите Карана Могучего Молота.\n\nКороль упомянул, что Каран сидит там в плену – может, стоит поискать темницу.", description = "Тебе приходилось бывать в дымящихся руинах Тауриссана? А тебе не попадался этот жалкий бездельник Каран Могучий Молот? Это дворф, который был должен охранять мою девочку!\n\n<Король всхлипывает.>\n\nИ теперь она пропала, <имя>!\n\nМои воины обшарили всю Степь. Им удалось узнать только то, что моя дочка может быть в Глубинах. Может, она уже погибла!\n\nА Харан, видимо, сидит там в плену... найди его! Я хочу получить ответ!", progress = nil, completion = "Прошу, позволь мне объясниться!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4342] = {title = "Рассказ Карана", objective = "Выслушайте рассказ Карана Могучего Молота.", description = "Пожалуйста, выслушай меня, а потом будешь судить!", progress = "Дай мне закончить рассказ.", completion = "Как ты сам понимаешь, я ничего не мог сделать.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4343] = {title = "Оскверненный ветроцвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4361] = {title = "Недобрые вести", objective = "Вернитесь в Стальгорн и сообщите нехорошие новости королю Магни Бронзобороду.", description = "Расскажи обо всем королю Магни, <имя>. Он знает, что делать.", progress = nil, completion = "*Король Магни в ярости бьет кулаком по столу.*", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4362] = {title = "Судьба королевства", objective = "Вернитесь в Глубины Черной горы и освободите принцессу Мойру Бронзобород от злобного императора Даграна Тауриссана.", description = "Похоже, и моя судьба, и судьба королевства Стальгорн ныне в руках моего старинного врага Даграна Тауриссана.\n\nВозможно, вы моя последняя надежда, <имя>. Вы должны спасти мою драгоценную дочь Мойру!\n\nЕсть только один путь наверняка разрушить лежащее на Мойре заклятие Тауриссана – убить его.\n\nНо умоляю, <имя>, не причиняйте ей вреда! Помните, она под властью Тауриссана! Все, что она будет делать или говорить, – результат злого заклятия Тауриссана!", progress = nil, completion = "*Принцесса оплакивает гибель императора Даграна Тауриссана.*\n\nЗа что???", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4363] = {title = "Королевский сюрприз", objective = "Вернитесь в Стальгорн и переговорите с королем Магни Бронзобородом.", description = "Тауриссан был великим и доблестным дворфом. Ты <разрушил/разрушила> мою жизнь и жизнь моего будущего ребенка!\n\n*Вы уверены, что принцесса до сих пор пребывает под действием чар императора.*\n\nВозвращайся в Стальгорн и скажи моему отцу, что наследником королевства будет дворф Черного Железа.\n\nНравится это ему или нет, но именно так все и будет!", progress = nil, completion = "*Король Магни Бронзобород явно расстроен.*\n\nСдается мне, даже в смерти Тауриссан победил.\n\nБольше я не нуждаюсь в твоих услугах, Тыж. Но прежде чем ты покинешь нас, выбери себе награду из королевских сокровищниц.\n\n*Король садится на трон и погружается в раздумья.*", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВоля МагниПоющий камень Стальгорна\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4381] = {title = "Кристалл восстановления", objective = "Табличка пилона позволяет сочетать зеленые и желтые кристаллы Силы. \n\nСогласно книге Джей Ди, это сочетание можно использовать для исцеления себя или своих союзников.", description = nil, progress = "Табличка пилона позволяет сочетать зеленые и желтые кристаллы Силы. \n\nСогласно книге Джей Ди, это сочетание можно использовать для исцеления себя или своих союзников.", completion = "Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино. \n\nТеперь полученное сочетание – ваше.", rewards = "Вы получите:\n\nКристалл восстановления"},
[4382] = {title = "Кристалл силы духа", objective = "Табличка пилона позволяет сочетать зеленые и синие кристаллы Силы. \n\nСогласно книге Джей Ди, это сочетание можно использовать для укрепления своего духа.", description = nil, progress = "Табличка пилона позволяет сочетать зеленые и синие кристаллы Силы. \n\nСогласно книге Джей Ди, это сочетание можно использовать для укрепления своего духа.", completion = "Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино. \n\nТеперь полученное сочетание – ваше.", rewards = "Вы получите:\n\nКристалл силы духа"},
[4383] = {title = "Кристалл-хранитель", objective = "Табличка пилона позволяет сочетать зеленые и красные кристаллы Силы. \n\nСогласно книге Джей Ди, это сочетание можно использовать для усиления защиты от физических повреждений.", description = nil, progress = "Табличка пилона позволяет сочетать зеленые и красные кристаллы Силы. \n\nСогласно книге Джей Ди, это сочетание можно использовать для усиления защиты от физических повреждений.", completion = "Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино. \n\nТеперь полученное сочетание – ваше.", rewards = "Вы получите:\n\nКристалл-хранитель"},
[4384] = {title = "Кристалл-губитель", objective = "Табличка пилона позволяет сочетать красные и синие кристаллы Силы. \n\nСогласно книге Джей Ди, это сочетание можно использовать для ослабления обороны противника.", description = nil, progress = "Табличка пилона позволяет сочетать красные и синие кристаллы Силы. \n\nСогласно книге Джей Ди, это сочетание можно использовать для ослабления обороны противника.", completion = "Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино. \n\nТеперь полученное сочетание – ваше.", rewards = "Вы получите:\n\nКристалл-губитель"},
[4385] = {title = "Обжигающий кристалл", objective = "Табличка пилона позволяет сочетать красные и желтые кристаллы Силы. \n\nСогласно книге Джей Ди, это сочетание можно использовать для производства мощного взрыва, наносящего серьезный ущерб силам противника.", description = nil, progress = "Табличка пилона позволяет сочетать красные и желтые кристаллы Силы. \n\nСогласно книге Джей Ди, это сочетание можно использовать для производства мощного взрыва, наносящего серьезный ущерб силам противника.", completion = "Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино. \n\nТеперь полученное сочетание – ваше.", rewards = "Вы получите:\n\nОбжигающий кристалл"},
[4386] = {title = "Кристальная cпираль", objective = "Табличка пилона позволяет сочетать синие и желтые кристаллы Силы. \n\nСогласно книге Джей Ди, это сочетание можно использовать для создания щита, наносящего повреждения противнику.", description = nil, progress = "Табличка пилона позволяет сочетать синие и желтые кристаллы Силы. \n\nСогласно книге Джей Ди, это сочетание можно использовать для создания щита, наносящего повреждения противнику.", completion = "Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино. \n\nТеперь полученное сочетание – ваше.", rewards = "Вы получите:\n\nКристальная спираль"},
[4401] = {title = "Оскверненный песнецвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4402] = {title = "Кактусовый десерт Галгара", objective = "Принесите Галгару 10 плодов кактуса.", description = "Ну и жарища у нас в долине!\n\n*Галгар утирает пот со лба.*\n\nБыли бы у меня плоды кактуса, я бы изготовил свой знаменитый кактусовый десерт! Ничто не освежает лучше этого восхитительного лакомства.\n\nЗнаешь что, <имя>? Принеси-ка мне десяток плодов кактуса, и я изготовлю тебе несколько порций кактусового десерта. Они тебе пригодятся в путешествиях. Плоды кактуса можно собрать со здешних кактусов.", progress = "Ну что, собрал плоды?", completion = "Замечательно, Гронгард! А вот и твой кактусовый десерт, как было обещано. И еще кое-что в придачу...", rewards = "Вы получите:\n\nКактусовый десерт"},
[4403] = {title = "Оскверненный ветроцвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4421] = {title = "Порча нефритового огня", objective = "Убейте 11 скверноподданных, 9 тенеловов, 9 разбойников из племени Нефритового Пламени и Ксаватраса. Возвращайтесь к Эридане Грусти Ветра в Оскверненный лес по выполнении задания.", description = "Мало кто отваживается искать здесь приключений... Порча, поразившая Оскверненный лес, расползается, поражая все без разбору.\n\nЯ, состоя в Измумрудном Круге, ищу способ исцелить эти земли, но есть те, кто радуется ее мучениям.\n\nЯ говорю о сатирах из племени Нефритового Пламени, что живут к северо-западу отсюда, в руинах Констелласа. Ими предводительствует особенно жестокий сатир по имени Ксаватрас. Они продолжают поражать заразой любое живое существо, которое попадается им на пути.\n\nМы должны защитить этот край – ведь некогда он был нашим. Срази Ксаватраса и уничтожь его приспешников.", progress = nil, completion = "Избавление Оскверненного леса от Ксаватраса – только первый шаг на долгом пути. Придется долго трудиться, чтобы залечить раны этой земли.\n\nЯ чувствую, что за всем этим стоит нечто большее, чем какие-то сатиры, но правду мы узнаем только со временем...", rewards = "Вы получите:\n\n"},
[4441] = {title = "Дерева в узах скверны", objective = "Отправляйтесь в Дарнасс и наберите в фиал Эриданы благословенной воды из храма Луны. Возвращайтесь к Эридане с полным фиалом.", description = "Флейта, найденная тобой, вырезана из древесины сторожевого древа, верного союзника ночных эльфов.\n\nСатиры поражают порчей все, на что наталкиваются, в том числе и древа, для которых Оскверненный лес был домом родным. Из-за скверны духи древ попали в узы и теперь терзаются, не в силах освободиться. Эти узы скверны, что ты <нашел/нашла>, наверняка с этим связаны.\n\nМы должны попытаться очистить эту флейту от скверны, <имя>. Принеси мне благословенной воды из дарнасского храма Луны.", progress = "Будем надеяться, что сия вода освободит духи Древ и подарит им мир.", completion = "Спасибо тебе, Драгунов. Будем же молиться, чтобы нам удалось исцелить нанесенные раны...", rewards = "Вы получите:\n\n"},
[4442] = {title = "Очищение явлено!", objective = "Через мгновение заговорите с Эриданой.", description = "При помощи сей воды Элуны я попытаюсь смыть скверну с этой флейты. Мы должны покончить со страданиями...\n\nДа направит мою руку Элуна и да укрепит она мое сердце.\n\nПодожди немного – потом поговорим.", progress = nil, completion = "При помощи этой благословенной воды я сумела разорвать связь между флейтой и духами Дерев. Но я все же уверена, что если ты заиграешь на этой флейте в священном месте, то ты мог бы призвать духи Дерев.\n\nВозможно, тебе следует попытаться сделать это в руинах в южной части Железнолесья. Некогда там обитало много оскверненных древней, и, возможно, они и до сих пор там находятся, пусть и в обличье духов.", rewards = "Вы получите:\n\nФлейта Древних"},
[4443] = {title = "Оскверненный кнутокорень", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4444] = {title = "Оскверненный кнутокорень", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4445] = {title = "Оскверненный кнутокорень", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4446] = {title = "Оскверненный кнутокорень", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4447] = {title = "Оскверненный ночной дракон", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4448] = {title = "Оскверненный ночной дракон", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4449] = {title = "Попался!", objective = "Убейте 8 геологов из клана Черного Железа и принесите 15 отрезов шелка тому, кто заперт в отхожем месте в Тлеющем ущелье.", description = "Эй! Эй, ты, там! Иди скорей сюда! \n\nПомоги мне! Я спасался бегством от дворфов Черного Железа и попытался спрятаться от них здесь. Проклятые геологи со своей проклятой магией! Они увидели, что я здесь прячусь, и заперли меня! Проучи, проучи этих проклятых геологов! И... это... добудь мне несколько лоскутков шелка... так... вдруг пригодится...", progress = "Я тут уже целый день торчу! Достань мне шелку... э-э... в смысле... геологов! Пусть узнают, что такой мой... в смысле... твой гнев!", completion = "О, какое облегчение! Как я рад, Томпсон! Тебе удалось отомстить проклятым геологам? Их наглость не знала границ, однако. Не знаю как благодарить тебя! Ты это... погоди минутку, мне тут надо закончить некоторые дела...", rewards = "Вы получите:\n\n"},
[4450] = {title = "Учетная книга из Танариса", objective = "Возьмите учетную книгу Кринкеля Сталлинна и найдите все перечисленные в ней вещи. Затем отнесите их и книгу Кринкелю Сталлинну в Танарис.", description = "Ты знаешь, мне это кое-что напоминает.\n\nНе хочешь закончить за меня одну работенку, за которую я взялся в Танарисе? Это пара пустяков...\n\nКринкель Сталлинн из Прибамбасска искал какие-то вещи – некоторые здесь, в Тлеющем ущелье, а некоторые в других местах. Может, глянешь на список? Ты наверняка сможешь что-нибудь найти.\n\nЕсли тебе это интересно, я просуну его учетную книгу под дверь. Отнесешь ее ему вместе с разыскиваемыми вещами, когда соберешь их все.", progress = "Да-да? Чем я могу помочь тебе, |3-6(гном)? Я ужасно занят, у меня полно капризных клиентов, которым вынь да положь немедленно их заказ.Так что давай пошустрей со своими делами. Не хочу показаться грубым, но у меня совершенно нет времени на пустую болтовню!", completion = "Ого, да ты смог выполнить эту работу! Прекрасно. Полагаю, теперь ты попросишь меня выковать для тебя что-нибудь. \n\nУ меня есть превосходное оружие и доспехи. Благодарю тебя, |3-6(Чернокнижник)! \n\nДумаю, ты заслужил... хммм... что-нибудь полезное.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗаряженный молниевый жезлРемень отпора\n\nВы также получите:\n\n"},
[4451] = {title = "Ключ к свободе", objective = "Найдите дверь в Тлеющем ущелье, к которой подходит ключ от дома Грязнули.", description = "Маленький медный ключик выглядит совершенно непритязательно. Единственное, что выдает его значимость, – надпись, выгравированная на бородке: \n\n\"Служебные помещения Черного Железа – изготовление дубликатов строжайше запрещено\".\n\nУ вас нет ни малейшего представления, что это за ключ и куда ведет открываемая им дверь.", progress = "*кашель* Кто там? Не видите что ли, занято!", completion = "Вот те на! Чтоб мне провалиться! Ты нашел ключ! Я знал, что проклятые дворфы Черного Железа спрятали его, после того как заперли меня в этой дыре! О, благодарю тебя, Томпсон! Скорее открой дверь и выпусти старика Локида на свободу!", rewards = "Вы получите:\n\n"},
[4461] = {title = "Оскверненный кнутокорень", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4462] = {title = "Оскверненный ночной дракон", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то грилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то грилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4463] = {title = "Манускрипт Размышления", objective = "Принеси все составляющие, смертный.\n\nКроме того, я потребую с тебя тридцать золотых за создание этой безделушки.", description = nil, progress = "Принеси все составляющие, смертный.\n\nКроме того, я потребую с тебя тридцать золотых за создание этой безделушки.", completion = "Забирай свою безделушку, неразумная тварь. Оставь меня в покое!", rewards = "Вы получите:\n\nПростой магический камень размышления"},
[4464] = {title = "Оскверненный песнецвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4465] = {title = "Оскверненный песнецвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает.", rewards = nil},
[4466] = {title = "Оскверненный ветроцвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и исцеляется.", rewards = nil},
[4467] = {title = "Оскверненный ветроцвет", objective = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", description = nil, progress = "Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.", completion = "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений. Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и исцеляется.", rewards = nil},
[4481] = {title = "Манускрипт Здоровья", objective = "За все в этом мире приходится платить. Цена искомого предмета – тридцать золотых.\n\nЕстественно, большую часть собранных тобой компонентов я оставлю себе. Но не беспокойся, свою игрушку ты получишь.", description = nil, progress = "За все в этом мире приходится платить. Цена искомого предмета – тридцать золотых.\n\nЕстественно, большую часть собранных тобой компонентов я оставлю себе. Но не беспокойся, свою игрушку ты получишь.", completion = "Это вызов его памяти... Смертный оканчивает работу всей его жизни.\n\nЗабирай свою безделушку и убирайся!", rewards = "Вы получите:\n\nПростой магический камень упорства"},
[4482] = {title = "Манускрипт Упорства", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПростой магический камень прочности"},
[4483] = {title = "Манускрипт Устойчивости", objective = "Коль устойчивость нужна, тридцать золотых – цена.", description = nil, progress = "Коль устойчивость нужна, тридцать золотых – цена.", completion = "Прочие манускрипты рассеяны по свету. По таким уголкам, куда ты не осмелишься войти. Которых бы лучше и не было.\n\nЯ выпью из этих составляющих силу. А ты получишь то, что останется...", rewards = "Вы получите:\n\nПростой магический камень стойкости"},
[4484] = {title = "Манускрипт Ненасытности", objective = "Не трать попусту мое время, |3-6(человек). Давай мне все, что нужно. Тридцать золотых и компоненты.", description = nil, progress = "Не трать попусту мое время, |3-6(человек). Давай мне все, что нужно. Тридцать золотых и компоненты.", completion = "Голова болит... Сила бескрайних пределов вселенной... Ахххх!\n\n*Матредис кривится от боли.*\n\nБери, что тебе нужно, и уходи!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПростой магический камень ненасытностиПростой магический камень ненасытностиПростой магический камень ненасытностиПростой магический камень ненасытностиПростой магический камень ненасытности"},
[4485] = {title = "Фолиант Благородства", objective = "Поговорите с Даторианом Раллом в Штормграде.", description = "Приветствую, <имя>. Я вижу, твоя решимость по-прежнему сильна, как и твоя вера.\n\nДумаю, настало время тебе поговорить с Даторианом Раллом в Штормграде. Ты <должен/должна> получить еще несколько уроков, и я чувствую, ты к ним <готов/готова>.\n\nНайди Даториана в Соборе Света – и пожалуйста, <имя>, отнесись к его урокам серьезно. Ты <добился/добилась> своего положения благодаря скромности и упорному труду, так не разочаруй нас – не становись <высокомерным/высокомерной>.\n\nУдачи тебе.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[4486] = {title = "Фолиант Благородства", objective = "Поговорите с Даторианом Раллом в Штормграде.", description = "Ну-ка, ну-ка, поглядите на могучего паладина во всей красе!\n\nПрошу прощения, <имя>, я не в обиду... Просто иногда немного завидую твоим достижениям. Тиза говорит, что в этом – моя слабость, и я обещал ей, что искореню этот недостаток. Но пока не преуспел, <сам/сама> понимаешь.\n\nНо вот почему я хотел с тобой поговорить: Даториан Ралл из Штормграда сообщил, что хочет встретиться с тобой в Соборе Света, когда ты будешь к этому <готов/готова>. Звучало веско. Звучало так, как будто что-то эдакое происходит.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[4487] = {title = "Призывание коня Скверны", objective = "Поговорите в Кабестане со Страхадом Фарсаном.", description = "Ага, хорошо, что ты здесь. Я посылал <суккуба/инфернала> за тобой, но, похоже, ты <успел/успела> добраться сюда раньше, чем они добрались до тебя. Ладно.\n\nТут недавно пошли разговоры о твоем растущем могуществе – и это очень хорошо для тебя, а для других, наверное, не очень. Короче, я думаю, что ты уже достаточно <зарекомендовал/зарекомендовала> себя и потому заслуживаешь...хе-хе... подарочка.\n\nВ Степях над Кабестаном ты найдешь человека по имени Страхад. Уверен, вы уже встречались.", progress = nil, completion = "Значит, ты снова решил пожаловать меня своим визитом. Очень мило с твоей стороны.\n\nМои помощники все гадали – придешь или нет? Я говорил им – несомненно, придет. Когда речь заходит о могуществе, летишь как мотылек на свечу.", rewards = "Вы получите:\n\n"},
[4488] = {title = "Призывание коня Скверны", objective = "Поговорите в Кабестане со Страхадом Фарсаном.", description = "О, <имя>, ты <почтил/почтила> нас своим присуствием. Какая честь!\n\nНадеюсь, ты не думаешь, что мы будем тебя облизывать с ног до головы. Может, ты и быстро набираешь могущество, но ты все еще дитя малое в том, что касается истинного знания и мудрости. Если не поостережешься, тебя охватит одержимость, и воля твоя ослабеет.\n\nBНо ближе к делу – Страхад желает говорить с тобой. Он по-прежнему живет в башне над Кабестаном в Степях. Советую не тянуть канитель.", progress = nil, completion = "Значит, ты снова решил пожаловать меня своим визитом. Очень мило с твоей стороны.\n\nМои помощники все гадали – придешь или нет? Я говорил им – несомненно, придет. Когда речь заходит о могуществе, летишь как мотылек на свечу.", rewards = "Вы получите:\n\n"},
[4489] = {title = "Призывание коня Скверны", objective = "Поговорите в Кабестане со Страхадом Фарсаном.", description = "А, <раса>! Иди сюда!\n\nТебя ведь зовут <имя>, не так ли?\n\nЯ так и думал. Короче: твоя мощь растет, и это было замечено. Теперь пора наградить тебя за старания.\n\nИди в Степи. Там, над Кременником, ищи Страхада Фарсана – может, помнишь его? У него есть для тебя кое-что. Это много времени не займет.", progress = nil, completion = "Значит, ты снова решил пожаловать меня своим визитом. Очень мило с твоей стороны.\n\nМои помощники все гадали – придешь или нет? Я говорил им – несомненно, придет. Когда речь заходит о могуществе, летишь как мотылек на свечу.", rewards = "Вы получите:\n\n"},
[4490] = {title = "Призывание коня Скверны", objective = "Поговорите в Кабестане со Страхадом Фарсаном, чтобы получить способность призывать коня Скверны.", description = "Я бы наградил тебя за терпение да усердие. Но, знаешь ли, в будущем призывание коня Скверны будет куда труднее. Придется заслужить награду... и это будет непросто.\n\nПока же получи способность призывать эту тварь и пользуйся ей по своему усмотрению.", progress = nil, completion = "Удачи, Шта. Надеюсь встретиться с тобой в будущем.", rewards = "Вы изучите:\n\nПризывание коня Скверны\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание коня Скверны\n\nВы также получите:\n\n"},
[4491] = {title = "Дружеская помощь", objective = "Отведите Ринго к Муче Кусора в Укрытие Маршалла. \n\nЕсли Ринго потеряет сознание, плесните на него воды из фляги Спрэггл, чтобы привести его в чувство.", description = "Уф... Как здесь жарко! \n\nЯ тут прогуливался по окрестностям, как вдруг накатила эта жуткая жара. Похоже, у меня тепловой удар. \n\nПомоги мне добраться до моей подруги Спрэггл в Укрытие Маршалла. Думаю, я сумею дойти, если кто-то будет вести меня. \n\nЕсли я вдруг потеряю сознание, просто плесни мне в лицо воды из фляги Спрэггл. Думаю, этого будет достаточно...", progress = "О, я так волновалась за Ринго!", completion = "Да, Ринго совсем плох, Хантор, но я рада, что он вернулся в целости и сохранности... \n\nСпасибо, что разыскал его!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНабедренники с самоцветамиПоножи древесной вершиныШлем Глиняной гряды\n\nВы также получите:\n\n"},
[4492] = {title = "Потерялся!", objective = "Найдите Ринго на Вулкане Огненного Венца.", description = "Помоги мне, <имя>! Мой друг Ринго отправился сегодня исследовать вулкан к югу отсюда, и его что-то долго нет! Я очень беспокоюсь. \n\nТы сможешь найти его? Вот, возьми с собой эту флягу, думаю она ему пригодится!", progress = "Кто... Кто здесь?", completion = "О, я так рад, что ты нашел меня!", rewards = "Вы получите:\n\n"},
[4493] = {title = "Нашествие силитидов", objective = "Поговорите с алхимиком Пестычинсом в Прибамбасске.", description = "Такое впечатление, что смысл самого существования силитидов состоит в том, чтобы сожрать все, что отлично от них. Они ведут себя очень целеустремленно и именно поэтому представляют серьезную опасность для всего Азерота.\n\nВсе, что мы видели до сих пор, – это только цветочки! Подозреваю, что их основные силы сосредоточены в глубине Калимдора, в Кратере Ун'Горо. Ступай в Прибамбасск в пустыне Танарис и поговори с алхимиком Пестычинсом. Расскажи ему о моей гипотезе. Он наверняка поможет нам бороться с силитидами.", progress = nil, completion = "Как понимаю, тебя прислала Грацина? Твой опыт в истреблении этих тварей воистину бесценен – пока я еще не видел никого, кто осмелился бы потягаться с ними. Что же до идеи Грацины насчет того, что их гнездо – Кратер Ун'Горо... может быть, оно и так. Ун'Горо – это таинственные и опасные джунгли к западу отсюда. Может быть, мы действительно подошли на шаг ближе к разрешению загадки силитидов.", rewards = "Вы получите:\n\n"},
[4494] = {title = "Нашествие силитидов", objective = "Поговорите с алхимиком Пестычинсом в Прибамбасске.", description = "Такое впечатление, что намерения, более того, смысл самого существования силитидов состоит в том, чтобы сожрать все, что отлично от них. Они ведут себя очень целеустремленно и именно поэтому представляют серьезную опасность для всего Азерота.\n\nВсе, что мы видели до сих пор, – это только цветочки! Подозреваю, что их основные силы сосредоточены в глубине Калимдора, в Кратере Ун'Горо. Ступай в Прибамбасск в пустыне Танарис и поговори с алхимиком Пестычинсом. Расскажи ему о моей гипотезе. Он наверняка поможет нам бороться с силитидами.", progress = nil, completion = "Да, я так понимаю, тебя Зилзибин прислал? Твой опыт воистину бесценен: до тебя я не встречал никого, кому доводилось сражаться с этими тварями. Что касается идеи Зиба насчет Кратера Ун'Горо... Может быть, он и прав. Ун'Горо – это таинственные и опасные джунгли к западу отсюда. Может быть, мы действительно подошли на шаг ближе к разрешению загадки силитидов.", rewards = "Вы получите:\n\n"},
[4495] = {title = "Добрый друг", objective = "Найдите Иверрона возле пещеры на севере.", description = "Мой друг по имени Иверрон обычно навещает меня в одно и то же время каждый день. Странно, что сегодня он вообще не пришел – он задерживается уже на несколько часов.\n\nПризнаться, <имя>, я несколько волнуюсь. Иверрон проводит много времени возле пещеры к северу отсюда, и я знаю, насколько там опасно – это ведь логово пауков!\n\nПослушай, если ты вдруг направляешься в ту сторону, то не поищешь ли Иверрона?", progress = nil, completion = "Я рад, что тебе удалось найти меня, Айлерон. Как ты узнал, что я тут?", rewards = "Вы получите:\n\n"},
[4496] = {title = "Путаница в джунглях", objective = "Принесите ароматическую железу Гориши и 5 образцов почвы из Кратера Ун'Горо алхимику Пестычинсу в Прибамбасск.", description = "Исследования показали, что силитиды подобны пчелам – стоит убить королеву улья, и остальные без нее пропадут. Я создам приманку, которая позволит тебе выманить королеву. Выманив ее, сразись с ней.\n\nВпрочем, для начала нам понадобятся некоторые составляющие. Отправляйся на запад, в ульи силитидов в Кратере Ун'Горо и принеси ароматическую железу одного из мерзких жуков. Кроме того мне понадобятся образцы почвы из кратера.", progress = "Найти подходящую ароматическую железу может оказаться непросто – она должна быть в идеальном состоянии, чему совсем не способствует способ добычи. Что же до почвы, ее-то должно быть совсем нетрудно отыскать.\n\nКороче, ты принес мне все необходимое?", completion = "А, вот и ароматическая железа. Похоже, мембрана цела – великолепно. И почва тоже подойдет. Я кое-чего добавлю, и сделаю из этого прекрасную приманку.\n\nПодожди минутку, и все будет готово. После этого можно будет сделать следующий шаг и остановить силитидов, пока они не захватили Прибамбасск... и весь остальной Калимдор.", rewards = "Вы получите:\n\n"},
[4501] = {title = "Осторожно, злой жутедактиль", objective = "Убейте 10 жутедактилей и 15 бесноватых жутедактилей, затем поговорите со Мучей Кусора в Укрытии Маршалла.", description = "Требуется: опытный боец для устранения угрозы со стороны жутедактилей, населяющих Кратер Ун'Горо. Популяция этих тварей растет, они уже представляют серьезную угрозу забредшим в кратер путникам. \n\nНеобходимо уменьшить популяцию, убив 10 жутедактилей и 15 бесноватых жутедактилей. \n\nВыполнивших задание просьба обращаться за наградой к Муче Кусора.", progress = nil, completion = "Я просто в шоке от жутедактилей! Спасибо тебе, Томпсон! Теперь я хотя бы смогу спокойно высунуть нос из Укрытия Маршалла!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки Пещерной плитыСкальные латные наголенники\n\nВы также получите:\n\n"},
[4502] = {title = "Вулканическая активность", objective = "Добудьте 9 образцов пепла Ун'Горо из элементалей огня, что водятся вокруг вулкана в Кратере Ун'Горо, и доставьте их Лив Быстрочин в Кабестан.", description = "Я многому научилась у Марвона Клепальщика. Но он уже так давно уехал, что я уж подумываю начать собственные эксперименты.\n\nЯ недавно читала о Кратере Ун'Горо и странной вулканической деятельности в его центре. Мне думается, что многе можно было бы узнать, если бы мне удалось заполучить для исследований немного пепла из тамошних элементалей.\n\nВы не против добыть немного пепла для меня, раз уж все равно туда идете?", progress = "Это правда, что вулкан в Ун'Горо активен? Уверена, что многе смогу узнать по вулканическому пеплу, Томпсон.", completion = "Эти образцы как нельзя лучше сгодятся для моих исследований! Спасибо, Томпсон! Обещаю – тебе я расскажу о моих открытиях в первую очередь!", rewards = "Вы получите:\n\n"},
[4503] = {title = "Крылолет Шиззла", objective = "Принесите 8 чешуй перепончатого деметродона 8 чешуй перепончатого жутедактиля Шиззлу в Укрытие Маршалла.", description = "Я работаю над вертолетом! \n\nИ вот, застрял здесь и не могу выбраться! С удовольствием тормознул бы грифона или ветрокрыла, чтобы подбросили меня до Прибамбасска, да только ужасно боюсь этих тварей! \n\nТы мне не поможешь? Мне осталось сделать только крылья, и я думаю, что чешуя жутедактиля или деметродона была бы идеальным материалом. Однако маленькому гоблину не под силу справиться со столь грозными хищниками! А ты на вид весьма <крут/крута>! Может, попытаешься добыть мне чешуек?", progress = "Как вы лодку назовете, так она и поплывет! Нужно хорошее имя моему летательному аппарату! Я назову его... Крылолет!", completion = "Да, эта чешуя подходит просто превосходно! С помощью этих чешуек мне уж точно удастся поднять мое творение в воздух! \n\nБлагодарю тебя!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПреграждающий щит ШиззлаНамордник ШиззлаБоевые нарукавники Шиззла\n\nВы также получите:\n\n"},
[4504] = {title = "Суперлипучка", objective = "Отнесите 12 образцов сверхлипкой смолы Тран'реку в Прибамбасск.", description = "Я всегда искал способ быстро заработать. Если ты поможешь воплотить мою последню идею, я поделюсь с тобой доходами. Что ты на это скажешь?\n\nТак я и думал!\n\nСтупай к смоляным ямам в северной части Кратера Ун'Горо и принеси мне смолы. Но не просто смолы, а смолы из зверей, живущих вокруг этих ям. Обычная смола недостаточно липкая.\n\nВ растениеподобных существах присутствиет хлорофилл, и смола, смешанная с ним, делается сверхлипкой.", progress = "Тран'рек гений, прочь сомненья – этот суперклей с руками оторвут!", completion = "Да, да, та самая смола…\n\nЭй, минуточку, руки мои, руки... Я не могу их разлепить…\n\nМожет быть, это не такая уж хорошая идея. Впрочем, стоп! Растворитель суперлипкой смолы! Вот что разойдется за полдня!", rewards = "Вы получите:\n\n"},
[4505] = {title = "Источник порчи", objective = "Принесите образец оскверненной воды из лунного колодца сатиров Нефритового Пламени Винне Хеззард на Заставу Отравленной Крови.", description = "Говорят, будто я слишком жестока... Но ведь это только потому, что я жажду добыть для Орды преимущество перед Альянсом любым способом.\n\nСейчас меня прежде всего интересует лунный колодец в руинах Констелласа, к югу отсюда, который охраняют сатиры из племени Нефритового Пламени. Этот лунный колодец, некогда символ возрождения этих несносных ночных эльфов, ныне осквернен, и порождает все больше сатиров.\n\nУ меня есть одна мысль, <имя>, и мне хотелось бы получить пробу воды оттуда... для моей любимой кошечки.", progress = "Это чрезвычайно важно. Ступай не медля!", completion = "Очень хорошо.Нам надо найти способ использовать эту порчу против наших врагов...", rewards = "Вы получите:\n\n"},
[4506] = {title = "Зараженные саблезубы", objective = "Отнесите котенка Винны к оскверненному лунному колодцу, выпустите его, затем снова принесите Винне.\n\nКак только вернетесь к Винне, щелкните мышкой по котенку, чтобы выпустить его.", description = "Эта оскверненная вода может помочь нам, <имя>. От одной ее капли мои котятки выросли вдвое и даже стали сильнее... кое в чем. Эти кошечки могут оказаться полезными...\n\nВот, <имя>. Возьми эту кошачью переноску и выпусти котеночка, что сидит внутри возле лунного колодца, что в руинах Констелласа. Хе-хе... результаты тебе наверняка понравятся!\n\nПотом принеси кошечку ко мне обратно, а я уж возмещу тебе затраты времени.", progress = "И не говори мне, что тебе не удалось туда попасть! Иди!", completion = "Отлично!\n\nОтрекшиеся не побрезгуют никакими средствами, чтобы сокрушить Альянс! И эта оскверненная вода весьма поможет нам в наших будущих трудах...", rewards = "Вы получите:\n\n"},
[4507] = {title = "Пешка берет королеву", objective = "Призовите и сразите матку улья Гориши.\n\nПринесите мозг матки Гориши алхимику Пестычинсу в Прибамбасск.", description = "Вот и приманка. Внутри улья должен быть какой-то кристалл. Мы думаем, что силитиды пользуются им для вещания по всему улью. Где он? Я бы поискал в инкубаторах.\n\nЕсли положить приманку на этот кристалл, непременно явится королева. Но предупреждаю, без охраны она не ходит. Убей ее и вынь из нее мозг. Как ни гадко это звучит, его необходимо изучить. Удачи, <имя>!", progress = "Нам не обойтись без мозга королевы. Судя по всему, силитиды находятся под контролем чуждой злой силы. Мне страшно думать, кто может управлять такой злобной тварью, как силитид, Томпсон.", completion = "Поразительно! Сегодня мы одержали победу. Впрочем, нам понадобится время, чтобы разобраться с полученными материалами. Не волнуйся, все пойдет в дело.\n\nЧто до силитидов, я искренне сомневаюсь, что мы сумели остановить их нашествие. К сожалению, это было бы слишком легко.", rewards = "Вы получите:\n\n"},
[4508] = {title = "Затишье перед бурей", objective = "Отнесите отчет Пестычинса о ситуации в Ун'Горо Грацине Силе Духа в Дарнасс.", description = "Все исследования, да и знания, полученные нами сегодня, как можно скорее должны дойти до тех, кто в силах что либо предпринять. Прибамбасску не выстоять одному, невзирая на наши многочисленные таланты.\n\nОтнеси мой последний отчет Грацине Силе Духа, в Дарнасс; она ведь по-прежнему в [раме Луны? У нее много друзей среди важных шишек Альянса, <имя>; если удастся привлечь их внимание, быть может мы и выживем.", progress = "Они глупцы, Джэйлол! Бессмысленная ненависть к Орде затмила им разум. Они не видят дальше своего носа – не верят в опасность, грозящую всем нам. Не знаю, как еще можно доказать им реальность нашествия силитидов. Может, бросить прямо в ульи?\n\nПрости, ты, наверное, несешь какие-то вести?", completion = "Хотя я очень благодарна тебе, не знаю, выйдет ли из этого толк. Альянс видит лишь опасность, исходящую от Орды, а ведь даже наши вожди здесь, в Дарнассе, не понимают, в чем именно она состоит. Глупцы вроде Фэндрала Оленьего Шлема уверяют, что силитиды не могут грозить нам как тогда, в далеком прошлом. Он невежда – и невежа!\n\nТы видел опасность своими глазами. Мы должны одолеть силитидов!", rewards = "Вы получите:\n\n"},
[4509] = {title = "Затишье перед бурей", objective = "Отнесите отчет Пестычинса о ситуации в Ун'Горо Зилзибину Барабанному Бою в Оргриммар.", description = "Все исследования, да и знания, полученные нами сегодня, как можно скорее должны дойти до тех, кто в силах что либо предпринять. Прибамбасску не выстоять одному, невзирая на наши многочисленные таланты.\n\nОтнеси мой последний отчет Зилзибину Барабанному Бою, в Оргриммар; он ведь по-прежнему там? У него много друзей среди важных шишек Орды; если удастся привлечь их внимание, быть может мы и выживем.", progress = "Они глупцы, Томпсон! Бессмысленная ненависть к Альянсу затмила им разум. Они не видят дальше своего носа – не верят в опасность, грозящую всему миру. Не знаю, как еще можно доказать им реальность нашествия силитидов. Может, бросить прямо в ульи?\n\nПрости, ты, наверное, несешь какие-то вести?", completion = "Хотя я очень благодарна тебе, не знаю, выйдет ли из этого толк. Орда видит лишь опасность, исходящую от Альянса. Если бы удалось доложить о случившемся лично Траллу, он непременно принял бы меры, но его окружают дурные советчики. Они готовы гоняться за собственным хвостом, надеясь застать Альянс врасплох!\n\nТы видел опасность своими глазами. Мы должны одолеть силитидов!", rewards = "Вы получите:\n\n"},
[4510] = {title = "Затишье перед бурей", objective = "Отнесите банковскую расписку Идриане в банк Дарнасса.", description = "<имя>, твоя помощь просто неоценима. Придет время, и, думается, я снова буду вынужден обратиться к тебе за содействием в борьбе против силитидов. Мы должны осмыслить все, что узнали в Ун'Горо. Опасаюсь, что мои предположения по поводу того, что силитиды родом из Ун'Горо, неверны... и где-то их гораздо больше.\n\nОтнеси эту бумагу Идриане в банк. Она выдаст тебе кое-что из моего хранилища в знак моей признательности. Благодарю тебя за помощь, <отважный/отважная:c> <класс>.", progress = "Элуне'адоре, |3-6(Жрец). Чем могу помочь?", completion = "Эта расписка дает мне право выдавать вам предметы из хранилища Грацины Силы Духа в нашем банке. Похоже, она весьма вам благодарна!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСфера ЗабвенияНаплеч Чудовищного лесаЭшевальские наголенники\n\nВы также получите:\n\n"},
[4511] = {title = "Затишье перед бурей", objective = "Отнесите банковскую расписку Карусу в банк Оргриммара.", description = "Спасибо тебе, <имя>. Без тебя у нас бы ничего не вышло. Несомненно, вскоре придет время, когда я снова попрошу твоей помощи в борьбе с силитидами. Придется пересмотреть то, что известно нам по Ун'Горо. Боюсь, мое предположение, что силитиды происходят из Ун'Горо, оказалось ложным. Где-то есть другое гнездо, куда более крупное.\n\nОтнеси эту записку Карусу в банк. Он выдаст тебе кое-что, что может считаться знаком моей благодарности. Спасибо за помощь, <могучий/могучая:c> <класс>!", progress = "Заг-заг! Чем могу служить, |3-6(Охотник)?", completion = "Согласно этой расписке, мне следует выдать вам некий предмет из хранилища Зилзибина Барабанного Боя. Кажется, вас можно поздравить!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСфера ЗабвенияНаплеч Чудовищного лесаЭшевальские наголенники\n\nВы также получите:\n\n"},
[4512] = {title = "Долгий путь слизнюка", objective = "Принесите 6 банок с проклятыми слизнюками и 6 банок с нечистыми слизнюками Ларису Обалдую в Стальгорн.", description = "Но больше всего я изучал слизнюков. Я понимаю, что звучит нелепо, но их же почти не осталось!\n\nНе так давно я помогал одной даме из Менетила искать ее сумку – так слизнюки эту сумку сожрали. Я видел, что члены Королевского фармацевтического общества Подгорода собирают образцы этих тварей. Я хочу понять, почему! Откуда они их берут?\n\nЯ слышал, что они водятся в Оскверненном лесу. Мне нужны экземпляры этих слизнюков для продолжения исследований. Я дам вам банки, а вы возьмете образцы мертвых существ.", progress = "Некоторые мои эксперименты дают просто невероятные результаты. Думаю, еще немного, и я смогу понять природу этих тварей и выяснить, какую роль они сыграли в происхождении жизни в Азероте... если, конечно, они вообще имеют отоношение к Азероту.\n\nОдна из величайших моих теорий – не слишком популярных – гласит, что слизнюки и слизь не связаны собственно с происхождением нашей планеты. Они, скорее, ее выделения.\n\nНо я не могу ни доказать ее, ни опровергнуть, пока не получу побольше образцов.", completion = "Блестящий результат, Кавару! Вы умудрились подойти достаточно близко, взять образцы этих гнилостных тварей и ничуть не пострадать! Благодарю вас. О, это как раз то, что надо. Немедленно примусь за эксперименты.\n\nЕсли я прав, я стану одним из величайших ученых Лиги Исследователей!\n\nЭто покажет всем дворфам, что они правильно поступили, пустив нас, гномов, в Стальгорн после гномреганской катастрофы.", rewards = "Вы получите:\n\n"},
[4513] = {title = "Долгий путь слизнюка", objective = "Принесите 10 банок с чистыми образцами Ларису Обалдую в Стальгорн.\n\nЕсли будет трудно их найти, возможно, стоит попытаться добиться от Лариса подсказки.", description = "Мне, похоже, понадобятся еще образцы, <имя>. Но – как бы это сказать – они должны быть чистыми. Да знаю, знаю. \"Что значит \"чистые\", Ларис?\" Я не уверен. Я знаю только, что вот эти – осквернены... прямо как Оскверненный лес. Потому так важно понять. Эти слизнюки словно бы приспосабливаются к условиям места, в котором находятся. Мне нужны образцы, которые не заражены. Но где их взять? Где?!\n\n<имя>, возьмите эти банки на случай, если вам попадутся чистые экземпляры.", progress = "Как много нужно обдумать. Но что это значит? И как это влияет на жизнь народов Азерота?", completion = "Так вы их нашли? Исчезайка, вы – сущее сокровище! Ваши преданность и помощь просто неоценимы, я даже не знаю, чем вас отблагодарить!\n\nПожалуйста, примите это за ваши труды. Мне надо кое над чем поработать, но я уверен, что, когда вы вернетесь, мне снова понадобится ваша помощь.\n\nБлагодарю вас! От всего сердца благодарю!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДымчатые сапогиБронзовые рукавицы\n\nВы также получите:\n\n"},
[4521] = {title = "Одичавшие стражи", objective = "Убейте для Трулла Баловня Судьбы 15 бешеных совухов и 15 лохматых совухов.", description = "Зимние Ключи расположены как раз за Древобрюхами на северо-востоке Оскверненного леса. Приходилось там бывать?\n\nЯ слышал, что эти края заселены существами, которых называют дикими совухами. Эти животные, как известно, охраняли тайны ночных эльфов.\n\nМы должны выяснить, какие тайны хранятся в Зимних Ключах.\n\nЯ слышал что лохматые совухи водятся к югу от этой дороги, а те, которых называют бешеными совухами, населяют центр Зимних Ключей. Убей их и расчисть дорогу.", progress = nil, completion = "Отличные новости, Томпсон. Теперь, когда эти твари не стоят у нас на пути, мы можем проникнуть в Зимние Ключи. Ты готов?", rewards = "Вы получите:\n\n"},
[4542] = {title = "Письмо на Заставу Вольного Ветра", objective = "Отнесите срочное послание дозорному утесов Долгорогу на Заставу Вольного Ветра.", description = "Кентавры стали все чаще нападать на эти земли, и об этом нужно срочно доложить на Заставу Вольного Ветра! Отправляйтесь туда, найдите дозорного утесов Долгорога и отдайте ему это письмо. Форт находится к юго-востоку отсюда.\n\nНо будьте осторожны: неподалеку есть поселение клана Зловещий Тотем, и его члены в последнее время ведут себя беспокойно", progress = "Что вы хотели, |3-6(Разбойник)? Срочное послание? Для меня?", completion = "Опять плохие новости! Эти кентавры зашли слишком далеко! Они напали на один из моих караванов и убили всех погонщиков! Это неслыханно, они должны за это заплатить!", rewards = "Вы получите:\n\n"},
[4561] = {title = "Образцы на пробу из кратера Ан-Горо", objective = "Вы наполняете слизью, добытой в Кратере Ун'Горо, различные колбы и мензурки, стоящие на столе. Все начинает бурлить и брызгаться, а слизь меняет цвет. Потом процесс замедляется, жидкость перестает кипеть, и вы видете маленькую чашечку Петри с пробой измененной слизи и какие-то ошметки.", description = nil, progress = "Вы наполняете слизью, добытой в Кратере Ун'Горо, различные колбы и мензурки, стоящие на столе. Все начинает бурлить и брызгаться, а слизь меняет цвет. Потом процесс замедляется, жидкость перестает кипеть, и вы видете маленькую чашечку Петри с пробой измененной слизи и какие-то ошметки.", completion = "Вы берете чашку Петри с пробой слизи. Выяснить, достаточно ли образец чистый, можно только одним способом – открыть колбы и самостоятельно исследовать их содержимое. В конце концов вы должны найти пробу, которая устроит химика Барабоса.", rewards = "Вы получите:\n\nПроверенный образец из Ун'Горо"},
[4581] = {title = "Кайнет Штиль", objective = "Отнесите записку Шиндрелл Кайнету Штилю в Лесную Песнь.", description = "Друид Кайнет Штиль прислал мне весточку. Он хотел бы получить отчет обо всем, что творится у нас на побережье и в лесах вокруг Астранаара. Он опасается, что по Ясеневому лесу расползается порча... Может, он и прав.\n\nВот, отнеси ему мой отчет. Ты найдешь его в святилище Лесной Песни, в лесах Ночной Песни к востоку отсюда.", progress = "Ты что-то мне принес?", completion = "А, отчет Шиндрелл! Премного благодарен, Вив. Шиндрелл – отличный часовой, она отважна и умна. Надо прочесть это донесение и попытаться понять, что за нечисть расползается по Ясеневому лесу.", rewards = "Вы получите:\n\n"},
[4601] = {title = "Чистер 5200!", objective = "Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200.", description = "Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений.Небольшая табличка, прикрепленная к устройству, гласит: \"Чистер 5200\".\n\nВаши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер 5200 легко справится с этой проблемой! Опустите в щель приемника три серебряные монеты и подождите пару минут, пока Чистер 5200 наводит лоск на ваши украшения.", progress = "Похоже, что в механизм следует положить предмет, нуждающийся в очистке, и три серебряных монеты.", completion = "Вы кладете покрытый грязью предмет и три серебряные монеты в Чистер 5200, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует.", rewards = nil},
[4602] = {title = "Чистер 5200!", objective = "Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200.", description = "Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений.Небольшая табличка, прикрепленная к устройству, гласит: \"Чистер 5200\".\n\nВаши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер 5200 легко справится с этой проблемой! Опустите в щель приемника три серебряные монеты и подождите пару минут, пока Чистер 5200 наводит лоск на ваши украшения.", progress = "Похоже, что в механизм следует положить предмет, нуждающийся в очистке, и три серебряных монеты.", completion = "Вы кладете покрытый грязью предмет и три серебряные монеты в Чистер 5200, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует.", rewards = nil},
[4603] = {title = "Работа для Чистера", objective = "Приемник Чистера 5200 пуст. Чтобы машина заработала, требуется загрязненный предмет и три серебряные монетки.", description = nil, progress = "Приемник Чистера 5200 пуст. Чтобы машина заработала, требуется загрязненный предмет и три серебряные монетки.", completion = "Чистер 5200 с яростным гудением принимается за работу. Въевшаяся грязь растворяется под воздействием гномьих чистящих средств. \n\nНаконец Чистер 5200 перестает вибрировать. Окошко премника со звоном открывается – в нем лежит аккуратно завернутая коробка.", rewards = "Вы получите:\n\nКоробка, упакованная \"Чистером\""},
[4604] = {title = "Работа для Чистера", objective = "Приемник Чистера 5200 пуст. Чтобы машина заработала, требуется загрязненный предмет и три серебряные монетки.", description = nil, progress = "Приемник Чистера 5200 пуст. Чтобы машина заработала, требуется загрязненный предмет и три серебряные монетки.", completion = "Чистер 5200 с яростным гудением принимается за работу. Въевшаяся грязь растворяется под воздействием гномьих чистящих средств. \n\nНаконец Чистер 5200 перестает вибрировать. Окошко премника со звоном открывается – в нем лежит аккуратно завернутая коробка.", rewards = "Вы получите:\n\nКоробка, упакованная \"Чистером\""},
[4605] = {title = "Чистер 5200!", objective = "С проглотив кольцо, машина несколько минут с гудением вертит его в своих недрах и наконец останавливается, звенящим звуком оповестив вас о том, что работа закончена. Окошко приемника открывается, и вы видите в нем аккуратно завернутую коробочку. Видимо, машина выдает очищенные предметы в подарочной упаковке. Ну, даже если кольцо не удалось очистить, вы получили довольно миленькую коробочку за свои деньги... \n\nЧто ж, посмотрим...", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКоробка, упакованная \"Чистером\""},
[4606] = {title = "Чистер 5200!", objective = "С проглотив кольцо, машина несколько минут с гудением вертит его в своих недрах и наконец останавливается, звенящим звуком оповестив вас о том, что работа закончена. Окошко приемника открывается, и вы видите в нем аккуратно завернутую коробочку. Видимо, машина выдает очищенные предметы в подарочной упаковке. Ну, даже если кольцо не удалось очистить, вы получили довольно миленькую коробочку за свои деньги... \n\nЧто ж, посмотрим...", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКоробка, упакованная \"Чистером\""},
[4621] = {title = "Стой, Адмирал!", objective = "Убейте командира флота Морского Рога и барона Ревилгаза из Пиратской бухты, а потом возвращайтесь к командиру флота Фираллону на борту \"Багрового Паруса\" неподалеку от побережья Тернистой долины.", description = "Слышь, ты, морской волк... Нам, пиратам Кровавого Паруса, жить да поживать бы, когда бы не Пиратская бухта. Ух, мы порезвились бы вдоволь! А если б ты <пырнул/пырнула> ножом командира флота Морского Рога,чихали бы мы тогда на его посудины! Если б ты <пырнул/пырнула> ножом барона Ревилгаза, мы б и их закона не боялись.\n\nВ общем, коль хочешь стать у нас почетным адмиралом – да, АДМИРАЛОМ, я не шучу, прирежь обоих, и все дела. Иди, <парень/девица>, возвращайся, когда дело будет сделано.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nАдмиральская шляпа Кровавого Паруса"},
[4641] = {title = "Твое место в мире", objective = "Поговорите с Горнеком. Вы помните, как Калтунк отметил на карте его местонахождение и упомянул, что Горнек живет в Логове, здании, расположенном на западе.", description = "Ну вот, <имя>, ты и <стал взрослым... достаточно взрослым/стала взрослой... достаточно взрослой>, чтобы сражаться во имя Орды и во славу вождя.\n\n*Калтунк меряет вас взглядом.*\n\nДа, ты вполне годишься!\n\nРазумеется, тебе уже хочется повстречаться с огромным драконом или каким-нибудь демоном и задушить его голыми руками, но, пожалуй, начать стоит с чего-нибудь... не такого грозного.\n\n*Калтунк хохочет.*\n\nОтправляйся к Горнеку, он сумеет подыскать дело, которое будет тебе по плечу, <юный/юная:c> <класс>. Горнека ты найдешь в Логове, на западе.", progress = nil, completion = "Очередной рекрут Калтунка?\n\nВидно, плохи наши дела, если у нас нет никого получше. Ну, ничего. К тому времени, как мы решим, что тебе пора покинуть долину, из тебя получится бравый воитель Орды!", rewards = "Вы получите:\n\n"},
[4642] = {title = "Слияние", objective = "Принесите образец перемешанной слизи химику Барабосу в Подгород.", description = "В этом сосуде находится слизнюк, созданный из пробы, которую ты <принес/принесла> из Оскверненного леса. Отнеси его к кратеру Ун'Горо и отыщи чистого слизнюка. Подберись поближе, выпусти наш экземпляр и посмотри, что они сделают друг с другом.\n\nПо завершении эксперимента принеси мне пробу того, что останется. Я буду ждать тебя здесь, в Районе Фармацевтов.", progress = "Как идет эксперимент, Томпсон? Я вернусь к изучению принесенных тобой проб, поскольку начинаю понимать, почему ими так заинтересовалась леди Сильвана. Если они в самом деле часть Древних богов, то кто знает, какую пользу они могли бы принести нам...", completion = "О, великолепно, Томпсон. Великолепно.\n\nНу и дела. Кто бы подумал, что они будут взаимодействовать таким образом... Придется посвятить побольше времени изучению феноменов окружающей среды, которые вызывают в этих тварях подобные изменения.\n\nА теперь я вернусь к своим исследованиям. Быть может, вскоре свидимся. Пока же – всего наилучшего.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо АптекаряХламида химика\n\nВы также получите:\n\n"},
[4661] = {title = "Проба – образцы из Оскверненного леса", objective = "Вы наполняете слизью, добытой в Оскверненном лесу, различные колбы и мензурки, стоящие на столе. Все начинает бурлить и брызгаться, а слизь меняет цвет. Потом процесс замедляется, жидкость перестает кипеть, и вы видете маленькую чашечку Петри с пробой измененной слизи и какие-то ошметки.", description = nil, progress = "Вы наполняете слизью, добытой в Оскверненном лесу, различные колбы и мензурки, стоящие на столе. Все начинает бурлить и брызгаться, а слизь меняет цвет. Потом процесс замедляется, жидкость перестает кипеть, и вы видете маленькую чашечку Петри с пробой измененной слизи и какие-то ошметки.", completion = "Вы берете чашку Петри с пробой слизи. Выяснить, достаточно ли образец чистый, можно только одним способом – открыть колбы и самостоятельно исследовать их содержимое. В конце концов вы должны найти пробу, которая устроит химика Барабоса.", rewards = "Вы получите:\n\nОскверненная проба"},
[4681] = {title = "Останки на берегу", objective = "Извлеките останки морской черепахи из скелета морской черепахи, лежащего в воде к западу от Аубердина, а затем поговорите с Гвеннид Блай'Леггонд в Аубердине.", description = "Та тварь на берегу – не единственная на Темном Берегу. Вдоль побережья их еще много, да и в воде тоже. Я хотела бы, чтобы вы исследовали другие известные нам останки. Мне сообщили, что они находятся в воде, непосредственно к западу от Аубердина, возле затонувшего судна. Возвращайтесь ко мне с тем, что вам удастся найти полезного для нас.\n\nКстати, в ваших странствиях вы можете найти и другие подобные останки. Если вы обнаружите что-то, обязательно принесите нам для дальнейших исследований!", progress = "Когда вы исследуете останки твари, лежащие в воде к западу отсюда, я, наверное, смогу представить надлежащий отчет в храм Луны в Дарнассе. Возможно, тогда мы приблизимся к пониманию того, почему эти несчастные создания выбирают такую смерть, выбрасываясь на отмели на Темных берегах.", completion = "Вы чрезвычайно помогли мне сегодня; теперь у нас есть серьезные шансы узнать, почему эти твари выбрасываются на отмели Темного Берега. Мысль о том, что они бегут сюда из прибрежных вод Тельдрассила, очень беспокоит меня. Если вы наткнетесь на другие останки в ваших странствиях, пожалуйста, дайте мне знать. Наши исследования здесь пока на начальной стадии.\n\nОт имени Храма Луны примите, пожалуйста, это в качестве благодарности за ваши труды. Благодарю вас, Wrestlecake!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги ПескоходаПояс из сухих водорослейНаручи из раковины\n\nВы также получите:\n\n"},
[4701] = {title = "Устранение опасности", objective = "Отправьтесь на пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами.", description = "Тебе несомненно приходилось видеть воргов, которыми командуют орки Черной Горы.\n\nВот что интересно – сколько мы их ни убиваем, их не делается меньше. Разведчики доносят, что воргов растят и обучают на пике Черной Горы, в столице орков этого клана. Отправляйся туда и поищи источник опасности. Отыщи... и уничтожь.\n\nУдачи, <имя>. Да хранит тебя Кенарий...", progress = nil, completion = "Не думай о том, страдала ли она, Август. Этого зверя осквернило касание темной магии. Ты оказал Альянсу огромную услугу и получишь за нее награду.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nАсторийские одеянияЗвероловецкий жакетКираса из нефритовой чешуи\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4721] = {title = "Одичавшие стражи", objective = "Убейте для Трулла Баловня Судьбы из Оскверненного леса 10 яростных совухов в Зимних Ключах.", description = "Гонцы вернулись из Зимних Ключей с сообщением о том, что в его южной части есть группа небольших пещер. У них сложилось впечатление, что этот район обжили дикие совухи. Если они охраняют что-то важное, то, я думаю, именно там мы это и найдем.\n\nС этими дикими совухами тебе будет справиться намного сложнее, чем в предыдущий раз, <имя>. Эти создания, похоже, ввергает в безумие та самая вещь, которую они столь яростно защищают.", progress = nil, completion = "Вот что я уважаю – так это хорошую работу, Томпсон. Теперь мы можем дальше действовать в Зимних Ключах.", rewards = "Вы получите:\n\n"},
[4722] = {title = "Останки морской черепахи", objective = "Отнесите останки морской черепахи Гвеннид Блай'Леггонд в Аубердин.", description = "Вы наткнулись на останки морской черепахи, некоторое время назад выбросившейся на Темный Берег. Плоть ее уже объели мурлоки, обосновавшиеся неподалеку от останков. Однако вы можете набрать достаточное количество образцов, которые пригодятся Гвеннид Блай'Леггонд.", progress = "Здравствуйте, Wrestlecake, вы хотите рассказать еще что-то о тварях, выбросившихся на берег?", completion = "Еще одна находка, которую нам надо изучить. Хорошая работа, Wrestlecake! Эти останки будут исследованы должным образом, когда их доставят в Дарнасс. Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете.", rewards = "Вы получите:\n\n"},
[4723] = {title = "Останки морской твари", objective = "Отнесите кости морской твари Гвеннид Блай'Леггонд в Аубердин.", description = "Останки гигантского крепкозуба – намного больших размеров, чем можно было бы ожидать на Темном Берегу, – лежат у побережья Туманного предела. Как это существо очутилось здесь, неизвестно; мурлоки, объедающие тушу, кажутся слишком слабыми и неспособными даже толпой притащить ее сюда.\n\nВ то время как некоторая часть костей уже начисто обглодана, останков еще достаточно, чтобы набрать образцов для Гвеннид Блай'Леггонд.", progress = "Может, когда-нибудь мы изыщем средство, чтобы несчастные твари больше не заканчивали впустую  свою жизнь на отмелях Темного Берега. А до тех пор мы должны продолжать наши исследования.\n\nПриветствую, Wrestlecake! С какими вы вестями?", completion = "Еще одна находка, которую нам надо изучить. Хорошая работа, Wrestlecake! Эти останки будут исследованы должным образом, когда их доставят в Дарнасс. Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете.", rewards = "Вы получите:\n\n"},
[4724] = {title = "Праматерь стаи", objective = "Убейте Халикон, праматерь стаи воргов Кровавого Топора.", description = "Ходят слухи, что ворги, управляемые орками Черной Горы, – создания сверхъестественных сил. Говорят также, что это не настоящие ворги, а потомство пса-демона, подаренное оркам властителем преисподней. \n\nПравда куда более проста, но не менее ужасна. Ворги Черной Горы – потомство Халикон, огромной праматери воргов. Каков из себя ее самец? Вряд ли кто из видевших его выжил, чтобы поведать об этом. \n\nНужно нанести удар по самому сердцу логова воргов. Уничтожь Халикон. И прошу тебя, не забывай об осторожности!", progress = nil, completion = "Бешеные щенки? Гизрул Поработитель? И ты стоишь передо мной живехонький и рассказываешь об этом?! Глазам не верю! Ты заслужил свою награду!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nАсторийские одеянияЗвероловецкий жакетКираса из нефритовой чешуи\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4725] = {title = "Останки морской черепахи", objective = "Отнесите ящик со странными пометками Гвеннид Блай'Леггонд в Аубердин.", description = "Еще одни останки морской черепахи лежат прямо на берегу. К панцирю прикреплена упряжь. Скорее всего, черепаху выгнали на берег неизвестные нам твари; она не выбросилась на берег сама, хотя другие останки и наводят на эту мысль. Теперь останками черепахи завладели мурлоки клана Серой Мглы, питающиеся мертвечиной.\n\nОбследуя упряжь, вы обнаруживаете ящик со странными пометками. Может быть, Гвеннид Блай'Леггонд сможет что-то понять?", progress = "Приятно вновь увидеть вас, Айлерон. Мы прилагаем большие усилия, чтобы узнать, почему же огромные морские существа выбрасываются на пески Темного Берега, но на каждый найденный ответ возникает два новых вопроса.\n\nВы пришли, чтобы снова оказать нам помощь в расследовании?", completion = "Я слышала о такой сбруе, которую вы нашли на черепашьем панцире. Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу. Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Темного Берега.\n\nЯ отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и еще раз спасибо за вашу помощь.", rewards = "Вы получите:\n\n"},
[4726] = {title = "Сущность детеныша дракона", objective = "Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.", description = "Я уже несколько недель изучаю драконов Пылающих степях, и кажется, наконец-то наметился определенный прорыв! Я создала устройство – Драко-инкарцинатор 900. Оно может поймать сущность детеныша дракона!\n\nПо крайней мере, я так думаю.\n\nВозьми это устройство и испытай его на детеныше дракона в Пылающих степях. Пока он будет под воздействием инкарцинатора, одолей его и выпусти из него сущность.\n\nЕсли это сработает, будет замечательно! И принеси мне образцы на изучение!", progress = "Удалось получить сущность детенышей? Мне не терпится изучить ее.\n\nКроме того, моего заказчика лучше не разочаровывать.", completion = "Сработало! Ты добыл сущность драконов! Молодец!\n\nОна мне очень пригодится в ходе экспериментов. Я надеюсь, что однажды придумаю способ ловить живых драконов или хотя бы добывать их яйца. Если ты придумаешь, как это сделать, то мне позавидуют все, кто занимается изучением драконов!\n\nЗаказчик тоже будет доволен. А такого, как он, лучше не огорчать...", rewards = "Вы получите:\n\n"},
[4727] = {title = "Останки морской черепахи", objective = "Отнесите останки морской черепахи Гвеннид Блай'Леггонд в Аубердин.", description = "Скелет морской черепахи лежит на песчаной отмели на севере Темного Берега. Мурлоки клана Серой Мглы либо не нашли ее тушу, либо по каким-то причинам не рискнули приблизиться к ней. В любом случае, от черепахи осталось достаточно, чтобы взять образцы для Гвеннид Блай'Леггонд, проводящей расследование по поручению Храма Луны.", progress = "Приветствую снова, Wrestlecake! Вы нашли еще каких-то выбросившихся на берег тварей, о которых следовало бы узнать Храму Луны?", completion = "Интересно, что мурлоков там не было. Мы будем иметь это в виду, когда начнем изучать эти останки! Благодарю вас за ваши труды, Wrestlecake; Храм Луны уполномочил меня передать вам эти деньги в качестве компенсации за потраченное время.", rewards = "Вы получите:\n\n"},
[4728] = {title = "Останки морской твари", objective = "Отнесите кости морской твари Гвеннид Блай'Леггонд в Аубердин.", description = "Растерзанные останки того, что на вид кажется похожим на гигантское морское млекопитающее, лежат на берегу. Около них валяется тачка и различные инструменты, как будто кто-то раньше уже пытался изучать останки. Хотя мурлоки основательно растащили скелет, останков достаточно, чтобы найти подходящий образец костей для Гвеннид Блай'Леггонд в Аубердине.", progress = "Приветствую вас снова, Цитромон! Что привело вас обратно в Аубердин? Может быть, вы хотите доложить о новой находке?", completion = "О, я уверена, вы обнаружили останки твари, которые уже изучались Лигой Исследователей. Они работают здесь, на Темном Берегу, и упоминали, что изучали одну из выбросившихся на берег тварей, пока их не прогнали мурлоки. Похоже, вам удалось добиться успеха там, где и мы, и они потерпели фиаско. Пожалуйста, примите эту скромную плату от имени Храма Луны.", rewards = "Вы получите:\n\n"},
[4729] = {title = "Редкие звери Киблера", objective = "Отправьтесь на пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру.", description = "Должно быть, тебе интересно, что я здесь делаю? Взгляни на клетки! Разве не ясно?\n\nЯ очень люблю животных, но по роду занятий я торговец. Я разыскиваю и приручаю редких зверей, чтобы богатые и знаменитые клиенты могли сделать их своими питомцами.\n\nТеперь ты, наверное, хочешь спросить: \"Чем я могу тебе помочь, Киблер.\" Отвечаю: возьми эту клетку и поймай несколько щенков-воргов. За это я приручу одного из них и отдам тебе!", progress = "*Киблер яростно спорит с Опусом.*", completion = "Ты вовремя их принес,Стиммакс. Подрасти они еще немного, и их не удалось бы приручить! Дай мне пару минут, и одного из них можешь забирать.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКлетка для ворга"},
[4730] = {title = "Останки морской твари", objective = "Отнесите кости морской твари Гвеннид Блай'Леггонд в Аубердин.", description = "Полуразложившиеся тело твари, похожей на огромное морское млекопитающее, лежит на берегу. Группа мурлоков, более сильных, чем обитающие ближе к Аубердину, обосновалась вокруг погибшего создания. Останков достаточно, чтобы отобрать образцы костей, которые можно отнести Гвеннид Блай'Леггонд.", progress = "Снова приветствую вас, Wrestlecake! Хотите сообщить об очередной находке?", completion = "Кости, которые вы принесли, принадлежат мирным морским млекопитающим, обитающим в водах, окружающих корни Тельдрассила. Им, насколько известно, никогда не было свойственно выбрасываться на берег, как это делают крепкозубы. Хотела бы я знать, почему они так ведут себя. Что ж, может быть, изучение их останков принесет свои плоды, и мы что-то узнаем.\n\nИ снова спасибо вам за помощь. Пожалуйста, примите это вознаграждение от имени Храма Луны.", rewards = "Вы получите:\n\n"},
[4731] = {title = "Останки морской черепахи", objective = "Отнесите ящик со странными пометками Гвеннид Блай'Леггонд в Аубердин.", description = "Еще одни останки морской черепахи лежат у береговой линии. На панцире есть упряжь, которая еще частично держится. Возможно, несчастная тварь не сама выбросилась на берег (что кажется наиболее вероятным по отношению к другим погибшим тварям), а была пригнана к береговой линии неизвестными существами. Могучие мурлоки клана Серой Мглы сделали остов этой твари своим жилищем.\n\nОбследуя упряжь, вы обнаруживаете ящик со странными пометками. Возможно, Гвеннид Блай'Леггонд сумеет что-то разобрать?", progress = "Я вновь приветствую вас, Wrestlecake! Работа, которую вы проделали для Храма Луны, просто великолепна. Порадуете нас снова плодами своих трудов?", completion = "Я слышала о такой сбруе, которую вы нашли на черепашьем панцире. Это, как я понимаю, упряжь наг – они используют такие как в сражениях, так и для перевозок своих припасов на сушу. Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Темного Берега.\n\nЯ отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и еще раз спасибо за вашу помощь.", rewards = "Вы получите:\n\n"},
[4732] = {title = "Останки морской черепахи", objective = "Отнесите останки морской черепахи Гвеннид Блай'Леггонд в Аубердин.", description = "Вы обнаружили тело морской черепахи, выбросившейся на Темный Берег некоторое время назад. Оно почти дочиста объедено мурлоками клана Серой Мглы – теми самыми, что поселились вокруг останков. Однако, похоже, несколько подходящих образцов для Гвиннед Блай'Леггонд вы сможете отобрать.", progress = "Я вновь приветствую вас, Wrestlecake! Вам удалось обнаружить еще что-то, интересное Храму Луны?", completion = "Так вы нашли и других выбросившихся на берег тварей, Wrestlecake? Морские черепахи обычно резвились в водах у подножья Нордрассила – до его гибели. Однако с рождением Тельдрассила этих созданий становится все меньше и меньше. Некоторые, как мы уже знаем, оканчивают свою жизнь здесь – непонятно почему.\n\nБыть может, ваша помощь поможет нам раскрыть эту тайну. Пожалуйста, примите эти деньги за образцы, предоставленные нам для исследований.", rewards = "Вы получите:\n\n"},
[4733] = {title = "Останки морской твари", objective = "Отнесите кости морской твари Гвеннид Блай'Леггонд в Аубердин.", description = "Останки животного, похожего на гигантского крепкозуба, лежат, вынесенные на отмель в скалистой Сумрачной Излучине. Этот крепкозуб в несколько раз больше любого из тех, что обитают в здешних водах. Откуда бы это создание ни приплыло, вряд ли оно родом с Темного Берега.\n\nХотя туша животного уже потеряла целостность, останков достаточно, чтобы найти подходящие образцы для Гвеннид Блай'Леггонд.", progress = "Хвала Элуне – я рада нашей встрече, дорогой Кармаприст. Расследование Храмом Луны феномена выброшенных на берег созданий продолжается. Быть может, вы хотите предложить нам еще что-то интересное?", completion = "Размеры крепкозуба, о котором вы рассказываете, просто ошеломляют. Даже самые старые крепкозубы в этих водах – и то в несколько раз меньше. В то время как крупные крепкозубы, как известно, обитают близ Тельдрассила, их количество постоянно уменьшается. Интересно, связано ли как-то это с выбрасывающимися на берег тварями?\n\nМы продолжим анализ костей, которые вы нам принесли, а это вам вознаграждение от имени Храма Луны. Благодарю вас, Кармаприст.", rewards = "Вы получите:\n\n"},
[4734] = {title = "Заморозка яйца", objective = "Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье.", description = "<имя>, я работаю над созданием нового устройства, яйцехладоскопа! Оно предназначено для того, чтобы направить сгусток холода на яйцо дракона... и заморозить его! Можешь испытать эту штуку?\n\nГоворят, что на пике Черной горы у драконов есть питомник, в котором полно яиц. Подходящее место для испытаний! Заморозь яйцо и расскажи, сработал прибор или нет.\n\nНе беспокойся. Замороженные драконьи яйца совершенно безобидны. А вот остальных надо опасаться!", progress = "Ну как, испытал яйцехладоскоп?", completion = "Сработало? Великолепно! Я так и знала!\n\nПока тебя не было, я создала новую модель яйцехладоскопа. С куда большим радиусом действия.\n\nВозьми его, вдруг случайно забредешь на пик Черной горы.", rewards = "Вы получите:\n\nЯйцехладоскоп"},
[4735] = {title = "Сбор яиц", objective = "Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.", description = "<имя>, я, наконец, готова исследовать настоящие яйца драконов! Возьми это устройство-коллекционер. Он предназначен для захвата драконьего яйца и подготовки его к транспортировке. Возвращайся в Гнездовье и собери при помощи этой штуки несколько яиц.\n\nНе забудь, первым делом их надо заморозить, иначе из них могут вылупиться драконы, не успеешь собрать!\n\nКак только наберешь достаточно яиц, неси их мне!", progress = "Ты несешь мне яйца, Стиммакс? Мой заказчик прослышал, что ты занимаешься их сбором, и очень хочет их получить!", completion = "Ух ты! Яйца! Значит, устройство-коллекционер сработало! Я гений!\n\nСпасибо, Стиммакс. Мой заказчик очень порадуется яйцам...", rewards = "Вы получите:\n\n"},
[4736] = {title = "Поиски Менары Расщепительницы Бездны", objective = "Поговорите с Менарой Расщепительницей Бездны в Степях.", description = "А, привет, <имя>. Твое обучение идет неплохо. Настолько неплохо, что, я думаю, пришло время вознаградить тебя за прилежание – и за то, что сила магии все еще не поработила тебя.\n\nЕсли тебя заинтересовали мои слова, поговори с Менарой Расщепительницей Бездны из Кабестана. В настоящий момент она живет в башне Страхада Фарсана, построенной на утесе над городом.\n\nОна не очень доброжелательно настроена, поэтому похвалы от нее не жди. Но если ты будешь стараться, твои усилия не пропадут втуне.", progress = nil, completion = "А, тебя прислал Остротерн. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.\n\nНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.\n\nВижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.", rewards = "Вы получите:\n\n"},
[4737] = {title = "Поиски Менары Расщепительницы Бездны", objective = "Поговорите с Менарой Расщепительницей Бездны в Степях.", description = "Ха! Я вижу, ты стремишься к могуществу. Не сомневаюсь, рано или поздно ты падешь жертвой соблазна и жажды магии.\n\nПфа! Ты <глуп/глупа>! Время покажет, что я был прав, – ничто другое, одно лишь время…\n\nНо мне кажется, что не все согласны с Зевростом. Менара готова создать предметы, которые помогут тебе обрести могущество и обуздать собственную силу. Если хочешь, ступай в Кабестан. Она живет в башне над городом.", progress = nil, completion = "А, тебя прислал Зеврост. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.\n\nНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.\n\nВижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.", rewards = "Вы получите:\n\n"},
[4738] = {title = "Поиски Менары Расщепительницы Бездны", objective = "Поговорите с Менарой Расщепительницей Бездны в Степях.", description = "Пойми одно, <имя>: я считаю, что ты не <готов/готова> к такой ответственности. Я уверена, что вовлекать новичков в создание любых предметов силы, тем более, непроверенных, недопустимо.\n\nНо решать не мне, а сильным мира сего, которые хотят наделить тебя такими дарами.\n\nЕсли ты хочешь узнать побольше, советую поговорить с Менарой Расщепительницей Бездны из Кабестана. Обычно ее можно найти в башне над портом.", progress = nil, completion = "А, тебя прислала Демизетта. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.\n\nНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.\n\nВижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.", rewards = "Вы получите:\n\n"},
[4739] = {title = "Поиски Менары Расщепительницы Бездны", objective = "Поговорите с Менарой Расщепительницей Бездны в Степях.", description = "<класс>! Да, ты!\n\nВижу, ты не полностью <экипирован/экипирована>, хотя уверенности и <поднабрался/поднабралась>. Да-да, теперь я это понимаю.\n\nМенара Расщепительница Бездны научит тебя нескольким вещам. Она немало времени посвящает обучению молодежи тайным искусствам. Тем, кто проходит ее испытания, она даже дает дары.\n\nЕсли хочешь поучиться, ступай в город Кабестан в Степях. Она живет над городом в башне Страхада.", progress = nil, completion = "А, тебя прислал Каэл. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.\n\nНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.\n\nВижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.", rewards = "Вы получите:\n\n"},
[4740] = {title = "РАЗЫСКИВАЕТСЯ: Глубомрак!", objective = "Найдите и убейте мурлока, известного как Глубомрак. Предполагается, что это существо охраняет и защищает хижины мурлоков в поселении к югу от Аубердина, у воды.\n\nО смерти Глубомрака доложите часовому Глинде Нал'Шии в Аубердине.", description = "Внимание!\n\nНазначена награда за голову мурлока, именуемого \"Глубомрак\". Эта злобная тварь повинна в смерти как минимум одного часового и подозревается в потоплении как минимум двух грузовых судов в прибрежных водах Темного Берега!\n\nГлубомрака в последний раз видели в поселении мурлоков к югу от Аубердина, и, судя по всему, он охраняет хижины своих сородичей. Награда за голову Глубомрака ждет смельчака у часового Глинды Нал'Шии в Аубердине.\n\nСовет Аубердина", progress = nil, completion = "Что ж, похоже, вы здесь не только затем, чтобы просто узнать! Жители Аубердина будут счастливы известию, что сегодня они смогут спать немного спокойнее.\n\nСегодня вы послужили для наших жителей орудием справедливости, Wrestlecake. И за это я хотела бы предложить вам вот это в качестве награды, подходящей... для настоящего героя народа Аубердина.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛесные боевые наручиНаручи гребнеспинаРемень волнолома\n\nВы также получите:\n\n"},
[4741] = {title = "Одичавшие стражи", objective = "Убейте для Трулла Баловня Судьбы из Оскверненного леса 13 лунных совухов.", description = "В северных областях Зимних Ключей дикие совухи совсем озверели. Необходимо положить этому конец!\n\nОтправляйся на охоту, а заодно исследуешь местность, где они обитают.\n\nМеста там дикие, но ты справишься. Возвращайся, когда убъешь 13 диких совухов.", progress = "Только не говори мне, что струсил, отправляйся!", completion = "Сдается мне, тебе нравится эта работенка. Думаю, мы стараемся не напрасно.", rewards = "Вы получите:\n\n"},
[4742] = {title = "Печать Вознесения", objective = "Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения.\n\nКамни могут быть у трех генералов: у воеводы Вуна из клана Тлеющего Терновника, у вождя Омокка из клана Черной Вершины и у повелителя Змейталака из клана Кровавого Топора.", description = "Видишь, в этой печати есть три простых углубления. В них надо вставить три камня власти; после этого властитель Змейталак, владыка нижней крепости, должен будет закалить печать в пламени черных драконов.\n\nНайди эти камни! И помни, <смертный/смертная>: шансы, что у кого-то из трех генералов нижней крепости будет при себе нужный нам камень, невелики. Не отступайся! Ищи, будь <внимателен/внимательна> и не теряй решимости!", progress = "Мужество и терпение – залог успеха, смертный!", completion = "*Образ Ваелана на миг расплывается мутным пятном.*\n\n*Камни, которые вы принесли, исчезли.*\n\nТеперь все готово к тому, чтобы печать вознесения обрела свою силу. Пора приступать к завершающему этапу.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4743] = {title = "Печать Вознесения", objective = "Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю.\n\nКак только воля великого зверя ослабнет, надо немедленно положить перед ним заготовку печати Вознесения и воспользоваться сферой Энергии дракона, чтобы подчинить себе его разум и направить его пламя на заготовку.", description = "Очень немногие черные драконы из верхней крепости способны закалить печать в пламени своего дыхания. Змейталак – один из них, но его волю сломить невозможно.\n\nТебе надо добраться до Драконьих топей в Пылевых топях. Там ты найдешь древнего дракона, известного под именем Огнебор. Ты <должен/должна> сломить его волю, <имя>. И когда он ослабнет, тебе нужно будет воспользоваться этой сферой. Но помни, <смертный/смертная>: его разум силен, и ты сможешь удерживать его под контролем не более нескольких секунд. За эти секунды тебе нужно успеть закалить печать.", progress = "Не теряй времени, смертный. Нефариан уже завершает последние приготовления. Если мы не остановим его сейчас, он обрушит на мир свою злобу.", completion = "Стой спокойно. Я наложу последнее защитное заклинание.\n\n*Глаза Ваелана превращаются в два огненных шара.*\n\nТеперь печать Вознесения обрела свою полную силу...\n\nЯ вложил в артефакт очень мощные защитные чары. В минуту предельного отчаяния, когда тебе покажется, что все потеряно, призови силу красных драконов и используй ее для защиты.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nПечать вознесения"},
[4761] = {title = "Тандрис Ветропряд", objective = "Поговорите с Тандрисом Ветропрядом в Аубердине.", description = "При разведке в лагере фурболгов вы обнаружили информацию, которую нужно довести до сведения Тандриса Ветропряда. Он любезно согласился исполнять обязанности старейшины в Аубердине, мудростью своей направляя повседневную жизнь деревни. Прошу вас поделиться с ним вашими находками в деле фурболгов.\n\nЯ уверен, что у него есть свои идеи по поводу источника наведенной на них порчи. Может быть, вы сможете вместе с ним выработать план восстановления природного равновесия!", progress = nil, completion = "Рад нашей встрече, |3-6(Охотник). Ваше расследование ситуации с фурболгами как нельзя кстати. Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящихся к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведенной на сами леса. Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена.", rewards = "Вы получите:\n\n"},
[4762] = {title = "Река Скалистая", objective = "Отправляйтесь на север от Аубердина, к первому водопаду вверх по реке Скалистой, и там возьмите пробу.\n\nС пробой воды Скалистой реки возвращайтесь в Аубердин к Тандрису Ветропряду.", description = "Воды реки Скалистой исполнились злобы и порчи. Река впадает в Туманный предел, и я боюсь, что скоро беда затронет и Аубердин. Я подозреваю, что в загрязнении повинны фурболги Чернолесья, живущие в верховьях реки, но я также полагаю, что они не являются подлинной причиной этой порчи.\n\nВозьмите эту пробирку и отправляйтесь к устью реки, что к северу отсюда. Идите вверх по реке до первого водопада и там возьмите пробу воды. Ориентиром вам послужит высокий мост через реку. Когда возьмете пробу, вернитесь ко мне в Аубердин.", progress = "Загрязнение реки Скалистой – лишь первое проявление тревожной тенденции здесь, на Темных берегах. Проба, которую вы добудете, поможет нам составить план... как я начинаю подозревать, план атаки.", completion = "Я не удивлен тем, насколько сильно отравлена эта вода, но поглядите, какой мерзостной она становится! Похоже, что нужно действовать как можно скорее, да, Wrestlecake? К востоку от нас находится Оскверненный лес; это и есть настоящий источник порчи, я в прошлом такой уже видел. Заранее могу сказать, что ваша проба подтвердит это. Наверное, мы могли бы найти средство для исцеления, но нам понадобится помощь, даже чтобы попытаться это сделать. Когда придет время, я надеюсь, Wrestlecake, вы сможете нам ее предоставить.", rewards = "Вы получите:\n\n"},
[4763] = {title = "Порабощенные фурболги Чернолесья", objective = "Наполните пустую чашу очищения из лунного колодца Аубердина.\n\nСоберите образцы фруктов, орехов и зерна в расположенных на севере лагерях фурболгов.\n\nСмешайте все в чаше и поместите ее возле ближайшего к реке Скалистой большого костра в северном лагере, вызвав таким образом сатира.\n\nСнимите с него талисман порчи и принесите его Тандрису Ветропряду в Аубердин.", description = "Мы узнали, что источником порчи, наведенной на фурболгов, являются сатиры. Они держат своих жертв в повиновении с помощью талисманов, через которые направляют магию. Если для фурболгов еще есть шансы на спасение, мы должны выманить сатиров-поработителей и отнять у них талисманы!\n\nНаполни эту чашу из нашего лунного колодца и стащи образцы пищи фурболгов из их северного лагеря. Смешай все и поставь чашу возле большого костра у реки; любой фурболг, поевший из этой чаши, на некоторое время очистится, что привлечет внимание сатира... которого нужно убить!", progress = "Талисман порчи – это жуткое приспособление, которое служит для нарушения природного баланса. Когда вы найдете этот предмет среди того, чем сатир мучает фурболгов, и принесете его мне для уничтожения, можно будет считать, что мы одержали великую победу!", completion = "Мы только начали войну за освобождение наших лесов от порабощающих сил порчи, но сегодняшняя битва выиграна! Wrestlecake, народ Аубердина в огромном и почти неоплатном долгу перед вами. Прошу вас принять это вместе с нашей благодарностью. То, что мы узнали сегодня, может в один прекрасный день навсегда освободить наших друзей-фурболгов от мучительных оков.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛуннокаменный жезлПоножи Хранителя ЧащобыНабедренники Ливнебури\n\nВы также получите:\n\n"},
[4764] = {title = "Пряжка Роковой оснастки", objective = "Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи.", description = "Высоко в горах, на пике Черной горы, есть чертог, который некогда звался Залом Сокровищ. Именно там дворфы Черного Железа хранили свои реликвии, трофеи и предметы искусства.\n\nЭто было давно. Говорят, что зал обрушился, и теперь используется... менее достойно. Но я думаю, что там остались дворфийские реликвии.\n\nОдна из них – пряжка Роковой оснастки. Ее поверхность так плотно инкрустирована редкими самоцветами, что любой дворф начинает плакать от одного ее вида.\n\nИменно эта пряжка и станет твоей целью, <имя>.", progress = "Ты принес пряжку, Принтскрин? Мой клиент готов хорошо за нее заплатить.", completion = "Ты нашел ее! Значит, слухи оказались правдой!\n\nСпасибо, Принтскрин. Мой клиент, граф Ремингтон Риджвелл, с радостью поместит ее в свою коллекцию.", rewards = "Вы получите:\n\n"},
[4765] = {title = "Доставить Риджвеллу", objective = "Отнесите ящик Риджвелла Ремингтону Риджвеллу в Штормград.", description = "Я упаковала пряжку Роковой оснастки в ящик для отправки в Штормград. <имя>, ты мне очень <помог/помогла>, но я хочу попросить еще об одной услуге.\n\nДоставь этот ящик графу Ремингтону Риджвеллу. Он в Крепости Ветров. Не сомневаюсь, он обрадуется.", progress = "Мне доложили о прибытии вестника. Вестника с даром с пика Черной горы.\n\nЭто ты?", completion = "А, так это ты! Спасибо, Мяуыч. И... если ты еще не знаешь об этом... благодарность дома Риджвеллов стоит королевской.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБыстроступные ботфортыБоевые наручи мгновенного удара\n\nВы также получите:\n\n"},
[4766] = {title = "Майра Светлое Крыло", objective = "Поговорите с Майрой в Пылающих степях.", description = "Мой агент, Майра, отправилась в Пылающие степи, чтобы обыскать развалины города Тауриссана. В разрушенном обиталище дворфов Черного Железа таится множество ценных вещей... которые украсят наш семейный музей.\n\nМайара говорит, что кое-что нашла, но ей нужна помощь. Правда, это находится не в Тауриссане. Вместо этого требуется устроить вылазку на пик Черной горы.\n\nПодробности мне неизвестны, но если тебя заинтересовало мое предложение, поговори с Майрой в Пылающих степях.", progress = nil, completion = "Ты из Штормграда? Чудесно – я знаю об одном предмете искусства, который Ремингтон любой ценой захочет заполучить в свой музей. Но это будет нелегко.\n\nТут-то ты и понадобишься.", rewards = "Вы получите:\n\n"},
[4767] = {title = "Ветрокрыл", objective = "Соберите в Скальном гнездовье 10 яиц виверн и отнесите их Элу на Заставу Вольного Ветра.", description = "Мне велели набрать новых виверн, чтобы выдрессировать их и использовать в качестве ездовых животных. Их поголовье постоянно растет, и я надеюсь, что когда-нибудь сам смогу стать воздушным всадником. Однако виверны пользуются большим спросом, и нам их постоянно не хватает. Может быть, вы, <имя>, сможете мне помочь?\n\nЯ хочу попросить вас отправиться в Скальное гнездовье и набрать с кладок виверн немного яиц. Отсюда ступайте на северо-запад, держитесь поближе к стене каньона – и увидите дорогу, ведущую наверх. Но будьте очень осторожны: виверны не любят чужаков, а уж за свои кладки они будут готовы разорвать кого угодно.", progress = "Атеистфрост, вы набрали для меня яиц виверн? Мне не терпится начать дрессировку моих новых ветрокрылов!", completion = "Отлично! Детеныши из этих яиц помогут мне осуществить задуманное! Возьмите это в знак моей признательности, пусть вам всегда везет на любой охоте, |3-6(Маг).", rewards = "Вы получите:\n\nНакладки из толстой кожи"},
[4768] = {title = "Табличка Темнокамня", objective = "Принесите табличку Темного Камня тенемагу Вивиан Лаграв в Каргат.", description = "Табличка Темного Камня – это записки покойного дворфа Урхельда Темного Камня. Он был величайшим алхимиком древности, но современники считали его сумасшедшим и не придавали значения его изысканиям.\n\nИзвестно, что он записал результаты своих трудов. Вырезал их на табличках. И у меня есть основания предполагать, что одна из этих табличек хранится в Пике Черной горы, в зале, который когда-то назывался залом Удачи. Как его называют сейчас, я не знаю, ибо многие уходили в Черную Скалу, но немногие вернулись назад.\n\nЕсли тебя не пугают опасности Пика Черной горы, принеси мне табличку, и я щедро тебя награжу.", progress = "Тебе удалось разыскать табличку, Стиммакс? Мне не терпится приступить к изучению ее секретов.", completion = "Превосходно. Для того чтобы разобраться со всеми формулами, мне потребуется не один день, но я уверена, что результат будет стоить затраченного труда.\n\nСпасибо, Стиммакс. Ты оказал нам поистине неоценимую услугу.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБыстроступные ботфортыБоевые наручи мгновенного удара\n\nВы также получите:\n\n"},
[4769] = {title = "Вивиан Лягроб и табличка Темнокамня", objective = "Переговорите с темным магом Вивианой Лягроб.", description = "Вивиан Лаграв прислала мне весть из Каргата, что в Бесплодных землях. Она выяснила, что в Пике Черной горы хранится один древний текст, который может помочь нам в изысканиях. Однако это всего лишь догадка, требующая подтверждения. Нужно, чтобы кто-то добыл этот текст из Пика. Но сразу скажу: это будет непросто.\n\nЕсли возьмешься за эту работу, обратись к Вивиан в Каргат.", progress = nil, completion = "Верно. У меня есть основания предполагать, что в Пике Черной горы хранится табличка, на которой записаны древние алхимические рецептуры. Я рада, что ты обратился ко мне, ибо мне нужна помощь. Я должна получить эту табличку.\n\nСадись и устраивайся поудобнее, я сейчас объясню, что к чему.", rewards = "Вы получите:\n\n"},
[4770] = {title = "Путь домой", objective = "Выведите Паоку Ходячую Гору из Скального гнездовья, а потом поговорите с Мотегой Огненной Гривой на заставе Белого Плеса.", description = "Пожалуйста, <класс>, помогите мне! Я уже несколько дней прячусь в этом Скальном гнездовье, и за это время не встретил ни одного знакомого лица! Я пришел сюда изучать виверн и, похоже, немного переборщил – пришлось спасаться от них бегством, вот тогда-то я и заблудился.\n\nМне срочно нужно вернуться на заставу Белого Плеса! Мотега не знает, что я потерялся, а когда узнает, что я полез в Скальное гнездовье один, он мне голову оторвет!\n\nЗастава прямо к востоку отсюда... пожалуйста, проводите меня туда!", progress = nil, completion = "Что?! Да если б я знал, что Паока Ходячая Гора полезет в Скальное гнездовье, я бы цепями приковал его к тотему! Его отец был против того, чтобы он ехал со мной в Тысячу Игл. Мы собирались изучать различных животных, населяющих эти прекрасные земли.\n\nЯ очень признателен вам за то, что вы помогли Паоке. Надеюсь, это покроет все ваши затраты.", rewards = "Вы получите:\n\n"},
[4771] = {title = "Рассветный гамбит", objective = "Отнесите \"Рассветный гамбит\" в Демонстрационную комнату в Некроситете. Уничтожьте Вектуса и возвращайтесь к Бетине Биггльцинк.", description = "Я поместила \"Рассветный гамбит\" в ящик, в котором были драконьи яйца. Ты <должен/должна> отнести его в самую глубину Некроситета.\n\nВектус, маг из нежити, руководит группой студентов Плети. Доставь \"Рассветный гамбит\" в комнату, которую они называют смотровой. Если все пойдет как надо, устройство уничтожит всю нежить, находящуюся в этот момент в комнате.\n\nПосле этого уничтожить Вектуса будет проще пареной репы. Так ведь?", progress = nil, completion = "Какое счастье! Вектус уничтожен! А \"Рассветный гамбит\", он сработал? \n\nВ самом деле? Ну... я, в общем-то, не сильно и надеялась... В общем, я рада, что ты справился, Кастрол. \n\nСеребряный Рассвет, да и весь Азерот у тебя в долгу.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВетрожнецТанцующее серебро\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4781] = {title = "Материалы для зачарованной золотой кроводежды", objective = "Отнесите слиток золота Зиску Ладноскрою в Тернистую долину.", description = "Следующее задание не сложнее первого, но тебе все равно потребуется помощь.\n\nДля вышивки мне нужна золотая нить, но ее не так просто найти, и мало кто знает, как ее делать. К счастью, этот секрет ведом одному из тех, кто верен нашему делу и старается помогать тем, кто стремится пополнить наши ряды.\n\nОтнеси золотой слиток Зиску Ладноскрою в Пиратскую бухту. Он отличный портной и с радостью спрядет для тебя нить. Золотые слитки могут изготавливать опытные горняки. Обратись к ним.", progress = "Да-да, золотые слитки. Принеси мне слиток, и тогда поговорим про нить. А пока я советую сосредоточиться на обучении. Самые суровые испытания еще впереди. Поверь, сколько ты ни занимайся, сколько ни копи силу, ее все равно будет не хватать.", completion = "Великолепно. Я рад, что ты сумел так быстро заручиться помощью горняка. Или ты сам справился? Так или иначе, молодчина. Нить из этого слитка выйдет превосходная.\n\nНа ее изготовление понадобится время, поэтому возвращайся немного позже – честно говоря, я послал слиток одной принцессе, запертой в башне, которая только и делает, что прядет золотые нити... нет, честно. Я не шучу... ладно, шучу.", rewards = "Вы получите:\n\n"},
[4782] = {title = "Материалы для зачарованной золотой кроводежды", objective = "Возвращайтесь к Менаре Расщепительнице Бездны в Степи.", description = "Возвращайся к Менаре и скажи ей, что работа предстоит долгая, но я постараюсь ради нее... и ради тебя. Передай ей, что пока ты собираешь остальные материалы, я закончу делать нить. Тогда ты придешь и заберешь ее.\n\nУдачи, <имя>. Ах, да, передай привет Страхаду, раз уж будешь рядом. Старый болван... как его угораздило построить башню рядом с Кабестаном?", progress = nil, completion = "Отлично, вот и ты, Эверек. А где же нитка?\n\nА, ясно. Понятно. Гоблин и его брат ни разу нас не подводили – думаю, вполне понятно, что он не смог сделать ее сразу. Да будет так... Тем временем мы займемся другими материалами.\n\nТы готов?", rewards = "Вы получите:\n\n"},
[4783] = {title = "Материалы для зачарованной золотой кроводежды", objective = "Принесите 10 фиалов крови сатира из племени Ярой Ненависти и 1 простой камень Преисподней в Степи, Менаре Менара Расщепительнице Бездны.", description = "Следующие материалы можно найти в Пустошах, далеко на западе от Степей, за Когтистыми горами.\n\nТам все еще царит хаос со времен Раскола. Это место, где предстоит серьезное испытание твоей силе и хитрости – там бродят омерзительные твари и приспешники Пылающего Легиона.\n\nПринеси мне кровь сатиров племени Ярой Ненависти и простой камень Преисподней от младших инферналов Поля Маннорок.\n\nИ то, и другое понадобится для создания одеяния.", progress = "Пустоши – опасное место: наги, гиганты, сатиры, Пылающий Легион... И вдобавок ко всему еще и воинственные кентавры.\n\nЯ уже говорил, что это подвергнет испытанию не только твою силу и ловкость, но и терпение. Не теряй бдительности, Ариакан.", completion = "Великолепно, Ариакан. Отличные материалы. Я пока подготовлю их, а тебе дам другое задание: принести два оставшихся ингредиента. Готов?", rewards = "Вы получите:\n\n"},
[4784] = {title = "Материалы для зачарованной золотой кроводежды", objective = "Принесите Менаре Расщепительнице Бездны в Степи нить из чистого золота, 2 тлеющих угля и осколок души.", description = "Осталось отыскать три составляющих, <имя>, и твое одеяние будет готово.\n\nВо-первых, нить из чистого золота, которую делает Зиск. Отправляйся к нему в Пиратскую бухту и принеси нить.\n\nВо-вторых, нужны тлеющие угли элементалей огня с нагорья Арати. Если я правильно помню, духов можно найти в западной части нагорья, рядом со стеной Торадина.\n\nИ, наконец, мне нужен осколок души, созданный тобой.\n\nСобрав все составляющие, возвращайся в башню, и я закончу работу над одеянием.", progress = "Осталось недолго, Ариакан, честное слово. Одеяние неплохо послужит тебе и даст преимущество над противниками.", completion = "Великолепно, Ариакан! Все материалы у меня есть, можно приступать.\n\nДумаю, ты будешь доволен.", rewards = "Вы получите:\n\n"},
[4785] = {title = "Нить из чистого золота", objective = "Вот, бери. И пожалуйста, передай от нас привет Менаре.\n\nМы ждем от тебя великих свершений. Быть может, когда Легион падет на колени, прозвучит твое имя и хвала твоей силе. Жду не дождусь!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nНить из чистого золота"},
[4786] = {title = "Завершенное одеяние", objective = "Дождитесь, пока Менара Расщепительница Бездны закончит работу над вашим одеянием, и еще раз поговорите с ней.", description = "А теперь я завершу работу над одеянием. Это займет немного времени. Не уходи далеко.", progress = nil, completion = "Готово. Прими это одеяние и носи его с честью.\n\nТы хорошо поработал, и я предвижу, что тебя ждут великие дела. Помни: чтобы справиться с искушением скверны, которое подстерегает каждого, ступившего на путь магии, понадобится сильная воля и немалая стойкость. Пока ты не лишился воли, тебя ждут великие успехи.", rewards = "Вы получите:\n\nЗачарованная золотая кроводежда"},
[4787] = {title = "Древнее яйцо", objective = "Принесите древнее яйцо Йе'кинье в Танарис.", description = "В пророчестве Мошару говорится о древнем яйце. Это реликвия тех времен, когда тролли правили громадными империями, и в нем заключена сила, которая сможет сдержать сущность Хаккара. Пожалуй, это единственный способ избавить наш мир от зла.\n\nПринеси мне древнее яйцо, <имя>. Говорят, оно спрятано в Джинта'Алоре, что во Внутренних землях, в пещере за амфитеатром в верхней части города.", progress = "Ты несешь древнее яйцо? Я чувствую, как просыпаются великие силы. Боюсь, время у нас на исходе.", completion = "А, ты добыл яйцо! Низкий тебе поклон, Нигилум. Твоя сила и храбрость будут воспеты в веках.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4788] = {title = "Последние таблички", objective = "Принесите пятую и шестую таблички Мошару геологу Железному Башмаку в Танарисе.", description = "Пока я изучаю третью и четвертую таблички Мошару, отыщи пятую и шестую! Это будет нелегко, потому что они в руках троллей из клана Тлеющего Терновника на пике Черной горы. Этот пик – огненная гора между Пылающими степями и Тлеющим ущельем.\n\nУдачи, <имя>. Она тебе понадобится.", progress = "Ты уже добрался до Черной Скалы? Пятая и шестая таблички у тебя?", completion = "Невероятно! Ты их нашел! Ты настоящий герой, Шэдоустайл!\n\nИ это очень удачно, потому что судя по предыдущим табличкам... без героя нам не обойдтись. Грядет такое...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4801] = {title = "Э'ко ледопардов", objective = "В Зимних Ключах тебе биться предстоит с огромными кошками, ледопардами. Эти звери жутко быстрые и ловкие. Если хочешь обрести скорость ледопарда принеси э‘ко, что найдешь у них.\n\nИ не забудь, что сокровище Мау'ари с собой нужно носить, если хочешь э‘ко добыть.", description = nil, progress = "В Зимних Ключах тебе биться предстоит с огромными кошками, ледопардами. Эти звери жутко быстрые и ловкие. Если хочешь обрести скорость ледопарда принеси э‘ко, что найдешь у них.\n\nИ не забудь, что сокровище Мау'ари с собой нужно носить, если хочешь э‘ко добыть.", completion = "Да, Грагхар, Мау'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках.", rewards = "Вы получите:\n\nБеспокойство джуджу"},
[4802] = {title = "Э'ко фурболгов племени Зимней Спячки", objective = "В Зимних Ключах тебе придется сражаться со свихнувшимися существами – фурболгами племени Зимней Спячки. По воле своего вождя они обрели невероятную силу. Если и ты хочешь получить силу этого племени, принеси мне э‘ко, что найдешь у них.\n\nИ не забудь, что сокровище Мау'ари с собой нужно носить, если хочешь камень Э‘ко добыть.", description = nil, progress = "В Зимних Ключах тебе придется сражаться со свихнувшимися существами – фурболгами племени Зимней Спячки. По воле своего вождя они обрели невероятную силу. Если и ты хочешь получить силу этого племени, принеси мне э‘ко, что найдешь у них.\n\nИ не забудь, что сокровище Мау'ари с собой нужно носить, если хочешь камень Э‘ко добыть.", completion = "Да, Гуреус, Мау'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках.", rewards = "Вы получите:\n\nСила джуджу"},
[4803] = {title = "Э'ко щербозубов", objective = "В Зимних Ключах тебе встретятся большие медведи с очень толстой шкурой. Это медведи-щербозубы. Судя по тому, что они способны выдержать – отлично защищены. Если хочешь получить сопротивляемость огню, принеси мне э‘ко, что найдешь у них.\n\nИ не забудь, что сокровище Мау'ари с собой нужно носить, если хочешь э‘ко добыть.", description = nil, progress = "В Зимних Ключах тебе встретятся большие медведи с очень толстой шкурой. Это медведи-щербозубы. Судя по тому, что они способны выдержать – отлично защищены. Если хочешь получить сопротивляемость огню, принеси мне э‘ко, что найдешь у них.\n\nИ не забудь, что сокровище Мау'ари с собой нужно носить, если хочешь э‘ко добыть.", completion = "Да, Бурн, Мау'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках.", rewards = "Вы получите:\n\nЖар джуджу"},
[4804] = {title = "Э'ко стылодыхов", objective = "В Зимних Ключах тебе предстоит биться с тварями, которые зовутся химеры-стылодыхами. Эти существа владеют мощной магией холода. Если хочешь обрести способность противостоять этой магии, принеси мне э'ко, что найдешь у них.\n\nИ не забудь, что сокровище Мау'ари с собой нужно носить, если хочешь э‘ко добыть.", description = nil, progress = "В Зимних Ключах тебе предстоит биться с тварями, которые зовутся химеры-стылодыхами. Эти существа владеют мощной магией холода. Если хочешь обрести способность противостоять этой магии, принеси мне э'ко, что найдешь у них.\n\nИ не забудь, что сокровище Мау'ари с собой нужно носить, если хочешь э‘ко добыть.", completion = "Да, Вилдан, Мау'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках.", rewards = "Вы получите:\n\nХолод джуджу"},
[4805] = {title = "Э'ко йети", objective = "В Зимних Ключах тебе предстоит биться с тварями, которые зовутся йети с холмов Ледополоха. Они неповоротливы, но их толстая шкура выдерживает любые удары. Если хочешь обрести эту способность, принеси мне э'ко, что найдешь у них.\n\nИ не забудь, что сокровище Мау'ари с собой нужно носить, если хочешь э'ко добыть.", description = nil, progress = "В Зимних Ключах тебе предстоит биться с тварями, которые зовутся йети с холмов Ледополоха. Они неповоротливы, но их толстая шкура выдерживает любые удары. Если хочешь обрести эту способность, принеси мне э'ко, что найдешь у них.\n\nИ не забудь, что сокровище Мау'ари с собой нужно носить, если хочешь э'ко добыть.", completion = "Да, Мард, Мау'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках.", rewards = "Вы получите:\n\nПобег джуджу"},
[4806] = {title = "Э'ко великанов", objective = "В Зимних Ключах тебе предстоит биться с великанами ледяного молота. Они сильны и яростны. Если хочешь обрести их силу, принеси мне э‘ко, что найдешь у них.\n\nИ не забудь, что сокровище Мау'ари с собой нужно носить, если хочешь э‘ко добыть.", description = nil, progress = "В Зимних Ключах тебе предстоит биться с великанами ледяного молота. Они сильны и яростны. Если хочешь обрести их силу, принеси мне э‘ко, что найдешь у них.\n\nИ не забудь, что сокровище Мау'ари с собой нужно носить, если хочешь э‘ко добыть.", completion = "Да, Борро, Мау'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках.", rewards = "Вы получите:\n\nМощь джуджу"},
[4807] = {title = "Э'ко диких совухов", objective = "В Зимних Ключах тебе предстоит сражаться с существами, обладающими врожденной способностью к магии. Сильная магия у этих диких совухов, да, сильная... Если хочешь обрести их магию и использовать в своих целях, принеси мне э'ко, что найдешь у них.\n\nИ не забудь, что с собой нужно носить сокровище Мау'ари, если хочешь э‘ко добыть.", description = nil, progress = "В Зимних Ключах тебе предстоит сражаться с существами, обладающими врожденной способностью к магии. Сильная магия у этих диких совухов, да, сильная... Если хочешь обрести их магию и использовать в своих целях, принеси мне э'ко, что найдешь у них.\n\nИ не забудь, что с собой нужно носить сокровище Мау'ари, если хочешь э‘ко добыть.", completion = "Да, Церезит, Мау'ари может добыть джуджу для тебя… Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках.", rewards = "Вы получите:\n\nКоварство джуджу"},
[4808] = {title = "Фелнок Сталлист", objective = "Отнесите письмо Тинки Фелноку Сталлисту.", description = "Мне придется попросить тебя еще об одной услуге.\n\nВ результате исследования добытых тобой сущностей, я поняла, как можно заморозить яйца драконов и сохранить их! Мне нужно испытать собственную теорию, но первым делом понадобятся кое-какие приспособления. Мой коллега, Фелнок Сталлист, умеет их делать.\n\nОтнеси это письмо Фелноку и объясни ему, что мне нужно. Фелнок живет в городе Круговзоре, в Зимних Ключах.", progress = "Как здесь холодно! Надеюсь, ты принес мне одеяло!", completion = "Это не одеяло! Что это? Письмо от Тинки? И что она пишет?..\n\nА, она занимается исследованиями в Пылающих степях. В этом есть смысл – драконов там полно. Смотри-ка, ей нужны кое-какие детали для создания одного устройства. Вот зачем я ей понадобился, а?", rewards = "Вы получите:\n\n"},
[4809] = {title = "Рога стылодыхов", objective = "Принесите 8 безупречных рогов стылодыха Фелноку Сталлисту.", description = "У меня есть почти все, что нужно Тинки, не хватает только одного важного компонента – рогов стылодыхов. Рога этих химер – великолепный источник стужи, но годятся только безупречные рога без единой трещинки! Чтобы выполнить заказ Тинки мне нужно несколько таких рогов.\n\nДобудь их, и я соберу посылку для Тинки.", progress = "Ты несешь мне рога стылодыхов, Томпсон?", completion = "Отличные рога. Прямо средоточие холода! Дай-ка я надену перчатки и упакую их вместе с остальным заказом Тинки...", rewards = "Вы получите:\n\n"},
[4810] = {title = "Возвращение к Тинки", objective = "Отнесите ящик Фелнока Тинки Кипеллер в Пылающие степи.", description = "Ну вот, все готово и запаковано! Доброго пути, не забудь передать Тинки, что она мой должник!", progress = "Томпсон! Ты поговорил с Фелноком? Ты принес, то что я просила?", completion = "Принес! Ура! Я немедленно примусь за работу! Огромное спасибо, Томпсон!\n\nТы очень мне помог, может быть я снова прибегну к твоей помощи...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМолниеносный колунМогильный скипетр\n\nВы также получите:\n\n"},
[4811] = {title = "Красный кристалл", objective = "Направляйтесь на восток от Аубердина и поищите большой красный кристалл в горной гряде на востоке Темного Берега. Вернитесь с докладом к часовому Глинде Нал'Шие в Аубердин.", description = "К востоку отсюда становится все больше враждебно настроенных лунных совухов. Когда-то их считали милыми и спокойными, почти мистическими созданиями. В то время как кое-кто продолжает почитать их, тревога о безопасности Аубердина вынуждает меня смотреть на вещи более реалистично.\n\nЯ получила сообщения, что лунных совухов привлекает большой красный кристалл, находящийся в горной гряде на востоке Темного Берега. Никто не только не знает, что это за кристалл, но есть ли он на самом деле. Я хочу, чтобы вы установили его местонахождение и доложили мне о том, что обнаружите.", progress = nil, completion = "Так значит, кристалл существует, Wrestlecake? Как интересно... В любом случае, вы хорошо справились с заданием; отличная работа!\n\nА какова же природа этого кристалла? Это лишь один вопрос в целом море вопросов... На ум мне приходит и другой: почему лунных совухов тянет к кристаллу? Он безвреден, или же таит в себе зло?\n\nУ меня еще много вопросов, но нам придется пристально изучить кристалл, чтобы добиться хоть каких-то ответов.", rewards = "Вы получите:\n\n"},
[4812] = {title = "Пока струится вода...", objective = "Наполните пустую колбу для воды в лунном колодце Аубердина, а затем исследуйте красный кристалл, находящийся в горной гряде на востоке Темного Берега.", description = "Возьмите этот пустой флакон и наполните его водой из лунного колодца в Аубердине. Ее могучая магия должна помочь нам разгадать структуру кристалла. Чтобы это сделать, просто облейте кристалл, а остальное должно произойти само собой.\n\nХотя я не думаю, чтобы вам что-то угрожало, я все же попрошу вас быть осторожнее. За горами на востоке находится Оскверненный лес, и если этот кристал как-то связан с тем местом (как я подозреваю), он может оказаться очень опасным.", progress = "На фоне лесного пейзажа Темного Берега кристалл выглядит совершенно чужеродным. Вам кажется, что откуда-то изнутри кристалла до вас доносится чуть слышное жужжание.", completion = "Вы снова добрались до таинственного кристалла. Откупорив флакон с водой лунного колодца, вы аккуратно выливаете его содержимое на верхушку кристалла. Пока вода струится по его граням, вы видете, как непроглядная поверхность кристалла становится прозрачной...", rewards = "Вы получите:\n\n"},
[4813] = {title = "Скрытые фрагменты", objective = "Доложите о результатах ваших изысканий часовому Глинде Нал'Шие в Аубердине.", description = "С помощью воды Лунного колодца выяснилось, что в кристалле заключено несколько мелких фрагментов костей, а также половина челюсти. Кажется, челюсть принадлежала гуманоиду, но точно нельзя сказать, не разбив кристалл, – а это даже для самой мощной магии может оказаться почти непосильной задачей.\n\nЗадание выполнено, и все, что вам остается, – это вернуться в Аубердин и доложить обо всем часовому Глинде Нал'Шие.", progress = nil, completion = "Да, похоже, что, хотя мы и знаем теперь о кристалле больше, в результате возникло множество новых вопросов.\n\nЯ пойду с добытой вами информацией в совет Аубердина. Может быть, они подскажут, что делать дальше с этим кристаллом. Если вообще есть о чем говорить – пока что угроза слишком далеко на востоке, чтобы принимаеть ее всерьез.\n\nЧто же касается вас, возьмите это. Считайте это наградой за хорошо проделанную работу, Wrestlecake.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСтальной короткий меч с шипамиКриволесский кинжалДубовый посох с символом дрозда\n\nВы также получите:\n\n"},
[4821] = {title = "Странное яйцо", objective = "Принесите неизвестное яйцо Хагару Грозовому Копыту на Заставу Вольного Ветра.", description = "Ходят слухи, что здесь, в Тысяче Игл, появилось яйцо какого-то странного существа. Но те, кто видел его, не смогли подойти достаточно близко и рассмотреть яйцо поподробнее. Его охраняют змеи, да так, словно это яйцо – их собственное!\n\nЯ хочу, чтобы вы нашли его и принесли мне для изучения. Говорят, что оно находится в логове змеев, но вообще-то таких гнезд несколько, они разбросаны вдоль стен каньона к югу и северо-востоку от заставы.", progress = "Мне нужно узнать побольше об этом таинственном яйце. Кто знает, что может из него вылупиться...", completion = "Наконец-то я получил это таинственное яйцо... Дайте-ка взглянуть на него... Что... что это?!", rewards = "Вы получите:\n\n"},
[4822] = {title = "Женщинам – цветы, детям -...", objective = "Купите своему подопечному клубничное мороженое. Кажется, мальчик предпочитает мороженое Тигуле и Форора.", description = "МОРОЖЕНОЕ! Пожалуйста, пожалуйста, пожалуйста, добудь для меня немного мороженого!!! Я больше всего люблю клубничное, а самое лучше клубничное мороженое делают Тигуле и Форор! Это мое самое любимое мороженое на свете!\n\nЯ пробовал его только один раз, когда меня водили на гонки на Мерцающей равнине, но говорят, его сейчас продают у нас в городе! Пожалуйста! Пожалуйста-препожалуйста! Преогромное пожалуйста!!!!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[4841] = {title = "Упокоение кентавров", objective = "Убейте 12 разведчиков, 10 пастухов и 6 ветроловок из племени Галак, после чего вернитесь к дозорному утесов Долгорогу на Заставу Вольного Ветра.", description = "<имя>, я поручаю вам охоту на этих кентавров. Отомстите им за нас как следует – вырежьте весь их лагерь к северу от Заставы Вольного Ветра. Пусть рука ваша будет тверда!", progress = "Роггин, вы убили слишком мало кентавров! Продолжайте охоту, а уж я в долгу не останусь.", completion = "Примите это в благодарность от меня, Ахахаха.", rewards = "Вы получите:\n\n"},
[4842] = {title = "Выяснение причин", objective = "Последуйте указаниям Доновы Снегоноры, а затем вернитесь к ней.", description = "По правде говоря, хотя в Зимних Ключах вулканов нет, я думаю, для возникновения этих горячих источников есть не менее опасные причины…\n\nВпрочем, наверное, ты <сам/сама> захочешь все увидеть. Тебе нужно будет пересечь все Зимние Ключи, до самого юга этого края. Там, где воздух станет плотным и удушливым, а небо потемнеет, ты как раз и найдешь то, что я считаю причиной возникновения горячих ключей.\n\nСходи взглянуть. Я уверена, ты вернешься с кучей вопросов.", progress = "У воды в ключах очень странные свойства… я по-прежнему не очень понимаю, что все это значит…", completion = "Да, демоны добрались до Теснины Зловещего Шепота. Я уверена, мы наблюдаем следы их присутствия. И я собираюсь и дальше наблюдать на горячими ключами, чтобы узнать о них больше.\n\nЯ немного подожду, чтобы ты набрался сил, а потом снова привлеку тебя к исследованию Теснины Зловещего Шепота.", rewards = "Вы получите:\n\nГлубоководный плащ"},
[4861] = {title = "Разъяренные дикие совухи", objective = "Найдите разоренный лагерь Джерона Гранильщика и его припасы на юге Зимних Ключей.", description = "Эй, послушай, <паренек/девчушка>! Меня какие-то кровожадные дикие совухи гнали всю дорогу из моего лагеря! Подозреваю, я слишком близко подобрался к разгадке того, что же они там охраняют. \n\nЯ еле ноги унес оттуда. Боюсь, мой коллега оказался менее везучим. Ты как, не против того, чтобы бросить вызов диким совухам и отправиться в мой лагерь? Мне очень нужны мои припасы, а также я хотел бы вернуть амулет, который извлек вчера во время раскопок.", progress = nil, completion = "Среди разрушенных пожитков в лагере находится и сильно потрепанный ящик.", rewards = "Вы получите:\n\n"},
[4862] = {title = "Товар на любителя", objective = "Отправьтесь на пик Черной горы и принесите Киблеру 15 яиц скального паука.\n\nСудя по всему, яйца надо искать недалеко от пауков.", description = "Верь – не верь, но есть народ, который готов отлично заплатить за необычную зверушку, причем чем она злее, тем лучше!\n\nЯ послал на пик Черной горы Блестяшку, чтобы собрать паучьи яйца, но она уже несколько недель не возвращается. Может, ты придешь ей на выручку?\n\nВот что, <имя>. Ступай-ка туда и принеси мне паучьи яйца. Я тебе не только хорошо заплачу, но еще и приручу для тебя одного паучка!", progress = "У тебя в сумке лежат паучьи яйца или ты так, поболтать, зашел?", completion = "Какой урожай! Что за яйца! Они принесут мне несколько хорошеньких золотых монеток.\n\nКак и обещано, вот тебе зверушка. Смотри, чтобы она тебя не цапнула!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКлетка Огнепаутинки"},
[4863] = {title = "Разъяренные дикие совухи", objective = "Найдите опрокинутый фургон Джерона Гранильщика.", description = "Вы озираетесь, но видите ничего такого, чтобы могло понадобиться Джерону. Однако, заметно, что найденный вами ящик был вскрыт силой, как будто тут побывали дикие совухи...\n\nВзглянув на восток, вы замечаете покинутый фургон. Стоит посмотреть не осталось ли там каких-то вещей Джерона.", progress = nil, completion = "Подойдя к фургону, вы думаете о том, что едва ли внутри осталось что-то полезное для Джерона. Однако, приглядевшись, вы замечаете в снегу возле фургона пару ящиков, которые выглядят неповрежденными.", rewards = "Вы получите:\n\n"},
[4864] = {title = "Разъяренные дикие совухи", objective = "Подберите припасы Джерона из снега, и найдите дикого совуха, похитившего амулет, о котором говорил Джерон.\n\nПринесите припасы и ожерелье миних перьев Джерону Гранильщику в его дом в Зимних Ключах.", description = "Изучив содержимое ящика, вы решаете, что Джарону могут пригодиться лежащие там инструменты. Однако среди них нет и следа амулета.\n\nПохоже, дикие совухи обитают к северу и к востоку отсюда, и вы решаете, что ваш следующий шаг – встретить этих существ лицом к лицу и забрать у них амулет.", progress = "Привет… Расскажи-ка, какие новости?", completion = "Ну, примерно это я и ожидал услышать, парень. Я уж было думал, что свихнувшиеся звери раздраконили все мои пожитки… \n\nНо тебе удалось найти мои инструменты и, что еще важнее, амулет! Интересно, почему дикосовухи так яростно его защищали… В любом случае, я теперь дважды подумаю, прежде чем сунуться к ним опять!", rewards = "Вы получите:\n\n"},
[4865] = {title = "Змеиная дикость", objective = "Расскажите о найденном Мотеге Огненной Гриве.", description = "Если бы я не видел это собственными глазами, то ни за что бы не поверил! Месть обрушилась на Тысячу Игл!\n\n*Хагар утирает лоб.*\n\n<имя>, надо действовать быстро! Скорее, иди и поговори с Мотегой Огненной Гривой, он на заставе Белого Плеса, это к северо-западу отсюда, прямо возле дороги. Он подскажет нам, что делать!", progress = nil, completion = "Отмщение! Значит, легенда об Арикаре не врет! Да, эту проблему следует разрешить немедленно.", rewards = "Вы получите:\n\n"},
[4866] = {title = "Материнское молоко", objective = "Найдите в самом сердце пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд.", description = "Должно быть, это один из сильнейших ядов на свете!\n\nВ одной из вылазок на пик Черной горы, я слышал, как орки говорят о его смертоносности. Они называют его \"материнское молоко\" в честь Дымной Паутины, огромной паучихи, поселившейся в одной из пещер Лабиринта.\n\nВот что мне нужно от тебя: образец молока в твоих собственных венах. Мешочка с ядом не пойдет! Дай ей отравить тебя, а потом возвращайся!\n\nА я тебя... подою!\n\n*Потирает руки в нетерпении.*", progress = "*Джон-Оборванец щипает вас.*", completion = "Из этого выйдет потрясный эль!\n\nА ты что думал? Что я сделаю яд или что-то такое?\n\nНу, дети пошли...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nНеупиваемая чаша Джона-Оборванца"},
[4867] = {title = "Аррок Смертный Вопль", objective = "Прочитайте записку Вароша. Принесите Варошу его амулет.", description = "Ар-рх! Трудно говорить!\n\nВозьми эту записку! Принеси мне мой амулет!", progress = "А, вот и ты! Ты принес мой амулет?", completion = "Я уже чувствую, как ко мне возвращаются силы! И проклятие Аррока уже не разрушает мой разум.\n\nСпасибо, Джэйлол! Я не люблю быть кому-то обязанным, но должен признать: ты мне очень помог.\n\nЖелаю удачи в походе на Пик Черной горы. Это безрассудство, если ты думаешь, что сможешь дойти до вершины, хотя твоя смелость поистине не знает границ.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nОберег-призма"},
[4881] = {title = "Убийственный заговор", objective = "Предупредите Канати Серое Облако на заставе Белого Плеса, что на него готовится покушение.", description = "Таурен по имени Канати Серое Облако собрался разбить в Тысяче Игл охотничий лагерь. Мы должны убить его и опустошить лагерь, уничтожив всех его сторонников. Собираемся на маленькой заставе к юго-западу от Великого подъемника.", progress = nil, completion = "Они хотят меня убить? Пусть приходят, я покажу им, как дерутся таурены!", rewards = "Вы получите:\n\n"},
[4882] = {title = "Умение хранить секреты", objective = "Отнесите ожерелье синих перьев Труллу Баловню Судьбы на Заставу Отравленной Крови.", description = "Вы не можете понять, важна ли ваша находка – ожерелье, упавшее с шеи недавно убитого дикого совуха. Оно источает яркий пульсирующий свет.\n\nМожет быть, Трулл Неудачное Проклятье сможет что-то рассказать – похоже, он очень много знает о диких совухах. Возможно, стоит его расспросить об этом ожерелье?", progress = "Хотите еще о чем-то сообщить?", completion = "Важная находка?", rewards = "Вы получите:\n\n"},
[4883] = {title = "Умение хранить секреты", objective = "Отнесите ожерелье синих перьев Наре Буйногривой.", description = "Хотя я располагаю некоторыми сведениями о совухах, с которыми ты <боролся/боролась> в Зимних Ключах, однако об их магии мне ничего не известно. Но я знаю кое-кого, кто с удовольствем изучит это ожерелье и скорее всего сумеет рассказать тебе о его свойствах.\n\nНара Буйногривая из Громового Утеса настоящий эксперт в подобных вещах, тебе стоит поговорить с ней. Удачи, <имя>!", progress = "Чем я могу помочь тебе, Томпсон?", completion = "Полагаю, у энергии этого ожерелья лишь один источник, Томпсон.\n\n*Нара закрывает глаза и замолкает на мгновение.*\n\nДикосовухи, обманутые и испуганные существа, не всегда были такими. Они были созданы для того чтобы служить ночным эльфам. Богиня ночных эльфов Элуна сотворила их, чтобы охранять священные места.\n\nКонечно, это кажется неважным, однако я призываю тебя взглянуть глубже.\n\nВ свое время ты поймешь. Спасибо, что принес мне это ожерелье, Томпсон.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНаручи морских брызгСияющие латные наручи\n\nВы также получите:\n\n"},
[4901] = {title = "Стражи алтаря", objective = "Защитите Раншаллу, пока она пытается активировать алтарь Элуны. Сообщите о ваших находках Эреласу Янтарному Небу в деревне Рут'теран.", description = "На самой вершине гребня находится, как я полагаю, алтарь богини Элуны. Насколько я знаю, нам нужно зажечь пять факелов – в каждой пещере, и тогда мы получим доступ к алтарю.\n\nЯ расшифровала заклинания, вырезанных на камне в древних руинах Кел'Терила, которые, как я думаю, являются ключом к активации алтаря. Помогите мне зажечь факелы, пока я буду читать заклинание.\n\nЕсли у нас все получится, вы сможете доложить Эреласу о результатах!", progress = nil, completion = "Вы виделись с Раншаллой?", rewards = "Вы получите:\n\n"},
[4902] = {title = "Питомцы Элуны", objective = "Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнассе.", description = "Это поразительно!\n\nМне всегда было интересно, какова же истина… Что ж, вы просто обязаны поделиться этими сведениями! Сразу же отправляйтесь к верховному друиду Фэндралу Оленьему Шлему – вы найдете его в Дарнассе, в Круге Кенария. Расскажите ему подробно о случившемся – так же, как рассказали мне. Я уверен, что ему будет очень интересно!\n\nЭто важная информация, <имя>!", progress = nil, completion = "Не ходите вокруг да около, рассказывайте, с чем пришли.\n\nАх, вот как? Хмм… Ясно.\n\nСпасибо, что сразу пришли с этим ко мне; докладывать все на самый верх – самое правильное… Но… Да. Друиды Круга Кенария знают о дикосовухах уже довольно давно. О том, что они – питомцы Элуны и были избраны охранять наиболее священные места.\n\nВ общем, хоть это для нас и не новость, я, безусловно, признателен вам за ваши усилия. Вот, возьмите это – думаю, это подходящая награда за ваши труды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМетатель ШиповОпалиновый медальон\n\nВы также получите:\n\n"},
[4903] = {title = "Приказ полководца", objective = "Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них важные бумаги Черной горы доставьте полководцу Клинозубу в Каргат.", description = "По приказу полководца Клинозуба следующие жители Пика Черной горы подлежат уничтожению: \n\nОсобо опасный преступник вождь Омокк. \n\nЖестокий и беспощадный тролль воевода Вун.\n\nПовелитель Змейталак, десятник в малом городе.\n\nТакже необходимо доставить в штаб все найденные при них документы. \n\nУспех – слава и награда.\n\nПоражение – позор и забвенье.", progress = "*Полководец Клинозуб берет под козырек*.", completion = "*Зеленые щеки полководца на минуту покрываются мертвенной бледностью.*", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОковы ВурмталакаТесьма-фиксатор ОмоккаНамордник ХаликонПояс Вос'гаджинПоганые захваты Вуна\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4904] = {title = "Долгожданная свобода", objective = "Выведите Лакоту Песню Ветра с Пика Темного Облака, а потом поговорите с Талией Янтарной Шкурой на Заставе Вольного Ветра.", description = "Арнак хотел жениться на мне, и поэтому похитил меня, когда я отвергла его предложение. Мой брат пытался остановить его, но Арнак оказался сильнее. Он... он убил моего брата и привел меня сюда. Мой бедный брат...\n\n<имя>, не могли бы вы вывести меня с Пика Темного Облака? Я хочу назад, к Талье! Она, наверное, с ума сходит от беспокойства.", progress = nil, completion = "Спасибо, Усамыч. В глубине души я всегда верила, что она найдет способ вернуться ко мне. Она рассказала мне о вашей храбрости и о том, как вы помогли ей сбежать. Эти вещи принадлежали ее брату. Уверена, она бы сама непременно отдала их вам.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКушак песни ветраПелерина Песни Ветра\n\nВы также получите:\n\n"},
[4906] = {title = "Снова порча!", objective = "Эридана Грусть Ветра из Оскверненного леса просит вас убить 8 призывателей огня, 8 предателей и 8 плутов из племени Нефритового огня, а также Ксаварика. По выполнении задания возвращайтесь к Эридане.", description = "Другой лагерь сатиров угрожает северной части Оскверненного леса. Тамошними сатирами предводительствует жестокий Ксаварик. Эти подлые предатели и обманщики радуются, поражая порчей тварей Оскверненного леса.\n\nКсаватрас и его приспешники – только часть большого плана по созданию оскверненного лунного колодца. А затем всем этим воспользуется Ксаварик.\n\nТеперь, когда Ксаватрас уже не мешается у нас под ногами, заверши это дело, <имя>. Отправляйся на север и срази Ксаварика.", progress = nil, completion = "Спасибо за все, что ты сделал, Мяуыч. Да защитит тебя Элуна, и да направит она твой путь.", rewards = "Вы получите:\n\nНаручи Ветрооблачка"},
[4907] = {title = "Тинки Кипеллер", objective = "Поговорите с Тинки Кипеллер.", description = "Привет, <имя>. Помнишь Тинки Кипеллер? Она-то тебя помнит! Она послала мне весточку, чтобы я передал тебе при случае. Ей снова нужна твоя помощь. Кажется, это опять связано с изучением драконов.\n\nСтупай в Пылающие степи, в Пламенеющий Стяг, и поговори с ней.", progress = nil, completion = "Фелнок не ошибся! Мне снова нужна твоя помощь, и на сей раз... задание будет опасным.\n\nТы готов?", rewards = "Вы получите:\n\n"},
[4921] = {title = "Пропавшая без вести", objective = "Отыщите жену Манкрика и возвращайтесь к нему в Перекресток.", description = "Мы бились в маленьком лагере тауренов и разделились в бою – на нее наседали разом три иглогрива Вздыбленной Щетины. Силы были неравны. Я отвлек на себя очень многих и увидел, что набежали новые враги и одолевают ее. Впав в ярость, я бросился на врагов, но они с легкостью одержали надо мной верх.\n\nЯ пришел в себя и увидел, что таурен-друид ухаживает за мной, – он набрел на меня на Золотом пути.\n\nПрошу тебя, <класс>, узнай что-нибудь о моей жене.", progress = nil, completion = "Понятно. Спасибо, |3-6(Воин).", rewards = "Вы получите:\n\n"},
[4941] = {title = "Мудрость Эйтригга", objective = "Поговорите с Эйтриггом в Оргриммаре. После этого обратитесь к вождю Траллу. \n\nВ последний раз Эйтригг был в в зале приемов Тралла.", description = "Ренд жив? \n\nБыть того не может! Я думал, он погиб несколько десятков лет назад. \n\nТебе нужно обратиться за советом к Эйтриггу, <имя>! Никто не знает о Черной горе больше него, и если то, что написано здесь, правда, Эйтриггу стоит об этом знать. Никому нельзя отказывать в праве на месть. \n\nКогда поговоришь с Эйтриггом, ступай к вождю за указаниями.", progress = "Зачем явился? Я занят!", completion = "*Тралл, похоже, весьма встревожен услышанным.*", rewards = "Вы получите:\n\n"},
[4961] = {title = "Очищение шара Орахила", objective = "Убейте демона сферы, а потом поговорите с Табетой.", description = "А, сфера призывателя – так вот откуда исходит искажение. Если ты хочешь ей пользоваться, придется изгнать из нее демона. С этим я легко справлюсь.\n\nТебе придется куда труднее. Как только демон выйдет из сферы, убей его.\n\nИ спеши. Если ты будешь возиться слишком долго, он вернется в сферу, и нам придется начать сначала!\n\nПодготовься к схватке, <имя>. Вспомни самые сильные заклинания и держи под рукой зелья. Если у тебя есть друг, можешь позвать его. Сражение будет нелегким.", progress = nil, completion = "Великолепно, Призрак. Тебе удалось преподать этому демону урок, который он надолго запомнит. Могущества и умения тебе не занимать. Полагаю, пришло время вернуться к Менаре с очищенным шаром и найти ему доброе применение.\n\nУдачи, |3-6(Чернокнижник). Быть может, наши пути еще пересекутся.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nОчищенная сфера Подземного огня"},
[4962] = {title = "Осколок гончей Скверны", objective = "Возьмите рубин Сквернолова и поймайте в него одну из гончих скверны в Пустошах. Добившись успеха, отнесите плененный дух Гончей Скверны и рубин Сквернолова Менаре Расщепительнице Бездны из Степей.", description = "Итак, ты <выбрал/выбрала> гончую скверны. Отлично.\n\nВозьми этот рубин, он позволит подчинить ее душу. Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он все сделает за тебя.\n\nСоветую отправиться в Пустоши и попробовать подчинить одну из тамошних гончих скверны. Они отлично подойдут.\n\nКогда добьешься успеха, отнеси плененного духа и рубин Менаре.", progress = "Да, Шта? Ты сделала выбор? Инфернал или гончая скверны?\n\nЧасто чернокнижники предпочитают усиливать сильные стороны, а не развивать слабые. Порой лучше научиться чему-то одному, чем стать разносторонним заклинателем.", completion = "А, дух гончей скверны. Молодец, Шта;.\n\nКогда у меня будет и дух, и очищенная сфера, я смогу слить их воедино, но не раньше.", rewards = "Вы получите:\n\n"},
[4963] = {title = "Осколок инфернала", objective = "Возьмите Пылающий изумруд и поймайте в него одного из инферналов в Пустошах. Добившись успеха, отнесите плененный дух инфернала и пылающий изумруд Менаре Расщепительнице Бездны из Степей.", description = "Итак, ты <выбрал/выбрала> инфернала. Отлично.\n\nВозьми этот изумруд, он позволит подчинить его душу. Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он все сделает за тебя.\n\nСоветую отправиться в Пустоши и попробовать подчинить одного из инферналов. Они отлично подойдут.\n\nКогда добьешься успеха, отнеси плененного духа и изумруд Менаре.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[4964] = {title = "Завершение шара Дар'орахила", objective = "Дождитесь, пока Менара Расщепительница Бездны закончит работу над шаром Дар'орахила, и еще раз поговорите с ней.", description = "Я немедленно займусь твоим шаром. Надо вселить в него нового демона. После этого у меня будет выбор: превратить его в сферу или в посох. Я всегда считала, что соответствие избранному оружию чернокнижника – это главное... Не вижу причин менять свое мнение.", progress = nil, completion = "Готово. А теперь скажи, что ты предпочитаешь,: посох, который займет обе руки, или шар, который позволит тебе пользоваться кинжалом или мечом.\n\nСражение с огненным големом – суровое испытание. Нет сомнений, что этот предмет славно послужит тебе в будущем. Прилежно изучай тайные искусства, Шта. Я буду ждать вестей о твоих подвигах.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСфера Дар'орахилаПосох Дар'орахила\n\nВы также получите:\n\n"},
[4965] = {title = "Знание шара Орахила", objective = "Поговорите с Менарой Расщепительницей Бездны в Степях.", description = "Так-так-так… приятно видеть, как ты набираешься могущества, <имя>. Мне кажется, ты <готов/готова> поговорить с Менарой Расщепительницей Бездны в Степях. Если вы раньше не встречались, то, поверь мне, другого такого специалиста по созданию предметов – особенно сфер, в которые можно заключить демона – не найти.\n\nИнтересно? Тогда поищи ее. Она живет в башне Страхада над Кабестаном.", progress = nil, completion = "А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь.\n\nПриятно видеть, что не все наши сородичи стремятся к одним лишь знаниям.\n\nИтак, думаешь, ты готов, Фронгли?", rewards = "Вы получите:\n\n"},
[4966] = {title = "Защитить Канати Серое Облако", objective = "Защитите Канати Серое Облако от нападения кентавров.", description = "Кентавров намного больше, чем я думал, <имя>. Пожалуйста, помогите мне отбиться от них.", progress = nil, completion = "Спасибо за помощь, Блудикнайф. Без тебя я бы ни за что не справился.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛегкоступные сапогиПокрытые глиной наручиПерчатки Белодолгонога\n\nВы также получите:\n\n"},
[4967] = {title = "Знание шара Орахила", objective = "Поговорите с Менарой Расщепительницей Бездны в Степях.", description = "Ты так и не <поумнел/поумнела> и по-прежнему стремишься в западню. Да, говорю я дерзко. Я смотрю на тебя и смеюсь. Ты жалкий червь!\n\nНо мое мнение не имеет значения. Главное, что думают те, кто желает иметь с тобой дело! И в данном случае наделенные силой полагают, что ты заслуживаешь большего.\n\nЕсли ты к чему-то стремишься, поговори с Менарой Расщепительницей Бездны в башне над Кабестаном. Кажется, ты с ней уже <встречался/встречалась>.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[4968] = {title = "Знание шара Орахила", objective = "Поговорите с Менарой Расщепительницей Бездны в Степях.", description = "Хм-м... Тебе удалось добиться немалого... Поразительно. Я думала, что ты давно <сошел/сошла> с ума, <раздираемый/раздираемая> скверной магией, просочившейся в твою душу. Тогда, пожалуй, двинемся дальше?\n\nЕсли ты хочешь испытать свое искусство, отыщи Менару Расщепительницу Бездны в башне Страхада над Кабестаном. Она поможет тебе сделать следующий шаг.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[4969] = {title = "Знание шара Орахила", objective = "Поговорите с Менарой Расщепительницей Бездны в Степях.", description = "Ха-ха! Ты растешь над собой, <юный/юная:c> <класс>.\n\nСо временем инферналы и повелители ужаса склонятся перед тобой!\n\nПока же тебе приходится полагаться на оружие, скованное руками смертных.\n\nПохоже, ты <готов/готова> создать еще одно. Если хочешь, с тобой может поговорить Менара Расщепительница Бездны! Она живет неподалеку от башни Страхада над портовым городом Кабестан. Отправляйся туда, как решишь, что время уже пришло.", progress = nil, completion = "А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь.\n\nПриятно видеть, что не все наши сородичи стремятся к одним лишь знаниям.\n\nИтак, думаешь, ты готова, Шта?", rewards = "Вы получите:\n\n"},
[4970] = {title = "Накормить ледопардов", objective = "Соберите 5 кусков мяса медведей-щеброзуба и 5 кусков мяса стылодыхов для Риверна Холодного Ветра в Зимних Ключах.", description = "Если хотите достойно проявить себя, начните с простого, но очень важного дела. \n\nДобудьте в окрестностях мясо химер и медведей-щербозубов. Принесите его мне, чтобы я мог кормить им ледопардов, которых я дрессирую.", progress = "Дисциплина и твердая решимость – вот чего вы должны достичь. Я могу поручать вам простейшее задание не один раз, и вы должны каждый раз делать все как можно лучше.", completion = "Спасибо за помощь, Вилдан. Мое мнение о вас со временем становится все лучше.", rewards = nil},
[4971] = {title = "Вопрос времени", objective = "Воспользуйтесь временным переместителем рядом с одним из амбаров Андорала и найдите временных паразитов.\n\nУбейте 10 временных паразитов и верните временной переместитель Хроми в таверну Андорала в Западных Чумных землях.", description = "Кто-то вмешался в ход времени в Андорале! Скорее всего, это дело рук Плети. Я могу попытаться сохранить неизменным ход времени здесь и исправить повреждения, но мне не должны мешать. В этом ты мне и поможешь.\n\nВ Андорале поселились временные паразиты, падальщики, питающиеся обрывками потока времени. Их можно обнаружить только по синему сиянию. Они очень мешают мне. Пожалуйста, <имя>, искорени этих паразитов, воспользовавшись временным переместителем.", progress = "Там, где кто-то вмешивается в ход времени, непременно появляются временные паразиты. Я чувствую, что их немало, и они мне очень мешают.\n\nЕсли ты искоренишь хотя бы часть, мне будет гораздо проще разрешить сложившуюся ситуацию. Я почувствую, когда ты справишься с моим заданием.", completion = "Мне стало много легче исправлять ход времени. Спасибо, Томпсон. Хотя тебе непросто понять все опасности нарушения естественного хода событий, я рада, что ты осознаешь важность противостояния Плети, а я почти уверена, что это дело ее рук.\n\nПочему бы не вознаградить тебя за помощь, смертный. Тебя ждут величайшие подвиги, и одна безделушка не заставит тебя свернуть с избранного пути. Хотя нам с драконами не помешает твоя помощь и в дальнейшем...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСветло-лиловый нарамникПояс с золотой сцепкой\n\nВы также получите:\n\n"},
[4972] = {title = "Отсчет времени", objective = "Найдите 5 часов Андорала, спрятанных в сундуки среди руин. Принесите их Хроми в таверну Андорала в Западных Чумных землях.", description = "Мне нужно отправить тебя в мир за пределами этой комнаты, <имя>. Сейчас все объясню.\n\nВидишь, как эта комната отличается от остального Андорала? Мои драконы существуют во многих пластах реальности и времени. Чтобы исправить ущерб, нанесенный Андоралу, я действую из другого временного пласта, чтобы не загрязнить его сверх меры. Для продолжения работ мне необходимы особые устройства, оставшиеся со времен прихода чумы. Они находятся в сундуках в руинах некогда гордого города.", progress = "Временные устройства, которые я ищу, очень просты. По большей части это просто часы, и их стрелки остановились в тот миг, когда в Андорале вспыхнула чума.\n\nВремя нескончамо, а часы, которые ты мне принесешь так и будут стоять... пока мы не справимся с временной аномалией.", completion = "Вот, как раз то, что нужно, Томпсон. Спасибо.\n\nПозволь вознаградить тебя. Быть может, ты не понимаешь, зачем тебе такое устройство. И даже для чего оно; довольно знать, что в будущем этот предмет тебе очень пригодится. А сохранишь ты его до тех времен или нет... дело твое, дружок.", rewards = "Вы получите:\n\nНастроенный глушитель"},
[4973] = {title = "Отсчет времени", objective = "Найдите 5 часов Андорала, спрятанных в сундуки среди руин. Принесите их Хроми в таверну Андорала в Западных Чумных землях.", description = "Если ты <готов/готова> еще раз оказать мне помощь, я попрошу тебя принести еще пять часов из руин Андорала. Это очень поможет мне на равных бороться со злобной силой, пытающейся изменить ход времени.\n\nВзамен часов ты получишь еще один дар, который, мне кажется, здорово пригодится тебе в будущем.", progress = "Часы Андорала, как и те, на башне, остановились в три часа. Именно в это время чума распространилась по всему городу, лишая жизни несчастных жителей.\n\nКак ни печалимся мы о событиях того дня, они уже вошли в историю, без них не было бы сегодняшнего дня, такого, каким видите его вы, смертные. Бронзовые драконы должны хранить линию времени!", completion = "И снова я благодарю тебя за помощь. Прими этот дар. Сейчас тебе невдомек, для чего он, но, быть может, ты еще узнаешь его истинную ценность. Можно сказать, что я предвижу это, Рейнон.", rewards = "Вы получите:\n\nНастроенный глушитель"},
[4974] = {title = "За Орду!", objective = "Пойдите в Пик Черной горы и убейте вождя Ренда Чернорука. Принесите его голову в Оргриммар.", description = "Ренд осмеливается делать подобные заявления, потому что он пользуется поддержкой черных драконов.\n\nТы, <имя>, проникнешь в Залы Вознесения, найдешь там \"вождя\" Ренда Чернорука и уничтожишь его – ВО ИМЯ ОРДЫ!!!\n\n*Тралл ударяет кулаком по своему трону.*\n\nВ следующий раз, как я увижу тебя в своих покоях, ты торжествующе поднимешь ввысь его отрубленную голову и вручишь ее своему вождю. Выполни это – и станешь одним из героев Орды!", progress = "*Тралл фыркает.*", completion = "Тебе удалось нанести силам Черной горы сокрушительный удар, Стиммакс! Теперь, когда их вождь убит, воинство Черной горы снова ввергнуто в хаос.\n\nНаградой за твой героизм будет процветание народа Калимдора!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗнак ТиранииГлаз ЗверяПластита Чернорука\n\nВы также получите:\n\n"},
[4975] = {title = "Завершение шара Дар'орахила", objective = "Дождитесь, пока Менара Расщепительница Бездны закончит работу над шаром Дар'орахила, и еще раз поговорите с ней.", description = "Я немедленно займусь твоим шаром. Надо вселить в него нового демона. После этого у меня будет выбор: превратить его в сферу или в посох. Я всегда считала, что соответствие избранному оружию чернокнижника – это главное... Не вижу причин менять свое мнение.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСфера Нох-ОрахилаПосох Нох-Орахила\n\nВы также получите:\n\n"},
[4976] = {title = "Возвращение к Менаре", objective = "Отнесите очищенную сферу инфернала Менаре Расщепительнице Бездны в Степи.", description = "Теперь, когда демон изгнан, ты можешь отнести шар Менаре в Кабестан, <имя>. Передай ей от меня привет, да и <сам/сама> не робей. Надеюсь, что тебе удастся противостоять искушениям порчи, которые, несомненно, будут подстерегать тебя на избранном пути.\n\nЖелаю удачи.", progress = "Как идут поиски Табеты и сферы?\n\nКогда дело доходит до магических сил, без нее не обойтись. Не сомневаюсь, она с радостью согласилась бы помочь тебе, отыщи ты ее.", completion = "Отлично, Шта. Подходящая сфера.\n\nОсталось одно – решить, какого демона следует заключить в нее. Решишь – считай, новый предмет силы у тебя в кармане.", rewards = "Вы получите:\n\n"},
[4981] = {title = "Агент Блестяшка", objective = "Отправьтесь к пику Черной горы и выясните, что сталось с Блестяшкой.", description = "Никогда нельзя верить гоблинам! Рано или поздно все приходят к этому выводу, <имя>. \n\nЕе зовут Блестяшка, она была одним из лучших наших агентов. Потом оказалось, что стерва вела двойную игру – работала на какого-то типа по имени Киблер, нелегально торгующего экзотическими животными в Пылающих степях, и использовала средства Орды для финансирования своих махинаций! \n\nОна должна быть доставлена ко мне живой. \n\nПоследний раз ее видели у Пика Черной горы. \n\nИ смотри, чтобы она не заговорила тебе зубы!", progress = nil, completion = "Я не буду лгать тебе, |3-6(нежить). Мне были нужны деньги! Киблер хорошо платит – куда больше, чем в Каргатском экспедиционном корпусе в лучшие его годы. \n\nНо можешь не сомневаться, я верна присяге! Думаешь, зачем я здесь? Чтобы таскать этому придурку-гоблину яйца экзотических зверушек или еще для каких глупостей? Нужно быть очень крупным идиотом, чтобы явиться в пик Черной горы отлавливать зверье! Не думаю, что на свете много таких сумасшедших. \n\n*Блестяшка заливисто хохочет.*\n\nВот что я тебе скажу, такие просто не должны размножаться, да-да!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4982] = {title = "Вещи Блестяшки", objective = "Найдите вещи Блестяшки и верните их владелице. Блестяшка сказала, что она спрятала свое оборудование где-то на нижнем ярусе подземелья.", description = "По ночам, когда городская стража не особенно ревностно исполняет свои обязанности, я незаметно брожу по улицам и беру на заметку все, что может иметь хоть какую-то ценность для стратегических планов К.Э.К. Все подмечаю и все записываю.\n\nНо вчера ночью случился прокол. В темноте я запнулась о натянутую веревку, и включился сигнал тревоги. Пришлось срочно прятать все оборудование для разведки и мчаться в укрытие. И что самое ужасное, сейчас мне уже не удастся забрать свои вещи из тайника. В городе ввели усиленный режим патрулирования! Вся информация утрачена.\n\nРазыщи мои вещи, верни их мне, и я тихо-мирно вернусь в К.Э.К.", progress = "Ну, как успехи?", completion = "Ой, молодчина! Когда я передам Лекслорту эти планы, он позабудет обо всех страшных угрозах в мой адрес и уж точно не станет спускать с меня шкуру.\n\nСтиммакс, ты мой герой!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[4983] = {title = "По данным разведки", objective = "Передайте донесение Блестяшки гроссмейстеру Лекслорту в Каргат.", description = "Передай этот рапорт Лекслорту. Теперь я верну себе доброе имя, потому что мое донесение, безусловно, сослужит хорошую службу К.Э.К. и даст им значительное стратегическое преимущество в борьбе с этими орками.\n\nПойти с тобой, говоришь? У меня много работы, недосуг мне носиться туда-сюда. Беги, донесение надо доставить как можно скорее!", progress = "Где эта гоблинша?!", completion = "Все-таки надо отдать ей должное;, хитрая бестия снова сумела выкрутиться! Ее донесение содержит бесценную информацию, которая очень поможет в наших делах с орками Черной Горы.\n\nРазумеется, ты не останешься без награды. Всякий труд должен быть оплачен.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки Вольного ветраРемень морской заставы\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[4984] = {title = "Страдания природы", objective = "Убейте 8 больных волков и вернитесь к Мулгрису Глубокой Реке в Удел Страданий в Западных Чумных землях.", description = "Хотя бороться с Плетью в одиночку бесполезно, я все равно прибыл в эти земли, чтобы лечить израненную природу. Чума поражает зверей и травы, не ведая пощады. Прошу, продолжи мое дело.\n\nНесчастных животных не спасти, остается прекратить их страдания. Ступай, отыщи больных волков и прикончи их. Прошу тебя, <имя>, избавь их от мучений – и мне тоже станет полегче.", progress = "Пораженных чумой волков необходимо истребить. Эта болезнь неизлечима. Я пытался справиться с ней, пока сам не пал ее жертвой.", completion = "Я... Чую, что души убитых волков обрели покой. Мы с ними благодарны тебе за милосердие.\n\nНо в этом проклятом месте страдают не только волки. Мне вновь придется просить тебя о помощи.", rewards = "Вы получите:\n\n"},
[4985] = {title = "Страдания природы", objective = "Убейте 8 болезненных гризли и вернитесь к Мулгрису Глубокой Реке в Удел Страданий в Западных Чумных землях.", description = "На востоке отсюда, рядом с границей Восточных Чумных земель, некогда жили гордые и могучие гризли.Чума затронула и их. Теперь они бродят по округе, страдая от застывающих мышц и гниющей плоти и меха.\n\nПрошу тебя, избавь их от страданий. Единственное исцеление для них – быстрая смерть. Ты можешь даровать ее.", progress = "Я слышу твою поступь, Херин. Зрение мое уже помутнилось, но я чувствую все, что вокруг. Ты избавил несчастных гризли от страданий?", completion = "\"Я чувствую, что гризли упокоились с миром. Вот... вот моя последняя просьба. Я записал ее.. на этой ветви, чувствуя, что дни мои сочтены.\n\nЯ не ошибся, мне и верно приходит конец. Еще раз спасибо, брат... все живые существа этой проклятой земли обрели покой... теперь мой черед.\"\n\nС этими словами друид испускает тяжелый вздох, сменяющийся предсмертным хрипом. На полу остается лишь безжизненное тело.", rewards = "Вы получите:\n\n"},
[4986] = {title = "Покрытая письменами дубовая ветвь", objective = "Судя по магии, вложенной в покрытую письменами дубовую ветвь, друид-таурен желал отнести ее в Круг Кенария в Дарнассе. Попросите о помощи одного из тамошних друидов.", description = "В безжизненной руке друида-таурена – удивительно живая дубовая ветвь. Внимательно осмотрев ее, вы видите вырезанные на ней друидические символы.\n\nСхватившись за ветвь, вы замечаете, что она слишком теплая для простой ветви. У вас в подсознании возникает образ древа Тельдрассила, точнее, самого Дарнасса. Более того, в голове так и вертятся слова \"Круг Кенария\". Кажется, в ветку вложили знания, куда ее лучше отнести.", progress = "Приветствую тебя от имени Круга Кенария, |3-6(Чернокнижник). Что за дела привели тебя к нам?", completion = "Это... Это странно. Тот друид – друид-таурен, надо же – передал тебе ценнейшие сведения о чуме Плети. Удивительно, зачем таурену понадобилось добровольно передавать подобные сведения |3-6(гном). Надеюсь, ты говоришь правду. Не сомневайся, мы воспользуемся этими данными. Значит, таурены не так далеко отпали от Кенария, как полагает Фэндрал...\n\nКхе-кхе, да. Прими это в знак признательности Круга Кенария.", rewards = "Вы получите:\n\nВишневая пелерина"},
[4987] = {title = "Покрытая письменами дубовая ветвь", objective = "Судя по магии, записанной в покрытую письменами дубовую ветвь, друид-таурен желал отнести ее в Круг Кенария в Громовом Утесе. Попросите о помощи одного из тамошних друидов.", description = "В безжизненной руке друида-таурена – удивительно живая дубовая ветвь. Внимательно осмотрев ее, вы видите вырезанные на ней друидические символы.\n\nСхватившись за ветвь, вы замечаете, что она слишком теплая для простой ветви. У вас в подсознании возникает образ Громового Утеса в Мулгоре, точнее, Вершины Старейшин. Более того, в голове так и вертятся слова \"Круг Кенария\". Кажется, в ветку вложили знания, куда ее лучше отнести.", progress = "Приветствую тебя от имени Круга Кенария, |3-6(Охотник). Что за дела привели тебя к нам?", completion = "Значит, это от Малгриса? Мы слышали, что он хотел избавить существ из Чумных земель от страдания, но столь плачевного итога мы не ждали... Печально. Малгрис... был моим другом. Я скорблю о его гибели.\n\nНо благодаря тебе его труды не пропали даром. В этой ветви заключено множество знаний о наступлении чумы на наши земли. Мы пристально изучим ее. А что до тебя, то возьми это. Мы хотели бы отблагодарить тебя.", rewards = "Вы получите:\n\nВишневая пелерина"},
[5001] = {title = "Вещи Блестяшки", objective = "Найдите вещи Блестяшки и верните их владелице. Удачи!", description = "Обычно я стараюсь не связываться с такими, как ты, <раса>, но, похоже, сейчас я застряла между троллем и горным завалом. Видишь ли, я выполняю важное задание для Орды. Однако та информация, которую мне удалось раздобыть, касается также и благополучия Альянса. Поверь мне, я не питаю симпатий к Альянсу, но угроза Черной горы – это гораздо серьезнее, чем какая-то там толпа грязных орков.\n\nПомоги мне найти мои вещи, а я передам тебе сведения, которые могут оказаться полезными для твоих сородичей.\n\nНу что, по рукам?", progress = "Ну, как успехи?", completion = "Ой, спасибо! И где ж они были?!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5002] = {title = "Донесение Максвелла", objective = "Передайте маршалу Максвеллу информацию Блестяшки.", description = "Я – честная гоблинша и хозяйка своего слова, <раса>. А теперь слушай внимательно...\n\nЭтих орков используют в основном в качестве вьючных животных или пушечного мяса для черных драконов!\n\nИх предводитель не кто иной, как Нефариан, сын Смертокрыла. Также мне удалось узнать, где именно в крепости засели приспешники Нефариана.\n\nОтнеси эту карту маршалу Максвеллу в Пылающие степи. Я там отметила все места, где найти этих извергов.", progress = "Август! Сколько лет, сколько зим!", completion = "Что ж, это лишь подтверждает уже известную нам информацию. Тем не менее здесь есть интересные сведения, которые нам пригодятся.\n\nОтметки на карте – это хорошее подспорье. Так мы быстрее разберемся с угрозой Черной горы.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5021] = {title = "Лучше поздно, чем никогда", objective = "Судя по сбивчивым объяснениям призрачной женщины, она хочет доставить посылку. Бедняга уверяет, что посылка лежала там, где стоял ее конь. Где именно это было, женщина не сказала.", description = "\"Доставьте посылку... Доставьте ее, пока я не очутилась в ловушке!\"\n\nПо всему дому разносятся причитания напуганной женщины. Привидение скорчилось в углу на втором этаже. Кажется, она не понимает, что вокруг, да и вас едва замечает.\n\n\"Ты хочешь доставить мою посылку? Прошу тебя, сделай это, пока хуже не стало. Я собиралась уехать отсюда. Должно быть, там все еще стоит мой конь... или я опоздала?\"", progress = nil, completion = "В сарае на полу лежит посылка. Вы могли бы пройти мимо, но она бросается в глаза среди развалин. Быть может, именно о ней говорила Джанис Фелстоун...", rewards = "Вы получите:\n\n"},
[5022] = {title = "Лучше поздно, чем никогда", objective = "Выясните у королевских представителей Переписи Штормграда местонахождение Эммы Фелстоун. Офицера-переписчика можно найти в Ратуше.", description = "Вы берете посылку, стирая с нее слой пыли и грязи. Она адресована Эмме Фелстоун из Штормграда; посылка должна была быть доставлена четыре года назад.\n\nХотя вы не уверены, что Эмма Фелстоун жива, всем известно, что в Штормграде существует реестр жителей города. Справки можно наводить у королевских представителей Переписи Штормграда.", progress = "Добро пожаловать в отдел переписи Штормграда. Если вы хотите навести справки о жителях города, то пришли по адресу.", completion = "Говорите, посылка для Эммы Фелстоун? И четыре года назад она жила в Штормграде? Посмотрим…\n\nСудя по всему, четыре города назад в городе и верно жила некая Эмма Фелстоун. Скорее всего жила. Я ориентируюсь по переписи, имевшей место пять лет назад, но никаких записей о том, что она уехала, нет. Но это не значит, что Эмма все еще здесь.\n\nМинуточку... уж не старушке ли Эмме адресована эта посылка?", rewards = "Вы получите:\n\n"},
[5023] = {title = "Лучше поздно, чем никогда", objective = "Поговорите с королевскими инспекторами Подгорода и наведите справки о Иеремии Фелстоуне. Офицера-переписчика можно найти рядом с пунктом регистрации гильдий и гербовых накидок.", description = "Вы берете посылку, стирая с нее слой пыли и грязи. Она адресована Иеремии Фелстоуну из Лордерона; посылка была подготовлена к отправке четыре года назад.\n\nХотя вы не уверены, что Иеремия Фелстоун жив, всем известно, что в Подгороде, прежде именовавшихся Лордероном, существует реестр жителей города. Справки можно наводить у королевских инспекторов Переписи Подгорода.", progress = "Тебе требуется помощь переписчика Подгорода или ты просто хочешь узнать, не умер ли твой давний знакомый? Ко мне с такими вопросами часто обращаются.", completion = "Посылка для Иеремии Фелстоуна... В Лордерон... Пожалуй, я смогу помочь.\n\nДо наступления чумы Иеремия Фелстоун жил в городе. Бывший Иеремия Фелстоун – многие представители нежити изменили фамилии, чтобы избавиться от прошлого. Так произошло и в этом случае. Иеремения Фелстоун стал Иеремией Пэйсоном.\n\nМинуточку... разве это не он продает тараканов?", rewards = "Вы получите:\n\n"},
[5041] = {title = "Снабжение Перекрестка", objective = "Найдите и верните Торку из Степей ящики с припасами из Перекрестка.", description = "Нападение на караваны лишает нас необходимых припасов.\n\nТебе хватило храбрости выступить против племени Иглогривых, и я вновь попрошу тебя о том же, но на сей раз посматривай, нет ли где украденных у нас припасов? Может быть, они в лагерях этих тварей, и иглогривы жиреют на чужом добре?\n\nНарод Перекрестка будет у тебя в неоплатном долгу.", progress = "Как идут поиски припасов? Надеюсь, иглогривов-то ты легко одолеешь?", completion = "Ха-ха! Спасибо, Гронгард! Ты нам очень помог. Ты неизменно спасаешь народ Перекрестка и Орды. Если я могу что-нибудь для тебя сделать, обращайся.", rewards = "Вы получите:\n\n"},
[5042] = {title = "Сила Агамаггана", objective = "Если ты желаешь обрести силу Агамаггана, |3-6(орк), принеси мне 4 кровавых осколка.\n\nВраги будут трепетать перед тобой, когда я благословлю тебя. *фыркает*\n\nЛишь величайшим воинам племени Иглогривых дарована такая сила!", description = nil, progress = "Если ты желаешь обрести силу Агамаггана, |3-6(орк), принеси мне 4 кровавых осколка.\n\nВраги будут трепетать перед тобой, когда я благословлю тебя. *фыркает*\n\nЛишь величайшим воинам племени Иглогривых дарована такая сила!", completion = "Ах, если бы Кривозуб мог видеть, как ты наказал предавших его! *фыркает*\n\nБлагодарю тебя, ведь, собирая эти осколки, ты убил еще нескольких иглогривов Дыбогривов. Продолжай в том же духе, и я вновь буду помогать тебе. *фыркает*", rewards = "Вы изучите:\n\nСила Агамаггана"},
[5043] = {title = "Ловкость Агамаггана", objective = "Величайшие разведчики моего племени издавна отличались несравненной меткостью, и ни одному разбойнику *фыркает* даже и не снилась подобная стремительность в битве.\n\nПринеси мне 4 кровавых осколка, и превзойдешь ловкостью любого иглогрива.", description = nil, progress = "Величайшие разведчики моего племени издавна отличались несравненной меткостью, и ни одному разбойнику *фыркает* даже и не снилась подобная стремительность в битве.\n\nПринеси мне 4 кровавых осколка, и превзойдешь ловкостью любого иглогрива.", completion = "Да будет верной твоя цель и метким оружие, |3-6(орк).\n\nДух Агамаггана пребывает с тобой. *фыркает* Возвращайся, если захочешь. Кривозуб снова благословит тебя, если будет на то воля великого кабаньего бога. *фыркает*", rewards = "Вы изучите:\n\nЛовкость Агамаггана"},
[5044] = {title = "Мудрость Агамаггана", objective = "Сила Агамаггана помогает шаманам и рудознатцам иглогривов *фыркает* в бою и во время проведения ритуалов.\n\nЕсли ты тоже желаешь обрести благословение Агамаггана, принеси мне 4 кровавых осколка, и Кривозуб тебе поможет. *фыркает*", description = nil, progress = "Сила Агамаггана помогает шаманам и рудознатцам иглогривов *фыркает* в бою и во время проведения ритуалов.\n\nЕсли ты тоже желаешь обрести благословение Агамаггана, принеси мне 4 кровавых осколка, и Кривозуб тебе поможет. *фыркает*", completion = "Теперь враги будут трепетать от одного твоего вида, |3-6(нежить). *фыркает*\n\nПоведай Кривозубу о своих битвах, когда мы встретимся в следующий раз – в этой жизни или в следующей. *фыркает*", rewards = "Вы изучите:\n\nМудрость Агамаггана"},
[5045] = {title = "Высокий дух", objective = "Высокий дух – благо для всех воинов. *фыркает* Он ведет к победе, даже когда надежды уже нет. Племя Иглогривых знает об этом. *фыркает* Мы ценим свою связь с Агамагганом больше доблести *фыркает* в бою.\n\nПринеси мне 4 кровавых осколка, и ты получишь благословение духа перед тем, как идти в бой. *фыркает*", description = nil, progress = "Высокий дух – благо для всех воинов. *фыркает* Он ведет к победе, даже когда надежды уже нет. Племя Иглогривых знает об этом. *фыркает* Мы ценим свою связь с Агамагганом больше доблести *фыркает* в бою.\n\nПринеси мне 4 кровавых осколка, и ты получишь благословение духа перед тем, как идти в бой. *фыркает*", completion = "Наши величайшие воины и величайшие шаманы *фыркает* позавидовали бы твоей силе воли, |3-6(нежить).\n\nТеперь, зная, что иглогривам не остановить тебя, ты нанесешь еще больший урон племени Вздыбленной Щетины. *фыркает*", rewards = "Вы изучите:\n\nВысокий дух"},
[5046] = {title = "Иглошкура", objective = "Идущему в бой *фыркает* защита не помешает. Кости должны быть крепкими, а шкура толстой. *фыркает* Мое племя отлично знает об этом, и, помимо дарованных нам от природы игл и толстой шкуры, *фыркает* мы защищаем себя и другими способами. Перед тем как идти на войну, мы просим Агамаггана защитить нас от урона.\n\nПринеси мне 4 кровавых осколка, *фыркает* и я дарую тебе ту же защиту.", description = nil, progress = "Идущему в бой *фыркает* защита не помешает. Кости должны быть крепкими, а шкура толстой. *фыркает* Мое племя отлично знает об этом, и, помимо дарованных нам от природы игл и толстой шкуры, *фыркает* мы защищаем себя и другими способами. Перед тем как идти на войну, мы просим Агамаггана защитить нас от урона.\n\nПринеси мне 4 кровавых осколка, *фыркает* и я дарую тебе ту же защиту.", completion = "В бой, |3-6(орк)!", rewards = "Вы изучите:\n\nИглошкура"},
[5047] = {title = "Пип Смышлен, к вашим услугам!", objective = "Переговорите с Малифоем Черномолотом в Круговзоре.", description = "Разыщи Малифоя Черномолота в Круговзоре, <класс>. Скажи ему, что с Пипом все в порядке и что костюмчик исправно работает.\n\nИ передай ему вот что...\n\n*Пип вручает вам ярко светящийся кусок мяса.*\n\nЯ его вырезал из внутренностей одной зверюги во время своих вынужденных каникул.\n\nГотов поспорить, Малифой очень подробно тебе растолкует, что можно сделать с мясом этого чудища!\n\nКстати, ты знаешь, где Круговзор? Это в Зимних Ключах.", progress = "Да?", completion = "Он жив? Костюм цел? А что это там у тебя?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5048] = {title = "Добросердечная Эмма", objective = "Найдите в Штормграде старушку Эмму и узнайте, действительно ли она – Эмма Фелстоун. Если да, то, может, ей понравится та посылочка, что собрала для нее Джанис Фелстоун.", description = "Это злобная старушенция и к тому же, весьма вероятно, уже с катушек съехала... Но записи указывают, что старушка Эмма как раз вполне может являться той самой Эммой Фелстоун.\n\nВозможно, вы видели старушку Эмму бредущей по городу – она разговаривает сама с собой, иногда неся совершенно невнятный вздор. Но она никому и ничему не мешает, так что горожане, в большинстве своем, оставили ее в покое.\n\nОбдумав все, я бы сказал, что старушка Эмма и в самом деле – Эмма Фелстоун. Можете сами спросить у нее, не Фелстоун ли ее фамилия.", progress = "Я поросила бы вас не топтать мою лужайку, но, как видите, у меня ее нет.", completion = "Мое имя и в самом деле Эмма Фелстоун – но меня впервые так называют за много лет. Кто... кто вы?\n\nВы говорите, что знали... мою сестру?! Она до сих пор жива? Да что это я – конечно же, нет. Когда чума охватила Лордерон, я ожидала самого худшего. Так много моих родственников погибло... или еще хуже того. И вот я здесь, сумасшедшая старушка Эмма, одна-одинешенька. Кто же вы – разоритель могил или что? Ищете следующую жертву?\n\nЧто... у вас посылка для меня от сестры?", rewards = "Вы получите:\n\n"},
[5049] = {title = "Грусть Иеремии", objective = "Найдите в Подгороде Иеремию Пэйсона и выясните, в самом ли деле он Иеремия Фелстоун. Если да, передайте ему посылку от Джанис Фелстоун.", description = "Мне удалось выяснить, что тот, кого ты ищешь, – он же получатель посылки – это Иеремия Пэйсон, продавец тараканов в Подгороде.\n\nМне всегда казалось, что для торговли тараканами нужны особые личные качества. Не сомневаюсь, тебя ждут великие дела, <класс>. Ступай, меняй мир к лучшему. Впрочем, позволь и мне поучаствовать в столь великих событиях и приоткрыть завесу тайны: он находится недалеко от банка, в стороне от одной из дорожек.", progress = "Всякий раз, как кто-то наступает на таракана, я плачу. Не доводи меня до слез.", completion = "Я не пользовался этим именем много лет... Да, некогда, до того прекрасного момента, когда я влился в ряды нежити, меня так звали.\n\nТак ты знал мою сестру... или, точнее, недавно говорил с моей сестрой?\n\nОна умерла.\n\nЧетыре года назад.\n\nЗнаешь, не будь у меня такие хрупкие кости, я бы с радостью тебя пнул. Глумишься над чужим горем?\n\nЧто... у тебя посылка от моей сестры?!", rewards = "Вы получите:\n\n"},
[5050] = {title = "Оберег удачи", objective = "Отнесите половинку талисмана Джанис Фелстоун в Западные Чумные земли.", description = "Кажется, я была неправа насчет тебя и должна извиниться. Сестра прислала мне ряд личных вещей, в том числе – ха-ха – документы на ферму Фелстоун. Я погожу предъявлять на нее права.\n\nЕсли призрак моей сестры не может упокоиться и привязан к ферме... может быть, ты вернешь ей это? Это половина талисмана; вторую носил ее муж.\n\nМожет быть, она обретет покой, если узнает, что я получила посылку?", progress = "Джон, милый... Это ты? Мне так холодно...", completion = "Вы отдаете половинку талисмана призраку. Джанис выжидающе смотрит на вас.\n\n\"Милый, а где твоя половина талисмана? Нам не быть вместе, не собрав его воедино. Милый... Ты меня видишь?\"", rewards = "Вы получите:\n\n"},
[5051] = {title = "Вторая половина", objective = "Отыщите вторую половину оберега Удачи на ферме Фелстоун в Западных Чумных землях и соберите его.\n\nОтдайте оберег Удачи Джанис Фелстоун.", description = "Несчастный призрак продолжает причитать:\n\n\"Мне холодно, Джон. Принеси мне свой оберег, и мы снова будем вместе! Скорее, Джон, пока чума не превратила нас в жутких тварей! Я не вижу тебя, Джон... Но знаю, ты рядом. Я чувствую.\"\n\nБыть может, если найти вторую половину оберега и собрать его воедино, душа Джанис Фелстоун обретет покой.", progress = "Джон, не давайся в руки вурдалаков... Не отдавай им меня... Гнусные вурдалаки, оберег защитит нас.", completion = "Вы отдаете целый оберег Удачи призраку Джанис Фелстоун. Взяв его в руки, она моментально преображается. Призрачный облик слегка мерцает, а девушка устремляет на вас ясный, хоть и грустный, взор.\n\n\"Ты освободил меня... Мне больше не нужен этот оберег. Возьми его, быть может он принесет тебе не меньшее утешение, чем мне.\"", rewards = "Вы получите:\n\nОберег Удачи из камня Скверны"},
[5052] = {title = "Кровавые осколки Агамаггана", objective = "Принесите кровавый осколок Кривозубу в Лагерь Таурахо в Степи.\n\nСоберите побольше кровавых осколков, и он одарит вас силой, дарованной ему Агамагганом.", description = "Кровь повлияла не только на шипы *фыркает*, но и на другие аспекты земли: среди прочих минералов попадаются кроваво-красные камни. Племя Дыбогривов выкапывает эти осколки и носит с собой как тотемы *фыркает*, и они дают им силы в бою и помогают творить заклинания. *фыркает*\n\nСекреты их магии мне известны.\n\nПринеси Кривозубу один кровавый осколок, и ты все поймешь. Принеси Кривозубу много осколков, и он благословит тебя. Сильна магия иглогривов, ведь это магия самого Агамаггана! *фыркает*", progress = "Наши племена селятся в тех областях Степей, где растут колючки, *фыркает* потому что это священные места. И первейшее из них – это земли Иглошкурых. Тело Агамаггана составляет все эти земли, но особенно хранимы холмы, потому что вход в них сделан из его огромной пасти! *фыркает* Она поглощает всех неверных и выплевывает их тела, когда он хорошенько прожует их! *фыркает*\n\nАгамагган оставил свое тело, чтобы защитить нас, и щедро делится своим духом, чтобы мы защищали его. *фыркает*", completion = "Да, ты понимаешь. *фыркает* Мои слова для тебя – не пустой звук, |3-6(нежить). Быть может, Кривозуб и заключен в клетку, но что клетка для силы Агамаггана! *фыркает*\n\nКасание осколка, какое забытое ощущение, |3-6(нежить). \n\nЗнаешь, каково это – чувствовать себя отрезанным от силы?\n\nНо об этом в другой раз. Я обещал поделиться с тобой сведениями. Я обещал тебе силу Агамаггана. Мой народ отвернулся от Кривозуба. Теперь они падут от твоей руки. *фыркает*", rewards = "Вы получите:\n\n"},
[5054] = {title = "Урсиус из щербозубов", objective = "По просьбе Шторма Призрачное Копыто в Круговзоре в Зимних Ключах убейте Урсиуса.", description = "В заснеженных горах Зимних Ключей, на северо-западе, умелый охотник идет по следу своей добычи… Я говорю о медведе-щербозубе Урсиусе – звере ловком и умном.\n\nЯ посылаю тебя в бой против него. Он бродит по холмам к северо-западу от Круговзора. Найди его и начни охоту на него – раньше, чем он поймет твои намерения.\n\nВсе, кто шли на Урсиуса, вскоре понимали, что они добыча, а отнюдь не охотники. Так что будь начеку.", progress = nil, completion = "Задание было непростым, но тебе сопутствовал успех. Только не думай так сразу, что тебе удалось произвести на меня впечатление, Томпсон.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5055] = {title = "Убить Брумеран", objective = "Убейте Брумеран по просьбе Шторма Призрачное Копыто в Круговзоре в Зимних Ключах.", description = "Быстрая и умная, Брумеран тихо скользит по заснеженным просторам южных окраин Зимних Ключей. Но пусть тебя не обманывает ее грация – она отнюдь не безопасна. Все, кто встает у нее на пути, расплачиваются за это – частенько своими собственными жизнями.\n\nНайди Брумеран среди химер Холодного Ветра. Срази ее, а затем возвращайся ко мне.", progress = "Брумеран ждет тебя, Канц.", completion = "Да. Ты вернулся. Теперь я верю, что охота – твое призвание. Ты встретился с самой свирепой из тварей и вернулся превзойдя мои ожидания.\n\nТеперь ты готов к моему последнему испытанию.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5056] = {title = "Ши-Ротам", objective = "Убейте Ши-Ротам для Шторма Призрачное Копыто.", description = "На севере Зимних Ключей, в районе, который называют Уступ Ледопардов, обитают огромные кошки. Их предводительница известна под именем Ши-Ротам. Если тебе удастся сразить матриарха ледопардов, ты завоюешь уважение в глазах своих сородичей.\n\nОтправляйся обратно в глушь. Придя на место, добудь священного мяса ледопардов. Найди камень Ши-Ротам и помести мясо на него. Мясо растерзанных подданных заставит их предводительницу Ши-Ротам явиться в гневе.\n\nБудь <готов/готова> встретиться с ней лицом к лицу и сразить ее.", progress = nil, completion = "Ты доказал как свою силу, так и решимость. Еще много испытаний ждет тебя впереди. Я показал тебе все, что мог.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКинжал Охотника на тварейКлинок загонщика\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[5057] = {title = "Прежние свершения", objective = "Отнесите Знак Шторма Призрачное Копыто Мелору Каменное Копыто в Громовой Утес.", description = "Еще раньше, чем вы пришли ко мне поговорить, <имя>, я слышал о ваших деяниях… что у вас есть непреодолимое желание проявить себя, что вы <класс> с отменными способностями, и теперь я знаю, что все это было правдой.\n\nТе, кто добивается таких успехов, заслуживают признания. Отнесите этот знак в Громовой Утес моему другу Мелору Каменному Копыту. Уверен, что он вспомнит и вас, и ваши подвиги. Расскажите ему о своих недавних достижениях. И никогда не забывайте о том, что свершили сегодня.", progress = nil, completion = "Мы учимся благодаря жизненным испытаниям, Томпсон. Я уверен, что в результате ты стал лишь сильнее и мудрее. Ты сильно повзрослел с того момента, когда мы общались впервые.\n\nПрими это в память о тех сложных заданиях, с которыми ты справился, и знай, что ты навсегда завоевал мое уважение и восхищение.", rewards = "Вы получите:\n\nЗнак Охотника"},
[5058] = {title = "Дневник миссис Далсон", objective = "В дневнике с пожелтевшими от времени страницами открыта последняя запись:\n\n\"Гарольд превратился в нежить, и я не знаю, что теперь будет. Я из последних сил утащила его в единственное место, которое можно надежно запереть. Я держу ключ при себе, будем надеяться, что моя уловка сработает...\n\nНадеюсь, я смогу выбраться отсюда, но для этого нужны деньги. Все наши вещи в шкафу... и, кажется, Гарольд держал ключ от него при себе.\n\nПора мне отдохнуть, я смертельно устала.\"", description = nil, progress = nil, completion = nil, rewards = nil},
[5059] = {title = "Под замком", objective = "Дверь в служебное помещение потрескалась, будто кто-то долго и упорно пытался ее выломать. В настоящий момент она заперта снаружи.\n\nПодергав за ручку, мы слышите изнутри утробные стоны! Что бы ни скрывалось внутри, оно кажется совсем недружелюбным.", description = nil, progress = "Дверь в служебное помещение потрескалась, будто кто-то долго и упорно пытался ее выломать. В настоящий момент она заперта снаружи.\n\nПодергав за ручку, мы слышите изнутри утробные стоны! Что бы ни скрывалось внутри, оно кажется совсем недружелюбным.", completion = "Вы отпираете дверь ключом, обнаруженным на скелете миссис Далсон. Наружу выскакивает кровожадный вурдалак, который сидел в заперти неизвестно сколько лет.\n\nСудя по леденящему кровь воплю, бывшего фермера Далсона уже не спасти.", rewards = nil},
[5060] = {title = "Под замком", objective = "Перед вами массивный шкаф, надежно запертый на врезной замок. Дверцы шкафа сильно исцарапаны. Судя по всему, его не раз пытались взломать, чтобы посмотреть, что внутри.\n\nПохоже, без ключа этот шкаф не открыть.", description = nil, progress = "Перед вами массивный шкаф, надежно запертый на врезной замок. Дверцы шкафа сильно исцарапаны. Судя по всему, его не раз пытались взломать, чтобы посмотреть, что внутри.\n\nПохоже, без ключа этот шкаф не открыть.", completion = "Ключ, взятый из останков фермера Далсона, идеально подходит к замку. Двери шкафа распахиваются. Внутри оказывается несколько уцелевших предметов, которые кажутся весьма ценными.", rewards = "Вы получите:\n\nДробовик фермера ДалсонаФамильное обручальное кольцо Далсона"},
[5061] = {title = "Водный облик", objective = "Вернитесь в Дарнасс и покажите Матренгилу Медвежьей Лапе свою подвеску Морского Льва.", description = "Ты <завершил/завершила> обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику,  Матренгилу Медвежьей Лапе в Дарнасс. Покажи ему свою подвеску и докажи, что ты <готов/готова> усвоить его уроки. Он завершит твое обучение, благодаря которому ты станешь <единым/единой> с водой.\n\nДоброго пути, <юный друид/дева-друид>. Мы еще встретимся.", progress = "Весть о твоем возвращении в Дарнасс опередила тебя, хотя я хочу увидеть доказательства того, что ты усвоил уроки Лунной поляны прежде, чем стану учить тебя принимать водный облик.\n\nЕсть ли у тебя подвеска Морского Льва?", completion = "Великолепно, Иселор. Ты готов принимать водный облик, и я с радостью научу тебя.\n\nА также, в знак признания твоих успехов в двух испытаниях, я даю тебе вот это. Надеюсь, тебе приятно будет присоединить эту вещь к своему снаряжению защитника Природы и хранителя равновесия.", rewards = "Следующее заклинание будет наложено на вас:\n\nВодный облик\n\nВы получите:\n\nПояс Водолея"},
[5062] = {title = "Священное пламя", objective = "Соберите 10 листов огненной агавы и поговорите с Магатой Зловещим Тотемом на Вершине Старейшин в Громовом Утесе.", description = "Арикара очень опасна,  и мы должны как можно быстрее разделаться с ней. Для того чтобы привлечь это чудовище, тебе нужно будет разжечь священный огонь жизни.\n\nСобери немного редкой огненной агавы и отнеси ее Магате Зловещий Тотем. Она живет в Громовом Утесе, на Вершине Старейшин. Магата – очень могущественная шаманка, владеющая тайной приготовления зачарованного порошка из огненной агавы.\n\nОгненную агаву можно собрать на Кипящем озере, это к востоку отсюда.", progress = "Значит, Мотега Огненная Грива сообщает об Арикаре... Хм, это дурные вести.\n\n*Магата оглядывается вокруг.*\n\nАрикара – это смертоносная тварь, рожденная лишь для того, чтобы мстить тем, кто совершает злодеяния.\n\n*Магата улыбается.*", completion = "Прекрасно, вы собрали достаточно огненной агавы. Эта редкая трава растет лишь в Тысяче Игл, и она поможет мне разбудить священное пламя жизни.\n\n*Магата начинает зачаровывать огненную агаву.*", rewards = "Вы получите:\n\n"},
[5063] = {title = "Шапка Алого Ученого", objective = "Для изготовления шапки Алого Ученого вам нужно принести Малифою Черномолоту 1 Безупречную звериную шкуру; 5 кусков потертого шовного материала поганища; 8 чародейских кристаллов; 5 зачарованных алых нитей. \n\nВы также должны будете уплатить 50 золотых монет за изготовление головного убора.", description = "Головного убора лучше этого тебе, быть может, и не придется увидеть. Из безупречной звериной шкуры наши опытные мастера изготовят потрясающую шляпу, о какой может только мечтать любой иллюзионист!\n\nПятьдесят золотых и предметы по списку – и твою голову украсит шапка Алого Ученого.\n\n*Безупречная звериная шкура.\n\n*Потертый шовный материал поганища.\n\n*Чародейские кристаллы.\n\n*Зачарованная алая нить.\n\nИ УЗРИШЬ ТЫ ЧУДО!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nШапка Алого Ученого"},
[5064] = {title = "Наблюдение за Зловещим Тотемом", objective = "Найдите и заберите три тайные записки на Пике Темного Облака.", description = "<имя>, вы уже помогали нам, поэтому я доверю вам еще одно важное задание. Клан Зловещий Тотем явно что-то замышляет: недавно мы видели, как в их поселение приходили какие-то странные путники. Потом нам удалось узнать, что важные записи они хранят в трех разных сундуках Пика Темного Облака.\n\nЕсли вам удастся достать эти документы, я щедро вас вознагражу.", progress = "Вы выяснили, что задумал клан Зловещего Тотема?", completion = "Великий тотем духов! Какие ужасные новости! Я немедленно начну готовиться, кто знает, что нас ждет...\n\nВот, Усамыч, как я и обещал, это награда за вашу храбрость и услугу.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНаплечники ПустыниСапоги для тундрыГоремычные накулачники\n\nВы также получите:\n\n"},
[5065] = {title = "Утраченные таблички Мошару", objective = "Принесите третью и четвертую таблички Мошару геологу Железному Башмаку в Танарис.", description = "Тот тролль обманул тебя. В тех двух табличках шла речь о пленении сущности Хаккара, но легенда этим не исчерпывается. Я долго изучал этот вопрос, и обнаружил, что табличек Мошару шесть, а не две! Шесть!\n\nИ боюсь, нас не порадует то, что в них записано.\n\nНайди третью и четвертую таблички. Они находятся в Восточных Чумных землях, у троллей из племени Моходеров. Найди их и принеси мне.", progress = "Ты принес мне таблички? Боюсь, в них написано о великой опасности, грозящей нашему миру.", completion = "Ты нашел их! Отлично!\n\nСпасибо, Шэдоустайл. Я изучу эти тексты и расшифрую их значение.\n\nДля тебя же у меня есть еще одно задание...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5066] = {title = "Призыв к оружию: Чумные земли!", objective = "Найдите командира Ашлама Отважного Кулака в лагере Промозглого Ветра на севере Альтеракских гор.", description = "Слушайте, слушайте все! Я обращаюсь к героям, и да услышат они мою речь!\n\nВКороль Штормграда призывает к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Стало известно, что над Чумными землями вновь сгущаются тучи!\n\nГерои королевства! Ищите командира Ашлама Отважного Кулака! Его гарнизон вы найдете в лагере Промозглого Ветра на севере Альтеракских гор!", progress = nil, completion = "Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!\n\nЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.", rewards = "Вы получите:\n\n"},
[5067] = {title = "Поножи Аркана", objective = "Для изготовления Поножей Аркана вам нужно принести Малифою Черномолоту следующее: 1 безупречную звериную шкуру; 5 кусков потертого шовного материала поганища, 5 арканитовых слитков, 5 порций бальзамировочного состава Снегошепота; \n\nВам придется также заплатить 50 золотых монет за изготовление этого предмета.", description = "В то время как изготовление такого предмета еще никому не удавалось, считается, что это все же возможно – при правильном стечении обстоятельств.\n\nЕсли искатель тайных знаний желает наделить поножи могучей силой, вот что должно быть найдено:\n\n*Безупречная звериная шкура.\n\n*Потертый шовный материал поганища.\n\n*Арканитовые Слитки.\n\n*Бальзамировочный состав Снегошепота.\n\nИ УЗРИШЬ ТЫ ЧУДО!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПоножи тайной магии"},
[5068] = {title = "Кираса кровавой жажды", objective = "Для изготовления кирасы кровавой жажды вам нужно будет принести Малифою Чернобойцу следующее: 1 безупречную звериную шкуру; 10 кусков потертого шовного материала поганища; 5 арканитовых слитков; 5 тенекож.\n\nВы также должны будете уплатить 50 золотых монет за изготовление доспеха.", description = "Говорят, что кираса кровавой жажды была создана лишь один раз, и изготовлена она была для легендарной убийцы Гароны. Суждено ли еще одному подобному доспеху увидеть свет? Сомнительно...\n\nИ все же! Наши мастера могут воспроизвести этот доспех, если дать им необходимые компоненты:\n\n*Безупречную звериную шкуру.\n\n*Потертый шовный материал мясника.\n\n*Арканитовые Слитки.\n\n*Тенекожу.\n\nИ УЗРИШЬ ТЫ ЧУДО!", progress = "До тех пор, пока не соберешь все необходимое, ты лишь попусту тратишь мое время.", completion = "Я уж думал, что не доживу до этого дня.\n\nДостижение такого масштаба может превзойти лишь награда за него.", rewards = "Вы получите:\n\nКираса кровавой жажды"},
[5081] = {title = "Миссия Максвелла", objective = "Отправляйтесь на пик Черной горы и устраните воеводу Вуна, вождя Омокка и повелителя Змейталака. По выполнении задания вернитесь к маршалу Максвеллу.", description = "Эти сведения заполняют последние пробелы в наших данных о пике Черной Горы.\n\nМы должны напасть со всей решительностью, <имя>.\n\nПервым делом нужно убить их воеводу, Вуна. Без его боевых планов орки Черной Горы будут ввергнуты в хаос.\n\nСледом должен умереть вождь огров, Омокк. Трусливые огры Черной Горы окажутся беспомощны.\n\nИ, наконец, повелитель всей цитадели зла: Вурмталак. Когда он умрет, командование будет обезглавлено.", progress = nil, completion = "Отличная работа, Август. По меньшей мере нам удалось выиграть время – а на счету каждая минута.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОковы ВурмталакаТесьма-фиксатор ОмоккаНамордник ХаликонПояс Вос'гаджинПоганые захваты Вуна\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[5082] = {title = "Угроза со стороны Зимней Спячки", objective = "По просьбе Доновы Снегоноры из Зимних Ключей убейте 8 землепроходцев, 8 дозорных и 8 тотемистов из племени Зимней Спячки.", description = "Сюда в Зимние Ключи я пришла, чтобы изучать Источники Ледяного Пламени. Я заметила, что у воды здесь какие-то… странные свойства. Мне пока не удалось определить источник этих свойств, да и, по правде говоря, в последнее время у меня возникли кое-какие сложности, из-за фурболгов племени Зимней Спячки.\n\nИх, кажется, тянет к источникам – так же, как и меня. Они яростно защищают воду и не подпускают меня близко к двум большим ключам к северу отсюда.\n\nЯ хотела бы продолжить свои изыскания. Ты не поможешь мне?", progress = "Буду очень признательна за помощь!", completion = "Огромное спасибо, Томпсон! Теперь я могу вернуться к работе.\n\nНашел что-нибудь интересное в поселении Зимней Спячки?", rewards = "Вы получите:\n\n"},
[5083] = {title = "Огненная вода племени Зимней Спячки", objective = "Принесите Донове Снегоноре пустую флягу из-под огненной воды.", description = "Тот сосуд, что вы нашли у фурболга племени Зимней Спячки, пуст, но внутри осталось несколько капель странной зеленой жидкости. Он почти сияет.\n\nОбнаружили ли вы нечто важное?\n\nВозможно, Донова Снегонора могла бы что-то вам разъяснить, поскольку она уже довольно давно живет у горячих ключей.", progress = "Что это у тебя?", completion = "Это было у фурболга из племени Зимней Спячки?", rewards = "Вы получите:\n\n"},
[5084] = {title = "Поддавшиеся порче", objective = "Исследуйте поселение фурболгов из племени Мертвого Леса в северной части Оскверненного леса в поисках ключа к разгадке.", description = "Зеленая жидкость… немного напоминает мне жижу, которую я видела, когда пробиралась через Оскверненный лес. И я видела несколько гонцов племени Зимней Спячки, входящих во владения Древобрюхов… Возможно, это имеет отношение к той склянке, что вы нашли, <имя>.\n\nСразу за Крепостью Древобрюхов, в Оскверненном лесу, живет большая группа фурболгов. Они зовутся племенем Мертвого Леса, и давно попали под власть скверны. Да, фурболги этого племени совершенно безумны. Может, сходишь и поищешь свидетельства того, что между племенами Зимней Спячки и Мертвого Леса есть какое-то сообщение?", progress = nil, completion = "В котле кипит гнилостная, отвратительно пахнущая субстанция…", rewards = "Вы получите:\n\n"},
[5085] = {title = "Таинственная слизь", objective = "Вернитесь к Донове и сообщите ей о своих находках.", description = "Зеленая субстанция внутри котла кажется точно такой же, какую вы обнаружили в сосуде. Это странное слизистое вещество может оказаться таким же полным скверны, как и фурболги, что его изготовили…\n\nЕсли фурболги племени Зимней Спячки его используют, значит ли это, что вскоре они окажутся в таком же состоянии, как и племя Мертвого леса?\n\nЛучше всего сообщить об этих находках Донове, прихватив и образец жидкости из котла.", progress = "Надеюсь, вы что-нибудь нашли, Томпсон. Фурболги племени Зимней Спячки становятся все агрессивнее!", completion = "Ты очень находчив, Томпсон. Так ты полагаешь, что фурболги племени Зимней Спячки побывали в лагере Мертвого Леса?", rewards = "Вы получите:\n\n"},
[5086] = {title = "Ядовитый Ужас", objective = "Соберите 3 капли ядовитого ужаса и принесите их Донове Снегоноре в Зимние Ключи.", description = "Я изучила образцы, с которыми вы вернулись, и хотя точно пока ничего сказать не могу, я думаю, что в них есть следы ядовитых компонентов. Однако, единственный способ узнать наверняка – это найти что-то для сравнения.\n\nЯ думаю, что фурболги Мертвого Леса могут собирать эти компоненты с других зараженных скверной существ в Оскверненном лесу: в частности, с элементалей, населяющих Железнолесье, которых называют ядовитым ужасом.\n\nСобери для меня несколько образцов для сравнения, но будь <осторожен/осторожна> – там очень опасно!", progress = "Я думаю, мы начинаем понимать, что тут происходит, Томпсон.", completion = "Мне нужно сравнить с этими образцами то вещество, что ты нашел в котле – тогда, я уверена, мы узнаем больше.", rewards = "Вы получите:\n\n"},
[5087] = {title = "Гонцы Зимней Спячки", objective = "Найдите гонцов из племени Зимней Спячки и не позвольте им донести их груз до их деревни.", description = "Очень интересно, <имя>…\n\nЕсли эту ядовитую субстанцию смешать с водой из горячих ключей, она потеряет свою токсичность, и остается лишь способность временно воздействовать на тех, кто такую смесь употребляет. Наверное, из-за этого племя Зимней Спячки и защищает источники столь яростно: они необходимы фурболгам для очистки огненной воды.\n\nМы должны положить этому конец: прекратить контакты между племенами Зимней Спячки и Мертвого Леса. Группа гонцов курсирует между поселением Зимней Спячки и Оскверненным лесом. Найди их, убей и забери то, что у них будет с собой.", progress = "Посмотрим, что случится, когда фурболги племени Зимней Спячки не получат своей огненной воды!", completion = "*Донова изучает содержимое ящика.*\n\nИнтересно, делает ли употребление этой субстанции фурболгов более агрессивными? На вид они кажутся намного крупнее…", rewards = "Вы получите:\n\n"},
[5088] = {title = "Арикара", objective = "Убейте Арикару и в качестве доказательства принесите ее останки вместе с воспламеняющим порошком Мотеге Огненной Гриве на заставу Белого Плеса.", description = "Возьмите этот зачарованный порошок и зажгите священный огонь жизни в Тысяче Игл. Сделать это нужно на Пике Темного Облака, на отдельной скале, где находится местное кладбище.\n\nЯ зачаровала порошок так, чтобы он привлек Арикару, <имя>.\n\nБоюсь, что она охотится за Кэрном Кровавым Копытом – из-за него обычаи тауренов претерпели слишком много изменений, и это могло разозлить чудовище. Поспешите, <класс>, вы можете не успеть!", progress = "Вы убили смертоносную змею Арикару, Вудупипл?", completion = "Ерунда какая-то. Зачем Арикаре охотиться за Кэрном Кровавым Копытом? Но Магата не может ошибаться, она наша самая могущественная шаманка.\n\n*Мотега качает головой.*\n\nВ любом случае, вы очень помогли Орде, и деяние ваше не останется незамеченным. Пожалуйста, выберите себе любую награду.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГрубый боевой молотЖалострельный жезлЗвенящий щит\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[5089] = {title = "Приказ генерала Драккисата", objective = "Отнесите приказ генерала Драккисата маршалу Максвеллу в Пылающие степи.", description = "Вы обыскали труп убитого драконида и обнаружили записку, содержание которой показалось вам важным: письмо от его непосредственного начальника, генерала Драккисата, в котором упоминается некий протокол.\n\nВнутренний голос подсказывает, что это письмо следует показать маршалу Максвеллу.", progress = "Что там у тебя, Эст?", completion = "Мда... теперь все усложняется...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5090] = {title = "Призыв к оружию: Чумные земли!", objective = "Разыщите командира Ашлама Отважного Кулака в лагере Промозглого Ветра к северу от Альтеракских гор.", description = "Слушайте все! Все герои – слушайте!\n\nКоролевство Штормграда призывает всех к оружию! Все способные держать оружие – на защиту севера Восточных королевств против черной угрозы Плети! Новая опасность надвигается из руин Чумных земель!\n\nГерои королевства – собирайтесь к командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра к северу от Альтеракских гор!", progress = nil, completion = "Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!\n\nЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.", rewards = "Вы получите:\n\n"},
[5091] = {title = "Призыв к оружию: Чумные земли!", objective = "Разыщите командира Ашлама Отважного Кулака в лагере Промозглого Ветра к северу от Альтеракских гор.", description = "Слушайте все! Все герои – слушайте!\n\nКоролевство Штормграда призывает всех к оружию! Все, кто способен держать оружие, – на защиту севера Восточных королевств против черной угрозы Плети! Новая опасность надвигается из руин Чумных земель!\n\nГерои королевства – собирайтесь к командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра к северу от Альтеракских гор!", progress = nil, completion = "Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!\n\nЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.", rewards = "Вы получите:\n\n"},
[5092] = {title = "Зачистка территории", objective = "Убейте 10 скелетов-свежевателей и 10 слюнявых вурдалаков на холме Печали.\n\nВернитесь к командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра в Западных Чумных землях.", description = "Поскольку западная и северная дороги, ведущие в Андорал, хорошо укреплены, я подумываю о нападении с востока, как наименее защищенной стороны. Плеть рассчитывает на защиту нежити, наводнившей холм Печали.\n\nПервым заданием будет зачистка холма Печали. Убей побольше скелетов и вурдалаков; по выполнении задания возвращайся ко мне!", progress = nil, completion = "Задание выполнено, Эфром! Отлично, отлично!\n\nПозволь наградить тебя за труды звонкой монетой из казны Штормграда. Советую потратить награду на подготовку к следующей битве... Ведь тебе придется войти в руины Андорала.\n\nГотовься! Будь бдителен!", rewards = "Вы получите:\n\n"},
[5093] = {title = "Призыв к оружию: Чумные земли!", objective = "Отыщите верховного палача Деррингтона. Его базовый лагерь находится у Бастиона, к востоку от Тирисфальских лугов и Подгорода.", description = "Внимайте моим словам, о герои! Орда призывает к решительным действиям!\n\nВсе, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли.\n\nХрабрецы, обращайтесь к верховному палачу Деррингтону. Он ждет вас в лагере у Бастиона, к востоку от Тирисфальских лугов!", progress = nil, completion = "Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!\n\nЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.", rewards = "Вы получите:\n\n"},
[5094] = {title = "Призыв к оружию: Чумные земли!", objective = "Отыщите верховного палача Деррингтона. Его базовый лагерь находится у Бастиона, к востоку от Тирисфальских лугов и Подгорода.", description = "Внимайте моим словам, о герои! Орда призывает к решительным действиям!\n\nВсе, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли.\n\nХрабрецы, обращайтесь к верховному палачу Деррингтону. Он ждет вас в лагере у Бастиона, к востоку от Тирисфальских лугов!", progress = nil, completion = "Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!\n\nЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.", rewards = "Вы получите:\n\n"},
[5095] = {title = "Призыв к оружию: Чумные земли!", objective = "Найдите верховного палача Деррингтона. Его базовый лагерь расположен в Бастионе к востоку от Тирисфальских лесов и Подгорода.", description = "Внимайте моим словам, о герои! Орда призывает к решительным действиям!\n\nВсе, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли.\n\nХрабрецы, обращайтесь к верховному палачу Деррингтону. Он ждет вас в лагере у Бастиона, к востоку от Тирисфальских лугов!", progress = nil, completion = "Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!\n\nЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.", rewards = "Вы получите:\n\n"},
[5096] = {title = "Вылазка в стан Алого Марша", objective = "Отправляйтесь в лагерь Алого ордена между полем Джанис и Слезами Далсона и уничтожьте командный шатер.\n\nРазместите в лагере знамя Плети и возвращайтесь к верховному палачу Деррингтону в Бастион, в Западные Чумные земли.", description = "Прежде чем заняться Андоралом, мы должны разобраться с Алым орденом, обосновавшемся в Дольном Очаге. Его приспешники разбили лагерь между полем Джанис и Слезами Далсона, так что мы оказались между двух огней – нам противостоят разом и Плеть, и Алый орден.\n\nМне кажется, надо их стравить между собой. Вот что я хочу тебе поручить: уничтожь командный шатер. Сожги его при помощи пламени в бутылке - вот, возьми в этом ящике. Сделав это, воткни посреди лагеря знамя Плети. При удаче, нас оставят в покое и займутся Плетью.", progress = "Налет на позиции Алого ордена даст нам время, необходимое для нападения на Андорал. Надеюсь, ты добился успеха?\n\nКоли так, мы должны действовать стремительно и тайно. Если Плеть и Алый орден не поддадутся на провокацию, нам против них не выстоять.", completion = "Отличная работа, Томпсон. Благодаря налету на Алый орден мы выиграли время. Я послал разведчика наблюдать за лагерем, чтобы убедиться, что прибывшее подкрепленея поддастся на провокацию.\n\nЕсли натиск ордена ослабеет, мы сможем рискнуть и устроить вылазку в Андорал. Это очень важно. Я бы хотел, чтобы этим тоже занялся ты – в конце концов, у тебя такой большой опыт.", rewards = "Вы получите:\n\n"},
[5097] = {title = "Сторожевые башни", objective = "Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен.\n\nОтметив все четыре башни, следует вернуть сигнальный факел командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра в Западных Чумных землях.", description = "Мы можем пометить будущие цели для наших войск при помощи магического устройства, сигнального факела. Мы подозреваем, что Плеть пользуется сторожевыми башнями Андорала для управления собственными войсками.\n\nТвоя цель – ворваться в Андорал и установить сигнальные факелы на всех четырех башнях. Устанавливать факелы надо в дверных проемах; они сами собой отметят всю башню. В сигнальном факеле всего пять зарядов, поэтому не трать их понапрасну.", progress = nil, completion = "Жрецы говорят, что со всех четырех башен идут четкие сигналы! Боюсь сглазить, но по-моему, ты только что выполнил очередную операцию без сучка, без задоринки! Отлично, Эфром!\n\nБашни помечены, и все готово к началу атаки. Пришло время сразиться с Плетью!", rewards = "Вы получите:\n\n"},
[5098] = {title = "Сторожевые башни", objective = "Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен.\n\nОтметив все четыре башни, следует вернуть сигнальный факел командиру Ашламу Смелонраву в лагерь Холодного Ветра в Западных Чумных землях.", description = "Мы можем поменить будущие цели для наших войск при помощи магического устройства, сигнального факела. Мы подозреваем, что Плеть пользуется сторожевыми башнями Андорала для управления собственными войсками.\n\nТвоя цель – ворваться в Андорал и установить силнальные факелы на всех четырех башнях. Устанавливать факелы надо в дверных проемах; они сами собой отметят всю башню. В сигнальном факеле всего пять зарядов, поэтому не трать их понапрасну.", progress = nil, completion = "Чернокнижники говорят, что со всех четырех башен идут четкие сигналы! Ты выполнил мои приказы с точностью, достойной закаленного бойца. Орда не забудет твоей верной службы!\n\nБашни помечены, и все готово к началу атаки. Пришло время сразиться с Плетью!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5101] = {title = "Lee's Ultimate Test Quest... of Doom!", objective = "Kill 6 sheep for Benny and then run like hell!\n\n\n\n\nJust kidding... about the running part.", description = "Bah! What do think this is, some kind of Test Quest? I be there even be typos in it!\n\nIf ya be thinkin' my quest is goin' ta be easy, then ya got another thing coming!\n\nKill me ten sheep (1933) and don't come back until you do!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nРыцарский длинный меч"},
[5102] = {title = "Кончина генерала Драккисата", objective = "Отправьтесь на пик Черной горы и устраните генерала Драккисата. По выполнении задания вернитесь к маршалу Максвеллу.", description = "Мы бьемся против этих тварей на двух фронтах – из столицы, Штормграда, мы бьем их в спину, а здесь, в Пылающих степях, мы стоим у самого их порога. Не теряй бдительности, <имя>. Никто не избегнет нашего гнева, как никто из наших не избегнул их гнева, который обрушился на наши дома и семьи.\n\nОтыщи этого генерала Драккисата и убей его!\n\nЗадание непростое, но и награда будет велика.", progress = nil, completion = "Следующий удар мы несомненно нанесем по драконьим лордам. Молодец, храбрый солдат Альянса! Отличная работа.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗнак ТиранииГлаз ЗверяПластита Чернорука\n\nВы также получите:\n\n"},
[5103] = {title = "Смерть в огне", objective = "Наверняка в этом мире есть кто-то, кто знает, что делать с этими рукавицами.", description = "От человека остался только обугленный скелет. Похоже, он умер буквально на расстоянии вытянутой руки от того, что пытался схватить, – неопалимых латных рукавиц.\n\nМожет, вам стоит забрать рукавицы и попробовать выбраться из огня?", progress = nil, completion = "Что это за...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5121] = {title = "Верховный вождь племени Зимней Спячки", objective = "По просьбе Доновы Снегоноры из Зимних Ключей убейте верховного вождя племени Зимней Спячки.", description = "Хотя нам по-прежнему известно очень мало о том, зачем фурболги используют эту странную субстанцию, я думаю, что лучше всего положить конец всему этому, пока ситуация не вышла из-под контроля.\n\nФурболги племени Зимней Спячки демонстрируют ненормальный уровень агрессии, и эта перемена в их поведении заставляет меня думать, что они, должно быть, выполняют приказ своего вождя. Скорее всего, мы не можем исправить тот вред, что уже нанесен, но я думаю, если их вождь будет убит, хуже они уж точно не станут.\n\nТебе нужно идти на восток, в деревню Зимней Спячки.", progress = nil, completion = "Большое тебе спасибо, Лавмэйкер. Я надеюсь, что смогу вернуться к своим исследованиям, не опасаясь нападения из засады. Пожалуйста, прими это от меня в качестве награды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОплечье Хрустального ветраПапоротникопульсный жакетИвовый хауберк\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[5122] = {title = "Медальон Веры", objective = "Укрывшись в этой часовне, я могу противостоять порче, заполняющей мое существо. Но если я покину эти стены, я немедленно превращусь в нежить. Я знаю, что есть на свете медальон, именуемый медальоном веры, который может дать мне силу противостоять порче. \n\nПрошу тебя, Димиллион, принеси мне медальон. Его охраняет безумный фанатик Малор Ревностный, один из Алых. Ты найдешь его в недрах бастиона Алого ордена в западной части Стратхольма.", description = nil, progress = "Укрывшись в этой часовне, я могу противостоять порче, заполняющей мое существо. Но если я покину эти стены, я немедленно превращусь в нежить. Я знаю, что есть на свете медальон, именуемый медальоном веры, который может дать мне силу противостоять порче. \n\nПрошу тебя, Димиллион, принеси мне медальон. Его охраняет безумный фанатик Малор Ревностный, один из Алых. Ты найдешь его в недрах бастиона Алого ордена в западной части Стратхольма.", completion = "Ты принес медальон! Теперь я смогу наконец покинуть священные стены и исполнить свой долг! \n\nЯ должен убить чудовище, из-за которых скверна поразила меня и многих моих братьев и сестер! Имя его – барон Ривендер.", rewards = nil},
[5123] = {title = "Последний фрагмент мозаики", objective = "Отнесите неразборчиво исписанный журнал Донове Снегоноре в Зимние Ключи.", description = "Записи, которые вы нашли у верховного вождя, кажутся обширными, но просмотрев пару страниц, вы понимаете, что не можете прочитать написанное. Все заметки написаны так коряво, что вы сомневаетесь, что кто-либо сможет что-то понять в них.\n\nНо, может быть, Донова сможет?..", progress = "Что это у тебя, Мну?", completion = "Что бы это значило? Ничего не могу разобрать…", rewards = "Вы получите:\n\n"},
[5124] = {title = "Огненные латные рукавицы", objective = "Принесите Малифою Черномолоту 6 зачарованных ториевых слитков, 2 субстанции Огня и 4 звездных рубина. Вам также нужно будет расстаться с неопалимыми латными рукавицами.", description = "Клянусь бородой Тауриссана! \n\nОткуда они у тебя?\n\nИ, что еще важнее, сможешь ли ты с ними расстаться? Само собой, я заплатил бы за столь благородный жест. \n\nВот что я тебе скажу, <имя>. Если отдашь мне эти неопалимые рукавицы, я научу тебя, как сделать себе пару хороших рукавиц. Все, что тебе нужно сделать – собрать для меня необходимое, чтобы я мог предложить тебе точный рецепт. \n\nДоговорились??\n\nВот список того, что мне нужно. С тебя – рукавицы, а я пока займусь незачарованным торием.", progress = "Время – деньги, Ек. И того, и другого мне всегда не хватает.", completion = "Как я и обещал, Ек, вот ваш рецепт! Я также добавлю кое-что от себя за ваши труды и самоотдачу. А то просто девать некуда!..", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЧертеж: огненные латные рукавицыОгненные латные рукавицы"},
[5125] = {title = "Слова Аурия", objective = "Я умираю, Арраон… но душа моя обрела спасение. Я так многим обязан тебе... Прошу, прими это... И продолжай биться за правое дело, храбрый |3-6(Друид)!", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nВоля МученикаКровь Мученика\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[5126] = {title = "История Лоракса", objective = "Поговорите с Лораксом. Выслушайте то, что он вам расскажет.", description = "Сатир расхаживает туда-сюда и разговаривает сам с собой. Решитесь ли вы задать ему вопрос?", progress = nil, completion = "*Лоракс смеется.*", rewards = "Вы получите:\n\n"},
[5127] = {title = "Демонова кузня", objective = "Отправляйтесь на пик Черной горы и найдите Горалука Треснувшую Наковальню. Убейте его, а потом воткните в труп окровавленную пику. Таким образом пика вытянет его душу и окрасится ей.\n\nКроме того, вам нужно найти заготовку рунической кирасы.\n\nОтнесите пику и кирасу Лораксу в Зимних Ключах.", description = "Лоракс заключает сделки, да, но он не имеет дел с никчемными смертными.\n\nС тобой, однако, я сделку заключу... возьми эту пику, она усилена мощной энергией скверны. Когда найдешь Горалука Треснувшую Наковальню, убей его и проткни этой пикой его остывающее сердце. Он продал свою душу, и она будет моей. Верни мне пику, а также кирасу, которую похитил этот вор, и я научу тебя тому, чему хотел научиться он.", progress = "Не поддайся соблазну…", completion = "Ты не нарушил договора. Душу я забрал. Награду я отдам.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЧертеж: выкованная демоном кирасаЭликсир истребления демоновСумка Поцелуя демона"},
[5128] = {title = "Слова верховного вождя", objective = "Отнесите неразборчиво исписанный журнал Келеку Стражу Неба в южную часть Оскверненного леса.", description = "Племя Зимней Спячки больше не представляет для меня угрозы, но если тебе по-прежнему хочется выяснить, что побудило фурболгов готовить и использовать эту странную огненную воду, думаю, вам стоит поискать Келека Стража Неба. \n\nОн принадлежит к группе, известной как Изумрудный Круг – это группа друидов, посвятивших себя работе над исцелением Оскверненного леса от порчи. \n\nКелек много работал с фурболгами – может быть, он сможет больше меня рассказать об этих записях. \n\nИ еще раз спасибо тебе, <имя>.", progress = "Изумрудный Круг благорасположен ко всем, |3-6(Шаман). Чем я могу вам помочь?", completion = "Да, если дадите мне немного времени, я, может быть, смогу перевести для вас то, что тут написано. \n\n*Келек пролистывает страницы.*\n\nКогда я смогу внимательно все просмотреть, я вам сообщу.\n\nСпасибо, что поделились этим со мной, Кастрол. О фурболгах из племени Зимней Спячки нет почти никаких сведений.", rewards = "Вы получите:\n\n"},
[5141] = {title = "Кожевничество: чешуя драконов", objective = "Принесите 2 прочные кирасы скорпида, 2 пары прочных перчаток скорпида и 10 потертых чешуек дракона Питеру Галену в Азшару. \n\nПо выполнении этого задания вы получите возможность обучения кожевничеству школы чешуи драконов. \n\nЕсли вы выполните это задание, вы не сможете изучать кожевничество школы традиций предков и школы силы стихий.", description = "Кожевничество школы чешуи драконов – непростое ремесло, однако весьма прибыльное. Я научу тебя изготовлять отличные кольчужные доспехи, но при одном условии. \n\nВыбрав этот путь, ты откажешься от изучения школ традиций предков и силы стихий. На пути к вершине мастерства ты <должен/должна> выбрать лишь одну из трех. Кроме того, я должен взглянуть на лучшие твои работы – в том числе на доспехи скорпида. И наконец, докажи мне, что ты <способен/способна> добыть основу нашего ремесла – чешую дракона.", progress = "Если ты готов принять это решение и из трех школ выбрать школу чешуи драконов, то я возьму тебя в ученики. Принеси мне то, что я просил, и мы начнем обучение.", completion = "Ты принял важное решение. Уверяю тебя, ты не пожалеешь о том, что выбрал школу чешуи драконов – это очень выгодное ремесло. \n\nЧтобы получить новые знания, просто побеседуй со мной, и я расскажу все, что тебе нужно.", rewards = "Следующее заклинание будет наложено на вас:\n\nКожевничество: чешуя драконов\n\nВы получите:\n\n"},
[5142] = {title = "Малышка Памела", objective = "Найдите Памелу Редпат.", description = "Многие погибли во время битвы при Дарроушире... и многие, избежавшие смерти, позавидовали мертвым.\n\nКогда битва началась, я спрятала мою племянницу Памелу и теперь не знаю, жива ли она. Я всего лишь странствующий дух, но мое сердце жаждет знать, все ли у нее хорошо.\n\nПожалуйста, <добрый/добрая:c> <класс>, не поищешь ли ты мою племянницу в Дарроушире? Это к востоку отсюда, за пустошью Гаррона.", progress = nil, completion = "Привет, я Памела. А ты кто?", rewards = "Вы получите:\n\n"},
[5143] = {title = "Кожевничество: традиции предков", objective = "Принесите дикарский кожаный жилет и дикарский кожаный шлем Кариссии Лунной Охотнице из Фераласа.\n\nВыполнив это задание, вы станете кожевником школы традиций предков.\n\nТакже вы лишитесь возможности изучать кожевничество школы чешуи драконов и школы силы стихий; убедитесь, что избрали именно этот путь, прежде чем выполнять задание.", description = "Чтобы постичь школу традиций предков, следует обрести понимание подлинной сути дикой природы. Я знаю, что ты уже владеешь искусством изготовления дикарского кожаного доспеха, и хочу завершить твое обучение.\n\nЗнай, <класс>: избрав этот путь, ты отказываешься от изучения школ чешуи драконов и силы стихий, изучать можно только одну из них. А теперь принеси мне свои лучшие дикарские кожаные доспехи. С них мы и начнем твое обучение.", progress = "Силы природы надлежит умиротворить прежде, чем пытаться использовать их в кожевенном деле. Принеси ко мне свою жертву этим силам, и я позабочусь о том, чтобы тебя услышали!", completion = "Ты пожертвовал лучшее, что у тебя было, и вскоре природа отплатит тебе сторицей. Когда мы завершим твое обучение, силы природы покорятся тебе.\n\nВ будущем, чтобы улучшить свое мастерство, просто обратись ко мне, и я сообщу тебе все, что ты захочешь знать.", rewards = "Следующее заклинание будет наложено на вас:\n\nКожевничество: традиции предков\n\nВы получите:\n\n"},
[5144] = {title = "Кожевничество: сила стихий", objective = "Принесите Саре Дубильщице 2 сердца огня, 2 сферы воды, 2 ядра земли и 2 дыхания ветра. \n\nВыполнение этого задания позволит вам изучать кожевничество школы силы стихий. \n\nКроме того, вы откажетесь от изучения  кожевничества школ чешуи драконов и традиций предков. Нужно быть уверенным, что выбрана верная школа, прежде чем выполнять задание.", description = "Я мастер кожевничества школы Стихии, и если ты хочешь открыть разум великим силам, я поделюсь с тобой всем, что знаю. \n\nНо знай, <класс>: выбирая этот путь, ты никогда уже не сможешь обучиться кожевничеству школы чешуи драконов и школы традиций предков, ибо из трех школ должно выбрать одну. Кроме того, мне требуется доказательство того, что ты в гармонии со всеми стихиями. Принеси мне чистейшие субстанции огня, воды, земли и ветра.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nКожевничество: сила стихий\n\nВы получите:\n\n"},
[5145] = {title = "Кожевничество: чешуя драконов", objective = "Принесите 2 прочные кирасы скорпида, 2 пары прочных перчаток скорпида и 10 потертых чешуек дракона Торкафу Оку Дракона в Бесплодные земли. \n\nПо выполнении этого задания вы получите возможность обучения кожевничеству школы чешуи драконов. \n\nЕсли вы выполните это задание, вы не сможете изучать кожевничество школы традиций предков и школы силы стихий.", description = "Кожевничество школы чешуи драконов – непростое ремесло, однако весьма прибыльное. Я научу тебя изготовлять отличные кольчужные доспехи, но при одном условии. \n\nВыбрав этот путь, ты откажешься от изучения школ традиций предков и силы стихий. На пути к вершине мастерства ты <должен/должна> выбрать лишь одну из трех. Кроме того, я должен взглянуть на лучшие твои работы – в том числе на доспехи скорпида. И наконец, докажи мне, что ты <способен/способна> добыть основу нашего ремесла – чешую дракона.", progress = "Если ты готов принять это решение и из трех школ выбрать школу чешуи драконов, то я возьму тебя в ученики. Принеси мне то, что я просил, и мы начнем обучение.", completion = "Ты принял важное решение. Уверяю тебя, ты не пожалеешь о том, что выбрал школу чешуи драконов – это очень выгодное ремесло. \n\nЧтобы получить новые знания, просто побеседуй со мной, и я расскажу все, что тебе нужно.", rewards = "Следующее заклинание будет наложено на вас:\n\nКожевничество: чешуя драконов\n\nВы получите:\n\n"},
[5146] = {title = "Кожевничество: сила стихий", objective = "Принесите Брумну Заиндевевшему Копыту на нагорье Арати 2 сердца огня, 2 сферы воды, 2 ядра земли и 2 дыхания ветра. \n\nВыполнение этого задания позволит вам изучать кожевничество школы силы стихий. \n\nКроме того, вы откажетесь от изучения  кожевничества школ чешуи драконов и традиций предков. Нужно быть уверенным, что выбрана верная школа, прежде чем выполнять задание.", description = "Я мастер кожевничества школы Стихии, и если ты хочешь открыть разум великим силам, я поделюсь с тобой всем, что знаю. \n\nНо знай, <класс>: выбирая этот путь, ты никогда уже не сможешь обучиться кожевничеству школы чешуи драконов и школы традиций предков, ибо из трех школ должно выбрать одну. Кроме того, мне требуется доказательство того, что ты в гармонии со всеми стихиями. Принеси мне чистейшие субстанции огня, воды, земли и ветра.", progress = "Изготовление этого типа кожаных доспехов требует терпения и самоотдачи. Когда решаешься связать свою судьбу со Стихиями, спиной к ним уже не повернешься. Принеси мне доказательства того, что ты на что-то годен, – и мы начнем.", completion = "Ты бросил жребий, и Стихии приняли тебя. Когда я закончу твое обучение, ты овладеешь искусством изготовления наилучших кожаных доспехов.\n\nЧтобы учиться этому искусству и дальше, приходи ко мне, и я разделю с тобой те знания, которые ты захочешь со мной разделить.", rewards = "Следующее заклинание будет наложено на вас:\n\nКожевничество: сила стихий\n\nВы получите:\n\n"},
[5147] = {title = "Разыскивается: Арнак Зловещий Тотем", objective = "Убейте Арнака Зловещий Тотем и принесите доказательство дозорному утесов Долгорогу на Заставу Вольного Ветра.", description = "Разыскивается: Арнак Зловещий Тотем.\n\nАрнак приговорен к смертной казни по многочисленным обвинениям в убийствах и похищениях. Достойная награда ждет того, кто найдет преступника и приведет приговор в исполнение.\n\nПоследний раз Арнака видели на утесе близ Пика Темного Облака. Принесите доказательство его смерти стражу утеса Долгорогу на Заставу Вольного Ветра и получите свою награду.", progress = "Есть новости об этом убийце, Арнаке Зловещем Тотеме?", completion = "Ха! Что ж, отличные новости! А я уж думал, его никогда не накажут.\n\nДержи награду, Большойзмей... И большое спасибо. Признаться, меня приводили в ярость сообщения о его бесчинствах!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБроня из шкуры дикого кабанаПоножи стража равнин\n\nВы также получите:\n\n"},
[5148] = {title = "Кожевничество: традиции предков", objective = "Принесите дикарский кожаный жилет и дикарский кожаный шлем Кариссии Лунной Охотнице из Фераласа.\n\nВыполнив это задание, вы станете кожевником школы традиций предков.\n\nТакже вы лишитесь возможности изучать кожевничество школы чешуи драконов и школы силы стихий; убедитесь, что избрали именно этот путь, прежде чем выполнять задание.", description = "Чтобы постичь школу традиций предков, следует обрести понимание подлинной сути дикой природы. Я знаю, что ты уже владеешь искусством изготовления дикарского кожаного доспеха, и хочу завершить твое обучение.\n\nЗнай, <класс>: избрав этот путь, ты отказываешься от изучения школ чешуи драконов и силы стихий, изучать можно только одну из них. А теперь принеси мне свои лучшие дикарские кожаные доспехи. С них мы и начнем твое обучение.", progress = "Прежде чем научиться подчинять Природу себе, вливая ее силу в кожаные доспехи, тебе следует получше узнать ее. Принеси жертву этой силе, и услышат тебя.", completion = "Ты принес богатые жертвы, и Природа вскоре позволит подчинить себя. Закончив обучение, ты сможешь делать истинные воплощения силы Природы.\n\nКогда решишь поучиться, поговори со мной, и я оделю тебя знаниями, к которым ты будешь готов.", rewards = "Следующее заклинание будет наложено на вас:\n\nКожевничество: традиции предков\n\nВы получите:\n\n"},
[5149] = {title = "Кукла Памелы", objective = "Найдите куклу Памелы.", description = "Тетушка Марлен сказала мне, что я должна остаться дома, пока папа на войне. Мой папа – самый смелый в мире!\n\nНо я здесь уже так долго, а он все не приходит за мной. Иногда сюда приходят злые люди и шепчут. Я так хочу, чтобы папа прогнал их, но его все нет и нет...\n\nА иногда, когда стемнеет, мне так хочется поиграть с моей куклой, но ее тоже нет, она осталась в городе.\n\nПринесешь мне мою куклу?", progress = "Ты нашел мою куклу?", completion = "Ты нашел мою куклу! Ура!", rewards = "Вы получите:\n\n"},
[5150] = {title = "Даданга проголодалась!", objective = "Даданга внимательно смотрит на вас, она явно чего-то ждет... \n\nВидимо, она голодна! \n\nВ кратере должно расти что-нибудь подходящее для крупного травоядного... Даданга – крупная девочка, придется потрудиться, чтобы принести ей достаточно еды!", description = nil, progress = "Даданга внимательно смотрит на вас, она явно чего-то ждет... \n\nВидимо, она голодна! \n\nВ кратере должно расти что-нибудь подходящее для крупного травоядного... Даданга – крупная девочка, придется потрудиться, чтобы принести ей достаточно еды!", completion = "Даданга с видимым удовольствием принюхивается к побегам. \n\nВ благодарность за лакомство она подталкивает к вам носом маленький коричневый сверток.", rewards = "Вы получите:\n\nМаленький сверток в оберточной бумаге"},
[5151] = {title = "Механизм гипервместимости", objective = "Убейте зверя и принестите механизм гипервместимости и ключ от клетки пантеры Визло Фингалету.", description = "На наш караван напали кентавры, и выжить удалось только мне! А самый лучший мой механизм висел на шее могучей пантеры-охранницы! Даже кентавры дрожали, увидев эту зверюгу!\n\nВот ключ от ее клетки. Они забрали все, а ключ оставили. Убей пантеру, принеси мне мой гипервместитель, а я хорошо заплачу за него.\n\nТо, что осталось от нашего каравана, находится к северу отсюда.", progress = "Нашелся мой гипервместитель?", completion = "Мой гипервместитель! Ну все, теперь с места не сойду, пока не разберусь, зачем же эта штука нужна...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКольцо Лиги изобретателей"},
[5152] = {title = "Тетушка Марлен", objective = "Поговорите с Марлен в южной части руин Андорала.", description = "О, я так одинока! Где моя семья? Тетушка Марлен велела мне ждать здесь, ушла и не вернулась. А ты случайно не <видел/видела> моего папу?\n\nМожет, тетушка Марлен знает, где он. Она живет рядом с Андоралом, у нее домик на самом юге. Вроде бы он на холме... да, она говорила, что на холме.\n\nПожалуйста, <имя>! Мы же с тобой теперь друзья? Поговори с моей тетушкой!", progress = nil, completion = "Ты видел Памелу? Она жива? О, нет! Бедная моя девочка! Она была так мала, так весела и шаловлива...\n\nОна ведь не знает, что стало с ее отцом? С моим братом Джозефом?\n\nОна едва ли сможет это понять... А даже если бы и могла, я не в силах сказать ей об этом.", rewards = "Вы получите:\n\n"},
[5153] = {title = "Странный историк", objective = "Принесите Хроми обручальное кольцо Джозефа.", description = "Увы, Джозефу не дано воссоединиться с дочерью. Его душа была искажена Плетью, он сам стал чудовищем. Как жестока судьба!\n\nИ все же судьбу можно изменить.\n\nОтправляйся к его монументу и обыщи окрестные могилы. Тела самого Джозефа там нет, однако где-то под монументом лежит его обручальное кольцо. Отнеси кольцо Хроми. Это странная гномесса... с весьма странными способностями.\n\nХроми живет в развалинах таверны в северо-западной части Андорала.", progress = "Ты очень вовремя. Часом не из будущего явился?", completion = "Что это, обручальное кольцо? Дай-ка взглянуть...\n\nКогда-то оно принадлежало великому человеку, однако с ним связано великое зло...\n\nТы хочешь помочь ему? Поздновато собрался, а впрочем... возможно, мы сможем изменить прошлое!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5154] = {title = "Анналы Дарроушира", objective = "Принесите Анналы Дарроушира Хроми в Андорал.", description = "Чтобы спасти Джозефа Редпата, придется обратиться к его прошлому. Надо прочитать, что говорится о нем в Анналах Дарроушира – книге, хранящейся в ратуше Андорала.\n\nПринеси мне книгу. Мы узнаем о судьбе Джозефа и, если повезет сможем... изменить ее.", progress = "Ты нашел книгу, Томпсон?", completion = "Прекрасно, ты нашел ее! Что в ней говорится? Там упоминается Джозеф Редпат? Если да, то мы сможем спасти его!\n\nО... В Анналах Дарроушира говорится, что во время битвы Джозеф Редпат пал жертвой порчи и примкнул к войскам Плети, предав защитников Дарроушира!\n\nЧто за горькая судьба! Думаю, мы должны приложить все усилия, чтобы изменить ее.", rewards = "Вы получите:\n\n"},
[5155] = {title = "Силы Джеденара", objective = "Отправляйтесь в Джеденар и убейте 4 джеденарских гончих, 4 джеденарских стражей, 6 джеденарских адептов и 6 джеденарских сектантов, затем возвращайтесь к Грете Заиндевевшее Копыто в Оскверненный лес.", description = "Если уж мне придется положиться на тебя в этом деле, то прежде заслужи доверие.\n\nЯ должна точно знать, что ты – враг Совета Теней, тех, кто в ответе за великие злодеяния здесь и за границами леса.\n\nОтправляйся в чащу Оскверненного леса. На западе ты увидишь тропинку в Джеденар. Именно там Совет строит свои козни вместе с Пылающим Легионом.\n\nПроникни в недра одной из населенных ими оскверненных Обителей и перебей их. Потом вернись ко мне. Тогда я увижу, что ты искренне нам помогаешь нам.", progress = nil, completion = "Хорошо, Томпсон! Теперь, когда они уменишились числом, мы усилим натиск.\n\nНу, попробовал их мощь? И как тебе? Они оказались так же сильны, как ты предполагал? Или сильнее? Или, может, они тебе вообще не противники? Разве это не здорово?\n\nМы сможем обсудить подробности твоих подвигов чуть позже. Сейчас у нас другие дела есть.", rewards = "Вы получите:\n\n"},
[5156] = {title = "Проверка на порчу", objective = "Найдите и уничтожьте 2 энтропических зверей и 2 энтропических ужасов при обследовании долины Рваных Ран. После проверьте, по-прежнему ли заполнены кратеры оскверненной водой. Затем возвращайтесь к Таруну Красному Перу в Оскверненный лес.", description = "На севере отсюда, если идти по восточной дороге, лежить так называемая долина Рваных Ран. Это то место, где во время последнией великой войны призывали инферналов. Там до сих пор поганят землю кратеры – да и сами големы.\n\nЯ хочу узнать две вещи. Во-первых, шляются ли там до сих пор эти энтропийные духи? И второе – до сих ли пор заполнены эти кратеры поганой вонючей водой, что скапливалась в них долгие годы? Поможешь ли ты мне это узнать, <имя>? Но будь <осторожен/осторожна> – инферналы уничтожают все на своем пути.", progress = nil, completion = "Хорошо, что тебе удалось остаться в живых, Томпсон. Плохо, что вода еще там. Я надеялся найти хоть один чистый источник воды в Оскверненном лесу. Похоже, тут я потерпел неудачу. Будь у нас такой источник, куда проще было бы исцелять землю.\n\nПридется заняться спасением тех лесных существ, что еще можно спасти, по ходу дела истребляя тех, в которых порча зашла так далеко, что они сами стали угрозой и для себя, и для всех, кто оказался в этом некогда великом лесу.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5157] = {title = "Собрать оскверненную воду", objective = "Возьмите пустую флягу и наполните ее водой из лунного колодца, что находится в центре Джеденара. Возвращайтесь к Грете Замшелому Копыту в Оскверненный лес.", description = "Глубоко в недрах Джеденара лежит Оплот Теней – главный оплот порчи и зла.\n\nСовет Теней окружил свое логово защитными заклятьями, заключенными в жаровнях. Если уж мне выпала задача узнать побольше о нашем враге путем магического наблюдения, то тогда мне надо будет, чтобы кто-то потушил эти жаровни. Тогда я смогу тайно понаблюдать за Советом и выяснить, кто его возглавляет.\n\nЕсли сможешь – возьми эту флягу и наполни ее водой из лунного колодца в центре Джеденара. Потом вернись ко мне.", progress = "Как только у нас будет вода из Лунного колодца, мы ее очистим и при помощи ее погасим эти жаровни защиты в Оплоте Теней. Это даст мне достаточно времени, чтобы заглянуть в еще более глубокие чертоги и понять, кто же на самом деле возглавляет этот... культ.\n\nМолю Мать-Землю о помощи!", completion = "Это то, что надо, Томпсон.\n\nТеперь нам остается только очистить воду и залить ей жаровни. Это будет нетрудно – придеться только совершить небольшое пуешествие.\n\nНадеюсь, это мы провернем быстро.", rewards = "Вы получите:\n\n"},
[5158] = {title = "В поисках духовной помощи", objective = "Отнесите порченую воду из Лунного колодца Ислен Заклинателю Воды в Степи.", description = "Отнеси эту оскверненную воду в Степи, <имя>. К югу от Кабестана на побережье скрытно живет моя старая приятельница, шаманка по имени Ислен Заклинатель Воды. Она может нам помочь. Ее узы с духами воды всегда были крепки. Веди себя благородно – и этого будет достаточно, чтобы убедить ее и духов воды помочь нам в нашем деле.\n\nИщи ее в маленьком лагере прямо у кромки воды. А на пиратов, <имя>, внимания не обращай... это все мелочи жизни, тебе они не угроза.", progress = "Чую, ты не простой путешественник, что ищет дорогу в Кабестан. Заходи, садись, отдохни у нас в лагере. Отдохнешь – тогда и поговорим.", completion = "А, так тебе надо очистить воду из этого Луннного колодца. Благородное дело – остановить порчу, пожирающуюу Оскверненный лес, но не от меня зависит, очистится ли вода. Я спрошу духов воды – это им решать, справедливо ли ваше дело.\n\nПодожди минутку, и я передам им твою просьбу. Надеюсь, они проникнутся к тебе сочувствием, как и я.", rewards = "Вы получите:\n\n"},
[5159] = {title = "Чистая вода возвращается в Оскверненный лес", objective = "Отнесите очищенную воду из лунного колодца Грете Замшелому Копыту в Оскверненный лес.", description = "Благодари духов, <имя>. Это они, а не я, помогли тебе.\n\nНыне я отдаю тебе эту очищенную воду. Передай Грете мой поклон и мои наилучшие пожелания. Она нащупала нечто более важное, чем сумели многие из нас... я уверена, что она вскоре все узнает.\n\nС Советом Теней шутки плохи, <имя>. Запомни это.\n\nТеперь ступай. Бери воду и возвращайся к Грете.", progress = "Вижу, ты вернулся, Томпсон. Это хорошо. Ты нашел Ислен в Степях? Или нам придется искать другой путь к нашей цели?", completion = "Этой воды для наших целей хватит с избытком.\n\nРада слышать, что Ислен смогла нам помочь. Ее связь с водными духами была всегда прочной. К тому же, она мудра, и духи редко не одобряют ее цели. То, что оба они благословили наше дело, дает мне надежду, что мы идем верным путем.", rewards = "Вы получите:\n\n"},
[5160] = {title = "Матрона-защитница", objective = "Дойдите до Зимних Ключей и найдите Халех. Отдайте ей пластину чешуи Ауби.", description = "Тебе придется отправиться в Калимдор, <раса>. Наша стая сейчас поселилась на холодных просторах Зимних Ключей. Когда доберешься туда, отправляйся в пещеры Маз-Торил.\n\nНа ледяном полу в пещерах ты найдешь письмена из кобальтовых рун. Сожми в руке пластинку моей чешуи, встань на руну – и перенесешься к Халех, нашей матроне-защитнице.\n\nОтдай ей пластинку моей чешуи. Халех посмотрит в нее, как в магический кристалл, и увидит все, что я видел и чувствовал в этом проклятом месте.", progress = "Рада видеть тебя, Штормбриндж.", completion = "Аспекты настойчиво утверждают, что нам не следует вмешиваться в дела смертных. Но иногда все-таки надо вмешаться – особенно когда кто-то из наших сородичей пренебрегает указами старших.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5161] = {title = "Ярость Синих драконов", objective = "Если у вас есть желание продолжить, поговорите снова с Халех.", description = "Мы понимаем, что пытается сделать проклятое порождение Смертокрыла, и мы знаем, что этого нельзя допустить.\n\nНо из-за Черной горы, которая защищает Нефариана, вмешательство стало для нас невероятно трудным.\n\nОднако, мы можем дать силу тебе, смертному существу, если ты решишься на это.\n\nЛежащий перед тобой путь полон опасностей. Примешь ли ты нашу помощь, решать тебе. Обдумай это и поговорим еще раз, когда ты примешь решение", progress = nil, completion = "Да будет так…", rewards = "Вы получите:\n\n"},
[5162] = {title = "Гнев синих драконов", objective = "Поговорите с Джезибой в Чумных землях. Он обитает в Андорале.", description = "Тайные силы контролирую я, и ради тайных сил пошлю я тебя к твоему следующему деянию.\n\nКогда будешь <готов/готова>, начнется твое путешествие. В Чумные земли лежит твой путь, и с Джезибой надлежит тебе говорить.\n\nЭто смертный, мудрый, как древние предки, и терпеливый, как сама недвижная земля. Ты найдешь его в Андорале.", progress = nil, completion = "Я Джезиба, многим известный как Скульптор. Правда ваяю я не статуи, а героев.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5163] = {title = "Йети где-то рядом…", objective = "Возьмите механического йети Уми и напугайте им ее друзей:\n\nЛегакки в Круговзоре (Зимние Ключи) \nполивалку в Прибамбасске (Танарис)\nКвикксиля в Укрытии Маршалла (Кратер Ун'Горо)\n\nКогда проделаете все это, принесите механического йети обратно Уми.", description = "Все готово, <имя>!\n\nИтак, я уже сообщила по почте моим друзьям, что у меня для них сюрприз. И тут на сцену выходишь ты!\n\nЯ дам тебе моего механического йети, а тебе нужно будет удивить их, нанеся визит каждому, включив йети и послав его по направлению к ним.\n\nКогда покажешь мое изделие Легакки в Круговзоре, Поливалке в Прибамбасске и Квикксилю в Укрытии Маршалла, возвращайся и расскажи мне, как все было!\n\nИ моего йети тоже, пожалуйста, приведи обратно.", progress = "Жду, не дождусь, так хочется услышать, как реагировали мои друзья!\n\nТакого они никак не могли ожидать!", completion = "Ха! Они теперь дважды подумают, прежде чем снова высмеивать мои идеи!\n\nСпасибо за помощь, Томпсон. Без тебя мне не удалось бы так развлечься!", rewards = "Вы получите:\n\nМеханический йети"},
[5164] = {title = "Перечень Заблудших", objective = "Прочитайте перечень Заблудших.", description = "Халех не могла отыскать лучшего орудия справедливости. Прочти перечень Заблудших и обрети просветление.\n\nЕсли ты выстоишь... Если ты сделаешь то, о чем тебя просят и выживешь... Из тебя выйдет герой.", progress = nil, completion = "Книга состоит по большей части из сотен страниц, исписанных словами и символами.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5165] = {title = "Погасить Пламя Защиты", objective = "При помощи очищенной воды из лунного колодца загасите пламя в четырех жаровнях защиты внутри Оплота Теней в Оскверненном лесу. Затем возвращайтесь к Грете Замшелому Копыту в Изумрудное святилище.", description = "Теперь тебе надо вернуться в Джеденар. Эти жаровни скорее всего расставлены в Оплоте Теней. Загаси их пламя, и защита, возведенная Советом, хотя бы на некоторое время падет. Я буду ждать этого мгновения. Когда оно настанет, я загляну в недра оплота и попытаюсь узнать, кто стоит во главе всего этого. Тогда – и только тогда – мы попытаемся атаковать их напрямую.", progress = nil, completion = "Я сумела увидеть тебя при помощи своих заклинаний, как только погасли жаровни. Славная работа, Томпсон.\n\nИ я успела кое-что узнать прежде, чем чернокнижники Совета Теней восстановили свои заклинания. Надеюсь, этого будет достаточно.\n\nТеперь отдыхай. Я сейчас расскажу тебе, что я узнала.", rewards = "Вы получите:\n\n"},
[5166] = {title = "Кираса Всецветных драконов", objective = "Джезиба \"Скульптор\" может сковать кирасу Всецветных драконов, если вы принесете ему следующее:\n\n1 всецветный панцирь.\n\n10 сверкающих всецветных чешуек.\n\n10 порций крови героев.\n\n10 мотков потертого шовного материала.", description = "По иронии судьбы, на изготовление мощной кирасы, призванной защитить от нападения всецветных драконов, идут их собственные шкуры.\n\nНа безупречную шкуру всецветного дракона нашивают их же чешую. В настоящий момент этих тварей не существует, и хочется верить, что и не будет.\n\nПоследний компонент, который труднее всего достать – это кровь героев.\n\nИ наконец, из этих компонентов Скульптор создает подлинный шедевр.", progress = "Ты сделал правильный выбор, |3-6(человек).", completion = "Неужели ты не понимаешь? Сам путь и был целью. Неужели тебя не тревожат шрамы? И боль забыта?\n\nВыстояв в испытании, ты сделался сильнее. Гораздо сильнее. И кираса – лишь внешнее проявление внутренней мощи.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКираса Разноцветного полета"},
[5167] = {title = "Ножные латы Всецветного воина", objective = "Джезиба 'Скульптор' может сковать ножные латы Всецветного воина, если вы принесете ему следующее:\n\n1 всецветный панцирь.\n\n10 сверкающих всецветных чешуек.\n\n10 порций крови героев.\n\n5 Шкур Тени.", description = "На изготовление этих поножей идут взрослых всецветных драконов. Переливчатую чешую закрепляют на проволочной основе и зачаровывают, окропляя кровью героев. В конце следует обтянуть поножи изнутри Шкурой Тени.", progress = "Свет не видывал таких поножей!", completion = "Когда ты войдешь в их чертоги, они почуют запах павших братьев. Пусть страх станет твоим оружием!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНабедренники Всецветного ВоинаНожные латы Всецветного воина\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[5168] = {title = "Герои Дарроушира", objective = "Принесите книгу Дейвила и щит Крассена Карлину Редпату.", description = "Герои Дарроушира навсегда поселились в моем сердцу, а эта книга, Анналы Дарроушира, рассказывает об их жизни.\n\nЗдесь рассказывается о паладине Дейвиле Яркосвете и о том, как Алый Марш забрал его манускрипт в ратушу Дольного Очага.\n\nЗдесь также говорится о моем брате, капитане Редпате. После его предательства, его щит раскололся и развалился на куски, и теперь лежит в самом неожиданном месте – рядом с амбаром в пустоши Гаррона.\n\nСобери эти реликвии, <имя>.", progress = "Ты собрал реликвее, Томпсон?", completion = "Это книга и щит!\n\nОни тесно связаны с историей Дарроушира, и я уверен – эта история еще не закончена.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5181] = {title = "Негодяи Дарроушира", objective = "Принести череп Хоргуса и сломанный меч Мардука Карлину Редпату в Часовню Последней Надежды.", description = "В Анналах Дарроушира упоминается о самых мерзких воинах, бившихся в том сражении. Там рассказывается о том, как Альянс разбил силы лорда Хоргуса Опустошителя. Тело его было брошено в озеро к северу от Перекрестка Корина, и череп его поныне там. \n\nМардук Черный так и не был побежден, но его легендарный меч был сломан и потерян. Он лежит на дне ущелья к западу от Перекрестка Корина.\n\nПринеси мне эти предметы, <имя>. Не знаю почему, но твоя судьба связана с ними.", progress = "Ты принес мне череп и меч, Томпсон?", completion = "Ты нашел их! Прекрасно, Томпсон! В этих предметах заключена великая сила, и однажды ты сможешь овладеть ею.\n\nОднако они навевают на меня печальные воспоминания о потерянных близких и о предательстве...", rewards = "Вы получите:\n\n"},
[5201] = {title = "Вторжение племени Зимней Спячки", objective = "По заданию Риверна Холодного Ветра убейте 5 шаманов и 5 ведмедей из клана Зимней Спячки.", description = "Мое присутствие здесь мало кто замечает, <имя>. Однако, существует одна неприятность, укроненившаяся в Зимних Ключах: это фурболги племени Зимней Спячки.\n\nХотя лично я никогда не атаковал фурболгов, они выглядят безумными и боятся всего, что им встречается на пути. Я видел, как они убивали бесчисленное количество существ, чья вина состояла лишь в том, что они оказались не в то время и не в том месте.\n\nМне все это уже поперек горла – пожалуйста, помогите мне нанести им ответный удар. Убивайте фурболгов и не подпускайте их к Уступу Ледопардов.", progress = nil, completion = "Меня невероятно радует, что хотя бы на короткое время мы можем забыть о вторжении фурболгов племени Зимней Спячки.\n\nЯ начинаю замечать вашу настойчивость, Маладат.", rewards = nil},
[5202] = {title = "Странный красный ключ", objective = "Обыщите Джеденар и найдите замок, который открывается странным красным ключом.", description = "Маленький красный ключ сделан из какого-то материала, похожего на кость. Он тяжел, но на вид кажется хрупким. Зачем прислужнику Совета Теней этот предмет? Возможно, этот странный ключ открывает какой-то замок в Джеденаре?", progress = "Смогу ли я хоть когда-нибудь вырваться из этой клетки?\n\nРано или поздно они принесут меня в жертву своим демонам. Чудовища!", completion = "Ключ! Ты его нашел! Пожалуйста, дай его мне, и я, наконец, освобожусь!", rewards = "Вы получите:\n\n"},
[5203] = {title = "Спасение из Джеденара", objective = "Сопроводите Арко'нарин туда, где лежат меч Светлая Сталь и снаряжение Арконарин, и защитите ее при побеге из Оплота Теней. Потом разыщите Джессиру Лунную Радугу в Оскверненном лесу и расскажите ей, что случилось с ее друзьями.", description = "Но, как бы мне это ни было тяжко, в первую очередь мне нужно сделать вот что: найти меч Трея, именуемый Светлая Сталь и сбежать из Оплота Теней, чтобы рассказать моим командирам, что здесь творится. Ты поможешь мне, <имя>?\n\nНаше снаряжение тут неподалеку, а ты уже <показал/показала>, что сумеешь выбраться наверх.\n\nКогда мы выберемся отсюда, я направлюсь в Дарнасс, если ты сможешь найти мою подругу Джессир на границе с Ясеневым лесом. Она должна была встретить нас у лагеря Изумрудного Круга неподалеку отсюда.\n\nЧто скажешь, <имя>? Поможешь мне еще раз?", progress = nil, completion = "Так это ты помог Арко спастись? Как я рада увидеть тебя! Она не так давно проходила мимо этих мест в Дарнасс. Она несла Светлую Сталь и у нее не было даже времени поговорить с друидами, чтобы те ее исцелили. Говорила, что дело слишком спешное.\n\nНо все же она рассказала мне о твоей встрече с духом Трея. Какая страшная судьба для рыцаря Серебряной Длани! Она, конечно, не подает виду, но я знаю, что ее душа разрывается от потери одного из ближайших друзей...", rewards = "Вы получите:\n\n"},
[5204] = {title = "Воздаяние Света", objective = "Вернитесь в Джеденар и убейте суккуба Ракайю, затем отыщите останки Трея Светогорна.", description = "Она делает вид, что с ней все в порядке. Ей хочется, чтобы я думала, будто она сама сумеет справиться, но я же не слепая. Смерть Трея и его крики под пытками, которым его подвергали, долго мучили ее, и мы ничем не могли ей помочь. Но мы все же можем дать ей хоть немного покоя!\n\n<имя>, вернись в Оплот Теней, убей мучителя Трея и найди его останки. Почему бы нам самим не покончить с этим, пока Арконарин плачет в глубине души?", progress = "Вы осматриваете тело. Вне всякого сомнения, это был рыцарь Серебряной Длани, Трей Легкий Горн. На мгновение вы вспоминаете об Арконарин и задумываетесь – нет ли в вашей жизни того, кто значил бы для вас столько же, как этот человек для недавно спасенной вами из Оплота Теней ночной эльфийки?\n\nСобравшись с мыслями, вы понимаете, что вы не понесете останки паладина к Джессир, пока не убьете его мучителя.", completion = "Вы как можно осторожнее собираете останки паладина, сознавая, что его хотя бы его дух свободен от мучений, которым его подвергали.", rewards = "Вы получите:\n\nОстанки Трея Светогорна"},
[5206] = {title = "Мародеры Дарроушира", objective = "Принесите 5 резонирующих черепов и загадочный кристалл Карлину Редпату в Восточные Чумные земли.", description = "Хроми утверждает, что собранные тобой реликвии могут служить ингредиентами для мощных чар. Однако требуется еще один ингредиент: черепа воинов Плети, участвовавших в битве при Дарроушире.\n\nВозьми этот кристалл и отправляйся за черепами лучших воителей Плети. Кристалл заколдован: он резонирует, если поднести его к черепу воителя, участвовавшего в битве.\n\nИди, <имя>. Ты найдешь воителей Плети на Ядовитой поляне к северу отсюда и в Грибной долине на западе.", progress = "Ты принес черепа? Хроми говорит, они необходимы для заклятия, а заклятие поможет нам спасти Дарроушир.", completion = "Отлично, у нас есть черепа!\n\nХоть я и не совсем понимаю, зачем именно они нужны, я чувствую исходящую от них силу и то, что они связаны с моей родной деревней, Дарроушир.", rewards = "Вы получите:\n\n"},
[5210] = {title = "Брат Карлин", objective = "Отнесите дополненные Анналы Дарроушира Карлину Редпату в Восточные Чумные земли.", description = "С помощью магии я дополнила Анналы Дарроушира – теперь они содержат сведения и о том, что случилось после битвы. И там говорится, что еще один из рода Крассенов пережил предательство Джозефа. Его имя Карлин, он сейчас в восточных пределах Чумных земель, в Часовне Последней Надежды.\n\nОтправляйся к нему и передай ему книгу.", progress = "Ты пришел с запада? Что там происходит? Я знаю, что Андорал пал, но добралось ли воинство Плети до Тирисфаля?", completion = "Что это за книга? Анналы Дарроушира? О, там был мой дом... пока не пришла Плеть! Зачем ты принес мне эту книгу?\n\nЧто это? Смотри, на последних страницах рассказывается о том, что случилось уже после битвы! Здесь говорится и обо мне, и о моем брате Джозефе... Неужели это правда?\n\nЯ должен знать!", rewards = "Вы получите:\n\n"},
[5211] = {title = "Защитники Дарроушира", objective = "Освободите 15 духов Дарроушира и возвращайтесь к Карлину Редпату.", description = "Многие защищавшие Дарроушир пали в битве. И многие из них восстали из мертвых, примкнув к Плети! Ты <должен/должна> отыскать эти несчастные души и избывить их от страданий.\n\nКаннибалы-вурдалаки, бормощущие вурдалаки, болезненные живодеры – многие из них были добрыми жителями Дарроушира. Уничтожив их тела, ты освободишь их души.\n\nТы найдешь их в Проклятом лесу, Перекрестке Корина и прочих опорных пунктах Плети в Восточных Чумных землях.", progress = nil, completion = "Рад слышать, что истерзанные души моих сородичей с твоей помощью обрели свободу. Ты пролил бальзам на мои раны – теперь я знаю, что хоть кто-то из моих павших сородичей освободился от ига Плети.", rewards = "Вы получите:\n\n"},
[5212] = {title = "Плоть не лжет", objective = "Принесите 20 препаратов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, любая тварь из Стратхольма сойдет за препарат.", description = "Аптекари Отрекшихся не единственные в этом мире, кто искушен в науках.\n\nЯ уже много лет изучаю эту заразу, <раса>. Ранее я полагала, что активность чумы со временем уменьшается, однако то, что наблюдается в Чумных землях, поражает воображение.\n\nЗдесь вирус со временем становится все более активным!\n\nЯ должна продолжать исследования! Вирус наиболее активен в певые дни после заражения, поэтому мне нужны образцы тканей, пораженных совсем недавно. Отправляйся в Стратхольм и снабди меня препаратами для исследований, <имя>.", progress = "Некоторые считают, что у меня параноя, а я вот отвечу: \"Бди! Вирус не дремлет!\"", completion = "В химическом составе вируса приизошли какие-то изменения. Я должна продолжать исследования.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5213] = {title = "Вирус чумы", objective = "Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк.", description = "Тебе предстоит углубиться еще дальше в кварталы Стратхольма, <имя>. B\nЗа первыми воротами ты увидишь зиккураты. Известно, что твари Плети черпают из этих сооружений великую силу. Обыщи зиккураты и расскажи мне обо всем, что там увидишь.", progress = "Мы на пороге открытия! Скоро мы узнаем, на чем основана устойчивость вируса чумы.", completion = "Потрясающе! Теперь я должна как следует изучить эти данные – это может потребовать нескольких месяцев. Серебряный Рассвет приносит тебе огромную благодарность, Стиммакс.\n\nТебе будет дарована печать Рассвета или руна Рассвета на твой выбор. И то, и другое можно использовать вместо Жетона Серебряного Рассвета для сбора знаков различия Плети. Если потеряешь, обращайся ко мне за заменой.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПечать РассветаРуна Рассвета\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[5214] = {title = "Великий Эзра Гримм", objective = "Найдите табачную лавку Эзры Гримма в Стратхольме, отыщите в ней коробку отличного табака Эзры Гримма и принесите ее Дымку ЛаРу.", description = "То, что произошло с Эзрой, поистине ужасно! Город осаждала нежить, но Эзра не хотел бросать свою лавку превосходного табака. Последнее, что он сказал мне: \"Я не уйду, пока не сожгу все до последнего листочка, чтобы ничего не осталось врагу!\"\n\nЯ тоже знаю толк в хорошем табаке, но не готов расстаться с жизнью ради каких-то сушеных листьев, пусть и наивысшего качества. Хотя... может там хоть что-то уцелело?\n\nЧто скажешь, <имя>? Не поищешь табачку для старины Дымка?", progress = "Я сам не справлюсь, Какагага! Помоги старику...", completion = "О, мои милые папироски, как я по вам скучал...", rewards = "Вы получите:\n\nВоспламенитель Дымка"},
[5215] = {title = "Котлы Плети", objective = "Поговорите с верховной жрицей Макдонелл на Берегу Промозглого Ветра в Западных Чумных землях.", description = "В пределах бывшего Лордерона спрятано восемь котлов – четыре здесь, на западе, и еще четыре – на востоке. Они испускают ядовитые пары, распространяя чуму нежити по всей земле на радость Плети.\n\nКел'Тузад слишком силен, чтобы взять да и угасить пламя под этими котлами, но, быть может, мы сможем придумать способ использовать их для собственной выгоды. Моя помощница, верховная жрица Макдонелл, поможет тебе выполнить задание; она продолжит инструктаж.", progress = nil, completion = "Да осияет тебя Свет в наши темные времена, |3-6(Воин). Я рада, что смогу помочь тебе в борьбе с планами Плети.\n\nНаша цель – таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети. Для этого придется взять пробы из всех котлов в Западных Чумных землях.\n\nГотовься к славной битве против жестокой Плети!", rewards = "Вы получите:\n\n"},
[5216] = {title = "Цель: поле Джанис", objective = "Отправляйтесь на поле Джанис в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Джанис.", description = "Из четырех котлов западных Проклятых земель проще всего подобраться к тому, что в поле Джанис. Его охраняют менее опытные воины Плети, хотя не стоит их недооценивать.\n\nОтправляйся на поле Джанис, что на востоке отсюда и на северо-западе от Андорала, и вступи в схватку с тамошним Хранителем котла. У него есть ключ, который даст доступ к котлу. Отперев панель доступа, набери в бутылку образец ядов из котла; они понадобятся нам, чтобы подобрать противодействующие вещества.", progress = "Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.", completion = "Ключ, который вы забрали у Хранителя котла Желчня входит в замочную скважину и немедленно исчезает. И все же, кажется, отныне вы сможете открывать панель доступа без ключа. Изнутри доносится гнусный запах. В котле бурлит смесь неизвестных веществ.\n\nБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для высшей жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.", rewards = "Вы получите:\n\n"},
[5217] = {title = "Возвращение в Лагерь Промозглого Ветра", objective = "Принесите полную бутылку с поля Джанис верховной жрице Макдонелл в Лагерь Промозглого Ветра, что в Западных Чумных землях.", description = "Вы наполняете бутыль из котла ядовитой жижей. Вроде бы должно хватить.\n\nЗаполучив яд, пора возвращаться к верховной жрице Макдонелл в Лагерь Промозглого Ветра.", progress = "Добро пожаловать в Лагерь Промозглого Ветра, Кавару. Наслаждайся ощущением безопасности. Как дела с котлами?", completion = "Молодец, Кавару! Алхимик Арбингтон мигом проведет анализ этой дряни и составит противодействующее вещество. Надо будет внести его в котел и постараться, чтобы побольше испарений попало в воздух. Кто знает, может удастся ослабить Плеть.\n\nЭто будет нелегко – придется постоянно устраивать набеги на котлы и добавлять в них необходимые реагенты. И все же у нас есть шанс получить в решающей битве преимущество перед Плетью!", rewards = "Следующее заклинание будет наложено на вас:\n\nСлово силы: Стойкость\n\nВы получите:\n\n"},
[5218] = {title = "Котел поля Джанис", objective = "Перед вами – котел Плети. Он бурлит, испуская в воздух огромное количество ядовитых испарений. У массивного основания котла находится небольшая панель доступа.\n\nОдолев Хранителя котла и забрав у него ключ, мы можете добавить в котел любые составляющие, чтобы превратить его в средство борьбы с чумой нежити.", description = nil, progress = "Перед вами – котел Плети. Он бурлит, испуская в воздух огромное количество ядовитых испарений. У массивного основания котла находится небольшая панель доступа.\n\nОдолев Хранителя котла и забрав у него ключ, мы можете добавить в котел любые составляющие, чтобы превратить его в средство борьбы с чумой нежити.", completion = "Добавив в котел все необходимые вещества, вы видите, как меняется цвет и состав исходящих от него паров. Приспешники Плети, находящиеся поблизости, в ужасе отшатываются и бегут прочь.", rewards = nil},
[5219] = {title = "Цель: Слезы Далсона", objective = "Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона.", description = "Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слезы Далсона. Но сегодня не время лить слезы, <класс>. Мы должны нанести удар по котлу и получить к нему доступ!\n\nОтправляйся в Слезы Далсона, к северу от Андорала, и убей Хранителя котла. Забери у него ключ, как и в прошлый раз и получи доступ к самому котлу. Наполни эту бутылку ядом, ведь в каждом из котлов бурлят свои яды.", progress = "Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.", completion = "Неприятного вида ключ, найденный в останках Хранителя котла, легко входит в замочную скважину и исчезает. Вы получили постоянный доступ у котлу. По переплетенным трубкам течет гнусная тягучая жижа.\n\nБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для высшей жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.", rewards = "Вы получите:\n\n"},
[5220] = {title = "Возвращение в Лагерь Промозглого Ветра", objective = "Принесите полную бутылку с поля Слез Далсона верховной жрице Макдонелл в Лагерь Промозглого Ветра, что в Западных Чумных землях.", description = "Вы наполняете бутыль из котла зловонной жижей. Вроде бы должно хватить.\n\nЗаполучив яд, пора возвращаться к верховной жрице Макдонелл в Лагерь Промозглого Ветра.", progress = "Мы знаем, что в каждом из котлов замешаны составляющие, распространяющие заразу. Также нам известно, что нужно для составления противоядий для каждого из котлов. Какие компоненты нужны для котла с поля Слез Далсона не определить без образца зелья. Действуй.", completion = "А, мне будет чем заняться. Молодец, Татаки!\n\nИтак, следующий шаг ясен. Мы должны составить список компонентов, которые будет необходимо смешать с зельем чумы, чтобы добиться от него обратного действия.\n\nДля этого придется поместить эти составляющие непосредственно в котел. Аптекарь Арбингтон знает гораздо больше чем я, поэтому в ближайшее время поговори с ним.", rewards = "Следующее заклинание будет наложено на вас:\n\nСлово силы: Стойкость\n\nВы получите:\n\n"},
[5221] = {title = "Котел Слез Далсона", objective = "Перед вами – котел Плети. Он бурлит, испуская в воздух огромное количество ядовитых испарений. У массивного основания котла находится небольшая панель доступа.\n\nОдолев Хранителя котла и забрав у него ключ, мы можете добавить в котел любые составляющие, чтобы превратить его в средство борьбы с чумой нежити.", description = nil, progress = "Перед вами – котел Плети. Он бурлит, испуская в воздух огромное количество ядовитых испарений. У массивного основания котла находится небольшая панель доступа.\n\nОдолев Хранителя котла и забрав у него ключ, мы можете добавить в котел любые составляющие, чтобы превратить его в средство борьбы с чумой нежити.", completion = "Добавив в котел все необходимые вещества, вы видите, как меняется цвет и состав исходящих от него паров. Приспешники Плети, находящиеся поблизости, в ужасе отшатываются и бегут прочь.", rewards = nil},
[5222] = {title = "Цель: Удел Страданий", objective = "Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий.", description = "Тебе удалось открыть уже два котла; теперь у тебя к ним неограниченный доступ, но остается еще два! Если справиться и с ними, то у нас будет больше шансов успешно внести противодействующее вещество!\n\nНа сей раз твоя цель – котел Удела Страданий. Он совсем рядом с разрушенными стенами Андорала, чуть восточнее. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Наполни эту бутылку из котла.\n\nДоброй охоты, <имя>!", progress = "Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.", completion = "Коснувшись панели доступа, ключ Хранителя котла исчезает, как и в прошлый раз. Внутри бурлит омерзительно пахнующая жидкость.\n\nБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для верховной жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.", rewards = "Вы получите:\n\n"},
[5223] = {title = "Возвращение в Лагерь Промозглого Ветра", objective = "Принесите полную бутылку с Призрачной фермы верховной жрице Макдонелл в Лагерь Промозглого Ветра, в Западные Чумные земли.", description = "Вы аккуратно закручиваете бутылку. Образец гнусной жижи, бурлящей в котле, плещется в хрупкой стеклянной оболочке.\n\nЗаполучив яд, пора возвращаться верховной жрице Макдонелл в Лагерь Промозглого Ветра.", progress = "Как только мы исследуем образец из котла Удела Страданий, у нас появится третий способ нанести сокрушительный урон Плети, подобрав правильное противодействующее вещество!", completion = "Еще одно задание выполнено без сучка, без задоринки! Итак, у нас есть доступ вот уже к трем котлам! Если бы не страшная некромантская власть Кел'Тузада в этих землях, я бы сказала, что нам удастся полностью нейтрализовать их!\n\nАлхимик Арбингтон вскоре сообщит, что требуется добавить в этот котел – и другие, подвластные нам – чтобы справиться с чумой нежити. Итак, настало время добраться до последнего из западных котлов!", rewards = "Следующее заклинание будет наложено на вас:\n\nСлово силы: Стойкость\n\nВы получите:\n\n"},
[5224] = {title = "Котел Призрачной фермы", objective = "Перед вами – котел Плети. Он бурлит, испуская в воздух огромное количество ядовитых испарений. У массивного основания котла находится небольшая панель доступа.\n\nОдолев Хранителя котла и забрав у него ключ, мы можете добавить в котел любые составляющие, чтобы превратить его в средство борьбы с чумой нежити.", description = nil, progress = "Перед вами – котел Плети. Он бурлит, испуская в воздух огромное количество ядовитых испарений. У массивного основания котла находится небольшая панель доступа.\n\nОдолев Хранителя котла и забрав у него ключ, мы можете добавить в котел любые составляющие, чтобы превратить его в средство борьбы с чумой нежити.", completion = "Добавив в котел все необходимые вещества, вы видите, как меняется цвет и состав исходящих от него паров. Приспешники Плети, находящиеся поблизости, в ужасе отшатываются и бегут прочь.", rewards = nil},
[5225] = {title = "Цель: пустошь Гаррона", objective = "Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с путоши Гаррона.", description = "Последний оставшийся котел находится на ферме, которая теперь зовется пустошью Гаррона. Его охраняют сильные прислужники Плети, по большей части призраки и духи. С ними шутки плохи, <имя>.\n\nПустошь Гаррона находится далеко на востоке от Бастиона, близко от границы Восточных Чумных земель. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Вот, возьми эту пустую бутылку, заполни ее из котла и принеси мне. Да укроет тебя тьма своим крылом, <класс>.", progress = "Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.", completion = "Коснувшись панели доступа у основания, ключ Хранителя котла Душегнева исчезает. Раздается негромкий щелчок, и панель распахивается, открывая доступ к зловредным ядам.\n\nБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для высшей жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.", rewards = "Вы получите:\n\n"},
[5226] = {title = "Возвращение в Лагерь Промозглого Ветра", objective = "Отнесите полную бутылку с пустоши Гаррона высшей жрице Макдонелл в Лагерь Промозглого Ветра, что в Западных Чумных землях.", description = "Вы тщательно перекрываете кран на панели управления, и остатки гнусной жижи медленно стекают в пустую бутылку.\n\nЗаполучив яд, пора возвращаться к высшей жрице Макдонелл в Лагерь Промозглого Ветра.", progress = "На пустоши Гаррона находится последний котел на западе, к которому у нас еще нет доступа. Получив образцы зелья чумы из этого котла, мы сможем внести необходимые компоненты в четыре сосуда! Плети придется нелегко, когда мы доберемся до всех четырех котлов, даже сила Кел'Тузада ее не спасет.", completion = "Поздравляю, Кирпичег, тебе удалось обеспечить нам доступ к последнему из котлов! Аптекарь Арбингтон вскоре составит список компонентов, которые необходимо добавить в него.\n\nЧто до тебя, я не сомневаюсь, что командир Отважный Кулак пожелает лично поблагодарить тебя за помощь. Без тебя наша борьба с Плетью была обречена. Спасибо, ты настоящий герой.", rewards = "Следующее заклинание будет наложено на вас:\n\nСлово силы: Стойкость\n\nВы получите:\n\n"},
[5227] = {title = "Котел пустоши Гаррона", objective = "Перед вами – котел Плети. Он бурлит, испуская в воздух огромное количество ядовитых испарений. У массивного основания котла находится небольшая панель доступа.\n\nОдолев Хранителя котла и забрав у него ключ, мы можете добавить в котел любые составляющие, чтобы превратить его в средство борьбы с чумой нежити.", description = nil, progress = "Перед вами – котел Плети. Он бурлит, испуская в воздух огромное количество ядовитых испарений. У массивного основания котла находится небольшая панель доступа.\n\nОдолев Хранителя котла и забрав у него ключ, мы можете добавить в котел любые составляющие, чтобы превратить его в средство борьбы с чумой нежити.", completion = "Добавив в котел все необходимые вещества, вы видите, как меняется цвет и состав исходящих от него паров. Приспешники Плети, находящиеся поблизости, в ужасе отшатываются и бегут прочь.", rewards = nil},
[5228] = {title = "Котлы Плети", objective = "Поговорите со жрицей Тьмы Вандис в Бастионе, что в Западных Чумных землях.", description = "В пределах бывшего Лордерона спрятано восемь котлов – четыре здесь, на западе, и еще четыре – на востоке. Они испускают ядовитые пары, распространяя чуму нежити по всей земле на радость Плети.\n\nКел'Тузад слишком силен, чтобы взять да и угасить пламя под этими котлами, но, быть может, мы сможем придумать способ использовать их для собственной выгоды. Моя помощница, жрица Тьмы Вандис, поможет тебе выполнить задание; она продолжит инструктаж.", progress = nil, completion = "Да благословит тебя Тьма, брат |3-6(нежить). Я помогу тебе организовать нападение на котлы Плети.\n\nНаша цель – таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети. Для этого придется взять пробы из всех котлов в Западных Чумных землях.\n\nТебя ждет героическая схватка с Плетью!", rewards = "Вы получите:\n\n"},
[5229] = {title = "Цель: поле Джанис", objective = "Отправляйтесь на поле Джанис в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Джанис.", description = "Из четырех котлов Западных Чумных земель проще всего подобраться к тому, что в поле Джанис. Его охраняют менее опытные воины Плети, хотя не стоит их недооценивать.\n\nОтправляйся на поле Джанис, что на востоке отсюда и на северо-западе от Андорала, и вступи в схватку с тамошним Хранителем котла. У него есть ключ, который даст доступ к котлу. Отперев панель доступа, набери в бутылку образец ядов из котла; они понадобятся нам, чтобы подобрать противодействующие вещества.", progress = "Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.", completion = "Ключ, который вы забрали у Хранителя котла Желчня входит в замочную скважину и немедленно исчезает. И все же, кажется, отныне вы сможете открывать панель доступа без ключа. Изнутри доносится гнусный запах. В котле бурлит смесь неизвестных веществ.\n\nБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис с вершины Холодного Ветра не составляет труда.", rewards = "Вы получите:\n\n"},
[5230] = {title = "Возвращение в Бастион", objective = "Принесите полную бутылку с поля Джанис жрице Тьмы Вандис в Бастион, что в Западных Чумных землях.", description = "Вы наполняете бутыль из котла ядовитой жижей. Вроде бы должно хватить.\n\nПора возвращаться к жрице Тьмы Вандис в Бастион.", progress = "Добро пожаловать в Бастион, Томпсон. Наслаждайся ощущением безопасности. Как дела с котлами?", completion = "Молодец, Томпсон! Аптекарь Дитерс мигом проведет анализ этой дряни и составит противодействующее вещество. Надо будет внести его в котел и постараться, чтобы побольше испарений попало в воздух. Кто знает, может удастся ослабить Плеть.\n\nЭто будет нелегко – придется постоянно устраивать набеги на котлы и добавлять в них необходимые реагенты. И все же у нас есть шанс получить в решающей битве преимущество перед Плетью!", rewards = "Следующее заклинание будет наложено на вас:\n\nСлово силы: Стойкость\n\nВы получите:\n\n"},
[5231] = {title = "Цель: Слезы Далсона", objective = "Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона.", description = "Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слезы Далсона. Но сегодня не время лить слезы, <класс>. Мы должны нанести удар по котлу и получить к нему доступ!\n\nОтправляйся в Слезы Далсона, к северу от Андорала, и убей Хранителя котла. Забери у него ключ, как и в прошлый раз и получи доступ к самому котлу. Наполни эту бутылку ядом, ведь в каждом из котлов бурлят свои яды.", progress = "Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.", completion = "Неприятного вида ключ, найденный в останках Хранителя котла, легко входит в замочную скважину и исчезает. Вы получили постоянный доступ у котлу. По переплетенным трубкам течет гнусная тягучая жижа.\n\nБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис из Бастиона не составляет труда.", rewards = "Вы получите:\n\n"},
[5232] = {title = "Возвращение в Бастион", objective = "Отнесите полную бутылку с поля Слез Далсона жрице Тьмы Вандис в Бастион в Западных Чумных землях.", description = "Вы наполняете бутыль из котла зловонной жижей. Вроде бы должно хватить.\n\nПора возвращаться к жрице Тьмы Вандис в Бастион.", progress = "Мы знаем, что в каждом из котлов замешаны составляющие, распространяющие заразу. Также нам известно, что нужно для составления противоядий для каждого из котлов. Какие компоненты нужны для котла с поля Слез Далсона не определить без образца зелья. Действуй.", completion = "А, мне будет чем заняться. Молодец, Томпсон!\n\nИтак, следующий шаг ясен. Мы должны составить список компонентов, которые будет необходимо смешать с зельем чумы, чтобы добиться от него обратного действия.\n\nДля этого придется поместить эти составляющие непосредственно в котел. Аптекарь Дитерс знает гораздо больше чем я, поэтому в ближайшее время поговори с ним.", rewards = "Следующее заклинание будет наложено на вас:\n\nСлово силы: Стойкость\n\nВы получите:\n\n"},
[5233] = {title = "Цель: Призрачная ферма", objective = "Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий.", description = "Тебе удалось открыть уже два котла; теперь у тебя к ним неограниченный доступ, но остается еще два! Если справиться и с ними, то у нас будет больше шансов успешно внести противодействующее вещество!\n\nНа сей раз твоя цель – котел Удела Страданий. Он совсем рядом с разрушенными стенами Андорала, чуть восточнее.И вновь тебе придется убить Хранителя котла и забрать у него ключ. Наполни эту бутылку из котла.\n\nДоброй охоты, <имя>!", progress = "Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.", completion = "Коснувшись панели доступа, ключ Хранителя котла исчезает, как и в прошлый раз. Внутри бурлит омерзительно пахнующая жидкость.\n\nБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис из Бастиона не составляет труда.", rewards = "Вы получите:\n\n"},
[5234] = {title = "Возвращение в Бастион", objective = "Принесите полную бутылку с Призрачной фермы жрице Тьмы Вандис в Бастион, что в Западных Чумных землях.", description = "Вы аккуратно закручиваете бутылку. Образец гнусной жижи, бурлящей в котле, плещется в хрупкой стеклянной оболочке.\n\nПора возвращаться к жрице Тьмы Вандис в Бастион.", progress = "Как только мы исследуем образец из котла Удела Страданий, у нас появится третий способ нанести сокрушительный урон Плети, подобрав правильное противодействующее вещество!", completion = "Еще одно задание выполнено без сучка, без задоринки! Итак, у нас есть доступ вот уже к трем котлам! Если бы не страшная некромантская власть Кел'Тузада в этих землях, я бы сказала, что нам удастся полностью нейтрализовать их!\n\nАптекарь Дитерс вскоре сообщит, что требуется добавить в этот котел – и другие, подвластные нам – чтобы справиться с чумой нежити. Итак, настало время добраться до последнего из западных котлов!", rewards = "Следующее заклинание будет наложено на вас:\n\nСлово силы: Стойкость\n\nВы получите:\n\n"},
[5235] = {title = "Цель: пустошь Гаррона", objective = "Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с путоши Гаррона.", description = "Последний оставшийся котел находится на ферме, которая теперь зовется пустошью Гаррона. Его охраняют сильные прислужники Плети, по большей части призраки и духи. С ними шутки плохи, <имя>.\n\nПустошь Гаррона находится далеко на востоке от Бастиона, близко к границам Восточных Чумных земель. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Вот, возьми эту пустую бутылку, заполни ее из котла и принеси мне. Да укроет тебя тьма своим крылом, <класс>.", progress = "Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.", completion = "Коснувшись панели доступа у основания, ключ Хранителя котла Душегнева исчезает. Раздается негромкий щелчок, и панель распахивается, открывая доступ к зловредным ядам.\n\nБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис из Бастиона не составляет труда.", rewards = "Вы получите:\n\n"},
[5236] = {title = "Возвращение в Бастион", objective = "Отнесите полную бутылку с пустоши Гаррона жрице Тьмы Вандис в Бастион в Западных Чумных землях.", description = "Вы тщательно перекрываете кран на панели управления, и остатки гнусной жижи медленно стекают в пустую бутылку.\n\nПора возвращаться к жрице Тьмы Вандис в Бастион.", progress = "На пустоши Гаррона находится последний котел на западе, к которому у нас еще нет доступа. Получив образцы зелья чумы из этого котла, мы сможем внести необходимые компоненты в четыре сосуда! Плети придется нелегко, даже сила Кел'Тузада ее не спасет.", completion = "Поздравляю, Томпсон, тебе удалось обеспечить нам доступ к последнему из котлов! Аптекарь Дитерс вскоре составит список компонентов, которые необходимо добавить в него.\n\nЧто до тебя, я не сомневаюсь, что верховный палач Деррингтон пожелает лично поблагодарить тебя за помощь. Без тебя наша борьба с Плетью была обречена. Спасибо, могучий |3-6(Охотник).", rewards = "Следующее заклинание будет наложено на вас:\n\nСлово силы: Стойкость\n\nВы получите:\n\n"},
[5237] = {title = "Задание выполнено!", objective = "Успешная диверсия против всех котлов – огромная победа!\n\n*Командир откашливается и оглушительно орет.*\n\nСлушайте, слушайте все! За верную и преданную службу королевству Штормграда и Альянсу, за выполнение долга и даже более того – перед лицом невероятной опасности, отметим – я вручаю Лорегон награду и передаю ему нашу вечную благодарность. Он – истинный герой Альянса. Ура!", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДоблестный короткий мечПрочный короткий меч\n\nВы также получите:\n\nБлагодарственная медаль Героя"},
[5238] = {title = "Задание выполнено!", objective = "Успешная диверсия против всех котлов – огромная победа!\n\n*Верховный палач откашливается и оглушительно орет.*\n\nСлушайте, слушайте все! За верную и преданную службу Отрекшимся и Орде, за выполнение долга и даже более того – перед лицом невероятной опасности, отметим – я вручаю Томпсон награду и передаю ему нашу вечную благодарность. Он – истинный герой Орды. Ура!", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДоблестный короткий мечПрочный короткий меч\n\nВы также получите:\n\nБлагодарственная медаль Героя"},
[5241] = {title = "Дядюшка Карлин", objective = "Найдите Карлина Редпата.", description = "Ты знаешь, иногда по ночам мне слышится плач дядюшки Карлина – как будто бы плач доносится откуда-то издалека, с востока.\n\nА вдруг он плачет обо мне... <имя>, пожалуйста, разыщи моего дядюшку и скажи ему, что со мной все в порядке.\n\nСкажи, что я здесь, жду его и очень скучаю по сказкам, которые он рассказывал мне на ночь... особенно той, про кроликов и черничное варенье. Она была такая забавная!", progress = nil, completion = "Ты видел Памелу? Она жива?\n\nПогибла?! Бедная моя девочка! За что твой дух осужден скитаться в этом жестоком мире... Почемы тебя не стало во цвете лет, а я все еще копчу небо! Как бы я хотел вместо тебя отдать жизнь и призраком бродить по руинам Дарроушира!\n\nСудьбу не изменить... Спасибо тебе, Томпсон. Теперь мой долг – месть, я осознаю это ясно как никогда.", rewards = "Вы получите:\n\n"},
[5242] = {title = "Окончательный удар", objective = "Убейте Моору и Салию и принесите голову владыки теней Скверн'дана Грете Замшелому Копыту в Оскверненный лес.", description = "Увы, я вижу только один путь покончить с угрозой Оскверненному лесу – прямую атаку. Других путей в Оплот Теней нет, телепортировать тебя внутрь я тоже не могу. Единственный путь – прямой путь в бездну... и я также знаю, кого тебе следует искать в этой бездне. Его зовут Скверн'дан... Владыка теней Скверн'дан. Его власть там, внизу, смертоносна... Он – голова змеи. Убей его и двух его суккубов-прислужниц, и вернись ко мне. Это Скверн'дан заключил союз с Легионом. Его надо остановить!", progress = "Теперь, без Фел-дана, Совет Теней потеряет цель и будет беспомощен. Они перегрызутся между собой за власть и сокровища – плату за будущие планы. А мы воспользуемся этим времением и вырежем и их, и их рабов-демонов.", completion = "Хвала Матери-Земле, Томпсон! Хвала тебе! Воистину, великий день!\n\nСовет Теней вряд ли сможет снова обрести ту власть которой обладал до того, как ты нанес удар по их иерархии. Великое дело ты ныне свершил!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКушак Гладкого дереваКожаные перчатки порчиРемень Кузни Орудий\n\nВы также получите:\n\n"},
[5243] = {title = "Святая вода", objective = "Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Бартоломею Чтимому, как только воды будет достаточно.", description = "Я склонен рассматривать свое бытие в форме нежити как род болезни, <раса>. Болезни, которая требует лечения. Впрочем, для Серебряного Рассвета это не болезнь, а истинное благословение. Действительно, нет лучше орудия против язычников Плети, чем нежить.\n\nКоллеги чтят меня за мои деяния, однако почести ничего не значат для меня.\n\nЕсли ты хочешь содействовать делу Серебряного Рассвета, у меня есть для тебя работа.\n\nОтправляйся в Стратхольм и пополни наши запасы святой воды. Искать ее следует в брошенных ящиках с припасами.", progress = "Учти, далеко не все ящики припасов в разрушенном городе остались в целости и сохранности. Воины Плети боятся святой воды, однако она не является препятствием для диких зверей.", completion = "Отлично, |3-6(человек). Ты доказал, что терпим к ближнему и непримирим в борьбе против приспешников Кел'Тузада.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКорона ПокаянияКольцо Покаяния\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nМощное лечебное зельеСильное зелье маны"},
[5244] = {title = "Руины Кел'Терила", objective = "Поговорите с Джероном Гранильщиком в деревне Звездопада.", description = "История Кел'Терила – это история проклятой расы, прикованной к месту, где был совершен неудавшийся ритуал…\n\nВысокорожденные, которых вы найдете там, когда-то похитили священный артефакт, будучи уверенными, что смогут вытянуть его мощь, перелить ее в себя и стать еще более могущественными. Из-за их действий реликвия взорвалась, а куски ее ушли под лед озера...\n\nЕсли хотите узнать больше, поговорите с Джероном Гранильщиком. Он был там недавно и сможет рассказать вам обо всем.", progress = nil, completion = "Ну, конечно, я могу подробно рассказать про Кел'Терил. Имей в виду, я не историк – но могу рассказать тебе о том, что я сам там видел…", rewards = "Вы получите:\n\n"},
[5245] = {title = "Беспокойные духи Кел'Терила", objective = "Используйте кирку Джерона, чтобы добыть фрагменты реликвии высокорожденных, Принесите их Авроре Зову Небес в Восточные Чумные земли.", description = "Несчастные существа эти духи высокорожденных, что и говорить. Они все еще ищут части самой вещи, которая навсегда привязала их к Кел'Терилу, эту похищенную у них реликвию.\n\nЕсли тебе это интересно, можешь взять мою кирку и отправляться на юг к озеру, чтобы попытаться достать части этого артефакта изо льда.\n\nЯ не могу сказать что именно ты найдешь, но Аврора Зов Небес наверняка сможет; она живет около башни Северного Перевала в северной части Восточных Чумных земель.", progress = "Что привело тебя сюда?", completion = "Прошлое Высоких Эльфов не лучшая тема для беседы, Драгунов. Мне до сих пор больно думать об этом... И самое главное, уже невозможно ничего исправить.", rewards = "Вы получите:\n\n"},
[5246] = {title = "Фрагменты прошлого", objective = "Найдите Священные письмена высокорожденных в Храме Зин-Малор, в Азшаре и принесите их Авроре Зову Небес к Башне Северного перевалa, в Восточных Чумных землях.", description = "Я не понимала… Простите мои жестокие слова, <класс>.\n\nЯ не хочу вспоминать об ошибках своих предков, но если ваша просьба искренна, я помогу.\n\n*Аврора изучает фрагменты.*\n\nЯ уверена, что это – Кристалл Зин-Малора, артефакт, содержащий в себе могучие силы тайной магии. Возможно, его использовали и во благо, но из-за злых намерений тех, кто его похитил, кристалл раскололся.\n\nОтправляйтесь в Храм Зин-Малор в Азшаре – я могу лишь надеяться, что книга все еще там.", progress = "Лишь по страницам священных записей я разберу, смогу ли помочь вам или нет…", completion = "Этих страниц долгие годы никто не касался…", rewards = "Вы получите:\n\n"},
[5247] = {title = "Фрагменты прошлого", objective = "Принесите зачарованный слиток тория, 5 кристаллов Восстановления и фиал пугающей воды Авроре Зову Небес к башне Северного Перевала, в Восточных Чумных землях.", description = "Я смогу помочь вам, если воссоздание артефакта действительно является вашим желанием.\n\nЧтобы воссоединить фрагменты, мне потребуются вещи, обладающие сильными магическими свойствами. Слитки зачарованного тория и пять кристаллов восстановления… Также вам нужно будет набрать воды из... необычного источника... Найдите Зловещий пруд на Пути Элдрета в Забытом Городе, что в Фераласе, и наполните этот фиал.\n\nПока вас не будет, я попытаюсь извлечь из этих страниц знание, как восполнить урон, нанесенный этой реликвии.", progress = "Реликвия должна быть в руках только того, кто заслуживает абсолютного доверия. Она не должна быть вновь похищена…", completion = "Используя эти компоненты, я сумею снова соединить эти фрагменты… надеюсь, получится именно то, чем эта реликвия когда-то являлась.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5248] = {title = "Измученный воспоминаниями о прошлом", objective = "Отнесите кристалл Зин-Малора к озеру Кел'Терил в Зимних Ключах и найдите духа высокорожденного, который согласится с вами поговорить.", description = "<имя>, Я скорблю о том, что раса эльфов была разрушена, подобно этому кристаллу. Я не знаю, соберутся ли когда-нибудь эти осколки воедино, и все же то, что я могу помочь тебе, уменьшает мою скорбь.\n\nМы не должны забывать о прошлом, <имя>...\n\nПожалуйста верни кристалл Зин-Малора к озеру Кел'Терил. Найди там духа высокорожденного, который, так же как и я, сожалеет о допущенных ошибках и скажи ему, что мы стремимся все исправить.", progress = "Прррроооокляааат.. Навееечноооо...", completion = "Оссстаааввь меняяяя...", rewards = "Вы получите:\n\n"},
[5249] = {title = "В Зимние Ключи!", objective = "Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником.", description = "В Зимних Ключах, к северу отсюда, много древних эльфийских руин. Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения.\n\nРабота здесь отнимает все мое время, так что у меня давно уже не было возможности самой добраться до Зимних Ключей. Но вам-то ничто не мешает!\n\nКогда будете там, поищите Вунда Ночного Охотника. Большую часть времени он проводит в деревне Звездопада и очень много знает о тех местах.", progress = nil, completion = "Друг Иви Росистой Листвы? Приятно познакомиться, Иштембек.", rewards = "Вы получите:\n\n"},
[5250] = {title = "Звездопад", objective = "Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником.", description = "В Зимних Ключах, к северу от Оскверненного леса, много древних эльфийских руин. Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения.\n\nЯ так занята своими исследованиями здесь, что у меня давно уже не было возможности самой добраться до Зимних ключей. Но у вас-то нет никаких причин для отказа от путешествия туда и изучения руин.\n\nКогда будете там, поищите Вунда Ночного Охотника. Большую часть времени он проводит в Звездопаде и очень много знает о том районе.\n\nСкажите ему, что вы <мой ученик/моя ученица>.", progress = nil, completion = "Ученик Дарин Доброго Ветра? Приятно познакомиться с вами, Эфром.", rewards = "Вы получите:\n\n"},
[5251] = {title = "Архивариус", objective = "Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алых.", description = "Впадать в крайности всегда опасно, <имя>. Взять, к примеру, Алый орден. Неужели такой слепой фанатизм способен привести к чему-то хорошему? Скольких невинных убили они во имя Света.\n\nЭто просто святотатство!\n\nВот что, один из этих негодяев мне особенно интересен – это архивариус Галфорд из Стратхольма. Этот человек отвечает за самые ценные документы ордена. Уничтожь его и сожги его архивы! Если справишься с этим, получишь достойную награду.", progress = nil, completion = "Отличная работа, Смоллетт! Ты уничтожил разведданные, собираемые Алым орденом годами! Алые будут в ярости...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5252] = {title = "Раскаявшийся высокорожденный", objective = "Поговорите с Вундом Ночным Охотником в деревне Звездопада и узнайте у него, куда нужно поместить кристалл Зин-Малора.", description = "Кри… кристалл…\n\nЗдешние высокорожденные находятся в плену их жалкого сущессствования…\n\nЯ полон горрречи, но я понимаю, в чем моя ошибка. И хотя изменить прошлое нееевозможно, теперь я обрел покой, зная, что тебе удалосссь добыть кристалл Зин-Малора...\n\nТы <должен/должна> вернуть крисссталл...\n\nОн должен быть воззвращен.", progress = "Прошло довольно много времени после твоего ухода, Драккард. Как прошло путешествие?", completion = "Это… это то, что я думаю?", rewards = "Вы получите:\n\n"},
[5253] = {title = "Кристалл Зин-Малора", objective = "Доставьте Кристалл Зин-Малора верховному друиду Фэндралу Оленьему Шлему в Дарнасс.", description = "Впечатляюще, <имя>. \n\nКристалл Зин-Малора никогда не вернется в храм, лежащий в руинах. Но я полагаю, что твои усилия уничтожить зло минувших лет не должно пойти прахом.\n\nНайди верховного друида Фэндрала Оленьего Шлема в Дарнассе, <имя>, и отдай ему кристалл. Он должен находится в руках тех, кто не злоупотребит его мощью. К тому же только самые сильные маги смогут управиться с артефактом такой мощи.", progress = "Да, |3-6(ночной эльф)?", completion = "Я слышал о кристалле Зин-Малора. Его обладатель получает практически неограниченную магическую мощь, но только если он достоин этого. Я впечатлен – вы не только умудрились добыть кристалл, вы еще и достаточно мудры, чтобы не пытаться его использовать самостоятельно.\n\nСпасибо, что принесли его мне, Драккард. Мы сохраним его, и пусть духи, охранявшие кристалл все это время, наконец-то обретут покой.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБирюзовый кушакНаплеч Плужного лесаРукавицы Изумрудного тумана\n\nВы также получите:\n\n"},
[5261] = {title = "Иган Меховщик", objective = "Поговорите с Иганом Меховщиком.", description = "Иган Меховщик ищет охотника на волков. Это добрая новость, поскольку в последнее время в Долине Североземья звери уж чересчур расплодились.\n\nЕсли тебе это интересно, то поговори с Иганом. Он за углом аббатства, если свернуть налево.", progress = nil, completion = "Что? Ищу ли я охотников на волков? Ну да, так и есть. А ты, наверное, ищешь работу?", rewards = "Вы получите:\n\n"},
[5262] = {title = "Ошеломляющая истина", objective = "Отнесите голову Бальназара герцогу Николасу Зверенхоффу в Восточные Чумные земли.", description = "В воздухе еще вихрится пыль, а вы пытаетесь собраться с мыслями и осознать произошедшее. И все же весь ужас вашего положения все же не укладывается в голове.\n\nВерховный рыцарь оказался демоном! И не просто демоном, а братом самого Вариматраса, верховного правителя Подгорода.\n\nВы бережно укладываете голову повелителя ужаса в суму. Разумеется, никто не поверит рассказанному вами без вещественных доказательств.\n\nНадо сообщить герцогу Николасу Зверенхоффу как можно скорее!", progress = "С чем пожаловал, Стиммакс?", completion = "Неужели все это время Алым Маршем правил демон! Все это время они служили злу, сами не подозревая об этом!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5263] = {title = "Быстрее, выше, сильнее", objective = "Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу.", description = "Ты <проявил/проявила> прирожденную склонность к разрушению и умеешь следовать приказам. Эти похвальные качества весьма редко сочетаются. Полагаю, ты можешь стать совершенным орудием высшего промысла.\n\n*Зверенхофф сжимает кулаки*\n\nКел'Тузад усадил своего мальчика на побегушках править в Стратхольме. Докажи мне свою верность и доблесть. Уничтожь барона Ривендера и принеси мне его голову.", progress = "На руках барона кровь стольких людей, скольких ты не видел в своей жизни.", completion = "Давно мне не приходилось объявлять о новых героях. Ты ты будешь первым, кого лорд Максвелл удостоит аудиенции за много лет.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5264] = {title = "Лорд Максвелл Тиросс", objective = "Поговорите с лордом Максвеллом Тироссом. Вы найдете его внутри храма.", description = "Тебе оказана большая честь, <имя>.\n\nЛорд Максвелл хочет наградить тебя за твои заслуги перед Серебряным Рассветом!\n\nПоверь мне, это большая честь – Максвелл уже много лет не удостаивал никого аудиенции.", progress = nil, completion = "Ты для нас очень ценный союзник, Стиммакс, и ты получишь достойную награду.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5265] = {title = "Серебряный Оплот", objective = "Откройте Серебряный Оплот и получите награду.", description = "Серебряный Оплот уже много лет закрыт и запечатан. Много лет не находилось достойных войти в него и прикоснуться к силе Серебряного Рассвета – до сегодняшнего дня.\n\nСеребряный Оплот распахнул врата перед тобой, <имя>.", progress = nil, completion = "Ух ты...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСеребряный МстительЗащитный щит Серебряного РассветаСеребряный рыцарь\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[5281] = {title = "Мятущиеся души", objective = "Найдите Эгана. В последний раз его видели недалеко от Стратхольма.", description = "Многие погибли во время битвы при Стратхольме. Многие предпочли расстаться с жизнью, бросившись в пламя пожара, чем повергнуться порче и примкнуть к Плети.\n\nТеперь они скитаются по улицам Стратхольма в обличье бесплотных призраков.\n\nМы должны помочь им, <имя>.\n\nУ меня есть помощник по имени Эган, он спец по призракам и духам. Найди его. Он, вероятно, сейчас в Восточных Чумных землях близ Стратхольма, проверяет свои изобретения.", progress = nil, completion = "Неужели Ален нашел кого-то, у кого будет довольно храбрости помочь мне?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5282] = {title = "Мятущиеся души", objective = "Стреляйте в призраков и неупокоенных на улицах Стратхольма из излучателя Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу.\n\nОсвободите 15 неупокоенных душ и возвращайтесь к Эгану.", description = "Только безграничная ненависть к Плети поддерживает во мне силы и желание жить. Но я не фанатик. Не такой, как этот сброд из Алого ордена – они скорее убьют невинную нежить, чем удостоят хоть каплей сочувствия.\n\nВозьми мой излучатель. С его помощью ты сможешь освободить истерзанные души, обреченные на скитания в Стратхольме.\n\nСтреляй в призраков, бродящих по улицам. Освободи их!", progress = nil, completion = "*Эган утирает скупую слезу*\n\nВидел ли ты мою матушку, Мардекай? Она обрела свободу?\n\nТы просто образец благородства. Прими эту скромную награду за труды...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЗавещание надежды"},
[5283] = {title = "Искусство изготовления брони", objective = "Изготовьте и отдайте Грумнусу 4 узорчатых мифриловых шлема, 2 узорчатых мифриловых сапога и 1 узорчатую мифриловую кирасу.", description = "Ты <принял/приняла> верное решение.\n\nМы со стариной Железнусом друг друга не перевариваем. Этот кустарь косорукий знает, кто тут настоящий мастер.\n\nВеликие войны не выигрываются без хорошего доспеха. Когда дойдет до дела, никакой меч не спасет.\n\nИ никак иначе, так что возьмемся-ка за работу. Тебе нужно только показать мне, что у тебя есть природный талант к делу. Потом я выкую из тебя настоящего бронника и как следует отшлифую. Знаешь, как делать узорчатый мифрил, а?", progress = "Ах, нет ничего краше доброго кузнечного загара. Сразу видно, у кого славный загар, по белым полосам от передника.", completion = "Самое оно, Улыбай. Теперь уж нельзя останавливаться. Нет, еще не поздно перейти на отковку шпилек, э-э-э, в оружейники податься.\n\nНо я уверен, что ты сделал верный выбор.", rewards = "Следующее заклинание будет наложено на вас:\n\nБронник-искусник\n\nВы получите:\n\n"},
[5284] = {title = "Путь оружейника", objective = "Сделайте и отдайте Железнусу 4 палаша лунной стали, 4 массивных железных топора, 2 тяжелых мифриловых топора и 2 большие черные палицы.", description = "Если станешь кузнецом, то к тебе очень часто будут обращаться за снаряжением всякие там герои и искатели приключений. Хотя порой работы невпроворот, спина ноет и дышать нечем, плата покрывает все с лихвой.\n\nДа, вот еще, <имя>, у кузнецов всегда водится золотишко!\n\nЕсли хочешь стать <одним/одной> из нас, тебе придется доказать, что ты сможешь заработать для меня пару звонких монет – то есть показать, что ты <усвоил/усвоила> все, чтобы стать специалистом по изготовлению оружия высшего качества. Приступай к работе!", progress = "*Железнус деловито складывает золотые монеты в аккуратные столбики.*", completion = "Как раз вовремя! Заказчики уже ждут.\n\nДавай сюда свои изделия да слушай внимательнее. Сейчас ты делаешь первый шаг в карьере оружейника.", rewards = "Следующее заклинание будет наложено на вас:\n\nОружейник-искусник\n\nВы получите:\n\n"},
[5301] = {title = "Искусство школы Брони", objective = "Чтобы присоединиться к школе Брони, изготовьте и отдайте Окотосу 4 изысканных мифриловых шлема, 2 пары изысканных мифриловых сапог и 1 изысканную мифриловую кирасу.", description = "Моя работа приносит мне подлинное удовлетворение! Когда я вижу гордого воина Орды, защищенного моими доспехами, я понимаю, зачем родился на свет. Это как наваждение, <имя>, я без этого просто жить не могу.\n\nКонечно, этому я тебя научить не смогу – я могу только указать тебе путь. Ведь кузнечное ремесло, как и любая жизненная стезя, – это путешествие.\n\nЕсли ты хочешь стать <одним/одной> из избранных, я, конечно, готов тебя учить. Но сначала тебе нужно выполнить мое задание.", progress = "Я буду ковать сталь, пока мое дыхание не иссякнет.", completion = "Это последний шаг перед тем, как ты начнешь свою новую карьеру в школе Брони, Вброне. Если ты колеблешься, сейчас твой последний шанс отступить. А иначе готовься к жизни, полной славы!", rewards = "Следующее заклинание будет наложено на вас:\n\nБронник-искусник\n\nВы получите:\n\n"},
[5302] = {title = "Путь оружейника", objective = "Изготовьте и отдайте Боргошу 4 палаша лунной стали, 4 массивных железных топора, 2 тяжелых мифриловых топора и 2 больших черных палицы.", description = "В один прекрасный день я создам легендарный молот. Молот, достойный вождя!\n\nЭто труд всей моей жизни, <имя>. Мое главное и единственное увлечение. Я вижу, что ты можешь стать <одним/одной> из нас – оружейником! И я помогу тебе в этом, если хочешь.\n\nТебе нужно только выполнить простое задание. При твоем мастерстве оно и впрямь несложное.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nОружейник-искусник\n\nВы получите:\n\n"},
[5305] = {title = "Секрет безмятежности", objective = "Отправляйтесь в Стратхольм и убейте Молотобойца из Багрового легиона. Возьмите его фартук и возвращайтесь к Лилит.", description = "В казематах Бастиона Алого ордена таится секрет безмятежности. Молотобоец из Багрового Легиона стережет его как зеницу ока. Срази его и принеси мне его фартук. За это я открою тебе секреты школы Молота.\n\nНо запомни. Если ты выберешь это умение, Школы Меча и Топора будут для тебя закрыты.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nМастер школы молота\n\nВы получите:\n\nЧертеж: зачарованный боевой молот"},
[5306] = {title = "Змеекамень Пленяющей Духов", objective = "Отправляйтесь на Пик Черной горы, убейте Темную охотницу Вос'гаджин. Заберите у нее змеекамень и принесите Килраму.", description = "Пусть ее красота не обманывает тебя, <класс>. Темная охотница Вос'гаджин безумна и смертельно опасна. \n\n*Килрам указывает на шрам у себя на лице.*\n\nДа, это ее рук дело – \"прикосновение любви\", как она выразилась. \n\nНаконец настал час отмщения. \n\nВос'гаджин ты найдешь на Пике Черной горы. Убей ее и принеси мне ее змеекамень. Сделай это, и я научу тебя секретам школы Топора.", progress = "Легенда гласит, что если хотя бы раз применить змеекамень Вос'гаджин, лезвие топора останется острым на тысячу лет!", completion = "Ты уверен. что тебе нужна именно эта школа? Помни, что это закроет для тебя возможность вступить в школу Меча или Молота.", rewards = "Следующее заклинание будет наложено на вас:\n\nМастер школы топора\n\nВы получите:\n\nЧертеж: Лезвие Рассвета"},
[5307] = {title = "Порча", objective = "Найдите в Стартхольме оружейника Черной Стражи и уничтожьте его. Возьмите его Знак Черной Стражи и принесите Сирилу Плетебою.", description = "Если кратко, на то есть причины. Чертежи для создания великого меча, известного под именем Порча, были похищены Черной стражей: элитным отрядом скелетов барона Ривендера. \n\nДа, именно, Ривендера из Стратхольма... \n\nОружейник Черной стражи хранит теперь эти чертежи как зеницу ока. \n\nУбей его и принеси доказательство его смерти, и в благодарность я научу тебя премудростям школы меча.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nМастер ковки клинков\n\nВы получите:\n\nЧертеж: пылающая рапира"},
[5321] = {title = "Спящий пробудился", objective = "Сопроводите Керлониана Вечный Сумрак к Лиладрис Лунной Реке на Заставу Мейстры в Ясеневом лесу.", description = "Я шел к Заставе Мейстры, чтобы встретиться с Лиладрис Лунная Река, но решил остановиться здесь и немного вздремнуть. С тех пор как я очнулся от Изумрудного Сна, я все время такой сонный...\n\n*зевает*\n\nНе откажетесь проводить меня? Я так понимаю, Застава Мейстры находится к югу отсюда, в Ясеневом лесу, у дороги. Путь может быть опасен; я надеюсь, у вас есть друзья, которые смогут составить нам компанию.\n\nДа, и вот еще что: я могу заснуть по дороге, так что если вам нужно будет меня разбудить, сделайте это с помощью моего рога. Он в этом сундуке.", progress = "Прибыл ли Керлониан?", completion = "О, я так рада, что Керлониан смог сюда добраться. И я уверена, что найду его спящим где-нибудь поблизости, ведь так?\n\nСпасибо вам за то, что показали ему дорогу, Wrestlecake.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСовиная винтовкаДубинка Нефритового пальцаСтальной щит\n\nВы также получите:\n\n"},
[5341] = {title = "Сокровище Баровых", objective = "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову.", description = "В Некроситете находятся сокровища семейства Баровых. Я, Алексий Баров, один из двух оставшихся наследников нашего дома. Второй – мой брат, Велдон.\n\nЭтот жалкий трус бежал во время войны и по-прежнему длит свое никчемное существование в человеческом обличье.\n\nСейчас он ищет документы, чтобы унаследовать все состояние. Доберись до этих документов раньше моего брата, и я озолочу тебя!", progress = "Кланяйся, |3-6(нежить). В конце концов, я дворянин, а ты – деревенщина без гроша за душой.", completion = "Отличная работа, |3-6(нежить). Теперь главное – подтвердить мое право наследования...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5342] = {title = "Последний из Баровых", objective = "Отправляйтесь в Лагерь Промозглого Ветра – на земли Альянса – и убейте Велдона Барова. Отнесите его голову Алексию Барову.\n\nСоблюдайте осторожность – скорее всего, Велдона охраняет мразь Альянса.", description = "Естественно, пока мой брат жив, могут возникать вопросы о порядке наследования. Я не допущу этого.\n\nПолагаю, ты, шваль, не побоишься замарать руки убийством.\n\nЗадание простое, надеюсь, ты справишься; если хочешь получить награду.\n\nУэлдон сидит под крылышком у Альянса в Лагере Промозглого Ветра на востоке. Убей его и принеси мне голову.\n\n*Алекси зевает.*\n\nДавай-давай, иди.", progress = "Обеспечишь мне получение наследства, получишь свою долю.", completion = "Чудесно! Теперь лишь в моих руках мощь и все сокровища дома Баровых.\n\n*Алекси швыряет в вас большим мешком.*\n\nСдачу оставь себе, животное.", rewards = "Вы получите:\n\nНабатный колокол рода Баровых"},
[5343] = {title = "Сокровище Баровых", objective = "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Велдону Барову.", description = "Милый братец Алекси. И зачем я, глупец, пощадил его? Я смотрел в лицо врага, нежити, и оставил его в живых.\n\n*Уэлдон сплевывает.*\n\nОн хочет отобрать МОЕ наследние. Не бывать тому!\n\nНайди документы на мои владения, прежде чем эта мерзость дотянется до них своими костлявыми ручками, и получишь большую награду. Документы находятся в руинах Некроситета. Спеши!", progress = "Позаботься о моей будущем, а я позабочусь о твоем.", completion = "Я хочу дать тебе еще одно задание, Мяуыч.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5344] = {title = "Последний из Баровых", objective = "Отправляйтесь в Бастион – на земли Орды – и убейте Алексия Барова. Отнесите его голову Велдону Барову.\n\nСоблюдайте осторожность – скорее всего, Алексия охраняет ордынская мразь.", description = "Документы у меня в руках, осталось только одно. Алекси придется убить. Когда он умрет, я смогу вздохнуть спокойно, не ожидая гибели от руки наемного убийцы.\n\nЗадание простое. Алекси находится под покровительством Орды – в Бастионе.\n\nНет, я не требую, чтобы ты прямо <взял и убил/взяла и убила> его, мне голова нужна! А как ты ее получишь... твое дело. Подобные размышления ниже моего аристократического достоинства.", progress = "Ты хочешь денег, да?", completion = "О радость, о счастье! Наконец-то черная овца в стаде семьи Баровых мертва, и я получил наследство!\n\nВозьми деньги и убирайся, деревенщина.", rewards = "Вы получите:\n\nНабатный колокол рода Баровых"},
[5361] = {title = "Семейное древо", objective = "Доставьте отчет стража утеса Долгорога Натаке Длинному Рогу на Заставу Скитающихся Духов в Пустоши.", description = "Мой брат, Натака, находится на Заставе Скитающихся Духов в Пустошах. Я хотел бы попросить вас... не доставите ли ему этот отчет? С тех пор, как я писал ему последний раз, прошел целый год, и вот сейчас кентавры опять что-то затевают. Мой брат должен узнать обо всем.\n\nВам нужно будет отправиться в Каменный Коготь – это горы к северу от Перекрестка, а потом свернуть на запад, в Обугленную долину. Пустоши находятся южнее долины. Следуйте по дороге на юг, и скоро увидите Заставу Скитающихся Духов.", progress = "Что у вас за новости, |3-6(Воин)? Ах, неужели это письмо от моего брата? Ну что ж, давайте его сюда!", completion = "Не знаю, как вы связаны с моим братом, но, вижу, он вам доверяет, |3-6(Воин).\n\nЯ – Натака Длинный Рог, и я приветствую вас на Заставе Скитающихся Духов! Воин нам здесь точно не помешает. Поговорите с другими, наверняка у них найдется работа для вас.", rewards = "Вы получите:\n\n"},
[5381] = {title = "Рука Ируксоса", objective = "Добудьте в Крепости Громового Топора Демоническую шкатулку, а затем принесите ее и кирку демонов Тайге Мудрой Гриве в Деревню Ночных Охотников.", description = "В руки клана Пылающего Клинка попала демоническая шкатулка, в которой хранится могущественный артефакт – Рука Ируксоса. Орки из клана Пылающего Клинка используют ее, чтобы открывать демонические порталы на поле Маннорок. Мы должны остановить нашествие демонов, захлестывающее наш мир, <имя>!\n\nРасколи красный кристалл в крепости Громового Топора этой киркой демонов: так ты сможешь добыть демоническую шкатулку.", progress = "Эй, Томпсон, а где Демоническая шкатулка?", completion = "О, Демоническая шкатулка... Наконец-то я увидел ее. Послушай, |3-6(Охотник), дай-ка ее мне, и я ее открою... и покажу тебе Руку Ируксоса.", rewards = "Вы получите:\n\n"},
[5382] = {title = "Доктор Теолен Крастинов – Мясник", objective = "Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф.", description = "Крастинов виновен в тысячах смертей. Справедливость должна восторжествовать – пусть он вкусит собственного блюда.\n\nНайди его и заставь испытать мучения его бессчетных жертв. Когда он умрет, сожги наши останки. Пусть обратятся в пепел, <имя>.", progress = "Мясника должно остановить!", completion = "Душа моя исцелена, Стиммакс. Ты оказал нам с мужем огромную услугу, но это еще не все.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5383] = {title = "Мешок ужасов Крастинова", objective = "Отнесите мешок ужасов Еве Саркофф в Каэр Дарроу.\n\nПрилагается предмет: \n", description = "Вы открываете мешок. Внутри – различные инструменты пытки. Ваше внимание привлекает странный предмет – сосуд крови, все еще теплый.\n\nПожалуй, Саркофф могла бы заинтересоваться вашей находкой.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[5384] = {title = "Киртонос Глашатай", objective = "Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос.\n\nСражайтесь как герой, не сдавайтесь! Уничтожьте Киртоноса и возвращайтесь к Еве Саркофф.", description = "Вот она, <имя>.\n\n*Ева указывает на сосуд в мешке.*\n\nКровь невинных. Чистейшая кровь, умилостивление хозяина Крастинова.\n\nПри помощи этой крови можно вызвать Киртоноса, и именно она поможет его уничтожить.\n\nОтнести эту кровь на балкон, помести в жаровню. Киртонос явится на зов – он не сможет устоять. Когда он явится, обрушь на него ярость и гнев тысяч невинно убиенных.\n\nЕсли ты добьешься успеха, мы на славу отблагодарим тебя.", progress = "Соблюдай осторожность, Киртонос – опытный боец.", completion = "Киртонос мертв, и страшная глава истории Некроситета подошла к концу. Но твои деяния не окончены. Многие узнали о твоих подвигах. Возьми это, Медведик. Это часть нашей сущности. При ее помощи ты сможешь связаться с другими павшими душами Каэр Дарроу.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nРоза ПенелопыПесня Мираха\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nСущность привидения"},
[5385] = {title = "Останки Трея Светогорна", objective = "Принесите останки Трея Светогорна Джессире Лунной Радуге в Оскверненный лес.", description = "Вы осторожно поднимаете мешок и собираетесь возвращаться к Джессире Лунной Радуге на границу Ясеневого леса и Оскверненного леса. Вы надеетесь, что паладин будет с почестями погребен, когда его останки будут доставлены его друзьям.", progress = "Как дела в Джеденаре, Кастрол?", completion = "Тебе удалось! Хвала Элуне и всем силам, что ты почитаешь, Кастрол! Сегодня ты совершил деяние благое и почетное. Я уверена, что Арконарин возрадуется, узнав, что ты не только спас ее, но так же убил тварь, которая истязала одного из лучших ее друзей.\n\nЯ бы хотела сделать для тебя больше, но прошу тебя – прими эту скромную награду.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКлинок Охотничьей ящейкиКлинок Гребня прилива\n\nВы также получите:\n\n"},
[5386] = {title = "Дорога рыбка к обеду", objective = "Отправляйтесь в Деревню Ночных Охотников и поговорите с Джинар'Зилленом, а затем принесите Натаке Длинному Рогу 2 рыбы-кровобрюха.", description = "Давненько на Заставе Скитающихся Духов не наслаждались запахом жареной рыбки... Тролли, живущие в Деревне Ночных Охотников – отличные рыбаки, вот только из-за разбушевавшихся в наших краях кентавров мне никак не выкроить времени, чтобы добраться до них.\n\nПослушай-ка, окажи мне услугу: отправляйся в Деревню Ночных Охотников. Разыщи там Джинар'Зиллена, потолкуй с ним и принеси мне рыбок-кровобрюхов: я их просто обожаю! На юг отсюда идет дорога: она приведет тебя аккурат в деревню троллей.", progress = "У меня копыта подергиваются и слюни текут от нетерпения, как подумаю о жареном кровобрюхе... Ты ведь принес мне кровобрюха, верно?", completion = "Ты просто спас меня, Томпсон! А эти кровобрюхи так хороши, что хоть сырыми их ешь.\n\n*Натака сглатывает слюну.*\n\nНу, давай, давай скорее, выбери один из этих предметов в уплату за рыбу!..", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМифриловая рудаПлотная кожаМагическая ткань\n\nВы также получите:\n\n"},
[5401] = {title = "Жетон Серебряного Рассвета", objective = "Все, кто сражаются со злом во имя Серебряного Рассвета, должны получить наш амулет. Он даст тебе право получать награды у наших интендантов.\n\nПока ты носишь его на шее, ты сможешь собирать камни Плети с убитой нежити; да-да, иногда они носят такие знаки различия. Собирай их и приноси мне. За каждый набор ты получишь по знаку доблести Серебряного Рассвета – так мы благодарим наших героев.\n\nСтупай навстречу судьбе – вступай в битву со злом!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЖетон Серебряного Рассвета"},
[5402] = {title = "Камни приспешников плети", objective = "Камни Плети приспешников – знаки различия Плети. Иногда их можно найти у нежити, у более слабых бойцов, хотя слово \"слабый\" – относительное понятие. Не стоит недооценивать Плеть. \n\nОт имени Серебряного Рассвета я готов вручить тебе по знаку доблести за каждые двадцать камней, причем с радостью – чем больше ты убьешь приспешников Плети, тем лучше.", description = nil, progress = "Камни Плети приспешников – знаки различия Плети. Иногда их можно найти у нежити, у более слабых бойцов, хотя слово \"слабый\" – относительное понятие. Не стоит недооценивать Плеть. \n\nОт имени Серебряного Рассвета я готов вручить тебе по знаку доблести за каждые двадцать камней, причем с радостью – чем больше ты убьешь приспешников Плети, тем лучше.", completion = "Поздравляю, Эст – и с радостью вручаю тебе знак доблести Серебряного Рассвета!\n\nЭти знаки служат двум целям – во-первых, позволяют упрочить твои позиции в Серебряном Рассвете; благодаря этому тебе станут доступны возможности и награды, которые мы бережем для самых преданных наших сторонников. Во-вторых – их можно отдавать нашим интендантам вместе с деньгами и получать ценные предметы, которые изготовляют в нашем ордене.\n\nТак или иначе, ты их заслужил сполна. Молодец!", rewards = "Вы получите:\n\nЗнак доблести Серебряного Рассвета"},
[5403] = {title = "Камни захватчиков Плети", objective = "Камни Плети приспешников – знаки различия элитных войск Плети. Порой их можно найти у сильных бойцов в Чумных землях. Убить таких бойцов – настоящий подвиг, который должно совершать во имя борьбы со злом.\n\nВ настоящий момент Серебряный Рассвет предлагает по знаку доблести в обмен на десять таких камней. Принеси их мне, и непременно получишь достойную награду.", description = nil, progress = "Камни Плети приспешников – знаки различия элитных войск Плети. Порой их можно найти у сильных бойцов в Чумных землях. Убить таких бойцов – настоящий подвиг, который должно совершать во имя борьбы со злом.\n\nВ настоящий момент Серебряный Рассвет предлагает по знаку доблести в обмен на десять таких камней. Принеси их мне, и непременно получишь достойную награду.", completion = "Поздравляю, Хлуси – и с радостью вручаю тебе знак доблести Серебряного Рассвета!\n\nКаждый выданный знак доблести приближает час победы над Плетью! Все больше героев вступают в бой с Плетью на ее землях, и Серебряный Рассвет несомненно будет в первых рядах той армии, что решится положить конец бесчинством прихвостней Повелителя Тьмы. Надеюсь, твоей доблести хватит и до того дня!", rewards = "Вы получите:\n\nЗнак доблести Серебряного Рассвета"},
[5404] = {title = "Камни осквернителей Плети", objective = "Камень Плети Осквернителя – знак различия предводителей Плети. Он есть у каждого обладающего властью в Плети. Убийство этих проклятых тварей служит благу Серебряного Рассвета... да и вообще всеобщему благу!\n\nОт имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков. Только соблюдай осторожность, Вилдан – с этими тварями шутки плохи.", description = nil, progress = "Камень Плети Осквернителя – знак различия предводителей Плети. Он есть у каждого обладающего властью в Плети. Убийство этих проклятых тварей служит благу Серебряного Рассвета... да и вообще всеобщему благу!\n\nОт имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков. Только соблюдай осторожность, Вилдан – с этими тварями шутки плохи.", completion = "Поздравляю, Вилдан – и с радостью вручаю тебе знак доблести Серебряного Рассвета!\n\nТе, кто удостаивается этих знаков – подлинные борцы за добро. Мы благодарны всем, кто выступает против Плети, но убийство одного из ее главарей – настоящий подвиг и тяжелейший удар по нашему противнику!\n\nЗа Рассвет, брат мой!", rewards = "Вы получите:\n\nЗнак доблести Серебряного Рассвета"},
[5405] = {title = "Жетон Серебряного Рассвета", objective = "Все, кто сражаются со злом во имя Серебряного Рассвета, должны получить наш амулет. Он даст тебе право получать награды у наших интендантов.\n\nПока ты носишь его на шее, ты сможешь собирать камни Плети с убитой нежити; да-да, иногда они носят такие знаки различия. Собирай их и приноси мне. За каждый набор ты получишь по знаку доблести Серебряного Рассвета – так мы благодарим наших героев.\n\nСтупай навстречу судьбе – вступай в битву со злом!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЖетон Серебряного Рассвета"},
[5406] = {title = "Камни осквернителей Плети", objective = "Камень Плети Осквернителя – знак различия предводителей Плети. Он есть у каждого обладающего властью в Плети. Убийство этих проклятых тварей служит благу Серебряного Рассвета... да и вообще всеобщему благу!\n\nОт имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков. Только соблюдай осторожность, Херин – с этими тварями шутки плохи.", description = nil, progress = "Камень Плети Осквернителя – знак различия предводителей Плети. Он есть у каждого обладающего властью в Плети. Убийство этих проклятых тварей служит благу Серебряного Рассвета... да и вообще всеобщему благу!\n\nОт имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков. Только соблюдай осторожность, Херин – с этими тварями шутки плохи.", completion = "Поздравляю, Херин – и с радостью вручаю тебе знак доблести Серебряного Рассвета!\n\nТе, кто удостаивается этих знаков – подлинные борцы за добро. Мы благодарны всем, кто выступает против Плети, но убийство одного из ее главарей – настоящий подвиг и тяжелейший удар по нашему противнику!\n\nЗа Рассвет, брат мой!", rewards = "Вы получите:\n\nЗнак доблести Серебряного Рассвета"},
[5407] = {title = "Камни захватчиков Плети", objective = "Камни Плети приспешников – знаки различия элитных войск Плети. Порой их можно найти у сильных бойцов в Чумных землях. Убить таких бойцов – настоящий подвиг, который должно совершать во имя борьбы со злом.\n\nВ настоящий момент Серебряный Рассвет предлагает по знаку доблести в обмен на десять таких камней. Принеси их мне, и непременно получишь достойную награду.", description = nil, progress = "Камни Плети приспешников – знаки различия элитных войск Плети. Порой их можно найти у сильных бойцов в Чумных землях. Убить таких бойцов – настоящий подвиг, который должно совершать во имя борьбы со злом.\n\nВ настоящий момент Серебряный Рассвет предлагает по знаку доблести в обмен на десять таких камней. Принеси их мне, и непременно получишь достойную награду.", completion = "Поздравляю, Херин – и с радостью вручаю тебе знак доблести Серебряного Рассвета!\n\nКаждый выданный знак доблести приближает час победы над Плетью!Все больше героев вступают в бой с Плетью на ее землях, и Серебряный Рассвет несомненно будет в первых рядах той армии, что решится положить конец бесчинством прихвостней Повелителя Тьмы. Надеюсь, твоей доблести хватит и до того дня!", rewards = "Вы получите:\n\nЗнак доблести Серебряного Рассвета"},
[5408] = {title = "Камни приспешников плети", objective = "Камни Плети приспешников – знаки различия Плети. Иногда их можно найти у нежити, у более слабых бойцов, хотя слово \"слабый\" – относительное понятие. Не стоит недооценивать Плеть. \n\nОт имени Серебряного Рассвета я готов вручить тебе по знаку доблести за каждые двадцать камней, причем с радостью – чем больше ты убьешь приспешников Плети, тем лучше.", description = nil, progress = "Камни Плети приспешников – знаки различия Плети. Иногда их можно найти у нежити, у более слабых бойцов, хотя слово \"слабый\" – относительное понятие. Не стоит недооценивать Плеть. \n\nОт имени Серебряного Рассвета я готов вручить тебе по знаку доблести за каждые двадцать камней, причем с радостью – чем больше ты убьешь приспешников Плети, тем лучше.", completion = "Поздравляю, Херин – и с радостью вручаю тебе знак доблести Серебряного Рассвета!\n\nЭти знаки служат двум целям – во-первых, позволяют упрочить твои позиции в Серебряном Рассвете; благодаря этому тебе станут доступны возможности и награды, которые мы бережем для самых преданных наших сторонников. Во-вторых – их можно отдавать нашим интендантам вместе с деньгами и получать ценные предметы, которые изготовляют в нашем ордене.\n\nТак или иначе, ты их заслужил сполна. Молодец!", rewards = "Вы получите:\n\nЗнак доблести Серебряного Рассвета"},
[5421] = {title = "Рыбка в ведерке", objective = "Я награжу любого, кто хоть немного облегчит мою жизнь... Чем меньше я делаю, тем мне лучше, дружище!\n\nЗдесь неподалеку, в Деревне Ночных Охотников, прямо за пристанью, я расставил ловушки на моллюсков. Много, много ловушек! Будь так любезен, сделай за меня мою работу: собери улов и принеси мне, а я уж тебя награжу кое-чем нужным... понимаешь мою мысль, да? За каждые пять моллюсков я дам тебе по отличной рыбе-кровобрюху!", description = nil, progress = "Я награжу любого, кто хоть немного облегчит мою жизнь... Чем меньше я делаю, тем мне лучше, дружище!\n\nЗдесь неподалеку, в Деревне Ночных Охотников, прямо за пристанью, я расставил ловушки на моллюсков. Много, много ловушек! Будь так любезен, сделай за меня мою работу: собери улов и принеси мне, а я уж тебя награжу кое-чем нужным... понимаешь мою мысль, да? За каждые пять моллюсков я дам тебе по отличной рыбе-кровобрюху!", completion = "Ах, дружочек, нет ничего лучше хорошо сделанной работы, особенно когда делаешь ее не ты... Верно ведь?", rewards = "Вы получите:\n\nРыба-кровобрюх"},
[5441] = {title = "Ленивые батраки", objective = "Проучите ленивых батраков дубинкой старшины. Разбудите 5 батраков, потом верните дубинку штейгеру Тазз'рилу в долине Испытаний.", description = "Проклятые батраки! Им велено валить лес, но они все время пытаются отлынивать. Мне нужен кто-то, кто их приструнит. Ты, <раса>, мне, пожалуй, годишься. На тебе дубинку – ступай и всыпь этим бездельникам. Хороший тумак заставит их взяться за ум! Управишься – не забудь вернуть дубинку.\n\nПроклятые лентяи...", progress = "Негодяи, бездельники…\n\nЧто? Где моя дубинка? Ну что, удалось тебе всыпать этим лентяям?", completion = "Отлично, отлично! В следующий раз будут знать, как дрыхнуть на работе! Спасибо за помощь!", rewards = "Вы получите:\n\n"},
[5461] = {title = "Рас Ледяной Шепот – человек", objective = "Отправляйтесь в высокогорья Арати, в руины Стромгарда. Поищите в Стромгарде книгу Воспоминаний. Если удастся ее отыскать, отнесите ее мировому судье Мардуку.", description = "Нежить боится жизни не меньше, чем живые – смерти. Ступившие на путь не-жизни нередко уничтожают все свидетельства прежнего бытия.\n\nК сожалению, для создания артефакта, способного превратить Раса Ледяной Шепот в смертного, мы должны отыскать какой-то предмет, сохранившийся со времени его настоящей жизни.\n\nОтправляйся в разрушенный город Стромгард, родину Ледяного Шепота, и найди такой предмет. Удачи тебе, <имя>.", progress = "Да, книгу Воспоминаний нелегко найти, Джэйлол.", completion = "Честно говоря, я сомневался, что эта вещь вообще существует. Перед нами открывается удивительная возможность – главное, ее не пропустить.\n\nГотовься, Джэйлол, ведь то, о чем я тебя попрошу, низведет тебя в самые глубины Преисподней.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5462] = {title = "Рас Ледяной Шепот – гибель", objective = "Отправляйтесь в часовню Светлых надежд в Восточных Чумных землях и найдите Леонида Бартоломея Чтимого. Покажите ему книгу Воспоминаний и расскажите обо всем, о чем удалось узнать.", description = "Оскверненной душе можно противопоставить особые памятные предметы.\n\nГоворят, будто Снегошепот встал под знамена Короля-лича в Стратхольме. Он добровольно лишил себя жизни с целью влиться в ряды нежити.\n\nИменно в тех землях следует искать память о его человеческом облике.\n\nВ часовне Светлых надежд ты найдешь Леонида Бартоломея Чтимого, некогда бывшего рабом Плети, освобожденного королевой банши, но отдавшего свою верность Серебряному Рассвету. Быть может, он знает больше, чем я. В путь!", progress = "Не задавай вопросов, если не хочешь узнать ответы.", completion = "*Леонид проглядывает книгу.*\n\nТы заставляешь меня вспоминать события, о которых хотелось забыть навек.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5463] = {title = "Дар Менетила", objective = "Отправляйтесь в Стратхольм и отыщите Дар Менетила. Положите книгу Воспоминаний на оскверненную землю.", description = "Рас Снегошепот некогда тоже был человеком. Я собственными глазами видел, как он вручил свою бессмертную душу Королю-личу. Он приставил к своему горлу кинжал и с улыбкой перерезал себе глотку от уха до уха. Его мертвое тело упало в центр пентаграммы. Король-лич бросил взгляд на мертвого мага, и в ту же секунду Рас Снегошепот восстал в обличье Короля-лича.\n\n*Леонид опускает глаза на мгновенье и снова продолжает рассказ*\n\nДа, <раса>, я помню. У того, что ты ищешь, есть имя – Дар Менетила: это земля, благословленная Королем-личом – священное место Плети.", progress = "От Дара Менетила веет могильным холодом.", completion = "Вы кладете книгу на оскверненную землю.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5464] = {title = "Дар Менетила", objective = "Отнесите Книгу Души Леониду Бартоломею в Восточные Чумные земли.", description = "Души падших цепляются за любое олицетворение их прежное жизни и превращают любой значимый для них предмет в Книгу Души. Вы поднимаете предмет и прячете в сумку.", progress = "*Леонид вздрагивает*", completion = "Как эта душа цепляется за книгу, также она будет цепляться и за человеческое обличье Раса Ледяного Шепота.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5465] = {title = "Книга Души", objective = "Возвращайтесь к мировому судье Мардуку в Каэр Дарроу. Покажите ему Книгу Души.", description = "Отнеси книгу Мардюку, <имя>, он расскажет тебе, что делать дальше.", progress = "Неужели тебе удалось сделать невозможное?", completion = "Признаться, я ожидал вновь увидеть тебя в обличье несчастного призрака.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5466] = {title = "Рас Снегошепот – лич", objective = "Отыщите в Некроситете Раса Снегошепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Снегошепота. Отнесите голову мировому судье Мардуку.", description = "Осталось одно задание, <имя> – бросить вызов личу Расу Снегошепоту.\n\nВоспользуйся против него силой Книги – не знай пощады! Терпи удары, которые обрушит на тебя злобная тварь. Не бойся боли!\n\nКогда ритуал будет завершел, Рас снова станет смертным. Именно в этот момент его необходимо убить. Срази злодея и забери его голову", progress = "На твоих плечах покоится бремя тысяч неупокоенных душ, Кастрол.", completion = "Десять тысяч душ возопили единым гласом! Ты нанес смертельный удар Плети и ее хозяевам.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБоевой клинок Каэр ДарроуКорона Каэр ДарроуПика Дэрроу\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nСильностраж Дарроушира"},
[5481] = {title = "Задание Толстяка", objective = "Соберите 3 ветки мракоцвета для младшего аптекаря Холланда на кладбище Брилла.", description = "Хозяину надо растения. У нас большие руки, цветы рвать никак. Ты нам помогать, мы тебя не трогать. Нам надо мракоцвет, он растет тут и у дороги.\n\nТы соберешь – отнеси хозяину Холланду на кладбище в Брилл.", progress = "Где это никчемное поганище? Ты принес мне то, что мне нужно? Если нет, то иди и не возвращайся, пока не соберешь достаточно цветков!", completion = "Что это? Мракоцвет?! Зачем он мне сдался?! Эта тупая гора мяса собирает ромашки и привлекает – сколько, Темная Госпожа знает, – к этому делу таких простаков, как ты! Без обид.\n\nЛадно, главное, что ты здесь. Я не собираюсь тратить свое время на то, чтобы объяснить этому поганищу элементарные вещи. Так что, может, ты соберешь для меня этот проклятый погибельник?", rewards = "Вы получите:\n\n"},
[5482] = {title = "Погибельник", objective = "Соберите 10 веток погибельника для младшего аптекаря Холланда.", description = "Теперь ты понимаешь, в каком затруднительном положении я нахожусь, <имя>? Это нечто все еще ходит там и собирает не те растения. Я непременно отблагодарю тебя, если ты соберешь то, что мне нужно. Принеси мне погибельник, и я щедро тебя награжу.\n\nНасколько я знаю, его можно найти у братских могил, к северу от кладбища Брилла. Поторопись – и будь <осторожен/осторожна> – в тех местах полно гноллов.", progress = "Я полагаю, ты уже собрал достаточно погибельника?", completion = "А, мой погибельник! Превосходно!\n\n&lt;Младший аптекарь Холланд жадно потирает ладони.&gt;\n\nОн мне очень пригодится. Ты оказал мне, ой, то есть Темной Госпоже, большую услугу, Веланокс. Как я и обещал, вот твоя награда.", rewards = "Вы получите:\n\n"},
[5501] = {title = "Собиратель костей", objective = "Принесите 10 костей с Кладбища кодо в хижину Кормека и отдайте Биббли Скобкофузу.", description = "Мы тут на золотой жиле сидим, на золотой жиле! Знаешь, что это? Кости кодо!.. Кости кодо изменят мир раз и навсегда! У меня масса клиентов, которые делают из этих костей мебель, музыкальные инструменты – даже взрывчатый порошок, чтоб тебе знать!\n\nСюда приходит караван, забирает у меня кости, а потом караванщики продают их в Деревне Ночных Охотников. И неплохая выручка, да, очень неплохая... Если пойдешь на юг отсюда, то доберешься прямиком до Кладбища кодо. Принеси мне десяток костей, а я дам тебе кое-что взамен. Ну что, идет?", progress = "Ну, где они, мои косточки, где же они? Караван вот-вот придет. Всего десять костей – и это будет мой звездный час, клянусь чем угодно! Вот увидишь!", completion = "Ох, вот они, мои косточки, мои драгоценные!..\n\nЯ стану самым богатым гоблином в мире, я прославлюсь, мое лицо не будет сходить с обложек \"Каравана истории\", и тогда они все еще увидят, кто я такой! Да-да, особенно тот зеленый сморчок, который вечно твердил: \"Ничего достойного в жизни совершить не сможешь ты!\"", rewards = "Вы получите:\n\nКостяное ожерелье Кодобона"},
[5502] = {title = "Опекун Орды", objective = "Возвратите своего подопечного в приют Оргриммара, вернув орочий сиротский свисток попечительнице сирот Батлвейл в Аллею Чести.", description = "Ты <был/была> очень <добр/добра> ко мне, <имя>. Я и представить не мог, что Детская неделя пройдет так весело. Спасибо. Я не хочу печалиться из-за собственной судьбы – предки всегда говорили мне, что я должен быть выше всех несчастий. Знаешь, когда я вырасту, я хочу стать героем... как ты.\n\nКак ни жаль, мне пора домой. Давай вернемся, и я расскажу нашей попечительнице, что ты лучше всех!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОшейник поросенкаКрысиная клеткаЧерепаха в коробочкеРасплата скупца\n\nВы также получите:\n\n"},
[5503] = {title = "Жетон Серебряного Рассвета", objective = "Все, кто сражаются со злом во имя Серебряного Рассвета, должны получить наш амулет. Он даст тебе право получать награды у наших интендантов.\n\nПока при тебе амулет, ты можешь собирать камни Плети с убитой нежити – иногда они носят такие знаки различия. Собирай их и приноси мне. За каждый из них ты получишь по знаку доблести Серебряного Рассвета – так мы благодарим наших героев.\n\nСтупай на встречу судьбе – вступай в битву со злом!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЖетон Серебряного Рассвета"},
[5504] = {title = "Оплечья Рассвета", objective = "Принесите 10 знаков доблести Серебряного Рассвета интенданту Хасане в Бастион.", description = "Тебе причитается награда за верную службу Серебряному Рассвету, <имя>. Тебе удалось завоевать всеобщее почтение. Мне поручено передать – ты можешь купить один из самых наших ценных предметов – оплечье защиты от магии.\n\nЕсли прикрепить его к доспехам, твое сопротивление силам одного из направлений магии возврастет. За это оплечье я попрошу от тебя не менее 10 знаков доблести Серебряного Рассвета.", progress = "А, благородный |3-6(Жрец)! Ты принес мне знаки доблести? Как только ты передашь мне все десять, я предложу на выбор наши оплечья.", completion = "Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока наше отношение к тебе не изменится, ты сможешь купить эти мантии у любого интенданта Серебряного Рассвета.\n\nЗа Рассвет, брат мой!", rewards = "Вы получите:\n\n"},
[5505] = {title = "Ключ от Некроситета", objective = "Ну, вот, готово, Август – это ключ от Некроситета. Я не сомеваюсь, что он позволит тебе проникнуть в пределы школы. Впрочем, есть лишь один способ узнать наверняка. И не теряй времени даром.\n\nУдачи тебе, герой. Да рассеют твои победы мрак!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nОтмычка"},
[5507] = {title = "Оплечья Рассвета", objective = "Принесите 10 знаков доблести Серебряного Рассвета интенданту Искре Света в Лагерь Промозглого Ветра.", description = "Тебе причитается награда за верную службу Серебряному Рассвету, <имя>. Тебе удалось завоевать всеобщее почтение. Мне поручено передать – ты можешь купить один из самых наших ценных предметов – оплечье защиты от магии.\n\nЕсли прикрепить его к доспехам, твое сопротивление силам одного из направлений магии возврастет. За это оплечье я попрошу от тебя не менее 10 знаков доблести Серебряного Рассвета.", progress = "А, благородный |3-6(Охотник)! Ты принес мне знаки доблести? Как только ты передашь мне все десять, я предложу на выбор наши оплечья.", completion = "Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока отношение нашего ордена к тебе не изменится, ты сможешь купить эти мантии у любого интенданта Серебряного Рассвета.\n\nЗа Рассвет, брат мой!", rewards = "Вы получите:\n\n"},
[5508] = {title = "Камни осквернителей Плети", objective = "Камень Плети Осквернителей – знак различия предводителей Плети. Их всегда можно найти у наиболее могучих тварей. Конечно, для этого придется их убить, тем самым способствуя делу Серебряного Рассвета и добра вообще!\n\nОт имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков. Только соблюдай осторожность, Мард – с этими тварями шутки плохи.", description = nil, progress = "Камень Плети Осквернителей – знак различия предводителей Плети. Их всегда можно найти у наиболее могучих тварей. Конечно, для этого придется их убить, тем самым способствуя делу Серебряного Рассвета и добра вообще!\n\nОт имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков. Только соблюдай осторожность, Мард – с этими тварями шутки плохи.", completion = "Поздравляю, Мард! С гордостью вручаю тебе знак доблести Серебряного Рассвета.\n\nТолько настоящие герои и воины добра получают его. Мы ценим любые деяния, направленные против подлой Плети, но убийство одного из их лидеров заслуживает особого почтения!\n\nВо имя Рассвета, брат!", rewards = "Вы получите:\n\nЗнак доблести Серебряного Рассвета"},
[5509] = {title = "Камни захватчиков Плети", objective = "Камни Плети Захватчиков – знаки различия элитных войск Плети. Порой их можно найти у сильных бойцов в Чумных землях. Убить таких бойцов – настоящий подвиг, который должно совершать во имя борьбы со злом.\n\nСеребряный Рассвет вручает знак доблести в обмен на десять таких камней. Принеси их мне, и непременно получишь достойную награду.", description = nil, progress = "Камни Плети Захватчиков – знаки различия элитных войск Плети. Порой их можно найти у сильных бойцов в Чумных землях. Убить таких бойцов – настоящий подвиг, который должно совершать во имя борьбы со злом.\n\nСеребряный Рассвет вручает знак доблести в обмен на десять таких камней. Принеси их мне, и непременно получишь достойную награду.", completion = "Поздравляю, Вродехант – и с радостью вручаю тебе знак доблести Серебряного Рассвета!\n\nКаждый выданный знак доблести означает, что вероятность победы Плети делается все ниже. Все больше героев вступают в бой с Плетью на ее землях, и Серебряный Рассвет несомненно будет в первых рядах той армии, что решится положить конец бесчинством прихвостней Повелителя Тьмы. Надеюсь, твоей доблести хватит и до того дня!", rewards = "Вы получите:\n\nЗнак доблести Серебряного Рассвета"},
[5510] = {title = "Камни приспешников плети", objective = "Камень Плети Осквернителей – знак различия войск Плети. Такие знаки обычно можно найти у более слабых тварей низшего ранга. Однако характеристика \"более слабый\" едва ли уместна, когда речь идет о Плети. Этих тварей никогда нельзя недооценивать!\n\nОт имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков – с огромным удовольствием.", description = nil, progress = "Камень Плети Осквернителей – знак различия войск Плети. Такие знаки обычно можно найти у более слабых тварей низшего ранга. Однако характеристика \"более слабый\" едва ли уместна, когда речь идет о Плети. Этих тварей никогда нельзя недооценивать!\n\nОт имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков – с огромным удовольствием.", completion = "Поздравляю, Пампа – и с радостью вручаю тебе знак доблести Серебряного Рассвета!\n\nОни служат двум целям – во-первых, позволяют упрочить твои позиции в Серебряном Рассвете; благодаря этому тебе станут доступны возможности и награды, которые мы бережем для самых преданных наших сторонников. Во-вторых – ими можно расплачиваться с нашими интендантам, также как и деньгами, и получать ценные предметы, которые изготовляют в нашем ордене.\n\nТак или иначе, ты их заслужил. Молодец!", rewards = "Вы получите:\n\nЗнак доблести Серебряного Рассвета"},
[5511] = {title = "Ключ от Некроситета", objective = "Ну, вот, готово, Дисскомаг – это ключ от Некроситета. Я не сомеваюсь, что он позволит тебе проникнуть в пределы школы. Впрочем, есть лишь один способ узнать наверняка. И не теряй времени даром.\n\nУдачи тебе, герой. Разгроми Некроситет и добейся заслуженной славы!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nОтмычка"},
[5513] = {title = "Оплечья Рассвета", objective = "Принесите 10 знаков доблести Серебряного Рассвета интенданту Затвор в Часовню Последней Надежды в Восточные Чумные земли.", description = "Тебе причитается награда за верную службу Серебряному Рассвету, <имя>. Тебе удалось завоевать всеобщее почтение. Мне поручено передать – ты можешь купить один из самых ценных наших предметов – оплечье защиты от магии.\n\nЕсли прикрепить его к доспехам, твое сопротивление силам одного из пяти направлений магии возрастет. За это оплечье я попрошу от тебя не менее 10 знаков доблести Серебряного Рассвета.", progress = "А, благородный |3-6(Маг)! Ты принес мне знаки доблести? Как только ты передашь мне все десять, я предложу на выбор наши оплечья.", completion = "Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока отношение нашего ордена к тебе не изменится, ты сможешь купить оплечья у любого интенданта Серебряного Рассвета.\n\nЗа Рассвет, брат мой!", rewards = "Вы получите:\n\n"},
[5514] = {title = "Форма денег стоит", objective = "Отнесите Кринкелю Сталлинну из Прибамбасска прочные фрагменты скелета и 15 золотых монет.", description = "Тебе нужно поговорить с гоблином по имени Кринкель Сталлинн. Он работает в Прибамбасске, в пустыне Танарис. Ему под силу сделать такую форму, но это обойдется недешево. Мы просим тебя не скупиться и заплатить ему.\n\nЯ алхимик, а не банкир. Будь у меня золото, я бы здесь не сидел.\n\nНу вот, опять я брякнул что-то не то. Ладно.\n\nТебя ждет Прибамбасск! Удачи!", progress = "Да, я знаю, кто ты и зачем пришел. Дитерс послал мне весточку. Сразу перейдем к делу?\n\nУ меня есть форма, в которой можно изготовить нужный тебе ключ, но она обойдется недешево – 15 золотых. Деньги вперед и не пытайся торговаться. Я сложу в форму фрагменты скелетов и покажу, как можно отлить его, не зная ничего о кузнечном деле... и все это бесплатно.\n\nПусть не говорят, что наемники за копейку удавятся!", completion = "Дитерс сказал, что ты принесешь все необходимое, и так оно и оказалось! Сделка есть сделка. Дай-ка я сложу фрагменты скелетов в форму.\n\nДитерс их заранее закалил? Великолепно... В противном случае тебе пришлось бы тащиться обратно в Бастион.", rewards = nil},
[5515] = {title = "Мешок ужасов Крастинова", objective = "Найдите в Некроситете Джандис Баров и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф.", description = "Мы сбросили с себя тяжелое бремя, но твое задание все еще не исполнено. Повелитель Крастинова, Киртонос, все еще жив.\n\nВпрочем, прежде чем бросить ему вызов, необходимо придумать, как его вызвать.\n\nГоворят, что кровь невинных от Крастинова к Киртоносу переправляет Джандис Баров.\n\nНайди ее в затопленных коридорах Некроситета и убей. Принеси все улики, которые только найдешь.", progress = "*Эва то появляется, то исчезает.*", completion = "Мешок ужасов!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5517] = {title = "Многоцветное оплечье Рассвета", objective = "Принесите 25 знаков доблести Серебряного Рассвета интенданту Затвор в Часовню Последней Надежды в Восточные Чумные земли.", description = "<Брат/Сестра> <имя> – нет числа твоим деяниям во славу Серебряного Рассвета. В знак признательности я готова расстаться с одним из наших знаменитых многоцветных оплечий Рассвета – тех самых, которые защищают от всех видов магии. Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев!\n\nПринеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМногоцветная драгоценность Рассвета"},
[5518] = {title = "Доспехи клана Гордок", objective = "Принесите 4 рулона рунной ткани, 8 кусков прочной кожи, 2 мотка рунной нити и огрскую дубильную кислоту Уззлу Наперстяку. Он прикован в секторе клана Гордок в Забытом Городе.", description = "Если вы собираетесь сразиться с королем этой помойки – а думаю, что без этого не обойтись, – тогда вам придется миновать капитана Давигрома. Конечно, можно его просто убить. Но возможно, вам стоит оставить его в живых.\n\nВы спросите – каким образом? Я сижу здесь уже довольно долго, и успел придумать, как можно изготовить личину огра, которая продержится достаточно долго, чтобы обмануть этих остолопов. Но, увы, больше чем на десять минут ее не хватит. Принесите мне все, что нужно, и я вам ее изготовлю. Торопиться-то мне все равно некуда...", progress = "Из всего, что мне нужно, пожалуй, труднее всего добыть огрскую дубильную кислоту. Может быть, наверху найдется? Мне самому туда не дойти, с этим ядром на цепи не больно-то побегаешь.\n\nВ общем, принесите мне все, что нужно, и я изготовлю вам огрскую личину, которая заставит капитана Давигрома принять вас за одного из своих.", completion = "Да, это подойдет. Вот тут подтянуть, тут подогнуть... Да-да, все должно пройти как по маслу!*Прикованный гоблин расплывается в широкой улыбке.*\n\nНу вот, все готово! Только не забывайте – это не самое долговечное изделие. У вас всего десять минут, после этого оно развалится, и все увидят, кто вы такой! Постарайтесь надеть его не раньше, чем приблизитесь к капитану, и помните: оно превратит в огра только вас, но не ваших спутников!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nДоспехи клана Гордок"},
[5519] = {title = "Доспехи клана Гордок", objective = "Вам снова нужна личина, да? Ну, мне сейчас не к спеху – принесите мне то же, что и в прошлый раз, и я изготовлю вам еще одну огрскую личину.", description = nil, progress = "Вам снова нужна личина, да? Ну, мне сейчас не к спеху – принесите мне то же, что и в прошлый раз, и я изготовлю вам еще одну огрскую личину.", completion = "Вот, пожалуйста, Мотлох: после того, как вы ее наденете, у вас в запасе будет десять минут. Удачи!\n\nДа, и если сумеете найти ключ, чтобы выпустить меня отсюда, непременно мне скажите, слышите?", rewards = "Вы получите:\n\nДоспехи клана Гордок"},
[5521] = {title = "Многоцветное оплечье Рассвета", objective = "Принесите 25 знаков доблести Серебряного Рассвета интенданту Искре Света в Лагерь Промозглого Ветра.", description = "<Брат/Сестра> <имя> – твоих деяний во славу Серебряного Рассвета не счесть. В знак признательности я готова продать тебе одно их наших знаменитых многоцветных оплечий Рассвета – тех самых, которые защищают от всех видов магии. Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев!\n\nПринеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМногоцветная драгоценность Рассвета"},
[5522] = {title = "Леонид Барталомей", objective = "Принесите охлажденные яйца Леониду Бартоломею в Восточные Чумные земли.", description = "Я получила весть от своего господина Вектуса. На самом деле... не напрямую от него, но от некого Леонида Бартоломея. Я не знаю его, однако он видел моего господина – а никто не может видеть моего господина, если он сам этого не пожелает.\n\nЛеонид сказал мне, что Вектусу необходимы драконьи яйца. Доставь их ему в Часовню Последней Надежды в Восточные Чумные земли.\n\nАй! За что? Разве Вектус не доверяет мне? Не обращай внимания, я не тебе. Просто доставь яйца куда следует и сообщи Леониду, что я сделал все, как было приказано.", progress = "Ага, ты ведь один из тех, кто устроил заварушку в Пике Черной горы? Принес то, о чем я просил?", completion = "Прекрасно, прекрасно. Тебе еще не известно, сколь великое зло кроется за теми, на кого ты работал но я открою тебе глаза на правду. Не бойся, я не служу им. Имя мне Леонид Бартоломей; братья мои из Серебряного Рассвета зовут меня Чтимым. \n\nОбманом я убедил Тинки отправить драконьи яйца мне. Нам несказанно повезло, что она попалась в эту ловушку, потому что если бы драконьи яйца были доставлены по назначению, в руках врага оказалась бы огромная сила.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5524] = {title = "Многоцветное оплечье Рассвета", objective = "Принесите 25 знаков доблести Серебряного Рассвета интенданту Хасане в Бастион, что в Западных Чумных землях.", description = "<Брат/Сестра> <имя> – твоих деяний во славу Серебряного Рассвета не счесть. В знак признательности я готова продать тебе одно их наших знаменитых многоцветных оплечий Рассвета – тех самых, которые защищают от всех видов магии. Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев!\n\nПринеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМногоцветная драгоценность Рассвета"},
[5525] = {title = "Освободите Нотта!", objective = "Эта вещь называется \"ключ от оков Гордока\" – по крайней мере, так называют его эти \"остроумцы\". Думаю, такой ключ может быть у любого из огров, но у кого именно – сказать не возьмусь. Есть вероятность, что такие ключи имеются у стражников…\n\nНо о чем я говорю? Он у вас есть, да? Он при вас?!", description = nil, progress = "Эта вещь называется \"ключ от оков Гордока\" – по крайней мере, так называют его эти \"остроумцы\". Думаю, такой ключ может быть у любого из огров, но у кого именно – сказать не возьмусь. Есть вероятность, что такие ключи имеются у стражников…\n\nНо о чем я говорю? Он у вас есть, да? Он при вас?!", completion = "Вы для меня – номер один во всем мире! Все остальные – после вас! Ох, большое вам спасибо, что освободили меня!\n\nЯ знал, я знал, что меня ждет более достойная участь, чем пойти на обед какому-нибудь огру!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5526] = {title = "Осколки сквернита", objective = "Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Вертоградаря. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне.", description = "Твои знания об Эльдре'Таласе – Забытом Городе – в Фераласе теперь очень пригодятся, <имя>. Именно в восточной части этого разрушенного города властвует нечестивый Алззин Перевертень. Ступай же туда со всей поспешностью и посмотри в лицо ожидающей тебя опасности. \n\nПлод Изобилия, ныне оскверненный и ставший Сквернитом, должен находиться неподалеку от Алззина. Когда он упадет, собери столько субстанции Сквернита, сколько сможешь. Закрой его в реликварий и принеси мне.\n\nУдачи тебе, и быстроты Кенария.", progress = "Имея в своем распоряжении запечатанный реликварий Чистоты, мы сможем не только устранить угрозу порчи, но и подойти к изучению этого проклятия со всей ответственностью. Возможно, мы даже сумеем разработать новые средства борьбы с порчей, что постоянно угрожает Азероту.\n\nЯ знаю, что Мили не согласиась бы ни на что иное...", completion = "Дело сделано, отважный |3-6(Друид), и Круг Кенария в долгу перед тобой. Хотя война еще далеко не окончена, мы выиграли великую битву с теми, кто хотел обрушить на нас молот рока.\n\nПрошу – прими это в знак нашей безмерной благодарности. Знай, Тириус,  что для Круга Кенариуса ты навсегда останешься героем.  Прими нашу благодарность.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЩит МиллиСловарь Милли\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[5527] = {title = "Реликварий Чистоты", objective = "Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне.", description = "Первый шаг – найти вместилище, способное удержать чрезвычайно оскверненную субстанцию и оградить обладателя от ее влияния. Единственное известное мне приспособление, в котором, возможно держать такую дрянь, как Сквернит, – это реликварий Чистоты.\n\nВ сердце пустошей Силитуса находятся руины поселения Ночных эльфов, деревня Южного Ветра. Я знаю, что реликварий хранился там много лет назад. Если хочешь помочь нам достичь успеха, обыщи эти руины в надежде найти его.", progress = "Реликварий Чистоты – удивительный предмет сам по себе. Их было сделано очень мало, и почти все они были утрачены за прошедшие века.\n\nНадо признать, я давно узнал о том, что деревне Южного Ветра хранится один из этих артефактов. Но после начала треволнений в Силитусе я решил, что эта тайна должна остаться тайной. Расспрашивать – лишь вызывать подозрения у наших врагов.\n\nУвы, спокойное время миновало, особенно учитывая нынешнюю ситуацию в Эльдре'Таласе.", completion = "Воистину, ты и правда находчив, как говорят. Кругу Кенария повезло, что ты на нашей стороне.\n\nТеперь, когда реликварий снова у нас в руках, на сердце у меня стало легче. Теперь мне значительно проще просить тебя не только повергнуть нечестивого демона, но и принести одну опасную вещь...", rewards = "Вы получите:\n\n"},
[5528] = {title = "Доспехи клана Гордок", objective = "Ну, ты теперь у нас большая шишка, так попробуй задаром моего лучшего пойла! Оно и сил добавляет, и голову кружит! Пей, пей, начальник – попробуй, сам увидишь!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗеленый грог клана ГордокУбойное пойло Крига"},
[5529] = {title = "Зачумленные детеныши дракона", objective = "Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды.", description = "До Серебряного Рассвета дошли слухи о том, что Плеть создает собственную армию драконов! Мы должны этому помешать – с помощью драконов Плеть сможет беспрепятственно перемещаться по всему Азероту!\n\nИх некроманты выращивают проклятых драконов в Некроситете, посреди озера Дарроумир.\n\nОтправляйся в Некроситет и убей как можно больше драконьих детенышей, пока они не успели вырасти и превратиться в неуязвимых монстров!", progress = nil, completion = "Отлично, Мечищит! Они нескоро смогут вырастить новый выводок. \n\n...По крайней мере, я на это очень надеюсь...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5530] = {title = "Ожерелье Рассвета", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nОжерелье Рассвета"},
[5531] = {title = "Бетина Биггльцинк", objective = "Принесите охлажденные яйца Бетине Биггльцинк.", description = "Яйца, которые ты <принес/принесла> мне, должны были быть использованы Плетью для создания чудовищных проклятых драконов. Охлажденные яйца черных драконов были бы бесценны для их опытов – это несомненно позволило бы Плети достичь своей подлой цели гораздо быстрее.\n\nОтнеси яйца Бетине Биггльцинк – она сведуща в науках и алхимии. Она обеспечила нас оружием против Плети. С твоей помощью мы нанесем этим тварям решающий удар.", progress = "Приветствую тебя, Стиммакс. Что ты принес мне, драконьи яйца? Посмотрим, посмотрим...", completion = "Прекрасно, правильная упаковка – залог сохранности яиц при транспортировке. Да они отборные!\n\nОтложим их в надежное место для дальнейшего исследования, а пока займемся более важным делом.\n\nЯ разработала прибор, предназначенный для уничтожения нежити в Некроситете. Тамошние ученые сейчас работают над выведением нового вида драконов – нежити. Мы должны помешать им!\n\nПрибор я назвала \"Рассветным гамбитом\", потому что... в общем, я сама не совсем понимаю, как он работает.\n\nСможешь проверить?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5533] = {title = "Некроситет", objective = "Поговорите с алхимиком Арбингтоном с вершины Холодной Скалы, что в Западных Чумных землях.", description = "На острове Каэр Дарроу располагается Некроситет – школа, которая одновременно служит цитаделью плети. В ее недрах наши враги спокойно проводят исследования и делаются все сильнее. Путь преграждают двери, и без подходящего ключа внутрь не войти.\n\nАлхимик Арбингтон многое знает о Некроситете и придумал, как достать ключ. Ты <зарекомендовал/зарекомендовала> себя как человека с большими способностями, поэтому я доверяю тебе это задание. Обсуди подробности с алхимиком.", progress = nil, completion = "Рад встрече, |3-6(Разбойник). В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ... который отомкнет входную дверь.\n\nПредставляю, какие кошмары таятся за ней, Исчезайка. Не понимаю, как герои вроде тебя решаются на такие подвиги...", rewards = "Вы получите:\n\n"},
[5534] = {title = "\"Пропавшее\"оборудование Ким'джаеля", objective = "Найдите некую руну, которую хранят наги в руинах Эльдарата и принесите ее Ким'джаелю в Азшару.", description = "Что?! Ты в уме?! Чем ты еще <недоволен/недовольна>?! \n\nТы хоть представляешь, сколько стоят эти гранаты? За них дают... ладно, не важно... Хочешь денег? Хорошо. Прежде докажи мне, что ты <ценный работник/ценная работница>.\n\nОтправляйся в руины Эльдарата и принеси мне некую руну, которую искали эльфы крови. Полагаю, она у наг.", progress = "Ну, Томпсон? Где моя руна? Ты же хочешь денег? Так вот сначала поработай! \n\nНе то не получишь уговоренную сумму. Что, мы ни о чем не договаривались? А, ну прекрасно. Тогда советую поторопиться, а не то получишь сильно меньше, чем ожидаешь.", completion = "Ха! Отлично! \n\nУж я выясню, что это за штука, зачем она нужна и зачем волхв Римтори – та кобыла, которая меня в это втянула – так хотела ее заполучить. Ха! Вонючие эльфы крови! Уж Ким'джаель покажет вам, где раки зимуют! Он покажет вам, кто тут букашка! \n\nНу, ты молодчина, Томпсон! Спасибо тебе... Чего говоришь, не булькает? Ну, держи свои презренные монеты и проваливай, мне и без тебя есть чем заняться.", rewards = "Вы получите:\n\n"},
[5535] = {title = "Духовное беспокойство", objective = "Уничтожьте по 6 теней высокорожденных обоих полов и возвращайтесь к Ло'хату в Азшару.", description = "Давным давно, высокорожденные были самыми могущественными адептами тайной магии, когда либо существовавшими среди ночных эльфов. Порча, которая охватывает каждого, кто имеет дело с тайной магией, принесла мног зла народу ночных эльфов и всему Азероту. \n\nЯ обещал Часовым, что буду освобождать встреченных мной духов от их смертных связей. Если поможешь мне в этом, я награжу тебя. \n\nДухи скитаются в святилище Песни Теней к северо-востоку отсюда.", progress = "Как идут поиски духов высокорожденных, Криворучка? \n\nАзерот видел много бедствий, однако эти духи являют собой одно из самых серьезных. Возможно, дело в их всепоглощающей тяге к тайной магии. Ты знаешь, что эта тяга ведет за собой Пылающий Легион... И ты знаешь, чем все это может закончиться.", completion = "Отличная работа, |3-6(Воин). Благодарю тебя. Теперь духи обрели покой, а опасность, которую могла навлечь их жажда магии, миновала. \n\nДумаю, обе стороны конфликта, раздирающего ныне Азерот, поймут, что ты выше этого.", rewards = "Вы получите:\n\n"},
[5536] = {title = "Земли, полные ненависти", objective = "Уничтожьте 6 сатиров, 2 плутов Халдарра и 2 скверноподданных из племени Халдарр и возвращайтесь к Ло'хату к границе Ясеневого леса.", description = "Сатиры, искаженные и зловредные порождения ночных эльфов, ныне оскверняют священные земли, по которым некогда ступал Кенарий. Конечно, не в моих силах помочь эльфам справиться со всеми этими отвратительными созданиями, однако я поклялся Матери-Земле помочь эльфам избавиться от сатиров хотя бы здесь. \n\nНадеюсь, ты поможешь мне в этом деле. \n\nК северо-востоку отсюда ты найдешь клан Халдарр. Возвращайся ко мне, когда испытаешь свою силу.", progress = nil, completion = "Отличная работа, |3-6(Воин). Вижу, ты не только силен, но и хитер. Битва с сатирами была испытанием твоей преданности Матери-Земле, даже если ты поклоняешься другим богам. Она пронизывает все сущее в нашем мире и за его пределами. Два ока ее, темное и светлое, всегда взирают на нас с небес. \n\nПрошу тебя, прими эту скромную плату в знак моей признательности.", rewards = "Вы получите:\n\n"},
[5537] = {title = "Фрагменты скелетов", objective = "Принесите 15 фрагментов скелетов алхимику Арбингтону в Берег Промозглого Ветра в Западных Чумных землях.", description = "Чтобы отомкнуть двери Некроситета необходим Костяной ключ. Его делают из остатков скелета – точнее, нескольких скелетов – и вплавляют в прочнейший из металлов в подходящей форме. Чтобы ключ заработал, необходим перстень власти одного из тех существ, что могут открыть портал данной им силой.\n\nНо не будем отвлекаться, для начала нам понадобятся фрагменты скелетов. Для этой цели подойдут скелеты внутри Андорала, да и те, что снаружи.", progress = "Как бы гнусно это ни звучало, для создания ключа нам нужен солидный запас фрагментов скелетов. Недаром его назвали Костяным ключом", completion = "Отличные образцы! Теперь моя очередь – я закалю их особым образом, чтобы они смогли вынести процесс отковки, через который им придется рано или поздно пройти.\n\nТеперь придется отыскать подходящую форму для отливки. Я знаю одного гоблина-кузнеца из Танариса, который в прошлом делал формы для не менее жутких вещей. Его девиз – как у всех гоблинов – кто платит, тот и музыку заказывает.", rewards = "Вы получите:\n\n"},
[5538] = {title = "Форма денег стоит", objective = "Отнесите Кринкелю Сталлинну из Прибамбасска прочные фрагменты скелета и 15 золотых монет.", description = "Тебе нужно поговорить с гоблином по имени Кринкель Сталлинн. Он работает в Прибамбасске, в пустыне Танарис. Ему под силу сделать такую форму, но это обойдется недешево. Мы просим тебя не скупиться и заплатить ему.\n\nЯ алхимик, а не банкир. Будь у меня золото, я бы здесь не сидел.\n\nНу вот, опять я брякнул что-то не то. Ладно.\n\nТебя ждет Прибамбасск! Удачи!", progress = "Да, я знаю, кто ты и зачем пришел. Арбингтон послал мне весточку. Сразу перейдем к делу?\n\nУ меня есть форма, в которой можно изготовить нужный тебе ключ, но она обойдется недешево – 15 золотых. Деньги вперед и не пытайся торговаться. Я сложу в форму фрагменты скелетов и покажу, как можно отлить его, не зная ничего о кузнечном деле... и все это бесплатно.\n\nПусть не говорят, что наемники за копейку удавятся!", completion = "Арбингтон сказал, что ты принесешь все необходимое, и так оно и оказалось! Сделка есть сделка. Дай-ка я сложу фрагменты скелетов в форму.\n\nАрбингтон их заранее закалил? Великолепно... В противном случае тебе пришлось бы тащиться обратно на Берег Промозглого Ветра.", rewards = nil},
[5541] = {title = "Боеприпасы для Громострела", objective = "Доставьте боеприпасы Хегнару Громострелу в Дун Мороге.", description = "Хегнар Громострел продает ружья у дороги в Старую Наковальню. Стрелки и минометные команды много упражняются возле его лавки, так что ему всегда нужны снаряды и патроны.\n\nНо... Последний ящик с боеприпасами, что я ему послал, пропал по дороге. Мой курьер рассказал мне, что он встал лагерем у Серой берлоги, когда на него напали вендиго... и этот дурак бросил боеприпасы для Громострела!\n\n<имя>, <не мог бы ты/не могла бы ты> найти их и вернуть Громострелу? Он их ждет, и наверняка у него боеприпасы уже на исходе.", progress = "Надеюсь, ты не за боеприпасами пришел, потому как они у меня почти закончились!", completion = "Вот радость-то, еще боеприпасы! Поставка старины Лослора, наконец, прибыла! Пусть и поздновато, но, как говаривал мой дедуля, лучше поздно, чем никогда!\n\nБольшое тебе спасибо, Эфром. Покупатели тут заждались!", rewards = "Вы получите:\n\n"},
[5542] = {title = "Псы-демоны", objective = "Убейте 20 карликовых чумных псов, 5 чумных псов и 5 бесноватых чумных псов. По выполнении задания вернитесь к Тириону Фордрингу.", description = "Если ты собираешься здесь оставаться, придется тебе поработать в уплату за проживание. У нас есть ряд докучающих обстоятельств, с которыми неплохо бы разобраться.\n\nНачни с чумных псов и их отродий.\n\nЯ не многим смогу тебе отплатить, но горячую пищу и приятную беседу гарантирую.", progress = "Не жалей этих демонов, это не звери, а омерзительные твари!", completion = "Молодец, Томпсон. Давай, отдохни. Поедим же и побеседуем о давно ушедших днях!", rewards = "Вы получите:\n\n"},
[5543] = {title = "Окровавленные небеса", objective = "Убейте 30 чумных нетопырей и вернитесь к Тириону Фордрингу.", description = "Горе тем, кто в глупости своей бродит по Чумным землям. В здешних лесах таится много опасностей – от Алого ордена, который убивает всех, кроме своих сторонников, до Плети, которая всегда рада пополнить свои ряды новой нежитью.\n\nДаже звери и птицы превратились в отвратительных хищных чудовищ. Я прошу тебя уничтожить тех, что нападают с небес – чумных нетопырей.", progress = nil, completion = "Ты бесподобный образец порядочности, |3-6(нежить)! Давненько я не чувствовал крови героев в своих венах. Подобная отвага внушает надежду!", rewards = "Вы получите:\n\n"},
[5544] = {title = "Мясо личинок-трупоедов", objective = "Найдите личинок-падальщиков и падальщиков-пожирателей. Убейте побольше и наберите из мяса. Возвращайтесь к Тириону Фордрингу, когда накопите 15 кусков мяса червей-трупоедов.", description = "<раса>, у меня еда на исходе. Мне стыдно признаться, но угостить тебя нечем.\n\nНе поможешь старику? Единственные твари в этих краях, которых не поразила чума, это личинки-трупоеды. Они довольно гадкие, зато их мясо хранится много месяцев. Мне необходимо запасти несколько сотен фунтов на зиму!", progress = "Ты постепенно привыкнешь к вкусу, |3-6(нежить).", completion = "Да благословит тебя Свет, юноша.", rewards = "Вы получите:\n\n"},
[5545] = {title = "Тридцать три несчастья", objective = "Принесите 8 вязанок дров Раэлен на Лесопилку Восточной долины.", description = "У меня большие неприятности. Приближается срок поставки древесины, а я не успеваю ее отправить. Самое обидное, что она уже заготовлена – но волки и медведи, расплодившиеся к северу отсюда, не дают моим работникам ее забрать\n\nЯ уже договорилась с заместителем судьи Рейнером насчет зверья, но мне нужен кто-нибудь, кто доставит сюда эти дрова. Если ты принесешь мне восемь вязанок, я все успею.", progress = "Послушай, |3-6(Воин), срок поставки мне никто продлять не будет. Мне позарез нужны эти дрова!", completion = "Великолепно! Благодаря тебе я сумела выполнить заказ вовремя. Всякий труд должен быть оплачен, так что прошу тебя принять эту плату за беспокойство.\n\nСпасибо – и до свидания!", rewards = "Вы получите:\n\n"},
[5561] = {title = "Отлов кодо", objective = "Приведите пять прирученных кодо Смиду Заржавеню в Лагерь Заржавня. Не забудьте вернуть ему энергетический инкапсулятор.", description = "Биббли думает, что он – единственный гоблин в Пустошах, умеющий делать деньги. Ха! Единственный караван, который осмеливается странствовать по этим землям, полностью зависит от меня. С тех самых пор, как я научился омолаживать кодо и управлять старыми и умирающими зверями при помощи моего энергетического инкапсулятора, мы трое – я, караванщик Корк и Риггер – создали что-то вроде компании.\n\nВот, держи инкапсулятор: он действует на древних, старых и умирающих кодо, превращая их в ручных и заставляя следовать за тобой. Как сумеешь приручить кодо, веди его ко мне.", progress = "Караван скоро будет здесь. Надеюсь, ты привел новых прирученных кодо? Да? Да?", completion = "*Смид Заржавень начинает считать.*\n\nТри... Четыре... Ага, пять. Прекрасно! Я просил пять прирученных кодо – и получил ровно пять прирученных кодо! Я буду богат... Да, очень, очень богат! Хотелось бы мне видеть, какую кислую рожу скорчит Биббли, когда узнает об этом!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги угонщика кодоНаплеч Ссоры\n\nВы также получите:\n\n"},
[5581] = {title = "Порталы Легиона", objective = "Уничтожьте 6 порталов на Поле Маннорок, а затем вернитесь к Тайге Мудрой Гриве в Деревню Ночных Охотников.", description = "Воззри: вот Рука Ируксоса. Поистине, ужасающее зрелище.\n\nЕсли ты намереваешься закрыть порталы демонов на Поле Маннорок, – а именно об этом я и хочу тебя попросить, – то она должна быть у тебя. Угроза со стороны демонов растет: мы должны закрыть их порталы, дабы демоническим существам более не было доступа в этот мир. Удачи тебе в этом нелегком деле, <имя>... и берегись стражей портала.", progress = "Удалось ли тебе закрыть порталы демонов на Поле Маннорок?", completion = "Ты воистину достоин величайших почестей, Томпсон. Твоими трудами жизнь на всем Азероте станет гораздо спокойнее.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНакулачники стальной хваткиПлетеные меховые перчатки\n\nВы также получите:\n\n"},
[5582] = {title = "Здоровая чешуя дракона", objective = "Отнесите здоровую чешую дракона Бетине Биггльцинк в Часовню Последней Надежды в Восточные Чумные земли.", description = "Это чешуйка была взята у пораженного проклятой чумой драконьего детеныша. Однако в отличие от других чешуек, изъязвленных и покрытых слизью, эта выглядит совершенно здоровой.\n\nЛюбопытное явление. Бетина Биггльцинк непременно захочет на это взглянуть.", progress = "Ты что-то принес мне, Ишт?", completion = "Очень интересно... Возможно, ч помощью этой чешуи мне удасться проникнуть в суть козней Плети. Благодарю тебя, Ишт. Впредь, если обнаружишь подобные чешуйки, непременно приноси их мне!", rewards = nil},
[5601] = {title = "Сестренка Памела", objective = "Найдите Памелу Редпат в Дарроушире.", description = "Во время войны я бежала в Лордерон – мне посчастливилось спастись до того, как полчища Плети прошли по моим родным местам и превратили их в зачумленные руины. Мне повезло, но судьба была не столь благосклонна к моей семье. Боюсь, все они погибли во время битвы при Дарроушире.\n\nДеревня Дарроушир была частью Восточных Королевств, теперь это еще одни развалины в южных пределах Восточных Чумных земель. Не <мог/могла> бы ты узнать, что сталось с моей семьей? Я так волнуюсь за них, особенно за мою сестренку Памелу.\n\nПожалуйста, отыщи ее!", progress = nil, completion = "Где моя сестра Джессика? Она покинула меня так давно, когда я была еще совсем маленькой девочкой. Она так плакала, когда уходила... Не знаю, почему, может, разбила коленку?\n\nРаньше мы с Джессикой вместе играли, и танцевали, и собирали цветы... А иногда мы прятались за дверью и ждали, когда отец придет домой, чтобы выскочить и напугать его.\n\nЯ хочу, чтобы она вернулась! Может, если вернется она, то вернется и папа, и остальные, и мы снова будем вместе играть...", rewards = "Вы получите:\n\n"},
[5621] = {title = "Облачение Луны", objective = "Найдите стража Шайю и исцелите ее раны при помощи малого исцеления (ранг 2). Потом скажите ей Слово силы: \"Стойкость\". Затем вернитесь к Лорне Утреннему Свету в Доланаар.", description = "Мне нужна твоя помощь, <имя>. Я должна оставаться здесь, чтобы обучать других, но ты <мог бы/могла бы> помочь одной из наших раненых часовых к югу от Доланаара. Ее ранили, когда она патрулировала город, и ей нужна наша помощь. Ее зовут Шайя.\n\nКогда найдешь ее, исцели ее раны и укрепи ее тело заклятиями. По крайней мере, это защитит ее от бед на некоторое время. Когда выполнишь свой долг перед Элуной, возвращайся ко мне.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЛунные одеяния Элуны"},
[5622] = {title = "Во имя Элуны", objective = "Поговорите в Тельдрассиле с Лорной Утренний Свет.", description = "<имя>, тебе предстоит отправиться в Доланаар, когда завершишь свои дела здесь, в Тенистой долине. Там ты разыщешь Лорну Утренний Свет. Она расскажет тебе больше о пути Элуны, и с ее помощью ты получишь свое первое облачение, говорящее о твоем статусе <жреца/жрицы> Элуны.\n\nБудь <осторожен/осторожна>, и да хранит тебя в пути Элуна!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[5623] = {title = "Во имя Света!", objective = "Поговорите с жрицей Жозеттой в Элвиннском лесу.", description = "Приветствую тебя, <юный жрец/юная жрица>. Пришло время узнать больше о нашей вере. После того как ты закончишь все дела в Североземье, разыщи в Златоземье жрицу Жозетту. Знания ее велики; к тому же она уже слышала о тебе и о твоем стремлении к Истинному Свету. Она готова поделиться с тобой своей мудростью.", progress = nil, completion = "Я рада видеть тебя здесь, Святодар. Нам нужно поговорить о твоем будущем и о пути Света...", rewards = "Вы получите:\n\n"},
[5624] = {title = "Облачение Света", objective = "Разыщите стражника Робертса и исцелите его раны, пользуясь \"Малым исцелением\" (уровень 2), а затем одарите его заклинанием \"Слово силы: Стойкость\", после чего вернитесь в Златоземье к жрице Жозетте.", description = "Обычно я подвергаю всех последователей Света небольшому испытанию. Так я выясняю, достойны ли они своего первого облачения – символа того, что церковь их принимает и поддерживает.\n\nНо сейчас ситуация немного отличается. Один из жителей Златоземья видел раненого стража на берегу озера к востоку отсюда. Этого стража зовут Робертс. Найди его, исцели его раны, придай ему стойкости и вернись сюда. Если ты справишься, я сочту твое испытание завершенным.", progress = "Возможно, тебе уже известно, что целительская магия необходима для выживания нашего народа, особенно в эти тяжелые и неспокойные времена. Особенно в ней нуждаются путешественники и воины – те, что сражаются мечом и магией со злом, пришедшим в наш мир.\n\nТебе не следует забывать, насколько важно это умение. В совокупности с заклинанием \"Слово силы: Стойкость\" целительская магия сделает твоих друзей могучими воинами, способными бестрепетно переносить удары врага.\n\nНе позволяй никому забыть о мощи твоей магии!", completion = "Прекрасно, Святодар. Теперь город охраняет еще один страж. Приятно видеть, что ты учишься пользоваться своими способностями. Если захочешь узнать что-нибудь новое, возвращайся ко мне. А пока что прими это облачение. Если наденешь его, все будут знать, что ты принадлежишь к нашему ордену. Впрочем, можешь и не надевать, если не хочешь: для выполнения следующих заданий оно не нужно.", rewards = "Вы получите:\n\nМонашеские одеяния Света"},
[5625] = {title = "Облачение Света", objective = "Надите горного пехотинца Дольфа и исцелите его раны при помощи Малого исцеления (ранг 2). Также наложите на него \"Слово силы: Стойкость\", а затем вернитесь к Максану Ковальне в Каранос.", description = "Как правило, примерно в эту пору <послушники/послушницы> вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе. Но, честно говоря, сейчас у меня есть и более важные дела. Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф.\n\nИзлечи Дольфа и наложи на него \"Слово Силы: Стойкость\", и я сочту, что ты <прошел/прошла> испытание. Справишься?", progress = "Ты нашел Дольфа, Дмитроярош?\n\nНаверное, ты уже знаешь, что наша способность исцелять весьма полезна. Мы можем не только лечить раненых, но и помогать всем так называемым героям, которые пытаются прославить свое имя. При помощи \"Слова Силы: Стойкость\", что позволяет им выдерживать больше ударов, и нашей целительской магии мы все преодолеем!", completion = "Прекрасно, Перш. В тебе есть Свет, и в этом нет сомнений.\n\nВот, прими это одеяние. Оно будет показывать всем, что ты жрец, – носи его, если желаешь.\n\nВ будущем тебе придется пройти через другие испытания. Старайся узнать побольше о своих способностях и возможностях. Испытай свою силу в одном-двух одиночных боях, а потом и в группе с другими путниками.\n\nНе страшись никого: твоей силе может позавидовать любой.", rewards = "Вы получите:\n\nМонашеские одеяния Света"},
[5626] = {title = "Во имя Света", objective = "Поговорите с Максаном Ковальней в Дун Мороге.", description = "Эй! <имя>! У тебя есть свободная минутка?!\n\nТы давно уже следуешь пути Света, так ведь? Как насчет того, чтобы сходить к Максану Ковальне в Каранос? Он расскажет тебе побольше о твоей судьбе, а если ты окажешься $Gдостойным:достойной;, он тебе даст твои первые одеяния <жреца/жрицы>.\n\nТеперь ступай! Как только закончишь все свои дела здесь, иди в Каранос через туннель – Максан будет тебя ждать.", progress = nil, completion = "О, так тебя послал Брансток? Славно, славно! Он прав, уже пора бы сделать шажок побольше в сторону Света. Это закалит твой характер и укрепит твое тело… и дух.", rewards = "Вы получите:\n\n"},
[5627] = {title = "Звезды Элуны", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы изучите:\n\nЗвездные осколки\n\nСледующее заклинание будет наложено на вас:\n\nЗвездные осколки"},
[5628] = {title = "Возвращение домой", objective = "Поговорите в Дарнассе со жрицей Алатеей.", description = "Если не ошибаюсь, <имя>? Рад, что ты <уделил/уделила> мне минутку внимания. Забраться так далеко от дома, да в такие юные годы, – мне по душе твое рвение! Если бы мне в молодые годы хватило духу постранствовать по миру...\n\nТут недавно тебя искала жрица из вашего ордена. Сказала, что тебе спешно надо вернуться в храм Луны в Дарнассе и поговорить со жрицей Алатеей – это как-то связано с твоим обучением. Я бы на твоем месте не тянул.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nЗвездные осколки\n\nСледующее заклинание будет наложено на вас:\n\nЗвездные осколки\n\nВы также получите:\n\n"},
[5629] = {title = "Возвращение домой", objective = "Поговорите в Дарнассе со жрицей Алатеей.", description = "Еще раз приветствую тебя, <имя>. Я знаю, что ты и так много помогаешь нашему народу, но надо и себе уделить хоть немного времени. Жрица Алатея прислала за тобой. Сдается, ты <привлек/привлекла> внимание наших старейшин, и они считают, что ты <созрел/созрела> для более великих дел. Отправляйся в дарнасский храм Луны и найди там Алатею. Удачи тебе, и да хранит тебя Элуна.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nЗвездные осколки\n\nСледующее заклинание будет наложено на вас:\n\nЗвездные осколки\n\nВы также получите:\n\n"},
[5630] = {title = "Возвращение домой", objective = "Поговорите в Дарнассе со жрицей Алатеей.", description = "Ну здравствуй, <друг/подруга. Приятно видеть> что ты так далеко <забрался/забралась>! Без обид, но многие из ваших не слишком хорошо переносят тутошние холода. Славно, что ты <слеплен/слеплена> из более крутого теста.\n\nНе так давно одна из ваших жриц искала тебя – говорила,  чтобы ты <нашел/нашла> жрицу Алатею в храме Луны в Дарнассе. Должно быть, это важно так что возвращайся туда как можно скорее.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nЗвездные осколки\n\nСледующее заклинание будет наложено на вас:\n\nЗвездные осколки\n\nВы также получите:\n\n"},
[5631] = {title = "Возвращение домой", objective = "Поговорите в Дарнассе со жрицей Алатеей.", description = "Недавно в наших чертогах побывала одна жрица, и она искала вас, <юный/юная:r> <раса>. Она сказала, что ее послали за вами и что вы должны вернуться в храм Луны в Дарнассе как можно скорее. По прибытии найдите жрицу – она расскажет вам больше.\n\nДа пребудет с вами Свет, <имя>.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nЗвездные осколки\n\nСледующее заклинание будет наложено на вас:\n\nЗвездные осколки\n\nВы также получите:\n\n"},
[5632] = {title = "Возвращение домой", objective = "Поговорите в Дарнассе со жрицей Алатеей.", description = "Да-да, конечно. Здравствуй, <имя>. Недавно тут побывала посланница нашего ордена. Она искала тебя. Она мельком упомянула, что в Дарнассе случилось что-то важное и что тебе следует как можно скорее вернуться в храм Луны. Сразу поговори там со жрицей Алатеей. Наверняка это касается твоих успехов.\n\nВ общем, возвращайся в Дарнасс, как только сможешь.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nЗвездные осколки\n\nСледующее заклинание будет наложено на вас:\n\nЗвездные осколки\n\nВы также получите:\n\n"},
[5633] = {title = "Возвращение домой", objective = "Поговорите в Дарнассе со жрицей Алатеей.", description = "Добро пожаловать, <друг/подруга>. Приятно видеть тебя в наших чертогах. Да пребудет благость с тобой и твоим народом.\n\nПока ты тут <странствовал/странствовала> в наших краях, тебя разыскивала здесь жрица из вашего храма. Она сказала, что тебе надо как можно скорее возвращаться в Храм Луны. Прости, большего не скажу, но мне показалось, что дело важное. Когда доберешься до Храма, поговори со жрицей Алатеей.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nЗвездные осколки\n\nСледующее заклинание будет наложено на вас:\n\nЗвездные осколки\n\nВы также получите:\n\n"},
[5634] = {title = "Молитва отчаяния", objective = "Твои услуги, оказанные силам Света, неоценимы, а твои деяния – пример блистательной храбрости для всех, кто путешествует в землях, полных опасностей. Прошу, считай этот урок наградой за все, сделанное тобой.", description = nil, progress = nil, completion = nil, rewards = "Вы изучите:\n\nМолитва отчаяния\n\nСледующее заклинание будет наложено на вас:\n\nМолитва отчаяния"},
[5635] = {title = "Молитва отчаяния", objective = "Поговорите с Верховной жрицей Лореной в Штормграде.", description = "<имя>, тобой заинтересовались наши высшие иерархи. Они желают твоего скорейшего возвращения в Собор Света Штормграда. Вероятно, они считают, что для тебя наступило время нового обучения. Когда доберешься до собора, обратись прямо к верховной жрице Лорене, она расскажет тебе об остальном. Удачи! Да хранит тебя Свет!", progress = nil, completion = "Я рада твоему прибытию, Талао. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.\n\nЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.", rewards = "Вы изучите:\n\nМолитва отчаяния\n\nСледующее заклинание будет наложено на вас:\n\nМолитва отчаяния\n\nВы также получите:\n\n"},
[5636] = {title = "Молитва отчаяния", objective = "Поговорите с Верховной жрицей Лореной в Штормграде.", description = "Да благословит тебя Элуна, <раса>! Надеюсь, что Свет не покидает тебя.\n\nТебя недавно разыскивал один из наших жрецов. Он просил передать тебе, что в Соборе Света Штормграда тебя ожидает Верховная жрица Лорена. Не трать времени даром, твой народ нуждается в тебе.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nМолитва отчаяния\n\nСледующее заклинание будет наложено на вас:\n\nМолитва отчаяния\n\nВы также получите:\n\n"},
[5637] = {title = "Молитва отчаяния", objective = "Поговорите с Верховной жрицей Лореной в Штормграде.", description = "<имя>, тебе пора отправляться в Штормград. Верховная жрица Лорена ожидает тебя в Соборе Света, она хочет поговорить с тобой. Должно случиться что-то особенное, если тобой заинтересовалась сама Верховная жрица. Не знаю, к добру это или к худу. Думаю, что так или иначе все это окажется полезным для тебя.\n\nНе трать много времени, собирайся быстрее.", progress = nil, completion = "Дмитроярош, я рада тебя видеть! Нам есть о чем поговорить, но твое обучение важнее всего, ведь это – путь Света.\n\nЕсть знание, которым должны овладеть все прислужники Света. Чувствуешь ли ты в себе достаточно сил? Если да, то перейдем к обсуждению.", rewards = "Вы изучите:\n\nМолитва отчаяния\n\nСледующее заклинание будет наложено на вас:\n\nМолитва отчаяния\n\nВы также получите:\n\n"},
[5638] = {title = "Молитва отчаяния", objective = "Поговорите с Верховной жрицей Лореной в Штормграде.", description = "Эй, <раса>! Тебя недавно искал один из ваших жрецов! Он просил тебе передать, что тебя очень ждут в Соборе Света. Еще сказал, что это очень важно, и мне кажется, что ему стоит верить. Он был настроен весьма благодушно, так что для тебя это хорошие новости. Тебе стоит поторопиться, чтобы не упустить этот шанс.\n\nДа хранит тебя Элуна, <раса>.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nМолитва отчаяния\n\nСледующее заклинание будет наложено на вас:\n\nМолитва отчаяния\n\nВы также получите:\n\n"},
[5639] = {title = "Молитва отчаяния", objective = "Поговорите с Верховной жрицей Лореной в Штормграде.", description = "<имя>! Тебя ждут в Штормграде! Верховная жрица Лорена говорит, что тебе пора доказать свою способность перейти на новый уровень подготовки. Не мешкай. Ты найдешь Лорену в Соборе Света в центре города. Передай ей от меня привет и постарайся не завалить экзамен. Да хранит тебя Свет!", progress = nil, completion = "Ягамля, я рада тебя видеть! Нам есть о чем поговорить, но твое обучение важнее всего, ведь это – путь Света.\n\nЕсть знание, которым должны овладеть все прислужники Света. Чувствуешь ли ты в себе достаточно сил? Если да, то перейдем к обсуждению.", rewards = "Вы изучите:\n\nМолитва отчаяния\n\nСледующее заклинание будет наложено на вас:\n\nМолитва отчаяния"},
[5640] = {title = "Молитва отчаяния", objective = "Поговорите с Верховной жрицей Лореной в Штормграде.", description = "Благословенна будь Элуна, чей свет хранит тебя, <имя>!\n\nСейчас многие члены нашего ордена решили укрепить свои познания и веру в силу Элуны. Как я знаю, и в твоем ордене происходит то же самое.\n\nКогда закончишь свои дела в Дарнассе, отправляйся к вашей верховной жрице, дабы получить новые знания.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nМолитва отчаяния\n\nСледующее заклинание будет наложено на вас:\n\nМолитва отчаяния\n\nВы также получите:\n\n"},
[5641] = {title = "Бесстрашие", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы изучите:\n\nЗащита от страха\n\nСледующее заклинание будет наложено на вас:\n\nЗащита от страха"},
[5642] = {title = "Страж Тьмы", objective = "Поговорите с Ур'кьо в Оргриммаре.", description = "В Оргриммаре происходит нечто важное, <имя>.\n\nОбычно посланцы, которые приезжают сюда за троллями-жрецами, держатся с ленцой. А на этот раз они, похоже, спешили! Не засиживайся в Громовом Утесе. Думаю, тебе стоит как можно скорее вернуться в Аллею Духов.", progress = nil, completion = "Тебя ждет один из самых важных обрядов инициации для жреца нашей веры, Юбари. Я вижу, что ты готова к нему, и потому сейчас объясню все подробнее.", rewards = "Вы изучите:\n\nСтраж Тьмы\n\nСледующее заклинание будет наложено на вас:\n\nСтраж Тьмы\n\nВы также получите:\n\n"},
[5643] = {title = "Страж Тьмы", objective = "Поговорите с Ур'кьо в Оргриммаре.", description = "Как и многие из наших жрецов, члены твоего племени проходят обряды инициации. Эти обряды часто наделяют жрецов особыми способностями, которые помогают им выжить. Я чувствую, что тебе пришло время пройти такой обряд. Возвращайся в Аллею Духов в Оргриммаре и поговори с Ур'кьо. То, чему он тебя научит, может оказаться чрезвычайно важным в будущем.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nСтраж Тьмы\n\nСледующее заклинание будет наложено на вас:\n\nСтраж Тьмы\n\nВы также получите:\n\n"},
[5644] = {title = "Всепожирающая чума", objective = "Поговорите с Эльталисте в Подгороде.", description = "Доброго тебе дня, <имя>. Вижу, ты многому <научился/научилась>, и пришло время вернуться к Эльталисте. Есть вещи, рассказать о которых может лишь она, и то лишь самым достойным.\n\nЯ не скажу, что тебя ждет – пусть для тебя это будет сюрпризом. Хотя, помнится, когда я был молодым жрецом и только-только понял, что есть истинная сила... божественная сила... Вот это были деньки.\n\nОтправляйся в Подгород, поговори с Эльталисте, <имя>. Она ждет тебя в Квартале Воинов.", progress = nil, completion = "Отлично, ты вернулся и даже не опоздал. Нам нужно обсудить кое-что важное, Жрецплети. Твоя сила растет, и надо подготовить тебя к грядущим испытаниям.", rewards = "Вы изучите:\n\nВсепожирающая чума\n\nСледующее заклинание будет наложено на вас:\n\nВсепожирающая чума\n\nВы также получите:\n\n"},
[5645] = {title = "Бесстрашие", objective = "Поговорите с верховным жрецом Роханом в Стальгорне.", description = "<имя>, ваш верховный жрец Рохан назначает вам аудиенцию в Стальгорне. Торопитесь, <могучий мой друг/могучая моя госпожа>, ибо близится срок вашего очередного испытания. Хотя я хотел бы стать свидетелем особых обрядов вашей расы, но мое место здесь. Но да пребудет с вами Свет в пути вашем. Когда вы достигнете города, Рохан будет ждать вас в Палатах Магии.", progress = nil, completion = "Хорошо, что ты пришел, Шпшпышь. Наша раса горда и могуча, и пришла пора научиться быть таким не только самому, но и вселять эти чувства в сердца других. готов ли ты, юноша?", rewards = "Вы изучите:\n\nЗащита от страха\n\nСледующее заклинание будет наложено на вас:\n\nЗащита от страха\n\nВы также получите:\n\n"},
[5646] = {title = "Всепожирающая чума", objective = "Поговорите с Эльталисте в Подгороде.", description = "Эльталисте оказала моему народу большое доверие, посылая ко мне учеников, а теперь я сделаю то же для ее племени.\n\nВозвращайся в Подгород, <имя>. Твоя госпожа ждет тебя в Квартале Воинов, чтобы рассказать еще больше о твоем народе и его обычаях. Ступай, не медли.", progress = nil, completion = "Отлично, ты вернулся и даже не опоздал. Нам нужно обсудить кое-что важное, Зелинг. Твоя сила растет, и надо подготовить тебя к грядущим испытаниям.", rewards = "Вы изучите:\n\nВсепожирающая чума\n\nСледующее заклинание будет наложено на вас:\n\nВсепожирающая чума\n\nВы также получите:\n\n"},
[5647] = {title = "Бесстрашие", objective = "Поговорите с верховным жрецом Роханом в Стальгорне.", description = "Твоя раса так сильна, <имя>. Мы гордимся союзом с вами. С каждым закатом ты и твои сородичи не только все ближе к разгадке вашего истинного происхождения, но и обретаете все большую уверенность в том, что вы на верном пути во многом. Именно эта уверенность приносит вам победу.\n\nНедавно из Стальгорна пришла весть. Тебя просят вернуться и поговорить с верховным жрецом Роханом в Палатах Магии. Не стоит заставлять его ждать. Да направит твой путь Элуна.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nЗащита от страха\n\nСледующее заклинание будет наложено на вас:\n\nЗащита от страха\n\nВы также получите:\n\n"},
[5648] = {title = "Одеяния духовности", objective = "Найдите рубаку Кор'жу и исцелите ее раны, пользуясь Малым исцелением (уровень 2). Затем скажите ей Слово силы: Стойкость – и вернитесь к Тай'джин в Колючий Холм.", description = "Что ж, <имя>, вот ты и <готов/готова> к своему первому испытанию. К югу от Колючего Холма, сразу за городской чертой, лежит раненная орчиха из нашего отряда. Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою. Помочь ей может только кто-то из нас. Ее зовут Корджа. Найди ее, исцели и дай ей благословение наших предков.\n\nСделай это – ия сочту, что ты <подтвердил/подтвердила> свою готовность ступить на путь жреца.", progress = nil, completion = "Отлично! Так значит, Корджа жива и может снова защищать наш город от злокозненных людей? Я люблю вспоминать дни битв, когда подлинная сила проявлялась в бою. Тогда часто случалось, что мудрые губили тех, кто недооценивал их, полагаясь лишь на мощь мышц.\n\nЯ считаю, что ты молодец, Юбари. Вот, возьми это одеяние. Может быть, оно тебе пригодится. Может быть, тебе все равно, однако ты его заслужила, и я горжусь тем, что теперь могу звать тебя сестрой.", rewards = "Вы получите:\n\nОдеяния проклятья джуджу"},
[5649] = {title = "В пользу духовности", objective = "Поговорите с Тай'джин в Дуротаре.", description = "Понимаешь, наш народ присоединился к Орде, потому что они к нам добры. Они – преданные друзья, они многому нас научили, внушили нам представление о чести... Но наши старые обычаи еще живы. Орки не одобряют многие из них, но никто не мешает нам придерживаться их втайне.\n\nТы это знаешь. Вот почему я посылаю тебя в Колючий Холм, к Тай'джин. Она откроет тебе мудрость нашего племени. Ступай к ней, когда будешь <готов/готова>.", progress = nil, completion = "Ах-ха... наконец-то твой путь привел тебя к Тай'джин. Это хорошо.\n\nТеперь ты знаешь, что мы уже не то племя, что когда-то присоединилось к Орде. Мы стали гораздо сильнее. Мы обрели эту силу потому, что научились приспосабливаться – это мы переняли у Орды. Прежде мы побеждали врагов и забирали их силу, теперь же мы набираемся сил, а потом побеждаем врагов.\n\nВозможно, разница не столь заметна, но ты ее поймешь. Ты увидишь. Племя рассчитывает на то, что ты научишься видеть такие вещи.", rewards = "Вы получите:\n\n"},
[5650] = {title = "Одеяния Тьмы", objective = "Найдите стража смерти Кела и вылечите его раны заклинанием \"Малое Исцеление\" (ранг 2). После этого прочтите над ним \"Слово Силы: Стойкость\", а затем вернитесь к темному священнику Берилу в Брилл.", description = "Мы черпаем силу из тьмы и теней, <имя>, но ваше дело – не только дело тьмы. Вы поняли, что большая заслуга есть и в изучении искусства лечения. Это мудрый выбор. Но прежде чем познать тьму, вы должны познать и свет, а для этого нужно пройти испытание.\n\nК северу от кладбища находится раненый страж смерти по имени Кел – он уже очень долго защищает нас от гноллов, и ему требуется лечение. Но для того чтобы он мог и дальше исполнять свой долг, вы должны также придать ему сил. Используйте для этого свои заклинания, а потом возвращайтесь ко мне.", progress = "Наши силы дают нам невероятные возможности, Пасториус, однако скоро вы поймете, что наша способность исцелять раны и повышать наносимый врагам урон является одной из самых полезных и желанных. Не сомневайтесь в выбранном пути жреца – вы не раз убедитесь, что поступили правильно, избрав его. А вот если вы желаете применять магическую энергию для уничтожения врагов, то вам стоило бы лучше отправиться изучать тайную магию.", completion = "Вы с легкостью выдержали мое испытание. Это хорошо.\n\nСкоро вы будете готовы принять на себя еще большую ответственность, и этот путь приведет вас к более темным силам – таким, которыми не обладает ни один жрец другой расы.\n\nПримите это одеяние в знак вашего положения. Вы его заслужили. Если же вы не хотите его носить, что ж, тогда вы вольны поступить с ним так, как вам будет угодно. Я и другие и так никогда не забудем того положения, которого вы достигли в наших рядах.", rewards = "Вы получите:\n\nЖертвенные одеяния послушника"},
[5651] = {title = "Во славу Тьмы", objective = "Поговорите с темным священником Берилом в Тирисфальских лесах.", description = "Отрекшиеся извлекли много уроков из своего опыта и поняли такие вещи, о которых остальные только начинают догадываться. И несмотря на то что наш путь лежит во тьме, скоро вы поймете, что очень много вещей зависит от нее – так же как и от света. Вы научитесь использовать и то и другое... с должной осторожностью. Но никогда не забывайте того, что нас создали в тлене и бросили гнить, как какие-нибудь отбросы. Тьма – это наш дом.\n\nКогда будете готовы узнать больше, разыщите темного священника Берила в Брилле.", progress = nil, completion = "Наконец-то вы прибыли! Чтобы пройти испытания, одной веры не достаточно. Нужно еще чувство долга и немного амбиций.", rewards = "Вы получите:\n\n"},
[5652] = {title = "Обессиливающий сглаз", objective = "Тебе стоит внимательно отнестись к этому уроку. \"Обессиливающий сглаз\" всегда пригодится в бою. Позднее я подвергну тебя испытаниям, чтобы дать тебе возможность показать себя и доказать свою полезность племени.", description = nil, progress = nil, completion = nil, rewards = "Вы изучите:\n\nОбессиливающий сглаз\n\nСледующее заклинание будет наложено на вас:\n\nОбессиливающий сглаз"},
[5654] = {title = "Обессиливающий сглаз", objective = "Поговорите с Ур'кьо в Оргриммаре.", description = "Пора тебе встретиться с Ур'кьо, <имя>. Ты найдешь его на аллее Духов, в городе орков. Ступай туда и поговори с ним. Пора тебе познать древнюю мудрость нашего народа. Пора вступить в круг и стать настоящим жрецом нашего племени.", progress = nil, completion = "А, ты здесь! Это хорошо. Теперь мы можем начать твое обучение.", rewards = "Вы изучите:\n\nОбессиливающий сглаз\n\nСледующее заклинание будет наложено на вас:\n\nОбессиливающий сглаз\n\nВы также получите:\n\n"},
[5655] = {title = "Обессиливающий сглаз", objective = "Поговорите с Ур'кьо в Оргриммаре.", description = "Мне нужно было удостовериться, что ты не уйдешь слишком далеко от дома, <имя>. Меня послали за тобой потому, что Ур'кьо, величайший из наших жрецов, желает поговорить с тобой. Ступай туда. Ступай в Аллею Духов в городе орков и поговори с Ур'кьо. Он ждет тебя.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nОбессиливающий сглаз\n\nСледующее заклинание будет наложено на вас:\n\nОбессиливающий сглаз\n\nВы также получите:\n\n"},
[5656] = {title = "Обессиливающий сглаз", objective = "Поговорите с Ур'кьо в Оргриммаре.", description = "Мое нестареющее сердце всегда греет мысль о том, что по миру бродит множество жрецов всех культур. Хорошо знать, что на свете есть сила, не имеющая отношения к тайной магии и вполне доступная нам. Вот почему я сочту за честь указать тебе путь, <имя>.\n\nУркьо, ваш великий жрец в Оргриммаре, просит тебя прибыть к нему. Ты найдешь его на аллее Духов.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nОбессиливающий сглаз\n\nСледующее заклинание будет наложено на вас:\n\nОбессиливающий сглаз\n\nВы также получите:\n\n"},
[5657] = {title = "Обессиливающий сглаз", objective = "Поговорите с Ур'кьо в Оргриммаре.", description = "Домой! Возвращайся домой, <юный/юная:r> <раса>!\n\nТвой духовный наставник Ур'кьо просит тебя вернуться к нему и поговорить об избранном тобой пути.\n\nСтупай в Аллею Духов в Оргриммаре, великом городе Орды! Ты найдешь его там.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nОбессиливающий сглаз\n\nСледующее заклинание будет наложено на вас:\n\nОбессиливающий сглаз\n\nВы также получите:\n\n"},
[5658] = {title = "Прикосновение слабости", objective = "А, юный жрец снова здесь. Я хочу преподать тебе урок, который ты не скоро забудешь. Готов ли ты?", description = nil, progress = nil, completion = nil, rewards = "Вы изучите:\n\nПрикосновение слабости\n\nСледующее заклинание будет наложено на вас:\n\nПрикосновение слабости"},
[5660] = {title = "Прикосновение слабости", objective = "Поговорите с Эльталисте в Подгороде.", description = "Далеко же ты <забрался/забралась:c>, <класс>. Тебя ждут в большом городе под землей. Твоя госпожа, Эльталисте, велит тебе вернуться. Как и в моем племени, есть вещи, которым тебя может научить лишь она. И не задерживайся попусту. Лучше лети в Квартал Воинов на самом быстром дирижабле.", progress = nil, completion = "А, вот и еще один. Для меня время не имеет значения, но для тебя оно бежит быстро. Тебе следует многому научиться, и я хочу передать тебе побольше знаний. А пока покажи, на что способен. Выполни это условие, и награда будет велика.", rewards = "Вы изучите:\n\nПрикосновение слабости\n\nСледующее заклинание будет наложено на вас:\n\nПрикосновение слабости\n\nВы также получите:\n\n"},
[5661] = {title = "Прикосновение слабости", objective = "Поговорите с Эльталисте в Подгороде.", description = "Ты всего лишь гость в Деревне Кровавого Копыта, <имя>, а дом твой далеко. Меня послали сюда искать жрецов из моего племени. С ними хотят говорить вожди. Но и тебе я могу помочь.\n\nГоворят, что ваша главная жрица велит всем Отрекшимся прийти к ней – видно, ей есть что сказать.\n\nСтупай, поговори с Эльталисте в Квартале Воинов этого вашего города, как его там...Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nПрикосновение слабости\n\nСледующее заклинание будет наложено на вас:\n\nПрикосновение слабости\n\nВы также получите:\n\n"},
[5662] = {title = "Прикосновение слабости", objective = "Поговорите с Эльталисте в Подгороде.", description = "Мое почтение тебе и твоему народу, <имя>. Обычно я учу лишь своих соплеменников. Тебе же передала знания Эльталисте из города, некогда звавшегося Лордероном.\n\nВозвращайся к ней, ведь только она может передать тебе способности, отличающие воинов вашей веры от других.\n\nСтупай в Квартал Воинов Подгорода и отыщи там свою госпожу.", progress = nil, completion = "А, вот и еще один. Для меня время не имеет значения, но для тебя оно бежит быстро. Тебе следует многому научиться, и я хочу передать тебе побольше знаний. А пока покажи, на что способен. Выполни это условие, и награда будет велика.", rewards = "Вы изучите:\n\nПрикосновение слабости\n\nСледующее заклинание будет наложено на вас:\n\nПрикосновение слабости\n\nВы также получите:\n\n"},
[5663] = {title = "Прикосновение слабости", objective = "Поговорите с Эльталисте в Подгороде.", description = "Эльталисте послала вести всем своим жрецам. Нам велено отправить молодежь в Подгород на обучение. Если ты в самом деле считаешь себя <одним/одной> из верных, возвращайся туда.\n\nЭльталисте живет в Квартале Воинов в глубинах Подгорода.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nПрикосновение слабости\n\nСледующее заклинание будет наложено на вас:\n\nПрикосновение слабости\n\nВы также получите:\n\n"},
[5672] = {title = "Благодать Элуны", objective = "Посвятив себя служению Элуне и нашему народу, ты достигла такого положения, которое не всякому из нас доступно. По традиции за великую твою преданность тебя полагается обучить более могучим способностям. Согласна ли ты?", description = nil, progress = nil, completion = nil, rewards = "Вы изучите:\n\nБлагодать Элуны\n\nСледующее заклинание будет наложено на вас:\n\nБлагодать Элуны"},
[5673] = {title = "Благодать Элуны", objective = "Поговорите в Дарнассе со жрицей Алатеей.", description = "Знай, что здесь ты можешь в любое время обратиться к любому наставнику, <имя>. Впрочем, есть знания, которые мы не можем тебе предоставить. Среди них – учение вашей богини Элуны. Верным своим приверженцам она дает особые способности, и, если я не ошибаюсь, тебе пора вернуться домой, в Храм Луны, и пройти испытание.\n\nТак что как сможешь – возвращайся и поговори со жрицей Алатеей.", progress = nil, completion = "Да благословит тебя Элуна за столь скорое возвращение. Это важный период в твоем обучении, и орден весьма серьезно к этому относится. Когда отдохнешь с дороги, дай мне знать. Тогда мы сможем поговорить о продолжении твоего обучения и о том, куда на сей раз приведет тебя твой путь.", rewards = "Вы изучите:\n\nБлагодать Элуны\n\nСледующее заклинание будет наложено на вас:\n\nБлагодать Элуны\n\nВы также получите:\n\n"},
[5674] = {title = "Благодать Элуны", objective = "Поговорите в Дарнассе со жрицей Алатеей.", description = "Настал славный день, <имя>. Ты $Gдостиг:достигла; возраста, когда наши <жрецы/жрицы> изучают те способности, которые свойственны только ночным эльфам. Тебе следует вернуться в Храм Луны и поговорить со жрицей Алатеей, как только закончишь тут свои дела. Она испытает тебя, убедится в твоей готовности и лишь потом научит тебя Благодати Элуны.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nБлагодать Элуны\n\nСледующее заклинание будет наложено на вас:\n\nБлагодать Элуны\n\nВы также получите:\n\n"},
[5675] = {title = "Благодать Элуны", objective = "Поговорите в Дарнассе со жрицей Алатеей.", description = "Не тяни время, <друг/подруга>. Пора тебе возвращаться домой в Дарнасс. Жрица Алатея велит возвращаться на обучение. Похоже, тебя решили допустить к испытаниям вроде тех, что проходят служители Света. Так что как сможешь – иди. Алатея в своем письме говорит, что будет ждать тебя в храме Луны. Удачи.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nБлагодать Элуны\n\nСледующее заклинание будет наложено на вас:\n\nБлагодать Элуны\n\nВы также получите:\n\n"},
[5676] = {title = "Волшебное искажение", objective = "Чтобы защититься от тайной магии, которая является нашим основным врагом, мы должны знать некоторые заклинания.\n\nЯ научу тебя заклинаниям, которые помогут защитить себя и спутников от вредоносного воздействия тайной магии.", description = nil, progress = nil, completion = nil, rewards = "Вы изучите:\n\nОтветная реакция\n\nСледующее заклинание будет наложено на вас:\n\nОтветная реакция"},
[5677] = {title = "Волшебное искажение", objective = "Поговорите с Верховной жрицей Лореной в Штормграде.", description = "Мне бы хотелось показать тебе кое-какие из наших особых методик обучения, которые направят тебя по пути Света, но меня опередили. Тебе нужно вернуться в Штормград, <имя>... Прямо сейчас. Поверь мне, так будет лучше. Когда ты встретишься с Верховной жрицей Лореной из Собора Света, ты поймешь, о чем я говорю. Для вашей расы настало время подумать о будущем и выбрать свой собственный путь.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nОтветная реакция\n\nСледующее заклинание будет наложено на вас:\n\nОтветная реакция\n\nВы также получите:\n\n"},
[5678] = {title = "Волшебное искажение", objective = "Поговорите с Верховной жрицей Лореной в Штормграде.", description = "Тебе пора возвращаться в Штормград. Старшие иерархи призывают тебя продолжить тренировки. Жаль, что мне пришлось разыскивать тебя, но я делаю это во имя союза между нашими расами.\n\nБуду говорить откровенно, тайная магия не внушает мне никакого доверия, хоть по благословлению богов, хоть без них...\n\nТы понимаешь, о чем я говорю? Вернись в Собор Света. Верховная жрица Лорена ждет тебя.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nОтветная реакция\n\nСледующее заклинание будет наложено на вас:\n\nОтветная реакция\n\nВы также получите:\n\n"},
[5679] = {title = "Всепожирающая чума", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы изучите:\n\nВсепожирающая чума\n\nСледующее заклинание будет наложено на вас:\n\nВсепожирающая чума"},
[5680] = {title = "Страж Тьмы", objective = "Время обряда уже близко. Теперь я научу тебя заклинанию, которое очень пригодится тебе в битвах с врагами.", description = nil, progress = nil, completion = nil, rewards = "Вы изучите:\n\nСтраж Тьмы\n\nСледующее заклинание будет наложено на вас:\n\nСтраж Тьмы"},
[5713] = {title = "Каждый выстрел – в цель", objective = "Защитите жизнь часового Айнаши, а потом поговорите с Ойнеей на Заставе Мейстры в Ясеневом лесу.", description = "Я направлялась в Аубердин с важным донесением, когда меня атаковал фурболг Марош и его следопыты. Во время атаки я получила отравление, так что еле держусь. Я могу изготовить противоядие, но это займет некоторое время.\n\nХотела попросить вас защитить меня, пока я не приму противоядие. Я подсоблю вам своим луком, как смогу.\n\nЕсли мы выживем, то смогу доставить донесение в Аубердин, а вас попрошу поговорить с Онейей на Заставе Мейстры и проинформировать ее о случившемся.", progress = nil, completion = "Вы принесли долгожданное известие, |3-6(Друид). Приятно слышать, что Айнаша жива и здорова благодаря вам. Смею надеяться, вы примете эту награду за вашу доблесть. Пусть Элуна заботится о вас и освещает ваш путь.", rewards = "Вы получите:\n\n"},
[5721] = {title = "Битва при Дарроушире", objective = "Положите сверток с реликвиями на городскую площадь Дарроушира.\n\nПредотвратите смерть Дейвила Яркосвета от рук Хоргуса.\n\nНе допустите смерти капитана Редпата до появления Редпата Оскверненного. \n\nУбейте Редпата Оскверненного. \n\nПоговорите с духом Джозефа Редпата, когда он вновь появится на городской площади, затем отправляйтесь к Памеле и поговорите с ней.", description = "Теперь, <имя>, тебе предстоит принять участие в битве при Дарроушире и спасти Джозефа Редпата.\n\nПоложи реликвии на городскую площадь Дарроушира, и духи его жителей восстанут из могил. Начнется битва, и ты <должен/должна> сделать все возможное, чтобы Дейвил выжил в битве с Хоргусом, а Редпат должен подвергнуться порче и после этого быть убитым.\n\nВ этом случае дух Редпата будет спасен. Поговори с ним и возвращайся к его дочери Памеле.", progress = "Там снаружи собрались злые духи. Они шепчут мне всякие ужасы...", completion = "Битва окончена! Мой папа сказал мне это! Он разогнал всех духов и возвращается домой! Я так счастлива! \n\nА еще он сказал, чтобы я радушно встретила тебя, так что я приготовила тебе чаю. Ты любишь с сахаром?", rewards = "Вы получите:\n\nЧай с сахаром"},
[5722] = {title = "В поисках потерянного ранца", objective = "Обыщите Огненную пропасть в поисках тела Маура Зловещего Тотема и найдите все необычные предметы.", description = "В Огненной пропасти Магату интересуют не только трогги. До нее дошли слухи, что один из ее слуг, некий Маур Зловещий Тотем, будучи в пропасти, нашел нечто особенное, но выбраться оттуда ему не удалось. Она хочет, чтобы кто-нибудь нашел тело Маура – если оно еще цело – и выяснил, что же он такое нашел, пытаясь вести переговоры с троггами.\n\nЕсли найдешь что-нибудь интересное, принеси это Магате, и она наверняка не поскупится на награду.\n\nДа, пропасть ищи в самых темных закоулках Оргриммара.", progress = nil, completion = "Тело выглядит так, будто Маура жестоко били дубинками или кулаками, но большая часть одежды и снаряжения на месте. Похоже, троггам не сильно были нужны его пожитки.\n\nВы начинаете осматривать тело в поисках любых предметов, которые могли бы заинтересовать Магату.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5723] = {title = "Испытание силы врага", objective = "Найдите в Оргриммаре Огненную пропасть, убейте 8 троггов и 8 шаманов Огненной пропасти и возвращайтесь к Рахауро в Громовой Утес.", description = "Назойливые твари, известные как трогги, вдруг полезли из заполненных лавой туннелей под Оргриммаром. Магата по своей доброте душевной хотела договориться с этими тварями, но они набросились на ее переговорщиков и перебили их. Но такого обращения с тауренами она допустить не может, так что теперь для нее эти твари – враги Орды.\n\nОна просит тебя разделаться с этими троггами, прежде чем они начнут угрожать Орде из-под земли. Найди Огненную пропасть и уничтожь их всех!", progress = nil, completion = "Я рад, что ты серьезно отнесся к просьбе Магаты. Спасибо тебе, Ахахаха. Теперь, когда троггов поубавилось, они уже не полезут так нагло на поверхность!\n\nМожет, в будущем мы сумеем узнать, откуда взялись эти твари, и что им надо.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5724] = {title = "Возвращение потерянной сумки", objective = "Отнесите сумку Маура Зловещего Тотема Рахауро в Громовой Утес.", description = "Под телом погибшего таурена вы находите сумку. Убитый до сих пор крепко держит ее – видимо, он пытался уберечь ее во время нападения троггов.\n\nВысвободив сумку из его крепкой хватки, вы закидываете ее себе на плечо и готовитесь возвращаться наружу из туннелей, чтобы отправиться к Рахауро в Громовой Утес.", progress = "Удалось ли что-нибудь найти, Демонорох? Хоть какой-нибудь намек на то, почему ее сородич погиб без нужды?", completion = "Прекрасно, Демонорох. Благодарю тебя.\n\nМагата сказала мне, что если ты найдешь ее сородича, то я должен отдать тебе вот это. Прошу, прими в знак благодарности.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПеробисерные наручиНаручи Саванны\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[5725] = {title = "Силы разрушения...", objective = "Принесите книги \"Заклинания Тьмы\" и \"Заклятия Пустоты\" Вариматрасу в Подгород.", description = "Тебе хорошо известно, что в Легионе принято всячески одаривать идейных последователей. Некоторым из этих даров лучше бы оказаться в руках у Темной Госпожи, чем у... простецов.\n\nНапример, в пещерах под Оргриммаром скрывается секта Совета Теней, известная как \"Огненный Клинок\". Госпожа сообщила, что они получили две могущественные книги заклинаний – она хотела бы \"позаимствовать\" их. Выполни ее волю.", progress = "Меня ждет сотня дел, |3-6(Воин). Где книги?", completion = "Молодец, |3-6(Воин). Ты оказал Темной Госпоже хорошую услугу. Ее подданным пригодятся твои упорство и честолюбие. Заходи ко мне в будущем. Быть может, я отправлю тебя на новые подвиги, которые помогут Темной Госпоже свергнуть Короля-лича и освободить рабов Плети.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМертвенные брюкиПоножи болотного черпателяПоножи горгульи\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[5726] = {title = "Тайные враги", objective = "Принесите лейтенантский знак отличия Траллу в Оргриммар.", description = "Чего я не потерплю, <имя>, так это предательства среди своих. Однако было бы глупо действовать напролом и сразу арестовать единственного известного мне предателя – это не очистит наши земли от порчи, наоборот, зараза расползется еще сильнее.\n\nНо ты, <юный искатель приключений/юная искательница приключений>, можешь проникнуть туда, куда моим агентам ходу нет. Ты можешь узнать правду... можешь обнаружить настоящего главу заговора!\n\nЕсли у тебя достаточно отваги, отправляйся к скале Черепа к востоку от Оргриммара, сорви с одного из чернокнижников клана Пылающего Клинка лейтенантский знак отличия и принеси его мне.", progress = "Ну что, Ахахаха, удалось тебе добыть знак отличия? Он необходим, чтобы внедриться в организацию, которая представляет собой самую серьезную угрозу Орде.\n\nТы еще узнаешь, насколько замысловатую сеть способны сплести как орки, так и люди, ведомые алчностью и жаждой власти. Тебе станут очевидны их козни и тайные помыслы. Ты обнаружишь, что вокруг тебя идет война, какая тебе и не снилась!", completion = "Молодец, Ахахаха! Слава духам! Быть может, именно ты – тот, кому суждено избавить меня от самых серьезных моих опасений! Ну кто бы мог подумать, что столь юное существо, как ты, сумеет достойно защитить наше дело? Ты мне напоминаешь меня самого в молодости... Я позабочусь о том, чтобы тебя достойно вознаградили за труды – если мы оба переживем грядущую бурю.\n\nЛадно, сейчас не время рассыпаться в похвалах. То, что тебе уже удалось совершить, – пустяки в сравнении с тем, что еще предстоит... Но начало положено хорошее.", rewards = "Вы получите:\n\n"},
[5727] = {title = "Тайные враги", objective = "Отнесите лейтенантский знак отличия Нииру Огненному Клинку. Убедите его в своей преданности Пылающему Клинку. Вернитесь к Траллу в Оргриммар.", description = "Ну-ка, посмотрим, стоил ли принесенный тобой знак отличия таких усилий.\n\nВ городе живет чернокнижник, который уверен, будто я ему полностью доверяю. Он и не подозревает, что мне известно о его предательстве. На самом деле он – предводитель Пылающего Клинка... Однако не торопись вступать с ним в бой. Он нам еще нужен, мы можем использовать его, чтобы навредить нашим врагам.\n\nОтнеси ему этот знак отличия в расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за <одного/одну> из своих. А потом возвращайся ко мне.", progress = "Ну что, |3-6(Воин)? Поверил ли он нашему обману, или все хуже, чем я думал поначалу?\n\nЕсли ты докажешь Нииру свою полезность, нам будет куда проще проникнуть в Совет Теней. У Нииру наверняка предостаточно информации, которую можно будет использовать, чтобы извести под корень всех, кто хочет погубить наше дело.", completion = "Великолепно, |3-6(Воин)! Просто великолепно!\n\nТвое сегодняшнее деяние – всего лишь первый шаг к куда более серьезным делам. Возможно, это поможет нам уничтожить Совет Теней раз и навсегда.\n\nПерескажи мне все, что он говорил, и смотри, не упусти ни слова: какой-нибудь пустяк может оказаться важнее, чем ты думаешь.", rewards = "Вы получите:\n\n"},
[5728] = {title = "Тайные враги", objective = "Убейте Баззалана и Жергоша Призывателя Духов и вернитесь в Оргриммар к Траллу.", description = "Хм, предводители клана Огненного Клинка... Это серьезно. Если Нииру ими дорожит, значит, именно их и нужно ликвидировать. Этот сатир... Баззалан, и тот, второй, которого упоминал Нииру, – он кто, чернокнижник? – их следует убить.\n\nВозвращайся в расселину Теней и проникни в Огненную пропасть, <имя>. Разыщи этих предводителей клана Огненного Клинка и убей их. Но будь <осторожен/осторожна>, чтобы Нииру не узнал, что это твоих рук дело. Пусть по-прежнему считает тебя <одним из братьев/одной из сестер> по оружию.", progress = nil, completion = "Я рад, что ты вернулся, Демонорох. Преданные мне агенты уже сообщили, что в пещерах под Оргриммаром воцарился хаос – теперь, когда их предводители убиты. Мне даже докладывали, что Нииру более чем взбудоражен. Похоже, мы пробили брешь в его броне. Не могу не признать, что меня это радует... Пусть небольшая, но все же победа.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5729] = {title = "Тайные враги", objective = "Поговорите с Нииру Огненным Клинком в Оргриммаре.", description = "Думаю, теперь тебе следует попытаться войти в число приближенных Нииру. Если он действительно так взбудоражен, как мне доносят, мы убьем сразу двух зайцев. Во-первых, тебе, возможно, удастся разузнать побольше о Совете или, по крайней мере, о Пылающем Клинке, и, во-вторых, он, возможно, начнет доверять тебе настолько, что попросит ему помогать. Ему сейчас отчаянно не хватает помощников.\n\nВозвращайся в Расселину и поговори с ним, но не особо навязывайся.", progress = nil, completion = "Ну в чем дело?! Ах, это ты, |3-6(Воин)... Прошу прощения. Я зол, как бешеный кодо... Но, возможно, я сам во всем виноват. Отправляя путешественников в Огненную пропасть, я должен был предвидеть, что это чревато проблемами. Похоже, что Баззалана и Жергоша застиг врасплох кто-то из Тралловых доброхотов. Они оба убиты. Как это невовремя! Но тут уж ничего не поделаешь.", rewards = "Вы получите:\n\n"},
[5730] = {title = "Тайные враги", objective = "Поговорите с Траллом в Оргриммаре.", description = "Теперь ты <один/одна> из моих лейтенантов! Готовься, <класс>. Скоро я призову тебя.\n\nМожно считать, что с Огненным Клинком я зря потратил время, но это не значит, что другие планы Совета Теней должны пострадать. Я сделаю все, что смогу, чтобы свести к минимуму потери здесь, в Огненной пропасти. А пока что распоряжусь, чтобы мои агенты в Степях и Ясеневом лесу начали выполнять наши последние замыслы. Возвращайся ко мне как можно скорее.", progress = nil, completion = "Ясеневый лес? Хм. Впервые слышу о присутствии Совета или Пылающего Клинка в Ясеневом лесу. Я поручу своим агентам это проверить, Томпсон. А ты молодец.\n\nПока отдыхай, занимайся другими делами. Скоро я призову тебя снова.\n\nЛок-тар Огар!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКрис ОргриммараМолот ОргриммараТопор ОргриммараПосох Оргриммара\n\nВы также получите:\n\n"},
[5741] = {title = "Скипетр Света", objective = "Отыщите Скипетр Света и принесите его Азору Альдаморту в башню Этель-Ретор.", description = "Говорят, что клан Пылающего Клинка, обосновавшийся на востоке в Крепости Громового Топора, заполучил Скипетр Света, добыв его у наг. Легенда гласит, что этот скипетр обладает властью погружать целые города в пучины моря. Мы не можем позволить, чтобы такая сила оставалась в их руках.\n\nТвой долг – вырвать скипетр из недостойных рук! Сейчас он у ясновидца из клана Пылающего Клинка на одной из башен крепости Громового Топора.", progress = "Ты нашел Скипетр Света? Он у тебя?", completion = "Неуловимый Скипетр Света!.. Добыв его, ты избавил мир от великой угрозы. Прекрасно, |3-6(Маг), просто прекрасно!..", rewards = "Вы получите:\n\n"},
[5742] = {title = "Спасение", objective = "Выслушайте Тириона Фордринга.", description = "Ты славно <поработал, друг мой/поработала> подруга;. Отдохни, а я пока расскажу тебе мою историю до конца.", progress = "Прошу, друг мой, сядь и выслушай меня.", completion = "Вернуть моего сына на путь истинный будет нелегко. Ты готов?", rewards = "Вы получите:\n\n"},
[5761] = {title = "Убить тварь", objective = "Спуститесь в Огненную пропасть, убейте Тарагамана Ненасытного и принесите его сердце Нииру Огненному Клинку в Оргриммаре.", description = "Главная задача, которую поручил мне наш великий вождь, – это извести тех тварей, которые повинны в том, что в великий город нашего владыки проникают демоны. Клан Пылающего Клинка – главная, но не единственная угроза. Есть еще и Огненный Клинок, клан, который обосновался в Огненной пропасти и втайне смущает умы простых представителей Орды.\n\nЧтобы их остановить, нужно убить их предводителя, стража Скверны по имени Тарагаман Ненасытный.\n\nУбей его. Я уверен, Вождь будет рад получить его сердце...", progress = "Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!", completion = "Ага! Тебе это удалось! Тралл, конечно, будет в восторге.\n\nЯ позабочусь о том, чтобы это сердце попало по назначению.\n\nНу, а ты можешь отпраздновать свою победу. Я сообщу Траллу о твоем успехе.\n\nСпасибо за помощь, |3-6(Воин).", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5762] = {title = "Хеминг Эрнестуэй", objective = "Отнесите ящик Крейвела Хемингу Эрнестуэю в Тернистую долину.", description = "У меня тут посылка для одного старого покупателя, дворфа по имени Хеминг Эрнестуэй. Посылка шла очень долго, и Хеминг уехал, не дождавшись ее. Говорят, что теперь он где-то в Тернистой долине, охотится там на зверей. Перед отъездом он оставил мне немного денег, чтобы я переслал ему посылку.\n\nОн очень богатый дворф, а с такими полезно водить дружбу, правда? Так что... не желаешь ли доставить Хемингу эту посылку?\n\nГоворят, он разбил лагерь в Тернистой долине, к северу от Гром'гола.", progress = "Уж не пустынная ли это пыль у тебя на воротнике?\n\nХм... Если мой нос не врет, то это не пыль, а соль! Прямиком с Мерцающей равнины, да?", completion = "Отлично, посылочка от Углебрада! Спасибо, Томпсон! В этом ящике находится специальное измерительное оборудование, – по крайней мере так сказал мой отец, – и в джунглях оно нам очень пригодится.\n\nВот ваша плата, и расскажите мне, как там поживает старина Углебрад? Наверняка опять замышляет какую-нибудь пакость?", rewards = "Вы получите:\n\n"},
[5763] = {title = "Охота в Тернистой долине", objective = "Отнесите рог кодо, принадлежащий Руну, Хемингу Эрнестуэю в Тернистую долину.", description = "Давным-давно пришел в эти земли дворф. Звали его Хеминг, и он хотел поохотиться на крупного зверя. С ружьем он умел обращаться просто великолепно, и много дней мы охотились с ним вместе, забыв даже о вражде, разделявшей наши народы…\n\nКогда он уходил в Тернистую долину, я поклялся, что, когда бы он ни вернулся, я встречу его как дорогого гостя. И вот это время пришло.\n\nОтнеси этот рог кодо в подарок Хемингу. Он поймет, что это это от меня. Ты найдешь его в Тернистой долине, к северу от лагеря Гром'гол.", progress = "Присядь и отдохни, |3-6(Охотник). Скоро ты снова отправишься в джунгли...", completion = "О, этот рог принадлежит таурену Руну Буйногривому! Отец часто рассказывал о том, как славно они вместе охотились в Пустошах. Значит, Рун приглашает меня на охоту, да?\n\nУ нас сейчас дел по горло, но я все равно благодарен тебе за добрую весть, Томпсон. Возможно, следующая моя экспедиция будет в Пустоши, в земли кентавров.", rewards = "Вы получите:\n\n"},
[5781] = {title = "Символ ушедших дней", objective = "Отправляйтесь в Крипту – в самой южной части Восточных Чумных земель – и добудьте молот Таэлана. Отнесите его Тириону Фордрингу.", description = "Чтобы помочь Таэлану вернуться на путь истинный, мы должны найти то, что напомнит ему о прошлом.\n\nОдин из таких предметов  – игрушка, которую я подарил ему на семилетие. Он очень дорожил этим маленьким боевым молотом, уменьшенной копией моего собственного оружия.\n\nКогда меня изгнали за предательство, его мать сказала сыну, что я погиб. Его отвели к моей пустой могиле в Крипте, и там он похоронил свой молот вместе со всеми воспоминаниями обо мне.\n\nПрошу тебя, отправляйся в Крипту и принеси молот Таэлана.", progress = "Он должен быть спасен.", completion = "*Тирион с трудом сдерживает слезы.*\n\nСама судьба свела нас вместе, Томпсон. Да благословят тебя небеса за доброту.", rewards = "Вы получите:\n\n"},
[5801] = {title = "Кузня Пламенного хребта", objective = "Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.\n\nОтнесите недоделанную отмычку алхимику Арбингтону на Берег Промозглого Ветра в Западные Чумные земли.", description = "Чтобы выковать основу ключа тебе понадобится два ториевых слитка и мощный источник тепла. Торий добывай самостоятельно, а где найти подходящую плавильню, я подскажу.\n\nНа западе от Кратера Ун'Горо располагается Вулкан Огненного Венца – действующий вулкан. Лава из его жерла сплавит торий и кость воедино. Твои денежки потрачены не зря – эту форму для отливки можно просто-напросто окунуть в огненное озеро, а остальное сделает лава.\n\nВот и все, чем я могу тебе помочь. Как доделать ключ тебе подскажет Арбингтон.", progress = "Тебе удалось сделать заготовку отмычки? Мне жаль, что тебе пришлось покупать форму на свои деньги, но всем приходится вносить свой вклад в борьбу с Плетью. Отдай мне заготовку отмычки, и я скажу, чего не хватает для завершения работы над ней.\n\nЭто будет нелегко, но подготовка к нападению на Андорал не пропадет втуне. Вот увидишь.", completion = "Недешево обошлась тебе эта отмычка, а? И все же работа над ней не закончена; пришло время завершающего этапа – а это самое сложное. Тебе придется выступить против того самого врага, что ждал нас в Андорале... Злобной твари, которая правит бал в стенах разрушенного города.\n\nЯ говорю об Араже Призывателе – личе, одном из самых могущественных сторонников Плети.", rewards = "Вы получите:\n\n"},
[5802] = {title = "Кузня Пламенного хребта", objective = "Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.\n\nОтнесите недоделанную отмычку аптекарю Дитерсу в Бастион, что в Западных Чумных землях.", description = "Чтобы выковать основу ключа тебе понадобится два ториевых слитка и мощный источник тепла. Торий добывай самостоятельно, а где найти подходящую плавильню, я подскажу.\n\nНа западе от Кратера Ун'Горо располагается Вулкан Огненного Венца – действующий вулкан. Лава из его жерла сплавит торий и кость воедино. Твои денежки потрачены не зря – эту форму для отливки можно просто-напросто окунуть в огненное озеро, а остальное сделает лава.\n\nВот и все, чем я могу тебе помочь. Как доделать ключ тебе подскажет Дитерс.", progress = "Тебе удалось сделать заготовку отмычки? Мне жаль, что тебе пришлось покупать форму на свои деньги, но всем приходится вносить свой вклад в борьбу с Плетью. Отдай мне заготовку отмычки, и я скажу, чего не хватает для завершения работы над ней.\n\nЭто будет нелегко, но подготовка к нападению на Андорал не пропадет втуне. Вот увидишь.", completion = "Недешево обошлась тебе эта отмычка, а? И все же работа над ней не закончена; пришло время завершающего этапа – а это самое сложное. Тебе придется выступить против того самого врага, что ждал нас в Андорале... Злобной твари, которая правит бал в стенах разрушенного города.\n\nЯ говорю об Араже Призывателе – личе, одном из самых могущественных сторонников Плети.", rewards = "Вы получите:\n\n"},
[5803] = {title = "Скарабей Араджи", objective = "Убейте Аража Призывателя отнесите его скарабея алхимику Арбингтону на Берег Промозглого Ветра, что в Западных Чумных землях.", description = "Араж Призыватель правит Андоралом из самого сердца разрушенного города. Мы знаем, что он был главой Некроситета, пока не захватил целый город. Для завершения работы над ключом нам нужен его перстень – он называется скарабеем – из него мы создадим головку ключа.\n\nПроберись в сердце Андорала и лиши его власти над городом, теперь, когда с ним можно сражаться в открытую. Убив мерзавца, забери скарабея!\n\nКлюч от Некроситета ждет тебя, <имя>!", progress = "Ты сумел далеко зайти, Кенмур – но только уничтожение физического облика Аража Призывателя даст нам возможность завершить работу над ключом. Добудь скарабея Араджа – любым из возможноых способов – и принеси мне, и я сделаю из него головку ключа.", completion = "А, вот она! Я... поражен твоей отвагой и хитростью. У меня в голове не укладывается, на что ты готов пойти ради победы над силами тьмы.\n\nПозволь и мне сыграть свою небольшую роль в твоем подвиге. Я приготовил особый раствор, который позволит мне закрепить скарабея в верзней части ключа. Его сила отомкнет двери Некроситета.\n\nНу вот, остался пустячок...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5804] = {title = "Скарабей Араджи", objective = "Убейте Аража Призывателя и отнесите его скарабея аптекарю Дитерсу в Бастион, что в Западных Чумных землях.", description = "Араж Призыватель правит Андоралом из самого сердца разрушенного города. Мы знаем, что он был главой Некроситета, пока не захватил целый город. Для завершения работы над ключом нам нужен его перстень – он называется скарабеем – из него мы создадим головку ключа.\n\nПроберись в сердце Андорала и лиши его власти над городом, теперь, когда с ним можно сражаться в открытую. Убив мерзавца, забери скарабея!\n\nКлюч от Некроситета ждет тебя, <имя>!", progress = "Ты сумел далеко зайти, Надей – но только уничтожение физического облика Аража Призывателя даст нам возможность завершить работу над ключом. Добудь скарабея Аража – мытьем или катаньем – и принеси мне, и я сделаю из него головку ключа.", completion = "А, вот она! Я... поражен твоей отвагой и хитростью. У меня в голове не укладывается, на что ты готов пойти ради победы.\n\nПозволь и мне сыграть свою небольшую роль в твоем подвиге. Я приготовил особый раствор, который позволит мне закрепить скарабея в верзней части ключа. Его сила отомкнет двери Некроситета.\n\nМного времени это не займет...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5805] = {title = "Добро пожаловать!", objective = "Передайте подарочный сертификат Златоземья Мериссе Стилвелл.", description = "Добро пожаловать в \"World of Warcraft\"!\n\nВ знак особой благодарности за приобретение коллекционного издания \"World of Warcraft\" примите этот подарочный сертификат и передайте Мериссе Стилвелл в долине Североземья. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.\n\nЕще раз благодарим вас и желаем приятного пребывания в \"World of Warcraft\"!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКамень ДьяблоОшейник пандыПоводок зерглинга"},
[5821] = {title = "Наемный телохранитель", objective = "Охраняйте караван Гизлтона на пути мимо деревни кентавров из племени Колкар. О награде поговорите со Смидом в Лагере Заржавня.", description = "Обычно мы с Риггером проводим кодо мимо поселения кентавров из племени Колкар. Боевые барабаны кентавров слышно издалека, так что, едва заслышав их, мы останавливаемся, чтобы переждать опасность. Мертвый торговец, знаешь ли, плохой торговец!\n\nВот что я тебе скажу, <класс>: если ты будешь охранять нас по дороге мимо деревни Колкар, мы тебе за это хорошо заплатим.\n\nРасстояние-то небольшое, да и делать почти ничего не придется – только проследить за тем, чтобы караван был цел. А награду ты получишь, не сомневайся: Смид Заржавень тебе сполна заплатит, мы с ним обделываем кое-какие делишки. Он живет чуть дальше по дороге.", progress = nil, completion = "Знаешь ли, мне не кажется такой уж хорошей идеей платить таким, как ты, за охрану каравана Гизлтона, |3-6(Охотник). Будь я повыше ростом, взялся бы за работу по совместительству. Только представь: сижу это я на кодо в седле, а в руках у меня – самая большая в мире пушка, и я готов показать этим кентаврам, где нежить зимует... А?", rewards = "Вы получите:\n\nКольцо Торговца"},
[5841] = {title = "Добро пожаловать!", objective = "Принесите подарочный сертификат Холодной долины Йори Шлемолому.", description = "Добро пожаловать в World of Warcraft!\n\nВ знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Йори Шлемолому в Холодной долине. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.\n\nЕще раз благодарим вас и желаем приятного пребывания в World of Warcraft!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКамень ДьяблоОшейник пандыПоводок зерглинга"},
[5842] = {title = "Добро пожаловать!", objective = "Отнесите подарочный сертификат Тенистой долины Орентилу Шепоту Ветра.", description = "Добро пожаловать в World of Warcraft!\n\nВ качестве особой благодарности за покупку коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Орентилу Шепоту Ветра в Тенистой долине. Вас ждет подарок – маленький спутник, который будет сопровождать вас на пути к приключениям и славе. \n\nЕще раз благодарим вас и желаем приятного времяпрепровождения в World of Warcraft!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКамень ДьяблоОшейник пандыПоводок зерглинга"},
[5843] = {title = "Добро пожаловать!", objective = "Передайте подарочный сертификат долины Испытаний Магге.", description = "Добро пожаловать в World of Warcraft!\n\nВ знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Магге в долине Испытаний. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.\n\nЕще раз благодарим вас и желаем приятного пребывания в World of Warcraft!", progress = nil, completion = "Таких героев, как вы, Облаумка, мало! Приветствуем вас в мире Азерота и вручаем вам этот уникальный дар!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКамень ДьяблоОшейник пандыПоводок зерглинга"},
[5844] = {title = "Добро пожаловать!", objective = "Отнесите подарочный сертификат лагеря Нараче Ворну Небесному Провидцу.", description = "Добро пожаловать в World of Warcraft!\n\nВ знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Ворну Небесному Провидцу в лагере Нараче. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.\n\nЕще раз благодарим вас и желаем приятного пребывания в World of Warcraft!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКамень ДьяблоОшейник пандыПоводок зерглинга"},
[5845] = {title = "Символ утраченной чести", objective = "Отправляйтесь в Северный дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу.", description = "Со смертью Утера орден Серебяной Длани утратил боевой дух.\n\nМой мальчик держался до последнего. Но, отступая в разоренную деревушку Северного дола, он принял окончательное решение.\n\nВыжил ли кто из ордена, подумал он, да и какая разница?\n\nС этой мыслью Таэлан бросил знамя Серебряной Длани и отрекся от всего, что прежде было ему дорого. Его честь осталась на обагренной кровью земле Северного дола.\n\nОтправляйся в Северный дол и принеси мне этот символ утраченной чести.", progress = "Моя вера поможет тебе, Томпсон. Свет не ведает пределов.", completion = "Даже в столь плачевном состоянии оно так же прекрасно, как и в тот день, когда я принес присягу, глядя на него.\n\nВозможно, вместе с этим знаменем ты спас и мою душу.", rewards = "Вы получите:\n\n"},
[5846] = {title = "Символ семейной любви", objective = "Отправляйтесь на остров Каэр Дарроу в центральной части Чумных земель и поищите там картину.", description = "Когда Таэлан был маленьким, мы нередко ездили в Каэр Дарроу. В последний раз художница по имени Ренфри изобразила всю нашу семью на берегу. Это лучшее мое воспоминание о Таэлане и Карандре. Именно тогда, стоя рядом с женой и держа на руках сына, я чувствовал глубокую связь с собственной семьей, которую мне не дано было почувствовать вновь.\n\nЕсли эта картина все еще существует, найди ее.\n\nОтправляйся на разоренный остров Каэр Дарроу и выясни, уцелел ли художник или картина.", progress = nil, completion = "Как я могла забыть? Многие духи этого острова обречены хранить последние счастливые воспоминания перед трагической гибелью.\n\nПроклятье это коснулось и меня – я одна из немногих, кто помнит все…\n\nБыть может, именно эта вещь, которая тебя интересует, держит меня прикованной к этим руинам. Я расскажу тебе все, что знаю, в надежде, что это дарует мне свободу.", rewards = "Вы получите:\n\n"},
[5847] = {title = "Добро пожаловать!", objective = "Отнесите подарочный сертификат Похоронного Звона Клэр Вилловер в Могильнике.", description = "Добро пожаловать в World of Warcraft!\n\nВ качестве особой благодарности за покупку коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Клэр Вилловер в Могильник. Вас ждет подарок – маленький спутник, который будет сопровождать вас на пути к приключениям и славе. \n\nЕще раз благодарим вас и желаем приятного времяпрепровождения в World of Warcraft!", progress = "Приветствую вас! Приятно познакомиться!\n\nЯ вижу, у вас есть специальный сертификат. Передайте его мне, и я предложу вам кое-что взамен.", completion = "Вы действительно незаурядная личность, Пейн. Мы приветствуем вас в мире Азерота и предлагаем вам один из этих уникальных подарков!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКамень ДьяблоОшейник пандыПоводок зерглинга"},
[5848] = {title = "Символ семейной любви", objective = "Отправляйтесь в Статхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину \"Символ семейной любви\", спрятанную за другой, изображающей две луны нашего мира.\n\nОтнесите картину Тириону Фордрингу.", description = "На стене мой мастерской... В казармах ордена... долгие годы висела картина.\n\nПосле суда над Тирионом я знала, что не смогу держать ее на виду. Я спрятала ее так, чтобы никто не нашел.\n\nОтправляйся в Стратхольм и проберись в то, что ныне зовется Бастионом Алого ордена. Найди там картину с двумя лунами. Сними лишнюю краску и увидишь мой шедевр – \"Символ семейной любви\".\n\nДа направляет Свет твою руку.", progress = "Картина. Где картина?", completion = "*При виде картины Тирион хватается за сердце.*\n\n*Он начинает всхлипывать.*", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5861] = {title = "Найти Миранду", objective = "Отправляйтесь к гробнице Утера, которая находится в южных Чумных землях. Покажите Миранде Колдунье подарок Тириона.", description = "Ты <сделал/сделала>  все, о чем я тебя просил. Остался один, последний шаг на пути к спасению.\n\nОтнеси все собранные тобой предметы Таэлану. К сожалению, Таэлан и его рыцари Алого ордена нападут на тебя, едва завидев.\n\nЕсть только один способ доставить мое сообщение – приняв обличье врага.\n\nНа юге отсюда находится гробница Утера. Там живет моя старая добрая подруга, Миранда. Найди ее, покажи все собранные тобой предметы, и она тебе поможет.", progress = "Я давно дожидалась этого дня.", completion = "Я была самой доверенной советницей Тириона, когда он носил титул лорда Марденхольдского. Я открыто отреклась от вердикта ордена Серебряной Длани и была изгнана за неповиновение.\n\nНа долю Тириона выпало много боли и разочарований. Готов ли ты исправить несправедливости, обрушившиеся на Фордрингов?", rewards = "Вы получите:\n\n"},
[5862] = {title = "Уловка против Алого Марша", objective = "Поговорите с Мирандой, пусть она наложит на вас Алую иллюзию. Отправляйтесь в Дольный Очаг, покуда она действует, и отнесите подарок Тириона верховному лорду Телану Фордрингу.\n\nДольный Очаг на севере, а Таэлан должен быть внутри Крепости Марденхольд.", description = "Я, как говорится, иллюзионистка. Хотя я могу создать иллюзию, благодаря которой ты проберешься в Дольный Очаг, помни – сила моя не безгранична.\n\nЕсли ты забредешь слишком далеко, иллюзия рассеется. Заклинание требует от меня значительного количества сил и сосредоточения, и я не слишком долго смогу поддерживать его.\n\nКогда будешь <готов/готова> – обращайся.", progress = "Ты прибыла нам на помощь из Длани Тира?", completion = "Что это, солдат?\n\nТаэлан открывает коробку и начинает рассматривать содержимое.*\n\nЭтого... Этого не может быть. Но все, что ты мне показала…\n\n*Таэлан опускается на колено, сердце у него колотится. На этот город того и гляди выплеснется ярость веков.*", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[5863] = {title = "Поселение Песчаного Молота", objective = "Анди Линн из Прибамбасска просит уничтожить поселение Песчаного Молота, убив 10 громил и 10 мародеров из клана Песчаного Молота и Гор'марока Опустошителя.", description = "Совсем недавно в Танарисе появились огры-кочевники. Они захватили большой участок пустыни к югу отсюда и построили целую крепость. Племена поменьше бродят по пустыне, захватывая руины тролльских городов.\n\nПоселение Песчаного Молота должно пасть! Не позволим же ограм превратиться в страшную силу.\n\nИх главаря зовут Гор'марок Опустошитель. Мне кажется, что если его устранить, это станет началом конца огров.", progress = nil, completion = "Я так рада, что ты выполнил мою просьбу, Эфром! Спасибо за помощь!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки Сухого семениОплечье Мехового леса\n\nВы также получите:\n\n"},
[5881] = {title = "Смена караула", objective = "Маггран просит вас передать письмо Гришу Выносливому Гонцу у Великого подъемника в Степи.", description = "Орда не дает нам растерять силы, и это правильно! С самой Великой Войны мы здесь, в Калимдоре, живем неплохо.\n\nЯ прошу тебя оказать мне услугу: один парень по имени Гриш Выносливый Гонец охраняет Великий подъемник в западных пустошах. Передай ему это письмо: там говорится, что один из солдат запаса скоро придет ему на смену, чтобы он мог навестить свою семью. Гриш недавно просил об этом, и он будет рад услышать эти новости.", progress = "У тебя какие-то новости от землепряда Магграна?", completion = "Это хорошие новости; я слишком долго сижу здесь, охраняя этот кусок дерева. Теперь я смогу побыть со своими родными... Ура!", rewards = "Вы получите:\n\n"},
[5882] = {title = "Лекарство из охотничьих трофеев", objective = "Тот, кто имеет при себе Маяк Кенария, может оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.\n\nЗа эти осколки я дам тебе немного уже готового бальзама.", description = nil, progress = "Тот, кто имеет при себе Маяк Кенария, может оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.\n\nЗа эти осколки я дам тебе немного уже готового бальзама.", completion = "Очень хорошо, вот тебе кенарийский бальзам. Ищи в Оскверненном лесу пораженные растения, Кеа! Когда найдешь, исцеляй их при помощи моего целебного бальзама.", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[5883] = {title = "Лекарство из минералов", objective = "Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.\n\nЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.", description = nil, progress = "Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.\n\nЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.", completion = "Что же, прекрасно! Вот тебе кенарийский бальзам. Если при разработках жил металлов в Оскверненном лесу найдешь еще порченого купороса, не забудь принести его мне! Чем больше найдешь, тем больше бальзама я смогу сделать.", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[5884] = {title = "Лекарство из оскверненных трав", objective = "Маяк Кенария позволяет опрытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться преврашать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.\n\nВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие Маяк Кенария. За то, что ты мне принесешь, я дам тебе уже готового бальзама Кенария.", description = nil, progress = "Маяк Кенария позволяет опрытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться преврашать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.\n\nВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие Маяк Кенария. За то, что ты мне принесешь, я дам тебе уже готового бальзама Кенария.", completion = "Отличная работа, Кирпичег – все это после очищения пойдет на исцеление Оскверненного леса. Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес. Исцеление этого края от порчи не терпит отлагательств!", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[5885] = {title = "Лекарство из оскверненных шкур", objective = "Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженных порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!\n\nКогда соберешь порченые клочки, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.", description = nil, progress = "Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженных порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!\n\nКогда соберешь порченые клочки, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.", completion = "То что нужно! Вот, бери этот бальзам для исцеления растений и лечи им Оскверненный лес от порчи! Мы не должны сдаваться, Кавару!", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[5886] = {title = "Лекарство из распыленных предметов", objective = "Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.\n\nМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам бальзама исцеления Кенария. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!", description = nil, progress = "Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.\n\nМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам бальзама исцеления Кенария. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!", completion = "Вот тебе кенарийский бальзам, и за него я прошу только одну порцию простой субстанции Пустоты, Лолкка. Субстанция эта – вещество самое мощное из тех, что я применяю при перековке мечей на орала. Если тебе понадобится еще бальзам, ищи меня тут!", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[5887] = {title = "Лекарство из охотничьих трофеев", objective = "Обладание Маяком Кенария позволяет увидеть оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.\n\nЗа эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений.", description = nil, progress = "Обладание Маяком Кенария позволяет увидеть оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.\n\nЗа эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений.", completion = "Очень хорошо, вот тебе кенарийский бальзам. Ищи в Оскверненном лесу пораженные растения, Томпсон! Когда найдешь, исцеляй их при помощи моего целебного бальзама.", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[5888] = {title = "Лекарство из минералов", objective = "Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.\n\nЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.", description = nil, progress = "Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.\n\nЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.", completion = "Что же, прекрасно! Вот тебе кенарийский бальзам. Если при разработках жил металлов в Оскверненном лесу найдешь еще порченого купороса, не забудь принести его мне! Чем больше найдешь, тем больше бальзама я смогу сделать.", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[5889] = {title = "Лекарство из оскверненных трав", objective = "Маяк Кенария позволяет опытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться превращать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.\n\nВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие \"Маяк Кенария\". За то, что ты мне принесешь, я дам тебе уже готового бальзама Кенария.", description = nil, progress = "Маяк Кенария позволяет опытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться превращать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.\n\nВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие \"Маяк Кенария\". За то, что ты мне принесешь, я дам тебе уже готового бальзама Кенария.", completion = "Отличная работа, Мну – все это после очищения пойдет на исцеление Оскверненного леса. Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес. Исцеление этого края от порчи не терпит отлагательств!", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[5890] = {title = "Лекарство из оскверненных шкур", objective = "Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженных порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяк Кенария!\n\nКогда соберешь испорченные куски, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.", description = nil, progress = "Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженных порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяк Кенария!\n\nКогда соберешь испорченные куски, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.", completion = "То что нужно! Вот, бери этот бальзам для исцеления растений и лечи им Оскверненный лес от порчи! Мы не должны сдаваться, Бурн!", rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[5891] = {title = "Лекарство из распыленных предметов", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nКенарийский бальзам исцеления растений"},
[5892] = {title = "Припасы Железного рудника", objective = "Принесите 10 припасов Железного рудника интенданту Альянса в Дун Болдар.", description = "Пока не началась война, мы хранили припасы для Дун Болдара на Железном руднике. Когда у нас были войска, чтобы охранять рудник, трогги не были такой уж большой проблемой, но сейчас мы сражаемся с Ордой и не в силах его удерживать.\n\nТем не менее, припасы с Железного рудника нам очень нужны, <имя>. Отправляйся туда и добудь их.", progress = "Что, Ахей, удалось раздобыть припасы? Их вечно не хватает...", completion = "Отлично! Уж я найду применение этому добру. Спасибо, Ахей!", rewards = "Вы получите:\n\n"},
[5893] = {title = "Припасы Ледяного Зуба", objective = "Доставьте 10 припасов Ледяного Зуба интенданту Орды в крепость Северного Волка.", description = "Рудник Ледяного Зуба, к северу отсюда, был идеальным местом для хранения припасов. Но сейчас, когда разгорелась война с Грозовой Вершиной, у нас не хватает солдат, чтобы его постоянно патрулировать и охранять. Так что рудник постоянно переходит из рук в руки, – то к Альянсу, то к местным подземным жителям...\n\nНо припасы нам по-прежнему нужны, <имя>! Ступай на рудник Ледяного Зуба и добудь их. Будь <осторожен/осторожна> – в этом месте то и дело возникают стычки.", progress = "Ты вернулся с рудника Ледяного Зуба? А где припасы?", completion = "А, вот они! Отличная работа, Гонзага! Припасы немного заплесневели – сказывается влажность воздуха в руднике – но все равно сгодятся.\n\nСпасибо тебе, Гонзага. Ты помог нашим войскам поддержать силы.", rewards = "Вы получите:\n\n"},
[5901] = {title = "Чума на вашу лесопилку!", objective = "Возьмите пустую банку для термитов и отправляйтесь к большим термитникам в Восточных Чумных землях. Наберите 100 термитов Восточных Чумных земель и возвращайтесь к Микки Левину в Бастион в Тирисфальских лесах.", description = "Ну все, теперь у меня есть партизанский план борьбы с Алым орденом! Для начала они расплатятся за свои деяния лесопилкой. Вот они у меня попрыгают! Посмотрим, будут ли они также лихо перестраивать все в городе под свои нужды, когда я перекрою им поступления стройматериалов. Поможешь мне, <имя>?\n\nВозьми эту банку и отправляйся в Проклятый лес, что в Восточных Чумных землях. Найди термитник и набери полную банку насекомых – уж мы натравим их на Алый орден!", progress = "Ну как, нашел термитники, Томпсон? Не сомневаюсь, такой умный |3-6(Охотник) справится с такой простенькой задачей!\n\nНаберем термитов и устроим диверсию на лесопилке!", completion = "Замечательно, Томпсон. Благодарю тебя.\n\nЕсли не сдрейфил, продолжим!", rewards = "Вы получите:\n\n"},
[5902] = {title = "Чума на вашу лесопилку!", objective = "Найдите подходящее место на лесопилке Северного Кряжа в Западных Чумных землях и оставьте там бочонок термитов из Чумных земель.\n\nПрилагается предмет: \n", description = "Теперь у нас просто прорва термитов. Я надежно запрятал их вот в этот окованный железом бочонок. Отнеси его на лесопилку Северного Кряжа, это к югу от Дольного Очага – сразу найдешь, если свернешь на запад с дороги, ведущей отсюда в город.\n\nКак будешь на лесопилке, поставь бочонок на какое-нибудь возвышение – например, на какой-нибудь ящик.\n\nГлавное открыть, а уж дальше термиты сами разберутся. А потом возвращайся ко мне – я придумаю, чем тебя порадовать.", progress = nil, completion = "Как только бочонок оказывается открыт, водопад термитов обрушивается из-под крышки.", rewards = "Вы получите:\n\n"},
[5903] = {title = "Чума на вашу лесопилку!", objective = "Возьмите пустую банку для термитов и отправляйтесь к большим термитникам в Восточных Чумных землях. Наберите 100 термитов Восточных Чумных земель и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Восточные Чумные земли.", description = "Я долгое время пытался бороться с Алым орденом в открытую, но без толку. Теперь я подумываю прибегнуть к некоторым партизанским методам – если не можешь одержать победу, хотя бы отрави врагу существование!\n\nЕсли хочешь мне помочь, слушай мой план: я собираюсь подбросить им на лесопилку самых зловредных термитов из всех существующих.\n\nЭти твари водятся в Проклятом лесу недалеко от Стратхольма – их колония пережила чуму и переродилась в новый, еще более живучий вид. Найди термитник и набери полную банку насекомых – уж мы натравим их на Алый орден!", progress = "Ну как, нашел термитники, Татаки? Их полно в Проклятых землях.", completion = "Замечательно, Татаки. Благодарю тебя. Их так много... честное слово, мне даже жаль бедняг из Алого Марша! Впрочем, лесопилка-то все равно не их, они ее нагло присвоили, так ведь?", rewards = "Вы получите:\n\n"},
[5904] = {title = "Чума на вашу лесопилку!", objective = "Найдите подходящее место в центре лесопилки Северного Кряжа в Западных Чумных землях и оставьте там бочонок термитов из Чумных земель.\n\nПрилагается предмет: \n", description = "Теперь у нас просто прорва термитов. Я надежно запрятал их вот в этот окованный железом бочонок. Отнеси его на лесопилку Северного Кряжа, это к югу от Дольного Очага – сразу найдешь, если свернешь на запад с дороги, ведущей отсюда в город.\n\nКак будешь на лесопилке, поставь бочонок на какое-нибудь возвышение – например, на какой-нибудь ящик.\n\nГлавное открыть, а уж дальше термиты сами разберутся. Едва ли Алый Марш сможет впредь использовать лесопилку!", progress = nil, completion = "Как только бочонок оказывается открыт, водопад термитов обрушивается из-под крышки.", rewards = "Вы получите:\n\n"},
[5921] = {title = "Лунная поляна", objective = "При помощи заклинания \"Телепортация: Лунная поляна\" перенеситесь в Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.", description = "На священной земле Лунной поляны рады всем друидам, невзирая на последние разногласия в Круге Кенария между верховным друидом Оленьим Шлемом и хранителем Ремулом – стражем Лунной поляны. Теперь, когда ты <встал/встала> на путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну. Пользуйся им, когда тебе нужно знание или уединение Лунной поляны.\n\nВот первый урок: отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд в Ночной гавани о том пути, по которому ты ныне следуешь. Удачи тебе, <юный друид/юная дева-друид>.", progress = nil, completion = "\"Да будет так, отец Кенарий. Да будет так.\"\n\nДендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы.\n\n\"Первое обличье, которое тебе следует освоить, – это обличье медведя. Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути – это твоя забота! И так отныне будет всегда.\"", rewards = "Вы получите:\n\n"},
[5922] = {title = "Лунная поляна", objective = "При помощи заклинания \"Телепортация: Лунная поляна\" перенеситесь в Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.", description = "На священной земле Лунной поляны рады всем друидам – и тауренам, и эльфам. Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погруженными в спячку друидами. Теперь, когда ты знаешь путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну. Пользуйся им всегда, когда тебе нужно знание или уединение Лунной поляны.\n\nВот первый урок – отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд в Ночной гавани о том пути, которым ты ныне следуешь. Удачи тебе, мой юный друид.", progress = nil, completion = "\"Да будет так, отец Кенарий. Да будет так.\"\n\nДендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы.\n\n\"Первое обличье, которое тебе следует освоить, – это обличье медведя. Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути – это твоя забота! И так отныне будет всегда.\"", rewards = "Вы получите:\n\n"},
[5923] = {title = "Зов Природы", objective = "Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнассе.", description = "Не уделишь мне минутку внимания?..\n\nДошло до меня, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдается, твое друидическое обучение выходит на следующую ступень, и он лично берется тебя обучать. Матренгил непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила.\n\nОн живет в анклаве Кенария в Дарнассе, на втором уровне дерева Фэндрала Оленьего Шлема.", progress = nil, completion = "Я рад, что ты нашел сюда дорогу, юный друид. Пришло тебе время вступить в большой мир.\n\nВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.\n\nГотовься!", rewards = "Вы получите:\n\n"},
[5924] = {title = "Отклик на призыв", objective = "Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнассе.", description = "Не уделишь мне минутку внимания?..\n\nДо моего сведения дошло, что Матренгил Медвежья Лапа желает пообщаться с вами. Похоже, ваше обучение искусству друида переходит на новую ступень, и он лично будет учить вас. Матренгил – правая рука самого верховного друида и один из самых мудрых и благородных друидов, каких только можно встретить в Тельдрассиле.\n\nОн обитает в анклаве Кенария в Дарнассе, на втором ярусе дерева Фэндрала Оленьего Шлема.", progress = nil, completion = "Я рад, что ты добралась сюда, мой юный друид. Пришло время тебе сделать большой шаг в огромный мир.\n\nКаждый из детей Кенария слышит внутри себя призыв служить природе. Животные и растения – наши друзья, а также и наша забота. Таков наш выбор – посвятить жизни сохранению равновесия во имя блага всего живого. Твой первый шаг в этот мир будет заключаться в изучении пути медведя, в изучении силы тела и силы сердца.\n\nПриготовься!", rewards = "Вы получите:\n\n"},
[5925] = {title = "Зов Природы", objective = "Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнассе.", description = "Не уделишь мне минутку внимания?..\n\nМне сообщили, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдается, твое друидическое обучение выходит на следующую ступень, и он лично берется тебя обучать. Матренгил – непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила.\n\nОн живет в анклаве Кенария в Дарнассе, на втором уровне дерева Фэндрала Оленьего Шлема.", progress = nil, completion = "Я рад, что ты нашел сюда дорогу, юный друид. Пришло тебе время вступить в большой мир.\n\nВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.\n\nГотовься!", rewards = "Вы получите:\n\n"},
[5926] = {title = "Зов Природы", objective = "Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин Громового Утеса.", description = "Извини, <друг/девушка>...\n\nДошло до меня, что Тюрак Рунический Тотем желает побеседовать с тобой. Сдается, твое друидическое обучение выходит на следующую ступень, и он лично берется тебя обучать. Тюрак – один из помощников самого верховного друида, он друид мудрый и терпеливый. Он сумеет хорошо обучить тебя.\n\nОн живет в Громовом Утесе, в главном шатре Круга Кенария на Вершине Старейшин.", progress = nil, completion = "Я рад, что ты нашел сюда дорогу, мой юный друид. Пришло тебе время вступить в большой мир.\n\nВ сердце каждого из детей Кенария звучит зов служения природе. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Твой первый шаг в этот мир станет шагом медведя – ты познаешь, что такое сила тела и духа.\n\nГотовься!", rewards = "Вы получите:\n\n"},
[5927] = {title = "Ответ на призыв", objective = "Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.", description = "Извини, <друг/подруга>…\n\nМне стало известно, что Тюрак Рунический Тотем желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься.\n\nТы найдешь его в Громовом Утесе, в главном шатре Круга Кенария на Вершине Старейшин.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[5928] = {title = "Услышанный зов", objective = "Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.", description = "Прости меня, друг мой…\n\nМне стало известно, что Тюрак Рунический Тотем желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься.\n\nТы найдешь его в Громовом Утесе, в главном шатре Круга Кенария на Вершине Старейшин.", progress = nil, completion = "Я рад, что тебе удалось добраться сюда, мой юный друид. Пришла тебе пора сделать очередной большой шаг на своем славном пути!\n\nВ каждом из детей Кенария живет стремление служить природе. Животные и растения – не только наши подопечные, но и наши друзья. Мы посвящаем свою жизнь сохранению равновесия не только ради себя, но и ради них. И первым твоим шагом в этот мир природы будет изучение медведя. Благодаря ему ты обретешь силу тела и духа.\n\nГотовься же!", rewards = "Вы получите:\n\n"},
[5929] = {title = "Дух Великого Медведя", objective = "Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне.", description = "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который дает начала понимания истинной природы медведя. Всем друидам в определенный момент требуется мудрость этого существа, и ты не исключение.\n\nОтправляйся же прямо сейчас к духу Великого Медведя и познай все, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты <усвоил/усвоила> его уроки.", progress = "Возвращайся только тогда, когда дух Великого Медведя отпустит тебя ко мне. Без его благословения твое обучение не может продолжаться.", completion = "Дендрит делает еще один неприметный жест над головой при вашем приближении. Его снова окутывает аура силы, и он еле заметно улыбается.\n\n\"Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи. Во взгляде твоем сила и осознанное стремление, хотя еще и не столь оформленное. Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя.\"", rewards = "Вы получите:\n\n"},
[5930] = {title = "Дух Великого Медведя", objective = "Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне.", description = "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который дает начала понимания истинной природы медведя. Всем друидам в определенный момент требуется мудрость этого существа, и ты не исключение.\n\nОтправляйся же прямо сейчас к духу Великого Медведя и познай все, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты <усвоил/усвоила> его уроки.", progress = "Возвращайся только тогда, когда дух Великого Медведя отпустит тебя ко мне. Без его благословения твое обучение не может продолжаться.", completion = "Дендрит делает еще один неприметный жест над головой при вашем приближении. Его снова окутывает аура силы, и он еле заметно улыбается.\n\n\"Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи. Во взгляде твоем сила и осознанное стремление, хотя еще и не столь оформленное. Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя.\"", rewards = "Вы получите:\n\n"},
[5931] = {title = "Возвращение в Дарнасс", objective = "Вернитесь в Дарнасс и поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария.", description = "Пришла пора нашим дорогам разойтись, дитя мое, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне. Матренгил Медвежья Лапа живет в истинном равновесии с природой, хотя и обитает опасно близко к тому месту, где это равновесие пошатнулось. Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия.\n\nСтупай же, дитя. Мы еще встретимся.", progress = nil, completion = "С возвращением, Миллит. Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя... немного сбивает с толку, но впечатляет. То же было и со мной.\n\nДух Великого Медведя был частью Азерота с самого его возникновения. Мы полагаемся на его мудрость и могущество в достижении наших целей. Теперь пришла пора тебе пройти первое свое испытание на этом пути. Слушай же...", rewards = "Вы получите:\n\n"},
[5932] = {title = "Возвращение в Громовой Утес", objective = "Вернитесь в Громовой Утес и поговорите с Тюраком Руническим Тотемом на Вершине Старейшин.", description = "Пришла пора нашим дорогам разойтись, дитя мое, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне. Хотя таурены недавно вступили на путь Кенария, Тюрак Рунический Тотем живет в равновесии с природой. Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия.\n\nСтупай же, дитя. Мы еще встретимся.", progress = nil, completion = "С возвращением, Ктулху. Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя... немного сбивает с толку, но впечатляет. То же было и со мной.\n\nДух Великого Медведя был частью Азерота с самого его возникновения. Мы, таурены, внимательно прислушиваемся к таким духам, и его цели ведут нас к процветанию. Теперь пришла пора тебе пройти первое свое испытание на этом пути. Слушай же...", rewards = "Вы получите:\n\n"},
[5941] = {title = "Возвращение к Хроми", objective = "Отнесите сумку с реликвиями Хроми в Андорал.", description = "Ты <собрал/собрала> многие реликвии, сохранившиеся со времен битвы при Дарроушире. Они взывают ко мне... умоляют изменить судьбу жителей Дарроушира.\n\nДа, звучит абсурдно, но Хроми, странный гном, живущий в Андорале, убеждает меня, что это возможно. Она говорит, ты можешь спасти Дарроушир! \n\nТы <должен/должна> отнести эти реликвии ей, она ждет тебя в разрушенной таверне в Андорале.", progress = "Я говорила с твоим другом Карлином. Он очень хорошо о тебе отзывался. Он верит, что именно ты сможешь изменить судьбу его деревни.\n\nТы принес мне собранные тобой реликвии?", completion = "Ага, вот они... Они послужат основой для мощного заклинания, которое сможет призвать духов Дарроушира.\n\nС помощью этих чар и толики удачи мы сможем спасти Джозефа Редпата!", rewards = "Вы получите:\n\n"},
[5942] = {title = "Спрятанные сокровища", objective = "Откройте сундук Джозефа ключом Джозефа.", description = "Папа велел отдать тебе этот ключ. Он открывает сундук, который стоит во дворе за домом.\n\nА еще он просил поблагодарить тебя. Не знаю, правда, за что – может, он знает, что ты <нашел/нашла> мою куклу?\n\nВот и ключ. Спасибо тебе, <имя>, ты <хороший/хорошая>!", progress = "Сундук стар и покрыт грязью.", completion = "Ключ со скрипом поворачивается в замке...", rewards = "Вы получите:\n\nОхранное кольцоТалисман Купола СветаЧеренок Погибели магов"},
[5943] = {title = "Караван Гизлтона", objective = "Проводите караван Гизлтона через Поле Маннорок. О награде поговорите со Смидом: его можно найти в Лагере Заржавня.", description = "Вид-то у тебя надежный, <раса>. Подзаработать хочешь? Мы с Корком думали, что на этом караване срубим кучу денег – но оказалось, что новое предприятие сулит гораздо больше неприятностей и опасностей, чем мы полагали.\n\nТам, впереди, находится Поле Маннорок... Обычно демоны не обращают на нас внимания, но на этот раз что-то изрядно напугало кодо. Я хорошо заплачу тебе за охрану каравана. Если нам удастся миновать Поле Маннорок без проблем, ты сможешь получить награду у Смида: это наш деловой партнер в Лагере Заржавня.", progress = nil, completion = "Я не уверен, что стоит платить такие деньги за защиту каравана Гизлтона. В конце концов, Корк и Риггер зарабатывают не больше одного золотого в неделю. Главное, чтобы они мне платили за кодо, а остальное – не мое дело.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСаперная лопатаТавро для кодоУкрашенное кольцо-щит\n\nВы также получите:\n\n"},
[5944] = {title = "Во сне", objective = "Вывести Таэлана Фордринга из Дольного Очага.", description = "Как же долго я был марионеткой верховного рыцаря. И что было проку сражаться с Алым орденом? Прошли десятки лет с мнимой смерти отца, но я жил лишь воспоминаниями о нем.\n\nМне снилось, что мы с отцом снова вместе. Он стоит рядом, с гордостью глядя, как меня принимают в орден. Мы бьемся с Плетью плечо к плечу, принося славу Альянсу и Лордерону.\n\nНе желаю больше жить во сне.\n\nОтведи меня к отцу.", progress = nil, completion = "Убийство моего сына не пройдет этим чудовищам даром. Пусть нас утешит мысль о возрождении Ордена.\n\nЯ встану во главе обновленного Ордена Серебряной Длани.\n\nВ знак своей признательности я могу отдать тебе лишь эти вещи, символы моего прошлого. Прими их, они служили мне верой и правдой долгие годы.\n\nДа встретимся мы в лучшие дни и вспомним давнее прошлое... трудные битвы... пробуждение от сна.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗнак ФордрингаИзысканная адамантовая кирасаМерцающий платиновый боевой молотНакидка ИзгнанниковПечать Фордринга\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[5961] = {title = "Защитник королевы банши", objective = "Поговорите с Натаносом Гнилостенем в Восточных Чумных землях. Он живет в Поместье Маррисов.", description = "Приятно видеть, что в наши ряды вступают закаленные бойцы. С каждым днем нас становится все больше. Ты <готов/готова> испытать собственную решимость, <класс>?\n\nПервый среди моих защитников – Натанос по прозвищу Гнилостень. Немногие могут превзойти его в преданности и доблести.\n\nОтыщи его в Восточных Чумных землях. Он живет в Поместье Маррисов и порой бродит по окружающим его пустошам, истребляя всякую мразь из воинств Плети и Альянса.", progress = nil, completion = "Темная Госпожа считает тебя достойным встретиться с ее защитником. Ты ведь прислан кормить моих псов, да? Иначе зачем ты меня тревожишь?", rewards = "Вы получите:\n\n"},
[5981] = {title = "Истребление великанов", objective = "По просьбе Риверна Холодного Ветра убейте 4 великанов и 4 оберегателей ледяного молота.", description = "Около четырех тысяч лет назад Тиранда Шелест Ветра спасла жизнь королевы ледопардов, вырвав ее из рук жестоких великанов. С тех самых пор ледопарды стали союзниками ночных эльфов. \n\nТе самые великаны, что когда-то представляли опасность для ледопардов, и поныне живут не очень далеко отсюда. Их называют кланом Ледяного Молота, и они обосновались в большой долине к югу отсюда.\n\nДокажите вашу лояльность – убейте этих великанов во имя королевы ледопардов, Ши-Ротам!После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil},
[6001] = {title = "Тело и дух", objective = "Посыпьте лунной пылью Кенария камень лунного совуха в Аубердине, чтобы вызвать Лунокогтя. Победите Лунокогтя, чтобы получить силу его тела и духа.\n\nЗатем поговорите с Матренгилом Медвежьей Лапой в Дарнассе.", description = "Прямо к востоку от Аубердина находятся пещеры лунных совухов. В той, что ближе всего к Аубердину, находится камень лунного совуха. Лунокоготь, страж камня, появится перед тобой только тогда, когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, которой ты, как <один/одна> из друидов-медведей, должен овладеть.\n\nТы $Gзаслужил:заслужила; право пользоваться этой лунной пылью Кенария, <имя>... теперь покажи мне, что также <заслужил/заслужила> право обладать силами тела и духа, необходимыми друиду!", progress = nil, completion = "Это твой первый большой шаг на пути к великим свершениям, Лесничий. Я чую учение Духа Великого Медведя в тебе и вижу, что ты перенял мощь Лунокогтя.\n\nБолее ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!", rewards = "Следующее заклинание будет наложено на вас:\n\nОблик медведя\n\nВы получите:\n\n"},
[6002] = {title = "Тело и дух", objective = "Посыпьте лунной пылью Кенария Камень Лунного совуха, что между Мулгором и Степями, чтобы вызвать Лунокогтя. Теперь вам надо побороть Лунокогтя, чтобы заслужить его силу духа и тела.\n\nКогда выполните это, поговорите с Тюраком Руническим Тотемом в Громовом Утесе.", description = "Прямо к западу от Таурахо в Степях – там, где они переходят в Мулгор – находится камень Лунного совуха. Лунные совухи – звери особые, в здешних краях они не живут. Лунокоготь, страж камня, появится перед тобой только когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, который ты <должен/должна> овладеть, как <один/одна> из друидов-медведей.\n\nТы <заслужил/заслужила> право пользоваться этой лунной пылью Кенария, <имя>... теперь покажи мне, что также <заслужил/заслужила> право обладать силой тела и духа, необходимыми друиду!", progress = "Пока ты не ответишь на вставший перед тобой вызов, ты не сумеешь полностью познать силу духа и тела. До тех пор я ничем не смогу тебе помочь.", completion = "Это твой первый большой шаг на пути к великим свершениям, Ктулху. Я чую учение Духа Великого Медведя в тебе, и вижу, что ты перенял мощь Лунокогтя.\n\nБолее ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!", rewards = "Следующее заклинание будет наложено на вас:\n\nОблик медведя\n\nВы получите:\n\n"},
[6004] = {title = "Неоконченное дело", objective = "Убейте 2 медиков, 2 охотников, 2 волхвов и 2 рыцарей Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.", description = "У меня была разведывательная миссия – немного сократить число противников и оценить укрепления Дольного Очага. Некоторые сторонники Альянса считают, что этот город имеет не только историческое значение. Не мое дело решать, что важнее, но выполнять задание я не в силах, пока не отдохну.\n\nЕсли хочешь, я неплохо заплачу тебе за помощь. Начти на юге, возле лагеря Алого Марша, у небольшого бастиона. Если ты окажешься достаточно <силен/сильна>, я попрошу тебя помочь мне выполнить основную часть задания.", progress = "Как успехи? Враг оказался сильнее, чем ты думал? Надеюсь, что нет. Мое следующее задание потребует гораздо больше сил, чем это.", completion = "Молодец, Томпсон. Как тебе удалось так быстро с ними разобраться? Спасибо. \n\nМне пока не встречался никто, кто одобрил бы Алый орден или его методы. Я верю в Свет, также как и все жители Штормграда, но эти фанатики наглядно доказали, что стремятся лишь убивать всех, кроме своих сторонников... даже ни в чем не повинных людей.", rewards = "Вы получите:\n\n"},
[6021] = {title = "Зельдарр Изгой", objective = "Принесите голову Зельдарра Управляющему Алену в Часовню Последней Надежды.", description = "Кто бы мог подумать, после всех наших заключений в Чумных землях нам не хватало только воров! И не просто воров, а троллей!\n\nИ не просто воров-троллей, а мертвых воров-троллей!\n\nИх главарь – огромный мертвый тролль по имени Зельдарр Изгой. Они являются по ночам, крадут тела из ямы и тащат их в свое мерзкое логово. Оно зовется Крипта, это к западу отсюда.\n\nОтправляйся туда, <имя>, и разберись с Зельдарром. Я сыт по горло его проделками!", progress = "Тебе удалось разыскать логово Зельдарра, Томпсон? Ты нашел на него управу?", completion = "Поделом ему! Надеюсь, и остальным их его шайки тоже досталось!", rewards = "Вы получите:\n\n"},
[6022] = {title = "Преднамеренное убийство", objective = "Отправляйтесь на восток в Перекресток Корина и убейте несколько населяющих его созданий Плети. Соберите 7 кусков живой гнили менее, чем за 10 минут. С помощью ступки и пестика превратите живую гниль в сгущенную гниль.", description = "Будь <готов/готова> на умышленное убийство, если хочешь со мной работать.\n\nДля начала покорми моих псов.\n\nВозьми эту ступку и пестик и отправляйся в Перекресток Корина. Там у тебя будет обширный выбор тварей Плети – убей тех, какие больше приглянутся. Из их свежих туш добудь живую гниль, растолки в ступке и дай отстояться, чтобы она сгустилась. Принесешь сгущенную гниль мне.\n\nИ слушай меня, недотепа, живая гниль – продукт скоропортящийся! Поэтому работать придется быстро.", progress = "Что нюни распустил? Если эта работенка не по тебе, отправляйся обратно к Темной Госпоже и сообщи ей, как дурно я с тобой обошелся.\n\nПроваливай!", completion = "Прискорбно, прискорбно... Я-то надеялся скормить моим псам тебя...\n\n*Натанос вздыхает*\n\nЛадно, по-крайней мере им есть, что погрызть.", rewards = "Вы получите:\n\n"},
[6023] = {title = "Неоконченное дело", objective = "Убейте охотника Радли и кавалериста Даргена и вернитесь к Кристе Чернотени в Западные Чумные земли.", description = "Подлинная суть моей миссии состояла в том, чтобы подорвать мощь внешних отрядов Алого ордена, а потом проникнуть внутрь Дольного Очага и оценить их основные силы. Я пока не в форме, но, может быть, могу снова попросить о помощи? Судя по собранным сведениям, за пределами города костяк сил ордена составляют двое: охотник Радли и кавалерист Дарген. Убей их, и дело стронется с мертвой точки. Они должны быть неподалеку от прохода, рядом с городом.", progress = "Тебе уже удалось их найти, Яробород? Если мы избавимся от этих двоих, я смогу пробраться в Дольный Очаг, посмотреть, что к чему. Без твоей помощи мне не обойтись. Пожалуйста, найди мне Рэдли и Даргена.", completion = "Спасибо, Томпсон. Я и не рассчитывала на такую помощь. Кажется, самый воздух этих земель лишает меня воли. Я очень устала, и чем дольше здесь нахожусь, тем мне хуже.\n\nНе представляю, как я проберусь в Дольный Очаг, чтобы выяснить размер армии Алого ордена.\n\nНо это другой разговор. Погоди, возьми это... в уплату. Спасибо еще раз.", rewards = "Вы получите:\n\n"},
[6024] = {title = "Мольба Хамейи", objective = "Убейте секретного агента Хамейю. С помощью ключа извлеките сокровище из кучи грязи за Криптой.", description = "Убей меня. Пока не поздно!\n\nМеня зовут Хамейя. Мы с собратьями путешествовали через Зул'Машар и, видимо, съели что-то не то. Мы заражены!\n\nЯ слышу, как лич нашептывает мне, что я должен отправиться в Зул'Машар и постараться распространить заразу. Я не могу противиться его словам, поэтому написал это послание прежде, чем разум окончательно оставит меня.\n\nЯ закопал сундук с сокровищами рядом повозкой, оставленной за этим склепом, но его можно открыть только моим ключом. Ключ у меня.\n\nЧтобы добыть сокровище, убей меня. Пока не поздно!", progress = "Сундук надежно заперт.", completion = "Сундук Хамейи открыт!", rewards = "Вы получите:\n\nРубило ХамейиПлащ Гамеи"},
[6025] = {title = "Неоконченное дело", objective = "Проберитесь в Дольный Очаг и найдите возвышенность, с которой открывается вид на весь город. Оцените силы Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.", description = "Что? Правда? Ты <готов/готова> меня выслушать? Но ты и так очень много для меня <сделал/сделала>, <имя>. Я не могу просить тебя отправиться в Дольный Очаг.\n\nТы серьезно? Дольный Очаг гораздо опаснее прохода... Я не смогу защитить тебя или даже рассказать, что тебя может ждать там.\n\nЕсли ты в самом деле хочешь мне помочь, то проникни в город, поднимись на гору и осмотри его с высоты. Оцени количество войск и доложи мне. Но будь <осторожен/осторожна>...", progress = "Это опасное задание, Лолкка. Я завидую твоей храбрости.", completion = "Молодец, Томпсон! Спасибо!\n\nЯ вернусь к Эллингу... точнее, в Штормград как только смогу. Возьми эту скромную сумму, должна же я тебя отблагодарить. Твой народ может тобой гордиться, Томпсон. Спасибо и удачи.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6026] = {title = "Работу пополам", objective = "Принесите 2 ториевых слитка, 1 золотой жезл, 8 высоковзрывных бомб и 8 нестабильных пусковых устройств Дымку ЛаРу.\n\nДля этого вам придется найти кузнеца и инженера.", description = "Серебряный Рассвет поручил старине Дымку кой-какую работенку. А я что, я токмо рад – денежка-то никогда не лишняя!\n\nОднако силы мои уже не те, и я бы, пожалуй, воспользовался твоей помощью, если ты тоже не прочь подзаработать. Я пойду в Проклятый лес и отмечу знаком строения, которые предстоит взорвать, а ты пока добудешь взрывчатки. Договорились? Жди меня на этом самом месте, как соберешь все необходимое. Ну, что скажешь?", progress = "Верь старине Дымку, |3-6(нежить), дело стоящее. Серебряный Рассвет за копейку не удавится.", completion = "Могу заплатить половину сейчас и половину по выполнению работы.", rewards = "Вы получите:\n\n"},
[6027] = {title = "Книга Древних", objective = "Отыщите Книгу Древних и принесите ее Азору Альдаморту в башню Этель-Ретор.", description = "Послушай меня, <имя>: я вручаю тебе Самоцвет Змеи. Его нужно поместить на руку Статуи Змеи, что на острове Раназьяр: это небольшой островок к северо-западу отсюда. Когда сделаешь это, явится тот, кто хранит Книгу Древних. В книге можно найти вековые тайны нагов. Принеси мне эту книгу: вместе мы сумеем узнать многое о наших чешуйчатых врагах!", progress = "Ах, Эфром, как я рад тебя видеть! Ну как, есть при тебе Книга Древних?", completion = "Утраченная Книга Древних! Я прослежу за тем, чтобы она была передана высокому совету. Сегодня ты свершил великое деяние; прими же благодарность за этот подвиг!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШелкоструйные манжетыДуговые наплечники\n\nВы также получите:\n\n"},
[6028] = {title = "Донесение из Круговзора", objective = "Доставьте донесение из Круговзора офицеру Чистосердой из ордена Серебряного Рассвета в Лагерь Промозглого Ветра в Западных Чумных землях.", description = "Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему. Я здесь как представитель интересов Серебряного Рассвета по управлению Круговзором. Я должен доложить обстановку офицеру Чистосердой в Лагерь Промозглого Ветра, расположенный на южной окраине Западных Чумных земель.\n\nЕсли мне это удастся, это будет прекрасный повод представить тебя моей начальнице и, возможно, устроить тебе персональное задание", progress = "Приветствую, |3-6(Жрец). От имени Серебряного Рассвета, я предлагаю вам безопасность и убежище, пока вы находитесь на территории Лагеря Промозглого Ветра. Так же я могла бы подыскать для вас подходящее дело...", completion = "Грегор крайне находчив. Он некоторое время имел дело с Картелем Хитрая Шестеренка, и стал экспертом по \"искусству\" переговоров с гоблинами. Хотя верно, что расположение гоблинов к вам напрямую зависит от толщины вашего кошелька, они также признают и уважают роль дипломатии. Если, так или иначе, она обеспечивает им повторные заказы...\n\nВо всяком случае, Серебряный Рассвет выражает вам признательность за проделанную работу. Примите это вместе с нашей благодарностью.", rewards = "Вы получите:\n\n"},
[6029] = {title = "Донесение из Круговзора", objective = "Доставьте донесение из Круговзора офицеру Гарушу из ордена Серебряного Рассвета в Бастион в Западных Чумных землях.", description = "Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему. Я здесь как представитель интересов Серебряного Рассвета в администрации Круговзора. Я должен доложить обстановку офицеру Гарушу в Бастион, расположенный на восточных окраинах Западных Чумных земель, к востоку от Тирисфальских лесов.\n\nЕсли я могу тебя об этом просить... это будет прекрасный повод представить тебя моему начальнику. И, возможно, он найдет тебе дело!", progress = "Приветствую, |3-6(Воин). От имени Серебряного Рассвета, я предлагаю вам безопасность и убежище, пока вы находитесь на территории Бастиона. Я мог бы также предложить хорошую драку за стоящие того цели!", completion = "Грегор крайне находчив. Он некоторое время имел дело с Картелем Хитрая Шестеренка, и стал экспертом по \"искусству\" переговоров с гоблинами. Хотя верно, что расположение гоблинов к вам напрямую зависит от толщины вашего кошелька, они также признают и уважают роль дипломатии. Если, так или иначе, она обеспечивает им повторные заказы...\n\nВо всяком случае, Серебряный Рассвет выражает вам признательность за проделанную работу. Примите это вместе с нашей благодарностью.", rewards = "Вы получите:\n\n"},
[6030] = {title = "Герцог Николас Зверенхофф.", objective = "Доставьте книгу \"Исследования речи духов\" Герцогу Николасу Зверенхоффу в Часовню Последней Надежды в Восточных Чумных землях.", description = "Отшельник-медиум по имени Умбранс, обитающий в этих краях, обеспечил Серебряный Рассвет настоящим шедевром литературы... Это самое большое собрание слухов и сплетен, которое только было когда-либо издано.\n\nОдин из наиболее уважаемых лидеров Рассвета, герцог Николас Зверенхофф, является блестящим лингвистом. Ты не <мог/могла> бы отнести ему эту книгу – не бесплатно, разумеется! Сейчас его можно найти в Часовне Последней Надежды, в восточной части Восточных Чумных земель.", progress = "Да пребудет с вами Свет, в эти темные времена, |3-6(Охотник). Что привело вас сюда, в этот последний оплот надежды среди тьмы и отчаяния?", completion = "Это... Вы принесли мне весьма особенную книгу. Я хотел бы сказать Вам, что \"особенная\" в этом случае означает \"уникальная и весьма познавательная\", но так ли это мы еще проверим.\n\nOoooooo? Кто это выдумал? \n\nХорошо, я узнал об этом Умбрансе, о котором говорил Грегор, и это ваша заслуга. Я приложу все усилия, чтобы расшифровать эту книгу. Что касается Вас... Серебряный Рассвет вам бесконечно благодарен. Возможно нам еще потребуются ваши услуги, пока вы здесь.", rewards = "Вы получите:\n\n"},
[6031] = {title = "Рунная ткань", objective = "Принесите 30 отрезов рунной ткани Мелиошу в крепость Древобрюхов.", description = "Мы, древобрюхи, самодостаточны. Мы не любим чужаков. Для нас такая жизнь хороша, но вот для торговли – нет.\n\nНедавно к нам в крепость Древобрюхов забрела редкая гостья – одна ночная эльфийка. У нее был плащ из рунной ткани. Рунная ткань у нас вещь редкая, но плащ был такой красивый, что мои сородичи пожелали, чтобы я нашил им побольше одежды из рунной ткани.\n\nТы принесешь мне рунной ткани? А за это я кое-что дам тебе.", progress = "Ты принес рунную ткань? Мой народ сгорает от нетерпения получить одежду из рунной ткани!", completion = "А, принес. Какая же красивая ткань!\n\nСпасибо тебе, Трансмастер. Ты настоящий друг. Пожалуйста, прими в благодарность.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТенекожаный наплечРукавицы из камнестали\n\nВы также получите:\n\n"},
[6032] = {title = "Священная ткань", objective = "Принесите 2 отреза луноткани Мелиошу в Крепость Древобрюхов.", description = "Хотя древобрюхам но нраву ощущение от рунной ткани, она для нас не священна. А вот луноткань – священна.\n\nПринеси мне немного этой священной ткани, и я научу тебя некоторым портняжным секретам.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nСапоги из луноткани\n\nСледующее заклинание будет наложено на вас:\n\nСапоги из луноткани\n\nВы также получите:\n\n"},
[6041] = {title = "Дымок над водою", objective = "Отправляйтесь в Проклятый лес, к северо-западу от часовни Светлых надежд. Уничтожьте 8 строений Плети, отмеченных знаком взрыва, поместив особый состав Дымка внутрь строения. Дымок отметил зиккураты и бойни.\n\nРазместив бомбу внутри строения, немедленно выбирайтесь наружу и любуйтесь делом рук своих с безопасного расстояния. \n\nАх да, вот еще что, особый состав Дымка – вещество весьма нестабильное.", description = "Пока ты <занимался/занималась> заготовкой припасов, мои люди отметили некоторые сооружения Плети, которые должны быть уничтожены.\n\nПлан действий таков: я дам тебе 10 брусков моего особого состава, ты отправишься в Проклятый лес и оставишь их в строениях Плети, помеченных знаком.\n\n*Дымок щелкает пальцами*\n\nБабах! Все очень просто!", progress = nil, completion = "Загар тебе очень идет. Я всегда говорил, игра с огнем весьма полезна для цвета лица!\n\n*Дымок хохочет во все горло*\n\nНу да ладно, вот обещанная награда. И кой-чего сверх обещанного, чтобы боль от ожогов не казалась столь жестокой!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГремучее ружье СмокиДымный огнестрел\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\nВлажная салфеткаПелерина Дымка"},
[6042] = {title = "Мелочи нежизни", objective = "Истребите 20 пагубных нетопырей и 10 чудовищных чумных нетопырей. После возвращайтесь к Натаносу Гнилостеню.", description = "С фермы и шагу нельзя ступить, чтобы не напороться на одну из этих проклятых летучих мышей! Я бы, знаешь ли, предпочел заниматься истреблением Плети, не отвлекаясь на всякую мелкую шушеру. Мое время слишком дорого, чтобы тратить его на охоту за мышами. А вот твое – нет.\n\nЧто ты там бормочешь? Обучение? Вот тебе обучение – пойди поучись ловле мышей! И не смей показываться мне на глаза, пока не перебьешь несколько десятков этих мерзких тварей.", progress = "Хватит ныть! Я мог бы заставить тебя собирать мышиный помет, но я сегодня добрый!\n\n*Натаноса явно осенила какая-то идея*\n\nЭй! А ну погоди! Куда побежал!", completion = "Вот можешь же, если захочешь! Главное, правильно подобрать аргументы.", rewards = "Вы получите:\n\n"},
[6061] = {title = "Приручение зверя", objective = "Приручите взрослого равнинного долгонога при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта.", description = "Для нас, тауренов, важно следовать традициям предков, сражаясь с могучими зверями. Одолевая их, мы вбираем в себя их дух, делаясь все ближе Матери-Земле.\n\nПриручив же зверя и сделав его своим помощником, мы делаем еще один шаг навстречу природе. В конце концов ты сможешь выбрать зверя себе по вкусу. Но сначала всему приходится учиться, и этому тоже. Для начала возьми этот хлыст приручения; ступай, приручи равнинного долгонога.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[6062] = {title = "Приручение зверя", objective = "Приручите лютого пятнистого вепря с помощью хлыста приручения. Потренируйтесь, потом верните хлыст приручения Тотару в Колючем Холме.", description = "Умение подчинять природу своей воле – великое искусство. Ты <охотник/охотница>, и тебе следует научиться использовать силу и мощь, свойственную любому избранному тобой существу.\n\nОбрести власть над животным – дело не простое, тут требуется решимость.\n\nДля начала возьми вот этот хлыст приручения и укроти с его помощью лютого пятнистого вепря. Они водятся поблизости от Колючего Холма. Попробуй поучаствовать в битве вместе с вепрем, а потом возвращайся ко мне.", progress = "Удачи тебе, юный охотник!", completion = "Молодец, Древосек! Думаю, тебе уже можно поручить задачу посложнее...", rewards = "Вы получите:\n\n"},
[6063] = {title = "Приручение зверя", objective = "С помощью хлыста приручения приручите чащобного тенетника. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.", description = "Охотнику важно помнить о том, какая перед ним стоит ответственность. Природа – не та сила, которую можно подчинить своим прихотям. Ее следует почитать как нечто, без чего само твое существование было бы невозможным.\n\n<имя>, ты <должен/должна> доказать, что понимаешь это, прежде чем получишь способность превращать любое животное в своего верного спутника.\n\nПервым делом возьми этот хлыст приручения. С его помощью ты сумеешь приручить чащобного тенетника. Приручи его и поупражняйся в своем охотничьем искусстве.", progress = "Ты быстро обучаешься, Миззрим. Однажды ты станешь великим охотником.", completion = "Отлично, Миззрим! Ты и правда быстро обучаешься.", rewards = "Вы получите:\n\n"},
[6064] = {title = "Приручение зверя", objective = "Приручите большого скального вепря с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.", description = "Привет, <парень/подруга>! Стало быть, хочешь узнать, как завести себе питомца?\n\nЧто же, начнем. Когда доходит до охоты, нет ничего важнее снаряжения, но о моем новом шрапнельном самостреле мы поболтаем в другой раз. А пока займемся тем, что, так интересует тебя в данный момент – питомцем!\n\nТебе лучше всего попытаться приручить нескольких существ и посмотреть, кто тебе больше по сердцу. Итак, найди большого скального вепря, а затем используй хлыст приручения, чтобы приручить его.", progress = "Тебе сначала надо попробовать приручить разных зверей – тогда ты сможешь понять, кто тебе больше по душе.", completion = "Знаю-знаю, тебе невтерпеж узнать, кого надо будет приручить следующим, да?", rewards = "Вы получите:\n\n"},
[6065] = {title = "Путь охотника", objective = "Поговорите с Йо Колкой Гривой в Деревне Кровавого Копыта.", description = "Привет тебе, <юный охотник/юная охотница>. Ты кажешься мне достаточно <опытным/опытной>, чтобы научиться обращаться с животным и обрести верного друга.\n\nТебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[6066] = {title = "Путь охотника", objective = "Поговорите с Йо Колкой Гривой в Деревне Кровавого Копыта.", description = "Привет тебе, <юный охотник/юная охотница>. Ты кажешься мне достаточно <опытным/опытной>, чтобы научиться обращаться с животным и обрести верного друга.\n\nТебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[6067] = {title = "Путь охотника", objective = "Поговорите с Йо Колкой Гривой в Деревне Кровавого Копыта.", description = "Привет тебе, <юный охотник/юная охотница>. Ты кажешься мне достаточно <опытным/опытной>, чтобы научиться обращаться с животным и обрести верного друга.\n\nТебе надо повидаться с Йо Колкой Гривой в Деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[6068] = {title = "Путь охотника", objective = "Поговорите с Тотаром в Колючем Холме.", description = "Привет тебе, <юный охотник/юная охотница>! Сдается мне, что у тебя уже достаточно опыта, чтобы подчинить себе зверя и сделать его своим спутником.\n\nНайди в Колючем Холме Тотара. Он научит тебя, как обзавестись собственным питомцем.", progress = nil, completion = "Да, тебе, пожалуй, пора учиться дальше...", rewards = "Вы получите:\n\n"},
[6069] = {title = "Путь охотника", objective = "Поговорите с Тотаром в Колючем Холме.", description = "Привет тебе, <юный охотник/юная охотница>! Сдается мне, что у тебя уже достаточно опыта, чтобы подчинить себе зверя и сделать его своим спутником.\n\nНайди в Колючем Холме Тотара. Он научит тебя, как обзавестись собственным питомцем.", progress = nil, completion = "Да, пожалуй, ты уже готов к обучению...", rewards = "Вы получите:\n\n"},
[6070] = {title = "Путь охотника", objective = "Поговорите с Тотаром в Колючем Холме.", description = "Привет тебе, <юный охотник/юная охотница>! Сдается мне, что у тебя уже достаточно опыта, чтобы подчинить себе зверя и сделать его своим спутником.\n\nНайди в Колючем Холме Тотара. Он научит тебя, как обзавестись собственным питомцем.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[6071] = {title = "Путь Охотника", objective = "Поговорите в Доланааре с Дазаларом.", description = "Привет тебе, <юный охотник/юная охотница>. Ты кажешься мне достаточно <опытным/опытной>, чтобы научиться обращаться с животным и обрести верного друга.\n\nТебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.", progress = nil, completion = "Да, охотник пришла пора.", rewards = "Вы получите:\n\n"},
[6072] = {title = "Путь Охотника", objective = "Поговорите в Доланааре с Дазаларом.", description = "Привет тебе, <юный охотник/юная охотница>. Ты кажешься мне достаточно <опытным/опытной>, чтобы научиться обращаться с животным и обрести верного друга.\n\nТебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[6073] = {title = "Путь Охотника", objective = "Поговорите в Доланааре с Дазаларом.", description = "Привет тебе, <юный охотник/юная охотница>. Ты кажешься мне достаточно <опытным/опытной>, чтобы научиться обращаться с животным и обрести верного друга.\n\nТебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.", progress = nil, completion = "Да, пора обучить тебя...", rewards = "Вы получите:\n\n"},
[6074] = {title = "Путь охотника", objective = "Поговорите с Грифом Диким Сердцем в Караносе.", description = "Привет тебе, <юный охотник/юная охотница>. Ты кажешься мне достаточно <опытным/опытной>, чтобы научиться обращаться с животным и обрести верного друга.\n\nТебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника.", progress = nil, completion = "Да, думаю, пора пришла...", rewards = "Вы получите:\n\n"},
[6075] = {title = "Путь охотника", objective = "Поговорите с Грифом Диким Сердцем в Караносе.", description = "Привет тебе, <юный охотник/юная охотница>. Ты кажешься мне достаточно <опытным/опытной>, чтобы научиться обращаться с животным и обрести верного друга.\n\nТебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника.", progress = nil, completion = "Да, думаю, пора тебя обучить...", rewards = "Вы получите:\n\n"},
[6076] = {title = "Путь охотника", objective = "Поговорите с Грифом Диким Сердцем в Караносе.", description = "Привет тебе, <юный охотник/юная охотница>. Ты кажешься мне достаточно <опытным/опытной>, чтобы научиться обращаться с животным и обрести верного друга.\n\nТебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[6081] = {title = "Обучение зверя", objective = "Поговорите с Ормаком Лютострелом в Оргриммаре.", description = "Теперь ты умеешь приручать зверей, но тебе еще осталось узнать, как их обучать.\n\nСтупай в Оргриммар. Там тебе нужно будет поговорить с одним из самых прославленных наших охотников, Ормаком Лютострелом. Он покажет тебе, как обучать своего нового питомца. Ты найдешь Ормака возле Зала Отважных.\n\nУдачи, <имя>!", progress = nil, completion = "А, молодой охотник! Да, я поделюсь с тобой навыками и знаниями, необходимыми для того, чтобы обучать и дрессировать питомца. Ты сможешь не только обучать своего питомца новым способностям, но также научишься кормить его и даже оживлять, если он погибнет в бою.\n\nА теперь ступай. Мы поговорим позднее.", rewards = "Вы изучите:\n\nУрок дрессировки\n\nСледующее заклинание будет наложено на вас:\n\nДрессировка\n\nВы также получите:\n\n"},
[6082] = {title = "Приручение зверя", objective = "Приручите бронескорпа с помощью хлыста приручения. Потренируйтесь, потом вернитесь к Тотару в Колючем Холме.", description = "Последнее животное, которое тебе придется приручить, – это бронескорп. Тебе придется частенько с ними сражаться. Но ты, будучи $Gохотником:охотницей;, <должен/должна> уметь повелевать и такими существами.\n\nКогда ты вернешься, я обучу тебя всему, что потребуется, чтобы приручить животное по твоему выбору. Выбранный тобой зверь будет набираться опыта и становиться сильнее. А еще я покажу тебе, как призывать его и отпускать на волю, когда в нем не будет надобности.", progress = "Ну что, удалось тебе укротить бронескорпида?", completion = "Теперь, Древосек, ты знаешь все, чему я мог тебя обучить. Пора тебе воспользоваться полученными знаниями и выбрать себе собственного питомца.\n\nВот, Древосек, я даю тебе способность приручать зверя, а также призывать и отсылать его по собственной воле. Можешь гордиться своим новым умением, ты заслужил эти знания!", rewards = "Вы изучите:\n\nУрок приручения\n\nСледующее заклинание будет наложено на вас:\n\nПриручение зверя\n\nВы также получите:\n\n"},
[6083] = {title = "Приручение зверя", objective = "Приручите приливного краба с помощью хлыста приручения. Потренируйтесь, потом верните хлыст приручения Тотару в Колючем Холме.", description = "Разумеется, <имя>, питомец дает тебе большое преимущество в бою. Подчиняя себе живое существо, ты добавляешь его силу к своей. Он становится как бы продолжением тебя.\n\nСледующее задание потребует от тебя обратиться от земли к морю. Приливный краб, которого тебе нужно будет приручить, обитает в прибрежных водах, близ деревни Сен'джин и островов Эха. Воспользуйся хлыстом приручения, чтобы усмирить зверя, а потом потренируй свои навыки.", progress = "Тебе нужно тренироваться, чтобы набраться опыта в укрощении питомцев. Удалось ли тебе приручить приливного краба?", completion = "Ты быстро учишься, Древосек! Молодец.", rewards = "Вы получите:\n\n"},
[6084] = {title = "Приручение зверя", objective = "Приручите снежного леопарда с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.", description = "Эти скальные вепри такие здоровенные – может, тебе хочется кого поизящнее? Ладушки, у меня есть кое-кто на примете. К югу и востоку отсюда ты найдешь больших белых кошек, называемых снежными леопардами. Они чем-то напоминают элегантную винтовку – такие же красивые и такие же смертоносные. Они гораздо проворнее и быстрее укрощенного тобой вепря.\n\nНа, держи этот хлыст приручения. Посмотрим, придется ли тебе по душе снежный леопард.", progress = "Ну, как тебе снежный леопард, Бронгард?", completion = "Когда я увижу, что ты достаточно подготовлен, я научу тебя приручать любого понравившегося тебя зверя.", rewards = "Вы получите:\n\n"},
[6085] = {title = "Приручение зверя", objective = "Приручите медведя-ледолапа с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.", description = "Возможно, тебе понравится животное, обладающее чем-то большим, чем просто грубая сила. Медведи-ледолапы – замечательные спутники для охотников-новичков, вроде тебя. Их можно найти к востоку от Караноса. Вот тебе хлыст приручения, попытайся приручить это животное и посмотри, как он тебе придется!\n\nКогда ты вернешься, я научу тебя, как приручать животных. Твой питомец будет вместе с тобой разделять опасности и получать опыт. Я также научу тебя призывать и отпускать животное по своему желанию.", progress = "Ну, удалось приручить медведя-ледолапа?", completion = "Отлично, Бронгард. Теперь научу тебя приручать зверя, а также призывать и отпускать его по желанию.\n\nНайди себе славного верного питомца – и доброй охоты!", rewards = "Вы изучите:\n\nУрок приручения\n\nСледующее заклинание будет наложено на вас:\n\nПриручение зверя\n\nВы также получите:\n\n"},
[6086] = {title = "Обучение зверя", objective = "Поговорите в с Белией Громовым Гранитом в Стальгорне.", description = "<имя>, ты умеешь приручать зверей, но ведь надо еще научиться тренировать своего питомца.\n\nИди в Палаты Войны в Стальгорне и поговори там с одним из наших лучших специлистов в обучении зверей – Белией Громовым Гранитом. Она покажет тебе, как обучать питомца. Так что отправляйся в путь, <парень/подруга>!\n\nБелия по характеру дружелюбна, у тебя не будет проблем в нахождении с ней общего языка. Удачи, <имя>.", progress = nil, completion = "Новенький? Вижу, быть тебе великим охотником.\n\nДа, я могу поделиться с тобой знаниями, необходимыми для обучения и управления питомцем. Ты сможешь не только обучить своего питомца новым способностям, но и научишься его кормить и даже воскрешать, если он погибнет в бою.\n\nПомни, лучший способ подружиться с питомцем – это обращаться с ним уважительно и хорошо за ним ухаживать. Тогда твой питомец будет безгранично предан тебе.", rewards = "Вы изучите:\n\nУрок дрессировки\n\nСледующее заклинание будет наложено на вас:\n\nДрессировка\n\nВы также получите:\n\n"},
[6087] = {title = "Приручение зверя", objective = "Приручите охотника прерий при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта.", description = "Твой дух полон огня, охотник, и ты с радостью встречаешь новые испытания.\n\nСледующее задание – приручить волка, известного как охотник прерий. Он быстр и бесстрашен, и чтобы сделать его своим спутником, тебе придется воспитать в себе эти качества.\n\nВо время боя ты поймешь, как вы будете сражаться бок о бок. Ведь вы с питомцем должны действовать очень слаженно, как единый организм.\n\nВот хлыст приручения, <имя>. Подчини себе охотника прерий, потренируйся.", progress = "Удалось найти охотника прерий?", completion = "Да... Мать-Земля полагает, что ты готов к следующему уроку.", rewards = "Вы получите:\n\n"},
[6088] = {title = "Приручение зверя", objective = "Приручите перепелятника при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта.", description = "Последним твоим заданием станет приручение жителя неба. Перепелятник – непростой противник, но зато отличный союзник – атакует он внезапно и пугает врагов.\n\nПо воле Матери-Земли, по возвращении с победой, я наделю тебя искусством приручать любого зверя и делать его своим спутником; твоему питомцу придется встретиться с теми же испытаниями, что и тебе, и вместе с тобой набираться опыта. Я покажу тебе, как подзывать и отсылать его по собственной воле.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nУрок приручения\n\nСледующее заклинание будет наложено на вас:\n\nПриручение зверя\n\nВы также получите:\n\n"},
[6089] = {title = "Обучение зверя", objective = "Поговорите с Хольтом Громовым Рогом в Громовом Утесе.", description = "Теперь ты знаешь, как приручать питомца, но тебе надо научиться еще и обучать его.\n\nОтправляйся в Громовой Утес. Там тебе нужно будет поговорить с одним из наших самых уважаемых охотников, Хольтом Громовым Рогом. Если он сочтет тебя достойным знаний, то объяснит тебе, как обучать твоего нового питомца. \n\nХольт одолел многих могущественных и страшных зверей Азерота и сам повелевает сильными существами. Его связь с Матерью-Землей сильна, и он многому может научить. Удачи, <имя>.", progress = nil, completion = "А, юный охотник. Да, я могу наделить тебя знаниями, как обучать и направлять твоего питомца. Ты не только сможешь научить его новым способностям, но также сможешь кормить его и даже оживлять, если он падет в бою.\n\nСтупай, Мать-Земля еще сведет наши пути. Поговорим позже.", rewards = "Вы изучите:\n\nУрок дрессировки\n\nСледующее заклинание будет наложено на вас:\n\nДрессировка\n\nВы также получите:\n\n"},
[6101] = {title = "Приручение зверя", objective = "С помощью хлыста приручения приручите ночного саблезуба-охотника. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.", description = "Природа изменчива, но на нее вполне можно положиться, <имя>. Она предсказуема в том, что никогда не остается одной и той же, она всегда меняется. \n\nПоручения, которые я тебе дам, помогут тебе увидеть и оценить различных существ, которые впоследствии смогут стать твоими спутниками.\n\nВозьми этот хлыст приручения и приручи ночного саблезуба-охотника, которого ты найдешь к югу отсюда. Поупражняйся в своем охотничьем искусстве. Таким образом ты начнешь понимать сходства и различия творений природы.", progress = "Постоянно поддерживать равновесие с природой – таков путь жизни каждого ночного эльфа.", completion = "Вижу в тебе обязательность и понимание всего, чему я научил тебя, Миззрим.", rewards = "Вы получите:\n\n"},
[6102] = {title = "Приручение зверя", objective = "С помощью хлыста приручите совиного крикуна. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.", description = "Тебе удалось приручить двух детей земли, и теперь тебе предстоит подружиться с обитателем неба. При помощи этого хлыста приручи совиного визгуна, которую найдешь к западу отсюда. Испытай свое искусство, взяв в спутники эту могучую сову.\n\nКогда вернешься, я наделю тебя знаниями, которые понадобятся тебе для приручения любого животного, которого ты выберешь себе в спутники. Твой спутник встретит лицом к лицу те же опасности, что и ты, и вместе с тобой будет набираться опыта. Я также научу тебя, как призывать и отпускать по желанию твоего питомца.", progress = "Я горжусь твоими достижениями, Миззрим. Справился ли ты с той задачей, что я тебе поручил?", completion = "Теперь ты знаешь все, чему я мог тебя обучить, Миззрим. Могу ли дать тебе еще один совет? Хорошенько подумай прежде, чем выбрать первого питомца. Будет ли это существо, что ходит по земле, плавает в воде или рассекает небеса? Кем бы оно ни было, твой питомец, вне всякого сомнения, долго пробудет при тебе.\n\nЧто же, Миззрим. Ныне я дам тебе умение приручать животное, а так же призывать и отпускать его, когда тебе будет нужно. Гордись своими новыми умениями – ты их честно заслужил.", rewards = "Вы изучите:\n\nУрок приручения\n\nСледующее заклинание будет наложено на вас:\n\nПриручение зверя\n\nВы также получите:\n\n"},
[6103] = {title = "Обучение зверя", objective = "Поговорите с Иокастой в анклаве Кенария в Дарнассе.", description = "Теперь ты знаешь, как приручать питомца, но тебе надо научиться еще и обучать его.\n\nОтправляйся в Дарнасс. Там тебе нужно будет поговорить с одной из наших самых уважаемых охотниц, Иокастой. Она объяснит тебе, как обучать твоего нового питомца, так что поторопись.\n\nХотя Иокаста и сурова, ей всегда приятно наблюдать за развитием способностей очередного охотника. Держись с ней почтительно, и она воздаст добром. Удачи, <имя>.", progress = nil, completion = "Новоиспеченный охотник?. Что же, я могу дать тебе знания, необходимые для обучения и управления твоим питомцем. Ты сможешь обучать своего питомца не только новым способностям, но научишься его кормить и возрождать, если он погибнет в схватке.\n\nЗапомни, Миззрим: всегда уважай равновесие и почитай природу. Теперь ступай. Попозже еще поговорим.", rewards = "Вы изучите:\n\nУрок дрессировки\n\nСледующее заклинание будет наложено на вас:\n\nДрессировка\n\nВы также получите:\n\n"},
[6121] = {title = "Новый урок", objective = "Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.", description = "Теперь, <имя>, ты <готов/готова> узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придется испытать на себе силу действия яда в полной мере. Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд – он ждет твоего прибытия, чтобы начать обучение.", progress = nil, completion = "Добро пожаловать, юный друид, рад видеть, что ты горишь желанием узнать о нейтрализации ядов.\n\nЕсли в прошлом большинство друидов проходили заранее установленные испытания, то для твоей работы такого не понадобится. В Аубердине вспышка отравления животных, и в тамошней деревне справиться с этим не могут. Поэтому представитель деревни просил помощи у Лунной поляны, и мы направляем тебя к ним. Это не учеба, а серьезное задание, имей в виду.", rewards = "Вы получите:\n\n"},
[6122] = {title = "Основной источник", objective = "Используйте пустую колбу для взятия пробы воды из устья пещеры у водопада Скалистый. \n\nДоставьте наполненную колбу Аландариан Песне Ночи в Аубердин, на Темный Берег.", description = "Водопад Скалистый на Темном Берегу – основной источник питьевой воды для всего региона, но теперь я подозреваю, что именно оттуда распространяется отрава, поражающей местную фауну – особенно оленей. Возьми эту пробирку, чтобы отобрать немного воды из устья пещеры. Осторожнее – в пещере у водопада ныне поселилась опасная нага.\n\nКак только наберешь воды, доставь ее Аландариан Песне Ночи в Аубердин. Именно она просила нашей помощи, и ты поможешь ей разобраться с этой заразой.", progress = "Это тебя прислал Круг Кенария Лунной поляны, да? Замечательно! Нам так не хватает рук для работы с бедными оленями, и мы рады любой помощи. \n\nТы принес пробу воды, о которой говорил мне Дендрит Блеск Звезд? Он сказал, что ты принесешь ее, чтобы мы могли тотчас же приступить к трудам по исцелению...", completion = "Клянусь Элуной, какая омерзительная вода! Немудрено, что оленей поразил недуг.\n\nЧто-то заражает воду, и она в свою очередь поражает все грунтовые воды Темного Берега. Больных оленей видели повсюду, не только у реки. Даже если эта вода и есть основной источник расползающейся болезни, тут замешано что-то еще.\n\nХочешь – верь, хочешь – не верь, но эта вода поможет нам найти исцеление. А пока я буду исследовать жидкость, мне понадобится кое-что еще, чтобы составить лекарство...", rewards = "Вы получите:\n\n"},
[6123] = {title = "Сбор лекарственных ингредиентов", objective = "Принесите 5 корешков землекорня и 12 лунных грибов Аландариан Песне Ночи в Аубердине, чтобы она могла сделать целительную мазь.", description = "Основой целительной мази для оленей послужит вода. Для придания ей целительных свойств мне понадобится землекорень. Травники знают, где его искать, так что, если нам не повезло и вы не <травник/травница>, придется найти кого-то, кто сможет помочь.\n\nДля усиления воздействия мне нужны лунные грибы. Найти их довольно легко: в пещерах, прямо на восток отсюда, их полным-полно. В этих пещерах обитают лунные совухи; в последнее время они стали очень раздражительны, так что будьте осторожны.", progress = "Вы собрали реагенты, необходимые для изготовления мази? Сами по себе олени не поправятся, так что нам лучше поспешить им на помощь!", completion = "Отлично, Иселор, вы принесли так много, что должно хватить на несколько больших доз мази – по крайней мере чтобы исцеление началось.\n\nИзготовление средств против ядов иногда бывает весьма сложным, поскольку каждый из них требует конкретного антидота для нейтрализации воздействия. Здорово было бы уметь в любой момент снимать отравление, не беспокоясь о конкретных ингредиентах, которые должен содержать антидот!\n\nА теперь позвольте мне приступить к работе!", rewards = "Вы получите:\n\n"},
[6124] = {title = "Исцеление больных", objective = "Нанесите мазь исцеления животных на 10 больных оленей, обитающих на Темном Берегу, – это должно их исцелить. По слухам, ареал обитания больных оленей – южнее реки Скалистой и севернее Аубердина, а далее – по всей области, вплоть до южных границ Темного Берега, где начинается Ясеневый лес.", description = "Мази, изготовленной из реактивов, которые вы принесли мне, <имя>, хватит на десять доз. Пока я работаю здесь, в деревне, пытаясь изготовить побольше этой мази, я хотел бы, чтобы вы помогли нам начать исцеление. По всему Темному Берегу встречаются больные олени. Используйте мазь для исцеления их недуга.\n\nЯ уверен, что Дендрит Звездная Вспышка из Лунной Поляны захочет поговорить с вами, когда вы закончите. Пожалуйста, передайте благодарность жителей Аубердина Кругу Кенария... и позвольте мне поблагодарить вас лично за вашу помощь!", progress = nil, completion = "Вы хорошо сделали, что позаботились о больных оленях Темных берегов; это невольные жертвы порчи и осквернения, расползающихся по всему краю. В Дарнассе есть те, кто признает наличие угрозы... и те, кто упорно игнорирует ее все усиливающиеся признаки. Я надеюсь, что вы, Келегорм, – один из тех, кто не собирается надевать шоры и будет смотреть в лицо фактам.\n\nКак бы там ни было, вы доказали, что являетесь другом природы и Круга Кенария, и я прошу вас принять это в качестве знака нашей дружбы.", rewards = "Вы получите:\n\nПокрытая пылью медицинская сумка"},
[6125] = {title = "Власть над ядом", objective = "Вернитесь к Матренгилу Медвежьей Лапе в анклав Кенария в Дарнассе.", description = "Ты $Gпознал:познала;, что значит исцелять от действия яда без помощи духов. Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами.\n\nТебе следует вернуться к Матренгилу Медвежьей Лапе в Дарнасс, <имя>. Теперь, когда его <ученик усвоил данный ему/ученица усвоила данный ей> урок, он несомненно научит тебя новому могучему заклинанию.\n\nДо свидания, юный друид. Мы еще встретимся.", progress = nil, completion = "С возвращением. Я следил за твоими успехами с тех самых пор, как ты покинул нас, и, должен признаться, был изумлен, узнав о ситуации в Аубердине. Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие.\n\nТы благородно поступил в трудной ситуации. И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами. Используй ее во благо, Иселор... во благо.", rewards = "Следующее заклинание будет наложено на вас:\n\nВыведение яда\n\nВы получите:\n\n"},
[6126] = {title = "Новый урок", objective = "Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.", description = "Теперь, <имя>, ты $Gготов:готова; узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты <усвоил/усвоила> этот важный урок, посему тебе придется испытать на себе силу действия яда в полной мере. Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд – он ждет твоего прибытия, чтобы начать обучение.", progress = nil, completion = "Привет тебе, мой юный друид, я рад, что ты жаждешь узнать, как изгонять из тела яд.\n\nВ старину друиды проходили заранее установленные испытания, но тебе этого делать не придется. В Перекрестке и Степях вспышка отравлений животных, и справиться с ней там никак не могут. Оттуда запросили помощи Лунной поляны, так что мы посылаем тебя. Это не учеба, а серьезное задание. Помни это.", rewards = "Вы получите:\n\n"},
[6127] = {title = "Основной источник", objective = "Используйте пустой пробоотборник Вершины Багрового Тумана для отбора воды из озера на вершине.\n\nДоставьте наполненный пробоотборник Вершины Багрового Тумана Тонге Руническому Тотему в Перекресток, что в Степях.", description = "Вершина Багрового Тумана, что к северо-западу от Перекрестка – самый вероятный источник распространения этой отравы. На его вершине находятся озера воды, влияющие на перемены погоды. Подозреваю, что вода сейчас заражена демонопоклонниками из клана Пылающего Клинка.\n\nВозьми этот пробоотборник и набери воды из озера у самой вершины. Наполнив, доставь его Тонге Руническому Тотему в Перекресток. Именно он и просил нашей помощи, и ты будешь работать вместе с ним над искоренением этой заразы.", progress = "Это тебя прислал Круг Кенария Лунной поляны, да? Большая удача для нас! Мы выбиваемся из сил, пытаясь восстановить равновесие среди больных газелей, что блуждают в северных Степях. Мы рады любой помощи. \n\nТы принес пробу воды, о которой говорил мне Дендрит Блеск Звезд? Он сказал, что ты принесешь воды, дабы мы могли приступить к трудам по исцелению тотчас же...", completion = "Клянусь предками, какая омерзительная вода! Немудрено, что газелей поразил недуг.\n\nЧто-то заражает воду, и она начинает разрушать экосистему северных Степей. Больных газелей видели повсюду к северу от тутошней дороги с востока на запад. Даже если эта вода и есть основной источник расползающейся болезни, тут замешано что-то еще.\n\nЭта вода, верь – не верь, поможет нам найти исцеление. А пока я буду исследовать эту воду, мне понадобится кое-что еще, чтобы составить лекарство...", rewards = "Вы получите:\n\n"},
[6128] = {title = "Создание лекарства", objective = "Принесите 5 корешков землекорня и 5 рогов кодо Тонге Руническому Тотему в Перекресток, и он сделает целебную мазь.", description = "Основой целебной мази для газелей послужит вода. Для придания ей целебных свойств мне понадобится землекорень. Травники знают, где его отыскать, так что если нам не повезло, и ты – не <травник/травница>, придется попросить кого-то о помощи. \n\nДля силы воздействия мне нужны рога кодо – осколки и куски не подойдут. Кодо живут в северной части Степей. Убей несколько зверюг, заодно и природное равновесие восстановится. Отпили у них рога и принеси мне.", progress = "Ты собрал реагенты, необходимые для изготовления мази? Сами по себе газели не поправятся, так что нам лучше поспешить к ним на помощь!", completion = "Отлично, Подлыйзмей, ты принес так много составляющих, что должно хватить на несколько больших доз мази – по крайней мере, положим начало исцелению.\n\nИзготовление средств против ядов иногда бывает весьма сложным, ведь для нейтрализации каждого из них требуется отдельный антидот. Здорово было бы научиться в любой момент лечить отравления, не беспокоясь о конкретных составляющих противоядия!\n\nЛадно, пора браться за работу!", rewards = "Вы получите:\n\n"},
[6129] = {title = "Исцеление больных", objective = "Нанесите мазь исцеления животных на 10 больных газелей, обитающих в северной части Степей, – это должно их вылечить. По слухам, больные газели живут севернее дороги, проходящей через Перекресток с востока на запад.", description = "Мне удалось сделать десять доз целебной мази. Пока я работаю здесь, в деревне, пытаясь изготовить побольше, я хотел бы, чтобы ты <помог/помогла> нам лечить бедных зверей. По всей северной части Степей бродят больные газели. Исцели их недуг при помощи этой мази.\n\nЯ уверен, что Дендрит Блеск Звезд  на Лунной Поляне захочет поговорить с тобой, когда ты закончишь. Пожалуйста, передай нашу благодарность Кругу Кенария... и позволь мне поблагодарить тебя лично за неоценимую помощь!", progress = nil, completion = "Вы хорошо сделали, что позаботились о больных газелях Степей; это невольные жертвы порчи и осквернения, расползающихся по всему краю. Вы, таурены, лучше прочих постигаете мудрость Кенария. И Вы, Комодик, как и мудрейшие из Громового Утеса, постигаете, что необходимость достичь равновесия превыше искусственных расовых границ. \n\nТак или иначе, вы доказали, что являетесь другом природы и Круга Кенария, и я прошу вас принять это в качестве знака нашей дружбы.", rewards = "Вы получите:\n\nПокрытая пылью медицинская сумка"},
[6130] = {title = "Власть над ядом", objective = "Вернитесь к Тюраку Руническому Тотему на Вершину Старейшин в Громовой Утес.", description = "Ты $Gпознал:познала;, что значит исцелять от действия яда без помощи духов. Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами.\n\nТебе следует вернуться к Тюраку Руническому Тотему в Громовой Утес, <имя>. Теперь, когда его <ученик усвоил данный ему/ученица усвоила данный ей> урок, он несомненно научит тебя новому могучему заклинанию.\n\nДо свидания, юный друид. Мы еще встретимся.", progress = nil, completion = "С возвращением. Я следил за твоими успехами с тех самых пор, как ты покинул нас, и, должен признаться, был изумлен, узнав о ситуации в Перекрестке. Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие.\n\nТы благородно поступил в трудной ситуации. И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами. Используй ее во благо, Подлыйзмей... во благо.", rewards = "Следующее заклинание будет наложено на вас:\n\nВыведение яда\n\nВы получите:\n\n"},
[6131] = {title = "Союзник Древобрюхов", objective = "Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 5 воинов 5 землепроходцев и 5 садовников из племени Мертвого Леса.", description = "Древобрюхи – единственное фурболгское племя, не затронутое порчей. Однако, нынче многие расы без разбору убивают всех фурболгов подряд. И потому фурболгов из племени Древобрюха осталось так мало.\n\nХочешь заслужить наше доверие? Изгони из Оскверненного леса пораженных порчей фурболгов Мертвого Леса, и в один прекрасный день мы признаем тебя союзником. Ты найдешь первое племя Мертвого Леса – воинов, следопытов и садовников – к западу от меня.После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil},
[6132] = {title = "Вытащи меня отсюда!", objective = "Проводите Мелиццу Жужжалит в лагерь у Кладбища кодо в Пустошах. Поговорите с Хормицем Жужжалитом.", description = "Вытащи меня отсюда!\n\nЯ отправилась к Долине Копий, чтобы поговорить с Мародинами. Мне казалось, с ними можно вести кое-какие дела... Но они не желают говорить со мной! Мне кажется, они... они хотят съесть меня!\n\nТолько вытащи меня отсюда – вот увидишь, мой брат Хормиц тебе кучу денег отвалит! А найти-то его несложно: он в нашем лагере, к востоку отсюда, там еще Кладбище кодо рядом.\n\nНам лучше поторопиться, <имя>: буквально пару минут назад я слышала, как два кентавра говорили, что нужно собрать дрова для готовки...", progress = "Тебе не встречалась моя сестра Мелисса? Вечно она где-то гуляет... До добра это не доведет!", completion = "Моя сестра Мелисса предупредила меня о твоем приходе. Хочу тебя поблагодарить за то, что вытащил ее из очередной беды. Правда, боюсь, она уже успела вязаться во что-то новое...", rewards = "Вы получите:\n\n"},
[6133] = {title = "Охота на следопытов", objective = "Отправляйтесь в северные пределы Восточных Чумных земель и заполучите реестр Кель'Таласа. Документ находится где-то в Сторожке Кель'Литиен.\n\nТакже убейте 8 следопытов, 8 разведчиц дорог и 8 лесников.", description = "Высшие эльфы в Сторожке Кель'Литиен присвоили себе кое-что, что принадлежит мне, <класс>. Это документ, описывающий мою смертную жизнь. B\nНет, к тебе его содержимое не имеет никакого отношения – даже не вздумай сунуть туда нос! Твое дело маленькое, насекомое – принеси мне документ!\n\nИ имей в виду, тупица, я хочу, чтобы эти негодяи пожалели, что наложили свои лапы на мою частную собственность! Нанеси им как можно больший ущерб!", progress = "Не заставляй меня ждать, |3-6(Охотник)!", completion = "Надеюсь, тебе хватило ума не совать свой нос в реестр. С твоей стороны это было бы равносильно самоубийству.", rewards = "Вы получите:\n\n"},
[6134] = {title = "Сбор эктоплазмы", objective = "Принесите 8 единиц эктоплазмы и ящик призрачных магнитов Хормицу Жужжалиту в Пустоши.", description = "На юго-востоке есть местность, именуемая Долиной Костей. Долину эту населяют призраки кентавров племени Маграм. Жутковато звучит, верно? Подумай, как это пугает Маграмов!.. Если бы нам удалось собрать энергию призраков – только представь, что за это дали бы кентавры!..\n\nВот, возьми эти призрачные магниты. Если поставишь такой магнит между двух скелетов, Мертвых Гигантов, то призраки потянутся к нему. Отойди подальше, уничтожь призраков и собери их эктоплазму: позже мы продадим ее Маграм.", progress = "Эй, Томпсон, где моя эктоплазма?", completion = "А вот и она!.. Похоже, ты и сам в эктоплазме перемазался. Склизкая штука, верно?\n\nЧто ж, Томпсон, прими мою благодарность. Эта дрянь стоит целого состояния... Конечно, если удастся убедить кентавров ее купить!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНаручи кондораЯкорный кулачный щит\n\nВы также получите:\n\n"},
[6135] = {title = "Проклятый Тенекрыл", objective = "Выследите Тенекрыла и убейте его. Принесите полоску меха Тенекрыла Натаносу Гнилостеню.\n\nГоворят, Тенекрыл рыщет в землях к северу от имения Марриса.", description = "Пока тебе удается с горем пополам выполнять мои поручения.\n\nПора бы заставить тебя сделать что-нибудь посложнее. Да, тупица, ты <дозрел/дозрела> до настоящей работенки.\n\nВот что, выследи и убей Тенекрыла – это чудовищная летучая мышь-альбинос, которая хозяйничает в землях к северу отсюда. И принеси мне клок его белой шерсти – чтоб я знал, что ты не врешь!", progress = "Не советую соваться к твари в одиночку, |3-6(Охотник).", completion = "Неплохая работа, тупица. Посмотрим, что можно сварганить для тебя из этого меха...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки ТенекрылаТенекрылые оплечье\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[6136] = {title = "Огромный червь", objective = "Найдите и уничтожьте Мерзкослиза в северных пустошах Восточных Чумных земель. Возвращайтесь к Натаносу Гнилостеню по выполнению задания.", description = "За лагерем Серебряного Рассвета и часовней Светлых надежд, к западу от Северного дола обитает огромный червь, Мерзкослиз.\n\nЯ потерял целые батальоны в попытках уничтожить его. Его размеры невообразимы! Чем больше он ест, тем больше растет...\n\nХотя я, в общем-то, мало волнуюсь по поводу того, сожрет ли тебя червь, должен признать, что предпочел бы, чтобы ты <вышел победителем/вышла победительницей>. Учти, Мерзкослиз особенно охотно жрет тех, кто попытался напасть на него.", progress = "Как же ты меня достал!", completion = "О, да ты делаешь успехи! Такими темпами скоро получишь повышение – от полного имбецила до недоумка.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nРазбрызгиватель лимфыМолот Каменного черепаРуководство Сары\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[6141] = {title = "Брат Антон", objective = "Найдите в Пустошах брата Антона и поговорите с ним.", description = "Антон, мой собрат по оружию, услышал вести о нашествии нежити в далеком Калимдоре, в тех землях, что называются Пустошами. Конечно же, он немедленно собрался в путь, чтобы покончить с этой угрозой!\n\nОн ищет отважных и решительных спутников – тех, у кого хватит храбрости сражаться с ним плечом к плечу. Если ты хранишь чистоту в своем сердце, разыщи брата Антона в городе, носящем имя Высоты Найджела, в Пустошах.", progress = nil, completion = "Я получил вести о помощи, грядущей с востока. Не о тебе ли шла речь? Ты пришел сюда, дабы помочь Алым в нашем благородном походе?\n\nЕсли это так, то слушай...", rewards = "Вы получите:\n\n"},
[6142] = {title = "Наживка из моллюска", objective = "Найдите 10 кусочков мяса мягкокожего моллюска и принесите Май'Лахии в Деревню Ночных Охотников.", description = "Судя по виду, <класс>, ты – <заядлый рыбак/заядлая рыбачка>! Обожаю ловить рыбу, всю жизнь этим занимаюсь. Можешь мне поверить, нет лучшей наживки, чем мясо мягкокожего моллюска: рыба просто не может против нее устоять, если ты понимаешь, о чем я.\n\nНа север отсюда, неподалеку от берега, есть потерпевший крушение корабль: так вот, вокруг него эти моллюски так и кишат! Принесешь мне 10 кусочков мяса моллюска – а взамен я тебе дам кое-что полезное...", progress = "Дождаться не могу, когда же отправлюсь на рыбалку. Я просто мечтаю о наживке из мяса моллюсков!.. Ты ведь принес мне 10 кусочков, как я просила?", completion = "Это просто великолепно!.. Когда я спросила у знахаря, как лечить головную боль, он мне ответил: Май'Лахия, детка, попробуй половить рыбку в мутной воде; увидишь – тебе сразу полегчает!\n\nОх, как подумаю – мне и правда сразу легче становится!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗахваты ПардокаРемень молодого луняСкрепостальной пояс\n\nВы также получите:\n\n"},
[6143] = {title = "Смерть земноводным!", objective = "Убейте 7 мирмидонов, 7 наг и 5 колдуний из клана Скользящего Плавника, а затем вернитесь в деревню Сумеречной Охоты и поговорите с Друлзегаром.", description = "Может, ты <слышал/слышала>, может, нет... Мы с командой рыбачили неподалеку от острова Раназьяр, к северу от разбитого корабля на северном побережье. Мы всегда там рыбачили, сколько я себя помню – а теперь я ни о чем другом не могу думать, кроме как о мести за своих друзей...\n\nОднажды утром на нас напали наги. Они убили всех, кроме меня!..\n\nЯ не могу вынести бремени этой вины, <класс>, пойми меня: ты <нужен/нужна> мне, чтобы расправиться с проклятыми нагами. Поверь, я хорошо вознагражу тебя. Ты ведь возьмешься за это дело?", progress = nil, completion = "Ты говоришь, эти мерзкие твари мертвы? Да, месть сладка... Но в моем сердце по-прежнему пустота, которой ничто не заполнит. Я посвящу всю свою жизнь тому, чтобы извести нагов под корень – весь их род до последнего змееныша!..\n\nВот, дружище, держи свою награду, как я и обещал – хотя она ничтожно мала в сравнении с моей благодарностью...", rewards = "Вы получите:\n\n"},
[6144] = {title = "Приказ по армии", objective = "Отправляйтесь в Подгород и предстаньте перед Вериматасом.", description = "Вот что, <класс>, поступил приказ по армии. Сам Вариматрас требует, чтобы я прислал ему самых способных солдат в Подгород для выполнения крайне сложной операции. \n\nУвы, самые достойные и способные давно погибли, а вместо них я располагаю кучкой жалких недоумков.\n\n*Натанос окидывает вас ледяным взглядом*\n\nПредстанешь перед Вариматрасом в Подгороде. Смотри, не опозорь меня, <класс>!", progress = nil, completion = "Верховный рыцарь восседает в Бастионе Алого ордена пока его войска хозяйничают в наших землях, сея скверну и разрушения.\n\nТемная Госпожа повелела мне разобраться с этим червяком раз и навсегда. Ты заставишь их расплатиться за свои деяния.", rewards = "Вы получите:\n\n"},
[6145] = {title = "Курьер из Багрового Легиона", objective = "Возвращайтесь в Восточные Чумные земли и выследите курьера из Багрового Легиона. Убейте его и заберите приказ верховного рыцаря.\n\nЗа дальнейшими указаниями обращайтесь к Натаносу Гнилостеню.", description = "Тело не может жить без головы, а голова без тела. Оборона сил Алого ордена в Стратхольме практически несокрушима. Однако мы можем обезглавить их армию.\n\nМои верные стражи смерти уже давно собирают сведения о деятельности Алого ордена за пределами Стратхольма. Каждый день им присылают инструкции из центрального штаба в Длани Тира. Мы должны перехватить их, <раса>! Убей курьера из Багрового Легиона и забери бумагу. Отдашь ее Натаносу.", progress = "Если ты справишься с этой задачей, можешь считать, что почти заслужил мое уважение? |3-6(Жрец).", completion = "*Натанос хохочет и потирает руки*\n\nОтлично! Наконец-то! Наконец-то у меня есть возможность уничтожить Алого Оракула!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6146] = {title = "Уловка Натаноса", objective = "Отправляйтесь в Длань Тира к юго-востоку от Поместья Маррисов. Прибыв в город, откусите от гнилого яблока. Под личиной рыцаря Алого ордена доставьте приказ верховного рыцаря лорду-рыцарю Вальдермару.", description = "Я тут немного подрихтовал приказ. Если наша маленькая уловка сработает, Алый Оракул на некоторое время окажется почти без защиты. Тут-то мы и нанесем удар!\n\nТеперь слушай внимательно, <класс>. Доставишь приказ лорду-рыцарю Вальдермару.\n\nЧто значит как?! Лично в руки, тупица!\n\nДержи приказ и это гнилое яблоко – съешь его, когда войдешь в город. Оно... э-э... придаст тебе более приятный для человеческого глаза вид. Запомни, лично в руки лорду-рыцарю Вальдермару!", progress = "Не ныть, солдат! Приказы не обсуждаются!", completion = "Где тебя носило так долго? Я уж думал, тебя схватили твари Плети!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6147] = {title = "Назад к Натаносу", objective = "Возвращайтесь к Натаносу и отчитайтесь о выполнении задания.", description = "Верховный рыцарь прислал очень странный приказ... Однако приказы не обсуждаются. Возвращайся в Бастион Алого ордена и сообщи, что Оракул выдвигается немедленно.\n\nМы приложим все усилия, чтобы доставить его в Стратхольм в целости и сохранности.", progress = nil, completion = "Болваны! Они ни о чем не догадались! Ну, готовься, |3-6(Жрец). Настало время нанести решающий удар!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6148] = {title = "Алый Оракул Деметрия", objective = "Алый орден сейчас в пути. Найдите Оракула Деметрию и ее свиту на дороге от Длани Тира в Стратхольм. Убейте Оракула и возвращайтесь к Натаносу Гнилостеню.", description = "Деметрия – главный советник верховного рыцаря. Ее величают Оракулом за ее сверхъестественные способности. Она неоднократно оказывала помощь Алому ордену в боях с Плетью.\n\nПосмотрим, в самом ли деле ей открыто будущее... Уверен, она предвидела, что ее ждут неприятности. Вот ты их ей и обеспечишь!\n\nВыследи Оракула и убей ее. Полагаю, сейчас она на пути к Длани Тира. Не подведи меня, насекомое!", progress = "Тебе удалось убить ее?", completion = "От этого удара они нескоро оправятся! Отлично, Незердрейк! Ты заслужил мое доверие и эту награду!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКлинолесский лукГрозаСвященный защитник\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[6161] = {title = "Сокровища Ракмора", objective = "Найдите серебряный и золотой ключи Ракмора, а затем разыщите и отоприте сундук Ракмора.", description = "Записи Ракмора рассказывают о том, как во время плаванья к Крепости Оперенной Луны его корабль был атакован морскими тварями. Чтобы не дать врагу завладеть его сокровищем, Ракмор спрятал сундук на острове Раназьяр.\n\nОткрыть сундук можно только двумя ключами, золотым и серебряным. Они были утрачены, но если разыскать и сундук, и оба ключа – кто знает, какие сокровища откроются счастливцу?", progress = "Сундук надежно заперт...", completion = "Сундук открывается. Перед вами сокровище Ракмора!", rewards = "Вы получите:\n\nКолесо капитана РакмораРумпель капитана Ракмора"},
[6162] = {title = "Последняя битва супруга", objective = "Убейте властителя Рора и принесите его коготь Дрейка'Сур на заставу Отравленной Крови в Оскверненном лесу.", description = "Мой супруг ради чести нашего клана отправился в Оскверненный лес, чтобы сразиться с Советом Теней и прочими мерзостными тварями!\n\nОн несколько раз избегал смерти. Потом я получила письмо от него, в котором он говорил, что некий друид попросил у него помощи против огромного пораженного порчей фурболга по имени Рор – и с тех пор я не слышала больше ни о муже, ни о друиде.\n\nЯ хочу, чтобы ты <принес/принесла> мне отрубленную когтистую лапу этого Рора, <имя>! Я жажду мести за мое вдовство! Эта тварь, как я знаю, засела где-то на юге, возле границы Ясеневого леса.", progress = "Где коготь этой твари, Томпсон? Он заплатит за свои преступления! Мне плевать, из-за порчи это или просто со злости, что он живет в таком поганом лесу! Никакому фурболгу не прощу зла, причиненного моей семье!", completion = "Ты держишь слово – честь для меня познакомиться с тобой. Мой муж погиб в бою – он гордился бы тобой. Но я не смогла бы спокойно спать, если б не знала, что тварь, обрекшая меня на одиночество, заплатила за все!\n\nЕще раз спасибо тебе, Томпсон.", rewards = "Вы получите:\n\n"},
[6163] = {title = "Рамштейн", objective = "Отправляйтесь в Стратхольм и убейте Рамштайна Ненасытного. Принесите его голову Натаносу в качестве сувенира.", description = "На этом самом месте я когда-то держал оборону Лордерона... Бесчисленное воинство Плети прошло волной по моей ферме, уничтожив все живое на своем пути.\n\nГрязь. Скверна. Я стал беспомощной и безвольной игрушкой в руках Плети, оказавшись в рядах нежити. Сознанием моим управляла воля Короля-лича. \n\nА потом она освободила меня... Я ждал, я надеялся и наконец обрел свободу.\n\nТеперь я хочу отомстить чудовищу, забравшему мою жизнь. Убей его!", progress = "Когда Сильвана освободила меня, я гонялся за тварью, убившей меня, многие месяцы, но безрезультатно. Чудовище укрылось в Стратхольме...", completion = "Надеюсь, ты заставил тварь умолять о пощаде?\n\n*Натанос всердцах плюет на землю*\n\nПовешу эту голову над камином.\n\nХорошая работа, Тихийгуставо. Ты заслужил мое уважение.\n\n*Натанос отдает честь*.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКоролевская печать АлексисаОбруч Стихий\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[6164] = {title = "Книга рецептов Августа", objective = "Принесите Августу Помешанному в Долину Ужаса его книгу рецептов.", description = "Пожалуй, я готов открыть лавку...\n\nО нет! Моя книга рецептов! Мне не обойтись без нее!\n\nКажется я оставил ее где-то в городе... да, видимо, в таверне, в которой останавливался!\n\nПринеси мне мою книгу, о умоляю, принеси мне ее! Ты увидишь, цены у меня СУМАСШЕДШИЕ!", progress = "Ты нашел книгу? Лавка простаивает!", completion = "Вот она! Какое счастье!\n\nЭто безумно счастливый день, Томпсон!", rewards = "Вы получите:\n\n"},
[6181] = {title = "Срочное сообщение", objective = "Отнесите записку Льюиса укротителю грифонов Тору.", description = "Хотя мы не получаем серьезной помощи напрямую из Штормграда, у меня в городе есть знакомый, снабжающий нас доспехами. Зовут его Озрик Штранг. Его магазин, \"Ограниченная неуязвимость\", находится в Старом городе.\n\nНаши запасы доспехов заканчиваются, и я должен связаться с Озриком, чтобы попросить еще. Можете ли вы передать ему эту записку?\nБыстрее всего добраться до Штормграда можно с помощью Тора, нашего укротителя грифонов. Он находится прямо у подножия этого холма. Приходите к нему с моей запиской, а затем летите на грифоне в Штормград.", progress = "Такое ощущение, что вы сильно торопитесь. Что ж, если так, то вы пришли в правильное место!", completion = "Вам нужно доставить эту записку в Штормград? Это не проблема, вы можете взять одного из моих грифонов!", rewards = "Вы получите:\n\n"},
[6182] = {title = "Первый и последний", objective = "Поговорите с Матиасом Шоу в Старом Городе в Штормграде. Матиас находится в казармах.", description = "Натанос Маррис был первым и последним человеком-предводителем следопытов. Учеником Сильваны Ветрокрылой, ныне королевы-банши Отрекшихся.\n\nМы думали, что Натанос погиб в бою много лет назад, при защите Лордерона. Хотя его тело не было обнаружено, считалось, что он не сумел выбраться из Восточных Чумных земель.\n\nМатиас Шоу изучил обстоятельства его исчезновения и у него может быть какая-то информация. Доложитесь ему немедленно. Он обитает в Старом городе, в казармах.", progress = nil, completion = "После появления сообщений о необычной активности Отрекшихся в Восточных Чумных землях туда были посланы агенты ШРУ для расследования ситуации. Результаты этого расследования оказались весьма тревожными.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6183] = {title = "Почитание мертвых", objective = "Еще раз поговорите с Матиасом Шоу, если хотите принять его задание.", description = "Пятеро моих лучших полевых агентов занимались делом Марриса. Вернулся только один, и тот через три дня умер во сне.\n\nТа скудная информация, которую удалось из него вытрясти, звучала несусветной чушью. Мы разобрали лишь два слова: \"Натанос\" и \"Гнилостень\".\n\nУ меня не хватает сотрудников, чтобы продолжить это расследование, и в \"Черном Вороне\" нам не помогут. Мы должны докопаться до сути, чтобы хотя бы принести какое-то утешение семьям погибших. Вы окажете нам помощь?", progress = nil, completion = "*Матиас кивает.*\n\nЯ и не сомневался, что Болвар пришлет мне честных и благородных людей – самых преданных солдат Альянса.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6184] = {title = "Флинт Тенемор", objective = "Отправляйтесь в Лагерь Промозглого Ветра в Западных Чумных землях и найдите Флинта Тенемора.", description = "Единственные сведения, которыми мы сейчас располагаем – это то, что Натаноса Марриса, возможно, убил этот тип по имени \"Гнилостень\". Мы допускаем, что тот же \"Гнилостень\" расправился и с моими агентами.\n\nФлинт Тенемор, еще один сотрудник ШРУ, находится в лагере на Берегу Промозглого Ветра в Западных Чумных землях. Найдите его. Он расскажет вам о текущей ситуации в Чумных землях и даст задание.\n\nУдачи вам, <имя>.", progress = nil, completion = "Ваше первое задание будет очень простым, Сарт. Уйти – и вернуться. Провести разведку...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6185] = {title = "Чума на востоке", objective = "Поищите в Восточных Чумных землях сведения про некоего Гнилостеня и пропавших агентов ШРУ. Если удастся найти знаки отличия ШРУ, отнесите их Флинту Тенемору в Лагерь Промозглого Ветра.", description = "Говорю же, первое задание – разведывательное. Ничего особенного, <имя>. Отправляйся в Восточные Чумные земли и поищи там сведения про Гнилостеня.\n\nИ поглядывай, не найдешь ли ты наших пропавших оперативников. Мы вынуждены предположить, что они погибли, но коли так, должны быть... трупы.\n\n*Флинт сглатывает трудный комок.*\n\nВсе агенты ШРУ носят такие знаки.\n\n*Флинт показывает вам знаки отличия ШРУ.*\n\nПринеси мне все, какие только найдешь.", progress = "Ну... Как дела?", completion = "Рутгер. Фредо. Турьен. Все... Мертвы…\n\n*Флинт сжимает в руках их регалии.*\n\nГде они были? Удалось ли тебе собрать сведения про этого мерзавца, Гнилостеня?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6186] = {title = "Пришествие Гнилостеня", objective = "Возвращайтесь в Штормград и сообщите верховному лорду Болвару Фордрагону о судьбе Натаноса Марриса.", description = "*Флинт бледнеет.*\n\nЭто дело рук На... Натаноса? Натанос и есть Гнилостень?\n\nНо почему? Он был... таким благородным, пользовался всеобщим уважением. Единственный человек, которого согласились обучать высшие эльфы. И теперь он безжалостный сторонник Отрекшихся?\n\nМне... жаль, что приходится просить об этом, <имя>, но об этих событиях должен узнать верховный лорд Фордрагон. Я прошу тебя незамедлительно вернуться в Штормград с вестями.", progress = nil, completion = "Нет. Не может... НЕТ! Как? Агент Отрекшихся? ЗАЩИТНИК Королевы банши???\n\n*Верховный лорд Болвар Фордрагон бессильно опускает руки.*", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6187] = {title = "Порядок должен быть восстановлен", objective = "Соберите войско и отправляйтесь в Восточные Чумные земли. Проведите полномасштабную атаку на Натаноса Гнилостеня и любых воинов Орды, которые могут попытаться его защитить.\n\nБудьте осторожны, потому что Орда всеми силами будет защищать бывшего предводителя следопытов.", description = "Знаете, сколько предводителей следопытов существует на этом свете? А сколько когда-либо существовало людей-предводителей следопытов?\n\nДостижения Натаноса необыкновенны. Он был тактическим гением, благодаря ему Альянс в течение десятилетия одерживал победы.\n\nА теперь... теперь он защитник Отрекшихся.\n\nНет. Такого быть не должно. Порядок должен быть восстановлен.\n\nСоберите армию, <имя>. Возвращайтесь в Проклятые земли со своими воинами и уничтожьте Гнилостеня.\n\nЖелаю удачи, <имя>. В этом бою она вам точно понадобится.", progress = nil, completion = "Это трагедия. Я думаю... я уверен, что над нами висит проклятие, Лорегон. Мы приговорены терять наших величайших воинов, благороднейших героев и даровитейших ученых.\n\nМы в долгу перед вами и, уверяю вас, Лорегон, где бы сейчас ни был Натанос Маррис, он с улыбкой взирает на вас.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКлинолесский лукГрозаСвященный защитник\n\nВы также получите:\n\n"},
[6261] = {title = "Дунгар Долгопив", objective = "Отнесите ящик Озрика к укротителю грифонов Дунгару Долгопиву.", description = "<имя>, я сложил в этот ящик все, о чем просил Льюис. Можете отвезти ему ящик?\n\nС Тором в Западном Крае вы уже общались – значит, сможете нанять грифона, чтобы туда вернуться. Наш укротитель грифонов – Дунгар Долгопив, он находится в Торговом квартале.\n\nПоговорите с Дунгаром и доставьте этот ящик Льюису как можно скорее. Мы не хотим, чтобы нашим воинам в Западном Крае пришлось сражаться без новых доспехов!", progress = "Да вы вспотели, сударь! Не стоило так много бегать на своих двоих. В следующий раз возьмите грифона!", completion = "Нужно доставить сундук в Западный Край, да? А вы там бывали прежде? Если да, то никаких проблем, друг мой. У меня есть множество грифонов, обученных этому маршруту!", rewards = "Вы получите:\n\n"},
[6281] = {title = "Продолжение пути в Штормград", objective = "Оплатите укротителю грифонов Тору полет до Штормграда и принесите записку Льюиса Озрику Штрангу в магазинчик \"Ограниченная неуязвимость\", расположенный в районе Старого города.", description = "За небольшую плату вы можете нанять грифона для полета в Штормград, чтобы доставить записку Льюиса Озрику. Более быстрого пути нет.\n\nЕсли для вас это приемлемо, поговорите со мной снова, когда будете готовы лететь. Я, конечно, возьму с вас немного денег, но поверьте, оно того стоит!", progress = "Путешествовали, да? Видели что-нибудь интересненькое?", completion = "А, записка от интенданта Льюиса! Я не удивлен, что ему понадобилась дополнительная экипировка. Сторожевой Холм далеко, и в Штормграде едва помнят о нем.\n\nЧто ж, спасибо вам, Wrestlecake. Вот немного денег на покрытие ваших транспортных расходов.", rewards = "Вы получите:\n\n"},
[6282] = {title = "Угроза со стороны гарпий", objective = "Землепряд Маггран из Приюта у Солнечного Камня просит вас убить 7 гарпий, 7 душительниц, 7 душегубок и 7 бродяжниц из стаи Кровавой Ярости.", description = "Таурен горд тем, что защищает эти земли. Несомненно, ты понимаешь, почему я обеспокоен тем, что здесь, в Каменном Когте, обитает множество гарпий.\n\nКлан Смертельной Ярости – вот откуда берутся все новые и новые гарпии в Калимдоре. Они посягают на жизнь всех и каждого, не давая слабым даже уйти отсюда!\n\nМне нужна твоя помощь в уничтожении гарпий, <имя>!", progress = "Не дай Обугленной долине изнурить тебя, Клифбут. В тех холмах обитает множество злых существ. Сохраняй силы, и ты одолеешь угрозу, нависшую над нашим народом. Иди же, и рази без колебаний – пусть наши дети никогда не изведают этого зла.", completion = "Замечательные новости! Поведай мне вновь, как тебе удалось вселить ужас в холодные сердца злобных гарпий. Клан Смертельной Ярости понес серьезный урон!", rewards = "Вы получите:\n\n"},
[6283] = {title = "Предводительница клана Кровавой Ярости", objective = "Маггран из Приюта у Солнечного Камня просит убить Потрошительницу из стаи Кровавой Ярости и принести ему ее останки в доказательство того, что она мертва.", description = "Уменьшить число гарпий из стаи Кровавой Ярости – этого недостаточно. Единственное, чем можно извести эту заразу – это убить их предводительницу, Потрошительницу!\n\nСредь этих мерзостных существ она почти королева. Убей ее, и гарпий станет меньше.\n\nВозвращайся в Обугленную долину, и ты найдешь ее у западных холмов. Ее не так-то легко уничтожить, но награда будет велика.", progress = "Потрошительница из стаи Кровавой Ярости – ужасное существо! Ты, несомненно, найдешь ее у подножия западных холмов в Обугленной долине.\n\nБез нее гарпии будут бессильны... и мы уж точно сможем избавиться от них!", completion = "Я уже чувствую, как гнев покидает меня. Что мне теперь делать? Знание о том, что зло бродило поблизости от моих земель, заставляло мои мысли течь быстро, пусть и безмолвно. Быть может, это и к лучшему... быть может, теперь я смогу обратить свои мысли в сторону добра, как и положено таурену.\n\nПрошу тебя, прими это в награду за твои труды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nДушевный плащПояс Визгуна\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[6284] = {title = "Арахнофобия", objective = "Убейте Бесселет и принесите клык Бесселет Магграну в Приют у Солнечного Камня.", description = "Предупреждение: дорога отсюда на запад, в Сиширский каньон, опасна.\n\nБесселет и ее восьминогие отпрыски превратили этот каньон в свое логово, заплетенное паутиной.\n\nМаггран Связующий Землю из Приюта у Солнечного Камня назначил награду за Бесселет. Убей ее и принеси доказательство ее смерти Магграну – получишь награду за устранение этой восьминогой угрозы.", progress = "Бесселет – безжалостный хищник... Я опасаюсь за тех, кто путешествует по Паучему Тракту ночами. Именно тогда Бесселет и ее отродья охотятся на ничего не подозревающих путников. Я сам едва не стал жертвой ее полуметровых смертоносных клыков, но, к счастью, сумел отбиться и убежать. Я отдам что угодно за то, чтобы это чудовище было уничтожено.", completion = "Добрая охота, Демонорох! Бесселет издавна была угрозой для этих земель... и я не буду по ней тосковать. Возьми эту награду в знак того, что тебе удалось защитить наш лес.\n\n*Маггран потирает рану, нанесенную Бесселет.*\n\nБыть может, теперь больше народа будет приходить в Приют у Солнечного Камня, не боясь того, что крадется во мраке.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nАргилитовый короткий мечЧистый хрустальный жезл\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[6285] = {title = "Возвращение к Льюису", objective = "Оплатите укротителю грифонов Дунгару Долгопиву полет до Сторожевого холма, а затем отнесите ящик Озрика Льюису.", description = "Укротителем грифонов в Западном Крае работает Тор. Если вы с ним уже знакомы, то можете на одном из моих грифонов к нему долететь.\n\nПолезная для вас информация: грифоны обучены так, что до столицы могут долететь всегда, а к укротителям, расположенным в других местах, полетят, только если вы там уже бывали.\n\nВы ведь уже были у Тора, так что просто поговорите со мной еще раз, когда будете готовы лететь в Западный Край. А там уже отнесете ящик Озрика интенданту Льюису.", progress = "Вы уже вернулись из Штормграда? Озрик прислал доспехи?", completion = "Отлично, вы привезли доспехи! Мы распределим их между теми, кому они срочно необходимы.\n\nСпасибо вам, сэр Мэйнард. Вы нам очень помогли. А теперь, когда вы знакомы и с нашими грифонами, я надеюсь, вы будете часто прилетать к нам и предлагать свою помощь Сторожевому холму!", rewards = "Вы получите:\n\n"},
[6301] = {title = "Цикл возрождения", objective = "Таммра Перекати-поле из Приюта у Солнечного Камня просит вас собрать 10 семян Геи.", description = "Жадность промышленников и постоянная война опустошили земли Каменного Пика. Только благословение Матери-Земли может исцелить такие раны.\n\n<имя>, я хочу отправить тебя на поиски особого семени – семени Геи. Его можно найти только здесь, в Каменном Когте, к северу от Приюта у Солнечного Камня, у Мутного Озера, у самого края воды. \n\nКак только ты принесешь мне эти семена, я напитаю их шаманской силой, дабы ускорить их рост.", progress = "Страшные разрушения, причиненные войной и теми, кто наживался на лесозаготовках, глубоко ранят мою душу. Чтобы начать цикл возрождения и оживить эти земли, мне нужны семена Геи. Есть ли они у тебя, |3-6(Шаман)?", completion = "О, Ахахаха, так вот они – семена Геи! Смотри и увидишь, как благословение Матери-Земли даст этим крошечным семенам жизни возможность цвести и плодоносить.\n\n*Таммра начинает читать заклинание.*", rewards = "Вы получите:\n\n"},
[6321] = {title = "Поставка оружия", objective = "Отнесите заказ Подрига Каросу Раззоку.", description = "Исполнитель Хадрик попросил меня заняться нашим арсеналом в Гробнице. По лесу рыщут силы Плети, а то и кое-что похуже, и он хочет, чтобы у наших стражей смерти было достаточно оружия, когда оно понадобится. \n\nЯ выяснил, что в целом у нас все в порядке, но нам нужно дополнительное оружие взамен потерянного в боях. \n\nВот заявка на поставку для торговца оружием Гордона Уиндема, находящегося в Подгороде. Отнесите этот заказ нашему дрессировщику летучих мышей, Каросу Раззоку, и поговорите с ним о полете в Подгород.", progress = "Похоже, вы пришли по серьезному делу?", completion = "А, заказ на поставки. Не сомневаюсь, вам нужно доставить его в Подгород. И как можно скорее, потому что в Гробнице нельзя допустить нехватку оружия.", rewards = "Вы получите:\n\n"},
[6322] = {title = "Майкл Гарретт", objective = "Отправляйтесь к Майклу Гарретту с ящиком Гордона.", description = "Я сложил припасы для Гробницы в этот ящик. Если вы уже бывали в Гробнице и знакомы с тамошним дрессировщиком летучих мышей, то можете туда лететь. \n\nПоговорите с дрессировщиком летучих мышей здесь, в Подгороде – с Майклом Гарреттом. Он поможет вам добраться до Гробницы.", progress = "Если вам нужно преодолеть большое расстояние, удобнее всего сделать это на летучей мыши.", completion = "Этот ящик нужно доставить в Гробницу, что в Серебряном бору? Это легко: наши мыши ежедневно туда летают.", rewards = "Вы получите:\n\n"},
[6323] = {title = "Полет в Подгород", objective = "Оплатите у дрессировщика летучих мышей Кароса Раззока полет до Подгорода, а затем отнесите заказ Подрига Гордону Уиндему в Подгороде.", description = "Одна из моих летучих мышей может отвезти вас в Подгород, за небольшую плату. Приходите ко мне, когда будете готовы, чтобы мы могли организовать ваш полет. \n\nГордона Уиндема вы найдете в Торговом квартале Подгорода. Именно там и приземлится летучая мышь.", progress = "Я держу оружие в отличном состоянии. Все почищено и готово к использованию.", completion = "Заказ из Гробницы? Отлично. Для меня честь – услужить тем, кто служит Темной Госпоже.", rewards = "Вы получите:\n\n"},
[6324] = {title = "Обратно к Подригу", objective = "Оплатите у дрессировщика летучих мышей Майкла Гарретта полет до Гробницы, а затем отдайте ящик Гордона стражу смерти Подригу в Гробнице.", description = "Дрессировщика летучих мышей в Гробнице зовут Карос Раззок. Если вы уже знакомы с ним, я могу предоставить вам одну из своих летучих мышей, чтобы вы к нему вернулись. \n\nВсе наши мыши всегда могут долететь до Подгорода, но, чтобы добраться до более отдаленных мест, пассажир должен сначала посетить эти места и познакомиться с тамошними дрессировщиками. \n\nС Каросом вы уже встречались в Гробнице, так что теперь можете летать туда на мышах. Вернитесь ко мне, когда будете готовы к полету.", progress = "Вы вернулись, Соулнце. Привезли наши припасы из Подгорода?", completion = "Хорошая работа, Соулнце. Это оружие позволит не застать врасплох наших стражей смерти. \n\nВы сослужили хорошую службу Темной Госпоже.", rewards = "Вы получите:\n\n"},
[6341] = {title = "Изобилие Тельдрассила", objective = "Отнесите коллекцию Нессы к Веспристу.", description = "Рыбаки деревни Рут'теран живут очень хорошо: ведь рыба здесь очень крупная, и ее много. Я хотела бы сравнить здешнее изобилие с ситуацией в материковых водах.\n\nЯ собрала образцы рыбьих костей и чешуи, которые хотела бы отправить своему коллеге на Темный Берег. Его зовут Лайрд, он торгует рыбой в Аубердине.\n\nИдите с моей коллекцией образцов к нашему дрессировщику гиппогрифов, Веспристу, и поговорите с ним насчет полета в Аубердин.", progress = "Чем могу помочь? Нужен транспорт?", completion = "А, вы хотите доставить эту посылку в Аубердин? Отлично...", rewards = "Вы получите:\n\n"},
[6342] = {title = "Полет в Аубердин", objective = "Совершите полет в Аубердин на гиппогрифе укротителя Весприста и отнесите коллекцию Нессы Лайрду.", description = "Из деревни Рут'теран можно добраться в Аубердин двумя путями: на пароме и на гиппогрифе. Оба способа быстры и надежны, но если вы еще никогда не летали в Аубердин на гиппогрифе, я бы порекомендовал вам это сделать.\n\nМой вам добрый совет: говорите с дрессировщикам гиппогрифов в каждом городе, где они есть. Когда вы поговорите с дрессировщиком, то сможете летать в этот город из других мест.\n\nВозвращаю вам коллекцию Нессы. Поговорите со мной, когда будете готовы лететь в Аубердин и доставить коллекцию Лайрду.", progress = "Вы прибыли из Тельдрассила? Скажите, как там ловится рыба?", completion = "Посылка от Нессы? Спасибо, Фелниар! Она говорила, что собирается прислать мне образцы рыбы, пойманной близ деревни Рут'теран. Она думает, что эта рыба может серьезно отличаться от той, что ловится здесь...\n\nНичего себе! Эта челюсть чуть ли не вдвое больше, чем у таких же здешних рыб. А эта чешуя размером с кулак! Невероятно!", rewards = "Вы получите:\n\n"},
[6343] = {title = "Возвращение к Нессе", objective = "Принесите ответ Лайрда Нессе Песне Теней.", description = "Мне нужно отправить Нессе ответ. Ей будет очень интересно знать, насколько здешняя рыба отличается от той, что водится у берегов Тельдрассила. Мы можем лишь догадываться о причинах, но подозреваю, что так воздействует само Древо Жизни на окружающую его природу!\n\nПожалуйста, отнесите мой ответ Нессе. Если хотите лететь в Рут'теран на гиппогрифе, поговорите с дрессировщиком гиппогрифов Кайлаис Лунному Перу. А если хотите добраться паромом, то он регулярно отходит от причала к северо-западу отсюда.", progress = "Бракоделл, вы уже вернулись из Аубердина? Вы говорили с Лайрдом?", completion = "Все это очень интересно. Рыба здесь крупная, но я не думала, что разница между обитающими в материковых и здешних водах столь велика. Для этого должна быть причина...\n\nЧто ж, благодарю вас, Бракоделл. Я обсужу с земляками новости, что вы принесли. Может быть, когда-нибудь мы найдем причину этой странности. А пока будем ею пользоваться!", rewards = "Вы получите:\n\n"},
[6344] = {title = "Несса Песня Теней", objective = "Поговорите с Нессой Песня Теней.", description = "Моя подруга, Несса Песня Теней, торгует рыбой в деревне Рут'теран. Ей нужно доставить посылку на Темный берег, и она ищет кого-нибудь, кто мог бы ей помочь.\n\nЕсли вы хотите помочь Нессе, то ступайте в деревню Рут'теран через портал в Дарнассе. Портал находится к западу от Храмовых садов.", progress = nil, completion = "Да, мне нужен курьер, который доставит посылку на Темный Берег. Вы мне поможете?", rewards = "Вы получите:\n\n"},
[6361] = {title = "Связка шкур", objective = "Отнесите связку шкур Зарга укротителю ветрокрылов Девраку из Перекрестка.", description = "Я хочу переслать в Громовой Утес связку шкур степных зверей. Мой коллега, Ахану, занимается кожевенным делом и найдет им достойное применение.\n\nНе возьмешься доставить ему шкуры?\n\nДо Громового Утеса проще всего добраться на ветрокрыле. Отнеси шкуры укротителю ветрокрылов Девраку и поговори с ним насчет доставки в Громовой Утес.", progress = "Тебе нужн ветрокрыл? Собираешься доставлять какие-то товары?", completion = "Хочешь отвезти эти шкуры в Громовой Утес? Тогда ты обратился по адресу!", rewards = "Вы получите:\n\n"},
[6362] = {title = "Дорога до Громового Утеса", objective = "Оплатите перелет в Громовой Утес укротителю ветрокрылов Девраку и, оказавшись на месте, отнесите связку шкур Ахану.", description = "За небольшую плату ты можешь полететь в Громовой Утес на ветрокрыле. Быстрее не бывает!\n\nЕсли тебя устраивает цена – обращайся, когда решишь отправиться в путь.\n\nЕсли ты везешь эти шкуры Ахану, думаю, ты отыщешь его в оружейной Хевы, у основания башни ветрокрылов в Громовом Утесе. Именно там ты и приземлишься!", progress = "Судя по пыли на одежде, ты только что из Степей. Тебя мой друг Джахан прислал?", completion = "А, новая связка шкур. Я немедленно ими займусь.\n\nСпасибо, брат. Ты оказал мне большую услугу. Возьми эти монеты, чтобы покрыть дорожные расходы и потраченное время.", rewards = "Вы получите:\n\n"},
[6363] = {title = "Укротитель ветрокрылов Тал", objective = "Отнесите кожаные вещи Ахану Талу из Громового Утеса.", description = "Я приготовил кое-какие кожаные изделия на продажу в Перекрестке. Не отнесешь их Джахану?\n\nЕсли ты уже <поговорил/поговорила> с укротителем ветрокрылов в Перекрестке, можешь полететь туда на виверне.\n\nОтнеси мои товары здешнему укротителю ветрокрылов Талу и поговори с ним насчет дороги до Перекрестка.", progress = "Приветствую тебя, |3-6(Друид). Чем могу помочь?", completion = "Тебе нужно в Перекресток? Нет проблем. Если ты там уже побывал и поговорила с Девраком, можешь лететь на одном из моих ветрокрылов.", rewards = "Вы получите:\n\n"},
[6364] = {title = "Возвращение к Джахану", objective = "Оплатите перелет до Перекрестка у укротителя ветрокрылов Тала, а затем отнесите кожаные вещи Ахану Джахану Ястребиному Крылу.", description = "Чтобы полететь в какой-нибудь город, следует прежде побывать в нем и поговорить с укротителем ветрокрылов. В Перекрестке ты уже <побывал/побывала>, поэтому за небольшую плату ветрокрыл может отнести тебя туда.\n\nОбращайся, когда решишь отправиться в путь. Оказавшись в Перекрестке, отнеси кожаные вещи Джахану Соколиному Крылу.", progress = "Коровкинг, ты уже вернулся из Громового Утеса? Ахану получил мои шкуры?", completion = "Ахану прислал мне готовые изделия? Очень хорошо. В Перекресток забредает много охотников и искателей приключений, и дела у меня идут неплохо.\n\nСпасибо за помощь, Коровкинг. Я у тебя в долгу.", rewards = "Вы получите:\n\n"},
[6365] = {title = "Мясные продукты в Оргриммар", objective = "Отнесите мясные продукты Зарга Девраку из Перекрестка.", description = "Я хочу послать своей подруге несколько видов превосходных мясных продуктов. Ее зовут Гришка, она хозяйка таверны в Оргриммаре. Поможешь мне доставить мясо?\n\nДо Оргриммара проще всего добраться на ветрокрыле. Отнеси мясные продукты Девраку, укротителю ветрокрылов, и поговори с ним насчет доставки в Оргриммар.", progress = "Хочешь куда-то добраться в мгновение ока? Тогда ты обратился по адресу!", completion = "Тебе нужно доставить мясо в Оргриммар? Нет проблем. За небольшую плату тебя отнесет туда мой ветрокрыл.", rewards = "Вы получите:\n\n"},
[6381] = {title = "Новая жизнь", objective = "Посадите 10 семян Геи в земляные курганы Геи, а затем верните оставшиеся зачарованные семена Геи Таммре в Приют у Солнечного Камня.", description = "Вот видишь, <класс>, хотя эта земля глубоко изранена, круговорот жизни – великая сила. Теперь мы должны внести свой вклад и помочь этой силе. Посади эти семена в самой сердцевине разрушения, на западе, в Обугленной долине. Но берегись – там, в полумертвых землях, еще встречаются гарпии и злобные элементали огня.\n\n<имя>, возьми эти зачарованные семена Геи и посади их в кучки плодородной почвы. Круговорот жизни должен продолжаться!", progress = "Семена, посаженные тобою, очень сильны, они сопротивляются порче и помогут создать основу для других видов жизни. Они будут расти и расти, сначала не давая распозаться порче и исцеляя израненную землю, а затем, в один прекрасный день, вновь покроют земли Каменного Котя густыми лесами.\n\nВсе ли семена Геи израсходованы на эти посадки?", completion = "Это великая победа, свершенная ради здешних земель. Со временем произойдут и другие перемены: Торговая компания уберется отсюда вместе со своими пилами и топорами, разгневанные духи огня успокоятся, а гарпии будут изгнаны с этих земель.\n\nТолько тогда, Эфко, в Каменном Когте настанет истинный мир.\n\nТы совершил благое дело, |3-6(Разбойник); возьми один из этих предметов в награду за вклад в создание новой жизни.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСапоги Искателя ветраПерчатки Песчаного шпиля\n\nВы также получите:\n\n"},
[6382] = {title = "Большая охота", objective = "Поговорите с Сенани Громосерд на заставе Расщепленного Древа в Ясеневом лесу.", description = "Твоя сила производит впечатление, <класс>, а интерес к охоте дает надежды, что вскоре тебе можно будет поручить дичь покрупнее... И посерьезнее.\n\nОрда стремится подчинить себе и в политическом и в духовном смысле бескрайние дикие просторы Ясеневого леса. Если ты <готов/готова> проявить себя в непознанных еще землях, обратись к Сенани Громосерд на заставе Расщепленного Древа. Она находится к северу от тропы из Степей.", progress = nil, completion = "Добро пожаловать на новое пограничье, Гронгард. Ясеневый лес – край неограниченных возможностей, где юному |3-2(Воин) вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть.\n\nКак понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.", rewards = "Вы получите:\n\n"},
[6383] = {title = "Большая охота", objective = "Великая охота в Ясеневом лесу заключается в убийстве трех легендарных тварей. Ты можешь выследить их и испытать свои умения против их хитрости и силы. И в этом испытании ты, надеюсь, поймешь что-то и о себе. Вот эти чудища – медведь Топтыжень, ночной саблезуб Тенумбра и гиппогриф Острокоготь.\n\nЭти твари могучи, и, возможно, тебе понадобится помощь. Ели тебе удастся их одолеть, принеси мне доказательства своих подвигов.", description = nil, progress = nil, completion = nil, rewards = nil},
[6384] = {title = "Дорога до Оргриммара", objective = "Оплатите полет в Оргриммар укротителю ветрокрылов Девраку и, оказавшись в Оргриммаре, отнесите мясные продукты Зарга Гришке.", description = "Всего лишь за несколько монет ветрокрыл отнесет тебя в Оргриммар. Оказавшись там, отнеси мясные продукты Зарга Гришке. Ее постоялый двор располагается на аллее Силы неподалеку от небесной башни, где тебя высадит мой ветрокрыл.\n\nПоговори со мной, когда решишь отправиться в путь.", progress = "Какой вкусный запах! Ты часом не сырое мясо несешь?", completion = "О, чудесно! Какое отличное мясо! Оно ведь от Зарга, да? Этот орк знает, как завоевать женское сердце…\n\nОх, мне не терпится его приготовить. Но не слишком много! Мясо вкуснее, когда его подают редко, верно?", rewards = "Вы получите:\n\n"},
[6385] = {title = "Укротитель ветрокрылов Дорас", objective = "Отнесите письмо Гришки Дорасу из Оргриммара.", description = "Я написала Заргу письмо благодарности. Поможешь с доставкой? Если ты уже <поговорил/поговорила> с укротителем ветрокрылов в Перекрестке, то можешь полететь туда.\n\nИди с моим письмом к Дорасу, оргриммарскому укротителю ветрокрылов, и поговори с ним насчет полета до Перекрестка.", progress = "Тебе нужен ветрокрыл?", completion = "Тебе нужно доставить письмо в Перекресток? Да, мои виверны могут отнести тебя туда.", rewards = "Вы получите:\n\n"},
[6386] = {title = "Возвращение на Перекресток", objective = "Оплатите перелет в Перекресток укротителю ветрокрылов Доресу и, оказавшись на месте, передайте письмо Гришки Заргху из Перекрестка.", description = "Мои виверны могут отвезти тебя в самые разные края – при условии, что ты <сам/сама> там уже <был/была> и <говорил/говорила> с местным укротителем ветрокрылов.\n\nТебе уже доводилось бывать в Перекрестке, да и Деврака ты знаешь, так что, лети прямо к нему. Оказавшись в Перекрестке, ты сможешь передать Заргху письмо Гришки.\n\nКак будешь <готов/готова>, скажи.", progress = "Ты вернулся из Оргриммара? Гришак понравилось мясо?", completion = "Ха! Я так и знал, что ей понравится! Ничто так не нравится женщинам, как хороший сочный стейк!\n\nСпасибо, Демонорох. Ты оказал мне неоценимую услугу. Вот тебе плата за труды – и не удивляйся, если я приглашу тебя на свадьбу!", rewards = "Вы получите:\n\n"},
[6387] = {title = "Награды ученикам", objective = "Отнесите список Брока Торгруму Боррелсону в Телcамаре.", description = "Ко мне приходит немало молодых дворфов, мечтающих научиться горному делу. Что же нужнее всего шахтеру? Кирка!\n\nЯ составил список учеников, которые хорошо проявили себя на занятиях и заслужили почетную кирку. Отнеси этот список Голниру Твердопалу в Стальгорн. Он подготовит для меня эти кирки.\n\nПроще всего добраться до Стальгорна на грифоне, поэтому ступай с этим списком к нашему укротителю грифонов, Торгруму Боррелсону, и поговори с ним насчет полета в Стальгорн.", progress = "Надоел Телcамар? Решил слетать в другой город?", completion = "Тебе нужно отвезти это в Стальгорн, да? За небольшую плату я позволю тебе оседлать одного из моих грифонов, и он отнесет тебя прямо в город. Что скажешь?", rewards = "Вы получите:\n\n"},
[6388] = {title = "Грит Турден", objective = "Отнесите почетные кирки Гриту Турдену в Стальгорне.", description = "Вот почетные кирки для учеников Брока. Если ты уже <бывал/бывала> в Телcамаре, можешь полететь обратно на грифоне!\n\nОтнеси кирки нашему укротителю грифонов, Гриту Турдену, и поговори с ним насчет полета в Телcамар.", progress = "Похоже, ты собрался куда-то лететь. Хочешь нанять грифона?", completion = "Значит, тебе нужно в Телcамар? Не вопрос. Если ты там уже бывал и беседовал с Торгрумом Боррелсоном, можешь полететь к нему на грифоне.", rewards = "Вы получите:\n\n"},
[6389] = {title = "Чума на вашу лесопилку!", objective = "Выпустите термитов с Чумных земель на лесопилке Северного Кряжа и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Западные Чумные земли.", description = "Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели.\n\nПримериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу.", progress = "Тебе удалось, Сарт? Выпустил термитов? Нельзя допустить, чтобы в руках Алого ордена оказалась и лесопилки, и Дольный Очаг. Нет уж, пусть лучше останутся вовсе с пустыми руками. Они лишь умножают наши и без того многочисленные жертвы в последней войне. Нет им пощады!", completion = "Ха-ха, превосходно! Ты справился! Дух моего отца наконец сможет покоиться с миром, а уж я-то как доволен!\n\nСпасибо тебе! Проси что хочешь, чем смогу – помогу!", rewards = "Вы получите:\n\n"},
[6390] = {title = "Чума на вашу лесопилку!", objective = "Выпустите термитов с Проклятых земель на лесопилке Северного Кряжа и возвращайтесь к Микки Левину в Бастион в Тирисфальских лесах.", description = "Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели.\n\nПримериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу.", progress = "Тебе удалось, Томпсон? Выпустил термитов?\n\nМои близкие лишились работы, а кое-кто и жизни, и я не желаю, чтобы вдобавок место, где прошло мое детство, досталось этим мнимым святошам!", completion = "Спасибо тебе, Томпсон. У меня есть лишь эта монета... Но, думаю, ты получил удовольствие от самого процесса!", rewards = "Вы получите:\n\n"},
[6391] = {title = "Полет в Стальгорн", objective = "Заплатите укротителю грифонов Торгруму Боррелсону, долетите на грифоне до Стальгорна и отдайте список Брока Голниру Твердопалу.", description = "Всего за несколько монет один из моих грифонов отнесет тебя в Стальгорн. Там ты сможешь отдать список Брока Голниру Твердопалу. Его можно найти в гильдии горняков Тайной Горы. Она находится неподалеку от Великой Кузни Стальгорна, и именно там тебя высадит мой грифон!\n\nКогда решишь отправиться в путь, обращайся ко мне.", progress = "Чем я могу вам помочь, господин?", completion = "А, последний список лучших учеников Брока. Я уже подготовил почетные кирки, осталось выбить на них имена учеников...", rewards = "Вы получите:\n\n"},
[6392] = {title = "Возвращение к Броку", objective = "Заплатите укротителю грифонов Гриту Турдену, долетите на грифоне до Телcамара и отдайте почетные кирки Броку Камнекопу.", description = "За небольшую плату грифон отнесет тебя в Телcамар... если ты там уже <бывал/бывала>. Грифоны могут летать только туда, где ты <успел/успела> побывать. Не упускай случая поговорить со всеми укротителями грифонов, и получишь возможность прилететь к ним.\n\nТоргрума, дрессировщика грифонов Телcамара, ты уже <видел/видела>, поэтому можешь вернуться к нему. Оказавшись в Телcамаре, отнеси кирки Броку Камнекопу.\n\nКогда решишь тронуться в путь – обращайся ко мне.", progress = "А, Барабаха. Ты уже вернулся из Стальгорна?", completion = "А вот и кирки. Отлично! Я раздам их своим ученикам. Им, конечно, не терпится пустить их в ход в рудниках возле озера Лок Модан.\n\nБлагодарю за помощь, Барабаха. Я у тебя в долгу. Возьми эти деньги, они должны покрыть стоимость перелета.", rewards = "Вы получите:\n\n"},
[6393] = {title = "Война элементалей", objective = "Принесите 10 Огненных кристаллов Цунаману в приют Солнечного Камня.", description = "Совет Приливов послал меня объявить войну элементалям огня здесь, в Каменном Когте. Нептулон Приливный Охотник, повелитель всех элементалей воды, лично заинтересован в том, чтобы узреть погибель всех наших огненных сородичей.\n\n<имя>, ты можешь помочь мне высоко подняться во мнении Совета путем уничтожения элементалей огня в Обугленной долине. После смерти от этих элементалей остаются огненные кристаллы. Отдай их мне, и ты получишь награду.", progress = "Совет Приливов проявляет нетерпение. Они желают положить конец войне, которая вот уже не одну эпоху идет во всех измерениях. Мои собратья жаждут услышать новости о грандиозной победе над ненавистными элементалями огня. Где же огненные кристаллы, что так нужны мне?", completion = "Духи воды внутри меня булькают от восторга. Соулнце, я высоко ценю твой дар – славную победу, о которой я могу сообщить в Совет Приливов.", rewards = "Вы получите:\n\n"},
[6394] = {title = "Кирка Тазз'рила", objective = "Принесите штейгеру Тазз'рилу его кирку.", description = "<имя>, ты <добросовестный/добросовестная:r> <раса>. Можно доверить тебе еще одно дело?\n\nНе так давно я ходил искать минералы в грот к северу отсюда и забыл там свою любимую кирку. А когда я вернулся за ней, то обнаружил, что там уже полно кровожадных зверей! Не можешь ли ты сходить в грот Пылающего Клинка и раздобыть мою кирку?\n\nЯ ее оставил в зале с водопадами. Кирка моя заговоренная – она светится в темноте, так что найти ее будет нетрудно... только, боюсь, ее уже стерегут!", progress = "Ну что, Ахахаха, удалось тебе проникнуть в грот? А кирку мою нашел?", completion = "Она у тебя! Моя любимая кирка! Спасибо большое, Ахахаха! Ну, теперь главное – дождаться, когда мои батраки управятся с рубкой леса, – и можно снова искать минералы!", rewards = "Вы получите:\n\n"},
[6395] = {title = "Последнее желание Марлы", objective = "Отнесите останки Самуэля Фиппса на могилу Марлы, а затем вернитесь к ученице Элрет.", description = "Моя подруга Марла Фиппс жила до чумы со своим мужем Самуэлем, но когда пришла чума, Самуэль погиб... и вступил в ряды Плети. \n\nМарла избежала чумы, но погибла от рук собственного мужа, лишившегося разума. Однако так велика была ее любовь, что последним желанием ее было, чтобы Самуэль был похоронен рядом с ней. \n\nСамуэль Фиппс обитает теперь у разоренного лагеря близ дороги на северо-восток от Могильника. Убей его и выполни желание Марлы: похорони Самуэля в ее могиле, в первом ряду нашего кладбища.", progress = nil, completion = "Ты, Сиамнео, совершил сегодня доброе дело. Хотя наша борьба против армии Плети продолжается, будем надеяться, что Марла и Самуэль упокоятся с миром.", rewards = "Вы получите:\n\n"},
[6401] = {title = "Кайя жива!", objective = "Передайте хорошие новости Таммре Перекати-поле, живущей в Приюте у Солнечного Камня.", description = "Передай Таммре Перекати-поле, тетушке Кайи, живущей в Приюте у Солнечного Камня, добрые новости – Кайя жива! Мы думали, что она погибла во время того жестокого нападения на нашу деревню. Иди по дороге на запад, и придешь в Приют у Солнечного Камня.", progress = nil, completion = "Хвала духам, моя племянница Кайя жива! Это поистине добрая новость. Спасибо тебе, Ахахаха!", rewards = "Вы получите:\n\n"},
[6402] = {title = "Встреча в Штормграде", objective = "Отправьтесь в Штормград и подойдите к городским воротам. Поговорите с оруженосцем Роу, чтобы он сообщил маршалу Виндзору о вашем прибытии.", description = "Вы с Виндзором должны встретиться у ворот Штормграда.\n\nВиндзор расскажет такое, что все королевство содрогнется!\n\nИ не ходи туда <один/одна>, <имя>. Собери целую армию! Позови своих земляков. К оружию!", progress = nil, completion = "Пока мы не вступили в бой, собери армию. В конце концов, на дракона идем!", rewards = "Вы получите:\n\n"},
[6403] = {title = "Великий Маскарад", objective = "Сопроводите Реджинальда Виндзора через весь Штормград. Защитите его!", description = "Вот это было приключение, друг мой. Я перед вами в огромном, неоплатном долгу. Может быть, когда все будет кончено...\n\nКак уже доподлинно установлено вами, Леди Престор – это Ониксия, отродье Смертокрыла, сестра-близнец владыки Черной горы Нефариана.\n\nСлишком долго держала она наше королевство под контролем. Даже сам Верховный лорд – марионетка в ее руках... Это колдовство будет разрушено.\n\nНе надо бойтесь, вместе мы победим!\n\nВы готовы?", progress = "Я... мне... я был бессилен.", completion = "*Болвар держит в руках расколовшийся амулет.*\n\nМагия, содержавшаяся в нем, должна воскреснуть. Око дракона должно быть настроено.\n\nСамопожертвование Виндзора освободило наше королевство, но угроза, исходящая от Ониксии и ей подобных, никуда не делась.\n\nЭтот медальон удерживал в плену мои разум и тело. Он также давал мне доступ к собственному разуму Ониксии – к ее тайнам. Хотя эти воспоминания сейчас как будто в тумане, кое-что я помню.", rewards = "Вы получите:\n\n"},
[6421] = {title = "Ущелье Камнепадов", objective = "Обследуйте глубины пещеры в ущелье Камнепадов и принесите 10 кристаллов резонита для исследования Мор'рогалу в Приют у Солнечного Камня.", description = "Что-то не так здесь, в Каменном Когте. Чувствуешь ли ты непокой, витающий в воздухе, <имя>?\n\nК юго-востоку отсюда, в ущелье Камнепадов, есть пещера. Там кобольды отчаянно ищут редкие кристаллы резонита. Я прошу тебя принести оттуда образцы руды, чтобы я мог понять, что происходит в этой пещере. Помимо того, неплохо бы тебе обследовать глубины этой пещеры.\n\nИди же, <юный/юная:c> <класс>, мне очень важно знать, что за зло таится под этими горами.", progress = "Какие новости из Ущелья Камнепадов? Я вспомнил, что существует легенда, в которой говорится о резоните... Но не за что ухватиться. Быть может, узнав, что таится на дне пещеры, мы сможем пролить свет на их зловещие намерения.", completion = "О да! Это оно – кристалл резонита несет следы земной магии. Должно быть, кобольды, докопавшись до глубин, обнаружили там земельника.\n\nЛегенда утверждает, что земельники – это существа, созданные титанами. Именно с их помощью создана земная твердь, по которой мы ступаем. Угроза велика, нельзя не обращать на нее внимания.\n\n*Мор'рогал качает головой.*\n\nБыть может, я сумею наложить заклинание на эти куски руды, чтобы нарушить затею кобольдов.", rewards = "Вы получите:\n\n"},
[6441] = {title = "Рога сатира", objective = "Добудьте 16 рогов сатира для Пиксель на заставе Расщепленного Древа.", description = "Привет! Я ехала через Ясеневый лес в Кабестан и решила остановиться здесь, в Расщепленном Древе. Я никогда не упущу выгодного дельца, а тут оказывается, что рога сатира нынче пользуются в Кабестане большим спросом.\n\nЯ тут поспрошала, и оказывается, что сатиры с Ночной поляны, Сатирнаара и Ксавиана как раз носят такие рога, что мне надо. Мне эти сатиры не по зубам... но вот вам – наверняка!\n\nСкажите, сколько возьмете, добудьте мне рога, и я оплачу ваше потраченное время.", progress = "Надеюсь, вы поторопитесь добыть мне эти рога, Седативщик. Я скоро возвращаюсь в Кабестан!", completion = "Изумительные рога, Седативщик! Спасибо за помощь!\n\nО, а это вам за труды...", rewards = "Вы получите:\n\n"},
[6442] = {title = "Наги на Зорамском взморье", objective = "Принесите 20 голов наг из клана Зловещего Хвоста Марукайе на Зорамское взморье.", description = "Зло рыщет по побережью, <раса>.\n\nЗдесь покоится под волнами проклятый город Зорам, давно разрушенный и поглощенный морем. Разрушенный и почти забытый.\n\nТеперь в него непонятно почему вернулись наги. Но причина не так важна – мы должны защитить край, за который так упорно боролись.\n\nПринеси мне 20 их голов! Загони наг назад, в глубины моря!", progress = "Наг все больше и больше, Гронгард. Прошу, сделай это для меня.", completion = "Побольше бы нам таких, как ты, Гронгард. Спасибо за помощь.", rewards = "Вы получите:\n\n"},
[6461] = {title = "Кровопийцы", objective = "Ксен'Зилла из Малака'джина просит вас убить 10 ползун из густого мха и 7 моховых ядоплюев.", description = "Мы, тролли, тут, в Малака'джине, живем с земли, да и живем хорошо. В Каменном Когте есть на что поохотиться. \n\nТолько вот повадились к нам в последнее время незваные гости... по ночам пауки на наши стоянки нападают, хотят украсть нашу добычу. \n\nЕсли поможешь нам поубивать этих злобных тварей, мы, тролли Малака'джина, будем перед тобой в долгу. Тут, в Каменном Когте, пауки повсюду – ступай на север, и увидишь, о чем я толкую.", progress = nil, completion = "О, вот и славненько! Ну хорошо, авось сегодня к нам на ужин меньше незваных гостей налезет.\n\nТысяча благодарностей, Ахахаха. Мы у тебя в долгу навечно.", rewards = "Вы получите:\n\n"},
[6462] = {title = "Оберег троллей", objective = "Принесите 8 оберегов троллей Митсуве в форт Зорам'гар.", description = "Мои сородичи шли сюда со священными тролльскими оберегами, но фурболги Колючего Меха напали на них и перебили прежде, чем они успели добраться до Зорам'гара! Эти подлые фурболги!\n\nЯ горюю по убитым братьям и сестрам – но мы еще встретимся в загробной жизни. Однако, их тролльские обереги в нашем мире весьма ценятся. Меня бесит, что ими завладели фурболги!\n\n<имя>, ты <должен/должна> вернуть эти обереги! Они находятся в сундуках в Крепости Колючего Меха, в пещере на окраине Деревни Колючего Меха, к северу от Астранаара.", progress = "Ты нашел обереги, Ахахаха? Моя кровь кипит от гнева, что эти священные обереги в руках фурболгов!", completion = "Ты их нашел! О, благодарю тебя, Ахахаха! Ты представить себе не можешь, что ты сделал для меня. \n\nТролль без оберега что орк без боевых шрамов...\n\nПустое место, а не тролль.", rewards = "Вы получите:\n\n"},
[6481] = {title = "Пробуждение земельника", objective = "Откройте резонитовую емкость при помощи зачарованного кристалла резонита и затем убейте Гоггерока. Вернитесь к Мор'рогалу с новостями и зачарованным кристаллом резонита.", description = "Благодаря тебе, <класс>, мы узнали, что этой земле грозит великая опасность. Резонитовая емкость, найденная тобою в пещере, служит вместилищем для спящего земельника по имени Гоггерок. \n\nЯ изменил своей шаманской силой принесенные тобой кристаллы. Возьми кристалл резинита и разбей резонитовую емкость, где спит земельник.\n\nСразу после пробуждения Гоггерок будет ослаблен... Убей его, <имя>!", progress = "Я боюсь, что если мы не избавимся от этой угрозы немедленно, весь Каменный Коготь падет. Мощь земельника несравнима ни с какой другой. По пробуждении Гоггерок будет ослаблен долгим сном, и тебе следует воспользоваться этим. Иди же, Шимада!", completion = "Это хорошие новости, |3-6(Друид)! Я опасался того, что земельник может сделать с Калимдором.\n\nУничтожение Гоггерока было задачей, достойной истинного героя. Но тебе удалось справиться с этим, и теперь и Каменный Коготь, и Калимдор перед тобой в долгу, благородный |3-6(Друид).\n\nПрими это как заслуженную и достойную награду.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНаручи СовобородаНакулачники Волчьей гривы\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[6482] = {title = "Свободу Руулу!", objective = "Сопроводите Руула, затем поговорите с Ями Снежное Копыто на заставе Расщепленного Древа.", description = "А? Ты кто?\n\n<имя>? Ты не фурболг. Они прокляты! Они подумали, что я медведь, и схватили меня, а теперь морят голодом! Я погибаю...\n\nПомоги мне сбежать, затем поговори с моей сестрой Ями на заставе Расщепленного Древа к востоку отсюда.\n\n<имя>! Мне надо сбежать!", progress = nil, completion = "Ты нашел моего брата! Его схватили фурболги Колючего Меха? Какая страшная весть! Хотя многие фурболги существа благородные, эти – извращенные твари.\n\nСпасибо за спасение брата, Шауе. Страшно подумать, как они обходились с бедняжкой Руулом! Наверняка после таких испытаний он будет долго спать...", rewards = "Вы получите:\n\n"},
[6501] = {title = "Око дракона", objective = "Найдите существа, способные вернуть силу фрагменту амулета Ока дракона. Все, что об этих существах известно – это то, что они есть.", description = "Фрагмент расколотого амулета – это все, что я могу вам предложить.\n\nВам придется найти еще одного дракона, который согласится помочь вам в изготовлении нового ключа. Как только вы добудете этот ключ, вам нужно будет отправиться в Драконьи топи в Пылевых топях. Там вы и найдете ее логово, <имя>.\n\nГде найти других драконов, готовых помочь? К сожалению, я не знаю... Говорят, что такие существуют. Некоторые из них могут даже жить среди нас в обличии людей, гномов или эльфов, например. Желаю вам удачи в поиске.", progress = "Я чувствую, что ты излучаешь недобрую ауру, |3-6(гном). Что у тебя может быть с собой такого, что обладало бы такой аурой?", completion = "Я должна была догадаться – часть плоти царицы черных драконов, Ониксии. Какая мерзость…", rewards = "Вы получите:\n\n"},
[6502] = {title = "Амулет Пламени дракона", objective = "Добудьте кровь могучего черного дракона генерала Драккисата, которого можно найти сидящим на троне в залах Вознесения в Пике Черной горы.", description = "Это – заколдованная драконья чешуя. Целая чешуйка открывает проход в драконье логово, а в сломанном виде она бесполезна.\n\nЕе можно починить, но для этого требуется кровь могучего черного дракона. Есть один такой... Его зовут генерал Драккисат, он возглавляет армию драконидов Нефариана. Тебе доводилось о нем слышать?\n\nВозвращайся с его кровью, <раса>, и я наложу чары на этот осколок. Тогда ты сможешь проникнуть в Логово Ониксии.", progress = "Река времени никогда не прекращает и не замедляет свой бег, |3-6(ночной эльф). Моя жизнь бесконечна, но твоя – нет. Не теряй даром времени...", completion = "Этот амулет поможет тебе достичь цели. Гнездо Ониксии ты найдешь в Пылевых топях. Пока амулет с тобой, ее стражи не смогут препятствовать тебе.\n\nСиние драконы желают тебе удачи, Лорегон.", rewards = "Вы получите:\n\nАмулет Пламени дракона"},
[6503] = {title = "Вестницы Ясеневого леса", objective = "Убейте 9 вестниц Ясеневого леса, а затем вернитесь к Курай'бину на заставу Расщепленного Древа.", description = "Мы получили донесение, что вестницы Ясеневого леса не так давно покинули Аванпост Среброкрылых и теперь шныряют в лесу у наших границ. Нам не надо, чтобы они разнюхивали что да как с нашей обороной!\n\nПроникни в лес к югу отсюда и к востоку от альянсовского Аванпоста Среброкрылых. Найди и перебей лазутчиц, а потом возвращайся.", progress = "Жду отчета о деле с лазутчицами, Шаматруль.", completion = "Очень хорошо, Демонорох. Твое охотничье мастерство впечатляет...\n\nПотеря лазутчиц малость притупит нюх Альянса, а ежели им разведданных не хватит, то вряд ли они нападут.", rewards = "Вы получите:\n\n"},
[6504] = {title = "Утраченные страницы", objective = "Найдите 12 пропавших страниц руководства по использованию резака и соберите их по порядку глав 1, 2 и 3. Верните страницы Гурде Печати Гнева близ заставы Расщепленного Древа.", description = "Этот резак я только что получила из Кабестана и как раз возвращалась на лесозаготовки Песни Войны, на свое рабочее место. Мне дали нструкцию к резаку, но по дороге назад у меня ее вырвало из рук порывом ветра. Все страницы разлетелись, и осталась у меня одна обложка.\n\nГде теперь эти страницы носит, одним предкам ведомо... Но как я резаком-то без них пользоваться буду? Не найдешь ли их для меня?", progress = "Надеюсь, ты быстро найдешь эти страницы, Всёводном! Мне очень надо скорее вернуться к работе!", completion = "Не сильна я в чтении... Но теперь я могу вернуться к работе! Спасибо, Всёводном!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nРабочие перчатки измельчителяПовязки Масляного лоскута\n\nВы также получите:\n\n"},
[6521] = {title = "Нечестивый союз", objective = "Принести голову посла Малкина Вариматрасу в Подгород.", description = "Повелеваю тебе убить посланника Малкина – я не позволю ему выполнить волю Короля-лича. Он пишет, что ждет встречи где-то поблизости от Курганов Иглошкурых.\n\nЕго присутствие там многое объясняет. Сила тамошних иглогривов многократно увеличилась, и среди них отмечаются признаки чумы. Очевидно, они заключили с Малкином какое-то соглашение.\n\nНайди и убей Малкина, <имя>. Возвращайся ко мне, когда испонишь мое повеление.", progress = "Ты нашел посланника, Большойзмей? Надеюсь, он мертв? Мы не можем позволить Плети закрепиться в Калимдоре. Довольно и того, что они постоянно осаждают наши границы – не хватало еще отбиваться от них на двух фронтах! Единственное, что радует меня в принесенных тобой вестях, – что старая ведьма, похоже, не подверглась скверне. В глубине души она понимала, что Плеть может наделить ее огромной властью, и все же осознавала, что, заключи она союз с нежитью, Степи перестанут быть ее истинной вотчиной.", completion = "Прекрасно. Ты хорошо поработал, |3-6(Воин). \n\nТеперь, после смерти Малкина, мы по крайней мере можем быть уверенными, что продвижение Плети будет остановлено. Темная Госпожа благодарит тебя за преданность и изволит одарить тебя. \n\nПока нам неизвестно, насколько прочные позиции заняла Плеть в холмах Железной Осоки, однако не сомневаюсь – скоро нам удастся разузнать их замыслы.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПробиватель череповГвоздометОдеяние фанатика\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[6522] = {title = "Нечестивый союз", objective = "Отнесите маленький свиток Вариматрасу в Подгород.", description = "Госпожа моя,\n\nНаше предложение вам прекрасно известно. Для вас это отличная возможность получить безграничную власть над Степью и окрестными землями. От вас нам требуется лишь небольшое содействие – вам нужно всего лишь дать нам свободу действий в этих землях.\n\nМы убедительно просим вас рассмотреть это предложение и обсудить его с нами. За нами великая сила, и мы с охотой поделимся ею с теми, кто достаточно мудр, чтобы примкнуть к нам. Я буду ждать вас у Курганов Иглошкурых.\n\nС наилучшими пожеланиями,\nПосланник Малкин.", progress = "С чем пожаловал, Тарчёк? Надеюсь, это действительно важное дело – я не люблю, когда мне докучают по пустякам.", completion = "Я узнаю знак на этом свитке, Тарчёк. Говоришь, нашел это у старухи, правящей в Лабиринтах Иглошкурых? Любопытно. \n\nПохоже, Плети мало одного континента. Посол Малкин – тот, кто написал письмо, – один из служителей Плети. Он был человеческим послом в Лордероне, прежде чем... все переменилось. \n\nЕсли Плеть в самом деле пытается закрепиться в Калимдоре, нам пора что-то предпринять.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6523] = {title = "Защита Кайи", objective = "Проводите Кайю Плоское Копыто до Лагеря Апарахе, затем вернитесь к Макабе Плоскому Копыту, находящемуся поблизости от юго-восточного края Каменного Когтя.", description = "Спасибо большое за спасение! Мы должны уходить побыстрее, прежде чем они обнаружат, что я на свободе. Я прошу сопроводить меня до Лагеря Апарахе. Оттуда я уже знаю, куда идти.\n\nМой отец, Макаба Плоское Копыто, наверное, уже отчаялся узнать, где я.", progress = nil, completion = "Кайя жива! Ахахаха, я благодарю тебя за ее спасение!", rewards = "Вы получите:\n\n"},
[6541] = {title = "Донесение Кадраку", objective = "Доложитесь Кадраку в сторожевой башне в северных Степях.", description = "Ты когда-нибудь <бывал/бывала> в Ясеневом лесу, на севере? Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ.\n\nЕсли тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне. Он руководит кампанией в Ясеневом лесу и может дать тебе поручение.", progress = nil, completion = "Ясеневый лес – разделенный войной край, но наши недавние усилия увенчались успехом. Мы основали заставу не только на Зорамском взморье, но еще прямо к северу отсюда построили заставу Расщепленного Древа.", rewards = "Вы получите:\n\n"},
[6542] = {title = "Донесение Кадраку", objective = "Доложитесь Кадраку в сторожевой башне в северных Степях.", description = "Ты когда-нибудь <бывал/бывала> в Ясеневом лесу, на севере? Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ.\n\nЕсли тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне. Он руководит кампанией в Ясеневом лесу и может дать тебе поручение.", progress = nil, completion = "Ясеневый лес – разделенный войной край, но наши недавние усилия увенчались успехом. Мы основали не только заставу на Зорамском взморье, но и еще прямо к северу отсюда построили заставу Расщепленного Древа.", rewards = "Вы получите:\n\n"},
[6543] = {title = "Отчет Песни Войны", objective = "Распакуйте связку донесений. Доставьте отчеты Песни Войны разведчику, гонцу и всаднику клана Песни Войны. Возьмите у них новые донесения для Кадрака и доставьте ему в северную сторожевую башню в Степях.", description = "Недавно я отправил в Ясеневый лес нескольких разведчиков. Мне нужен гонец, чтобы доставить им приказы и вернуться с отчетом об их наблюдениях.\n\nПервый твой пункт – форт Зорам'гар, что на западном побережье на Зорамском взморье. Там ты найдешь первого гонца. Так же тебе придется заглянуть на заставу Расщепленного Древа, что на севере и к востоку по дороге близ Азшары. Там найдешь разведчика и сопровождающего.\n\nПередай каждому указания и забери у них новые донесения.", progress = "Торопись, Гронгард. Они должны получить указания, это срочно.", completion = "Вижу, на тебя можно положиться. Эти новые сведения чрезвычайно важны для осуществления планов по расширению нашего присуствия в Ясеневом лесу. Теперь мы можем разработать следующий шаг.", rewards = "Вы получите:\n\n"},
[6544] = {title = "Налет Торека", objective = "Сопровождайте Торека при нападении на Аванпост Среброкрылых и в сражении с Дариэлем Лунным Пламенем, затем доложитесь Эртогу Лютоклыку на заставе Расщепленного Древа.", description = "Эй! <класс>! Иди-ка сюда!\n\nМы с ребятами хотим напасть на Аванпост Среброкрылых на западе. Наша цель – их командир, Дариэль Лунное Пламя. Разведчики говорят, что форт здорово защищен, там полно часовых и воинов. Славная будет драка!\n\nХочешь помочь нам, <имя>, и разделить нашу славу? Если пойдешь с нами, то когда победим, сможешь доложить о наших успехах моему начальнику, Эртогу Лютоклыку. Ты найдешь его в Расщепленном Древе.\n\nЧто скажешь? Пойдешь с нами?", progress = nil, completion = "Значит, Тореку дельце удалось! Хорошая работа, Ахахаха. Ночные эльфы – достойные враги. Худоваты на вид, но сильные да яростные! Видать, драка была красивая, посмотреть бы... \n\nНадеюсь, парочку шрамов-то ты заработал?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПолированный дорожный посохБулатная сабля\n\nВы также получите:\n\n"},
[6545] = {title = "Сведения гонца клана Песни Войны", objective = "Так у тебя есть для меня приказ? Всегда приятно увидеть новобранца с горячей душой и твердой волей.\n\nТебе нужна хорошая соображалка, если хочешь задержаться здесь. Наги все сильнее угрожают нам, Ахахаха. Я сам видел. А с тех пор как я сюда прибыл, мне несколько раз приходилось отбивать их нападения на этой самой заставе.\n\nНо если тебе охота поучаствовать в этом, поговори с кем-нибудь еще на заставе.", description = nil, progress = "Так у тебя есть для меня приказ? Всегда приятно увидеть новобранца с горячей душой и твердой волей.\n\nТебе нужна хорошая соображалка, если хочешь задержаться здесь. Наги все сильнее угрожают нам, Ахахаха. Я сам видел. А с тех пор как я сюда прибыл, мне несколько раз приходилось отбивать их нападения на этой самой заставе.\n\nНо если тебе охота поучаствовать в этом, поговори с кем-нибудь еще на заставе.", completion = "Что же, в моих последних донесениях Кадраку все подробно описано. Возвращайся к нему как можно быстрее.", rewards = "Вы получите:\n\nСведения гонца клана Песни Войны"},
[6546] = {title = "Сведения всадника из клана Песни Войны", objective = "На этой дороге путника подстерегает много опасностей, Ахахаха. Помни это, путешествуя по этим землям. Альянс не дремлет!\n\nКругом враги. На востоке Ясеневого леса самой жуткой и могучей силой являются сатиры. Еще я узнал, что наги захватили большой кусок земли в Азшаре.\n\nПриятно, что мы получаем подкрепление. Будь всегда наготове, Ахахаха.", description = nil, progress = "На этой дороге путника подстерегает много опасностей, Ахахаха. Помни это, путешествуя по этим землям. Альянс не дремлет!\n\nКругом враги. На востоке Ясеневого леса самой жуткой и могучей силой являются сатиры. Еще я узнал, что наги захватили большой кусок земли в Азшаре.\n\nПриятно, что мы получаем подкрепление. Будь всегда наготове, Ахахаха.", completion = "Доставь мое донесение Кадраку, Ахахаха. И побыстрее.", rewards = "Вы получите:\n\nСведения всадника из клана Песни Войны"},
[6547] = {title = "Сведения разведчика клана Песни Войны", objective = "Держи ухо востро, |3-6(орк). В тенях часто скрываются эльфы...\n\nМы должны быть начеку постоянно. Нам слишком тяжело достались эти земли, и эльфы всегда ищут случая отнять их у нас.\n\nКак я понимаю, у тебя есть очередное поручение для меня от Кадрака?", description = nil, progress = "Держи ухо востро, |3-6(орк). В тенях часто скрываются эльфы...\n\nМы должны быть начеку постоянно. Нам слишком тяжело достались эти земли, и эльфы всегда ищут случая отнять их у нас.\n\nКак я понимаю, у тебя есть очередное поручение для меня от Кадрака?", completion = "Передай Кадраку, что мы тут успешно сдерживаем ночных эльфов. Все идет согласно плану.", rewards = "Вы получите:\n\nСведения разведчика клана Песни Войны"},
[6548] = {title = "Отомсти за мою деревню", objective = "Убейте 8 бузотеров и 6 наемников из племени Зловещего Тотема, затем вернитесь к Макабе Плоскому Копыту, ожидающему вас на юго-восточной границе Когтистых гор.", description = "Клан Зловещего Тотема напал на мою деревню и убил почти всех жителей. Я сразил столько нападавших, сколько мог, но едва спас собственную жизнь.\n\n<имя>, всё, чего я желаю – это чтобы как можно больше этих негодяев умерло. Ты найдешь их к западу отсюда.", progress = "Тебе удалось их убить?", completion = "Демонорох, я благодарю тебя... но я никогда не забуду того, что клан Зловещего Тотема сделал с моей деревней.", rewards = "Вы получите:\n\n"},
[6561] = {title = "Жестокость Черных Глубин", objective = "Принесите голову Повелителя сумрака Келриса Башане Руническому Тотему в Громовой Утес.", description = "Силы оставили меня. Мне необходима твоя помощь!\n\nВ давние времена на этом месте был храм Элуны. К несчастью, он был разрушен, когда порча Древнего бога просочилась из-под земли и осквернила священный лунный колодец.\n\nАку'май, слуга Древнего бога, поднялся из глубин.\n\nСектанты Сумеречного Молота объединились с нагами в борьбе за эти земли. Сектанты, ведомые Келрисом, приносят Аку'май невинные жертвы.\n\nУбей Келриса и принеси его голову Башане в Громовой Утес, <имя>.", progress = "Да пребудет с тобой милость Матери-Земли, Шауе. \n\nМы должны стремиться к гармонии и согласию во всем мире. Все происходит по воле Матери-Земли, и все мы – орудия в ее руках.", completion = "Келрису много раз удавалось ускользнуть от Серебряного Рассвета. \n\nЕго считали мертвым или пропавшим без вести.\n\nПоложив конец его власти, ты спас жизнь многих, Шауе. \n\nСлава Матери-Земле! Нет прощенья тем, кто приносит невинные жертвы Древнему Богу! \n\nТы совершил великий подвиг, Шауе. Келрис был порождением зла, он стремился повергнуть наш мир в хаос, поклоняясь Старым Богам. Благодарю тебя, Шауе.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nНадгробный скипетрАрктический кулачный щит\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[6562] = {title = "Угроза из Глубин", objective = "Поговорите с Дже'неу Санкри в Ясеневом лесу.", description = "Дже'неу Санкри нужна помощь. Он в форте Зорам'гар в Ясеневом лесу. Этот лес ночных эльфов находится к северу от Когтистых гор. Ты можешь добраться до него через Утес Ветрорезов или идя на север через Степи. Зорамское взморье лежит далеко на западе от леса. Будь <осторожен/осторожна>, <имя>. Там обитают такие силы, от которых теплого приема не жди.", progress = nil, completion = "Тебя послал Цунаман? Великолепно. Тогда нам есть что обсудить.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6563] = {title = "Сущность Аку'май", objective = "Принесите 20 сапфиров Аку'май Дже'неу Санкри в Ясеневый лес.", description = "В начале туннелей Непроглядной Пучины по стенам пещер можно найти большие сапфировые друзы. Недавно было замечено, что эти кристаллы собирают наги. Пока не станет ясно, зачем им это, сдается мне, что надо наг этой возможности лишить. В кристаллах этих содержится великая сила стихий, и если их применить не как должно, то они могут стать мощным чародейским ингредиентом.\n\nТы мне не поможешь, <имя>? Непроглядная Пучина находится на Зорамском взморье к северу от нашей заставы.", progress = "Как поиски кристаллов, Шауе? Ты видел, как наги их собирают? Я молю своих предков, чтобы нам удалось понять, зачем им это.", completion = "Хорошая работа, Шауе. Это те самые кристаллы, о которых я говорил. Как интригующе...\n\nЯ чувствую в них силу. К ним тянутся духи воды. Для чего бы наги ни собирались их использовать... Ладно, хорошо, что они больше не в их руках.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6564] = {title = "Верность Древним богам", objective = "Принесите отсыревшую записку Дже'неу Санкри в Ясеневый лес.", description = "На смятом обрывке бумаги кое-как нацарапано :\n\n\"Да, вели всем жрицам приносить мне эти кристаллы. В них обитают могучие духи элементалей воды, и они весьма помогут нашим аквамантам в призывании духов.\n\nОвладев силой, заключенной в кристаллах, мы сумеем умилостивить Аку'май. И однажды настанет день, когда мы накопим достаточно сил, чтобы вернуть Аку'май к нам, и мир вернется в величайшую свою эпоху! Эпоху власти Древних богов!\"", progress = "Да, Пухмен? В чем дело? Мне еще многое нужно узнать об этих кристаллах, что собирают наги.", completion = "Это и правда интересно. Я рад, что ты принес мне эту записку.\n\nТеперь мы знаем, как зовут причину наших бед... Лоргус Джетт!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6565] = {title = "Верность Древним богам", objective = "Убейте Лоргуса Джетта в Непроглядной Пучине и вернитесь к Дже'неу Санкри в Ясеневый лес.", description = "Мы не можем допустить, чтобы этот последователь Сумеречного Молота выполнил свой план. Клан Сумеречного Молота не понимает духов Природы. Они верят в Древних богов – богов хаоса и разрушения, побежденных давным-давно. Нельзя дать этому Лоргусу добиться своего! Ты <должен/должна> оставновить его, <имя>. Мне самому этого не сделать – я слишком слаб.\n\nСтупай в Непроглядную Пучину, найди и убей его! А потом возвращайся в Зорам'гар.", progress = "Ты еще не нашел его, Несмеро? Лоргуса надо остановить!", completion = "Прекрасно!!! Хвала тебе, Тузвколоде. Может, мы и не окончательно разобрались с Сумеречным Молотом, но по крайней мере один их план по возвращению в могуществе своем Древних богов мы нарушили.\n\nКто знает, какие еще замыслы них на уме, но пока мы можем вздохнуть свободно.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо КулакаОплечье Гнедого\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[6566] = {title = "Что принес ветер", objective = "Выслушайте Тралла.", description = "Рад видеть тебя снова, <имя>. Ветер принес вести из Восточного королевства.\n\nСадись и слушай.", progress = "Терпение, Стиммакс. Слушай внимательно!", completion = "Готов ли ты взять на себя эту задачу?", rewards = "Вы получите:\n\n"},
[6567] = {title = "Защитник Орды", objective = "Найдите Рексара. Вождь сказал, что он бродит в Пустошах, по дороге, что ведет из Когтичтых гор в Фералас.", description = "Рексар, один из самых преданных моих защитников, нашел путь в логово дракона. Разыщи его.\n\nОн скитается по Пустошам, что раскинулись между Когтистыми горами и Фераласом. Он уже знает, что ты придешь.", progress = nil, completion = "В драконье логово можно проникнуть только одним способом.\n\nНу, разумеется, если ты не почетный член их клана.\n\nНо и тогда тебе пришлось бы пройти немало испытаний и получить ключ, заколдованный самим генералом Драккисатом.\n\nНо раз уж ты не черный дракон, все будет несколько сложнее.\n\n&lt;Рексар ухмыляется.&gt;", rewards = "Вы получите:\n\n"},
[6568] = {title = "Завет Рексара", objective = "Доставьте письмо Рексара Миранде Колдунье в Западные Чумные земли.", description = "<имя>, а что ты знаешь об иллюзиях? Ведь только иллюзия поможет тебе обмануть черных драконов и добыть то, что ты ищешь.\n\nЯ знаю, кто смог бы тебе помочь. В она не раз помогала нам и поможет тебе, если сочтет твои цели достойными.\n\nОтправляйся в Западные Чумные земли и разыщи Миранду Колдунью. Когда-то она была мастером иллюзий Алянса Лордерона, но ее изгнали. Вот, отнеси ей это послание, она все поймет.", progress = "Нечасто приходится видеть выходцев из Орды в этой части Лордерона. Ну, с чем же ты пришел к Миранде?", completion = "&lt;Миранда берет записку и через некоторое время улыбается.&gt;\n\nКак он? Я про Рексара. Ой, к чему удивление? Письмо не просто так оставлено пустым. Ведь главное – это мысли и поступки того, кто его отправил. Да и, судя по обстоятельствам, Рексар не мог ничего написать. Представь, если бы тебя поймали или убили, и важная информация досталась бы врагу!\n\nНо все хорошо. Миранда поможет тебе, нежить. У меня должок перед вождем.\n\n&lt;Миранда улыбается.&gt;", rewards = "Вы получите:\n\n"},
[6569] = {title = "Иллюзии Ока", objective = "Отправляйтесь на пик Черной горы и добудьте 20 глаз черных драконидов. По выполнении задания вернитесь к Миранде Колдунье.", description = "Значит, <раса> <возжелал/возжелала> войти в Черное Племя?\n\nСоздать необходимую тебе иллюзию – пара пустяков. Куда труднее собрать компоненты, необходимые для наложения этих чар. Раз Вождь поручил тебе такую миссию, Миранде остается повиноваться.\n\nОтправляйся в верхнюю часть крепости на пике Черной горы и убей столько черных драконидов, чтобы набить заплечные мешки их глазами.\n\nКогда наберешь достаточно, возвращайся к Миранде.", progress = "Самое главное для создания любой иллюзии – глаза тех, кого мы хотим изобразить, Стиммакс.\n\n*Миранда указывает на мешок, до отказа набитый глазами. Надпись на нем гласит \"Алый орден\".*\n\n*Миранда хохочет.*", completion = "Дай-ка Миранде посмотреть, |3-6(орк).\n\nО, да, отличные глаза.\n\nТеперь Миранда сделает для тебя медальон, который создаст иллюзию, при помощи которой ты сможешь обмануть привратника Черного Племени.", rewards = "Вы получите:\n\n"},
[6570] = {title = "Огнебор", objective = "Отправляйтесь в Драконьи топи в Пылевых топях и найдите Логово Огнебора. Оказавшись внутри, наденьте амулет Обмана драконов и поговорите с Огнебором.\n\nПрилагается предмет: \n", description = "Благодаря этому медальону в пределах логова Огнебора ты будешь сохранять нужный облик.\n\nОгнебор – старый дракон, древний привратник Нефариана. На него возложена обязанность испытывать тех драконов, которые должны войти в элитную стражу Ониксии.\n\nОтправляйся в Драконьи топи в Пылевых топях и войди в его логово. Оказавшись внутри, надень амулет, и следуй за своей судьбой!", progress = nil, completion = "Неужели у нас иссякли хорошие бойцы? Зачем Нефариан присылает мне детенышей? Тебе не пройти испытания, мелочь пузатая.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6571] = {title = "Поставка для Песни Войны", objective = "Соберите полностью поставку Песни Войны: лезвия для пил, веревку для бревен, масло и партию топоров Песни Войны для Локе Окарра на заставе Расщепленного Древа.", description = "Нам на лесозаготовках Песни Войны страшно не хватает кое-чего!\n\nУ Пиксель на заставе Расщепленного Древа наш груз лезвий для пил. За ящиком топоров от управляющего пристанью Подгребая придется сгонять в Пиратскую бухту. \n\nА получить груз масла и веревок будет еще труднее. Веревку стянули фурболги Колючего Меха и Гиблой Чащи, а сатиры перехватили партию масла, и теперь изводят его на свои гадкие ритуалы на Ночной поляне, Сатирнааре и Ксавиане!\n\nТы мне поможешь?", progress = "Надеюсь, ты с грузом? У меня будут большие неприятности, если я не доставлю все как можно скорее!", completion = "Замечательно, Ахахаха! Ты избавил меня от больших забот!\n\nНо не думай, что я буду неблагодарен!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКушак Песни ВойныСапоги Песни ВойныРукавицы Песни Войны\n\nВы также получите:\n\n"},
[6581] = {title = "Пилы Песни Войны", objective = "Прямо из Кабестана, свеженькие лезвия для пил Песни Войны! Да, они у меня с собой.\n\n..Но чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!\n\nЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защищать себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.\n\nИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?", description = nil, progress = "Прямо из Кабестана, свеженькие лезвия для пил Песни Войны! Да, они у меня с собой.\n\n..Но чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!\n\nЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защищать себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.\n\nИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?", completion = "Само совершенство – то, что надо! Ладно, вот груз.", rewards = "Вы получите:\n\nЛезвие пилы Песни Войны"},
[6582] = {title = "Черепа: Провидец", objective = "Найдите в Зимних Ключах избранного бойца синих дракона по имени Провидец и убейте его. С его черепом вернитесь к Огнебору.", description = "Все мы дети Смертокрыла, ничтожество. И наша власть над младшими аспектами должна укрепиться.\n\nЕсли ты действительно <достоин/достойна> возвышения, то другие драконы должны дрожать от одних звуков твоего имени. Найди их вожаков и сокруши во имя нашего Отца!\n\nОтправляйся в Зимние ключи и найди там дракона по имени Провидец. Убей его и любого синего дракона, кто осмелится встать на твоем пути, и принеси мне его череп.", progress = "*Огнебор шипит*", completion = "Одно исссс нессскольких ссаданий иссполнено...", rewards = "Вы получите:\n\n"},
[6583] = {title = "Черепа: Сомнус", objective = "Убейте вожака зеленых драконов Сомнуса и вернитесь с его черепом к Огнебору.", description = "Так же как наш отец сокрушил самих Аспектов, так и мы должны сеять хаос и страх среди их детей.\n\nТы <должен/должна> доказать свою боеспособность перед бессонно грезящими, я говорю о племени зеленых драконов.\n\nОтправляйся в трясины Скорби и порази вожака зеленых драконов Сомнуса. Не сдерживай своей ненависти, раздави его как червяка, и вернись ко мне с его черепом.", progress = "Не смей возвращаться, пока не омоешь рук в крови наших врагов и не упьешься их страданиями.", completion = "Еще один мертв...", rewards = "Вы получите:\n\n"},
[6584] = {title = "Черепа: Хроналис", objective = "Убейте Хроналиса, охраняющего Пещеры Времени в Пустыне Танарис и вернитесь с его черепом к Огнебору.", description = "Дозорные Времени, дети Ноздорму – Повелителя Вечноссссти...\n\nТрое из них охраняют Пещеры Времени, но только один из этих троих представляет интерес для черных драконов: Изменяющий время Хроналис, любимый отпрыск Нодзорму. Расправьсссся с ним так, чтобы даже песок в его часах рыдал от ужаса, и вернись ко мне с его черепом.", progress = "Забавно, не правда ли, птенчик? Время как оно есссть...", completion = "Оссталссся только один... Самый ненависссстный...", rewards = "Вы получите:\n\n"},
[6585] = {title = "Черепа: Акстроз", objective = "Отправьтесь в Грим Батол и убейте Акстроза, избранного бойца красных драконов. Принесите его череп Огнебору.", description = "Над горами Грим Батола отец наш бился против объединенных сил Аспектов. Но коварное предательство Алекстразы дало им возможность избежать его гнева.\n\nПосссзорное пятно на иссстории нашшшего рода.\n\nТеперь Грим Батол стерегут красные драконы. Их военачальник Акстроз должен быть убит, а его череп доставлен мне. Вперед, птенчик! За нашего Отца!", progress = "Я вижу в тебе ссследы перемен, птенчик. Ты прошшел иссспытание, осстался один обряд.", completion = "Я сомневался, стоишь ли ты посвящения, птенчик. Но ты выказал немалое упорство, побеждая наших врагов и добывая честь нашему роду. Теперь я должен подготовить черепа для твоего возвышения.", rewards = "Вы получите:\n\n"},
[6601] = {title = "Вознесение", objective = "Казалось бы, загадка разгадана. Ты знаешь, что амулет обмана драконов, который сделала для тебя Миранда Колдунья, не будет работать на пике Черной горы. Найди Рексара и расскажи о возникших затруднениях. Покажи ему амулет угасающего пламени дракона. Будем надеяться, он знает что делать.", description = "Из черепов наших врагов сделан медальон. Ты его ссснаешшь, не правда ли? Ты несомненно <видел/видела> его на ваших старейшинах.\n\nВозьми его, птенчик, отнеси на Пик и отдай генералу Драккисату. Генерал наложит на него последнее заклятье, чтобы настроить амулет на тебя.\n\nТы будешь носить его как знак доблести, обозначающий твою принадлежность к одному из самых привилегированных слоев нашего общества, Защитникам Царицы Драконов.\n\nИди же!", progress = "Стиммакс! Без паники!", completion = "Пара медных грошей стоят больше чем вся эта драконья болтовня, Стиммакс. На твоем месте, я не придавал бы столько значения их словам, некоторое хвастовство присуще всему их роду.", rewards = "Вы получите:\n\n"},
[6602] = {title = "Кровь могучего черного дракона", objective = "Отправляйтесь к пику Черной горы и убейте генерала Драккисата. Соберите его кровь и вернитесь к Рексару.", description = "Как насчет того, чтобы нанести визит генералу? На этот раз – никаких иллюзий и прикрытий.\n\nЦеремония?.. Весьма изящное определение для той кровавой бойни, которой так любят услаждать себя черные драконы.\n\nВсе, чего недостает этому амулету – кровь генерала Драккисата. Весьма примитивная защита. Я расскажу тебе, как разрешить эту маленькую проблему.\n\nОтправляйся к пику Черной горы и прикончи Драккисата. Принеси мне его кровь, и я активирую ключ от Логова Ониксии.", progress = "Драккисата не так легко победить, Стиммакс. Об этом могли бы свидетельствовать тысячи, павшие по его вине...", completion = "&lt;Рексар ухмыляется.&gt;\n\nЭту победу будут помнить много лет, можешь мне поверить, Стиммакс. Амулет Пламени Дракона отркоет тебе путь в Логово Ониксии. Собирай своих союзников: я верю, ты принесешь Орде новую победу!", rewards = "Вы получите:\n\nАмулет Пламени дракона"},
[6603] = {title = "Сложности в Зимних ключах!", objective = "Найдите Донову Снегонору у горячего источника в Зимних ключах.", description = "В Зимних ключах какая-то заваруха!\n\nЯ некоторое время жила в тех диких местах и в этих вещах разбираюсь... Я всегда с гордостью это говорю. По мне, так время, что я прожила в холмах, прямо-таки золотое времечко. Помогает развивать быстроту рефлексов, сохранять холодную голову и держать ухо востро...\n\nЧтобы так разбираться в ситуации в диких краях, как я, надо быть зрелым и иметь хорошие мозги.\n\nЛадно, о чем, бишь, я?\n\nА, да, заваруха. Найди Донову Снегонору у горячих источников, и она расскажет тебе побольше.", progress = nil, completion = "О, привет! Значит, Мегги рассказала тебе о моих трудностях?", rewards = "Вы получите:\n\n"},
[6604] = {title = "Взбесившиеся дикие совухи", objective = "Поговорите с Джероном Гранильщиком в деревне Звездопада.", description = "Вы заметили заброшенный лагерь к югу отсюда? Такое впечатление, что дикие совухи сошли с ума и уничтожили все, до чего смогли дотянуться! \n\nЯ слыхал, что один из выживших после этой атаки сейчас приходит в себя в деревне Звездопада, к западу отсюда. Мне очень любопытно, что же там произошло... а вам нет?", progress = nil, completion = "Слушаю, чем могу быть полезен?", rewards = "Вы получите:\n\n"},
[6605] = {title = "Странная дамочка", objective = "Поговорите с Винной Хезард в Оскверненном лесу.", description = "Я только что вернулся из Оскверненного леса, <имя>. По пути я останавливался на Заставе Отравленной Крови, и познакомился с одной очень странной дамочкой… Казалось, она зациклилась на одной вещи и, полагаю, я мог бы сказать вам, на чем именно, но думаю, лучше она сама вам это объяснит. \n\nЕсли вам стало интересно, отправляйтесь на Заставу Отравленной Крови, в западной части Оскверненного леса и поищите Винну Хеззард.\n\nКто знает, может быть, ей нужна ваша помощь...", progress = nil, completion = "О, |3-6(Жрец). Вижу, еще есть надежда. Ты здесь, чтобы мне помочь?", rewards = "Вы получите:\n\n"},
[6606] = {title = "Немного удачи", objective = "Поговорите со знахаркой Мау'ари в Кругозоре.Немного удачи никому не повредит, так ведь? Иногда даже крошечного преимущества достаточно, чтобы обратить все в свою пользу...\n\nНедавно мне довелось познакомиться с одной довольно эксцентричной особой. Она сделала мне счастливый амулет... не бесплатно, разумеется. Но, поверь уж мне, он того стоит!\n\nМожет, тебе тоже такой нужен? Найди знахарку Мау'ари в Кругозоре. Свой амулет я тебе не отдам!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Немного удачи никому не повредит, так ведь? Иногда даже крошечного преимущества достаточно, чтобы обратить все в свою пользу...\n\nНедавно мне довелось познакомиться с одной довольно эксцентричной особой. Она сделала мне счастливый амулет... не бесплатно, разумеется. Но, поверь уж мне, он того стоит!\n\nМожет, тебе тоже такой нужен? Найди знахарку Мау'ари в Кругозоре. Свой амулет я тебе не отдам!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[6607] = {title = "Экстремальная рыбалка Ната Пэгла", objective = "Поймайте для Ната Пэгла следующих рыб:\nМахи-махи с берега Туманных Тростников на Болоте Печали. \nУдарник Сартериса с побережья Сар'Терис из Пустошей.\nФералас-ахи из реки Вердантис из Фераласа.\nСиний плавник Гибельного берега из Тернистой долины.\nПо выполнении вернитесь к Нату Пэглу.", description = "Не скажу, что мне так уж нравится рыбачить. Последний раз мне этим приходилось заниматься 20, а то и 30 лет назад. \n\nЛюди занимаются своим делом по разным причинам.\n\nЯ не говорю, что ты <должен/должна> убить на рыбалку 30 лет, или выловить всю рыбу в этом море, чтобы стать хорошим рыбаком. Я думаю, тебе просто надо собраться и решиться несколько часов просиживать зад на берегу, ничего не делая.\n\nВот что я тебе скажу, поймай мне несколько редких рыб из этого списка, и я взамен научу тебя кой-чему.", progress = "Ну как, сегодня клев был?", completion = "Вот это, я понимаю, улов!\n\nПоди сюда, дай-ка я тебе покажу пару трюков.", rewards = "Вы изучите:\n\nРыбная ловля\n\nСледующее заклинание будет наложено на вас:\n\nРыбная ловля (искусник)\n\nВы также получите:\n\n"},
[6608] = {title = "Больше учить нечему", objective = "Похоже, Лумак хочет сказать, что ему больше нечему вас учить. Возможно, стоит найти его друга Ната Пэгла – человека, который удит рыбу на островах к югу от Терамора. Кажется, Лумак имеет в виду именно это.", description = "Лумак больше не может тебя учить, <имя>. Нечему больше учить тебя. Найди друга Лумака, Ната Пэгла. Он человек, не еда! Нат друг Лумака! Он тебя научит ловить рыбу лучше.\n\nНата можно найти в Пылевых топях, к югу от Тераморо... как его там. Он, наверное, удит рыбу. Иди!", progress = nil, completion = "Так ты че, друг Лумака?\n\nРыбная ловля? Чего я о ней не знаю, того и знать не стоит!", rewards = "Вы получите:\n\n"},
[6609] = {title = "С меня больше нечего взять!", objective = "Отправляйтесь на Калимдор, в приморский город Терамор. Там к югу от города найдите остров. Нат Пэгл уже ждет.", description = "Я же дворф, <парень/подруга>, это ж без очков видать! Не мое дело рыбу ловить! Ты только глянь на меня! Я ж, считай, каменный!\n\nС меня больше нечего взять – все тебе отдал! Я тебя научил всему, что умел, балда!\n\nЕще не <понял/поняла>? А, да ладно. Есть у меня старый дружок в Калимдоре, который сможет тебе помочь. Его зовут Нат Пэгл, он хороший парень. Ищи его на островах к югу от Терамора. Ну, топай!", progress = nil, completion = "У меня на островке всегда найдется место для гостей... Насколько помню...", rewards = "Вы получите:\n\n"},
[6610] = {title = "Мидии с сюрпризом", objective = "Могиль Быстроруб поручил принести ему следующее:\n\n12 гигантских яиц. Их можно отыскать у рухов Танариса или других крупных птиц.\n\n10 кусков острого мяса моллюсков. Разумеется, его добывают у моллюсков!\n\n20 кусков альтеракского сыра. Из сыроварни!\n\nСобрав все составляющие, возвращайтесь к Диргу.", description = "Тебе случалось слышать о мидиях с сюрпризом? Конечно же нет! Это мой последний кулинарный шедевр. Ах, от одной мысли слюнки текут.\n\nК сожалению, у меня кончились все припасы, и я не могу его сделать! Хочешь сделку? Принеси мне нужные продукты, а я поучу тебя готовить, и даже дам парочку омлетов с мидиями! <Согласен/Согласна>??\n\nВот, что мне нужно:", progress = "Мне скоро конец придет от голода! Быстрей, Эфром – а то мне придется залезть в собственную заначку.", completion = "Вот ты полакомишься, Эфром. Смотри и учись!\n\n*Дирг начинает готовить мидии с сюрпризом.*", rewards = "Вы изучите:\n\nКулинария\n\nСледующее заклинание будет наложено на вас:\n\nКулинария (искусник)\n\nВы также получите:\n\nМидии с сюпризом"},
[6611] = {title = "Ступай в Прибамбасск!", objective = "Отправляйтесь в Прибамбасск в пустыне Танарис и поговорите с Могилем Быстрорубом.", description = "Как может Замджа научить тебя всему на свете? Ты знаешь все кулинарные заговоры Замджи и требуешь новых!\n\nЗамджа ничем помочь не может. Пусть <толстый/толстая:r> <раса> пойдет в Прибамбасск. Найдешь там мелкого гоблина по имени Могиль – вот он тебе и поможет, обжора.\n\nКогда станешь великим поваром – вернешься, научишь Замджу всему, что знаешь, а? Ну, ступай, ступай.", progress = nil, completion = "*Дирг выплевывает ошметки кожаной сандалии.*\n\nОх! Фу! Тьфу!*Дирг долго откашливается.*\n\nВ чем дело? Ты разве не знаешь, что в коже очень много белка и чрезвычайно мало углеводов? Ничего, узнаешь еще!", rewards = "Вы получите:\n\n"},
[6612] = {title = "Я знаю одного парня...", objective = "Пойдите в Прибамбасск в пустыне Танарис и поговорите с Могилем Быстрорубом насчет продвижения в поварской карьере.", description = "Судя по твоему половнику, ты знаешь, чего хочешь. Да вот научить мне тебя нечему.\n\nНо тебе свезло, я знаю одного парня. Он гоблин, и считается первым поваром Калимдора.\n\nДа, <приятель/подруга>, придется тебе податься до Калимдора. Иди-ка в Прибамбасск и сыщи Могиля Быстроруба. Он тебя прямиком и направит.", progress = nil, completion = "*Дирг выплевывает кожу.*\n\nТьфу...\n\n*Дирг громко кашляет.*\n\nНу? Известно ли тебе, что в коже чрезвычайно много белка и мало углеводов, |3-6(дворф)?", rewards = "Вы получите:\n\n"},
[6621] = {title = "Король Гиблой Чащи", objective = "Водрузите знамя Каранга на тотемном кургане Гиблой Чащи. Не дайте фурболгам унитожить знамя. Одолейте вождя Мургута и принесите тотем Мургута Карангу Амаккару в Зорам'гар.", description = "<имя>, к юго-востоку от Астранаара живет еще одно племя фурболгов, Гиблая Чаща. Они не так многочисленны, как Колючий Мех, но их ярость в будущем может представлять угрозу. Продемонстрировав им силу, мы сможем эту угрозу ликвидировать.\n\nБери этот штандарт, иди в деревлю Гиблой Чащи и поставь его на их тотемном кургане. Они попытаются уничтожить штандарт, но ты держись, пока не появится их вождь, Мургут. Он захочет отстоять честь племени. Принеси мне тотем, что будет на нем.\n\nСобирай друзей, <имя>. С этим делом <класс>-одиночка не справится.", progress = "Ты победил вождя Мургута, Шауе? принес его тотем Гиблой Чащи?", completion = "Хорошая работа, Шауе. Бросив вызов Гиблой Чаще и победив их вождя, ты крепко вдолбил в их головы:\n\nС Ордой шутки плохи.\n\nТеперь это племя долго не осмелится досаждать нам.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМундир грубиянаКобальтовые набедренники\n\nВы также получите:\n\n"},
[6622] = {title = "Очередь на медобслуживание", objective = "Окажите помощь пациентам, используя для перевязки их ран очередные перевязочные бинты. Вы должны оказать помощь 15 пациентам прежде, чем 6 из них успеют умереть от ран.\n\nПомните о порядке оказания помощи! Находящиеся при смерти солдаты умирают быстрее, чем тяжелораненые. Легкораненые живут дольше всех, потому им надо оказывать помощь ПОСЛЕ того, как перевяжете тех, кто при смерти, и тяжелораненых.", description = "Добрый день, доктор. Вы должны будете пройти тест на оказание срочной медицинской помощи. Если тест будет пройден успешно, вы вольетесь в ряды наших лучших травматологов.\n\nА теперь внимание! Раненые, находящиеся в критическом состоянии, должны получить помощь первыми. После критически раненых следует перевязать тяжелых пациентов. Потом можно заняться и обычными ранеными. Для прохождения теста вам нужно спасти 15 пациентов. Если 6 пациентов умрут, так и не дождавшись перевязки, испытание будет провалено.\n\nДля этого теста вам будут предоставлены специальные бинты.\n\nУдачи, доктор.", progress = nil, completion = "Доктор Стиммакс, добро пожаловать в ряды травматологов Орды.", rewards = "Вы изучите:\n\nПервая помощь\n\nСледующее заклинание будет наложено на вас:\n\nПервая помощь (искусник)\n\nВы также получите:\n\n"},
[6623] = {title = "Травматология", objective = "Пойдите в Павший Молот на нагорье Арати и поговорите с доктором Грегори Виктором о том, чтобы стать травматологом.", description = "Доктор <имя>, я так понимаю? Рад новой встрече.\n\nУ меня для тебя замечательные новости. Доктор Грегори Виктор, главный травматолог Орды, предлагает тебе поработать у него в Павшем Молоте. Такой шанс выпадает раз в жизни! Лично я отдал бы все на свете за возможность поработать под руководством великого Грегори Виктора! Не упусти свою удачу!", progress = nil, completion = "Отлично. Надевайте халат, работа не ждет!", rewards = "Вы получите:\n\n"},
[6624] = {title = "Очередность перевязки", objective = "Окажите помощь пациентам, используя для перевязки их ран очередные перевязочные бинты. Вы должны оказать помощь 15 пациентам прежде, чем 6 из них успеют умереть от ран.\n\nПомните о порядке оказания помощи! Находящиеся при смерти солдаты умрут быстрее, чем тяжелораненые. Легкораненые могут прожить дольше всех, потому им надо оказывать помощь ПОСЛЕ того, как перевяжете тех, кто при смерти, и тяжелораненых.", description = "Здравствуйте, доктор. Вам сегодня предстоит пройти испытание на очередность оказания помощи раненым. Если вы успешно пройдете этот экзамен, вы будете приняты в ряды престижного сообщества травматологов Альянса.\n\nА теперь слушайте внимательно! Сначала необходимо оказать помощь тяжелораненным. После – тем, у кого ранения средней тяжести. Последними идут легкораненные. Вы должны оказать помощь 15 пациентам. чтобы пройти этот экзамен. Если 6 ваших пациентов после оказания им помощи скончаются, экзамен будет считаться проваленным.\n\nУдачи, доктор.", progress = nil, completion = "Доктор Маркуру, Добро пожаловать в ряды травматологов Альянса!", rewards = "Вы изучите:\n\nПервая помощь\n\nСледующее заклинание будет наложено на вас:\n\nПервая помощь (искусник)\n\nВы также получите:\n\n"},
[6625] = {title = "Травматологи Альянса", objective = "Отправляйтесь в Терамор в Пылевых топях и поговорите с доктором Густавом ван Схлиффом насчет зачисления в травматологи Альянса.", description = "Полагаю, вы доктор <имя>. Приятно познакомиться.\n\nУ меня есть для вас замечательная новость! Густаф Ванхорцен, главный врач-травматолог Альянса, делает вам личное предложение приехать к нему в Терамор. Такая возможность выпадает раз в жизни! Я бы все отдала за возможность учиться у великого доктора Густафа Ванхорцена! Не упустите возможности, доктор!", progress = nil, completion = "Чудесно. Мойте руки, и сразу начнем!", rewards = "Вы получите:\n\n"},
[6626] = {title = "Воинство зла", objective = "Убейте 8 боевых стражей и 8 терноплетов из племени Иглошкурых, а также 8 сектанток из племени Мертвой Головы и возвращайтесь к Мириам Лунной Певице на Курганы Иглошкурых.", description = "Отрекшиеся не стремятся превратить смертных в себе подобных... насколько мне известно. Однако этот посланник, видимо, охотно превращает в нежить всех желающих. Я начинаю думать, что на самом деле он работает на Плеть.\n\nОднако сейчас меня больше беспокоит не он, а его последователи, число которых все возрастает. Я вижу,что каждые день из тьмы выползают все новые и новые его приспешники, пресмыкающиеся перед ним в жажде власти.\n\nЯ слишком слаба, чтобы справиться с ними, <имя>. Помоги мне.", progress = "Как охота, Шэдоустайл? Глядя на то, что творит это посланник в наших землях, я перестаю сомневаться, что Плеть представляет самую страшную угрозу нашему миру с самого его сотворения.", completion = "Спасибо, Большойзмей. Ты оказал мне неоценимую помощь! Я продолжу наблюдать за посланником и иглогривами. Если же ты ищешь более серьезных противников, собери соратников и отправляйся к пещере, напоминающей кабанью утробу. Не сомневаюсь, внутри скрываются создания, с которыми будет интересно померяться силами столь великому воителю.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6627] = {title = "Испытание знаний", objective = "Дайте верный ответ на вопрос Брауга Тусклого Духа и поговорите с ним еще раз. Брауга можно в любое время найти в Когтистых горах.", description = "Ты <принес/принесла> мне книгу, и я должен задать тебе вопрос. Ты <готов/готова>?\n\nСпешить нам некуда, так что не торопись. Можешь ответить мне в любое время.", progress = "Жизнь полна вопросов, |3-6(Охотник). Тебе никогда не удастся ответить на все, но если не будешь пренебрегать обучением, то сможешь слегка увеличить свои знания.", completion = "Отличная работа, |3-6(Маг). Ты изучил книгу как следует и прошел еще одно наше испытание.", rewards = "Вы получите:\n\n"},
[6628] = {title = "Испытание знаний", objective = "Дайте верный ответ на вопрос Парквела Финталласа и поговорите с ним еще раз. Парквелла можно в любое время найти в Подгороде.", description = "Вот мы и встретились снова. Ты <проявил/проявила> недюжинные способности при прохождении моих испытаний, и теперь мне осталось только задать тебе последний вопрос.\n\nКогда будешь <готов/готова>, подойди и поговори со мной, но перед этим как следует подготовься. Спешить нам некуда.", progress = "Я считаю, что для выживания в этом мире нужно помнить только одно правило: чем больше знаешь, тем больше видишь.\n\nУчись, наблюдай, и тогда разглядишь то, чего никто другой не увидит |3-6(нежить).", completion = "Отличная работа, Томпсон. Я сомневался, что у тебя хватит терпения изучить этот текст, но ты дал верный ответ.", rewards = "Вы получите:\n\n"},
[6629] = {title = "Убить Грундига Темное Облако", objective = "Убейте Грундига Темное Облако и 6 громил из племени Зловещего Тотема и вернитесь к Макабе Плоскому Копыту, который ждет вблизи юго-восточного края Каменного Когтя.", description = "Что ж, <имя>, с негодяями из клана Зловещего Тотема тебе удалось расправиться отлично. Но Грундиг Темное Облако и его личная банда громил куда хуже. Именно он возглавлял то жестокое нападение на мою деревню.\n\nЕсли осмелишься, то найдешь его на Заставе Зловещего Тотема чуть дальше по дороге на запад. Убей его, и я буду вечно тебе признателен.", progress = nil, completion = "Грундиг Темное Облако мертв! Ахахаха, за это деяние я буду вечно признателен тебе!", rewards = "Вы получите:\n\n"},
[6641] = {title = "Ворша Хлестунья", objective = "Охраняйте Муглаша на его пути к жаровне. Помогите ему погасить жаровню, а затем защищайте его, ведя бой с нагами.\n\nЕсли вам все удастся, возвращайтесь в форт Зорам'гар и сообщите гонцу клана Песни Войны о смерти Ворши Хлестуньи.", description = "Ворша Хлестунья... это омерзительная гидра, что рыщет в морях...\n\nОна нападает на нашу заставу почем зря, уничтожая все на своем пути.\n\nНо я готов драться, <имя>. Я готов уничтожить гидру и положить конец ее нападениям на Зорам'гар.\n\nНаги почитают эту гадкую тварь и поддерживают в ее честь пламя на жаровне, что находится на острове у побережья. Думаю, если мы ее загасим, то разъяренная Ворша вылезет из моря.\n\nНам понадобится помощь, так что приведи крепких друзей.", progress = nil, completion = "С тех пор, как я сюда прибыл, я пережил много нападений наг. Мне прямо легче на душе становится от мысли, что Ворша больше не будет разгуливать где ей вздумается.\n\nМы в большом долгу перед тобой, Ахахаха.", rewards = "Вы получите:\n\nРоговое кольцо"},
[6642] = {title = "Покровительство братства, черное железо", objective = "Хотя черное железо в изобилии водится в Глубинах, оно высоко ценится в братстве. Священное оружие Рагнароса куется именно из него.\n\nЗа каждые 10 кусков руды черного железа, которые ты пожертвуешь братству, наградой тебе будет наше доброе отношение.", description = nil, progress = "Хотя черное железо в изобилии водится в Глубинах, оно высоко ценится в братстве. Священное оружие Рагнароса куется именно из него.\n\nЗа каждые 10 кусков руды черного железа, которые ты пожертвуешь братству, наградой тебе будет наше доброе отношение.", completion = "Твой дар приняли и оценили. Ты заслужил добрую славу. Если братство удостоверится в твоей преданности, тебе дадут доступ к тайнам древних ремесел.", rewards = nil},
[6643] = {title = "Покровительство братства, огненное ядро", objective = "Горе тем, кто искушает судьбу и безоглядно бросается в Огненные Недра. Кара за дерзость – мгновенная смерть, каковая не ведает жалости.\n\nМногие братья расстались с жизнью, отправившись на поиски огненных ядер.\n\nПожертвуй братству огненное ядро, и можешь рассчитывать на наше доброе отношение.", description = nil, progress = "Горе тем, кто искушает судьбу и безоглядно бросается в Огненные Недра. Кара за дерзость – мгновенная смерть, каковая не ведает жалости.\n\nМногие братья расстались с жизнью, отправившись на поиски огненных ядер.\n\nПожертвуй братству огненное ядро, и можешь рассчитывать на наше доброе отношение.", completion = "Твой дар приняли и оценили. Ты действительно достоин доверия братьев. Думаю, рано или поздно ты получишь доступ к тайнам древних ремесел.", rewards = nil},
[6644] = {title = "Покровительство братства, ядро лавы", objective = "Братство Тория помогает только тем, кто заслужил нашу дружбу и уважение, |3-6(таурен). Собственно поэтому Локтоса и уполномочили заключить с тобой договор.\n\nПожертвуй братству ядро лавы, и можешь рассчитывать на нашу помощь.", description = nil, progress = "Братство Тория помогает только тем, кто заслужил нашу дружбу и уважение, |3-6(таурен). Собственно поэтому Локтоса и уполномочили заключить с тобой договор.\n\nПожертвуй братству ядро лавы, и можешь рассчитывать на нашу помощь.", completion = "Твой дар приняли и оценили. Теперь мы видим, что ты действительно ищешь дружбы с нами. Если ты заслужишь добрую славу в братстве, мы поделимся с тобой тайнами древних ремесел.", rewards = nil},
[6645] = {title = "Покровительство братства, сердцевинная кожа", objective = "Во многих священных рецептурах упоминаются шкуры питомцев Рагнароса.\n\nПожертвуй братству два куска сердцевинной кожи, снятой с псов Недр из Огненных Недр, – и заслужишь добрую славу.", description = nil, progress = "Во многих священных рецептурах упоминаются шкуры питомцев Рагнароса.\n\nПожертвуй братству два куска сердцевинной кожи, снятой с псов Недр из Огненных Недр, – и заслужишь добрую славу.", completion = "Твой дар приняли и оценили. Многие братья относятся к тебе с уважением. Если ты заслужишь почет в братстве, мы поделимся с тобой тайнами древних ремесел.", rewards = nil},
[6646] = {title = "Покровительство братства, кровь горы", objective = "Слезы Повелителя огня – поистине великая редкость.\n\nПожертвуй братству кровь горы, и можешь рассчитывать на наше доброе отношение.", description = nil, progress = "Слезы Повелителя огня – поистине великая редкость.\n\nПожертвуй братству кровь горы, и можешь рассчитывать на наше доброе отношение.", completion = "Твой дар приняли и оценили. Если заслужишь доверие братства, тебе дадут доступ к тайнам древних ремесел.", rewards = nil},
[6661] = {title = "Охота на крыс", objective = "Поймайте 5 подземных крыс, используя Флейту крысолова, и принесите их Монти. Не забудьте вернуть флейту владельцу.", description = "Эй ты, стой, да? Ррры!.. Зарррработать хочешь? У нас тут большая проблема с крысами и не хватает умелых рук.\n\nЧто ты там болтаешь? Все, что от тебя требуется – взять эту флейту крысолова и сыграть подходящую мелодию. Они пойдут за тобой хоть на край света!\n\nНо это лишнее – ты просто поймай пяток и принеси, они нужны нам живыми.\n\nРрррр...", progress = "Аррр... Мы еще долго будем ждать?", completion = "Ха, хорошо сделанная работенка, молодец! Моему братцу они нужны свеженькими, чтобы приготовить из них котлеты.", rewards = "Вы получите:\n\n"},
[6662] = {title = "Братишка Нипси", objective = "Отвезите Нипси в подземное депо Штормграда коробку таинственного мяса.", description = "Мой братишка Нипси занимается производством котлет из подземных крыс на том конце подземки. Надо, чтобы ты доставил этот ящик с крысами к нему, пока они не протухли. Так что давай, двигай!\n\nТы ведь ездил раньше на поезде, да? Это очень просто. Заходи, когда поезд прибудет – и наслаждайся поездкой. Главное, не высовывай руки-ноги, не то на всю жисть калекой останешься.", progress = "*Нипси просовывает указательный палец в одно из отверстий для доступа воздуха, проделанных в коробке.*\n\nЖивенькие-здоровенькие... и как раз вовремя!", completion = "Бедняга Монти. После того, что случилось в Гномрегане, он сам на себя не похож. Этот парень океана в жизни не видал, а туда же – в пираты метит.\n\n*Нипси вздыхает.* Ну, по крайней мере, он обеспечивает непрерывные поставки этих дерганых тварей.", rewards = "Вы получите:\n\nШашлык из подземной крысы"},
[6681] = {title = "Поместье, Черный Ворон", objective = "Отнесите печать Черного Ворона Фахраду в поместье Черный Ворон, сокрытое среди холмов Хилсбрада.\n\nНе теряйте бдительности. Поиски поместья – проверка на ловкость.", description = "<имя>,\n\nЧерный Ворон очень заинтересовался тобой, <юный вор/юная воришка>. Мы наблюдали. Тебе не хватает ловкости, но это преходяще.\n\nЕсли ты хочешь стать <учеником/ученицей> мастера Черного Ворона и членом Лиги убийц, стоит только принести печать Черного Ворона (приложенную к этому письму) в поместье Черный Ворон.\n\nПервым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость.\n\nС уважением,\n\nФахрад.", progress = "Ты знаешь Милтона?\n\n*Фахрад смеется.*", completion = "Отлично, юный вор.\n\nВид у тебя немного побитый, но ничего особенного.\n\nТебя ждет долгий путь – долгий и исполненный наград. Ты готов принять свою судьбу, войдя в число мастеров Черного Ворона?\n\nПоговори со стражами снаружи дома. Они дадут тебе первое задание.", rewards = "Вы получите:\n\n"},
[6701] = {title = "Эмблемы Синдиката", objective = "Мы уже давно воюем с Синдикатом. Недостаток умения они с лихвой восполняют численностью. К сожалению, их число растет быстрее, чем мы их убиваем!\n\nОказывается, лучший способ справиться с ними – это похитить их эмблемы. Лишившись эмблемы, опозоренный сторонник Синдиката лишается и жизни.\n\nОбчисти их карманы и принеси эмблемы мне или другим стражам.\n\nМожешь начать с Дарнхольда, что находится к югу отсюда.", description = nil, progress = "Мы уже давно воюем с Синдикатом. Недостаток умения они с лихвой восполняют численностью. К сожалению, их число растет быстрее, чем мы их убиваем!\n\nОказывается, лучший способ справиться с ними – это похитить их эмблемы. Лишившись эмблемы, опозоренный сторонник Синдиката лишается и жизни.\n\nОбчисти их карманы и принеси эмблемы мне или другим стражам.\n\nМожешь начать с Дарнхольда, что находится к югу отсюда.", completion = "Эй, отличная работа! Если ты продолжишь в том же духе, может, прочие разбойники перестанут над тобой смеяться.", rewards = nil},
[6721] = {title = "Путь Охотника", objective = "Поговорите в Доланааре с Дазаларом.", description = "Привет тебе, <юный охотник/юная охотница>. Ты кажешься мне достаточно <опытным/опытной>, чтобы научиться обращаться с животным и обрести верного друга.\n\nТебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[6722] = {title = "Путь Охотника", objective = "Поговорите в Доланааре с Дазаларом.", description = "Привет тебе, <юный охотник/юная охотница>. Ты кажешься мне достаточно <опытным/опытной>, чтобы научиться обращаться с животным и обрести верного друга.\n\nТебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[6741] = {title = "Больше добычи!", objective = "Мне нужно больше обломков брони, Профессия! У тебя есть еще?", description = nil, progress = "Мне нужно больше обломков брони, Профессия! У тебя есть еще?", completion = "Еще раз спасибо, Профессия. Орда гордится тобой...", rewards = "Следующее заклинание будет наложено на вас:\n\nПолированная броня"},
[6761] = {title = "Новое пограничье", objective = "Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнассе.", description = "Я поручил своему заместителю, Матренгилу Медвежьей Лапе, разобраться с призывом о помощи из Лунной поляны. Так что по этому поводу говори с ним – НЕ со мной!\n\nИ позволь мне дать тебе один дружеский совет. Это я вывел нас всех из тьмы – я, а вовсе не Круг Кенария Лунной поляны, – когда наша раса потеряла все. Тельдрассил дает нам новую жизнь! Они наверняка попытаются внушить тебе совсем другое, но только глупец поверит их пропаганде!\n\nТы же, вроде, не из таких. Или я ошибаюсь?", progress = nil, completion = "Да, |3-6(Паладин), спасибо, что пришел. Прошу прощения за это недоразумение... но взаимное недоверие между здешним верховным друидом и хранителем Ремулом с Лунной поляны прямо-таки дрожит в воздухе. Каждый подозревает другого в кляузничестве, а ведь проблема странной порчи Тельдрассила все еще не решена. Но взаимное недоверие от этого не стихает.\n\nКак бы то ни было, у нас есть долг перед Кругом Кенария... даже если его предводители не ладят друг с другом.", rewards = "Вы получите:\n\n"},
[6762] = {title = "Рабин Сатурна", objective = "Поговорите с Рабином Сатурной в селении Ночная Гавань на Лунной поляне. Лунная поляна находится между Оскверненным лесом и Зимними Ключами, туда можно добраться по дороге, идущей от крепости Древобрюхов.", description = "Мажордом хранителя Лунной поляны Ремула – Рабин Сатурна – ищет помощи. Нужно обследовать обширные пустоши к западу от Танариса... и еще дальше, к западу от Ун'Горо. Найди его в Ночной Гавани, главном поселении Лунной поляны.\n\nПоскольку твои труды будут на благо всем нам, советую тебе вести себя осторожно. Между Дарнассом и Лунной поляной трения... и как бы они не переросли со временем в нечто большее.", progress = nil, completion = "Я Рабин Сатурна. От лица хранителя Ремула и всех обитателей сего священного места приветствую тебя.\n\nЯ ценю твою заинтересованность и горячую готовность помочь Кругу Кенария. Также мне ведомо о недовольстве, с которым верховный друид Дарнасса отозвался о твоей помощи нам. Будь уверен, что все, что делается, – делается во благо, и что тебя не коснутся необдуманные выпады, целью коих ты можешь стать.\n\nЗдесь ты среди друзей, Драгунов.", rewards = "Вы получите:\n\n"},
[6781] = {title = "Больше обломков брони", objective = "Хлуси, нам нужно больше обломков брони для поставки в наши войска!", description = nil, progress = "Хлуси, нам нужно больше обломков брони для поставки в наши войска!", completion = "Это неплохие образчики, Хлуси. Я могу перековать их на новую экипировку для наших воинов.\n\nЕсли припасов у меня окажется достаточно, может, наши опытные воины смогут выйти на поле боя!", rewards = "Следующее заклинание будет наложено на вас:\n\nПолированная броня"},
[6801] = {title = "Локолар Владыка Льда", objective = "Я из Громового Утеса, |3-6(орк). Кэрн лично велел мне помочь клану Северных Волков в эти суровые времена.\n\nНо не будем тратить время! Убивайте наших врагов и несите мне их кровь. Как только наберется достаточно крови, можно будет начать ритуал призыва.\n\nКогда могучий элементаль обрушится на армию Грозовой Вершины, победа будет наша!", description = nil, progress = "Я из Громового Утеса, |3-6(орк). Кэрн лично велел мне помочь клану Северных Волков в эти суровые времена.\n\nНо не будем тратить время! Убивайте наших врагов и несите мне их кровь. Как только наберется достаточно крови, можно будет начать ритуал призыва.\n\nКогда могучий элементаль обрушится на армию Грозовой Вершины, победа будет наша!", completion = "Мы пролили достаточно вражеской крови. Я смешаю эту кровь с остальной... И как только жертва будет принесена, Владыка Льда покажет этим псам Грозовой Вершины всю силу ярости Северных Волков!", rewards = nil},
[6804] = {title = "Отравленная вода", objective = "Исцелите отравленных элементалей в Восточных Чумных землях с помощью аспекта Нептулона. Принесите 12 браслетов колыхающихся волноплесков и аспект Нептулона герцогу Гидраксису в Азшару.", description = "Мы отправили отряд элементалей воды на разведку в восточные пределы Лордерона, пораженные чумой нежити. Теперь наши разведчики поражены скверной. Повелители Вод не могут допустить, чтобы проклятая чума угрожала нашему народу!\n\nВозьми этот фиал. В нем заключен один из аспектов Нептулона. Он исцелит пораженных скверной элементалей, уничтожив проникшую в их тела заразу. Однако этот процесс столь болезнен, что некоторые из них могут стать нестабильными.\n\nТебе придется убить колыхающихся волноплесков. Принеси мне их браслеты.", progress = "Принес браслеты?", completion = "Ты отлично справился, |3-6(Воин). Оскверненные элементали воды были позором для всего нашего племени – ведь в основе элементалей воды лежит чистота, именно в ней коренится наша сила.", rewards = "Вы получите:\n\n"},
[6805] = {title = "Буря в пустыне", objective = "Убейте 15 пылевихрей и 15 пустынных грохотунов, а затем возвращайтесь к герцогу Гидраксису в Азшару.", description = "Мы, элементали воды, противостоим существам низших стихий. Если и в самом деле хочешь быть <нашим союзником/нашей союзницей>, докажи это!\n\nДалеко на юге, в пустынных землях Силитуса, в скалистом уголке, именуемом долиной Кристаллов, кишат слуги воздуха и земли. Они защищают сокрытые там предметы силы от примитивных существ, смертных. Мне нет никакого дела до того, что они там стерегут, я хочу, чтобы ты <перебил/перебила> их.\n\nОтправляйся в Долину Кристаллов в Силитус и уничтожь наших врагов.", progress = "Трусость – это то, чему нет прощения, |3-6(Чернокнижник). Отправляйся в Силитус и докажи свою доблесть.", completion = "Ты доказал свою доблесть и полезность для нашего народа. Возможно, у меня будет для тебя и другая работа – работа, более достойная ценного союзника Повелителей Вод.", rewards = "Вы получите:\n\n"},
[6821] = {title = "Око Углеглаза", objective = "Принесите глаз Созерцателя Углей герцогу Гидраксису в Азшару.", description = "Ты <доказал/доказала> мне, что <способен/способна> доблестно противостоять врагам и верно служить Повелителям Вод. Однако пока тебе приходилось выходить на бой с довольно слабыми противниками. Сможешь ди ты сразить более могущественного врага.\n\nСлушай мое повеление.\n\nНа вершине Пика Черной горы орки изловили слугу огня, Пиростража Созерцателя Углей. Найди место, где они его держат, и перебей и стражу и пленника. Принеси мне его глаз – докажи свою преданность.", progress = "Ты принес мне глаз, |3-6(Шаман)? Или у тебя не хватило духу и близко подойте к Пику Черной горы.", completion = "Что ж, ты доказал, что у тебя довольно силы и хитрости для столь сложной задачи – ведь для того, чтобы противостоять тварям, скрывающимся в Черной горе, одной только силы недостаточно. \n\nТеперь я уверен, ты станешь для нас ценным союзником, Стиммакс...", rewards = "Вы получите:\n\n"},
[6822] = {title = "Огненные Недра", objective = "Убейте 1 Повелителя огня, 1 лавового гиганта, 1 древнюю гончую бездны и 1 лавового волноплеска и возвращайтесь к герцогу Гидраксису в Азшару.", description = "Пришло время испытать твои силы всерьез, <имя>. Ты <готов/готова>?\n\nНа самом дне Глубин Черной горы скрывается путь к Огненным Недрам. Это оплот нашего врага, охраняемый самыми мощными служителями огня в нашем мире.\n\nОтправляйся в Огненные Недра, <имя>. Докажи мне, что у тебя хватит сил справиться с тем, что скрывается там.\n\nЕсли у тебя есть союзники, бери их с собой. Не стоит отправляться в Огненные Недра в одиночку.", progress = nil, completion = "Тебе под силу подвиги, которые большинству кажутся невозможными. Ты вступил в схватку с тварями Огненных Недр и вышел из нее победителем. \n\nТы силен для столь маленького создания. \n\nВозможно, однажды Повелители Вод заключат союз с твоим племенем.", rewards = "Вы получите:\n\n"},
[6823] = {title = "Агент Гидраксиса", objective = "Добейтесь уважительного отношеия к себе со стороны Гидраксианских Повелителей Вод, затем отправляйтесь к герцогу Гидраксису в Азшару.", description = "Если в самом деле хочешь быть <нашим союзником/нашей союзницей>, докажи серьезность своих намерений в боях против наших врагов – слуг воздуха, земли и огня. Каждое нанесенное им поражение подорвет их позиции в этих землях и послужит доказательством твоей приверженности благу нашего народа.", progress = "Твоя работа еще не закончена, Машин. Приложи больше стараний в борьбе против наших врагов, духов воздуха, огня и земли, и однажды ты обретешь место в зале Повелителей Вод.", completion = "Молва о твоих необыкновенных успехах в борьбе против наших врагов облетела всех Повелителей Вод. Некоторые из нас считали, что твое тело слишком маленькое и хрупкое, чтобы ты мог биться в наших рядах, однако теперь никто не сомневается в твоей силе. Ты завоевал наше уважение.", rewards = "Вы получите:\n\n"},
[6824] = {title = "Руки врага", objective = "Принесите руки Люцифрона, Сульфурона, Гееннаса и Шаззраха герцогу Гидраксису в Азшару.", description = "<имя>, твоя помощь для нас неоценима, и мы с неохотой отправляем тебя на последнее задание – мы не хотим терять столь полезного союзника, однако работа есть работа.\n\nИмей в виду, если ты успешно выполнишь поставленную перед тобой задачу, это весьма существенно приблизит час нашей победы.\n\nМы хотим, чтобы ты <уничтожил/уничтожила> нескольких капитанов в Огненных Недрах: Люцифрона, Сульфурона, Гееннаса и Шаззраха. Убей их и принеси их отрубленные руки.\n\nЭто потребует от тебя всех сил, но если ты преуспеешь, Повелителям огня будет нанесен ужасный удар.", progress = "Тебе удалось разбить капитанов Недр, Вилдан? Ты принес мне их руки.", completion = "Это их руки! Тебе действительно удалось уничтожить их! \n\nВилдан, твоим подвигам нет числа, но последнее твое деяние нескоро будет стерто из памяти Повелителей Вод. Твое имя станет легендой. \n\nВозвращайся ко мне, Вилдан, у меня найдется для тебя работа.", rewards = "Вы получите:\n\n"},
[6825] = {title = "Воздух зовет – флот Гуса", objective = "Нужно подготовить новый флот боевых виверн, |3-6(нежить)! Чтобы мои виверны могли нанести в битве решающий удар, они должны быть сытыми.\n\nИм нужна плоть солдат Грозовой Вершины! Сотни фунтов мяса! Уверен, ты справишься с этим заданием. Понял? Ступай!", description = nil, progress = "Нужно подготовить новый флот боевых виверн, |3-6(нежить)! Чтобы мои виверны могли нанести в битве решающий удар, они должны быть сытыми.\n\nИм нужна плоть солдат Грозовой Вершины! Сотни фунтов мяса! Уверен, ты справишься с этим заданием. Понял? Ступай!", completion = "Флот питается плотью своих врагов.\n\nСкоро мы двинемся в бой!", rewards = nil},
[6826] = {title = "Воздух зовет – флот Джезтора", objective = "Ты отлично поработал, Бхт, но это только начало.\n\nМои боевые виверны должны наесться вдоволь. Тогда мы сможет сокрушить врага с неумолимой точностью!\n\nМой флот – второй по силе в воздушных войсках. А значит, они должны сразаться с самыми грозными противниками! Моим боевым вивернам нужно мясо лейтенантов Грозовой Вершины.\n\nИ поторопись, солдат!", description = nil, progress = "Ты отлично поработал, Бхт, но это только начало.\n\nМои боевые виверны должны наесться вдоволь. Тогда мы сможет сокрушить врага с неумолимой точностью!\n\nМой флот – второй по силе в воздушных войсках. А значит, они должны сразаться с самыми грозными противниками! Моим боевым вивернам нужно мясо лейтенантов Грозовой Вершины.\n\nИ поторопись, солдат!", completion = "Больше мяса! Чтобы мои виверны снова могли вступить в бой, нужно еще!", rewards = nil},
[6827] = {title = "Воздух зовет – флот Малверика", objective = "Я провел в этой проклятой дворфийской дыре долгие дни. Можешь поверить, я жажду мести!\n\nМы должны все четко спланировать.\n\nМоим боевым вивернам нужна особая цель! Я собираюсь накормить их мясом командиров Грозовой Вершины. К сожалению, эти трусы глубоко окопались в своих укреплениях. Ничего – я уверен, ты справишься с этой задачей!", description = nil, progress = "Я провел в этой проклятой дворфийской дыре долгие дни. Можешь поверить, я жажду мести!\n\nМы должны все четко спланировать.\n\nМоим боевым вивернам нужна особая цель! Я собираюсь накормить их мясом командиров Грозовой Вершины. К сожалению, эти трусы глубоко окопались в своих укреплениях. Ничего – я уверен, ты справишься с этой задачей!", completion = "Что это?! Ты думаешь, меня устроит такое качество работы, а, Топблэйд? Ступай, солдат! Катись! Нужно больше мяса!", rewards = nil},
[6843] = {title = "Штуковина", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6844] = {title = "Умбер, архивариус", objective = "Отнесите покрытый коркой предмет Умберу – архивариусу Круга Кенария – в деревню Ночная Гавань, что в Лунной поляне.", description = "Здесь полно работы, но мне кажется, главное – отнести это в Круг, на анализ. Поверь мне, дела здесь не переводятся. Если внутри этого хитина находится дневник, то Круг сможет заглянуть в прошлое!\n\nОтнеси этот дневник архивариусу Круга в Ночную Гавань. Его зовут Умбер, он настоящий гений! Да, тронутый, не без того, но все равно гений! Умбер находил манускрипты в куда более плохом состоянии. Если эти записи можно восстановить, он это сделает.", progress = "Эй, привет! Хмм…\n\nНе скрою, друг мой... Пахнешь ты неважно. Можно сказать, воняешь. Нет-нет, ничего личного. Всего лишь маленький совет... В будущем, вернувшись из боя, освежись немного. Первое впечатление – это очень важно!\n\nВпрочем... Чем могу служить?", completion = "Жаба меня побери! Что это? Формой определенно напоминает книгу... Попытаюсь-ка я взломать оболочку.\n\nТебя прислал Лайо из Силитуса? До меня доходили только смутные слухи – не такие уж смутные, если хорошо подумать – об ужасах, творящихся в тех краях. Учитывая мою нелюбовь ко всему, что напоминает насекомых, все эти сплетни – хорошая причина остаться здесь, с моими книжечками!", rewards = "Вы получите:\n\n"},
[6845] = {title = "Раскрытие древних секретов", objective = "Поговорите с Рабином Сатурной в деревне Ночная Гавань в Лунной поляне.", description = "Короче, свяжись со мной как можно скорее... если, конечно, хочешь знать, что там внутри. Как только я это узнаю, с удовольствием поделюсь с тобой информацией – разумеется, если там действительно окажется книга.\n\nА пока я свяжусь с самой-большой-медведицей этого медвежьего угла, то есть, Рабином. Он, несомненно, пожелает узнать, что за кашу ты тут <заварил/заварила>. Никогда не заставляй мать-медведицу ждать, <имя>... ну, если только тебе неймется искупаться в меду.\n\nТакое бывает, уж поверь мне.", progress = nil, completion = "А, Томпсон – я надеялся, что у тебя найдется для меня минутка. Рад видеть, что ты в добром здравии.\n\nЯ получил известие, что ты идешь с поля, и мне захотелось лично выразить тебе признательность Круга Кенария за помощь. Несомненно, в Силитусе еще много тайн, и то, что ты доставил Умберу, может оказаться наиболее интересным. Прошу тебя, прими это в знак нашей благодарности за помощь.\n\nСпасибо тебе, благородный |3-6(Охотник).", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо Живого камняСветящееся хрустальное кольцо\n\nВы также получите:\n\n"},
[6846] = {title = "В атаку!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6847] = {title = "Всевидящее око мастера Рисона", objective = "Заберите Всевидящее око мастера Рисона из пещер Секиры Зимы и возвращайтесь к мастеру Рисону.\n\nБудьте осторожны: говорят, что на Всевидящее око мастера Рисона наложено ужасное проклятие!", description = "Для Синдиката ничего не значат войны, которые ведутся в этой долине, <класс>. Мы будем делать то, что делали всегда: подождем, пока из пепла не появится истинный вождь, свободный от всеобщего безумия, и не нанесет решающий удар.\n\nПравда, сейчас мы здесь не поэтому. Тролли из племени Секиры Зимы похитили наше сокровище – Всевидящее око.\n\nСпаси Око, и мы всегда будем к твоим услугам, что бы ни случилось.\n\nВозвращайся, когда добудешь Око, я тебя проверю.\n\n*Мастер Рисон оскаливает зубы в усмешке.*После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil},
[6848] = {title = "Всевидящее око мастера Рисона", objective = "Заберите Всевидящее око мастера Рисона из пещер Секиры Зимы и возвращайтесь к мастеру Рисону.\n\nБудьте осторожны: говорят, что на Всевидящее око мастера Рисона наложено ужасное проклятие!", description = "Для Синдиката ничего не значат войны, которые ведутся в этой долине, <класс>. Мы будем делать то, что делали всегда: подождем, пока из пепла не появится истинный вождь, свободный от всеобщего безумия, и не нанесет решающий удар.\n\nПравда, сейчас мы здесь не поэтому. Тролли из племени Секиры Зимы похитили наше сокровище – Всевидящее око.\n\nСпаси Око, и мы всегда будем к твоим услугам, что бы ни случилось.\n\nВозвращайся, когда добудешь Око, я тебя проверю.\n\n*Мастер Рисон оскаливает зубы в усмешке.*После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil},
[6861] = {title = "Портативный резак Зинфиззлекса", objective = "Принесите мастеру-инженеру Спустипару\n\n30 ториевых слитков\n\n50 мифриловых слитков\n\n75 железных слитков\n\n1 паровую пилу.", description = "Я хочу опробовать свой портативный резак не меньше тебя, <раса>, но для того, чтобы его сделать, мне нужны материалы – много материалов!\n\nСказать точнее, целая гора тория, мифрила и железа. Кроме того, по паровой пиле на каждый резак. Их можно достать на лесопилке.\n\nДо того, как меня поймали, я здесь все разнюхал и обнаружил, что куча паровых пил есть на лесозаготовках Грозовой Вершины.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПортативный резак Зинфиззлекса"},
[6862] = {title = "Портативный резак Зинфиззлекса", objective = "Принесите мастеру-инженеру Спустипару\n\n30 ториевых слитков\n\n50 мифриловых слитков\n\n75 железных слитков\n\n1 паровую пилу.", description = "Я хочу опробовать свой портативный резак не меньше тебя, <раса>, но для того, чтобы его сделать, мне нужны материалы – много материалов!\n\nСказать точнее, целая гора тория, мифрила и железа. Кроме того, по паровой пиле на каждый резак. Их можно достать на лесопилке.\n\nДо того, как меня поймали, я здесь все разнюхал и обнаружил, что куча паровых пил есть на лесозаготовках Грозовой Вершины.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПортативный резак Зинфиззлекса"},
[6881] = {title = "Ивус Лесной Властелин", objective = "Клан Северного Волка защищает энергия стихий. Если мы ослабим бдительность, их шаманы могут нас уничтожить.\n\nУщерб становится все больше и больше, Круг скоро не сможет его контролировать! Нам нужно звать на помощь.\n\nСолдаты Северного Волка носят талисманы стихий, которые называются кристаллами бури. Мы можем использовать их, чтобы связаться с Айвусом. Ступай и добудь эти кристаллы, Докторус!", description = nil, progress = "Клан Северного Волка защищает энергия стихий. Если мы ослабим бдительность, их шаманы могут нас уничтожить.\n\nУщерб становится все больше и больше, Круг скоро не сможет его контролировать! Нам нужно звать на помощь.\n\nСолдаты Северного Волка носят талисманы стихий, которые называются кристаллами бури. Мы можем использовать их, чтобы связаться с Айвусом. Ступай и добудь эти кристаллы, Докторус!", completion = "Отлично, Докторус. Сила этих чар пригодится для усиления уже имеющейся магии. Когда энергии наберется достаточно, я смогу ее сфокусировать и воззвать к Владыке Леса о помощи.", rewards = nil},
[6901] = {title = "В атаку!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6921] = {title = "Среди руин", objective = "Принесите глубинный сердечник Дже'неу Санкри в форт Зорам'гар в Ясеневый лес.", description = "Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны Непроглядной Пучины. Их присуствие приведет лишь к тому, что Стихии озлобятся на нас. Если это так и оставить, то они захватят эти места навсегда.\n\n<имя>, ступай в Непроглядную Пучину и найди в руинах глубинный камень. Он должен быть где-то поблизости в воде. В нем находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий. Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!", progress = "Удалось ли тебе отыскать глубинный сердечник? Без него нам не понять, что именно затевает там Сумеречный Молот.", completion = "Это именно то, что мне было нужно! Глубинный сердечник – неиссякаемая кладезь информации, которую мы сможем оттуда извлечь. Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить.\n\nТы сегодня хорошо потрудился, и Служители Земли весьма благодарны тебе за помощь. Ты и всей Орде помог, и имеешь право гордиться собой.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6922] = {title = "Барон Акванис", objective = "Принесите странную водяную сферу Дже'неу Санкри в форт Зорам'гар в Ясеневом лесу.", description = "Сраженный элементаль воды оставил после себя странную сферу. Вы предполагаете, что этот предмет каким-то образо подпитывал тварь энергией. Внутри сферы плещется грязная на вид жидкость. Сама сфера вроде бы не поддается никаким физическим воздействиям.\n\nЕсли кто и сможет понять, что это за штука, то это Дже'неу Санкри из Служителей Земли. Он находится в форте Орды Зорам'гар в Ясеневом лесу.", progress = "О, привет еще раз, Шауе. Я, как всегда, взирал на морские волны и читал их письмена. Что привело тебя в форт?", completion = "Ого... вот это находка, Шауе.\n\nГоворишь, ты добыл это из барона Акваниса в Черных Глубинах? Барон Акванис давно уже считается оскверненной силой Стихии, а этот шар даст понять, что именно повергло его в скверну. Хотя я не удивлюсь, если это окажется клан Сумеречного Молота, зато мы узнаем, как они сумели это сделать.\n\nХорошо, что ты принес эту штуку мне. Прошу – прими это вместе с горячей благодарностью Служителей Земли.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСабля беззаконникаВедьмин палец\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[6941] = {title = "Воздух зовет – флот Змейера", objective = "Мы должны что-то сделать с элитными войсками Северного Волка, которые охраняют границы, солдат! Возвращайся ко мне с медалями их лейтенантов и легионеров. Когда я пойму, что этому сброду хорошо досталось, то добью их с воздуха.", description = nil, progress = "Мы должны что-то сделать с элитными войсками Северного Волка, которые охраняют границы, солдат! Возвращайся ко мне с медалями их лейтенантов и легионеров. Когда я пойму, что этому сброду хорошо досталось, то добью их с воздуха.", completion = "Скоро флот будет готов подняться в воздух! А пока – продолжай!", rewards = nil},
[6942] = {title = "Зов воздуха – флот Слидора", objective = "Мои грифоны должны отправиться вглубь территории противника, чтобы нанести удар, но линия фронта слишком хорошо охраняется.\n\nВоины клана Северного Волка, которые охраняют линию фронта, носят на груди медали за верную службу. Сорви эти медали с их трупов и принеси мне.\n\nКак только линия фронта будет ослаблена, мы нанесем удар с воздуха!", description = nil, progress = "Мои грифоны должны отправиться вглубь территории противника, чтобы нанести удар, но линия фронта слишком хорошо охраняется.\n\nВоины клана Северного Волка, которые охраняют линию фронта, носят на груди медали за верную службу. Сорви эти медали с их трупов и принеси мне.\n\nКак только линия фронта будет ослаблена, мы нанесем удар с воздуха!", completion = "Продолжай свое дело, солдат! Грифоны Заоблачного пика готовы к вылету с минуты на минуту!", rewards = nil},
[6943] = {title = "Зов воздуха – флот Ичмена", objective = "Их дух сломлен, солдат. После нашего неудачного налета на Орду они отказываются подниматься в воздух! Но ты можешь поднять их боевой дух.\n\nВозвращайся на поле битвы и лиши клан Северного Волка командования. Сокруши всех стражей и командиров! Все они носят медали. Собери с трупов столько их медалей, сколько сможешь унести, и возвращайся ко мне. Как только мои грифоны увидят награду и почуют запах поверженного врага, они снова сумеют подняться в воздух. А теперь ступай!", description = nil, progress = "Их дух сломлен, солдат. После нашего неудачного налета на Орду они отказываются подниматься в воздух! Но ты можешь поднять их боевой дух.\n\nВозвращайся на поле битвы и лиши клан Северного Волка командования. Сокруши всех стражей и командиров! Все они носят медали. Собери с трупов столько их медалей, сколько сможешь унести, и возвращайся ко мне. Как только мои грифоны увидят награду и почуют запах поверженного врага, они снова сумеют подняться в воздух. А теперь ступай!", completion = "Видишь? Посмотри на них, солдат! Вот они, кружат в воздухе! Скоро флот Ичмена нанесет удар в самое сердце долины! Грозовая Вершина будет править в небесах!", rewards = nil},
[6961] = {title = "Здравствуй, Дедушка Зима!", objective = "Поговорите с Дедушкой Зимой. Он находится неподалеку от торговца из \"Пастбищ Дымного Леса\" в Оргриммаре.", description = "Веселого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой! Все, кто хорошо себя вел в этом году, получат замечательные подарки в день Зимнего Покрова! Предупреждать его нужно заранее, иначе подарка не дождешься.\n\nИ <сам/сама> не забудь купить подарки для тех, кто хорошо себя вел весь год. У нас богатейший выбор подарков на любой вкус! \"Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!\"", progress = nil, completion = "Хо-хо-хо! Я – Дедушка Зима, явился к вам благодаря добросердечию работников Пастбищ Дымного Леса! \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова!\n\nВсе, кто хорошо себя вел в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова. Уррра!", rewards = "Вы получите:\n\n"},
[6962] = {title = "Угощение для Дедушки Зимы", objective = "Принесите 5 имбирных пряников и ледяное молоко Дедушке Зиме в Оргриммар.", description = "Эй, <мальчуган/девчушка>, не окажешь ли услугу Дедушке Зиме?\n\nДедушка Зима весь день провел на ногах и сам не откажется угоститься. Немного пряников и ледяного молока, чтобы запить, будут очень кстати. Ты ведь любишь дедушку? Принесешь мне угощение?", progress = "От всех этих разговоров об угощении у меня у самого аппетит разыгрался. М-м-м... Прянички с молочком...", completion = "Ну, спасибо! Угодил ты Дедушке Зиме, Ахахаха! Доброго тебе праздника Зимнего Покрова.\n\nА вот тебе кое-что... ну, за труды, понимаешь.", rewards = "Вы получите:\n\nПодарочный набор Пастбищ Дымного Леса"},
[6963] = {title = "Пропавшее угощение Зимнего Покрова", objective = "Отыщите агента Пастбищ Дымного Леса, который затерялся в снегах Альтеракских гор.", description = "Слушай... Не хотелось бы разрушать праздничное волшебство, однако Пастбищам Дымного Леса нужна помощь <искателя приключений/искательницы приключений> вроде тебя.\n\nУ нас пропал груз сладостей, которые мы закупили к зиме, а теперь куда-то подевался еще и наш агент, которого мы отправили разыскивать товар! В последний раз груз видели в Альтеракских горах, туда за ним и отправился наш агент.\n\nПозаботься о том, чтобы и товар, и наш работник вернулись сюда в целости и сохранности!", progress = nil, completion = "Т-т-ты м-м-меня с-слышишь! Слава б-б-богам!\n\nН-нет, я не с-с-снеговик. М-меня зовут Сакс, я раб-ботаю в Оргриммарском отделении Пастбищ Дымного Леса. М-м-м-меня отп-правили искать пропавший товар, и тут на меня нап-пала тварь, какой я никогда не видывал!\n\nБр-р, ну и холодрыга!", rewards = "Вы получите:\n\n"},
[6964] = {title = "Повод для праздника", objective = "Поговорите с Сагорном Гривастым Странником в Аллее Мудрости Оргриммара о празднике Зимнего Покрова.", description = "Подарки, гости, угощение... чушь собачья!\n\nЭти гоблины искажают саму суть праздника Зимнего Покрова. Это время возрождения – земля спит под покровом снега, которым ее укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке!\n\nЕжели вам интересно узнать, что такое на самом деле этот праздник, поспрошайте Сагорна Гривастого Странника. Уверен, он будет очень удивлен, что хоть кому-то история интереснее подарков.", progress = nil, completion = "Праздник Зимнего Покрова, говоришь? Увы, в прежние времена для нас, тауренов, он был куда важнее. А теперь, похоже, другие используют древние легенды, чтобы продать побольше сладостей и подарков.\n\nНеудивительно, что Фарманда это так огорчает. Он и остальные таурены держатся за наше прошлое, как за боевое знамя. Я лично считаю, что немного веселья никогда не помешает, но о происхождении праздника забывать нельзя.", rewards = "Вы получите:\n\n"},
[6981] = {title = "Светящийся осколок", objective = "Отправляйтесь в Кабестан и найдите там кого-нибудь, кто сможет вам рассказать об этом светящемся осколке.\n\nЗатем отнесите осколок туда, куда вас направят.", description = "Блестящий осколок ярко-зеленый, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство.\n\nПожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке.", progress = "Приветствую тебя, |3-6(таурен). Я могу тебе чем-то помочь?", completion = "О... мне никогда не приходилось видеть ничего подобного...", rewards = "Вы получите:\n\n"},
[6982] = {title = "Припасы из рудника Ледяного Зуба", objective = "Принесите 10 ящиков с припасами Ледяного Зуба интенданту Альянса в Дун Болдар.", description = "Рудник Ледяного Зуба – это хранилище Орды. Мой желудок не переваривает жратву, которой они кормят своих солдат, а их доспехи и оружие выглядят ужасно! Но... в такие времена, когда припасы столь важны, приходится использовать то, что есть. \n\nОтправляйся в рудник Ледяного Зуба и принеси мне часть их припасов. Это поможет Альянсу поддержать свою боевую форму, а заодно лишить воинов Орды самого необходимого.\n\nРудник находится далеко на юге, в глубоком тылу Орды.", progress = "Удалось ли вам добраться до рудника Ледяного Зуба в тылу Орды, Аллория? Сумели ли вы стащить их припасы?", completion = "Сколько припасов! Отличная работа, Аллория. Я проверю содержимое ящиков и раздам его нашим воинам.", rewards = "Вы получите:\n\n"},
[6983] = {title = "Прохладное чувство юмора", objective = "Отыщите украденные лакомства и верните их Каймарду Меднокнопу в Оргриммар. Лакомства должны быть у Омерзительного Гринча, который бродит где-то среди заснеженных вершин Альтеракских гор.", description = "<имя>, с-существо, которое зовут \"Оме-мерзительный Гри-инч\", похитило все наши лакомства! Т-только ос-стор-р-рожно! Это он с-сделал из меня с-снеговика!\n\nВа-ва-вам понадобится помощь! Я в-видел, как он шляется тут в-в-вместе с другими йети. Он нав-верняка где-то п-поблизости! Отыщите мой груз, <имя>, отвезите его в Оргриммар, П-пастбищам Дымного Леса, и п-п-передайте им, что м-меня надо разморозить!", progress = "Зарригар, без этих лакомств наш праздник Зимнего Покрова будет загублен на корню! Можете себе представить: все послушные детки останутся без знаменитых пирожков Гракку!", completion = "Вы нашли груз! Вы спасли наш праздник!\n\nБедный Сакс! Конечно же, мы немедленно отправим спасателей и придумаем, как его разморозить. Надеюсь, он успеет прийти в себя к празднику... Хотя, конечно же, потом ему придется отработать то время, которое он прогулял! Но в любом случае, если бы не вы, все пошло бы прахом!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[6984] = {title = "\"Пастбища Дымного Леса\" благодарны тебе!", objective = "Поговорите с Дедушкой Зимой в Оргриммаре.", description = "Спасибо тебе от \"Пастбищ Дымного Леса\" за возвращение краденых сладостей, <имя>! И хотим мы тебе за это предложить особый подарок... От самого Дедушки Зимы!\n\nПоговори с Дедушкой Зимой, и он даст тебе подарок праздника Зимнего Покрова от нашего имени! От нашего села да к вашему столу – вкусная и здоровая пища от \"Пастбищ Дымного Леса\"... благодаря тебе, конечно же!", progress = nil, completion = "Хо-хо-хо! Добро пожаловать!\n\nГоблины мне сказали, что тебе нынче полагается специальный приз, и я рад отдать его. Вот он – и веселого тебе праздника Зимнего Покрова каждый год!", rewards = "Вы получите:\n\nОсобый дар Пастбищ Дымного Леса"},
[6985] = {title = "Припасы Железного рудника", objective = "Доставьте 10 ящиков припасов Железного рудника интенданту Орды в крепость Северного Волка.", description = "Дворфы Грозовой Вершины используют Железный рудник для хранения припасов. Сбегай на этот рудник и позаимствуй у дворфов их богатства. Это малость подрежет крылья Грозовой Вершине, а мы получим необходимые материалы.\n\nДействуй осторожно, <имя>. Железный рудник лежит в глубине территории Альянса, и за него постоянно идут бои.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7001] = {title = "Пустые стойла", objective = "Найдите северного волка в Альтеракской долине. Подойдите к нему на достаточное расстояние, чтобы его \"приручить\", и используйте намордник Северного Волка. После приручения северный волк проследует за вами к смотрителю стойл из клана Северного Волка. Поговорите со смотрителем, чтобы получить награду за пойманных волков.", description = "Набат войны зовет наших солдат к оружию! Мы должны восстановить боеспособность армии!\n\nЕсли в стойлах заведется зверье, то волчьи всадники смогут снова отправиться в бой.\n\nВозьми этот намордник и найди следы северных волков, обитающих в ближайшем лесу. Когда отыщешь волка, используй намордник, чтобы его приручить. Прирученных зверей приводи ко мне, я поставлю их в стойла.\n\nКогда стойла будут полны, наши волчьи всадники снова смогут отправиться на фронт.", progress = "Без твоей помощи наездники на волках из клана Северного Волка останутся без верховых животных. Ты оказываешь нам неоценимую услугу!", completion = "Я могу только надеяться, что те, кого я послал за шкурами баранов, будут столь же удачливы, Харвестер.\n\nС такой скоростью мы заполним стойла за считанные часы!", rewards = nil},
[7002] = {title = "Упряжь из бараньей кожи", objective = "Одни наши солдаты занимаются поимкой волков для стойл, другие должны раздобыть необходимую упряжь.\n\nТебе придется поохотиться на местных баранов. Тех самых, на которых ездит кавалерия Грозовой Вершины!\n\nУбей этих баранов и принеси мне их шкуры. Из них мы соорудим упряжь для волков. Наездники снова сядут в седла!", description = nil, progress = "Одни наши солдаты занимаются поимкой волков для стойл, другие должны раздобыть необходимую упряжь.\n\nТебе придется поохотиться на местных баранов. Тех самых, на которых ездит кавалерия Грозовой Вершины!\n\nУбей этих баранов и принеси мне их шкуры. Из них мы соорудим упряжь для волков. Наездники снова сядут в седла!", completion = "Отлично, солдат. Я скажу тебе, когда будет достаточно.\n\nА пока продолжай работать!", rewards = nil},
[7003] = {title = "Ликвидация великанов", objective = "Используйте ультрасжиматель Зорбина, чтобы уменьшить великанов любого вида, каких вы найдете в Фераласе. Принесите 15 остатков миниатюризации этих великанов Зорбину Дребезгуну в порт Забытого берега в Фераласе.", description = "Нет, если я собираюсь здесь остаться, мне решительно необходимо что-то сделать с великанами! Они губят весь бизнес.\n\nЯ взял за основу разновидность гномского уменьшающего луча, но внес в конструкцию превосходные гоблинские усовершенствования! Дабы самому избежать различных неудобств – например, смерти, – я поручаю его испытание вам. Испробуйте его на любых великанах, каких найдете в Фераласе. После уменьшения вы обнаружите на месте великана остатки миниатюризации – принесите их мне!", progress = "Остатки миниатюризации – ценнейшая штука для инженера, скажу я вам! Ну, например, они помогают гарантировать, что уменьшитель не сделает чего-нибудь не того: например, не взорвется в руках при работе с ним.\n\nНет-нет, тот, что у вас, конечно же, не взорвется! Он абсолютно надежен!", completion = "Архивеликолепно! Я крайне рад видеть, что вы не только вернулись живым, но и благополучно сохранили все ваши конечности! Нет-нет, разумеется, ультрасжиматель совершенно безопасен, как вы могли подумать!\n\nЯ ценю ваши усилия, Эфром. Вы – добрый друг всех гоблинов! Примите это в знак моей признательности!", rewards = "Вы получите:\n\nМегатесак Зорбина"},
[7021] = {title = "Здравствуй, Дедушка Зима!", objective = "Поговорите с Дедушкой Зимой – он находится рядом с торговцем из Пастбищ Дымного Леса в Оргриммаре.", description = "Веселого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой – он сейчас в Оргриммаре! Все, кто хорошо себя вел в этом году, получат замечательные подарки в день Зимнего Покрова! Предупреждать его нужно заранее, иначе подарка не дождешься.\n\nИ <сам/сама> не забудь купить подарки для тех, кто хорошо себя вел весь год. У нас богатейший выбор подарков на любой вкус! От нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!", progress = nil, completion = "Хо-хо-хо! Я – Дедушка Зима, явился к вам благодаря добросердечию работников Пастбищ Дымного Леса! \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова!\n\nВсе, кто хорошо себя вел в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова. Уррра!", rewards = "Вы получите:\n\n"},
[7022] = {title = "Здравствуй, Дедушка Зима!", objective = "Поговорите с Дедушкой Зимой – он находится неподалеку от торговца из Пастбищ Дымного Леса в Стальгорне.", description = "Доброго тебе Зимнего Покрова! Не забудь поздороваться с Дедушкой Зимой! Если в этом году ты <был примерным мальчиком/была примерной девочкой>, получишь в день праздника замечательные угощения. Не забудь сказать ему, что именно тебе хотелось бы получить в этом году!\n\nТакже не забудь приготовить угощение для тех, кто хорошо себя вел. У нас есть из чего выбрать. Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!", progress = nil, completion = "Хо-хо-хо! Я Дедушка Зима, и от имени доброго народа Пастбищ Дымного Леса... \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса,\" – хотел бы пожелать всем замечательно провести праздник Зимнего Покрова.\n\nЕсли в этом году ты был примерным мальчиком, то, может быть, ты получишь лакомство от Пастбищ Дымного Леса в качестве угощения на праздник Зимнего Покрова. Хо-хо!", rewards = "Вы получите:\n\n"},
[7023] = {title = "Здравствуй, Дедушка Зима!", objective = "Поговорите с Дедушкой Зимой – он находится неподалеку от торговца из Пастбищ Дымного Леса в Стальгорне.", description = "Доброго тебе Зимнего Покрова! Не забудь поздороваться с Дедушкой Зимой! Если в этом году ты <был примерным мальчиком/была примерной девочкой>, получишь в день праздника замечательные угощения. Не забудь сказать ему, что именно тебе хотелось бы получить в этом году!\n\nТакже не забудь приготовить угощение для тех, кто хорошо себя вел. У нас есть из чего выбрать. Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища с пастбищ Дымного леса!", progress = nil, completion = "Хо-хо-хо! Я – Дедушка Зима, и от имени доброго народа пастбищ Дымного леса... \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из пастбищ Дымного леса,\" – хотел бы пожелать всем замечательно провести праздник Зимнего Покрова.\n\nЕсли в этом году ты был примерным мальчиком, то, может быть, ты получишь лакомство от Пастбищ Дымного Леса в качестве угощения на праздник Зимнего Покрова. Хо-хо!", rewards = "Вы получите:\n\n"},
[7024] = {title = "Здравствуй, Дедушка Зима!", objective = "Поговорите с Дедушкой Зимой. Он находится неподалеку от торговца из Пастбищ Дымного Леса в Оргриммаре.", description = "Веселого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой! Все, кто хорошо себя вел в этом году, получат замечательные подарки в день Зимнего Покрова! Предупреждать его нужно заранее, иначе подарка не дождешься.\n\nИ <сам/сама> не забудь купить подарки для тех, кто хорошо себя вел весь год. У нас богатейший выбор подарков на любой вкус! Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!", progress = nil, completion = "Хо-хо-хо! Я Дедушка Зима, и я явился к вам благодаря добросердечию Пастбищ Дымного Леса! \"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова!\n\nВсе, кто хорошо себя вел в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова. Ур-р-ра!", rewards = "Вы получите:\n\n"},
[7025] = {title = "Угощение для Дедушки Зимы", objective = "Принесите 5 пряников и ледяного молока Дедушке Зиме в Стальгорн.", description = "Эй, не окажешь ли услугу Дедушке Зиме, хм, <мальчуган/девчушка>?\n\nНет смысла говорить о себе в третьем лице, но Дедушка Зима весь день был на ногах и хотел бы и сам полакомиться угощением. Немного пряников и ледяного молока, чтобы запить, – и будет довольно. Ты ведь любишь дедушку и принесешь мне угощение?", progress = "От всех этих разговоров об угощении у меня самого аппетит разыгрался. Мммм... Прянички с молочком...", completion = "Ну, ты и угодил Дедушке Зиме, Мерандир! Доброго тебе праздника Зимнего Покрова.\n\nА вот тебе кое-что... ну, за труды, ты понимаешь.", rewards = "Вы получите:\n\nПодарочный набор Пастбищ Дымного Леса"},
[7026] = {title = "Упряжь ездовых баранов", objective = "Бригада Грозовой Вершины не может отправиться в бой, не имея седел! Мы же не дикари, нам нужна упряжь для наших баранов.\n\nМы бы, конечно, могли снять шкуры с баранов, которые пасутся рядом с базой, но это было бы исключительной глупостью. А ездить мы на чем будем?\n\nТы должен напасть на базу наших врагов, клана Северного Волка и снять шкуры с волков, которых они используют как верховых животных. Когда добудешь шкуры, возвращайся, из них получится отличная упряжь. Ступай!", description = nil, progress = "Бригада Грозовой Вершины не может отправиться в бой, не имея седел! Мы же не дикари, нам нужна упряжь для наших баранов.\n\nМы бы, конечно, могли снять шкуры с баранов, которые пасутся рядом с базой, но это было бы исключительной глупостью. А ездить мы на чем будем?\n\nТы должен напасть на базу наших врагов, клана Северного Волка и снять шкуры с волков, которых они используют как верховых животных. Когда добудешь шкуры, возвращайся, из них получится отличная упряжь. Ступай!", completion = "Отлично, солдат. Я скажу тебе, когда будет достаточно.\n\nА пока продолжай работать!", rewards = nil},
[7027] = {title = "Пустые стойла", objective = "Найдите в Альтеракской долине альтеракского барана. Чтобы приручить барана, используйте учебный ошейник Грозовой Вершины. Для этого надо подойти в барану поближе. Пойманный баран проследует за вами к смотрителю стойл. Поговорите со смотрителем стойл, чтобы получить вознаграждение за пойманных баранов.", description = "Посмотри на эти стойла, <имя>! Они совершенно пустые! У бригады Грозовой Вершины нет ездовых баранов, а значит, нет и кавалерии.\n\nТы <должен/должна> помочь нам, солдат! Возьми учебный ошейник и отправляйся в самую глушь этой долины. Найди альтеракских баранов, которые там бродят, и поймай их при помощи ошейника. Как поймаешь барана, возвращайся ко мне, я поставлю его в стойла.\n\nКогда баранов будет достаточно, я извещу командира всадников. В твоих силах возродить нашу кавалерию!", progress = "Без твоей помощи бараньи наездники на баранах из клана Грозовой Вершины останутся без верховых животных. Ты можешь оказать нам неоценимую услугу!", completion = "Стойла наполняется прямо на глазах. Так держать!", rewards = nil},
[7028] = {title = "Хрустальные орнаменты", objective = "Соберите 25 терадрических хрустальных орнаментов для Ивы из Пустошей.", description = "На западе, в глубинах Мародона, раскинулись хрустальные пещеры Террамока... Это очень древнее место, <класс>. А я хочу наложить лапу на часть тамошних древностей. За огромными дверями скрыты реликвии древних богов.\n\nЕсли ты отважишься бросить вызов злу, таящемуся в Мародоне, я щедро тебе заплачу. Собери там терадрические хрестальные орнаменты и принеси их мне.\n\nКак только я доберусь до этих орнаментов, я смогу их... изучить. Слишком долго дремали скрытые силы...", progress = "Не задавай лишних вопросов!\n\nЗаказ есть заказ.", completion = "Ха-ха-ха! Я так и знала, что ты вернешься.\n\n*Ива бормочет себе под нос.*\n\n... Как легко убедить.\n\n… пойдет на что угодно за сходную цену. Хе-хе-хе...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПроницательные одеянияШлем Кольца духовБеспощадная кольчугаНаплечье мегакамня\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[7029] = {title = "Порча Злоязыкого", objective = "Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона.\n\nПолейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу.\n\nИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в Деревню Ночных Охотников.", description = "В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет все, до чего может дотянуться. Из-за него умирают растения.\n\nВозьми этот фиал, <имя>, и наполни его из оранжевого пруда рядом с пещерами. Внутри фиала есть особое покрытие, которое превратит яд в лекарство.\n\nОтыщи в оранжевых пещерах гнусь-лозу и полей ее целебной жидкостью. Растение очистится от порчи, но все равно останется в воле Злоязыкого. Он может обратить его против тебя.", progress = "Если ты сумеешь исцелить растение, оно снова оживет. Мы должны делать все, что в наших силах, Хантор…", completion = "Спасибо, что принес мне фиал. Я исследую остатки жидкости.\n\nХотя впереди много работы, зло, совершенное Злоязыким в Мародоне, хотя бы отчасти исправлено. Прими это в знак моей благодарности.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо Лесных СемянПолынный ременьРукавицы Когтистой ветви\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[7041] = {title = "Порча Злоязыкого", objective = "Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона.\n\nПолейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу.\n\nИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела.", description = "В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет все кругом. Из-за него там больше не растут цветы.\n\nВозьми этот фиал, <имя>, и наполни его из оранжевого пруда рядом с пещерами. Внутри фиала есть особое покрытие, которое превратит яд в лекарство.\n\nОтыщи в оранжевых пещерах гнусь-лозу и полей ее целебной жидкостью. Растение очистится от порчи, но все равно останется в воле Злоязыкого. Он может обратить его против тебя.", progress = "Если ты сумеешь исцелить растение, оно снова оживет. Мы должны делать все, что в наших силах, Эфром…", completion = "Спасибо, что принес мне фиал, Эфром. Я исследую остатки жидкости.\n\nХотя впереди много работы, зло, совершенное Злоязыким в Мародоне, хотя бы отчасти исправлено. Прими это в знак моей благодарности.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо Лесных СемянПолынный ременьРукавицы Когтистой ветви\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[7042] = {title = "Кража угощения Зимнего Покрова", objective = "Найдите агента Пастбищ Дымного Леса, пропавшего в снежных районах Альтеракских гор.", description = "Слушай... не хочется портить праздничное настроение, но Пастбищам Дымного Леса нужна помощь как раз от <искателя/искательницы> приключений вроде тебя.\n\nМы потеряли важную партию угощения, что запасаем на праздник, а теперь еще пропал и агент Пастбищ Дымного Леса, которого мы отправили на поиски! Помоги, будь <любезен/любезна>! Говорят, покраденное в последний раз видели в Альтеракских горах, туда наш посланец и отправился.\n\nПривези оттуда и его, и наши припасы в целости и сохранности!", progress = nil, completion = "В-в-вы м-м-меня с-с-слыш-шит-т-е! П-по г-г-гроб ж-жиз-зни б-б-б-лагодарен!\n\nЯ н-н-не с-с-нег-говик, я М-м-еш-ш-окс, я р-р-абот-т-аю на с-с-с-т-ттальгорнское от-т-деление П-п-астбищ Д-д-дымного л-леса... М-меня п-п-ослали на-найти п-пропавший груз, к-кок-гда на м-м-меня н-напала т-т-варь, каких я п-п-прежде и н-н-е в-видывал!\n\nКак же я з-з-з-ам-м-мерз-з-з...", rewards = "Вы получите:\n\n"},
[7043] = {title = "Прохладное чувство юмора", objective = "Отыщите украденные лакомства и верните их Кардену Деньгозвону в Стальгорн. Лакомства должны быть у Омерзительного Гринча, который бродит где-то среди заснеженных вершин Альтеракских гор.", description = "<имя>, с-существо, которое зовут \"Оме-мерзительный Гри-инч\", похитило все наши лакомства! Т-только ос-стор-р-рожно! Это он с-сделал из меня с-снеговика!\n\nВа-ва-вам понадобится помощь! Я в-видел, как он шляется тут в-в-вместе с другими йети. Он нав-верняка где-то п-поблизости! Отыщите мой груз, <имя>, отвезите его в Стальгорн, П-пастбищам Дымного леса, и п-п-передайте им, что м-меня надо разморозить!", progress = "Кортезз, без этих лакомств наш праздник Зимнего Покрова будет загублен на корню! Можете себе представить: все послушные детки останутся без знаменитых пирожков Гракку!", completion = "Вы нашли груз! Вы спасли наш праздник!\n\nБедный Сакс! Конечно же, мы немедленно отправим спасателей и придумаем, как его разморозить. Надеюсь, он успеет прийти в себя к празднику... Хотя, конечно же, потом ему придется отработать то время, которое он прогулял! Но в любом случае, если бы не вы, все пошло бы прахом!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[7044] = {title = "Легенды Мародона", objective = "Добудьте две части скипетра Келебраса – жезл Келебраса и бриллиант Келебраса.\n\nНайдите способ поговорить с Келебрасом.", description = "Повелитель сатиров, лорд Злоязыкий, сеет ужас по всем ходам-переходам этой пещеры, отравляя разум и чувства всех несчастных, оказавшихся внутри. Он живет за лиловыми кристаллами.\n\nКроме того, Злоязыкий создал живой символ собственного падения, Ноксиона, который живет за оранжевыми кристаллами. Эти двое похитили скипетр моего брата. Келебрас, мой брат... бессмысленно бродит по пещерам, снедаемый порчей.\n\nПомоги ему! Найди обломки скипетра и попробуй поговорить с моим братом.", progress = "Я очнулся от нескончамого кошмара...", completion = "Теперь, когда мой жезл собран воедино, надеюсь, вскоре мы сумеем избавить Мародон от скверны.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[7045] = {title = "Пастбища Дымного Леса благодарят тебя!", objective = "Поговорите с Дедушкой Зимой в Стальгорне.", description = "Спасибо тебе от Пастбищ Дымного Леса за возвращение краденых сладостей, <имя>! И хотим мы тебе за это предложить особый подарок... От самого Дедушки Зимы!\n\nПоговори с Дедушкой Зимой, и он даст тебе подарок праздника Зимнего Покрова от нашего имени! От нашего села да к вашему столу, вкусная и здоровая пища от Пастбищ Дымного Леса... благодаря тебе, конечно же!", progress = nil, completion = "Хо-хо-хо! Добро пожаловать!\n\nГоблины мне сказали, что тебе нынче полагается специальный приз, и я рад отдать его. Вот он – и веселого тебе праздника Зимнего Покрова каждый год!", rewards = "Вы получите:\n\nОсобый дар Пастбищ Дымного Леса"},
[7046] = {title = "Скипетр Келебраса", objective = "Помогите Селебрасу Искупленному воссоздать скипетр Селебраса.\n\nПо завершении ритуала снова обратитесь к нему.", description = "Некогда скипетр был моей опорой и надежей. Его сила позволяла мне стремительно перемещаться по этим пещерам. Я надеялся умиротворить дух моего дяди... Теперь я передам это бремя тебе.\n\nДля того же, чтобы слить воедино обе половины скипетра, мне понадобится твоя помощь. Иди за мной и пока я буду призывать энергию, чтобы воссоединить жезл с бриллиантом, выполняй мои указания.\n\nВоссоздадим же совместными усилиями скипетр Келебраса!", progress = "Если ты хочешь начать ритуал заново, останови его и снова обратись ко мне.", completion = "Прошу тебя, возьми этот скипетр и знай, что заключенная в нем сила должна служить лишь добру. Не останавливайся на достигнутом, иди дальше, вглубь пещер. Надеюсь, ты сумеешь отыскать останки моего дяди. Тебя подстерегает множество опасностей, Эфром.\n\nЕсли понадобится, можешь смело обращаться ко мне.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nСкипетр Селебраса"},
[7061] = {title = "Праздник Зимнего Покрова", objective = "Прочитайте книгу \"Праздник Зимнего Покрова\". Отнесите книгу Кэрну Кровавому Копыту в Громовой Утес.", description = "Вот, если тебе интересно узнать о празднике Зимнего Покрова побольше, прочти эту книгу. Я полагаю, что наше толкование легенды достаточно верное, и все же, как ученый, предпочитаю, чтобы вся информация была проверена.\n\nКогда дочитаешь, отнеси эту книгу в Громовой Утес Кэрну Кровавому Копыту. Ему наверняка приятно будет узнать, что кто-то еще интересуется преданиями нашего народа.", progress = "Добро пожаловать в Мулгор и нашу скромную общину Громового Утеса, друг мой. Мне всегда были по нраву те, кому интересно наше королевство, его народ и его предания. Ты ведь поэтому здесь?", completion = "Предания и легенды, связанные с Зимним Покровом, с годами потускнели и забылись. Да, я знаю, что гоблины помогают возрождать этот праздник в своих собственных целях, но все же радует, что народ хоть как-то помнит о нем.\n\nТвое желание узнать еще больше о нем и о нашем прошлом весьма похвально, |3-6(Шаман). Подобное стремление к мудрости можно лишь приветствовать.", rewards = "Вы получите:\n\n"},
[7062] = {title = "Повод для праздника", objective = "Поговорите с историком Карником в лиге Исследователей в Стальгорне о празднике Зимнего Покрова.", description = "Подарки, гости, угощение... чушь собачья!\n\nЭти гоблины искажают самую суть праздника Зимнего Покрова. Это время возрождения – земля спит под покровом снега, которым ее укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке!\n\nЕжели вам интересно узнать, что такое на самом деле этот праздник, поспрошайте историка Карника из лиги Исследователей. Уверен, он будет очень удивлен, что кому-то история интереснее подарков.", progress = nil, completion = "Говорите, праздник Зимнего Покрова? Увы, в прежние времена для нас, дворфов, он имел гораздо более весомое значение. А теперь, похоже, другие используют легенду о Дедушке Зиме, чтобы продать побольше сладостей и подарков.\n\nНеудивительно, что Голли так огорчает эта перемена. Он и остальные дворфы держатся за наше прошлое, как за боевое знамя. Я лично считаю, что небольшой праздник никогда не помешает, но о его происхождении забывать нельзя.", rewards = "Вы получите:\n\n"},
[7063] = {title = "Праздник Зимнего Покрова", objective = "Прочтите книгу \"Праздник Зимнего Покрова\", узнайте побольше о происхождении праздника. Закончив читать книгу, отнесите ее королю Магни Бронзобороду в Стальгорн.", description = "Если вам интересно побольше узнать о празднике Зимнего Покрова, прочтите эту книгу. Хотя я и думаю, что наше толкование легенды вполне соответствующее, я все же ученый и буду рад, если мне удастся свести всю информацию воедино.\n\nКогда вы отправитесь к королю Магни Бронзобороду, отнесите ему эту книгу. Я точно знаю: ему приятно будет услышать, что кто-то еще интересуется старинными легендами.", progress = "Добро пожаловать в королевство Стальгорн. Мне всегда по сердцу те, кто интересуется нашим королевством, его народом и его преданиями. Вы ведь ради этого явились ко мне?", completion = "Легенды и предания о Зимнем Покрове уже много лет подернуты дымкой забвения. Я понимаю, что гоблины возродили праздник ради собственных целей, но хорошо, что жители хотя бы так помнят о нем.\n\nВаше желание докопаться до истины и узнать о нашем прошлом – замечательное качество, юный |3-6(Маг). Меня радует ваша природная любознательность.", rewards = "Вы получите:\n\n"},
[7064] = {title = "Яблочко от яблоньки...", objective = "Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от Деревни Ночных Охотников в Пустошах.", description = "В глубинах Мародона живет злобное создание Хаоса, элементаль земли, принцесса Терадрас, находящаяся в родстве с Древними Богами. Когда-то, давным-давно, ее отыскал Зейтар, первый сын Кенария. Их... потомство зовется кентаврами. Благодарные потомки убили Зейтара, а его останки оказались во власти Терадрас. Я ищу того, кому хватит сил одолеть Терадрас и вернуть останки Зейтара в Каменный Коготь.", progress = nil, completion = "Отличные новости, Нигилум! Спасибо!\n\nЯ поговорю с Марандисом и спрошу его совета, как быть с останками Зейтара. Ну, по крайней мере, самая сложная часть задания выполнена.\n\nМне было предписано предложить эти предметы в награду тому, кто сумеет помочь нам. Выбери любой из них.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМолотящий клинокЖезл ВозрожденияЦель Зеленого хранителя\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[7065] = {title = "Яблочко от яблоньки...", objective = "Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши.", description = "В глубинах Мародона живет злобное создание Хаоса, элементаль земли, принцесса Терадрас, находящаяся в родстве с Древними Богами. Когда-то, давным-давно, ее отыскал Зейтар, первый сын Кенария. Их... потомство зовется кентаврами. Благодарные потомки убили Зейтара, а его останки оказались во власти Терадрас. Я ищу того, кому хватит сил одолеть Терадрас и вернуть останки Зейтара в Каменный Коготь.", progress = nil, completion = "Отличные новости, Эфром! Спасибо!\n\nХотя мне жаль, что ты не смог принести останки Зейтара, кто я, чтобы оспаривать волю первенца Кенария? Может быть, кентавры сумеют преодолеть собственную кровожадность – будем надеяться на лучшее.\n\nМне было предписано предложить эти предметы в награду тому, кто сумеет помочь нам. Выбери любой из них.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМолотящий клинокЖезл ВозрожденияЦель Зеленого хранителя\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[7066] = {title = "Семя Жизни", objective = "Найдите в Лунной поляне Ремулоса и отдайте ему Семя Жизни.", description = "Несчастные кентавры – мои дети – пропадут без отца.\n\nОглянись – это место исполнены надежды и того, чему учил мой отец, Кенарий. И все это произошло от меня! Я не могу лишить их своей поддержки... хоть они и обратились против меня.\n\nУ меня есть к тебе просьба – я хочу успокоить своего брата. Возьми это... первое семя жизни, родившейся из моих останков. Скажи ему, что я не погиб, а мой дух ныне пребывает здесь. Уверен, он меня поймет.", progress = "От тебя несет скверной, как от большинства искателей приключений наших дней. Но ты отличаешься от остальных. О чем ты хочешь со мной поговорить? Я чую что-то знакомое, но не могу понять, что именно.\n\nПрошу тебя, скажи, почему ты хотел поговорить со мной?", completion = "Итак, мой брат обрел покой? Я счастлив, что дожил до этого дня. Видя его гордость и гнев, я опасался, что он навеки потерян для нас... Но этот символ принесенной им жертвы доказывает, что он не погиб, но возродился для жизни вечной. Он занял свое место в природе, как и пристало ему.\n\nБлагодарю тебя, Эфром. Принеся мне дар от моего брата, ты посеял во мне надежду, которая, казалось, давно умерла. Я чувствую, что это семя еще принесет свой благой плод в этой истерзанной войнами земле.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[7067] = {title = "Инструкции кентавра-парии", objective = "Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей.", description = "Хотя меня изгнали из племени как еретика, меня поддерживает вера. Только ей я и живу. Впрочем, мне не исполнить предначертанное без посторонней помощи... Причем помощи чужака, а не кентавра.\n\nКто-то должен войти в священные залы Мародона – гробницы, которую защищает мой народ, допуская внутрь лишь избранных.\n\nЕсли ты <согласен/согласна> помочь мне, стоит только кивнуть. Я отдам тебе свиток с инструкциями. прочти его и обдумай мои слова.", progress = "Что ты решил, Тузвколоде? Ты сможешь мне помочь? Ступишь ли ты на священную землю, чтобы помочь мне создать единый народ кентавров?!", completion = "Вот он, вот амулет! Теперь мне предстоит долгое дело объединения племен. Спасибо.\n\nВот, возьми это за услуги. Надеюсь, мы еще встретимся в совсем другой обстановке.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЗнак Избранного"},
[7068] = {title = "Фрагменты осколка сумрака", objective = "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель'наю в Оргриммар.", description = "Сильна магия в святом месте для кентавров, священном Мародоне. Племена кентавров Пустошей готовы биться за эти места до последней капли крови, но куда им! Мы свое возьмем!\n\nСтупай в ихний Мародон и найди там каменных тварей из осколков сумрака. Ты дашь Утель'наю лиловые кристаллы, а уж он тебя не обидит!\n\nМеста там опасные, так что бери с собой друзей.", progress = "Ну как, нашел кристаллы? Ритуалы силы, могущественные заклятья... Одним словом, эти осколки очень и очень нужны всем знатокам тайных искусств.", completion = "Ага, как раз то, что нужно для колдовства. Возьми одну из этих побрякушек и иди отсюда... У меня полно работы.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМогучая подвеска Осколков СумракаЧудесная подвеска Осколков Сумрака\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[7070] = {title = "Фрагменты осколка сумрака", objective = "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей.", description = "Я недавно начал испытания различных кристаллов и их магических свойств. Леди Праудмур позволила мне обратиться к путешественникам в Пустошах с просьбой отыскать там некое место, называющееся Мародон. В руинах храма поселились огромные каменные элементали, состоящие из лиловых кристаллов, которые я нарек осколками сумрака.\n\nЕсли ты решишь направиться в ту сторону и захватишь по пути несколько кристаллов, я буду очень признателен. Более того, я могу сделать тебе из них украшение.", progress = "Ты уже побывал в Мараудоне? Понимаю, дело это опасное, но если ты достигнешь успеха, награда с лихвой окупит затраченные усилия.", completion = "Отличные кристаллы, Черриот. На самом деле некоторые искатели приключений уже принесли мне образцы этих кристаллов, и из них я сделал эти украшение... Можешь выбрать любое из них. И еще раз спасибо. Чем больше образцов, тем лучше.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nМогучая подвеска Осколков СумракаЧудесная подвеска Осколков Сумрака\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[7081] = {title = "Кладбища Альтеракской долины", objective = "Захватите кладбище, затем возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.", description = "Кладбища в Альтеракской долине представляют собой очень большую ценность. И Орда, и Альянс свирепо дерутся за право обладать этими сакральными местами. $GГотов:Готова; ли ты вступить в эту схватку, <имя>?\n\nЯ хочу, чтобы ты <захватил/захватила> кладбище неприятеля. Найди кладбище с вымпелом Орды и вытащи из земли этот вымпел! Вот и все, задание выполнено.\n\nЕсли не сложно, можешь покараулить захваченное кладбище несколько минут, до прибытия наших войск.", progress = "Кислод, ты еще не захватил кладбище. Возвращайся, когда задание будет выполнено!", completion = "Отлично! Кладбища нам необходимы, чтобы удерживать контроль над Альтеракской долиной. Захватывая кладбища, ты помогаешь Альянсу отстоять свою независимость.\n\nА теперь ступай, Старч. Возвращайся в бой, и если увидишь еще одно кладбище Орды... то ты знаешь, что надо делать!", rewards = "Вы получите:\n\n"},
[7082] = {title = "Кладбища долины Альтерака", objective = "Захватите кладбище, затем возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.", description = "Линия фронта в Альтеракской долине постоянно изменяется. Мы отступаем и снова отвоевываем территории в смертельной схватке с врагом. Особо яростные сражения идут за кладбища, <имя>.\n\nЯ приказываю тебе атаковать кладбище Альянса! Найди кладбище с вымпелом Альянса в центре и вырви вымпел из земли!\n\nНа этом задание будет выполнено. Но тебе нужно будет подождать некоторое время, пока не придут наши войска.", progress = nil, completion = "Отлично, Стиммакс! Если мы завладеем всеми кладбищами, духи врагов будут бесцельно слоняться по этим землям, не в силах помешать нам.", rewards = "Вы получите:\n\n"},
[7101] = {title = "Башни и бункеры", objective = "Захватите башню врага и возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.", description = "Башни и бункеры – основные защитные сооружения, так что все они должны быть нашими! Твое следующее задание – захват вражеского бункера.\n\nЗайди в бункер Альянса – над ним развевается их флаг. Внутри ты увидишь вымпел. Сними его, и на его месте появится белый вымпел Орды. Дело сделано!\n\nБольше ничего не нужно, но если ты немного подождешь и не дашь Альянсу отбить бункер обратно, то он самоуничтожится!", progress = nil, completion = "Я слышала, задание успешно выполнено! Это хорошо...\n\nТеперь наши войска смогут безнаказанно продвинуться вперед и показать Альянсу, что ему не место в Альтеракской долине!", rewards = "Вы получите:\n\n"},
[7102] = {title = "Башни и бункеры", objective = "Уничтожьте вымпел на вражеской башне или бункере и возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.", description = "Башни и бункеры – основные защитные сооружения, так что у нас их должно быть как можно больше! Я приказываю тебе атаковать вражескую башню или бункер в Альтеракской долине.\n\nЗайди в бункер Орды – над ним развевается их флаг. Внутри ты увидишь вымпел. Сними его, и на его месте появится белый вымпел Альянса. Дело сделано!\n\nОднако, на этом задание еще не закончено. Если ты продержишься рядом с башней некоторое время, чтобы ее не захватила Орда, то она разрушится!", progress = nil, completion = "Я получил отчет о том, что ты обезвредил вражеский вымпел. Отлично, Старч! Теперь мы перенесем линию фронта на вражескую территорию.", rewards = "Вы получите:\n\n"},
[7121] = {title = "Интендант", objective = "Поговорите с интендантом клана Грозовой Вершины.", description = "<имя>, интендант велел отправлять новых рекрутов к нему. Нам нужны припасы, которые хранятся в тайниках на рудниках Альтерака, так что, скорее всего, он отправит тебя за ними.\n\nСтупай по этой дороге на запад, там найдешь интенданта.", progress = nil, completion = "Приятно видеть новых солдат, Козелдур, но если повезет, ты скоро отправишься на задание и перестанешь быть новичком.\n\nПодойди ко мне через минутку, я дам тебе задание...", rewards = "Вы получите:\n\n"},
[7122] = {title = "Захват рудника", objective = "Захватите рудник, который не принадлежит Грозовой Вершине, и возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.", description = "Рудники в Альтеракской долине – нечто большее, чем обычные сырьевые ресурсы. И Грозовая Вершина, и клан Северного Волка хранят на рудниках свои припасы. Одни – на Железном руднике, другие – на руднике Ледяного Зуба. Неплохо было бы захватить чужие припасы!\n\nЗахвати рудник и возращайся ко мне. Найди рудник, который никому не принадлежит, и убей того, кто там главный. После этого рудник перейдет к нам, и мы вышлем войска для его охраны.", progress = nil, completion = "У тебя получилось! Прекрасная работа, Старч! Теперь, когда рудник охраняют наши войска, добывать сырье и хранить припасы станет гораздо легче.", rewards = "Вы получите:\n\n"},
[7123] = {title = "Разговор с интендантом", objective = "Поговорите с интендантом клана Северного Волка.", description = "<имя>, интендант клана Северного Волка набирает рекрутов для задания на рудниках Альтеракской долины. Поговори с ним, он расскажет тебе все подробно.\n\nСтупай в бункер по западной дороге, зайди в западный вход, там ты и найдешь интенданта.", progress = nil, completion = "Привет тебе, Стиммакс! Приятно видеть |3-3(Шаман), который решил служить Орде. Обратись ко мне через минутку, я выдам тебе жизненно важное задание...", rewards = "Вы получите:\n\n"},
[7124] = {title = "Захват рудника", objective = "Захватите рудник и возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.", description = "Битва, разгоревшаяся на землях Альтеракской долины, идет и за рудники – Железный и Ледяного Зуба. Они богаты сырьем, и к тому же их можно использовать для хранения припасов.\n\nПомоги нам, <имя>! Захвати один из этих рудников, во имя Орды! Отправляйся на рудник, который принадлежит нашим врагам, и убей того, кто там главный. Как только ты захватишь рудник, мы вышлем войска, чтобы взять его под охрану.", progress = nil, completion = "Ты захватил рудник! Мы вышлем туда охрану и сможем добывать сырье и хранить припасы.\n\nОтлично, Снатяжкой. Ты оказал Орде неоценимую помощь в ведении боевых действий!", rewards = "Вы получите:\n\n"},
[7141] = {title = "Битва за Альтерак", objective = "Отправляйтесь в Альтеракскую долину, сразитесь с генералом Орды Дрек'Таром и возвращайтесь к проспектору Камнетерке в Альтеракские горы.", description = "Лига Исследователей уверена, что в Альтеракской долине есть артефакты, но клан Северного Волка не позволяет нам проводить здесь исследования. Не дадим Орде задушить наши благородные научные начинания! Уничтожь генерала Северного Волка, Дрек'Тара. Без него орки ничего сделать не смогут.\n\nДрек'Тара можно найти в крепости Северного Волка, на юге Альтеракской долины. Убей его и возвращайся.", progress = "Ступай, Гнумка. Отправляйся в Альтеракскую долину и уничтожь генерала орков!", completion = "Прекрасная работа, Флейфе! Орда не скоро оправится от смерти генерала, так что мы можем начинать наши исследования!", rewards = "Вы получите:\n\n"},
[7142] = {title = "Битва за Альтерак", objective = "Отправляйтесь в Альтеракскую долину и убейте генерала дворфов, Вандара Грозовую Вершину. После этого возвращайтесь к Вогге Смертной Хватке в Альтеракские горы.", description = "Дворфы Грозовой Вершины вместе со своими союзниками вторглись в Альтеракскую долину, и мы должны выкинуть их отсюда! Если мы хотим выиграть битву за Альтерак наверняка, то нам нужно уничтожить их генерала, Вандара Грозовую Вершину!\n\nЕго можно найти в Дун Болдаре, на севере Альтеракской долины.\n\nУбей его, <имя>, и возвращайся обратно ко мне.", progress = "Мы не потерпим дворфов на наших землях! Отправляйся к нашим врагам и убей их вождя, генерала Грозовую Вершину!", completion = "Отлично, Стиммакс! Зря Грозовая Вершина вторглась на эти земли. Себе дороже вышло!\n\nХа! Все, чего они добились – это смерти своего генерала!", rewards = "Вы получите:\n\n"},
[7161] = {title = "Испытательные земли", objective = "Отправляйтесь в пещеры Дикой Лапы, расположенные на юго-востоке от основной базы в Альтеракской долине, и добудьте вымпел клана Северного Волка. Отнесите выпмел клана Северного Волка воеводе Лаггронду.", description = "Приветствую, <класс>. Много времени прошло с тех пор, когда мы в последний раз внимали зову битвы. Трудно пробудить давно забытые чувства, но если они проснулись, обязательно прольется кровь. Ярость боя зовет нас...\n\nВ долине Альтерака все новички должны пройти боевое крещение.\n\nГлубоко в пещерах гноллов из стаи Дикой Лапы хранится вымпел клана Северного Волка. Отправляйся туда и добудь его. Возвращайся ко мне вместе с вымпелом, и получишь знак отличия новобранца.", progress = "Подъем! Подъем, Орканавт! Это не сон! Ты и правда попал в самое пекло сражений!", completion = "Это жгучее чувство означает, что твоя душа пробудилась и услышала зов битвы.\n\nТеперь ты – один из клана Северного Волка, Снатяжкой. Поздравляю тебя.\n\nПостоянно носи с собой этот знак. По мере того как ты будешь продвигаться по службе в клане Северного Волка, я буду заменять его на другие, соответствующие более высокому званию.\n\nВозможно, однажды придет день, когда ты заслужишь полное уважение клана Северного Волка и получишь Око Командования.", rewards = "Вы получите:\n\nЗнак различия клана Северного Волка, ранг 1Очищая луковицу"},
[7162] = {title = "Испытательные земли", objective = "Отправляйтесь в Пещеру Ледяного Крыла, которые расположены в Альтеракской долине, на юго-западе от Дун Болдара, и добудьте вымпел Грозовой Вершины. Отдайте вымпел лейтенанту Мурпу в Альтеракских горах.", description = "Ты <прибыл/прибыла> вовремя, <класс>. Эти дикари из клана Северного Волка ни в какую не желают сдаваться! Ничего, мы им покажем, на что способна Грозовая Вершина. Они склонятся перед нашей мощью!\n\nПеред тем, как отправиться в бой, ты <должен/должна> вступить в ряды Грозовой Вершины.\n\nК юго-востоку от Дун Болдара находится Пещера Ледяного Крыла. В их недрах хранится вымпел Грозовой Вершины. Отправляйся туда и добудь его. Принеси вымпел мне, и получишь отличительный знак новобранца.", progress = "В этих землях следует опасаться гарпий, |3-6(Воин). Они не задумываясь вырвут тебе глотку.", completion = "Прими этот знак и носи его с честью, Мерандир. Это символ твоего положения в Грозовой Вершине. Когда ты приобретешь уважение Грозовой Вершины, я выдам тебе другой знак.\n\nВозможно, в один прекрасный день ты станешь легендарным воителем и получишь Око Командования.", rewards = "Вы получите:\n\nЗнак отличия Грозовой Вершины, ранг 1Артишок Северного Волка"},
[7163] = {title = "Награда найдет героя", objective = "*Воевода Лаггронд отдает вам салют.*\n\nПришло твое время, Снатяжкой. Ты столько сделал для клана Северного Волка, что можешь считаться не просто солдатом, а настоящим другом.\n\nОтлично! Давай свой знак новобранца.", description = nil, progress = "*Воевода Лаггронд отдает вам салют.*\n\nПришло твое время, Снатяжкой. Ты столько сделал для клана Северного Волка, что можешь считаться не просто солдатом, а настоящим другом.\n\nОтлично! Давай свой знак новобранца.", completion = "Это знак особого расположения клана Северного Волка. Носи его с собой все время.\n\nИ вот что, |3-6(Охотник)... Придет время умирать – умри с честью!", rewards = "Вы получите:\n\nЗнак различия клана Северного Волка, ранг 2"},
[7164] = {title = "Уважение клана", objective = "Рад снова тебя видеть, |3-6(Жрец). Не ожидал, что ты вернешься. Но вот, ты зарекомендовал себя как отважный и доблестный воитель клана Северного Волка.\n\nПришло время получить новое звание, Шэдоустайл. А с ним и новый знак отличия.\n\nДай мне свой знак.", description = nil, progress = "Рад снова тебя видеть, |3-6(Жрец). Не ожидал, что ты вернешься. Но вот, ты зарекомендовал себя как отважный и доблестный воитель клана Северного Волка.\n\nПришло время получить новое звание, Шэдоустайл. А с ним и новый знак отличия.\n\nДай мне свой знак.", completion = "*Воевода Лаггронд отдает салют.*\n\nСтупай, Снатяжкой! Продолжай сражаться за клан Северного Волка! Мы должны выиграть эту войну! За Дрек'Тара! За Вождя!", rewards = "Вы получите:\n\nЗнак различия клана Северного Волка, ранг 3"},
[7165] = {title = "Заслуженное почтение", objective = "Ты убил так много врагов, что реки покраснели от крови. Твоя стойкость в бою достойна всяческих похвал. Я верю, ты приведешь нашу армию к великим победам. Солдат, ты заслужил новое звание.\n\nПредъяви свой знак отличия.", description = nil, progress = "Ты убил так много врагов, что реки покраснели от крови. Твоя стойкость в бою достойна всяческих похвал. Я верю, ты приведешь нашу армию к великим победам. Солдат, ты заслужил новое звание.\n\nПредъяви свой знак отличия.", completion = "*Воевода Лаггронд рычит.*\n\nО твоих подвигах уже слагаются песни, солдат. Грозовая Вершина содрогается в страхе, слыша твое имя. Так держать!", rewards = "Вы получите:\n\nЗнак различия клана Северного Волка, ранг 4"},
[7166] = {title = "Легендарные герои", objective = "Я чувствую исходящие от тебя мощь и силу, |3-6(Чернокнижник). Клан Северного Волка восхищен твоим героизмом. Мы знаем, что враги трепещут при одном упоминании твоего имени.\n\nВстань, великий воитель Северного Волка. Встань и прими хвалу!\n\nДай мне свой знак отличия.", description = nil, progress = "Я чувствую исходящие от тебя мощь и силу, |3-6(Чернокнижник). Клан Северного Волка восхищен твоим героизмом. Мы знаем, что враги трепещут при одном упоминании твоего имени.\n\nВстань, великий воитель Северного Волка. Встань и прими хвалу!\n\nДай мне свой знак отличия.", completion = "Скоро ты окинешь бдительным оком все поля сражений! Ты примешь командование долиной Альтерака и всеми ее войсками!", rewards = "Вы получите:\n\nЗнак различия клана Северного Волка, ранг 5"},
[7167] = {title = "Око Командования", objective = "Дрек'Тар наслышан о твоих подвигах. В Калимдоре только и говорят, что о твоем героизме. Сам Вождь гордится тем, что ты сделал для нашего клана.\n\nТы заслужил Око Командования.\n\nПредъяви свой знак отличия, командир Дулозалепи.\n\n*Воевода Лаггронд отдает салют.*", description = nil, progress = "Дрек'Тар наслышан о твоих подвигах. В Калимдоре только и говорят, что о твоем героизме. Сам Вождь гордится тем, что ты сделал для нашего клана.\n\nТы заслужил Око Командования.\n\nПредъяви свой знак отличия, командир Дулозалепи.\n\n*Воевода Лаггронд отдает салют.*", completion = "Направь силу своего знака, и пусть враги услышат твой голос. Мощь Орды несокрушима!", rewards = "Вы получите:\n\nЗнак различия клана Северного Волка, ранг 6"},
[7168] = {title = "Награда найдет героя", objective = "Жизнь многих заканчивается раньше, чем они получают то, чего заслуживают. Ты показал себя образцовым солдатом, |3-6(Охотник). Время пришло.\n\nДай мне свой отличительный знак.", description = nil, progress = "Жизнь многих заканчивается раньше, чем они получают то, чего заслуживают. Ты показал себя образцовым солдатом, |3-6(Охотник). Время пришло.\n\nДай мне свой отличительный знак.", completion = "Пусть враги знают, что их поверг не простой солдат, а один из командиров Грозовой Вершины!", rewards = "Вы получите:\n\nЗнак отличия Грозовой Вершины, ранг 2"},
[7169] = {title = "Уважение Стражи", objective = "База полна слухами о твоих подвигах на Поле брани. Ты нанес нашим врагам могучий удар, от которого они не скоро оправятся. Ты заслужил уважение Грозовой Вершины.\n\nПредъяви свой знак отличия!", description = nil, progress = "База полна слухами о твоих подвигах на Поле брани. Ты нанес нашим врагам могучий удар, от которого они не скоро оправятся. Ты заслужил уважение Грозовой Вершины.\n\nПредъяви свой знак отличия!", completion = "Сам король наслышан о твоих подвигах на поле брани, |3-6(Чернокнижник). Продолжай с честью нести стражу Грозовой Вершины!", rewards = "Вы получите:\n\nЗнак отличия Грозовой Вершины, ранг 3"},
[7170] = {title = "Заслуженное почтение", objective = "Ответь мне, Рен. Видишь ли ты страх в глазах своих врагов? Они разбегаются в панике при виде тебя? Должно быть, понимают, что у них нет ни шанса.\n\nТы заслужил почтительное отношение Стражи. Дай мне свой знак отличия.", description = nil, progress = "Ответь мне, Рен. Видишь ли ты страх в глазах своих врагов? Они разбегаются в панике при виде тебя? Должно быть, понимают, что у них нет ни шанса.\n\nТы заслужил почтительное отношение Стражи. Дай мне свой знак отличия.", completion = "Когда мы встретились впервые, я не сомневался, что из тебя получится великий воитель. Носи свой знак с честью, солдат!", rewards = "Вы получите:\n\nЗнак отличия Грозовой Вершины, ранг 4"},
[7171] = {title = "Легендарные герои", objective = "Предо мной стоит великий воитель Альянса!\n\n*Лейтенант Мурп отдает салют.*\n\nНемногие в Грозовой Вершине удостоены такого ранга. Я видел, как ты сокрушаешь врагов. Один твой взгляд повергает их в трепет. Когда ты вступаешь в бой, в сердцах наших солдат загорается надежда.\n\nДай мне свой знак отличия.", description = nil, progress = "Предо мной стоит великий воитель Альянса!\n\n*Лейтенант Мурп отдает салют.*\n\nНемногие в Грозовой Вершине удостоены такого ранга. Я видел, как ты сокрушаешь врагов. Один твой взгляд повергает их в трепет. Когда ты вступаешь в бой, в сердцах наших солдат загорается надежда.\n\nДай мне свой знак отличия.", completion = "Без сомнения, ты сумеешь заслужить и Око Командования!", rewards = "Вы получите:\n\nЗнак отличия Грозовой Вершины, ранг 5"},
[7172] = {title = "Око Командования", objective = "Пусть они услышат тебя, командир Дайчи! Пусть познают, что такое страх. Покажи им силу Грозовой Вершины!\n\nПредъяви свой знак отличия.", description = nil, progress = "Пусть они услышат тебя, командир Дайчи! Пусть познают, что такое страх. Покажи им силу Грозовой Вершины!\n\nПредъяви свой знак отличия.", completion = "Ты поведешь нашу армию к победе, командир! Вот твое войско. Веди его в бой... Сокруши клан Северного Волка!", rewards = "Вы получите:\n\nЗнак отличия Грозовой Вершины, ранг 6"},
[7181] = {title = "Легенда о Корраке", objective = "Согласно легенде, вождь могущественного племени троллей Секиры Зимы периодически появляется на поле боя, внося хаос и опустошение в жизнь обитателей Альтеракской долины.\n\nЕсли Коррак появится, убейте его и возвращайтесь к воеводе Лаггронду.", description = "Вторжение Грозовой Вершины – это не единственная угроза в этих землях, солдат. Война в долине ведется на два фронта. Тролли-канибалы из племени Секиры Зимы тоже представляют собой силу, с которой надо считаться.\n\nИх предводитель – Коррак Кровопуск – жестокая и коварная тварь.\n\nУбийство Коррака нанесло бы непоправимый удар племени Секиры Зимы. Убей его и получи награду!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКровоискательПокрытое изморозью копьеЖезл Лютого холода\n\nВы также получите:\n\nРуна Возвращения"},
[7201] = {title = "Последняя Стихия", objective = "Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лаграв также бормотала что-то про элементалей.", description = "У меня есть работа для тех, кто не боится заглянуть в глубины, <имя>. \n\nКлан Черного Железа научился создавать чрезвычайно мощных големов. \n\nИсходя из отчетов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим гоблинам невероятную разрушительную силу. \n\nПодумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют... Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без нее можешь не возвращаться! Награда будет сопоставима с затраченными усилиями.", progress = "*Потирает руки*\n\nНу, показывай скорее, что принес!", completion = "Превосходно! Я немедля отправлю это с курьером в Подгород. \n\nЧто же до тебя, вот твоя плата, как я и обещала. Сдачу можешь оставить себе, грязное животное!", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nПечать Лаграва"},
[7202] = {title = "Коррак Кровопуск", objective = "Согласно легенде, вождь могущественного племени троллей Секиры Зимы периодически появляется на поле боя, внося хаос и опустошение в жизнь обитателей Альтеракской долины.\n\nЕсли вам удастся найти Коррака, убейте его и возвращайтесь к лейтенанту Мурпу в Альтеракские горы.", description = "Племя Секиры Зимы, местные аборигены, имеют скверную привычку украшать свой стол блюдами из мяса наших солдат.\n\nНичего, мы им покажем, как с нами связываться!\n\nНам удалось добыть книгу, в которой записаны имена не только их знати, но и самого вождя, которое они тщательно скрывают! Его зовут Коррак Ярость Боя.\n\nСмерть Коррака – это смерть всего племени Секиры Зимы! Убей его и возвращайся.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКровоискательПокрытое изморозью копьеЖезл Лютого холода\n\nВы также получите:\n\nРуна Возвращения"},
[7221] = {title = "Разговор с геологом Камнетеркой", objective = "Поговорите с геологом Камнетеркой в гарнизоне Дун Болдара.А, <имя>, с докладом, да? Отлично, Грозовая Вершина должна использовать всех, кто годится хоть на что-нибудь.\n\nПоговори с геологом Камнетеркой в Дун Болдаре. Она как раз набирает добровольцев для очень важного задания на вражеской территории. Ты найдешь ее в гарнизоне Дун Болдара, внизу.\n\nСмотри внимательно, когда будешь пробираться через Дун Болдар. Для <класс>, <который/которая:c> не чурается работы, здесь найдется много дел.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "А, <имя>, с докладом, да? Отлично, Грозовая Вершина должна использовать всех, кто годится хоть на что-нибудь.\n\nПоговори с геологом Камнетеркой в Дун Болдаре. Она как раз набирает добровольцев для очень важного задания на вражеской территории. Ты найдешь ее в гарнизоне Дун Болдара, внизу.\n\nСмотри внимательно, когда будешь пробираться через Дун Болдар. Для <класс>, <который/которая:c> не чурается работы, здесь найдется много дел.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7222] = {title = "Разговор с Воггой Смертобоем", objective = "Поговорите с Воггой в крепости Северного Волка.<класс>? Отлично! Рады видеть тебя в Альтераке, <имя>. Дворфы и их союзники вторглись в нашу долину, так что Орда приветствует каждого, кто решил вступить в праведный бой!\n\nПоговори с Воггой Смертобоем. Он как раз набирает агентов для важного задания в крепости Альянса в Альтеракской долине!\n\nВоггу можно найти в крепости Северного Волка.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "<класс>? Отлично! Рады видеть тебя в Альтераке, <имя>. Дворфы и их союзники вторглись в нашу долину, так что Орда приветствует каждого, кто решил вступить в праведный бой!\n\nПоговори с Воггой Смертобоем. Он как раз набирает агентов для важного задания в крепости Альянса в Альтеракской долине!\n\nВоггу можно найти в крепости Северного Волка.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7223] = {title = "Обломки брони", objective = "Принесите 20 обломков брони Марготу Подземной Кузне в Дун Болдар.", description = "В Альтеракской долине часто гремят сражения, и поставок из Стальгорна для нужд наших войск недостаточно.\n\nЕсли ты найдешь на поле боя обломки брони, приноси их мне, они нам пригодятся.", progress = "Удалось найти обломки, Юмикор?", completion = "Среди них попадаются весьма неплохие куски, Юмикор. Я смогу сделать из них новую броню для наших войск.\n\nЕсли унас будет достаточно брони, то скоро новые войска смогут выйти на поле боя!", rewards = "Следующее заклинание будет наложено на вас:\n\nПолированная броня\n\nВы получите:\n\n"},
[7224] = {title = "Вражеский трофей", objective = "Принесите 20 обломков брони кузнецу Регзару в деревню Северного Волка.", description = "Если надешь на поле боя обломки вражеских доспехов, неси их мне. Из них выйдет отличная броня для наших собственных войск!", progress = "Что, Баронгеддон, попались обломки брони среди остальной добычи?", completion = "Просто отлично. Я залатаю повреждения так, что никто и не отличит обломки вражеской брони от наших доспехов!\n\nСпасибо, Баронгеддон. Хочешь, отполирую твои собственные доспехи?", rewards = "Следующее заклинание будет наложено на вас:\n\nПолированная броня\n\nВы получите:\n\n"},
[7241] = {title = "Защита клана Северного Волка", objective = "Отправляйтесь в Альтеракскую долину, расположенную в Альтеракских горах. Найдите воеводу Лаггронда у входа в тоннель и поговорите с ним, чтобы начать свою военную карьеру в клане Северного Волка. Альтеракская долина находится к северу от деревни Мельница Таррен у подножия Альтеракских гор.", description = "Издалека доносится рокот барабанов войны, <класс>. Клан твоего вождя подвергается атакам презренных дворфов клана Грозовой Вершины из Стальгорна. \n\nСудя по твоему виду, можно решить, что ты <закален в битвах и готов/закалена в битвах и готова> постоять за дело клана Северного Волка. \n\nА сейчас тебе предстоит сделать новый шаг к усовершенствованию твоего воинского мастерства. К северу от мельницы Таррен, в Альтеракских горах, есть вход в Альтеракскую долину. Там тебе нужно отыскать воеводу Лаггронда.", progress = nil, completion = "Чтобы стать солдатом Северного Волка, нужно сначала пройти испытания...", rewards = "Вы получите:\n\n"},
[7261] = {title = "Королевское право", objective = "Отправляйтесь в Альтеракскую долину, к предгорьям Хилсбрада. Найдите лейтенанта Мурпа рядом со входом в туннель и поговорите с ним.\n\nВо славу Бронзеборода!", description = "Здесь, в Альтеракской долине, идут тяжелые бои. С одной стороны на нас наступают тролли-каннибалы из племени Секиры Зимы, с другой – дикари из клана Северного Волка. Во имя короля Магни Бронзоборода, все они должны быть уничтожены! Владение этими землями – неотъемлемое суверенное право королевства Стальгорн!\n\nК сожалению, солдаты не растут на деревьях. Доложись лейтенанту Мурпу рядом с Альтеракской долиной и с честью приступай к несению службы в Грозовой Вершине!", progress = nil, completion = "За работу!", rewards = "Вы получите:\n\n"},
[7281] = {title = "Братская любовь", objective = "Отправляйтесь на территорию Грозовой Вершины и убейте командира Карла Филипса. После выполнения задания возвращайтесь к командиру Луи Филипсу.", description = "Ужасно... В сражении я столкнулся со своим братом, командиром Грозовой Вершины.\n\nИз всех четырех командиров Грозовой Вершины он самый опасный. Возможно, Королева банши сможет возродить его после смерти, и тогда я докажу ему ошибочность его поступков...\n\nМой брат находится в глубине территории врага. Убей его и возвращайся ко мне. Я уверен, солдат, что у тебя хватит сил выполнить это задание.\n\nНо лучше не отправляйся в одиночку.", progress = nil, completion = "Твой героизм не останется незамеченным, Топблэйд.\n\nЕсли я хочу спасти брата, то нельзя терять ни минуты. Я должен немедленно обратиться к Сильване!", rewards = "Вы получите:\n\n"},
[7282] = {title = "Братская любовь", objective = "Отправляйтесь на территорию клана Северного Волка и убейте командира Луи Филипса. После выполнения задания возвращайтесь к командиру Карлу Филипсу.", description = "Нужно избавить его от страданий, солдат! Воистину, он не ведает, что творит. Ужасная Королева банши сделала его своей бездумной марионеткой.\n\nСтупай вперед, через Поле брани, в глубину территории Северного Волка. Найди моего брата и уничтожь его. Его мучениям должен прийти конец.", progress = nil, completion = "Надеюсь, ты не забыл сжечь тело?", rewards = "Вы получите:\n\n"},
[7301] = {title = "Свергнутые властители небес", objective = "Отправляйтесь в крепость Северного Волка и поищите командиров звена Слидора, Змейера и Ичмана. Вернитесь с отчетом к командиру Даффи.", description = "Мы взяли их в плен, <раса>. Мы захватили командиров звена. В небе разразилась яростная битва, но в итоге они все же уступили! К сожалению, во время контратаки против крепости Северного Волка были сбиты наши лучшие пилоты. Нужно выяснить, что с ними случилось. \n\nОбыщи западную Смотровую башню и крепость Северного Волка. Там они были замечены в последний раз. Как можно тщательней осмотри эти районы.", progress = nil, completion = "Невероятно! Ты их освободил, да? Правда? Ну, по крайней мере, мы знаем теперь, где их держали.", rewards = "Вы получите:\n\n"},
[7302] = {title = "Свергнутые властители небес", objective = "Выясните, что стало с командирами звена Гусом, Джезтором и Малвериком. Вернитесь с отчетом к командиру Мулфорту.", description = "Наша воздушная поддержка в полном беспорядке, <имя>. Командиров звена сбили на вражеской территории. Ты <должен/должна> узнать, что с ними стало, чтобы мы могли попытаться их спасти! \n\nГуса в последний раз видели над укрытием Ледяного Крыла. Боевую виверну Джезтора заметили у лесопилки Грозовой Вершины. Малверик... кто-то видел, как этот безголовый идиот разбился возле северного оплота Дун Болдара. \n\nЭто вся информация, что у меня есть. За дело! Как следует прочеши указанные районы.", progress = nil, completion = "Отличная работа! Собранная тобой информация поистине бесценна.", rewards = "Вы получите:\n\n"},
[7321] = {title = "Нежный черепаховый суп", objective = "Принесите 10 кусков черепашьего мяса и немного смягчающих пряностей Кристофу Френчу на Мельницу Таррен.", description = "Кто сказал, что нежить не понимает в кулинарии? Взять, к примеру, мой заветный рецепт нежного черепашьего супа. Да я знаю народ, что из мертвых бы восстал, только бы скушать тарелочку! Хе-хе...\n\nКстати, в последнее время мне ни тарелочки приготовить не удалось. Обычно я сам ходил на озеро Лордамер ловить хрустогрызов – у, грязные тварюги – но не могу сейчас бросить работу.\n\nЕсли ты добудешь мне немного черепашьего мяса и приправ, я научу тебя варить такой суп!", progress = "Повезло добыть ингредиенты? Надо сказать, нынче эти места просто кишат подонками из Альянса... По мне, они уже зашли слишком далеко...", completion = "Мой нежный черепаший супчик согреет тебя холодной ночью... Если, конечно, ты еще помнишь, что такое холод.", rewards = "Вы получите:\n\nРецепт: нежный черепаховый супНежный черепаховый суп"},
[7341] = {title = "Честная сделка", objective = "Привет, |3-6(орк)! Я – Коларк, охотник за головами из Громового Утеса. Я обошел чуть ли не весь мир и повидал немало.\n\nПутешествуя в Южных морях, я раздобыл эти замечательные стрелы с ториевыми наконечниками. Этих стрел у меня сколько угодно, но, увы, у меня кончились ториевые патроны! А какой уважающий себя таурен будет пользоваться хлипким луком? Стрелы мне ни к чему!\n\nДавай поменяемся: я тебе – стрелы, а ты мне – такое же количество ториевых патронов! Идет?", description = nil, progress = "Привет, |3-6(орк)! Я – Коларк, охотник за головами из Громового Утеса. Я обошел чуть ли не весь мир и повидал немало.\n\nПутешествуя в Южных морях, я раздобыл эти замечательные стрелы с ториевыми наконечниками. Этих стрел у меня сколько угодно, но, увы, у меня кончились ториевые патроны! А какой уважающий себя таурен будет пользоваться хлипким луком? Стрелы мне ни к чему!\n\nДавай поменяемся: я тебе – стрелы, а ты мне – такое же количество ториевых патронов! Идет?", completion = "Отлично! Я – таурен слова, |3-6(орк). Вот тебе твои стрелы.", rewards = "Вы получите:\n\nСтрела с ториевым наконечником"},
[7342] = {title = "Стрелы – для неженок!", objective = "Нет, ты представляешь?! Последнюю партию снарядов из Караноса запороли! И остается стрелять этими хлипкими, ни на что не годными стрелами! Что мне делать с 500 000 стрел с ториевыми наконечниками?\n\nВВот что, парень. Если принесешь мне ториевых патронов, я отдам за них эти стрелы с ториевыми наконечниками, прямо сразу и отдам! Идет?", description = nil, progress = "Нет, ты представляешь?! Последнюю партию снарядов из Караноса запороли! И остается стрелять этими хлипкими, ни на что не годными стрелами! Что мне делать с 500 000 стрел с ториевыми наконечниками?\n\nВВот что, парень. Если принесешь мне ториевых патронов, я отдам за них эти стрелы с ториевыми наконечниками, прямо сразу и отдам! Идет?", completion = "Добрая сделка, если я что-то в этом понимаю! Стрелы – твои.", rewards = "Вы получите:\n\nСтрела с ториевым наконечником"},
[7361] = {title = "Благосклонность племени Черного Копья", objective = "Вам поручили убивать в Альтеракской долине ночных эльфов.\n\nУбив ночного эльфа, вернитесь с его отрубленной головой к Нажьяку Проклятуну в крепость Северного Волка.", description = "<Нажьяк ворчит.>\n\nПрежде чем появились ночные эльфы, были тролли. И именно от троллей пошли ночные эльфы. \n\nИх злобные вылазки против моего народа нельзя более терпеть. Олений Шлем хочет стереть нас с лица земли, чтобы не осталось и упоминания о тех, от кого ведут свой род он и его собратья. Не бывать этому! \n\nЗа каждого ночного эльфа, которого ты убьешь и обезглавишь, Надьяк будет одаривать тебя благосклонностью народа Черного Копья. Слава о твоих деяниях распространится по всему Калимдору и Восточным королевствам. Иди же и послужи Черному Копью!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7362] = {title = "Союзник тауренов", objective = "Убивайте гномов в Альтеракской долине.\n\nУбив гнома, принесите Раваку Зловещему Тотему в крепость Северного Волка пучок волос гнома.", description = "Мудрая Магата прислала меня в эту зону боевых действий, чтобы изучать другие расы. Точнее, мне поручено собрать образцы тканей гномов. Магату особенно интересует их живучесть. Ведь гномы – эти крошечные, жалкие создания, – проявляют удивительную устойчивость как к боевым ранениям, так и к обычным тяготам жизни.\n\nТебе повезло – мне как раз нужны помощники, чтобы выполнить поручение Магаты. Приноси мне пряди гномьих волос, и таурены будут считать тебя своим союзником.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7363] = {title = "Человечья жизнь", objective = "Вам поручили убивать людей в Альтеракской долине.\n\nУбив человека, принесите командору Луи Филипсу (который бродит между линией фронта и крепостью Северного Волка) осколок человеческой кости.\n\nОкончить человеческие страдания совсем несложно!", description = "Люди так отвратительны!\n\n<Командир Филипс брезгливо кривится.>\n\nКонечно, сейчас я состою на службе у клана Северного Волка, и все же я по-прежнему остаюсь слугой Сильваны.\n\nИ в свободное от службы время я подрабатываю, помогая Темным аптекарям Подгорода.\n\nМне поручено собирать осколки человеческих костей, которые будут использованы, чтобы исцелять людей от их жалкого состояния.\n\nЯ также могу давать аналогичное поручение своим подчиненным.\n\nИщите их. Убивайте их. И приносите мне осколки их костей!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7364] = {title = "Награда Гномрегана", objective = "Убивайте тауренов в Альтеракской долине.\n\nУбив таурена, вернитесь к Дирку Надувалло в Дун Болдар с копытом таурена.", description = "Сам главный механик прислал меня на это поле брани, чтобы защитить наших собратьев! До нас дошли вести, что таурены нарочно выискивают и убивают гномов! А самое ужасное, что они срезают с трупов павших их роскошные волосы! Этому необходимо положить конец. Мы обязаны отомстить!\n\nМы лишим их копыт, <класс>! Принеси мне их копыта! Докажи, что ты – союзник гномов!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7365] = {title = "Реквием Оленьего Шлема", objective = "Ваше задание – убивать в Альтеракской долине троллей.\n\nУбейте тролля и возвращайтесь к Атраманису в Дун Болдар с амулетом тролля из племени Черного Копья.", description = "Олений Шлем отдал приказ: во время сражений всех троллей необходимо истребить. Они должны ответить за свое наглое заявление, что ночные эльфы ведут свой род от троллей.\n\nУничтожь троллей и принеси мне их амулеты. Повторяю: мне нужны их амулеты.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7366] = {title = "Милосердие архиепископа", objective = "Ваше задание – убивать в Альтеракской долине Отрекшихся.\n\nУбейте Отрекшегося и возвращайтесь к Карлу Филипсу (он ходит между лесопилкой и рудником) с сердцем Отрекшегося.", description = "Доброта архиепископа сравнима только с его мудростью. Надо иметь невероятно чуткую душу, чтобы относиться к подобной швали с милосердием...\n\n<Командир Филипс в недоумении пожимает плечами.>\n\nОн слишком добр...Просто слишком.\n\nАрхиепископ просил нас, чтобы мы имели сострадание к нежити и даровали им быструю и верную смерть. Чтобы проявить подобное великодушие, мы должны раздобыть их черные, пораженные болезнью сердца.\n\nПринеси мне сердца Отрекшихся, чтобы мы могли сжечь их с надлежащими церемониями в Соборе Света. Поспеши, <имя>!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7367] = {title = "Обезвредить угрозу", objective = "Найдите эксперта по взрывчатым веществам из клана Северного Волка и убейте его. После завершения задания возвращайтесь к эксперту по взрывчатым веществам из клана Грозовой Вершины.", description = "Клан Северного Волка позволил заманить себя в совершенно идиотскую ловушку, <класс>. Надо быть более осмотрительным, действуя на территории врага.\n\nЕсли хочешь нанести им ощутимый удар, нужно уничтожить того, кто отвечает их за минные поля, – я говорю об эксперте по взрывчатым веществам. Пока он жив, минные поля существуют. Но если он будет мертв, поддерживать их станет некому.\n\nНе исключаю, что эксперта можно найти в башне рядом с гарнизоном Стылой Крови. Удачи тебе!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7368] = {title = "Обезвредить угрозу", objective = "Найдите эксперта по взрывчатым веществам из клана Грозовой Вершины и убейте его. После завершения задания возвращайтесь к эксперту по взрывчатым веществам из клана Северного Волка.", description = "Про противопехотные мины я знаю все. Именно я, а не кто-нибудь, отвечаю за мины на всей линии фронта.\n\nЕсли ты хочешь обезвредить все минные поля Грозовой Вершины, сначала надо убить их эксперта по взрывчатым веществам. Этот трусливый дворф скорее всего прячется в первой башне Поля брани. Убей его, и минные поля будут обезврежены раз и навсегда.\n\nКак убьешь его, возвращайся ко мне. Добрые дела не должны оставаться без награды.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7381] = {title = "Возвращение Коррака", objective = "В случае, если Коррак Кровопуск возвратится на Поле брани, найдите его и уничтожьте.\n\nПринесите череп Коррака воеводе Лаггронду в предгорья Хилсбрада.", description = "Коррак мертв, но надолго ли? О магии троллей ходит грозная слава. Я не удивлюсь, если их мертвый вождь снова восстанет, чтобы править своим племенем.\n\nТы знаешь, что делать, если это случится.\n\n<Воевода Лаггронд проводит ребром ладони по горлу.>\n\nНо на этот раз принеси его череп. И гляди в оба, солдат!\n\n<Свободен/Свободна>!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nРуна Возвращения"},
[7382] = {title = "Коррак Бессмертный", objective = "В случае, если Коррак Кровопуск возвратится на Поле брани, найдите его и уничтожьте.\n\nПринесите череп Коррака лейтенанту Хаггердину в предгорья Хилсбрада.", description = "Что-то здесь не так... Кто-нибудь догадался сжечь тело Коррака? Эти синекожие язычники ни перед чем не остановятся, чтобы возродить своего вождя.\n\nСмотри в оба, <имя>. Не удивляйся, если снова увидишь Коррака в живых. Убей его снова, но на этот раз обязательно сожги тело.\n\nЧтобы уж все проделать наверняка, отрежь ему голову и принеси череп мне, а все остальное пусть горит синим пламенем.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nРуна Возвращения"},
[7383] = {title = "Венец Земли", objective = "Наполните аметистовый фиал и принесите его Коритрасу Лунному Гневу в Доланаар.", description = "Но не все было ладно с Тельдрассилом. Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие. Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила.\n\nОднако, пока я об этом говорить не буду. Тебе нужно посетить последний лунный колодец, к северо-западу от Поляны Оракула. Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне.", progress = "Друиды, Древо-оракул и верховный друид тщательно наблюдали за ростом Тельдрассила. Но хотя мы и обрели новый дом, бессмертие к нам не вернулось.", completion = "Находиться в присуствии Древа-оракула... это все равно что увидеть воплощенную мудрость. Позволь мне продолжить...\n\nТельдрассил рос, и верховный друид обратился за благословением к драконам, ведь именно они благословили Нордрассил в древние времена. Однако Ноздорму, Повелитель Времени, отказал друиду, упрекнув его в самонадеянности. Алекстраза также отказала Оленьему Шлему, а без ее благословения рост Тельдрассила стал непредсказуем, и в нем обнаружились изъяны...", rewards = "Вы получите:\n\n"},
[7384] = {title = "Ремесленники по чешуе", objective = "Соберите немного чешуи для Караны из Убежища на Болоте Печали.", description = "Принеси мне немного чешуи", progress = nil, completion = nil, rewards = nil},
[7385] = {title = "Галлон крови", objective = "Знаешь, Профессия – давай-ка ты мне будешь носить кровь галлонами. Зачем мелочиться?", description = nil, progress = "Знаешь, Профессия – давай-ка ты мне будешь носить кровь галлонами. Зачем мелочиться?", completion = "И вновь пролилась кровь наших врагов. Я смешаю ее с той, что уже собрана. Когда крови будет столько, сколько нам нужно, Владыка Льда покажет этим собакам с Грозовой Вершины, что значит ярость клана Северного Волка!", rewards = nil},
[7386] = {title = "Гроздь кристаллов", objective = "Наверняка ты попадешь в битвы, которые будут длиться долгие дни. В такие времена не забывай собирать кристаллы Бури клана Северного Волка.\n\nКруг Кенариуса будет рад подобным дарам, Хлуси.", description = nil, progress = "Наверняка ты попадешь в битвы, которые будут длиться долгие дни. В такие времена не забывай собирать кристаллы Бури клана Северного Волка.\n\nКруг Кенариуса будет рад подобным дарам, Хлуси.", completion = "Отлично, Хлуси. Сила этих чар пригодится для усиления уже имеющейся магии. Когда энергии наберется достаточно, я смогу ее сфокусировать и воззвать к Владыке Леса о помощи.", rewards = nil},
[7401] = {title = "РАЗЫСКИВАЮТСЯ: дворфы!", objective = "Ваша задача – убивать дворфов в Альтеракской долине.\n\nУбейте дворфа и вырвите ему хребет. Отнесите хребет дворфа сержанту Язре Кровавый Рык в крепость Северного Волка.", description = "Согласно приказу сержанта Язры Кровавый Рык, все дворфы на поле сражения подлежат неукоснительному уничтожению.\n\nПосле боя из каждого убитого дворфа следует выдрать хребет, а тело оставить вонять и разлагаться, – в назидание всем, кто осмелится замахнуться на Орду.\n\nВыдранные хребты, как доказательство своих подвигов, сдавайте Язре Кровавый Рык.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7402] = {title = "РАЗЫСКИВАЮТСЯ: орки!", objective = "Ваше задание – убивать орков в Альтеракской долине.\n\nУбейте орка и доставьте зуб орка капралу Норгу Грозовой Вершине в Дун Болдар.", description = "Согласно приказу капрала Норга Грозовой Вершины, все солдаты Грозовой Вершины должны убить как можно больше орков.\n\nВ качестве трофея предъявляйте орочьи зубы.\n\nПеред тем, как вырывать оркам зубы, не забывайте надевать защитные перчатки!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[7421] = {title = "Защита Черного Копья", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7422] = {title = "Хоть шерсти клок...", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
