[8190] = {title = "Наговор худу", objective = "Занза владеет искусством древних троллей и может сделать множество полезных вещей.\n\nПринеси мне изначального идола Хаккари. Его можно отнять у двух самых могучих лейтенантов Хаккара – Джин'до и Повелителя Крови.\n\nЕще мне нужна исколотая кукла вуду. Она наверняка найдется среди отбросов в Зул-Гурубе. Поройся в заколдованных грудах мусора, скорее всего, ты отыщешь то, что нужно.\n\nПринеси мне все компоненты, и я сделаю для тебя могущественный амулет!", description = nil, progress = "Занза владеет искусством древних троллей и может сделать множество полезных вещей.\n\nПринеси мне изначального идола Хаккари. Его можно отнять у двух самых могучих лейтенантов Хаккара – Джин'до и Повелителя Крови.\n\nЕще мне нужна исколотая кукла вуду. Она наверняка найдется среди отбросов в Зул-Гурубе. Поройся в заколдованных грудах мусора, скорее всего, ты отыщешь то, что нужно.\n\nПринеси мне все компоненты, и я сделаю для тебя могущественный амулет!", completion = "Используй подарок с умом, |3-6(Чернокнижник). Не давай спуску приспешникам Хаккара!", rewards = "Вы получите:\n\nНаговор худу"},
[8191] = {title = "Пророческая аура", objective = "Занза владеет искусством древних троллей и может сделать множество полезных вещей.\n\nПринеси мне изначального идола Хаккари. Его можно отнять у двух самых могучих лейтенантов Хаккара – Джин'до и Повелителя Крови.\n\nЕще мне нужна исколотая кукла вуду. Она наверняка найдется среди отбросов в Зул-Гурубе. Поройся в заколдованных грудах мусора, скорее всего, ты отыщешь то, что нужно.\n\nПринеси мне все компоненты, и я сделаю для тебя могущественный амулет!", description = nil, progress = "Занза владеет искусством древних троллей и может сделать множество полезных вещей.\n\nПринеси мне изначального идола Хаккари. Его можно отнять у двух самых могучих лейтенантов Хаккара – Джин'до и Повелителя Крови.\n\nЕще мне нужна исколотая кукла вуду. Она наверняка найдется среди отбросов в Зул-Гурубе. Поройся в заколдованных грудах мусора, скорее всего, ты отыщешь то, что нужно.\n\nПринеси мне все компоненты, и я сделаю для тебя могущественный амулет!", completion = "Используй подарок с умом, |3-6(Жрец). Не давай спуску приспешникам Хаккара!", rewards = "Вы получите:\n\nПророческая аура"},
[8192] = {title = "Прикосновение анимиста", objective = "Занза владеет искусством древних троллей и может сделать множество полезных вещей.\n\nПринеси мне изначального идола Хаккари. Его можно отнять у двух самых могучих лейтенантов Хаккара – Джин'до и Повелителя Крови.\n\nЕще мне нужна исколотая кукла вуду. Она наверняка найдется среди отбросов в Зул-Гурубе. Поройся в заколдованных грудах мусора, скорее всего, ты отыщешь то, что нужно.\n\nПринеси мне все компоненты, и я сделаю для тебя могущественный амулет!", description = nil, progress = "Занза владеет искусством древних троллей и может сделать множество полезных вещей.\n\nПринеси мне изначального идола Хаккари. Его можно отнять у двух самых могучих лейтенантов Хаккара – Джин'до и Повелителя Крови.\n\nЕще мне нужна исколотая кукла вуду. Она наверняка найдется среди отбросов в Зул-Гурубе. Поройся в заколдованных грудах мусора, скорее всего, ты отыщешь то, что нужно.\n\nПринеси мне все компоненты, и я сделаю для тебя могущественный амулет!", completion = "Используй подарок с умом, |3-6(Друид). Не давай спуску приспешникам Хаккара!", rewards = "Вы получите:\n\nПрикосновение анимиста"},
[8193] = {title = "Лучший удильщик", objective = "Сегодня, с 2 до 4 часов пополудни, мы проведем состязания и узнаем, кто самый лучший удильщик Азерота! Это звание заслужит тот, кто ПЕРВЫМ принет мне 40 вкуснорыб, пойманных вдоль побережья Тернистой долины!\n\nЕсли ты не сумеешь победить, моя ученица все же даст тебе по кругленькой сумме за каждые 5 вкуснорыб.\n\nДа, и не советую медлить. Вкуснорыба быстро портится!", description = nil, progress = "Сегодня, с 2 до 4 часов пополудни, мы проведем состязания и узнаем, кто самый лучший удильщик Азерота! Это звание заслужит тот, кто ПЕРВЫМ принет мне 40 вкуснорыб, пойманных вдоль побережья Тернистой долины!\n\nЕсли ты не сумеешь победить, моя ученица все же даст тебе по кругленькой сумме за каждые 5 вкуснорыб.\n\nДа, и не советую медлить. Вкуснорыба быстро портится!", completion = "Скорее сдавай пойманную рыбу, если хочешь заслужить звание лучшего удильщика! Я торчу здесь уже много ЧАСОВ, и даже маковой росинки во рту не было! Давай сюда вкуснорыб!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nАрканитовая удочкаКрючок мастера Англера\n\nВы также получите:\n\n"},
[8194] = {title = "Начинающий удильщик", objective = "Хотя мы уже определили победителя соревнований, я все равно готов купить у тебя вкуснорыбу по сходной цене. Что скажешь?", description = nil, progress = "Хотя мы уже определили победителя соревнований, я все равно готов купить у тебя вкуснорыбу по сходной цене. Что скажешь?", completion = "По рукам!", rewards = "Вы получите:\n\n"},
[8195] = {title = "Монеты племен: Зулиан, Раззаши и Хаккари", objective = "Мне нужны Знаки Силы, более известные как Монеты племен. Это ходовые монеты различных племен Зул'Гуруба, и на каждую из них наложено незаметное, но могущественное заклятие.\n\nСуществует девять видов таких монет. За некоторые из них мои компаньоны готовы поделиться с тобой снаряжением. Будут лишние – обращайся и ко мне, я обменяю три монеты на знак отличия. А ты эти знаки уже сможешь обменять у  Рин'вошо Торговца на нечто особенное.", description = nil, progress = "Мне нужны Знаки Силы, более известные как Монеты племен. Это ходовые монеты различных племен Зул'Гуруба, и на каждую из них наложено незаметное, но могущественное заклятие.\n\nСуществует девять видов таких монет. За некоторые из них мои компаньоны готовы поделиться с тобой снаряжением. Будут лишние – обращайся и ко мне, я обменяю три монеты на знак отличия. А ты эти знаки уже сможешь обменять у  Рин'вошо Торговца на нечто особенное.", completion = "Отлично – эти монеты прекрасно дополнят в мою коллекцию... Они нужны племени, чтобы помешать возрождению Кровавого бога. Этот почетный знак – твой по праву, Горрат, прими его вместе с нашей благодарностью!", rewards = "Вы получите:\n\nПочетный знак Зандалара"},
[8196] = {title = "Экстракт манго", objective = "Манго, из которых можно изготовить могучий экстракт, растут на островах Южных морей. Одно-единственное манго придает и физические и душевные силы тому, кто его съест. Тебе когда-нибудь приходилось пробовать манго? Если нет, то ты много потерял!\n\nУ нас есть запасы манго, и мы охотно обменяем плоды на Почетный знак Зандалара. Если ты не знаешь, где достать знаки, поговори с Винчаксой. Приступим к обмену?", description = nil, progress = "Манго, из которых можно изготовить могучий экстракт, растут на островах Южных морей. Одно-единственное манго придает и физические и душевные силы тому, кто его съест. Тебе когда-нибудь приходилось пробовать манго? Если нет, то ты много потерял!\n\nУ нас есть запасы манго, и мы охотно обменяем плоды на Почетный знак Зандалара. Если ты не знаешь, где достать знаки, поговори с Винчаксой. Приступим к обмену?", completion = "Хорошая сделка, дружище, наслаждайся ароматом экзотических плодов Южных морей, и да пребудет с тобой благословение племени.", rewards = "Вы получите:\n\nКонцентрат манго"},
[8201] = {title = "Коллекция голов", objective = "Соберите ожерелье из голов пятерых жрецов и вернитесь с ним к Экзалу на остров Йоджамба.", description = "Это правда. Хаккар теперь обитает в Зул'Гурубе, питаясь силой наших богов. Порабощеные им жрецы направляют энергию самых священных божеств Свежевателю Душ, и скоро сильнее его в Азероте не будет существа. Его надо остановить!\n\nВозьми этот священный шнур. Нанижи на него головы верховных жрецов, по вине которых сила наших богов утекает к Хаккару.\n\nСделав это, возвращайся ко мне.", progress = "Ты уже открутил жрецам головы, Ишт? Мы должны остановить Хаккара, пока он не набрался сил!", completion = "Вот это ожерелье! Тебе удалось остановить хищение силы наших богов и ослабить Хаккара!\n\nТы совершил настоящий подвиг, Ишт. Пусть головы этих презренных троллей продолжают умолять тебя о пощаде – даже после того, как в них остынет кровь.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПояс Усохших ГоловПояс Высохших ГоловПояс Сохраненных ГоловПояс Крошечных Голов\n\nВы также получите:\n\n"},
[8221] = {title = "Редкая рыба – Рыба-ангел Кифера", objective = "*ЖЖЖ**Щелк*\n\nЯ разыскиваю редкие сорта рыбы по поручению рыбака  Синежаброго. Если вы принесете мне рыбу-ангела Кифера, то получите награду.\n\n*Щелк**Жжж*", description = nil, progress = "*ЖЖЖ**Щелк*\n\nЯ разыскиваю редкие сорта рыбы по поручению рыбака  Синежаброго. Если вы принесете мне рыбу-ангела Кифера, то получите награду.\n\n*Щелк**Жжж*", completion = "*Жжж*\n\nОпознание рыбы-ангела Кифера завершено.\n\nВы можете получить награду.\n\n*Щелк-щелк**Бзззз*", rewards = "Вы получите:\n\nСчастливая шляпа рыболова"},
[8222] = {title = "Светящаяся кровь скорпида", objective = "За все время, что я работаю на ярмарке, я усвоил множество истин. Поделюсь полезным знанием: публика обожает блестящие безделушки! Это может быть что угодно – возьми, скажем, ножку от стула и покрась ее золотой краской. За эту штуковину будет драться детвора со всей округи!\n\nИтак, Великийгром, мне нужна светящаяся кровь скорпида. Скорпидов можно найти в Силитусе, Выжженных землях или Пылающих степях.", description = nil, progress = "За все время, что я работаю на ярмарке, я усвоил множество истин. Поделюсь полезным знанием: публика обожает блестящие безделушки! Это может быть что угодно – возьми, скажем, ножку от стула и покрась ее золотой краской. За эту штуковину будет драться детвора со всей округи!\n\nИтак, Великийгром, мне нужна светящаяся кровь скорпида. Скорпидов можно найти в Силитусе, Выжженных землях или Пылающих степях.", completion = "Чудесно, чудесно, Великийгром! Спасибо тебе. Наварю краски и превращу вон ту кучу мусора в восхитительные сувениры!\n\nВот твои купоны – удачно отдохнуть!", rewards = "Вы получите:\n\nПодарочный купон ярмарки Новолуния"},
[8223] = {title = "Обмен: светящаяся кровь скорпида", objective = "А знаешь, Кхалдун, кровь скорпидов – отличное средство! Удивительно, как с помощью блесток можно любой мусор превратить в изысканную поделку. Клиентам полюбились безделушки, а любовь правит миром, так ведь?\n\nТвоя помощь неоценима, Кхалдун. Если вдруг ты раздобудешь еще светящейся крови скорпида, принеси ее мне, и я дам тебе ярмарочные купоны!", description = nil, progress = "А знаешь, Кхалдун, кровь скорпидов – отличное средство! Удивительно, как с помощью блесток можно любой мусор превратить в изысканную поделку. Клиентам полюбились безделушки, а любовь правит миром, так ведь?\n\nТвоя помощь неоценима, Кхалдун. Если вдруг ты раздобудешь еще светящейся крови скорпида, принеси ее мне, и я дам тебе ярмарочные купоны!", completion = "Спасибо тебе, Кхалдун. А вот и твои купоны!", rewards = "Вы получите:\n\nПодарочный купон ярмарки Новолуния"},
[8224] = {title = "Редкая рыба – дезийская ставрида", objective = "*ЖЖЖ**Щелк*\n\nЯ разыскиваю редкие сорта рыбы по поручению рыбака  Синежаброго. Если вы принесете мне дезийскую ставриду, то получите награду.\n\n*Щелк**Жжж*", description = nil, progress = "*ЖЖЖ**Щелк*\n\nЯ разыскиваю редкие сорта рыбы по поручению рыбака  Синежаброго. Если вы принесете мне дезийскую ставриду, то получите награду.\n\n*Щелк**Жжж*", completion = "*Жжж*\n\nОпознание дезийской ставриды завершено.\n\nВы можете получить награду.\n\n*Щелк-щелк**Бзззз*", rewards = "Вы получите:\n\nСверхпрочная этерниевая леска"},
[8225] = {title = "Редкая рыба – Синий полосатик Браунелла", objective = "*ЖЖЖ**Щелк*\n\nЯ разыскиваю редкие сорта рыбы по поручению рыбака Синежаброго. Если вы принесете мне синего полосатика Браунелла, то получите награду.\n\n*Щелк**Жжж*", description = nil, progress = "*ЖЖЖ**Щелк*\n\nЯ разыскиваю редкие сорта рыбы по поручению рыбака Синежаброго. Если вы принесете мне синего полосатика Браунелла, то получите награду.\n\n*Щелк**Жжж*", completion = "*Жжж*\n\nОпознание синего полосатика Браунелла завершено.\n\nВы можете получить награду.\n\n*Щелк-щелк**Бзззз*", rewards = "Вы получите:\n\nНебывалые рыбацкие сапоги Ната Пэгла"},
[8226] = {title = "Редкая рыба – бледная упырыба", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПоношенная шляпа рыболова\n\nВы также получите:\n\n"},
[8227] = {title = "Измерительная лента Ната", objective = "Верните измерительную ленту Нату Пэглу. Найти Пэгла можно в Пылевых топях.", description = "Среди разбросанных рыболовных инструментов лежит свернутая шелковая измерительная лента. К ней прицеплена бирка с надписью:\n\n\"Нат Пэгл, Пылевые топи\".", progress = "Привет, сынок. Хочешь порыбачить?", completion = "О, тебе удалось отыскать мою измерительную ленту? Она мне очень дорога! Именно ею я измерял самых больших рыб, которых мне удавалось поймать...\n\nНо ведь я потерял свою ленту в Зул'Гурубе... Ты там был? Может быть, ты видел этого самого Газ'ранку, о котором рассказывают басни?\n\nЧто ж... может быть, ты хочешь его поймать?", rewards = "Вы получите:\n\n"},
[8228] = {title = "Путевка на рыбалку", objective = "В это воскресенье в Пиратской бухте будет рыболовецкое состязание! Если хочешь принять участие, вот, почитай правила!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nСостязание рыбаков!"},
[8229] = {title = "Путевка на рыбалку", objective = "В это воскресенье в Пиратской бухте будет рыболовецколе состязание! А вот и правила!", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nСостязание рыбаков!"},
[8230] = {title = "Пробное задание Коллина", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8231] = {title = "Охота на волномета", objective = "Принесите 6 чешуй волношлепа Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", description = "Волношлеп – земноводное, встречающееся только в Азшаре. Эти твари сильны и очень живучи. \n\nВ их твердой блестящей чешуе, как в зеркале, отражается мастерство охотника. \n\nВыследи и убей нескольких на побережье Азшары и принеси мне их чешую.", progress = "Удачна ли была охота, Юмикор?", completion = "Волношлепы – не самые слабые противники, особенно если пытаться биться с ними в воде – их естественной среде обитания. Ты доказала что можешь справиться с очень опасной добычей.", rewards = "Вы получите:\n\n"},
[8232] = {title = "Зеленый дракон", objective = "Принесите зуб Морфаза Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", description = "Ты отправляешься на опасную охоту, <раса>. Убей зеленого дракона Морфаза и принеси мне его зуб. Морфаз обитает в Храме Атал'Хаккара. Вход в него ты найдешь на Болоте Печали. \n\nНо помни, <одному/одной> тебе его не осилить. У дракона много врагов – найди соратников и уничтожь его! \n\nМногие, очень многие не прочь добыть зуб этой твари. Принеси его мне, и я достойно награжу тебя.", progress = "Я вижу на твоем челе печать невзгод, Аркох. Тебе удалось убить дракона?", completion = "Ты показал себя великим воителем, Аркох. Прими этот дар, я храню его с давних лет, когда сам был охотником.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОхотничье копьеГлаз девизавраЗуб девизавра\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[8233] = {title = "Приглашение", objective = "Поговорите с лордом Джорахом Черным Вороном в его поместье.", description = "Лорд Джорах Черный Ворон настоятельно приглашает вас к себе. Приглашение тайное, поэтому никаких подробностей.\n\nПоместье Черный Ворон находится в предгорьях Хилсбрада – горная тропа начинается на северо-западе от крепости Дарнхольд.", progress = nil, completion = "Добро пожаловать! Прошу вас, Энталионс, присаживайтесь. Я хочу обсудить с вами одно простое дельце.\n\nВидите ли, недавно я лишился кое-чего очень ценного, и, прямо говоря, хочу вернуть его любой ценой. Это дело и для вас выгодное, да, очень выгодное.\n\nЧто скажете, Энталионс? Вы же любите приключения?", rewards = "Вы получите:\n\n"},
[8234] = {title = "Запечатанная лазурная сумка", objective = "Добудьте запечатанную лазурную сумку у шамана из племени Древобрюхов в Азшаре. Затем отнесите сумку верховному магу Ксилему в Азшаре.", description = "Начнем сначала. Я потерял небольшую сумку голубого цвета. В ней были мои личные вещи. \n\nНет нужды искать воров – они уже мертвы. Мне известно лишь, что эти дураки не сумели открыть сумку и продали ее какому-то шаману из племени Древобрюхов в Азшаре, выдав ее за священную реликвию. Очень умно. \n\nЯ хочу, чтобы ты <отправился/отправилась> в Азшару и <заполучил/заполучила> у шамана мою сумку – хитростью или силой. Полагаю, что лучше все же хитростью. Сумку отнеси верховному магу Ксилему.", progress = "Мы знакомы?", completion = "Вижу, у тебя сумка лорда Черного Ворона. Что ж ты сразу не сказал, сынок?", rewards = "Вы получите:\n\n"},
[8235] = {title = "Зашифрованные фрагменты", objective = "Принесите 10 зашифрованных фрагментов верховному магу Ксилему в Азшару.", description = "Лорд Черный Ворон просил нас с тобой об услуге. Он желает снять заклятие с этой сумки. \n\nК сожалению, мои книги по снятию чар были захвачены и уничтожены дикарями. Каждый клочок, оставшийся от них, невероятно ценен для меня. \n\nЕсли ты сможешь принести мне зашифрованные фрагменты, я попробую восстановить хотя бы часть моих книг. Чтобы найти фрагменты, поохоться на обитающих на северо-востоке Азшары лесных слизнюков – они обычно подбирают все, что плохо лежит.", progress = "Ты принес мне фрагменты? Я должен как можно скорее приступить к работе.", completion = "Похоже, тебе удалось найти весьма ценные фрагменты. Не так уж ты и бесполезен, в конце концов.", rewards = "Вы получите:\n\n"},
[8236] = {title = "Лазурный ключ", objective = "Принесите лазурный ключ лорду Черному Ворону.", description = "Мне потребуется время, чтобы расшифровать фрагменты и снять заклятие. Когда я закончу, то самолично доставлю сумку лорду Черному Ворону. \n\nОднако нам все еще нужен ключ. Говорят, что ключ присвоил зеленый дракон по имени Морфаз. Его логово находится в глубинах Храма Атал'Хаккара – вход в него ты найдешь на Болоте Печали. \n\nСобери своих сподвижников и отправляйся к логову дракона. Лорд Черный Ворон ждет, когда ты принесешь ему ключ.", progress = "Верховный маг Ксилем уже прислал мне сумку. Ты принес ключ?", completion = "Ключ! Я уже думал, что он потерян навеки! Прошу тебя, возьми что-то из зачарованной одежды из моих запасов. Она предназначена для особо искусных разбойников. Пусть все знают, что с тобой шутки плохи! \n\n*Джорах раскрывает сумку, и из нее вырывается золотое сияние. Джорах с изумлением смотрит внутрь...*", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЭбеновая маскаСапоги шелеста шаговПелерина из сумеречницы\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[8237] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8238] = {title = "Монеты племен: Гурубаши, Порочная Ветвь и Сухокожие", objective = "Мне нужны Знаки Силы, более известные как Монеты племен. Это ходовые монеты различных племен Зул'Гуруба, и на каждую из них наложено незаметное, но могущественное заклятие.\n\nСуществует девять видов таких монет. За некоторые из них мои компаньоны готовы поделиться с тобой снаряжением. Будут лишние – обращайся и ко мне, я обменяю три монеты на знак отличия. А ты эти знаки уже сможешь обменять у  Рин'вошо Торговца на нечто особенное.", description = nil, progress = "Мне нужны Знаки Силы, более известные как Монеты племен. Это ходовые монеты различных племен Зул'Гуруба, и на каждую из них наложено незаметное, но могущественное заклятие.\n\nСуществует девять видов таких монет. За некоторые из них мои компаньоны готовы поделиться с тобой снаряжением. Будут лишние – обращайся и ко мне, я обменяю три монеты на знак отличия. А ты эти знаки уже сможешь обменять у  Рин'вошо Торговца на нечто особенное.", completion = "Отлично – эти монеты прекрасно дополнят в мою коллекцию... Они нужны племени, чтобы помешать возрождению Кровавого бога. Этот почетный знак – твой по праву, Илиторий, прими его вместе с нашей благодарностью!", rewards = "Вы получите:\n\nПочетный знак Зандалара"},
[8239] = {title = "Монеты племен: Песчаная Буря, Дробители Черепов и Кровавый Скальп", objective = "Мне нужны Знаки Силы, более известные как Монеты племен. Это ходовые монеты различных племен Зул'Гуруба, и на каждую из них наложено незаметное, но могущественное заклятие.\n\nСуществует девять видов таких монет. За некоторые из них мои компаньоны готовы поделиться с тобой снаряжением. Будут лишние – обращайся и ко мне, я обменяю три монеты на знак отличия. А ты эти знаки уже сможешь обменять у  Рин'вошо Торговца на нечто особенное.", description = nil, progress = "Мне нужны Знаки Силы, более известные как Монеты племен. Это ходовые монеты различных племен Зул'Гуруба, и на каждую из них наложено незаметное, но могущественное заклятие.\n\nСуществует девять видов таких монет. За некоторые из них мои компаньоны готовы поделиться с тобой снаряжением. Будут лишние – обращайся и ко мне, я обменяю три монеты на знак отличия. А ты эти знаки уже сможешь обменять у  Рин'вошо Торговца на нечто особенное.", completion = "Отлично – эти монеты прекрасно дополнят в мою коллекцию... Они нужны племени, чтобы помешать возрождению Кровавого бога. Этот почетный знак – твой по праву, Супертоон, прими его вместе с нашей благодарностью!", rewards = "Вы получите:\n\nПочетный знак Зандалара"},
[8240] = {title = "Драгоценности для Занзы", objective = "Найдите в Зул'Гурубе драгоценности Хаккари и уничтожьте их на Алтаре Занзы на острове Йоджамба. Поговорите с Винчаксой.", description = "Драгоценности Хаккари необходимо уничтожить. Это наше внутреннее дело, но оно настолько важное, что мы просим о помощи и чужеземцев.\n\nОтыщи в Зул'Гурубе все драгоценности, которые сможешь, принеси на Алтарь Занзы и уничтожь их. Если ты справишься с этим заданием, я дам тебе почетный знак нашего племени. Знай, что у нас этими знаками не разбрасываются!\n\nСтупай, и да пребудет с тобой благословение Занзы!", progress = "Уничтожь драгоценности на Алтаре Занзы! Сделай это, и Занза благословит тебя дважды!", completion = "Отлично... Каждая драгоценность, которую удалось отнять у прислужников Кровавого бога – еще один шаг к тому, чтобы покончить с ними навечно. Ты оказал племени неоценимую услугу, и племя этого не забудет.\n\nПомни, что найденные драгоценности нужно уничтожить на Алтаре Занзы. За уничтожение каждой драгоценности ты получишь почетный знак племени! Для хранения почетных знаков тебе потребуется свободное место в сумках.", rewards = "Вы получите:\n\nПочетный знак Зандалара"},
[8241] = {title = "Пополнить запасы огненного плавня с помощью железа", objective = "Не будем тратить драгоценное время на ерунду, |3-6(дворф). Пора пополнить запасы огненного плавня – они уже совсем на исходе. \n\nВот что мне от тебя нужно: \n\n*Чешуя пламезавра \n\n*Железные слитки \n\n*Уголь.\n\nМне нужно все, что ты сможешь предложить! И поторопись, если хочешь угодить Братству.", description = nil, progress = "Не будем тратить драгоценное время на ерунду, |3-6(дворф). Пора пополнить запасы огненного плавня – они уже совсем на исходе. \n\nВот что мне от тебя нужно: \n\n*Чешуя пламезавра \n\n*Железные слитки \n\n*Уголь.\n\nМне нужно все, что ты сможешь предложить! И поторопись, если хочешь угодить Братству.", completion = "Плавень в кузне лишним не бывает, поверь моему слову... Неси сколько можешь, пока не скажу – хватит.", rewards = nil},
[8242] = {title = "Пополнить запасы огненного плавня с помощью тяжелой кожи", objective = "Не будем тратить драгоценное время на ерунду, |3-6(дворф). Пора пополнить запасы огненного плавня – они уже совсем на исходе. \n\nВот что мне от тебя нужно: \n\n*Чешуя пламезавра \n\n*Тяжелая кожа \n\n*Уголь \n\nМне нужно все, что ты сможешь предложить! И поторопись, если хочешь угодить Братству.", description = nil, progress = "Не будем тратить драгоценное время на ерунду, |3-6(дворф). Пора пополнить запасы огненного плавня – они уже совсем на исходе. \n\nВот что мне от тебя нужно: \n\n*Чешуя пламезавра \n\n*Тяжелая кожа \n\n*Уголь \n\nМне нужно все, что ты сможешь предложить! И поторопись, если хочешь угодить Братству.", completion = "Плавень в кузне лишним не бывает, поверь моему слову...", rewards = nil},
[8243] = {title = "Напиток могущества Занзы", objective = "Теперь, когда племя тебе доверяет, ты можешь воспользоваться нашими зельями. Вот, смотри. Этот напиток несет на себе благословение Занзы, и любой искатель приключений будет счастлив обладать им.\n\nУ меня в запасе три таких напитка, и я дам тебе один из них, но взамен мне нужен почетный знак Зандалара. Запомни: пока ты находишься под действием одного из напитков, ты не сможешь принять другой.\n\nВозвращайся, когда у тебя появится то, что нужно для обмена.", description = nil, progress = "Теперь, когда племя тебе доверяет, ты можешь воспользоваться нашими зельями. Вот, смотри. Этот напиток несет на себе благословение Занзы, и любой искатель приключений будет счастлив обладать им.\n\nУ меня в запасе три таких напитка, и я дам тебе один из них, но взамен мне нужен почетный знак Зандалара. Запомни: пока ты находишься под действием одного из напитков, ты не сможешь принять другой.\n\nВозвращайся, когда у тебя появится то, что нужно для обмена.", completion = "Все по-честному, приятель! Вот твой напиток – пусть он поможет в твоих странствиях!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБлеск ЗанзыДух ЗанзыСкорость Занзы"},
[8246] = {title = "Перстни Зандалара", objective = "Для друзей нашего племени, Лорегон, у меня есть особый подарок прямо из нашего дома в Южных морях... Перстни Зандалара! Они усиливают любые наплечники и влияют на силу нападения или заклинаний.\n\nВ обмен на каждое кольцо мне нужно 15 почетных знаков Зандалара.", description = nil, progress = "Для друзей нашего племени, Лорегон, у меня есть особый подарок прямо из нашего дома в Южных морях... Перстни Зандалара! Они усиливают любые наплечники и влияют на силу нападения или заклинаний.\n\nВ обмен на каждое кольцо мне нужно 15 почетных знаков Зандалара.", completion = "Все по-честному, приятель! Вот твой перстень – пусть он поможет в твоих странствиях!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерстень могущества ЗандалараМагический перстень ЗандалараПерстень безмятежности Зандалара"},
[8249] = {title = "Принести лари", objective = "Моим разбойникам необходимо потренироваться во вскрытии замков, и мне нужны соответствующие замки. Зан делает такие, что они только зеленым новичкам годятся.\n\nВот что, принеси-ка мне 5 тяжелых ларей, а я дам тебе несколько лучших метательных ножей, какие только бывают у разбойников.\n\nТы можешь отпереть лари и порыться в них, но оставь там хотя бы несколько монеток... даже разбойнику-ученику нужна мотивация.", description = nil, progress = "Моим разбойникам необходимо потренироваться во вскрытии замков, и мне нужны соответствующие замки. Зан делает такие, что они только зеленым новичкам годятся.\n\nВот что, принеси-ка мне 5 тяжелых ларей, а я дам тебе несколько лучших метательных ножей, какие только бывают у разбойников.\n\nТы можешь отпереть лари и порыться в них, но оставь там хотя бы несколько монеток... даже разбойнику-ученику нужна мотивация.", completion = "Да найдется место для этих ножей в чьем-нибудь сердце.\n\nВ буквальном смысле.", rewards = "Вы получите:\n\nМетательный нож туманной стали"},
[8250] = {title = "Магическое искусство", objective = "Найдите Саната Лим-Йо и добейтесь, чтобы он доставил вас к верховному магу Ксилему.", description = "Верховный маг Ксилем ищет кого-то... Не менее опытного, чем ты.\n\nЕсли хочешь, поговори с ним. Он живет в Азшаре, в башне на вершине утеса. Добраться туда можно лишь при помощи заклинания, которое известно его заносчивому слуге, Санату Лим-Йо.\n\nСанат живет в лагере ниже башни своего хозяина. Найти его можно так: там, где главная дорога Азшары разветвляется у входа в руины Эльдарата, поворачивай строго на север и иди, пока не упрешься в скалы.", progress = nil, completion = "*Санат смотрит на вас с презрением.*\n\nВерховный маг Ксилем ждет тебя.", rewards = "Следующее заклинание будет наложено на вас:\n\nТелепорт в башню Азшары\n\nВы получите:\n\n"},
[8251] = {title = "Волшебная пыль", objective = "Принесите 10 горстей сияющей пыли верховному магу Ксилему.", description = "Эльфы крови в Азшаре изобрели свой способ распылять магические предметы. Получаемая в результате сияющая пыль отличается от элементов, получаемых в результате обычного распыления.\n\nЯ отправил ученика купить этой пыли, но эльфы безжалостно убили его. Они должны заплатить за это! \n\nВремя мирных переговоров прошло, <имя>. Найди эльфов крови в скалах Азшары и примени к ним более... убедительные методы. Мне нужна эта пыль.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8252] = {title = "Кораллы сирен", objective = "Соберите 6 заколдованных кораллов и принесите их верховному магу Ксилему.", description = "Оглянись вокруг. Развалины и все побережье кишат тварями Бича Злобы. Проклятые создания научились искать редкие вещества и предметы, встречающиеся в Азшаре. \n\nНапример, эти твари почему-то очень интересуются заколдованными кораллами – по совершенно не ясным мне причинам. Теперь этих кораллов в бухте почти не осталось, а они так нужны мне для исследований! Прошу тебя, отбери несколько кораллов у сирен из клана Бича Злобы и принеси их мне.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8253] = {title = "Уничтожить Морфаза", objective = "Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему.", description = "В глубинах Храма Атал'Хаккара скрывается зеленой дракон по имени Морфаз. \n\nМного лет назад он напал на меня из засады и проглотил целиком сопровождавшего меня ученика. Мне не впервой терять ученика, однако имено этот, проглоченный, нес кристалл тайной магии небывалой мощи. \n\nВыбери достаточно сильных соратников и отправляйся в храм. Уничтожь Морфаза и принеси мне мой кристалл.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЛедовый шипПодвеска из чародейного кристаллаОгненный рубин\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[8254] = {title = "Помощь Кенарию", objective = "Отыщи Огтинка в Азшаре.", description = "Служителям богов пристало помогать попавшим в беду. Как именно – неважно, главное – во имя чего.\n\nКругу Кенария необходима помощь. Если ты хочешь протянуть им руку помощи, поговори с Огтинком. Он живет на вершинах скал на северо-востоке от руин Эльдарата в Азшаре.", progress = nil, completion = "Я очень рад твоему приходу. У меня словно камень с души свалился. Нам предстоит очень много дел.", rewards = "Вы получите:\n\n"},
[8255] = {title = "Охота на беговых оленей", objective = "Добудьте 4 железы здорового мохоногого оленя и принесите их Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", description = "Мохноногие олени, обитающие в Азшаре, – самые великолепные создания, когда-либо населявшие Оскверненный лес. Они наделены естественной невосприимчивостью ко всем болезням и ядам, поэтому порча не коснулась их. Мудрые животные предпочли покинуть зараженные земли. \n\nК прискорбию своему я должен просить тебя поохотиться на этих прекрасных созданий, поскольку их железы необходимы для изготовления целительного снадобья. Снадобья, которое вернет Оскверненному лесу его прежний облик.", progress = "Ты вернулась. Надеюсь, удача улыбнулась тебе?", completion = "Сама судьба привела тебя сюда, Юбари. Вера твоя не противоречит тому, что должно исполнить для создания снадобья. \n\nВидишь ли, Круг Кенария считает этих беговых оленей священными животными, убийство которых невозможно ни при каких обстоятельствах. Если бы им пришлось это сделать, это сильно подорвало бы их дух.", rewards = "Вы получите:\n\n"},
[8256] = {title = "Лимфа нежити", objective = "Принесите лимфу нежити Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", description = "Чтобы получить целительное снадобье, воспользуемся простым рецептом: смешаем одну часть яда с двумя благотворными субстанциями. Один целительный компонент у нас уже есть, теперь надо добыть яд. \n\nСамые могущественные твари нежити, такие как неупокоенные высокорожденные, скитающиеся по руинам Эльдарата, часто настолько сильно поражены порчей, что она принимает вполне осязаемую форму зеленой слизи. Среди живых эта субстанция известна как лимфа нежити. \n\nЭто очень мощный яд, поэтому потребуется лишь одна мера.", progress = "Нам нужна лимфа как можно скорее! Тебе удалось добыть ее?", completion = "Да, не самое приятное зрелище... Но, как это не печально, эта мерзкая субстанция необходима для создания целебной мази. Спасибо, Юбари.", rewards = "Вы получите:\n\n"},
[8257] = {title = "Кровь Морфаза", objective = "Убейте Морфаза в затонувшем храме Атал'Хаккара и принесите его кровь Грете Замшелому Копыту в Оскверненный лес. Вход в храм сокрыт на болоте Печали.", description = "Теперь нам нужен последний целительный компонент. \n\nИзвестно, что зеленый дракон Морфаз наделен невосприимчивостью ко всем болезням и ядам. Это знание досталось дорогой ценой – не один друид погиб, пытаясь справиться с драконом. Уверен, его кровь послужит отличным компонентом для нашего снадобья.\n\nПосланник Круга Кенария заберет уже собранные тобой компоненты, пока ты будешь добывать последний. Собери соратников и отправляйся в логово зеленого дракона в затонувший храм Атал'Хаккара. Принеси его кровь Грете Замшелому Копыту в Оскверненный лес.", progress = "Ты добыл кровь Морфаза?", completion = "Не могу поверить... тебе действительно удалось справиться с драконом и добыть его кровь! Мы немедленно приготовим снадобье и начнем исцеление растений и животных Оскверненного леса. Это займет очень много времени, но теперь мы можем это сделать – и все благодаря тебе!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБлагословенные четкиГорепосохОбруч Надежды\n\nСледующее заклинание будет наложено на вас:\n\nЗнак дикой природы\n\nВы также получите:\n\n"},
[8258] = {title = "Угроза Темного Губителя", objective = "Используйте кристальный предсказатель в Главном склепе в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его.\n\nПринесите голову Темного Терзателя Сагорну Гривастому Страннику в Аллею Мудрости Оргриммара.", description = "Темный Терзатель, рыцарь смерти, владычествует над Главным cклепом в Некроситете. Он собирается подчинить себе весь мир духов! Его необходимо остановить! Тут-то тебе и понадобится кристальный предсказатель.\n\nПриведи его в действие в Главном склепе, чтобы вызвать духов-приспешников Темного Терзателя. Когда ты одолеешь этих духов, явится сам рыцарь смерти. Принеси мне его голову, <имя>! Только его гибель способна исправить урон, нанесенный миру духов!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nШлем Небесной Ярости"},
[8259] = {title = "Более достойная награда", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nШлем Небесной Ярости"},
[8261] = {title = "Стандартный полевой комплект Лиги Аратора", objective = "Ты хорошо зарекомендовала себя, Кусачаявода, тут сомнений нет! В награду возьми этот пакет! В нем паек и бинты, которые найдешь только в лощине Боевого Клича.\n\nКогда в лощине тебя еще больше зауважают, тебе их тут даже продадут. Паек мы выдаем, если относимся к кому-то дружественно, а бинты – когда уважаем.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nСтандартная амуниция Аратора"},
[8262] = {title = "Улучшенный полевой комплект Лиги Аратора", objective = "Ты хорошо зарекомендовал себя, Олин, тут сомнений нет! В награду возьми этот пакет! В нем паек и бинты, которые найдешь только в лощине Боевого Клича.\n\nКогда в лощине тебя еще больше зауважают, тебе их тут даже продадут. Паек мы выдаем, если относимся к кому-то дружественно, а бинты – когда уважаем.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nДоукомплектованная амуниция Аратора"},
[8263] = {title = "Полевой комплект Осквернителей", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nАмуниция Осквернителей"},
[8264] = {title = "Стандартный полевой комплект Осквернителей", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nСтандартная амуниция Осквернителей"},
[8265] = {title = "Улучшенный полевой комплект Осквернителей", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nДоукомплектованная амуниция Осквернителей"},
