[8270] = {title = "test copy quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8271] = {title = "Герой Грозовой Вершины", objective = "Как великий воитель Грозовой Вершины, можешь выбрать одну вещь из награб... из этих спасенных сокровищ.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКровоискательПокрытое изморозью копьеЖезл Лютого холодаХолоднокованный молот\n\nВы также получите:\n\n"},
[8272] = {title = "Герой Северного Волка", objective = "Как ощущения, Стиммакс? Приятно видеть поверженных врагов в пыли у своих ног? Отличное чувство, правда?\n\nПрими награду за свои героические деяния, солдат.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКровоискательПокрытое изморозью копьеЖезл Лютого холодаХолоднокованный молот\n\nВы также получите:\n\n"},
[8273] = {title = "Благодарность Оран", objective = "Надо же, как интересно. Говоришь, ты нашел эту табличку на Отвесных скалах во Внутренних землях? Очень, очень любопытно. *Оран потирает руки и прячет табличку подальше.*\n\nБлагодарю за труды. Темная Госпожа будет довольна этим открытием. Позволь тебя наградить.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШапка резервиста ПодгородаСтаромодный мундир дворянина\n\nВы также получите:\n\n"},
[8274] = {title = "Test Kill Quest", objective = "Kill 5 Murlocs and come back to the test character.", description = "Got some time to spare?  Kill me some Murlocs and I'll give you something shiny!", progress = nil, completion = nil, rewards = nil},
[8275] = {title = "Отвоевание Силитуса", objective = "Поговорите с призывательницей ветров Гордый Рог в крепости Кенария.", description = "Слушайте, герои Альянса! Мы слишком долго не обращали внимания на опасность, источник которой – силитиды. Им никто не противостоял, и мерзкие насекомые подготовились к масштабному вторжению.\n\nСилы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю!\n\nВсе на защиту Азерота! Все, способные держать оружие, должны пройти инструктаж у призывательницы ветров Гордый Рог в крепости Кенария!", progress = nil, completion = "Отлично, еще один доброволец готов выступить против силитидов. Добро пожаловать в крепость Кенария, |3-6(Друид). Я рад, что слова наших посланников привлекают героев вроде тебя. У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников.", rewards = "Вы получите:\n\n"},
[8276] = {title = "Отвоевание Силитуса", objective = "Поговорите с призывательницей ветров Гордый Рог в крепости Кенария.", description = "Слушайте, герои Орды! Мы слишком долго не обращали внимания на серьезную угрозу. Дрожание земли рядом с ульями силитидов говорит о серьезном возрастании их числа в связи с готовящимся нападением.\n\nСилы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю!\n\nВсе, способные держать оружие, должны обратиться к призывательнице ветров Гордый Рог в крепости Кенария! Смерть силитидам!", progress = nil, completion = "Отлично, еще один доброволец готов выступить против силитидов. Добро пожаловать в крепость Кенария, |3-6(Воин). Я рад, что слова наших посланников привлекают героев вроде тебя. У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников.", rewards = "Вы получите:\n\n"},
[8277] = {title = "Смертельный яд", objective = "Принесите Битиссе Шаткобрус из крепости Кенария 8 жал камнехвостых скорпидов и 8 жвал песчаных пауков-быстроногов.", description = "Битисса Шаткобрус к твоим услугам! Мой кузен Ноггл зарабатывает на жизнь, продавая алхимикам из крепости Кенария редкие травы. Точее, зарабатывал. Из последней вылазки он вернулся отравленный страшным ядом.\n\nЯ сумела замедлить действие яда, но чтобы полностью нейтрализовать его, мне понадобятся образцы яда тех тварей, что ужалили его.\n\nНоггл вернулся с севера, поэтому я готова поспорить, что он пострадал от камнехвостых скорпидов или песчаных пауков-быстроногов. Принеси мне несколько жал и жвал, и я сделаю противоядие.", progress = "Ты уже собрал для меня образцы? Мы теряем Ноггла!", completion = "Скрести пальцы, дружище! Будем надеяться, что нам удастся спасти Ноггла!", rewards = "Вы получите:\n\n"},
[8278] = {title = "Последняя надежда Ноггла", objective = "Принесите Битиссе Шаткобрус из крепости Кенария 3 жала камнехвостых клешневиков, 3 жала камнехвостых живодеров и 3 клыка скальных пауков-скакунов.", description = "Проклятье! Противоядие не сработало. Наверное, Ноггла укусила одна из тварей на далеком юге, они гораздо страшнее остальных.\n\nПридется попросить тебя отправиться за образцами, <имя>. В утешение могу сказать, что поскольку яд у них сильный, мне потребуется не так много образцов, как в прошлый раз. С другой стороны, на юге больше ядовитых тварей, поэтому придется убить по несколько существ разных видов.", progress = "Это последний шанс спасти Ноггла! Спеши!", completion = "Да! Похоже, сработало, Ноггл приходит в себя. Мы у тебя в долгу!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСильнейшее лечебное зельеСильнейшее зелье маны\n\nВы также получите:\n\n"},
[8279] = {title = "Сумеречный словарь", objective = "Принесите три главы Сумеречного словаря отшельнику Ортеллу из Силитуса.", description = "Сумеречный Молот не прощает тех, кто покидает его ряды. Они охотятся за мной, словно за диким зверем! Излишне говорить, что их враги – мои друзья!\n\nЧтобы расшифровать эту табличку, мне понадобится книга, которой пользуются их писцы при закодировании тайных посланий, Сумеречный словарь. Эта книга настолько важна, что три ее главы держат в разных местах! Главы находятся у особых офицеров, именуемых сумеречными хранителями. Ищи их в лагерях Сумеречного Молота.", progress = "Кто идет? А, это ты! Ты уже все главы словаря собрал?", completion = "Ура! Вот они, все части книги! Приступим, Лорегон.\n\nЗаменить каждое третье слово словами из второй главы... Потом заменить каждое второе слово словами из первой главы... Стоп, я что-то путаю?", rewards = "Вы получите:\n\n"},
[8280] = {title = "Надежные поставки", objective = "Убейте 15 землечерпов по поручению призывательницы ветров Гордый Рог.", description = "Крепость Кенария имеет важнейшее стратегическое значение. Не сомневаюсь, что пока мы удерживаем его, силитидам нас не одолеть. Разумеется, если припасы будут поступать регулярно.\n\nПесчаные черви оказались даже большей помехой для наших караванов, чем сами силитиды. Например, сегодня утром землечерпы разграбили большой караван с рассветницей. Необходимо сократить число этих тварей, чтобы обеспечить бесперебойные поставки.", progress = nil, completion = "Прими мою глубочайшую благодарность. Помогая крепости Кенария, ты проявил редкое мужество.", rewards = "Вы получите:\n\n"},
[8281] = {title = "Обеспечение безопасности", objective = "Убейте 20 земляных сокрушителей по поручению призывательницы ветров Гордый Рог.", description = "Ты великолепно себя <зарекомендовал/зарекомендовала>, <имя>. К сожалению, нашему снабжению по-прежнему грозит опасность. Землечерпов теперь нет, но их место несомненно займут их более крупные южные родственники – земляные сокрушители.\n\nЧтобы приструнить этих червяков, придется убить их побольше. Но мы не можем подвергать опасности наше снабжение.", progress = nil, completion = "Великолепно! Ты оказался ценным союзником в подготовке к войне против силитидов.", rewards = "Вы получите:\n\n"},
[8282] = {title = "Потерянная сумка Ноггла", objective = "Принесите сумку Ноггля из гор в южной части Силитуса и верните ее хозяину в крепость Кенария.", description = "Где я? Где моя сумка? <вздыхает> Наверное, я потерял ее, убегая от Смертехвата, огромного скорпида. Я мчался, не разбирая дороги, и забрел прямо в гнездо камнехвостых живодеров.\n\nВ моей сумке были ценнейшие реагенты. Без них мы с Битикс не сможем делать зелья для крепости Кенария. Я пока не в силах встать, но если ты сможешь вернуть мне реагенты, я тебе отплачу сторицей.\n\nНа Смертехвата я наткнулся в южных горах, за лагерем Бронзоборода.", progress = "Ты еще не нашел мою сумку? С другой стороны, грех жаловаться, от яда-то меня излечили.", completion = "Да! Ты принес мне сумку. И все ценные реагенты вместе с ней! Я твой должник на долгие годы.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЭликсир мангустаЭликсир мудрецов\n\nВы также получите:\n\n"},
[8283] = {title = "РОЗЫСК: Смертехват, гроза пустыни", objective = "Принесите хелицеры Смертехвата Вишу Коцусу, капитану стражи.", description = "Согласно последним сведениям, ужасный скорпион, Смертехват, отступил в южные горы перед лицом нашествия силитидов. Эта тварь представляет большую угрозу патрулям и экспедициям южных регионов. Тех, кто поспособствует ее уничтожению, будет ждать неплохая награда. По вопросам получения награды обращаться к капитану Вишу Коцусу, на вершину сторожевой башни крепости Кенария.", progress = "Доказательством гибели твари послужат ее хелицеры. Нет хелицер, нет и награды.", completion = "Замечательно! Смертехвата нет, и мы сможем спокойно подобраться к ульям силитидов по южным горам. Мы высоко ценим твою работу.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗнак Песчаного странникаЧерный хрустальный кинжал\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[8284] = {title = "Сумеречная тайна", objective = "Геолог Ехидная из крепости Кенария просит вас собрать 8 фрагментов сумеречной таблички.", description = "На северо-западе отсюда некогда благоденствовал лагерь культистов Сумеречного Молота. Теперь на месте лагеря остались лишь обломки древесины и ткани, среди которых бродят элементали.\n\nМне удалось добыть там несколько кусочкой глиняной таблички, но их слишком мало, чтобы узнать что-нибудь ценное. Не сможешь ли ты добыть остальные фрагменты? Быть может, они прольют свет на деятельность Сумеречного Молота в Силитусе.", progress = "Разграбленный лагерь находится на северо-западе. Возвращайся, когда соберешь все фрагменты.", completion = "Так я и думала. Я могу перевести отдельные слова, но они лишены смысла. Сумеречный Молот часто пользуется особыми шифрами, чтобы скрыть значение своих текстов от чужих; нужно найти кого-ниудь, кто разбирается в таких вещах.", rewards = "Вы получите:\n\n"},
[8285] = {title = "Дезертир", objective = "Отнесите восстановленную табличку отшельнику Ортеллу в Силитус.", description = "Ходят слухи, что некто по имени Ортелл вышел из рядов Сумеречного Молота. Говорят, он прячется в горах на юге от деревни Южного Ветра и живет в полном уединении. Может быть, имеет смысл прибегнуть к его помощи в расшифровании таблички.\n\nВозьми восстановленную табличку и отнеси ее Ортеллу.", progress = "Ты! Как ты меня нашел? Кто ты? За тобой не следят? Говори!", completion = "Вижу, ты не понаслышке знаешь о моей бывшей организации. Должно быть, ты из крепости Кенария.\n\nТебе нужна информация для борьбы с Сумеречным Молотом? Подойди ближе, может быть, мы сможем помочь друг другу.", rewards = "Вы получите:\n\n"},
[8286] = {title = "Что ждет нас завтра", objective = "Отправляйтесь в Пещеры Времени в Танарисе и найдите Анахроноса, из рода Ноздорму.", description = "Я уже почти очутился в объятьях смерти, и тут вмешался он. Лишь раз дохнул он на мое искалеченное тело, а затем оставалось лишь дождаться, пока пески времени исцелят мои раны.\n\n\"Навеки останешься ты, коли так нужно,\" сказал он, и с этими словами сделал меня Стражем.\n\nТолько взгляни на пустыню. Вторая война неминуема. Найди тайное укрытие бронзовых драконов. Отправляйся в Пещеры Времени и узнай, не вернулся ли повелитель. Я должен знать наверняка, иначе не смогу действовать.", progress = "Анахронос вернулся?", completion = "Так и предначертано – восстал великий. Мое бдение подходит к концу...", rewards = "Вы получите:\n\n"},
[8287] = {title = "Ужасная цель", objective = "Отнесите переписанный с таблички расшифрованный текст командиру Мар'алиту.", description = "Ну вот... Ценная информация, скажу я тебе! Я видел, как силы Круга Кенария прибыли в Силитус. Они планируют выбить из наших краев Сумеречный Молот, верно? Это поспособствует воплощению их планов.\n\nОтнеси этот пергамент их главе, командиру Мар'алиту. Скоро Сумеречный Молоты изгонят из этих земель и их жадные ручки до меня не дотянутся!", progress = "Что ты мне принес, Лорегон?", completion = "Очень интересные сведения, Лорегон. Они проливают свет на деятельность Сумеречного Молота в Силитусе и несомненно помогут бороться с этой сектой. Вот тебе награда за труды, |3-6(Друид).", rewards = "Вы получите:\n\n"},
[8288] = {title = "Кто будет избран?", objective = "Принесите голову предводителя драконов Разящего Бича Баристольфу из Зыбучих Песков в крепость Кенария в Силитусе.", description = "Время у нас на исходе! Нам необходим герой! Выполнить мое задание под силу лишь целой армии, но только одному из целой толпы будущих героев суждено принять на себя тяжкую ношу ответственности – стать союзником Племени.\n\nВ логове повелителя Черной горы живет жестокий зверь, предводитель драконов Разящий Бич. Он охраняет Зал Раздора, перекрывая путь в покои Нефариана. Убей гнусную тварь и принеси мне ее голову. Это будет первым шагом на твоем пути.", progress = "Твоя цель – завоевать благосклонность рода Ноздорму.", completion = "Неужели ты станешь первым союзником бронзовых драконов за тысячу лет?", rewards = "Вы получите:\n\n"},
[8289] = {title = "Талисманы заслуг", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8290] = {title = "Долой захватчиков!", objective = "Войдите в Ущелье Песни Войны, одержите победу над Ордой, получите почетный знак Ущелья Песни Войны и вернитесь с ним к часовому Дальней Песня в рощу Среброкрылых.", description = "<Юный/Юная:c> <класс>! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!\n\nОтправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков!\n\nНаградой тебе будет талисман заслуг. Принеси мне такой талисман, <имя>, и получишь награду!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8291] = {title = "Долой захватчиков!", objective = "Войдите в Ущелье Песни Войны, одержите победу над Ордой, получите почетный знак Ущелья Песни Войны и вернитесь с ним к часовому Дальней Песне в рощу Среброкрылых.", description = "<Юный/Юная:c> <класс>! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!\n\nОтправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков!\n\nНаградой тебе будет талисман заслуг. Принеси мне такой талисман, <имя>, и получишь награду!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8292] = {title = "Талисманы заслуг", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8293] = {title = "Почетный знак", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8294] = {title = "Громи захватчиков-Среброкрылых!", objective = "Войдите в Ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак Ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор'шан.", description = "Чащобы Ясеневого леса падут пред мощью Орды, <раса>! Что бы ни делали часовые из клана Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше?\n\nПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из клана Среброкрылых и заслужи почетный знак Ущелья Песни Войны. Вернись ко мне с этим знаком, <имя> – и получишь награду!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8295] = {title = "Громи захватчиков-Среброкрылых!", objective = "Войдите в Ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак Ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор'шан.", description = "Чащобы Ясеневого леса падут пред мощью Орды, <раса>! Что бы ни делали часовые из клана Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше?\n\nПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из клана Среброкрылых и заслужи почетный знак Ущелья Песни Войны. Вернись ко мне с этим знаком, <имя> – и получишь награду!Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8296] = {title = "Почетный знак", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8297] = {title = "Ресурсы Низины Арати", objective = "Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Макчисту в Опорный пункт.", description = "Войну выигрывают солдаты, любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна, еще не начавшись!\n\nВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо, и все можно добыть там.\n\nИ вот чего я хочу от вас, <имя>. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8298] = {title = "Новые ящики с ресурсами", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8299] = {title = "Перекрыть линии поставок Аратора", objective = "Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его стражу смерти Мортису в Павший Молот.", description = "Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдаленную область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы.\n\nВы, <имя>, можете нам помочь. Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8300] = {title = "Новые ящики с ресурсами", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8301] = {title = "Путь правых", objective = "Принесите Баристолфу 200 фрагментов силитидских панцирей.", description = "Род Ноздорму инстинктивно не верит низшим расам. Хоть ты и <смог/смогла> доказать мне, что у тебя задатки настоящего героя, пришло время доказать это моему повелителю.\n\nУлей Аши, улей Зора и улей Регал кишат силитидами, которые грозят нашему существованию. Убей как можно больше проклятых тварей и принеси мне фрагменты их панцирей. Когда у тебя закончится место в заплечных мешках, возвращайся и я укреплю твою решимость.", progress = "Недоверие к смертным расам коренится в далеком прошлом; но пусть тебе об этом расскажут сами драконы, когда придет время", completion = "Не думай, что ты один. Я дарую тебе способность привлекать других к себе на помощь. Подлинному защитнику своего народа не обойтись без помощи собратьев.", rewards = "Следующее заклинание будет наложено на вас:\n\nМилость Ноздорму\n\nВы получите:\n\nДоверенный Ноздорму"},
[8302] = {title = "Рука Правого", objective = "Принесите Баристолфу 200 фрагментов силитидских панцирей.", description = "Старательно выбирай своих представителей, <смертный/смертная>. Всякий раз, выполнив задание, ты сможешь выбрать себе нового представителя.\n\nА теперь, не теряя времени, скажу: мне по-прежнему нужны обломки силитидских панцирей. Что стоишь? Иди!", progress = "Быть может, когда-нибудь ты возглавишь гарнизон крепости Кенария.", completion = "Молодец, герой. Тебе будет дарована возможность назначить еще одного агента Ноздорму.", rewards = "Следующее заклинание будет наложено на вас:\n\nМилость Ноздорму\n\nВы получите:\n\nДоверенный Ноздорму"},
[8303] = {title = "Анахронос", objective = "Отыщите Анахроноса в Пещерах Времени в Танарисе.\n\nПрилагается предмет: \n", description = "Время пришло, <имя>.\n\nЯ должен извиниться за то, что так долго держал все в тайне. Но кругом враги, они могут оказаться у нас прямо под носом. Прошу тебя, прими этот фолиант, читай его и учись. Я с радостью делюсь с тобой знаниями. Теперь же отыщи нашего повелителя.", progress = nil, completion = "Весь Калимдор надеется на тебя, Лорегон.", rewards = nil},
[8304] = {title = "Дражайшая Наталиа", objective = "Допросите обитателей лагеря Бронзоборода по поручению командира Мар'алита из крепости Кенария. Этот лагерь находится южнее крепости Кенария.\n\nСобрав необходимые сведения, вернитесь к командиру Мар'алиту.", description = "Моя милая Наталиа пропала.\n\nЧестно говоря, в последние недели перед исчезновением она довольно странно вела себя. Я несколько раз видел, как она говорила сама с собой. При этом Наталиа уверяла, что все в порядке и ей необходимо продолжать исследования.\n\nВ последний раз я видел ее, когда она направилась в лагерь Бронзоборода, на юг.\n\nУ меня слишком мало солдат, <имя>. Сходи в лагерь Бронзоборода и допроси дворфов.", progress = nil, completion = "*Командир Мар'алит опускает голову в раздумье.*\n\nЖива она или мертва, я должен выполнить свой долг. И найти ее. Увы, я не имею права покинуть этот форт. Придешь ли ты мне на помощь, Сабантул?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[8305] = {title = "Давно забытые воспоминания", objective = "Отыщите в Силитусе хрустальную слезу и загляните в ее глубины.", description = "В пустыне неподалеку от Силитуса, рядом со священной стеной, есть хрустальная слеза. Эта слеза – символ великих потерь, понесенных во время войны Зыбучих песков. Отыщи эту слезу и загляни в ее глубины, дабы достичь просветления.", progress = nil, completion = "Вы чувствуете, что кристалл исполнен великой скорби. Сила ее столь велика, что вам кажется, будто вы немедленно рухнете и умрете от тоски.", rewards = "Вы получите:\n\n"},
[8306] = {title = "В бездне безумия", objective = "Найдите возлюбленную командира Мар'алита из крепости Кенария в Силитусе. По имеющим сведениям, госпожу Наталию Мар'алит можно найти в улье Регал.\n\nПрежде чем отправляться в улей, не забудьте поговорить с гномами из лагеря Бронзоборода. Они могут дать пару советов и подкинуть дополнительную работу.\n\nСледует помнить слова командира: \"Сделай, что должно...\"", description = "Прошу тебя, <имя>, отправляйся в Улей Регал и узнай, что сталось с моей возлюбленной Наталией. Это будет очень непросто, так что собери друзей. Прежде чем нырять в бездну безумия, вернись и поговори с дворфами. Быть может, они подскажут тебе, как разобраться с силитидами из улья.\n\nИ последнее, <имя>. Если она в самом деле безумна, как говорят... сделай, что должно.\n\n*Командир Мар'алит отворачивается в сторону.*", progress = nil, completion = "*Командир Мар'алит хватается за сердце.*\n\nК'Тун? ЧТО все это значит? Что еще за К'Тун? Как мог этот демон превратить мою милую Наталию в описанного тобой монстра?", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nОскверненный посох Чернолесья"},
[8307] = {title = "Блюдо из червей", objective = "Поищите в лагере Сумеречного Молота на западе от крепости Кенария сведения о приготовлении мяса песчаных червей.", description = "Приспособиться к жизни в пустыне, мягко говоря, нелегко. Мне не хватает не только птиц и деревьев Аубердина, но и нормальной еды! Я делаю все, что моих силах, но выбор продуктов у нас невелик. Я изучаю местные травы, но их так мало…\n\nЗато я видела, как в лагерях Сумеречного Молота охотятся на песчаных червей. Но их мясо очень горькое, и я не представляю, как сделать его съедобным. Если ты окажешься в их лагере, смотри в оба. Как узнаешь что-нибудь – сообщи мне.", progress = nil, completion = "В книге содержится несколько обычных рецептов и пара очень оригинальных. Полистав ее, вы находите рецепт, в котором упоминается мясо песчаных червей.", rewards = "Вы получите:\n\n"},
[8308] = {title = "Потерянное письмо Бранна Бронзоборода", objective = "Отнесите письмо Бранна Бронзоборода в лагерь Бронзоборода в южной части Силитуса.", description = "Всем заинтересованным лицам:\n\nЕсли вы читаете это письмо, значит я мертв или скоро умру. Трудно сказать. Большая часть команды уже мертва.\n\nНашел сведения про титана. Страшная битва между ним и Древним богом. Самый настоящий Древний Бог. Нашел древний туннель в Ан'Кираж. Иду по нему.\n\nОтнесите это письмо в мой старый лагерь. Покормите, напоите и приласкайте моих обезьянок.\n\n- Бранн Бронзобород, оперативный исследователь\n\nP.S. Остерегайся безумного ночного эльфа, поклоняющегося Древнему богу.", progress = "Мамочки.", completion = "Что ж, многое прояснилось. Если ты доберешься до Ан'Киража, посматривай, нет ли там старины Бранна. Боюсь, без своих обезьян он бессилен.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nВерная кирка Бранна"},
[8309] = {title = "Поиски рун", objective = "Рутгар Знакописец из лагеря Бронзеборода в Силитусе просит отправиться в улья Аши, Зора и Регал и сделать оттиски со всех покрытых письменами кристаллов.\n\nЧтобы сделать приличные копии древних рун, можно воспользоваться копирующим устройством геолога. По выполнении задания вернуться к Рутгару Знакописцу.", description = "После нашего первого рейда в ульи и последовавшего безумия госпожи Мар'алит, их этих трех ульев так и хлынули проклятые жуки! Мне кажется, их повышенная активность связана с письменами, покрывающими эти странные кристаллы.\n\nНам нужны оттиски с кристаллов из всех трех ульев. Заполучив их, мы можем попытаться понять причины этого безумия.\n\nВозьми копирующее устройство геолога и ступай в ульи, <имя>. Без оттисков из всех ульев даже не возвращайся.", progress = "Если в одном из ульев тебе попадется ненормальная ночная эльфийка, дай ей хорошего пинка от нашего имени.", completion = "Ничего я не понимаю в этих письменах. Первый раз такие вижу! Надеюсь, исследования Франкала помогут пролить на них свет.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[8310] = {title = "Расшифровка", objective = "Добудьте для Франкала Каменного Моста из лагеря Бронзоборода в Силитусе мозг силитидов из ульев Зора, Аши и Регал. По выполнении задания вернитесь к Франкалу.", description = "Мне кажется, я изобрел эликсир, который поможет нам расшифровать письмена и язык силитидов и киражей! Что мне нужно? Хорошо, что ты <спросил/спросила>! Мне нужны мозги! Точнее говоря, мозги всех видов силитидов, живущих в ульях. Принеси мне мозги, и работа Рутгара не пойдет насмарку.", progress = "Поиграй с мартышками, дитя. У меня нет времени на глупости.", completion = "Поразительно! Не уходи далеко, дитя. Может быть, мы поручим тебе еще задание-другое.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[8311] = {title = "Тыквовинские вкусности для Джеспера!", objective = "Поговорите с хозяевами таверн в Штормграде, Стальгорне и Дарнассе, а также с Талвашом де Кисселем в Стальгорне. Выполните то, что они потребуют за предлагамые ими сладости.\n\nВернитесь к Джесперу в сиротский приют Штормграда и принесите ему марципан из Дарнасса, леденец из Гномрегана, нугу из Штормграда и конфету из Стальгорна.", description = "Хотел бы я пойти потыквовинничать, но не могу – приболел. Если ты вместо меня сходишь, я обменяю тебе сладости, что ты наберешь, на те, что у меня уже есть. Думаю, тебе они понравятся – они превратят тебя в разные смешные и страшные штуки!\n\nУ каждого из хозяев таверн в больших городах есть сладости, которые они раздают на Тыквовин. Поговори с ними и выполни их задания. А еще в Стальгорне живет гном по имени Талваш, и он тоже раздает сладости. Когда соберешь их все, принеси мне сюда!", progress = "Ты уже набрал для меня сладостей? Жаль, что я сам не могу пойти, но я рад, что ты мне помогаешь! Мне даже становится легче.", completion = "Ух ты, тебе удалось собрать их все! Просто супер!\n\nСпасибо за то, что тыквовинничал вместо меня. Вот, возьми эти тыквовинские конфетки – я уверен, ты будешь от них в восторге!\n\nСчастливого Тыквовина, Wrestlecake!", rewards = "Вы получите:\n\nТыквовинская конфета"},
[8312] = {title = "Тыквовинские вкусности для Мальца!", objective = "Поговорите с хозяевами таверн в Оргриммаре, Подгороде и Громовом Утесе и с Кали Ремик из деревни Сен'джин. Выполните то, что они потребуют за предлагамые ими сладости.\n\nВернитесь к Мальцу в сиротский приют Оргриммара и принесите ей марципан Громового Утеса, леденец племени Черного Копья, нугу из Оргриммара и конфету Подгорода.", description = "Я так хотела бы пойти просить сладости! Но не могу, потому что болею... Сходи вместо меня, а? А я с тобой потом поменяюсь: отдам те конфеты, что у меня уже есть, взамен тех, которые дадут тебе! Вот эта конфетка тебе наверняка понравится: она позволяет превращаться в разных существ, забавных и страшных!\n\nУ всех хозяев таверн в больших городах непременно есть конфеты, которые они дарят на Тыквовин – надо только поговорить с ними и сделать то, что они попросят. И троллиха по имени Кали Ремик в деревне Сен'джин тоже раздает конфеты. Когда соберешь все конфеты, принеси их мне, ладно?Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТыквовинская конфета"},
[8313] = {title = "Наделение знаниями", objective = "Принесите вырванную страницу с рецептом Каландрате в таверну крепости Кенария.", description = "Хотя вам вполне понятен рецепт по приготовлению мяса песчаного червя, в нем упоминаются незнакомые травы и специи. Быть может, Каландрата хорошо разбирается в растениях пустыни и сможет помочь вам.", progress = "Ты освоил рецепт? Надеюсь, ты поделишься им с друзьями?", completion = "Дай-ка взглянуть…\n\nКажется, все просто. У них есть свои названия для некоторых видов растений, но догадаться совсем просто. Дай, я покажу!", rewards = "Следующее заклинание будет наложено на вас:\n\nКопченые пустынные клецки\n\nВы получите:\n\n"},
[8314] = {title = "Разгадка тайны", objective = "Рутгар Знакописец из лагеря Бронзоборода в Силитусе просит вас отнести покрытую письменами хрустальную призму геологу Ехидной в крепость Кенария.", description = "Мы на грани крупного прорыва, <имя>! Принесенные тобой оттиски позволили нам воссоздать письмена на хрустально призме. Очевидно, что для киражей и прочих непонятных сущностей они имеют большое значение и позволяют передавать силитидам сообщения.\n\nК несчастью, это все, что нам удалось понять. Необходимо прочитать послания, сокрытые в кристаллах.\n\nОтнеси покрытую письменами хрустальную призму геологу Ехидной в крепость Кенария. Может, она сумеет тебе помочь.", progress = "Ну и ну! Что это, Винникруг?", completion = "Дворфы не смогли расшифровать письмена, потому что тут и расшифровывать нечего. Следовало просто правильно повернуть верхний слой призмы, так, чтобы он выровнялся с изображениями внутри кристалла. Тогда сообщение можно прочитать. Умно…\n\nВпрочем, хотя теперь мы можем перевести полученные данные, главное – понять их правильно. На поверхности призмы есть только одна подсказыка – если я правильно перевела оттиски – и если ей верить, то дело плохо.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[8315] = {title = "Зов", objective = "Геолог Ехидная из крепости Кенария просит добыть открыватель кристаллов у киражского посланника.\n\nВам следует отнести письмена зова к Костям Граккаронда, на юг от крепости Кенария, и нарисовать их на песке. Если появится киражский посланник, убейте его и заберите открыватель кристаллов. При успехе вернитесь к геологу Ехидной.\n\nДля выполнения задания понадобится целая армия!", description = "Здесь изображена встреча посланника киражей с тремя силитидами у костей большого дракона. Над рисунком я вижу надпись, судя по всему, какой-то шифр. Не исключено, что это ключевой момент призыва посланника.\n\nЯ создам копию, попробуй воспользоваться ей в пустыне у Костей Граккаронда. Если я права, вожди решат, что им посылают какие-то данные и явятся на зов. Убей их и сразись с посланником. Ключ к кристаллам у него...", progress = "Мы должны воспользоваться подходящей возможностью и нанести удар!", completion = "20.000 лет истории у меня в руках!", rewards = "Вы получите:\n\n"},
[8316] = {title = "Оружие войны", objective = "Грядет война, а вместе с ней невиданные ужасы. Ты сделал все, что мог, и должен получить награду.\n\nЕсли это... пророчество сбудется…\n\n*Геолог Ехидная бледнеет.*\n\nМожно считать, что у нас нет будущего.\n\nЭто оружие понадобится тебе на войне в пустыне.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nНожные латы кенарийского резервистаИнкрустированные хрусталем наголенники"},
[8317] = {title = "Помощь по кухне", objective = "Каландрате из крепости Кенария необходимы 10 копченых пустынных клецок.", description = "Рецепт мне несомненно пригодится. Пора приниматься за работу, чтобы приготовить копченые пустынные клецки уже сегодня. Мне не помешала бы помощь, а уж я бы тебе отплатила сторицей.", progress = "Как идут дела с клецками?", completion = "Отлично! Ты мой спаситель. Не думала, что сторонники Сумеречного Молота могут придумать такой хороший рецепт.", rewards = "Вы получите:\n\n"},
[8318] = {title = "Тайные послания", objective = "Принесите 10 зашифрованных Сумрачных текстов Бору Буйногривому в крепость Кенария.", description = "Некоторые из культистов Сумеречного Молота носят с собой листы бумаги, на которых нацарапана какая-то неразборчивая писанина. Принеси мне целую пачку таких писулек.\n\nЯ не могу понять, что означает эта ерунда, но дело не в том! При помощи этих бумажек происходят тайные переговоры их группировок. Чем больше текстов мы у них отнимем, тем сложнее им будет обмениваться сообщениями!", progress = "Ты принес мне тексты?", completion = "Великолепно! Уберу-ка я их подальше, они мне потом пригодятся.", rewards = "Вы получите:\n\n"},
[8319] = {title = "Зашифрованные Сумеречные тексты", objective = "Можешь и дальше приносить мне тексты. Скоро мы выгоним Сумеречный Молот из Силитуса.", description = nil, progress = "Можешь и дальше приносить мне тексты. Скоро мы выгоним Сумеречный Молот из Силитуса.", completion = "Отличная работа! Я замолвлю за тебя доброе слово.", rewards = nil},
[8320] = {title = "Геолорды из культа Сумеречного Молота", objective = "Убейте 10 геолордов из культа Сумеречного Молота и вернитесь к Хууму Буйногривому в крепость Кенария.", description = "Сумеречный Молот, безумная секта, поклоняющаяся богам смерти и разрушения, разбила лагеря по всему Силитусу и день и ночь проводит свои ритуалы. Планы ее стронников нам неизвестны, но они как-то связаны с пульсирующими красными кристаллами, разбросанными по всей пустыне.\n\nХотя, быть может, однажды нам удастся разгадать эту тайну, но сейчас главное – избавиться от угрозы. Ступай в их лагеря и найди там геолордов из культа Сумеречного Молота. Они командуют этими змеюками, поэтому нанести удар необходимо именно по ним!", progress = nil, completion = "Ты отлично справился с этим заданием, Лорегон. Смерть геолордов из культа Сумеречного Молота – серьезный удар по силам культа. Будем надеяться, что мы сумели отсрочить выполнение их планов...", rewards = "Вы получите:\n\n"},
[8321] = {title = "Вайрал Подлый", objective = "Принесите перстень-печатку Вайрала Хууму Буйногривому в крепость Кенария.", description = "Мы обнаружили еще одну базу Сумеречного Молота. Она зовется Сумеречная пещера и находится в северо-восточной части Силитуса. Их главарь, Вайрал Подлый, живет именно в этой пещере, и его-то тебе и предстоит победить. Одолев злодея, принеси мне его перстень-печатку.\n\nГоворят, что в Сумеречной пещере можно насмотреться таких ужасов, что век не забудешь.", progress = "Тебе удалось победить Вайрала Подлого? Где его перстень-печатка?", completion = "Получилось! Вайрал мертв! Что ж, нападение Сумеречного Молота на Силитус обречено на провал. Их здесь еще немало осталось, но они нескоро оправятся от сегодняшнего удара.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nРукавицы Ветров пустыниПодвеска Солнечной призмы\n\nВы также получите:\n\n"},
[8322] = {title = "Тухлые яйца", objective = "Бросьте тухлые яйца в главную бочку с пивом в таверне Южнобережья.", description = "Люди Южнобережья любят эль, особенно тот, что подают в местной таверне. Думаю, тыквовинского хаоса им маловато – надо бы подпортить им недельный, а то и месячный запас выпивки!\n\nВозьмите вот эти тухлые яйца и подбросьте в главную бочку с пивом в таверне Южнобережья. Однако вашего присутствия там не потерпят, поэтому приготовьтесь защищаться!\n\nКак только угостите все Южнобережье этим незабываемым элем, возвращайтесь на наш фестиваль!", progress = "Бочка полна эля.", completion = "Пробившись в таверну, вы опускаете тухлые яйца в бочку. В воздухе разливается отвратительная вонь...", rewards = "Вы получите:\n\n"},
[8323] = {title = "Истинно верующие", objective = "Принесите 10 зашифрованных Сумеречных текстов отшельнику Ортеллу.", description = "Теперь, когда у меня есть Сумеречный словарь, мне остается попросить тебя о небольшой услуге.\n\nВ моей бывшей организации ежемесячно издаются тщательно закодированные сводки новостей.\n\nЕсли они получат новые сведения обо мне или решат перестать меня искать, об этом сообщат в \"Истинно верующем\".\n\nХотя меня, безусловно, интересует подобная информация, в этих сводках могут быть и другие полезные сведения. Принеси мне как можно больше зашифрованных текстов, добытых у сторонников Сумеречного Молота.", progress = "Тебе удалось найти зашифрованные тексты? Мне было бы интересно заглянуть в свеженький номер \"Истинно верующего\".", completion = "Великолепно! Я как можно скорее займусь расшифровкой. Если мне попадется интересная информация, я найду способ связаться с тобой.", rewards = "Вы получите:\n\n"},
[8324] = {title = "Не теряя веры", objective = "Ты нашел новые зашифрованные тексты? Принеси мне целую кипу, на расшифровку уходит немало времени.", description = nil, progress = "Ты нашел новые зашифрованные тексты? Принеси мне целую кипу, на расшифровку уходит немало времени.", completion = "Великолепно! Если тебе снова попадутся зашифрованные тексты, сразу неси мне.", rewards = "Вы получите:\n\n"},
[8325] = {title = "Очищение острова Солнечного Скитальца", objective = "Убейте 6 маназмеев – они находятся у пламенеющих кристаллов, недалеко от башни и беседки.", description = "Чем скорее ты начнешь обучение, <имя>, тем лучше будет для всех нас. Поскольку права на ошибку у нас нет, слушай внимательно.\n\nПламенеющие кристаллы – зеленые парящие в воздухе объекты к западу от Солнечного шпиля – используются как источники энергии для проведения магических экспериментов. Маназмеи издревле охраняли их, но во время вторжения Плети в Кель'Талас наша магическая сила ослабла, и маназмеи вышли из повиновения.\n\nУ нас нет иного выбора, кроме как истребить их ради очищения острова. Убей несколько маназмеев и возвращайся ко мне.", progress = nil, completion = "Что же, ты успешно справился со своим первым заданием, прими мои поздравления. Твои успехи вселяют в меня уверенность, что ты пойдешь гораздо дальше, чем те молодые эльфы крови, что пропускают мимо ушей уроки наставников. Дальнейшие успехи будут вознаграждаться, и не только знаниями, но и кое-чем более ощутимым.\n\nОднако твоя работа здесь пока не закончена. Тебе еще многому предстоит научиться...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #20997Предмет #20998\n\nВы также получите:\n\n"},
[8326] = {title = "Вынужденные меры", objective = "Соберите 8 ошейников с убитых рысей-прыголапов и детенышей прыголапов и возвращайтесь к магистру Эроне на острове Солнечного Скитальца.", description = "Благодаря тебе мне удалось кое-что выяснить, но, честно говоря, открытие меня не порадовало. Необузданная мощь пламенеющих кристаллов нарушила природное равновесие острова гораздо сильнее, чем я думала. Так что придется прибегнуть к весьма жестким мерам, чтобы восстановить равновесие.\n\nНекоторые из местных животных, например рыси, попали под влияние кристаллов, и их придется истребить. Принеси мне их ошейники, <имя>, и я попробую восстановить нашу власть над оставшимися рысями.", progress = "Мне не доставляет никакого удовольствия просить тебя убивать этих животных. В прошлом мы жили в относительной гармонии с лесными тварями, но настали другие времена. Главная задача син'дорай – выжить. Помни об этом.", completion = "Теперь башня и ее окрестности станут относительно безопасными, пусть и ненадолго. Ты хорошо потрудился, но если мы хотим здесь прочно обосноваться, необходимо взять под контроль весь остров. А для этого придется сталкиваться с куда более грозными противниками, чем обезумевшие маназмеи и рыси.\n\nВозьми мой подарок, Адраан, он тебе, несомненно, пригодится в дальнейшем.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #20992Предмет #20993Предмет #20994Предмет #131818\n\nВы также получите:\n\n"},
[8327] = {title = "Визит к Лантану Перилону", objective = "Поговорите с Лантаном Перилоном на острове Солнечного Скитальца – он стоит рядом с дорогой, отходящей на запад от Солнечного шпиля.Ступай к моему помощнику, Лантану Перилону. Он скажет тебе, что делать дальше. Пока мы обуздываем мощь пламенеющих кристаллов, тебе придется заняться академией Фалтриена. Лантан подробно объяснит тебе все при встрече.\n\nИди на запад по этой дороге и скоро увидишь его.\n\nУдачи, <имя>, твои труды будут вознаграждены.", description = "Ступай к моему помощнику, Лантану Перилону. Он скажет тебе, что делать дальше. Пока мы обуздываем мощь пламенеющих кристаллов, тебе придется заняться академией Фалтриена. Лантан подробно объяснит тебе все при встрече.\n\nИди на запад по этой дороге и скоро увидишь его.\n\nУдачи, <имя>, твои труды будут вознаграждены.", progress = nil, completion = "Адраан, магистр Эрона говорила мне, что ты скоро прибудешь. Видишь на западе высокое здание с резными шпилями, парящее в воздухе? Это Академия Фалтриена. Тебе предстоит отбить ее у одного из Презренных – эльфов крови, поддавшихся своим самым низменным страстям.\n\nНадеюсь, ты готов к битве. Это станет для тебя не просто уроком доблести, но и примером того, что с тобой случится, если ты забудешь о том, кто ты есть.", rewards = "Вы получите:\n\n"},
[8328] = {title = "Наставник магов", objective = "Поговорите с наставницей магов Джулией Солнцесвет в Солнечном Шпиле на Острове Солнечного Скитальца.По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных магов на Острове Солнечного Скитальца тренирует Джулия Солнцесвет. Поговори с ней, может быть, она сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nДжулия, как и все наставники Острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.После выполнения этого задания вы получите:\n\n", description = "По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных магов на Острове Солнечного Скитальца тренирует Джулия Солнцесвет. Поговори с ней, может быть, она сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nДжулия, как и все наставники Острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil},
[8329] = {title = "Наставник воинов", objective = "Поговорите с Делиосом – наставником воинов – в Солнечном Шпиле на Острове Солнечного Скитальца.По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных воинов на Острове Солнечного Скитальца тренирует Делиос. Поговори с ним, может быть, он сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nДелиос, как и все наставники Острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.После выполнения этого задания вы получите:\n\n", description = "По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных воинов на Острове Солнечного Скитальца тренирует Делиос. Поговори с ним, может быть, он сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nДелиос, как и все наставники Острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil},
[8330] = {title = "olanian's Belongings", objective = "Верните Соланиану его гадальный шар, дневник и свиток магии Плети. Их можно найти на острове Солнечного Скитальца у пруда, у одного из пламенеющих кристаллов и у фонтана. Вернитесь с вещами к хранителю Колодца в Солнечный шпиль на острове Солнечного Скитальца.", description = "Из-за беспорядков в Солнечном шпиле я не успел собрать свои вещи, которые оставил в разных местах по всему острову. Я не могу бросить свой пост у Солнечного Колодца, поэтому прошу тебя собрать их.\n\nМне нужен мой гадальный шар, дневник и свиток магии Плети. Возьми эту сумку и сложи в нее вещи. Принеси их мне, и я награжу тебя, а в придачу отдам сумку!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #20995Предмет #20996Предмет #131235\n\nВы также получите:\n\n"},
[8331] = {title = "Аурель Золотой Лист", objective = "Поговорите с Аурель Золотой Лист в крепости Кенария.", description = "Мы надеялись, что Сумеречный Молот свернет свои операции в Силитусе... Увы, мы ошиблись. Благодаря постоянным нападением на лагеря сектантов нам удалось выяснить, что Молот контролирует еще более страшная сила, Совет Бездны. Для связи с культистами, этот совет пользуется ветровыми камнями, рассеянными по лагерям Молота. Пришло время выступить против Совета Бездны.\n\nПоговори с ремесленницей Аурель Золотой Лист, в восточной части крепости Кенария. Мы задумали одну хитрость, для которой необходимо ее искусство.", progress = nil, completion = "Добрый день, Ренгольд. Говорят, ты собираешься выступить против Совета Бездны? Коли так, слушай внимательно...", rewards = "Вы получите:\n\n"},
[8332] = {title = "Герцоги Совета", objective = "Принесите Аурель Золотой Лист в крепость Кенария 1 большой сияющий осколок и 3 талисмана Бездны.", description = "Мы думаем, что при помощи ветрового камня можно устроить засаду на герцога Совета Бездны. Для этого придется связаться с Советом через этот камень и убедить всех, что ты – <один/одна> из командующих среднего ранга Сумеречного Молота.\n\nЧтобы эта хитрость удалась, необходим станционный медальон. Я могу создать его, но мне понадобится большой сияющий осколок и талисманы храмовников Бездны.\n\nПринеси их мне, а остальное я сделаю сама.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСтатусный медальон служителя Сумрака"},
[8333] = {title = "Станционный медальон", objective = "Если тебе понадобится еще один станционный медальон служителя Сумрака, я с радостью помогу тебе. Но мне понадобится еще один осколок и несколько талисманов Бездны...", description = nil, progress = "Если тебе понадобится еще один станционный медальон служителя Сумрака, я с радостью помогу тебе. Но мне понадобится еще один осколок и несколько талисманов Бездны...", completion = "Вот, Драккард. Еще один станционный медальон служителя Сумрачного Молота. Бери на здоровье. Удачи тебе в борьбе с Советом Бездны!", rewards = "Вы получите:\n\nСтатусный медальон служителя Сумрака"},
[8334] = {title = "Агрессия", objective = "Убейте 7 древунов и 7 одичавших древунов, затем вернитесь к Лантану Перилону на острове Солнечного Скитальца.", description = "Прежде чем направить тебя в академию, я хочу, чтобы ты <выполнил/выполнила> одну задачу, требующую немедленного решения. Некогда древуны помогали нам возделывать наш прекрасный остров, но теперь они вышли из повиновения. Уничтожь их как можно скорее, но помни: они очень агрессивны. Именно из-за этого нам приходится истреблять некогда покорных нам слуг.\n\nМне неприятно просить тебя об этом, но выживание – не самое приятное дело. Горевать будем потом.", progress = nil, completion = "Хотя гибель древунов не приносит мне радости, твое свершение показывает мне, что ты созрел для выполнения важнейшей задачи на Острове Солнечного Скитальца. Выбери награду – для следующего задания тебе понадобится надежное оружие. От твоего успеха зависит дальнейшая судьба острова.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #20835Предмет #20836Предмет #20837Предмет #20839Предмет #20840\n\nВы также получите:\n\n"},
[8335] = {title = "Фелендрен Изгой", objective = "Убейте 8 чародейских призраков, 2 нечистых чародейских призрака и Фелендрена Изгоя в академии Фалтриена. Принесите голову Фелендрена Лантану Перилону на остров Солнечного Скитальца.", description = "В академии Фалтриена, что к юго-западу отсюда, обитает предатель нашего народа.\n\nЕго зовут Фелендрен. Он был изгнан из земель эльфов крови за то, что не слушал предостережений наставников и старейшин. Он изгой нашего общества, ибо живет он лишь для того, чтобы насыщать свою неутолимую жажду магии. Фелендрен не пожелал бороться со своим пагубным пристрастием и превратился в жалкое подобие мыслящего существа. Теперь он один из Презренных, которые угрожают нашему спокойствию!\n\nСрази его и тех духов, которых он сделал своими приспешниками!", progress = "Помни: Фелендрен Изгой – всего лишь вестник куда большей беды. Его уничтожение решит лишь наши сегодняшние проблемы, но всем эльфам крови грозит та же участь, если мы не научимся обуздывать свою тягу к магии.", completion = "Голова Фелендрена... ты достоин похвалы, Адраан. Ты преуспел там, где прочие, как и Фелендрен, потерпели крах. Возможно, ты и правда уже готов совершать подвиги во имя эльфов крови.\n\nТвой успех говорит о том, что ты способен преодолеть серьезные испытания, таящиеся в чащобах Лесов Вечной Песни... и поверь мне, они уже ждут тебя.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #20838Предмет #20841\n\nВы также получите:\n\n"},
[8336] = {title = "Fistful of Slivers", objective = "Соберите 6 магических осколков, убивая любых существ, обладающих магическими способностями, а затем вернитесь к чародею Итанасу.", description = "Очень жаль, что мы утратили контроль над многими существами этого острова. Некогда это был оплот спокойствия, трудов и исследований. Теперь мы только и делаем, что отбиваемся от нападений собственных созданий!\n\nВыполни для меня небольшое поручение и получишь волшебный дар. Принеси мне горсть магических осколков. Ты можешь найти их у существ, обладающих магическими способностями. В награду за это я наложу на тебя заклятие, которое поможет тебе в твоих приключениях.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПредмет #20991"},
[8338] = {title = "Оскверненный магический осколок", objective = "Принесите оскверненный магический осколок чародею Хелиону, который стоит возле беседки у Солнечного шпиля на острове Солнечного Скитальца.", description = "Вы нашли странный магический осколок, обыскав останки нечистого чародейского призрака. Осколок не похож на те, что вам уже попадались. Он темный и выглядит зловеще – прямо как тот дух, у которого вы его забрали. Один вид его на вашей ладони наполняет вас зловещими предчувствиями.\n\nЧародей Хелион возле беседки у Солнечного шпиля на острове Солнечного Скитальца наверняка сможет найти ему применение.", progress = "Судя по всему, у тебя какое-то срочное дело. Чем я могу помочь?", completion = "Как интересно... Когда я говорю \"интересно\", это значит, что я крайне взволнован.\n\nВосстановление контроля над островом после разрушения Солнечного Колодца – задача чрезвычайно тяжелая. Подозреваю, что за всеми нашими бедами стоит одна и та же злая сила, и этот осколок поможет мне понять, что же на самом деле происходит.\n\nТы мудро поступил, принеся его мне, Адраан. Вот, возьми это в награду за предусмотрительность. Благодарю тебя.", rewards = "Вы получите:\n\n"},
[8340] = {title = "Сумеречный перстень-печатка", objective = "Вы получите:\n\n", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nКольцо Власти служителя Сумрака"},
[8341] = {title = "Лорды Совета", objective = "Принесите Аурель Золотой Лист в крепость Кенария 5 больших сияющих осколков и 3 перстня Бездны.", description = "Чтобы вызвать лордов Совета Бездны, необходим больший ветровой камень. К тому же они согласны беседовать лишь с самыми высокопоставленными представителями Сумеречного Молота. Но... Я придумала, как поработать над твоей маскировкой и обмануть лордов Бездны!\n\nДля этого понадобится кольцо Власти, которое носят лишь вожди культистов. Я готова создать такое кольцо, если ты принесешь мне большие сияющие осколки и перстни Бездны.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКольцо Власти служителя Сумрака"},
[8342] = {title = "Кольцо Власти служителя Сумрака", objective = "Лорегон, если ты собираешься вновь выступить против Высшего Совета Бездны, тебе понадобится еще одно кольцо Власти служителя Сумрака. Принеси мне еще несколько осколков и перстней, и я сделаю такое кольцо.", description = nil, progress = "Лорегон, если ты собираешься вновь выступить против Высшего Совета Бездны, тебе понадобится еще одно кольцо Власти служителя Сумрака. Принеси мне еще несколько осколков и перстней, и я сделаю такое кольцо.", completion = "А, вижу, твоя решимость не ослабела. Немногие решились бы схватиться с демоническим советом!\n\nВот кольцо, Лорегон. Да пребудет воля твоя тверда, и да сопутствует тебе удача.", rewards = "Вы получите:\n\nКольцо Власти служителя Сумрака"},
[8343] = {title = "Открытие Золотого Листа", objective = "Поговорите с Аурель Золотой Лист в крепости Кенария.", description = "<имя>, Аурель придумала, как вызвать и одолеть правящую верхушку Совета Бездны! Это опасно, но ты <заслужил/заслужила> уважение всего Круга Кенария. Мы знаем, что ты – <единственный/единственная>, кому по плечу такое задание.\n\nЖелаю удачи, <имя>. Когда решишь приняться за это задание, поговори с Аурель.", progress = nil, completion = "Хуум говорит правду. Думаю, я знаю, как вызвать лорда Совета Бездны. Слушай внимательно...", rewards = "Вы получите:\n\n"},
[8344] = {title = "Постижение основ", objective = "Принесите 4 призрачные сущности и 1 оскверненную призрачную сущность призывателю Тель'Лариену в Солнечный Шпиль на Остров Солнечного Скитальца.", description = "Внимай моим словам, <юноша/дева>, этот остров поражен порчей, и она куда сильнее, чем последствия удара Плети.\n\nЯ уверен, что на острове затаились демоны.\n\nК западу ты увидишь шпили академии Фалтриена. Чародейские призраки, что наводнили ее, – источники демонической силы. Принеси мне сущности этих духов.\n\nЗа твое послушание я научу тебя призывать беса – твоего первого спутника на долгом пути чернокнижника.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nПризыв беса"},
[8345] = {title = "he Shrine of Dath'Remar", objective = "Прочтите надпись на святилище Дат'Ремара и вернитесь к хранителю Колодца Соланиану в Солнечный шпиль на острове Солнечного Скитальца.", description = "День за днем я стою здесь, смотрю и жду. Глаза мои устремлены к горизонту, но все говорят, что я живу лишь прошлым. И все же я твердо убежден, что каждый, кто попадает на этот остров, обязан почтить память героев, пожертвовавших собой ради нашего народа.\n\nДат'Ремар Солнечный Скиталец был нашим первым королем. Он привел нас сюда из Калимдора через бурный Водоворот.\n\nНайди его святилище на западе отсюда и не возвращайся, пока не прочтешь надпись, посвященную памяти короля.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8346] = {title = "hirst Unending", objective = "Используйте расовую способность \"Волшебный поток\" против маназмея, затем вернитесь к чародею Хелиону.", description = "На острове Солнечного Скитальца тебя ждет множество уроков, но один ты <должен/должна> запомнить навсегда: контролируй свою жажду магии, <имя>! Она неутолима! Тебе необходимо научиться контролировать поглощение энергии при помощи \"Волшебного потока\". Если ошибешься – станешь <одним/одной> из Презренных... безнадежно зависимых от магии безумцев.\n\nНайди на острове маназмея и попрактикуй на нем \"Волшебный поток\". Научись обуздывать свою тягу к магии. Возвращайся, когда закончишь.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #20999Предмет #21000Предмет #21001Предмет #131236\n\nВы также получите:\n\n"},
[8347] = {title = "Помощь курьерам", objective = "Поговорите с курьером Аларион у моста к югу от острова Солнечного Скитальца.Магистр Эрона желает, чтобы ты <направился/направилась> в город Луносвет и <помог/помогла> нам восстановить его... Она начала питать к тебе особое доверие после того, как ты <разрешил/разрешила> ситуацию в академии Фалтриена. Не разочаруй нас, <имя>.\n\nПо дороге на площадь Соколиных Крыльев, к югу отсюда, поговори с курьером Аларион. Ты найдешь ее неподалеку от моста.\n\nКурьеры заботятся о перевозке грузов отсюда на континент и обратно, и ты <мог/могла> бы оказать им существенную помощь в этом деле.", description = "Магистр Эрона желает, чтобы ты <направился/направилась> в город Луносвет и <помог/помогла> нам восстановить его... Она начала питать к тебе особое доверие после того, как ты <разрешил/разрешила> ситуацию в академии Фалтриена. Не разочаруй нас, <имя>.\n\nПо дороге на площадь Соколиных Крыльев, к югу отсюда, поговори с курьером Аларион. Ты найдешь ее неподалеку от моста.\n\nКурьеры заботятся о перевозке грузов отсюда на континент и обратно, и ты <мог/могла> бы оказать им существенную помощь в этом деле.", progress = nil, completion = "О, привет, |3-6(Маг)! Дошел до меня слух, что молодой и талантливый эльф, хорошо послуживший магистру Эроне, направляется сюда, дабы помочь Курьерам. Мы не откажемся от помощи, зная, что ты проявил себя так хорошо.\n\nНадеюсь, ты выполнишь для нас парочку поручений?", rewards = "Вы получите:\n\n"},
[8348] = {title = "Перстень герцогов", objective = "Принесите перстень Бездны Бору Буйногривому из крепости Кенария.", description = "Хуум говорит, что ты <придумал/придумала>, как вызвать герцогов Бездны! Это большое достижение.\n\nЗнаешь, что бы еще хорошо сделать? Убить одного из них. Это произвело бы неизгладимое впечатление на их прихвостней, если ты понимаешь, о чем я. В доказательство собственного подвига принеси перстень герцога.", progress = "Как дела с герцогом Бездны? Трудно пришлось?", completion = "Стоило тебе войти в крепость Кенария, и я сразу понял, что передо мной могучий |3-6(Воин). Так держать!", rewards = "Вы получите:\n\nСумка с трофеями"},
[8349] = {title = "Бор Буйногривый", objective = "Поговорите с Бором Буйногривым из крепости Кенария.", description = "Теперь у тебя есть медальон, и ты можешь вызвать герцога Бездны. Поговори с Бором Буйногривым. Он даст тебе задание.\n\nУдачи, <имя>. Если тебе снова понадобятся медальоны, возвращайся ко мне.", progress = nil, completion = "Рад видеть тебя, |3-6(Воин)! Значит, теперь у тебя есть медальон? Хорошо – он понадобится тебе для следующего задания...", rewards = "Вы получите:\n\n"},
[8350] = {title = "Доставка посылки", objective = "Доставьте посылку Эроны хозяйке таверны Деланиель на площадь Соколиных Крыльев в лесах Вечной Песни.", description = "Гибель еще одного нашего курьера – истинная трагедия, но это неизбежные издержки нашего ремесла. Нужно как можно быстрее доставить эту посылку в таверну на площади Соколиных Крыльев.\n\nНам недостает курьеров, и мне больше некому дать это поручение.\n\nНе скрою – путь на площадь Соколиных Крыльев станет чрезвычайно опасен, как только ты покинешь пределы Рассветной улицы. Возьмешься за это дело, <имя>?", progress = "Добро пожаловать в мою таверну, |3-6(Маг). Я вижу, ты что-то мне принес?", completion = "Благодарю за быструю доставку.\n\nИ пока ты здесь, чувствуй себя как дома. Если у тебя еще нет камня возвращения – возьми его. Он позволит тебе мгновенно перенестись в таверну – но не чаще, чем раз в полчаса. Если вдруг потеряешь свой камень возвращения – просто зайди в любую таверну, и хозяин охотно даст тебе другой камень.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОсвежающая ключевая водаСпелое красное яблоко\n\nВы также получите:\n\n"},
[8351] = {title = "Разговор с Бором", objective = "Поговорите с Бором Буйногривым из крепости Кенария.", description = "Теперь ты можешь замаскироваться под высокопоставленного представителя Сумрачного Совета, и с тобой хочет поговорить Бор Буйногривый. Ступай, поговори с ним и готовься к трудному заданию...Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8352] = {title = "Скипетр Совета", objective = "Принесите скипетр Бездны Бору Буйногривому из крепости Кенария.", description = "Мы с Хуумом только что обсуждали тебя. Он говорит, что ты <готов/готова> испытать себя и сразиться с лордом Бездны!\n\nДолжен предупредить, что это очень опасно. Возьми с собой подкрепление. И не пару друзей, а хороший боевой отряд. Если твои друзья стоят тебя, кто знает, может быть, удастся одолеть этого лорда!\n\nЕсли ты вдруг справишься – мне как всегда потребуются доказательства – то тебя ждет великая награда.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСундук с трофеями"},
[8353] = {title = "Курочка с мятой", objective = "Изобразите курицу для хозяина таверны Огневара.", description = "А, тыквовинничаем для больных деток? Я сказал бы, ты малость <староват/старовата> конфетки выпрашивать...\n\nЧто же, за мое лакомство – стальгорнскую мятную конфетку – ты мне... поквохтаешь как курица! Да, курочка с мятой хорошо идет... ладно, может, курочке от этого и не так ХОРОШО... но конфетку не дам, пока не поквохтаешь!\n\nЛадно, <класс>, будешь квохтать или нет?! Пора отрабатывать лакомство!", progress = nil, completion = "Ой, забавно! Просто здорово, Мирдин! Вот твое угощение.\n\nВеселого Тыквовина!", rewards = "Вы получите:\n\nКонфета Стальгорна"},
[8354] = {title = "Курочка с мятой", objective = "Изобразите курицу для хозяина таверны Нормана и получите за это конфету Подгорода!", description = "А, ты у нас сегодня заместо детишек, да? Я сказал бы, ты малость <староват/старовата> конфетки выпрашивать...\n\nЧто же, за мое лакомство – мятную конфету Подгорода – ты... поквохчешь как курица! Да, курочки любят мятные конфетки... впрочем, им не обязательно их ЛЮБИТЬ... главное, что конфетку ты не получишь, пока не поквохчешь!\n\nНу что, <класс>, будешь квохтать или нет?! Пора отрабатывать лакомство!", progress = "Я жду...", completion = "Ха-ха-ха! Просто здорово, Дэдоутсайд! Вот твое угощение.\n\nВеселого Тыквовина!", rewards = "Вы получите:\n\nКонфета Подгорода"},
[8355] = {title = "Плата за мармеладки", objective = "Изобразите паровозик для Талваша де Кисселя.", description = "А, тебе нужны сладости! Ха-ха!\n\nНу, хотя ты и доброе дело делаешь, собирая сладости для больных детишек, так просто я тебя не отпущу. Есть у меня вкусные гномреганские мармеладки, и я отдам их больным детишкам... если ты изобразишь мне паровоз! Ха, вот это будет штука! За мармеладку – целый паровоз!\n\nТу-ту, <класс>!", progress = "Ну, давай!", completion = "У-у-у! Великолепно, Wrestlecake! Вот твои сладости.\n\nСчастливого Тыквовина!", rewards = "Вы получите:\n\nЛеденец Гномрегана"},
[8356] = {title = "Поиграй мускулами!", objective = "Поиграйте мышцами для хозяйки таверны Аллисон и получите от нее за это нугу из Штормграда.", description = "Какой у тебя... интересный костюмчик. Несмотря на то, что ты по доброте своей помогаешь заболевшему ребенку, мне все же придется попросить тебя сделать что-нибудь!\n\nНу-ка, ну-ка... ты выглядишь <таким сильным и мускулистым/такой сильной и мускулистой> в этом... наряде... посмотрим-ка на твои бицепсы! Да, давай, поиграй-ка мускулами, <силач/силачка>!\n\nПоиграешь мускулами – дам тебе вкуснейшей нуги. Это отличное тыквовинское угощение!", progress = "Никаких сластей, пока не поиграешь бицепсами, Глодек...", completion = "Да ты и правда силач, ха-ха! Прекрасно, и спасибо за то, что так ценишь спорт. Вот твои сладости.\n\nСчастливого Тыквовина, Коин!", rewards = "Вы получите:\n\nНуга из Штормграда"},
[8357] = {title = "Танец за марципан", objective = "Потанцуйте для хозяйки таверны Салиенны, и за это вы получите дарнасский марципан!", description = "Хоть это и не твоя прямая обязанность, лакомство тебе придется отработать! От традиции, пожалуй, отходить не будем...\n\nДумается, нынче марципановая булочка потянет на... ТАНЕЦ! Да-да, покажи, как ты пляшешь! Попляши для меня, и я дам тебе вкусненькую марципышечку!", progress = nil, completion = "Да тебе стоило бы в балет податься, Wrestlecake!\n\nВот твоя награда за чудесное развлечение. Веселого тебе тыквовина, и передай привет больным детишкам! Пусть быстрее поправляются.", rewards = "Вы получите:\n\nДарнасский марципан"},
[8358] = {title = "Плата за леденец", objective = "Изобразите паровозик перед Кали Ремик (команда /train) и получите в награду леденец племени Черного Копья!", description = "А, тебе нужны сладости? Ну-ну!\n\nЗаруби себе на носу: ты, конечно, занимаешься благородным делом, собираешь сласти для больного ребенка, но без платы ты ничего не получишь! У меня как раз имеется сладкий-пресладкий леденец племени Черного Копья, больная девочка ему будет очень рада... но сначала изобрази-ка ты мне паровозик! То-то я посмеюсь! Посмотри, какой замечательный леденец – а всего-то и надо изобразить паровозик!\n\nНу-ка, <класс>! Чух-чух-чух-чух!", progress = "Ну, поехали...", completion = "Ту-ту-у! Ну, молодец, Тотенштерн! Вот твоя конфета.\n\nСчастливого Тыквовина!", rewards = "Вы получите:\n\nЛеденец племени Черного Копья"},
[8359] = {title = "Поиграй мускулами!", objective = "Поиграйте мускулами (команда /мускулы) перед хозяйкой таверны Гришкой.", description = "Ой, какой интересненький костюмчик! Нет, ты, конечно, <хороший мальчик/хорошая девочка>, собираешь сладости для больного ребенка, но, боюсь, тебе все же придется выполнить для меня какое-нибудь задание, прежде чем ты получишь конфету.\n\nДай-ка подумать... У тебя такой накачанный вид в этом... костюмчике! Вот поиграй-ка мускулами!\n\nА я тебе за это дам вкусной оргриммарской нуги. Дети ее очень любят!", progress = "Не-ет, Канц, сначала поиграй мускулами!", completion = "О-о, да ты настоящий силач, ха-ха! Молодец, Ямир! Я ужасно повеселилась. Вот тебе твоя конфета.\n\nВеселого Тыквовина!", rewards = "Вы получите:\n\nНуга из Оргриммара"},
[8360] = {title = "Танец за марципан", objective = "Потанцуйте для хозяйки таверны Палы, и за это вы получите марципан Громового Утеса!", description = "Хоть это и не твоя прямая обязанность, лакомство тебе придется отработать! От традиции, пожалуй, отходить не будем...\n\nДумается, нынче марципановая булочка потянет на... ТАНЕЦ! Да-да, покажи, как ты пляшешь! Попляши для меня, и я дам тебе вкусненькую марципышечку!", progress = "Ты ведь умеешь танцевать, а? Ну, попытайся – правая нога вперед... затем назад... вперед...потряси ей...", completion = "Да тебе стоило бы в балет податься, Зулалар!\n\nВот твоя награда за чудесное развлечение. Веселого тебе тыквовина, и передай привет больным детишкам! Пусть быстрее поправляются.", rewards = "Вы получите:\n\nМарципан Громового Утеса"},
[8361] = {title = "Связь с Бездной", objective = "Убейте храмовника Бездны по поручению Бора Буйногривого из крепости Кенария, что в Силитусе, и принесите в доказательство талисман Бездны.", description = "Мы видели, как сектанты проводят ритуалы и вызывают могущественных повелителей стихий. Мы не знаем, поклоняются ли им культисты или используют как посредников при общении с еще более страшными силами. Ясно одно – они получают приказы от этих элементалей.\n\nОтыщи храмовника Бездны и задай ему хорошую трепку! Стоит лишить войска командира, и в их рядах начинается разброд и шатания. Принеси доказательство своего подвига.", progress = "Тебе удалось выполнить мое поручение?", completion = "Ха! У тебя получилось! Скоро мы одолеем Сумеречный Молот!", rewards = "Вы получите:\n\nМешок с трофеями"},
[8362] = {title = "Талисманы Бездны", objective = "Ты уже доказал, что умеешь сражаться, Керирофу. Нельзя ослаблять натиск на Сумеречный Молот. Ступай, сразись с новыми храмовниками Бездны, и получишь в награду вещи, которые мы с Хуумом добыли в бою.", description = nil, progress = "Ты уже доказал, что умеешь сражаться, Керирофу. Нельзя ослаблять натиск на Сумеречный Молот. Ступай, сразись с новыми храмовниками Бездны, и получишь в награду вещи, которые мы с Хуумом добыли в бою.", completion = "Молодец! Меньше храмовников – меньше забот.\n\nВот, возьми, Керирофу. Надеюсь, это тебе пригодится.", rewards = "Вы получите:\n\nМешок с трофеями"},
[8363] = {title = "Перстни Бездны", objective = "Ты доказал, что можешь вызвать на бой герцогов Бездны, Олин. А я всегда готов поощрять хорошие тенденции. Принеси мне еще перстней, и я награжу тебя.", description = nil, progress = "Ты доказал, что можешь вызвать на бой герцогов Бездны, Олин. А я всегда готов поощрять хорошие тенденции. Принеси мне еще перстней, и я награжу тебя.", completion = "Великолепно, Олин! Одолев герцогов, ты нанес серьезный удар Сумеречному Молоту. Вот обещанная награда. Это лучшее из найденного нами с Хуумом.", rewards = "Вы получите:\n\nСумка с трофеями"},
[8364] = {title = "Скипетры Бездны", objective = "Тебе удалось превзойти все мои ожидания, Драккард. Ты можешь справиться с противниками, которых мы с Хуумом не решились бы вызвать на бой.\n\nМне остается лишь поощрять тебя за борьбу с Сумеречным Молотом и его главарями.\n\nПринеси мне еще сумеречных скипетров, и я постараюсь достойно тебя наградить.", description = nil, progress = "Тебе удалось превзойти все мои ожидания, Драккард. Ты можешь справиться с противниками, которых мы с Хуумом не решились бы вызвать на бой.\n\nМне остается лишь поощрять тебя за борьбу с Сумеречным Молотом и его главарями.\n\nПринеси мне еще сумеречных скипетров, и я постараюсь достойно тебя наградить.", completion = "Я знал, что ты справишься, Драккард! Вот твоя награда.", rewards = "Вы получите:\n\nСундук с трофеями"},
[8365] = {title = "Пиратские шляпы", objective = "Добудьте 20 шляп пиратов Южных Морей и отнесите их Отти Кутюри в Порт Картеля в Танарисе.", description = "Так это тебя Картель послал к нам на помощь? Пожалуй, ты сойдешь. Слушай внимательно, <класс>. Ты ведь знаешь, что я законодатель мод Азерота? Короли и королевы, вожди и... как там Орда называет своих королев? Одним словом, все носят, что я укажу. И платят за это бешеные деньги, что особенно приятно.\n\nВ общем, поступим так. Отправляйся в Бухту Сорванных Парусов и раздобудь побольше пиратских шляп. Справишься?", progress = "У тебя на руках все двадцать шляп? Не верю, покажи. И все должны быть в безупречном состоянии!", completion = "Ты просто душка, даже если провозился дольше, чем я привыкла. Остается почистить и украсить эти шляпы, и я заработаю кругленькую сумму! Я всегда считала, что за хорошую работу полагается вознаграждение. Вот, возьми. И советую потратить часть на хорошую ванну, солнышко.", rewards = "Вы получите:\n\n"},
[8366] = {title = "Покажи этим пиратам", objective = "Начальник отдела безопасности Чепухастер из Порта Картеля в Танарисе просит убить 10 пиратов, 10 флибустьеров, 10 рабочих и 10 висельников Южных морей.", description = "Они требуют от меня невозможного!\n\nКартель Хитрая Шестеренка хочет, чтобы я преподал пиратам Южных Морей урок. Мне что, разорваться?! Я должен поддерживать здесь порядок.\n\nВ последнее время пираты забыли, что Картель платит им за защиту. Нужно показать им, что к чему.\n\nПираты поселились в Бухте Сорванных Парусов, неподалеку отсюда, на юге. Спасибо, <имя>. Я твой должник!", progress = "Уже вернулся? Надеюсь, ты хорошенько проучил эту южноморскую шваль!", completion = "Эфром! Да ты просто герой!!!\n\nТеперь-то Картель от меня отстанет, ведь эта шваль получила по заслугам! Так, что бы дать тебе в награду? Пожалуй, немного денег, да еще выбери из этих вещей, что понравится.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШлем-ведро Южного моряЮжноморские сапоги-амулет\n\nВы также получите:\n\n"},
[8367] = {title = "Ради славы", objective = "Принесите 3 почетных знака Альтеракской долины, 3 почетных знака Низины Арати и 3 почетных знака Ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.", description = "Нет выше чести, чем биться с Альянсом во имя Орды! Лучшие же наши воины – те немногие, которым довелось сразиться на ВСЕХ полях битвы. Отдельные стычки не помогут нам одолеть врага. Лишь тщательно спланировав наступление, мы сломим проклятый Альянс.\n\nСтупай в Низину Арати, Альтеракскую долину и Ущелье Песни Войны и вступи в схватку с Альянсом. За честь! За Орду!", progress = "Земля в Низине Арати пропитана кровью, а эхо битвы все еще не смолкло в Альтераке. Не теряй попусту мое время, ступай на фронт!", completion = "На твою долю выпали непростые испытание, но ты не лишился мужества и сила тебя не покинула. Знаки победы – пустое. Не по ним судят о твоей доблести. Выше голову, Зелинг. Сегодня тебе подобает смотреть на других свысока, ведь ты настоящий герой!", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +2388\n\nВы получите:\n\n"},
[8368] = {title = "Битва за Ущелье Песни Войны", objective = "Принесите 3 почетных знака Ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.", description = "Битва со Среброкрылыми Часовыми за Ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины.\n\nНе бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!", progress = "Ты несешь вести из Ущелья Песни Войны?", completion = "Великолепно! Ты показал, чего стоишь, выступив против врага в Ущелье Песни Войны! Да разнесутся вести о твоих подвигах по всем нашим землям.", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +50\n\nВы получите:\n\n"},
[8369] = {title = "Вторжение в Альтеракскую долину", objective = "Принесите 3 почетных знака Альтеракской долины ордынскому вестнику войны рядом со входом на поля боя.", description = "Слушай, <имя>. Что бы ни болтали про битву в Альтеракской долине, правда состоит в следующем: экспедиция Грозовой Вершины вторглась в земли клана Северного Волка. В тот день, когда мы позволим Альянсу безнаказанно нарушать наши границы, я повешу секиру на стену и примусь посыпать голову пеплом. Отправляйся и сотри в порошок наглых захватчиков!", progress = "Что слышно из земель Северного Волка? Как идет битва в Альтеракской долине?", completion = "Ты встал на защиту наших земель с невиданной храбостью! Я непременно расскажу командующим о твоих подвигах.", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +398\n\nВы получите:\n\n"},
[8370] = {title = "Завоевание Низины Арати", objective = "Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.", description = "Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.\n\nВ Низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, <имя>!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +82\n\nВы получите:\n\n"},
[8371] = {title = "В едином порыве", objective = "Принесите 3 почетных знака Альтеракской долины, 3 почетных знака Низины Арати и 3 почетных знака Ущелья Песни Войны бригадному генералу Альянса рядом со входом на поля боя.", description = "В войне против Орды решающей может оказаться любая битва, <сынок/дочка>.\n\nПобеда на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот – любая проигранная битва может дать нашим врагам преимущество в другой.\n\nАльянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закаленных в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне.", progress = "Какие вести из дальних стран?", completion = "Да, ты не из тех, кто дает слабину! То, что тебе удалось постичь, не измерить никчемными медалями и наградами. Лишь те, кто тоже прошли сквозь огонь битвы, могут понять, что такое закалка истинного бойца.\n\nТы молодец, |3-6(Охотник). Настоящий герой Альянса!", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +2388\n\nВы получите:\n\n"},
[8372] = {title = "Битва за Ущелье Песни Войны", objective = "Принесите 3 почетных знака Ущелья Песни Войны бригадному генералу Альянса рядом со входом на поля боя.", description = "Среброкрылые Часовые вступили в бой со всадниками из клана Песни Войны, стараясь защитить от них лес. Впрочем, желание сохранить этот лес объсняется не только их любовью к природе.\n\nЭтот лес представляет собой естественную преграду для наступления сил Орды. Без него Астранаар не продержался бы и дня, и в наши земли давно вторглась бы огромная армия Орды.\n\nВнеси свой вклад в борьбу со всадниками из клана Песни Войны, <имя>! За Альянс!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +50\n\nВы получите:\n\n"},
[8373] = {title = "Сила сосен", objective = "Уберите любую бомбу-вонючку Отрекшихся, брошенную в Южнобережье, при помощи очистителя бомб-вонючек. По выполнении задания возвращайтесь к сержанту Дыгалу.", description = "Самое гнусное в Тыквовине – это бомбы-вонючки, которые Отрекшиеся бросают на Южнобережье. Кто бы мог подумать, что праздновение свободы требует такой вони?\n\nКогда наступит Тыквовин, убери при помощи этого очистителя любую из мерзких бомб, которые Орда может подкинуть к нам в деревню. Очиститель действует благодаря силе сосен.\n\nПрими участие в поддержании чистоты Южнобережья, и я дам тебе кое-какие тыквовинские вкусности, которым ты несомненно порадуешься. Договорились?Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТыквовинская конфета"},
[8374] = {title = "Завоевание Низины Арати", objective = "Принесите 3 почетных знака Низины Арати бригадному генералу Альянса рядом со входом на поля боя.", description = "Чтобы выиграть войну, мало быть быть умнее и хитрее противника. Зачастую победа достается тем, в чьих руках сосредоточены все ресурсы.\n\nРесурсов в Низине Арати – хоть отбавляй. Главное – захватить их первыми.\n\nЕсли победа будет за Альянсом, нашим солдатам достанется больше мечей и копий. Если Орде – те же мечи и копья обратятся против нас! Твой долг помочь Альянсу захватить Низину Арати!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +82\n\nВы получите:\n\n"},
[8375] = {title = "Помни Альтеракскую долину!", objective = "Принесите 3 почетных знака Альтеракской долины бригадному генералу Альянса рядом со входом на поля боя.", description = "Не пойми меня превратно, <имя>. Орда совершенно справедливо считает долину Альтерака территорией клана Северного Волка.\n\nВидишь ли, экспедиция Грозовой Вершины прибыла в эти края как мирные исследователи. Они искали руду и древние реликвии, но нашли лишь смерть. Альянс не ожидал такой бессмысленной жестокости даже от клана Северного Волка.\n\nВечная память отважным дворфам, павшим от рук вероломных орков. Ступай, <класс>, внеси свой вклад в битву за Альтеракскую долину. За Альянс!", progress = "Какие вести с фронта, Бракоделл?", completion = "Ты исполнил свой долг, Бракоделл. Орда заплатит за свое вероломство!", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +398\n\nВы получите:\n\n"},
[8376] = {title = "Оружие войны", objective = "Грядет война, а вместе с ней невиданные ужасы. Ты сделал все, что мог, и должен получить награду.\n\nЕсли это... пророчество сбудется…\n\n*Геолог Ехидная бледнеет.*\n\nМожно считать, что у нас нет будущего.\n\nЭто оружие понадобится тебе на войне в пустыне.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nНожные латы кенарийского резервистаНаголенники, отделанные хрусталем"},
[8377] = {title = "Оружие войны", objective = "Грядет война, а вместе с ней невиданные ужасы. Ты сделал все, что мог, и должен получить награду.\n\nЕсли это... пророчество сбудется…\n\n*Геолог Ехидная бледнеет.*\n\nМожно считать, что у нас нет будущего.\n\nЭто оружие понадобится тебе на войне в пустыне.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nНабедренники кенарийского резервистаРукавицы пустынного бродяги"},
[8378] = {title = "Оружие войны", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПоножи кенарийского резервистаСапоги дюнного следопыта"},
[8379] = {title = "Оружие войны", objective = "Грядет война, а вместе с ней невиданные ужасы. Ты сделал все, что мог, и должен получить награду.\n\nЕсли это... пророчество сбудется…\n\n*Геолог Ехидная бледнеет.*\n\nМожно считать, что у нас нет будущего.\n\nЭто оружие понадобится тебе на войне в пустыне.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nШтаны кенарийского резервистаПерчатки Цветка пустыни"},
[8380] = {title = "Оружие войны", objective = "Грядет война, а вместе с ней невиданные ужасы. Ты сделал все, что мог, и должен получить награду.\n\nЕсли это... пророчество сбудется…\n\n*Геолог Ехидная бледнеет.*\n\nМожно считать, что у нас нет будущего.\n\nЭто оружие понадобится тебе на войне в пустыне.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nНабедренники кенарийского резервистаРукавицы Странника пустошей"},
[8381] = {title = "Оружие войны", objective = "Грядет война, а вместе с ней невиданные ужасы. Ты сделал все, что мог, и должен получить награду.\n\nЕсли это... пророчество сбудется…\n\n*Геолог Ехидная бледнеет.*\n\nМожно считать, что у нас нет будущего.\n\nЭто оружие понадобится тебе на войне в пустыне.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nШтаны кенарийского резервистаПерчатки из кожи песчаного червя"},
[8382] = {title = "Оружие войны", objective = "Грядет война, а вместе с ней невиданные ужасы. Ты сделал все, что мог, и должен получить награду.\n\nЕсли это... пророчество сбудется…\n\n*Геолог Ехидная бледнеет.*\n\nМожно считать, что у нас нет будущего.\n\nЭто оружие понадобится тебе на войне в пустыне.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПоножи кенарийского резервистаСапоги самума"},
[8383] = {title = "Помни Альтеракскую долину!", objective = "Битва в Альтеракской долине идет, не утихая! Давно ли ты вступал в бой, Драккард?", description = nil, progress = "Битва в Альтеракской долине идет, не утихая! Давно ли ты вступал в бой, Драккард?", completion = "Ты – гордость Альянса, Драккард. Если не сдаваться и не отступать, вскоре мы одержим победу над Ордой!", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +398"},
[8384] = {title = "Завоевание Низины Арати", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +82"},
[8385] = {title = "В едином порыве", objective = "А, Хлуси. Я надеюсь, что ты еще не раз вступишь в бой на разных полях битвы. Многие юноши и девушки стараются подражать закаленным бойцам вроде тебя.", description = nil, progress = "А, Хлуси. Я надеюсь, что ты еще не раз вступишь в бой на разных полях битвы. Многие юноши и девушки стараются подражать закаленным бойцам вроде тебя.", completion = "Не зря о тебе так много говорят в последнее время, Хлуси. Не будь в рядах Альянса таких, как ты, нам бы не выстоять против жестоких бойцов Орды.", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +2388"},
[8386] = {title = "Битва за Ущелье Песни Войны", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +50"},
[8387] = {title = "Вторжение в Альтеракскую долину", objective = "Битва за Альтерак продолжается! Возвращайся в Альтеракскую долину и выгони наглых захватчиков с исконных земель клана Северного Волка, Ксаер!", description = nil, progress = "Битва за Альтерак продолжается! Возвращайся в Альтеракскую долину и выгони наглых захватчиков с исконных земель клана Северного Волка, Ксаер!", completion = "Отличная работа, Ксаер! Тебе есть, чем гордиться. Еще немного, и мы вышвырнем Альянс из Альтерака!", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +398"},
[8388] = {title = "Великая честь", objective = "Многие храбрые воины стараются брать с тебя пример, бросаясь в бой против Альянса. Что нового тебе встретилось в странствиях?", description = nil, progress = "Многие храбрые воины стараются брать с тебя пример, бросаясь в бой против Альянса. Что нового тебе встретилось в странствиях?", completion = "Твоих подвигов во имя Орды не счесть. Приятно видеть, что твой дух по-прежнему крепок.", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +2388\n\nВы получите:\n\n"},
[8389] = {title = "Битва за Ущелье Песни Войны", objective = "Битва в Ущелье Песни Войны идет, не прекращаясь. Внеси свой вклад в изгнание часовых из клана Среброкрылых с наших земель!", description = nil, progress = "Битва в Ущелье Песни Войны идет, не прекращаясь. Внеси свой вклад в изгнание часовых из клана Среброкрылых с наших земель!", completion = "Молодчина, |3-6(Друид)! Благодаря тебе и таким как ты Орда вернет себе Ущелье Песни Войны!", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +50"},
