[8435] = {title = "Битва за Ущелье Песни Войны", objective = "Битва в Ущелье Песни Войны идет, не прекращаясь. Внеси свой вклад в изгнание Среброкрылых Часовых из наших земель!", description = nil, progress = "Битва в Ущелье Песни Войны идет, не прекращаясь. Внеси свой вклад в изгнание Среброкрылых Часовых из наших земель!", completion = "Молодчина, |3-6(Маг)! Благодаря тебе и таким как ты Орда вернет себе Ущелье Песни Войны!", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +398"},
[8436] = {title = "Завоевание Низины Арати", objective = "Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.", description = "Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.\n\nВ Низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, <имя>!", progress = "Какие вести из Низины Арати, |3-6(Разбойник)?", completion = "Контроль над ресурсами Низины Арати - важнейшее дело! Ты молодец, Шишгарип.", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +138\n\nВы получите:\n\n"},
[8437] = {title = "Завоевание Низины Арати", objective = "Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.", description = "Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.\n\nВ Низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, <имя>!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +228\n\nВы получите:\n\n"},
[8438] = {title = "Завоевание Низины Арати", objective = "Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.", description = "Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.\n\nВ Низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, <имя>!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +378\n\nВы получите:\n\n"},
[8439] = {title = "Завоевание Низины Арати", objective = "Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.", description = "Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.\n\nВ Низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, <имя>!", progress = "Какие вести из Низины Арати, |3-6(Охотник)?", completion = "Контроль над ресурсами Низины Арати - важнейшее дело! Ты молодец, Дулозалепи.", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +398\n\nВы получите:\n\n"},
[8440] = {title = "Завоевание Низины Арати", objective = "Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине битвы. Низина Арати должна отойти к нам!", description = nil, progress = "Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине битвы. Низина Арати должна отойти к нам!", completion = "Отличная работа, Сенжин! Пока Низина Арати в наших руках, припасов нам хватит.", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +138"},
[8441] = {title = "Завоевание Низины Арати", objective = "Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине сражения. Низина Арати должна отойти к нам!", description = nil, progress = "Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине сражения. Низина Арати должна отойти к нам!", completion = "Отличная работа, Сенжин! Пока Низина Арати в наших руках, припасов нам хватит.", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +228"},
[8442] = {title = "Завоевание Низины Арати", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +378"},
[8443] = {title = "Завоевание Низины Арати", objective = "Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине битвы. Низина Арати должна отойти к нам!", description = nil, progress = "Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине битвы. Низина Арати должна отойти к нам!", completion = "Отличная работа, Дэдоутсайд! Пока Низина Арати в наших руках, припасов нам хватит.", rewards = "Следующее заклинание будет наложено на вас:\n\nОчки чести +398"},
[8446] = {title = "Под покровом кошмара", objective = "Найдите того, кто сможет осознать значение поглощенного кошмарами предмета.\n\nМожет быть, вам сможет помочь могущественный друид.", description = "Эта вещь так и сочится порчей.\n\nМожет быть, существует связь между ней и драконами, вылетающими из Сна. Кто-то должен разобраться, что делать с этой штукой. Может, тебе обратиться к друидам Лунной поляны или крепости Кенария?", progress = "Да, |3-6(дворф)?", completion = "Я должен очистить этот предмет от скверны. Тогда, быть может, мне удастся понять, почему в последнее время я не могу проникнуть в Сон. Давай.", rewards = "Вы получите:\n\n"},
[8447] = {title = "Пробуждение легенд", objective = "Дождитесь, пока хранитель Ремул из Лунной поляны очистит поглощенный кошмарами предмет.", description = "Воды озера Элуны смоют кошмары, поглотившие этот предмет. Это займет совсем немного времени. Подожди, <имя>.", progress = nil, completion = "Возьми это кольцо, Эффект. Оно помогло Малфуриону, а теперь поможет тебе...", rewards = "Вы получите:\n\nПерстень-печатка Малфуриона"},
[8460] = {title = "Союзник Древобрюхов", objective = "Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 6 воинов, 6 землепроходцев и 6 садовников из племени Мертвого Леса. Выполнив поручение, возвращайтесь в южную часть Оскверненного леса к Изумрудному святилищу.", description = "Фурболги Древобрюхов – единственное фурболгское племя, не затронутое порчей. Однако, нынче многие расы без разбору убивают всех фурболгов подряд. И потому фурболгов Древобрюхов осталось так мало.\n\nХочешь заслужить доверие? Изгони из Оскверненного леса пораженных порчей фурболгов Мертвого Леса, и в один прекрасный день мы признаем тебя <союзником/союзницей>. Ты найдешь первое племя Мертвого Леса – воинов, следопытов и садовников – к западу от меня.", progress = "Запомни, Канц. Если хочешь заслужить наше доверие, прояви себя.", completion = "Мы сильно страдаем от того, что случилось в прошлом. Спасибо за все, что ты сделал для защиты Древобрюхов. И в знак начала нашей дружбы, прими этот скромный подарок.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖилет ЗемлестражаПояс стража логова\n\nВы также получите:\n\n"},
[8461] = {title = "Северные фурболги Мертвого Леса", objective = "Нафиэн просит вас убить 6 дозорных, 6 мстителей и 6 шаманов из племени Мертвого Леса. По выполнении возвращайтесь на север Оскверненного леса ко входу в крепость Древобрюхов.", description = "Прямо на юго-западе отсюда расположен лагерь фурболгов Мертвого Леса. В лагере царствует порча, и я хочу положить этому конец прежде, чем эти фурболги стали настоящей угрозой.\n\nПлемя Мертвого Леса злобное, но это все действие скверны, поразившей их разум. Они враждебны не от природы, но тут уж ничего не поделать. Мне невыносимо тяжело сражаться против собратьев.\n\nПрошу тебя, <имя>, делай, что должно, но не рассказывай мне подробностей – у меня и без того сердце разрывается.", progress = nil, completion = "Чую, что ты вернулся с победой. Победа... какое пустое слово, если подумать о том, что еще надо сделать. Как бы то ни было, ты доказал, что достоин нашего доверия.\n\nНе сразу фурболги Крепости Древобрюхов начнут относиться к тебе без враждебности в этой берлоге. Но твое упорство пробьет стену любой подозрительности, которую мои братья могут питать к тебе. Пока ты не предашь нас и не поднимешь на нас оружия, мы будем находить общий язык.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПоножи фурболгаШлем землепроходца\n\nВы также получите:\n\n"},
[8462] = {title = "Беседа с Нафиэном", objective = "Отправляйтесь на север по главной дороге в Оскверненном лесу и поговорите с фурболгом по имени Нафиэн. Он стоит на страже у входа в крепость Древобрюхов.", description = "Кто знает, может ты справишься с еще более страшной угрозой, что нынче нависла над нами, кланом Древобрюхов. Ты уже <сумел/сумела> показать здесь свою доблесть...\n\nЕще один мой сородич стоит на страже у входа в Крепость Древобрюхов, по этой дороге дальше к северу. Его зовут Нафиэн. Он может показаться тебе злобной грязной тварью, но ты его не бойся. Он всего лишь ищет помощи против злых сил, что угрожают нашему дому.", progress = nil, completion = "Ага... ветер принес мне весть о чужаке не из нашего племени, который ищет союза с фурболгами Крепости Древобрюхов. Добро пожаловать – но знай, мое племя не доверяет чужакам.\n\nВремена сейчас смутные, и мы можем доверять только тем, кто вместе с нами сражается с осквернителями наших краев... тем, кто доказал нам свою верность. А те, кому мы не доверяем, встретят откровенную враждебность, как только войдут в крепость.", rewards = "Вы получите:\n\n"},
[8463] = {title = "Нестабильные кристаллы маны", objective = "Верните 6 нестабильных кристаллов маны Аэльдону Озаренному Солнцем на площади Соколиных Крыльев.", description = "Шайка Презренных не так давно похитила из одного из наших волшебных святилищ запас нестабильных кристаллов маны. А эти кристаллы при неправильном обращении могут взрываться с такой силой, что ее хватит, чтобы проломить городскую стену!\n\nТак вот, <имя>, меня не волнует, если эти кристаллы взорвутся у них – пусть хоть все повзрываются, – но этот инцидент выставляет моих подчиненных не в лучшем свете!\n\nПринеси мне все оставшиеся похищенные кристаллы, сколько найдешь – возможно, они даже до сих пор не распакованы.", progress = "Ну что, удалось тебе отыскать похищенное?", completion = "Прекрасно, Адраан!", rewards = "Вы получите:\n\n"},
[8464] = {title = "Боевые действия в деревне Зимней Спячки", objective = "Убейте 8 шаманов, 8 дозорных и 8 ведмедей из племени Зимней Спячки по просьбе Сальфы. Он ждет у входа в Крепость Древобрюхов в Зимних Ключах.", description = "Клан Древобрюхов готов постоять за себя, <имя>. В то время как мы позволяем свободно ходить среди нас тем, кому мы доверяем, мы стараемся по возможности избегать общения с другими племенами фурболгов. \n\nПлемя Зимней Спячки в последнее время становится все более враждебным к нам. Они, похоже, впали в состояние ярости, всецело поглощенные собственным страхом и ненавистью ко всему, чего они не понимают. \n\nЯ вынужден просить вас пробить брешь в их рядах для уменьшения угрозы для нас. Ищите их в деревне Зимней Спячки далеко на восток отсюда.", progress = nil, completion = "Спасибо за то, что вы сделали, как ни печально все это. Примите это в качестве знака нашей благодарности. \n\nЯ бы очень просил вас не прекращать оказывать нам помощь, Томпсон. У нас слишком мало союзников, которых мы можем призвать, и без вашей помощи опасность для моего племени была бы слишком велика, чтобы мы могли справиться с нею в одиночку.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки ЗемлестражаПерчатки землепроходцаЖилет Стража логоваМедвежье облачение\n\nВы также получите:\n\n"},
[8465] = {title = "Разговор с Сальфой", objective = "Пройдите через Крепость Древобрюхов и выйдите к Зимним Ключам. Поговорите с Сальфой, который стоит на страже у входа в Крепость Древобрюхов.", description = "Порча расползается не только от фурболгов Мертвого Леса с юга, но и с востока, от фурболгов из племени Зимней Спячки, что в Зимних Ключах. Если хочешь еще нам помочь, поговори с Сальфой по другую сторону берлоги, у входа в Зимние Ключи. Иди туда по левой тропке.\n\nОсторожнее – если мои тамошние сородичи сочтут, что ты – недобрый гость или ненавистный враг, они на тебя нападут. Иди так быстро, как можешь, чтобы избежать стычки. Убьешь кого из Древобрюхов, пусть даже защищаясь – вызовешь еще большую враждебность.", progress = nil, completion = "Привет тебе, |3-6(Охотник) – я тут и страж, и глашатай Древобрюхов в Зимних Ключах, и защитник моего племени.\n\nНаши сородичи из племени Зимней Спячки в этой холодной земле подпали под ту же власть порчи, что и фурболги Оскверненного леса. Если ты пришел помочь фурболгам из крепости Древобрюхов, то мы рады принять твое предложение.", rewards = "Вы получите:\n\n"},
[8466] = {title = "Перья для Гразла", objective = "Хотя я уже тебе доверяю, заслужить доверие моих подозрительных соплеменников тебе еще только предстоит. Тут я смогу тебе помочь.\n\nУ некоторых фурболгов Мертвого Леса есть характерные головные уборы, которые могут послужить доказательством уменьшения их числа. Приноси мне перья из всех головных уборов, какие только сможешь добыть, и с каждыми очередными пятью штуками доверие к тебе в племени Древобрюхов будет возрастать.", description = nil, progress = "Хотя я уже тебе доверяю, заслужить доверие моих подозрительных соплеменников тебе еще только предстоит. Тут я смогу тебе помочь.\n\nУ некоторых фурболгов Мертвого Леса есть характерные головные уборы, которые могут послужить доказательством уменьшения их числа. Приноси мне перья из всех головных уборов, какие только сможешь добыть, и с каждыми очередными пятью штуками доверие к тебе в племени Древобрюхов будет возрастать.", completion = "Хорошая работа, Тиотенши! Я уж постараюсь, чтобы мои сородичи узнали о твоих делах.\n\nНе забывай приносить мне все перья, что добудешь. Я возьму все, сколько принесешь.", rewards = nil},
[8467] = {title = "Перья для Нафиэна", objective = "Хотя я уже тебе доверяю, заслужить доверие моих соплеменников тебе еще только предстоит. Тут я смогу тебе помочь.\n\nУ некоторых фурболгов Мертвого Леса есть характерные головные уборы, которые могут послужить доказательством уменьшения их числа. Приноси мне перья из всех головных уборов, какие только сможешь добыть, и с каждыми очередными пятью штуками доверие к тебе в племени Древобрюхов будет возрастать.", description = nil, progress = "Хотя я уже тебе доверяю, заслужить доверие моих соплеменников тебе еще только предстоит. Тут я смогу тебе помочь.\n\nУ некоторых фурболгов Мертвого Леса есть характерные головные уборы, которые могут послужить доказательством уменьшения их числа. Приноси мне перья из всех головных уборов, какие только сможешь добыть, и с каждыми очередными пятью штуками доверие к тебе в племени Древобрюхов будет возрастать.", completion = "Хорошая работа, Драккард! Я уж постараюсь, чтобы мои сородичи узнали о твоих делах.\n\nНе забывай приносить мне все перья, что добудешь. Я возьму все, сколько принесешь.", rewards = nil},
[8468] = {title = "РАЗЫСКИВАЕТСЯ: Таэлис Ненасытный", objective = "Принесите голову Таэлиса сержанту Ка'рену на площадь Соколиных Крыльев в лесах Вечной Песни.", description = "Город Луносвет назначает награду за голову Таэлиса Ненасытного, известного главаря Презренных. Он разыскивается за то, что неоднократно совершал преступления против жителей Луносвета, в том числе убил двух городских стражников.\n\nОтносительно награды обращайтесь к сержанту Ка'рену.", progress = "Ты хочешь мне что-то показать?", completion = "Наконец-то этот негодяй, Таэлис, получил по заслугам! Молодец, Адраан. Теперь-то Презренные присмиреют хотя бы на время!", rewards = "Вы получите:\n\n"},
[8469] = {title = "Бусы для Сальфы", objective = "Ты заслужил мое доверие Орканавт, теперь осталось проделать то же самое с моим крайне недоверчивым племенем. Для этого придется потрудиться.\n\nПлемя Зимней Спячки, как известно, носит особые бусы, чтобы защищаться от злых духов. Бусы не оправдали свое предназначение, поскольку все племя подверглось порче. Принеси мне бусы, которые носят падшие фурболги. Твой авторитет в племени будет расти с каждыми принесенными бусами.", description = nil, progress = "Ты заслужил мое доверие Орканавт, теперь осталось проделать то же самое с моим крайне недоверчивым племенем. Для этого придется потрудиться.\n\nПлемя Зимней Спячки, как известно, носит особые бусы, чтобы защищаться от злых духов. Бусы не оправдали свое предназначение, поскольку все племя подверглось порче. Принеси мне бусы, которые носят падшие фурболги. Твой авторитет в племени будет расти с каждыми принесенными бусами.", completion = "Ты снова доказал свою доблесть! Я позабочусь о том, чтобы о твоих деяниях узнало все наше племя.\n\nНе забывай приносить мне бусы Зимней Спячки. О каждом твоем успехе я расскажу своим сородичам.", rewards = nil},
[8470] = {title = "Ритуальный тотем Мертвого Леса", objective = "Отнесите ритуальный тотем Мертвого Леса в Крепость Древобрюхов и посмотрите, не пригодится ли этот предмет кому из тамошних фурболгов. Фурболги Крепости Древобрюхов не станут говорить с вами – разве что их отношение к вам нейтральное или лучше.", description = "Вы нашли один из ритуальных тотемов фурболгов клана Мертвого Леса. Сам тотем совершенно неописуемой конструкции, и от него исходит ощутимое чувство отчаяния. Если есть предмет, который мог бы стать олицетворением порчи, снедающей фурболгов Мертвого Леса – то вот он.\n\nОдин из фурболгов в крепости Древобрюхов мог бы найти применение этому предмету... конечно, если вы уже добились достаточного доверия от них, чтобы они снизошли до разговора с вами.", progress = "Да, |3-6(Охотник), чем могу тебе помочь? Ты ходишь среди нас беспечно, хотя это не слишком-то правильно. Я чую что-то... что-то тревожное...", completion = "Тотем... похоже, один из мертволесских, но от него прямо несет разложением. В этом предмете явственно ощущается то, что обратило наших собратьев против нас.\n\nТы мудро поступил, принеся его нам, Томпсон. Возможно, изучив его и проведя обряды, мы сможем узнать, что отравило разум наших сородичей. Благодарю тебя, друг, – прими эти дары в благодарность за твою находку.", rewards = "Вы получите:\n\nСильнейшее лечебное зельеСильнейшее зелье маны"},
[8471] = {title = "Ритуальный тотем Зимней Спячки", objective = "Отнесите ритуальный тотем Зимней Спячки в берлогу Древобрюхов и отдайте его фурболгу, который им заинтересуется. Никто из племени Древобрюхов не заговорит с вами, пока вы не завоюете себе среди них достойную репутацию.", description = "Вы нашли один из ритуальных тотемов Зимней Спячки. Сам тотем представляет собой неописуемую конструкцию, которая испускает почти осязаемые волны страха и отчаяния. Если такую вещь носят все фурболги, то понятно, что довело их до такого состояния.\n\nКто-нибудь из фурболгов логова Древобрюхов наверняка разберется с этой вещью... однако фурболги будут говорить только с теми, кому достаточно доверяют.", progress = "Охотник – ты пришел к нам с миром, но я вижу, что у тебя очень важная цель. Важная не только для фурболгов, но и для твоих соплеменников, |3-6(орк). О чем ты хочешь нам поведать?", completion = "Эта вещь... она имеет форму ритуального тотема Зимней Спячки, однако этот тотем был испорчен непостижимыми для меня силами. Так или иначе, в нем присутсвует именно та энергия, которая заставила племя Зимней Спячки обратиться против нас.\n\nС твоей стороны было очень мудро принести его нам, Томпсон. Мы тщательно его изучим и, будем надеяться, найдем способ исцелить наших собратьев.\n\nМы благодарны тебе, и просим тебя принять это за твои услуги.", rewards = "Вы получите:\n\nСильнейшее лечебное зельеСильнейшее зелье маны"},
[8472] = {title = "Серьезная неполадка", objective = "Соберите 6 волшебных сердечников с волшебных часовых, которые бродят по руинам Луносвета, и принесите их магистру Джаронису на площадь Соколиных Крыльев в лесах Вечной Песни.", description = "Волшебные часовые, которых наши предки изготовили, чтобы охранять город, в последнее время пришли в полную негодность. Они уже не признают в нас своих хозяев и нападают, как только увидят!\n\nОни созданы много лет назад, но волшебные сердечники, на которых они работают, все еще вполне пригодны. Собери эти сердечники и принеси мне, чтобы я мог пустить их в дело. Часовые бродят по разрушенным кварталам Луносвета, на северо-западе.", progress = "Ну что, Адраан, удалось тебе собрать волшебные сердечники?", completion = "Молодец, Адраан! Теперь, когда наши волшебные святилища не работают в полную силу, эти энергетические сердечники очень сильно поспособствуют решению наших проблем.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #23367Предмет #24241Предмет #27552Предмет #131237\n\nВы также получите:\n\n"},
[8473] = {title = "Печальное задание", objective = "Убейте 10 высохших хранителей лесов в Выжженной роще. Вернитесь к Ларанне Речной Ветер в башне к северо-западу от Выжженной рощи в лесах Вечной Песни.", description = "Трудные ныне времена, <имя>. Нам очень не хотелось сжигать леса вдоль границы Призрачных земель, но иначе никак не удавалось предотвратить распространение Плети.\n\nИ вот теперь древни, которые в течение многих лет были нашими друзьями, пытаются восстановить леса вдоль Выжженной рощи.\n\nНам так и не удалось убедить наших бывших союзников прекратить эти попытки. Мне очень горько тебя об этом просить, <класс>, но тебе придется пустить в ход единственное оставшееся у нас средство – силу.", progress = nil, completion = "Значит, дело сделано... Будь прокляты эти времена, вынудившие нас пойти на крайние меры... и будь проклята Плеть!\n\nЗапомни, Дзйрт: мы должны защищать свои земли во что бы то ни стало! И мы победим!", rewards = "Вы получите:\n\n"},
[8474] = {title = "Подвеска Старого Белоствола", objective = "Отыщите того, кто мог изготовить подвеску Старого Белоствола. Возможно, он подскажет, что это за предмет?", description = "На подвеске выгравированы инициалы: ЛРВ. Возможно, они помогут вам найти создателя подвески...", progress = "Ты хочешь мне что-то показать?", completion = "О-о... эта подвеска... Я подарила ее Старому Белостволу, после того как его народ помог нам отстроить нашу деревню.\n\nБоюсь, это означает, что он…\n\n*Эльфийка откашливается и берет себя в руки.*\n\nСпасибо, что принес мне эту вещь, Дзйрт. Я хотела бы попросить тебя об одной услуге...", rewards = "Вы получите:\n\n"},
[8475] = {title = "Тропа Мертвых", objective = "Убейте 8 чумных мародеров и вернитесь к следопыту Джеле на Тропе Мертвых в лесах Вечной Песни.", description = "Полоса выжженной земли, которая тянется через леса Вечной Песни, служит напоминанием о том дне, когда Артас привел Плеть в наш город...\n\nЭто хуже, чем бельмо на глазу: даже теперь по ней в Луносвет приходят прислужники Плети из Призрачных земель.\n\nСтупай, <имя>, и помоги моим воинам убивать лишенную разума нежить, которая приходит Тропой Мертвых.", progress = nil, completion = "Разумеется, Плеть еще нескоро отступится от нас, но все же оборонять тропу Мертвых необходимо, и мы ценим любую помощь!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #23375Предмет #23376Предмет #23377Предмет #131238\n\nВы также получите:\n\n"},
[8476] = {title = "Угроза Амани", objective = "Убейте 5 аманийских берсерков и 5 аманийских метателей топоров по просьбе лейтенанта Вестницы Зари из обители Странников, что в лесах Вечной Песни.", description = "Наши владения – это не обширные королевства людей или орков. То, что ты видишь перед собой, <имя>, – это, считай, и есть все земли, что принадлежат нам в Азероте.\n\nИ пока мы не сумеем добраться до Запределья, мы должны любой ценой защищать то немногое, что имеем.\n\nОднако у наших нецивилизованных соседей на юго-востоке, троллей из племени Амани, явно имеется свое мнение насчет того, кому принадлежат эти земли. Мы больше не можем терпеть их непрекращающиеся набеги! Отправляйся в их поселения, Зеб'Вату и Тор'Вату, и преподай им урок!", progress = nil, completion = "Спасибо, Дзйрт! Чем больше у нас будет таких бойцов, как ты, тем быстрее мы вернем нашим землям прежнее великолепие.", rewards = "Вы получите:\n\n"},
[8477] = {title = "Молот копьедела", objective = "Найдите в Тор'Вате к юго-востоку от обители Странников копьедела Отембе и принесите его молот Аратель Кузне Солнца в обитель Странников, что в лесах Вечной Песни.", description = "Между племенем троллей Амани и син'дорай существует многовековая неприязнь и открытая вражда. Однако же это не мешает мне оценить работу коллеги-оружейника, <имя>.\n\nМне уже попадались изделия троллей из племени Амани, и должна признаться, что это очень качественные вещи. Ходят слухи, что копьедел Отембе владеет волшебным молотом, таким легким и хорошо сбалансированным, что он позволяет работать очень ловко и эффективно.\n\nЕсли ты принесешь мне этот инструмент, я сделаю тебе оружие.", progress = "Ну что, Дзйрт, ты принес мне молот Отембе?", completion = "Да, Дзйрт, слухи не лгали! Этот молот – легкий, и в то же время мощный. Теперь я смогу завершить несколько начатых и не оконченных мною вещей! И, разумеется, первая же из них – твоя!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #22958Предмет #22959Предмет #22963\n\nВы также получите:\n\n"},
[8478] = {title = "Выбор оружия", objective = "Вы получите:\n\n", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8479] = {title = "Зул'Марош", objective = "Принесите Вень'яши, пленному троллю в Тор'Вате, голову вождя Зул'Мароша. Вождя можно найти в Зеб'Вате, за озером Элрендар.", description = "Поди-ка поближе. Да не боись, не укусит тебя Вень'яши!\n\nМы, тролли из племени Черного Копья – смертельные враги Амани, как и ваш народ. Их старшой, Зул'Марош – очень злой тролль. Он отравил меня и оставил подыхать в этой клетке.\n\nСмерти я не боюсь, нет. Я смотрел смерти в глаза, и смеюсь над нею!\n\nНо я не смогу умереть спокойно. Пусть Зул'Марош тоже умрет! Он там, за озером, в Зеб'Вате. Я буду сопротивляться яду, пока ты не принесешь мне его башку!", progress = "Принес ли ты голову Зул'Мароша?", completion = "О да! Наконец-то Зул'Марош получил по заслугам! Он сжег деревню Вень'яши. Я убил много Амани, прежде чем меня затолкали в эту клетку! Я спрятал кое-что в песке – это будет мой дар тебе.\n\nОх... яд расходится по жилам... Пора мне помирать...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #22969Предмет #22971\n\nВы также получите:\n\n"},
[8480] = {title = "Потерянное оружие", objective = "Принесите 8 комплектов оружия син'дорай Велендрису Белому Рассвету в лесах Вечной Песни.", description = "Презренные наглеют с каждым днем, <имя>! Они уже расхрабрились настолько, что захватили причал Солнечного Паруса!\n\nА что самое неприятное – когда нас атаковали, нам пришлось бросить большую часть нашего оружия. Верни его, чтобы мы смогли показать этим подонкам, кто здесь хозяин!", progress = "Ну что, тебе удалось собрать потерянное оружие?", completion = "Отлично, Дзйрт! Теперь мы зададим жару этим Презренным!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #22956Предмет #22957Предмет #133696\n\nВы также получите:\n\n"},
[8481] = {title = "Корень всех зол", objective = "Установите факел призыва демона у входа в пещеру верховного вождя племени Зимней Спячки в деревне фурболгов Зимней Спячки. Сразите демона и добудьте сущность Зандивиуса для Горна Одноглаза из Крепости Древобрюхов.", description = "<имя>, спасибо тебе за то, что <нашел/нашла> способ вырвать корень зла из душ племени Зимней Спячки – уничтожить демона, овладевшего ими!\n\nОтнеси этот факел к входу в пещеру верховного вождя племени Зимней Спячки и поставь его там. Это заставит демона появиться. Вот тогда ты со своими союзниками нападешь на него! Только сущность погибшего демона поможет начать долгий процесс исцеления племени Зимней Спячки... и спасения Крепости Древобрюхов.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЗащита Древобрюхов"},
[8482] = {title = "Обличающие документы", objective = "Отнесите обличающие документы Аэльдону Озаренному Солнцем на площадь Соколиных Крыльев в лесах Вечной Песни.", description = "В документах содержатся подробные карты стратегически важных объектов в лесах Вечной Песни. Прилагается также план волшебного святилища. Кроме того, присутствует множество заметок на неизвестном вам языке.\n\nПоскольку все эти документы вы нашли у дарнасского шпиона, пожалуй, стоит отнести их капитану стражи – Аэльдону Озаренному Солнцем.", progress = "Ты мне что-то принес? Дай-ка взглянуть...", completion = "Все это было у ночного эльфа? Точно? Язык-то явно дворфийский…\n\nНасколько я понимаю из письма, тот, кто его написал, не сам устроил аварию, но был прислан сюда, чтобы понаблюдать за ее результатами. Тут сказано, что наши усилия опасны и безрассудны... но вот кто это был?\n\nНу разумеется! Тот посланец из Стальгорна! Не глупо ли было доверяться тому, кто принадлежит к Альянсу?", rewards = "Вы получите:\n\n"},
[8483] = {title = "Дворфийский шпион", objective = "Принесите голову геолога Стража Наковальни Аэльдону Озаренному Солнцем на площадь Соколиных Крыльев в лесах Вечной Песни.", description = "Слушай, <имя>. Ситуация очень деликатная. Мы вычислили шпиона, но убить его открыто не можем. Не можем мы и попытаться его схватить – слишком велик риск, что уйдет.\n\nПрошу тебя: пойди в Северное святилище, найди там геолога Стража Наковальни и убей его. Только тихо: мы не хотим, чтобы пошли разговоры, что мы допустили в свой город шпиона.\n\nПринеси мне в доказательство его голову. Пусть стальгорнцы знают, что к син'дорай соваться опасно.", progress = "Ну что, удалось тебе разобраться с этим прохвостом?", completion = "Ага, дело сделано! Прекрасно.\n\nПредводителю следопытов уже обо всем сообщили – поверь мне, дворфы дорого заплатят за предательство.\n\nСегодня ты оказал большую услугу своему народу, Адраан!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #23372Предмет #23373Предмет #133695\n\nВы также получите:\n\n"},
[8484] = {title = "Знак мира", objective = "Отнесите мирное приношение Древобрюхов королю Магни Бронзобороду в Стальгорн.", description = "Твои подвиги выше любых похвал, <имя>. И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир.\n\nПрошу – отнеси этот дар королю дворфов, что живет в железной горе – вроде бы вы зовете этот город Стальгорном. В былые времена он пытался заключить с нами союз от имени Альянса. Так что теперь достойно будет, чтобы ты <завершил/завершила> труды Альянса по установлению мира с нами.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nАльянс - отношение\n\nВы получите:\n\n"},
[8485] = {title = "Знак мира", objective = "Отнесите мирное приношение Древобрюхов Траллу в Оргриммар.", description = "Твои подвиги выше любых похвал, <имя>. И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир.\n\nПрошу – отнеси этот дар вождю орков, что живет в Дуротаре. Кажется, вы называете его город Оргриммаром. В былые времена он пытался заключить с нами союз от имени Орды. Так что теперь достойно будет, чтобы ты <завершил/завершила> труды Орды по установлению мира с нами.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nОтношение Орды\n\nВы получите:\n\n"},
[8486] = {title = "Магическая нестабильность", objective = "Убейте 5 магических призраков и 5 волшебных охотников по просьбе хранительницы энергии Велании.", description = "Ну наконец-то этот олух Кайданис прислал хоть кого-то!\n\nЯ предупреждала о том, как опасно перегружать Западное святилище! И вот теперь один из энергетических конвертеров уничтожен, а из святилища лезут чародейские призраки!\n\nМне нужна твоя помощь, чтобы разобраться с этими существами, прежде чем мы отправим туда ремонтников. Времени в обрез!", progress = nil, completion = "Спасибо, Адраан. Теперь, когда ситуация под контролем, можно отправить туда рабочих и все наладить. Надеюсь, там ничего серьезного...", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #23370Предмет #23371\n\nВы также получите:\n\n"},
[8487] = {title = "Зараженная почва", objective = "Соберите 8 проб зараженной земли для ученицы Мирведы в Восточном святилище, что в лесах Вечной Песни.", description = "Пока Артас и его армия Плети не проложили здесь свой гибельный путь к Луносвету, это было действующее волшебное святилище.\n\nА теперь от него не больше проку, чем от любой другой части Тропы Мертвых. Почва заражена, это место кишит нежитью, энергия силовых линий полностью искажена.\n\nИ теперь я хочу знать, <имя>, обратимо ли это искажение или нет. Собери образцы почвы, чтобы я могла изучить их. Возможно, со временем мы сумеем все исправить?", progress = "Ну что, Дзйрт, ты собрал образцы, которые я просила?", completion = "Отлично! Я обработаю эти образцы заклятием усиления, чтобы мне было удобнее исследовать порчу.", rewards = "Вы получите:\n\n"},
[8488] = {title = "Неожиданный результат", objective = "Поговорите с ученицей Мирведой и защитите ее от нападения Плети.", description = "Что-то не так, <имя>. Я чувствую присутствие Плети! Готовься сражаться!", progress = "Ну что, все? Они разбежались?", completion = "Нет, Дзйрт, все мои надежды тщетны... Сама природа здешней почвы изменилась. Спасибо тебе за помощь. Напоследок окажи мне, пожалуйста, еще одну услугу.", rewards = "Вы получите:\n\n"},
[8489] = {title = "Невредимый преобразователь", objective = "Принесите хранительнице энергии Велании невредимый чародейский преобразователь.Кажется, перед вами один из чародейских преобразователей, о которых говорила хранительница энергии Велания. Огонь его не коснулся, так что он может ей пригодиться.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", description = "Кажется, перед вами один из чародейских преобразователей, о которых говорила хранительница энергии Велания. Огонь его не коснулся, так что он может ей пригодиться.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8490] = {title = "Усиление обороны", objective = "Установите заряженный кристалл рядом с восточным руническим камнем и в течение одной минуты обороняйте его от нежити. Затем верните кристалл хранителю рун Дериану в лесах Вечной Песни и получите награду.", description = "Некогда древние рунические камни поддерживали защитный барьер вдоль границ лесов Вечной Песни. Многие из них были уничтожены во время нападения Артаса, а некоторые были похищены.\n\nИз трех оставшихся лишь один сохранил прежнюю мощь. Но возможно, тот рунический камень, что на востоке, тоже можно спасти.\n\nВот, возьми этот кристалл и влей его энергию в восточный рунический камень. Это займет не более минуты. Однако берегись: находящиеся поблизости твари Плети попытаются уничтожить камень. Этого нельзя допустить!", progress = "Ну что, Дзйрт, тебе удалось зарядить рунный камень?", completion = "Отлично! Значит, наша оборона продержится еще немного. Спасибо тебе за помощь, Дзйрт!", rewards = "Вы получите:\n\n"},
[8491] = {title = "Добывание шкур", objective = "Принесите 6 шкур прыголапов Велану Светлому Тополю из деревни Легкий Ветерок, что в лесах Вечной Песни.", description = "Прыголапы, которые водятся в здешних краях, славятся своими превосходными шкурами. Порой даже эти мошенники, ночные эльфы, забредают к нам, чтобы побраконьерствовать.\n\nИз-за стычек с троллями из племени Амани все наши припасы иссякли, и нашим следопытам не до охоты. Если ты согласишься помочь нам добыть шкуры прыголапов, я вознагражу тебя надежными доспехами. Прыголапов-охотников легко встретить в лесах к северу отсюда.", progress = "О, ты уже здесь! А где шкуры?", completion = "Отлично, Дзйрт! Вот, возьми в награду эти доспехи. Кстати, ты принес столько шкур, что их хватит на что-нибудь еще.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПредмет #22951Предмет #22952Предмет #22953Предмет #131239\n\nВы также получите:\n\n"},
[8492] = {title = "Альянсу не хватает медных слитков!", objective = "Принесите 20 медных слитков сержанту Каменлобу в Военный Двор Стальгорна.", description = "Здорово, <класс>! На вид ты вполне <пригоден/пригодна> к тому, чтобы принять участие в подготовке к войне! Нам пригодится любая помощь, так что наступил твой звездный час.\n\nЯ собираю медные слитки стопками по двадцать штук. Дело благое, да? Ты как, хочешь оказать помощь Альянсу?", progress = "Ну что, солдат, удалось собрать 20 медных слитков?", completion = "Похвально, солдат! Сейчас мы уложим эти слитки в штабель и используем их по назначению. Альянс будет гордиться тобой. \n\nЕсли раздобудешь еще стопку медных слитков, не раздумывай, неси мне.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8493] = {title = "Альянсу все еще не хватает медных слитков!", objective = "Принесите 20 медных слитков сержанту Каменлобу в Военный двор Стальгорна.", description = "Ты <вернулся/вернулась>, <класс>? Превосходно! Для подготовки к войне в Ан'Кираже все еще нужны медные слитки. Ты поможешь нам собрать их?", progress = "Ты уже вернулся, |3-6(Друид)? Превосходно! Слитки, которые тебе удалось достать, сослужат нам добрую службу. Я могу сказать со всей ответственностью, что медь пойдет на изготовление паровых танков, а так же вертолетов и прочей военной техники.\n\nИ пусть эти штабеля меди не смущают твой взгляд, к сожалению, их пока недостаточно, чтобы подготовится к войне в Ан'Кираже как следует. Но ведь мы еще можем рассчитывать на твою помощь?", completion = "Прекрасная работа! Добыча и выплавка всей этой меди, должно быть, была тем еще развлечением. Если, конечно, ты не купил слитки на аукционе. В любом случае, главное – результат. Приложенные тобой усилия не останутся незамеченными, |3-6(Друид). Если раздобудешь еще слитки, без малейшего колебания неси их мне.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8494] = {title = "Альянсу не хватает железных слитков!", objective = "Принесите 20 железных слитков капралу Карнсу в Палаты Войны Стальгорна.", description = "Эгей, <мистер/мисс.> Красивые Штанишки, ты прямо отрада для моих измученных глаз. Пока ты <шатался/шаталась> по городам и весям в поисках приключений, у нас тут произошла прорва всего. К примеру, Альянс вот готовится к войне в Ан'Кираже, и всем резко понадобились железные слитки... чертова прорва железных слитков. Можешь таскать их мне стопками по двадцать. Ну как, могу я на тебя рассчитывать, <класс>?", progress = "Если эти двадцать железных слитков у тебя с собой, даже не рассказывай мне, куда ты умудрился их запрятать.", completion = "Ну хорошо, Лорегон, на этот раз тебе удалось вывернуться. Пожалуй, на будущее за тобой стоит приглядывать. Как ни тяжело это говорить, но спасибо тебе за помощь. Альянс тебя не забудет, и я тоже. А теперь дуй-ка отсюда и лучше помоги еще кому-нибудь в заготовках.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8495] = {title = "Альянсу по-прежнему не хватает железных слитков!", objective = "Принесите 20 железных слитков капралу Карнсу на аэродром в Дун Морог.", description = "Ты опять здесь? Не заставляй меня слишком хорошо о тебе думать, <класс>, а то я прямо таять начинаю. Как видишь, мы еще не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и все остальное-прочее, что нужно изготовить для большой драчки. Я думаю, ты сможешь принести еще слитков двадцать в перерыве между своими шатаниями в Зул'Гуруб, или где там у вас, у молодежи, сейчас модно тусоваться.", progress = "Ты опять здесь? Не заставляй меня слишком хорошо о тебе думать, |3-6(Друид), а то я буквально таю изнутри. Как видишь, мы еще не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и все остальное-прочее, что нужно изготовить для большой драчки. Я думаю, ты сможешь принести еще слитков двадцать в перерыве между своими шатаниями в Зул'Гуруб, или где там у вас, у молодежи, сейчас модно тусоваться.", completion = "Должно быть, в Пылающих Степях выпал снег. Вы только посмотрите, это же Лорегон, да не просто так, а с подарком. Двадцать железных слитков! Именно то, что мне нужно. \n\nХочу сказать тебе со всей серьезностью, Лорегон, Альянс перед тобой в долгу. А теперь давай, шлепай отсюда и помоги еще кому-нибудь в заготовках.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8496] = {title = "Запас бинтов", objective = "Принесите 30 плотных бинтов из рунной ткани, 30 плотных шелковых бинтов и 30 бинтов из магической ткани призывательнице ветров Гордый Рог в крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу X.", description = "В последнее время мы понесли серьезные потери, и запас бинтов стремительно иссякает. Добудь нам первоклассные перевязочные материалы и отнеси их призывательнице ветров Гордый Рог в крепость Кенария.", progress = "Что ты мне принес, Драккард?", completion = "Ты как раз вовремя. Принесенные тобой перевязочные материалы спасут немало жизней. Мы благодарны тебе за труды. Вот твое следующее задание.", rewards = "Вы получите:\n\nКенарийский знак тыловикаДополнительное задание по материально-техническому снабжению"},
[8497] = {title = "Неприкосновенный запас", objective = "Принесите 4 сферы воды, 4 мощных противоядия и 4 копченые пустынные клецки Каландрате в таверну в крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу I.", description = "В крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих неприкосновенных наборов для отправляющихся в пустыню и отнеси их Каландрате в крепость Кенария.", progress = "Что ты мне принес, Лорегон?", completion = "Отлично! Нам очень нужны эти материалы. Спасибо.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"},
[8498] = {title = "Боевые приказы Сумеречного Молота", objective = "Добудьте боевые приказы Сумеречного Молота и отнесите их командиру Мар'алиту в крепость Кенария в Силитусе. Для завершения задания понадобится тактическая задача X.", description = "Разведчики донесли, что от вождей Сумеречного Молота поступили новые приказы. Их распространяют пророки под охраной солдат. Перехвати эти приказы и принеси их командиру Мар'алиту.", progress = "Что ты мне принес, Горрат?", completion = "Великолепно. Главное – опережать противника на ход. Благодаря полученным сведениям, нам известны намерения Сумеречного Молота.", rewards = "Вы получите:\n\nКенарийский знак тактикаТактическое задание"},
[8499] = {title = "Альянсу не хватает ториевых слитков!", objective = "Принесите 20 ториевых слитков госпоже Двукоссе в Палаты Войны Стальгорна.", description = "Крайне любезно с твоей стороны, что ты так беспокоишься о нуждах Альянса. Приготовления к войне идут полным ходом, и, помимо всего прочего, нам нужно очень много ториевых слитков. Именно за их сбор я и отвечаю. Торий необходим для изготовления различных военных машин, в основном паровых танков, которые планируется доставлять по воздуху в Силитус сразу же после сборки. За помощь в добыче ториевых слитков я была бы очень признательна, <класс>.", progress = "Я надеюсь, тебе удалось собрать необходимое количество ториевых слитков?", completion = "О, спасибо тебе, |3-6(Разбойник)! Огромное спасибо! Прибавилось еще двадцать, осталось собрать еще несчетное количество. Альянс пред тобой в долгу. Если раздобудешь еще двадцать слитков, обращайся ко мне.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8500] = {title = "Альянсу по-прежнему не хватает ториевых слитков!", objective = "Принесите 20 ториевых слитков госпоже Двукоссе на аэродром в Дун Морог.", description = "Добро пожаловать снова, <имя>. Надеюсь, у тебя все в порядке? Это правда, нам все еще нужны ториевые слитки. Если сможешь достать их, я буду очень признательна.", progress = "Добро пожаловать снова, Хэллпер. Надеюсь, у тебя все в порядке? Это правда, нам все еще нужны ториевые слитки. Если сможешь достать их, я буду очень признательна.", completion = "Отличная работа, |3-6(Разбойник)! Я прослежу, чтобы ториевые слитки были хорошо упакованы и доставлены кузнецам и инженерам, которые изготавливают для нашей армии военную технику. Спасибо тебе еще раз. Если сможешь достать еще двадцать слитков, я приму их у тебя с благодарностью.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8501] = {title = "Цель: острожалы из улья Аши", objective = "Убейте 30 острожалов из улья Аши и доложите о выполнении задания командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу XII.", description = "По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Аши. Твоей основной целью будут летающие острожалы из этого улья.\n\nВыполнив задание, отчитайся командиру Мар'алиту.", progress = "О чем ты хочешь рассказать, Элисон?", completion = "Отличная работа, Элисон. Твои подвиги в сражении при Улье Аши не прошли незамеченными.", rewards = "Вы получите:\n\nКенарийский знак бойца"},
[8502] = {title = "Цель: рабочие из улья Аши", objective = "Убейте 30 рабочих из улья Аши и доложите о выполнении задания командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу III.", description = "По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на Улей Аши. Твоей основной целью будут рабочие из этого улья.\n\nВыполнив задание, отчитайся командиру Мар'алиту.", progress = "Ты хочешь что-то сказать, |3-6(Воин)?", completion = "Отличная работа, Ренн. Без рабочих силитидам придется нелегко. Кто будет восстанавливать их ульи?", rewards = "Вы получите:\n\nКенарийский знак бойца"},
[8503] = {title = "Альянсу не хватает удавника!", objective = "Принесите 20 стеблей удавника рядовому Драксельмеру в Палаты Войны Стальгорна.", description = "Знаешь ли ты, <класс>, насколько широко и разнообразно применение удавника? Как, я тебе уже об этом рассказывал? Правда?.. Ну ладно. В любом случае, нам нужно много этой травы, и когда я говорю так, я имею в виду действительно МНОГО! Не следует ли тебе помочь нам, как ты считаешь? Я понимаю, это означает, что тебе придется остаться без всех этих чудесных штучек, которые можно приготовить из удавника... но ведь это ради благого дела!", progress = "Это грязный поклеп! Я не брал отсюда ни одной травинки! Хотя соблазн очень велик... ведь это ж практически настоящая панацея от утилитарной бесполезности. *кашляет* Да, кстати, как там насчет удавника, который ты должен был принести мне?", completion = "Урра! Еще двадцатью меньше собирать. Отлично справляешься с работой! Пойду уберу травы, пока они не засохли. Времени так мало, а удавника так много!\n\nСпасибо еще раз, |3-6(Друид)!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8504] = {title = "Альянсу по-прежнему не хватает удавника!", objective = "Принесите 20 стеблей удавника рядовому Драксельмеру на аэродром в Дун Морог.", description = "Эй, ты там... Ой... Что это было? Ах, да, <имя>! <Зашел/Зашла> поинтересоваться, не нужно ли мне еще удавника? О, тебе крупно повезло, потому что ответ на этот жизненно важный вопрос – конечно, ДА! Ну как, соберешь еще двадцать штук?", progress = "Эй, ты там... Ой... Что это было? Ах, да, Лорегон! Зашел поинтересоваться, не нужно ли мне еще удавника? О, тебе крупно повезло, потому что ответ на этот жизненно важный вопрос – конечно, ДА! Ну как, соберешь еще двадцать штук?", completion = "О мой бог, сколько у тебя тут удавника! Давай-ка по-быстрому упакуем его в коробку, чтобы не испортился. Ты оказал мне... то есть, я хотел сказать, нам, Альянсу, угромную услугу! Я приложу все усилия, чтобы все узнали, что это великий Лорегон внес неоценимый вклад в подготовку к киражской войне, пожертвовав столько удавника!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8505] = {title = "Альянсу не хватает лилового лотоса!", objective = "Принесите 20 цветков лилового лотоса мастеру Ночной Песне в Палаты Войны Стальгорна.", description = "<класс>, цветы лилового лотоса где только не применяют. От имени Альянса я отвечаю за заготовку лотоса в количестве, достаточном для удовлетворения всех военных нужд.\n\nНо чтобы собирать цветы, мне нужны добровольцы. Справишься с этим заданием?", progress = "Тебе удалось собрать цветы лилового лотоса?", completion = "Твой вклад очень ценен для всех нас, |3-6(Друид). Только объединив наши усилия, мы сможем отбросить армию безжалостных силитидов и одержать победу. Даже Орда занимается сбором лилового лотоса. Если снова наберешь этих цветов, возвращайся ко мне.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8506] = {title = "Альянсу по-прежнему не хватает лилового лотоса!", objective = "Принесите 20 цветков лилового лотоса мастеру Ночной Песне на аэродром в Дун Морог.", description = "Добро пожаловать обратно, <класс>. Наши запасы лилового лотоса растут, но нам все равно нужно еще. Займись сбором цветов, если можешь, я тебя очень прошу.", progress = "Добро пожаловать обратно, |3-6(Друид). Наши запасы лилового лотоса растут, но нам все равно нужно еще. Если в твоих силах заняться сбором этих цветов, я прошу тебя это сделать.", completion = "От имени Альянса с радостью принимаю твой дар, Лорегон. Ты внес неоценимый вклад в создание снадобий, которые помогут нашим воинам на поле боя. Я благодарю тебя и прошу принести еще лилового лотоса, как только у тебя появится возможность.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8507] = {title = "Рутинное задание", objective = "Поступите в распоряжение дружины Стальгорна возле улья Зора. Подготовьте неподписанные бумаги о полевых обязанностях и получите подписанные бумаги о полевых обязанностях от капитана Черной Наковальни, вернитесь к призывателю ветров Калдону в крепость Кенария в Силитусе.\n\nВнимание: исцеление или наложение благоприятных заклинаний на бойцов дружины Стальгорна переводит в режим PvP.", description = "Приветствую тебя, <имя>. Прежде чем дать тебе ответственные задания, я должен поручить тебе более простые и рутинные.\n\nДружина Стальгорна под предводительством капитана Черной Наковальни расквартирована рядом с Ульем Зора.\n\nПоговори с капитаном и его лейтенантом, Джанелой Твердомолот, а потом возвращайся. Тем временем я подготовлю для тебя новое задание.\n\nАх да, сделай одолжение, держись подальше от легиона Оргриммара. Нам нелегко удерживать эти два войска от грызни, очень уж они друг друга не любят.", progress = "Дружина капитана Черной Наковальни расквартирована рядом с Ульем Зора. Если ты не найдешь его, поговори с Джанелой Твердомолот.", completion = "Отлично, Ренн. Я подготовила целую серию заданий, которые наилучшим образом распорядятся твоими навыками.\n\nЕсли ты и такие как ты будут биться, не покладая рук, скоро мы изгоним врагов!\n\nЕсли тебе понадобится новое задание, возвращайся к капитану Черной Наковальне.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБоевое заданиеЗадание по материально-техническому снабжениюТактическое задание"},
[8508] = {title = "Бумаги о полевых обязанностях", objective = "Я так понимаю, мне надо подписать эти бумаги, парень?", description = nil, progress = "Я так понимаю, мне надо подписать эти бумаги, парень?", completion = "Да, в наши дни эта небольшая заварушка сойдет за рутинные обязанности. Отнеси бумаги в крепость Кенария, уверен, они уж подготовят тебе работу поинтереснее.\n\nСтупай!", rewards = "Вы получите:\n\nПодписанные бумаги о полевых обязанностях"},
[8509] = {title = "Альянсу не хватает слез Артаса!", objective = "Принесите 20 слез Артаса старшему сержанту Гермайн в Палаты Войны Стальгорна.", description = "Я предпочитаю говорить быстро и по существу, <класс>. Альянсу нужно много слез Артаса для войны в Ан'Кираже. Не спрашивай меня, зачем, я всего лишь выполняю приказ. Собери столько этих цветов, сколько унесешь, и сдай мне. Ну что, возьмешься за это задание?", progress = "Что? Докладывай быстро и четко, |3-6(Друид)! Тебе удалось собрать необходимое количество слез Артаса?", completion = "Неплохо сработано, |3-6(Друид). Должна сказать, я приятно удивлена. Ты никогда бы не поверил, сколько людей приходят, обещают помочь и не возвращаются. Одну секунду, сейчас я упакую травы в ящик и прикреплю к нему бирку с твоим именем, а потом сможем поговорить на тему того, нужны ли мне еще эти растения.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8510] = {title = "Альянсу снова нужны слезы Артаса", objective = "Принесите 20 цветков слезы Артаса старшему сержанту Гермайн на аэродром в Дун Морог.", description = "Так, похоже, слезы Артаса мне все еще нужны. Я предполагаю, что они растут там же, где и раньше. Чем быстрее мы закончим подготовку, тем быстрее начнем наступление на Ан'Кираж.\n\nЯ могу вновь рассчитывать на твою помощь, <класс>?", progress = "Так, похоже, слезы Артаса мне все еще нужны. Я предполагаю, что они растут там же, где и раньше. Чем быстрее мы закончим подготовку, тем быстрее начнем наступление на Ан'Кираж.\n\nЯ могу вновь рассчитывать на твою помощь, |3-6(Друид)?", completion = "Просто невероятно, Облизни! Альянс перед тобой в долгу. Мне нужно проследить, чтобы эти травы были упакованы и хранились надлежащим образом, пока кто-нибудь не изготовит из них что-нибудь полезное. Обращайся ко мне в любое время, особенно, если принесешь еще слез Артаса.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8511] = {title = "Альянсу не хватает легкой кожи!", objective = "Принесите 10 легких кож Бонни Шлифовальщице в Палаты Войны Стальгорна.", description = "Наш клан Обдирщиков Камня испокон века знал толк в снятии шкур, <класс>. Как говорится, и с камня снимем шкуру. Потому-то Альянс и попросил нас взяться за заготовку тонкой кожи для войны в Ан'Кираже. Я слежу, чтобы кожа была хорошо выдублена, уж не знаю, для чего она там понадобится. Но без помощи мне никак не обойтись.\n\nПока я здесь за всем надзираю, тебе придется прогуляться малость и добыть кож, а потом принести их мне. Ну что, <паренек/девушка>, возьмешься за дело?", progress = "Ну, |3-6(Друид), где обещанная кожа?", completion = "Я прямо скажу, Альянску крупно повезло, что у него есть такие искушенные специалисты по снятию шкур, как ты,|3-6(Друид). Уж я прослежу, чтобы ни одну кожу ненароком не попортили. Спасибо тебе – и не забудь, когда я пересчитаю кожу, справиться у меня, не требуется ли нам еще.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8512] = {title = "Альянсу по-прежнему не хватает легкой кожи!", objective = "Принесите 10 кусков легкой кожи Бонни Шлифовальщице на аэродром в Дун Морог.", description = "Рада снова тебя видеть, <имя>. Похоже, что мы еще не собрали достаточно кожи для наших воинских нужд. Если принесешь мне штук десять кож, это будет просто отлично.", progress = "Рада снова тебя видеть, Облизни. Похоже, что мы еще не собрали достаточно кожи для всяких воинских нужд. Если принесешь мне штук десять кож, это будет просто отлично.", completion = "Спасибо за столь щедрое пожертвование, Облизни. Пойду уложу кожи в стопку. Я думаю, их быстренько превратят в красивые доспехи, пустят на всякие заплатки, или для чего еще там нужна кожа. Возвращайся, как сможешь, и приноси еще – легкой кожи много не бывает.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8513] = {title = "Альянсу не хватает средней кожи!", objective = "Принесите 10 средних кож рядовому Портеру в Палаты Войны Стальгорна.", description = "Так точно, <сэр/мэм>, я отвечаю за сбор всей средней кожи, необходимой для подготовки к войне с Ан'Кираем. Если вы можете раздобыть среднюю кожу, неважно где, сдайте ее мне, пожалуйста. Я буду благодарен за любую помощь, если у вас найдется на нее время.", progress = "Так точно, сэр, я помню вас. Вы принесли среднюю кожу?", completion = "Вау! Похоже, вы и правда решили помочь. Большое спасибо за ваш вклад в общее дело. Пойду-ка я упакую и пересчитаю кожи. Нет, вы действительно знаете, чем скрасить день простого служаки.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8514] = {title = "Альянсу по-прежнему не хватает средней кожи!", objective = "Принесите 10 средних кож рядовому Портеру на аэродром в Дун Морог.", description = "Так точно, <сэр/мэм>, к настоящему времени нам удалось собрать $2063w кусков средней кожи. Я знаю, что прошу слишком многого, но не могли бы вы снова оказать помощь? Если желаете, конечно. Мне необходимо выполнить установленную норму.", progress = "Так точно, сэр, мы собрали много средней кожи, но все равно недостаточно. Заверяю вас, мы найдем этой коже самое наилучшее применение, ни один клочок не пропадет зря. Я знаю, что требую слишком многого, но если у вас еще сохранилось желание, помогите мне набрать установленную норму.", completion = "Ничего себе, вот это кипа кожи, которую вы притащили, сэр! Я послежу, чтобы она попала точно по назначению, непременно. Если вы и дальше будете помогать нам, то мы выполним план гораздо раньше срока! \n\nСпасибо, Облизни!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8515] = {title = "Альянсу не хватает плотной кожи!", objective = "Принесите 10 плотных кож Марте Остроигл в Палаты Войны Стальгорна.", description = "О, будет так здорово! <класс>, приготовления к ан'киражской войне идут вовсю, и так получилось, что я отвечаю за заготовку плотной кожи. Из нее мы сможем наделать тысячи разных вещей, но сначала надо ее достать – тоже тысячами. В буквальном смысле. И тут на сцену выходишь ты.\n\nТы ведь принесешь мне отличную увесистую кипу плотной кожи? Правда-правда?", progress = "Это же обещанной кожей у тебя сумки набиты, |3-6(Друид)? Не могу дождаться, когда же ты отдашь ее мне! Тогда все-все останутся нами довольны, правда?", completion = "О, я знала, что ты справишься, |3-6(Друид), конечно же, я это знала! Я отправлю эту кожу по нужному адресу, как только смогу. Ага, а теперь давай-ка посмотрим. Похоже, в итоге все получается очень, очень миленько. Загляни ко мне еще разочек, я сейчас проверю, не нужно ли нам еще кожи. Если понадобится, то было бы так здорово, если бы ты смог достать для нас еще!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8516] = {title = "Альянсу по-прежнему не хватает плотной кожи!", objective = "Принесите 10 плотных кож Марте Остроигл на аэродром Стальгорна.", description = "Да-да, стопки все еще не очень высокие. <имя>, мы не выполняем норму – не хватает целых $2071w кусков плотной кожи. Только подумай, сколько всего полезного из нее можно сделать! Броню и оружие на любой вкус! Она годится как на отделку паровых танков, так и на оптические винтовки. Держу пари, все закончится тем, что мы соберем столько кожи, что остаток придется отдать Орде на дирижабли.\n\nТы ведь принесешь мне еще плотной кожи?", progress = "Да-да, стопки еще не очень высокие. Лорегон, мы не выполняем норму – не хватает целых 80000 плотной кожи. Только подумай, сколько всего полезного из нее можно сделать! Броню и оружие на любой вкус! Она годится как на отделку паровых танков, так и на оптические винтовки. Держу пари, все закончится тем, что мы соберем столько кожи, что остаток придется отдать Орде на дирижабли. \n\nТы ведь принесешь мне еще плотной кожи?", completion = "У тебя снова все получилось! Просто невероятно, как ты умудряешься выбраться отсюда, собрать все, что нужно, а потом еще вернуться и сдать все мне. Когда люди узнают, сколько ты для нас сделал, они встанут в очередь за твоими автографами! \n\nБольшое-пребольшое спасибо за столь благородное и щедрое пожертвование плотной кожи, Лорегон.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8517] = {title = "Альянсу не хватает льняных бинтов!", objective = "Принесите 20 льняных бинтов часовому Серебринке Небес в Палаты Войны Стальгорна.", description = "Война в Ан'Кираже будет долгой и кровавой. Прибегнуть к помощи людей, подобных тебе, было для Альянса мудрым решением. Перед тем как сломя голову ринуться в военный конфликт, надо собрать достаточно припасов.\n\nМне поручили запасать льняные бинты, и я надеюсь, что ты мне поможешь. Это не так-то легко, но по крайней мере льняные бинты проще всего изготовить. Что скажешь, <класс>?", progress = "Двадцать льняных бинтов у тебя, |3-6(Друид)?", completion = "Многим солдатам ты, считай, сослужил добрую службу, |3-6(Друид). Я лично прослежу, чтобы твои усилия не остались незамеченными. Одну минуту, сейчас я упакую эти бинты, куда надо, и внесу их в реестр, а потом посмотрим, сколько нужно ли мне еще. \n\nДа осенит тебя своим светом Элуна, ночной эльф!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8518] = {title = "Альянсу по-прежнему не хватает льняных бинтов!", objective = "Принесите 20 льняных бинтов часовому Серебринке Небес на аэродром в Дун Морог.", description = "Меня всегда изумляет самоотверженность – ведь столь многие обычно гораздо более склонны к эгоизму. <класс>, я все никак не могу выполнить свою норму по сбору льняных бинтов. Не поможешь ли мне еще раз?", progress = "Меня всегда изумляет самоотверженность, ведь многие обычно более склонны к эгоизму. Друид, я все никак не могу выполнить свою норму по сбору льняных бинтов. Не поможешь ли мне еще раз?", completion = "Прими мою благодарность, Лорегон. Пока некоторые пытаются нажиться на подготовке к войне, ты раз за разом доказываешь свою бескорыстную преданность делу Альянса, да что там, всего Азерота. \n\nДа пребудет с тобой благословение Элуны!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8519] = {title = "Пешка на Доске Вечности", objective = "Узнайте о прошлом все, что можно. Потом поговорите с Анахроносом в Пещерах Времени в Танарисе.", description = "Успокоившись и сосредоточив взгляд на кристалле, вы замечаете, что внутри что-то шевелится. Посмотрев поближе, вы осознаете, что перед вами предстало прошлое... давно забытое.", progress = nil, completion = "После предательства Оленьего Шлема я собрал осколки скипетра Зыбучих песков и вернулся сюда. Я желал охранить скипетр от посягательств тех, кто был готов воспользоваться им во зло – так были созданы драконы.\n\nМне казалось, что если разделить части скипетра между четырьмя могущественными Аспектами, то взыскующие Хаос не смогут восстановить его. Я был глупцом. Проклятые драконы охотятся на меня по сей день.", rewards = "Вы получите:\n\n"},
[8520] = {title = "Альянсу не хватает шелковых бинтов!", objective = "Принесите 20 шелковых бинтов медсестре Стоунфилд в Палаты Войны Стальгорна.", description = "На горизонте маячит война в Ан'Кираже, так что мы должны приложить все усилия, чтобы на поле боя солдаты ни в чем не нуждались. Именно этим мы и занимаемся. Я вот, например, отвечаю за заготовку шелковых бинтов.\n\nНе хочешь ли мне помочь малость?", progress = "Приветик, |3-6(Друид), ну что, удалось раздобыть двадцать шелковых бинтов?", completion = "Друид, ты молодчина! Спасибо за бинты. Благодаря тебе мы еще на шаг приблизились к нашей общей цели. Сейчас пойду уберу бинты, а потом можем еще поболтать.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8521] = {title = "Альянсу по-прежнему не хватает шелковых бинтов!", objective = "Принесите 20 шелковых бинтов медсестре Стоунфилд на аэродром в Дун Морог.", description = "Очень мило с твой стороны снова предложить мне помощь, <класс>. Мы пока собрали всего лишь $2082w шелковых бинтов, так что еще работать и работать.", progress = "Очень мило с твоей стороны снова предложить мне помощь, |3-6(Друид). Мы уже собрали очень много шелковых бинтов, но это, к сожалению, далеко не конец. Лорегон, можешь принести еще штук двадцать? Я была бы благодарна тебе от имени всего Альянса.", completion = "Приятно иметь дело с бескорыстными ребятами вроде тебя, Лорегон. Мы не забудем твой вклад в подготовку к войне. Именно от таких, как ты, и зависит, победим мы или проиграем. Я надеюсь, что наших усилий хватит для победы. \n\nЕще раз большое спасибо!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8522] = {title = "Альянсу не хватает бинтов из рунной ткани!", objective = "Принесите 20 бинтов из рунной ткани Хранителю Лунному Сумраку в Палаты Войны Стальгорна.", description = "Считай ведение войны сколь угодно сомнительным занятием, <класс>, но военная машина уже завертелась. Оглянись на свою семью и друзей и спроси, чем ты можешь помочь им, – ведь все мы попадем в горнило битвы, и надо будет как-то выживать.\n\nИменно поэтому я запасаюсь бинтами из рунной ткани, кто бы их ни принес. Не хочешь ли внести посильный вклад в это дело?", progress = "Проходит день за днем, а мы все продолжаем и продолжаем готовиться. Друид, тебе удалось достать бинты из рунной ткани?", completion = "Твоя настойчивость в выполнении этого задания выше всяких похвал, |3-6(Друид). Сейчас я уберу бинты на склад и вернусь. Я бы хотел побеседовать с тобой относительно возможности добыть еще бинтов из рунной ткани.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8523] = {title = "Альянсу по-прежнему не хватает бинтов из рунной ткани!", objective = "Принесите 20 бинтов из рунной ткани Хранителю Лунному Сумраку на аэродром в Дун Морог.", description = "Итак, мы снова вынуждены говорить о делах, не терпящих отлагательств, <класс>. Хочу еще раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно. Но работы еще непочатый край.\n\n<имя>, можешь принести мне еще бинтов из рунной ткани?", progress = "Итак, мы слова вынуждены говорить о делах, не терпящих отлагательств, |3-6(Воин). Хочу еще раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно. Но работы еще непочатый край. \n\nЖестя, можешь принести мне еще бинтов из рунной ткани?", completion = "Я рад что этот путь мы проделали вместе, Жестя. Работать с тобой – одно удовольствие. Хочу еще раз поблагодарить за бескорыстную помощь Альянсу тебя и всех, подобных тебе. Возращайся скорей, побеседуем еще.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8524] = {title = "Альянсу не хватает радужного тунца!", objective = "Принесите 20 тушек радужного тунца Гладню Гастрогному в Палаты Войны Стальгорна.", description = "Эй, дружище! Если бы я спросил тебя: \"Нужно ли солдатам на войне хорошо кушать?\" – ты бы, без сомнения, <ответил/ответила>: \"Да, конечно!\". И я абсолютно с тобой согласен! Рад, что мы сошлись во мнениях. Теперь, я думаю, ты не будешь спорить, что тебе осталось только отправиться на рыбалку, наловить радужного тунца, приготовить всю порцию и принести мне. М-м-м, я уже в предвкушении.", progress = "Готов поспорить, что ты вернешься с нужным количеством радужного тунца, |3-6(Друид)!", completion = "Два для Альянса, один мне, два для Альянса, один мне... Эгей, отличная работа, рыбак! Похоже, ты отличное приобретение для нашего клуба. А мне кажется, надо б раздобыть еще тунца. Почему бы тебе не прогуляться и не принести еще рыбки? У меня уже в животе урчит...", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8525] = {title = "Альянсу по-прежнему не хватает радужного тунца!", objective = "Принесите 20 тушек радужного тунца Гладню Гастрогному на аэродром в Дун Морог.", description = "Что? Снова ты? Ну и дела, не будь я гном! Гладень Гастрогном, чтобы быть точным. Выходит, ты <пришел/пришла>, чтобы снова помочь мне? Не могу сказать, чтобы я был этим недоволен. А может, тебе просто понравилось, как пахнет жареный тунец? *облизывается*\n\nЛадно, хватит болтать. Ступай-ка и принеси мне побольше радужного тунца!", progress = "Что? Снова ты? Ну и дела, не будь я гном! Гладень Гастрогном, чтобы быть точным. Выходит, ты пришла, чтобы снова помочь мне? Не могу сказать, чтобы я был этим недоволен. А может, тебе просто понравилось, как пахнет жареный тунец? *облизывается*\n\nЛадно, хватит болтать. Ступай-ка и принеси мне побольше радужного тунца!", completion = "Я сразу понял, что в тебе что-то такое есть, детка. Ты выглядишь, как человек, который знает, чего хочет. Да-да, с Глади Гастрогномом есть верное правило, – сделай мне приятно, и ты об этом не пожалеешь. \n\nХа-ха-ха! Ладно, сейчас пойду сложу рыбку и вернусь. Если хочешь, можешь пока приготовить еще двадцать штук.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8526] = {title = "Альянсу не хватает жареного мяса ящера!", objective = "Принесите 20 жареных ящеров Саре Грустносвист в Палаты Войны Стальгорна.", description = "Как делишки, <класс>? Я вижу, ты просто рвешься принять участие в заготовке провизии для ан'киражской войны. Мой папочка решил, что ответственность за сбор чего-то там чему-то там меня научит. Как бы не так. Я мясо на дух не выношу.\n\nЛадно, если вдруг захочешь помочь, принеси побольше жареных ящеров. Несомненно, именно об этом мясе и будут мечтать все наши отважные солдаты.", progress = "Ну что, где там наши жареные ящеры?", completion = "Вот это да. Спасибо, что притащил сюда всю эту жженую плоть, |3-6(Друид). Минуточку, сейчас я его покидаю в кучу, – надеюсь, кто-нибудь о нем да позаботится. Если время найдется, может быть, еще принесешь?", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8527] = {title = "Альянсу по-прежнему не хватает жареного мяса ящера!", objective = "Принесите 20 жареных ящеров Саре Грустносвист на аэродром в Дун Морог.", description = "О, снова здорово, <класс>. Я вижу, ты в восторге от всей этой беготни. Наверное, ты хочешь принести мне еще двадцать жареных ящеров? Отлично. Тогда пойди и принеси. Увидимся.", progress = "О, снова здорово, |3-6(Друид). Я вижу, ты в восторге от всей этой беготни. Наверное, хочешь принести мне еще двадцать жареных ящеров? Отлично. Так пойди и принеси. Увидимся.", completion = "Вау, ты просто бизнес-воротила. Один твой вид уже наводит на меня усталость. В любом случае, спасибо тебе от имени Альянса и все такое. Пойду позабочусь, чтобы всю эту дохлятину куда-нибудь прибрали. Думаю, ты можешь вернуться попозже, когда я проверю, сколько нам еще осталось собрать. Хотя, если честно, этим мясом уже провоняло здесь абсолютно все.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8528] = {title = "Альянсу не хватает пятнистого желтохвоста!", objective = "Принесите 20 пятнистых желтохвостов охотнице Быстрой Реке на Военный Двор Стальгорна.", description = "Возможно, заготовка вареной рыбы выглядит не особенно героически, но не стоит преуменьшать значение нашей работы, <класс>.Солдаты – такие же люди, как и все, и они хотят есть. Именно поэтому мы должны обеспечить их провиантом, пока не началась война в Ан'Кираже.\n\nЯ получила приказ заготавливать пятнистый желтохвост. Это отличный пищевой ресурс, он хорошо хранится, идет на изготовление различных блюд и совсем не пахнет, в отличие от другой морской рыбы. Ну что, поможешь мне в его заготовке?", progress = "Я уверена, что ты вернулся так быстро, потому что принес необходимое количество желтохвоста.", completion = "Спасибо за быструю и своевременную помощь, |3-6(Друид). Теперь наши солдаты не будут испытывать недостатка в провианте. Подожди немного, я позабочусь о размещении рыбы на складе, и мы обсудим доставку еще одной порции, если ты не против.", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8529] = {title = "Альянсу по-прежнему не хватает пятнистого желтохвоста!", objective = "Принесите 20 пятнистых желтохвостов охотнице Быстрой Реке на аэродром в Дун Морог.", description = "Если у тебя еще не пропало желание помогать нам, то нам все еще нужен желтохвост, <имя>. Я думаю, в прошлый раз ты <приобрел/приобрела> достаточно опыта, так что сейчас дело пойдет веселее. Ну что, по рукам?", progress = "Если у тебя еще не пропало желание помогать нам, то нам опять нужен желтохвост, Бэдэльф. Я думаю, в прошлый раз ты приобрел достаточно опыта, так что сейчас дело пойдет веселее. Ну что, по рукам?", completion = "Сразу видно, что ты заботишься о нуждах Альянса, как о своих собственных, Бэдэльф. Твои старания не останутся незамеченными, и награда обязательно найдет своего героя. Спасибо за отлично приготовленную рыбу. Теперь ее можно хранить долго и без особых проблем. Пойду-ка я запишу, сколько ты принес. Когда близится война, на счету должна быть каждая рыбина!", rewards = "Вы получите:\n\nРекомендательный жетон АльянсаПрипасы для войны в Ан'Кираже"},
[8530] = {title = "Альянсу не хватает опаленных вулканических камней!", objective = "Принесите 50 оплавленных вулканических камней командиру Мощному Молоту на аэродром в Дун Мороге.", description = "<класс>, мне нужна твоя помощь. Есть камни, которые можно достать в Огненных Недрах, – я имею в виду опаленные вулканические камни. Они нужны нам для подготовки к войне в Ан'Кираже. Наши кузнецы и инженеры знают, как их использовать, так что мы получили на них заказ. Проберись в Огненные Недра и собери столько, сколько сможешь. Не сомневаюсь, что тебе удастся уговорить пойти с тобой штук тридцать девять близких приятелей.", progress = nil, completion = nil, rewards = nil},
[8531] = {title = "Альянсу по-прежнему не хватает опаленных вулканических камней!", objective = "Принесите 50 оплавленных вулканических камней командиру Мощному Молоту на аэродром в Дун Морог.", description = "Спасибо, что <пришел/пришла> снова, <имя>. Если твои друзья все еще с тобой, вернитесь в Огненные Недра и наберите еще оплавленных вулканических камней. Ну как, по рукам?", progress = nil, completion = nil, rewards = nil},
[8532] = {title = "Орде не хватает медных слитков!", objective = "Принесите 20 медных слитков шахтеру Кромвелю в Аллею Духов Оргриммара.", description = "Я так рад, что ты <решил/решила> помочь нам. Не всякий бы согласился, так что я лучше еще раз уточню, правильно ли ты меня <понял/поняла>. Мне нужны медные слитки, а не просто медь. У нас недостаточно ни времени, ни людей, чтобы самим ее выплавлять, так что твои усилия не останутся незамеченными. Ну как, <класс>, справишься?", progress = "Я надеюсь, 20 медных слитков у тебя с собой, |3-6(Воин)?", completion = "Вот они, слитки, хорошо, что ты не стал полировать их. В блеске нет никакого смысла, они все равно пойдут на военные нужды. Пойду уложу их в штабели, и нужно позаботиться, чтобы они были пущены в дело. Если добудешь еще двадцать, обращайся прямо ко мне.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8533] = {title = "Орде по-прежнему не хватает медных слитков!", objective = "Принесите 20 медных слитков шахтеру Кромвелю в Дуротар.", description = "Уже <вернулся/вернулась>? Из тебя быстро бы получился отличный рудокоп, <класс>. Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь ее в слитки и возвращайся ко мне. Я знаю, что ты кое-что можешь, вопрос – хочешь ли?", progress = "Уже вернулся? Из тебя быстро получился бы отличный рудокоп, |3-6(Маг). Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь ее в слитки и возвращайся ко мне. Я знаю, что кое-что ты можешь, но вот вопрос – хочешь ли.", completion = "Ты опять доказал, что ты многого стоишь, |3-6(Маг). Я чувствую, эта медь хорошо нам послужит, когда придет время. А теперь мне надо сложить ее в штабеля и подсчитать. Если у тебя не пропало желание, ты, вероятно, сможешь помочь нам, если принесешь еще медных слитков.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8534] = {title = "Донесение разведчика из Улья Зора", objective = "Свяжитесь с кенарийским разведчиком Азенель в улье Зора и отнесите донесение разведчика призывательнице ветров Гордый Рог в крепость Кенария. Кроме того, принесите тактическую задачу VI.", description = "Мы отправили наших лучших разведчиков к ульям силитидов. Азенель уже несколько дней наблюдает за передвижениями этих насекомых. Найди ее и забери у нее письменный отчет. Нам необходимо как можно скорее получить от нее сведения.", progress = "Разведчик Азенель находится внутри Улья Зора. Спеши! Время не ждет.", completion = "Мы очень ценим твои усилия, Лорегон. Я немедленно займусь этим донесением, а ты можешь переходить к следующему заданию.", rewards = "Вы получите:\n\nКенарийский знак тактикаДополнительное тактическое задание"},
[8535] = {title = "Седой храмовник", objective = "Призовите и убейте седого храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу IV.", description = "Сумеречный Молот и повелители стихий, которым поклоняются культисты, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан'Кираже, мы не должны терять бдительность и давать волю внешним врагам.\n\nОтыщи способ вызвать и уничтожить седого храмовника и доложи о выполнении задания Бору Буйногривому.", progress = "Ты уже выполнил задание?", completion = "Отличная работа, Ренн. Вот следующее задание.", rewards = "Вы получите:\n\nКенарийский знак тактикаТактическое задание"},
[8536] = {title = "Земной храмовник", objective = "Призовите и убейте земного храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу III.", description = "Сумеречный Молот и повелители стихий, которым поклоняются культисты, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан'Кираже, мы не должны терять бдительность и давать волю внешним врагам.\n\nОтыщи способ вызвать и уничтожить земного храмовника и доложи о выполнении задания Бору Буйногривому.", progress = "Ты уже выполнил задание?", completion = "Отличная работа, Ренн. Вот следующее задание.", rewards = "Вы получите:\n\nКенарийский знак тактикаДополнительное тактическое задание"},
[8537] = {title = "Багровый храмовник", objective = "Призовите и убейте багрового храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу II.", description = "Сумеречный Молот и повелители стихий, которым поклоняются культисты, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан'Кираже, мы не должны терять бдительность и давать волю внешним врагам.\n\nОтыщи способ вызвать и уничтожить багрового храмовника и доложи о выполнении задания Бору Буйногривому.", progress = "Ты уже выполнил задание?", completion = "Отличная работа, Рисунок. Вот следующее задание.", rewards = "Вы получите:\n\nКенарийский знак тактикаТактическое задание"},
[8538] = {title = "Четыре герцога", objective = "Отыщите способ вызвать и убить герцога Пепла, герцога Глубин, герцога Ветров и герцога Осколков и доложите о выполнении задания командиру Мар'алиту в крепости Кенария. Для завершения задания принесите тактическую задачу V.", description = "Связь между Сумеречным Молотом и Советом Бездны оказалась куда важнее, чем нам казалось вначале.\n\nМы не сомневаемся, что повелители Стихий, именуемые герцогами Бездны, управляют культистами Сумеречного Молота. Найди способ выманить в наш мир четырех герцогов Бездны и убей их!\n\nМы избрали тебя за прежние заслуги и не сомневаемся, что ты справишься.", progress = "Ты уже выполнила задание?", completion = "Сегодня ты сделала великое дело, Киберка. Тебе удалось избавить нас от злейших врагов. Хвала тебе за это!", rewards = "Вы получите:\n\nДрагоценность Кенария"},
[8539] = {title = "Цель: сестры-убийцы из Улья Зора", objective = "Убейте 30 сестер-убийц из улья Зора и доложите о выполнении задания командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу V.", description = "Мы вызвали подкрепление для сражения у Улья Зора. Твоя задача – убить как можно больше сестер-убийц. Выполнив задание, отчитайся командиру Мар'алиту.", progress = "Ты хочешь что-то сказать, |3-6(Паладин)?", completion = "Отличная работа, Ренн. Ты очень ценный союзник.", rewards = "Вы получите:\n\nКенарийский знак бойца"},
[8540] = {title = "Сапоги для стражей", objective = "Принесите 3 пары изысканных мифриловых сапог Вишу Коцусу, капитану стражи в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу II.", description = "Верховому подразделению крепости Кенария не хватает изысканных мифриловых сапог. Принеси нам очередную партию и передай их капитану Вишу Коцусу из крепости Кенария.", progress = "Что ты мне принесла, Киберка?", completion = "Отлично! Как раз то, что нужно. Спасибо.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"},
[8541] = {title = "Шлифовальные камни", objective = "Принесите 10 массивных шлифовальных камней, 10 твердых шлифовальных камней и 10 тяжелых точильных камней Вишу Коцусу, капитану стражи в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу III.", description = "У стражи крепости Кенария на исходе шлифовальные камни. Добудь их и отнеси капитану Вишу Коцусу в крепость Кенария.", progress = "Что ты мне принес, Лорегон?", completion = "Отлично! Нам очень нужны эти материалы. Спасибо.", rewards = "Вы получите:\n\nКенарийский знак тыловикаЗадание по материально-техническому снабжению"},
[8542] = {title = "Орде не хватает оловянных слитков!", objective = "Принесите 20 оловянных слитков рубаке Маугу в Аллею Духов Оргриммара.", description = "Лок'тар, <раса>, я уверен, ты в курсе, что мы собираемся воевать с киражскими тараканами. Вождь сказал, что сначала надо как следует подготовиться. Я б охотней точил мечи или подгонял броню, но мне доверили сбор оловянных слитков. Для меня это большая честь, да! Но без помощи мне не справиться.\n\nНадо, чтобы кто-то добывал эти самые слитки и приносил сюда. Нам нужно так много, что, боюсь, я и считать-то до стольких не умею.", progress = "Ну, сколько там у тебя оловянных слитков, |3-6(Чернокнижник)? Думаю, после войны надо бы научиться считать, что ли...", completion = "Хм... Выглядит так, будто слитков столько, сколько нужно... Только не пытайся обмануть меня, |3-6(Чернокнижник)! От этого счета у меня башка раскалывается. Пойду сложу слитки в штабель, а ты пока отправляйся и принеси еще столько же.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8543] = {title = "Орде все еще нужны оловянные слитки!", objective = "Принесите 20 оловянных слитков рубаке Маугу в Дуротар.", description = "Отлично, я понял, к войне ты относишься серьезно. Видишь ли, в ее предвкушении я так нервничаю, что потихоньку начинаю выходить из себя. А твоя медлительность меня просто бесит!!! Не можешь притаскивать товар быстрее, что ли? Может, мне малость с тобой поразмяться, чтобы снять стресс...\n\nХар!!! Нет, не буду, пожалуй, а то кто тогда будет носить мне слитки?", progress = "Отлично, я понял, к войне ты относишься серьезно. Видишь ли, в ее предвкушении я немного нервничаю, думаю, ты меня понимаешь, как солдат солдата, |3-6(Маг). Это будет победоносная война, когда начнется. Воины Орды преодолеют пески и с оружием в руках кинутся на киражских тараканов. В этот день все мы обретем великую славу! \n\nХар! Но сначала нужно собрать достаточное количество этих несчастных оловянных слитков. Забавно, что мы не можем начать грандиозную войну без этих маленьких штуковин, правда?", completion = "Тром'ка, Дэдоутсайд! Своими делами ты оказываешь и мне, и Орде большую честь. Сейчас я позабочусь об этих слитках. А когда мы сделаем все, что нужно, то отправимся на войну и покажем этому ничтожному Альянсу, как надо давить тараканов! \n\nТак что ступай и принеси еще слитков!", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8544] = {title = "Наплеч Завоевателя", objective = "Принесите киражские наручники Командования, 2 идола Ночи, 5 каменных и 5 глиняных скарабеев Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.\n\nПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!", progress = "Тебе удалось собрать все, что мне нужно?", completion = "Я изготовил это наплечье, смертный, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.", rewards = "Вы получите:\n\nНаплеч Завоевателя"},
[8545] = {title = "Орде не хватает мифриловых слитков!", objective = "Принесите 20 мифриловых слитков старшему сержанту Ткелаху. Ткелах находится на аллее Духов Оргриммара.", description = "Война надвигается неотвратимо, и все, что нам остается, <класс>, – это как следует подготовиться к ней. В такие времена мы должны сплотиться и помогать друг другу. Как видишь, меня поставили ответственным за сбор мифриловых слитков, которые потом пойдут на нужды армии. Я стараюсь как могу, но этого пока недостаточно.\n\nСумеешь добыть мифрил на рудниках и переплавить его в слитки? Это бы нам очень пригодилось.", progress = "Хорошо бы поскорее собрать все слитки и закончить подготовку к войне в Ан'Кираже. Ты уже достал все, что мне нужно, дружище?", completion = "Ну вот, очень неплохой зачин в нашей работе, |3-6(Воин). Теперь на складе лежит еще 20 новеньких слиточков, сейчас я внесу их в список. Когда на пороге война, на счету каждая крупинка мифрила! \n\nТы заглядывай, похоже, нам скоро еще понадобятся слитки.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8546] = {title = "Орде все еще не хватает мифриловых слитков!", objective = "Ага, приятно снова тебя видеть, дружище. Я помню, ты уже помог мне разок, а теперь снова нужна твоя помощь. Мы продолжаем собирать для войны мифриловые слитки. Из них получится отличное оружие, которым мы легко передавим всех этих киражских тараканов.\n\nТак что, если ты и правда нам друг, принеси еще мифриловых слитков. Пока мы не выполнили нашу квоту, я очень на тебя рассчитываю.", description = nil, progress = "Ага, приятно снова тебя видеть, дружище. Я помню, ты уже помог мне разок, а теперь снова нужна твоя помощь. Мы продолжаем собирать для войны мифриловые слитки. Из них получится отличное оружие, которым мы легко передавим всех этих киражских тараканов.\n\nТак что, если ты и правда нам друг, принеси еще мифриловых слитков. Пока мы не выполнили нашу квоту, я очень на тебя рассчитываю.", completion = "Отлично сработано, Мард! Мы ближе к цели на целых двадцать слитков. Сейчас я прослежу, чтобы их отгрузили. Если раздобудешь еще двадцать, дружище, сразу же тащи их мне.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8547] = {title = "Добро пожаловать!", objective = "Принесите подарочный сертификат площади Соколиных Крыльев Марсилле Утренней Звезде.", description = "Добро пожаловать в мир World of Warcraft!\n\nВ знак особой благодарности за приобретение коллекционного издания вы получаете подарок! Передайте этот подарочный сертификат Марсилле Утренней Звезде на площади Соколиных Крыльев. Взамен вы получите маленького спутника, который будет сопровождать вас на пути к славе.\n\nЕще раз благодарим вас и желаем приятного времяпровождения в мире World of Warcraft!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПоводок зерглингаОшейник пандыКамень Дьябло"},
[8548] = {title = "Броня добровольца", objective = "Принесите 5 боевых, 3 тыловых и 7 тактических знаков Кенария Варгусу из крепости Кенария в Силитусе. Кроме того, для выполнения этого задания вам необходимо заслужить дружелюбное отношение Круга Кенария.", description = "Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в крепости Кенария, нужны не для красоты, <имя>.\n\nНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки Силы ЗемлиКольцо Гнева ЗемлиЗемлетканный плащ"},
[8549] = {title = "Орде не хватает мироцвета!", objective = "Принесите 20 цветков мироцвета травнице Гордый Плюмаж в Аллею Духов Оргриммара.", description = "Говорят, каждое поколение должно пройти испытание огнем. Боюсь, что ан'киражская война станет для нас тем самым горном для закалки. Ничего, подготовимся как следует и покажем всем, из какого мы слеплены теста.\n\nНам нужен мироцвет, который пойдет на создание лекарственных снадобий, и я вызвалась быть ответственной за его сбор. Надеюсь, ты <пришел/пришла> предложить мне свою помощь. Собери побольше мироцвета и принеси его мне.", progress = "Уже собрал мироцвет и вернулся, |3-6(Воин)?", completion = "Подготовка близится к концу, и скоро грянет война. Спасибо за помощь, Мард. Мироцвет очень нужен нам, и твой вклад в общее дело не останется незамеченным. Если сможешь, возвращайся и помоги мне собрать еще мироцвета. А пока ступай, и пусть Мать-Земля хранит тебя.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8550] = {title = "Орде все еще не хватает мироцвета!", objective = "Приветствую тебя еще раз, Дэдоутсайд. Я рада, что ты решил снова помочь нам в этом бесконечном сборе мироцвета. Подготовка к войне идет полным ходом, поэтому эликсиры и снадобья нужны в огромных количествах.\n\nСобери столько же мироцвета, сколько и в прошлый раз, и благодарность моя не будет знать границ. Если вдруг собранный мироцвет у тебя уже с собой, то я приму его с радостью.", description = nil, progress = "Приветствую тебя еще раз, Дэдоутсайд. Я рада, что ты решил снова помочь нам в этом бесконечном сборе мироцвета. Подготовка к войне идет полным ходом, поэтому эликсиры и снадобья нужны в огромных количествах.\n\nСобери столько же мироцвета, сколько и в прошлый раз, и благодарность моя не будет знать границ. Если вдруг собранный мироцвет у тебя уже с собой, то я приму его с радостью.", completion = "Спасибо, что продолжаешь помогать нам, Дэдоутсайд. Твоя самоотдача делает честь тебе и твоим предкам. Пойду упакую травы, чтобы они не потеряли своей свежести к тому времени, когда они понадобятся. Продолжай трудиться на благо нашей победы, во имя Орды!", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8551] = {title = "Сундук капитана", objective = "Верните Гекельберри Шмотту из Пиратской бухты его сундук.", description = "Когда-то у меня был корабль, на котором я плавал до самого Кабестана в Калимдоре, и репутация у меня была безупречная.\n\nПока…\n\nПока не появились проклятые морские великаны! Они разбили мой корабль, поубивали всю команду, а меня отправили на шлюпке в Пиратскую бухту. А один из гигантов, Горлаш, украл мой капитанский сундук, мол табакерка из него выйдет неплохая. Наглец!\n\nГоворят, Горлаш бродит по берегу к востоку отсюда. Найди его и верни мой сундук! Благодарность моя не будет знать предела.", progress = "Эгей, Эфром! Нашел Горлаша? Это был мой любимый сундук, к тому же в тайном отделении там лежат все мои сокровища!", completion = "О, ты нашел его! О, радость, о счастье! Спасибо, Эфром. Ко мне вернулся мой сундук, и в душе разгорается прежний огонь.\n\nНо месть моя еще не свершилась...", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nНаручи Кровавой повязки"},
[8552] = {title = "Кушак с монограммой", objective = "Верните кушак с монограммой владельцу.", description = "Вдоль каймы кушака вышита монограмма \"ГШ\".", progress = "Привет. У тебя ко мне какое-то дело?", completion = "Тебе удалось вернуть мой кушак? Тогда... ты, должно быть, убил морского великана! Урааа!\n\nКак я рад, что этот негодяй мертв – Мок'раш был одним из трех великанов, которые уничтожили мои корабли и поубивали всю команду.\n\nИ так три раза подряд!\n\nТы достойный |3-6(Друид), Ыгрок.", rewards = "Вы получите:\n\n"},
[8553] = {title = "Капитанская сабля", objective = "Поговорите с Салагой.", description = "После того как эти проклятые великаны уничтожили мой корабль, я купил еще один. Назвал его \"Месть Шмотта\", запасся продовольствием, нанял команду и отправился в поисках этих злодеев. Найти-то я их нашел, но... они снова надавали мне по шее. \"Месть Шмотта\" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку.\n\nУ другого великана, Неголаша, моя сабля.\n\nСразись с Неголашем и принеси мне мою саблю!\n\nМожешь поговорить со Салагой, поваром с \"Мести Шмотта\", который выжил в последней битве. Он поможет тебе найти великана.", progress = nil, completion = "Привет-привет, Ыгрок. Капитан говорит, что ты пойдешь на Неголаша, а?", rewards = "Вы получите:\n\n"},
[8554] = {title = "Бой с Неголашем", objective = "Отнесите 10 жареных крылышек канюка и 5 бутылок экзотического вина в спасательную шлюпку капитана Шмотта.\n\nУбейте Неголаша и отнесите абордажную саблю Шмотта хозяину в Тернистую долину.", description = "Неголаш – великан-обжора.\n\nКогда они уничтожили мой корабль, Неголаш бросился прямиком на кухню. В отличие от его товарищей, команда его не очень интересовала. Ему хотелось вина... и жареных крылышек канюка. Это мое коронное блюдо, рецепт я привез из самих Бесплодных земель!\n\nЕсли ты хочешь приманить великана, добудь вина и кучу крылышек канюка. Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда. Когда Неголаш почует запах еды, он непременно явится!", progress = "Тебе удалось добыть мою саблю, Сипсик?", completion = "Ты отобрал у Неголаша мою саблю! Глазам своим не верю! Я чувствую, с момента нашей встречи ветер удачи переменился, теперь он попутный!\n\nСпасибо! Если я все же куплю себе новый корабль, а ты пожелаешь поплыть в море, приходи, гостем будешь.", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nКомпас Шмотта"},
[8555] = {title = "Создание драконов", objective = "Эраникус, Веластрас и Азурегос... Не сомневаюсь, тебе приходилось слышать об этих драконах, смертный. И они не случайно сыграли очень важную роль как наблюдатели нашего мира.\n\nК сожалению (и в этом виновата отчасти моя наивность), под воздействием то ли посланников Древних Богов, то ли предательства близких людей, все они пали. Благодаря чему мое недоверие к твоим собратьям только усилилось.\n\nОтыщи их... И готовься к худшему, |3-6(ночной эльф).", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8556] = {title = "Перстень Неукротимой силы", objective = "Принесите киражское кольцо власти, 2 лучистых идола, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Зовущей Йессендре в Силитус. Кроме того, необходимо заслужить как минимум уважительное отношение Круга Кенария.", description = "Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности. Однако считается, что если заменить пораженные скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастет еще больше.\n\nКамни, украшающие киражских идолов, вполне подойдут – они отменного качества.\n\nПринеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, <класс>.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПерстень Непреклонной силы"},
[8557] = {title = "Пелерина Неукротимой силы", objective = "Принесите киражскую воинскую пелерину, 2 ониксовых идола, 5 серебряных и 5 костяных скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.", description = "Я рад слышать, что ты помогаешь нам в нападении на Ан'Кираж, <имя>. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.\n\nМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.\n\nУвидишь, эта вещь тебя не разочарует.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПелерина Непреклонной силы"},
[8558] = {title = "Серп Неукротимой силы", objective = "Принесите киражскую шипастую рукоять, 2 алебастровых идола, 5 хрустальных и 5 каменных скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария.", description = "Киражи и их прислужники владеют вещами, которые созданы из редчайших и благороднейших материалов – костей гигантских древних созданий, драгоценностей из самых глубин земли, чистейших и прочных металлов...\n\nПри одном взгляде на киражские артефакты мне хочется разбить их, чтобы переплавить обломки и испробовать на них свое собственное искусство. Докажи Кругу Кенариуса свою преданность, <имя>, и я создам для тебя могучее оружие из лучших киражских материалов.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСерп Непреклонной силы"},
[8559] = {title = "Наголенники Завоевателя", objective = "Принесите киражские наручники Командования, 2 идола Войны, 5 золотых скарабеев и 5 скарабеев из слоновой кости Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.\n\nПринеси мне киражские наручники Господства и еще несколько компонентов, и я создам для тебя потрясающие сапоги.\n\nУвидишь, насколько они окажутся полезны в схватке с врагом.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nНаголенники Завоевателя"},
[8560] = {title = "Набедренники Завоевателя", objective = "Принесите целую шкуру Оуро, 2 идола Смерти, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.", description = "Хочешь доказать нам, что тебе можно доверять, <смертный/смертная>? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.\n\nСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.\n\nШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.\n\nПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nНабедренники Завоевателя"},
[8561] = {title = "Корона Завоевателя", objective = "Принесите венец Век'нилаша, 2 идола Солнца, 5 каменных и 5 хрустальных скарабеев Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.", description = "Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.\n\nЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы власти Ан'Кираж будут служить нам.\n\nПринеси то, что мне нужно, <имя>. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКорона Завоевателя"},
[8562] = {title = "Кираса Завоевателя", objective = "Принесите панцирь Древнего Бога, 2 идола Войны, 5 серебряных и 5 костяных скарабеев Ветсере в Ан'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.", description = "Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.\n\nВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.\n\nКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКираса Завоевателя"},
[8563] = {title = "Наставник чернокнижников", objective = "Поговорите с наставником чернокнижников – заклинателем Тель'Лариеном в Солнечном Шпиле на Острове Солнечного Скитальца.По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных чернокнижников на Острове Солнечного Скитальца тренирует заклинатель Тель'Лариен. Поговори с ним, может быть, он сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nТель'Лариен, как и все наставники Острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.После выполнения этого задания вы получите:\n\n", description = "По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных чернокнижников на Острове Солнечного Скитальца тренирует заклинатель Тель'Лариен. Поговори с ним, может быть, он сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nТель'Лариен, как и все наставники Острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil},
[8564] = {title = "Наставник жрецов", objective = "Поговорите с наставницей жрецов сестрой Ариной в Солнечном Шпиле на Острове Солнечного Скитальца.По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных жрецов на Острове Солнечного Скитальца тренирует сестра Арина. Поговори с ней, может быть, она сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nАрина, как и все наставники Острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.После выполнения этого задания вы получите:\n\n", description = "По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных жрецов на Острове Солнечного Скитальца тренирует сестра Арина. Поговори с ней, может быть, она сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.\n\nАрина, как и все наставники Острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil},
[8565] = {title = "Былые победы в Арати", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПочетный знак Низины Арати"},
[8566] = {title = "Былые победы в Арати", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПочетный знак Низины Арати"},
[8567] = {title = "Былые победы в Ущелье Песни Войны", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПочетный знак Ущелья Песни Войны"},
[8568] = {title = "Былые победы в Ущелье Песни Войны", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПочетный знак Ущелья Песни Войны"},
[8569] = {title = "Былые сражения в Ущелье Песни Войны", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПочетный знак Ущелья Песни Войны"},
[8570] = {title = "Былые сражения в Ущелье Песни Войны", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПочетный знак Ущелья Песни Войны"},
[8572] = {title = "Броня ветерана", objective = "Принесите 7 боевых, 4 тыловых и 4 тактических знаков Кенария Варгусу из крепости Кенария в Силитусе. Кроме того, для выполнения этого задания вам необходимо заслужить уважительное отношение Круга Кенария.", description = "Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в крепости Кенария, нужны не для красоты, <имя>.\n\nНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБлагодать ЗемлиКольцо Мощи ЗемлиЖилет Силы земли"},
[8573] = {title = "Броня Защитника", objective = "Принесите 15 боевых, 20 тыловых, 20 тактических знаков Кенария и 1 знак Кенария Варгусу из крепости Кенария в Силитусе. Кроме того, вас должны превозносить в Круге Кенария.", description = "Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в крепости Кенария, нужны не для красоты, <имя>.\n\nНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.", progress = "Мы заинтересованы в том, чтобы у ближайших наших сподвижников было хорошее снаряжение, Киберка.", completion = "Отличная работа, Киберка. Прошу тебя, прими это от лица Круга Кенария. Ты заслужила такую награду!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБоевая перчатка КенарияГнев КенарияЗемной удар\n\nВы также получите:\n\n"},
[8574] = {title = "Стойкая броня", objective = "Принесите 15 боевых, 20 тыловых, 17 тактических знаков Кенария и 1 знак Ремулоса Варгусу из крепости Кенария в Силитусе. Кроме того, для выполнения этого задания необходимо заслужить почтительное отношение Круга Кенария.", description = "Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий Зовущей из клана Гордый Рог, нужны не для красоты, <имя>.\n\nНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nГлубокоскальные наручиСфера Спокойствия землиНаручи Скальной ЯростиМощь Кенария"},
[8575] = {title = "Магическая книга Азурегоса", objective = "Принесите магическую книгу Азурегоса Нарайну Причудденю в Танарис.", description = "Из надписи на книге вы ни слова не понимаете. Вы даже не знаете, на каком языке сделана эта надпись!", progress = "ОООХХХ! Эта штучка прямо-таки пульсирует магией! Это мне?", completion = "*Нарайн жадно рассматривает письмена.*\n\nНевероятно, |3-6(ночной эльф)!Что это? Я по-драконьи ни бум-бум.", rewards = "Вы получите:\n\n"},
[8576] = {title = "Перевод книги", objective = "Первым делом, Лорегон, нам надо узнать, что там Азурегос написал в своей книжке.\n\nГоворите, он сказал вам, будто он умеет делать арканитовые буйки, и что тут – чертежи? Странно, что он написал это на драконьем. Этот старый козел знает, что я не могу читать эту белиберду!\n\nЕжели мы хотим это сделать, то мне нужны мои гадальные очки, пятисотфунтовая курица и второй том \"Драконьего языка для чайников.\" Не обязательно в этом порядке.", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[8577] = {title = "Тушеный Лис, БЛД.", objective = "Нарайн Причуддень хочет, чтобы вы нашли его бывшего лучшего друга (БВЛ) Тушеного Лиса, и отняли у него гадальные очки, которые БВЛ украл у Причудденя.", description = "Если я хочу хоть что-то перевести, мне нужны мои гадальные очки. Увы, их давным-давно спер мой бывший лучший друг Тушеный Лис. Он разбил мое сердце на пять частей и оставил меня в горести.\n\nПри помощи моего верного хрустального шара я выяснил, где он находится – либо у Стены Седогрива в Серебролесье или в каком-то мире за порталом Запределья, нынче разоренном Пылающим Легионом. Вы должны найти его след и отнять у него мои очки, <имя>!", progress = nil, completion = "Поверить не могу, что он меня нашел. Я был полностью уверен, что потерял его, когда был в Запределье. Я туда не вернусь, |3-6(ночной эльф)! Ни за какие коврижки! Я готов быть ему по четным лучшим другом и рабом по нечетным!", rewards = "Вы получите:\n\n"},
[8578] = {title = "Гадальные очки? Без проблем!", objective = "Найдите гадальные очки Нарайна и отнесите их Нарайну Причудденю в Танарис.", description = "* Из ящика доносится вздох облегчения.*\n\nТак вам нужны только его очки? Отлично! Никаких проблем... Подождите минуточку, и... Эй! Где... Епрст!\n\nВ общем, есть новость плохая и еще хуже. Плохая – я потерял очки. Еще хуже – я потерял их, когда в прошлом месяце разнюхивал обстановку в Огненных Недрах. Да, в Огненных Недрах... Думаю, что на этом наш разговор закончен! Пока!", progress = "Что, Огненные Недра? Надеюсь, мои очки еще целы!", completion = "Прекрасно! Теперь где взять 500-фунтовую курочку и второй том \"Драконьего языка для чайников???\" О, а вот вам кое-что за ваши тяжкие труды!", rewards = "Вы получите:\n\nСильнейшее зелье омоложения"},
[8579] = {title = "Поборники правого дела из числа смертных", objective = "Мы чуем наших порабощенных собратьев, томящихся в глубинах Ан'Киража, но даже армия драконов не сможет спасти их, |3-6(человек).\n\nК'Тун наложил заклинание, которое не только держит их в плену, но поработит всех нас, если мы подойдем достаточно близко.\n\nДревний Бог предвидел наше появление и не оставил нам никакой надежды. Смешно даже думать, что смертное существо вроде тебя сможет чего-то добиться.", description = nil, progress = "Мы чуем наших порабощенных собратьев, томящихся в глубинах Ан'Киража, но даже армия драконов не сможет спасти их, |3-6(человек).\n\nК'Тун наложил заклинание, которое не только держит их в плену, но поработит всех нас, если мы подойдем достаточно близко.\n\nДревний Бог предвидел наше появление и не оставил нам никакой надежды. Смешно даже думать, что смертное существо вроде тебя сможет чего-то добиться.", completion = "Я вижу, ты не обычная смертная, Хёллка. Твои шансы победить Древнего Бога исчезающе малы, но они все равно больше, чем наши. В конце концов, если он ожидает у своих дверей драконов, то вряд ли готовится встретить кого-нибудь вроде тебя. \n\nТысячу лет назад Анахронос и Олений Шлем создали союз смертных и драконов, и смогли победить киражей. Можем заключить договор и мы. Если ты завоюешь доверие крыла Бронзовых драконов, мы тоже будем тебе доверять, и ты сможешь стать настоящим защитником правого дела.", rewards = "Следующее заклинание будет наложено на вас:\n\nОтношение - храм Ан'Киража, ключевой противник\n\nВы получите:\n\n"},
[8580] = {title = "Орде не хватает огнецвета!", objective = "Принесите 20 огнецветов нетопыриному наезднику Пелекейки в Аллею Духов Оргриммара.", description = "Даров, <класс>. Как делишки, дружище? Орде тут для войны в Ан'Кираже понадобилась прорва этого несчастного огнецвета. Даж интересно, они собираются запихнуть его во всякие взрывающиеся штуки или отдать Альянсу на топливо для танков? Спроси что-нибудь полегче, тут Пелекейки не в курсе, ага.\n\nНо кое-что Пелекейки знает... например, что ты сейчас пойдешь и принесешь ему этого несчастного огнецвета, ага, дружище?", progress = "Ты ведь не хочешь рассердить Пелекейки, ага, дружище? Ты хочешь, чтобы Пелекейки был счастлив. Поэтому щас пойдешь и принесешь ему целую охапку огнецвета, причем очень-очень быстро!", completion = "Воин! Пелекейки просто счастлив. Сейчас он заберет эти цветочки и сложит их в коробку, чтоб не попортились. Уж Пелекейки присмотрит, чтоб их употребили на всякие военные штуки, а не на какую-нибудь дребедень. А если добудешь еще цветочков, сразу же тащи Пелекейки, ему это всяко понадобится.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8581] = {title = "Орде все еще не хватает огнецвета!", objective = "Пелекейки знает, что ты хочешь помочь, ага. Принеси побольше огнецвета, и он будет счастлив. Пелекейки сделает из цветочков большие-большие бомбы и очень повеселится, когда они упадут на всяких жучков в Ан'Кираже. Но для этого Пелекейки нужен огнецвет, ага, |3-6(Шаман).\n\nТак что давай тащи его Пелекейки, и поживее. Приноси столько же, сколько и в прошлый раз, и Пелекейки будет доволен.", description = nil, progress = "Пелекейки знает, что ты хочешь помочь, ага. Принеси побольше огнецвета, и он будет счастлив. Пелекейки сделает из цветочков большие-большие бомбы и очень повеселится, когда они упадут на всяких жучков в Ан'Кираже. Но для этого Пелекейки нужен огнецвет, ага, |3-6(Шаман).\n\nТак что давай тащи его Пелекейки, и поживее. Приноси столько же, сколько и в прошлый раз, и Пелекейки будет доволен.", completion = "Ты случайно не шутишь, |3-6(Шаман)? Ты принес Пелекейки огнецвет так быстро? Сейчас-ка, дружище, Пелекейки его посчитает. Пелекейки так счастлив, он думает, что ты лучший собиратель огнецвета, ага. Скорей бы началась война с Ан'Кираем, уж мы бы позажигали в Силитусе, так ведь, братище?", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8582] = {title = "Орде не хватает лилового лотоса!", objective = "Принесите 20 цветков лилового лотоса аптекарю Жезель в Аллею Духов Оргриммара.", description = "Лилового лотос, <класс>, является основной составляющей множества зелий, эликсиров и масел, которые необходимы для войны в Ан'Кираже. Мы создадим бесчисленное количество самых разных снадобий. Я думаю, придется даже поэкспериментировать, чтобы исследовать все возможные способы его применения. Но для экспериментов необходимо иметь достаточно цветов в запасе.\n\nА вот это уже работа для тебя. Ступай и собери как можно больше цветков лилового лотоса. Возьмешься ради нас за это задание?", progress = "Ты так скоро возвратился |3-6(Разбойник)? А где лиловый лотос? Поторопись, а то все мои труды пойдут насмарку.", completion = "Твоя работа заслуживает одобрения, |3-6(Разбойник). Я должна рассортировать образцы и не забыть отметить, что это был твой вклад. Пока у меня не дойдут руки до этих цветов, нужно их правильно хранить. Как ты мог отметить, лотоса нужно гораздо больше, чем мы сейчас имеем. Далеко не уходи.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8583] = {title = "Орде все еще не хватает лилового лотоса!", objective = "Вынуждена констатировать тот факт, что мы все еще нуждаемся в цветах лилового лотоса, |3-6(Шаман). Мои исследования направлены на изучение новых способов применения этого реагента, и очень много уходит на то, чтобы выработать методологию.\n\nМне нужно, чтобы ты собрал как минимум еще двадцать образцов. Возвращайся, когда выполнишь это задание.", description = nil, progress = "Вынуждена констатировать тот факт, что мы все еще нуждаемся в цветах лилового лотоса, |3-6(Шаман). Мои исследования направлены на изучение новых способов применения этого реагента, и очень много уходит на то, чтобы выработать методологию.\n\nМне нужно, чтобы ты собрал как минимум еще двадцать образцов. Возвращайся, когда выполнишь это задание.", completion = "Безукоризненно точная работа, Бхт. Не могу не похвалить твое прилежание, а так же быстроту. Я лично присмотрю, чтобы ни один из этих цветков не пропал понапрасну. \n\nБольшое тебе спасибо. Если соберешь еще лилового лотоса, бегом неси ко мне.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8584] = {title = "Никогда не расспрашивай меня о моем бизнесе!", objective = "Нарайн Причуддень из Танариса хочет, чтобы вы поговорили с Диргом Быстрорубом из Прибамбасска.", description = "Обо мне вам следует знать только одно – НИКОГДА не расспрашивайте меня о моем бизнесе! Я работаю с такими материями, в которых вы просто ничего не понимаете! Например: знаете ли вы, что такое психотронный мордарий? Конечно, не знаете! Именно поэтому я – мозговой центр, а вы – добывающий придаток.\n\nКак я уже сказал, если мы хотим, чтобы у нас все получилось, нам понадобится 500-фунтовая курица.\n\nСтупайте в Прибамбасск и поговорите с Диргом Быстрорубом – он скажет, где вам искать подходящий экземпляр.", progress = nil, completion = "*Дирг чешет голову.*\n\n500-фунтовая курица? Таких не бывает! То есть, уже не бывает. Знавал я такую птицу... Черного бройлера-убийцу...\n\n*У Дирга дрожит голос.*\n\nНо его давно уже никто не видел, и эта птица теперь существует только в сказках. Однако, у меня есть идейка, от которой будет выгода нам обоим.", rewards = "Вы получите:\n\n"},
[8585] = {title = "Остров Ужаса!", objective = "Принесите тушу Лакмерана и 20 кусков вырезки химер Диргу Быстрорубу в Танарис.", description = "Легенды гласят, что у химер Острова Ужаса, что в Фераласе, самое сочное и и нежное на свете мясо! У этих химер есть главный химер, который, если его приготовить как надо сойдет за 500-фунтовую курицу. Или не сойдет.\n\nСтупай на остров Ужаса и убей лорда Лакмерана. Принеси мне его тушу. Гному схавает. А вот чтобы я был доволен, достань мне немного вырезки химеры.\n\nСделай это – и будет тебе твоя 500-фунтовая курица и кое-что сверх того.", progress = "Хммммм... Химерятинка...", completion = "Посмотри только на мраморные прожилки в этой химерятинке! Блеск!\n\nТеперь вернемся к нашим цыплятам... Посмотрим... Чтобы составить рецепт мне нужно пару минут.", rewards = "Вы получите:\n\n"},
[8586] = {title = "Отпадные химеровые отбивные Дирга", objective = "Дирг Быстроруб Прибамбасска просит, чтобы вы принесли ему 20 порций гоблинского ракетного топлива и 20 порций глубокоскальной соли.", description = "Рецепт готов! Теперь мне нужно от тебя немного ракетного топлива и глубокоскальной соли. Я займусь специями, а за счет мяса, что ты <добыл/добыла> покроем остальные расходы.\n\nКак принесешь мне то, что я просил, курица будет готова, и можешь нести ее Нарайну.", progress = "Поторопись. А то мясо протухнет.", completion = "Готово! Представляю тебе величайшее мое творение: лягающиеся химеровые отбивные Дирга!", rewards = "Вы получите:\n\nРецепт: отпадные химеровые отбивные ДиргаОтпадные химеровые отбивные Дирга"},
[8587] = {title = "Возвращение к Нарайну", objective = "Доставьте 500-фунтового цыпленка Нарайну Причудденю в Танарис.", description = "Я гоблин слова, <парень/подруга>. Вот твой 500 фунтовый цыпленок.\n\nНа кой гному 500-фунтовый цыпленок – понятия не имею...\n\n*Дирг ворчит себе под-нос что-то неразборчивое.*\n\nМожет, он спать в нем будет... Грязные гномы...", progress = "Какой восхитительный запах!", completion = "*Нарайн обеими руками рвет огромного цыпленка, зарывается носом во вкуснейшее блюдо Дирга.*\n\nМмммм... Невероятно! Никогда ничего вкуснее не едал!", rewards = "Вы получите:\n\n"},
[8588] = {title = "Орде не хватает тяжелой кожи!", objective = "Принесите 10 кусков толстой кожи специалисту по снятию шкур Джамани в Аллею Духов Оргриммара.", description = "Если уж мы собрались воевать, сначала надо подготовиться как следует, правда, дружище? Тяжелая кожа на войне – продукт первой необходимости. Она идет на все – начиная с заплаток на доспехи и заканчивая старыми добрыми ловушками.\n\nИменно поэтому ее надо собрать как можно больше. А вот это уже твоя работа, <класс>. Наточи поострее нож и добудь кож этак штук десять. Вот принесешь их, тогда и поговорим.", progress = "Я тут не в игрушки играю, так что времени трепаться с тобой у меня нет, |3-6(Воин). Слишком много толстой кожи, с которой надо возиться. Возвращайся обратно, когда соберешь хотя бы десять кусков.", completion = "О, тебе удалось достать толстую кожу. У тебя острый нож, |3-6(Воин), кожи отлично выделаны! Пойду уберу их на склад. Нужно убедиться, что твой вклад не пропадет и послужит на благо Орде. Если удастся раздобыть еще, неси сюда.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8589] = {title = "Орде все еще не хватает тяжелой кожи!", objective = "Так точно, |3-6(Охотник), мне все еще нужна толстая кожа. Запросы от генералов и интендантских служб кажутся бесконечными. Но это еще ничто по сравнению с тем, что требуют от нас хозяева дирижаблей!\n\nМне придется, пожалуй, двойную норму сдать. Шекелман, пожалуйста, принеси побольше толстой кожи, и как можно скорее!", description = nil, progress = "Так точно, |3-6(Охотник), мне все еще нужна толстая кожа. Запросы от генералов и интендантских служб кажутся бесконечными. Но это еще ничто по сравнению с тем, что требуют от нас хозяева дирижаблей!\n\nМне придется, пожалуй, двойную норму сдать. Шекелман, пожалуйста, принеси побольше толстой кожи, и как можно скорее!", completion = "Ну ты даешь, дружище! Огромное тебе спасибо за эти кожи. Каждая из них хоть немного, но приближает нас к завершению военной подготовки. Пойду сдам кожи на склад, чтобы кожевники могли приступить к работе. \n\nБольшое тебе спасибо еще раз. Если раздобудешь следующую порцию кож, то ты знаешь, где меня найти.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8590] = {title = "Орде не хватает плотной кожи!", objective = "Принесите 10 плотных кож сержанту Умале в Аллею Духов Оргриммара.", description = "Я рада, что ты <решил/решила> поговорить со мной, <класс>. Подготовка к войне в Ан'Кираже идет полным ходом, так что нам с тобой нельзя сбавлять темп работы.\n\nЯ отвечаю за сбор плотной кожи, и ее нужно действительно много, поэтому без твоей помощи никак не справиться. Если ты мне поможешь, в моем лице тебе будет благодарна вся Орда.", progress = "Что, |3-6(Жрец), уже удалось достать плотную кожу?", completion = "Ты хорошо постарался, |3-6(Жрец). Эта кожа не будет истрачена зря – она пойдет на усиление наших дирижаблей и изготовление оружия и брони. Благодарю тебя от лица всей Орды. Если тебе в своих путешествиях удастся добыть еще плотной кожи, неси ее мне. И удачи тебе.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8591] = {title = "Орде все еще не хватает плотной кожи!", objective = "Как видишь, |3-6(Маг), я все еще продолжаю собирать плотную кожу. И я снова хочу просить тебя о помощи. Обещаю, Орда не забудет приложенных тобой усилий.\n\nПостарайся достать кожу как можно скорее, для нас очень важно поскорее закончить приготовления к войне!", description = nil, progress = "Как видишь, |3-6(Маг), я все еще продолжаю собирать плотную кожу. И я снова хочу просить тебя о помощи. Обещаю, Орда не забудет приложенных тобой усилий.\n\nПостарайся достать кожу как можно скорее, для нас очень важно поскорее закончить приготовления к войне!", completion = "Ты справился, я знала, что у тебя все выйдет! От имени всей Орды я снова благодарю тебя. Твой вклад не останется незамеченным. Если достанешь еще плотной кожи, приноси ее мне. \n\nЛок'тар огар, |3-6(Маг)!", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8592] = {title = "Тиара Оракула", objective = "Принесите венец Век'нилаша, 2 идола Мудреца, 5 серебряных и 5 костяных скарабеев Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.", description = "Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.\n\nЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы власти Ан'Кираж будут служить нам.\n\nПринеси то, что мне нужно, <имя>. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТиара Оракула"},
[8593] = {title = "Брюки Оракула", objective = "Принесите целую шкуру Оуро, 2 идола Жизни, 5 золотых и 5 глиняных скарабеев Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.", description = "Хочешь доказать нам, что тебе можно доверять, <смертный/смертная>? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.\n\nСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.\n\nШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.\n\nПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nБрюки Оракула"},
[8594] = {title = "Оплечье Оракула", objective = "Принесите киражские наручники Командования, 2 идола Возрождения, 5 серебряных скарабеев и 5 скарабеев из слоновой кости Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.\n\nПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!", progress = "Тебе удалось собрать все, что мне нужно?", completion = "Я изготовил это наплечье, смертный, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.", rewards = "Вы получите:\n\nОплечье Оракула"},
[8595] = {title = "Поборники правого дела из числа смертных", objective = "Удивительно, что смертному существу вроде тебя, Вилдан, удалось одолеть Киражского владыку. Но их армия по-прежнему сильна и многочисленна. Если хочешь доказать, что ты действительно поборник нашего дела, продолжай истреблять киражей.", description = nil, progress = "Удивительно, что смертному существу вроде тебя, Вилдан, удалось одолеть Киражского владыку. Но их армия по-прежнему сильна и многочисленна. Если хочешь доказать, что ты действительно поборник нашего дела, продолжай истреблять киражей.", completion = "Мы довольны твоей службой, Вилдан. Наш договор остается в силе.", rewards = "Следующее заклинание будет наложено на вас:\n\nОтношение - храм Ан'Киража, ключевой противник"},
[8596] = {title = "Обмотки Оракула", objective = "Принесите киражские наручники Командования, 2 идола Смерти, 5 бронзовых и 5 золотых скарабеев Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.\n\nПринеси мне киражские наручники Господства и еще несколько компонентов, и я создам для тебя потрясающие сапоги.\n\nУвидишь, насколько они окажутся полезны в схватке с врагом.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nОбмотки Оракула"},
[8597] = {title = "Драконий язык для чайников", objective = "Найдите книгу Нарайна Причудденя на острове в Южных Морях.", description = "Я так и знал, что однажды эта книга мне пригодится! И я в своей мудрости и и предусмотрительности приготовил для нее укромное хранилище.\n\nНе беспокойтесь, это место никто и никогда не найдет! Только для того, чтобы туда добраться, мне понадобился вертолет. Увы, я потерпел крушение на берегу по дороге домой. Но именно в результате этого несчастного случая я обрел сверхгномские способности!\n\nНайдите мой разбитый вертолет на Последнем берегу и плывите оттуда к югу! Нужное место узнаете с первого взгляда!", progress = nil, completion = "Книга пропала! На куче земли лежит записка.", rewards = "Вы получите:\n\n"},
[8598] = {title = "вЫкУП", objective = "Отнесите письмо с требованием выкупа to Нарайну Причудденю в Танарис.", description = "*Текст записки оттиснут на пергаменте различными шрифтами.*\n\nТвоя драгоценная книга у нас, гном. Ежели хочешь снова ее увидеть, делай как сказано.\n\n*Дальше идет список инструкций на три страницы.*\n\nНеси деньги и приходи один!", progress = "Ну, в чем дело?", completion = "*Нарайн багровеет.*\n\nПохитили... мою... книгу, книгокрады!!! Я покажу им, как попадаться под руку гному с паранормальным способностями!", rewards = "Вы получите:\n\n"},
[8599] = {title = "Любовная песнь для Нарайна", objective = "Отнесите любовное послание Меридит Нарайну Причудденю в Танарис.", description = "Нечасто у меня бывают гости. Говоря по чести, последний раз это было тогда, когда я спасла этого миленького, сладенького гномика из-под обломков разбитого ветролета.\n\n*Меридит смотрит вдаль, погрузившись в воспоминания.*\n\nТы его знаешь? Нарайн? Нарайн Причуддень? О, как бы я была благодарна, если бы кто-нибудь доставил ему письмо от меня. Я просто должна рассказать ему о своих чувствах! Я знаю, это любовь! Я точно знаю!\n\nНе можешь ли ты доставить это письмецо Нарайну? Я век буду благодарна тебе!", progress = "От вас рыбой несет!", completion = "Что!?\n\n*Нарайн начинает суетиться.*\n\nНу, хммм... От меня-то вы чего хотите??? Она же рыба! РЫБА, говорю вам! А я гном. У нас все равно ничего бы не вышло.", rewards = "Вы получите:\n\n"},
[8600] = {title = "Орде не хватает прочной кожи!", objective = "Принесите 10 прочных кож доктору Серратусу, который находится на аллее Духов в Оргриммаре.", description = "Я понял, что подгонка ножа по руке важна даже больше, чем острота лезвия. И самый тупой клинок способен порезать, если приложить нужное усилие. Правильно, <класс>? Думаю, у нас не будет таких проблем, ведь наши ножи всегда хорошо заточены.\n\nНу, это не важно. У меня для тебя есть дело. Достань мне побольше прочной кожи. Она нужна, чтобы Орда как следует подготовилась к войне в Ан'Кираже. Я не сомневаюсь, что ты отлично справишься, ага?", progress = "Не может же быть, чтобы срезка десяти прочных кож отняла столько времени! Может, тебе стоит наточить охотничий нож? Или я ошибся, и кожи у тебя с собой?", completion = "Прекрасно, прекрасно, ты проделал неплохую работенку, хотя некоторые из этих кож по краям обрезаны не слишком ровно. Но, без сомнений, задание выполнено, и ты получишь обещанную награду. Если вдруг раздобудешь еще прочной кожи, то тащи ее мне поскорее.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8601] = {title = "Орде все еще не хватает прочной кожи!", objective = "Война в Ан'Кираже неотвратимо приближается, и приготовления идут полным ходом, |3-6(Разбойник). Мы не должны снижать темп подготовки. По крайней мере, я не хочу, чтобы это случилось по моей вине. Достань мне еще одну стопку прочной кожи. Я буду крайне признателен, если ты быстро разберешься с этой проблемой, Арт.", description = nil, progress = "Война в Ан'Кираже неотвратимо приближается, и приготовления идут полным ходом, |3-6(Разбойник). Мы не должны снижать темп подготовки. По крайней мере, я не хочу, чтобы это случилось по моей вине. Достань мне еще одну стопку прочной кожи. Я буду крайне признателен, если ты быстро разберешься с этой проблемой, Арт.", completion = "Тренировка, тренировка и еще раз тренировка. Хорошо заточенный нож и умение им пользоваться еще не раз сослужат тебе добрую службу, Арт. Похоже, края этих кож стали ровнее, чем было вначале. Ты купил себе новый нож? \n\nВ любом случае, большое спасибо за потраченные силы. Твой вклад не останется незамеченным, уж будь уверен. Если вдруг сыщещь еще прочной кожи, приходи узнать, не нужна ли она мне.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8602] = {title = "Наплечье Зовущего бурю", objective = "Принесите киражские наручники Господства, 2 идола Жизни, 5 золотых и 5 хрустальных скарабеев Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.\n\nПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nНаплечье Зовущего бурю"},
[8603] = {title = "Одеяние Оракула", objective = "Принесите броню Древнего Бога, 2 идола Смерти, 5 каменных и 5 хрустальных скарабеев Ветсере в Ан'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.", description = "Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.\n\nВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.\n\nКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nОдеяние Оракла"},
[8604] = {title = "Орде не хватает шерстяных бинтов!", objective = "Принесите 20 шерстяных бинтов целителю клана Долгий Бег в Аллею Духов Оргриммара.", description = "Приветствую, <класс>. Мне поручено собирать шерстяные бинты для подготовки к войне в Ан'Кираже. К сожалению, на поле боя солдаты не могут рассчитывать, что лекари успеют добраться сразу до всех. Поэтому мы должны уделить как можно больше внимания оказанию первой помощи.\n\nЕсли у тебя есть время, помоги мне собрать шерстяные бинты. Принеси их сюда, а я позабочусь, чтобы тебе выдали положенное вознаграждение.", progress = "О, |3-6(Жрец), тебе уже удалось раздобыть бинты? Так быстро?", completion = "Прими мою благодарность, |3-6(Жрец), и вместе с ней – благодарность всей Орды. Если тебе еще попадутся шерстяные бинты, неси их мне. А пока – да хранят тебя предки!", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8605] = {title = "Орде все еще не хватает шерстяных бинтов!", objective = "Рад снова тебя видеть, |3-6(Воин). Мы продолжаем трудиться в поте лица, и мне опять нужна помощь в сборе шерстяных бинтов. Если ты нам поможешь, я буду крайне благодарен. В прошлых битвах из-за недостатка первой помощи погибло слишком много хороших солдат. Я никогда не прощу себе, если подобное случится еще раз.", description = nil, progress = "Рад снова тебя видеть, |3-6(Воин). Мы продолжаем трудиться в поте лица, и мне опять нужна помощь в сборе шерстяных бинтов. Если ты нам поможешь, я буду крайне благодарен. В прошлых битвах из-за недостатка первой помощи погибло слишком много хороших солдат. Я никогда не прощу себе, если подобное случится еще раз.", completion = "Ты знаешь, что такое настоящее благородство, Тащиалеша! Я прослежу, чтобы эти бинты попали в нужные руки. Прими мою благодарность и благодарность Орды.\n\nСтупай с миром и обязательно возвращайся, если у тебя будут лишние шерстяные бинты. Нам понадобится вся помощь, которая только возможна.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8606] = {title = "Утка!", objective = "Нарайн Причуддень из Танариса хочет, чтобы вы отправились в Зимние кючи и сбросили мешок с золотом в условленной точке, указанной книгокрадами.", description = "Меня посетила гениальная мысль! Вот что мы сделаем. Я насыплю в мешок камней, а вы осуществите сброс. Да. знаю, я должен доставить выкуп лично – я и доставлю, типа того.\n\n*Нарайн меряет вас взглядом.*\n\nСойдете. Берите этот тюрбан, одежду и мешок с камнями и направляйтесь к условленной точке сброса в Зимних ключах.\n\nВ этом специальном наборе все, что вам нужно. Когда они высунут нос, чтобы забрать выкуп, задайте им перцу! Будут знать, как наезжать на Нарайна!", progress = nil, completion = "А вдруг мы недооценили этих книгокрадов?", rewards = "Вы получите:\n\n"},
[8607] = {title = "Орде не хватает бинтов из магической ткани!", objective = "Принесите 20 бинтов из магической ткани госпоже Кэллоу в Аллею Духов Оргриммара.", description = "Ты действительно хочешь помочь мне в сборе материалов, за которые я отвечаю? Отлично! Бинты из магической ткани нужны мне любой ценой, я имею в виду, в буквальном смысле \"любой ценой\". Хорошо бы свежие, но это совершенно не обязательно. Когда добудешь их, <класс>, возвращайся ко мне, я прослежу, чтобы тебя соответственным образом наградили.", progress = "Пожалуйста, не подведи, это поставит меня в крайне неудобное положение. Возвращайся с бинтами из магической ткани как только сможешь.", completion = "Удивительно, но все в порядке. Возможно, я недооценила твои способности, |3-6(Воин). Все возможно. К тому же, задание было несложное, а награда гораздо больше, чем следует. Впрочем, не бери в голову. Если хочешь в самом деле доказать, чего стоишь, ступай и принеси еще бинтов из магической ткани.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8608] = {title = "Орде опять не хватает бинтов из магической ткани!", objective = "Ты вернулся? Занятно. Как можно заметить, я все еще собираю материалы для так называемой ан'киражской военной кампании. Это означает, что мне опять нужны волшебные бинты. С нетерпением жду твоего возвращения, |3-6(Воин).", description = nil, progress = "Ты вернулся? Занятно. Как можно заметить, я все еще собираю материалы для так называемой ан'киражской военной кампании. Это означает, что мне опять нужны волшебные бинты. С нетерпением жду твоего возвращения, |3-6(Воин).", completion = "Просто поразительно, |3-6(Воин), тебе опять все удалось! Ну, говорят, что у меня нюх на помощников. Хорошо, твой вклад не останется незамеченным и ты несоменно получишь социальные льготы соразмерно своим заслугам. А пока, я полагаю, тебе следует вернуться к сбору бинтов из магической ткани, если ты действительно хочешь доказать, чего стоишь.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8609] = {title = "Орде не хватает бинтов из рунной ткани!", objective = "Принесите 20 бинтов из рунной ткани Каменному стражу Глиняному Копыту в Аллею Духов Оргриммара.", description = "Альянс и Орда готовятся к войне в Ан'Кираже, идя встречными курсами. Просто удивительно, что они собираются воевать не друг с другом, а с силитидами, какая бы сила ни стояла за ними. Не менее удивительно, что обе стороны вносят свой вклад в заготовку военных ресурсов в достаточном количестве.\n\nЯ отвечаю за сбор бинтов из рунной ткани, для оказания первой помощи. Но одна я точно не справлюсь. Помоги мне, <класс>, я буду очень признательна.", progress = "Я думаю, война скоро начнется, |3-6(Жрец). Хорошо, что ты нашел время позаботиться о наших общих нуждах. Тебе уже удалось достать бинты из рунной ткани?", completion = "Орда в долгу перед тобой, |3-6(Жрец). Спасибо тебе за то, что ты для нас сделала, мы сохраним твои поступки в своем сердце. Я должна складировать эти бинты и посчитать, насколько мы приблизились к выполнению цели. Если получится, добудь еще бинтов из рунной ткани и возвращайся ко мне.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8610] = {title = "Орде все еще не хватает бинтов из рунной ткани!", objective = "Близится время, когда мы очертя голову кинемся в бой и пройдем огнем и мечом по всему Ан'Киражу, |3-6(Охотник). Но сначала мы должны накопить силы и как следует подготовиться ко встрече с насекомыми, которые там засели, и их хозяевами.\n\nРаз уж ты пришел сюда, значит хочешь внести очередное пожертвование на нужды нашей армии? Мне нужны бинты из рунной ткани. Принеси мне их как можно скорее.", description = nil, progress = "Близится время, когда мы очертя голову кинемся в бой и пройдем огнем и мечом по всему Ан'Киражу, |3-6(Охотник). Но сначала мы должны накопить силы и как следует подготовиться ко встрече с насекомыми, которые там засели, и их хозяевами.\n\nРаз уж ты пришел сюда, значит хочешь внести очередное пожертвование на нужды нашей армии? Мне нужны бинты из рунной ткани. Принеси мне их как можно скорее.", completion = "С твоей стороны это очень бескорыстный поступок, Грагхар. Может быть, именно он спасет жизнь многим бойцам нашей армии в Ан'Кираже. Орда в долгу перед тобой. Если сумеешь достать еще бинтов из рунной ткани, пожалуйста, неси их мне.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8611] = {title = "Орде не хватает постных стейков из волчатины!", objective = "Принесите 20 постных стейков из волчатины кровостражу Сыросмолла в Аллею Духов Оргриммара.", description = "Я здесь не просто так загораю, <класс>. Подготовка к войне – дело нешуточное! Если мы хотим передавить киражских тараканов, надо приложить массу усилий, в том числе к заготовке провианта.\n\nМеня назначили ответственным за засолку постных стейков из волчатины. Однако не могу же я разорваться на части – бегать за волками по лесам и обеспечивать хранение и учет мяса одновременно. Так что это тебе придется добыть волчатины и приготовить ее, как надо, а потом ты принесешь ее мне. Все понятно?", progress = "Что, уже наготовил волчатины, |3-6(Воин)? Мне не важно, если они будут пережаренные или переперченные, главное, чтобы их можно было жевать и чтобы они оказались у меня побыстрее!", completion = "О, это мясо неплохо выглядит. Сейчас я его засолю и уберу на хранение. Надеюсь, до войны оно доживет свежим. \n\nСпасибо за вклад в наше общее дело, |3-6(Воин). А пока – как насчет того, чтобы принести мне еще порцию стейков?", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8612] = {title = "Орде все еще не хватает постных стейков из волчатины!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8613] = {title = "Орде не хватает пятнистого желтохвоста!", objective = "Принесите 20 пятнистых желтохвостов Линдо Рыболову в Аллею Духов Оргриммара.", description = "Отличный денек для рыбалки, ага, дружище? Эта ты правильно думаешь, мне б рыбка ого как пригодилась. Орде нужна чертова куча пятнистого желтохвоста. Говорят, мы будем его хавать, когда отправимся в Ан'Кираж рубиться. Так я ответил, что всегда готов служить, ага. Тока мне, конечно, помощь понадобится. Ты как насчет помочь, <класс>?", progress = "Уже пришлепал обратно, |3-6(Воин)? И как там насчет рыбки? Помнишь, что ее надо было вкусненько приготовить, ага? Травить наших солдат сырой рыбой не годится, особенно посередь пустыни.", completion = "О, вот эт'дело. Отличный рыбец! Счас-ка я ее приберу, штоб не попортилась. Спасибо, што помог. Я так скажу, ты пока номер один по этому самому желтохвосту. Как наловишь и изготовишь еще штук двадцать, тащи сюда. Будь спок, уж я всем раззвоню о твоих подвигах!", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8614] = {title = "Орде все еще не хватает пятнистого желтохвоста!", objective = "Как вишь, рыбка нам все еще нужна. И немало, ага. Бойцы должны хорошо лопать, штобы завалить всех киражских тараканов. Так что желтохвост – эт наше все. Налови его побольше, прожарь хорошенько и тащи сюда, а уж я и вся Орда скажем тебе спасибо.", description = nil, progress = "Как вишь, рыбка нам все еще нужна. И немало, ага. Бойцы должны хорошо лопать, штобы завалить всех киражских тараканов. Так что желтохвост – эт наше все. Налови его побольше, прожарь хорошенько и тащи сюда, а уж я и вся Орда скажем тебе спасибо.", completion = "Лучший улов сезона, Мард! Отличная работенка. Вот эт' я понимаю, никаких костей в рыбе. За такого желтохвоста всякий боец спасибо скажет. Наловишь еще, тащи сюда обзательно.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8615] = {title = "Орде не хватает запеченного лосося!", objective = "Принесите 20 запеченных лососей повару Острой Шпоре в Аллею Духов Оргриммара.", description = "Подготовка к войне в Ан'Кираже – дело нешуточное, <класс>. Чтобы изготовить оружие, нужно железо, а чтобы крепко держать его в руках – провиант. Если ты не поешь пару дней, хватит ли у тебя сил поднять боевой топор, когда придет время для битвы?\n\nИменно поэтому сбор провизии не менее важен, чем все остальное. Я занимаюсь заготовками запеченного лосося. Он хорошо хранится и обладает отличными питательными свойствами. Ну что, поможешь мне, <класс>?", progress = "Ну как, удалось раздобыть рыбу, |3-6(Воин)? Помни, что она должна быть хорошо приготовлена. К сожалению, сырая рыба мне без надобности.", completion = "Большое спасибо, что помог мне с заготовкой рыбы, |3-6(Воин). Очень многим нет никакого дела до подготовки к войне, их интересует только, как бы набить свои карманы. Они недостойны благорасположения Орды, в отличие от тебя. Пусть твое сердце исполнится гордости за свои бескорыстные деяния. \n\nПрими еще раз мою благодарность. Если найдешь время, чтобы еще раз помочь нам, буду очень признателен.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8616] = {title = "Орде все еще не хватает запеченного лосося!", objective = "В прошлый раз ты принес просто отличную запеченную рыбу, |3-6(Воин). Должен признать, я не удержался и взял немного себе. Как видишь, мы еще не собрали столько, сколько нужно. Я надеюсь, ты вернулся, потому что принес еще штук двадцать?", description = nil, progress = "В прошлый раз ты принес просто отличную запеченную рыбу, |3-6(Воин). Должен признать, я не удержался и взял немного себе. Как видишь, мы еще не собрали столько, сколько нужно. Я надеюсь, ты вернулся, потому что принес еще штук двадцать?", completion = "Трудно представить, сколько времени и сил ты потратил, чтобы помочь нам, Тащиалеша. Знай, твои труды не пропадут впустую. Я благодарен тебе от имени всей Орды. Возвращайся, когда наготовишь следующую порцию рыбы.", rewards = "Вы получите:\n\nРекомендательный жетон ОрдыПрипасы для войны в Ан'Кираже"},
[8617] = {title = "Орде не хватает опаленного вулканического камня!", objective = "Принесите 50 оплавленных вулканических камней генералу Зогу в Дуротар.", description = "Пришло время и тебе поучаствовать в нашей подготовке войны в Ан'Кираже, <класс>. Прошли деньки, когда можно было беззаботно валяться на солнышке. Нынче каждый должен встать под знамена Орды и Вождя! А я, в отличие от нашего вождя, добросердечием не страдаю, уж будь <спокоен/спокойна>.\n\nТы <должен/должна> собрать военные силы своей гильдии (если состоишь в таковой) и проникнуть в Огненные Недра. Мне нужны оплавленные вулканические камни, которые можно обнаружить у тамошних обитателей. Собери столько камней, сколько сможешь, и возвращайся обратно.", progress = nil, completion = nil, rewards = nil},
[8618] = {title = "Орде все еще не хватает опаленных вулканических камней!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8619] = {title = "Старейшина Рассветень", objective = "Приятно знать, что народ этих земель все еще отдает дань уважения старшим расам. Всего хорошего, Мерандир. Прими этот знак...", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nЗаставить себя - лук\n\nВы получите:\n\nМонета Наследия"},
[8620] = {title = "Единственный способ", objective = "Найдите 8 утраченных глав из книги \"Драконий язык для чайников\" и соберите их при помощи магического книжного переплета. Принесите полную книгу \"Драконий язык для дураков: том II\" Нарайну Причудденю в Танарис.", description = "Надо было раньше собразить! Мой архивраг, Доктор Жло, взялся за старое! А теперь, благодаря вашему провалу в Зимних ключах, Доктор Жло уничтожил мою книгу! И как теперь вы будете спасать мир, герой?\n\nИз полученной мной записки я узнал, что \"Драконий язык для чайников\", том II разорван на 8 частей и разбросан по ветру! Если вы как-нибудь умудритесь найти пропавшие главы, при помощи этого магического переплета сшейте их снова и возвращайтесь ко мне.", progress = "Я надеваю штаны точно так же, как и вы – по штанине на ногу. Только когда мои штаны на мне, я делаю арканитовые буйки. Арканитовые, детка!", completion = "Фантастика. Поверить не могу, что вы прошли через барьер! Вы, часом, не машина? Будь я на вашем месте – да горел бы этот мир синим огнем!\n\nСнимаю перед вами тюрбан, сэр. Что же, доброе дело не должно остаться без награды.", rewards = "Вы получите:\n\nГномий тюрбан душевной силы"},
[8621] = {title = "Прочные ботинки Зовущего бурю", objective = "Принесите киражские наручники Господства, 2 идола Мудреца, 5 бронзовых и 5 глиняных скарабеев Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.\n\nПринеси мне киражские наручники Господства и еще несколько компонентов, и я создам для тебя потрясающие сапоги.\n\nУвидишь, насколько они окажутся полезны в схватке с врагом.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПрочные ботинки Зовущего бурю"},
[8622] = {title = "Хауберк Зовущего бурю", objective = "Принесите панцирь Древнего Бога, 2 идола мудреца, 5 серебряных и 5 костяных скарабеев Ветсере в Ан'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.", description = "Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.\n\nВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.\n\nКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nХауберк Зовущего бурю"},
[8623] = {title = "Диадема Зовущего бурю", objective = "Принесите диадему Век'лора, 2 идола Возрождения, 5 каменных и 5 хрустальных скарабеев Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.", description = "Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.\n\nЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы власти Ан'Кираж будут служить нам.\n\nПринеси то, что мне нужно, <имя>. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nДиадема Зова Бури"},
[8624] = {title = "Поножи Зовущего Бурю", objective = "Принесите шкуру гигантского песчаного червя, 2 идола Борьбы, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.", description = "Хочешь доказать нам, что тебе можно доверять, <смертный/смертная>? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.\n\nСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.\n\nШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.\n\nПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПоножи Зовущего бурю"},
[8625] = {title = "Наплечные щитки Таинства", objective = "Принесите киражские наручники Господства, 2 идола возрождения, 5 серебряных скарабеев и 5 скарабеев из слоновой кости Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.\n\nПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!", progress = "Тебе удалось собрать все, что мне нужно?", completion = "Я изготовил это наплечье, смертный, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.", rewards = "Вы получите:\n\nНаплечные щитки Таинства"},
[8626] = {title = "Прочные ботинки бойца", objective = "Принесите киражские наручники Командования, 2 идола Жизни, 5 каменных и 5 костяных скарабеев Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.\n\nПринеси мне киражские наручники Господства и еще несколько компонентов, и я создам для тебя потрясающие сапоги.\n\nУвидишь, насколько они окажутся полезны в схватке с врагом.", progress = "Тебе удалось достать то, что мне нужно, Киберка?", completion = "Поздравляю, Киберка. Тебе удалось выполнить это задание. Теперь я вижу, что ты не простая смертная. Прими эту вещь, она поможет тебе сокрушить мерзких киражей.", rewards = "Вы получите:\n\nПрочные ботинки бойца"},
[8627] = {title = "Кираса Мстителя", objective = "Принесите кирасу Древнего Бога, 2 идола Мудреца, 5 серебряных и 5 костяных скарабеев Ветсере в Ан'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.", description = "Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.\n\nВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.\n\nКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКираса Мстителя"},
[8628] = {title = "Корона Мстителя", objective = "Принесите диадему Век'лора, два идола Возрождения, пять каменных и пять хрустальных скарабеев Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.", description = "Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.\n\nЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы власти Ан'Кираж будут служить нам.\n\nПринеси то, что мне нужно, <имя>. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКорона Мстителя"},
[8629] = {title = "Набедренники Мстителя", objective = "Принесите шкуру гигантского песчаного червя, два идола Борьбы, пять бронзовых скарабеев и пять скарабеев из слоновой кости Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.", description = "Хочешь доказать нам, что тебе можно доверять, <смертный/смертная>? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.\n\nСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.\n\nШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.\n\nПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nНабедренники Мстителя"},
[8630] = {title = "Наплечье Мстителя", objective = "Принесите киражские наручники Господства, два идола Жизни, пять хрустальных и пять золотых скарабеев Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "У нас говорят, что вычурные наплечные доспехи, которую носят смертные, были изначально созданы в подражание крыльям драконов.\n\nПринеси мне наручники, принадлежащие киражским владыкам, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nНаплечье Мстителя"},
[8631] = {title = "Поножи Таинства", objective = "Принесите целую шкуру Оуро, 2 идола Мудреца, 5 серебряных и 5 костяных скарабеев Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.", description = "Хочешь доказать нам, что тебе можно доверять, <смертный/смертная>? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.\n\nСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.\n\nШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.\n\nПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПоножи Таинства"},
[8632] = {title = "Венец Таинства", objective = "Принесите венец Век'нилаша, 2 идола Ночи, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.", description = "Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.\n\nЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы мощи Ан'Киража будут служить нам.\n\nПринеси то, что мне нужно, <имя>. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nВенец Таинства"},
[8633] = {title = "Одеяния Таинства", objective = "Принесите броню Древнего Бога, 2 идола Солнца, 5 золотых и 5 глиняных скарабеев Ветсере в Ан'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.", description = "Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.\n\nВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.\n\nКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nОдеяния Таинства"},
[8634] = {title = "Сапоги Таинства", objective = "Принесите киражские наручники Господства, 2 идола Солнца, 5 серебряных и 5 хрустальных скарабеев Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.\n\nПринеси мне киражские наручники Господства и еще несколько компонентов, и я создам для тебя потрясающие сапоги.\n\nУвидишь, насколько они окажутся полезны в схватке с врагом.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСапоги Таинства"},
[8635] = {title = "Старейшина Камнепад", objective = "Легенды растут из семени давних битв. Ты живешь в эпоху героев, юноша. Да укоренится твоя легенда и да принесет она обильный плод.\n\nВсего тебе наилучшего, Манаштиль. Прими от меня этот знак...", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nЗаставить себя - лук\n\nВы получите:\n\nМонета Наследия"},
[8636] = {title = "Старейшина Громоскал", objective = "Плоть, материя жизни, смертна и рано или поздно обратится в прах. Дух же вечен. Всего наилучшего тебе, Димиллион. Прими этот знак...", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nЗаставить себя - лук\n\nВы получите:\n\nМонета Наследия"},
[8637] = {title = "Сапоги Смертеторговца", objective = "Принесите киражские наручники Командования, 2 идола Борьбы, 5 хрустальных и 5 костяных скарабеев Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.\n\nПринеси мне киражские наручники Господства и еще несколько компонентов, и я создам для тебя потрясающие сапоги.\n\nУвидишь, насколько они окажутся полезны в схватке с врагом.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСапоги Смертоносца"},
[8638] = {title = "Жилет Смертеторговца", objective = "Принесите панцирь Древнего Бога, 2 идола Борьбы, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Ветсере в Ан'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.", description = "Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.\n\nВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.\n\nКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЖилет Торговца Смертью"},
[8639] = {title = "Шлем Смертеторговца", objective = "Принесите диадему Век'лора, 2 идола Войны, 5 золотых и 5 глиняных скарабеев Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.", description = "Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.\n\nЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы мощи Ан'Киража будут служить нам.\n\nПринеси то, что мне нужно, <имя>. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nШлем Смертоносца"},
[8640] = {title = "Поножи Смертеторговца", objective = "Принесите целую шкуру Оуро, 2 идола Ночи, 5 каменных и 5 хрустальных скарабеев Кандострасу в Ан'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздрому.", description = "Хочешь доказать нам, что тебе можно доверять, <смертный/смертная>? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.\n\nСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни.\n\nШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.\n\nПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПоножи Смертоносца"},
[8641] = {title = "Наплеч Смертеторговца", objective = "Принесите киражские наручники Командования, 2 идола Солнца, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Андоргосу в Ан'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.", description = "У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.\n\nПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nНаплеч Смертоносца"},
[8642] = {title = "Старейшина Среброжил", objective = "Приятно знать, что народ этих земель все еще отдает дань уважения старшим расам. Всего хорошего, Медведик. Прими этот знак...", description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nЗаставить себя - лук\n\nВы получите:\n\nМонета Наследия"},
