[9082] = {title = "Рукавицы костяной косы", objective = "Роган Убийца из Часовни Последней Надежды в Восточных Чумных землях готов создать рукавицы костяной косы, если вы принесете ему следующее: 1 испоганенные рукавицы, 8 обрывков кожи, 1 слиток арканита и 5 обработанных грубых шкур.", description = "Если ты хочешь броню костяной косы, принеси мне все материалы.\n\nСтупай в Наксрамас, огромный парящий город смерти, и набери там испоганенных доспехов и обрывков кольчуг. Принеси их мне вместе с остальными материалами, и, считай, Костяная коса – твоя. Ах да, не забудь и мне отстегнуть за работу... Кости я тебе обеспечу.", progress = "Из чего мне делать доспехи? Неси материалы!", completion = "Эти рукавицы сами все равно, что оружие. Носи их с гордостью!", rewards = "Вы получите:\n\nРукавицы костяной косы"},
[9083] = {title = "Воинский пояс костяной косы", objective = "Роган Убийца из Часовни Последней Надежды в Восточных Чумных землях готов создать воинский пояс костяной косы, если вы принесете ему следующее: 1 испоганенный воинский пояс, 8 обрывков кожи, 5 обработанных грубых шкур, 1 кристалл-источник и 15 золотых.", description = "Если ты хочешь броню костяной косы, принеси мне все материалы.\n\nСтупай в Наксрамас, огромный парящий город смерти, и набери там испоганенных доспехов и обрывков кольчуг. Принеси их мне вместе с остальными материалами, и, считай, Костяная коса – твоя. Ах да, не забудь и мне отстегнуть за работу... Кости я тебе обеспечу.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nВоинский пояс костяной косы"},
[9084] = {title = "Наручи костяной косы", objective = "Роган Убийца из Часовни Последней Надежды в Восточных Чумных землях готов создать наручи костяной косы, если вы принесете ему следующее: 1 испоганенные наручи, 6 обрывков кожи, 1 слиток арканита, 2 обработанных грубых шкуры и 10 золотых.", description = "Если ты хочешь броню костяной косы, принеси мне все материалы.\n\nСтупай в Наксрамас, огромный парящий город смерти, и набери там испоганенных доспехов и обрывков кольчуг. Принеси их мне вместе с остальными материалами, и, считай, Костяная коса – твоя. Ах да, не забудь и мне отстегнуть за работу... Кости я тебе обеспечу.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nНаручи костяной косы"},
[9085] = {title = "Тени Рока", objective = "Идите к кругу призыва и убейте Тень Рока, затем возвращайтесь к командиру Томасу Элерану в Часовню Последней Надежды в Восточные Чумные земли.", description = "После разрушения защиты кругов призыва Плети, которые появляются в тех местах, где происходит нападение, тебе придется сразиться с послушниками, которые охраняют эти круги.\n\nЧестно говоря, это не живые существа, а тени, одни из самых устрашающих созданий Короля-лича. Их можно обнаружить с помощью некротических рун, которые они носят при себе, а затем уничтожить посредством магии или силой оружия.", progress = nil, completion = "Превосходная работа, Синдрия. Теперь, когда тени уничтожены, остается лишь подождать, пока Король-лич решит отозвать свои некрополи и оставит нас в покое.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБлагословенное волшебное маслоОсвященное точило"},
[9086] = {title = "Мундир сновидца", objective = "Райн из Часовни Последней Надежды в Восточных Чумных землях готова создать мундир сновидца, если вы принесете ей следующее: 1 испоганенный мундир, 25 обрывков кожи, 6 обработанных грубых шкур и 2 кристалла-источника.", description = "В последней войне пало немало героев, да и сегодня все больше славных бойцов погибает под натиском Плети. С тел погибших срывают доспехи, уносят в Наксрамас и используют для неведомых, но несомненно гнусных, целей.\n\nВерни испоганенные доспехи и их обрывки, принеси все остальные материалы, и я сделаю для тебя броню сновидца.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМундир сновидца"},
