[9298] = {title = "reuse", objective = "Deliver the Dim Necrotic Stone to SOMEONE.", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", progress = nil, completion = nil, rewards = nil},
[9299] = {title = "Записка с фронта", objective = "Отнесите потертую записку хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.", description = "Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...", progress = "Да? Что у тебя там?", completion = "Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.", rewards = "Вы получите:\n\n"},
[9300] = {title = "Страничка с фронта", objective = "Отнесите разорванную страницу хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.", description = "Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...", progress = "Да? Что у тебя там?", completion = "Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.", rewards = "Вы получите:\n\n"},
[9301] = {title = "Конверт с фронта", objective = "Отнесите конверт, запятнанный кровью, хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.", description = "Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...", progress = "Да? Что у тебя там?", completion = "Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.", rewards = "Вы получите:\n\n"},
[9302] = {title = "Послание с фронта", objective = "Отнесите смятое послание хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.", description = "Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...", progress = "Да? Что у тебя там?", completion = "Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.", rewards = "Вы получите:\n\n"},
[9304] = {title = "Документ с фронта", objective = "Отнесите испачканный документ хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.", description = "Это письмо найдено у одного из множества приспешников Плети, убитых тобой. Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время. Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется в дальнейшем изучении данного письма...", progress = "Да? Что у тебя там?", completion = "Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.", rewards = "Вы получите:\n\n"},
[9310] = {title = "Тусклый некротический кристалл", objective = "Отнесите тусклый некротический кристалл лейтенанту Рукагу во внутренний двор Подгорода.", description = "На трупе павшей твари вы находите кристалл, излучающий тусклую некротическую энергию.", progress = "Я могу чем-нибудь помочь?", completion = "Это было у одной из тварей, напавших на город?\n\nМы слышали о лагерях-некрополях, призванных Плетью. Я подозреваю, что они хотят создать такой лагерь в Подгороде. Впредь мы должны быть бдительными..", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБлагословенное волшебное маслоОсвященное точило"},
[9317] = {title = "Освященное точило", objective = "Если ты принесешь мне восемь некротических рун, отобрав их у захватчиков из Плети, я дам тебе освященное точило. Оно способно помочь тебе в борьбе против приспешников Короля-лича.", description = nil, progress = "Если ты принесешь мне восемь некротических рун, отобрав их у захватчиков из Плети, я дам тебе освященное точило. Оно способно помочь тебе в борьбе против приспешников Короля-лича.", completion = "Спасибо, Гуреус. Вот освященное точило. Используй его с толком.", rewards = "Вы получите:\n\nОсвященное точило"},
[9318] = {title = "Благословенное волшебное масло", objective = "В обмен на некротические руны Плети Серебряный Рассвет дарует тебе один фиал благословенного волшебного масла.", description = nil, progress = "В обмен на некротические руны Плети Серебряный Рассвет дарует тебе один фиал благословенного волшебного масла.", completion = "Надеюсь, этот предмет пригодится тебе в грядущих битвах.", rewards = "Вы получите:\n\nБлагословенное волшебное масло"},
[9319] = {title = "Свет в темных местах", objective = "Найдите костры, размещенные в Пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени.", description = "Мы не единственные, кто справляет сегодня праздник, <имя>. Все создания, все народы возжигают пламя. Даже в самых темных уголках сегодня горят огни.\n\nЕсли хочешь увидеть их своими глазами, спустись в глубины. Отыщи костры, горящие в Стратхольме, Некроситете, у огров в Забытом Городе и в залах самого Пика Черной горы. Я буду ждать твоего возвращения.", progress = nil, completion = "Твоя сущность поет, переполненная энергией найденного тобой пламени, Поняха. Огонь, с которым тебе пришлось столкнуться, весьма силен, и тот, кто наделен нужным знанием, может обуздать эту силу...\n\n*Хранитель праздничных костров бормочет заклинание на странном, загадочном языке, затем достает сияющую бутыль.*\n\nА, вот. Пусть это озарит твой путь, куда бы он ни лежал.", rewards = "Вы получите:\n\nЗачарованное пламяПылающий цвет"},
[9320] = {title = "Сильнейшее зелье маны", objective = "Помимо других поставок, у нас есть немного сильнейших зелий маны, которые могут тебе пригодиться. Я дам тебе одну порцию зелья в обмен на пятнадцать некротических рун.", description = nil, progress = "Помимо других поставок, у нас есть немного сильнейших зелий маны, которые могут тебе пригодиться. Я дам тебе одну порцию зелья в обмен на пятнадцать некротических рун.", completion = "Вот, Корольшам. Но соблюдай осторожность. Нас не так много, чтобы мы могли позволить себе большие потери в бою.", rewards = "Вы получите:\n\nСильнейшее зелье маны"},
[9321] = {title = "Хорошее лечебное зелье", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nСильнейшее лечебное зелье"},
[9322] = {title = "Костры Калимдора", objective = "Посетите лагеря праздника Огненного солнцеворота, размещенные в Азшаре, Силитусе, Кратере Ун'Горо и Зимних Ключах, затем вернитесь к хранителю праздничного пламени.", description = "Праздник Огненного солнцеворота отмечается повсюду в Азероте, и различные регионы Калимдора – не исключение. Похоже, тебе приходилось много путешествовать, и у тебя есть опыт в странствиях. \n\nПраздник Середины лета нельзя оценить должным образом, пока не увидишь горячие огни синего цвета. Зажигаются костры в холодных западных регионах Зимних Ключей, в северо-восточной Азшаре, возле Покоя Доблестных в пустошах Силитуса и у входа в обширный ркатер Ун'Горо. Возвращайся по завершении путешествия.", progress = nil, completion = "Твой дух сияет жаром костров Калимдора. Разве это пламя не воодушевляет тебя?\n\nКогда тебя покинут силы, быть может, это поможет тебе вновь возжечь этот жар.", rewards = "Вы получите:\n\nПепельные наручиПылающий цвет"},
[9323] = {title = "Костры Восточных Королевств", objective = "Посетите лагеря Праздника Огня, размещенные в Выжженных землях, Восточных Чумных землях, во Внутренних землях и Тлеющем ущелье, затем поговорите с хранителем праздничного пламени.", description = "Огненный праздник распространился по всем землям, <класс>. Нет ни единого уголка, куда не проник бы жар этого празднества, а самые сильные огни пылают ярко-синим цветом. Найди их.\n\nОдин из них можно обнаружить к северу от Пика Черной горы. Другие размещаются в глубине территории Восточных Чумных земель возле полуразрушенного города, вдоль дороги, ведущей на утесы гористых Внутренних Земель, и на пути к Темный портал в Выжженных землях.\n\nВозвращайся, когда завершишь свое путешествие.", progress = nil, completion = "А, вот и ты. Чуть больше усталости, чуть больше пыли, но внутри сияет свет! В это время года жар касается нас всех и объединяет нас. Сама твоя суть сияет силой костров, которых тебе довелось касаться.\n\nО, но в эти дни просвещение считается довольно ничтожным вознаграждением за выполнение задания, как мне кажется. Так прими это и наслаждайся праздником.", rewards = "Вы получите:\n\nОплечье Праздника ОгняПылающий цвет"},
[9324] = {title = "Похищение пламени Оргриммара", objective = "Верните Пламя Оргриммара хранителю мудрости Праздника.", description = "Это пламя, похищенное из сердца Оргриммара, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПылающий цвет"},
[9325] = {title = "Похищение пламени Громового Утеса", objective = "Верните Пламя Громового Утеса хранителю мудрости Праздника.", description = "Это пламя, похищенное у шамана Громового Утеса, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПраздничный грогПылающий цвет"},
[9326] = {title = "Похищение пламени Подгорода", objective = "Верните Пламя Подгорода хранителю мудрости Праздника.", description = "Это пламя, похищенное из руин над Подгородом, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...", progress = "Ты поистине светишься, |3-6(ночной эльф). Что у тебя там?", completion = "Хм... Какой странный огонь! Он слаб, почти угасает, но его жар силен. Ты говоришь, он из Подгорода? Поразительно. Кто знает, чего мы можем достичь, заполучив пламя из всех трех городов?", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБузинный пирогПоджаренная булочкаЛетняя колбаскаПеченый чоко-пай\n\nВы также получите:\n\nПылающий цвет"},
[9330] = {title = "Похищение пламени Штормграда", objective = "Верните Пламя Штормграда Праздничному Сказителю.", description = "Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...", progress = "Ты поистине светишься, |3-6(тролль). Что у тебя там?", completion = "И это ярко горящее пламя... ты говоришь, оно из Штормграда? Замечательно! Должно быть, это было славное приключение! Конечно же, я заплачу тебе за это. Если ты найдешь еще что-нибудь подобное, обязательно приходи поговорить со мной.", rewards = "Вы получите:\n\nПраздничный грогПылающий цвет"},
[9331] = {title = "Похищение пламени Стальгорна", objective = "Верните Пламя Стальгорна Праздничному Сказителю.", description = "Это пламя, похищенное из сердца Стальгорна, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...", progress = "Ты поистине светишься, |3-6(тролль). Что у тебя там?", completion = "Это сильное пламя, должно быть, явилось из залов Стальгорна; оно столь же неукротимо, как сами дворфы. Отличная добыча, Поняха. Если бы у меня был огонь из других городов... а, неважно. Вот твоя плата.", rewards = "Вы получите:\n\nПылающий цвет"},
[9332] = {title = "Похищение пламени Дарнасса", objective = "Верните пламя Дарнасса праздничному сказителю.", description = "Это пламя, похищенное с берегов Тельдрассила, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...", progress = "Ты поистине светишься, |3-6(тролль). Что у тебя там?", completion = "Этот огонь полон древней скорби, Поняха. Ты говоришь, он добыт от корней Тельдрассила? Невероятно! Вот награда за твое мастерство. Возвращайся ко мне, если найдешь еще что-либо подобное; возможно, у меня найдется применение этому.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБузинный пирогПоджаренная булочкаЛетняя колбаскаПеченый чоко-пай\n\nВы также получите:\n\nПылающий цвет"},
[9333] = {title = "Перчатки Серебряного Рассвета", objective = "Если принесешь мне тридцать некротических рун, я подарю тебе защитные перчатки для рук, по твоему выбору. Они оказались очень ценными в борьбе против нежити Плети", description = nil, progress = "Если принесешь мне тридцать некротических рун, я подарю тебе защитные перчатки для рук, по твоему выбору. Они оказались очень ценными в борьбе против нежити Плети", completion = "Хорошая работа, Корольшам. Возьми выбранные тобой защитные перчатки в благодарность за твои усилия.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерчатки искоренения нежитиПовязки истребления нежитиБоевые рукавицы истребления нежитиРукавицы истребления нежити"},
[9334] = {title = "Благословенное волшебное масло", objective = "В обмен на некротические руны Плети Серебряный Рассвет дарует тебе один фиал благословенного волшебного масла.", description = nil, progress = "В обмен на некротические руны Плети Серебряный Рассвет дарует тебе один фиал благословенного волшебного масла.", completion = "Надеюсь, этот предмет пригодится тебе в грядущих битвах.", rewards = "Вы получите:\n\nБлагословенное волшебное масло"},
[9335] = {title = "Освященное точило", objective = "Если ты принесешь мне восемь некротических рун, отобрав их у захватчиков из Плети, я дам тебе освященное точило. Оно способно помочь тебе в борьбе против приспешников Короля-лича.", description = nil, progress = "Если ты принесешь мне восемь некротических рун, отобрав их у захватчиков из Плети, я дам тебе освященное точило. Оно способно помочь тебе в борьбе против приспешников Короля-лича.", completion = "Спасибо, Элеутерококк. Вот освященное точило. Используй его с толком.", rewards = "Вы получите:\n\nОсвященное точило"},
[9336] = {title = "Хорошее лечебное зелье", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nСильнейшее лечебное зелье"},
[9337] = {title = "Сильнейшее зелье маны", objective = "Помимо других поставок, у нас есть немного сильнейших зелий маны, которые могут тебе пригодиться. Я дам тебе одну порцию зелья в обмен на пятнадцать некротических рун.", description = nil, progress = "Помимо других поставок, у нас есть немного сильнейших зелий маны, которые могут тебе пригодиться. Я дам тебе одну порцию зелья в обмен на пятнадцать некротических рун.", completion = "Вот, Рансу. Но соблюдай осторожность. Нас не так много, чтобы мы могли позволить себе большие потери в бою.", rewards = "Вы получите:\n\nСильнейшее зелье маны"},
[9338] = {title = "Верность Кругу Кенария", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[9339] = {title = "Награда вора", objective = "Верните Пламя Штормграда (NAME)Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...", description = "Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...", progress = nil, completion = "Сегодняшние твои деяния свидетельствуют сами за себя, Поняха.\n\nЯ мало что могу дать тебе помимо этого, но у меня есть вот этот венец – дар, что соответствует ловкости и дерзости. Пусть он озарит твой путь.", rewards = "Вы получите:\n\nКорона Огненного Празднества"},
[9341] = {title = "Гербовая накидка Серебряного Рассвета", objective = "Твоя помощь в нашем деле была очень ценной, Трансмастер. Если пожелаешь, я могу сделать так, что ты получишь гербовую накидку Серебряного Рассвета. Мы гордимся тем, что ты в числе наших союзников.", description = nil, progress = "Твоя помощь в нашем деле была очень ценной, Трансмастер. Если пожелаешь, я могу сделать так, что ты получишь гербовую накидку Серебряного Рассвета. Мы гордимся тем, что ты в числе наших союзников.", completion = "Возьми эту гербовую накидку и носи его с гордостью. Быть может, твой пример побудит и других взяться за оружие, чтобы поддержать нас в борьбе против Плети.", rewards = "Вы получите:\n\nГербовая накидка Серебряного Рассвета"},
[9343] = {title = "Гербовая накидка Серебряного Рассвета", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nГербовая накидка Серебряного Рассвета"},
[9353] = {title = "Redeem iCoke Gift Box Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nSummer Gift Package"},
[9362] = {title = "Полководец Креллиан", objective = "Принесите радужную раковину верховному магу Ксилему в башню в утесах Азшары.", description = "У меня мало времени, <имя>! С помощью чар магического зрения я обнаружил мощный источник магии. Я не могу покинуть башню, поэтому прошу тебя убить мерзкое создание, завладевшее мощным артефактом. \n\nЖалкий недоумок, известный как полководец Креллиан, прячется за широкими спинами своих стражей в храме Зин-Малор. Испепели это ничтожество и принеси мне радужную раковину, которую он прячет.", progress = "Мы не можем терять не минуты! Ты принес раковину?", completion = "Должен заметить, у этой раковины странная аура. Очень хорошо, что частью твоей награды будет уникальная возможность исследовать свойства этого артефакта.", rewards = "Вы получите:\n\n"},
[9364] = {title = "Частицы магии", objective = "Наложите заклинание превращения на тварей Бича Злобы в Азшаре и убейте клонов, которые появятся несколько мгновений спустя. Убейте 50 клонов и возвращайтесь к верховному магу Ксилему в Азшару.", description = "В ходе исследований я выявил потрясающее свойство радужной раковины. \n\nВозьми раковину и наложи заклинание превращения на тварей Бича Злобы в Азшаре. Через несколько мгновений хаотическая аура раковины создаст нескольких маленьких клонов. Клонов надо убить – как можно скорее! – и тогда раковина вберет в себя их сущность. \n\nВозвращайся ко мне, когда раковина будет полна.", progress = "Ты выполнил мое поручение?", completion = "Прекрасно! Прекрасно! \n\nТеперь мы можем использовать собранную магическую силу для создания нового заклинания!", rewards = "Вы изучите:\n\nПревращение\n\nСледующее заклинание будет наложено на вас:\n\nzzOLDПолиморф: свинья\n\nВы также получите:\n\n"},
[9365] = {title = "Награда вора", objective = "Верните Пламя Штормграда (NAME)Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...Вы получите:\n\n", description = "Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКорона Огненного Празднества"},
[9367] = {title = "Праздник Огня", objective = "Прикоснитесь к пламени праздничных костров в Штормграде, Стальгорне и Дарнассе, затем поговорите с хранителем мудрости праздника в столичных городах.", description = "Вновь наступает праздник Огненного солнцеворота!\n\nКаждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажженными в наших столичных городах. По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Середине Лета.\n\nНа самом деле, если ты не против, у меня для тебя есть задание. Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах. Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!", progress = "Горят ли костры?", completion = "Превосходно! Похоже, в этом году мы избрали ответственных Хранителей праздничных костров, если огни поддерживаются так хорошо, как ты утверждаешь. Спасибо за проведенное исследование; вот, прими это как небольшой знак моей благодарности.", rewards = "Вы получите:\n\nПылающий цветПраздничный грог"},
[9368] = {title = "Праздник Огня", objective = "Прикоснитесь к пламени праздничных костров в Оргриммаре, Громовом Утесе и Подгороде, затем поговорите с Праздничным сказителем в столичных городах.", description = "Вновь наступает праздник Огненного солнцеворота!\n\nКаждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажженными в наших столичных городах. По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Огненному солнцевороту.\n\nНа самом деле, если ты не против, у меня для тебя есть задание. Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах. Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!", progress = nil, completion = "Превосходно! Похоже, в этом году мы избрали ответственных Хранителей праздничных костров, если огни поддерживаются так хорошо, как ты утверждаешь. Спасибо за проведенное исследование; вот, прими это как небольшой знак моей благодарности.", rewards = "Вы получите:\n\nПылающий цветПраздничный грог"},
[9386] = {title = "Свет в темных местах", objective = "Найдите костры, размещенные в Пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени.", description = "Неужели тебе этого так хочется? Ну что ж, если снова желаешь спуститься в глубины, я с радостью тебя вознагражу. \n\nОтыщи костры, горящие в Стратхольме, Некроситете, Забытом Городе и в залах самого Пика Черной горы. Я буду ждать твоего возвращения, <имя>.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПылающий цвет"},
[9388] = {title = "Мерцающие огни Калимдора", objective = "Посетите праздничные костры в Ясеневом лесу, Степях, на Темном Берегу и в Когтистых горах, затем поговорите с хранителем праздничного пламени.", description = "Сегодня по всему миру горит множество огней, <имя>. Сложнее всего присматривать за теми кострами, которые пылают зеленым; без присмотра они не будут гореть долго. Убедись, что изумрудные огни все еще горят в Калимдоре – пусть наш Хранитель костров успокоится.\n\nТы найдешь эти костры вблизи Кабестана в Степях, неподалеку от Меча Властителя на Темном Берегу, в Ясеневом лесу у моста около Аванпоста Среброкрылых, и поблизости от дороги на Утес Ветрорезов вдоль главного тракта в Когтистых горах.", progress = nil, completion = "Ах, так они еще горят. Какая радость! Было бы горько, если бы их пламя угасло до срока. Хорошая работа, Дворфпауэр. Прими это вместе с моим благословением.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБузинный пирогПоджаренная булочкаЛетняя колбаскаПеченый чоко-пай\n\nВы также получите:\n\n"},
[9389] = {title = "Мерцающие огни Восточных Королевств", objective = "Посетите праздничные костры в предгорьях Хиллсбрада, в Серебряном бору, Западном Крае и Болотине, затем поговорите с хранителем праздничного пламени.", description = "Во время праздника Огненного солнцеворота по всей земле традиционно зажигаются мириады огней. Кое-кто считает, что зеленое пламя является самым изящным, поскольку его труднее всего поддерживать, и оно имеет столь уникальный оттенок.\n\nУбедись, что это пламя все еще горит в Восточных королевствах, чтобы успокоить нашего хранителя огня. Эти костры размещены около Дун Модра в Болотине, поблизости от деревни Погребальных Костров в Серебряном бору, на утесах неподалеку от маяка Западного края и возле разрушенной башни в предгорьях Хиллсбрада.", progress = nil, completion = "Так ты возвращаешься, повидав изумрудное пламя, горящее в разных уголках континента... И что ты об этом думаешь? Несомненно, это редкостное и замечательное зрелище. Однако я осознаю, что весомая награда ценится больше... поэтому возьми вот это за твои труды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБузинный пирогПоджаренная булочкаЛетняя колбаскаПеченый чоко-пай\n\nВы также получите:\n\n"},
[9415] = {title = "Маршал Синяя Синестен", objective = "Поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора.", description = "Ты новобранец маршала Синестена? Ну, конечно.\n\nЧего ты ждешь? Наши солдаты умирают там, в пустыне. Правда, тебе не терпится к ним присоединиться?\n\nИди, и смотри, не присохни к песку по пути.", progress = nil, completion = "Альянсу нужна помощь всех, кто способен держать оружие. Орда регулярно получает подкрепление с северной части континента, и мы изо всех сил стараемся от них не отстать.\n\nПозволь, я объясню тебе ситуацию.", rewards = nil},
[9416] = {title = "Генерал Кирика", objective = "Поговорите с генералом Кирикой в лагере Орды рядом с Ульем Регал.", description = "Должно быть, ты <один/одна> из новобранцев генерала Кирики. Пора тебе браться за дело. В пустыне тела очень быстро портятся.\n\nДворфы ежедневно получают подкрепление, а мы не должны им уступать. Полезные ископаемые Силитуса наши!\n\nГенерал тебя проинструктирует. Не мое дело – учить тебя. Мне приказали только найти тебя.", progress = nil, completion = "Хорошо, что ты здесь, но на любезности времени нет. Я проведу инструктаж, и ты сразу отправляйся в бой.\n\nСлушай.", rewards = nil},
[9419] = {title = "Истощение пустыни", objective = "Найдите и принесите силитист к экстрактору силитистов и поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора.", description = "Совсем недавно мы выяснили, что Орда добывает в Силитусе полезные ископаемые. Мы думали, что в таком климате не стоит держать много войск.\n\nК сожалению, выяснилось, насколько важны эти полезные ископаемые, и теперь мы тщетно пытаемся догнать Орду по масштабам добычи.\n\nЕсли ты хочешь мне помочь, ступай в пустыню и принеси оттуда силитист.", progress = "Соблюдай осторожность, но не медли. Время на исходе.", completion = "Хвала Свету! Ты добился успеха!\n\nНачни мы добычу кристаллов раньше, не оказались бы в таком отчаянном положении. Мы не допустим, чтобы сокровища пустыни попали в руки Орды.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСильнейшее лечебное зельеСильнейшее зелье маны\n\nВы также получите:\n\n"},
[9422] = {title = "Истощение пустыни", objective = "Найдите и принесите силитист к экстрактору силитистов и поговорите с генералом Кирикой в лагере Орды возле Улья Регал.", description = "Мы давно начали добычу кристаллов пустыни Силитуса. Поначалу мы сталкивались лишь с опасностями, исходящими от местных жителей, песка, пыли и жары.\n\nТеперь же Альянс пронюхал, чем мы тут занимаемся, и началась гонка за добычей полезных ископаемых.\n\nУ меня каждая пара рук на счету, надеюсь, ты мне тоже поможешь.", progress = "Пустыня очень опасна,будь настороже, Снатяжкой. В барханах шныряют сторонники Альянса, и каждый шаг может оказаться последним.", completion = "Ты молодец, Дейдара. Мы отправим добытые ресурсы на склад, а наши приобретения все равно что потери для наших врагов!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nСильнейшее лечебное зельеСильнейшее зелье маны\n\nВы также получите:\n\n"},
[9556] = {title = "Вода для мага", objective = "Найдите бутылку святой воды Стратхольма на улицах Стратхольма и доставьте ее Лордеронскому магу в квартал магов в Штормграде или Подгороде, если вашей стороне удалось одержать верх в Восточных Чумных землях.", description = "Ты без сомнения прекрасно <проявил/проявила> себя в борьбе за башни, <раса>, и непременно получишь свою награду за доблесть. Но сначала ты <должен/должна> доказать, что понимаешь всю глубину разыгравшейся здесь трагедии.\n\nОтправляйся на улицы Стратхольма и найди сосуд со святой водой. Отнеси его в квартал магов в Штормград или Подгород... Если твои сородичи одержали верх в тех землях, тебе удастся добраться до кого-то из моих коллег.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[9664] = {title = "Новые форпосты", objective = "Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и башню Проклятого леса в Восточных Чумных землях и вернитесь к посланнику Белобороду в Часовню Последней Надежды.", description = "Добро пожаловать в Чумные земли,<имя>. Как тебе известно, Отрекшиеся и их приспешники удерживают земли к западу отсюда, несмотря на все наши усилия. Командующие Альянса приняли решение укрепить наши прифронтовые позиции, завоевав новые укрепления.\n\nБашни, давно заброшенные и позабытые еще в дни Лордерона, необходимо захватить и восстановить. Это очень опасные земли, и нам потребуется твоя помощь.", progress = nil, completion = "Превосходно, Синдрия. Теперь необходимо удерживать эти башни до прибытия подкрепления – для этого нам потребуется твоя помощь.", rewards = "Вы получите:\n\n"},
[9665] = {title = "Укрепим оборону", objective = "Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и башню Проклятого леса в Восточных Чумных землях и возвращайтесь к посланнику Гормоку в Часовню Последней Надежды.", description = "Разведчики Отрекшихся раскрыли планы Альянса создать новые форпосты в Восточных Чумных землях на базе заброшенных башен.\n\nНельзя позволить им закрепиться на наших восточных границах, поэтому необходимо помешать планам Альянса. Мы должны выманить их войска из тех башен, которые они уже успели захватить, и занять те, которые еще не были захвачены.", progress = nil, completion = "Это хорошие вести, Шпилэ. Мы будем биться в Чумных землях до конца, пока окончательно не разобьем силы Альянса.\n\nДо этого дня надеюсь на твою помощь.", rewards = "Вы получите:\n\n"},
[65593] = {title = "Сердца влюбленных", objective = "Принесите сердца Авелины Лилли и Исаака Пирсона Карнедину Халгару в Храм Проклятых.", description = "Инкуба привлекают сердца влюбленных, и чем крепче любовь, тем надежнее приманка.\n\nСвоим незримым оком я вижу двоих, перед чьей любовью не устоит ни один инкуб.\n\nАвелина Лилли из Серебряного бора шьет одежду для павших чародеев Янтарной мельницы. Исаак Пирсон из Степей надеется заработать состояние в приморском Кабестане.\n\nОни трудятся, не зная отдыха, на разных концах света, но их сердца тоскуют лишь друг о друге. Принеси сердца Карендину.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[65597] = {title = "Связывание", objective = "С помощью сердец влюбленных призовите и подчините инкуба, затем верните сердца Карендину Халгару в Квартал Магов Подгорода.", description = "Время наконец пришло. Отнеси сердца в круг призыва внизу. Положи их в центр и позови инкуба.\n\nКогда демон поймет, что его заманили в ловушку, ему это ох как не понравится. Сопротивляйся его попыткам обольстить тебя, <имя>. Его надо подчинить себе полностью.\n\nТолько после этого я смогу научить тебя, как заставить демона выполнять твою волю.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nПризыв инкуба\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание инкуба\n\nВы также получите:\n\nМалая сума душ"},
[65601] = {title = "Несчастная любовь", objective = "Поговорите с Магаром в Оргриммаре.", description = "Мужчин-сайаадов называют инкубами. Эти существа исполнены злобы и изощренной хитрости.\n\nДемона можно привлечь в наш мир особой приманкой – символом великой дружбы и верности.\n\nЕсли ты <готов/готова> довериться слепому поводырю, <имя>, то слушай. К востоку от Расселины Теней, у Волока Оргриммара, живет Магар. Он тоскует по Крилге, своей давно пропавшей подруге.\n\nНайди Магара. Он попросит тебя отыскать некую ценность. Это и есть ключ, который надо отнести Ган'рулу.", progress = nil, completion = "Кто рассказал тебе о Крилге? Ты знаешь, где она? Лучше не шути со мной...", rewards = "Вы получите:\n\n"},
[65602] = {title = "Лучшие друзья", objective = "Добудьте деревянную статуэтку и принесите ее Гакину Темнопряду в квартал магов Штормграда.", description = "Чтобы призвать инкуба, нужен мощный реагент – символ дружбы и верности.\n\nЯ заглянул в прошлое сквозь туман времени и увидел небольшую статуэтку, которая годится для ритуала.\n\nТысячи лет назад она принадлежала двум друзьям. Они давно мертвы, но их реликвия сохранилась.\n\nИди по дороге в Ясеневый лес, потом сверни на запад и иди дальше мимо заставы Мейстры. Ищи дом между деревьев – статуэтка находится в нем.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[65603] = {title = "Связывание", objective = "Воспользуйтесь деревянной статуэткой, чтобы призвать и подчинить инкуба, затем верните статуэтку Гакину Темнопряду. Он будет ждать в \"Забитом ягненке\".", description = "Пора. Бери статуэтку и спускайся в гробницу. Круг призыва готов, поставь статуэтку точно в центре.\n\nОткроются врата, и инкуб явится в наш мир.\n\nСайаадов нельзя недооценивать. Как только демон поймет, что его обманули, он сразу атакует. Используй все, чему ты <научился/научилась>, чтобы победить его.\n\nЕсли все получится, возвращайся ко мне, и я подчиню демона твоей воле. Но если ты проиграешь, твоя душа обречена.Вы изучите:\n\n", progress = nil, completion = nil, rewards = "Вы изучите:\n\nПризыв инкуба\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание инкуба\n\nВы также получите:\n\nМалая сума душ"},
[65604] = {title = "Связывание", objective = "С помощью истлевшего платка призовите и подчините своей воле инкуба, затем верните его Ган'рулу Кровавому Глазу в Оргриммаре.", description = "Да... то, что нужно. Давние чувства переплелись с нитями ткани. Любовь проходит вдоль стежков. Инкуб не сможет устоять.\n\nОтнеси это к кругу призыва в шатре Нииру, <имя>. Вызови гнусного инкуба и покажи ему, кто здесь хозяин. Не жди легкой победы. Приготовься пустить в ход всю свою магическую силу. Многие чернокнижники поплатились жизнью, недооценив демона.\n\nКогда подчинишь инкуба, верни ткань мне. Нужно будет сообщить Магару о твоей находке.", progress = "Сайаады пленяют разум и истязают душу. Завороженный их красотой, ты не будешь сопротивляться, пока они рвут твое тело на части кнутом и когтями.\n\nНе дай им усыпить твою бдительность, Вий. Срази демона быстро и не дай ему ни единого шанса.", completion = "Ха-ха! Я и не сомневался в победе!\n\nТеперь, когда инкуб подчинен, я с удовольствием научу тебя его призывать. Твоя сила растет, но я уверен, что это лишь первый шаг на пути к настоящей мощи.\n\nЯ верну платок Магару. Я много лет знаю этого орка и никогда бы не подумал, что он способен на такую глубокую привязанность.\n\nПусть его чувства станут напоминанием того, чем мы отличаемся от демонов. Это их темная магия служит нам, а не мы им.", rewards = "Вы изучите:\n\nПризыв инкуба\n\nСледующее заклинание будет наложено на вас:\n\nИзучить призывание инкуба\n\nВы также получите:\n\nМалая сума душ"},
[65610] = {title = "Если бы мы были вместе...", objective = "Осмотрите озеро Зеркало Небес в Ясеневом лесу и расскажите о находках Ган'рулу Кровавый Глаз в Оргриммаре.", description = "Я встретил Крилге, когда изготавливал луноткань в Ясеневом лесу. Ее отправили туда защищать местных жителей, но однажды она пропала...\n\nЕе посчитали дезертиром и прекратили поиски, но я не верю, что она сбежала.\n\nМы часто ходили к Зеркалу Небес, пока озеро не заполонили дикие болотные твари.\n\nЯ редко прошу других об услуге, но буду рад, если ты поищешь в Ясеневом лесу ее следы.", progress = "Да, чего тебе?", completion = "Что это у тебя, Вий? Платок... из луноткани? Надеюсь, это не попытка флирта.", rewards = "Вы получите:\n\n"},
[76156] = {title = "Неслышная поступь Матери-Земли", objective = "Проберитесь в шахту Торговой Компании к юго-западу от Громового Утеса и соберите 5 шахтерских сефориевых зарядов из тележек со взрывчаткой, а затем вернитесь к Бортону Теневому Тотему в Громовой Утес.", description = "Я чувствую в тебе скрытый талант к искусству незаметности, <шаман/шаманка>. Возьми эту маску, проберись в ближайшую шахту Торговой Компании и укради их припасы. Да, маски хватит – ловкий разбойник умеет усыпить бдительность одной лишь обаятельной улыбкой и хитроумным трюком. Тебе это тоже вполне под силу.", progress = "Тебе надо поработать над незаметностью, шаман. Твои шаги было слышно по всей горе.", completion = "Хм... наверное, к маскировке у тебя особых способностей нет.", rewards = "Вы получите:\n\n"},
[76160] = {title = "Неслышная поступь Матери-Земли", objective = "Соберите 8 шишек Неистовства Ветра к северу от Громового Утеса, разотрите их пестиком в ступке и возвращайтесь к Бортону Теневому Тотему в Громовой Утес.", description = "Я обращаюсь к тебе с посланием из будущего, где на долю Орды выпали тяжелейшие испытания. Меня видишь только ты, поэтому тебе я и передам свои знания, чтобы ты <научил/научила> этому мастерству все племя.\n\nБыть может, у тебя склонность к ядам, а не к маскировке. К северу отсюда находится логово гарпий. Они гнездятся на деревьях, которые вырабатывают необычайно ядовитую смолу. Собери упавшие шишки и разотри их в кашицу. Если смазать ею клинок, любая рана прожжет плоть до кости, а кровь посолонеет как морская вода.", progress = "Осторожней с готовым ядом, шаман. Он вызывает сильную боль, даже если просто попадет на кожу.", completion = "Где яд, шаман? Это же перетертые кедровые орешки. Ты точно ничего не перепутал?\n\nИх впору на хлеб мазать, а не на кинжал. Хотя против врага с аллергией на орехи лучше оружия не придумаешь.", rewards = "Вы получите:\n\nМасло из кедровых орешков"},
[76240] = {title = "Неслышная поступь Матери-Земли", objective = "Поймайте или купите сырую блестящую рыбку и покажите Бортону Теневому Тотему из Громового Утеса, как будете ее разделывать набором ножей.", description = "Не будем терять надежды и попробуем в последний раз. Я все еще чувствую в тебе талант, но как видно, с ходу его не раскопаешь.\n\nДостань мне сырую блестящую рыбку и разделай ее этими кинжалами. Доверься инстинктам – пусть руки сами тебя ведут.", progress = "Что ты мне принес?", completion = "Впечатляюще, шаман. Для разбойника тебе не хватает отточенности движений, но зато левой рукой ты владеешь не хуже, чем правой.\n\nПусть ты не сможешь обучить мой народ искусству тайного боя, но сам кое-чему все же научился. Удачных тебе странствий, шаман. Герои вроде тебя хорошо послужат Орде.", rewards = "Вы изучите:\n\nБой двумя оружиями\n\nСледующее заклинание будет наложено на вас:\n\nГравировка перчаток \"Вскипание лавы\"\n\nВы также получите:\n\n"},
[77568] = {title = "Сила охотника", objective = "Победите Гитьис Зловещую в Паучьем логове и добудьте пропавшую руну. Изучите ее и возвращайтесь к Аянне Вечной Страннице в Тенистую долину.", description = "Охотники черпают силу в близости и уважении ко всем живым созданиям, а не только к своим питомцам. На службе у Альянса ты убьешь не одного зверя, но даже в бою надо уважать врага.\n\nМоя предыдущая ученица усиливала свои способности чародейской руной, но самонадеянно решила потренироваться на Гитьис Зловещей – самой крупной паучихе из пещеры на севере. Неуважение к врагу ее погубило.\n\nУбей Гитьис – но не вздумай недооценивать ее силу.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшиеся кожаные перчатки"},
[77571] = {title = "Реликвии калдорай", objective = "Заберите реликвию у греллей в Тенистой долине. Выслушайте ее наставления, чтобы освоить новую способность, и возвращайтесь к Марданту Крепкому Дубу.", description = "Калдорай – древний народ, и наши утерянные реликвии рассеяны по всему Азероту. Через них ты можешь обратиться к духам и узнать, как укрепить связь со Сном.\n\nОдну из таких реликвий украли грелли. Убей их и верни реликвию, а потом выслушай ее наставления, чтобы изучить новый боевой прием. Когда закончишь, возвращайся ко мне.", progress = "Чему реликвия научила тебя?", completion = "Прекрасно, Гансли. Руна зачарует твое снаряжение новой мощной магией.\n\nПродолжай искать другие утерянные реликвии в своих странствиях.", rewards = "Вы получите:\n\nПотрескавшийся кожаный жилет"},
[77573] = {title = "Работа на высоте", objective = "Достаньте руну из потайного отделения статуэтки и выучите новую способность. После этого возвращайтесь к Фрагуну Шепоту Тени.", description = "Предлагаю потренироваться, <имя>. На крыше этого здания стоит статуэтка совы. Ее видно со стороны южного входа. В этой статуэтке есть потайное отделение, где хранится резная руна.\n\nЗаберись на крышу, достань руну и запомни ее, а потом возвращайся ко мне.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшиеся кожаные перчатки"},
[77574] = {title = "Медитация об Элуне", objective = "Преклоните колени у лунного колодца и помедитируйте об Элуне, а затем узнайте новую способность через воспоминание. После этого возвращайтесь к Шанде в Тенистую долину.", description = "В лице Альянса наш народ получил могущественного союзника, но калдорай нельзя забывать о своих корнях. Связь с Элуной – опора нашей души.\n\nОчисти сознание, <имя>, и следуй за моим голосом. Я передам в твой разум древнее воспоминание предков. Отправляйся к лунному колодцу на севере, преклони колени перед священными водами и погрузись в медитацию о тайнах Элуны. Когда все твои мысли устремятся к ней, ты проникнешь в смысл этого воспоминания и откроешь в себе новые способности. Возвращайся ко мне, когда закончишь.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрепанные матерчатые перчатки"},
[77575] = {title = "В темных сетях", objective = "Убейте чащобных тенетников в Паучьем логове и добудьте потерянную руну. Изучите ее и возвращайтесь к Алайссии в Тенистую долину.", description = "У воинов Альянса можно многому научиться, но забрасывать самостоятельные тренировки тоже нельзя.\n\nК северу отсюда лежит пещера чащобных тенетников, куда недавно отправился один воин-новичок. Обратно он не вернулся. Этот воин проводил эксперименты с чародейскими рунами, расписывая и усиливая ими свое снаряжение.\n\nНайди руну в паучьем гнезде и изучи ее магию.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотускневшие плетеные перчатки"},
[77582] = {title = "Испытание физической силы", objective = "Найдите тайник в скалах, что виднеются позади Франга. Изучите руну и возвращайтесь к Франгу в Долину Испытаний.", description = "Воину Орды прежде всего нужна физическая сила. В странствиях твоя воля и выносливость подвергнутся тяжелым испытаниям. \n\nПоэтому я спрятал сундук среди скал: его видно отсюда, если встать у костра в центре деревни. Чтобы добраться туда, тебе придется напрячь все свои силы. В сундуке ты найдешь руну с могущественными чарами.\n\nЕсли добудешь эту руну и познаешь ее тайны, я смогу назвать тебя истинным воином.", progress = nil, completion = "Прекрасно, Табу. Руна зачарует твое снаряжение новой мощной магией.\n\nТакие руны встречаются нередко. Ищи их по всему Азероту – они пригодятся тебе в странствиях.", rewards = "Вы получите:\n\nПотускневшие плетеные перчатки"},
[77583] = {title = "На вершинах скал", objective = "Найдите тайник в скалах вокруг Долины Испытаний. Изучите руну и возвращайтесь к Руагу в Логово.", description = "Предлагаю потренироваться, <имя>. Я спрятал сундук среди скал позади меня: его видно отсюда, если встать у костра в центре деревни. В сундуке ты найдешь руну с могущественными чарами.\nЕсли добудешь эту руну и познаешь ее тайны, я смогу назвать тебя истинным воином.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшиеся кожаные перчатки"},
[77584] = {title = "Охота за руной", objective = "Убивайте скорпидов в Долине Испытаний и ищите украденную руну. Получите ее силу и возвращайтесь к Джен'шан.", description = "Охотник черпает силу в родстве с дикой природой. В странствиях тебе придется выслеживать добычу по непролазным дебрям, где не на кого положиться, кроме своей смекалки.\n\nУвы, одного из охотников она недавно подвела. Он вышел поохотиться на скорпидов и уже не вернулся. Этот охотник проводил эксперименты с чародейскими рунами, расписывая и усиливая ими свое снаряжение.\n\nНайди руну в логове скорпидов и возвращайся, когда постигнешь ее секреты.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшиеся кожаные перчатки"},
[77585] = {title = "Образы силы", objective = "Убивайте скорпидов в Долине Испытаний и ищите украденный образ. Получите его силу и возвращайтесь к Шикрик.", description = "Шаманизм – очень древнее учение, <имя>. По всему Азероту встречаются артефакты, пропитанные энергией духов. Недавно мне тоже попался один мощный мистический образ, но гадины-скорпиды его украли.\n\nОдин из них наверняка таскает его сейчас с собой, думая пристроить яркую безделушку себе в гнездо. \n\nНайди этот образ, получи его силу и возвращайся ко мне.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшийся кожаный жилет"},
[77586] = {title = "Похищенная сила", objective = "Найдите украденную руну в гроте Пылающего Клинка. Изучите ее магию и возвращайтесь к Нартоку в Логово.", description = "Я экспериментирую с новой разновидностью магии – руной, которая может преобразовывать энергию Скверны в мощные заклинания. Я не против посвятить в это знание тебя, но ее украл один из приспешников Пылающего Клинка.\n\nСходи в их грот на севере и попробуй отыскать руну среди их барахла. По опыту знаю, эти мерзавцы чаще прячут награбленное добро в дальних незаметных углах. \n\nКогда найдешь руну, изучи ее магию и возвращайся ко мне. Интересно будет посмотреть, к чему привели мои эксперименты.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрепанные матерчатые перчатки"},
[77587] = {title = "Образы силы", objective = "Убивайте скорпидов в Долине Испытаний и ищите украденный образ. Получите его силу и возвращайтесь к Шикрик.", description = "Шаманизм – очень древнее учение, <имя>. По всему Азероту встречаются артефакты, пропитанные энергией духов. Недавно мне тоже попался один мощный мистический образ, но гадины-скорпиды его украли.\n\nОдин из них наверняка таскает его сейчас с собой, думая пристроить яркую безделушку себе в гнездо. \n\nНайди этот образ, получи его силу и возвращайся ко мне.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшийся кожаный жилет"},
[77588] = {title = "Испытание физической силы", objective = "Найдите тайник в скалах, что виднеются позади Франга. Изучите руну и возвращайтесь к Франгу в Долину Испытаний.", description = "Воину Орды прежде всего нужна физическая сила. В странствиях твоя воля и выносливость подвергнутся тяжелым испытаниям. \n\nПоэтому я спрятал сундук среди скал: его видно отсюда, если встать у костра в центре деревни. Чтобы добраться до него, тебе придется напрячь все свои силы. В сундуке ты найдешь руну с могущественными чарами.\n\nЕсли добудешь эту руну и познаешь ее тайны, я смогу назвать тебя истинным воином.", progress = nil, completion = "Прекрасно, Топот. Руна зачарует твое снаряжение новой мощной магией.\n\nТакие руны встречаются нередко. Ищи их по всему Азероту – они пригодятся тебе в странствиях.", rewards = "Вы получите:\n\nПотускневшие плетеные перчатки"},
[77590] = {title = "Непроходимые дебри", objective = "Убивайте скорпидов в Долине Испытаний и ищите украденную руну. Получите ее силу и возвращайтесь к Джен'шан.", description = "Охотник черпает силу в родстве с дикой природой. В странствиях тебе придется выслеживать добычу по непролазным дебрям, где не на кого положиться, кроме своей смекалки.\n\nУвы, одного из охотников она недавно подвела. Он вышел поохотиться на скорпидов и уже не вернулся. Этот охотник проводил эксперименты с чародейскими рунами, расписывая и усиливая ими свое снаряжение.\n\nНайди руну в логове скорпидов и возвращайся, когда постигнешь ее секреты.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшиеся кожаные перчатки"},
[77592] = {title = "На вершинах скал", objective = "Найдите тайник в скалах вокруг Долины Испытаний. Изучите руну и возвращайтесь к Руагу в Логово.", description = "Предлагаю потренироваться, <имя>. Я спрятал сундук среди скал позади меня: его видно отсюда, если встать у костра в центре деревни. В сундуке ты найдешь руну с могущественными чарами.\nЕсли добудешь эту руну и познаешь ее тайны, я смогу назвать тебя истинным воином.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшиеся кожаные перчатки"},
[77616] = {title = "Пропавшая руна", objective = "Найдите пропавшую руну в Руднике Горного Эха и выучите новую способность, а затем возвращайтесь к Ллану Бишеру в Североземье.", description = "У воинов Альянса можно многому научиться, но забрасывать самостоятельные тренировки тоже нельзя.\n\nОдна молодая воительница недавно отправилась к Руднику Горного Эха. Она проводила эксперименты с чародейскими рунами, расписывая и усиливая ими свое снаряжение.\n\nПодозреваю, что она не пережила нападения кобольдов, когда те захватывали рудник. Найди руну в их логове и выучи ее магию.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотускневшие плетеные перчатки"},
[77617] = {title = "Реликвии Света", objective = "Добудьте манускрипт, выполните его наставления и выучите новый боевой прием, а затем возвращайтесь к брату Самуэлю в Североземье.", description = "Реликвии Света можно найти по всему Азероту. К ним относятся и манускрипты, хранящие доктрины нашего ордена с самого его основания. Они помогут тебе укрепить связь со Светом.\n\nОдин из таких манускриптов входил в коллекцию аббатства, но бандиты из Братства Справедливости утащили его в свой лагерь на востоке. Отбери у них манускрипт, внимательно прочти и выполни все наставления, чтобы научиться новым боевым приемам. Возвращайся ко мне, когда закончишь.", progress = nil, completion = "Well done, &lt;имя&gt;. Applying the rune you have learned to your equipment will grant you powerful new abilities.\n\nSeek out more of these relics along your travels.", rewards = "Вы получите:\n\nПотускневшие плетеные перчатки"},
[77618] = {title = "Переходящий приз", objective = "Добудьте пропавшую руну в лагере Братства Справедливости и выучите новую способность, а затем возвращайтесь к Джорику Керридану в Североземье.", description = "Стыдно признаться, <имя>, но шакалы из Братства Справедливости меня обставили. Они сперли магическую руну, которую я, э-э... позаимствовал из архивов аббатства. Решил, что она меня выручит, если прижмет... Но в итоге всю голову сломал, пытаясь в ней разобраться.\n\nСбегай-ка на восток и попробуй порыться в заначках этих бандитов. И если найдешь руну, заодно проверь – вдруг она на что годится. Вон какая у тебя рожа ученая. Без обид.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшиеся кожаные перчатки"},
[77619] = {title = "Медитация о Свете", objective = "Убивайте кобольдов в Руднике Горного Эха, чтобы получить воспоминание. Преклоните колени в аббатстве Североземья, обратитесь к воспоминанию и выучите новую способность. После этого возвращайтесь к жрице Анетте.", description = "Свет показал мне видение о твоем будущем: в нем ты сражаешься с кобольдами в Руднике Горного Эха. Там Свет явит тебе воспоминание из прошлого. Приходи с этим воспоминанием в аббатство, преклони колени и помедитируй о тайнах Света.\n\nКогда все твои мысли устремятся к нему, ты проникнешь в смысл воспоминания и откроешь в себе новые способности. Возвращайся ко мне, когда закончишь.", progress = nil, completion = "Когда Свет пошлет тебе новые видения, помедитируй у святилищ, чтобы очистить разум и познать их тайны.\n\nМне открылось, что твой духовный путь приведет к нашим союзникам-эльфам из Калимдора. Если мы изучим их любопытные обряды поклонения луне, когда-нибудь эти знания помогут причастить их к Свету.", rewards = "Вы получите:\n\nПотрепанные матерчатые перчатки"},
[77620] = {title = "Исследование заклинаний", objective = "Добудьте исследовательские записи у бандитов Братства Справедливости и выучите новое заклинание. После этого возвращайтесь к Кельдену Бремену в Североземье.", description = "Я научу тебя всему, что знаю, <имя>. Но в самостоятельных изысканиях ты можешь обрести невообразимую силу. Советую начать с рабочих заметок величайших верховных магов Азерота. В архивах аббатства хранились сотни трудов о чародейских искусствах, но все их украли диверсанты Братства Справедливости.\n\nДобудь заметки о заклинаниях в лагере бандитов на востоке и обратись к этому введению, чтобы их расшифровать. Как все прочитаешь, возвращайся ко мне.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье пониманияПотрепанные матерчатые перчатки"},
[77621] = {title = "Похищенная сила", objective = "Добудьте руну в лагере Братства Справедливости на востоке и выучите новую способность, а затем возвращайтесь к Друзилле ла Салле в Североземье.", description = "Я экспериментирую с новой разновидностью магии – руной, которая может преобразовывать энергию Скверны в мощные заклинания. Я не против посвятить в это знание тебя, но вчера мои записи кто-то украл. Подозреваю, что без так называемого \"Братства Справедливости\" не обошлось.\n\nСходи в их лагерь на востоке и попробуй отыскать руну среди их барахла. Когда найдешь, изучи ее магию и возвращайся ко мне. Интересно будет посмотреть, к чему привели мои эксперименты.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрепанные матерчатые перчатки"},
[77642] = {title = "Мудрость лоа", objective = "Преклоните колени у алтаря лоа в деревне Сен'джин. Обратитесь к духу лоа и получите новую способность через воспоминание. После того вернитесь к Кен'джаю в Долину Испытаний.", description = "В Орде наш народ обрел безопасный дом, <имя>. Но мы помним и о лоа, которые всегда оберегали нас.\n\nОчисти разум – я передам тебе воспоминание из прошлого. Иди к алтарю лоа в деревне Сен'джин и преклони перед ним колени, чтобы обратиться к великому духу лоа. Его мудрость поможет тебе понять смысл этого воспоминания и открыть новые способности.\n\nВозвращайся ко мне, когда закончишь.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрепанные матерчатые перчатки"},
[77643] = {title = "Исследование заклинаний", objective = "Найдите украденные заметки о заклинаниях в гроте Пылающего Клинка и выучите новую способность. После этого возвращайтесь к Май'ах в Долину Испытаний.", description = "Без постоянного изучения магии нельзя добиться высот в чародейском искусстве. Начинать лучше всего с рабочих заметок величайших магов Азерота. Некоторые встречались и мне, но приспешники Пылающего Клинка украли их у меня.\n\nДобудь заметки о заклинаниях из грота на севере и расшифруй их с помощью этого введения. Как все прочитаешь, возвращайся ко мне.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье пониманияПотрепанные матерчатые перчатки"},
[77648] = {title = "Реликвии тауренов", objective = "Заберите украденную реликвию из Ежевичной лощины. Выслушайте ее наставления, чтобы выучить новую способность, и возвращайтесь к Гарту Вестнику Туманов в лагерь Нараче.", description = "Таурены – древний народ, <имя>, и наши утерянные реликвии оказались рассеяны по всему Азероту. Через них ты можешь обратиться к духам и узнать, как укрепить связь со Сном.\n\nОдну из таких реликвий утащили свинобразы из племени Дыбогривов – скорее всего, куда-то в Ежевичную лощину. Верни реликвию и выслушай ее наставления, чтобы выучить новый боевой прием. Когда закончишь, возвращайся ко мне.", progress = nil, completion = "Well done, &lt;имя&gt;. Applying the rune you have learned to your equipment will grant you powerful new abilities.\n\nSeek out more of our lost relics along your travels.", rewards = "Вы получите:\n\nПотрескавшийся кожаный жилет"},
[77649] = {title = "Сила охотника", objective = "Убейте боевых вепрей из племени Дыбогривов в Ежевичной лощине и найдите пропавшую руну. Выучите с ее помощью новую способность и возвращайтесь к Ланко Дальний Выстрел в лагерь Нараче.", description = "Охотники – опора традиционного уклада жизни тауренов, <имя>. Мы обеспечиваем племя и защитой, и пропитанием. В странствиях тебе нередко придется выживать на вражеских территориях, где не на кого положиться, кроме своей смекалки.\n\nНедавно один охотник проводил эксперименты с чародейскими рунами, расписывая и усиливая ими свое снаряжение. Он ушел на восток, чтобы опробовать их против боевых вепрей из племени Дыбогривов, и уже не вернулся.\n\nНайди эту руну и изучи ее, чтобы освоить новый боевой прием. Возвращайся ко мне, когда закончишь.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшиеся кожаные перчатки"},
[77651] = {title = "В колючие заросли", objective = "Найдите пропавшую руну в Ежевичной лощине. Выучите с ее помощью новую способность и возвращайтесь к Харуту Громовому Рогу в лагерь Нараче.", description = "У воинов Орды можно многому научиться, <имя>, но забрасывать самостоятельные тренировки тоже нельзя.\n\nКак ты наверняка уже знаешь, на востоке поселилась община агрессивных свинобразов. Туда недавно отправился один воин-новичок. Обратно он не вернулся. Этот воин проводил эксперименты с чародейскими рунами, расписывая и усиливая ими свое снаряжение.\n\nНайди руну в логове свинобразов и выучи ее магию. Возвращайся ко мне, когда закончишь.", progress = nil, completion = "Прекрасно, Овермастер. Руна зачарует твое снаряжение новой мощной магией.\n\nТакие руны встречаются нередко. Ищи их по всему Азероту – они пригодятся тебе в странствиях.", rewards = "Вы получите:\n\nПотускневшие плетеные перчатки"},
[77652] = {title = "Образы силы", objective = "Добудьте украденный образ у шаманов из племени Дыбогривов в Ежевичной лощине. Получите его силу и возвращайтесь к Харуту Громовому Рогу в лагерь Нараче.", description = "Шаманизм – очень древнее учение, <имя>. По всему Азероту встречаются артефакты, пропитанные энергией духов. Недавно мне тоже попался один мощный мистический образ, но свинобразы украли его у меня.\n\nНаведайся в их логово на востоке и найди украденный образ. Скорее всего, один из них забрал его себе и пытается разгадать его тайны. \n\nКогда добудешь образ, получи его силу и возвращайся ко мне.", progress = nil, completion = "Прекрасно, Серошкур. Руна зачарует твое снаряжение новой мощной магией.\n\nТакие руны встречаются нередко. Ищи их по всему Азероту – они пригодятся тебе в странствиях.", rewards = "Вы получите:\n\nПотрескавшийся кожаный жилет"},
[77655] = {title = "Пропавшая руна", objective = "Найдите пропавшую руну у тролля из племени Мерзлогривов в Холодной долине. Выучите с ее помощью новую способность и возвращайтесь к Трану Корману в Старую Наковальню.", description = "У воинов Альянса можно многому научиться, <имя>, но забрасывать самостоятельные тренировки тоже нельзя.\n\nК югу отсюда лежит пещера троллей из племени Мерзлогривов, куда недавно отправился один воин-новичок. Обратно он не вернулся. Этот воин проводил эксперименты с чародейскими рунами, расписывая и усиливая ими свое снаряжение.\n\nОбыщи логово троллей, отбери у них руну и выучи ее магию. Возвращайся ко мне, когда закончишь.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотускневшие плетеные перчатки"},
[77656] = {title = "Пропавшая руна", objective = "Найдите пропавшую руну у тролля из племени Мерзлогривов в Холодной долине. Выучите с ее помощью новую способность и возвращайтесь к Трану Корману в Старую Наковальню.", description = "У воинов Альянса можно многому научиться, <имя>, но забрасывать самостоятельные тренировки тоже нельзя.\n\nК югу отсюда лежит пещера троллей из племени Мерзлогривов, куда недавно отправился один воин-новичок. Обратно он не вернулся. Этот воин проводил эксперименты с чародейскими рунами, расписывая и усиливая ими свое снаряжение.\n\nОбыщи логово троллей, отбери у них руну и выучи ее магию. Возвращайся ко мне, когда закончишь.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотускневшие плетеные перчатки"},
[77657] = {title = "Реликвии Света", objective = "Добудьте украденный манускрипт у троллей из племени Мерзлогривов в Холодной долине. Выполните его наставления и выучите новый боевой прием, а затем возвращайтесь к Бромосу Груммнеру в Старую Наковальню.", description = "Реликвии Света можно найти по всему Азероту. К ним относятся и манускрипты, хранящие доктрины нашего ордена с самого его основания. Они помогут тебе укрепить связь со Светом.\n\nОдин из таких манускриптов входил в нашу коллекцию, но тролли из племени Мерзлогривов украли его. Вор наверняка еще носит его при себе. Отбери у троллей манускрипт, внимательно прочти и выполни все наставления, чтобы научиться новым боевым приемам. Возвращайся ко мне, когда закончишь.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотускневшие плетеные перчатки"},
[77658] = {title = "Переходящий приз", objective = "Добудьте украденную руну из пещеры троллей-Мерзлогривов в Холодной долине. Выучите с ее помощью новую способность и возвращайтесь к Сольму Харгрину в Старую Наковальню.", description = "Стыдно признаться, <имя>, но мерзавцы-Мерзлогривы меня обставили. Они сперли магическую руну, которую я, э-э... позаимствовал из сокровищницы. Решил, что такую мощную штуку полезно иметь... Но в итоге всю голову сломал, пытаясь в ней разобраться.\n\nСбегай-ка в их пещеру на юге и попробуй порыться в заначках этих бандитов. И если найдешь руну, заодно проверь – вдруг она на что годится. Вон какая у тебя рожа ученая. Без обид.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшиеся кожаные перчатки"},
[77659] = {title = "Переходящий приз", objective = "Добудьте украденную руну из пещеры троллей-Мерзлогривов в Холодной долине. Выучите с ее помощью новую способность и возвращайтесь к Сольму Харгрину в Старую Наковальню.", description = "Стыдно признаться, <имя>, но мерзавцы-Мерзлогривы меня обставили. Они сперли магическую руну, которую я, э-э... позаимствовал из сокровищницы. Решил, что такую мощную штуку полезно иметь... Но в итоге всю голову сломал, пытаясь в ней разобраться.\n\nСбегай-ка в их пещеру на юге и попробуй порыться в заначках этих бандитов. И если найдешь руну, заодно проверь – вдруг она на что годится. Вон какая у тебя рожа ученая. Без обид.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшиеся кожаные перчатки"},
[77660] = {title = "Вылазка в пещеры", objective = "Добудьте украденную руну из пещеры троллей-Мерзлогривов в Холодной долине. Выучите с ее помощью новую способность и возвращайтесь к Торгасу Мрачнону в Старую Наковальню.", description = "Охотники славятся стойкостью, <имя>. Даже среди дворфов. Мы путешествуем по неизведанным землям Азерота, охотясь на опаснейших и удивительнейших зверей. В странствиях тебе нередко придется выживать на вражеских территориях, где не на кого положиться, кроме своей смекалки.\n\nТролли из племени Мерзлогривов украли у нас руну великой мощи. Скорее всего, они спрятали ее в своей пещере на юге. Найди руну и открой в себе новую силу. Возвращайся ко мне, когда закончишь.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшиеся кожаные перчатки"},
[77661] = {title = "Медитация о Свете", objective = "Найдите воспоминание из прошлого в сундуке в лагере троггов у Старой Наковальни. Преклоните колени у алтаря Света, помедитируйте и выучите новую способность. После этого поговорите с Бранстоком Халдером.", description = "Свет показал мне видение о твоем будущем, <имя>: в нем ты сражаешься с троггами на юго-западе. Там ты найдешь сундук, а в нем – воспоминание из прошлого. Приходи с этим воспоминанием сюда, преклони колени у алтаря Света и помедитируй о его тайнах.\n\nКогда все твои мысли устремятся к нему, ты проникнешь в смысл воспоминания и откроешь в себе новые способности. Возвращайся ко мне, когда закончишь.", progress = nil, completion = "Когда Свет пошлет тебе новые видения, помедитируй у святилищ, чтобы очистить разум и познать их тайны.\n\nМне открылось, что твой духовный путь приведет к нашим союзникам-эльфам из Калимдора. Если мы изучим их любопытные обряды поклонения луне, когда-нибудь эти знания помогут причастить их к Свету.", rewards = "Вы получите:\n\nПотрепанные матерчатые перчатки"},
[77666] = {title = "Похищенная сила", objective = "Добудьте руну из лагеря троггов к юго-западу от Старой Наковальни и выучите с ее помощью новую способность, а затем возвращайтесь к Аламару Мрачнну.", description = "Я экспериментирую с новой разновидностью магии – руной, которая может преобразовывать энергию Скверны в мощные заклинания. Я не против посвятить в это знание тебя, но ее украл один из нахальных троггов.\n\nК юго-западу отсюда как раз обитает племя Каменной Челюсти. Сходи в их лагерь и попробуй отыскать руну среди их барахла. Скорее всего, они запрятали ее в какой-нибудь сундук. Когда найдешь руну, изучи ее магию и возвращайся ко мне. Интересно будет посмотреть, к чему привели мои эксперименты.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрепанные матерчатые перчатки"},
[77667] = {title = "Исследование заклинаний", objective = "Найдите украденные заметки о заклинаниях в лагере троггов к юго-западу от Старой Наковальни, выучите с их помощью новую способность и возвращайтесь к Маррику Нуррибиту.", description = "Без постоянного изучения магии нельзя добиться высот в чародейском искусстве. Начинать лучше всего с рабочих заметок величайших магов Азерота. Некоторые встречались и мне, но их утащили нахальные трогги, что на юго-западе отсюда.\n\nДобудь заметки о заклинаниях из лагеря троггов и расшифруй с помощью этого введения. Как все прочитаешь, возвращайся ко мне.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье пониманияПотрепанные матерчатые перчатки"},
[77668] = {title = "Пропавшая руна", objective = "Найдите руну в Паучьей низине и выучите с ее помощью новую способность, а затем возвращайтесь к Данналу Штерну в Похоронный Звон.", description = "У воинов Темной Госпожи можно многому научиться, но забрасывать самостоятельные тренировки тоже нельзя.\n\nОдин воин недавно отправился на север в Паучью низину. Он проводил эксперименты с чародейскими рунами, расписывая и усиливая ими свое снаряжение.\n\nПодозреваю, что его сожрали расплодившиеся пауки. Найди руну среди их паутины и выучи ее магию.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотускневшие плетеные перчатки"},
[77669] = {title = "Руна Алого ордена", objective = "Обшаривайте карманы или убивайте новообращенных Алого ордена, чтобы найти руну. Изучите ее и возвращайтесь к Давиду Триасу в Похоронный Звон.", description = "Кем ты <был/была> при жизни, <имя>? Шпионом? Вором? Поваром с удивительным талантом к разделке мяса? Уже неважно. Пора осваивать новые приемы. Разбойники Отрекшихся не упускают ни единого шанса на победу.\n\nНовообращенные Алого ордена раньше оружия даже в руки не брали, но им выдали магические руны, с которыми они стали намного сильнее. Укради одну из этих рун и изучи ее, а затем возвращайся ко мне.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрескавшиеся кожаные перчатки"},
[77670] = {title = "Медитация о смерти", objective = "Преклоните колени на кладбище и помедитируйте о тайнах смерти. Выучите новую способность и возвращайтесь к темному священнику Дьюстену в часовню Похоронного Звона.", description = "Я вызову в твоем сознании воспоминание живущих – может быть, даже твое собственное. Иди на кладбище позади этой часовни и найди, где аура смерти ощутимее всего. Преклони колени и обрати к ней свои мысли. Узрев внутренним оком тайны бессмертной жизни, ты проникнешь в суть этого воспоминания и откроешь в себе новые способности. Возвращайся ко мне, когда закончишь.", progress = nil, completion = "Живые цепляются за Свет только лишь потому, что боятся забвения после смерти. Отрекшиеся оставили этот страх в прошлом. Хотя Свет теперь отвергает даже тех из нас, кто прежде самоотверженно ему служил, мы повелеваем силами тьмы далеко за последним рубежом.\n\nЧтобы совершенствоваться дальше, я советую тебе поучиться у троллей Орды. Культура у них примитивная, но они почитают божеств-лоа, которые не связаны границами жизни и смерти. В ней тебе может открыться понимание нашей природы.", rewards = "Вы получите:\n\nПотрепанные матерчатые перчатки"},
[77671] = {title = "Исследование заклинаний", objective = "Убейте посвященных Алого ордена, найдите заметки о заклинаниях, выучите новую способность и вернитесь к Изабелле в Похоронный Звон.", description = "Чародеи Королевского фармацевтического общества посвящают жизнь после смерти изучению заклинаний ради блага Отрекшихся. Пусть тебя влечет тропа приключений, но в странствиях ты можешь найти заметки о заклинаниях. Темной Госпоже угодно, чтобы ты <хранил и исследовал/хранила и исследовала> их.\n\nУбей посвященных Алого ордена, которые разбили лагерь у Похоронного Звона, и отбери их заметки о заклинаниях. Используй введение, чтобы их расшифровать, выучи новое заклинание и возвращайся ко мне.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье пониманияПотрепанные матерчатые перчатки"},
[77672] = {title = "Пропавшая руна", objective = "Найдите руну в Паучьей низине, выучите с ее помощью новую способность и возвращайтесь к Максимиллиону в Похоронный Звон.", description = "Я экспериментирую с новой разновидностью магии – руной, которая может преобразовывать энергию Скверны в мощные заклинания. Я послал ученика опробовать ее против пауков из северного рудника, но он так и не вернулся. Подозреваю, что больше мы его не увидим.\n\nМожет, ты окажешься покрепче? Иди к руднику и найди руну среди паучьих сетей. Изучи ее магию и возвращайся ко мне.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nПотрепанные матерчатые перчатки"},
[78088] = {title = "Странный артефакт", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[78089] = {title = "В Штормград за советом", objective = "Посоветуйтесь с паладинами Штормграда насчет сферы.", description = "Я чувствую в сфере темную силу, но не могу нащупать ее источник. Надо спросить совета у паладинов Штормграда. Отнеси сферу им.", progress = "У тебя вести из Калимдора?", completion = "&lt;Осматривает сферу, озабоченно прищурившись.&gt;", rewards = nil},
[78090] = {title = "Вердикт специалиста", objective = "Найдите укрытие чернокнижников в Штормграде и попросите их взглянуть на сферу.", description = "Не могу сказать об этой сфере ничего определенного, <имя>. Тут нужна помощь... специалиста.\n\nНам известно, что в Штормграде действует свой культ чернокнижников. Официально мы не признаем его существование. Неофициально их познания в общении с демонами бывают полезны.\n\nНайди представителя этого культа и расспроси его о сфере.", progress = "Далековато ты от собора, |3-6(Паладин). Советую просить, а не требовать.", completion = "Так Серебряной Длани нужна моя помощь? Она вам обойдется недешево.", rewards = nil},
[78091] = {title = "Самая соль", objective = "Добудьте 14 мешочков соли призывателя у призывателей из клана Черной горы в Красногорье и возвращайтесь к Урсуле Делайн в Штормград.", description = "Я изучу сферу и расскажу о своих выводах, но сначала твоя очередь мне помогать.\n\nЧернокнижники клана Черной горы усиливают ритуалы призыва особыми ароматическими солями. Достань мне их у орков в Красногорье.\n\nКогда вернешься, я изложу результаты исследований.", progress = nil, completion = nil, rewards = nil},
[78092] = {title = "Ее надо уничтожить", objective = "Придумайте, как уничтожить сферу.", description = "От этой сферы проходит связь к мощной сущности где-то за пределами Круговерти Пустоты. Я не могу осмыслить ее природу, но ее разум вглядывается с обратной стороны сферы... наблюдает за мной в ответ.\n\nОчень жаль, <имя>, но сферу придется уничтожить.\n\nОбычные средства, судя по всему, не причиняют ей вреда, но оружие могущественного повелителя демонов может сработать. Правда, не знаю, где ты его достанешь. Но ничего лучше предложить не могу.\n\nУдачи, <имя>.", progress = "<От бурлящей в воздухе инфернальной энергии у вас электризуются волосы.>", completion = "&lt;Вы поднимаете сферу к копью.&gt;", rewards = "Следующее заклинание будет наложено на вас:\n\nРаскалывание сферы"},
[78093] = {title = "Возвращение к Делгрену", objective = "Верните осколки сферы Делгрену.", description = "<Осколки разрушенной сферы падают к вашим ногам. Делгрену будет полезно знать, что у вас получилось.>Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nБожественная буря"},
[78114] = {title = "Виражи на вивернах", objective = "Принесите гипнотический кристалл и корявый жезл буйной магии Джиксо Ракетобаху в Когтистые горы.", description = "<Видал/Видала>, как носятся величавые виверны? Зеваки небось завалят меня золотом, когда я крутану на них петлю!\n\nНо к этим злющим тварям так просто не подступишься. Они не даются ни одному наезднику – что уж говорить о фигурах высшего пилотажа.\n\nХодит слух, что их можно усмирить магическим жезлом. Может, я даже сам могу такой смастерить. Всего-то и нужно, что гипнотический кристалл и корявый жезл буйной магии.\n\nНе знаю только, где их взять, но о мелочах подумаем потом.", progress = "Ну что, все нашел?", completion = "Супер! Переходим к полевым испытаниям.", rewards = "Вы получите:\n\n"},
[78121] = {title = "Усмирение виверны", objective = "Идите за Джиксо Ракетобахом и понаблюдайте, как он укрощает виверну.", description = "Жезл готов, осталось только одно: укротить виверну! \n\nПошли вместе, <имя>. У тебя, можно сказать, эксклюзивный билет на мое новое шоу!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЖезл приручения вивернРуна команды \"Взять!\""},
[78124] = {title = "Нар'таласский альманах", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье понимания"},
