[78143] = {title = "Тайны Дремлющих", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье понимания"},
[78144] = {title = "Алонсо Истребитель Драконов", objective = "Посмотрите, как Алонсо убивает дракона.", description = "Время пришло, <имя>. Я облачился в доспехи, достойные истинного драконоборца! Твою помощь трудно переоценить.\n\nА теперь я прошу тебя, <моего верного оруженосца/мою верную оруженосицу>, пойти со мной и посмотреть, как я одолею великого дракона!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nРуна яростного выпада"},
[78145] = {title = "Руководство по магическим системам", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье понимания"},
