[81775] = {title = "Ясеневый лес, задание VIII: Азшарское пророчество", objective = "Найдите Азшарское пророчество в небольшом шатре в Сатирнааре в Ясеневом лесу, где происходит кошмарное вторжение, и вернитесь к полевому командиру Ханнале.", description = "Пока нас отвлекают демоны, Изумрудный Сон постепенно превращается в кошмар. Поспеши! Пройди через портал Изумрудного Сна в Тенистую Крону и отправляйся в область кошмарного вторжения в Сатирнааре. Найди потерянный свиток, где записано Азшарское пророчество, и принеси его мне.", progress = "Принес Азшарское пророчество?", completion = "Отличная работа! Мы непременно отблагодарим тебя за помощь. Может, еще задание выполнишь?", rewards = "Вы получите:\n\nЗадание: Ясеневый лес"},
[81776] = {title = "Ясеневый лес, задание IX: усиленное Сном яйцо дракона", objective = "Найдите усиленное Сном яйцо дракона в развалинах в центре Лесной Песни в Ясеневом лесу, где происходит кошмарное вторжение, и вернитесь к полевому командиру Ханнале.", description = "Пока нас отвлекают демоны, Изумрудный Сон постепенно превращается в кошмар. Поспеши! Пройди через портал Изумрудного Сна в Тенистую Крону и отправляйся в область кошмарного вторжения в Лесной Песни. Найди усиленное Сном яйцо дракона и принеси его мне.", progress = "Принес яйцо?", completion = "Отличная работа! Мы непременно отблагодарим тебя за помощь. Может, еще задание выполнишь?", rewards = "Вы получите:\n\nЗадание: Ясеневый лес"},
[81777] = {title = "Ясеневый лес, задание X: сон-корень", objective = "Соберите 10 сон-корней в областях кошмарного вторжения в Ясеневом лесу и вернитесь к полевому командиру Ханнале.", description = "Пока нас отвлекают демоны, Изумрудный Сон постепенно превращается в кошмар. Поспеши! Пройди через портал Изумрудного Сна в Тенистую Крону и собери сон-корни в областях кошмарного вторжения. Их магическая сила может исцелить больную землю. Но тебе понадобится помощь травника.", progress = "Принес сон-корни?", completion = "Отличная работа! Мы непременно отблагодарим тебя за помощь. Может, еще задание выполнишь?", rewards = "Вы получите:\n\nЗадание: Ясеневый лес"},
[81778] = {title = "Ясеневый лес, задание XI: пыль из ложного золота", objective = "Соберите 10 горстей пыли из ложного золота в областях кошмарного вторжения в Ясеневом лесу и вернитесь к полевому командиру Ханнале.", description = "Пока нас отвлекают демоны, Изумрудный Сон постепенно превращается в кошмар. Поспеши! Пройди через портал Изумрудного Сна в Тенистую Крону и собери пыль из ложного золота в областях кошмарного вторжения. Ее магическая сила может исцелить больную землю. Но тебе понадобится помощь рудокопа.", progress = "Принес пыль из ложного золота?", completion = "Отличная работа! Мы непременно отблагодарим тебя за помощь. Может, еще задание выполнишь?", rewards = "Вы получите:\n\nЗадание: Ясеневый лес"},
