[81787] = {title = "Внутренние земли, задание II: победа над гигантскими черепахами", objective = "Убейте 20 ротохватов воды снов в Шаол'вата во Внутренних землях, где происходит кошмарное вторжение, и вернитесь к полевому командиру Корлиану.", description = "Пока нас отвлекают демоны, Изумрудный Сон постепенно превращается в кошмар. Поспеши! Пройди через портал Изумрудного Сна в Серадан и отправляйся в область кошмарного вторжения в Шаол'вата. Истреби гигантских черепах и возвращайся обратно.", progress = nil, completion = "Отличная работа! Мы непременно отблагодарим тебя за помощь. Может, еще задание выполнишь?", rewards = "Следующее заклинание будет наложено на вас:\n\nЗадание выполнено\n\nВы получите:\n\nИзумрудный осколокЗадание: Внутренние земли"},
[81788] = {title = "Внутренние земли, задание III: победа над драконами", objective = "Убейте 10 дракончиков гнева и 3 драконидов – ловцов звезд в Агол'вата во Внутренних землях, где происходит кошмарное вторжение, и вернитесь к полевому командиру Корлиану.", description = "Пока нас отвлекают демоны, Изумрудный Сон постепенно превращается в кошмар. Поспеши! Пройди через портал Изумрудного Сна в Серадан и отправляйся в область кошмарного вторжения в Агол'вата. Истреби драконов и возвращайся обратно.", progress = nil, completion = "Отличная работа! Мы непременно отблагодарим тебя за помощь. Может, еще задание выполнишь?", rewards = "Следующее заклинание будет наложено на вас:\n\nЗадание выполнено\n\nВы получите:\n\nИзумрудный осколокЗадание: Внутренние земли"},
[81789] = {title = "Внутренние земли, задание IV: доклад о драконах", objective = "Отправляйтесь в область кошмарного вторжения в Агол'вата во Внутренних землях и заберите доклад разведки у хранителя снов Ланинара, который ждет у арки, а затем вернитесь к полевому командиру Корлиану.", description = "Пока нас отвлекают демоны, Изумрудный Сон постепенно превращается в кошмар. Поспеши! Пройди через портал Изумрудного Сна в Серадан и отправляйся в область кошмарного вторжения в Агол'вата. Забери доклад разведки у хранителя снов Ланинара и возвращайся сюда.", progress = "Принес доклад?", completion = "Отличная работа! Мы непременно отблагодарим тебя за помощь. Может, еще задание выполнишь?", rewards = "Следующее заклинание будет наложено на вас:\n\nЗадание выполнено\n\nВы получите:\n\nИзумрудный осколокЗадание: Внутренние земли"},
[81790] = {title = "Важные материалы", objective = "Найдите материалы, перечисленные в записке Грегори, и принесите их Грегори к истоку водопада Отравленной Крови в Оскверненном лесу.", description = "Каждая сфера Эха связана с отдельным аспектом того, кто эти сферы создал. Вот почему ты не сможешь уничтожить эту находку так же, как ты <уничтожил/уничтожила> сферу Алталакса в Ясеневом лесу. Я знаю один ритуал, который может помочь, но для него нужны материалы с особыми магическими свойствами. Некоторые у нас уже есть, а вот за остальными придется поохотиться. Держи. Это поможет тебе в поисках.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[81817] = {title = "Внутренние земли, задание V: доклад о черепахах", objective = "Отправляйтесь в область кошмарного вторжения в Шаол'вата во Внутренних землях и заберите доклад разведки у хранительницы снов Санатель, которая ждет за барабаном, а затем вернитесь к полевому командиру Корлиану.", description = "Пока нас отвлекают демоны, Изумрудный Сон постепенно превращается в кошмар. Поспеши! Пройди через портал Изумрудного Сна в Серадан и отправляйся в область кошмарного вторжения в Шаол'вата. Забери доклад разведки у хранительницы снов Санатель и возвращайся сюда.", progress = "Принес доклад?", completion = "Отличная работа! Мы непременно отблагодарим тебя за помощь. Может, еще задание выполнишь?", rewards = "Следующее заклинание будет наложено на вас:\n\nЗадание выполнено\n\nВы получите:\n\nИзумрудный осколокЗадание: Внутренние земли"},
