[81857] = {title = "Фералас, задание III: победа над драконами", objective = "Убейте 15 взбесившихся дракончиков и 5 драконидов-берсерков в Онейросе в Фераласе, где происходит кошмарное вторжение, и вернитесь к полевому командиру Аруннель.", description = "Пока нас отвлекают демоны, Изумрудный Сон постепенно превращается в кошмар. Поспеши! Пройди через портал Изумрудного Сна в Сонные Ветви и отправляйся в область кошмарного вторжения в Онейросе. Истреби драконов и возвращайся обратно.", progress = nil, completion = "Отличная работа! Мы непременно отблагодарим тебя за помощь. Может, еще задание выполнишь?", rewards = "Следующее заклинание будет наложено на вас:\n\nЗадание выполнено\n\nВы получите:\n\nИзумрудный осколокЗадание: Фералас"},
[81864] = {title = "Фералас, задание IX: бессвязные записи гарпии", objective = "Найдите бессвязные записи гарпии в юго-западной беседке в руинах Яростного Ветра в Фераласе, где происходит кошмарное вторжение, и вернитесь к полевому командиру Аруннель.", description = "Пока нас отвлекают демоны, Изумрудный Сон постепенно превращается в кошмар. Поспеши! Пройди через портал Изумрудного Сна в Сонные Ветви и отправляйся в область кошмарного вторжения в руинах Яростного Ветра. Найди бессвязные записи гарпии и принеси их мне.", progress = "Принес записи?", completion = "Отличная работа! Мы непременно отблагодарим тебя за помощь. Может, еще задание выполнишь?", rewards = "Следующее заклинание будет наложено на вас:\n\nЗадание выполнено\n\nВы получите:\n\nИзумрудный осколокЗадание: Фералас"},
[81900] = {title = "Пылающий зверь", objective = "Найдите знатока зверей, обитающих в Выжженных землях.", description = "Перед вами резное изображение двухголового зверя, который выбирается из Темного портала. Из пастей его хлещет пламя Скверны. Под картиной вы замечаете надпись: \"Калефакт Освобожденный\". \n\nЧто-то подсказывает вам, что сумеречные сектанты хотят призвать эту тварь и подчинить ее себе.\n\nПоразмыслив, вы решаете отправиться в Выжженные земли. Быть может, там найдется кто-нибудь, кому знаком этот жуткий зверь.", progress = nil, completion = "Расскажи об этом звере, |3-6(тролль). Не исключено, что у нас одни интересы.", rewards = nil},
[81924] = {title = "Мудрость хранителей", objective = "Пройдите испытания духов-хранителей Фераласа, Азшары и Внутренних земель, а затем вернитесь к Тирисию в Фералас.", description = "Какие бы древние знания калдорай ты ни <искал/искала>, <класс>, здесь ты не найдешь ничего – только руины и развалины.\n\nНо знай: хоть оболочка мертва, дух продолжает жить.\n\nНайди духов-хранителей Азшары, Внутренних земель и Фераласа. Ты узнаешь их по святилищам. Докажи, что <достоин/достойна>, и они поделятся с тобой мудростью. Тогда она не канет в забвение, как это случилось со всем, что ты здесь видишь.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nРуна периода цветенияСемя обновления"},
[81947] = {title = "Кровавое святилище", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье понимания"},
[81949] = {title = "Легенды жрецов моря", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье понимания"},
[81951] = {title = "О переходности и магии", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье понимания"},
[81952] = {title = "Повседневный этикет", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье понимания"},
[81953] = {title = "Каменный эскиз", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье понимания"},
[81954] = {title = "Ядовитые странствия", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье понимания"},
[81955] = {title = "Металлический разум", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье понимания"},
[81956] = {title = "Кодекс кудесника", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nЗаклятье понимания"},
[81967] = {title = "Сокровище из иного мира", objective = "Забирай, босс!Вы получите:\n\n", description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nСокровище из иного мира"},
[81974] = {title = "Мусор для Зири", objective = "Поговорите с Зири \"Гаечный Ключ\" Шестерец в Гномрегане.", description = "Вы обнаружили еще одно ядро процессора Г-7. Оно явно знавало лучшие времена. Изнутри сочится едкая жидкость, похожая на чернила. Скорее всего, ядро уже нерабочее, но все равно стоит показать его Зири: вдруг она куда-нибудь его приспособит.", progress = "Что это у тебя там, Делреди?", completion = "Ух ты! Ядро процессора Г-7. Не думаю, что когда-нибудь такое видела. Знаешь, на твоем месте я бы его выкинула подальше. Я слышала, они опасны.", rewards = "Вы получите:\n\n"},
[81975] = {title = "Опасная деталь", objective = "Поговорите с Зири.", description = "Чего? Ты что, головой <ударился/ударилась>? С чего бы мне просить ядро Г-7? Все, что требовалось этому ведру с гайками, – пара патронных предохранителей, мифриловые слитки и капля таинственной субстанции. И ничего больше! Если я вставлю рабочее ядро Г-7 в \"Утилизатор\", то... да я даже не знаю, что произойдет! Ничего хорошего, это уж точно. Может, взрыв! А может, пожар! А может, вообще монстры из других измерений полезут! Ужас да и только!", progress = nil, completion = "Да как ты вообще могла подумать, что я суну Г-7 в \"Утилизатор\"! Не хочу помирать раньше времени, знаешь ли.\n\n&lt;Зири мрачно усмехается и возвращается к работе.&gt;", rewards = "Вы получите:\n\n"},
[81986] = {title = "Пора просыпаться от кошмара", objective = "Уничтожьте Слияние Кошмара и принесите таинственной незнакомке все, что добудете.", description = "Теперь у тебя есть устройство Зири, а значит, пора поохотиться. Собери всех союзников, кого сможешь найти, и возвращайся в Кошмар через портал в Тенистой Кроне в Ясеневом лесу. Найди Слияние Кошмара и уничтожь его.\n\nО, и еще кое-что... у чудовища есть одна... штучка, которая мне очень нужна. Принеси все, что найдешь на теле зверушки, и я щедро тебя награжу.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЛишенное энергии оплечье ночных кошмаров"},
[81987] = {title = "Проблемы с гномами...", objective = "Принесите 5 гоблинских мин Максимилиану \"Ремонтнику\" на Мерцающую равнину.", description = "Эй, иди-ка сюда. Дай на тебя взглянуть. Мм-м, все как я и думал! Мастера гоблинских искусств за милю видать. У тебя пятна сажи на костяшках, как и у всех нас. Слушай, мне тут помощь нужна.\n\nМне поручили наставлять собратьев-гоблинов, дабы мы победили в гонке. Но эти хитрые гномы тоже притащили эксперта! И понемногу нас обходят! У меня есть кое-какая мысль... можешь раздобыть для меня пару гоблинских мин? Ты же умеешь их делать?Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[82001] = {title = "...Требуются гоблинские решения", objective = "Принесите рог громового стегодона Максимилиану \"Ремонтнику\".", description = "У меня плохие новости. Этот гномий эксперт на шаг впереди меня. Оказывается, их гонщик вовсе не поедет, а полетит!\n\nОни покрыли трассу штуковинами, которые зовутся \"магниты\", и собираются парить над землей! А значит, никаких взрывов! Ну что ж, раз они не хотят к минам, то мины придут к ним!\n\nНам нужен мощный электрический заряд. Отправляйся в юго-западную часть кратера Ун'Горо и принеси рог громового стегодона.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[82004] = {title = "Плата за исчезновение", objective = "Примите взятку у Вжикопрыга Медномота.", description = "Я не могу потерять лицо и деньги из-за вас с вашим гоблинским дружком. Вот что я предлагаю: я буду делиться с тобой секретами гномьих инженеров, а ты уходишь. Пропадаешь. Испаряешься. И чтобы я тебя больше здесь не видел!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nИнженерный обменный купон"},
[82008] = {title = "Проблемы с гоблинами...", objective = "Принесите Вжикопрыгу Медномоту 2 пояса гномов, хранящих от вреда.", description = "Приветствую, <многоуважаемый/многоуважаемая> коллега! Кажется, я вижу перед собой интеллектуала высочайшего класса! Мне как раз нужен кто-нибудь способный. Начнем с малого! На трассе то и дело происходят взрывы. Подозрительно, не так ли? Безопасность водителей – моя главная задача. Принеси пару поясов гномов, хранящих от вреда! Уверен, это решит нашу маленькую проблему.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[82013] = {title = "Плата за исчезновение", objective = "Примите взятку у Максимилиана \"Ремонтника\".", description = "Давай-ка расскажу тебе, что будет дальше. Ты мне слишком дорого обходишься, так что вот как мы с тобой поступим. Ты уходишь. Прямо сейчас. Но раз в неделю, так и быть, можешь сюда заглядывать. Разрешаю.\n\nКак знать, быть может, если ты сюда придешь, то увидишь на земле кое-что. Мелочь. Мусор. Может, тебе захочется его поднять, чтобы... ну, не загрязнять природу. А я в благодарность тебе кое-что подарю. Люблю природу, знаешь ли.\n\nКак тебе?", progress = nil, completion = "Увидимся через неделю... дружище.", rewards = "Вы получите:\n\nИнженерный обменный купон"},
[82016] = {title = "Напиток могущества Атал'ай", objective = "У меня для тебя отличная сделка, браток! Принеси мне колдунство, которым владеют только Атал'ай, и я такое тебе за него дам, что глазам своим не поверишь. Знай, дружище, это колдунство действует только в болотах, где зародилось. Говорят, Атал'ай занимаются запретным ведьмовством, и я кой-чего об этом знаю. \n\nНу, как тебе такое? Мы договорились?", description = nil, progress = "У меня для тебя отличная сделка, браток! Принеси мне колдунство, которым владеют только Атал'ай, и я такое тебе за него дам, что глазам своим не поверишь. Знай, дружище, это колдунство действует только в болотах, где зародилось. Говорят, Атал'ай занимаются запретным ведьмовством, и я кой-чего об этом знаю. \n\nНу, как тебе такое? Мы договорились?", completion = "Хе, ты об этом не пожалеешь, братишка!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЖивительное колдунство Атал'айВоенное колдунство Атал'айКолдунство запретной магии Атал'ай"},
[82017] = {title = "Слияние Кошмаров", objective = "Найдите Логанаара на Лунной поляне", description = "Аура ужаса, которую ты <почувствовал/почувствовала>, исходит не от места, но от существа. От смертоносного порождения мрака. От искаженного, извращенного отражения темнейших сторон мироздания, которые слились в чистый кошмар. Я не могу толком объяснить, откуда это узнала... кажется... оно мне снилось. Или, верней, его мне показали. Прошу, отправляйся на Лунную поляну и найди там друида Логанаара. Может, у нас еще получится остановить чудовище, пока оно не стало слишком сильным.", progress = nil, completion = "Ты принес страшные вести. Если Ханнала говорит правду, то дела у нас только что стали еще хуже.", rewards = "Вы получите:\n\n"},
[82018] = {title = "Итар", objective = "Найдите Итара где-то на Болоте Печали.", description = "Знаком ли тебе храм Атал'Хаккар? У него долгая история, но я ее пересказывать не буду. Все, что тебе надо знать, – это то, что сейчас там заправляют могущественные зеленые драконы. Главный страж храма – великий дракон по имени Эраникус, и он тесно связан со Сном. Я надеюсь, он сможет нам помочь. Отправляйся на Болото Печали и найди там разведчика Итара. Он должен знать, как связаться с Эраникусом.", progress = nil, completion = "Ищешь Эраникуса? Боюсь, ты невовремя, |3-6(Охотник). В храме Атал'Хаккар творится что-то неладное. Я тебе все расскажу.", rewards = "Вы получите:\n\n"},
[82019] = {title = "Погибший храм", objective = "Выясните, что происходит в храме Атал'Хаккар.", description = "В былые дни так называемый Затонувший храм населяли тролли-сектанты, которые пытались возродить древнее кровожадное божество – Хаккара Свежевателя Душ. Но прежде чем Атал'ай хоть что-нибудь успели, на них обрушился гнев Изеры, и храм опустился в трясину. Охранять его Изера поручила дракону Эраникусу. Недавно до меня дошли слухи, что в храме опять завелись тролли. Я боюсь за драконов.\n\nПрошу тебя. отправляйся в храм и узнай, что происходит.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[82020] = {title = "Возвращение на Лунную поляну", objective = "Вернитесь к Логанаару на Лунную поляну.", description = "Возвращайся к Логанаару и расскажи о том, что мы узнали. А я пока сам отправлюсь в храм и попытаюсь связаться с драконами или хотя бы выяснить чуть больше.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nDNT SF Phase\n\nВы получите:\n\n"},
[82021] = {title = "Удачный поворот событий", objective = "Выслушайте таинственную незнакомку.", description = "Привет тебе, <имя>! Я просто стояла тут рядом, любовалась видами и ненароком подслушала ваш разговор. Да, положение у вас незавидное. К счастью, у меня найдется кое-что, что поможет разобраться с этим милым \"злобным всепожирающим монстром из кошмаров\".Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[82023] = {title = "Потерянные наручи", objective = "Найдите логово зверя, о котором говорил раненый гном, и заберите усиленные Бездной тяжелые наручи.", description = "Видишь ли, я знаменитый рыцарь. И недавно я вознамерился избавить эту землю от страшного зла, которое обитает на ближайшем островке к востоку отсюда. Я выследил чудовище и сразился с ним в великой битве. Мы сражались часами, пока зверь наконец не сдался и не сбежал. Наверняка он уже издох от смертельных ран. Ну а я так утомился, что еле добрался до города, а потом сразу упал от усталости. Должно быть, я потерял наручи, пока бился со злом.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nРазряженные усиленные Бездной тяжелые наручи"},
[82043] = {title = "Дикие боги", objective = "Добудьте зелье шепота ветра в Джинта'Алоре во Внутренних землях, а потом используйте его на вершине Курганов Иглошкуров и поговорите с духом Агамаггана.", description = "С хиджальскими лоа что-то не то. За этой горой тысячи лет присматривали самые сильные духи природы, но теперь они пропадают, один за другим.\n\nЖил тут когда-то один древний лоа, Агамагган. Он был самым великим из всех, пока не помер. Но, к счастью, тролли Амани умеют говорить с мертвецами. Найди вуду, которое они используют, и отнеси в Курганы Иглошкурых. Поговори с Агамагганом и выясни, что творится с его сородичами.", progress = nil, completion = "Пусть мироздание сокрыто от меня пеленою смерти, я все равно почувствовал, как на гору Хиджал опустилась тень.\n\nВозьми эту вещь, смертный. Она тебе понадобится.", rewards = "Вы получите:\n\nРев Агамаггана"},
[82044] = {title = "Дикие боги", objective = "Отдайте дикие подношения эмиссару племени Темнозубов в Оскверненном лесу. Чтобы получить дикие подношения, вызовите на бой безумную древнюю богиню, используя рев Агамаггана, и победите ее.", description = "В Изумрудном Сне пустила корни тьма. Она же накрыла древних духов Хиджала, смутила их, напугала.\n\nНайди этих безумных духов, <смертный/смертная>, и пусть мой рев призовет их к бою.\n\nКогда ты убьешь оскверненные оболочки, души освободятся и очистятся, а затем возродятся вновь.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nМудрость Хиджала"},
[82055] = {title = "Колода карт Новолуния: Дюны", objective = "Принесите колоду Дюн на ярмарку Новолуния.", description = "Как только вы собираете вместе восемь карт из колоды Дюн, девятая карта с такой же \"рубашкой\" мистическим образом появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько недель. Придется подождать до следующего раза...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКарта Новолуния: песчаная буря"},
[82056] = {title = "Колода карт Новолуния: Кошмары", objective = "Принесите колоду Кошмаров на ярмарку Новолуния.", description = "Как только вы собираете вместе восемь карт из колоды Кошмаров, девятая карта с такой же \"рубашкой\" мистическим образом появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько недель. Придется подождать до следующего раза...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКарта Новолуния: мучение"},
[82057] = {title = "Колода карт Новолуния: Чума", objective = "Принесите колоду Чумы на ярмарку Новолуния.", description = "Как только вы собираете вместе восемь карт из колоды Чумы, девятая карта с такой же \"рубашкой\" мистическим образом появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько недель. Придется подождать до следующего раза...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКарта Новолуния: гниение"},
[82058] = {title = "Колода карт Новолуния: Дикая природа", objective = "Принесите колоду Дикой природы на ярмарку Новолуния.", description = "Как только вы собираете вместе восемь карт из колоды Дикой природы, девятая карта с такой же \"рубашкой\" мистическим образом появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько недель. Придется подождать до следующего раза...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКарта Новолуния: разрастание"},
[82062] = {title = "Во веки веков", objective = nil, description = "Пришлось убедиться, что мы можем тебе доверять. Друзей в наше время найти непросто. \n\nНа Азероте завелось зло. Третья сторона. И Орда, и Альянс неосознанно ему помогают. Все, что мы можем, – это сдерживать врага и добывать информацию.\n\nВот, держи. Это поднимет твой боевой дух и напомнит о лучших временах. Скоро нам потребуется вся сила, какая у нас только есть. И твоя тоже.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nТребовательная форма ПримоКорм для учениковГенератор радуги"},
[82068] = {title = "Борьба с кошмарами", objective = "Выполните задание кошмарного вторжения во Внутренних землях или в Фераласе и доложите Корлиану или Аруннель.", description = "Выполните сегодня задание кошмарного вторжения во Внутренних землях или в Фераласе и получите дополнительную награду.", progress = nil, completion = "Отлично, Делреди!", rewards = "Вы получите:\n\n"},
[82074] = {title = "Ответ на зов огня", objective = "Добудьте 3 стихийных сущности у элементалей воды, обитающих на Забытом берегу напротив острова Сардор в Фераласе, и объедините их с фрагментом огня, чтобы призвать помощь у оскверненного святилища.", description = "Ты <сильный/сильная>. Достаточно <сильный/сильная>.\n\n<Элементаль мерцает и искрится.>\n\nНужны стихии Фераласа. Сущность. Тогда найдешь святилище.\n\nВозьми фрагмент. Поможет.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[82081] = {title = "Прерванный ритуал", objective = "Принесите лопаточную кость мертвого божества Молтору на остров Йоджамба.", description = "Эту безупречную лопаточную кость трудно спутать с чем-то еще. Хаккара призвали в этот мир, а потом победили. Тролли с острова Йоджамба наверняка захотят узнать о том, что произошло в Затонувшем храме.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо предвестника с когтем драконаКольцо кровавого пророка с когтем драконаКольцо берсерка с когтем драконаКольцо владыки мира с когтем драконаКольцо ловчего с когтем дракона"},
[82083] = {title = "Прерванный ритуал", objective = "Принесите лопаточную кость мертвого божества Молтору на остров Йоджамба.", description = "Эту безупречную лопаточную кость трудно спутать с чем-то еще. Хаккара призвали в этот мир, а потом победили. Тролли с острова Йоджамба наверняка захотят узнать о том, что произошло в Затонувшем храме.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо предвестника с когтем драконаКольцо кровавого пророка с когтем драконаКольцо берсерка с когтем драконаКольцо владыки мира с когтем драконаКольцо ловчего с когтем дракона"},
[82084] = {title = "Урок грамотности", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\n[DNT] Temporal Anomaly\n\nВы получите:\n\nПерсональная книга заклинаний"},
[82089] = {title = "Мастер трансмутации", objective = "Принесите Кримеону Лаблейду три арканитовых слитка.", description = "Трансмутация – это уникальный навык, которым владеют все талантливые алхимики. Но, как и везде, только преданный делу мастер достигнет в нем больших высот. Может, у тебя есть потенциал, но это еще не все. Ты <должен/должна> доказать, что <готов/готова> отбросить все лишнее и погрузиться в науку с головой, дабы обрести подлинные знания.\n\nПринеси мне 3 арканитовых слитка, и я поверю, что ты хочешь посвятить себя трансмутации.", progress = nil, completion = nil, rewards = nil},
[82090] = {title = "Миксология: весело и полезно", objective = "Принесите мастеру-миксологу Бликсу 10 зелий невидимости, 10 эликсиров истребления демонов и 5 эликсиров мудрецов.", description = "Каждый стоящий алхимик скажет, что самое главное в этой науке – прибыль. Берешь дешевые материалы, налаживаешь производство и продаешь по заоблачным ценам. А что если я скажу, что есть один способ извлечь максимальную выгоду из ингредиентов? Как самопровозглашенный мастер миксологии, я могу вывести твои зелья и эликсиры на новый уровень. Принеси мне 10 зелий невидимости, 10 эликсиров истребления демонов и 5 эликсиров мудрецов – и я поделюсь всем, что знаю.", progress = nil, completion = nil, rewards = nil},
[82093] = {title = "Тропический дуриан", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nТропический дуриан"},
[82094] = {title = "Перстни затерянного храма", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПерстень могущества Атал'айМагический перстень Атал'айПерстень безмятежности Атал'ай"},
[82095] = {title = "Бог Хаккар", objective = "Отнесите заполненное яйцо Хаккара Йе'кинье в Танарис.", description = "Пришло время взять в плен сущность аватары Хаккара.\n\nОтнеси яйцо Хаккара в святилище Падшего бога в Затонувшем храме Азерота. Призови силу яйца и разбуди мертвого бога.\n\nНо знай, что даже новорожденная аватара обладает невообразимой силой и будет сопротивляться со всей яростью, на какую способна.\n\n Одолей ее и помести ее сущность в яйцо Хаккара.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nШлем АвангардаКортик жизненной силыДрагоценный венец\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[82099] = {title = "Туман зла", objective = "Соберите 5 образцов тумана Атал'ай и принесите их Муиджину в Кратер Ун'Горо.", description = "Честно говоря, <имя>, я таких растений прежде не видел. Возможно, имеет смысл наведаться в этот кратер...\n\nВ любом случае, думаю, я знаю, что ищет Муиджин. Ему нужен туман Атал'ай. Это жуткая субстанция, которую весьма сложно собрать, однако с ним можно управлять маленькими монстрами.\n\nНайди храм Атал'Хаккар на Болоте Печали. Там обитают глубинные скрытни, мракочерви и слизнюки, с которых и можно собрать туман. Удачи тебе, <имя>!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[82100] = {title = "Храм Атал'Хаккар", objective = "Соберите 20 фетишей Хаккара и принесите их Фел'зерулу в Каменор.", description = "Так он говорил о пророчестве Джаммал'ана?\n\nДуховный вождь Атал'ай верит, что, когда Хаккар вернется на Азерот из Пустоты, он дарует племени бессмертие.\n\nПо мне дураком надо быть, чтобы раньше срока вызывать светопреставление.\n\nНо ты говоришь, этот изгой упоминал зачарованные амулеты? А вот это уже важно. Если амулеты – ключ к ритуалу Атал'ай, который и привел ко всей заварухе, мы должны понять, в чем их сила.\n\nОтправляйся в Храм и добудь амулеты!Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nТалисман-хранитель"},
[82101] = {title = "Топливо для шокера", objective = "Доставьте незаряженный шокер и 5 образцов тумана Атал'ай Лариону в Укрытие Маршалла.", description = "Тебе повезло, <имя>! Я тут работал над кой-какими собственными изобретениями, пока Марвон в отъезде. И вот моя последняя разработка – антижучиный шокер ближнего действия! Его надо совсем чуть-чуть поправить, и можно смело использовать против кровоцветов-паразитов.\n\nС удовольствием подарю тебе одну из тестовых моделей, однако ей нужно топливо – туман Атал'ай. Его можно собрать с трясинных скрытней, мракочервей и слизнюков, которые обитают в храме Атал'Хаккар.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\n"},
[82102] = {title = "Сущность Эраникуса", objective = "Поместите сущность Эраникуса в купель сущности в его логове в Затонувшем храме.", description = "Вы касаетесь камня и слышите голос, звучащий в вашем сознании.\n\n\"Внемли моей мольбе, о <смертный/смертная>. Имя мне Эраникус из рода зеленых драконов. Я пытался положить конец богохульным деяниям троллей, но потерпел неудачу. Я вдохнул частицу своей души в этот кристалл. Однако я чувствую, что моя связь с Изумрудным Сном теряется и меня поглощает хаос. Прошу, помести этот кристалл в купель сущности в моем логове – пусть магия очистит мое сознание от скверны. Тогда я обрету покой\".", progress = "Приблизившись к купели, о которой говорил Эраникус, вы снова слышите его голос.\n\n\"Да, смертный, эта купель освободит неоскверненную частицу моего разума, заключенную в камне. Помести его в купель, и пусть магия зеленых драконов очистит мою сущность от скверны. Только так я обрету истинную свободу, а драконы вернут себе власть над Атал'ай\".", completion = "Вы опускаете камень в купель сущности. \"Благодарю тебя, смертный, теперь я... О нет! Не может быть! Порча проклятого бога проникла даже в эту купель! Нет! Моя сущность! КАК БОЛЬНО! Мою душу поглощает вечный кошмар!\"\n\n\"Умоляю тебя, смертный, найди одного из зеленых драконов... он прекратит... мои мучения... помоги... я во тьме... агонии не будет конца... пощады... только не....\"", rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nСкованная сущность Эраникуса"},
[82104] = {title = "Пророк Джаммал'ан", objective = "Принесите голову Джаммал'ана изгнаннику Атал'ай во Внутренние земли.", description = "Мои товарищи из клана Сухокожих не любят, когда чужаки приходят к ним домой.\n\nА у меня и дома-то нет. Я жил в племени Атал'ай на Болоте Печали, но меня оттуда изгнали.\n\nНашему духовному лидеру Джаммал'ану было, как он сам говорил, \"видение\". Он считает, что если призвать бога Хаккара, то этот бог дарует Атал'ай бессмертие.\n\nЯ посоветовал ему быть осторожнее. Что если это видение – пустой обман? Ну и поплатился.\n\nТеперь я хочу отомстить. Принеси мне голову Джаммал'ана. Может, тогда мой народ освободится!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПоножи Странника дождяШлем изгнания\n\nСледующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы также получите:\n\n"},
[82106] = {title = "Создание камня силы", objective = "Принесите вудуистские перья Ашламу Отважный Кулак.", description = "Теперь мы сможем создать оружие против нежити из бездействующих камней Плети. Задание непростое, <имя>. Магией, которая может обратить зло против самого себя, владеют лишь тролли из Затонувшего храма.\n\nНайди там троллей Ранокола, Миджана, Золо, Хукку, Зул'Лора и Лоро. Не стоит их жалеть... их души запятнало зло.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nСвященный камень силыОсвященная сфераРыцарский перстеньКлинок из светлостали"},
[82107] = {title = "Вудуистские перья", objective = "Принесите вудуистские перья павшему герою Орды, забрав их у троллей в Затонувшем храме.", description = "Благодаря твоему благородству я обрел покой. Неправильно было бы ничего не предложить взамен.\n\nПри жизни я носил великолепное оружие и доспехи, но теперь они для меня бесполезны. Быть может, тебе они послужат лучше.\n\nОтправляйся к Затонувшему храму и уничтожь троллей-охранников Ранокола, Миджана, Золо, Хукку, Зул'Лора и Лоро. У них хранятся магические перья, которые могут на время вернуть мне тело, и я отдам тебе награду.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЩиток ЯростиАлмазная фляжкаОстростальные наплечники"},
[82112] = {title = "Лучший ингредиент", objective = "Добудьте гнилую лозу у стража в глубинах Затонувшего храма и вернитесь к Землепроходцу Торве.", description = "Как я и опасался – яд слишком слаб для такого большого зверя.\n\nЧтобы создать более мощный яд, мне потребуются лучшие ингредиенты. Отправляйся в самую глубину храма Атал'Хаккар, раскрой секреты алтаря и отними у местного стража гнилую лозу. Храм опасен, поэтому не ходи <один/одна>.\n\nВозвращайся ко мне, когда выполнишь задание.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nСедая шкураОблачение ЛесаПосох Лунной тени"},
[82114] = {title = "Уничтожить Морфаза", objective = "Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему.", description = "В глубинах храма Атал'Хаккар скрывается зеленый дракон по имени Морфаз.\n\nМного лет назад он напал на меня из засады и проглотил целиком моего ученика. Мне не впервой терять ученика, однако именно этот, проглоченный, нес кристалл тайной магии небывалой мощи.\n\nСобери сильных соратников и отправляйся в храм. Уничтожь Морфаза и принеси мне мой кристалл.Следующее заклинание будет наложено на вас:\n\n", progress = nil, completion = nil, rewards = "Следующее заклинание будет наложено на вас:\n\nПриток опыта\n\nВы получите:\n\nЛедовый шипПодвеска из чародейного кристаллаОгненный рубин"},
[82209] = {title = "Награда за воду", objective = "Опять ты здесь, Октавиос? Если принесешь еще пять бурдюков с водой Скитальцев Пустыни, то тебя ждет еще один именной полевой набор!", description = nil, progress = "Опять ты здесь, Октавиос? Если принесешь еще пять бурдюков с водой Скитальцев Пустыни, то тебя ждет еще один именной полевой набор!", completion = "Великолепно! Чем больше мехов с водой нам удастся добыть, тем дальше катастрофа! Можешь таскать их сотнями, и за каждые пять получишь награду.", rewards = "Вы получите:\n\nПолевой набор Водной компании Прибамбасска"},
[82210] = {title = "Ожерелья троллей", objective = "Ты уже выполнил мое задание, но если захочешь принести еще тролльих ожерелий, то я с радостью приму их. Клан Громового Молота это оценит – если ты нам помогаешь, то и мы с радостью поможем тебе!\n\nПриноси по пять ожерелий за раз, Ванпачмен.", description = nil, progress = "Ты уже выполнил мое задание, но если захочешь принести еще тролльих ожерелий, то я с радостью приму их. Клан Громового Молота это оценит – если ты нам помогаешь, то и мы с радостью поможем тебе!\n\nПриноси по пять ожерелий за раз, Ванпачмен.", completion = "Чем больше ожерелий, тем меньше троллей во Внутренних Землях! Ты молодец, Ванпачмен. Так держать!", rewards = nil},
[82271] = {title = "Обмен: светящаяся кровь скорпида", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПодарочный купон ярмарки Новолуния"},
