[82275] = {title = "Большая черная палица", objective = "Чтобы доказать, что я – самая сильная женщина в мире, во время представления я должна разбить большой черной палицей любой предмет по выбору зрителей.\n\nПожалуйста, достань мне большую черную палицу, Ксайдар.", description = nil, progress = "Чтобы доказать, что я – самая сильная женщина в мире, во время представления я должна разбить большой черной палицей любой предмет по выбору зрителей.\n\nПожалуйста, достань мне большую черную палицу, Ксайдар.", completion = "То, что надо! У этой палицы такой увесистый наконечник! Да я ею что угодно в щепки разнесу. Надеюсь, она не развалится во время представления.\n\nВот твои купоны, Ксайдар. Веселой ярмарки!", rewards = "Вы получите:\n\nПодарочный купон ярмарки Новолуния"},
[82276] = {title = "Ритуалы Силы", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Вы получите:\n\nПодарочный купон ярмарки Новолуния"},
