[82307] = {title = "Полная партия", objective = "Ты что-то мне принес?", description = nil, progress = "Ты что-то мне принес?", completion = "Все на месте! Спасибо, Ксайдар. Эти припасы очень важны для фронта.", rewards = "Следующее заклинание будет наложено на вас:\n\nРепутация – фракция торговцев\n\nВы получите:\n\n"},
[82308] = {title = "Полная партия", objective = "Ты что-то мне принес?", description = nil, progress = "Ты что-то мне принес?", completion = "Все на месте! Спасибо, Иридиан. Эти припасы очень важны для фронта.", rewards = "Следующее заклинание будет наложено на вас:\n\nРепутация – фракция торговцев\n\nВы получите:\n\n"},
