[86326] = {title = "Сила пустыни", objective = "Поговорите с Селестразой, чтобы получить киражский резонирующий кристалл.", description = "В древние земли нередко ведут темные и глубокие туннели. Они не предназначены для созданий вроде тебя.", progress = nil, completion = "Твоя сила не осталась незамеченной, смертный. Пусть этот усмиренный силитид поможет тебе быстрее исследовать древние владения киражей.", rewards = "Вы получите:\n\nПрирученный силитид-танк"},
[86670] = {title = "Спаситель Калимдора", objective = "Принесите глаз К'Туна Анахроносу в Пещеры Времени.", description = "Пришла пора вернуться в Пещеры Времени, <господин/госпожа> <имя>. Анахронос ожидает тебя. Отдай ему глаз К'Туна – не сомневаюсь, он непременно захочет поместить его в коллекцию своего хозяина.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nАмулет Падшего богаПлащ Падшего богаКольцо Падшего бога\n\nСледующее заклинание будет наложено на вас:\n\nРод Ноздорму - фракция +1000\n\nВы также получите:\n\n"},
[86673] = {title = "Повергнутый Оссириан", objective = "Принесите голову Оссириана Неуязвимого командиру Мар'алиту в крепость Кенария.", description = "Смертельная угроза больше не нависает над нами. Безжалостный Оссириан повержен!\n\nОб этой победе должны узнать все жители Калимдора. Отнеси голову Оссириана командиру Мар'алиту в крепость Кенария.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nОберег Зыбучих песковАмулет Зыбучих песковКолье Зыбучих песковПодвеска Зыбучих песков\n\nВы также получите:\n\n"},
[86725] = {title = "Прах к праху", objective = "Найдите и принесите 5 порций силитиста к экстрактору силитиста и поговорите со старшим снабженцем экспедиции Анклсом в лагере Альянса возле улья Зора.", description = "О да, пустыня полна опасностей. И дело не только в изнуряющей жаре, палящем солнце, песке, проникающем в складки одежды, и морозных ночах.\n\nЯ говорю о других опасностях! Сперва это были только жуки, но теперь к ним прибавились эти жуткие громилы. Наши разведчики доложили, что отряд Орды вышел в пустыню и копается там в грязи! \n\nДля них это, конечно, нормально, но на этот раз они добывают силитист! Не хотелось бы, чтобы они разгадали тайны этого песка. Как старший снабженец экспедиции, я делаю конкурирующий заказ! Принеси мне эту грязь!", progress = nil, completion = nil, rewards = nil},
[86760] = {title = "Карты Новолуния: Звери", objective = "Принесите колоду Зверей на ярмарку Новолуния.", description = "Как только вы собираете вместе восемь карт из колоды Зверей, девятая карта с такой же \"рубашкой\" мистическим образом появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКарта Новолуния: Синий Дракон"},
[86761] = {title = "Карты Новолуния: Полководцы", objective = "Принесите карты Полководцев на ярмарку Новолуния.", description = "Как только вы собираете вместе восемь карт из колоды Полководцев, девятая карта с такой же \"рубашкой\" мистическим образом появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКарта Новолуния: Героизм"},
[86762] = {title = "Карты Новолуния: Элементали", objective = "Принесите колоду Элементалей на ярмарку Новолуния.", description = "Как только вы собираете вместе восемь карт из колоды Элементалей, девятая карта с такой же \"рубашкой\" мистическим образом появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКарта Новолуния: Мальстрим"},
[86763] = {title = "Карты Новолуния: Порталы", objective = "Принесите карты Порталов на ярмарку Новолуния.", description = "Как только вы собираете вместе восемь карт из колоды Порталов, девятая карта с такой же \"рубашкой\" мистическим образом появляется в колоде. На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\". Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев. Придется подождать до следующего раза...Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nКарта Новолуния: Круговерть Пустоты"},
[86964] = {title = "За сокровищами и славой!", objective = "Похоже, кто-то хотел нанять искателей приключений, чтобы добыть нечто ценное из склепов Каражана на перевале Мертвого Ветра. Вы не знаете, кто разместил это объявление и где его теперь искать, но значительная награда от такой известной и состоятельной организации, как Кирин-Тор, а также тайник с сокровищами, которые можно просто забрать, – это весьма заманчиво.\n\nОтправляйтесь на перевал Мертвого Ветра и исследуйте склепы за башней Каражан.", description = "Призываем всех искателей приключений и охотников за сокровищами! Да станет вам известно, что Кирин-Тор готов выплатить значительную сумму команде, которая сумеет спуститься в склепы под Каражаном и отыскать необходимый магический артефакт. Любые другие найденные сокровища, любопытные вещицы или монеты орден не интересуют. Их можно оставить себе в качестве дополнительной компенсации. Заинтересованным лицам следует обратиться... \n\n<Нижняя часть записки оборвана.>", progress = nil, completion = nil, rewards = nil},
[86965] = {title = "Непростые тени", objective = "Тьма, просачивающаяся из входа в склеп, не поддается разумению и не подчиняется естественному порядку вещей. Свет не проходит через нее и не рассеивает тени, а если тьма окутывает сточник света, то обволакивает полностью, не выпуская ни луча. Вы уверены, что если войдете в склеп прямо сейчас, то встретите свою погибель.\n\nЧтобы пройти дальше, нужно отыскать способ миновать эту тьму. Вы припоминаете, что в лагере на севере видели посланницу из Даларана. Может, она скажет что-нибудь дельное про мертвого искателя приключений и странную тьму?", description = "Когда вы склоняетесь над телом, вас внезапно начинают окутывать густые тени. Вы замечаете, что с их приближением свет вокруг тускнеет и гаснет. Это явно необычные тени. \n\nБросив беглый взгляд на вход в склеп, вы сразу понимаете, что зловещая тьма исходит из него. Вы с дрожью наблюдаете за тем, как новые чернильно-черные щупальца тянутся к свету, чтобы его погасить, и по вашей спине пробегает холодок.", progress = nil, completion = nil, rewards = nil},
[86966] = {title = "Поиски выживших", objective = "Постарайтесь найти выживших из злополучной экспедиции и узнать, что произошло в склепе.", description = "Вот как... Да, тело, о котором ты говоришь, действительно подходит под описание одного из тех путешественников. Насколько я помню, их было пятеро. Я уговаривала их не идти дальше, но они были непреклонны. Похоже, я не зря их предостерегала: никто из тех путешественников больше здесь не проходил. Я боялась, что случилось худшее, и, как видишь...\n\nГоворишь, ты <нашел/нашла> только труп той женщины? Быть может, на перевале еще остались выжившие?", progress = nil, completion = nil, rewards = nil},
[86967] = {title = "Спешим на помощь", objective = "Найдите ключ от клетки в пещере огров на перевале Мертвого Ветра и освободите раненого искателя приключений.", description = "<Один открытый глаз незнакомца останавливается на вас.>\n\nЭй, ты... Да, ты! Можешь меня отсюда вытащить? Я уже много часов лежу здесь, притворяясь мертвым, но проклятые огры могут в любой момент вспомнить, что я здесь, и прийти меня сожрать... или того хуже! \n\nКлетка заперта наглухо, но у одного из этих верзил должен быть ключ. Найди его и выпусти меня. Я буду перед тобой в долгу! \n\nЯ продолжу притворяться, пока ты будешь искать. А теперь иди... Только тихо!", progress = nil, completion = nil, rewards = nil},
[86968] = {title = "Боишься темноты?", objective = "Выслушайте рассказ Харрисона Джонса о том, что произошло в склепах Каражана.", description = "Спасибо, что <спас/спасла> мою шкуру в том лагере. Даже не знаю, что бы я делал.\n\nПока я тебя ждал, немного пообщался с этой милой дамой: она придумала пару возможных способов попасть в склеп, если, конечно, ты все еще <намерен/намерена> испытать там удачу.\n\nНо я слишком забегаю вперед. В конце концов, я сам обещал кое-что тебе рассказать.", progress = nil, completion = nil, rewards = nil},
[87360] = {title = "Падение Кел'Тузада", objective = "Отнесите талисман Кел'Тузада в часовню Последней Надежды в Восточных Чумных землях.", description = "От повелителя Наксрамаса осталась лишь эта филактерия. Голос рассудка подсказывает, что ее следует уничтожить, чтобы могучий лич не смог более возродиться. К счастью, вы не привыкли слушать внутренний голос.\n\nКое-кто из часовни Последней Надежды обещал недурно заплатить за этот талисман. Что с того, если Кел'Тузаду удастся вернуться?Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nЗнак ПобедителяЗнак Победителя\n\nВы также получите:\n\n"},
[87361] = {title = "Покой для усопших", objective = "Обратитесь за помощью в часовню Последней Надежды а Восточных Чумных землях.", description = "Вырванное из Тени Рока сердце слабо пульсирует у вас в руках.\n\nВы начинаете убирать жуткий орган в сумку, как вдруг вас охватывает сильнейшее чувство ярости, страха, а затем... печали.\n\nКогда наплыв эмоций проходит, вам кажется, будто вы только что прожили чью-то жизнь.\n\nБыть может, кто-то в часовне Последней Надежды сумеет объяснить это странное наваждение.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nОстанки доблести"},
[87362] = {title = "Надежда рождается во тьме", objective = "Заберите печать Рассвета.", description = "Наксрамас опаснее, чем все, с чем ты когда-либо <сталкивался/сталкивалась>. Это главное средоточие силы Кел'Тузада, где таятся кошмары, неведомые даже закаленным в бою ветеранам Серебряного Рассвета.\n\nВозьми эту печать. \n\nКогда отправишься в глубины некрополя, на тебя ляжет бремя наших надежд, <имя>. Потому мы просто обязаны поделиться с тобой силой.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПечать Рассвета претендентаПечать Рассвета претендентаПечать Рассвета претендента"},
[87364] = {title = "Потенциал печати", objective = "Добудьте останки доблести в Наксрамасе.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПечать Рассвета посвященногоПечать Рассвета посвященногоПечать Рассвета посвященного"},
[87365] = {title = "Отвага увеличивает доблесть", objective = "Добудьте останки доблести в Наксрамасе.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПечать Рассвета оруженосцаПечать Рассвета оруженосцаПечать Рассвета оруженосца"},
[87366] = {title = "Рыцарское рвение", objective = "Добудьте останки доблести в Наксрамасе.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПечать Рассвета рыцаряПечать Рассвета рыцаряПечать Рассвета рыцаря"},
[87368] = {title = "Плод веры", objective = "Заберите печать Рассвета.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПечать Рассвета поборникаПечать Рассвета поборникаПечать Рассвета поборника"},
[87369] = {title = "Взращивание веры", objective = "Заберите печать Рассвета.", description = nil, progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nПечать Рассвета авангардаПечать Рассвета авангардаПечать Рассвета авангарда"},
[87493] = {title = "Беспорядки в Длани Тира", objective = "Осмотрите лагерь Алого ордена к западу от Длани Тира в Восточных Чумных землях и постарайтесь выяснить, что происходит среди местных алых рыцарей.", description = "Произошло кое-что весьма интересное, <имя>. Похоже, когда Алый орден сосредоточился на Наксрамасе, в Длани Тира началась смута. Трудно сказать, что именно там творится, но, судя по всему, алые рыцари сцепились друг с другом. \n\nЯ посылаю тебя в лагерь на западе от Длани Тира. Выясни, что случилось, и доложи нам как можно скорее.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[87497] = {title = "Раскол", objective = "Поговорите с Беатрисой и узнайте, что происходит в анклаве Алого ордена в Длани Тира, а потом расскажите все Леониду Барталомею Чтимому в часовне Последней Надежды.", description = "Перейду сразу к делу: анклав Длани Тира больше нам не подчиняется. Пока мы сражались в Наксрамасе, из Стратхольма прибыл отряд рыцарей и захватил крепость. Они настроены против нас, и в Длань Тира теперь путь заказан. Все посланники, которых мы туда отправили, так и не вернулись.\n\nМне очень не хочется просить о помощи у посторонних, но, боюсь, тут замешано нечто такое, с чем в одиночку не справиться.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[87498] = {title = "Вернуть крепость", objective = "Вернитесь к главнокомандующей Беатрисе в лагерь Алого ордена на западе от Длани Тира.", description = "<Леонид заметно мрачнеет, когда вы говорите, что Калдоран и вправду сейчас в лагере Алого ордена. Но через пару секунд к нему возвращается самообладание.>\n\nСпа... спасибо, <имя>. Пока продолжай помогать Беатрисе. Я же посовещаюсь с лордом Тироссом, и вместе мы разработаем план на случай, если придется вмешаться. Я молю небеса, чтобы на деле все оказалось не так скверно, как кажется, но, если нам не повезет, Серебряному Рассвету лучше встретить врага во всеоружии.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[87502] = {title = "Сбор информации", objective = "Войдите в Длань Тира в Восточных Чумных землях и осмотрите центральный собор, а затем разведайте обстановку в башне магов и крепости в Новом Авалоне. Потом возвращайтесь к Калдорану в лагерь Алого ордена.\n\nВы можете ворваться в Новый Авалон с боем, но это опасно. Поговорите с инквизитором Джосифайн в лагере Алого ордена, если хотите пробраться туда незаметно.", description = "Мне не нравится, что ты нам помогаешь. Ты якшаешься с еретиками и нечистыми душами. Связываться с тобой – ниже нашего достоинства. Но... в прошлом ты хорошо себя <показал/показала>, а значит, и сейчас принесешь пользу.\n\nПроберись в Длань Тира и разведай обстановку в соборе, а затем углубись в Новый Авалон и осмотри крепость и башню магов. Как закончишь, сразу же возвращайся. Мы должны знать, что нас там поджидает.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[87506] = {title = "Ослабить защиту", objective = "Войдите в Длань Тира в Восточных Чумных землях и убейте трех командиров обороны Алого ордена.", description = "Пока тебя не было, мы закончили обсуждать план нападения на Длань Тира. Мы пойдем в лобовую атаку и нанесем еще один удар с фланга, который возглавлю лично я. Но перед нападением надо ослабить врага, поэтому посылаю тебя назад в Длань Тира. Постарайся убить столько вражеских командиров, сколько получится: именно они управляют обороной.\n\nЯ меж тем отправлюсь к своим войскам на позицию. Отчитайся главнокомандующей Беатрисе, когда вернешься.\n\nИ не вздумай нас подвести.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[87508] = {title = "Доклад лорду Тироссу", objective = "Поговорите с лордом Максвеллом Тироссом в часовне Последней Надежды в Восточных Чумных землях.", description = "<имя>, только что прибыл посланник. Ты <должен/должна> как можно скорее вернуться в часовню Последней Надежды! На нас напали! Лорд Максвелл Тиросс требует, чтобы ты <явился/явилась> немедленно.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[87509] = {title = "Гнев Рассвета", objective = "Вернитесь к главнокомандующей Беатрисе в лагерь Алого ордена в Восточных Чумных землях и приготовьтесь отбить анклав.", description = "Не знаем, почему зверь убрался назад в анклав, но мы не дадим ему второго шанса нас погубить. Серебряный Рассвет все-таки втянули в конфликт, а значит, мы положим конец непотребствам, которые творятся в анклаве Алого ордена.\n\nСтупай в лагерь Алого ордена к Беатрисе. Скажи, что мы будем помогать ей... до поры до времени.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[87516] = {title = "Страшный удар", objective = "Доберитесь до анклава Алого ордена по дороге через горы и атакуйте защитников Длани Тира. Прозвоните в колокол в аббатстве, чтобы отвлечь врагов и подать Беатрисе сигнал к атаке.\n\nКак только прозвонит колокол, сразитесь с Балназзаром и убейте его.", description = "Наши войска готовы идти в атаку. Мы займем позиции, пока ты со своими воинами зайдешь к собору с тыла через горы.\n\nКак только там окажетесь, доберитесь до аббатства и прозвоните в колокол, чтобы подать сигнал к атаке.\n\nВам придется продержаться, пока мы до вас не доберемся, так что готовьтесь к серьезной битве.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[87517] = {title = "Смерть алым", objective = "Вступите в бой и дойдите до внутренней части анклава Алого ордена. Перебейте там воинов главнокомандующей Беатрисы и одолейте ее саму, а затем убейте дракона Солистразу.", description = "Похоже, зверь, что напал на часовню, подчиняется Калдорану, а само нападение было всего лишь уловкой, чтобы вынудить Рассвет вмешаться. Мы отвлекли Балназзара и помогли Беатрисе с Калдораном избавиться от него. А потом они попытались избавиться еще и от нас. Очевидно, чтобы Серебряный Рассвет не мешал им в Чумных землях.\n\nУ нас нет ответов на все вопросы, и ситуация выглядит скверно. Но все же мы должны прикончить алых псов за такой удар в спину.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[88722] = {title = "Превосходное боевое снаряжение – Уважение Рассвета", objective = "За 20 знаков Рассвета и 20 знаков Марша вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.", description = "Приветствую тебя, <брат/сестра>. Желаешь ли обменять знаки Рассвета или Марша на боевое снаряжение?\n\nСразу предупреждаю, легендарное снаряжение стоит немало даже для тех, кого уважают в Рассвете. Рекомендую для начала заслужить полное доверие Серебряного Рассвета!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nКольцо БлагочестияКольцо решимостиПоследняя надежда ВеримондыСумка с припасамиПоножи Чумного ОхотникаОсвященный шлем"},
[88726] = {title = "Легендарное снаряжение – Уважение Рассвета", objective = "За 75 знаков Рассвета и 75 знаков Марша вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.", description = "Приветствую тебя, <брат/сестра>. Желаешь ли обменять знаки Рассвета или Марша на боевое снаряжение?\n\nСразу предупреждаю, легендарное снаряжение стоит немало даже для тех, кого уважают в Рассвете. Рекомендую для начала заслужить полное доверие Серебряного Рассвета!Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nАмулет РассветаНаручи НадеждыНаручи ухищренияРассветный медальонТалисман ГосподстваОчиститель"},
[88744] = {title = "Под тенью", objective = "Найдите по карте регион, атакуемый Плетью. Отправляйтесь туда и разгромите толпы Плети вокруг Некрополя, чтобы навредить ему. Доставьте 10 некротических рун Плети командиру Томасу Элерану в Часовню Последней Надежды в Восточные Чумные земли.", description = "Парящие некрополи Плети не щадят ни Орду, ни Альянс. Тень летающих крепостей пала на Танарис, Выжженные Земли, Зимние Ключи и Пылающие степи.\n\nТолько объединив усилия, мы сможем противостоять этой беде.\n\nНекрополи питает энергия магических кругов, которые покоятся в разных местах захваченных регионов. Все круги охраняют полчища нежити. Мы выяснили, что если уничтожить этих тварей, то защита кругов разрушится.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБлагословенное волшебное маслоОсвященное точилоУтяжеленное освященное точило"},
[88745] = {title = "Тени Рока", objective = "Идите к кругу призыва и убейте Тень Рока, затем возвращайтесь к командиру Томасу Элерану в Часовню Последней Надежды в Восточные Чумные земли.", description = "Когда ты разрушишь защиту кругов призыва, которые появляются там, где происходит нападение, тебе придется сразиться с послушниками. Они охраняют эти круги.\n\nЧестно говоря, это не живые существа, а тени – одни из самых устрашающих созданий Короля-лича. Их можно обнаружить с помощью некротических рун, которые они носят при себе, а затем уничтожить магией или оружием.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБлагословенное волшебное маслоОсвященное точилоУтяжеленное освященное точило"},
[88748] = {title = "Треснувший некротический кристалл", objective = "Отнесите треснутый некротический кристалл лейтенанту Оррину за ворота Штормграда.", description = "На трупе сраженного поганища вы обнаруживаете треснувший кристалл, медленно пульсирующий некротической энергией.", progress = "Тебе что-нибудь нужно?", completion = "Хм, так это нашлось на трупе одного из мерзостных поганищ?\n\nМы слышали о лагерях-некрополях, призванных Плетью. Подозреваю, они хотели создать такой и в Штормграде. Хорошо что им это не удалось.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nБлагословенное волшебное маслоОсвященное точилоУтяжеленное освященное точило"},
[89224] = {title = "Нехватка провизии", objective = "Найдите неаппетитные объедки в Новом Авалоне и принесите их шеф-повару. Если у вас не получается их отыскать, можете прибегнуть к насилию и отнять еду.", description = "<Вы даже не успеваете поздороваться, как шеф-повар перебивает вас.>\n\nХвала Свету, помощь наконец-то прибыла! У нас столько заказов, что мы не справляемся на кухне, так еще и припасы кончаются. Что-то случилось, и мы остались без обычных поставок. Подозреваю, это как-то связано с воплями снаружи.\n\nТак или иначе, мне все равно нужен помощник, и быстро. Ступай, найди в городе что-нибудь выглядящее хоть немного съедобным. А потом подумаем, что из этого можно сделать.", progress = nil, completion = nil, rewards = nil},
[89229] = {title = "Верный путь", objective = "Поговорите с Леонидом Барталомеем Чтимым в часовне Последней Надежды и получите награду.", description = "Теперь ты все знаешь. Было нелегко бередить старые раны, но я слишком долго убегал от прошлого. Странно, но мне... даже стало лучше. Я годами молил судьбу о том, чтобы правосудие восторжествовало, но совершить это правосудие суждено не мне. Я иду по пути, который избрал сам. Погоня за местью не подарит мне покоя. Если я вновь кану во тьму, то лишь пойду наперекор желаниям сына.\n\nЯ вернусь в часовню Последней Надежды и вручу лорду Тироссу мой доклад. Найди меня там. Хочу передать тебе одну вещь.Вам дадут возможность выбрать одну из следующих наград:\n\n", progress = nil, completion = nil, rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nТалисман ЛеонидаДлань возрожденного правосудияФамильная печать БарталомеяДневник Чтимого\n\nВы также получите:\n\n"},
[89234] = {title = "Вопрос личного характера", objective = "Встретьтесь с Леонидом Барталомеем Чтимым у черного входа на востоке от главных ворот Стратхольма.", description = "Моя вражда с Калдораном, о которой я говорил в часовне... началась здесь, в Стратхольме. Тебе ведь доводилось слышать об \"очищении\", которое произошло в этом городе в начале Третьей войны?\n\nЯ видел все своими глазами, как и Калдоран. В тот день наши судьбы переплелись. Если ты не против, отправляйся на восток, к боковым вратам в город. Я буду ждать тебя там.После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil},
[89235] = {title = "Еще одно очищение", objective = "Войдите в Стратхольм и пройдите через ворота, ведущие на площадь Живодерни. Найдите там Леонида Барталомея Чтимого.", description = "Город за нашей спиной полон неупокоенных духов. Умерев в первый раз, я стал безвольным рабом Короля-лича и многие годы скитался по этим улицам. Но даже тогда часть меня осознавала, кто я на самом деле. Я помню, как не один раз проходил мимо тела жены. Она навеки застыла в ужасе, который испытывала перед смертью. \n\nПройди через ворота в район, который теперь называют площадью Живодерни. Я тоже подойду туда, когда соберусь с духом. И возьми с собой соратников. В одиночку там будет непросто.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[89245] = {title = "Без труда не выловишь и рыбку", objective = "Осмотрите лодку у причала к югу от Нового Авалона в поисках рыбы, а затем вернитесь к Кэрри с уловом.", description = "Одно время я работала в Дольном Очаге. Не могу передать, как жутко было полагаться на поставки через Чумные земли, ведь другого источника еды у нас не было. В Новом Авалоне провизию возят по морю, и это настоящее спасение... по крайней мере, так было до недавних пор.\n\nИ вот у нас снова разыгрывается старая пьеса под названием \"Кэрри пытается накормить армию едой, которой хватит разве что на семью\". Мне очень нужна рыба. Навести-ка гавань на юге и узнай, не пришла ли поставка, которую я заказывала.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nРецепт: филе с окороком"},
[89253] = {title = "Главное блюдо", objective = "Добудьте мясо, которое могут есть люди. Если у вас не получается отыскать такое в Новом Авалоне, попробуйте поохотиться на зверей в Восточных Чумных землях. Рано или поздно вы соберете нужное количество.", description = "Что за обед – и без мяса? Без него нельзя, это самый важный ингредиент! Как ты понимаешь, найти в Чумных землях зверя, который окажется съедобным, задача не из легких.\n\nЧто еще хуже, наши псы едят только мясо! Ты понимаешь, что это значит. Вот почему мне постоянно недостает припасов!\n\nНу, чего ты ждешь?Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nРецепт: хищнический стейк"},
[89256] = {title = "Покажите себя: наплечники", objective = "Создайте наплечники Алого ордена с помощью любого ремесла, которое позволяет изготавливать доспехи. Или пожертвуйте любую уже созданную деталь униформы Алого ордена.\n\nЕсли хотите пожертвовать предмет, найдите ящик рядом с интендантом в казармах. Положите туда снаряжение, а потом передайте ящик Бриону Стилблейду, чтобы получить награду.", description = "Мастер всегда должен стремиться к вершинам ремесла и создавать снаряжение высочайшего качества. Наши солдаты вверяют ремесленникам свою жизнь, и моя задача – убедиться, что те не подведут.\n\nДам тебе простое задание. Если ты разбираешься в кожевничестве, портняжном или кузнечном деле, то смастери пару наплечников. Потом можешь оставить их себе.\n\nА если ты не ремесленник, тогда закажи у кого-нибудь любую деталь униформы Алого ордена и пожертвуй нам.", progress = nil, completion = "Отличная работа.\n\nУ нас накапливается столько конфискованного барахла, что мы начали складывать его в эти старые сундуки. Вот только места для сундуков уже едва хватает. Кажется, ты умеешь находить пользу в подобных мелочах. Как раз получится достойная награда за одно пожертвование.\n\nА в некоторые сундуки я добавил ценный сюрприз. Может, он достанется именно тебе?", rewards = "Вы получите:\n\nЛарец Алого ордена"},
[89257] = {title = "Покажите себя: нагрудник", objective = "Создайте нагрудник Алого ордена с помощью любого ремесла, которое позволяет изготавливать доспехи. Или пожертвуйте любую уже созданную деталь униформы Алого ордена.\n\nЕсли хотите пожертвовать предмет, найдите ящик рядом с интендантом в казармах. Положите туда снаряжение, а потом передайте ящик Бриону Стилблейду, чтобы получить награду.", description = "Мастер всегда должен стремиться к вершинам ремесла и создавать снаряжение высочайшего качества. Наши солдаты вверяют ремесленникам свою жизнь, и моя задача – убедиться, что те не подведут.\n\nДам тебе простое задание. Если ты разбираешься в кожевничестве, портняжном или кузнечном деле, то смастери нагрудник. Потом можешь оставить его себе.\n\nА если ты не ремесленник, тогда закажи у кого-нибудь любую деталь униформы Алого ордена и пожертвуй нам.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЛарец Алого ордена"},
[89258] = {title = "Покажите себя: нарукавники", objective = "Создайте наручи Алого ордена с помощью любого ремесла, которое позволяет изготавливать доспехи. Или пожертвуйте любую уже созданную деталь униформы Алого ордена.\n\nЕсли хотите пожертвовать предмет, найдите ящик рядом с интендантом в казармах. Положите туда снаряжение, а потом передайте ящик Бриону Стилблейду, чтобы получить награду.", description = "Мастер всегда должен стремиться к вершинам ремесла и создавать снаряжение высочайшего качества. Наши солдаты вверяют ремесленникам свою жизнь, и моя задача – убедиться, что те не подведут.\n\nДам тебе простое задание. Если ты разбираешься в кожевничестве, портняжном или кузнечном деле, то смастери наручи. Потом можешь оставить их себе.\n\nА если ты не ремесленник, тогда закажи у кого-нибудь любую деталь униформы Алого ордена и пожертвуй нам.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЛарец Алого ордена"},
[89259] = {title = "Покажите себя: перчатки", objective = "Создайте перчатки Алого ордена с помощью любого ремесла, которое позволяет изготавливать доспехи. Или пожертвуйте любую уже созданную деталь униформы Алого ордена.\n\nЕсли хотите пожертвовать предмет, найдите ящик рядом с интендантом в казармах. Положите туда снаряжение, а потом передайте ящик Бриону Стилблейду, чтобы получить награду.", description = "Мастер всегда должен стремиться к вершинам ремесла и создавать снаряжение высочайшего качества. Наши солдаты вверяют ремесленникам свою жизнь, и моя задача – убедиться, что те не подведут.\n\nДам тебе простое задание. Если ты разбираешься в кожевничестве, портняжном или кузнечном деле, то смастери пару перчаток. Потом можешь оставить их себе.\n\nА если ты не ремесленник, тогда закажи у кого-нибудь любую деталь униформы Алого ордена и пожертвуй нам.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЛарец Алого ордена"},
[89260] = {title = "Покажите себя: пояс", objective = "Создайте пояс Алого ордена с помощью любого ремесла, которое позволяет изготавливать доспехи. Или пожертвуйте любую уже созданную деталь униформы Алого ордена.\n\nЕсли хотите пожертвовать предмет, найдите ящик рядом с интендантом в казармах. Положите туда снаряжение, а потом передайте ящик Бриону Стилблейду, чтобы получить награду.", description = "Мастер всегда должен стремиться к вершинам ремесла и создавать снаряжение высочайшего качества. Наши солдаты вверяют ремесленникам свою жизнь, и моя задача – убедиться, что те не подведут.\n\nДам тебе простое задание. Если ты разбираешься в кожевничестве, портняжном или кузнечном деле, то смастери пояс. Потом можешь оставить его себе.\n\nА если ты не ремесленник, тогда закажи у кого-нибудь любую деталь униформы Алого ордена и пожертвуй нам.", progress = nil, completion = "Отличная работа.\n\nУ нас накапливается столько конфискованного барахла, что мы начали складывать его в эти старые сундуки. Вот только места для сундуков уже едва хватает. Кажется, ты умеешь находить пользу в подобных мелочах. Как раз получится достойная награда за одно пожертвование.\n\nА в некоторые сундуки я добавил ценный сюрприз. Может, он достанется именно тебе?", rewards = "Вы получите:\n\nЛарец Алого ордена"},
[89261] = {title = "Покажите себя: поножи", objective = "Создайте брюки Алого ордена с помощью любого ремесла, которое позволяет изготавливать доспехи. Или пожертвуйте любую уже созданную деталь униформы Алого ордена.\n\nЕсли хотите пожертвовать предмет, найдите ящик рядом с интендантом в казармах. Положите туда снаряжение, а потом передайте ящик Бриону Стилблейду, чтобы получить награду.", description = "Мастер всегда должен стремиться к вершинам ремесла и создавать снаряжение высочайшего качества. Наши солдаты вверяют ремесленникам свою жизнь, и моя задача – убедиться, что те не подведут.\n\nДам тебе простое задание. Если ты разбираешься в кожевничестве, портняжном или кузнечном деле, то смастери брюки. Потом можешь оставить их себе.\n\nА если ты не ремесленник, тогда закажи у кого-нибудь любую деталь униформы Алого ордена и пожертвуй нам.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nЛарец Алого ордена"},
[89310] = {title = "Долина Ужаса", objective = "Отправьтесь в Долину Ужаса и найдите Леонида Барталомея Чтимого у одного из домов.", description = "Когда мой разум освободился от власти Короля-лича, меня еще долгие годы снедало чувство вины. Хотя Сильвана освободила меня, я отказался вставать под знамя Темной Госпожи и скрылся ото всех. Месяцами бродил по Чумным землям, сам не знаю зачем. Но однажды скитания привели меня домой, и я нашел там... совсем не то, что ожидал.\n\nЕсли хочешь узнать, что было дальше, отправляйся в населенную призраками деревню, которую теперь называют Долиной Ужаса. Я буду ждать тебя у крайнего дома на севере.После выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = nil},
[89328] = {title = "Потеря", objective = "Выслушайте последнюю часть истории Леонида.", description = "Когда я явился сюда после долгих странствий, то к своему величайшему удивлению обнаружил своего сына – живым и здоровым. Вместо того чтобы отвергнуть меня, как другие живые, он заключил меня в объятия. Видишь ли, он стал целителем, изучавшим живых мертвецов. Он был убежден, что есть способ не только предотвратить проклятие нежити, но и обратить его действие. \n\nКакое-то время мы жили счастливо. Я помогал сыну с исследованиями, а он поддерживал во мне надежду, которую я едва не утратил.\n\nТак было, пока в нашей жизни вновь не появился Бейлин Калдоран.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[89329] = {title = "Раздавить насекомых", objective = "Убейте 8 некрорахнидов и 5 некрорахнидов-могильщиков, а затем вернитесь к Леониду Барталомею Чтимому в его бывший дом в Долине Ужаса.", description = "Отвратительно. Тут повсюду кишмя кишат гнилые нерубы. Их надо уничтожить.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[89340] = {title = "Абсурдное послание", objective = "Отнесите письмо по адресу.", description = "Многоуважаемому главному шеф-повару Нового Авалона Кэрри Хартфайр,\n\nНадеюсь, это письмо застанет тебя в добром здравии! Когда ты покинула Дольный Очаг, то оставила зияющую рану в наших сердцах и голодную пропасть в желудках. Не проходит и дня, чтобы кто-нибудь не жаловался на утреннюю кашу и не требовал чего-нибудь повкуснее.\n\nПоэтому мы решили устроить банкет, где будем подавать самые лучшие блюда во всем Лордероне. То есть твои блюда.\n\nЧерез две недели прибудет караван с сопровождением. Поэтому готовься сама и готовь свои блюда.", progress = nil, completion = nil, rewards = nil},
[89463] = {title = "Соглашение о разглашении", objective = "Добудьте для Шипоплава в Новом Авалоне писчее перо и помогите сделать его укрытие более уютным. Изящное перо можно найти в ратуше Нового Авалона, а в окрестностях Некроситета или в склепах Каражана можно раздобыть бутафорский дом.", description = "Я не из тех гоблинов, кто выбалтывает все свои секреты первому встречному искателю приключений, зато могу разболтать секреты одного гнома! По пути сюда я раздобыл кое-какие схемы – сейчас исправляю в них недочеты. В них используются предохранители, представляешь! На кой нам предохранители?!\n\nВ общем, я с удовольствием поделюсь с тобой успехами, но сначала мне понадобится писчее перо. Надо зачеркнуть в этих схемах все лишнее. А еще мне нужно уютное местечко, где хорошо думается. Ну, что скажешь?Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСхема: бутафорский куст"},
[89471] = {title = "Гоблинское мастерство", objective = "Шипоплав в Новом Авалоне составил для вас список инженерных компонентов, необходимых для его изобретений. Принесите ему нужные предметы.", description = "Теперь можно смело сказать, что между нами сложились настоящие деловые отношения. Я отвечаю за ум, а ты – за грубую силу. И это все очень кстати, потому что примерно полминуты назад я вдруг понял, что мне не хватает нескольких важнейших компонентов!\n\nВот список всего необходимого. Все, как указано в схеме, кроме всякого гномьего барахла. А я пока доведу до ума эти эскизы. Когда вернешься, мы сможем сразу взяться за дело.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСхема: коробка гаджета"},
[89485] = {title = "Телепортационные кошмары", objective = "Пока вы в маскировке, прокрадитесь за спину жителям Нового Авалона и дайте им портативный портатор. Как только убедитесь, что устройство вас не убьет, опробуйте его на себе, чтобы выявить проблему, о которой говорил Шипоплав.", description = "Хотя мне очень нравится испытывать на тебе свои изобретения, с последним придется поступить иначе. Оно должно всего лишь перемещать испытателя на пару метров вперед, но когда я потыкал палкой первый прототип, он исчез полностью! Вместе с палкой!\n\nС тех пор я сделал еще несколько прототипов и слегка изменил их. Видел, что ты водишься с местными, и подумал: может, ты испытаешь эту штуку сначала на них? А потом и на себе, если осмелишься.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСхема: коробка гаджета – телепорт"},
[89486] = {title = "Щепотка пороха", objective = "Посетите следующие места в Новом Авалоне за отведенное время.", description = "Уверен, тебе не терпится узнать, что же я придумал сделать с порохом.\n\nТы когда-нибудь <слышал/слышала> о нитроускорителях? Нет, я не про один жалкий ускоритель, а про УСКОРИТЕЛИ! Если скажешь, что <слышал/слышала>, значит, ты просто лгунишка, потому что их еще не изобрели! То есть их только что изобрели!\n\nОкажи мне честь, испытай их. Просто засыпь сюда щепотку пороху и нажми кнопку. Если хочешь разогнаться посильнее, просто насыпь побольше!\n\nИ прокатись по разным местам, перед тем как вернуться.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСхема: коробка гаджета – нитроускорители"},
[89487] = {title = "Много шума из-за магнитов", objective = "Возьмите прототип магнита и попробуйте обнаружить и притянуть намагниченные частицы в разных местах Нового Авалона. Вернитесь к Шипоплаву, когда соберете достаточно доказательств в пользу его теории.", description = "Спасибо, что <добыл/добыла> припасы, но без нормальной мастерской мои возможности ограничены. И все же я наконец-то придумал, как разобраться в действии этих странных магнетических полей. Причем план получился просто гениальный. Думаю, если хорошенько поднапрячь мое гоблинское инженерное мастерство, я смогу разработать технологию, постоянно сокращающую расстояние между собеседниками. Теперь от меня никто не уйдет без покупки!\n\nНо мою теорию надо проверить. Возьми-ка этот прототип и поразмахивай им в Новом Авалоне. Если повезет, тебе что-нибудь попадется!Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСхема: коробка гаджета – магнитный переместитель"},
[89489] = {title = "Высокий шанс получения поясов", objective = "Шипоплав в Новом Авалоне потребовал у вас большое количество поясов для одного важного дела. Пояса наверняка можно добыть у солдат Нового Авалона.", description = "Теперь, когда мы убедились, что мои изобретения работают сами по себе, пришло время сделать их более удобными и доступными! Не думаю, что кто-то из нас готов тратить пригоршню золота каждый раз, когда надо телепортироваться через какую-нибудь лужу.\n\nКак и всегда, я уже задумал кое-что подходящее.\n\nПояс – самый несправедливо недооцененный предмет снаряжения, а ведь он так удобно расположен на теле! Это самое подходящее место для разных многоразовых гаджетов. Но сначала мне надо потренироваться на разных поясах, чтобы понять, как их лучше оснащать. Иди и укради несколько штук.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nРуководство по гаджетам Шипоплава"},
[89491] = {title = "Изощренный план побега", objective = "Используйте триангуляционный самофланж в трех некстати расположенных точках, а затем завершите настройку телепорта, применив сверхбезопасный транспортер \"Прибамбасск\" или пространственный проходчик \"Круговзор\", встав на пьедестал для телепортации. После этого вернитесь к Шипоплаву в Новый Авалон.", description = "Что ж, было весело, но пора и честь знать. Сначала я хотел смотаться отсюда поскорее с помощью новых гаджетов, но не смогу забрать все мои обновки за один раз!\n\nКогда я только прибыл сюда, мне удалось установить пьедестал для телепортации. Ты это уже <видел/видела>. Его осталось только настроить.\n\nВозьми это устройство и примени у ворот, на стрельбище и в местной таверне. А уже тогда – и только тогда – встань на пьедестал телепорта и запусти его с помощью твоего транспортера в Прибамбасск или Круговзор.Вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\nСхема: довольно безопасный транспортер в Новый Авалон"},
[89562] = {title = "Мой старый враг", objective = "Узнайте больше о Бейлине Калдоране у Леонида Барталомея Чтимого.", description = "Я слышал, что Калдоран участвовал в кампании в Наксрамасе, и боялся, что мне придется сражаться с ним в одном строю, если ход войны переменится.\n\nЗнаю, орден Серебряного Рассвета поддерживает твое сотрудничество с силами Алого ордена, но я настоятельно тебя предупреждаю: остерегайся Бейлина Калдорана. Мои руки начинают дрожать от гнева, стоит мне только подумать об этом человеке и тех зверствах, которые он творил. Ему нельзя верить. Прошу тебя... нет, умоляю... Отнесись к моим словам серьезно.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[89563] = {title = "Бремя Леонида", objective = "Получите указания у лорда Максвелла Тиросса.", description = "Я невольно подслушал твой разговор с Леонидом об инквизиторе Калдоране. Леонид поведал лишь немногое из того, что произошло. Калдоран причинил ему неимоверные страдания. Я был рядом в самый темный час и помог Леониду собраться и двинуться дальше. \n\nЯ опасаюсь, что наше сотрудничество с Алым орденом может навредить ему, особенно если придется иметь дело с тем человеком.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[89567] = {title = "Уничтоженный караван", objective = "Осмотрите останки каравана Алого ордена в Проклятом лесу на дороге, ведущей в Стратхольм. Когда что-то узнаете, поговорите с Леонидом Барталомеем Чтимым.", description = "Лорд Тиросс велел мне осмотреть останки каравана Алого ордена, обнаруженные в Проклятом лесу на дороге, ведущей в Стратхольм.\n\nНедавно нам сообщили, что незадолго до раскола в Длани Тира перемещения ордена по Чумным землям заметно участились. Возможно, этот караван поможет нам узнать, почему.\n\nДавай встретимся там и все осмотрим.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[89568] = {title = "Нечто новое", objective = "Примените образцы новой чумы к ослабленным каннибалам-вурдалакам, лоскутным ужасам, проклятым магам, солдатам Плети и хранителям Плети в Проклятом лесу и посмотрите, что произойдет.", description = "Думаю, нам нужно побольше узнать об этом новом штамме чумы. Похоже, он убивает... и живых, и даже нежить? Обычно чума нежити не вредит мертвецам, ведь именно она их порождает. Если мои подозрения верны, новая чума – ужасное оружие.\n\nМне жаль подвергать местную нежить новым мучениям, но мы должны узнать как можно больше, прежде чем вернемся в часовню.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[89574] = {title = "Служители смерти", objective = "Примените образцы новой чумы к призывателям Тьмы и некромантам в Восточных Чумных землях и посмотрите, что произойдет.", description = "Для меня не существует созданий более подлых, чем живые слуги Короля-лича. Я презираю и отвергаю любого, кто обладает свободой воли и может отличать добро от зла, но при этом намеренно служит смерти. Возьми еще несколько образцов чумы и опробуй их на живых сектантах из культа Проклятых.\n\nНе жалей этих монстров и не давай им пощады. Раз они примкнули к проклятым, так пусть ими и станут.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[90510] = {title = "Новый Авалон", objective = "Соберите достаточно предметов для маскировки, чтобы обмануть алых рыцарей в Новом Авалоне, а затем примените знак Алого ордена и поговорите с инквизитором Джосифайн. Игроки, обученные профессиям для создания снаряжения, могут использовать выкройки и чертежи, которые добываются у враждебных рыцарей в Длани Тира и Новом Авалоне.", description = "Как ты <заметил/заметила>, в Новом Авалоне стоит немало войск, но гражданских тоже хватает. Им там безопасно.\n\nЕсли ты придумаешь, как замаскироваться надолго, предложи местным свою помощь. Дружить с ними полезно: так нам будет проще вернуть анклав. А еще ты сможешь \"одалживать\" разные ценные вещи и ресурсы. Не только обогатишься, но и оставишь войско врага без припасов.", progress = nil, completion = nil, rewards = nil},
[90518] = {title = "Яблоки продлевают жизнь", objective = "Найдите яблоневый сад в южном районе Нового Авалона и добудьте яблоки, а затем отнесите их Кэрри Хартфайр в таверну Нового Авалона. Если яблоки окажутся слишком дорогими, попробуйте достать их по-другому.", description = "Рада снова тебя видеть. Пока тебя не было, с запасами продуктов все было в порядке, но этим утром оказалось, что мне чуть-чуть не хватает яблок для пирога. А я как раз хотела порадовать себя небольшим лакомством.\n\nТы не <мог/могла> бы заглянуть в яблоневый сад и достать немного яблок? Это не займет много времени. Боюсь, пирог для Джонни я тоже еще не испекла, но я не собираюсь сейчас тратить на него яблоки!\n\nА вот тебе кусочек обязательно оставлю.", progress = "Имей в виду: за хорошие яблоки Джонни берет больше обычного. Если не хочешь платить ему целое состояние, попробуй что-нибудь придумать.", completion = "Чудесно! Я сразу же займусь пирогом! Эти яблоки выглядят даже лучше предыдущей партии. Ты что, хочешь меня умаслить и выведать рецепт?..\n\n&lt;Кэрри подготавливает место на кухне к выпечке пирога и грозит вам пальцем.&gt;\n\nКак же хорошо, что ты зашла. Благодаря тебе у нас будет изумительный ужин. Мы с Маркусом всегда будем тебе рады.", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nХищнический стейкФиле с окорокомРассветный омлетОсвященная соль\n\nВы также получите:\n\nКусочек яблочного пирога КэрриИзумительные приправы"},
[90520] = {title = "Продовольственная безопасность", objective = "Добудьте мясо, которое могут есть люди. Если у вас не получается отыскать такое в Новом Авалоне, попробуйте поохотиться на зверей в Восточных Чумных землях. Рано или поздно вы добудете нужное количество.", description = "Припоминаю, что когда мы с тобой только встретились, я отправила тебя добывать мясо. А еще вдруг вспомнилось, что многие солдаты жаловались в тот вечер на несварение желудка. Странное дело...\n\nЧто ж, ладно. У нас в кладовой опять заканчивается мясо, и мне пригодился бы такой надежный поставщик, как ты. Я совсем не хочу ждать поставку, а потом обнаружить, что ее не будет, потому что курьер где-то погиб.", progress = "Хм... Похоже, сегодня у нас будет поздний обед.", completion = "А ты хорошо держишь планку, мой друг. Мясо порезано на аккуратные порции, а цвет и текстура у него такая же, как и в прошлый раз. Надеюсь, что если мне когда-нибудь придется добывать пропитание охотой, ты будешь рядом.\n\nИ Маркус, конечно же.\n\nДавай-ка я заберу у тебя заказ и поскорее начну готовить. Сегодня в Новом Авалоне будет настоящий пир!", rewards = "Вам дадут возможность выбрать одну из следующих наград:\n\nХищнический стейкФиле с окорокомРассветный омлетОсвященная соль\n\nВы также получите:\n\nИзумительные приправы"},
[90625] = {title = "На крыльях ужаса", objective = "Отнесите крыло Балназзара в часовню Последней Надежды в Восточных Чумных землях.", description = "От побежденного повелителя ужаса Балназзара осталось только истерзанное крыло.\n\nВозможно, его стоит показать кому-нибудь в часовне Последней Надежды.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
[90626] = {title = "Жила Света", objective = "Одолейте Солистразу и добудьте жилу взрослого дракона Света, а затем принесите ее Грок'ло в часовню Последней Надежды в Восточных Чумных землях.", description = "Грок'ло поможет встретиться с особым мастером, если найдешь подходящую тетиву к своему крылу.\n\nГрок'ло советует найти самую лучшую.\n\n<Хотя его лицо скрыто шлемом, вы замечаете, что Грок'ло ухмыляется.>\n\nСамая лучшая тетива – это жила дракона.Вы получите:\n\nПосле выполнения этого задания вы получите:\n\n", progress = nil, completion = nil, rewards = "Вы получите:\n\n"},
}
